// مولّدة آلياً بواسطة scripts/split-tafseer.mjs — لا تُعدَّل يدوياً.
export default [{"id":"1","s":1,"a":1,"at":"بسم الله الرحمن الرحيم","dt":"[1] ابتدئ قراءه القران باسم الله مستعينا به، الله علم على الرب -تبارك وتعالى- المعبود بحق دون سواه، وهو اخص اسماء الله تعالى، ولا يسمى به غيره سبحانه.الرحمن ذي الرحمه العامه الذي وسعت رحمته جميع الخلق، الرحيم بالمؤمنين، وهما اسمان من اسمائه تعالى، يتضمنان اثبات صفه الرحمه لله تعالى، كما يليق بجلاله."},{"id":"2","s":1,"a":2,"at":"الحمد لله رب العالمين","dt":"[2] الثناء على الله بصفاته التي كلها اوصاف كمال، وبنعمه الظاهره والباطنه، الدينيه والدنيويه. وفي ضمنه امر لعباده ان يحمدوه، فهو المستحق له وحده، وهو سبحانه المنشئ للخلق، القائم بامورهم، المربي لجميع خلقه بنعمه، ولاوليائه بالايمان والعمل الصالح."},{"id":"3","s":1,"a":3,"at":"الرحمن الرحيم","dt":"[3] الرحمن ذي الرحمه العامه الذي وسعت رحمته جميع الخلق، الرحيم بالمؤمنين، وهما اسمان من اسماء الله تعالى."},{"id":"4","s":1,"a":4,"at":"مالك يوم الدين","dt":"[4] وهو سبحانه وحده مالك يوم القيامه، وهو يوم الجزاء على الاعمال.وفي قراءه المسلم لهذه الايه في كل ركعه من صلواته تذكير له باليوم الاخر، وحث له على الاستعداد بالعمل الصالح، والكف عن المعاصي والسيئات."},{"id":"5","s":1,"a":5,"at":"اياك نعبد واياك نستعين","dt":"[5] انا نخصك وحدك بالعباده، ونستعين بك وحدك في جميع امورنا، فالامر كله بيدك، لا يملك منه احد مثقال ذره.وفي هذه الايه دليل على ان العبد لا يجوز له ان يصرف شيئا من انواع العباده كالدعاء، والاستغاثه، والذبح، والطواف الا لله وحده، وفيها شفاء القلوب من داء التعلق بغير الله، ومن امراض الرياء، والعجب، والكبرياء."},{"id":"6","s":1,"a":6,"at":"اهدنا الصراط المستقيم","dt":"[6] دلنا وارشدنا، ووفقنا الى الطريق المستقيم، وثبتنا عليه حتى نلقاك، وهو الاسلام الذي هو الطريق الواضح الموصل الى رضوان الله والى جنته، الذي دل عليه خاتم رسله وانبيائه محمد -صلى الله عليه وسلم-، فلا سبيل الى سعاده العبد الا بالاستقامه عليه."},{"id":"7","s":1,"a":7,"at":"صراط الذين انعمت عليهم غير المغضوب عليهم ولا الضالين","dt":"[7] طريق الذين انعمت عليهم، من النبيين والصديقين والشهداء والصالحين، فهم اهل الهدايه والاستقامه، ولا تجعلنا ممن سلك طريق المغضوب عليهم، الذين عرفوا الحق ولم يعملوا به، وهم اليهود، ومن كان على شاكلتهم، ولا تجعلنا من الضالين، وهم الذين لم يهتدوا عن جهل منهم، فضلوا الطريق، وهم النصارى، ومن اتبع سنتهم.وفي هذا الدعاء شفاء لقلب المسلم من مرض الجحود والجهل والضلال، ودلاله على ان اعظم نعمه على الاطلاق هي نعمه الاسلام، فمن كان اعرف للحق واتبع له، كان اولى بالصراط المستقيم، ولا ريب ان اصحاب رسول الله -صلى الله عليه وسلم- هم اولى الناس بذلك بعد الانبياء عليهم السلام، فدلت الايه على فضلهم، وعظيم منزلتهم، رضي الله عنهم.ويستحب للقارئ ان يقول في الصلاه بعد قراءه الفاتحه: امين، ومعناها: اللهم استجب، وليست ايه من سوره الفاتحه باتفاق العلماء؛ ولهذا اجمعوا على عدم كتابتها في المصاحف."},{"id":"8","s":2,"a":1,"at":"الم","dt":"[1] الم هذه الحروف وغيرها من الحروف المقطعه في اوائل السور، فيها اشاره الى اعجاز القران؛ فقد وقع به تحدي المشركين، فعجزوا عن معارضته، وهو مركب من هذه الحروف التي تتكون منها لغه العرب. فدل عجز العرب عن الاتيان بمثله -مع انهم افصح الناس- على ان القران وحي من الله."},{"id":"9","s":2,"a":2,"at":"ذلك الكتاب لا ريب فيه هدى للمتقين","dt":"[2] ذلك القران هو الكتاب العظيم الذي لا شك انه من عند الله، فلا يصح ان يرتاب فيه احد لوضوحه، ينتفع به المتقون بالعلم النافع والعمل الصالح، وهم الذين يخافون الله، ويتبعون احكامه."},{"id":"10","s":2,"a":3,"at":"الذين يؤمنون بالغيب ويقيمون الصلاه ومما رزقناهم ينفقون","dt":"[3] وهم الذين يصدقون بالغيب الذي لا تدركه حواسهم ولا عقولهم وحدها؛ لانه لا يعرف الا بوحي الله الى رسله، مثل الايمان بالملائكه، والجنه، والنار، وغير ذلك مما اخبر الله به او اخبر به رسوله -صلى الله عليه وسلم-، (والايمان: كلمه جامعه للاقرار بالله، وملائكته، وكتبه، ورسله، واليوم الاخر، والقدر خيره وشره، وتصديق الاقرار بالقول والعمل بالقلب واللسان والجوارح) وهم مع تصديقهم بالغيب يحافظون على اداء الصلاه في مواقيتها اداء صحيحا وفق ما شرع الله لنبيه محمد -صلى الله عليه وسلم-، ومما اعطيناهم من المال يخرجون صدقه اموالهم الواجبه والمستحبه."},{"id":"11","s":2,"a":4,"at":"والذين يؤمنون بما انزل اليك وما انزل من قبلك وبالاخره هم يوقنون","dt":"[4] والذين يصدقون بما انزل اليك ايها الرسول من القران، وبما انزل اليك من الحكمه، وهي السنه، وبكل ما انزل من قبلك على الرسل من كتب، كالتوراه والانجيل وغيرهما، ويصدقون بدار الحياه بعد الموت وما فيها من الحساب والجزاء، تصديقا بقلوبهم يظهر على السنتهم وجوارحهم. وخص يوم الاخره بالذكر؛ لان الايمان به من اعظم البواعث على فعل الطاعات، واجتناب المحرمات، ومحاسبه النفس."},{"id":"12","s":2,"a":5,"at":"اولئك على هدى من ربهم واولئك هم المفلحون","dt":"[5] اصحاب هذه الصفات على نور من ربهم وبتوفيق من خالقهم وهاديهم، وهم الفائزون الذين ادركوا ما طلبوا، ونجوا من شر ما منه هربوا."},{"id":"13","s":2,"a":6,"at":"ان الذين كفروا سواء عليهم اانذرتهم ام لم تنذرهم لا يؤمنون","dt":"[6] ان الذين جحدوا ما انزل اليك من ربك استكبارا وطغيانا، لن يقع منهم الايمان، سواء اخوفتهم وحذرتهم -ايها الرسول- من عذاب الله، ام تركت ذلك؛ لاصرارهم على باطلهم."},{"id":"14","s":2,"a":7,"at":"ختم الله على قلوبهم وعلى سمعهم وعلى ابصارهم غشاوه ولهم عذاب عظيم","dt":"[7] طبع الله على قلوب هؤلاء وعلى سمعهم، وجعل على ابصارهم غطاء؛ بسبب كفرهم وعنادهم من بعد ما تبين لهم الحق، فلم يوفقهم للهدى، ولهم عذاب شديد في نار جهنم."},{"id":"15","s":2,"a":8,"at":"ومن الناس من يقول امنا بالله وباليوم الاخر وما هم بمؤمنين","dt":"[8] ومن الناس فريق يتردد متحيرا بين المؤمنين والكافرين، وهم المنافقون الذين يقولون بالسنتهم: صدقنا بالله وباليوم الاخر، وهم في باطنهم كاذبون لم يؤمنوا."},{"id":"16","s":2,"a":9,"at":"يخادعون الله والذين امنوا وما يخدعون الا انفسهم وما يشعرون","dt":"[9] يعتقدون بجهلهم انهم يخادعون الله والذين امنوا باظهارهم الايمان واضمارهم الكفر، وما يخدعون الا انفسهم؛ لان عاقبه خداعهم تعود عليهم. ومن فرط جهلهم لا يحسون بذلك؛ لفساد قلوبهم."},{"id":"17","s":2,"a":10,"at":"في قلوبهم مرض فزادهم الله مرضا ولهم عذاب اليم بما كانوا يكذبون","dt":"[10] في قلوبهم شك وفساد فابتلوا بالمعاصي الموجبه لعقوبتهم، فزادهم الله شكا، ولهم عقوبه موجعه؛ بسبب كذبهم ونفاقهم."},{"id":"18","s":2,"a":11,"at":"واذا قيل لهم لا تفسدوا في الارض قالوا انما نحن مصلحون","dt":"[11] واذا نصحوا ليكفوا عن الافساد في الارض بالكفر والمعاصي، وافشاء اسرار المؤمنين، وموالاه الكافرين، قالوا -كذبا وجدالا-: انما نحن اهل الاصلاح."},{"id":"19","s":2,"a":12,"at":"الا انهم هم المفسدون ولكن لا يشعرون","dt":"[12] ان هذا الذي يفعلونه ويزعمون انه اصلاح هو عين الفساد، لكنهم بسبب جهلهم وعنادهم لا يحسون."},{"id":"20","s":2,"a":13,"at":"واذا قيل لهم امنوا كما امن الناس قالوا انؤمن كما امن السفهاء الا انهم هم السفهاء ولكن لا يعلمون","dt":"[13] واذا قيل للمنافقين: امنوا -مثل ايمان الصحابه، وهو الايمان بالقلب واللسان والجوارح- جادلوا وقالوا: انصدق مثل تصديق ضعاف العقل والراي، فنكون نحن وهم في السفه سواء؟ فرد الله عليهم بان السفه مقصور عليهم، وهم لا يعلمون ان ما هم فيه هو الضلال والخسران."},{"id":"21","s":2,"a":14,"at":"واذا لقوا الذين امنوا قالوا امنا واذا خلوا الى شياطينهم قالوا انا معكم انما نحن مستهزئون","dt":"[14] هؤلاء المنافقون اذا قابلوا المؤمنين قالوا: صدقنا بالاسلام مثلكم، واذا انصرفوا وذهبوا الى زعمائهم الكفره المتمردين على الله اكدوا لهم انهم على مله الكفر لم يتركوها، وانما كانوا يستخفون بالمؤمنين، ويسخرون منهم."},{"id":"22","s":2,"a":15,"at":"الله يستهزئ بهم ويمدهم في طغيانهم يعمهون","dt":"[15] الله يستهزئ بهم ويمهلهم؛ ليزدادوا ضلالا وحيره وترددا، ويجازيهم على استهزائهم بالمؤمنين."},{"id":"23","s":2,"a":16,"at":"اولئك الذين اشتروا الضلاله بالهدى فما ربحت تجارتهم وما كانوا مهتدين","dt":"[16] اولئك المنافقون باعوا انفسهم في صفقه خاسره، فاخذوا الكفر، وتركوا الايمان، فما كسبوا شيئا، بل خسروا الهدايه. وهذا هو الخسران المبين."},{"id":"24","s":2,"a":17,"at":"مثلهم كمثل الذي استوقد نارا فلما اضاءت ما حوله ذهب الله بنورهم وتركهم في ظلمات لا يبصرون","dt":"[17] حال المنافقين الذين امنوا -ظاهرا لا باطنا- برساله محمد -صلى الله عليه وسلم-، ثم كفروا، فصاروا يتخبطون في ظلمات ضلالهم وهم لا يشعرون، ولا امل لهم في الخروج منها، تشبه حال جماعه في ليله مظلمه، واوقد احدهم نارا عظيمه للدفء والاضاءه، فلما سطعت النار وانارت ما حوله، انطفات واعتمت، فصار اصحابها في ظلمات لا يرون شيئا، ولا يهتدون الى طريق ولا مخرج."},{"id":"25","s":2,"a":18,"at":"صم بكم عمي فهم لا يرجعون","dt":"[18] هم صم عن سماع الحق سماع تدبر، بكم عن النطق به، عمي عن ابصار نور الهدايه؛ لذلك لا يستطيعون الرجوع الى الايمان الذي تركوه، واستعاضوا عنه بالضلال."},{"id":"26","s":2,"a":19,"at":"او كصيب من السماء فيه ظلمات ورعد وبرق يجعلون اصابعهم في اذانهم من الصواعق حذر الموت والله محيط بالكافرين","dt":"[19] او تشبه حال فريق اخر من المنافقين يظهر لهم الحق تاره، ويشكون فيه تاره اخرى، حال جماعه يمشون في العراء، فينصب عليهم مطر شديد، تصاحبه ظلمات بعضها فوق بعض، مع قصف الرعد، ولمعان البرق، والصواعق المحرقه، التي تجعلهم من شده الهول يضعون اصابعهم في اذانهم؛ خوفا من الهلاك. والله تعالى محيط بالكافرين لا يفوتونه ولا يعجزونه."},{"id":"27","s":2,"a":20,"at":"يكاد البرق يخطف ابصارهم كلما اضاء لهم مشوا فيه واذا اظلم عليهم قاموا ولو شاء الله لذهب بسمعهم وابصارهم ان الله على كل شيء قدير","dt":"[20] يقارب البرق -من شده لمعانه- ان يسلب ابصارهم، ومع ذلك فكلما اضاء لهم مشوا في ضوئه، واذا ذهب اظلم الطريق عليهم فيقفون في اماكنهم. ولولا امهال الله لهم لسلب سمعهم وابصارهم، وهو قادر على ذلك في كل وقت، انه على كل شيء قدير."},{"id":"28","s":2,"a":21,"at":"ياايها الناس اعبدوا ربكم الذي خلقكم والذين من قبلكم لعلكم تتقون","dt":"[21] نداء من الله للبشر جميعا: ان اعبدوا الله الذي رباكم بنعمه، وخافوه ولا تخالفوا دينه؛ فقد اوجدكم من العدم، واوجد الذين من قبلكم؛ لتكونوا من المتقين الذين رضي الله عنهم ورضوا عنه."},{"id":"29","s":2,"a":22,"at":"الذي جعل لكم الارض فراشا والسماء بناء وانزل من السماء ماء فاخرج به من الثمرات رزقا لكم فلا تجعلوا لله اندادا وانتم تعلمون","dt":"[22] ربكم الذي جعل لكم الارض بساطا؛ لتسهل حياتكم عليها، والسماء محكمه البناء، وانزل المطر من السحاب فاخرج لكم به من الوان الثمرات وانواع النبات رزقا لكم، فلا تجعلوا لله نظراء في العباده، وانتم تعلمون تفرده بالخلق والرزق، واستحقاقه العبوديه."},{"id":"30","s":2,"a":23,"at":"وان كنتم في ريب مما نزلنا على عبدنا فاتوا بسوره من مثله وادعوا شهداءكم من دون الله ان كنتم صادقين","dt":"[23] وان كنتم -ايها الكافرون المعاندون- في شك من القران الذي نزلناه على عبدنا محمد -صلى الله عليه وسلم-، وتزعمون انه ليس من عند الله، فهاتوا سوره تماثل سوره من القران، واستعينوا بمن تقدرون عليه من اعوانكم، ان كنتم صادقين في دعواكم."},{"id":"31","s":2,"a":24,"at":"فان لم تفعلوا ولن تفعلوا فاتقوا النار التي وقودها الناس والحجاره اعدت للكافرين","dt":"[24] فان عجزتم الان -وستعجزون مستقبلا لا محاله- فاتقوا النار بالايمان بالنبي -صلى الله عليه وسلم- وطاعه الله تعالى. هذه النار التي حطبها الناس والحجاره، اعدت للكافرين بالله ورسله."},{"id":"32","s":2,"a":25,"at":"وبشر الذين امنوا وعملوا الصالحات ان لهم جنات تجري من تحتها الانهار كلما رزقوا منها من ثمره رزقا قالوا هذا الذي رزقنا من قبل واتوا به متشابها ولهم فيها ازواج مطهره وهم فيها خالدون","dt":"[25] واخبر -ايها الرسول- اهل الايمان والعمل الصالح خبرا يملؤهم سرورا، بان لهم في الاخره حدائق عجيبه، تجري الانهار تحت قصورها العاليه واشجارها الظليله. كلما رزقهم الله فيها نوعا من الفاكهه اللذيذه قالوا: قد رزقنا الله هذا النوع من قبل، فاذا ذاقوه وجدوه شيئا جديدا في طعمه ولذته، وان تشابه مع سابقه في اللون والمنظر والاسم. ولهم في الجنات زوجات مطهرات من كل الوان الدنس الحسي كالبول والحيض، والمعنوي كالكذب وسوء الخلق. وهم في الجنه ونعيمها دائمون، لا يموتون فيها ولا يخرجون منها."},{"id":"33","s":2,"a":26,"at":"ان الله لا يستحيي ان يضرب مثلا ما بعوضه فما فوقها فاما الذين امنوا فيعلمون انه الحق من ربهم واما الذين كفروا فيقولون ماذا اراد الله بهذا مثلا يضل به كثيرا ويهدي به كثيرا وما يضل به الا الفاسقين","dt":"[26] ان الله تعالى لا يستحيي من الحق ان يذكر شيئا ما، قل او كثر، ولو كان تمثيلا باصغر شيء، كالبعوضه والذباب ونحو ذلك، مما ضربه الله مثلا لعجز كل ما يعبد من دون الله. فاما المؤمنون فيعلمون حكمه الله في التمثيل بالصغير والكبير من خلقه، واما الكفار فيسخرون ويقولون: ما مراد الله من ضرب المثل بهذه الحشرات الحقيره؟ويجيبهم الله بان المراد هو الاختبار، وتمييز المؤمن من الكافر؛ لذلك يصرف الله بهذا المثل ناسا كثيرين عن الحق لسخريتهم منه، ويوفق به غيرهم الى مزيد من الايمان والهدايه. والله تعالى لا يظلم احدا؛ لانه لا يصرف عن الحق الا الخارجين عن طاعته."},{"id":"34","s":2,"a":27,"at":"الذين ينقضون عهد الله من بعد ميثاقه ويقطعون ما امر الله به ان يوصل ويفسدون في الارض اولئك هم الخاسرون","dt":"[27] الذين ينكثون عهد الله الذي اخذه عليهم بالتوحيد والطاعه، وقد اكده بارسال الرسل، وانزال الكتب، ويخالفون دين الله كقطع الارحام ونشر الفساد في الارض، اولئك هم الخاسرون في الدنيا والاخره."},{"id":"35","s":2,"a":28,"at":"كيف تكفرون بالله وكنتم امواتا فاحياكم ثم يميتكم ثم يحييكم ثم اليه ترجعون","dt":"[28] كيف تنكرون -ايها المشركون- وحدانيه الله تعالى، وتشركون به غيره في العباده مع البرهان القاطع عليها في انفسكم؟ فلقد كنتم غير مخلوقين فاوجدكم ونفخ فيكم الحياه، ثم يميتكم بعد انقضاء اجالكم التي حددها لكم، ثم يعيدكم احياء يوم البعث، ثم اليه ترجعون للحساب والجزاء."},{"id":"36","s":2,"a":29,"at":"هو الذي خلق لكم ما في الارض جميعا ثم استوى الى السماء فسواهن سبع سموات وهو بكل شيء عليم","dt":"[29] الله وحده الذي خلق لاجلكم كل ما في الارض من النعم التي تنتفعون بها، ثم قصد الى خلق السموات، فسواهن سبع سموات، وهو بكل شيء عليم. فعلمه -سبحانه- محيط بجميع ما خلق."},{"id":"37","s":2,"a":30,"at":"واذ قال ربك للملائكه اني جاعل في الارض خليفه قالوا اتجعل فيها من يفسد فيها ويسفك الدماء ونحن نسبح بحمدك ونقدس لك قال اني اعلم ما لا تعلمون","dt":"[30] واذكر -ايها الرسول- للناس حين قال ربك للملائكه: اني جاعل في الارض قوما يخلف بعضهم بعضا لعمارتها. قالت: يا ربنا علمنا وارشدنا ما الحكمه في خلق هؤلاء، مع ان من شانهم الافساد في الارض واراقه الدماء ظلما وعدوانا ونحن طوع امرك، ننزهك التنزيه اللائق بحمدك وجلالك، ونمجدك بكل صفات الكمال والجلال؟ قال الله لهم: اني اعلم ما لا تعلمون من المصلحه الراجحه في خلقهم."},{"id":"38","s":2,"a":31,"at":"وعلم ادم الاسماء كلها ثم عرضهم على الملائكه فقال انبئوني باسماء هؤلاء ان كنتم صادقين","dt":"[31] وبيانا لفضل ادم عليه السلام علمه الله اسماء الاشياء كلها، ثم عرض مسمياتها على الملائكه قائلا لهم: اخبروني باسماء هؤلاء الموجودات، ان كنتم صادقين في انكم اولى بالاستخلاف في الارض منهم."},{"id":"39","s":2,"a":32,"at":"قالوا سبحانك لا علم لنا الا ما علمتنا انك انت العليم الحكيم","dt":"[32] قالت الملائكه: ننزهك يا ربنا، ليس لنا علم الا ما علمتنا اياه. انك انت وحدك العليم بشؤون خلقك، الحكيم في تدبيرك."},{"id":"40","s":2,"a":33,"at":"قال ياادم انبئهم باسمائهم فلما انباهم باسمائهم قال الم اقل لكم اني اعلم غيب السموات والارض واعلم ما تبدون وما كنتم تكتمون","dt":"[33] قال الله: يا ادم اخبرهم باسماء هذه الاشياء التي عجزوا عن معرفتها. فلما اخبرهم ادم بها، قال الله للملائكه: لقد اخبرتكم اني اعلم ما خفي عنكم في السموات والارض، واعلم ما تظهرونه وما تخفونه."},{"id":"41","s":2,"a":34,"at":"واذ قلنا للملائكه اسجدوا لادم فسجدوا الا ابليس ابى واستكبر وكان من الكافرين","dt":"[34] واذكر -ايها الرسول- للناس تكريم الله لادم حين قال سبحانه للملائكه: اسجدوا لادم اكراما له واظهارا لفضله، فاطاعوا جميعا الا ابليس امتنع عن السجود تكبرا وحسدا، فصار من الجاحدين بالله، العاصين لامره."},{"id":"42","s":2,"a":35,"at":"وقلنا ياادم اسكن انت وزوجك الجنه وكلا منها رغدا حيث شئتما ولا تقربا هذه الشجره فتكونا من الظالمين","dt":"[35] وقال الله: يا ادم اسكن انت وزوجك حواء الجنه، وتمتعا بثمارها تمتعا هنيئا واسعا في اي مكان تشاءان فيها، ولا تقربا هذه الشجره حتى لا تقعا في المعصيه، فتصيرا من المتجاوزين امر الله."},{"id":"43","s":2,"a":36,"at":"فازلهما الشيطان عنها فاخرجهما مما كانا فيه وقلنا اهبطوا بعضكم لبعض عدو ولكم في الارض مستقر ومتاع الى حين","dt":"[36] فاوقعهما الشيطان في الخطيئه: بان وسوس لهما حتى اكلا من الشجره، فتسبب في اخراجهما من الجنه ونعيمها. وقال الله لهم: اهبطوا الى الارض، يعادي بعضكم بعضا -اي ادم وحواء والشيطان- ولكم في الارض استقرار واقامه، وانتفاع بما فيها الى وقت انتهاء اجالكم."},{"id":"44","s":2,"a":37,"at":"فتلقى ادم من ربه كلمات فتاب عليه انه هو التواب الرحيم","dt":"[37] فتلقى ادم بالقبول كلمات، الهمه الله اياها توبه واستغفارا، وهي قوله تعالى: ربنا ظلمنا انفسنا وان لم تغفر لنا وترحمنا لنكونن من الخسرين، فتاب الله عليه، وغفر له ذنبه. انه تعالى هو التواب لمن تاب من عباده، الرحيم بهم."},{"id":"45","s":2,"a":38,"at":"قلنا اهبطوا منها جميعا فاما ياتينكم مني هدى فمن تبع هداي فلا خوف عليهم ولا هم يحزنون","dt":"[38] قال الله لهم: اهبطوا من الجنه جميعا، وسياتيكم انتم وذرياتكم المتعاقبه ما فيه هدايتكم الى الحق. فمن عمل بها فلا خوف عليهم فيما يستقبلونه من امر الاخره، ولاهم يحزنون على ما فاتهم من امور الدنيا."},{"id":"46","s":2,"a":39,"at":"والذين كفروا وكذبوا باياتنا اولئك اصحاب النار هم فيها خالدون","dt":"[39] والذين جحدوا وكذبوا باياتنا المتلوه ودلائل توحيدنا، اولئك الذين يلازمون النار، هم فيها خالدون، لا يخرجون منها."},{"id":"47","s":2,"a":40,"at":"يابني اسرائيل اذكروا نعمتي التي انعمت عليكم واوفوا بعهدي اوف بعهدكم واياي فارهبون","dt":"[40] يا ذريه يعقوب اذكروا نعمي الكثيره عليكم، واشكروا لي، واتموا وصيتي لكم: بان تؤمنوا بكتبي ورسلي جميعا، وتعملوا بشرائعي. فان فعلتم ذلك اتمم لكم ما وعدتكم به من الرحمه في الدنيا، والنجاه في الاخره. واياي -وحدي- فخافوني، واحذروا نقمتي ان نقضتم العهد، وكفرتم بي."},{"id":"48","s":2,"a":41,"at":"وامنوا بما انزلت مصدقا لما معكم ولا تكونوا اول كافر به ولا تشتروا باياتي ثمنا قليلا واياي فاتقون","dt":"[41] وامنوا -يا بني اسرائيل- بالقران الذي انزلته على محمد نبي الله ورسوله، موافقا لما تعلمونه من صحيح التوراه، ولا تكونوا اول فريق من اهل الكتاب يكفر به، ولا تستبدلوا باياتي ثمنا قليلا من حطام الدنيا الزائل، واياي وحدي فاعملوا بطاعتي واتركوا معصيتي."},{"id":"49","s":2,"a":42,"at":"ولا تلبسوا الحق بالباطل وتكتموا الحق وانتم تعلمون","dt":"[42] ولا تخلطوا الحق الذي بينته لكم بالباطل الذي افتريتموه، واحذروا كتمان الحق الصريح من صفه نبي الله ورسوله محمد -صلى الله عليه وسلم- التي في كتبكم، وانتم تجدونها مكتوبه عندكم، فيما تعلمون من الكتب التي بايديكم."},{"id":"50","s":2,"a":43,"at":"واقيموا الصلاه واتوا الزكاه واركعوا مع الراكعين","dt":"[43] وادخلوا في دين الاسلام: بان تقيموا الصلاه على الوجه الصحيح، كما جاء بها نبي الله ورسوله محمد -صلى الله عليه وسلم-، وتؤدوا الزكاه المفروضه على الوجه المشروع، وتكونوا مع الراكعين من امته -صلى الله عليه وسلم-."},{"id":"51","s":2,"a":44,"at":"اتامرون الناس بالبر وتنسون انفسكم وانتم تتلون الكتاب افلا تعقلون","dt":"[44] ما اقبح حالكم وحال علمائكم حين تامرون الناس بعمل الخيرات، وتتركون انفسكم، فلا تامرونها بالخير العظيم، وهو الاسلام، وانتم تقرؤون التوراه، التي فيها صفات محمد -صلى الله عليه وسلم-، ووجوب الايمان به! افلا تستعملون عقولكم استعمالا صحيحا؟"},{"id":"52","s":2,"a":45,"at":"واستعينوا بالصبر والصلاه وانها لكبيره الا على الخاشعين","dt":"[45] واستعينوا في كل اموركم بالصبر بجميع انواعه، وكذلك الصلاه. وانها لشاقه الا على الخاشعين."},{"id":"53","s":2,"a":46,"at":"الذين يظنون انهم ملاقو ربهم وانهم اليه راجعون","dt":"[46] الذين يخشون الله ويرجون ما عنده، ويوقنون انهم ملاقو ربهم جل وعلا بعد الموت، وانهم اليه راجعون يوم القيامه للحساب والجزاء."},{"id":"54","s":2,"a":47,"at":"يابني اسرائيل اذكروا نعمتي التي انعمت عليكم واني فضلتكم على العالمين","dt":"[47] يا ذريه يعقوب تذكروا نعمي الكثيره عليكم، واشكروا لي عليها، وتذكروا اني فضلتكم على عالمي زمانكم بكثره الانبياء، والكتب المنزله كالتوراه والانجيل."},{"id":"55","s":2,"a":48,"at":"واتقوا يوما لا تجزي نفس عن نفس شيئا ولا يقبل منها شفاعه ولا يؤخذ منها عدل ولا هم ينصرون","dt":"[48] وخافوا يوم القيامه، يوم لا يغني احد عن احد شيئا، ولا يقبل الله شفاعه في الكافرين، ولا يقبل منهم فديه، ولو كانت اموال الارض جميعا، ولا يملك احد في هذا اليوم ان يتقدم لنصرتهم وانقاذهم من العذاب."},{"id":"56","s":2,"a":49,"at":"واذ نجيناكم من ال فرعون يسومونكم سوء العذاب يذبحون ابناءكم ويستحيون نساءكم وفي ذلكم بلاء من ربكم عظيم","dt":"[49] واذكروا نعمتنا عليكم حين انقذناكم من بطش فرعون واتباعه، وهم يذيقونكم اشد العذاب، فيكثرون من ذبح ابنائكم، ويستبقون نساءكم للخدمه والامتهان. وفي ذلك اختبار لكم من ربكم، وفي انجائكم منه نعمه عظيمه، تستوجب شكر الله تعالى في كل عصوركم واجيالكم."},{"id":"57","s":2,"a":50,"at":"واذ فرقنا بكم البحر فانجيناكم واغرقنا ال فرعون وانتم تنظرون","dt":"[50] واذكروا نعمتنا عليكم حين فصلنا بسببكم البحر، وجعلنا فيه طرقا يابسه، فعبرتم، وانقذناكم من فرعون وجنوده، ومن الهلاك في الماء. فلما دخل فرعون وجنوده طرقكم اهلكناهم في الماء امام اعينكم."},{"id":"58","s":2,"a":51,"at":"واذ واعدنا موسى اربعين ليله ثم اتخذتم العجل من بعده وانتم ظالمون","dt":"[51] واذكروا نعمتنا عليكم حين واعدنا موسى اربعين ليله لانزال التوراه هدايه ونورا لكم، فاذا بكم تنتهزون فرصه غيابه هذه المده القليله، وتجعلون العجل الذي صنعتموه بايديكم معبودا لكم من دون الله -وهذا اشنع الكفر بالله- وانتم ظالمون باتخاذكم العجل الها."},{"id":"59","s":2,"a":52,"at":"ثم عفونا عنكم من بعد ذلك لعلكم تشكرون","dt":"[52] ثم تجاوزنا عن هذه الفعله المنكره، وقبلنا توبتكم بعد عوده موسى؛ رجاء ان تشكروا الله على نعمه وافضاله، ولا تتمادوا في الكفر والطغيان."},{"id":"60","s":2,"a":53,"at":"واذ اتينا موسى الكتاب والفرقان لعلكم تهتدون","dt":"[53] واذكروا نعمتنا عليكم حين اعطينا موسى الكتاب الفارق بين الحق والباطل -وهو التوراه-؛ لكي تهتدوا من الضلاله."},{"id":"61","s":2,"a":54,"at":"واذ قال موسى لقومه ياقوم انكم ظلمتم انفسكم باتخاذكم العجل فتوبوا الى بارئكم فاقتلوا انفسكم ذلكم خير لكم عند بارئكم فتاب عليكم انه هو التواب الرحيم","dt":"[54] واذكروا نعمتنا عليكم حين قال موسى لقومه: انكم ظلمتم انفسكم باتخاذكم العجل الها، فتوبوا الى خالقكم: بان يقتل بعضكم بعضا، وهذا خير لكم عند خالقكم من الخلود الابدي في النار، فامتثلتم ذلك، فمن الله عليكم بقبول توبتكم. انه تعالى هو التواب لمن تاب من عباده، الرحيم بهم."},{"id":"62","s":2,"a":55,"at":"واذ قلتم ياموسى لن نؤمن لك حتى نرى الله جهره فاخذتكم الصاعقه وانتم تنظرون","dt":"[55] واذكروا اذ قلتم: يا موسى لن نصدقك في ان الكلام الذي نسمعه منك هو كلام الله، حتى نرى الله عيانا، فاخذتكم العقوبه المهلكه التي رايتموها باعينكم، فقتلتكم بسبب ذنوبكم، وجراتكم على الله تعالى."},{"id":"63","s":2,"a":56,"at":"ثم بعثناكم من بعد موتكم لعلكم تشكرون","dt":"[56] ثم احييناكم من بعد موتكم بالصاعقه؛ لتشكروا نعمه الله عليكم. فهذا الموت عقوبه لهم، ثم بعثهم الله لاستيفاء اجالهم."},{"id":"64","s":2,"a":57,"at":"وظللنا عليكم الغمام وانزلنا عليكم المن والسلوى كلوا من طيبات ما رزقناكم وما ظلمونا ولكن كانوا انفسهم يظلمون","dt":"[57] واذكروا نعمتنا عليكم حين كنتم تتيهون في الارض؛ اذ جعلنا السحاب مظللا عليكم من حر الشمس، وانزلنا عليكم المن، وهو شيء يشبه الصمغ طعمه كالعسل، وانزلنا عليكم السلوى، وهو طير يشبه السمانى، وقلنا لكم: كلوا من طيبات ما رزقناكم، ولا تخالفوا دينكم، فلم تمتثلوا. وما ظلمونا بكفران النعم، ولكن كانوا انفسهم يظلمون؛ لان عاقبه الظلم عائده عليهم."},{"id":"65","s":2,"a":58,"at":"واذ قلنا ادخلوا هذه القريه فكلوا منها حيث شئتم رغدا وادخلوا الباب سجدا وقولوا حطه نغفر لكم خطاياكم وسنزيد المحسنين","dt":"[58] واذكروا نعمتنا عليكم حين قلنا: ادخلوا مدينه «بيت المقدس» فكلوا من طيباتها في اي مكان منها اكلا هنيئا، وكونوا في دخولكم خاضعين لله، ذليلين له، وقولوا: ربنا ضع عنا ذنوبنا، نستجب لكم ونعف عنكم ونسترها عليكم، وسنزيد المحسنين باعمالهم خيرا وثوابا."},{"id":"66","s":2,"a":59,"at":"فبدل الذين ظلموا قولا غير الذي قيل لهم فانزلنا على الذين ظلموا رجزا من السماء بما كانوا يفسقون","dt":"[59] فبدل الجائرون الضالون من بني اسرائيل قول الله، وحرفوا القول والفعل جميعا، اذ دخلوا يزحفون على استاههم وقالوا: حبه في شعره، واستهزؤوا بدين الله. فانزل الله عليهم عذابا من السماء؛ بسبب تمردهم وخروجهم عن طاعه الله."},{"id":"67","s":2,"a":60,"at":"واذ استسقى موسى لقومه فقلنا اضرب بعصاك الحجر فانفجرت منه اثنتا عشره عينا قد علم كل اناس مشربهم كلوا واشربوا من رزق الله ولا تعثوا في الارض مفسدين","dt":"[60] واذكروا نعمتنا عليكم -وانتم عطاش في التيه- حين دعانا موسى -بضراعه- ان نسقي قومه، فقلنا: اضرب بعصاك الحجر، فضرب، فانفجرت منه اثنتا عشره عينا، بعدد القبائل، مع اعلام كل قبيله بالعين الخاصه بها حتى لا يتنازعوا. وقلنا لهم: كلوا واشربوا من رزق الله، ولا تسعوا في الارض مفسدين."},{"id":"68","s":2,"a":61,"at":"واذ قلتم ياموسى لن نصبر على طعام واحد فادع لنا ربك يخرج لنا مما تنبت الارض من بقلها وقثائها وفومها وعدسها وبصلها قال اتستبدلون الذي هو ادنى بالذي هو خير اهبطوا مصرا فان لكم ما سالتم وضربت عليهم الذله والمسكنه وباءوا بغضب من الله ذلك بانهم كانوا يكفرون بايات الله ويقتلون النبيين بغير الحق ذلك بما عصوا وكانوا يعتدون","dt":"[61] واذكروا حين انزلنا عليكم الطعام الحلو، والطير الشهي، فبطرتم النعمه كعادتكم، واصابكم الضيق والملل، فقلتم: يا موسى لن نصبر على طعام ثابت لا يتغير مع الايام، فادع لنا ربك يخرج لنا من نبات الارض طعاما من البقول والخضر، والقثاء، والحبوب التي تؤكل، والعدس، والبصل. قال موسى -مستنكرا عليهم-: اتطلبون هذه الاطعمه التي هي اقل قدرا، وتتركون هذا الرزق النافع الذي اختاره الله لكم؟ اهبطوا من هذه الباديه الى اي مدينه، تجدوا ما اشتهيتم كثيرا في الحقول والاسواق. ولما هبطوا تبين لهم انهم يقدمون اختيارهم -في كل موطن- على اختيار الله، ويؤثرون شهواتهم على ما اختاره الله لهم؛ لذلك لزمتهم صفه الذل وفقر النفوس، وانصرفوا ورجعوا بغضب من الله؛ لاعراضهم عن دين الله، ولانهم كانوا يكفرون بايات الله ويقتلون النبيين ظلما وعدوانا؛ وذلك بسبب عصيانهم وتجاوزهم حدود ربهم."},{"id":"69","s":2,"a":62,"at":"ان الذين امنوا والذين هادوا والنصارى والصابئين من امن بالله واليوم الاخر وعمل صالحا فلهم اجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون","dt":"[62] ان المؤمنين من هذه الامه، الذين صدقوا بالله ورسله، وعملوا بشرعه، والذين كانوا قبل بعثه محمد -صلى الله عليه وسلم- من الامم السالفه من اليهود، والنصارى، والصابئين -وهم قوم باقون على فطرتهم، ولا دين مقرر لهم يتبعونه- هؤلاء جميعا اذا صدقوا بالله تصديقا صحيحا خالصا، وبيوم البعث والجزاء، وعملوا عملا مرضيا عند الله، فثوابهم ثابت لهم عند ربهم، ولا خوف عليهم فيما يستقبلونه من امر الاخره، ولا هم يحزنون على ما فاتهم من امور الدنيا. واما بعد بعثه محمد -صلى الله عليه وسلم- خاتما للنبيين والمرسلين الى الناس كافه، فلا يقبل الله من احد دينا غير ما جاء به، وهو الاسلام."},{"id":"70","s":2,"a":63,"at":"واذ اخذنا ميثاقكم ورفعنا فوقكم الطور خذوا ما اتيناكم بقوه واذكروا ما فيه لعلكم تتقون","dt":"[63] واذكروا -يا بني اسرائيل- حين اخذنا العهد المؤكد منكم بالايمان بالله وافراده بالعباده، ورفعنا جبل الطور فوقكم، وقلنا لكم: خذوا الكتاب الذي اعطيناكم بجد واجتهاد واحفظوه، والا اطبقنا عليكم الجبل، ولا تنسوا التوراه قولا وعملا؛ كي تتقوني وتخافوا عقابي."},{"id":"71","s":2,"a":64,"at":"ثم توليتم من بعد ذلك فلولا فضل الله عليكم ورحمته لكنتم من الخاسرين","dt":"[64] ثم خالفتم وعصيتم مره اخرى، بعد اخذ الميثاق ورفع الجبل كشانكم دائما. فلولا فضل الله عليكم ورحمته بالتوبه، والتجاوز عن خطاياكم، لصرتم من الخاسرين في الدنيا والاخره."},{"id":"72","s":2,"a":65,"at":"ولقد علمتم الذين اعتدوا منكم في السبت فقلنا لهم كونوا قرده خاسئين","dt":"[65] ولقد علمتم -يا معشر اليهود- ما حل من الباس باسلافكم من اهل القريه التي عصت امر الله، فيما اخذه عليهم من تعظيم السبت، فاحتالوا لاصطياد السمك في يوم السبت بوضع الشباك وحفر البرك، ثم اصطادوا السمك يوم الاحد؛ حيله الى المحرم، فلما فعلوا ذلك، مسخهم الله قرده منبوذين."},{"id":"73","s":2,"a":66,"at":"فجعلناها نكالا لما بين يديها وما خلفها وموعظه للمتقين","dt":"[66] فجعلنا هذه القريه عبره لمن بحضرتها من القرى، يبلغهم خبرها وما حل بها، وعبره لمن يعمل بعدها مثل تلك الذنوب، وجعلناها تذكره للصالحين؛ ليعلموا انهم على الحق، فيثبتوا عليه."},{"id":"74","s":2,"a":67,"at":"واذ قال موسى لقومه ان الله يامركم ان تذبحوا بقره قالوا اتتخذنا هزوا قال اعوذ بالله ان اكون من الجاهلين","dt":"[67] واذكروا –يا بني اسرائيل- جنايه اسلافكم، وكثره تعنتهم وجدالهم لموسى عليه الصلاه والسلام، حين قال لهم: ان الله يامركم ان تذبحوا بقره، فقالوا -مستكبرين-: اتجعلنا موضعا للسخريه والاستخفاف؟ فرد عليهم موسى بقوله: استجير بالله ان اكون من المستهزئين."},{"id":"75","s":2,"a":68,"at":"قالوا ادع لنا ربك يبين لنا ما هي قال انه يقول انها بقره لا فارض ولا بكر عوان بين ذلك فافعلوا ما تؤمرون","dt":"[68] قالوا: ادع لنا ربك يوضح لنا صفه هذه البقره، فاجابهم: ان الله يقول لكم: صفتها الا تكون مسنه هرمه، ولا صغيره فتيه، وانما هي متوسطه بينهما، فسارعوا الى امتثال امر ربكم."},{"id":"76","s":2,"a":69,"at":"قالوا ادع لنا ربك يبين لنا ما لونها قال انه يقول انها بقره صفراء فاقع لونها تسر الناظرين","dt":"[69] فعادوا الى جدالهم قائلين: ادع لنا ربك يوضح لنا لونها. قال: انه يقول: انها بقره صفراء شديده الصفره، تسر من ينظر اليها."},{"id":"77","s":2,"a":70,"at":"قالوا ادع لنا ربك يبين لنا ما هي ان البقر تشابه علينا وانا ان شاء الله لمهتدون","dt":"[70] قال بنو اسرائيل لموسى: ادع لنا ربك يوضح لنا صفات اخرى غير ما سبق؛ لان البقر -بهذه الصفات- كثير فاشتبه علينا ماذا نختار؟ واننا -ان شاء الله- لمهتدون الى البقره المامور بذبحها."},{"id":"78","s":2,"a":71,"at":"قال انه يقول انها بقره لا ذلول تثير الارض ولا تسقي الحرث مسلمه لا شيه فيها قالوا الان جئت بالحق فذبحوها وما كادوا يفعلون","dt":"[71] قال لهم موسى: ان الله يقول: انها بقره غير مذلله للعمل في حراثه الارض للزراعه، وغير معده للسقي من الساقيه، وخاليه من العيوب جميعها، وليس فيها علامه من لون غير لون جلدها. قالوا: الان جئت بحقيقه وصف البقره، فاضطروا الى ذبحها بعد طول المراوغه، وقد قاربوا الا يفعلوا ذلك لعنادهم. وهكذا شددوا فشدد الله عليهم."},{"id":"79","s":2,"a":72,"at":"واذ قتلتم نفسا فاداراتم فيها والله مخرج ما كنتم تكتمون","dt":"[72] واذكروا اذ قتلتم نفسا فتنازعتم بشانها، كل يدفع عن نفسه تهمه القتل، والله مخرج ما كنتم تخفون من قتل القتيل."},{"id":"80","s":2,"a":73,"at":"فقلنا اضربوه ببعضها كذلك يحي الله الموتى ويريكم اياته لعلكم تعقلون","dt":"[73] فقلنا: اضربوا القتيل بجزء من هذه البقره المذبوحه، فان الله سيبعثه حيا، ويخبركم عن قاتله. فضربوه ببعضها فاحياه الله واخبر بقاتله. كذلك يحيي الله الموتى يوم القيامه، ويريكم –يا بني اسرائيل- معجزاته الداله على كمال قدرته تعالى؛ لكي تتفكروا بعقولكم، فتمتنعوا عن معاصيه."},{"id":"81","s":2,"a":74,"at":"ثم قست قلوبكم من بعد ذلك فهي كالحجاره او اشد قسوه وان من الحجاره لما يتفجر منه الانهار وان منها لما يشقق فيخرج منه الماء وان منها لما يهبط من خشيه الله وما الله بغافل عما تعملون","dt":"[74] ولكنكم لم تنتفعوا بذلك؛ اذ بعد كل هذه المعجزات الخارقه اشتدت قلوبكم وغلظت، فلم ينفذ اليها خير، ولم تلن امام الايات الباهره التي اريتكموها، حتى صارت قلوبكم مثل الحجاره الصماء، بل هي اشد منها غلظه؛ لان من الحجاره ما يتسع وينفرج حتى تنصب منه المياه صبا، فتصير انهارا جاريه، ومن الحجاره ما يتصدع فينشق، فتخرج منه العيون والينابيع، ومن الحجاره ما يسقط من اعالي الجبال من خشيه الله تعالى وتعظيمه. وما الله بغافل عما تعملون."},{"id":"82","s":2,"a":75,"at":"افتطمعون ان يؤمنوا لكم وقد كان فريق منهم يسمعون كلام الله ثم يحرفونه من بعد ما عقلوه وهم يعلمون","dt":"[75] ايها المسلمون انسيتم افعال بني اسرائيل، فطمعت نفوسكم ان يصدق اليهود بدينكم؟ وقد كان علماؤهم يسمعون كلام الله من التوراه، ثم يحرفونه بصرفه الى غير معناه الصحيح بعد ما عقلوا حقيقته، او بتحريف الفاظه، وهم يعلمون انهم يحرفون كلام رب العالمين عمدا وكذبا."},{"id":"83","s":2,"a":76,"at":"واذا لقوا الذين امنوا قالوا امنا واذا خلا بعضهم الى بعض قالوا اتحدثونهم بما فتح الله عليكم ليحاجوكم به عند ربكم افلا تعقلون","dt":"[76] هؤلاء اليهود اذا لقوا الذين امنوا قالوا بلسانهم: امنا بدينكم ورسولكم المبشر به في التوراه، واذا خلا بعض هؤلاء المنافقين من اليهود الى بعض قالوا في انكار: اتحدثون المؤمنين بما بين الله لكم في التوراه من امر محمد؛ لتكون لهم الحجه عليكم عند ربكم يوم القيامه؟ افلا تفقهون فتحذروا؟"},{"id":"84","s":2,"a":77,"at":"او لا يعلمون ان الله يعلم ما يسرون وما يعلنون","dt":"[77] ايفعلون كل هذه الجرائم، ولا يعلمون ان الله يعلم جميع ما يخفونه وما يظهرونه؟"},{"id":"85","s":2,"a":78,"at":"ومنهم اميون لا يعلمون الكتاب الا اماني وان هم الا يظنون","dt":"[78] ومن اليهود جماعه يجهلون القراءه والكتابه، ولا يعلمون التوراه وما فيها من صفات نبي الله ورسوله محمد -صلى الله عليه وسلم-، وما عندهم من ذلك الا اكاذيب وظنون فاسده."},{"id":"86","s":2,"a":79,"at":"فويل للذين يكتبون الكتاب بايديهم ثم يقولون هذا من عند الله ليشتروا به ثمنا قليلا فويل لهم مما كتبت ايديهم وويل لهم مما يكسبون","dt":"[79] فهلاك ووعيد شديد لاحبار السوء من اليهود الذين يكتبون الكتاب بايديهم، ثم يقولون: هذا من عند الله، وهو مخالف لما انزل الله على نبيه موسى عليه الصلاه والسلام؛ لياخذوا في مقابل هذا عرض الدنيا. فلهم عقوبه مهلكه بسبب كتابتهم هذا الباطل بايديهم، ولهم عقوبه مهلكه بسبب ما ياخذونه في المقابل من المال الحرام، كالرشوه وغيرها."},{"id":"87","s":2,"a":80,"at":"وقالوا لن تمسنا النار الا اياما معدوده قل اتخذتم عند الله عهدا فلن يخلف الله عهده ام تقولون على الله ما لا تعلمون","dt":"[80] وقال بنو اسرائيل: لن تصيبنا النار في الاخره الا اياما قليله العدد. قل لهم -ايها الرسول مبطلا دعواهم-: اعندكم عهد من الله بهذا، فان الله لا يخلف عهده؟ بل انكم تقولون على الله ما لا تعلمون بافترائكم الكذب."},{"id":"88","s":2,"a":81,"at":"بلى من كسب سيئه واحاطت به خطيئته فاولئك اصحاب النار هم فيها خالدون","dt":"[81] فحكم الله ثابت: ان من ارتكب الاثام حتى جرته الى الكفر، واستولت عليه ذنوبه من جميع جوانبه -وهذا لا يكون الا فيمن اشرك بالله- فاولئك هم المشركون والكفار الذين يلازمون نار جهنم ملازمه دائمه لا تنقطع."},{"id":"89","s":2,"a":82,"at":"والذين امنوا وعملوا الصالحات اولئك اصحاب الجنه هم فيها خالدون","dt":"[82] وحكم الله الثابت في مقابل هذا: ان الذين صدقوا بالله ورسله تصديقا خالصا، وعملوا الاعمال المتفقه مع شريعه الله التي اوحاها الى رسله، هؤلاء يلازمون الجنه في الاخره ملازمه دائمه لا تنقطع."},{"id":"90","s":2,"a":83,"at":"واذ اخذنا ميثاق بني اسرائيل لا تعبدون الا الله وبالوالدين احسانا وذي القربى واليتامى والمساكين وقولوا للناس حسنا واقيموا الصلاه واتوا الزكاه ثم توليتم الا قليلا منكم وانتم معرضون","dt":"[83] واذكروا يا بني اسرائيل حين اخذنا عليكم عهدا مؤكدا: بان تعبدوا الله وحده لا شريك له، وان تحسنوا للوالدين، وللاقربين، وللاولاد الذين مات اباؤهم وهم دون بلوغ الحلم، وللمحتاجين الذين لا يملكون ما يكفيهم ويسد حاجتهم، وان تقولوا للناس اطيب الكلام، مع اداء الصلاه وايتاء الزكاه، ثم اعرضتم ونقضتم العهد -الا قليلا منكم ثبت عليه- وانتم مستمرون في اعراضكم."},{"id":"91","s":2,"a":84,"at":"واذ اخذنا ميثاقكم لا تسفكون دماءكم ولا تخرجون انفسكم من دياركم ثم اقررتم وانتم تشهدون","dt":"[84] واذكروا -يا بني اسرائيل- حين اخذنا عليكم عهدا مؤكدا في التوراه: يحرم سفك بعضكم دم بعض، واخراج بعضكم بعضا من دياركم، ثم اعترفتم بذلك، وانتم تشهدون على صحته."},{"id":"92","s":2,"a":85,"at":"ثم انتم هؤلاء تقتلون انفسكم وتخرجون فريقا منكم من ديارهم تظاهرون عليهم بالاثم والعدوان وان ياتوكم اسارى تفادوهم وهو محرم عليكم اخراجهم افتؤمنون ببعض الكتاب وتكفرون ببعض فما جزاء من يفعل ذلك منكم الا خزي في الحياه الدنيا ويوم القيامه يردون الى اشد العذاب وما الله بغافل عما تعملون","dt":"[85] ثم انتم يا هؤلاء يقتل بعضكم بعضا، ويخرج بعضكم بعضا من ديارهم، ويتقوى كل فريق منكم على اخوانه بالاعداء بغيا وعدوانا. وان ياتوكم اسارى في يد الاعداء سعيتم في تحريرهم من الاسر، بدفع الفديه، مع انه محرم عليكم اخراجهم من ديارهم. ما اقبح ما تفعلون حين تؤمنون ببعض احكام التوراه وتكفرون ببعضها! فليس جزاء من يفعل ذلك منكم الا ذلا وفضيحه في الدنيا. ويوم القيامه يردهم الله الى افظع العذاب في النار. وما الله بغافل عما تعملون."},{"id":"93","s":2,"a":86,"at":"اولئك الذين اشتروا الحياه الدنيا بالاخره فلا يخفف عنهم العذاب ولا هم ينصرون","dt":"[86] اولئك هم الذين اثروا الحياه الدنيا على الاخره، فلا يخفف عنهم العذاب، وليس لهم ناصر ينصرهم من عذاب الله."},{"id":"94","s":2,"a":87,"at":"ولقد اتينا موسى الكتاب وقفينا من بعده بالرسل واتينا عيسى ابن مريم البينات وايدناه بروح القدس افكلما جاءكم رسول بما لا تهوى انفسكم استكبرتم ففريقا كذبتم وفريقا تقتلون","dt":"[87] ولقد اعطينا موسى التوراه، واتبعناه برسل من بني اسرائيل، واعطينا عيسى بن مريم المعجزات الواضحات، وقويناه بجبريل عليه السلام. افكلما جاءكم رسول بوحي من عند الله لا يوافق اهواءكم، استعليتم عليه، فكذبتم فريقا وتقتلون فريقا؟"},{"id":"95","s":2,"a":88,"at":"وقالوا قلوبنا غلف بل لعنهم الله بكفرهم فقليلا ما يؤمنون","dt":"[88] وقال بنو اسرائيل لنبي الله ورسوله محمد -صلى الله عليه وسلم-: قلوبنا مغطاه، لا ينفذ اليها قولك. وليس الامر كما ادعوا، بل قلوبهم ملعونه، مطبوع عليها، وهم مطرودون من رحمه الله بسبب جحودهم، فلا يؤمنون الا ايمانا قليلا لا ينفعهم."},{"id":"96","s":2,"a":89,"at":"ولما جاءهم كتاب من عند الله مصدق لما معهم وكانوا من قبل يستفتحون على الذين كفروا فلما جاءهم ما عرفوا كفروا به فلعنه الله على الكافرين","dt":"[89] وحين جاءهم القران من عند الله مصدقا لما معهم من التوراه جحدوه، وانكروا نبوه محمد -صلى الله عليه وسلم-، وكانوا قبل بعثته يستنصرون به على مشركي العرب، ويقولون: قرب مبعث نبي اخر الزمان، وسنتبعه ونقاتلكم معه. فلما جاءهم الرسول الذي عرفوا صفاته وصدقه كفروا به وكذبوه. فلعنه الله على كل من كفر بنبي الله ورسوله محمد -صلى الله عليه وسلم-، وكتابه الذي اوحاه الله اليه."},{"id":"97","s":2,"a":90,"at":"بئسما اشتروا به انفسهم ان يكفروا بما انزل الله بغيا ان ينزل الله من فضله على من يشاء من عباده فباءوا بغضب على غضب وللكافرين عذاب مهين","dt":"[90] قبح ما اختاره بنو اسرائيل لانفسهم؛ اذ استبدلوا الكفر بالايمان ظلما وحسدا لانزال الله -من فضله- القران على نبي الله ورسوله محمد -صلى الله عليه وسلم-، فرجعوا بغضب من الله عليهم بسبب جحودهم بالنبي محمد -صلى الله عليه وسلم-، بعد غضب الله كذلك عليهم بسبب تحريفهم التوراه. وللجاحدين نبوه محمد -صلى الله عليه وسلم- عذاب يذلهم ويخزيهم."},{"id":"98","s":2,"a":91,"at":"واذا قيل لهم امنوا بما انزل الله قالوا نؤمن بما انزل علينا ويكفرون بما وراءه وهو الحق مصدقا لما معهم قل فلم تقتلون انبياء الله من قبل ان كنتم مؤمنين","dt":"[91] واذا قال بعض المسلمين لليهود: صدقوا بما انزل الله من القران، قالوا: نحن نصدق بما انزل الله على انبيائنا، ويجحدون ما انزل الله بعد ذلك، وهو الحق مصدقا لما معهم. فلو كانوا يؤمنون بكتبهم حقا لامنوا بالقران الذي صدقها. قل لهم -ايها الرسول-: ان كنتم مؤمنين بما انزل الله عليكم، فلماذا قتلتم انبياء الله من قبل؟"},{"id":"99","s":2,"a":92,"at":"ولقد جاءكم موسى بالبينات ثم اتخذتم العجل من بعده وانتم ظالمون","dt":"[92] ولقد جاءكم نبي الله موسى بالمعجزات الواضحات الداله على صدقه، كالطوفان والجراد والقمل والضفادع، وغير ذلك مما ذكره الله في القران العظيم، ومع ذلك اتخذتم العجل معبودا، بعد ذهاب موسى الى ميقات ربه، وانتم متجاوزون حدود الله."},{"id":"100","s":2,"a":93,"at":"واذ اخذنا ميثاقكم ورفعنا فوقكم الطور خذوا ما اتيناكم بقوه واسمعوا قالوا سمعنا وعصينا واشربوا في قلوبهم العجل بكفرهم قل بئسما يامركم به ايمانكم ان كنتم مؤمنين","dt":"[93] واذكروا حين اخذنا عليكم عهدا مؤكدا بقبول ما جاءكم به موسى من التوراه، فنقضتم العهد، فرفعنا جبل الطور فوق رؤوسكم، وقلنا لكم: خذوا ما اتيناكم بجد، واسمعوا واطيعوا، والا اسقطنا الجبل عليكم، فقلتم: سمعنا قولك وعصينا امرك؛ لان عباده العجل قد امتزجت بقلوبكم بسبب تماديكم في الكفر. قل لهم -ايها الرسول-: قبح ما يامركم به ايمانكم من الكفر والضلال، ان كنتم مصدقين بما انزل الله عليكم."},{"id":"101","s":2,"a":94,"at":"قل ان كانت لكم الدار الاخره عند الله خالصه من دون الناس فتمنوا الموت ان كنتم صادقين","dt":"[94] قل -ايها الرسول- لليهود الذين يدعون ان الجنه خاصه بهم؛ لزعمهم انهم اولياء الله من دون الناس، وانهم ابناؤه واحباؤه: ان كان الامر كذلك فادعوا على الكاذبين منكم او من غيركم بالموت، ان كنتم صادقين في دعواكم هذه."},{"id":"102","s":2,"a":95,"at":"ولن يتمنوه ابدا بما قدمت ايديهم والله عليم بالظالمين","dt":"[95] ولن يفعلوا ذلك ابدا؛ لما يعرفونه من صدق النبي محمد -صلى الله عليه وسلم- ومن كذبهم وافترائهم، وبسبب ما ارتكبوه من الكفر والعصيان، المؤديين الى حرمانهم من الجنه ودخول النار. والله تعالى عليم بالظالمين من عباده، وسيجازيهم على ذلك."},{"id":"103","s":2,"a":96,"at":"ولتجدنهم احرص الناس على حياه ومن الذين اشركوا يود احدهم لو يعمر الف سنه وما هو بمزحزحه من العذاب ان يعمر والله بصير بما يعملون","dt":"[96] ولتعلمن -ايها الرسول- ان اليهود اشد الناس رغبه في طول الحياه ايا كانت هذه الحياه من الذله والمهانه، بل تزيد رغبتهم في طول الحياه على رغبات المشركين. يتمنى اليهودي ان يعيش الف سنه، ولا يبعده هذا العمر الطويل -ان حصل- من عذاب الله. والله تعالى لا يخفى عليه شيء من اعمالهم، وسيجازيهم عليها بما يستحقونه من العذاب."},{"id":"104","s":2,"a":97,"at":"قل من كان عدوا لجبريل فانه نزله على قلبك باذن الله مصدقا لما بين يديه وهدى وبشرى للمؤمنين","dt":"[97] قل -ايها الرسول- لليهود حين قالوا: ان جبريل هو عدونا من الملائكه: من كان عدوا لجبريل فانه نزل القران على قلبك باذن الله تعالى مصدقا لما سبقه من كتب الله، وهاديا الى الحق، ومبشرا للمصدقين به بكل خير في الدنيا والاخره."},{"id":"105","s":2,"a":98,"at":"من كان عدوا لله وملائكته ورسله وجبريل وميكال فان الله عدو للكافرين","dt":"[98] من عادى الله وملائكته، ورسله من الملائكه او البشر، وبخاصه الملكان جبريل وميكال؛ لان اليهود زعموا ان جبريل عدوهم، وميكال وليهم، فاعلمهم الله انه من عادى واحدا منهما فقد عادى الاخر، وعادى الله ايضا، فان الله عدو للجاحدين ما انزل على رسوله محمد -صلى الله عليه وسلم-."},{"id":"106","s":2,"a":99,"at":"ولقد انزلنا اليك ايات بينات وما يكفر بها الا الفاسقون","dt":"[99] ولقد انزلنا اليك -ايها الرسول- ايات بينات واضحات، تدل على انك رسول من الله صدقا وحقا، وما ينكر تلك الايات الا الخارجون عن دين الله."},{"id":"107","s":2,"a":100,"at":"او كلما عاهدوا عهدا نبذه فريق منهم بل اكثرهم لا يؤمنون","dt":"[100] ما اقبح حال بني اسرائيل في نقضهم للعهود ! فكلما عاهدوا عهدا طرح ذلك العهد فريق منهم، ونقضوه، فتراهم يبرمون العهد اليوم وينقضونه غدا، بل اكثرهم لا يصدقون بما جاء به نبي الله ورسوله محمد -صلى الله عليه وسلم-."},{"id":"108","s":2,"a":101,"at":"ولما جاءهم رسول من عند الله مصدق لما معهم نبذ فريق من الذين اوتوا الكتاب كتاب الله وراء ظهورهم كانهم لا يعلمون","dt":"[101] ولما جاءهم محمد رسول الله -صلى الله عليه وسلم- بالقران الموافق لما معهم من التوراه طرح فريق منهم كتاب الله، وجعلوه وراء ظهورهم، شانهم شان الجهال الذين لا يعلمون حقيقته."},{"id":"109","s":2,"a":102,"at":"واتبعوا ما تتلوا الشياطين على ملك سليمان وما كفر سليمان ولكن الشياطين كفروا يعلمون الناس السحر وما انزل على الملكين ببابل هاروت وماروت وما يعلمان من احد حتى يقولا انما نحن فتنه فلا تكفر فيتعلمون منهما ما يفرقون به بين المرء وزوجه وما هم بضارين به من احد الا باذن الله ويتعلمون ما يضرهم ولا ينفعهم ولقد علموا لمن اشتراه ما له في الاخره من خلاق ولبئس ما شروا به انفسهم لو كانوا يعلمون","dt":"[102] واتبع اليهود ما تحدث الشياطين به السحره على عهد ملك سليمان بن داود. وما كفر سليمان وما تعلم السحر، ولكن الشياطين هم الذين كفروا بالله حين علموا الناس السحر؛ افسادا لدينهم. وكذلك اتبع اليهود السحر الذي انزل على الملكين هاروت وماروت، بارض «بابل» في «العراق»؛ امتحانا وابتلاء من الله لعباده، وما يعلم الملكان من احد حتى ينصحاه ويحذراه من تعلم السحر، ويقولا له: لا تكفر بتعلم السحر وطاعه الشياطين. فيتعلم الناس من الملكين ما يحدثون به الكراهيه بين الزوجين حتى يتفرقا. ولا يستطيع السحره ان يضروا به احدا الا باذن الله وقضائه. وما يتعلم السحره الا شرا يضرهم ولا ينفعهم، وقد نقلته الشياطين الى اليهود، فشاع فيهم حتى فضلوه على كتاب الله. ولقد علم اليهود ان من اختار السحر وترك الحق ما له في الاخره من نصيب في الخير. ولبئس ما باعوا به انفسهم من السحر والكفر عوضا عن الايمان ومتابعه الرسول، لو كان لهم علم يثمر العمل بما وعظوا به."},{"id":"110","s":2,"a":103,"at":"ولو انهم امنوا واتقوا لمثوبه من عند الله خير لو كانوا يعلمون","dt":"[103] ولو ان اليهود امنوا وخافوا الله لايقنوا ان ثواب الله خير لهم من السحر ومما اكتسبوه به، لو كانوا يعلمون ما يحصل بالايمان والتقوى من الثواب والجزاء علما حقيقيا لامنوا."},{"id":"111","s":2,"a":104,"at":"ياايها الذين امنوا لا تقولوا راعنا وقولوا انظرنا واسمعوا وللكافرين عذاب اليم","dt":"[104] يا ايها الذين امنوا لا تقولوا للرسول محمد -صلى الله عليه وسلم-: راعنا، اي: راعنا سمعك، فافهم عنا وافهمنا؛ لان اليهود كانوا يقولونها للنبي -صلى الله عليه وسلم-، يلوون السنتهم بها، يقصدون سبه ونسبته الى الرعونه، وقولوا -ايها المؤمنون- بدلا منها: انظرنا، اي انظر الينا وتعهدنا، وهي تؤدي المعنى المطلوب نفسه، واسمعوا ما يتلى عليكم من كتاب ربكم وافهموه. وللجاحدين عذاب موجع."},{"id":"112","s":2,"a":105,"at":"ما يود الذين كفروا من اهل الكتاب ولا المشركين ان ينزل عليكم من خير من ربكم والله يختص برحمته من يشاء والله ذو الفضل العظيم","dt":"[105] ما يحب الكفار من اهل الكتاب والمشركين ان ينزل عليكم ادنى خير من ربكم قرانا او علما، او نصرا او بشاره. والله يختص برحمته من يشاء من عباده بالنبوه والرساله. والله ذو الاحسان والعطاء الكثير الواسع."},{"id":"113","s":2,"a":106,"at":"ما ننسخ من ايه او ننسها نات بخير منها او مثلها الم تعلم ان الله على كل شيء قدير","dt":"[106] ما نبدل من ايه او نزلها من القلوب والاذهان نات بانفع لكم منها، او نات بمثلها في التكليف والثواب، ولكل حكمه. الم تعلم -ايها النبي- انت وامتك ان الله قادر لا يعجزه شيء؟"},{"id":"114","s":2,"a":107,"at":"الم تعلم ان الله له ملك السموات والارض وما لكم من دون الله من ولي ولا نصير","dt":"[107] اما علمت -ايها النبي- انت وامتك ان الله تعالى هو المالك المتصرف في السموات والارض؟ يفعل ما يشاء، ويحكم ما يريد، ويامر عباده وينهاهم كيفما شاء، وعليهم الطاعه والقبول. وليعلم من عصى ان ليس لاحد من دون الله من ولي يتولاهم، ولا نصير يمنعهم من عذاب الله."},{"id":"115","s":2,"a":108,"at":"ام تريدون ان تسالوا رسولكم كما سئل موسى من قبل ومن يتبدل الكفر بالايمان فقد ضل سواء السبيل","dt":"[108] بل اتريدون -ايها الناس- ان تطلبوا من رسولكم محمد -صلى الله عليه وسلم- اشياء بقصد العناد والمكابره، كما طلب مثل ذلك من موسى. واعلموا ان من يختر الكفر ويترك الايمان فقد خرج عن صراط الله المستقيم الى الجهل والضلال."},{"id":"116","s":2,"a":109,"at":"ود كثير من اهل الكتاب لو يردونكم من بعد ايمانكم كفارا حسدا من عند انفسهم من بعد ما تبين لهم الحق فاعفوا واصفحوا حتى ياتي الله بامره ان الله على كل شيء قدير","dt":"[109] تمنى كثير من اهل الكتاب ان يرجعوكم بعد ايمانكم كفارا كما كنتم من قبل تعبدون الاصنام؛ بسبب الحقد الذي امتلات به نفوسهم من بعد ما تبين لهم صدق نبي الله ورسوله محمد -صلى الله عليه وسلم- فيما جاء به، فتجاوزوا عما كان منهم من اساءه وخطا، واصفحوا عن جهلهم، حتى ياتي الله بحكمه فيهم بقتالهم (وقد جاء ووقع)، وسيعاقبهم لسوء افعالهم. ان الله على كل شيء قدير لا يعجزه شيء."},{"id":"117","s":2,"a":110,"at":"واقيموا الصلاه واتوا الزكاه وما تقدموا لانفسكم من خير تجدوه عند الله ان الله بما تعملون بصير","dt":"[110] واشتغلوا -ايها المؤمنون- باداء الصلاه على وجهها الصحيح، واعطاء الزكاه المفروضه. واعلموا ان كل خير تقدمونه لانفسكم تجدون ثوابه عند الله في الاخره. انه تعالى بصير بكل اعمالكم، وسيجازيكم عليها."},{"id":"118","s":2,"a":111,"at":"وقالوا لن يدخل الجنه الا من كان هودا او نصارى تلك امانيهم قل هاتوا برهانكم ان كنتم صادقين","dt":"[111] ادعى كل من اليهود والنصارى ان الجنه خاصه بطائفته لا يدخلها غيرهم، تلك اوهامهم الفاسده. قل لهم -ايها الرسول-: احضروا دليلكم على صحه ما تدعون ان كنتم صادقين في دعواكم."},{"id":"119","s":2,"a":112,"at":"بلى من اسلم وجهه لله وهو محسن فله اجره عند ربه ولا خوف عليهم ولا هم يحزنون","dt":"[112] ليس الامر كما زعموا ان الجنه تختص بطائفه دون غيرها، وانما يدخل الجنه من اخلص لله وحده لا شريك له، وهو متبع للرسول محمد -صلى الله عليه وسلم- في كل اقواله واعماله. فمن فعل ذلك فله ثواب عمله عند ربه في الاخره، وهو دخول الجنه، وهم لا يخافون فيما يستقبلونه من امر الاخره، ولا هم يحزنون على ما فاتهم من حظوظ الدنيا."},{"id":"120","s":2,"a":113,"at":"وقالت اليهود ليست النصارى على شيء وقالت النصارى ليست اليهود على شيء وهم يتلون الكتاب كذلك قال الذين لا يعلمون مثل قولهم فالله يحكم بينهم يوم القيامه فيما كانوا فيه يختلفون","dt":"[113] وقالت اليهود: ليست النصارى على شيء من الدين الصحيح، وكذلك قالت النصارى في اليهود وهم يقرؤون التوراه والانجيل، وفيهما وجوب الايمان بالانبياء جميعا. كذلك قال الذين لا يعلمون من مشركي العرب وغيرهم مثل قولهم، اي قالوا لكل ذي دين: لست على شيء، فالله يفصل بينهم يوم القيامه فيما اختلفوا فيه من امر الدين، ويجازي كلا بعمله."},{"id":"121","s":2,"a":114,"at":"ومن اظلم ممن منع مساجد الله ان يذكر فيها اسمه وسعى في خرابها اولئك ما كان لهم ان يدخلوها الا خائفين لهم في الدنيا خزي ولهم في الاخره عذاب عظيم","dt":"[114] لا احد اظلم من الذين منعوا ذكر الله في المساجد من اقام الصلاه، وتلاوه القران، ونحو ذلك، وجدوا في تخريبها بالهدم، او الاغلاق، او بمنع المؤمنين منها. اولئك الظالمون ما كان ينبغي لهم ان يدخلوا المساجد الا على خوف ووجل من العقوبه. لهم بذلك ذل وفضيحه في الدنيا، ولهم في الاخره عذاب شديد."},{"id":"122","s":2,"a":115,"at":"ولله المشرق والمغرب فاينما تولوا فثم وجه الله ان الله واسع عليم","dt":"[115] ولله جهتا شروق الشمس وغروبها وما بينهما، فهو مالك الارض كلها. فاي جهه توجهتم اليها في الصلاه بامر الله لكم فانكم مبتغون وجهه، لم تخرجوا عن ملكه وطاعته. ان الله واسع الرحمه بعباده، عليم بافعالهم، لا يغيب عنه منها شيء."},{"id":"123","s":2,"a":116,"at":"وقالوا اتخذ الله ولدا سبحانه بل له ما في السموات والارض كل له قانتون","dt":"[116] وقالت اليهود والنصارى والمشركون: اتخذ الله لنفسه ولدا، تنزه الله -سبحانه- عن هذا القول الباطل، بل كل ما في السموات والارض ملكه وعبيده، وهم جميعا خاضعون له، مسخرون تحت تدبيره."},{"id":"124","s":2,"a":117,"at":"بديع السموات والارض واذا قضى امرا فانما يقول له كن فيكون","dt":"[117] والله تعالى هو خالق السموات والارض على غير مثال سبق. واذا قدر امرا واراد كونه فانما يقول له: «كن» فيكون."},{"id":"125","s":2,"a":118,"at":"وقال الذين لا يعلمون لولا يكلمنا الله او تاتينا ايه كذلك قال الذين من قبلهم مثل قولهم تشابهت قلوبهم قد بينا الايات لقوم يوقنون","dt":"[118] وقال الجهله من اهل الكتاب وغيرهم لنبي الله ورسوله محمد -صلى الله عليه وسلم- على سبيل العناد: هلا يكلمنا الله مباشره ليخبرنا انك رسوله، او تاتينا معجزه من الله تدل على صدقك. مثل هذا القول قالته الامم من قبل لرسلها عنادا ومكابره؛ بسبب تشابه قلوب السابقين واللاحقين في الكفر والضلال. قد اوضحنا الايات للذين يصدقون تصديقا جازما؛ لكونهم مؤمنين بالله تعالى، متبعين ما شرعه لهم."},{"id":"126","s":2,"a":119,"at":"انا ارسلناك بالحق بشيرا ونذيرا ولا تسال عن اصحاب الجحيم","dt":"[119] انا ارسلناك -ايها الرسول- بالدين الحق المؤيد بالحجج والمعجزات، فبلغه للناس مع تبشير المؤمنين بخيري الدنيا والاخره، وتخويف المعاندين بما ينتظرهم من عذاب الله، ولست -بعد البلاغ- مسؤولا عن كفر من كفر بك؛ فانهم يدخلون النار يوم القيامه ولا يخرجون منها."},{"id":"127","s":2,"a":120,"at":"ولن ترضى عنك اليهود ولا النصارى حتى تتبع ملتهم قل ان هدى الله هو الهدى ولئن اتبعت اهواءهم بعد الذي جاءك من العلم ما لك من الله من ولي ولا نصير","dt":"[120] ولن ترضى عنك -ايها الرسول- اليهود ولا النصارى الا اذا تركت دينك واتبعت دينهم. قل لهم: ان دين الاسلام هو الدين الصحيح. ولئن اتبعت اهواء هؤلاء بعد الذي جاءك من الوحي ما لك عند الله من ولي ينفعك، ولا نصير ينصرك. وهذا الخطاب وان كان خاصا بالنبي -صلى الله عليه وسلم-، فهو موجه الى الامه عامه."},{"id":"128","s":2,"a":121,"at":"الذين اتيناهم الكتاب يتلونه حق تلاوته اولئك يؤمنون به ومن يكفر به فاولئك هم الخاسرون","dt":"[121] الذين اعطيناهم الكتاب من اليهود والنصارى، يقرؤونه القراءه الصحيحه، و يتبعونه حق الاتباع، ويؤمنون بما جاء فيه من الايمان برسل الله، ومنهم خاتمهم نبينا ورسولنا محمد -صلى الله عليه وسلم-، ولا يحرفون ولا يبدلون ما جاء فيه. هؤلاء هم الذين يؤمنون بالنبي محمد -صلى الله عليه وسلم- وبما انزل عليه، واما الذين بدلوا بعض الكتاب وكتموا بعضه، فهؤلاء كفار بنبي الله محمد -صلى الله عليه وسلم- وبما انزل عليه، ومن يكفر به فاولئك هم اشد الناس خسرانا عند الله."},{"id":"129","s":2,"a":122,"at":"يابني اسرائيل اذكروا نعمتي التي انعمت عليكم واني فضلتكم على العالمين","dt":"[122] يا ذريه يعقوب اذكروا نعمي الكثيره عليكم، واني فضلتكم على عالمي زمانكم بكثره انبيائكم، وما انزل عليهم من الكتب."},{"id":"130","s":2,"a":123,"at":"واتقوا يوما لا تجزي نفس عن نفس شيئا ولا يقبل منها عدل ولا تنفعها شفاعه ولا هم ينصرون","dt":"[123] وخافوا اهوال يوم الحساب اذ لا تغني نفس عن نفس شيئا، ولا يقبل الله منها فديه تنجيها من العذاب، ولا تنفعها وساطه، ولا احد ينصرها."},{"id":"131","s":2,"a":124,"at":"واذ ابتلى ابراهيم ربه بكلمات فاتمهن قال اني جاعلك للناس اماما قال ومن ذريتي قال لا ينال عهدي الظالمين","dt":"[124] واذكر -ايها النبي- حين اختبر الله ابراهيم بما شرع له من تكاليف، فاداها وقام بها خير قيام. قال الله له: اني جاعلك قدوه للناس. قال ابراهيم: رب اجعل بعض نسلي ائمه فضلا منك، فاجابه الله سبحانه انه لا تحصل للظالمين الامامه في الدين."},{"id":"132","s":2,"a":125,"at":"واذ جعلنا البيت مثابه للناس وامنا واتخذوا من مقام ابراهيم مصلى وعهدنا الى ابراهيم واسماعيل ان طهرا بيتي للطائفين والعاكفين والركع السجود","dt":"[125] واذكر -ايها النبي- حين جعلنا الكعبه مرجعا للناس، ياتونه، ثم يرجعون الى اهليهم، ثم يعودون اليه، ومجمعا لهم في الحج والعمره، والطواف، والصلاه، وامنا لهم، لا يغير عليهم عدو فيه. وقلنا: اتخذوا من مقام ابراهيم مكانا للصلاه فيه، وهو الحجر الذي وقف عليه ابراهيم عند بنائه الكعبه. واوحينا الى ابراهيم وابنه اسماعيل: ان طهرا بيتي من كل رجس ودنس؛ للمتعبدين فيه بالطواف حول الكعبه، او الاعتكاف في المسجد، والصلاه فيه."},{"id":"133","s":2,"a":126,"at":"واذ قال ابراهيم رب اجعل هذا بلدا امنا وارزق اهله من الثمرات من امن منهم بالله واليوم الاخر قال ومن كفر فامتعه قليلا ثم اضطره الى عذاب النار وبئس المصير","dt":"[126] واذكر -ايها النبي- حين قال ابراهيم داعيا: رب اجعل «مكه» بلدا امنا من الخوف، وارزق اهله من انواع الثمرات، وخص بهذا الرزق من امن منهم بالله واليوم الاخر. قال الله: ومن كفر منهم فارزقه في الدنيا وامتعه متاعا قليلا، ثم الجئه مرغما الى عذاب النار. وبئس المرجع والمقام هذا المصير."},{"id":"134","s":2,"a":127,"at":"واذ يرفع ابراهيم القواعد من البيت واسماعيل ربنا تقبل منا انك انت السميع العليم","dt":"[127] واذكر -ايها النبي- حين رفع ابراهيم واسماعيل اسس الكعبه، وهما يدعوان الله في خشوع: ربنا تقبل منا صالح اعمالنا ودعاءنا، انك انت السميع لاقوال عبادك، العليم باحوالهم."},{"id":"135","s":2,"a":128,"at":"ربنا واجعلنا مسلمين لك ومن ذريتنا امه مسلمه لك وارنا مناسكنا وتب علينا انك انت التواب الرحيم","dt":"[128] ربنا واجعلنا ثابتين على الاسلام، منقادين لاحكامك، واجعل من ذريتنا امه منقاده لك، بالايمان، وبصرنا بمعالم عبادتنا لك، وتجاوز عن ذنوبنا. انك انت كثير التوبه على عبادك، واسع الرحمه بهم."},{"id":"136","s":2,"a":129,"at":"ربنا وابعث فيهم رسولا منهم يتلو عليهم اياتك ويعلمهم الكتاب والحكمه ويزكيهم انك انت العزيز الحكيم","dt":"[129] ربنا وابعث في هذه الامه رسولا من ذريه اسماعيل يتلو عليهم اياتك ويعلمهم القران والسنه، ويطهرهم من الشرك وسوء الاخلاق. انك انت العزيز الذي لا يمتنع عليه شيء، الحكيم الذي يضع الاشياء في مواضعها."},{"id":"137","s":2,"a":130,"at":"ومن يرغب عن مله ابراهيم الا من سفه نفسه ولقد اصطفيناه في الدنيا وانه في الاخره لمن الصالحين","dt":"[130] ولا احد يعرض عن دين ابراهيم -وهو الاسلام- الا سفيه جاهل، ولقد اخترنا ابراهيم في الدنيا نبيا ورسولا، وانه في الاخره لمن الصالحين الذين لهم اعلى الدرجات."},{"id":"138","s":2,"a":131,"at":"اذ قال له ربه اسلم قال اسلمت لرب العالمين","dt":"[131] وسبب هذا الاختيار مسارعته الى الاسلام دون تردد، حين قال له ربه: اخلص نفسك لله منقادا له. فاستجاب ابراهيم وقال: اسلمت لرب العالمين، اخلاصا وتوحيدا ومحبه وانابه."},{"id":"139","s":2,"a":132,"at":"ووصى بها ابراهيم بنيه ويعقوب يابني ان الله اصطفى لكم الدين فلا تموتن الا وانتم مسلمون","dt":"[132] وحث ابراهيم ويعقوب ابناءهما على الثبات على الاسلام قائلين: يا ابناءنا ان الله اختار لكم هذا الدين -وهو دين الاسلام- فلا تفارقوه ايام حياتكم، ولا ياتكم الموت الا وانتم عليه."},{"id":"140","s":2,"a":133,"at":"ام كنتم شهداء اذ حضر يعقوب الموت اذ قال لبنيه ما تعبدون من بعدي قالوا نعبد الهك واله ابائك ابراهيم واسماعيل واسحاق الها واحدا ونحن له مسلمون","dt":"[133] اكنتم -ايها اليهود- حاضرين حين جاء الموت يعقوب، اذ جمع ابناءه وسالهم: ما تعبدون من بعد موتي؟ قالوا: نعبد الهك واله ابائك ابراهيم واسماعيل واسحاق الها واحدا، ونحن له منقادون خاضعون."},{"id":"141","s":2,"a":134,"at":"تلك امه قد خلت لها ما كسبت ولكم ما كسبتم ولا تسالون عما كانوا يعملون","dt":"[134] تلك امه من اسلافكم قد مضت، لهم اعمالهم، ولكم اعمالكم، ولا تسالون عن اعمالهم، وهم لا يسالون عن اعمالكم، وكل سيجازى بما فعله، لا يؤاخذ احد بذنب احد، ولا ينفع احدا الا ايمانه وتقواه."},{"id":"142","s":2,"a":135,"at":"وقالوا كونوا هودا او نصارى تهتدوا قل بل مله ابراهيم حنيفا وما كان من المشركين","dt":"[135] وقالت اليهود لامه محمد -صلى الله عليه وسلم-: ادخلوا في دين اليهوديه تجدوا الهدايه، وقالت النصارى لهم مثل ذلك. قل لهم -ايها الرسول-: بل الهدايه ان نتبع -جميعا- مله ابراهيم، الذي مال عن كل دين باطل الى دين الحق، وما كان من المشركين بالله تعالى."},{"id":"143","s":2,"a":136,"at":"قولوا امنا بالله وما انزل الينا وما انزل الى ابراهيم واسماعيل واسحاق ويعقوب والاسباط وما اوتي موسى وعيسى وما اوتي النبيون من ربهم لا نفرق بين احد منهم ونحن له مسلمون","dt":"[136] قولوا -ايها المؤمنون- لهؤلاء اليهود والنصارى: صدقنا بالله الواحد المعبود بحق، وبما انزل الينا من القران الذي اوحاه الله الى نبيه ورسوله محمد -صلى الله عليه وسلم-، وما انزل من الصحف الى ابراهيم وابنيه اسماعيل واسحاق، والى يعقوب، والاسباط -وهم الانبياء من ولد يعقوب، الذين كانوا في قبائل بني اسرائيل الاثنتي عشره- وما اعطي موسى من التوراه، وعيسى من الانجيل، وما اعطي الانبياء جميعا من وحي ربهم، لا نفرق بين احد منهم في الايمان، ونحن خاضعون لله بالطاعه والعباده."},{"id":"144","s":2,"a":137,"at":"فان امنوا بمثل ما امنتم به فقد اهتدوا وان تولوا فانما هم في شقاق فسيكفيكهم الله وهو السميع العليم","dt":"[137] فان امن الكفار من اليهود والنصارى وغيرهم، بمثل الذي امنتم به، مما جاء به الرسول، فقد اهتدوا الى الحق، وان اعرضوا فانما هم في خلاف شديد، فسيكفيك الله -ايها الرسول- شرهم وينصرك عليهم، وهو السميع لاقوالكم، العليم باحوالكم."},{"id":"145","s":2,"a":138,"at":"صبغه الله ومن احسن من الله صبغه ونحن له عابدون","dt":"[138] الزموا دين الله الذي فطركم عليه، فليس هناك احسن من فطره الله التي فطر الناس عليها، فالزموها، وقولوا: نحن له خاضعون مطيعون لربنا في اتباعنا مله ابراهيم."},{"id":"146","s":2,"a":139,"at":"قل اتحاجوننا في الله وهو ربنا وربكم ولنا اعمالنا ولكم اعمالكم ونحن له مخلصون","dt":"[139] قل -ايها الرسول- لاهل الكتاب: اتجادلوننا في توحيد الله والاخلاص له، وهو رب العالمين جميعا، لا يختص بقوم دون قوم، ولنا اعمالنا ولكم اعمالكم، ونحن لله مخلصو العباده والطاعه لا نشرك به شيئا، ولا نعبد احدا غيره؟"},{"id":"147","s":2,"a":140,"at":"ام تقولون ان ابراهيم واسماعيل واسحاق ويعقوب والاسباط كانوا هودا او نصارى قل اانتم اعلم ام الله ومن اظلم ممن كتم شهاده عنده من الله وما الله بغافل عما تعملون","dt":"[140] بل اتقولون مجادلين في الله: ان ابراهيم واسماعيل واسحاق ويعقوب والاسباط -وهم الانبياء من ولد يعقوب، الذين كانوا في قبائل بني اسرائيل الاثنتي عشره- كانوا على دين اليهود او النصارى؟ وهذا كذب؛ فقد بعثوا وماتوا قبل نزول التوراه والانجيل . قل لهم -ايها الرسول-: اانتم اعلم بدينهم ام الله تعالى؟ وقد اخبر في القران بانهم كانوا حنفاء مسلمين، ولا احد اظلم منكم حين تخفون شهاده ثابته عندكم من الله تعالى، وتدعون خلافها افتراء على الله. وما الله بغافل عن شيء من اعمالكم، بل هو محص لها ومجازيكم عليها."},{"id":"148","s":2,"a":141,"at":"تلك امه قد خلت لها ما كسبت ولكم ما كسبتم ولا تسالون عما كانوا يعملون","dt":"[141] تلك امه من اسلافكم قد مضت، لهم اعمالهم ولكم اعمالكم، ولا تسالون عن اعمالهم، وهم لا يسالون عن اعمالكم. وفي الايه قطع للتعلق بالمخلوقين، وعدم الاغترار بالانتساب اليهم، وان العبره بالايمان بالله وعبادته وحده، واتباع رسله، وان من كفر برسول منهم فقد كفر بسائر الرسل."},{"id":"149","s":2,"a":142,"at":"سيقول السفهاء من الناس ما ولاهم عن قبلتهم التي كانوا عليها قل لله المشرق والمغرب يهدي من يشاء الى صراط مستقيم","dt":"[142] سيقول الجهال وضعاف العقول من اليهود وامثالهم، في سخريه واعتراض: ما الذي صرف هؤلاء المسلمين عن قبلتهم التي كانوا يصلون الى جهتها اول الاسلام؟ (وهي «بيت المقدس») قل لهم -ايها الرسول-: المشرق والمغرب وما بينهما ملك لله، فليست جهه من الجهات خارجه عن ملكه، يهدي من يشاء من عباده الى طريق الهدايه القويم. وفي هذا اشعار بان الشان كله لله في امتثال اوامره، فحيثما وجهنا توجهنا."},{"id":"150","s":2,"a":143,"at":"وكذلك جعلناكم امه وسطا لتكونوا شهداء على الناس ويكون الرسول عليكم شهيدا وما جعلنا القبله التي كنت عليها الا لنعلم من يتبع الرسول ممن ينقلب على عقبيه وان كانت لكبيره الا على الذين هدى الله وما كان الله ليضيع ايمانكم ان الله بالناس لرءوف رحيم","dt":"[143] وكما هديناكم -ايها المسلمون- الى الطريق الصحيح في الدين، جعلناكم امه خيارا عدولا؛ لتشهدوا على الامم في الاخره ان رسلهم بلغتهم رسالات ربهم، ويكون الرسول في الاخره -كذلك- شهيدا عليكم انه بلغكم رساله ربه. وما جعلنا -ايها الرسول- قبله «بيت المقدس» التي كنت عليها، ثم صرفناك عنها الى الكعبه ب«مكه»، الا ليظهر ما علمناه في الازل، علما يتعلق به الثواب والعقاب؛ لنميز من يتبعك ويطيعك ويستقبل معك حيث توجهت، ومن هو ضعيف الايمان فينقلب مرتدا عن دينه لشكه ونفاقه. وان هذه الحال التي هي تحول المسلم في صلاته من استقبال «بيت المقدس» الى استقبال الكعبه، لثقيله شاقه، الا على الذين هداهم الله ومن عليهم بالايمان والتقوى. وما كان الله ليضيع ايمانكم به واتباعكم لرسوله، ويبطل صلاتكم الى القبله السابقه. انه سبحانه وتعالى ليرحم الناس رحمه واسعه في عاجلهم واجلهم."},{"id":"151","s":2,"a":144,"at":"قد نرى تقلب وجهك في السماء فلنولينك قبله ترضاها فول وجهك شطر المسجد الحرام وحيث ما كنتم فولوا وجوهكم شطره وان الذين اوتوا الكتاب ليعلمون انه الحق من ربهم وما الله بغافل عما يعملون","dt":"[144] قد نرى تحول وجهك -ايها الرسول- في جهه السماء، مره بعد مره؛ انتظارا لنزول الوحي اليك في شان القبله، فلنصرفنك عن «بيت المقدس» الى قبله تحبها وترضاها، وهي وجهه المسجد الحرام ب«مكه»، فول وجهك اليها. وفي اي مكان كنتم -ايها المسلمون- واردتم الصلاه فتوجهوا نحو المسجد الحرام. وان الذين اعطاهم الله علم الكتاب من اليهود والنصارى ليعلمون ان تحويلك الى الكعبه هو الحق الثابت في كتبهم. وما الله بغافل عما يعمل هؤلاء المعترضون المشككون، وسيجازيهم على ذلك."},{"id":"152","s":2,"a":145,"at":"ولئن اتيت الذين اوتوا الكتاب بكل ايه ما تبعوا قبلتك وما انت بتابع قبلتهم وما بعضهم بتابع قبله بعض ولئن اتبعت اهواءهم من بعد ما جاءك من العلم انك اذا لمن الظالمين","dt":"[145] ولئن جئت -ايها الرسول- الذين اعطوا التوراه والانجيل بكل حجه وبرهان على ان توجهك الى الكعبه في الصلاه هو الحق من عند الله، ما تبعوا قبلتك؛ عنادا واستكبارا، وما انت بتابع قبلتهم مره اخرى، وما بعضهم بتابع قبله بعض. ولئن اتبعت اهواءهم في شان القبله وغيرها بعد ما جاءك من العلم بانك على الحق وهم على الباطل، انك حينئذ لمن الظالمين لانفسهم. وهذا خطاب لجميع الامه، وهو تهديد ووعيد لمن يتبع اهواء المخالفين لشريعه الاسلام."},{"id":"153","s":2,"a":146,"at":"الذين اتيناهم الكتاب يعرفونه كما يعرفون ابناءهم وان فريقا منهم ليكتمون الحق وهم يعلمون","dt":"[146] الذين اعطيناهم التوراه والانجيل من احبار اليهود وعلماء النصارى يعرفون ان محمدا -صلى الله عليه وسلم- رسول الله باوصافه المذكوره في كتبهم، مثل معرفتهم ابناءهم. وان فريقا منهم ليكتمون الحق وهم يعلمون صدقه، وثبوت اوصافه."},{"id":"154","s":2,"a":147,"at":"الحق من ربك فلا تكونن من الممترين","dt":"[147] الذي انزل اليك -ايها النبي- هو الحق من ربك، فلا تكونن من الشاكين فيه. وهذا وان كان خطابا للرسول -صلى الله عليه وسلم-، فهو موجه للامه."},{"id":"155","s":2,"a":148,"at":"ولكل وجهه هو موليها فاستبقوا الخيرات اين ما تكونوا يات بكم الله جميعا ان الله على كل شيء قدير","dt":"[148] ولكل امه من الامم قبله يتوجه اليها كل واحد منها في صلاته، فبادروا -ايها المؤمنون- متسابقين الى فعل الاعمال الصالحه التي شرعها الله لكم في دين الاسلام. وسيجمعكم الله جميعا يوم القيامه من اي موضع كنتم فيه. ان الله على كل شيء قدير."},{"id":"156","s":2,"a":149,"at":"ومن حيث خرجت فول وجهك شطر المسجد الحرام وانه للحق من ربك وما الله بغافل عما تعملون","dt":"[149] ومن اي مكان خرجت -ايها النبي- مسافرا، واردت الصلاه، فوجه وجهك نحو المسجد الحرام. وان توجهك اليه لهو الحق الثابت من ربك. وما الله بغافل عما تعملونه، وسيجازيكم على ذلك."},{"id":"157","s":2,"a":150,"at":"ومن حيث خرجت فول وجهك شطر المسجد الحرام وحيث ما كنتم فولوا وجوهكم شطره لئلا يكون للناس عليكم حجه الا الذين ظلموا منهم فلا تخشوهم واخشوني ولاتم نعمتي عليكم ولعلكم تهتدون","dt":"[150] ومن اي مكان خرجت -ايها النبي- فتوجه الى المسجد الحرام، وحيثما كنتم -ايها المسلمون-، باي قطر من اقطار الارض فولوا وجوهكم نحو المسجد الحرام؛ لكي لا يكون للناس المخالفين لكم احتجاج عليكم بالمخاصمه والمجادله، بعد هذا التوجه اليه، الا اهل الظلم والعناد منهم، فسيظلون على جدالهم، فلا تخافوهم وخافوني بامتثال امري، واجتناب نهيي؛ ولكي اتم نعمتي عليكم باختيار اكمل الشرائع لكم، ولعلكم تهتدون الى الحق والصواب."},{"id":"158","s":2,"a":151,"at":"كما ارسلنا فيكم رسولا منكم يتلو عليكم اياتنا ويزكيكم ويعلمكم الكتاب والحكمه ويعلمكم ما لم تكونوا تعلمون","dt":"[151] كما انعمنا عليكم باستقبال الكعبه ارسلنا فيكم رسولا منكم يتلو عليكم الايات المبينه للحق من الباطل، ويطهركم من دنس الشرك وسوء الاخلاق، ويعلمكم الكتاب والسنه واحكام الشريعه، ويعلمكم من اخبار الانبياء، وقصص الامم السابقه ما كنتم تجهلونه."},{"id":"159","s":2,"a":152,"at":"فاذكروني اذكركم واشكروا لي ولا تكفرون","dt":"[152] امر تعالى المؤمنين بذكره، ووعد عليه افضل الجزاء، وهو الثناء في الملا الاعلى على من ذكره، وخصوني -ايها المؤمنون- بالشكر قولا وعملا، ولا تجحدوا نعمي عليكم."},{"id":"160","s":2,"a":153,"at":"ياايها الذين امنوا استعينوا بالصبر والصلاه ان الله مع الصابرين","dt":"[153] يا ايها المؤمنون اطلبوا العون من الله في كل اموركم: بالصبر على النوائب والمصائب، وبالصبر على ترك المعاصي والذنوب، وبالصبر على الطاعات والقربات، وبالصلاه التي تطمئن بها النفس، وتنهى عن الفحشاء والمنكر. ان الله مع الصابرين بعونه وتوفيقه وتسديده. وفي الايه اثبات معيه الله الخاصه بالمؤمنين، المقتضيه لما سلف ذكره؛ اما المعيه العامه، المقتضيه للعلم والاحاطه فهي لجميع الخلق."},{"id":"161","s":2,"a":154,"at":"ولا تقولوا لمن يقتل في سبيل الله اموات بل احياء ولكن لا تشعرون","dt":"[154] ولا تقولوا -ايها المؤمنون- فيمن يقتلون مجاهدين في سبيل الله: هم اموات؛ بل هم احياء حياه خاصه بهم في قبورهم، لا يعلم كيفيتها الا الله -تعالى-، ولكنكم لا تحسون بها. وفي هذا دليل على نعيم القبر."},{"id":"162","s":2,"a":155,"at":"ولنبلونكم بشيء من الخوف والجوع ونقص من الاموال والانفس والثمرات وبشر الصابرين","dt":"[155] ولنختبرنكم بشيء يسير من الخوف، ومن الجوع، وبنقص من الاموال بتعسر الحصول عليها، او ذهابها، ومن الانفس: بالموت او الشهاده في سبيل الله، وبنقص من ثمرات النخيل والاعناب والحبوب، بقله ناتجها او فسادها. وبشر -ايها النبي- الصابرين على هذا وامثاله بما يفرحهم ويسرهم من حسن العاقبه في الدنيا والاخره."},{"id":"163","s":2,"a":156,"at":"الذين اذا اصابتهم مصيبه قالوا انا لله وانا اليه راجعون","dt":"[156] من صفه هؤلاء الصابرين انهم اذا اصابهم شيء يكرهونه قالوا: انا عبيد مملوكون لله، مدبرون بامره وتصريفه، يفعل بنا ما يشاء، وانا اليه راجعون بالموت، ثم بالبعث للحساب والجزاء."},{"id":"164","s":2,"a":157,"at":"اولئك عليهم صلوات من ربهم ورحمه واولئك هم المهتدون","dt":"[157] اولئك الصابرون لهم ثناء من ربهم ورحمه عظيمه منه سبحانه، واولئك هم المهتدون الى الرشاد."},{"id":"165","s":2,"a":158,"at":"ان الصفا والمروه من شعائر الله فمن حج البيت او اعتمر فلا جناح عليه ان يطوف بهما ومن تطوع خيرا فان الله شاكر عليم","dt":"[158] ان الصفا والمروه -وهما جبلان صغيران قرب الكعبه من جهه الشرق- من معالم دين الله الظاهره التي تعبد الله عباده بالسعي بينهما. فمن قصد الكعبه حاجا او معتمرا، فلا اثم عليه ولا حرج في ان يسعى بينهما، بل يجب عليه ذلك، ومن فعل الطاعات طواعيه من نفسه، مخلصا بها لله تعالى، فان الله تعالى شاكر يثيب على القليل بالكثير، عليم باعمال عباده فلا يضيعها، ولا يبخس احدا مثقال ذره."},{"id":"166","s":2,"a":159,"at":"ان الذين يكتمون ما انزلنا من البينات والهدى من بعد ما بيناه للناس في الكتاب اولئك يلعنهم الله ويلعنهم اللاعنون","dt":"[159] ان الذين يخفون ما انزلنا من الايات الواضحات الداله على نبوه محمد -صلى الله عليه وسلم- وما جاء به، وهم احبار اليهود وعلماء النصارى وغيرهم ممن يكتم ما انزل الله من بعد ما اظهرناه للناس في التوراه والانجيل، اولئك يطردهم الله من رحمته، ويدعو عليهم باللعنه جميع الخليقه."},{"id":"167","s":2,"a":160,"at":"الا الذين تابوا واصلحوا وبينوا فاولئك اتوب عليهم وانا التواب الرحيم","dt":"[160] الا الذين رجعوا مستغفرين الله من خطاياهم، واصلحوا ما افسدوه، وبينوا ما كتموه، فاولئك اقبل توبتهم واجازيهم بالمغفره، وانا التواب على من تاب من عبادي، الرحيم بهم؛ اذ وفقتهم للتوبه وقبلتها منهم."},{"id":"168","s":2,"a":161,"at":"ان الذين كفروا وماتوا وهم كفار اولئك عليهم لعنه الله والملائكه والناس اجمعين","dt":"[161] ان الذين جحدوا الايمان وكتموا الحق، واستمروا على ذلك حتى ماتوا، اولئك عليهم لعنه الله بالطرد من رحمته، وعليهم لعنه الملائكه والناس اجمعين."},{"id":"169","s":2,"a":162,"at":"خالدين فيها لا يخفف عنهم العذاب ولا هم ينظرون","dt":"[162] دائمين في اللعنه والنار، لا يخفف عنهم العذاب، ولا هم يمهلون بمعذره يعتذرون بها."},{"id":"170","s":2,"a":163,"at":"والهكم اله واحد لا اله الا هو الرحمن الرحيم","dt":"[163] والهكم -ايها الناس- اله واحد متفرد في ذاته واسمائه وصفاته وافعاله، وعبوديه خلقه له، لا معبود بحق الا هو، الرحمن المتصف بالرحمه في ذاته وافعاله لجميع الخلق، الرحيم بالمؤمنين."},{"id":"171","s":2,"a":164,"at":"ان في خلق السموات والارض واختلاف الليل والنهار والفلك التي تجري في البحر بما ينفع الناس وما انزل الله من السماء من ماء فاحيا به الارض بعد موتها وبث فيها من كل دابه وتصريف الرياح والسحاب المسخر بين السماء والارض لايات لقوم يعقلون","dt":"[164] ان في خلق السموات بارتفاعها واتساعها، والارض بجبالها وسهولها وبحارها، وفي اختلاف الليل والنهار من الطول والقصر، والظلمه والنور، وتعاقبهما بان يخلف كل منهما الاخر، وفي السفن الجاريه في البحار، التي تحمل ما ينفع الناس، وما انزل الله من السماء من ماء المطر، فاحيا به الارض، فصارت مخضره ذات بهجه بعد ان كانت يابسه لا نبات فيها، وما نشره الله فيها من كل ما دب على وجه الارض، وما انعم به عليكم من تقليب الرياح وتوجيهها، والسحاب المسير بين السماء والارض، ان في كل الدلائل السابقه لايات على وحدانيه الله، وجليل نعمه، لقوم يعقلون مواضع الحجج، ويفهمون ادلته سبحانه على وحدانيته، واستحقاقه وحده للعباده."},{"id":"172","s":2,"a":165,"at":"ومن الناس من يتخذ من دون الله اندادا يحبونهم كحب الله والذين امنوا اشد حبا لله ولو يرى الذين ظلموا اذ يرون العذاب ان القوه لله جميعا وان الله شديد العذاب","dt":"[165] ومع هذه البراهين القاطعه يتخذ فريق من الناس من دون الله اصناما واوثانا واولياء يجعلونهم نظراء لله تعالى، ويعطونهم من المحبه والتعظيم والطاعه، ما لا يليق الا بالله وحده. والمؤمنون اعظم حبا لله من حب هؤلاء الكفار لله ولالهتهم؛ لان المؤمنين اخلصوا المحبه كلها لله، واولئك اشركوا في المحبه. ولو يعلم الذين ظلموا انفسهم بالشرك في الحياه الدنيا، حين يشاهدون عذاب الاخره، ان الله هو المتفرد بالقوه جميعا، وان الله شديد العذاب، لما اتخذوا من دون الله الهه يعبدونهم من دونه، ويتقربون بهم اليه."},{"id":"173","s":2,"a":166,"at":"اذ تبرا الذين اتبعوا من الذين اتبعوا وراوا العذاب وتقطعت بهم الاسباب","dt":"[166] عند معاينتهم عذاب الاخره يتبرا الرؤساء المتبوعون ممن اتبعهم على الشرك، وتنقطع بينهم كل الصلات التي ارتبطوا بها في الدنيا: من القرابه، والاتباع، والدين، وغير ذلك."},{"id":"174","s":2,"a":167,"at":"وقال الذين اتبعوا لو ان لنا كره فنتبرا منهم كما تبرءوا منا كذلك يريهم الله اعمالهم حسرات عليهم وما هم بخارجين من النار","dt":"[167] وقال التابعون: يا ليت لنا عوده الى الدنيا، فنعلن براءتنا من هؤلاء الرؤساء، كما اعلنوا براءتهم منا. وكما اراهم الله شده عذابه يوم القيامه يريهم اعمالهم الباطله ندامات عليهم، وليسوا بخارجين من النار ابدا."},{"id":"175","s":2,"a":168,"at":"ياايها الناس كلوا مما في الارض حلالا طيبا ولا تتبعوا خطوات الشيطان انه لكم عدو مبين","dt":"[168] يا ايها الناس كلوا من رزق الله الذي اباحه لكم في الارض، وهو الطاهر غير النجس، النافع غير الضار، ولا تتبعوا طرق الشيطان في التحليل والتحريم، والبدع والمعاصي. انه عدو لكم ظاهر العداوه."},{"id":"176","s":2,"a":169,"at":"انما يامركم بالسوء والفحشاء وان تقولوا على الله ما لا تعلمون","dt":"[169] انما يامركم الشيطان بكل ذنب قبيح يسوءكم، وبكل معصيه بالغه القبح، وبان تفتروا على الله الكذب من تحريم الحلال وغيره بدون علم."},{"id":"177","s":2,"a":170,"at":"واذا قيل لهم اتبعوا ما انزل الله قالوا بل نتبع ما الفينا عليه اباءنا او لو كان اباؤهم لا يعقلون شيئا ولا يهتدون","dt":"[170] واذا قال المؤمنون ناصحين اهل الضلال: اتبعوا ما انزل الله من القران والهدى، اصروا على تقليد اسلافهم المشركين قائلين: لا نتبع دينكم، بل نتبع ما وجدنا عليه اباءنا. ايتبعون اباءهم ولو كانوا لا يعقلون عن الله شيئا، ولا يدركون رشدا؟"},{"id":"178","s":2,"a":171,"at":"ومثل الذين كفروا كمثل الذي ينعق بما لا يسمع الا دعاء ونداء صم بكم عمي فهم لا يعقلون","dt":"[171] وصفه الذين كفروا وداعيهم الى الهدى والايمان كصفه الراعي الذي يصيح بالبهائم ويزجرها، وهي لا تفهم معاني كلامه، وانما تسمع النداء ودوي الصوت فقط. هؤلاء الكفار صم سدوا اسماعهم عن الحق، بكم اخرسوا السنتهم عن النطق به، عمي لا ترى اعينهم براهينه الباهره، فهم لا يعملون عقولهم فيما ينفعهم."},{"id":"179","s":2,"a":172,"at":"ياايها الذين امنوا كلوا من طيبات ما رزقناكم واشكروا لله ان كنتم اياه تعبدون","dt":"[172] يا ايها المؤمنون كلوا من الاطعمه المستلذه الحلال التي رزقناكم، ولا تكونوا كالكفار الذين يحرمون الطيبات، ويستحلون الخبائث، واشكروا لله نعمه العظيمه عليكم بقلوبكم والسنتكم وجوارحكم، ان كنتم حقا منقادين لامره، سامعين مطيعين له، تعبدونه وحده لا شريك له."},{"id":"180","s":2,"a":173,"at":"انما حرم عليكم الميته والدم ولحم الخنزير وما اهل به لغير الله فمن اضطر غير باغ ولا عاد فلا اثم عليه ان الله غفور رحيم","dt":"[173] انما حرم الله عليكم ما يضركم كالميته التي لم تذبح بطريقه شرعيه، والدم المسفوح، ولحم الخنزير، والذبائح التي ذبحت لغير الله. ومن فضل الله عليكم وتيسيره انه اباح لكم اكل هذه المحرمات عند الضروره. فمن الجاته الضروره الى اكل شيء منها، غير ظالم في اكله فوق حاجته، ولا متجاوز حدود الله فيما ابيح له، فلا ذنب عليه في ذلك. ان الله غفور لعباده، رحيم بهم."},{"id":"181","s":2,"a":174,"at":"ان الذين يكتمون ما انزل الله من الكتاب ويشترون به ثمنا قليلا اولئك ما ياكلون في بطونهم الا النار ولا يكلمهم الله يوم القيامه ولا يزكيهم ولهم عذاب اليم","dt":"[174] ان الذين يخفون ما انزل الله في كتبه من صفه محمد -صلى الله عليه وسلم- وغير ذلك من الحق، ويحرصون على اخذ عوض قليل من عرض الحياه الدنيا مقابل هذا الاخفاء، هؤلاء ما ياكلون في مقابله كتمان الحق الا نار جهنم تتاجج في بطونهم ، ولا يكلمهم الله يوم القيامه لغضبه وسخطه عليهم، ولا يطهرهم من دنس ذنوبهم وكفرهم، ولهم عذاب موجع."},{"id":"182","s":2,"a":175,"at":"اولئك الذين اشتروا الضلاله بالهدى والعذاب بالمغفره فما اصبرهم على النار","dt":"[175] اولئك المتصفون بهذه الصفات استبدلوا الضلاله بالهدى وعذاب الله بمغفرته، فما اشد جراءتهم على النار بعملهم اعمال اهل النار! يعجب الله من اقدامهم على ذلك، فاعجبوا -ايها الناس- من جراءتهم، ومن صبرهم على النار ومكثهم فيها. وهذا على وجه الاستهانه، بهم والاستخفاف بامرهم."},{"id":"183","s":2,"a":176,"at":"ذلك بان الله نزل الكتاب بالحق وان الذين اختلفوا في الكتاب لفي شقاق بعيد","dt":"[176] ذلك العذاب الذي استحقوه بسبب ان الله تعالى نزل كتبه على رسله مشتمله على الحق المبين، فكفروا به. وان الذين اختلفوا في الكتاب فامنوا ببعضه وكفروا ببعضه، لفي منازعه ومفارقه بعيده عن الرشد والصواب."},{"id":"184","s":2,"a":177,"at":"ليس البر ان تولوا وجوهكم قبل المشرق والمغرب ولكن البر من امن بالله واليوم الاخر والملائكه والكتاب والنبيين واتى المال على حبه ذوي القربى واليتامى والمساكين وابن السبيل والسائلين وفي الرقاب واقام الصلاه واتى الزكاه والموفون بعهدهم اذا عاهدوا والصابرين في الباساء والضراء وحين الباس اولئك الذين صدقوا واولئك هم المتقون","dt":"[177] ليس الخير عند الله -تعالى- في التوجه في الصلاه الى جهه المشرق والمغرب ان لم يكن عن امر الله وشرعه، وانما الخير كل الخير هو ايمان من امن بالله وصدق به معبودا وحده لا شريك له، وامن بيوم البعث والجزاء، وبالملائكه جميعا، وبالكتب المنزله كافه، وبجميع النبيين من غير تفريق، واعطى المال تطوعا- مع شده حبه- ذوي القربى، واليتامى المحتاجين الذين مات اباؤهم وهم دون سن البلوغ، والمساكين الذين لا يملكون ما يكفيهم ويسد حاجتهم، والمسافرين المحتاجين الذين بعدوا عن اهلهم ومالهم، والسائلين الذين اضطروا الى السؤال لشده حاجتهم، وانفق في تحرير الرقيق والاسرى، واقام الصلاه، وادى الزكاه المفروضه، والذين يوفون بالعهود، ومن صبر في حال فقره ومرضه، وفي شده القتال. اولئك المتصفون بهذه الصفات هم الذين صدقوا في ايمانهم، واولئك هم الذين اتقوا عقاب الله فتجنبوا معاصيه."},{"id":"185","s":2,"a":178,"at":"ياايها الذين امنوا كتب عليكم القصاص في القتلى الحر بالحر والعبد بالعبد والانثى بالانثى فمن عفي له من اخيه شيء فاتباع بالمعروف واداء اليه باحسان ذلك تخفيف من ربكم ورحمه فمن اعتدى بعد ذلك فله عذاب اليم","dt":"[178] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه فرض الله عليكم ان تقتصوا من القاتل عمدا بقتله، بشرط المساواه والمماثله: يقتل الحر بمثله سواء الرجل بالمراه او المراه بالرجل، والعبد بمثله، والانثى بمثلها. فمن سامحه ولي المقتول بالعفو عن الاقتصاص منه والاكتفاء باخذ الديه -وهي قدر مالي محدد يدفعه الجاني مقابل العفو عنه- فليلتزم الطرفان بحسن الخلق، فيطالب الولي بالديه من غير عنف، ويدفع القاتل اليه حقه باحسان، من غير تاخير ولا نقص. ذلك العفو مع اخذ الديه تخفيف من ربكم ورحمه بكم؛ لما فيه من التسهيل والانتفاع. فمن قتل القاتل بعد العفو عنه واخذ الديه فله عذاب اليم بقتله قصاصا في الدنيا، او بالنار في الاخره."},{"id":"186","s":2,"a":179,"at":"ولكم في القصاص حياه يااولي الالباب لعلكم تتقون","dt":"[179] ولكم في تشريع القصاص وتنفيذه حياه امنه -يا اصحاب العقول السليمه-؛ رجاء تقوى الله وخشيته بطاعته دائما."},{"id":"187","s":2,"a":180,"at":"كتب عليكم اذا حضر احدكم الموت ان ترك خيرا الوصيه للوالدين والاقربين بالمعروف حقا على المتقين","dt":"[180] فرض الله عليكم اذا حضر احدكم علامات الموت ومقدماته -ان ترك مالا- الوصيه بجزء من ماله للوالدين والاقربين مع مراعاه العدل؛ فلا يدع الفقير ويوصي للغني، ولا يتجاوز الثلث، وذلك حق ثابت يعمل به اهل التقوى الذين يخافون الله. وكان هذا قبل نزول ايات المواريث التي حدد الله فيها نصيب كل وارث."},{"id":"188","s":2,"a":181,"at":"فمن بدله بعد ما سمعه فانما اثمه على الذين يبدلونه ان الله سميع عليم","dt":"[181] فمن غير وصيه الميت بعدما سمعها منه قبل موته، فانما الذنب على من غير وبدل. ان الله سميع لوصيتكم واقوالكم، عليم بما تخفيه صدوركم من الميل الى الحق والعدل او الجور والحيف، وسيجازيكم على ذلك."},{"id":"189","s":2,"a":182,"at":"فمن خاف من موص جنفا او اثما فاصلح بينهم فلا اثم عليه ان الله غفور رحيم","dt":"[182] فمن علم من موص ميلا عن الحق في وصيته على سبيل الخطا او العمد، فنصح الموصي وقت الوصيه بما هو الاعدل، فان لم يحصل له ذلك فاصلح بين الاطراف بتغيير الوصيه؛ لتوافق الشريعه، فلا ذنب عليه في هذا الاصلاح. ان الله غفور لعباده، رحيم بهم."},{"id":"190","s":2,"a":183,"at":"ياايها الذين امنوا كتب عليكم الصيام كما كتب على الذين من قبلكم لعلكم تتقون","dt":"[183] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، فرض الله عليكم الصيام كما فرضه على الامم قبلكم؛ لعلكم تتقون ربكم، فتجعلون بينكم وبين المعاصي وقايه بطاعته وعبادته وحده."},{"id":"191","s":2,"a":184,"at":"اياما معدودات فمن كان منكم مريضا او على سفر فعده من ايام اخر وعلى الذين يطيقونه فديه طعام مسكين فمن تطوع خيرا فهو خير له وان تصوموا خير لكم ان كنتم تعلمون","dt":"[184] فرض الله عليكم صيام ايام معلومه العدد وهي ايام شهر رمضان. فمن كان منكم مريضا يشق عليه الصوم، او مسافرا فله ان يفطر، وعليه صيام عدد من ايام اخر بقدر التي افطر فيها. وعلى الذين يتكلفون الصيام ويشق عليهم مشقه غير محتمله كالشيخ الكبير، والمريض الذي لا يرجى شفاؤه، فديه عن كل يوم يفطره، وهي طعام محتاج لا يملك ما يكفيه ويسد حاجته، فمن زاد في قدر الفديه تبرعا منه فهو خير له، وصيامكم خير لكم من اعطاء الفديه، ان كنتم تعلمون الفضل العظيم للصوم عند الله تعالى."},{"id":"192","s":2,"a":185,"at":"شهر رمضان الذي انزل فيه القران هدى للناس وبينات من الهدى والفرقان فمن شهد منكم الشهر فليصمه ومن كان مريضا او على سفر فعده من ايام اخر يريد الله بكم اليسر ولا يريد بكم العسر ولتكملوا العده ولتكبروا الله على ما هداكم ولعلكم تشكرون","dt":"[185] شهر رمضان الذي ابتدا الله فيه انزال القران في ليله القدر؛ هدايه للناس الى الحق، فيه اوضح الدلائل على هدى الله، وعلى الفارق بين الحق والباطل. فمن حضر منكم الشهر وكان صحيحا مقيما فليصم نهاره. ويرخص للمريض والمسافر في الفطر، ثم يقضيان عدد تلك الايام. يريد الله تعالى بكم اليسر والسهوله في شرائعه، ولا يريد بكم العسر والمشقه، ولتكملوا عده الصيام شهرا، ولتختموا الصيام بتكبير الله في عيد الفطر، ولتعظموه على هدايته لكم، ولكي تشكروا له على ما انعم به عليكم من الهدايه والتوفيق والتيسير."},{"id":"193","s":2,"a":186,"at":"واذا سالك عبادي عني فاني قريب اجيب دعوه الداع اذا دعان فليستجيبوا لي وليؤمنوا بي لعلهم يرشدون","dt":"[186] واذا سالك -ايها النبي- عبادي عني فقل لهم: اني قريب منهم، اجيب دعوه الداعي اذا دعاني، فليطيعوني فيما امرتهم به ونهيتهم عنه، وليؤمنوا بي، لعلهم يهتدون الى مصالح دينهم ودنياهم. وفي هذه الايه اخبار منه سبحانه عن قربه من عباده، القرب اللائق بجلاله."},{"id":"194","s":2,"a":187,"at":"احل لكم ليله الصيام الرفث الى نسائكم هن لباس لكم وانتم لباس لهن علم الله انكم كنتم تختانون انفسكم فتاب عليكم وعفا عنكم فالان باشروهن وابتغوا ما كتب الله لكم وكلوا واشربوا حتى يتبين لكم الخيط الابيض من الخيط الاسود من الفجر ثم اتموا الصيام الى الليل ولا تباشروهن وانتم عاكفون في المساجد تلك حدود الله فلا تقربوها كذلك يبين الله اياته للناس لعلهم يتقون","dt":"[187] اباح الله لكم في ليالي شهر رمضان جماع نسائكم، هن ستر وحفظ لكم، وانتم ستر وحفظ لهن. علم الله انكم كنتم تخونون انفسكم؛ بمخالفه ما حرمه الله عليكم من مجامعه النساء بعد العشاء في ليالي الصيام -وكان ذلك في اول الاسلام-، فتاب الله عليكم ووسع لكم في الامر، فالان جامعوهن، واطلبوا ما قدره الله لكم من الاولاد، وكلوا واشربوا حتى يتبين لكم ضياء الصباح من سواد الليل؛ بظهور الفجر الصادق، ثم اتموا الصيام بالامساك عن المفطرات الى دخول الليل بغروب الشمس. ولا تجامعوا نساءكم او تتعاطوا ما يفضي الى جماعهن اذا كنتم معتكفين في المساجد؛ لان هذا يفسد الاعتكاف (وهو الاقامه في المسجد مده معلومه بنيه التقرب الى الله تعالى). تلك الاحكام التي شرعها الله لكم هي حدوده الفاصله بين الحلال والحرام، فلا تقربوها حتى لا تقعوا في الحرام. بمثل هذا البيان الواضح يبين الله اياته واحكامه للناس؛ كي يتقوه ويخشوه."},{"id":"195","s":2,"a":188,"at":"ولا تاكلوا اموالكم بينكم بالباطل وتدلوا بها الى الحكام لتاكلوا فريقا من اموال الناس بالاثم وانتم تعلمون","dt":"[188] ولا ياكل بعضكم مال بعض بسبب باطل كاليمين الكاذبه، والغصب، والسرقه، والرشوه، والربا ونحو ذلك، ولا تلقوا الى الحكام بالحجج الباطله؛ لتاكلوا عن طريق التخاصم اموال طائفه من الناس بالباطل، وانتم تعلمون تحريم ذلك عليكم."},{"id":"196","s":2,"a":189,"at":"يسالونك عن الاهله قل هي مواقيت للناس والحج وليس البر بان تاتوا البيوت من ظهورها ولكن البر من اتقى واتوا البيوت من ابوابها واتقوا الله لعلكم تفلحون","dt":"[189] يسالك اصحابك -ايها النبي-: عن الاهله وتغير احوالها، قل لهم: جعل الله الاهله علامات يعرف بها الناس اوقات عباداتهم المحدده بوقت مثل الصيام والحج، ومعاملاتهم. وليس الخير ما تعودتم عليه في الجاهليه واول الاسلام من دخول البيوت من ظهورها حين تحرمون بالحج او العمره، ظانين ان ذلك قربه الى الله، ولكن الخير هو فعل من اتقى الله واجتنب المعاصي، وادخلوا البيوت من ابوابها عند احرامكم بالحج او العمره، واخشوا الله تعالى في كل اموركم؛ لتفوزوا بكل ما تحبون من خيري الدنيا والاخره."},{"id":"197","s":2,"a":190,"at":"وقاتلوا في سبيل الله الذين يقاتلونكم ولا تعتدوا ان الله لا يحب المعتدين","dt":"[190] وقاتلوا -ايها المؤمنون- لنصره دين الله الذين يقاتلونكم، ولا ترتكبوا المناهي من المثله، والغلول، وقتل من لا يحل قتله من النساء والصبيان والشيوخ، ومن في حكمهم. ان الله لا يحب الذين يجاوزون حدوده، فيستحلون ما حرم الله ورسوله -صلى الله عليه وسلم-."},{"id":"198","s":2,"a":191,"at":"واقتلوهم حيث ثقفتموهم واخرجوهم من حيث اخرجوكم والفتنه اشد من القتل ولا تقاتلوهم عند المسجد الحرام حتى يقاتلوكم فيه فان قاتلوكم فاقتلوهم كذلك جزاء الكافرين","dt":"[191] واقتلوا الذين يقاتلونكم من المشركين حيث وجدتموهم، واخرجوهم من المكان الذي اخرجوكم منه وهو «مكه». والفتنه -وهي الكفر والشرك والصد عن الاسلام- اشد من قتلكم اياهم. ولا تبدؤوهم بالقتال عند المسجد الحرام تعظيما لحرماته حتى يبدؤوكم بالقتال فيه، فان قاتلوكم في المسجد الحرام فاقتلوهم فيه. مثل ذلك الجزاء الرادع يكون جزاء الكافرين."},{"id":"199","s":2,"a":192,"at":"فان انتهوا فان الله غفور رحيم","dt":"[192] فان تركوا ما هم فيه من الكفر وقتالكم عند المسجد الحرام، ودخلوا في الايمان، فان الله غفور لعباده، رحيم بهم."},{"id":"200","s":2,"a":193,"at":"وقاتلوهم حتى لا تكون فتنه ويكون الدين لله فان انتهوا فلا عدوان الا على الظالمين","dt":"[193] واستمروا -ايها المؤمنون- في قتال المشركين المعتدين، حتى لا تكون فتنه للمسلمين عن دينهم ولا شرك بالله، ويبقى الدين لله وحده خالصا لا يعبد معه غيره. فان كفوا عن الكفر والقتال فكفوا عنهم؛ فالعقوبه لا تكون الا على المستمرين على كفرهم وعدوانهم."},{"id":"201","s":2,"a":194,"at":"الشهر الحرام بالشهر الحرام والحرمات قصاص فمن اعتدى عليكم فاعتدوا عليه بمثل ما اعتدى عليكم واتقوا الله واعلموا ان الله مع المتقين","dt":"[194] قتالكم -ايها المؤمنون- للمشركين في الشهر الذي حرم الله القتال فيه هو جزاء لقتالهم لكم في الشهر الحرام. والذي يعتدي على ما حرم الله من المكان والزمان، يعاقب بمثل فعله، ومن جنس عمله. فمن اعتدى عليكم بالقتال او غيره فانزلوا به عقوبه مماثله لجنايته، ولا حرج عليكم في ذلك؛ لانهم هم البادئون بالعدوان، وخافوا الله فلا تتجاوزوا المماثله في العقوبه، واعلموا ان الله مع الذين يتقونه ويطيعونه باداء فرائضه وتجنب محارمه."},{"id":"202","s":2,"a":195,"at":"وانفقوا في سبيل الله ولا تلقوا بايديكم الى التهلكه واحسنوا ان الله يحب المحسنين","dt":"[195] واستمروا -ايها المؤمنون- في انفاق الاموال لنصره دين الله تعالى، والجهاد في سبيله، ولا توقعوا انفسكم في المهالك بترك الجهاد في سبيل الله، وعدم الانفاق فيه، واحسنوا في الانفاق والطاعه، واجعلوا عملكم كله خالصا لوجه الله تعالى. ان الله يحب اهل الاخلاص والاحسان."},{"id":"203","s":2,"a":196,"at":"واتموا الحج والعمره لله فان احصرتم فما استيسر من الهدي ولا تحلقوا رءوسكم حتى يبلغ الهدي محله فمن كان منكم مريضا او به اذى من راسه ففديه من صيام او صدقه او نسك فاذا امنتم فمن تمتع بالعمره الى الحج فما استيسر من الهدي فمن لم يجد فصيام ثلاثه ايام في الحج وسبعه اذا رجعتم تلك عشره كامله ذلك لمن لم يكن اهله حاضري المسجد الحرام واتقوا الله واعلموا ان الله شديد العقاب","dt":"[196] وادوا الحج والعمره تامين، خالصين لوجه الله تعالى. فان منعكم عن الذهاب لاتمامهما بعد الاحرام بهما مانع كالعدو والمرض، فالواجب عليكم ذبح ما تيسر لكم من الابل او البقر او الغنم تقربا الى الله تعالى؛ لكي تخرجوا من احرامكم بحلق شعر الراس او تقصيره، ولا تحلقوا رؤوسكم اذا كنتم محصرين حتى ينحر المحصر هديه في الموضع الذي حصر فيه ثم يحل من احرامه، كما نحر النبي -صلى الله عليه وسلم- في «الحديبيه» ثم حلق راسه، وغير المحصر لا ينحر الهدي الا في الحرم، الذي هو محله في يوم العيد، اليوم العاشر وما بعده من ايام التشريق. فمن كان منكم مريضا، او به اذى من راسه يحتاج معه الى الحلق -وهو محرم- حلق، وعليه فديه: بان يصوم ثلاثه ايام، او يتصدق على سته مساكين لكل مسكين نصف صاع من طعام، او يذبح شاه لفقراء الحرم. فاذا كنتم في امن وصحه: فمن استمتع بالعمره الى الحج وذلك باستباحه ما حرم عليه بسبب الاحرام بعد انتهاء عمرته، فعليه ذبح ما تيسر من الهدي، فمن لم يجد هديا يذبحه فعليه صيام ثلاثه ايام في اشهر الحج، وسبعه اذا فرغتم من اعمال الحج ورجعتم الى اهليكم، تلك عشره كامله لا بد من صيامها. ذلك الهدي وما ترتب عليه من الصيام لمن لم يكن اهله من ساكني ارض الحرم، وخافوا الله تعالى وحافظوا على امتثال اوامره واجتناب نواهيه، واعلموا ان الله شديد العقاب لمن خالف امره، وارتكب ما عنه زجر."},{"id":"204","s":2,"a":197,"at":"الحج اشهر معلومات فمن فرض فيهن الحج فلا رفث ولا فسوق ولا جدال في الحج وما تفعلوا من خير يعلمه الله وتزودوا فان خير الزاد التقوى واتقون يااولي الالباب","dt":"[197] وقت الحج اشهر معلومات، وهي: شوال، وذو القعده، وعشر من ذي الحجه. فمن اوجب الحج على نفسه فيهن بالاحرام، فيحرم عليه الجماع ومقدماته القوليه والفعليه، ويحرم عليه الخروج عن طاعه الله تعالى بفعل المعاصي، والجدال في الحج الذي يؤدي الى الغضب والكراهيه. وما تفعلوا من خير يعلمه الله، فيجازي كلا على عمله. وخذوا لانفسكم زادا من الطعام والشراب لسفر الحج، وزادا من صالح الاعمال للدار الاخره، فان خير الزاد تقوى الله، وخافوني يا اصحاب العقول السليمه."},{"id":"205","s":2,"a":198,"at":"ليس عليكم جناح ان تبتغوا فضلا من ربكم فاذا افضتم من عرفات فاذكروا الله عند المشعر الحرام واذكروه كما هداكم وان كنتم من قبله لمن الضالين","dt":"[198] ليس عليكم حرج في ان تطلبوا رزقا من ربكم بالربح من التجاره في ايام الحج. فاذا دفعتم بعد غروب الشمس راجعين من «عرفات» -وهي المكان الذي يقف فيه الحجاج يوم التاسع من ذي الحجه- فاذكروا الله بالتسبيح والتلبيه والدعاء عند المشعر الحرام -«المزدلفه»-، واذكروا الله على الوجه الصحيح الذي هداكم اليه، ولقد كنتم من قبل هذا الهدى في ضلال لا تعرفون معه الحق."},{"id":"206","s":2,"a":199,"at":"ثم افيضوا من حيث افاض الناس واستغفروا الله ان الله غفور رحيم","dt":"[199] وليكن اندفاعكم من «عرفات» التي افاض منها ابراهيم عليه السلام، مخالفين بذلك من لا يقف بها من اهل الجاهليه، واسالوا الله ان يغفر لكم ذنوبكم. ان الله غفور لعباده المستغفرين التائبين، رحيم بهم."},{"id":"207","s":2,"a":200,"at":"فاذا قضيتم مناسككم فاذكروا الله كذكركم اباءكم او اشد ذكرا فمن الناس من يقول ربنا اتنا في الدنيا وما له في الاخره من خلاق","dt":"[200] فاذا اتممتم عبادتكم، وفرغتم من اعمال الحج، فاكثروا من ذكر الله والثناء عليه، مثل ذكركم مفاخر ابائكم واعظم من ذلك. فمن الناس فريق يجعل همه الدنيا فقط، فيدعو قائلا: ربنا اتنا في الدنيا صحه، ومالا، واولادا، وهؤلاء ليس لهم في الاخره حظ ولا نصيب؛ لرغبتهم عنها وقصر همهم على الدنيا."},{"id":"208","s":2,"a":201,"at":"ومنهم من يقول ربنا اتنا في الدنيا حسنه وفي الاخره حسنه وقنا عذاب النار","dt":"[201] ومن الناس فريق مؤمن يقول في دعائه: ربنا اتنا في الدنيا عافيه ورزقا وعلما نافعا، وعملا صالحا، وغير ذلك من امور الدين والدنيا ، وفي الاخره الجنه، واصرف عنا عذاب النار. وهذا الدعاء من اجمع الادعيه، ولهذا كان اكثر دعاء النبي -صلى الله عليه وسلم-، كما ثبت في الصحيحين."},{"id":"209","s":2,"a":202,"at":"اولئك لهم نصيب مما كسبوا والله سريع الحساب","dt":"[202] اولئك الداعون بهذا الدعاء لهم ثواب عظيم؛ بسبب ما كسبوه من الاعمال الصالحه. والله سريع الحساب، محص اعمال عباده، ومجازيهم بها."},{"id":"210","s":2,"a":203,"at":"واذكروا الله في ايام معدودات فمن تعجل في يومين فلا اثم عليه ومن تاخر فلا اثم عليه لمن اتقى واتقوا الله واعلموا انكم اليه تحشرون","dt":"[203] واذكروا الله تسبيحا وتكبيرا في ايام قلائل، وهي ايام التشريق: الحادي عشر والثاني عشر والثالث عشر من شهر ذي الحجه. فمن اراد التعجل وخرج من «منى» قبل غروب شمس اليوم الثاني عشر بعد رمي الجمار فلا ذنب عليه، ومن تاخر بان بات ب«منى» حتى يرمي الجمار في اليوم الثالث عشر فلا ذنب عليه، لمن اتقى الله في حجه. والتاخر افضل؛ لانه تزود في العباده واقتداء بفعل النبي -صلى الله عليه وسلم-.وخافوا الله -ايها المسلمون- وراقبوه في كل اعمالكم، واعلموا انكم اليه وحده تحشرون بعد موتكم للحساب والجزاء."},{"id":"211","s":2,"a":204,"at":"ومن الناس من يعجبك قوله في الحياه الدنيا ويشهد الله على ما في قلبه وهو الد الخصام","dt":"[204] وبعض الناس من المنافقين يعجبك -ايها الرسول- كلامه الفصيح الذي يريد به حظا من حظوظ الدنيا لا الاخره، ويحلف مستشهدا بالله على ما في قلبه من محبه الاسلام، وفي هذا غايه الجراه على الله، وهو شديد العداوه والخصومه للاسلام والمسلمين."},{"id":"212","s":2,"a":205,"at":"واذا تولى سعى في الارض ليفسد فيها ويهلك الحرث والنسل والله لا يحب الفساد","dt":"[205] واذا خرج من عندك ايها الرسول، جد ونشط في الارض ليفسد فيها، ويتلف زروع الناس، ويقتل ماشيتهم. والله لا يحب الفساد."},{"id":"213","s":2,"a":206,"at":"واذا قيل له اتق الله اخذته العزه بالاثم فحسبه جهنم ولبئس المهاد","dt":"[206] واذا نصح ذلك المنافق المفسد، وقيل له: اتق الله واحذر عقابه، وكف عن الفساد في الارض، لم يقبل النصيحه، بل يحمله الكبر وحميه الجاهليه على مزيد من الاثام، فحسبه جهنم وكافيته عذابا، ولبئس الفراش هي."},{"id":"214","s":2,"a":207,"at":"ومن الناس من يشري نفسه ابتغاء مرضات الله والله رءوف بالعباد","dt":"[207] وبعض الناس يبيع نفسه طلبا لرضا الله عنه، بالجهاد في سبيله، والتزام طاعته. والله رؤوف بالعباد، يرحم عباده المؤمنين رحمه واسعه في عاجلهم واجلهم، فيجازيهم احسن الجزاء."},{"id":"215","s":2,"a":208,"at":"ياايها الذين امنوا ادخلوا في السلم كافه ولا تتبعوا خطوات الشيطان انه لكم عدو مبين","dt":"[208] يا ايها الذين امنوا بالله ربا وبمحمد نبيا ورسولا وبالاسلام دينا، ادخلوا في جميع شرائع الاسلام، عاملين بجميع احكامه، ولا تتركوا منها شيئا، ولا تتبعوا طرق الشيطان فيما يدعوكم اليه من المعاصي. انه لكم عدو ظاهر العداوه فاحذروه."},{"id":"216","s":2,"a":209,"at":"فان زللتم من بعد ما جاءتكم البينات فاعلموا ان الله عزيز حكيم","dt":"[209] فان انحرفتم عن طريق الحق، من بعد ما جاءتكم الحجج الواضحه من القران والسنه، فاعلموا ان الله عزيز في ملكه لا يفوته شيء، حكيم في امره ونهيه، يضع كل شيء في موضعه المناسب له."},{"id":"217","s":2,"a":210,"at":"هل ينظرون الا ان ياتيهم الله في ظلل من الغمام والملائكه وقضي الامر والى الله ترجع الامور","dt":"[210] ما ينتظر هؤلاء المعاندون الكافرون بعد قيام الادله البينه الا ان ياتيهم الله عز وجل، على الوجه اللائق به سبحانه في ظلل من السحاب يوم القيامه؛ ليفصل بينهم بالقضاء العادل، وان تاتي الملائكه، وحينئذ يقضي الله تعالى فيهم قضاءه. واليه وحده ترجع امور الخلائق جميعها."},{"id":"218","s":2,"a":211,"at":"سل بني اسرائيل كم اتيناهم من ايه بينه ومن يبدل نعمه الله من بعد ما جاءته فان الله شديد العقاب","dt":"[211] سل -ايها الرسول- بني اسرائيل المعاندين لك: كم اعطيناهم من ايات واضحات في كتبهم تهديهم الى الحق، فكفروا بها كلها، واعرضوا عنها، وحرفوها عن مواضعها. ومن يبدل نعمه الله -وهي دينه- ويكفر بها من بعد معرفتها، وقيام الحجه عليه بها، فان الله تعالى شديد العقاب له."},{"id":"219","s":2,"a":212,"at":"زين للذين كفروا الحياه الدنيا ويسخرون من الذين امنوا والذين اتقوا فوقهم يوم القيامه والله يرزق من يشاء بغير حساب","dt":"[212] حسن للذين جحدوا وحدانيه الله الحياه الدنيا وما فيها من الشهوات والملذات، وهم يستهزئون بالمؤمنين. وهؤلاء الذين يخشون ربهم فوق جميع الكفار يوم القيامه؛ حيث يدخلهم الله اعلى درجات الجنه، وينزل الكافرين اسفل دركات النار. والله يرزق من يشاء من خلقه بغير حساب."},{"id":"220","s":2,"a":213,"at":"كان الناس امه واحده فبعث الله النبيين مبشرين ومنذرين وانزل معهم الكتاب بالحق ليحكم بين الناس فيما اختلفوا فيه وما اختلف فيه الا الذين اوتوه من بعد ما جاءتهم البينات بغيا بينهم فهدى الله الذين امنوا لما اختلفوا فيه من الحق باذنه والله يهدي من يشاء الى صراط مستقيم","dt":"[213] كان الناس جماعه واحده، متفقين على الايمان بالله ثم اختلفوا في دينهم، فبعث الله النبيين دعاه لدين الله، مبشرين من اطاع الله بالجنه، ومحذرين من كفر به وعصاه النار، وانزل معهم الكتب السماويه بالحق الذي اشتملت عليه؛ ليحكموا بما فيها بين الناس فيما اختلفوا فيه، وما اختلف في امر محمد -صلى الله عليه وسلم- وكتابه ظلما وحسدا الا الذين اعطاهم الله التوراه، وعرفوا ما فيها من الحجج والاحكام، فوفق الله المؤمنين بفضله الى تمييز الحق من الباطل، ومعرفه ما اختلفوا فيه. والله يوفق من يشاء من عباده الى طريق مستقيم."},{"id":"221","s":2,"a":214,"at":"ام حسبتم ان تدخلوا الجنه ولما ياتكم مثل الذين خلوا من قبلكم مستهم الباساء والضراء وزلزلوا حتى يقول الرسول والذين امنوا معه متى نصر الله الا ان نصر الله قريب","dt":"[214] بل اظننتم -ايها المؤمنون- ان تدخلوا الجنه، ولما يصبكم من الابتلاء مثل ما اصاب المؤمنين الذين مضوا من قبلكم: من الفقر والامراض والخوف والرعب، وزلزلوا بانواع المخاوف، حتى قال رسولهم والمؤمنون معه -على سبيل الاستعجال للنصر من الله تعالى-: متى نصر الله؟ الا ان نصر الله قريب من المؤمنين."},{"id":"222","s":2,"a":215,"at":"يسالونك ماذا ينفقون قل ما انفقتم من خير فللوالدين والاقربين واليتامى والمساكين وابن السبيل وما تفعلوا من خير فان الله به عليم","dt":"[215] يسالك اصحابك -ايها النبي- اي شيء ينفقون من اصناف اموالهم تقربا الى الله تعالى، وعلى من ينفقون؟ قل لهم: انفقوا اي خير يتيسر لكم من اصناف المال الحلال الطيب، واجعلوا نفقتكم للوالدين، والاقربين من اهلكم وذوي ارحامكم، واليتامى الذين مات اباؤهم وهم دون سن البلوغ، والمحتاجين الذين لا يملكون ما يكفيهم ويسد حاجتهم، والمسافر المحتاج الذي بعد عن اهله وماله. وما تفعلوا من خير فان الله تعالى به عليم."},{"id":"223","s":2,"a":216,"at":"كتب عليكم القتال وهو كره لكم وعسى ان تكرهوا شيئا وهو خير لكم وعسى ان تحبوا شيئا وهو شر لكم والله يعلم وانتم لا تعلمون","dt":"[216] فرض الله عليكم -ايها المؤمنون- قتال الكفار، والقتال مكروه لكم من جهه الطبع؛ لمشقته وكثره مخاطره، وقد تكرهون شيئا وهو في حقيقته خير لكم، وقد تحبون شيئا لما فيه من الراحه او اللذه العاجله، وهو شر لكم. والله تعالى يعلم ما هو خير لكم، وانتم لا تعلمون ذلك. فبادروا الى الجهاد في سبيله."},{"id":"224","s":2,"a":217,"at":"يسالونك عن الشهر الحرام قتال فيه قل قتال فيه كبير وصد عن سبيل الله وكفر به والمسجد الحرام واخراج اهله منه اكبر عند الله والفتنه اكبر من القتل ولا يزالون يقاتلونكم حتى يردوكم عن دينكم ان استطاعوا ومن يرتدد منكم عن دينه فيمت وهو كافر فاولئك حبطت اعمالهم في الدنيا والاخره واولئك اصحاب النار هم فيها خالدون","dt":"[217] يسالك المشركون -ايها الرسول- عن الشهر الحرام: هل يحل فيه القتال؟ قل لهم: القتال في الشهر الحرام عظيم عند الله استحلاله وسفك الدماء فيه، ومنعكم الناس من دخول الاسلام بالتعذيب والتخويف، وجحودكم بالله وبرسوله وبدينه، ومنع المسلمين من دخول المسجد الحرام، واخراج النبي والمهاجرين منه وهم اهله واولياؤه، ذلك اكبر ذنبا، واعظم جرما عند الله من القتال في الشهر الحرام. والشرك الذي انتم فيه اكبر واشد من القتل في الشهر الحرام. وهؤلاء الكفار لم يرتدعوا عن جرائمهم، بل هم مستمرون عليها، ولا يزالون يقاتلونكم حتى يردوكم عن الاسلام الى الكفر ان استطاعوا تحقيق ذلك. ومن يطعهم منكم -ايها المسلمون- ويرتدد عن دينه فيمت على الكفر، فقد ذهب عمله في الدنيا والاخره، وصار من الملازمين لنار جهنم لا يخرج منها ابدا."},{"id":"225","s":2,"a":218,"at":"ان الذين امنوا والذين هاجروا وجاهدوا في سبيل الله اولئك يرجون رحمه الله والله غفور رحيم","dt":"[218] ان الذين صدقوا بالله ورسوله وعملوا بشرعه والذين تركوا ديارهم، وجاهدوا في سبيل الله، اولئك يطمعون في فضل الله وثوابه. والله غفور لذنوب عباده المؤمنين، رحيم بهم رحمه واسعه."},{"id":"226","s":2,"a":219,"at":"يسالونك عن الخمر والميسر قل فيهما اثم كبير ومنافع للناس واثمهما اكبر من نفعهما ويسالونك ماذا ينفقون قل العفو كذلك يبين الله لكم الايات لعلكم تتفكرون","dt":"[219] يسالك المسلمون -ايها النبي- عن حكم تعاطي الخمر شربا وبيعا وشراء، والخمر كل مسكر خامر العقل وغطاه مشروبا كان او ماكولا، ويسالونك عن حكم القمار -وهو اخذ المال او اعطاؤه بالمقامره وهي المغالبات التي فيها عوض من الطرفين-، قل لهم: في ذلك اضرار ومفاسد كثيره في الدين والدنيا، والعقول والاموال، وفيهما منافع للناس من جهه كسب الاموال وغيرها، واثمهما اكبر من نفعهما؛ اذ يصدان عن ذكر الله وعن الصلاه، ويوقعان العداوه والبغضاء بين الناس، ويتلفان المال. وكان هذا تمهيدا لتحريمهما. ويسالونك عن القدر الذي ينفقونه من اموالهم تبرعا وصدقه، قل لهم: انفقوا القدر الذي يزيد على حاجتكم. مثل ذلك البيان الواضح يبين الله لكم الايات واحكام الشريعه؛ لكي تتفكروا فيما ينفعكم في الدنيا والاخره."},{"id":"227","s":2,"a":220,"at":"في الدنيا والاخره ويسالونك عن اليتامى قل اصلاح لهم خير وان تخالطوهم فاخوانكم والله يعلم المفسد من المصلح ولو شاء الله لاعنتكم ان الله عزيز حكيم","dt":"[220] ويسالونك -ايها النبي- عن اليتامى الذين مات اباؤهم وهم دون سن البلوغ كيف يتصرفون معهم في معاشهم واموالهم؟ قل لهم: اصلاحكم لهم خير، فافعلوا الانفع لهم دائما، وان تخالطوهم في سائر شؤون المعاش فهم اخوانكم في الدين. وعلى الاخ ان يرعى مصلحه اخيه. والله يعلم المضيع لاموال اليتامى من الحريص على اصلاحها. ولو شاء الله لضيق وشق عليكم بتحريم المخالطه. ان الله عزيز في ملكه، حكيم في خلقه وتدبيره وتشريعه."},{"id":"228","s":2,"a":221,"at":"ولا تنكحوا المشركات حتى يؤمن ولامه مؤمنه خير من مشركه ولو اعجبتكم ولا تنكحوا المشركين حتى يؤمنوا ولعبد مؤمن خير من مشرك ولو اعجبكم اولئك يدعون الى النار والله يدعو الى الجنه والمغفره باذنه ويبين اياته للناس لعلهم يتذكرون","dt":"[221] ولا تتزوجوا -ايها المسلمون- المشركات العابدات الاوثان، حتى يدخلن في الاسلام. واعلموا ان امراه مملوكه لا مال لها ولا حسب، مؤمنه بالله، خير من امراه مشركه، وان اعجبتكم المشركه الحره. ولا تزوجوا نساءكم المؤمنات -اماء او حرائر- للمشركين حتى يؤمنوا بالله ورسوله. واعلموا ان عبدا مؤمنا مع فقره، خير من مشرك، وان اعجبكم المشرك. اولئك المتصفون بالشرك رجالا ونساء يدعون كل من يعاشرهم الى ما يؤدي به الى النار، والله سبحانه يدعو عباده الى دينه الحق المؤدي بهم الى الجنه ومغفره ذنوبهم باذنه، ويبين اياته واحكامه للناس؛ لكي يتذكروا، فيعتبروا."},{"id":"229","s":2,"a":222,"at":"ويسالونك عن المحيض قل هو اذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن فاذا تطهرن فاتوهن من حيث امركم الله ان الله يحب التوابين ويحب المتطهرين","dt":"[222] ويسالونك عن الحيض -وهو الدم الذي يسيل من ارحام النساء جبله في اوقات مخصوصه-، قل لهم -ايها النبي-: هو اذى مستقذر يضر من يقربه، فاجتنبوا جماع النساء مده الحيض حتى ينقطع الدم، فاذا انقطع الدم، واغتسلن، فجامعوهن في الموضع الذي احله الله لكم، وهو القبل لا الدبر. ان الله يحب عباده المكثرين من الاستغفار والتوبه، ويحب عباده المتطهرين الذين يبتعدون عن الفواحش والاقذار."},{"id":"230","s":2,"a":223,"at":"نساؤكم حرث لكم فاتوا حرثكم انى شئتم وقدموا لانفسكم واتقوا الله واعلموا انكم ملاقوه وبشر المؤمنين","dt":"[223] نساؤكم موضع زرع لكم، تضعون النطفه في ارحامهن، فيخرج منها الاولاد بمشيئه الله، فجامعوهن في محل الجماع فقط، وهو القبل باي كيفيه شئتم، وقدموا لانفسكم اعمالا صالحه بمراعاه اوامر الله، وخافوا الله، واعلموا انكم ملاقوه للحساب يوم القيامه. وبشر المؤمنين -ايها النبي- بما يفرحهم ويسرهم من حسن الجزاء في الاخره."},{"id":"231","s":2,"a":224,"at":"ولا تجعلوا الله عرضه لايمانكم ان تبروا وتتقوا وتصلحوا بين الناس والله سميع عليم","dt":"[224] ولا تجعلوا -ايها المسلمون- حلفكم بالله مانعا لكم من البر وصله الرحم والتقوى والاصلاح بين الناس: بان تدعوا الى فعل شيء منها، فتحتجوا بانكم اقسمتم بالله الا تفعلوه، بل على الحالف ان يعدل عن حلفه، ويفعل اعمال البر، ويكفر عن يمينه، ولا يعتاد ذلك. والله سميع لاقوالكم، عليم بجميع احوالكم."},{"id":"232","s":2,"a":225,"at":"لا يؤاخذكم الله باللغو في ايمانكم ولكن يؤاخذكم بما كسبت قلوبكم والله غفور حليم","dt":"[225] لا يعاقبكم الله بسبب ايمانكم التي تحلفونها بغير قصد، ولكن يعاقبكم بما قصدته قلوبكم. والله غفور لمن تاب اليه، حليم بمن عصاه حيث لم يعاجله بالعقوبه."},{"id":"233","s":2,"a":226,"at":"للذين يؤلون من نسائهم تربص اربعه اشهر فان فاءوا فان الله غفور رحيم","dt":"[226] للذين يحلفون بالله ان لا يجامعوا نساءهم ابدا، او اكثر من اربعه اشهر، انتظار اربعه اشهر، فان رجعوا قبل فوات الاشهر الاربعه، فان الله غفور لما وقع منهم من الحلف بسبب رجوعهم، رحيم بهم."},{"id":"234","s":2,"a":227,"at":"وان عزموا الطلاق فان الله سميع عليم","dt":"[227] وان عقدوا عزمهم على الطلاق، باستمرارهم في اليمين، وترك الجماع، فان الله سميع لاقوالهم، عليم بمقاصدهم، وسيجازيهم على ذلك."},{"id":"235","s":2,"a":228,"at":"والمطلقات يتربصن بانفسهن ثلاثه قروء ولا يحل لهن ان يكتمن ما خلق الله في ارحامهن ان كن يؤمن بالله واليوم الاخر وبعولتهن احق بردهن في ذلك ان ارادوا اصلاحا ولهن مثل الذي عليهن بالمعروف وللرجال عليهن درجه والله عزيز حكيم","dt":"[228] والمطلقات ذوات الحيض، يجب ان ينتظرن دون نكاح بعد الطلاق مده ثلاثه اطهار او ثلاث حيضات على سبيل العده؛ ليتاكدن من فراغ الرحم من الحمل. ولا يجوز لهن تزوج رجل اخر في اثناء هذه العده حتى تنتهي. ولا يحل لهن ان يخفين ما خلق الله في ارحامهن من الحمل او الحيض، ان كانت المطلقات مؤمنات حقا بالله واليوم الاخر. وازواج المطلقات احق بمراجعتهن في العده. وينبغي ان يكون ذلك بقصد الاصلاح والخير، وليس بقصد الاضرار؛ تعذيبا لهن بتطويل العده. وللنساء حقوق على الازواج، مثل التي عليهن على الوجه المعروف، وللرجال على النساء منزله زائده من حسن الصحبه، والعشره بالمعروف، والقوامه على البيت، وملك الطلاق. والله عزيز له العزه القاهره، حكيم يضع كل شيء في موضعه المناسب."},{"id":"236","s":2,"a":229,"at":"الطلاق مرتان فامساك بمعروف او تسريح باحسان ولا يحل لكم ان تاخذوا مما اتيتموهن شيئا الا ان يخافا الا يقيما حدود الله فان خفتم الا يقيما حدود الله فلا جناح عليهما فيما افتدت به تلك حدود الله فلا تعتدوها ومن يتعد حدود الله فاولئك هم الظالمون","dt":"[229] الطلاق الذي تحصل به الرجعه مرتان، واحده بعد الاخرى، فحكم الله بعد كل طلقه هو امساك المراه بالمعروف، وحسن العشره بعد مراجعتها، او تخليه سبيلها مع حسن معاملتها باداء حقوقها، والا يذكرها مطلقها بسوء. ولا يحل لكم -ايها الازواج- ان تاخذوا شيئا مما اعطيتموهن من المهر ونحوه، الا ان يخاف الزوجان الا يقوما بالحقوق الزوجيه، فحينئذ يعرضان امرهما على الاولياء، فان خاف الاولياء عدم اقامه الزوجين حدود الله، فلا حرج على الزوجين فيما تدفعه المراه للزوج مقابل طلاقها. تلك الاحكام هي حدود الله الفاصله بين الحلال والحرام، فلا تتجاوزوها، ومن يتجاوز حدود الله تعالى فاولئك هم الظالمون انفسهم بتعريضها لعذاب الله."},{"id":"237","s":2,"a":230,"at":"فان طلقها فلا تحل له من بعد حتى تنكح زوجا غيره فان طلقها فلا جناح عليهما ان يتراجعا ان ظنا ان يقيما حدود الله وتلك حدود الله يبينها لقوم يعلمون","dt":"[230] فان طلق الرجل زوجته الطلقه الثالثه، فلا تحل له الا اذا تزوجت رجلا غيره زواجا صحيحا وجامعها فيه، ويكون الزواج عن رغبه، لا بنيه تحليل المراه لزوجها الاول، فان طلقها الزوج الاخر او مات عنها وانقضت عدتها، فلا اثم على المراه وزوجها الاول ان يتزوجا بعقد جديد، ومهر جديد، ان غلب على ظنهما ان يقيما احكام الله التي شرعها للزوجين. وتلك احكام الله المحدده يبينها لقوم يعلمون احكامه وحدوده؛ لانهم المنتفعون بها."},{"id":"238","s":2,"a":231,"at":"واذا طلقتم النساء فبلغن اجلهن فامسكوهن بمعروف او سرحوهن بمعروف ولا تمسكوهن ضرارا لتعتدوا ومن يفعل ذلك فقد ظلم نفسه ولا تتخذوا ايات الله هزوا واذكروا نعمه الله عليكم وما انزل عليكم من الكتاب والحكمه يعظكم به واتقوا الله واعلموا ان الله بكل شيء عليم","dt":"[231] واذا طلقتم النساء فقاربن انتهاء عدتهن، فراجعوهن، ونيتكم القيام بحقوقهن على الوجه المستحسن شرعا وعرفا، او اتركوهن حتى تنقضي عدتهن. واحذروا ان تكون مراجعتهن بقصد الاضرار بهن لاجل الاعتداء على حقوقهن. ومن يفعل ذلك فقد ظلم نفسه باستحقاقه العقوبه، ولا تتخذوا ايات الله واحكامه لعبا ولهوا. واذكروا نعمه الله عليكم بالاسلام وتفصيل الاحكام. واذكروا ما انزل الله عليكم من القران والسنه، واشكروا له سبحانه على هذه النعم الجليله، يذكركم الله بهذا، ويخوفكم من المخالفه، فخافوا الله وراقبوه، واعلموا ان الله عليم بكل شيء، لا يخفى عليه شيء، وسيجازي كلا بما يستحق."},{"id":"239","s":2,"a":232,"at":"واذا طلقتم النساء فبلغن اجلهن فلا تعضلوهن ان ينكحن ازواجهن اذا تراضوا بينهم بالمعروف ذلك يوعظ به من كان منكم يؤمن بالله واليوم الاخر ذلكم ازكى لكم واطهر والله يعلم وانتم لا تعلمون","dt":"[232] واذا طلقتم نساءكم دون الثلاث وانتهت عدتهن من غير مراجعه لهن، فلا تضيقوا -ايها الاولياء- على المطلقات بمنعهن من العوده الى ازواجهن بعقد جديد اذا اردن ذلك، وحدث التراضي شرعا وعرفا. ذلك يوعظ به من كان منكم صادق الايمان بالله واليوم الاخر. ان ترك العضل وتمكين الازواج من نكاح زوجاتهم اكثر نماء وطهاره لاعراضكم، واعظم منفعه وثوابا لكم. والله يعلم ما فيه صلاحكم وانتم لا تعلمون ذلك."},{"id":"240","s":2,"a":233,"at":"والوالدات يرضعن اولادهن حولين كاملين لمن اراد ان يتم الرضاعه وعلى المولود له رزقهن وكسوتهن بالمعروف لا تكلف نفس الا وسعها لا تضار والده بولدها ولا مولود له بولده وعلى الوارث مثل ذلك فان ارادا فصالا عن تراض منهما وتشاور فلا جناح عليهما وان اردتم ان تسترضعوا اولادكم فلا جناح عليكم اذا سلمتم ما اتيتم بالمعروف واتقوا الله واعلموا ان الله بما تعملون بصير","dt":"[233] وعلى الوالدات ارضاع اولادهن مده سنتين كاملتين لمن اراد اتمام الرضاعه، ويجب على الاباء ان يكفلوا للمرضعات المطلقات طعامهن وكسوتهن، على الوجه المستحسن شرعا وعرفا؛ لان الله لا يكلف نفسا الا قدر طاقتها، ولا يحل للوالدين ان يجعلوا المولود وسيله للمضاره بينهما، ويجب على الوارث عند موت الوالد مثل ما يجب على الوالد قبل موته من النفقه والكسوه. فان اراد الوالدان فطام المولود قبل انتهاء السنتين فلا حرج عليهما اذا تراضيا وتشاورا في ذلك؛ ليصلا الى ما فيه مصلحه المولود. وان اتفق الوالدان على ارضاع المولود من مرضعه اخرى غير والدته فلا حرج عليهما، اذا سلم الوالد للام حقها، وسلم للمرضعه اجرها بما يتعارفه الناس. وخافوا الله في جميع احوالكم، واعلموا ان الله بما تعملون بصير، وسيجازيكم على ذلك."},{"id":"241","s":2,"a":234,"at":"والذين يتوفون منكم ويذرون ازواجا يتربصن بانفسهن اربعه اشهر وعشرا فاذا بلغن اجلهن فلا جناح عليكم فيما فعلن في انفسهن بالمعروف والله بما تعملون خبير","dt":"[234] والذين يموتون منكم، ويتركون زوجات بعدهم، يجب عليهن الانتظار بانفسهن مده اربعه اشهر وعشره ايام، لا يخرجن من منزل الزوجيه، ولا يتزين، ولا يتزوجن، فاذا انتهت المده المذكوره فلا اثم عليكم يا اولياء النساء فيما يفعلن في انفسهن من الخروج، والتزين، والزواج على الوجه المقرر شرعا. والله سبحانه وتعالى خبير باعمالكم ظاهرها وباطنها، وسيجازيكم عليها."},{"id":"242","s":2,"a":235,"at":"ولا جناح عليكم فيما عرضتم به من خطبه النساء او اكننتم في انفسكم علم الله انكم ستذكرونهن ولكن لا تواعدوهن سرا الا ان تقولوا قولا معروفا ولا تعزموا عقده النكاح حتى يبلغ الكتاب اجله واعلموا ان الله يعلم ما في انفسكم فاحذروه واعلموا ان الله غفور حليم","dt":"[235] ولا اثم عليكم -ايها الرجال- فيما تلمحون به من طلب الزواج بالنساء المتوفى عنهن ازواجهن، او المطلقات طلاقا بائنا في اثناء عدتهن، ولا ذنب عليكم ايضا فيما اضمرتموه في انفسكم من نيه الزواج بهن بعد انتهاء عدتهن. علم الله انكم ستذكرون النساء المعتدات، ولن تصبروا على السكوت عنهن، لضعفكم؛ لذلك اباح لكم ان تذكروهن تلميحا او اضمارا في النفس، واحذروا ان تواعدوهن على النكاح سرا بالزنى او الاتفاق على الزواج في اثناء العده، الا ان تقولوا قولا يفهم منه ان مثلها يرغب فيها الازواج، ولا تعزموا على عقد النكاح في زمان العده حتى تنقضي مدتها. واعلموا ان الله يعلم ما في انفسكم فخافوه، واعلموا ان الله غفور لمن تاب من ذنوبه، حليم على عباده لا يعجل عليهم بالعقوبه."},{"id":"243","s":2,"a":236,"at":"لا جناح عليكم ان طلقتم النساء ما لم تمسوهن او تفرضوا لهن فريضه ومتعوهن على الموسع قدره وعلى المقتر قدره متاعا بالمعروف حقا على المحسنين","dt":"[236] لا اثم عليكم -ايها الازواج- ان طلقتم النساء بعد العقد عليهن، وقبل ان تجامعوهن، او تحددوا مهرا لهن، ومتعوهن بشيء ينتفعن به جبرا لهن، ودفعا لوحشه الطلاق، وازاله للاحقاد. وهذه المتعه تجب بحسب حال الرجل المطلق: على الغني قدر سعه رزقه، وعلى الفقير قدر ما يملكه، متاعا على الوجه المعروف شرعا، وهو حق ثابت على الذين يحسنون الى المطلقات والى انفسهم بطاعه الله."},{"id":"244","s":2,"a":237,"at":"وان طلقتموهن من قبل ان تمسوهن وقد فرضتم لهن فريضه فنصف ما فرضتم الا ان يعفون او يعفو الذي بيده عقده النكاح وان تعفوا اقرب للتقوى ولا تنسوا الفضل بينكم ان الله بما تعملون بصير","dt":"[237] وان طلقتم النساء بعد العقد عليهن، ولم تجامعوهن، ولكنكم الزمتم انفسكم بمهر محدد لهن، فيجب عليكم ان تعطوهن نصف المهر المتفق عليه، الا ان تسامح المطلقات، فيتركن نصف المهر المستحق لهن، او يسمح الزوج بان يترك للمطلقه المهر كله، وتسامحكم ايها الرجال والنساء اقرب الى خشيه الله وطاعته، ولا تنسوا -ايها الناس- الفضل والاحسان بينكم، وهو اعطاء ما ليس بواجب عليكم، والتسامح في الحقوق. ان الله بما تعملون بصير، يرغبكم في المعروف، ويحثكم على الفضل."},{"id":"245","s":2,"a":238,"at":"حافظوا على الصلوات والصلاه الوسطى وقوموا لله قانتين","dt":"[238] حافظوا -ايها المسلمون- على الصلوات الخمس المفروضه بالمداومه على ادائها في اوقاتها بشروطها واركانها وواجباتها، وحافظوا على الصلاه المتوسطه بينها وهي صلاه العصر، وقوموا في صلاتكم مطيعين لله، خاشعين ذ ليلين."},{"id":"246","s":2,"a":239,"at":"فان خفتم فرجالا او ركبانا فاذا امنتم فاذكروا الله كما علمكم ما لم تكونوا تعلمون","dt":"[239] فان خفتم من عدو لكم فصلوا صلاه الخوف ماشين، او راكبين، على اي هيئه تستطيعونها ولو بالايماء، او الى غير جهه القبله، فاذا زال خوفكم فصلوا صلاه الامن، واذكروا الله فيها، ولا تنقصوها عن هيئتها الاصليه، واشكروا له على ما علمكم من امور العبادات والاحكام ما لم تكونوا على علم به."},{"id":"247","s":2,"a":240,"at":"والذين يتوفون منكم ويذرون ازواجا وصيه لازواجهم متاعا الى الحول غير اخراج فان خرجن فلا جناح عليكم في ما فعلن في انفسهن من معروف والله عزيز حكيم","dt":"[240] والازواج الذين يموتون ويتركون زوجات بعدهم، فليوصوا وصيه لهن: ان يمتعن سنه تامه من يوم الوفاه، بالسكنى في منزل الزوج من غير اخراج الورثه لهن مده السنه؛ جبرا لخاطر الزوجه، وبرا بالمتوفى. فان خرجت الزوجات باختيارهن قبل انقضاء السنه، فلا اثم عليكم -ايها الورثه- في ذلك، ولا حرج على الزوجات فيما فعلن في انفسهن من امور مباحه. والله عزيز في ملكه، حكيم في امره ونهيه. وهذه الايه منسوخه بقوله تعالى: والذين يتوفون منكم ويذرون ازوجا يتربصن بانفسهن اربعه اشهر وعشرا."},{"id":"248","s":2,"a":241,"at":"وللمطلقات متاع بالمعروف حقا على المتقين","dt":"[241] وللمطلقات متاع من كسوه ونفقه على الوجه المعروف المستحسن شرعا، حقا على الذين يخافون الله ويتقونه في امره ونهيه."},{"id":"249","s":2,"a":242,"at":"كذلك يبين الله لكم اياته لعلكم تعقلون","dt":"[242] مثل ذلك البيان الواضح في احكام الاولاد والنساء، يبين الله لكم اياته واحكامه في كل ما تحتاجون اليه في معاشكم ومعادكم؛ لكي تعقلوها وتعملوا بها."},{"id":"250","s":2,"a":243,"at":"الم تر الى الذين خرجوا من ديارهم وهم الوف حذر الموت فقال لهم الله موتوا ثم احياهم ان الله لذو فضل على الناس ولكن اكثر الناس لا يشكرون","dt":"[243] الم تعلم -ايها الرسول- قصه الذين فروا من ارضهم ومنازلهم، وهم الوف كثيره؛ خشيه الموت من الطاعون او القتال، فقال لهم الله: موتوا، فماتوا دفعه واحده عقوبه على فرارهم من قدر الله، ثم احياهم الله تعالى بعد مده؛ ليستوفوا اجالهم، وليتعظوا ويتوبوا؟ ان الله لذو فضل عظيم على الناس بنعمه الكثيره، ولكن اكثر الناس لا يشكرون فضل الله عليهم."},{"id":"251","s":2,"a":244,"at":"وقاتلوا في سبيل الله واعلموا ان الله سميع عليم","dt":"[244] وقاتلوا -ايها المسلمون- الكفار لنصره دين الله، واعلموا ان الله سميع لاقوالكم، عليم بنياتكم واعمالكم."},{"id":"252","s":2,"a":245,"at":"من ذا الذي يقرض الله قرضا حسنا فيضاعفه له اضعافا كثيره والله يقبض ويبسط واليه ترجعون","dt":"[245] من ذا الذي ينفق في سبيل الله انفاقا حسنا احتسابا للاجر، فيضاعفه له اضعافا كثيره لا تحصى من الثواب وحسن الجزاء؟ والله يقبض ويبسط، فانفقوا ولا تبالوا؛ فانه هو الرزاق، يضيق على من يشاء من عباده في الرزق، ويوسعه على اخرين، له الحكمه البالغه في ذلك، واليه وحده ترجعون بعد الموت، فيجازيكم على اعمالكم."},{"id":"253","s":2,"a":246,"at":"الم تر الى الملا من بني اسرائيل من بعد موسى اذ قالوا لنبي لهم ابعث لنا ملكا نقاتل في سبيل الله قال هل عسيتم ان كتب عليكم القتال الا تقاتلوا قالوا وما لنا الا نقاتل في سبيل الله وقد اخرجنا من ديارنا وابنائنا فلما كتب عليهم القتال تولوا الا قليلا منهم والله عليم بالظالمين","dt":"[246] الم تعلم -ايها الرسول- قصه الاشراف والوجهاء من بني اسرائيل من بعد زمان موسى؟ حين طلبوا من نبيهم ان يولي عليهم ملكا، يجتمعون تحت قيادته، ويقاتلون اعداءهم في سبيل الله. قال لهم نبيهم: هل الامر كما اتوقعه ان فرض عليكم القتال في سبيل الله انكم لا تقاتلون؟ فاني اتوقع جبنكم وفراركم من القتال، قالوا مستنكرين توقع نبيهم: واي مانع يمنعنا عن القتال في سبيل الله، وقد اخرجنا عدونا من ديارنا، وابعدنا عن اولادنا بالقتل والاسر؟ فلما فرض الله عليهم القتال مع الملك الذي عينه لهم جبنوا وفروا عن القتال، الا قليلا منهم ثبتوا بفضل الله. والله عليم بالظالمين الناكثين عهودهم."},{"id":"254","s":2,"a":247,"at":"وقال لهم نبيهم ان الله قد بعث لكم طالوت ملكا قالوا انى يكون له الملك علينا ونحن احق بالملك منه ولم يؤت سعه من المال قال ان الله اصطفاه عليكم وزاده بسطه في العلم والجسم والله يؤتي ملكه من يشاء والله واسع عليم","dt":"[247] وقال لهم نبيهم: ان الله قد ارسل اليكم طالوت ملكا اجابه لطلبكم، يقودكم لقتال عدوكم كما طلبتم. قال كبراء بني اسرائيل: كيف يكون طالوت ملكا علينا، وهو لا يستحق ذلك؟ لانه ليس من سبط الملوك، ولا من بيت النبوه، ولم يعط كثره في الاموال يستعين بها في ملكه، فنحن احق بالملك منه؛ لاننا من سبط الملوك ومن بيت النبوه. قال لهم نبيهم: ان الله اختاره عليكم وهو سبحانه اعلم بامور عباده، وزاده سعه في العلم وقوه في الجسم ليجاهد العدو. والله مالك الملك يعطي ملكه من يشاء من عباده، والله واسع الفضل والعطاء، عليم بحقائق الامور، لا يخفى عليه شيء."},{"id":"255","s":2,"a":248,"at":"وقال لهم نبيهم ان ايه ملكه ان ياتيكم التابوت فيه سكينه من ربكم وبقيه مما ترك ال موسى وال هارون تحمله الملائكه ان في ذلك لايه لكم ان كنتم مؤمنين","dt":"[248] وقال لهم نبيهم: ان علامه ملكه ان ياتيكم الصندوق الذي فيه التوراه -وكان اعداؤهم قد انتزعوه منهم- فيه طمانينه من ربكم تثبت قلوب المخلصين، وفيه بقيه من بعض اشياء تركها ال موسى وال هارون، مثل العصا وفتات الالواح تحمله الملائكه. ان في ذلك لاعظم برهان لكم على اختيار طالوت ملكا عليكم بامر الله، ان كنتم مصدقين بالله ورسله."},{"id":"256","s":2,"a":249,"at":"فلما فصل طالوت بالجنود قال ان الله مبتليكم بنهر فمن شرب منه فليس مني ومن لم يطعمه فانه مني الا من اغترف غرفه بيده فشربوا منه الا قليلا منهم فلما جاوزه هو والذين امنوا معه قالوا لا طاقه لنا اليوم بجالوت وجنوده قال الذين يظنون انهم ملاقو الله كم من فئه قليله غلبت فئه كثيره باذن الله والله مع الصابرين","dt":"[249] فلما خرج طالوت بجنوده لقتال العمالقه قال لهم: ان الله ممتحنكم على الصبر بنهر امامكم تعبرونه؛ ليتميز المؤمن من المنافق، فمن شرب منكم من ماء النهر فليس من اهل ديني، ولا يصلح للجهاد معي، ومن لم يذق الماء فانه مني؛ لانه مطيع لامري وصالح للجهاد، الا من ترخص واغترف غرفه واحده بيده فلا لوم عليه. فلما وصلوا الى النهر انكبوا على الماء، وافرطوا في الشرب منه، الا عددا قليلا منهم صبروا على العطش والحر، واكتفوا بغرفه اليد، وحينئذ تخلف العصاه. ولما عبر طالوت النهر هو والقله المؤمنه معه -وهم ثلاثمائه وبضعه عشر رجلا- لملاقاه العدو، وراوا كثره عدوهم وعدتهم، قالوا: لا قدره لنا اليوم بجالوت وجنوده الاشداء، فاجاب الذين يوقنون بلقاء الله، يذكرون اخوانهم بالله وقدرته قائلين: كم من جماعه قليله مؤمنه صابره، غلبت - باذن الله وامره - جماعه كثيره كافره باغيه. والله مع الصابرين بتوفيقه ونصره، وحسن مثوبته."},{"id":"257","s":2,"a":250,"at":"ولما برزوا لجالوت وجنوده قالوا ربنا افرغ علينا صبرا وثبت اقدامنا وانصرنا على القوم الكافرين","dt":"[250] ولما ظهروا لجالوت وجنوده، وراوا الخطر راي العين، فزعوا الى الله بالدعاء والضراعه قائلين: ربنا انزل على قلوبنا صبرا عظيما، وثبت اقدامنا، واجعلها راسخه في قتال العدو، لا تفر من هول الحرب، وانصرنا بعونك وتاييدك على القوم الكافرين."},{"id":"258","s":2,"a":251,"at":"فهزموهم باذن الله وقتل داود جالوت واتاه الله الملك والحكمه وعلمه مما يشاء ولولا دفع الله الناس بعضهم ببعض لفسدت الارض ولكن الله ذو فضل على العالمين","dt":"[251] فهزموهم باذن الله، وقتل داود -عليه السلام- جالوت قائد الجبابره، واعطى الله عز وجل داود - بعد ذلك - الملك والنبوه في بني اسرائيل، وعلمه مما يشاء من العلوم. ولولا ان يدفع الله ببعض الناس -وهم اهل الطاعه له والايمان به- بعضا، وهم اهل المعصيه لله والشرك به، لفسدت الارض بغلبه الكفر، وتمكن الطغيان، واهل المعاصي، ولكن الله ذو فضل على المخلوقين جميعا."},{"id":"259","s":2,"a":252,"at":"تلك ايات الله نتلوها عليك بالحق وانك لمن المرسلين","dt":"[252] تلك حجج الله وبراهينه، نقصها عليك -ايها النبي- بالصدق، وانك لمن المرسلين الصادقين."},{"id":"260","s":2,"a":253,"at":"تلك الرسل فضلنا بعضهم على بعض منهم من كلم الله ورفع بعضهم درجات واتينا عيسى ابن مريم البينات وايدناه بروح القدس ولو شاء الله ما اقتتل الذين من بعدهم من بعد ما جاءتهم البينات ولكن اختلفوا فمنهم من امن ومنهم من كفر ولو شاء الله ما اقتتلوا ولكن الله يفعل ما يريد","dt":"[253] هؤلاء الرسل الكرام فضل الله بعضهم على بعض، بحسب ما من الله به عليهم: فمنهم من كلمه الله كموسى ومحمد عليهما الصلاه والسلام، وفي هذا اثبات صفه الكلام لله عز وجل على الوجه اللائق بجلاله، ومنهم من رفعه الله درجات عاليه كمحمد -صلى الله عليه وسلم-، بعموم رسالته، وختم النبوه به، وتفضيل امته على جميع الامم، وغير ذلك. واتى الله تعالى عيسى بن مريم عليه السلام البينات المعجزات الباهرات، كابراء من ولد اعمى باذن الله تعالى، ومن به برص باذن الله، وكاحيائه الموتى باذن الله، وايده بجبريل عليه السلام. ولو شاء الله الا يقتتل الذين جاؤوا من بعد هؤلاء الرسل، من بعد ما جاءتهم البينات ما اقتتلوا، ولكن وقع الاختلاف بينهم: فمنهم من ثبت على ايمانه، ومنهم من اصر على كفره. ولو شاء الله بعد ما وقع الاختلاف بينهم، الموجب للاقتتال، ما اقتتلوا، ولكن الله يوفق من يشاء لطاعته والايمان به، ويخذل من يشاء، فيعصيه ويكفر به، فهو يفعل ما يشاء ويختار."},{"id":"261","s":2,"a":254,"at":"ياايها الذين امنوا انفقوا مما رزقناكم من قبل ان ياتي يوم لا بيع فيه ولا خله ولا شفاعه والكافرون هم الظالمون","dt":"[254] يا من امنتم بالله وصدقتم رسوله وعملتم بهديه اخرجوا الزكاه المفروضه، وتصدقوا مما اعطاكم الله قبل مجيء يوم القيامه، حين لا بيع فيكون ربح، ولا مال تفتدون به انفسكم من عذاب الله، ولا صداقه صديق تنقذكم، ولا شافع يملك تخفيف العذاب عنكم. والكافرون هم الظالمون المتجاوزون حدود الله."},{"id":"262","s":2,"a":255,"at":"الله لا اله الا هو الحي القيوم لا تاخذه سنه ولا نوم له ما في السموات وما في الارض من ذا الذي يشفع عنده الا باذنه يعلم ما بين ايديهم وما خلفهم ولا يحيطون بشيء من علمه الا بما شاء وسع كرسيه السموات والارض ولا يئوده حفظهما وهو العلي العظيم","dt":"[255] الله الذي لا يستحق الالوهيه والعبوديه الا هو، الحي الذي له جميع معاني الحياه الكامله كما يليق بجلاله، القائم على كل شيء، لا تاخذه سنه اي: نعاس، ولا نوم، كل ما في السموات وما في الارض ملك له، ولا يتجاسر احد ان يشفع عنده الا باذنه، محيط علمه بجميع الكائنات ماضيها وحاضرها ومستقبلها، يعلم ما بين ايدي الخلائق من الامور المستقبله، وما خلفهم من الامور الماضيه، ولا يطلع احد من الخلق على شيء من علمه الا بما اعلمه الله واطلعه عليه، وسع كرسيه السموات والارض، والكرسي: هو موضع قدمي الرب -جل جلاله- ولا يعلم كيفيته الا الله سبحانه، ولا يثقله سبحانه حفظهما، وهو العلي بذاته وصفاته على جميع مخلوقاته، الجامع لجميع صفات العظمه والكبرياء. وهذه الايه اعظم ايه في القران، وتسمى: (ايه الكرسي)."},{"id":"263","s":2,"a":256,"at":"لا اكراه في الدين قد تبين الرشد من الغي فمن يكفر بالطاغوت ويؤمن بالله فقد استمسك بالعروه الوثقى لا انفصام لها والله سميع عليم","dt":"[256] لكمال هذا الدين واتضاح اياته لا يحتاج الى الاكراه عليه، فالدلائل بينه يتضح بها الحق من الباطل، والهدى من الضلال. فمن يكفر بكل ما عبد من دون الله ويؤمن بالله، فقد ثبت واستقام على الطريقه المثلى، واستمسك من الدين باقوى سبب لا انقطاع له. والله سميع لاقوال عباده، عليم بنياتهم وافعالهم، وسيجازيهم على ذلك."},{"id":"264","s":2,"a":257,"at":"الله ولي الذين امنوا يخرجهم من الظلمات الى النور والذين كفروا اولياؤهم الطاغوت يخرجونهم من النور الى الظلمات اولئك اصحاب النار هم فيها خالدون","dt":"[257] الله يتولى المؤمنين بنصره وتوفيقه وحفظه، يخرجهم من ظلمات الكفر، الى نور الايمان. والذين كفروا انصارهم واولياؤهم الانداد والاوثان الذين يعبدونهم من دون الله، يخرجونهم من نور الايمان الى ظلمات الكفر، اولئك اصحاب النار الملازمون لها، هم فيها باقون بقاء ابديا لا يخرجون منها."},{"id":"265","s":2,"a":258,"at":"الم تر الى الذي حاج ابراهيم في ربه ان اتاه الله الملك اذ قال ابراهيم ربي الذي يحيي ويميت قال انا احيي واميت قال ابراهيم فان الله ياتي بالشمس من المشرق فات بها من المغرب فبهت الذي كفر والله لا يهدي القوم الظالمين","dt":"[258] هل رايت -ايها الرسول- اعجب من حال هذا الذي جادل ابراهيم عليه السلام في توحيد الله تعالى وربوبيته؛ لان الله اعطاه الملك فتجبر وسال ابراهيم: من ربك؟ فقال عليه السلام: ربي الذي يحيي الخلائق فتحيا، ويسلبها الحياه فتموت، فهو المتفرد بالاحياء والاماته، قال: انا احيي واميت، اي اقتل من اردت قتله، واستبقي من اردت استبقاءه، فقال له ابراهيم: ان الله الذي اعبده ياتي بالشمس من المشرق، فهل تستطيع تغيير هذه السنه الالهيه بان تجعلها تاتي من المغرب؟ فتحير هذا الكافر وانقطعت حجته، شانه شان الظالمين لا يهديهم الله الى الحق والصواب."},{"id":"266","s":2,"a":259,"at":"او كالذي مر على قريه وهي خاويه على عروشها قال انى يحيي هذه الله بعد موتها فاماته الله مائه عام ثم بعثه قال كم لبثت قال لبثت يوما او بعض يوم قال بل لبثت مائه عام فانظر الى طعامك وشرابك لم يتسنه وانظر الى حمارك ولنجعلك ايه للناس وانظر الى العظام كيف ننشزها ثم نكسوها لحما فلما تبين له قال اعلم ان الله على كل شيء قدير","dt":"[259] او هل رايت -ايها الرسول- مثل الذي مر على قريه قد تهدمت دورها، وخوت على عروشها، فقال: كيف يحيي الله هذه القريه بعد موتها؟ فاماته الله مائه عام، ثم رد اليه روحه، وقال له: كم قدر الزمان الذي لبثت ميتا؟ قال: بقيت يوما او بعض يوم، فاخبره بانه بقي ميتا مائه عام، وامره ان ينظر الى طعامه وشرابه، وكيف حفظهما الله من التغير هذه المده الطويله، وامره ان ينظر الى حماره كيف احياه الله بعد ان كان عظاما متفرقه، وقال له: ولنجعلك ايه للناس، اي: دلاله ظاهره على قدره الله على البعث بعد الموت، وامره ان ينظر الى العظام كيف يرفع الله بعضها على بعض، ويصل بعضها ببعض، ثم يكسوها بعد الالتئام لحما، ثم يعيد فيها الحياه، فلما اتضح له ذلك عيانا اعترف بعظمه الله، وانه على كل شيء قدير، وصار ايه للناس."},{"id":"267","s":2,"a":260,"at":"واذ قال ابراهيم رب ارني كيف تحي الموتى قال او لم تؤمن قال بلى ولكن ليطمئن قلبي قال فخذ اربعه من الطير فصرهن اليك ثم اجعل على كل جبل منهن جزءا ثم ادعهن ياتينك سعيا واعلم ان الله عزيز حكيم","dt":"[260] واذكر -ايها الرسول- طلب ابراهيم من ربه ان يريه كيفيه البعث، فقال الله له: او لم تؤمن؟ قال: بلى، ولكن اطلب ذلك لازداد يقينا على يقيني، قال: فخذ اربعه من الطير فاضممهن اليك واذبحهن وقطعهن، ثم اجعل على كل جبل منهن جزءا، ثم نادهن ياتينك مسرعات. فنادى ابراهيم عليه السلام، فاذا كل جزء يعود الى موضعه، واذا بها تاتي مسرعه. واعلم ان الله عزيز لا يغلبه شيء، حكيم في اقواله وافعاله وشرعه وقدره."},{"id":"268","s":2,"a":261,"at":"مثل الذين ينفقون اموالهم في سبيل الله كمثل حبه انبتت سبع سنابل في كل سنبله مائه حبه والله يضاعف لمن يشاء والله واسع عليم","dt":"[261] ومن اعظم ما ينتفع به المؤمنون الانفاق في سبيل الله. ومثل المؤمنين الذين ينفقون اموالهم في سبيل الله كمثل حبه زرعت في ارض طيبه، فاذا بها قد اخرجت ساقا تشعب منها سبع شعب، لكل واحده سنبله، في كل سنبله مائه حبه. والله يضاعف الاجر لمن يشاء، بحسب ما يقوم بقلب المنفق من الايمان والاخلاص التام. وفضل الله واسع، وهو سبحانه عليم بمن يستحقه، مطلع على نيات عباده."},{"id":"269","s":2,"a":262,"at":"الذين ينفقون اموالهم في سبيل الله ثم لا يتبعون ما انفقوا منا ولا اذى لهم اجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون","dt":"[262] الذين يخرجون اموالهم في الجهاد وانواع الخير، ثم لا يتبعون ما انفقوا من الخيرات منا على من اعطوه ولا اذى بقول او فعل يشعره بالتفضل عليه، لهم ثوابهم العظيم عند ربهم، ولا خوف عليهم فيما يستقبلونه من امر الاخره، ولا هم يحزنون على شيء فاتهم في هذه الدنيا."},{"id":"270","s":2,"a":263,"at":"قول معروف ومغفره خير من صدقه يتبعها اذى والله غني حليم","dt":"[263] كلام طيب يرد به السائل، وعفو عما بدر منه من الحاح في السؤال، خير من صدقه يتبعها من المتصدق اذى واساءه. والله غني عن صدقات العباد، حليم لا يعاجلهم بالعقوبه."},{"id":"271","s":2,"a":264,"at":"ياايها الذين امنوا لا تبطلوا صدقاتكم بالمن والاذى كالذي ينفق ماله رئاء الناس ولا يؤمن بالله واليوم الاخر فمثله كمثل صفوان عليه تراب فاصابه وابل فتركه صلدا لا يقدرون على شيء مما كسبوا والله لا يهدي القوم الكافرين","dt":"[264] يا من امنتم بالله واليوم الاخر لا تذهبوا ثواب ما تتصدقون به بالمن والاذى، فهذا شبيه بالذي يخرج ماله ليراه الناس، فيثنوا عليه، وهو لا يؤمن بالله ولا يوقن باليوم الاخر، فمثل ذلك مثل حجر املس عليه تراب هطل عليه مطر غزير فازاح عنه التراب، فتركه املس لا شيء عليه، فكذلك هؤلاء المراؤون تضمحل اعمالهم عند الله، ولا يجدون شيئا من الثواب على ما انفقوه. والله لا يوفق الكافرين لاصابه الحق في نفقاتهم وغيرها."},{"id":"272","s":2,"a":265,"at":"ومثل الذين ينفقون اموالهم ابتغاء مرضات الله وتثبيتا من انفسهم كمثل جنه بربوه اصابها وابل فاتت اكلها ضعفين فان لم يصبها وابل فطل والله بما تعملون بصير","dt":"[265] ومثل الذين ينفقون اموالهم طلبا لرضا الله واعتقادا راسخا بصدق وعده، كمثل بستان عظيم بارض عاليه طيبه هطلت عليه امطار غزيره، فتضاعفت ثمراته، وان لم تسقط عليه الامطار الغزيره فيكفيه رذاذ المطر ليعطي الثمره المضاعفه، وكذلك نفقات المخلصين تقبل عند الله وتضاعف، قلت ام كثرت، فالله المطلع على السرائر، البصير بالظواهر والبواطن، يثيب كلا بحسب اخلاصه."},{"id":"273","s":2,"a":266,"at":"ايود احدكم ان تكون له جنه من نخيل واعناب تجري من تحتها الانهار له فيها من كل الثمرات واصابه الكبر وله ذريه ضعفاء فاصابها اعصار فيه نار فاحترقت كذلك يبين الله لكم الايات لعلكم تتفكرون","dt":"[266] ايرغب الواحد منكم ان يكون له بستان فيه النخيل والاعناب، تجري من تحت اشجاره المياه العذبه، وله فيه من كل الوان الثمرات، وقد بلغ الكبر، ولا يستطيع ان يغرس مثل هذا الغرس، وله اولاد صغار في حاجه الى هذا البستان، وفي هذه الحاله هبت عليه ريح شديده، فيها نار محرقه فاحرقته؟ وهكذا حال غير المخلصين في نفقاتهم، ياتون يوم القيامه ولا حسنه لهم. بمثل هذا البيان يبين الله لكم ما ينفعكم؛ كي تتاملوا، فتخلصوا نفقاتكم لله."},{"id":"274","s":2,"a":267,"at":"ياايها الذين امنوا انفقوا من طيبات ما كسبتم ومما اخرجنا لكم من الارض ولا تيمموا الخبيث منه تنفقون ولستم باخذيه الا ان تغمضوا فيه واعلموا ان الله غني حميد","dt":"[267] يامن امنتم بي واتبعتم رسلي انفقوا من الحلال الطيب الذي كسبتموه ومما اخرجنا لكم من الارض، ولا تقصدوا الرديء منه لتعطوه الفقراء، ولو اعطيتموه لم تاخذوه الا اذا تغاضيتم عما فيه من رداءه ونقص. فكيف ترضون لله ما لا ترضونه لانفسكم؟ واعلموا ان الله الذي رزقكم غني عن صدقاتكم، مستحق للثناء، محمود في كل حال."},{"id":"275","s":2,"a":268,"at":"الشيطان يعدكم الفقر ويامركم بالفحشاء والله يعدكم مغفره منه وفضلا والله واسع عليم","dt":"[268] هذا البخل واختيار الرديء للصدقه من الشيطان الذي يخوفكم الفقر، ويغريكم بالبخل، ويامركم بالمعاصي ومخالفه الله تعالى، والله سبحانه وتعالى يعدكم على انفاقكم غفرانا لذنوبكم ورزقا واسعا. والله واسع الفضل، عليم بالنيات والاعمال."},{"id":"276","s":2,"a":269,"at":"يؤتي الحكمه من يشاء ومن يؤت الحكمه فقد اوتي خيرا كثيرا وما يذكر الا اولو الالباب","dt":"[269] يؤتي الله الاصابه في القول والفعل من يشاء من عباده، ومن انعم الله عليه بذلك فقد اعطاه خيرا كثيرا. وما يتذكر هذا وينتفع به الا اصحاب العقول المستنيره بنور الله وهدايته."},{"id":"277","s":2,"a":270,"at":"وما انفقتم من نفقه او نذرتم من نذر فان الله يعلمه وما للظالمين من انصار","dt":"[270] وما اعطيتم من مال او غيره قليل او كثير تتصدقون به ابتغاء مرضات الله، او اوجبتم على انفسكم شيئا من مال او غيره، فان الله يعلمه، وهو المطلع على نياتكم، وسوف يثيبكم على ذلك. ومن منع حق الله فهو ظالم، والظالمون ليس لهم انصار يمنعونهم من عذاب الله."},{"id":"278","s":2,"a":271,"at":"ان تبدوا الصدقات فنعما هي وان تخفوها وتؤتوها الفقراء فهو خير لكم ويكفر عنكم من سيئاتكم والله بما تعملون خبير","dt":"[271] ان تظهروا ما تتصدقون به لله فنعم ما تصدقتم به، وان تسروا بها، وتعطوها الفقراء فهذا افضل لكم؛ لانه ابعد عن الرياء، وفي الصدقه -مع الاخلاص- محو لذنوبكم. والله الذي يعلم دقائق الامور، لا يخفى عليه شيء من احوالكم، وسيجازي كلا بعمله."},{"id":"279","s":2,"a":272,"at":"ليس عليك هداهم ولكن الله يهدي من يشاء وما تنفقوا من خير فلانفسكم وما تنفقون الا ابتغاء وجه الله وما تنفقوا من خير يوف اليكم وانتم لا تظلمون","dt":"[272] لست -ايها الرسول- مسؤولا عن توفيق الكافرين للهدايه، ولكن الله يشرح صدور من يشاء لدينه، ويوفقهم له. وما تبذلوا من مال يعد عليكم نفعه من الله، والمؤمنون لا ينفقون الا طلبا لمرضاه الله. وما تنفقوا من مال -مخلصين لله- توفوا ثوابه، ولا تنقصوا شيئا من ذلك. وفي الايه اثبات صفه الوجه لله تعالى على ما يليق به سبحانه."},{"id":"280","s":2,"a":273,"at":"للفقراء الذين احصروا في سبيل الله لا يستطيعون ضربا في الارض يحسبهم الجاهل اغنياء من التعفف تعرفهم بسيماهم لا يسالون الناس الحافا وما تنفقوا من خير فان الله به عليم","dt":"[273] اجعلوا صدقاتكم لفقراء المسلمين الذين لا يستطيعون السفر؛ طلبا للرزق لاشتغالهم بالجهاد في سبيل الله، يظنهم من لا يعرفهم غير محتاجين الى الصدقه؛ لتعففهم عن السؤال، تعرفهم بعلاماتهم واثار الحاجه فيهم، لا يسالون الناس بالكليه، وان سالوا اضطرارا لم يلحوا في السؤال. وما تنفقوا من مال في سبيل الله فلا يخفى على الله شيء منه، وسيجزي عليه اوفر الجزاء واتمه يوم القيامه."},{"id":"281","s":2,"a":274,"at":"الذين ينفقون اموالهم بالليل والنهار سرا وعلانيه فلهم اجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون","dt":"[274] الذين يخرجون اموالهم مرضاه لله ليلا ونهارا مسرين ومعلنين، فلهم اجرهم عند ربهم، ولا خوف عليهم فيما يستقبلونه من امر الاخره، ولا هم يحزنون على ما فاتهم من حظوظ الدنيا. ذلك التشريع الالهي الحكيم هو منهاج الاسلام في الانفاق لما فيه من سد حاجه الفقراء في كرامه وعزه، وتطهير مال الاغنياء، وتحقيق التعاون على البر والتقوى؛ ابتغاء وجه الله دون قهر او اكراه."},{"id":"282","s":2,"a":275,"at":"الذين ياكلون الربا لا يقومون الا كما يقوم الذي يتخبطه الشيطان من المس ذلك بانهم قالوا انما البيع مثل الربا واحل الله البيع وحرم الربا فمن جاءه موعظه من ربه فانتهى فله ما سلف وامره الى الله ومن عاد فاولئك اصحاب النار هم فيها خالدون","dt":"[275] الذين يتعاملون بالربا -وهو الزياده على راس المال- لا يقومون في الاخره من قبورهم الا كما يقوم الذي يتخبطه الشيطان من الجنون؛ ذلك لانهم قالوا: انما البيع مثل الربا، في ان كلا منهما حلال، ويؤدي الى زياده المال، فاكذبهم الله، وبين انه احل البيع وحرم الربا؛ لما في البيع والشراء من نفع للافراد والجماعات، ولما في الربا من استغلال وضياع وهلاك. فمن بلغه نهي الله عن الربا فارتدع، فله ما مضى قبل ان يبلغه التحريم لا اثم عليه فيه، وامره الى الله فيما يستقبل من زمانه، فان استمر على توبته فالله لا يضيع اجر المحسنين، ومن عاد الى الربا ففعله بعد بلوغه نهي الله عنه، فقد استوجب العقوبه، وقامت عليه الحجه، ولهذا قال سبحانه: فاولئك اصحب النار هم فيها خلدون ."},{"id":"283","s":2,"a":276,"at":"يمحق الله الربا ويربي الصدقات والله لا يحب كل كفار اثيم","dt":"[276] يذهب الله الربا كله، او يحرم صاحبه بركه ماله فلا ينتفع به، وينمي الصدقات ويكثرها، ويضاعف الاجر للمتصدقين، ويبارك لهم في اموالهم. والله لا يحب كل مصر على كفره، مستحل اكل الربا، متماد في الاثم والحرام ومعاصي الله."},{"id":"284","s":2,"a":277,"at":"ان الذين امنوا وعملوا الصالحات واقاموا الصلاه واتوا الزكاه لهم اجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون","dt":"[277] ان الذين صدقوا الله ورسوله، وعملوا الاعمال الطيبه، وادوا الصلاه كما امر الله ورسوله، واخرجوا زكاه اموالهم، لهم ثواب عظيم خاص بهم عند ربهم ورازقهم، ولا يلحقهم خوف في اخرتهم، ولا حزن على ما فاتهم من حظوظ دنياهم."},{"id":"285","s":2,"a":278,"at":"ياايها الذين امنوا اتقوا الله وذروا ما بقي من الربا ان كنتم مؤمنين","dt":"[278] يامن امنتم بالله واتبعتم رسوله خافوا الله، واتركوا طلب ما بقي لكم من زياده على رؤوس اموالكم التي كانت لكم قبل تحريم الربا، ان كنتم محققين ايمانكم قولا وعملا."},{"id":"286","s":2,"a":279,"at":"فان لم تفعلوا فاذنوا بحرب من الله ورسوله وان تبتم فلكم رءوس اموالكم لا تظلمون ولا تظلمون","dt":"[279] فان لم ترتدعوا عما نهاكم الله عنه فاستيقنوا بحرب من الله ورسوله، وان رجعتم الى ربكم وتركتم اكل الربا فلكم اخذ ما لكم من ديون، دون زياده، لا تظلمون احدا باخذ ما زاد على رؤوس اموالكم، ولا يظلمكم احد بنقص ما اقرضتم."},{"id":"287","s":2,"a":280,"at":"وان كان ذو عسره فنظره الى ميسره وان تصدقوا خير لكم ان كنتم تعلمون","dt":"[280] وان كان المدين غير قادر على السداد فامهلوه الى ان ييسر الله له رزقا فيدفع اليكم مالكم، وان تتركوا راس المال كله او بعضه وتضعوه عن المدين فهو افضل لكم، ان كنتم تعلمون فضل ذلك، وانه خير لكم في الدنيا والاخره."},{"id":"288","s":2,"a":281,"at":"واتقوا يوما ترجعون فيه الى الله ثم توفى كل نفس ما كسبت وهم لا يظلمون","dt":"[281] واحذروا -ايها الناس- يوما ترجعون فيه الى الله، وهو يوم القيامه، حيث تعرضون على الله ليحاسبكم، فيجازي كل واحد منكم بما عمل من خير او شر دون ان يناله ظلم. وفي الايه اشاره الى ان اجتناب ما حرم الله من المكاسب الربويه، تكميل للايمان وحقوقه من اقام الصلاه وايتاء الزكاه وعمل الصالحات."},{"id":"289","s":2,"a":282,"at":"ياايها الذين امنوا اذا تداينتم بدين الى اجل مسمى فاكتبوه وليكتب بينكم كاتب بالعدل ولا ياب كاتب ان يكتب كما علمه الله فليكتب وليملل الذي عليه الحق وليتق الله ربه ولا يبخس منه شيئا فان كان الذي عليه الحق سفيها او ضعيفا او لا يستطيع ان يمل هو فليملل وليه بالعدل واستشهدوا شهيدين من رجالكم فان لم يكونا رجلين فرجل وامراتان ممن ترضون من الشهداء ان تضل احداهما فتذكر احداهما الاخرى ولا ياب الشهداء اذا ما دعوا ولا تساموا ان تكتبوه صغيرا او كبيرا الى اجله ذلكم اقسط عند الله واقوم للشهاده وادنى الا ترتابوا الا ان تكون تجاره حاضره تديرونها بينكم فليس عليكم جناح الا تكتبوها واشهدوا اذا تبايعتم ولا يضار كاتب ولا شهيد وان تفعلوا فانه فسوق بكم واتقوا الله ويعلمكم الله والله بكل شيء عليم","dt":"[282] يامن امنتم بالله واتبعتم رسوله محمدا -صلى الله عليه وسلم- اذا تعاملتم بدين الى وقت معلوم فاكتبوه؛ حفظا للمال ودفعا للنزاع. وليقم بالكتابه رجل امين ضابط، ولا يمتنع من علمه الله الكتابه عن ذلك، وليقم المدين باملاء ما عليه من الدين، وليراقب ربه، ولا ينقص من دينه شيئا. فان كان المدين لا يحسن التصرف في ماله، او كان صغيرا او مجنونا، او لا يستطيع النطق لخرس به او عدم قدره كامله على الكلام، فليتول الاملاء عن المدين القائم بامره، واطلبوا شهاده رجلين مسلمين بالغين عاقلين من اهل العداله، فان لم يوجد رجلان، فاطلبوا شهاده رجل وامراتين ترضون شهادتهم؛ حتى اذا نسيت احداهما ذكرتها الاخرى، وعلى الشهداء ان يجيبوا من دعاهم الى الشهاده، وعليهم اداؤها اذا ما دعوا اليها، ولا تملوا من كتابه الدين قليلا او كثيرا الى وقته المعلوم. ذلكم اعدل في شرع الله وهديه، واعظم عونا على اقامه الشهاده وادائها، واقرب الى نفي الشك في جنس الدين وقدره واجله، لكن ان كانت المساله مساله بيع وشراء، باخذ سلعه ودفع ثمنها في الحال، فلا حاجه الى الكتابه، ويستحب الاشهاد على ذلك منعا للنزاع والشقاق، ومن الواجب على الشاهد والكاتب اداء الشهاده على وجهها والكتابه كما امر الله، ولا يجوز لصاحب الحق ومن عليه الحق الاضرار بالكتاب والشهود، وكذلك لا يجوز للكتاب والشهود ان يضاروا بمن احتاج الى كتابتهم او شهادتهم، وان تفعلوا ما نهيتم عنه فانه خروج عن طاعه الله، وعاقبه ذلك حاله بكم. وخافوا الله في جميع ما امركم به، ونهاكم عنه، ويعلمكم الله جميع ما يصلح دنياكم واخراكم. والله بكل شيء عليم، فلا يخفى عليه شيء من اموركم، وسيجازيكم على ذلك."},{"id":"290","s":2,"a":283,"at":"وان كنتم على سفر ولم تجدوا كاتبا فرهان مقبوضه فان امن بعضكم بعضا فليؤد الذي اؤتمن امانته وليتق الله ربه ولا تكتموا الشهاده ومن يكتمها فانه اثم قلبه والله بما تعملون عليم","dt":"[283] وان كنتم مسافرين ولم تجدوا من يكتب لكم فادفعوا الى صاحب الحق شيئا يكون عنده ضمانا لحقه الى ان يرد المدين ما عليه من دين، فان وثق بعضكم ببعض فلا حرج في ترك الكتابه والاشهاد والرهن، ويبقى الدين امانه في ذمه المدين، عليه اداؤه، وعليه ان يراقب الله فلا يخون صاحبه. فان انكر المدين ما عليه من دين، وكان هناك من حضر وشهد، فعليه ان يظهر شهادته، ومن اخفى هذه الشهاده فهو صاحب قلب غادر فاجر. والله المطلع على السرائر، المحيط علمه بكل اموركم، وسيحاسبكم على ذلك."},{"id":"291","s":2,"a":284,"at":"لله ما في السموات وما في الارض وان تبدوا ما في انفسكم او تخفوه يحاسبكم به الله فيغفر لمن يشاء ويعذب من يشاء والله على كل شيء قدير","dt":"[284] لله ملك السموات والارض وما فيهما ملكا وتدبيرا واحاطه، لا يخفى عليه شيء. وما تظهروه مما في انفسكم او تخفوه فان الله يعلمه، وسيحاسبكم به، فيعفو عمن يشاء، ويؤاخذ من يشاء. والله قادر على كل شيء.وقد اكرم الله المسلمين بعد ذلك فعفا عن حديث النفس وخطرات القلب، ما لم يتبعها كلام او عمل، كما ثبت ذلك عن رسول الله -صلى الله عليه وسلم-."},{"id":"292","s":2,"a":285,"at":"امن الرسول بما انزل اليه من ربه والمؤمنون كل امن بالله وملائكته وكتبه ورسله لا نفرق بين احد من رسله وقالوا سمعنا واطعنا غفرانك ربنا واليك المصير","dt":"[285] صدق وايقن رسول الله محمد -صلى الله عليه وسلم- بما اوحي اليه من ربه، وحق له ان يوقن، والمؤمنون كذلك صدقوا وعملوا بالقران العظيم، كل منهم صدق بالله ربا والها متصفا بصفات الجلال والكمال، وان لله ملائكه كراما، وانه انزل كتبا، وارسل الى خلقه رسلا، لا نؤمن -نحن المؤمنين- ببعضهم وننكر بعضهم، بل نؤمن بهم جميعا. وقال الرسول والمؤمنون: سمعنا يا ربنا ما اوحيت به، واطعنا في كل ذلك، نرجو ان تغفر -بفضلك- ذنوبنا، فانت الذي ربيتنا بما انعمت به علينا، واليك -وحدك- مرجعنا ومصيرنا."},{"id":"293","s":2,"a":286,"at":"لا يكلف الله نفسا الا وسعها لها ما كسبت وعليها ما اكتسبت ربنا لا تؤاخذنا ان نسينا او اخطانا ربنا ولا تحمل علينا اصرا كما حملته على الذين من قبلنا ربنا ولا تحملنا ما لا طاقه لنا به واعف عنا واغفر لنا وارحمنا انت مولانا فانصرنا على القوم الكافرين","dt":"[286] دين الله يسر لا مشقه فيه، فلا يطلب الله من عباده ما لا يطيقونه، فمن فعل خيرا نال خيرا، ومن فعل شرا نال شرا. ربنا لا تعاقبنا ان نسينا شيئا مما افترضته علينا، او اخطانا في فعل شيء نهيتنا عن فعله، ربنا ولا تكلفنا من الاعمال الشاقه ما كلفته من قبلنا من العصاه عقوبه لهم، ربنا ولا تحملنا ما لا نستطيعه من التكاليف والمصائب، وامح ذنوبنا، واستر عيوبنا، واحسن الينا، انت مالك امرنا ومدبره، فانصرنا على من جحدوا دينك وانكروا وحدانيتك، وكذبوا نبيك محمدا -صلى الله عليه وسلم-، واجعل العاقبه لنا عليهم في الدنيا والاخره."},{"id":"294","s":3,"a":1,"at":"الم","dt":"[1] الم سبق الكلام عليها في اول سوره البقره."},{"id":"295","s":3,"a":2,"at":"الله لا اله الا هو الحي القيوم","dt":"[2] هو الله، لا معبود بحق الا هو، المتصف بالحياه الكامله كما يليق بجلاله، القائم على كل شيء."},{"id":"296","s":3,"a":3,"at":"نزل عليك الكتاب بالحق مصدقا لما بين يديه وانزل التوراه والانجيل","dt":"[3] نزل عليك -ايها الرسول- القران بالحق الذي لا ريب فيه، يشهد على صدق ما قبله من كتب ورسل، وانزل التوراه على موسى عليه السلام، والانجيل على عيسى عليه السلام"},{"id":"297","s":3,"a":4,"at":"من قبل هدى للناس وانزل الفرقان ان الذين كفروا بايات الله لهم عذاب شديد والله عزيز ذو انتقام","dt":"[4] من قبل نزول القران؛ لارشاد المتقين الى الايمان، وصلاح دينهم ودنياهم، وانزل ما يفرق بين الحق والباطل. والذين كفروا بايات الله المنزله، لهم عذاب عظيم. والله عزيز لا يغالب، ذو انتقام ممن جحد حججه وادلته، وتفرده بالالوهيه."},{"id":"298","s":3,"a":5,"at":"ان الله لا يخفى عليه شيء في الارض ولا في السماء","dt":"[5] ان الله محيط علمه بالخلائق، لا يخفى عليه شيء في الارض ولا في السماء، قل او كثر."},{"id":"299","s":3,"a":6,"at":"هو الذي يصوركم في الارحام كيف يشاء لا اله الا هو العزيز الحكيم","dt":"[6] هو وحده الذي يخلقكم في ارحام امهاتكم كما يشاء، من ذكر وانثى، وحسن وقبيح، وشقي وسعيد، لا معبود بحق سواه، العزيز الذي لا يغالب، الحكيم في امره وتدبيره."},{"id":"300","s":3,"a":7,"at":"هو الذي انزل عليك الكتاب منه ايات محكمات هن ام الكتاب واخر متشابهات فاما الذين في قلوبهم زيغ فيتبعون ما تشابه منه ابتغاء الفتنه وابتغاء تاويله وما يعلم تاويله الا الله والراسخون في العلم يقولون امنا به كل من عند ربنا وما يذكر الا اولو الالباب","dt":"[7] هو وحده الذي انزل عليك القران: منه ايات واضحات الدلاله، هن اصل الكتاب الذي يرجع اليه عند الاشتباه، ويرد ما خالفه اليه، ومنه ايات اخر متشابهات تحتمل بعض المعاني، لا يتعين المراد منها الا بضمها الى المحكم، فاصحاب القلوب المريضه الزائغه، لسوء قصدهم يتبعون هذه الايات المتشابهات وحدها؛ ليثيروا الشبهات عند الناس، كي يضلوهم، ولتاويلهم لها على مذاهبهم الباطله. ولا يعلم حقيقه هذه الايات المتشابهات وما تؤول اليه الا الله. والمتمكنون في العلم يقولون: امنا بهذا القران، كله قد جاءنا من عند ربنا على لسان رسوله محمد -صلى الله عليه وسلم-، ويردون متشابهه الى محكمه، وانما يفهم ويعقل ويتدبر المعاني على وجهها الصحيح اولو العقول السليمه."},{"id":"301","s":3,"a":8,"at":"ربنا لا تزغ قلوبنا بعد اذ هديتنا وهب لنا من لدنك رحمه انك انت الوهاب","dt":"[8] ويقولون: يا ربنا لا تصرف قلوبنا عن الايمان بك بعد ان مننت علينا بالهدايه لدينك، وامنحنا من فضلك رحمه واسعه، انك انت الوهاب: كثير الفضل والعطاء، تعطي من تشاء بغير حساب."},{"id":"302","s":3,"a":9,"at":"ربنا انك جامع الناس ليوم لا ريب فيه ان الله لا يخلف الميعاد","dt":"[9] يا ربنا اننا نقر ونشهد بانك ستجمع الناس في يوم لاشك فيه، وهو يوم القيامه، انك لا تخلف ما وعدت به عبادك."},{"id":"303","s":3,"a":10,"at":"ان الذين كفروا لن تغني عنهم اموالهم ولا اولادهم من الله شيئا واولئك هم وقود النار","dt":"[10] ان الذين جحدوا الدين الحق وانكروه، لن تنفعهم اموالهم ولا اولادهم من عذاب الله شيئا ان وقع بهم في الدنيا، ولن تدفعه عنهم في الاخره، وهؤلاء هم حطب النار يوم القيامه."},{"id":"304","s":3,"a":11,"at":"كداب ال فرعون والذين من قبلهم كذبوا باياتنا فاخذهم الله بذنوبهم والله شديد العقاب","dt":"[11] شان الكافرين في تكذيبهم وما ينزل بهم، شان ال فرعون والذين من قبلهم من الكافرين، انكروا ايات الله الواضحه، فعاجلهم بالعقوبه بسبب تكذيبهم وعنادهم. والله شديد العقاب لمن كفر به وكذب رسله."},{"id":"305","s":3,"a":12,"at":"قل للذين كفروا ستغلبون وتحشرون الى جهنم وبئس المهاد","dt":"[12] قل -ايها الرسول- للذين كفروا من اليهود وغيرهم والذين استهانوا بنصرك في «بدر»: انكم ستهزمون في الدنيا وستموتون على الكفر، وتجمعون الى نار جهنم؛ لتكون فراشا دائما لكم، وبئس الفراش."},{"id":"306","s":3,"a":13,"at":"قد كان لكم ايه في فئتين التقتا فئه تقاتل في سبيل الله واخرى كافره يرونهم مثليهم راي العين والله يؤيد بنصره من يشاء ان في ذلك لعبره لاولي الابصار","dt":"[13] قد كان لكم -ايها اليهود المتكبرون المعاندون- دلاله عظيمه في جماعتين تقابلتا في معركه «بدر»: جماعه تقاتل من اجل دين الله، وهم محمد -صلى الله عليه وسلم- واصحابه، وجماعه اخرى كافره بالله، تقاتل من اجل الباطل، ترى المؤمنين في العدد مثليهم راي العين، وقد جعل الله ذلك سببا لنصر المسلمين عليهم. والله يؤيد بنصره من يشاء من عباده. ان في هذا الذي حدث لعظه عظيمه لاصحاب البصائر الذين يهتدون الى حكم الله وافعاله."},{"id":"307","s":3,"a":14,"at":"زين للناس حب الشهوات من النساء والبنين والقناطير المقنطره من الذهب والفضه والخيل المسومه والانعام والحرث ذلك متاع الحياه الدنيا والله عنده حسن الماب","dt":"[14] حسن للناس حب الشهوات من النساء والبنين، والاموال الكثيره من الذهب والفضه، والخيل الحسان، والانعام من الابل والبقر والغنم، والارض المتخذه للغراس والزراعه. ذلك زهره الحياه الدنيا وزينتها الفانيه. والله عنده حسن المرجع والثواب، وهو الجنه."},{"id":"308","s":3,"a":15,"at":"قل اؤنبئكم بخير من ذلكم للذين اتقوا عند ربهم جنات تجري من تحتها الانهار خالدين فيها وازواج مطهره ورضوان من الله والله بصير بالعباد","dt":"[15] قل -ايها الرسول-: ااخبركم بخير مما زين للناس في هذه الحياه الدنيا، لمن راقب الله وخاف عقابه جنات تجري من تحت قصورها واشجارها الانهار، خالدين فيها، ولهم فيها ازواج مطهرات من الحيض والنفاس، وسوء الخلق، ولهم اعظم من ذلك: رضوان من الله. والله مطلع على سرائر خلقه، عالم باحوالهم، وسيجازيهم على ذلك."},{"id":"309","s":3,"a":16,"at":"الذين يقولون ربنا اننا امنا فاغفر لنا ذنوبنا وقنا عذاب النار","dt":"[16] هؤلاء العباد المتقون يقولون: اننا امنا بك، واتبعنا رسولك محمدا -صلى الله عليه وسلم-، فامح عنا ما اقترفناه من ذنوب، ونجنا من عذاب النار."},{"id":"310","s":3,"a":17,"at":"الصابرين والصادقين والقانتين والمنفقين والمستغفرين بالاسحار","dt":"[17] هم الذين اتصفوا بالصبر على الطاعات، وعن المعاصي، وعلى ما يصيبهم من اقدار الله المؤلمه، وبالصدق في الاقوال والافعال، وبالطاعه التامه، وبالانفاق سرا وعلانيه، وبالاستغفار في اخر الليل؛ لانه مظنه القبول واجابه الدعاء."},{"id":"311","s":3,"a":18,"at":"شهد الله انه لا اله الا هو والملائكه واولو العلم قائما بالقسط لا اله الا هو العزيز الحكيم","dt":"[18] شهد الله انه المتفرد بالالهيه، وقرن شهادته بشهاده الملائكه واهل العلم، على اجل مشهود عليه، وهو توحيده تعالى وقيامه بالعدل، لا اله الا هو العزيز الذي لا يمتنع عليه شيء اراده، الحكيم في اقواله وافعاله."},{"id":"312","s":3,"a":19,"at":"ان الدين عند الله الاسلام وما اختلف الذين اوتوا الكتاب الا من بعد ما جاءهم العلم بغيا بينهم ومن يكفر بايات الله فان الله سريع الحساب","dt":"[19] ان الدين الذي ارتضاه الله لخلقه وارسل به رسله، ولا يقبل غيره هو الاسلام، وهو الانقياد لله وحده بالطاعه والاستسلام له بالعبوديه، واتباع الرسل فيما بعثهم الله به في كل حين حتى ختموا بمحمد -صلى الله عليه وسلم-، الذي لا يقبل الله من احد بعد بعثته دينا سوى الاسلام الذي ارسل به. وما وقع الخلاف بين اهل الكتاب من اليهود والنصارى، فتفرقوا شيعا واحزابا الا من بعد ما قامت الحجه عليهم بارسال الرسل وانزال الكتب؛ بغيا وحسدا طلبا للدنيا. ومن يجحد ايات الله المنزله واياته الداله على ربوبيته والوهيته، فان الله سريع الحساب، وسيجزيهم بما كانوا يعملون."},{"id":"313","s":3,"a":20,"at":"فان حاجوك فقل اسلمت وجهي لله ومن اتبعن وقل للذين اوتوا الكتاب والاميين ااسلمتم فان اسلموا فقد اهتدوا وان تولوا فانما عليك البلاغ والله بصير بالعباد","dt":"[20] فان جادلك -ايها الرسول- اهل الكتاب في التوحيد بعد ان اقمت الحجه عليهم فقل لهم: انني اخلصت لله وحده فلا اشرك به احدا، وكذلك من اتبعني من المؤمنين، اخلصوا لله وانقادوا له. وقل لهم ولمشركي العرب وغيرهم: ان اسلمتم فانتم على الطريق المستقيم والهدى والحق، وان توليتم فحسابكم على الله، وليس علي الا البلاغ، وقد ابلغتكم واقمت عليكم الحجه. والله بصير بالعباد، لا يخفى عليه من امرهم شيء."},{"id":"314","s":3,"a":21,"at":"ان الذين يكفرون بايات الله ويقتلون النبيين بغير حق ويقتلون الذين يامرون بالقسط من الناس فبشرهم بعذاب اليم","dt":"[21] ان الذين يجحدون بالدلائل الواضحه وما جاء به المرسلون، ويقتلون انبياء الله ظلما بغير حق، ويقتلون الذين يامرون بالعدل واتباع طريق الانبياء، فبشرهم بعذاب موجع."},{"id":"315","s":3,"a":22,"at":"اولئك الذين حبطت اعمالهم في الدنيا والاخره وما لهم من ناصرين","dt":"[22] اولئك الذين بطلت اعمالهم في الدنيا والاخره، فلا يقبل لهم عمل، وما لهم من ناصر ينصرهم من عذاب الله."},{"id":"316","s":3,"a":23,"at":"الم تر الى الذين اوتوا نصيبا من الكتاب يدعون الى كتاب الله ليحكم بينهم ثم يتولى فريق منهم وهم معرضون","dt":"[23] ارايت -ايها الرسول- اعجب من حال هؤلاء اليهود الذين اتاهم الله حظا من الكتاب فعلموا ان ما جئت به هو الحق، يدعون الى ما جاء في كتاب الله -وهو القران- ليفصل بينهم فيما اختلفوا فيه، فان لم يوافق اهواءهم ياب كثير منهم حكم الله؛ لان من عادتهم الاعراض عن الحق؟"},{"id":"317","s":3,"a":24,"at":"ذلك بانهم قالوا لن تمسنا النار الا اياما معدودات وغرهم في دينهم ما كانوا يفترون","dt":"[24] ذلك الانصراف عن الحق سببه اعتقاد فاسد لدى اهل الكتاب؛ بانهم لن يعذبوا الا اياما قليله، وهذا الاعتقاد ادى الى جراتهم على الله واستهانتهم بدينه، واستمرارهم على دينهم الباطل الذي خدعوا به انفسهم."},{"id":"318","s":3,"a":25,"at":"فكيف اذا جمعناهم ليوم لا ريب فيه ووفيت كل نفس ما كسبت وهم لا يظلمون","dt":"[25] فكيف يكون حالهم اذا جمعهم الله ليحاسبوا في يوم لا شك في وقوعه -وهو يوم القيامه-، واخذ كل واحد جزاء ما اكتسب، وهم لا يظلمون شيئا؟"},{"id":"319","s":3,"a":26,"at":"قل اللهم مالك الملك تؤتي الملك من تشاء وتنزع الملك ممن تشاء وتعز من تشاء وتذل من تشاء بيدك الخير انك على كل شيء قدير","dt":"[26] قل -ايها النبي متوجها الى ربك بالدعاء-: يا من لك الملك كله، انت الذي تمنح الملك والمال والتمكين في الارض من تشاء من خلقك، وتسلب الملك ممن تشاء، وتهب العزه في الدنيا والاخره من تشاء، وتجعل الذله على من تشاء، بيدك الخير، انك -وحدك- على كل شيء قدير. وفي الايه اثبات لصفه اليد لله تعالى على ما يليق به سبحانه."},{"id":"320","s":3,"a":27,"at":"تولج الليل في النهار وتولج النهار في الليل وتخرج الحي من الميت وتخرج الميت من الحي وترزق من تشاء بغير حساب","dt":"[27] ومن دلائل قدرتك انك تدخل الليل في النهار، وتدخل النهار في الليل، فيطول هذا ويقصر ذاك، وتخرج الحي من الميت الذي لا حياه فيه، كاخراج الزرع من الحب، والمؤمن من الكافر، وتخرج الميت من الحي كاخراج البيض من الدجاج، وترزق من تشاء من خلقك بغير حساب."},{"id":"321","s":3,"a":28,"at":"لا يتخذ المؤمنون الكافرين اولياء من دون المؤمنين ومن يفعل ذلك فليس من الله في شيء الا ان تتقوا منهم تقاه ويحذركم الله نفسه والى الله المصير","dt":"[28] ينهى الله المؤمنين ان يتخذوا الكافرين اولياء بالمحبه والنصره من دون المؤمنين، ومن يتولهم فقد برئ من الله، والله بريء منه، الا ان تكونوا ضعافا خائفين فقد رخص الله لكم في مهادنتهم اتقاء لشرهم، حتى تقوى شوكتكم. ويحذركم الله نفسه، فاتقوه وخافوه. والى الله وحده رجوع الخلائق للحساب والجزاء."},{"id":"322","s":3,"a":29,"at":"قل ان تخفوا ما في صدوركم او تبدوه يعلمه الله ويعلم ما في السموات وما في الارض والله على كل شيء قدير","dt":"[29] قل -ايها النبي- للمؤمنين: ان تكتموا ما استقر في قلوبكم من موالاه الكافرين ونصرتهم او تظهروا ذلك لا يخف على الله منه شيء، فان علمه محيط بكل ما في السموات وما في الارض، وله القدره التامه على كل شيء."},{"id":"323","s":3,"a":30,"at":"يوم تجد كل نفس ما عملت من خير محضرا وما عملت من سوء تود لو ان بينها وبينه امدا بعيدا ويحذركم الله نفسه والله رءوف بالعباد","dt":"[30] وفي يوم القيامه يوم الجزاء تجد كل نفس ما عملت من خير ينتظرها موفرا لتجزى به، وما عملت من عمل سيئ تجده في انتظارها ايضا، فتتمنى لو ان بينها وبين هذا العمل زمنا بعيدا. فاستعدوا لهذا اليوم، وخافوا بطش الاله الجبار. ومع شده عقابه فانه سبحانه المتصف بكمال الرحمه بالعباد."},{"id":"324","s":3,"a":31,"at":"قل ان كنتم تحبون الله فاتبعوني يحببكم الله ويغفر لكم ذنوبكم والله غفور رحيم","dt":"[31] قل -ايها الرسول-: ان كنتم تحبون الله حقا فاتبعوني وامنوا بي ظاهرا وباطنا، يحببكم الله، ويمح ذنوبكم، فانه غفور لذنوب عباده المؤمنين، رحيم بهم. وهذه الايه الكريمه حاكمه على كل من ادعى محبه الله -تعالى- وليس متبعا لنبيه محمد -صلى الله عليه وسلم- حق الاتباع، مطيعا له في امره ونهيه، فانه كاذب في دعواه حتى يتابع الرسول -صلى الله عليه وسلم- حق الاتباع."},{"id":"325","s":3,"a":32,"at":"قل اطيعوا الله والرسول فان تولوا فان الله لا يحب الكافرين","dt":"[32] قل -ايها الرسول-: اطيعوا الله باتباع كتابه، واطيعوا الرسول باتباع سنته في حياته وبعد مماته، فان هم اعرضوا عنك، واصروا على ما هم عليه من كفر وضلال، فليسوا اهلا لمحبه الله؛ فان الله لا يحب الكافرين."},{"id":"326","s":3,"a":33,"at":"ان الله اصطفى ادم ونوحا وال ابراهيم وال عمران على العالمين","dt":"[33] ان الله اختار ادم ونوحا وال ابراهيم وال عمران، وجعلهم افضل اهل زمانهم."},{"id":"327","s":3,"a":34,"at":"ذريه بعضها من بعض والله سميع عليم","dt":"[34] هؤلاء الانبياء والرسل سلسله طهر متواصله في الاخلاص لله وتوحيده والعمل بوحيه. والله سميع لاقوال عباده، عليم بافعالهم، وسيجازيهم على ذلك."},{"id":"328","s":3,"a":35,"at":"اذ قالت امراه عمران رب اني نذرت لك ما في بطني محررا فتقبل مني انك انت السميع العليم","dt":"[35] اذكر -ايها الرسول- ما كان من امر مريم وامها وابنها عيسى عليه السلام؛ لترد بذلك على من ادعوا الوهيه عيسى او بنوته لله سبحانه، اذ قالت امراه عمران حين حملت: يا رب اني جعلت لك ما في بطني خالصا لك، لخدمه «بيت المقدس»، فتقبل مني، انك انت وحدك السميع لدعائي، العليم بنيتي."},{"id":"329","s":3,"a":36,"at":"فلما وضعتها قالت رب اني وضعتها انثى والله اعلم بما وضعت وليس الذكر كالانثى واني سميتها مريم واني اعيذها بك وذريتها من الشيطان الرجيم","dt":"[36] فلما تم حملها ووضعت مولودها قالت: رب اني وضعتها انثى لا تصلح للخدمه في «بيت المقدس» -والله اعلم بما وضعت، وسوف يجعل الله لها شانا- وقالت: وليس الذكر الذي اردت للخدمه كالانثى في ذلك؛ لان الذكر اقوى على الخدمه واقوم بها، واني سميتها مريم، واني حصنتها بك هي وذريتها من الشيطان المطرود من رحمتك."},{"id":"330","s":3,"a":37,"at":"فتقبلها ربها بقبول حسن وانبتها نباتا حسنا وكفلها زكريا كلما دخل عليها زكريا المحراب وجد عندها رزقا قال يامريم انى لك هذا قالت هو من عند الله ان الله يرزق من يشاء بغير حساب","dt":"[37] فاستجاب الله دعاءها وقبل منها نذرها احسن قبول، وتولى ابنتها مريم بالرعايه فانبتها نباتا حسنا، ويسر الله لها زكريا عليه السلام كافلا، فاسكنها في مكان عبادته، وكان كلما دخل عليها هذا المكان وجد عندها رزقا هنيئا معدا قال: يا مريم من اين لك هذا الرزق الطيب؟ قالت: هو رزق من عند الله. ان الله -بفضله- يرزق من يشاء من خلقه بغير حساب."},{"id":"331","s":3,"a":38,"at":"هنالك دعا زكريا ربه قال رب هب لي من لدنك ذريه طيبه انك سميع الدعاء","dt":"[38] عندما راى زكريا ما اكرم الله به مريم من رزقه وفضله توجه الى ربه قائلا: يا رب اعطني من عندك ولدا صالحا مباركا، انك سميع الدعاء لمن دعاك."},{"id":"332","s":3,"a":39,"at":"فنادته الملائكه وهو قائم يصلي في المحراب ان الله يبشرك بيحيى مصدقا بكلمه من الله وسيدا وحصورا ونبيا من الصالحين","dt":"[39] فنادته الملائكه وهو واقف بين يدي الله في مكان صلاته يدعوه: ان الله يخبرك بخبر يسرك، وهو انك سترزق بولد اسمه يحيى، يصدق بكلمه من الله -وهو عيسى بن مريم عليه السلام-، ويكون يحيى سيدا في قومه، له المكانه والمنزله العاليه، وحصورا لا ياتي الذنوب والشهوات الضاره، ويكون نبيا من الصالحين الذين بلغوا في الصلاح ذروته ."},{"id":"333","s":3,"a":40,"at":"قال رب انى يكون لي غلام وقد بلغني الكبر وامراتي عاقر قال كذلك الله يفعل ما يشاء","dt":"[40] قال زكريا فرحا متعجبا: رب انى يكون لي غلام مع ان الشيخوخه قد بلغت مني مبلغها، وامراتي عقيم لا تلد؟ قال: كذلك يفعل الله ما يشاء من الافعال العجيبه المخالفه للعاده."},{"id":"334","s":3,"a":41,"at":"قال رب اجعل لي ايه قال ايتك الا تكلم الناس ثلاثه ايام الا رمزا واذكر ربك كثيرا وسبح بالعشي والابكار","dt":"[41] قال زكريا: رب اجعل لي علامه استدل بها على وجود الولد مني؛ ليحصل لي السرور والاستبشار، قال: علامتك التي طلبتها: الا تستطيع التحدث الى الناس ثلاثه ايام الا باشاره اليهم، مع انك سوي صحيح، وفي هذه المده اكثر من ذكر ربك، وصل له اواخر النهار واوائله."},{"id":"335","s":3,"a":42,"at":"واذ قالت الملائكه يامريم ان الله اصطفاك وطهرك واصطفاك على نساء العالمين","dt":"[42] واذكر -ايها الرسول- حين قالت الملائكه: يا مريم ان الله اختارك لطاعته وطهرك من الاخلاق الرذيله، واختارك على نساء العالمين في زمانك."},{"id":"336","s":3,"a":43,"at":"يامريم اقنتي لربك واسجدي واركعي مع الراكعين","dt":"[43] يا مريم داومي على الطاعه لربك، وقومي في خشوع وتواضع، واسجدي واركعي مع الراكعين؛ شكرا لله على ما اولاك من نعمه."},{"id":"337","s":3,"a":44,"at":"ذلك من انباء الغيب نوحيه اليك وما كنت لديهم اذ يلقون اقلامهم ايهم يكفل مريم وما كنت لديهم اذ يختصمون","dt":"[44] ذلك الذي قصصناه عليك -ايها الرسول- من اخبار الغيب التي اوحاها الله اليك، اذ لم تكن معهم حين اختلفوا في كفاله مريم ايهم احق بها واولى، ووقع بينهم الخصام، فاجروا القرعه بالقاء اقلامهم، فاصابت زكريا عليه السلام، ففاز بكفالتها."},{"id":"338","s":3,"a":45,"at":"اذ قالت الملائكه يامريم ان الله يبشرك بكلمه منه اسمه المسيح عيسى ابن مريم وجيها في الدنيا والاخره ومن المقربين","dt":"[45] وما كنت -يا نبي الله- هناك حين قالت الملائكه: يا مريم ان الله يبشرك بولد يكون وجوده بكلمه من الله، اي يقول له: «كن»، فيكون، اسمه المسيح عيسى بن مريم، له الجاه العظيم في الدنيا والاخره، ومن المقربين عند الله يوم القيامه."},{"id":"339","s":3,"a":46,"at":"ويكلم الناس في المهد وكهلا ومن الصالحين","dt":"[46] ويكلم الناس وهو رضيع قبل اوان الكلام، ويدعوهم الى الله وهو كبير قد اجتمعت قوته وكمل شبابه بما اوحاه الله اليه. وهذا تكليم النبوه والدعوه والارشاد، وهو معدود من اهل الصلاح والفضل في قوله وعمله."},{"id":"340","s":3,"a":47,"at":"قالت رب انى يكون لي ولد ولم يمسسني بشر قال كذلك الله يخلق ما يشاء اذا قضى امرا فانما يقول له كن فيكون","dt":"[47] قالت مريم متعجبه من هذا الامر: انى يكون لي ولد وانا لست بذات زوج ولا بغي؟ قال لها الملك: هذا الذي يحدث لك ليس بمستبعد على الاله القادر، الذي يوجد ما يشاء من العدم، فاذا اراد ايجاد شيء فانما يقول له: «كن» فيكون."},{"id":"341","s":3,"a":48,"at":"ويعلمه الكتاب والحكمه والتوراه والانجيل","dt":"[48] ويعلمه الكتابه، والسداد في القول والفعل، والتوراه التي اوحاها الله الى موسى عليه السلام، والانجيل الذي انزل الله عليه."},{"id":"342","s":3,"a":49,"at":"ورسولا الى بني اسرائيل اني قد جئتكم بايه من ربكم اني اخلق لكم من الطين كهيئه الطير فانفخ فيه فيكون طيرا باذن الله وابرئ الاكمه والابرص واحي الموتى باذن الله وانبئكم بما تاكلون وما تدخرون في بيوتكم ان في ذلك لايه لكم ان كنتم مؤمنين","dt":"[49] ويجعله رسولا الى بني اسرائيل، ويقول لهم: اني قد جئتكم بعلامه من ربكم تدل على اني مرسل من الله، وهي اني اصنع لكم من الطين مثل شكل الطير، فانفخ فيه فيكون طيرا حقيقيا باذن الله، واشفي من ولد اعمى، ومن به برص، واحيي من كان ميتا باذن الله، واخبركم بما تاكلون وتدخرون في بيوتكم من طعامكم. ان في هذه الامور العظيمه التي ليست في قدره البشر لدليلا على اني نبي الله ورسوله، ان كنتم مصدقين حجج الله واياته، مقرين بتوحيده."},{"id":"343","s":3,"a":50,"at":"ومصدقا لما بين يدي من التوراه ولاحل لكم بعض الذي حرم عليكم وجئتكم بايه من ربكم فاتقوا الله واطيعون","dt":"[50] وجئتكم مصدقا بما في التوراه، ولاحل لكم بوحي من الله بعض ما حرمه الله عليكم تخفيفا من الله ورحمه، وجئتكم بحجه من ربكم على صدق ما اقول لكم، فاتقوا الله ولا تخالفوا امره، واطيعوني فيما ابلغكم به عن الله."},{"id":"344","s":3,"a":51,"at":"ان الله ربي وربكم فاعبدوه هذا صراط مستقيم","dt":"[51] ان الله الذي ادعوكم اليه هو وحده ربي وربكم فاعبدوه، فانا وانتم سواء في العبوديه والخضوع له، وهذا هو الطريق الذي لا اعوجاج فيه."},{"id":"345","s":3,"a":52,"at":"فلما احس عيسى منهم الكفر قال من انصاري الى الله قال الحواريون نحن انصار الله امنا بالله واشهد بانا مسلمون","dt":"[52] فلما استشعر عيسى منهم التصميم على الكفر نادى في اصحابه الخلص: من يكون معي في نصره دين الله؟ قال اصفياء عيسى: نحن انصار دين الله والداعون اليه، صدقنا بالله واتبعناك، واشهد انت يا عيسى بانا مستسلمون لله بالتوحيد والطاعه."},{"id":"346","s":3,"a":53,"at":"ربنا امنا بما انزلت واتبعنا الرسول فاكتبنا مع الشاهدين","dt":"[53] ربنا صدقنا بما انزلت من الانجيل، واتبعنا رسولك عيسى عليه السلام، فاجعلنا ممن شهدوا لك بالوحدانيه ولانبيائك بالرساله، وهم امه محمد -صلى الله عليه وسلم- الذين يشهدون للرسل بانهم بلغوا اممهم."},{"id":"347","s":3,"a":54,"at":"ومكروا ومكر الله والله خير الماكرين","dt":"[54] ومكر الذين كفروا من بني اسرائيل بعيسى عليه السلام، بان وكلوا به من يقتله غيله، فالقى الله شبه عيسى على رجل دلهم عليه فامسكوا به، وقتلوه وصلبوه ظنا منهم انه عيسى عليه السلام، والله خير الماكرين. وفي هذا اثبات صفه المكر لله -تعالى- على ما يليق بجلاله وكماله؛ لانه مكر بحق، وفي مقابله مكر الماكرين."},{"id":"348","s":3,"a":55,"at":"اذ قال الله ياعيسى اني متوفيك ورافعك الي ومطهرك من الذين كفروا وجاعل الذين اتبعوك فوق الذين كفروا الى يوم القيامه ثم الي مرجعكم فاحكم بينكم فيما كنتم فيه تختلفون","dt":"[55] ومكر الله بهم حين قال الله لعيسى: اني قابضك من الارض من غير ان ينالك سوء، ورافعك الي ببدنك وروحك، ومخلصك من الذين كفروا بك، وجاعل الذين اتبعوك -اي: على دينك وما جئت به عن الله من الدين والبشاره بمحمد -صلى الله عليه وسلم- وامنوا بمحمد -صلى الله عليه وسلم-، بعد بعثته، والتزموا شريعته- ظاهرين على الذين جحدوا نبوتك الى يوم القيامه، ثم الي مصيركم جميعا يوم الحساب، فافصل بينكم فيما كنتم فيه تختلفون من امر عيسى عليه السلام."},{"id":"349","s":3,"a":56,"at":"فاما الذين كفروا فاعذبهم عذابا شديدا في الدنيا والاخره وما لهم من ناصرين","dt":"[56] فاما الذين كفروا بالمسيح من اليهود او غلوا فيه من النصارى، فاعذبهم عذابا شديدا في الدنيا: بالقتل وسلب الاموال وازاله الملك، وفي الاخره بالنار، ومالهم من ناصر ينصرهم ويدفع عنهم عذاب الله."},{"id":"350","s":3,"a":57,"at":"واما الذين امنوا وعملوا الصالحات فيوفيهم اجورهم والله لا يحب الظالمين","dt":"[57] واما الذين امنوا بالله ورسله وعملوا الاعمال الصالحه، فيعطيهم الله ثواب اعمالهم كاملا غير منقوص. والله لا يحب الظالمين بالشرك والكفر."},{"id":"351","s":3,"a":58,"at":"ذلك نتلوه عليك من الايات والذكر الحكيم","dt":"[58] ذلك الذي نقصه عليك في شان عيسى، من الدلائل الواضحه على صحه رسالتك، وصحه القران الحكيم الذي يفصل بين الحق والباطل، فلا شك فيه ولا امتراء."},{"id":"352","s":3,"a":59,"at":"ان مثل عيسى عند الله كمثل ادم خلقه من تراب ثم قال له كن فيكون","dt":"[59] ان خلق الله لعيسى من غير اب مثله كمثل خلق الله لادم من غير اب ولا ام؛ اذ خلقه من تراب الارض، ثم قال له: «كن بشرا» فكان. فدعوى الهيه عيسى لكونه خلق من غير اب دعوى باطله؛ فادم عليه السلام خلق من غير اب ولا ام، واتفق الجميع على انه عبد من عباد الله."},{"id":"353","s":3,"a":60,"at":"الحق من ربك فلا تكن من الممترين","dt":"[60] الحق الذي لا شك فيه في امر عيسى هو الذي جاءك -ايها الرسول- من ربك، فدم على يقينك، وعلى ما انت عليه من ترك الافتراء، ولا تكن من الشاكين. وفي هذا تثبيت وطمانه لرسول الله -صلى الله عليه وسلم-."},{"id":"354","s":3,"a":61,"at":"فمن حاجك فيه من بعد ما جاءك من العلم فقل تعالوا ندع ابناءنا وابناءكم ونساءنا ونساءكم وانفسنا وانفسكم ثم نبتهل فنجعل لعنه الله على الكاذبين","dt":"[61] فمن جادلك -ايها الرسول- في المسيح عيسى بن مريم، من بعد ما جاءك من العلم في امر عيسى عليه السلام، فقل لهم: تعالوا نحضر ابناءنا وابناءكم، ونساءنا ونساءكم، وانفسنا وانفسكم، ثم نتجه الى الله بالدعاء ان ينزل عقوبته ولعنته على الكاذبين في قولهم، المصرين على عنادهم."},{"id":"355","s":3,"a":62,"at":"ان هذا لهو القصص الحق وما من اله الا الله وان الله لهو العزيز الحكيم","dt":"[62] ان هذا الذي انباتك به -ايها الرسول- من امر عيسى لهو النبا الحق الذي لا شك فيه، وما من معبود يستحق العباده الا الله وحده، وان الله لهو العزيز في ملكه، الحكيم في تدبيره وفعله."},{"id":"356","s":3,"a":63,"at":"فان تولوا فان الله عليم بالمفسدين","dt":"[63] فان اعرضوا عن تصديقك واتباعك فهم المفسدون، والله عليم بهم، وسيجازيهم على ذلك."},{"id":"357","s":3,"a":64,"at":"قل يااهل الكتاب تعالوا الى كلمه سواء بيننا وبينكم الا نعبد الا الله ولا نشرك به شيئا ولا يتخذ بعضنا بعضا اربابا من دون الله فان تولوا فقولوا اشهدوا بانا مسلمون","dt":"[64] قل -ايها الرسول- لاهل الكتاب من اليهود والنصارى: تعالوا الى كلمه عدل وحق نلتزم بها جميعا: وهي ان نخص الله وحده بالعباده، ولا نتخذ اي شريك معه، من وثن او صنم او صليب او طاغوت او غير ذلك، ولا يدين بعضنا لبعض بالطاعه من دون الله. فان اعرضوا عن هذه الدعوه الطيبه فقولوا لهم -ايها المؤمنون-: اشهدوا علينا بانا مسلمون منقادون لربنا بالعبوديه والاخلاص. والدعوه الى كلمه سواء، كما توجه الى اليهود والنصارى، توجه الى من جرى مجراهم."},{"id":"358","s":3,"a":65,"at":"يااهل الكتاب لم تحاجون في ابراهيم وما انزلت التوراه والانجيل الا من بعده افلا تعقلون","dt":"[65] يا اصحاب الكتب المنزله، من اليهود والنصارى، كيف يجادل كل منكم في ان ابراهيم عليه السلام كان على ملته، وما انزلت التوراه والانجيل الا من بعده؟ افلا تفقهون خطا قولكم: ان ابراهيم كان يهوديا او نصرانيا، وقد علمتم ان اليهوديه والنصرانيه حدثت بعد وفاته بحين؟"},{"id":"359","s":3,"a":66,"at":"ها انتم هؤلاء حاججتم فيما لكم به علم فلم تحاجون فيما ليس لكم به علم والله يعلم وانتم لا تعلمون","dt":"[66] ها انتم يا هؤلاء جادلتم رسول الله محمدا -صلى الله عليه وسلم- فيما لكم به علم من امر دينكم، مما تعتقدون صحته في كتبكم، فلم تجادلون فيما ليس لكم به علم من امر ابراهيم؟ والله يعلم الامور على خفائها، وانتم لا تعلمون."},{"id":"360","s":3,"a":67,"at":"ما كان ابراهيم يهوديا ولا نصرانيا ولكن كان حنيفا مسلما وما كان من المشركين","dt":"[67] ما كان ابراهيم يهوديا ولا نصرانيا، فلم تكن اليهوديه ولا النصرانيه الا من بعده، ولكن كان متبعا لامر الله وطاعته، مستسلما لربه، وما كان من المشركين."},{"id":"361","s":3,"a":68,"at":"ان اولى الناس بابراهيم للذين اتبعوه وهذا النبي والذين امنوا والله ولي المؤمنين","dt":"[68] ان احق الناس بابراهيم واخصهم به، الذين امنوا به وصدقوا برسالته واتبعوه على دينه، وهذا النبي محمد -صلى الله عليه وسلم- والذين امنوا به. والله ولي المؤمنين به المتبعين شرعه."},{"id":"362","s":3,"a":69,"at":"ودت طائفه من اهل الكتاب لو يضلونكم وما يضلون الا انفسهم وما يشعرون","dt":"[69] تمنت جماعه من اليهود والنصارى لو يضلونكم -ايها المسلمون- عن الاسلام، وما يضلون الا انفسهم واتباعهم، وما يدرون ذلك ولا يعلمونه."},{"id":"363","s":3,"a":70,"at":"يااهل الكتاب لم تكفرون بايات الله وانتم تشهدون","dt":"[70] يا اهل التوراه والانجيل لم تجحدون ايات الله التي انزلها على رسله في كتبكم، وفيها ان محمدا -صلى الله عليه وسلم- هو الرسول المنتظر، وان ما جاءكم به هو الحق، وانتم تشهدون بذلك؟ ولكنكم تنكرونه."},{"id":"364","s":3,"a":71,"at":"يااهل الكتاب لم تلبسون الحق بالباطل وتكتمون الحق وانتم تعلمون","dt":"[71] يا اهل التوراه والانجيل لم تخلطون الحق في كتبكم بما حرفتموه وكتبتموه من الباطل بايديكم، وتخفون ما فيهما من صفه محمد -صلى الله عليه وسلم-، وان دينه هو الحق، وانتم تعلمون ذلك؟"},{"id":"365","s":3,"a":72,"at":"وقالت طائفه من اهل الكتاب امنوا بالذي انزل على الذين امنوا وجه النهار واكفروا اخره لعلهم يرجعون","dt":"[72] وقالت جماعه من اهل الكتاب من اليهود: صدقوا بالذي انزل على الذين امنوا اول النهار واكفروا اخره؛ لعلهم يتشككون في دينهم، ويرجعون عنه."},{"id":"366","s":3,"a":73,"at":"ولا تؤمنوا الا لمن تبع دينكم قل ان الهدى هدى الله ان يؤتى احد مثل ما اوتيتم او يحاجوكم عند ربكم قل ان الفضل بيد الله يؤتيه من يشاء والله واسع عليم","dt":"[73] ولا تصدقوا تصديقا صحيحا الا لمن تبع دينكم فكان يهوديا، قل لهم -ايها الرسول-: ان الهدى والتوفيق هدى الله وتوفيقه للايمان الصحيح. وقالوا: لا تظهروا ما عندكم من العلم للمسلمين فيتعلموه منكم فيساووكم في العلم به، وتكون لهم الافضليه عليكم، او ان يتخذوه حجه عند ربكم يغلبونكم بها. قل لهم -ايها الرسول-: ان الفضل والعطاء والامور كلها بيد الله وتحت تصرفه، يؤتيها من يشاء ممن امن به وبرسوله. والله واسع عليم، يسع بعلمه وعطائه جميع مخلوقاته، ممن يستحق فضله ونعمه."},{"id":"367","s":3,"a":74,"at":"يختص برحمته من يشاء والله ذو الفضل العظيم","dt":"[74] ان الله يختص من خلقه من يشاء بالنبوه والهدايه الى اكمل الشرائع. والله ذو الاحسان والعطاء الكثير الواسع."},{"id":"368","s":3,"a":75,"at":"ومن اهل الكتاب من ان تامنه بقنطار يؤده اليك ومنهم من ان تامنه بدينار لا يؤده اليك الا ما دمت عليه قائما ذلك بانهم قالوا ليس علينا في الاميين سبيل ويقولون على الله الكذب وهم يعلمون","dt":"[75] ومن اهل الكتاب من اليهود من ان تامنه على كثير من المال يؤده اليك من غير خيانه، ومنهم من ان تامنه على دينار واحد لا يؤده اليك، الا اذا بذلت غايه الجهد في مطالبته. وسبب ذلك عقيده فاسده تجعلهم يستحلون اموال العرب بالباطل، ويقولون: ليس علينا في اكل اموالهم اثم ولا حرج؛ لان الله احلها لنا. وهذا كذب على الله، يقولونه بالسنتهم، وهم يعلمون انهم كاذبون."},{"id":"369","s":3,"a":76,"at":"بلى من اوفى بعهده واتقى فان الله يحب المتقين","dt":"[76] ليس الامر كما زعم هؤلاء الكاذبون، فان المتقي حقا هو من اوفى بما عاهد الله عليه من اداء الامانه والايمان به وبرسله والتزم هديه وشرعه، وخاف الله عز وجل فامتثل امره وانتهى عما نهى عنه. والله يحب المتقين الذين يتقون الشرك والمعاصي."},{"id":"370","s":3,"a":77,"at":"ان الذين يشترون بعهد الله وايمانهم ثمنا قليلا اولئك لا خلاق لهم في الاخره ولا يكلمهم الله ولا ينظر اليهم يوم القيامه ولا يزكيهم ولهم عذاب اليم","dt":"[77] ان الذين يستبدلون بعهد الله ووصيته التي اوصى بها في الكتب التي انزلها على انبيائهم، عوضا وبدلا خسيسا من عرض الدنيا وحطامها، اولئك لا نصيب لهم من الثواب في الاخره، ولا يكلمهم الله بما يسرهم، ولا ينظر اليهم يوم القيامه بعين الرحمه، ولا يطهرهم من دنس الذنوب والكفر، ولهم عذاب موجع."},{"id":"371","s":3,"a":78,"at":"وان منهم لفريقا يلوون السنتهم بالكتاب لتحسبوه من الكتاب وما هو من الكتاب ويقولون هو من عند الله وما هو من عند الله ويقولون على الله الكذب وهم يعلمون","dt":"[78] وان من اليهود لجماعه يحرفون الكلام عن مواضعه، ويبدلون كلام الله؛ ليوهموا غيرهم ان هذا من الكلام المنزل، وهو التوراه، وما هو منها في شيء، ويقولون: هذا من عند الله اوحاه الله الى نبيه موسى، وما هو من عند الله، وهم لاجل دنياهم يقولون على الله الكذب، وهم يعلمون انهم كاذبون."},{"id":"372","s":3,"a":79,"at":"ما كان لبشر ان يؤتيه الله الكتاب والحكم والنبوه ثم يقول للناس كونوا عبادا لي من دون الله ولكن كونوا ربانيين بما كنتم تعلمون الكتاب وبما كنتم تدرسون","dt":"[79] ما ينبغي لاحد من البشر ان ينزل الله عليه كتابه ويجعله حكما بين خلقه ويختاره نبيا، ثم يقول للناس: اعبدوني من دون الله، ولكن يقول: كونوا حكماء فقهاء علماء بما كنتم تعلمونه غيركم من وحي الله تعالى، وبما تدرسونه منه حفظا وعلما وفقها."},{"id":"373","s":3,"a":80,"at":"ولا يامركم ان تتخذوا الملائكه والنبيين اربابا ايامركم بالكفر بعد اذ انتم مسلمون","dt":"[80] وما كان لاحد منهم ان يامركم باتخاذ الملائكه والنبيين اربابا تعبدونهم من دون الله. ايعقل -ايها الناس- ان يامركم بالكفر بالله بعد انقيادكم لامره؟"},{"id":"374","s":3,"a":81,"at":"واذ اخذ الله ميثاق النبيين لما اتيتكم من كتاب وحكمه ثم جاءكم رسول مصدق لما معكم لتؤمنن به ولتنصرنه قال ااقررتم واخذتم على ذلكم اصري قالوا اقررنا قال فاشهدوا وانا معكم من الشاهدين","dt":"[81] واذكر -ايها الرسول- اذ اخذ الله سبحانه العهد المؤكد على جميع الانبياء: لئن اتيتكم من كتاب وحكمه، ثم جاءكم رسول من عندي، مصدق لما معكم لتؤمنن به ولتنصرنه. فهل اقررتم واعترفتم بذلك واخذتم على ذلك عهدي الموثق؟ قالوا: اقررنا بذلك، قال: فليشهد بعضكم على بعض، واشهدوا على اممكم بذلك، وانا معكم من الشاهدين عليكم وعليهم. وفي هذا ان الله اخذ الميثاق على كل نبي ان يؤمن بمحمد -صلى الله عليه وسلم-، واخذ الميثاق على امم الانبياء بذلك."},{"id":"375","s":3,"a":82,"at":"فمن تولى بعد ذلك فاولئك هم الفاسقون","dt":"[82] فمن اعرض عن دعوه الاسلام بعد هذا البيان وهذا العهد الذي اخذه الله على انبيائه، فاولئك هم الخارجون عن دين الله وطاعه ربهم."},{"id":"376","s":3,"a":83,"at":"افغير دين الله يبغون وله اسلم من في السموات والارض طوعا وكرها واليه يرجعون","dt":"[83] ايريد هؤلاء الفاسقون من اهل الكتاب غير دين الله -وهو الاسلام الذي بعث الله به محمدا -صلى الله عليه وسلم--، مع ان كل من في السموات والارض استسلم وانقاد وخضع لله طواعيه -كالمؤمنين- ورغما عنهم عند الشدائد، حين لا ينفعهم ذلك وهم الكفار، كما خضع له سائر الكائنات، واليه يرجعون يوم المعاد، فيجازي كلا بعمله. وهذا تحذير من الله تعالى لخلقه ان يرجع اليه احد منهم على غير مله الاسلام."},{"id":"377","s":3,"a":84,"at":"قل امنا بالله وما انزل علينا وما انزل على ابراهيم واسماعيل واسحاق ويعقوب والاسباط وما اوتي موسى وعيسى والنبيون من ربهم لا نفرق بين احد منهم ونحن له مسلمون","dt":"[84] قل لهم -ايها الرسول-: صدقنا بالله واطعنا، فلا رب لنا غيره، ولا معبود لنا سواه، وامنا بالوحي الذي انزله الله علينا، والذي انزله على ابراهيم خليل الله، وابنيه اسماعيل واسحاق، وابن ابنه يعقوب بن اسحاق، والذي انزله على الاسباط -وهم الانبياء من ولد يعقوب، الذين كانوا في قبائل بني اسرائيل الاثنتي عشره - وما اوتي موسى وعيسى من التوراه والانجيل، وما انزله الله على انبيائه، نؤمن بذلك كله، ولا نفرق بين احد منهم، ونحن لله وحده منقادون بالطاعه، مقرون له بالربوبيه والالوهيه والعباده."},{"id":"378","s":3,"a":85,"at":"ومن يبتغ غير الاسلام دينا فلن يقبل منه وهو في الاخره من الخاسرين","dt":"[85] ومن يطلب دينا غير دين الاسلام الذي هو الاستسلام لله بالتوحيد والانقياد له بالطاعه، والعبوديه، ولرسوله النبي الخاتم محمد -صلى الله عليه وسلم- بالايمان به وبمتابعته ومحبته ظاهرا وباطنا، فلن يقبل منه ذلك، وهو في الاخره من الخاسرين الذين بخسوا انفسهم حظوظها."},{"id":"379","s":3,"a":86,"at":"كيف يهدي الله قوما كفروا بعد ايمانهم وشهدوا ان الرسول حق وجاءهم البينات والله لا يهدي القوم الظالمين","dt":"[86] كيف يوفق الله للايمان به وبرسوله قوما جحدوا نبوه محمد -صلى الله عليه وسلم- بعد ايمانهم به، وشهدوا ان محمدا -صلى الله عليه وسلم- حق وما جاء به هو الحق، وجاءهم الحجج من عند الله والدلائل بصحه ذلك؟ والله لا يوفق للحق والصواب الذين عدلوا عن الحق الى الباطل، فاختاروا الكفر على الايمان."},{"id":"380","s":3,"a":87,"at":"اولئك جزاؤهم ان عليهم لعنه الله والملائكه والناس اجمعين","dt":"[87] اولئك الظالمون جزاؤهم ان عليهم لعنه الله والملائكه والناس اجمعين، فهم مطرودون من رحمه الله."},{"id":"381","s":3,"a":88,"at":"خالدين فيها لا يخفف عنهم العذاب ولا هم ينظرون","dt":"[88] ماكثين في النار، لا يرفع عنهم العذاب قليلا ليستريحوا، ولا يؤخر عنهم لمعذره يعتذرون بها."},{"id":"382","s":3,"a":89,"at":"الا الذين تابوا من بعد ذلك واصلحوا فان الله غفور رحيم","dt":"[89] الا الذين رجعوا الى ربهم بالتوبه النصوح من بعد كفرهم وظلمهم، واصلحوا ما افسدوه بتوبتهم فان الله يقبلها، فهو غفور لذنوب عباده، رحيم بهم."},{"id":"383","s":3,"a":90,"at":"ان الذين كفروا بعد ايمانهم ثم ازدادوا كفرا لن تقبل توبتهم واولئك هم الضالون","dt":"[90] ان الذين كفروا بعد ايمانهم واستمروا على الكفر الى الممات لن تقبل لهم توبه عند حضور الموت، واولئك هم الذين ضلوا السبيل، فاخطؤوا منهجه."},{"id":"384","s":3,"a":91,"at":"ان الذين كفروا وماتوا وهم كفار فلن يقبل من احدهم ملء الارض ذهبا ولو افتدى به اولئك لهم عذاب اليم وما لهم من ناصرين","dt":"[91] ان الذين جحدوا نبوه محمد -صلى الله عليه وسلم-، وماتوا على الكفر بالله ورسوله، فلن يقبل من احدهم يوم القيامه ملء الارض ذهبا؛ ليفتدي به نفسه من عذاب الله، ولو افتدى به نفسه فعلا. اولئك لهم عذاب موجع، وما لهم من احد ينقذهم من عذاب الله."},{"id":"385","s":3,"a":92,"at":"لن تنالوا البر حتى تنفقوا مما تحبون وما تنفقوا من شيء فان الله به عليم","dt":"[92] لن تدركوا الجنه حتى تتصدقوا مما تحبون، واي شيء تتصدقوا به مهما كان قليلا او كثيرا فان الله به عليم، وسيجازي كل منفق بحسب عمله."},{"id":"386","s":3,"a":93,"at":"كل الطعام كان حلا لبني اسرائيل الا ما حرم اسرائيل على نفسه من قبل ان تنزل التوراه قل فاتوا بالتوراه فاتلوها ان كنتم صادقين","dt":"[93] كل الاطعمه الطيبه كانت حلالا لابناء يعقوب عليه السلام الا ما حرم يعقوب على نفسه لمرض نزل به، وذلك من قبل ان تنزل التوراه. فلما نزلت التوراه حرم الله على بني اسرائيل بعض الاطعمه التي كانت حلالا لهم؛ وذلك لظلمهم وبغيهم. قل لهم -ايها الرسول-: هاتوا التوراه، واقرؤوا ما فيها ان كنتم محقين في دعواكم ان الله انزل فيها تحريم ما حرمه يعقوب على نفسه، حتى تعلموا صدق ما جاء في القران من ان الله لم يحرم على بني اسرائيل شيئا من قبل نزول التوراه، الا ما حرمه يعقوب على نفسه."},{"id":"387","s":3,"a":94,"at":"فمن افترى على الله الكذب من بعد ذلك فاولئك هم الظالمون","dt":"[94] فمن كذب على الله من بعد قراءه التوراه ووضوح الحقيقه، فاولئك هم الظالمون القائلون على الله بالباطل."},{"id":"388","s":3,"a":95,"at":"قل صدق الله فاتبعوا مله ابراهيم حنيفا وما كان من المشركين","dt":"[95] قل لهم -ايها الرسول- صدق الله فيما اخبر به وفيما شرعه. فان كنتم صادقين في محبتكم وانتسابكم لخليل الله ابراهيم عليه السلام، فاتبعوا ملته التي شرعها الله على لسان محمد -صلى الله عليه وسلم-، فانها الحق الذي لا شك فيه. وما كان ابراهيم عليه السلام من المشركين بالله في توحيده وعبادته احدا."},{"id":"389","s":3,"a":96,"at":"ان اول بيت وضع للناس للذي ببكه مباركا وهدى للعالمين","dt":"[96] ان اول بيت بني لعباده الله في الارض لهو بيت الله الحرام الذي في «مكه»، وهذا البيت مبارك تضاعف فيه الحسنات، وتتنزل فيه الرحمات، وفي استقباله في الصلاه، وقصده لاداء الحج والعمره، صلاح وهدايه للناس اجمعين."},{"id":"390","s":3,"a":97,"at":"فيه ايات بينات مقام ابراهيم ومن دخله كان امنا ولله على الناس حج البيت من استطاع اليه سبيلا ومن كفر فان الله غني عن العالمين","dt":"[97] في هذا البيت دلالات ظاهرات انه من بناء ابراهيم، وان الله عظمه وشرفه، منها: مقام ابراهيم عليه السلام، وهو الحجر الذي كان يقف عليه حين كان يرفع القواعد من البيت هو وابنه اسماعيل، ومن دخل هذا البيت امن على نفسه فلا يناله احد بسوء. وقد اوجب الله على المستطيع من الناس في اي مكان قصد هذا البيت لاداء مناسك الحج. ومن جحد فريضه الحج فقد كفر، والله غني عنه وعن حجه وعمله، وعن سائر خلقه."},{"id":"391","s":3,"a":98,"at":"قل يااهل الكتاب لم تكفرون بايات الله والله شهيد على ما تعملون","dt":"[98] قل -ايها الرسول- لاهل الكتاب من اليهود والنصارى: لم تجحدون حجج الله التي دلت على ان دين الله هو الاسلام، وتنكرون ما في كتبكم من دلائل وبراهين على ذلك، وانتم تعلمون ؟ والله شهيد على صنيعكم. وفي ذلك تهديد ووعيد لهم."},{"id":"392","s":3,"a":99,"at":"قل يااهل الكتاب لم تصدون عن سبيل الله من امن تبغونها عوجا وانتم شهداء وما الله بغافل عما تعملون","dt":"[99] قل -ايها الرسول- لليهود والنصارى: لم تمنعون من الاسلام من يريد الدخول فيه تطلبون له زيغا وميلا عن القصد والاستقامه، وانتم تعلمون ان ما جئت به هو الحق؟ وما الله بغافل عما تعملون، وسوف يجازيكم على ذلك."},{"id":"393","s":3,"a":100,"at":"ياايها الذين امنوا ان تطيعوا فريقا من الذين اوتوا الكتاب يردوكم بعد ايمانكم كافرين","dt":"[100] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، ان تطيعوا جماعه من اليهود والنصارى ممن اتاهم الله التوراه والانجيل، يضلوكم، ويلقوا اليكم الشبه في دينكم؛ لترجعوا جاحدين للحق بعد ان كنتم مؤمنين به، فلا تامنوهم على دينكم، ولا تقبلوا لهم رايا او مشوره."},{"id":"394","s":3,"a":101,"at":"وكيف تكفرون وانتم تتلى عليكم ايات الله وفيكم رسوله ومن يعتصم بالله فقد هدي الى صراط مستقيم","dt":"[101] وكيف تكفرون بالله -ايها المؤمنون- وايات القران تتلى عليكم، وفيكم رسول الله محمد -صلى الله عليه وسلم- يبلغها لكم؟ ومن يتوكل على الله ويستمسك بالقران والسنه فقد وفق لطريق واضح، ومنهاج مستقيم."},{"id":"395","s":3,"a":102,"at":"ياايها الذين امنوا اتقوا الله حق تقاته ولا تموتن الا وانتم مسلمون","dt":"[102] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، خافوا الله حق خوفه: وذلك بان يطاع فلا يعصى، ويشكر فلا يكفر، ويذكر فلا ينسى، وداوموا على تمسككم باسلامكم الى اخر حياتكم؛ لتلقوا الله وانتم عليه."},{"id":"396","s":3,"a":103,"at":"واعتصموا بحبل الله جميعا ولا تفرقوا واذكروا نعمه الله عليكم اذ كنتم اعداء فالف بين قلوبكم فاصبحتم بنعمته اخوانا وكنتم على شفا حفره من النار فانقذكم منها كذلك يبين الله لكم اياته لعلكم تهتدون","dt":"[103] وتمسكوا جميعا بكتاب ربكم وهدي نبيكم، ولا تفعلوا ما يؤدي الى فرقتكم. واذكروا نعمه جليله انعم الله بها عليكم: اذ كنتم -ايها المؤمنون- قبل الاسلام اعداء، فجمع الله قلوبكم على محبته ومحبه رسوله، والقى في قلوبكم محبه بعضكم لبعض، فاصبحتم بفضله اخوانا متحابين، وكنتم على حافه نار جهنم، فهداكم الله بالاسلام ونجاكم من النار. وكما بين الله لكم معالم الايمان الصحيح فكذلك يبين لكم كل ما فيه صلاحكم؛ لتهتدوا الى سبيل الرشاد، وتسلكوها، فلا تضلوا عنها."},{"id":"397","s":3,"a":104,"at":"ولتكن منكم امه يدعون الى الخير ويامرون بالمعروف وينهون عن المنكر واولئك هم المفلحون","dt":"[104] ولتكن منكم -ايها المؤمنون- جماعه تدعو الى الخير وتامر بالمعروف، وهو ما عرف حسنه شرعا وعقلا، وتنهى عن المنكر، وهو ما عرف قبحه شرعا وعقلا، واولئك هم الفائزون بجنات النعيم."},{"id":"398","s":3,"a":105,"at":"ولا تكونوا كالذين تفرقوا واختلفوا من بعد ما جاءهم البينات واولئك لهم عذاب عظيم","dt":"[105] ولا تكونوا -ايها المؤمنون- كاهل الكتاب الذين وقعت بينهم العداوه والبغضاء فتفرقوا شيعا واحزابا، واختلفوا في اصول دينهم من بعد ان اتضح لهم الحق، واولئك مستحقون لعذاب عظيم موجع."},{"id":"399","s":3,"a":106,"at":"يوم تبيض وجوه وتسود وجوه فاما الذين اسودت وجوههم اكفرتم بعد ايمانكم فذوقوا العذاب بما كنتم تكفرون","dt":"[106] يوم القيامه تبيض وجوه اهل السعاده الذين امنوا بالله ورسوله، وامتثلوا امره، وتسود وجوه اهل الشقاوه ممن كذبوا رسوله، وعصوا امره. فاما الذين اسودت وجوههم، فيقال لهم توبيخا: اكفرتم بعد ايمانكم، فاخترتم الكفر على الايمان؟ فذوقوا العذاب بسبب كفركم."},{"id":"400","s":3,"a":107,"at":"واما الذين ابيضت وجوههم ففي رحمه الله هم فيها خالدون","dt":"[107] واما الذين ابيضت وجوههم بنضره النعيم، وما بشروا به من الخير، فهم في جنه الله ونعيمها، وهم باقون فيها، لا يخرجون منها ابدا."},{"id":"401","s":3,"a":108,"at":"تلك ايات الله نتلوها عليك بالحق وما الله يريد ظلما للعالمين","dt":"[108] هذه ايات الله وبراهينه الساطعه، نتلوها ونقصها عليك -ايها الرسول- بالصدق واليقين. وما الله بظالم احدا من خلقه، ولا بمنقص شيئا من اعمالهم؛ لانه الحاكم العدل الذي لا يجور."},{"id":"402","s":3,"a":109,"at":"ولله ما في السموات وما في الارض والى الله ترجع الامور","dt":"[109] ولله ما في السموات وما في الارض، ملك له وحده خلقا وتدبيرا، ومصير جميع الخلائق اليه وحده، فيجازي كلا على قدر استحقاقه."},{"id":"403","s":3,"a":110,"at":"كنتم خير امه اخرجت للناس تامرون بالمعروف وتنهون عن المنكر وتؤمنون بالله ولو امن اهل الكتاب لكان خيرا لهم منهم المؤمنون واكثرهم الفاسقون","dt":"[110] انتم -يا امه محمد صلى الله عليه وسلم- خير الامم وانفع الناس للناس، تامرون بالمعروف، وهو ما عرف حسنه شرعا وعقلا، وتنهون عن المنكر، وهو ما عرف قبحه شرعا وعقلا، وتصدقون بالله تصديقا جازما يؤيده العمل. ولو امن اهل الكتاب من اليهود والنصارى بمحمد -صلى الله عليه وسلم- وما جاءهم به من عند الله كما امنتم، لكان خيرا لهم في الدنيا والاخره، منهم المؤمنون المصدقون برساله محمد -صلى الله عليه وسلم- العاملون بها، وهم قليل، واكثرهم الخارجون عن دين الله وطاعته."},{"id":"404","s":3,"a":111,"at":"لن يضروكم الا اذى وان يقاتلوكم يولوكم الادبار ثم لا ينصرون","dt":"[111] لن يضركم هؤلاء الفاسقون من اهل الكتاب الا ما يؤذي اسماعكم من الفاظ الشرك والكفر وغير ذلك، وان يقاتلوكم يهزموا، ويهربوا مولين الادبار، ثم لا ينصرون عليكم باي حال."},{"id":"405","s":3,"a":112,"at":"ضربت عليهم الذله اين ما ثقفوا الا بحبل من الله وحبل من الناس وباءوا بغضب من الله وضربت عليهم المسكنه ذلك بانهم كانوا يكفرون بايات الله ويقتلون الانبياء بغير حق ذلك بما عصوا وكانوا يعتدون","dt":"[112] جعل الله الهوان والذل امرا لازما لا يفارق اليهود، فهم اذلاء محتقرون اينما وجدوا، الا بعهد من الله وعهد من الناس يامنون به على انفسهم واموالهم، وذلك هو عقد الذمه لهم والزامهم احكام الاسلام، ورجعوا بغضب من الله مستحقين له، وضربت عليهم الذله والمسكنه، فلا ترى اليهودي الا وعليه الخوف والرعب من اهل الايمان؛ ذلك الذي جعله الله عليهم بسبب كفرهم بالله، وتجاوزهم حدوده، وقتلهم الانبياء ظلما واعتداء، وما جراهم على هذا الا ارتكابهم للمعاصي، وتجاوزهم حدود الله."},{"id":"406","s":3,"a":113,"at":"ليسوا سواء من اهل الكتاب امه قائمه يتلون ايات الله اناء الليل وهم يسجدون","dt":"[113] ليس اهل الكتاب متساوين: فمنهم جماعه مستقيمه على امر الله مؤمنه برسوله محمد -صلى الله عليه وسلم-، يقومون الليل مرتلين ايات القران الكريم، مقبلين على مناجاه الله في صلواتهم."},{"id":"407","s":3,"a":114,"at":"يؤمنون بالله واليوم الاخر ويامرون بالمعروف وينهون عن المنكر ويسارعون في الخيرات واولئك من الصالحين","dt":"[114] يؤمنون بالله واليوم الاخر، ويامرون بالخير كله، وينهون عن الشر كله، ويبادرون الى فعل الخيرات، واولئك من عباد الله الصالحين."},{"id":"408","s":3,"a":115,"at":"وما يفعلوا من خير فلن يكفروه والله عليم بالمتقين","dt":"[115] واي عمل قل او كثر من اعمال الخير تعمله هذه الطائفه المؤمنه فلن يضيع عند الله، بل يشكر لهم، ويجازون عليه. والله عليم بالمتقين الذين فعلوا الخيرات وابتعدوا عن المحرمات؛ ابتغاء رضوان الله، وطلبا لثوابه."},{"id":"409","s":3,"a":116,"at":"ان الذين كفروا لن تغني عنهم اموالهم ولا اولادهم من الله شيئا واولئك اصحاب النار هم فيها خالدون","dt":"[116] ان الذين كفروا بايات الله، وكذبوا رسله، لن تدفع عنهم اموالهم ولا اولادهم شيئا من عذاب الله في الدنيا ولا في الاخره، واولئك اصحاب النار الملازمون لها، لا يخرجون منها."},{"id":"410","s":3,"a":117,"at":"مثل ما ينفقون في هذه الحياه الدنيا كمثل ريح فيها صر اصابت حرث قوم ظلموا انفسهم فاهلكته وما ظلمهم الله ولكن انفسهم يظلمون","dt":"[117] مثل ما ينفق الكافرون في وجوه الخير في هذه الحياه الدنيا وما يؤملونه من ثواب، كمثل ريح فيها برد شديد هبت على زرع قوم كانوا يرجون خيره، وبسبب ذنوبهم لم تبق الريح منه شيئا. وهؤلاء الكافرون لا يجدون في الاخره ثوابا، وما ظلمهم الله بذلك، ولكنهم ظلموا انفسهم بكفرهم وعصيانهم."},{"id":"411","s":3,"a":118,"at":"ياايها الذين امنوا لا تتخذوا بطانه من دونكم لا يالونكم خبالا ودوا ما عنتم قد بدت البغضاء من افواههم وما تخفي صدورهم اكبر قد بينا لكم الايات ان كنتم تعقلون","dt":"[118] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه لا تتخذوا الكافرين اولياء من دون المؤمنين، تطلعونهم على اسراركم، فهؤلاء لا يفترون عن افساد حالكم، وهم يفرحون بما يصيبكم من ضرر ومكروه، وقد ظهرت شده البغض في كلامهم، وما تخفي صدورهم من العداوه لكم اكبر واعظم. قد بينا لكم البراهين والحجج؛ لتتعظوا وتحذروا، ان كنتم تعقلون عن الله مواعظه وامره ونهيه."},{"id":"412","s":3,"a":119,"at":"ها انتم اولاء تحبونهم ولا يحبونكم وتؤمنون بالكتاب كله واذا لقوكم قالوا امنا واذا خلوا عضوا عليكم الانامل من الغيظ قل موتوا بغيظكم ان الله عليم بذات الصدور","dt":"[119] ها هو ذا الدليل على خطئكم في محبتهم، فانتم تحبونهم وتحسنون اليهم، وهم لا يحبونكم ويحملون لكم العداوه والبغضاء، وانتم تؤمنون بالكتب المنزله كلها ومنها كتابهم، وهم لا يؤمنون بكتابكم، فكيف تحبونهم؟ واذا لقوكم قالوا -نفاقا-: امنا وصدقنا، واذا خلا بعضهم الى بعض بدا عليهم الغم والحزن، فعضوا اطراف اصابعهم من شده الغضب؛ لما يرون من الفه المسلمين واجتماع كلمتهم، واعزاز الاسلام، واذلالهم به. قل لهم -ايها الرسول-: موتوا بشده غضبكم. ان الله مطلع على ما تخفي الصدور، وسيجازي كلا على ما قدم من خير او شر."},{"id":"413","s":3,"a":120,"at":"ان تمسسكم حسنه تسؤهم وان تصبكم سيئه يفرحوا بها وان تصبروا وتتقوا لا يضركم كيدهم شيئا ان الله بما يعملون محيط","dt":"[120] ومن عداوه هؤلاء انكم -ايها المؤمنون- ان نزل بكم امر حسن من نصر وغنيمه ظهرت عليهم الكابه والحزن، وان وقع بكم مكروه من هزيمه او نقص في الاموال والانفس والثمرات فرحوا بذلك، وان تصبروا على ما اصابكم، وتتقوا الله فيما امركم به ونهاكم عنه، لا يضركم اذى مكرهم. والله بجميع ما يعمل هؤلاء الكفار من الفساد محيط، وسيجازيهم على ذلك."},{"id":"414","s":3,"a":121,"at":"واذ غدوت من اهلك تبوئ المؤمنين مقاعد للقتال والله سميع عليم","dt":"[121] واذكر -ايها الرسول- حين خرجت من بيتك لابسا عده الحرب، تنظم صفوف اصحابك، وتنزل كل واحد في منزله للقاء المشركين في غزوه «احد». والله سميع لاقوالكم، عليم بافعالكم."},{"id":"415","s":3,"a":122,"at":"اذ همت طائفتان منكم ان تفشلا والله وليهما وعلى الله فليتوكل المؤمنون","dt":"[122] اذكر -ايها النبي- ما كان من امر بني سلمه وبني حارثه حين حدثتهم انفسهم بالرجوع مع زعيمهم المنافق عبدالله بن ابي؛ خوفا من لقاء العدو، ولكن الله عصمهم وحفظهم، فساروا معك متوكلين على الله. وعلى الله وحده فليتوكل المؤمنون."},{"id":"416","s":3,"a":123,"at":"ولقد نصركم الله ببدر وانتم اذله فاتقوا الله لعلكم تشكرون","dt":"[123] ولقد نصركم الله -ايها المؤمنون- ب«بدر» على اعدائكم المشركين مع قله عددكم وعددكم، فخافوا الله بفعل اوامره واجتناب نواهيه؛ لعلكم تشكرون له نعمه."},{"id":"417","s":3,"a":124,"at":"اذ تقول للمؤمنين الن يكفيكم ان يمدكم ربكم بثلاثه الاف من الملائكه منزلين","dt":"[124] اذكر -ايها النبي- ما كان من امر اصحابك في «بدر» حين شق عليهم ان ياتي مدد للمشركين، فاوحينا اليك ان تقول لهم: الن تكفيكم معونه ربكم بان يمدكم بثلاثه الاف من الملائكه منزلين من السماء الى ارض المعركه، يثبتونكم، ويقاتلون معكم؟"},{"id":"418","s":3,"a":125,"at":"بلى ان تصبروا وتتقوا وياتوكم من فورهم هذا يمددكم ربكم بخمسه الاف من الملائكه مسومين","dt":"[125] بلى يكفيكم هذا المدد. وبشاره اخرى لكم: ان تصبروا على لقاء العدو وتتقوا الله بفعل ما امركم به واجتناب ما نهاكم عنه، ويات كفار «مكه» على الفور مسرعين لقتالكم، يظنون انهم يستاصلونكم، فان الله يمدكم بخمسه الاف من الملائكه مسومين اي: قد اعلموا انفسهم وخيولهم بعلامات واضحات."},{"id":"419","s":3,"a":126,"at":"وما جعله الله الا بشرى لكم ولتطمئن قلوبكم به وما النصر الا من عند الله العزيز الحكيم","dt":"[126] وما جعل الله هذا الامداد بالملائكه الا بشرى لكم يبشركم بها ولتطمئن قلوبكم، وتطيب بوعد الله لكم. وما النصر الا من عند الله العزيز الذي لا يغالب، الحكيم في تدبيره وفعله."},{"id":"420","s":3,"a":127,"at":"ليقطع طرفا من الذين كفروا او يكبتهم فينقلبوا خائبين","dt":"[127] وكان نصر الله لكم ب«بدر» ليهلك فريقا من الكفار بالقتل، ومن نجا منهم من القتل رجع حزينا قد ضاقت عليه نفسه، يظهر عليه الخزي والعار."},{"id":"421","s":3,"a":128,"at":"ليس لك من الامر شيء او يتوب عليهم او يعذبهم فانهم ظالمون","dt":"[128] ليس لك -ايها الرسول- من امر العباد شيء، بل الامر كله لله تعالى وحده لا شريك له، ولعل بعض هؤلاء الذين قاتلوك تنشرح صدورهم للاسلام فيسلموا، فيتوب الله عليهم. ومن بقي على كفره يعذبه الله في الدنيا والاخره؛ بسبب ظلمه وبغيه."},{"id":"422","s":3,"a":129,"at":"ولله ما في السموات وما في الارض يغفر لمن يشاء ويعذب من يشاء والله غفور رحيم","dt":"[129] ولله وحده ما في السموات وما في الارض، يغفر لمن يشاء من عباده برحمته، ويعذب من يشاء بعدله. والله غفور لذنوب عباده، رحيم بهم."},{"id":"423","s":3,"a":130,"at":"ياايها الذين امنوا لا تاكلوا الربا اضعافا مضاعفه واتقوا الله لعلكم تفلحون","dt":"[130] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه احذروا الربا بجميع انواعه، ولا تاخذوا في القرض زياده على رؤوس اموالكم وان قلت، فكيف اذا كانت هذه الزياده تتضاعف كلما حان موعد سداد الدين؟ واتقوا الله بالتزام شرعه؛ لتفوزوا في الدنيا والاخره."},{"id":"424","s":3,"a":131,"at":"واتقوا النار التي اعدت للكافرين","dt":"[131] واجعلوا لانفسكم وقايه بينكم وبين النار التي هيئت للكافرين."},{"id":"425","s":3,"a":132,"at":"واطيعوا الله والرسول لعلكم ترحمون","dt":"[132] واطيعوا الله -ايها المؤمنون- فيما امركم به من الطاعات وفيما نهاكم عنه من اكل الربا وغيره من الاشياء، واطيعوا الرسول؛ لترحموا، فلا تعذبوا."},{"id":"426","s":3,"a":133,"at":"وسارعوا الى مغفره من ربكم وجنه عرضها السموات والارض اعدت للمتقين","dt":"[133] وبادروا بطاعتكم لله ورسوله لاغتنام مغفره عظيمه من ربكم وجنه واسعه، عرضها السموات والارض، اعدها الله للمتقين."},{"id":"427","s":3,"a":134,"at":"الذين ينفقون في السراء والضراء والكاظمين الغيظ والعافين عن الناس والله يحب المحسنين","dt":"[134] الذين ينفقون اموالهم في اليسر والعسر، والذين يمسكون ما في انفسهم من الغيظ بالصبر، واذا قدروا عفوا عمن ظلمهم. وهذا هو الاحسان الذي يحب الله اصحابه."},{"id":"428","s":3,"a":135,"at":"والذين اذا فعلوا فاحشه او ظلموا انفسهم ذكروا الله فاستغفروا لذنوبهم ومن يغفر الذنوب الا الله ولم يصروا على ما فعلوا وهم يعلمون","dt":"[135] والذين اذا ارتكبوا ذنبا كبيرا او ظلموا انفسهم بارتكاب ما دونه، ذكروا وعد الله ووعيده فلجؤوا الى ربهم تائبين، يطلبون منه ان يغفر لهم ذنوبهم، وهم موقنون انه لا يغفر الذنوب الا الله، فهم لذلك لا يقيمون على معصيه، وهم يعلمون انهم ان تابوا تاب الله عليهم."},{"id":"429","s":3,"a":136,"at":"اولئك جزاؤهم مغفره من ربهم وجنات تجري من تحتها الانهار خالدين فيها ونعم اجر العاملين","dt":"[136] اولئك الموصوفون بتلك الصفات العظيمه جزاؤهم ان يستر الله ذنوبهم، ولهم جنات تجري من تحت اشجارها وقصورها المياه العذبه، خالدين فيها لا يخرجون منها ابدا. ونعم اجر العاملين المغفره والجنه."},{"id":"430","s":3,"a":137,"at":"قد خلت من قبلكم سنن فسيروا في الارض فانظروا كيف كان عاقبه المكذبين","dt":"[137] يخاطب الله المؤمنين لما اصيبوا يوم «احد» تعزيه لهم بانه قد مضت من قبلكم امم، ابتلي المؤمنون منهم بقتال الكافرين فكانت العاقبه لهم، فسيروا في الارض معتبرين بما ال اليه امر اولئك المكذبين بالله ورسله."},{"id":"431","s":3,"a":138,"at":"هذا بيان للناس وهدى وموعظه للمتقين","dt":"[138] هذا القران بيان وارشاد الى طريق الحق، وتذكير تخشع له قلوب المتقين، وهم الذين يخشون الله، وخصوا بذلك؛ لانهم هم المنتفعون به دون غيرهم."},{"id":"432","s":3,"a":139,"at":"ولا تهنوا ولا تحزنوا وانتم الاعلون ان كنتم مؤمنين","dt":"[139] ولا تضعفوا -ايها المؤمنون- عن قتال عدوكم، ولا تحزنوا لما اصابكم في «احد»، وانتم الغالبون والعاقبه لكم، ان كنتم مصدقين بالله ورسوله، متبعين شرعه."},{"id":"433","s":3,"a":140,"at":"ان يمسسكم قرح فقد مس القوم قرح مثله وتلك الايام نداولها بين الناس وليعلم الله الذين امنوا ويتخذ منكم شهداء والله لا يحب الظالمين","dt":"[140] ان اصابتكم -ايها المؤمنون -جراح او قتل في غزوه «احد» فحزنتم لذلك، فقد اصاب المشركين جراح وقتل مثل ذلك في غزوه «بدر». وتلك الايام يصرفها الله بين الناس، نصر مره وهزيمه اخرى؛ لما في ذلك من الحكمه، حتى يظهر ما علمه الله في الازل؛ ليميز الله المؤمن الصادق من غيره، ويكرم اقواما منكم بالشهاده. والله لا يحب الذين ظلموا انفسهم، وقعدوا عن القتال في سبيله."},{"id":"434","s":3,"a":141,"at":"وليمحص الله الذين امنوا ويمحق الكافرين","dt":"[141] وهذه الهزيمه التي وقعت في «احد» كانت اختبارا وتصفيه للمؤمنين، وتخليصا لهم من المنافقين وهلاكا للكافرين."},{"id":"435","s":3,"a":142,"at":"ام حسبتم ان تدخلوا الجنه ولما يعلم الله الذين جاهدوا منكم ويعلم الصابرين","dt":"[142] يا اصحاب محمد -صلى الله عليه وسلم- اظننتم ان تدخلوا الجنه، ولم تبتلوا بالقتال والشدائد؟ لا يحصل لكم دخولها حتى تبتلوا، ويعلم الله علما ظاهرا للخلق المجاهدين منكم في سبيله، والصابرين على مقاومه الاعداء."},{"id":"436","s":3,"a":143,"at":"ولقد كنتم تمنون الموت من قبل ان تلقوه فقد رايتموه وانتم تنظرون","dt":"[143] ولقد كنتم -ايها المؤمنون- قبل غزوه «احد» تتمنون لقاء العدو؛ لتنالوا شرف الجهاد والاستشهاد في سبيل الله الذي حظي به اخوانكم في غزوه «بدر»، فها هو ذا قد حصل لكم الذي تمنيتموه وطلبتموه، فدونكم فقاتلوا وصابروا."},{"id":"437","s":3,"a":144,"at":"وما محمد الا رسول قد خلت من قبله الرسل افان مات او قتل انقلبتم على اعقابكم ومن ينقلب على عقبيه فلن يضر الله شيئا وسيجزي الله الشاكرين","dt":"[144] وما محمد -صلى الله عليه وسلم- الا رسول من جنس الرسل الذين قبله يبلغ رساله ربه. افان مات بانقضاء اجله، او قتل كما اشاعه الاعداء رجعتم عن دينكم، وتركتم ما جاءكم به نبيكم؟ ومن يرجع منكم عن دينه فلن يضر الله شيئا، انما يضر نفسه ضررا عظيما. اما من ثبت على الايمان وشكر ربه على نعمه الاسلام، فان الله يجزيه احسن الجزاء."},{"id":"438","s":3,"a":145,"at":"وما كان لنفس ان تموت الا باذن الله كتابا مؤجلا ومن يرد ثواب الدنيا نؤته منها ومن يرد ثواب الاخره نؤته منها وسنجزي الشاكرين","dt":"[145] لن يموت احد الا باذن الله وقدره وحتى يستوفي المده التي قدرها الله له، كتب الله ذلك كتابا مؤقتا، لا يتقدم على اجله ولا يتاخر. ومن يطلب بعمله عرض الدنيا، نعطه ما قسمناه له من رزق، ولا حظ له في الاخره، ومن يطلب بعمله الجزاء من الله في الاخره نمنحه ما طلبه، ونؤته جزاءه وافرا مع ما له في الدنيا من رزق مقسوم، فهذا قد شكرنا بطاعته وجهاده، وسنجزي الشاكرين خيرا."},{"id":"439","s":3,"a":146,"at":"وكاين من نبي قاتل معه ربيون كثير فما وهنوا لما اصابهم في سبيل الله وما ضعفوا وما استكانوا والله يحب الصابرين","dt":"[146] كثير من الانبياء السابقين قاتل معهم جموع كثيره من اصحابهم، فما ضعفوا لما نزل بهم من جروح او قتل؛ لان ذلك في سبيل ربهم، وما عجزوا، ولا خضعوا لعدوهم، انما صبروا على ما اصابهم. والله يحب الصابرين."},{"id":"440","s":3,"a":147,"at":"وما كان قولهم الا ان قالوا ربنا اغفر لنا ذنوبنا واسرافنا في امرنا وثبت اقدامنا وانصرنا على القوم الكافرين","dt":"[147] وما كان قول هؤلاء الصابرين الا ان قالوا: ربنا اغفر لنا ذنوبنا، وما وقع منا من تجاوز في امر ديننا، وثبت اقدامنا حتى لا نفر من قتال عدونا، وانصرنا على من جحد وحدانيتك ونبوه انبيائك."},{"id":"441","s":3,"a":148,"at":"فاتاهم الله ثواب الدنيا وحسن ثواب الاخره والله يحب المحسنين","dt":"[148] فاعطى الله اولئك الصابرين جزاءهم في الدنيا بالنصر على اعدائهم، وبالتمكين لهم في الارض، وبالجزاء الحسن العظيم في الاخره، وهو جنات النعيم. والله يحب كل من احسن عبادته لربه ومعاملته لخلقه."},{"id":"442","s":3,"a":149,"at":"ياايها الذين امنوا ان تطيعوا الذين كفروا يردوكم على اعقابكم فتنقلبوا خاسرين","dt":"[149] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه ان تطيعوا الذين جحدوا الوهيتي، ولم يؤمنوا برسلي من اليهود والنصارى والمنافقين والمشركين فيما يامرونكم به وينهونكم عنه، يضلوكم عن طريق الحق، وترتدوا عن دينكم، فتعودوا بالخسران المبين والهلاك المحقق."},{"id":"443","s":3,"a":150,"at":"بل الله مولاكم وهو خير الناصرين","dt":"[150] انهم لن ينصروكم، بل الله ناصركم، وهو خير ناصر، فلا يحتاج معه الى نصره احد."},{"id":"444","s":3,"a":151,"at":"سنلقي في قلوب الذين كفروا الرعب بما اشركوا بالله ما لم ينزل به سلطانا وماواهم النار وبئس مثوى الظالمين","dt":"[151] سنقذف في قلوب الذين كفروا اشد الفزع والخوف؛ بسبب اشراكهم بالله الهه مزعومه، ليس لهم دليل او برهان على استحقاقها للعباده مع الله، فحالتهم في الدنيا: رعب وهلع من المؤمنين، اما مكانهم في الاخره الذي ياوون اليه فهو النار؛ وذلك بسبب ظلمهم وعدوانهم، وساء هذا المقام مقاما لهم."},{"id":"445","s":3,"a":152,"at":"ولقد صدقكم الله وعده اذ تحسونهم باذنه حتى اذا فشلتم وتنازعتم في الامر وعصيتم من بعد ما اراكم ما تحبون منكم من يريد الدنيا ومنكم من يريد الاخره ثم صرفكم عنهم ليبتليكم ولقد عفا عنكم والله ذو فضل على المؤمنين","dt":"[152] ولقد حقق الله لكم ما وعدكم به من نصر، حين كنتم تقتلون الكفار في غزوه «احد» باذنه تعالى، حتى اذا جبنتم وضعفتم عن القتال واختلفتم: هل تبقون في مواقعكم او تتركونها لجمع الغنائم مع من يجمعها؟ وعصيتم امر رسولكم حين امركم الا تفارقوا اماكنكم باي حال، حلت بكم الهزيمه من بعد ما اراكم ما تحبون من النصر، وتبين ان منكم من يريد الغنائم، وان منكم من يطلب الاخره وثوابها، ثم صرف الله وجوهكم عن عدوكم؛ ليختبركم، وقد علم الله ندمكم وتوبتكم فعفا عنكم، والله ذو فضل عظيم على المؤمنين."},{"id":"446","s":3,"a":153,"at":"اذ تصعدون ولا تلوون على احد والرسول يدعوكم في اخراكم فاثابكم غما بغم لكيلا تحزنوا على ما فاتكم ولا ما اصابكم والله خبير بما تعملون","dt":"[153] اذكروا -يا اصحاب محمد صلى الله عليه وسلم- ما كان من امركم حين اخذتم تصعدون الجبل هاربين من اعدائكم، ولا تلتفتون الى احد لما اعتراكم من الدهشه والخوف والرعب، ورسول الله -صلى الله عليه وسلم- ثابت في الميدان يناديكم من خلفكم قائلا: الي عباد الله، وانتم لا تسمعون ولا تنظرون، فكان جزاؤكم ان انزل الله بكم الما وضيقا وغما؛ لكي لا تحزنوا على ما فاتكم من نصر وغنيمه، ولا ما حل بكم من خوف وهزيمه. والله خبير بجميع اعمالكم، لا يخفى عليه منها شيء."},{"id":"447","s":3,"a":154,"at":"ثم انزل عليكم من بعد الغم امنه نعاسا يغشى طائفه منكم وطائفه قد اهمتهم انفسهم يظنون بالله غير الحق ظن الجاهليه يقولون هل لنا من الامر من شيء قل ان الامر كله لله يخفون في انفسهم ما لا يبدون لك يقولون لو كان لنا من الامر شيء ما قتلنا هاهنا قل لو كنتم في بيوتكم لبرز الذين كتب عليهم القتل الى مضاجعهم وليبتلي الله ما في صدوركم وليمحص ما في قلوبكم والله عليم بذات الصدور","dt":"[154] ثم كان من رحمه الله بالمؤمنين المخلصين ان القى في قلوبهم -من بعد ما نزل بها من هم وغم- اطمئنانا وثقه في وعد الله، وكان من اثره نعاس غشي طائفه منهم، وهم اهل الاخلاص واليقين، وطائفه اخرى اهمهم خلاص انفسهم خاصه، وضعفت عزيمتهم وشغلوا بانفسهم، واساؤوا الظن بربهم وبدينه وبنبيه، وظنوا ان الله لا يتم امر رسوله، وان الاسلام لن تقوم له قائمه، ولذلك تراهم نادمين على خروجهم، يقول بعضهم لبعض: هل كان لنا من اختيار في الخروج للقتال؟ قل لهم -ايها الرسول-: ان الامر كله لله، فهو الذي قدر خروجكم وما حدث لكم، وهم يخفون في انفسهم ما لا يظهرونه لك من الحسره على خروجهم للقتال، يقولون: لو كان لنا ادنى اختيار ما قتلنا هاهنا. قل لهم: ان الاجال بيد الله، ولو كنتم في بيوتكم، وقدر الله انكم تموتون، لخرج الذين كتب الله عليهم الموت الى حيث يقتلون، وما جعل الله ذلك الا ليختبر ما في صدوركم من الشك والنفاق، وليميز الخبيث من الطيب، ويظهر امر المؤمن من المنافق للناس في الاقوال والافعال. والله عليم بما في صدور خلقه، لا يخفى عليه شيء من امورهم."},{"id":"448","s":3,"a":155,"at":"ان الذين تولوا منكم يوم التقى الجمعان انما استزلهم الشيطان ببعض ما كسبوا ولقد عفا الله عنهم ان الله غفور حليم","dt":"[155] ان الذين فروا منكم -يا اصحاب محمد صلى الله عليه وسلم- عن القتال يوم التقى المؤمنون والمشركون في غزوه «احد»، انما اوقعهم الشيطان في هذا الذنب ببعض ما عملوا من الذنوب، ولقد تجاوز الله عنهم فلم يعاقبهم. ان الله غفور للمذنبين التائبين، حليم لا يعاجل من عصاه بالعقوبه."},{"id":"449","s":3,"a":156,"at":"ياايها الذين امنوا لا تكونوا كالذين كفروا وقالوا لاخوانهم اذا ضربوا في الارض او كانوا غزى لو كانوا عندنا ما ماتوا وما قتلوا ليجعل الله ذلك حسره في قلوبهم والله يحيي ويميت والله بما تعملون بصير","dt":"[156] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه لا تشابهوا الكافرين الذين لا يؤمنون بربهم، فهم يقولون لاخوانهم من اهل الكفر اذا خرجوا يبحثون في ارض الله عن معاشهم او كانوا مع الغزاه المقاتلين فماتوا او قتلوا: لو لم يخرج هؤلاء ولم يقاتلوا واقاموا معنا ما ماتوا وما قتلوا. وهذا القول يزيدهم الما وحزنا وحسره تستقر في قلوبهم، اما المؤمنون فانهم يعلمون ان ذلك بقدر الله فيهدي الله قلوبهم، ويخفف عنهم المصيبه، والله يحيي من قدر له الحياه -وان كان مسافرا او غازيا- ويميت من انتهى اجله وان كان مقيما. والله بكل ما تعملونه بصير، فيجازيكم به."},{"id":"450","s":3,"a":157,"at":"ولئن قتلتم في سبيل الله او متم لمغفره من الله ورحمه خير مما يجمعون","dt":"[157] ولئن قتلتم -ايها المؤمنون- وانتم تجاهدون في سبيل الله او متم في اثناء القتال، ليغفرن الله لكم ذنوبكم، وليرحمنكم رحمه من عنده، فتفوزون بجنات النعيم، وذلك خير من الدنيا وما يجمعه اهلها."},{"id":"451","s":3,"a":158,"at":"ولئن متم او قتلتم لالى الله تحشرون","dt":"[158] ولئن انقضت اجالكم في هذه الحياه الدنيا، فمتم على فرشكم، او قتلتم في ساحه القتال، لالى الله وحده تحشرون، فيجازيكم باعمالكم."},{"id":"452","s":3,"a":159,"at":"فبما رحمه من الله لنت لهم ولو كنت فظا غليظ القلب لانفضوا من حولك فاعف عنهم واستغفر لهم وشاورهم في الامر فاذا عزمت فتوكل على الله ان الله يحب المتوكلين","dt":"[159] فبرحمه من الله لك ولاصحابك - ايها النبي - من الله عليك فكنت رفيقا بهم، ولو كنت سيئ الخلق قاسي القلب، لانصرف اصحابك من حولك، فلا تؤاخذهم بما كان منهم في غزوه «احد»، واسال الله -ايها النبي- ان يغفر لهم، وشاورهم في الامور التي تحتاج الى مشوره، فاذا عزمت على امر من الامور -بعد الاستشاره- فامضه معتمدا على الله وحده، ان الله يحب المتوكلين عليه."},{"id":"453","s":3,"a":160,"at":"ان ينصركم الله فلا غالب لكم وان يخذلكم فمن ذا الذي ينصركم من بعده وعلى الله فليتوكل المؤمنون","dt":"[160] ان يمددكم الله بنصره ومعونته فلا احد يستطيع ان يغلبكم، وان يخذلكم فمن هذا الذي يستطيع ان ينصركم من بعد خذلانه لكم؟ وعلى الله وحده فليتوكل المؤمنون."},{"id":"454","s":3,"a":161,"at":"وما كان لنبي ان يغل ومن يغلل يات بما غل يوم القيامه ثم توفى كل نفس ما كسبت وهم لا يظلمون","dt":"[161] وما كان لنبي ان يخون اصحابه بان ياخذ شيئا من الغنيمه غير ما اختصه الله به، ومن يفعل ذلك منكم يات بما اخذه حاملا له يوم القيامه؛ ليفضح به في الموقف المشهود، ثم تعطى كل نفس جزاء ما كسبت وافيا غير منقوص دون ظلم."},{"id":"455","s":3,"a":162,"at":"افمن اتبع رضوان الله كمن باء بسخط من الله وماواه جهنم وبئس المصير","dt":"[162] لا يستوي من كان قصده رضوان الله ومن هو مكب على المعاصي، مسخط لربه، فاستحق بذلك سكن جهنم، وبئس المصير."},{"id":"456","s":3,"a":163,"at":"هم درجات عند الله والله بصير بما يعملون","dt":"[163] اصحاب الجنه المتبعون لما يرضي الله متفاوتون في الدرجات، واصحاب النار المتبعون لما يسخط الله متفاوتون في الدركات، لا يستوون. والله بصير باعمالهم لا يخفى عليه منها شيء."},{"id":"457","s":3,"a":164,"at":"لقد من الله على المؤمنين اذ بعث فيهم رسولا من انفسهم يتلو عليهم اياته ويزكيهم ويعلمهم الكتاب والحكمه وان كانوا من قبل لفي ضلال مبين","dt":"[164] لقد انعم الله على المؤمنين من العرب؛ اذ بعث فيهم رسولا من انفسهم، يتلو عليهم ايات القران، ويطهرهم من الشرك والاخلاق الفاسده، ويعلمهم القران والسنه، وان كانوا من قبل هذا الرسول لفي غي وجهل ظاهر."},{"id":"458","s":3,"a":165,"at":"او لما اصابتكم مصيبه قد اصبتم مثليها قلتم انى هذا قل هو من عند انفسكم ان الله على كل شيء قدير","dt":"[165] او لما اصابتكم -ايها المؤمنون- مصيبه، وهي ما اصيب منكم يوم «احد» قد اصبتم مثليها من المشركين في يوم «بدر»، قلتم متعجبين: كيف يكون هذا ونحن مسلمون ورسول الله -صلى الله عليه وسلم- فينا وهؤلاء مشركون؟ قل لهم -ايها النبي-: هذا الذي اصابكم هو من عند انفسكم؛ بسبب مخالفتكم امر رسولكم واقبالكم على جمع الغنائم. ان الله يفعل ما يشاء ويحكم ما يريد، لا معقب لحكمه."},{"id":"459","s":3,"a":166,"at":"وما اصابكم يوم التقى الجمعان فباذن الله وليعلم المؤمنين","dt":"[166] وما وقع بكم من جراح او قتل في غزوه «احد» يوم التقى جمع المؤمنين وجمع المشركين فكان النصر للمؤمنين اولا ثم للمشركين ثانيا، فذلك كله بقضاء الله وقدره، وليظهر ما علمه الله في الازل؛ ليميز المؤمنين الصادقين منكم."},{"id":"460","s":3,"a":167,"at":"وليعلم الذين نافقوا وقيل لهم تعالوا قاتلوا في سبيل الله او ادفعوا قالوا لو نعلم قتالا لاتبعناكم هم للكفر يومئذ اقرب منهم للايمان يقولون بافواههم ما ليس في قلوبهم والله اعلم بما يكتمون","dt":"[167] وليعلم المنافقين الذين كشف الله ما في قلوبهم حين قال المؤمنون لهم: تعالوا قاتلوا معنا في سبيل الله، او كونوا عونا لنا بتكثيركم سوادنا، فقالوا: لو نعلم انكم تقاتلون احدا لكنا معكم عليهم، هم للكفر في هذا اليوم اقرب منهم للايمان؛ لانهم يقولون بافواههم ما ليس في قلوبهم. والله اعلم بما يخفون في صدورهم."},{"id":"461","s":3,"a":168,"at":"الذين قالوا لاخوانهم وقعدوا لو اطاعونا ما قتلوا قل فادرءوا عن انفسكم الموت ان كنتم صادقين","dt":"[168] هؤلاء المنافقون هم الذين قعدوا وقالوا لاخوانهم الذين اصيبوا مع المسلمين في حربهم المشركين يوم «احد»: لو اطاعنا هؤلاء ما قتلوا. قل لهم -ايها الرسول-: فادفعوا عن انفسكم الموت ان كنتم صادقين في دعواكم انهم لو اطاعوكم ما قتلوا، وانكم قد نجوتم منه بقعودكم عن القتال."},{"id":"462","s":3,"a":169,"at":"ولا تحسبن الذين قتلوا في سبيل الله امواتا بل احياء عند ربهم يرزقون","dt":"[169] ولا تظنن -ايها النبي- ان الذين قتلوا في سبيل الله اموات لا يحسون شيئا، بل هم احياء حياه برزخيه في جوار ربهم الذي جاهدوا من اجله، وماتوا في سبيله، يجري عليهم رزقهم في الجنه، وينعمون."},{"id":"463","s":3,"a":170,"at":"فرحين بما اتاهم الله من فضله ويستبشرون بالذين لم يلحقوا بهم من خلفهم الا خوف عليهم ولا هم يحزنون","dt":"[170] لقد عمتهم السعاده حين من الله عليهم، فاعطاهم من عظيم جوده وواسع كرمه من النعيم والرضا ما تقر به اعينهم، وهم يفرحون باخوانهم المجاهدين الذين فارقوهم وهم احياء؛ ليفوزوا كما فازوا، لعلمهم انهم سينالون من الخير الذي نالوه اذا استشهدوا في سبيل الله مخلصين له، وان لا خوف عليهم فيما يستقبلون من امور الاخره، ولا هم يحزنون على ما فاتهم من حظوظ الدنيا."},{"id":"464","s":3,"a":171,"at":"يستبشرون بنعمه من الله وفضل وان الله لا يضيع اجر المؤمنين","dt":"[171] وانهم في فرحه غامره بما اعطوا من نعم الله وجزيل عطائه، وان الله لا يضيع اجر المؤمنين به، بل ينميه ويزيده من فضله."},{"id":"465","s":3,"a":172,"at":"الذين استجابوا لله والرسول من بعد ما اصابهم القرح للذين احسنوا منهم واتقوا اجر عظيم","dt":"[172] الذين لبوا نداء الله ورسوله وخرجوا في اعقاب المشركين الى «حمراء الاسد» بعد هزيمتهم في غزوه «احد» مع ما كان بهم من الام وجراح، وبذلوا غايه جهدهم، والتزموا بهدي نبيهم، للمحسنين منهم والمتقين ثواب عظيم."},{"id":"466","s":3,"a":173,"at":"الذين قال لهم الناس ان الناس قد جمعوا لكم فاخشوهم فزادهم ايمانا وقالوا حسبنا الله ونعم الوكيل","dt":"[173] وهم الذين قال لهم بعض المشركين: ان ابا سفيان ومن معه قد اجمعوا امرهم على الرجوع اليكم لاستئصالكم، فاحذروهم واتقوا لقاءهم، فانه لا طاقه لكم بهم، فزادهم ذلك التخويف يقينا وتصديقا بوعد الله لهم، ولم يثنهم ذلك عن عزمهم، فساروا الى حيث شاء الله، وقالوا: حسبنا الله اي: كافينا، ونعم الوكيل المفوض اليه تدبير عباده."},{"id":"467","s":3,"a":174,"at":"فانقلبوا بنعمه من الله وفضل لم يمسسهم سوء واتبعوا رضوان الله والله ذو فضل عظيم","dt":"[174] فرجعوا من «حمراء الاسد» الى «المدينه» بنعمه من الله بالثواب الجزيل، وبفضل منه بالمنزله العاليه، وقد ازدادوا ايمانا ويقينا، واذلوا اعداء الله، وفازوا بالسلامه من القتل والقتال، واتبعوا رضوان الله بطاعتهم له ولرسوله. والله ذو احسان وعطاء كثير واسع عليهم وعلى غيرهم."},{"id":"468","s":3,"a":175,"at":"انما ذلكم الشيطان يخوف اولياءه فلا تخافوهم وخافون ان كنتم مؤمنين","dt":"[175] انما المثبط لكم في ذلك هو الشيطان جاءكم يخوفكم انصاره، فلا تخافوا المشركين؛ لانهم ضعاف لا ناصر لهم، وخافوني بالاقبال على طاعتي ان كنتم مصدقين بي، ومتبعين رسولي."},{"id":"469","s":3,"a":176,"at":"ولا يحزنك الذين يسارعون في الكفر انهم لن يضروا الله شيئا يريد الله الا يجعل لهم حظا في الاخره ولهم عذاب عظيم","dt":"[176] لا يدخل الحزن الى قلبك -ايها الرسول- هؤلاء الكفار بمسارعتهم في الجحود والضلال، انهم بذلك لن يضروا الله شيئا، انما يضرون انفسهم بحرمانها حلاوه الايمان وعظيم الثواب، يريد الله الا يجعل لهم ثوابا في الاخره؛ لانهم انصرفوا عن دعوه الحق، ولهم عذاب شديد."},{"id":"470","s":3,"a":177,"at":"ان الذين اشتروا الكفر بالايمان لن يضروا الله شيئا ولهم عذاب اليم","dt":"[177] ان الذين استبدلوا الكفر بالايمان لن يضروا الله شيئا، بل ضرر فعلهم يعود على انفسهم، ولهم في الاخره عذاب موجع."},{"id":"471","s":3,"a":178,"at":"ولا يحسبن الذين كفروا انما نملي لهم خير لانفسهم انما نملي لهم ليزدادوا اثما ولهم عذاب مهين","dt":"[178] ولا يظنن الجاحدون اننا اذا اطلنا اعمارهم، ومتعناهم بمتع الدنيا، ولم نؤاخذهم بكفرهم وذنوبهم، انهم قد نالوا بذلك خيرا لانفسهم، انما نؤخر عذابهم واجالهم؛ ليزدادوا ظلما وطغيانا، ولهم عذاب يهينهم ويذلهم."},{"id":"472","s":3,"a":179,"at":"ما كان الله ليذر المؤمنين على ما انتم عليه حتى يميز الخبيث من الطيب وما كان الله ليطلعكم على الغيب ولكن الله يجتبي من رسله من يشاء فامنوا بالله ورسله وان تؤمنوا وتتقوا فلكم اجر عظيم","dt":"[179] ما كان الله ليدعكم ايها المصدقون بالله ورسوله العاملون بشرعه على ما انتم عليه من التباس المؤمن منكم بالمنافق حتى يميز الخبيث من الطيب، فيعرف المنافق من المؤمن الصادق. وما كان من حكمه الله ان يطلعكم -ايها المؤمنون- على الغيب الذي يعلمه من عباده، فتعرفوا المؤمن منهم من المنافق، ولكنه يميزهم بالمحن والابتلاء، غير ان الله تعالى يصطفي من رسله من يشاء؛ ليطلعه على بعض علم الغيب بوحي منه، فامنوا بالله ورسوله، وان تؤمنوا ايمانا صادقا وتتقوا ربكم بطاعته، فلكم اجر عظيم عند الله."},{"id":"473","s":3,"a":180,"at":"ولا يحسبن الذين يبخلون بما اتاهم الله من فضله هو خيرا لهم بل هو شر لهم سيطوقون ما بخلوا به يوم القيامه ولله ميراث السموات والارض والله بما تعملون خبير","dt":"[180] ولا يظنن الذين يبخلون بما انعم الله به عليهم تفضلا منه ان هذا البخل خير لهم، بل هو شر لهم؛ لان هذا المال الذي جمعوه سيكون طوقا من نار يوضع في اعناقهم يوم القيامه. والله سبحانه وتعالى هو مالك الملك، وهو الباقي بعد فناء جميع خلقه، وهو خبير باعمالكم جميعها، وسيجازي كلا على قدر استحقاقه."},{"id":"474","s":3,"a":181,"at":"لقد سمع الله قول الذين قالوا ان الله فقير ونحن اغنياء سنكتب ما قالوا وقتلهم الانبياء بغير حق ونقول ذوقوا عذاب الحريق","dt":"[181] لقد سمع الله قول اليهود الذين قالوا: ان الله فقير الينا يطلب منا ان نقرضه اموالا، ونحن اغنياء. سنكتب هذا القول الذي قالوه، وسنكتب انهم راضون بما كان من قتل ابائهم لانبياء الله ظلما وعدوانا، وسوف نؤاخذهم بذلك في الاخره، ونقول لهم وهم في النار يعذبون: ذوقوا عذاب النار المحرقه."},{"id":"475","s":3,"a":182,"at":"ذلك بما قدمت ايديكم وان الله ليس بظلام للعبيد","dt":"[182] ذلك العذاب الشديد بسبب ما قدمتموه في حياتكم الدنيا من المعاصي القوليه والفعليه والاعتقاديه، وان الله ليس بظلام للعبيد."},{"id":"476","s":3,"a":183,"at":"الذين قالوا ان الله عهد الينا الا نؤمن لرسول حتى ياتينا بقربان تاكله النار قل قد جاءكم رسل من قبلي بالبينات وبالذي قلتم فلم قتلتموهم ان كنتم صادقين","dt":"[183] هؤلاء اليهود حين دعوا الى الاسلام قالوا: ان الله اوصانا في التوراه الا نصدق من جاءنا يقول: انه رسول من الله، حتى ياتينا بصدقه يتقرب بها الى الله، فتنزل نار من السماء فتحرقها. قل لهم -ايها الرسول-: انتم كاذبون في قولكم؛ لانه قد جاء اباءكم رسل من قبلي بالمعجزات والدلائل على صدقهم، وبالذي قلتم من الاتيان بالقربان الذي تاكله النار، فلم قتل اباؤكم هؤلاء الانبياء ان كنتم صادقين في دعواكم؟"},{"id":"477","s":3,"a":184,"at":"فان كذبوك فقد كذب رسل من قبلك جاءوا بالبينات والزبر والكتاب المنير","dt":"[184] فان كذبك -ايها الرسول- هؤلاء اليهود وغيرهم من اهل الكفر، فقد كذب المبطلون كثيرا من المرسلين من قبلك، جاؤوا اقوامهم بالمعجزات الباهرات والحجج الواضحات، والكتب السماويه التي هي نور يكشف الظلمات، والكتاب البين الواضح."},{"id":"478","s":3,"a":185,"at":"كل نفس ذائقه الموت وانما توفون اجوركم يوم القيامه فمن زحزح عن النار وادخل الجنه فقد فاز وما الحياه الدنيا الا متاع الغرور","dt":"[185] كل نفس لابد ان تذوق الموت، وبهذا يرجع جميع الخلق الى ربهم؛ ليحاسبهم. وانما توفون اجوركم على اعمالكم وافيه غير منقوصه يوم القيامه، فمن اكرمه ربه ونجاه من النار وادخله الجنه فقد نال غايه ما يطلب. وما الحياه الدنيا الا متعه زائله، فلا تغتروا بها."},{"id":"479","s":3,"a":186,"at":"لتبلون في اموالكم وانفسكم ولتسمعن من الذين اوتوا الكتاب من قبلكم ومن الذين اشركوا اذى كثيرا وان تصبروا وتتقوا فان ذلك من عزم الامور","dt":"[186] لتختبرن -ايها المؤمنون- في اموالكم باخراج النفقات الواجبه والمستحبه، وبالجوائح التي تصيبها، وفي انفسكم بما يجب عليكم من الطاعات، وما يحل بكم من جراح او قتل وفقد للاحباب؛ وذلك حتى يتميز المؤمن الصادق من غيره. ولتسمعن من اليهود والنصارى والمشركين ما يؤذي اسماعكم من الفاظ الشرك والطعن في دينكم. وان تصبروا -ايها المؤمنون- على ذلك كله، وتتقوا الله بلزوم طاعته واجتناب معصيته، فان ذلك من الامور التي يعزم عليها، وينافس فيها."},{"id":"480","s":3,"a":187,"at":"واذ اخذ الله ميثاق الذين اوتوا الكتاب لتبيننه للناس ولا تكتمونه فنبذوه وراء ظهورهم واشتروا به ثمنا قليلا فبئس ما يشترون","dt":"[187] واذكر -ايها الرسول- اذ اخذ الله العهد الموثق على الذين اتاهم الله الكتاب من اليهود والنصارى، فلليهود التوراه وللنصارى الانجيل؛ ليعملوا بهما، ويبينوا للناس ما فيهما، ولا يكتموا ذلك ولا يخفوه، فتركوا العهد ولم يلتزموا به، واخذوا ثمنا بخسا مقابل كتمانهم الحق وتحريفهم الكتاب، فبئس الشراء يشترون، في تضييعهم الميثاق، وتبديلهم الكتاب."},{"id":"481","s":3,"a":188,"at":"لا تحسبن الذين يفرحون بما اتوا ويحبون ان يحمدوا بما لم يفعلوا فلا تحسبنهم بمفازه من العذاب ولهم عذاب اليم","dt":"[188] ولا تظنن الذين يفرحون بما اتوا من افعال قبيحه كاليهود والمنافقين وغيرهم، ويحبون ان يثني عليهم الناس بما لم يفعلوا، فلا تظننهم ناجين من عذاب الله في الدنيا، ولهم في الاخره عذاب موجع. وفي الايه وعيد شديد لكل ات لفعل السوء معجب به، ولكل مفتخر بما لم يعمل؛ ليثني عليه الناس ويحمدوه."},{"id":"482","s":3,"a":189,"at":"ولله ملك السموات والارض والله على كل شيء قدير","dt":"[189] ولله وحده ملك السموات والارض وما فيهما، والله على كل شيء قدير."},{"id":"483","s":3,"a":190,"at":"ان في خلق السموات والارض واختلاف الليل والنهار لايات لاولي الالباب","dt":"[190] ان في خلق السموات والارض على غير مثال سابق، وفي تعاقب الليل والنهار، واختلافهما طولا وقصرا، لدلائل وبراهين عظيمه على وحدانيه الله لاصحاب العقول السليمه."},{"id":"484","s":3,"a":191,"at":"الذين يذكرون الله قياما وقعودا وعلى جنوبهم ويتفكرون في خلق السموات والارض ربنا ما خلقت هذا باطلا سبحانك فقنا عذاب النار","dt":"[191] الذين يذكرون الله في جميع احوالهم: قياما وقعودا وعلى جنوبهم، وهم يتدبرون في خلق السموات والارض، قائلين: يا ربنا ما اوجدت هذا الخلق عبثا، فانت منزه عن ذلك، فاصرف عنا عذاب النار."},{"id":"485","s":3,"a":192,"at":"ربنا انك من تدخل النار فقد اخزيته وما للظالمين من انصار","dt":"[192] يا ربنا نجنا من النار، فانك -يا الله- من تدخله النار بذنوبه فقد فضحته واهنته، وما للمذنبين الظالمين لانفسهم من احد يدفع عنهم عقاب الله يوم القيامه."},{"id":"486","s":3,"a":193,"at":"ربنا اننا سمعنا مناديا ينادي للايمان ان امنوا بربكم فامنا ربنا فاغفر لنا ذنوبنا وكفر عنا سيئاتنا وتوفنا مع الابرار","dt":"[193] يا ربنا اننا سمعنا مناديا -هو نبيك محمد - صلى الله عليه وسلم- ينادي الناس للتصديق بك، والاقرار بوحدانيتك، والعمل بشرعك، فاجبنا دعوته وصدقنا رسالته، فاغفر لنا ذنوبنا، واستر عيوبنا، والحقنا بالصالحين."},{"id":"487","s":3,"a":194,"at":"ربنا واتنا ما وعدتنا على رسلك ولا تخزنا يوم القيامه انك لا تخلف الميعاد","dt":"[194] يا ربنا اعطنا ما وعدتنا على السنه رسلك من نصر وتمكين وتوفيق وهدايه، ولا تفضحنا بذنوبنا يوم القيامه، فانك كريم لا تخلف وعدا وعدت به عبادك."},{"id":"488","s":3,"a":195,"at":"فاستجاب لهم ربهم اني لا اضيع عمل عامل منكم من ذكر او انثى بعضكم من بعض فالذين هاجروا واخرجوا من ديارهم واوذوا في سبيلي وقاتلوا وقتلوا لاكفرن عنهم سيئاتهم ولادخلنهم جنات تجري من تحتها الانهار ثوابا من عند الله والله عنده حسن الثواب","dt":"[195] فاجاب الله دعاءهم بانه لا يضيع جهد من عمل منهم عملا صالحا، ذكرا كان او انثى، وهم في اخوه الدين وفي الطاعه وقبول الاعمال سواء، فالذين هاجروا رغبه في رضا الله تعالى، واخرجوا من ديارهم، واوذوا في طاعه ربهم وعبادتهم اياه، وقاتلوا وقتلوا في سبيل الله لاعلاء كلمته، ليسترن الله عليهم ما ارتكبوه من المعاصي، كما سترها عليهم في الدنيا، فلا يحاسبهم عليها، وليدخلنهم جنات تجري من تحت قصورها واشجارها الانهار جزاء من عند الله، والله عنده حسن الثواب."},{"id":"489","s":3,"a":196,"at":"لا يغرنك تقلب الذين كفروا في البلاد","dt":"[196] لا تغتر -ايها الرسول- بما عليه اهل الكفر بالله من بسطه في العيش، وسعه في الرزق، وانتقالهم من مكان الى مكان للتجارات وطلب الارباح والاموال، فعما قليل يزول هذا كله عنهم، ويصبحون مرتهنين باعمالهم السيئه."},{"id":"490","s":3,"a":197,"at":"متاع قليل ثم ماواهم جهنم وبئس المهاد","dt":"[197] متاع قليل زائل، ثم يكون مصيرهم يوم القيامه الى النار، وبئس الفراش."},{"id":"491","s":3,"a":198,"at":"لكن الذين اتقوا ربهم لهم جنات تجري من تحتها الانهار خالدين فيها نزلا من عند الله وما عند الله خير للابرار","dt":"[198] لكن الذين خافوا ربهم، وامتثلوا اوامره، واجتنبوا نواهيه، قد اعد الله لهم جنات تجري من تحت قصورها واشجارها الانهار، هي منزلهم الدائم لا يخرجون منه. وما عند الله اعظم وافضل لاهل الطاعه مما يتقلب فيه الذين كفروا من نعيم الدنيا."},{"id":"492","s":3,"a":199,"at":"وان من اهل الكتاب لمن يؤمن بالله وما انزل اليكم وما انزل اليهم خاشعين لله لا يشترون بايات الله ثمنا قليلا اولئك لهم اجرهم عند ربهم ان الله سريع الحساب","dt":"[199] وان بعضا من اهل الكتاب ليصدق بالله ربا واحدا والها معبودا، وبما انزل اليكم من هذا القران، وبما انزل اليهم من التوراه والانجيل متذللين لله، خاضعين له، لا يشترون بايات الله ثمنا قليلا من حطام الدنيا، ولا يكتمون ما انزل الله، ولا يحرفونه كغيرهم من اهل الكتاب. اولئك لهم ثواب عظيم عند ربهم يوم يلقونه، فيوفيهم اياه غير منقوص. ان الله سريع الحساب، لا يعجزه احصاء اعمالهم، ومحاسبتهم عليها."},{"id":"493","s":3,"a":200,"at":"ياايها الذين امنوا اصبروا وصابروا ورابطوا واتقوا الله لعلكم تفلحون","dt":"[200] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه اصبروا على طاعه ربكم، وعلى ما ينزل بكم من ضر وبلاء، وغالبوا اعداءكم في الصبر حتى لا يكونوا اشد صبرا منكم، واقيموا على جهاد عدوي وعدوكم، وخافوا الله في جميع احوالكم؛ رجاء ان تفوزوا برضاه في الدنيا والاخره."},{"id":"494","s":4,"a":1,"at":"ياايها الناس اتقوا ربكم الذي خلقكم من نفس واحده وخلق منها زوجها وبث منهما رجالا كثيرا ونساء واتقوا الله الذي تساءلون به والارحام ان الله كان عليكم رقيبا","dt":"[1] يا ايها الناس خافوا الله والتزموا اوامره، واجتنبوا نواهيه؛ فهو الذي خلقكم من نفس واحده هي ادم عليه السلام، وخلق منها زوجها وهي حواء، ونشر منهما في انحاء الارض رجالا كثيرا ونساء كثيرات، وراقبوا الله الذي يسال به بعضكم بعضا، واحذروا ان تقطعوا ارحامكم. ان الله مراقب لجميع احوالكم."},{"id":"495","s":4,"a":2,"at":"واتوا اليتامى اموالهم ولا تتبدلوا الخبيث بالطيب ولا تاكلوا اموالهم الى اموالكم انه كان حوبا كبيرا","dt":"[2] واعطوا من مات اباؤهم وهم دون البلوغ -وكنتم عليهم اوصياء- اموالهم اذا وصلوا سن البلوغ، ورايتم منهم قدره على حفظ اموالهم، ولا تاخذوا الجيد من اموالهم، وتجعلوا مكانه الرديء من اموالكم، ولا تخلطوا اموالهم باموالكم؛ لتحتالوا بذلك على اكل اموالهم. ان من تجرا على ذلك فقد ارتكب اثما عظيما."},{"id":"496","s":4,"a":3,"at":"وان خفتم الا تقسطوا في اليتامى فانكحوا ما طاب لكم من النساء مثنى وثلاث ورباع فان خفتم الا تعدلوا فواحده او ما ملكت ايمانكم ذلك ادنى الا تعولوا","dt":"[3] وان خفتم الا تعدلوا في يتامى النساء اللاتي تحت ايديكم بان لا تعطوهن مهورهن كغيرهن، فاتركوهن وانكحوا ما طاب لكم من النساء من غيرهن: اثنتين او ثلاثا او اربعا، فان خشيتم الا تعدلوا بينهن فاكتفوا بواحده، او بما عندكم من الاماء. ذلك الذي شرعته لكم في اليتيمات والزواج من واحده الى اربع، او الاقتصار على واحده او ملك اليمين، اقرب الى عدم الجور والتعدي."},{"id":"497","s":4,"a":4,"at":"واتوا النساء صدقاتهن نحله فان طبن لكم عن شيء منه نفسا فكلوه هنيئا مريئا","dt":"[4] واعطوا -ايها الازواج- النساء مهورهن، عطيه واجبه وفريضه لازمه عن طيب نفس منكم. فان طابت انفسهن لكم عن شيء من المهر فوهبنه لكم فخذوه، وتصرفوا فيه، فهو حلال طيب."},{"id":"498","s":4,"a":5,"at":"ولا تؤتوا السفهاء اموالكم التي جعل الله لكم قياما وارزقوهم فيها واكسوهم وقولوا لهم قولا معروفا","dt":"[5] ولا تؤتوا -ايها الاولياء- من يبذر من الرجال والنساء والصبيان اموالهم التي تحت ايديكم فيضعوها في غير وجهها، فهذه الاموال هي التي عليها قيام حياه الناس، وانفقوا عليهم منها واكسوهم، وقولوا لهم قولا معروفا من الكلام الطيب والخلق الحسن."},{"id":"499","s":4,"a":6,"at":"وابتلوا اليتامى حتى اذا بلغوا النكاح فان انستم منهم رشدا فادفعوا اليهم اموالهم ولا تاكلوها اسرافا وبدارا ان يكبروا ومن كان غنيا فليستعفف ومن كان فقيرا فلياكل بالمعروف فاذا دفعتم اليهم اموالهم فاشهدوا عليهم وكفى بالله حسيبا","dt":"[6] واختبروا من تحت ايديكم من اليتامى لمعرفه قدرتهم على حسن التصرف في اموالهم، حتى اذا وصلوا الى سن البلوغ، وعلمتم منهم صلاحا في دينهم، وقدره على حفظ اموالهم، فسلموها لهم، ولا تعتدوا عليها بانفاقها في غير موضعها اسرافا ومبادره لاكلها قبل ان يكبروا فياخذوها منكم. ومن كان صاحب مال منكم فليستعفف بغناه، ولا ياخذ من مال اليتيم شيئا، ومن كان فقيرا فلياخذ بقدر حاجته عند الضروره. فاذا علمتم انهم قادرون على حفظ اموالهم بعد بلوغهم الحلم وسلمتموها اليهم، فاشهدوا عليهم؛ ضمانا لوصول حقهم كاملا اليهم؛ ولئلا ينكروا ذلك. ويكفيكم ان الله شاهد عليكم، ومحاسب لكم على ما فعلتم."},{"id":"500","s":4,"a":7,"at":"للرجال نصيب مما ترك الوالدان والاقربون وللنساء نصيب مما ترك الوالدان والاقربون مما قل منه او كثر نصيبا مفروضا","dt":"[7] للذكور -صغارا او كبارا- نصيب شرعه الله فيما تركه الوالدان والاقربون من المال، قليلا كان او كثيرا، في انصبه محدده واضحه فرضها الله عز وجل لهؤلاء، وللنساء كذلك."},{"id":"501","s":4,"a":8,"at":"واذا حضر القسمه اولو القربى واليتامى والمساكين فارزقوهم منه وقولوا لهم قولا معروفا","dt":"[8] واذا حضر قسمه الميراث اقارب الميت ممن لا حق لهم في التركه، او حضرها من مات اباؤهم وهم صغار دون سن البلوغ، او من لا يملكون ما يكفيهم ويسد حاجتهم، فاعطوهم شيئا من المال على وجه الاستحباب قبل تقسيم التركه على اصحابها، وقولوا لهم قولا حسنا غير فاحش ولا قبيح."},{"id":"502","s":4,"a":9,"at":"وليخش الذين لو تركوا من خلفهم ذريه ضعافا خافوا عليهم فليتقوا الله وليقولوا قولا سديدا","dt":"[9] وليخف الذين لو ماتوا وتركوا من خلفهم ابناء صغارا ضعافا خافوا عليهم الظلم والضياع، فليراقبوا الله فيمن تحت ايديهم من اليتامى وغيرهم، وذلك بحفظ اموالهم، وحسن تربيتهم، ودفع الاذى عنهم، وليقولوا لهم قولا موافقا للعدل والمعروف."},{"id":"503","s":4,"a":10,"at":"ان الذين ياكلون اموال اليتامى ظلما انما ياكلون في بطونهم نارا وسيصلون سعيرا","dt":"[10] ان الذين يعتدون على اموال اليتامى، فياخذونها بغير حق، انما ياكلون نارا تتاجج في بطونهم يوم القيامه، وسيدخلون نارا يقاسون حرها."},{"id":"504","s":4,"a":11,"at":"يوصيكم الله في اولادكم للذكر مثل حظ الانثيين فان كن نساء فوق اثنتين فلهن ثلثا ما ترك وان كانت واحده فلها النصف ولابويه لكل واحد منهما السدس مما ترك ان كان له ولد فان لم يكن له ولد وورثه ابواه فلامه الثلث فان كان له اخوه فلامه السدس من بعد وصيه يوصي بها او دين اباؤكم وابناؤكم لا تدرون ايهم اقرب لكم نفعا فريضه من الله ان الله كان عليما حكيما","dt":"[11] يوصيكم الله ويامركم في شان اولادكم: اذا مات احد منكم وترك اولادا: ذكورا واناثا، فميراثه كله لهم: للذكر مثل نصيب الانثيين، اذا لم يكن هناك وارث غيرهم. فان ترك بنات فقط فللبنتين فاكثر ثلثا ما ترك، وان كانت ابنه واحده، فلها النصف. ولوالدي الميت لكل واحد منهما السدس ان كان له ولد: ذكرا كان او انثى، واحدا او اكثر. فان لم يكن له ولد وورثه والداه فلامه الثلث ولابيه الباقي. فان كان للميت اخوه اثنان فاكثر، ذكورا كانوا او اناثا، فلامه السدس، وللاب الباقي ولا شيء للاخوه. وهذا التقسيم للتركه انما يكون بعد اخراج وصيه الميت في حدود الثلث، او اخراج ما عليه من دين. اباؤكم وابناؤكم الذين فرض لهم الارث لا تعرفون ايهم اقرب لكم نفعا في دنياكم واخراكم، فلا تفضلوا واحدا منهم على الاخر. هذا الذي اوصيتكم به مفروض عليكم من الله. ان الله كان عليما بخلقه، حكيما فيما شرعه لهم."},{"id":"505","s":4,"a":12,"at":"ولكم نصف ما ترك ازواجكم ان لم يكن لهن ولد فان كان لهن ولد فلكم الربع مما تركن من بعد وصيه يوصين بها او دين ولهن الربع مما تركتم ان لم يكن لكم ولد فان كان لكم ولد فلهن الثمن مما تركتم من بعد وصيه توصون بها او دين وان كان رجل يورث كلاله او امراه وله اخ او اخت فلكل واحد منهما السدس فان كانوا اكثر من ذلك فهم شركاء في الثلث من بعد وصيه يوصى بها او دين غير مضار وصيه من الله والله عليم حليم","dt":"[12] ولكم -ايها الرجال- نصف ما ترك ازواجكم بعد وفاتهن ان لم يكن لهن ولد، ذكرا كان او انثى، فان كان لهن ولد فلكم الربع مما تركن، ترثونه من بعد انفاذ وصيتهن الجائزه، او ما يكون عليهن من دين لمستحقيه. ولازواجكم -ايها الرجال- الربع مما تركتم، ان لم يكن لكم ابن او ابنه منهن او من غيرهن، فان كان لكم ابن او ابنه فلهن الثمن مما تركتم، يقسم الربع او الثمن بينهن، فان كانت زوجه واحده كان هذا ميراثا لها، من بعد انفاذ ما كنتم اوصيتم به من الوصايا الجائزه، او قضاء ما يكون عليكم من دين. وان مات رجل او امراه وليس له او لها ولد ولا والد، وله او لها اخ او اخت من ام فلكل واحد منهما السدس. فان كان الاخوه او الاخوات لام اكثر من ذلك فهم شركاء في الثلث يقسم بينهم بالسويه لا فرق بين الذكر والانثى، وهذا الذي فرضه الله للاخوه والاخوات لام ياخذونه ميراثا لهم، من بعد انفاذ وصيته ان كان قد اوصى بشيء، او قضاء ديون الميت، لا ضرر فيه على الورثه. بهذا اوصاكم ربكم وصيه نافعه لكم. والله عليم بما يصلح خلقه، حليم لا يعاجلهم بالعقوبه."},{"id":"506","s":4,"a":13,"at":"تلك حدود الله ومن يطع الله ورسوله يدخله جنات تجري من تحتها الانهار خالدين فيها وذلك الفوز العظيم","dt":"[13] تلك الاحكام الالهيه التي شرعها الله في اليتامى والنساء والمواريث، شرائعه الداله على انها من عند الله العليم الحكيم. ومن يطع الله ورسوله فيما شرع لعباده من هذه الاحكام وغيرها، يدخله جنات كثيره الاشجار والقصور، تجري من تحتها الانهار بمياهها العذبه، وهم باقون في هذا النعيم، لا يخرجون منه، وذلك الثواب هو الفلاح العظيم."},{"id":"507","s":4,"a":14,"at":"ومن يعص الله ورسوله ويتعد حدوده يدخله نارا خالدا فيها وله عذاب مهين","dt":"[14] ومن يعص الله ورسوله، بانكاره لاحكام الله، وتجاوزه ما شرعه الله لعباده بتغييرها، او تعطيل العمل بها، يدخله نارا ماكثا فيها، وله عذاب يخزيه ويهينه."},{"id":"508","s":4,"a":15,"at":"واللاتي ياتين الفاحشه من نسائكم فاستشهدوا عليهن اربعه منكم فان شهدوا فامسكوهن في البيوت حتى يتوفاهن الموت او يجعل الله لهن سبيلا","dt":"[15] واللاتي يزنين من نسائكم، فاستشهدوا -ايها الولاه والقضاه- عليهن اربعه رجال عدول من المسلمين، فان شهدوا عليهن بذلك فاحبسوهن في البيوت حتى تنتهي حياتهن بالموت، او يجعل الله لهن طريقا للخلاص من ذلك."},{"id":"509","s":4,"a":16,"at":"واللذان ياتيانها منكم فاذوهما فان تابا واصلحا فاعرضوا عنهما ان الله كان توابا رحيما","dt":"[16] واللذان يقعان في فاحشه الزنى، فاذوهما بالضرب والهجر والتوبيخ، فان تابا عما وقع منهما واصلحا بما يقدمان من الاعمال الصالحه فاصفحوا عن اذاهما. ويستفاد من هذه الايه والتي قبلها ان الرجال اذا فعلوا الفاحشه يؤذون، والنساء يحبسن ويؤذين، فالحبس غايته الموت، والاذيه نهايتها الى التوبه والصلاح. وكان هذا في صدر الاسلام، ثم نسخ بما شرع الله ورسوله، وهو الرجم للمحصن والمحصنه، وهما الحران البالغان العاقلان، اللذان جامعا في نكاح صحيح، والجلد مائه جلده، وتغريب عام لغيرهما. ان الله كان توابا على عباده التائبين، رحيما بهم."},{"id":"510","s":4,"a":17,"at":"انما التوبه على الله للذين يعملون السوء بجهاله ثم يتوبون من قريب فاولئك يتوب الله عليهم وكان الله عليما حكيما","dt":"[17] انما يقبل الله التوبه من الذين يرتكبون المعاصي والذنوب بجهل منهم لعاقبتها، وايجابها لسخط الله، وبغفله منهم او ضعف يقين -فكل عاص لله، مخطئا او متعمدا، فهو جاهل بهذا الاعتبار، وان كان عالما بالتحريم- ثم يرجعون الى ربهم بالانابه والطاعه قبل معاينه الموت، فاولئك يقبل الله توبتهم. وكان الله عليما بخلقه، حكيما في تدبيره وتقديره."},{"id":"511","s":4,"a":18,"at":"وليست التوبه للذين يعملون السيئات حتى اذا حضر احدهم الموت قال اني تبت الان ولا الذين يموتون وهم كفار اولئك اعتدنا لهم عذابا اليما","dt":"[18] وليس قبول التوبه للذين يصرون على ارتكاب المعاصي، ولا يرجعون الى ربهم الى ان تاتيهم سكرات الموت، فيقول احدهم: اني تبت الان، كما لا تقبل توبه الذين يموتون وهم جاحدون، منكرون لوحدانيه الله ورساله رسوله محمد -صلى الله عليه وسلم-. اولئك المصرون على المعاصي الى ان ماتوا، والجاحدون الذين يموتون وهم كفار، اعتدنا لهم عذابا موجعا."},{"id":"512","s":4,"a":19,"at":"ياايها الذين امنوا لا يحل لكم ان ترثوا النساء كرها ولا تعضلوهن لتذهبوا ببعض ما اتيتموهن الا ان ياتين بفاحشه مبينه وعاشروهن بالمعروف فان كرهتموهن فعسى ان تكرهوا شيئا ويجعل الله فيه خيرا كثيرا","dt":"[19] يا ايها الذين امنوا لا يجوز لكم ان تجعلوا نساء ابائكم من جمله تركتهم، تتصرفون فيهن بالزواج منهن، او المنع لهن، او تزويجهن للاخرين، وهن كارهات لذلك كله، ولا يجوز لكم ان تضاروا ازواجكم وانتم كارهون لهن؛ ليتنازلن عن بعض ما اتيتموهن من مهر ونحوه، الا ان يرتكبن امرا فاحشا كالزنى، فلكم حينئذ امساكهن حتى تاخذوا ما اعطيتموهن. ولتكن مصاحبتكم لنسائكم مبنيه على التكريم والمحبه، واداء ما لهن من حقوق. فان كرهتموهن لسبب من الاسباب الدنيويه فاصبروا؛ فعسى ان تكرهوا امرا من الامور ويكون فيه خير كثير."},{"id":"513","s":4,"a":20,"at":"وان اردتم استبدال زوج مكان زوج واتيتم احداهن قنطارا فلا تاخذوا منه شيئا اتاخذونه بهتانا واثما مبينا","dt":"[20] وان اردتم استبدال زوجه مكان اخرى، وكنتم قد اعطيتم من تريدون طلاقها مالا كثيرا مهرا لها، فلا يحل لكم ان تاخذوا منه شيئا، اتاخذونه كذبا وافتراء واضحا؟"},{"id":"514","s":4,"a":21,"at":"وكيف تاخذونه وقد افضى بعضكم الى بعض واخذن منكم ميثاقا غليظا","dt":"[21] وكيف يحل لكم ان تاخذوا ما اعطيتموهن من مهر، وقد استمتع كل منكما بالاخر بالجماع، واخذن منكم ميثاقا غليظا من امساكهن بمعروف او تسريحهن باحسان؟"},{"id":"515","s":4,"a":22,"at":"ولا تنكحوا ما نكح اباؤكم من النساء الا ما قد سلف انه كان فاحشه ومقتا وساء سبيلا","dt":"[22] ولا تتزوجوا من تزوجه اباؤكم من النساء الا ما قد مضى منكم في الجاهليه فلا مؤاخذه فيه. ان زواج الابناء من زوجات ابائهم امر قبيح يفحش ويعظم قبحه، وبغيض يمقت الله فاعله، وبئس طريقا ومنهجا ما كنتم تفعلونه في جاهليتكم."},{"id":"516","s":4,"a":23,"at":"حرمت عليكم امهاتكم وبناتكم واخواتكم وعماتكم وخالاتكم وبنات الاخ وبنات الاخت وامهاتكم اللاتي ارضعنكم واخواتكم من الرضاعه وامهات نسائكم وربائبكم اللاتي في حجوركم من نسائكم اللاتي دخلتم بهن فان لم تكونوا دخلتم بهن فلا جناح عليكم وحلائل ابنائكم الذين من اصلابكم وان تجمعوا بين الاختين الا ما قد سلف ان الله كان غفورا رحيما","dt":"[23] حرم الله عليكم نكاح امهاتكم، ويدخل في ذلك الجدات من جهه الاب او الام، وبناتكم: ويشمل بنات الاولاد وان نزلن، واخواتكم الشقيقات او لاب او لام، وعماتكم: اخوات ابائكم واجدادكم، وخالاتكم: اخوات امهاتكم وجداتكم، وبنات الاخ، وبنات الاخت: ويدخل في ذلك اولادهن، وامهاتكم اللاتي ارضعنكم، واخواتكم من الرضاعه -وقد حرم رسول الله -صلى الله عليه وسلم- من الرضاع ما يحرم من النسب- وامهات نسائكم، سواء دخلتم بنسائكم، ام لم تدخلوا بهن، وبنات نسائكم من غيركم اللاتي يتربين غالبا في بيوتكم وتحت رعايتكم، وهن محرمات وان لم يكن في حجوركم، ولكن بشرط الدخول بامهاتهن، فان لم تكونوا دخلتم بامهاتهن وطلقتموهن او متن قبل الدخول فلا جناح عليكم ان تنكحوهن، كما حرم الله عليكم ان تنكحوا زوجات ابنائكم الذين من اصلابكم، ومن الحق بهم من ابنائكم من الرضاع، وهذا التحريم يكون بالعقد عليها، دخل الابن بها ام لم يدخل، وحرم عليكم كذلك الجمع في وقت واحد بين الاختين بنسب او رضاع الا ما قد مضى منكم في الجاهليه. ولا يجوز كذلك الجمع بين المراه وعمتها او خالتها كما جاء في السنه. ان الله كان غفورا للمذنبين اذا تابوا، رحيما بهم، فلا يكلفهم ما لا يطيقون."},{"id":"517","s":4,"a":24,"at":"والمحصنات من النساء الا ما ملكت ايمانكم كتاب الله عليكم واحل لكم ما وراء ذلكم ان تبتغوا باموالكم محصنين غير مسافحين فما استمتعتم به منهن فاتوهن اجورهن فريضه ولا جناح عليكم فيما تراضيتم به من بعد الفريضه ان الله كان عليما حكيما","dt":"[24] ويحرم عليكم نكاح المتزوجات من النساء، الا من سبيتم منهن في الجهاد، فانه يحل لكم نكاحهن، بعد استبراء ارحامهن بحيضه، كتب الله عليكم تحريم نكاح هؤلاء، واجاز لكم نكاح من سواهن، مما احله الله لكم ان تطلبوا باموالكم العفه عن اقتراف الحرام. فما استمتعتم به منهن بالنكاح الصحيح، فاعطوهن مهورهن، التي فرض الله لهن عليكم، ولا اثم عليكم فيما تم التراضي به بينكم، من الزياده او النقصان في المهر، بعد ثبوت الفريضه. ان الله تعالى كان عليما بامور عباده، حكيما في احكامه وتدبيره."},{"id":"518","s":4,"a":25,"at":"ومن لم يستطع منكم طولا ان ينكح المحصنات المؤمنات فمن ما ملكت ايمانكم من فتياتكم المؤمنات والله اعلم بايمانكم بعضكم من بعض فانكحوهن باذن اهلهن واتوهن اجورهن بالمعروف محصنات غير مسافحات ولا متخذات اخدان فاذا احصن فان اتين بفاحشه فعليهن نصف ما على المحصنات من العذاب ذلك لمن خشي العنت منكم وان تصبروا خير لكم والله غفور رحيم","dt":"[25] ومن لا قدره له على مهور الحرائر المؤمنات، فله ان ينكح غيرهن، من فتياتكم المؤمنات المملوكات. والله تعالى هو العليم بحقيقه ايمانكم، بعضكم من بعض، فكلكم من نفس واحده، واخوه في الدين، فتزوجوهن بموافقه اهلهن، واعطوهن مهورهن على ما تراضيتم به عن طيب نفس منكم، متعففات عن الحرام، غير مجاهرات بالزنى، ولا مسرات به باتخاذ اخلاء، فاذا تزوجن واتين بفاحشه الزنى فعليهن من الحد -وهو الجلد لا الرجم- نصف ما على الحرائر. ذلك الذي ابيح من نكاح الاماء بالصفه المتقدمه انما ابيح لمن خاف على نفسه الوقوع في الزنى، وشق عليه الصبر عن الجماع، والصبر عن نكاح الاماء مع العفه اولى وافضل. والله تعالى غفور لكم، رحيم بكم اذ اذن لكم في نكاحهن عند العجز عن نكاح الحرائر."},{"id":"519","s":4,"a":26,"at":"يريد الله ليبين لكم ويهديكم سنن الذين من قبلكم ويتوب عليكم والله عليم حكيم","dt":"[26] يريد الله تعالى بهذه التشريعات، ان يوضح لكم معالم دينه القويم، وشرعه الحكيم، ويدلكم على طرق الانبياء والصالحين من قبلكم في الحلال والحرام، ويتوب عليكم بالرجوع بكم الى الطاعات، وهو سبحانه عليم بما يصلح شان عباده، حكيم فيما شرعه لكم."},{"id":"520","s":4,"a":27,"at":"والله يريد ان يتوب عليكم ويريد الذين يتبعون الشهوات ان تميلوا ميلا عظيما","dt":"[27] والله يريد ان يتوب عليكم، ويتجاوز عن خطاياكم، ويريد الذين ينقادون لشهواتهم وملذاتهم ان تنحرفوا عن الدين انحرافا كبيرا."},{"id":"521","s":4,"a":28,"at":"يريد الله ان يخفف عنكم وخلق الانسان ضعيفا","dt":"[28] يريد الله تعالى بما شرعه لكم التيسير، وعدم التشديد عليكم؛ لانكم خلقتم ضعفاء."},{"id":"522","s":4,"a":29,"at":"ياايها الذين امنوا لا تاكلوا اموالكم بينكم بالباطل الا ان تكون تجاره عن تراض منكم ولا تقتلوا انفسكم ان الله كان بكم رحيما","dt":"[29] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، لا يحل لكم ان ياكل بعضكم مال بعض بغير حق، الا ان يكون وفق الشرع والكسب الحلال عن تراض منكم، ولا يقتل بعضكم بعضا فتهلكوا انفسكم بارتكاب محارم الله ومعاصيه. ان الله كان بكم رحيما في كل ما امركم به، ونهاكم عنه."},{"id":"523","s":4,"a":30,"at":"ومن يفعل ذلك عدوانا وظلما فسوف نصليه نارا وكان ذلك على الله يسيرا","dt":"[30] ومن يرتكب ما نهى الله عنه من اخذ المال الحرام كالسرقه والغصب والغش معتديا متجاوزا حد الشرع، فسوف يدخله الله نارا يقاسي حرها، وكان ذلك على الله يسيرا."},{"id":"524","s":4,"a":31,"at":"ان تجتنبوا كبائر ما تنهون عنه نكفر عنكم سيئاتكم وندخلكم مدخلا كريما","dt":"[31] ان تبتعدوا -ايها المؤمنون- عن كبائر الذنوب كالاشراك بالله وعقوق الوالدين وقتل النفس بغير الحق وغير ذلك، نكفر عنكم ما دونها من الصغائر، وندخلكم مدخلا كريما، وهو الجنه."},{"id":"525","s":4,"a":32,"at":"ولا تتمنوا ما فضل الله به بعضكم على بعض للرجال نصيب مما اكتسبوا وللنساء نصيب مما اكتسبن واسالوا الله من فضله ان الله كان بكل شيء عليما","dt":"[32] ولا تتمنوا ما فضل الله به بعضكم على بعض، في المواهب والارزاق وغير ذلك، فقد جعل الله للرجال نصيبا مقدرا من الجزاء بحسب عملهم، وجعل للنساء نصيبا مما عملن، واسالوا الله الكريم الوهاب يعطكم من فضله بدلا من التمني. ان الله كان بكل شيء عليما، وهو اعلم بما يصلح عباده فيما قسمه لهم من خير."},{"id":"526","s":4,"a":33,"at":"ولكل جعلنا موالي مما ترك الوالدان والاقربون والذين عقدت ايمانكم فاتوهم نصيبهم ان الله كان على كل شيء شهيدا","dt":"[33] ولكل واحد منكم جعلنا ورثه يرثون مما ترك الوالدان والاقربون، والذين تحالفتم معهم بالايمان المؤكده على النصره واعطائهم شيئا من الميراث فاعطوهم ما قدر لهم. والميراث بالتحالف كان في اول الاسلام، ثم رفع حكمه بنزول ايات المواريث. ان الله كان مطلعا على كل شيء من اعمالكم، وسيجازيكم على ذلك."},{"id":"527","s":4,"a":34,"at":"الرجال قوامون على النساء بما فضل الله بعضهم على بعض وبما انفقوا من اموالهم فالصالحات قانتات حافظات للغيب بما حفظ الله واللاتي تخافون نشوزهن فعظوهن واهجروهن في المضاجع واضربوهن فان اطعنكم فلا تبغوا عليهن سبيلا ان الله كان عليا كبيرا","dt":"[34] الرجال قوامون على توجيه النساء ورعايتهن، بما خصهم الله به من خصائص القوامه والتفضيل، وبما اعطوهن من المهور والنفقات. فالصالحات المستقيمات على شرع الله منهن، مطيعات لله تعالى ولازواجهن، حافظات لكل ما غاب عن علم ازواجهن بما اؤتمن عليه بحفظ الله وتوفيقه، واللاتي تخشون منهن ترفعهن عن طاعتكم، فانصحوهن بالكلمه الطيبه، فان لم تثمر معهن الكلمه الطيبه، فاهجروهن في الفراش، ولا تقربوهن، فان لم يؤثر فعل الهجران فيهن، فاضربوهن ضربا لا ضرر فيه، فان اطعنكم فاحذروا ظلمهن، فان الله العلي الكبير وليهن، وهو منتقم ممن ظلمهن وبغى عليهن."},{"id":"528","s":4,"a":35,"at":"وان خفتم شقاق بينهما فابعثوا حكما من اهله وحكما من اهلها ان يريدا اصلاحا يوفق الله بينهما ان الله كان عليما خبيرا","dt":"[35] وان علمتم -يا اولياء الزوجين- شقاقا بينهما يؤدي الى الفراق، فارسلوا اليهما حكما عدلا من اهل الزوج، وحكما عدلا من اهل الزوجه؛ لينظرا ويحكما بما فيه المصلحه لهما، وبسبب رغبه الحكمين في الاصلاح، واستعمالهما الاسلوب الطيب يوفق الله بين الزوجين. ان الله تعالى عليم، لا يخفى عليه شيء من امر عباده، خبير بما تنطوي عليه نفوسهم."},{"id":"529","s":4,"a":36,"at":"واعبدوا الله ولا تشركوا به شيئا وبالوالدين احسانا وبذي القربى واليتامى والمساكين والجار ذي القربى والجار الجنب والصاحب بالجنب وابن السبيل وما ملكت ايمانكم ان الله لا يحب من كان مختالا فخورا","dt":"[36] واعبدوا الله وانقادوا له وحده، ولا تجعلوا له شريكا في الربوبيه والعباده، واحسنوا الى الوالدين، وادوا حقوقهما، وحقوق الاقربين، والاولاد الذين مات اباؤهم وهم دون سن البلوغ، والمحتاجين الذين لا يملكون ما يكفيهم ويسد حاجتهم، والجار القريب منكم والبعيد، والرفيق في السفر وفي الحضر، والمسافر المحتاج، والمماليك من فتيانكم وفتياتكم. ان الله تعالى لا يحب المتكبرين من عباده، المفتخرين على الناس."},{"id":"530","s":4,"a":37,"at":"الذين يبخلون ويامرون الناس بالبخل ويكتمون ما اتاهم الله من فضله واعتدنا للكافرين عذابا مهينا","dt":"[37] الذين يمتنعون عن الانفاق والعطاء مما رزقهم الله، ويامرون غيرهم بالبخل، ويجحدون نعم الله عليهم، ويخفون فضله وعطاءه. واعددنا للجاحدين عذابا مخزيا."},{"id":"531","s":4,"a":38,"at":"والذين ينفقون اموالهم رئاء الناس ولا يؤمنون بالله ولا باليوم الاخر ومن يكن الشيطان له قرينا فساء قرينا","dt":"[38] واعتدنا هذا العذاب كذلك للذين ينفقون اموالهم رياء وسمعه، ولا يصدقون بالله اعتقادا وعملا ولا بيوم القيامه. وهذه الاعمال السيئه مما يدعو اليها الشيطان. ومن يكن الشيطان له ملازما فبئس الملازم والقرين."},{"id":"532","s":4,"a":39,"at":"وماذا عليهم لو امنوا بالله واليوم الاخر وانفقوا مما رزقهم الله وكان الله بهم عليما","dt":"[39] واي ضرر يلحقهم لو صدقوا بالله واليوم الاخر اعتقادا وعملا، وانفقوا مما اعطاهم الله باحتساب واخلاص، والله تعالى عليم بهم وبما يعملون، وسيحاسبهم على ذلك."},{"id":"533","s":4,"a":40,"at":"ان الله لا يظلم مثقال ذره وان تك حسنه يضاعفها ويؤت من لدنه اجرا عظيما","dt":"[40] ان الله تعالى لا ينقص احدا من جزاء عمله مقدار ذره، وان تكن زنه الذره حسنه فانه سبحانه يزيدها ويكثرها لصاحبها، ويتفضل عليه بالمزيد، فيعطيه من عنده ثوابا كبيرا هو الجنه."},{"id":"534","s":4,"a":41,"at":"فكيف اذا جئنا من كل امه بشهيد وجئنا بك على هؤلاء شهيدا","dt":"[41] فكيف يكون حال الناس يوم القيامه، اذا جاء الله من كل امه برسولها ليشهد عليها بما عملت، وجاء بك -ايها الرسول- لتكون شهيدا على امتك انك بلغتهم رساله ربك؟"},{"id":"535","s":4,"a":42,"at":"يومئذ يود الذين كفروا وعصوا الرسول لو تسوى بهم الارض ولا يكتمون الله حديثا","dt":"[42] يوم يكون ذلك، يتمنى الذين كفروا بالله تعالى وخالفوا الرسول ولم يطيعوه، لو يجعلهم الله والارض سواء، فيصيرون ترابا، حتى لا يبعثوا وهم لا يستطيعون ان يخفوا عن الله شيئا مما في انفسهم؛ اذ ختم الله على افواههم، وشهدت عليهم جوارحهم بما كانوا يعملون."},{"id":"536","s":4,"a":43,"at":"ياايها الذين امنوا لا تقربوا الصلاه وانتم سكارى حتى تعلموا ما تقولون ولا جنبا الا عابري سبيل حتى تغتسلوا وان كنتم مرضى او على سفر او جاء احد منكم من الغائط او لامستم النساء فلم تجدوا ماء فتيمموا صعيدا طيبا فامسحوا بوجوهكم وايديكم ان الله كان عفوا غفورا","dt":"[43] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، لا تقربوا الصلاه ولا تقوموا اليها حال السكر حتى تميزوا وتعلموا ما تقولون (وقد كان هذا قبل التحريم القاطع للخمر في كل حال)، ولا تقربوا الصلاه ان اصابكم الحدث الاكبر، ولا تقربوا كذلك مواضعها وهي المساجد، الا من كان منكم مجتازا من باب الى باب، حتى تتطهروا بالاغتسال. وان كنتم في حال مرض لا تقدرون معه على استعمال الماء، او حال سفر، او جاء احد منكم من الغائط، او جامعتم النساء، فلم تجدوا ماء للطهاره فاقصدوا ترابا طاهرا، فامسحوا بوجوهكم وايديكم منه. ان الله تعالى كان كثير العفو يتجاوز عن سيئاتكم، ويسترها عليكم."},{"id":"537","s":4,"a":44,"at":"الم تر الى الذين اوتوا نصيبا من الكتاب يشترون الضلاله ويريدون ان تضلوا السبيل","dt":"[44] الم تعلم -ايها الرسول- امر اليهود الذين اعطوا حظا من العلم مما جاءهم من التوراه، يستبدلون الضلاله بالهدى، ويتركون ما لديهم من الحجج والبراهين، الداله على صدق رساله الرسول محمد -صلى الله عليه وسلم-، ويتمنون لكم -ايها المؤمنون المهتدون- ان تنحرفوا عن الطريق المستقيم؛ لتكونوا ضالين مثلهم."},{"id":"538","s":4,"a":45,"at":"والله اعلم باعدائكم وكفى بالله وليا وكفى بالله نصيرا","dt":"[45] والله سبحانه وتعالى اعلم منكم -ايها المؤمنون- بعداوه هؤلاء اليهود لكم، وكفى بالله وليا يتولاكم، وكفى به نصيرا ينصركم على اعدائكم."},{"id":"539","s":4,"a":46,"at":"من الذين هادوا يحرفون الكلم عن مواضعه ويقولون سمعنا وعصينا واسمع غير مسمع وراعنا ليا بالسنتهم وطعنا في الدين ولو انهم قالوا سمعنا واطعنا واسمع وانظرنا لكان خيرا لهم واقوم ولكن لعنهم الله بكفرهم فلا يؤمنون الا قليلا","dt":"[46] من اليهود فريق دابوا على تبديل كلام الله وتغييره عما هو عليه افتراء على الله، ويقولون للرسول -صلى الله عليه وسلم-: سمعنا قولك وعصينا امرك واسمع منا لا سمعت، ويقولون: راعنا سمعك اي: افهم عنا وافهمنا، يلوون السنتهم بذلك، وهم يريدون الدعاء عليه بالرعونه حسب لغتهم، والطعن في دين الاسلام. ولو انهم قالوا: سمعنا واطعنا، بدل و«عصينا»، واسمع دون «غير مسمع»، وانظرنا بدل «راعنا» لكان ذلك خيرا لهم عند الله واعدل قولا، ولكن الله طردهم من رحمته؛ بسبب كفرهم وجحودهم نبوه محمد -صلى الله عليه وسلم-، فلا يصدقون بالحق الا تصديقا قليلا لا ينفعهم."},{"id":"540","s":4,"a":47,"at":"ياايها الذين اوتوا الكتاب امنوا بما نزلنا مصدقا لما معكم من قبل ان نطمس وجوها فنردها على ادبارها او نلعنهم كما لعنا اصحاب السبت وكان امر الله مفعولا","dt":"[47] يا اهل الكتاب، صدقوا واعملوا بما نزلنا من القران، مصدقا لما معكم من الكتب من قبل ان ناخذكم بسوء صنيعكم، فنمحو الوجوه ونحولها قبل الظهور، او نلعن هؤلاء المفسدين بمسخهم قرده وخنازير، كما لعنا اليهود من اصحاب السبت، الذين نهوا عن الصيد فيه فلم ينتهوا، فغضب الله عليهم، وطردهم من رحمته، وكان امر الله نافذا في كل حال."},{"id":"541","s":4,"a":48,"at":"ان الله لا يغفر ان يشرك به ويغفر ما دون ذلك لمن يشاء ومن يشرك بالله فقد افترى اثما عظيما","dt":"[48] ان الله تعالى لا يغفر ولا يتجاوز عمن اشرك به احدا من مخلوقاته، او كفر باي نوع من انواع الكفر الاكبر، ويتجاوز ويعفو عما دون الشرك من الذنوب، لمن يشاء من عباده، ومن يشرك بالله غيره فقد اختلق ذنبا عظيما."},{"id":"542","s":4,"a":49,"at":"الم تر الى الذين يزكون انفسهم بل الله يزكي من يشاء ولا يظلمون فتيلا","dt":"[49] الم تعلم -ايها الرسول- امر اولئك الذين يثنون على انفسهم واعمالهم، ويصفونها بالطهر والبعد عن السوء؟ بل الله تعالى وحده هو الذي يثني على من يشاء من عباده، لعلمه بحقيقه اعمالهم، ولا ينقصون من اعمالهم شيئا مقدار الخيط الذي يكون في شق نواه التمره."},{"id":"543","s":4,"a":50,"at":"انظر كيف يفترون على الله الكذب وكفى به اثما مبينا","dt":"[50] انظر اليهم -ايها الرسول- متعجبا من امرهم، كيف يختلقون على الله الكذب، وهو المنزه عن كل ما لا يليق به؟ وكفى بهذا الاختلاق ذنبا كبيرا كاشفا عن فساد معتقدهم."},{"id":"544","s":4,"a":51,"at":"الم تر الى الذين اوتوا نصيبا من الكتاب يؤمنون بالجبت والطاغوت ويقولون للذين كفروا هؤلاء اهدى من الذين امنوا سبيلا","dt":"[51] الم تعلم -ايها الرسول- امر اولئك اليهود الذين اعطوا حظا من العلم، يصدقون بكل ما يعبد من دون الله من الاصنام وشياطين الانس والجن، تصديقا يحملهم على التحاكم الى غير شرع الله، ويقولون للذين كفروا بالله تعالى وبرسوله محمد -صلى الله عليه وسلم-: هؤلاء الكافرون اقوم واعدل طريقا من اولئك الذين امنوا؟"},{"id":"545","s":4,"a":52,"at":"اولئك الذين لعنهم الله ومن يلعن الله فلن تجد له نصيرا","dt":"[52] اولئك الذين كثر فسادهم وعم ضلالهم، طردهم الله تعالى من رحمته، ومن يطرده الله من رحمته فلن تجد له من ينصره، ويدفع عنه سوء العذاب."},{"id":"546","s":4,"a":53,"at":"ام لهم نصيب من الملك فاذا لا يؤتون الناس نقيرا","dt":"[53] بل الهم حظ من الملك، ولو اوتوه لما اعطوا احدا منه شيئا، ولو كان مقدار النقره التي تكون في ظهر النواه؟"},{"id":"547","s":4,"a":54,"at":"ام يحسدون الناس على ما اتاهم الله من فضله فقد اتينا ال ابراهيم الكتاب والحكمه واتيناهم ملكا عظيما","dt":"[54] بل ايحسدون محمدا -صلى الله عليه وسلم- على ما اعطاه الله من نعمه النبوه والرساله، ويحسدون اصحابه على نعمه التوفيق الى الايمان، والتصديق بالرساله، واتباع الرسول، والتمكين في الارض، ويتمنون زوال هذا الفضل عنهم؟ فقد اعطينا ذريه ابراهيم عليه السلام -من قبل- الكتب، التي انزلها الله عليهم وما اوحي اليهم مما لم يكن كتابا مقروءا، واعطيناهم مع ذلك ملكا واسعا."},{"id":"548","s":4,"a":55,"at":"فمنهم من امن به ومنهم من صد عنه وكفى بجهنم سعيرا","dt":"[55] فمن هؤلاء الذين اوتوا حظا من العلم، من صدق برساله محمد -صلى الله عليه وسلم-، وعمل بشرعه، ومنهم من اعرض ولم يستجب لدعوته، ومنع الناس من اتباعه. وحسبكم -ايها المكذبون- نار جهنم تسعر بكم."},{"id":"549","s":4,"a":56,"at":"ان الذين كفروا باياتنا سوف نصليهم نارا كلما نضجت جلودهم بدلناهم جلودا غيرها ليذوقوا العذاب ان الله كان عزيزا حكيما","dt":"[56] ان الذين جحدوا ما انزل الله من اياته ووحي كتابه ودلائله وحججه، سوف ندخلهم نارا يقاسون حرها، كلما احترقت جلودهم بدلناهم جلودا اخرى؛ ليستمر عذابهم والمهم. ان الله تعالى كان عزيزا لا يمتنع عليه شيء، حكيما في تدبيره وقضائه."},{"id":"550","s":4,"a":57,"at":"والذين امنوا وعملوا الصالحات سندخلهم جنات تجري من تحتها الانهار خالدين فيها ابدا لهم فيها ازواج مطهره وندخلهم ظلا ظليلا","dt":"[57] والذين اطمانت قلوبهم بالايمان بالله تعالى والتصديق برساله رسوله محمد -صلى الله عليه وسلم-، واستقاموا على الطاعه، سندخلهم جنات تجري من تحت قصورها واشجارها الانهار، ينعمون فيها ابدا ولا يخرجون منها، ولهم فيها ازواج طهرها الله من كل اذى، وندخلهم ظلا كثيفا ممتدا في الجنه."},{"id":"551","s":4,"a":58,"at":"ان الله يامركم ان تؤدوا الامانات الى اهلها واذا حكمتم بين الناس ان تحكموا بالعدل ان الله نعما يعظكم به ان الله كان سميعا بصيرا","dt":"[58] ان الله تعالى يامركم باداء مختلف الامانات، التي اؤتمنتم عليها الى اصحابها، فلا تفرطوا فيها، ويامركم بالقضاء بين الناس بالعدل والقسط، اذا قضيتم بينهم، ونعم ما يعظكم الله به ويهديكم اليه. ان الله تعالى كان سميعا لاقوالكم، مطلعا على سائر اعمالكم، بصيرا بها."},{"id":"552","s":4,"a":59,"at":"ياايها الذين امنوا اطيعوا الله واطيعوا الرسول واولي الامر منكم فان تنازعتم في شيء فردوه الى الله والرسول ان كنتم تؤمنون بالله واليوم الاخر ذلك خير واحسن تاويلا","dt":"[59] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، استجيبوا لاوامر الله تعالى ولا تعصوه، واستجيبوا للرسول -صلى الله عليه وسلم- فيما جاء به من الحق، واطيعوا ولاه امركم في غير معصيه الله، فان اختلفتم في شيء بينكم، فارجعوا الحكم فيه الى كتاب الله تعالى وسنه رسوله محمد -صلى الله عليه وسلم-، ان كنتم تؤمنون حق الايمان بالله تعالى وبيوم الحساب. ذلك الرد الى الكتاب والسنه خير لكم من التنازع والقول بالراي، واحسن عاقبه ومالا."},{"id":"553","s":4,"a":60,"at":"الم تر الى الذين يزعمون انهم امنوا بما انزل اليك وما انزل من قبلك يريدون ان يتحاكموا الى الطاغوت وقد امروا ان يكفروا به ويريد الشيطان ان يضلهم ضلالا بعيدا","dt":"[60] الم تعلم -ايها الرسول- امر اولئك المنافقين الذين يدعون الايمان بما انزل اليك -وهو القران- وبما انزل الى الرسل من قبلك، وهم يريدون ان يتحاكموا في فصل الخصومات بينهم الى غير ما شرع الله من الباطل، وقد امروا ان يكفروا بالباطل؟ ويريد الشيطان ان يبعدهم عن طريق الحق بعدا شديدا. وفي هذه الايه دليل على ان الايمان الصادق، يقتضي الانقياد لشرع الله، والحكم به في كل امر من الامور، فمن زعم انه مؤمن واختار حكم الطاغوت على حكم الله، فهو كاذب في زعمه."},{"id":"554","s":4,"a":61,"at":"واذا قيل لهم تعالوا الى ما انزل الله والى الرسول رايت المنافقين يصدون عنك صدودا","dt":"[61] واذا نصح هؤلاء، وقيل لهم: تعالوا الى ما انزل الله، والى الرسول محمد -صلى الله عليه وسلم-، وهديه، ابصرت الذين يظهرون الايمان ويبطنون الكفر، يعرضون عنك اعراضا."},{"id":"555","s":4,"a":62,"at":"فكيف اذا اصابتهم مصيبه بما قدمت ايديهم ثم جاءوك يحلفون بالله ان اردنا الا احسانا وتوفيقا","dt":"[62] فكيف يكون حال اولئك المنافقين اذا حلت بهم مصيبه؛ بسبب ما اقترفوه بايديهم، ثم جاؤوك -ايها الرسول- يعتذرون، ويؤكدون لك انهم ما قصدوا باعمالهم تلك الا الاحسان والتوفيق بين الخصوم؟"},{"id":"556","s":4,"a":63,"at":"اولئك الذين يعلم الله ما في قلوبهم فاعرض عنهم وعظهم وقل لهم في انفسهم قولا بليغا","dt":"[63] اولئك هم الذين يعلم الله حقيقه ما في قلوبهم من النفاق، فتول عنهم، وحذرهم من سوء ما هم عليه، وقل لهم قولا مؤثرا فيهم زاجرا لهم."},{"id":"557","s":4,"a":64,"at":"وما ارسلنا من رسول الا ليطاع باذن الله ولو انهم اذ ظلموا انفسهم جاءوك فاستغفروا الله واستغفر لهم الرسول لوجدوا الله توابا رحيما","dt":"[64] وما بعثنا من رسول من رسلنا، الا ليستجاب له، بامر الله تعالى وقضائه. ولو ان هؤلاء الذين ظلموا انفسهم باقتراف السيئات، جاؤوك -ايها الرسول- في حياتك تائبين سائلين الله ان يغفر لهم ذنوبهم، واستغفرت لهم، لوجدوا الله توابا رحيما."},{"id":"558","s":4,"a":65,"at":"فلا وربك لا يؤمنون حتى يحكموك فيما شجر بينهم ثم لا يجدوا في انفسهم حرجا مما قضيت ويسلموا تسليما","dt":"[65] اقسم الله تعالى بنفسه الكريمه ان هؤلاء لا يؤمنون حقيقه حتى يجعلوك حكما فيما وقع بينهم من نزاع في حياتك، ويتحاكموا الى سنتك بعد مماتك، ثم لا يجدوا في انفسهم ضيقا مما انتهى اليه حكمك، وينقادوا مع ذلك انقيادا تاما، فالحكم بما جاء به رسول الله -صلى الله عليه وسلم- من الكتاب والسنه في كل شان من شؤون الحياه من صميم الايمان مع الرضا والتسليم."},{"id":"559","s":4,"a":66,"at":"ولو انا كتبنا عليهم ان اقتلوا انفسكم او اخرجوا من دياركم ما فعلوه الا قليل منهم ولو انهم فعلوا ما يوعظون به لكان خيرا لهم واشد تثبيتا","dt":"[66] ولو اوجبنا على هؤلاء المنافقين المتحاكمين الى الطاغوت ان يقتل بعضهم بعضا، او ان يخرجوا من ديارهم، ما استجاب لذلك الا عدد قليل منهم، ولو انهم استجابوا لما ينصحون به لكان ذلك نافعا لهم، واقوى لايمانهم،"},{"id":"560","s":4,"a":67,"at":"واذا لاتيناهم من لدنا اجرا عظيما","dt":"[67] ولاعطيناهم من عندنا ثوابا عظيما في الدنيا والاخره."},{"id":"561","s":4,"a":68,"at":"ولهديناهم صراطا مستقيما","dt":"[68] ولارشدناهم ووفقناهم الى طريق الله القويم"},{"id":"562","s":4,"a":69,"at":"ومن يطع الله والرسول فاولئك مع الذين انعم الله عليهم من النبيين والصديقين والشهداء والصالحين وحسن اولئك رفيقا","dt":"[69] ومن يستجب لاوامر الله تعالى وهدي رسوله محمد -صلى الله عليه وسلم- فاولئك الذين عظم شانهم وقدرهم، فكانوا في صحبه من انعم الله تعالى عليهم بالجنه، من الانبياء والصديقين الذين كمل تصديقهم بما جاءت به الرسل، اعتقادا وقولا وعملا، والشهداء في سبيل الله وصالح المؤمنين، وحسن هؤلاء رفقاء في الجنه."},{"id":"563","s":4,"a":70,"at":"ذلك الفضل من الله وكفى بالله عليما","dt":"[70] ذلك العطاء الجزيل من الله وحده. وكفى بالله عليما يعلم احوال عباده، ومن يستحق منهم الثواب الجزيل بما قام به من الاعمال الصالحه."},{"id":"564","s":4,"a":71,"at":"ياايها الذين امنوا خذوا حذركم فانفروا ثبات او انفروا جميعا","dt":"[71] يا ايها الذين امنوا خذوا حذركم بالاستعداد لعدوكم، فاخرجوا لملاقاته جماعه بعد جماعه او مجتمعين."},{"id":"565","s":4,"a":72,"at":"وان منكم لمن ليبطئن فان اصابتكم مصيبه قال قد انعم الله علي اذ لم اكن معهم شهيدا","dt":"[72] وان منكم لنفرا يتاخر عن الخروج لملاقاه الاعداء متثاقلا، ويثبط غيره عن عمد واصرار، فان قدر عليكم واصبتم بقتل وهزيمه، قال مستبشرا: قد حفظني الله، حين لم اكن حاضرا مع اولئك الذين وقع لهم ما اكرهه لنفسي، وسره تخلفه عنكم."},{"id":"566","s":4,"a":73,"at":"ولئن اصابكم فضل من الله ليقولن كان لم تكن بينكم وبينه موده ياليتني كنت معهم فافوز فوزا عظيما","dt":"[73] ولئن نالكم فضل من الله وغنيمه، ليقولن -حاسدا متحسرا، كان لم تكن بينكم وبينه موده في الظاهر-: يا ليتني كنت معهم فاظفر بما ظفروا به من النجاه والنصره والغنيمه."},{"id":"567","s":4,"a":74,"at":"فليقاتل في سبيل الله الذين يشرون الحياه الدنيا بالاخره ومن يقاتل في سبيل الله فيقتل او يغلب فسوف نؤتيه اجرا عظيما","dt":"[74] فليجاهد في سبيل نصره دين الله، واعلاء كلمته، الذين يبيعون الحياه الدنيا بالدار الاخره وثوابها. ومن يجاهد في سبيل الله مخلصا، فيقتل او يغلب، فسوف نؤتيه اجرا عظيما."},{"id":"568","s":4,"a":75,"at":"وما لكم لا تقاتلون في سبيل الله والمستضعفين من الرجال والنساء والولدان الذين يقولون ربنا اخرجنا من هذه القريه الظالم اهلها واجعل لنا من لدنك وليا واجعل لنا من لدنك نصيرا","dt":"[75] وما الذي يمنعكم -ايها المؤمنون- عن الجهاد في سبيل نصره دين الله، ونصره عباده المستضعفين من الرجال والنساء والصغار الذين اعتدي عليهم، ولا حيله لهم ولا وسيله لديهم الا الاستغاثه بربهم، يدعونه قائلين: ربنا اخرجنا من هذه القريه -يعني «مكه»- التي ظلم اهلها انفسهم بالكفر والمؤمنين بالاذى، واجعل لنا من عندك وليا يتولى امورنا، ونصيرا ينصرنا على الظالمين؟"},{"id":"569","s":4,"a":76,"at":"الذين امنوا يقاتلون في سبيل الله والذين كفروا يقاتلون في سبيل الطاغوت فقاتلوا اولياء الشيطان ان كيد الشيطان كان ضعيفا","dt":"[76] الذين صدقوا في ايمانهم اعتقادا وعملا يجاهدون في سبيل نصره الحق واهله، والذين كفروا يقاتلون في سبيل البغي والفساد في الارض، فقاتلوا ايها المؤمنون اهل الكفر والشرك الذين يتولون الشيطان، ويطيعون امره، ان تدبير الشيطان لاوليائه كان ضعيفا."},{"id":"570","s":4,"a":77,"at":"الم تر الى الذين قيل لهم كفوا ايديكم واقيموا الصلاه واتوا الزكاه فلما كتب عليهم القتال اذا فريق منهم يخشون الناس كخشيه الله او اشد خشيه وقالوا ربنا لم كتبت علينا القتال لولا اخرتنا الى اجل قريب قل متاع الدنيا قليل والاخره خير لمن اتقى ولا تظلمون فتيلا","dt":"[77] الم تعلم -ايها الرسول- امر اولئك الذين قيل لهم قبل الاذن بالجهاد: امنعوا ايديكم عن قتال اعدائكم من المشركين، وعليكم اداء ما فرضه الله عليكم من الصلاه والزكاه، فلما فرض عليهم القتال اذا جماعه منهم قد تغير حالهم، فاصبحوا يخافون الناس ويرهبونهم، كخوفهم من الله او اشد، ويعلنون عما اعتراهم من شده الخوف، فيقولون: ربنا لم اوجبت علينا القتال؟ هلا امهلتنا الى وقت قريب، رغبه منهم في متاع الحياه الدنيا، قل لهم -ايها الرسول-: متاع الدنيا قليل، والاخره وما فيها اعظم وابقى لمن اتقى، فعمل بما امر به، واجتنب ما نهي عنه. ولا يظلم ربك احدا شيئا، ولو كان مقدار الخيط الذي يكون في شق نواه التمره."},{"id":"571","s":4,"a":78,"at":"اينما تكونوا يدرككم الموت ولو كنتم في بروج مشيده وان تصبهم حسنه يقولوا هذه من عند الله وان تصبهم سيئه يقولوا هذه من عندك قل كل من عند الله فمال هؤلاء القوم لا يكادون يفقهون حديثا","dt":"[78] اينما تكونوا يلحقكم الموت في اي مكان كنتم فيه عند حلول اجالكم، ولو كنتم في حصون منيعه بعيده عن ساحه المعارك والقتال. وان يحصل لهم ما يسرهم من متاع هذه الحياه، ينسبوا حصوله الى الله تعالى، وان يقع عليهم ما يكرهونه ينسبوه الى الرسول محمد -صلى الله عليه وسلم- جهاله وتشاؤما، وما علموا ان ذلك كله من عند الله وحده، بقضائه وقدره، فما بالهم لا يقاربون فهم اي حديث تحدثهم به؟"},{"id":"572","s":4,"a":79,"at":"ما اصابك من حسنه فمن الله وما اصابك من سيئه فمن نفسك وارسلناك للناس رسولا وكفى بالله شهيدا","dt":"[79] ما اصابك -ايها الانسان- من خير ونعمه فهو من الله تعالى وحده، فضلا واحسانا، وما اصابك من جهد وشده فبسبب عملك السيئ، وما اقترفته يداك من الخطايا والسيئات. وبعثناك -ايها الرسول- لعموم الناس رسولا تبلغهم رساله ربك، وكفى بالله شهيدا على صدق رسالتك."},{"id":"573","s":4,"a":80,"at":"من يطع الرسول فقد اطاع الله ومن تولى فما ارسلناك عليهم حفيظا","dt":"[80] من يستجب للرسول -صلى الله عليه وسلم-، ويعمل بهديه، فقد استجاب لله تعالى وامتثل امره، ومن اعرض عن طاعه الله ورسوله فما بعثناك -ايها الرسول- على هؤلاء المعرضين رقيبا تحفظ اعمالهم وتحاسبهم عليها، فحسابهم علينا."},{"id":"574","s":4,"a":81,"at":"ويقولون طاعه فاذا برزوا من عندك بيت طائفه منهم غير الذي تقول والله يكتب ما يبيتون فاعرض عنهم وتوكل على الله وكفى بالله وكيلا","dt":"[81] ويظهر هؤلاء المعرضون -وهم في مجلس رسول الله صلى الله عليه وسلم- طاعتهم للرسول وما جاء به، فاذا ابتعدوا عنه وانصرفوا عن مجلسه، دبر جماعه منهم ليلا غير ما اعلنوه من الطاعه، وما علموا ان الله يحصي عليهم ما يدبرون، وسيجازيهم عليه اتم الجزاء، فتول عنهم -ايها الرسول- ولا تبال بهم، فانهم لن يضروك، وتوكل على الله، وحسبك به وليا وناصرا."},{"id":"575","s":4,"a":82,"at":"افلا يتدبرون القران ولو كان من عند غير الله لوجدوا فيه اختلافا كثيرا","dt":"[82] افلا ينظر هؤلاء في القران، وما جاء به من الحق، نظر تامل وتدبر، حيث جاء على نسق محكم يقطع بانه من عند الله وحده؟ ولو كان من عند غيره لوجدوا فيه اختلافا كثيرا."},{"id":"576","s":4,"a":83,"at":"واذا جاءهم امر من الامن او الخوف اذاعوا به ولو ردوه الى الرسول والى اولي الامر منهم لعلمه الذين يستنبطونه منهم ولولا فضل الله عليكم ورحمته لاتبعتم الشيطان الا قليلا","dt":"[83] واذا جاء هؤلاء الذين لم يستقر الايمان في قلوبهم امر يجب كتمانه، متعلقا بالامن الذي يعود خيره على الاسلام والمسلمين، او بالخوف الذي يلقي في قلوبهم عدم الاطمئنان، افشوه واذاعوا به في الناس، ولو رد هؤلاء ما جاءهم الى رسول الله -صلى الله عليه وسلم- والى اهل العلم والفقه لعلم حقيقه معناه اهل الاستنباط منهم. ولولا ان تفضل الله عليكم ورحمكم لاتبعتم الشيطان ووساوسه الا قليلا منكم."},{"id":"577","s":4,"a":84,"at":"فقاتل في سبيل الله لا تكلف الا نفسك وحرض المؤمنين عسى الله ان يكف باس الذين كفروا والله اشد باسا واشد تنكيلا","dt":"[84] فجاهد -ايها النبي- في سبيل الله واعلاء كلمته، لا تلزم فعل غيرك ولا تؤاخذ به، وحض المؤمنين على القتال والجهاد، ورغبهم فيه، لعل الله يمنع بك وبهم باس الكافرين وشدتهم. والله تعالى اشد قوه واعظم عقوبه للكافرين."},{"id":"578","s":4,"a":85,"at":"من يشفع شفاعه حسنه يكن له نصيب منها ومن يشفع شفاعه سيئه يكن له كفل منها وكان الله على كل شيء مقيتا","dt":"[85] من يسع لحصول غيره على الخير يكن له بشفاعته نصيب من الثواب، ومن يسع لايصال الشر الى غيره يكن له نصيب من الوزر والاثم. وكان الله على كل شيء شاهدا وحفيظا."},{"id":"579","s":4,"a":86,"at":"واذا حييتم بتحيه فحيوا باحسن منها او ردوها ان الله كان على كل شيء حسيبا","dt":"[86] واذا سلم عليكم المسلم فردوا عليه بافضل مما سلم لفظا وبشاشه، او ردوا عليه بمثل ما سلم ، ولكل ثوابه وجزاؤه. ان الله تعالى كان على كل شيء مجازيا."},{"id":"580","s":4,"a":87,"at":"الله لا اله الا هو ليجمعنكم الى يوم القيامه لا ريب فيه ومن اصدق من الله حديثا","dt":"[87] الله وحده المتفرد بالالوهيه لجميع الخلق، ليجمعنكم يوم القيامه، الذي لا شك فيه؛ للحساب والجزاء. ولا احد اصدق من الله حديثا فيما اخبر به."},{"id":"581","s":4,"a":88,"at":"فما لكم في المنافقين فئتين والله اركسهم بما كسبوا اتريدون ان تهدوا من اضل الله ومن يضلل الله فلن تجد له سبيلا","dt":"[88] فما لكم -ايها المؤمنون- في شان المنافقين اذ اختلفتم فرقتين: فرقه تقول بقتالهم واخرى لا تقول بذلك؟ والله تعالى قد اوقعهم في الكفر والضلال بسبب سوء اعمالهم. اتودون هدايه من صرف الله تعالى قلبه عن دينه؟ ومن خذله الله عن دينه، واتباع ما امره به، فلا طريق له الى الهدى."},{"id":"582","s":4,"a":89,"at":"ودوا لو تكفرون كما كفروا فتكونون سواء فلا تتخذوا منهم اولياء حتى يهاجروا في سبيل الله فان تولوا فخذوهم واقتلوهم حيث وجدتموهم ولا تتخذوا منهم وليا ولا نصيرا","dt":"[89] تمنى المنافقون لكم -ايها المؤمنون- لو تنكرون حقيقه ما امنت به قلوبكم، مثلما انكروه بقلوبهم، فتكونون معهم في الانكار سواء، فلا تتخذوا منهم اصفياء لكم، حتى يهاجروا في سبيل الله، برهانا على صدق ايمانهم، فان اعرضوا عما دعوا اليه، فخذوهم اينما كانوا واقتلوهم، ولا تتخذوا منهم وليا من دون الله ولا نصيرا تستنصرون به."},{"id":"583","s":4,"a":90,"at":"الا الذين يصلون الى قوم بينكم وبينهم ميثاق او جاءوكم حصرت صدورهم ان يقاتلوكم او يقاتلوا قومهم ولو شاء الله لسلطهم عليكم فلقاتلوكم فان اعتزلوكم فلم يقاتلوكم والقوا اليكم السلم فما جعل الله لكم عليهم سبيلا","dt":"[90] لكن الذين يتصلون بقوم بينكم وبينهم عهد وميثاق فلا تقاتلوهم، وكذلك الذين اتوا اليكم وقد ضاقت صدورهم وكرهوا ان يقاتلوكم، كما كرهوا ان يقاتلوا قومهم، فلم يكونوا معكم ولا مع قومهم، فلا تقاتلوهم، ولو شاء الله تعالى لسلطهم عليكم، فلقاتلوكم مع اعدائكم من المشركين، ولكن الله تعالى صرفهم عنكم بفضله وقدرته، فان تركوكم فلم يقاتلوكم، وانقادوا اليكم مستسلمين، فليس لكم عليهم من طريق لقتالهم."},{"id":"584","s":4,"a":91,"at":"ستجدون اخرين يريدون ان يامنوكم ويامنوا قومهم كل ما ردوا الى الفتنه اركسوا فيها فان لم يعتزلوكم ويلقوا اليكم السلم ويكفوا ايديهم فخذوهم واقتلوهم حيث ثقفتموهم واولئكم جعلنا لكم عليهم سلطانا مبينا","dt":"[91] ستجدون قوما اخرين من المنافقين يودون الاطمئنان على انفسهم من جانبكم، فيظهرون لكم الايمان، ويودون الاطمئنان على انفسهم من جانب قومهم الكافرين، فيظهرون لهم الكفر، كلما اعيدوا الى موطن الكفر والكافرين، وقعوا في اسوا حال. فهؤلاء ان لم ينصرفوا عنكم، ويقدموا اليكم الاستسلام التام، ويمنعوا انفسهم عن قتالكم فخذوهم بقوه واقتلوهم اينما كانوا، واولئك الذين بلغوا في هذا المسلك السيئ حدا يميزهم عمن عداهم، فهم الذين جعلنا لكم الحجه البينه على قتلهم واسرهم."},{"id":"585","s":4,"a":92,"at":"وما كان لمؤمن ان يقتل مؤمنا الا خطا ومن قتل مؤمنا خطا فتحرير رقبه مؤمنه وديه مسلمه الى اهله الا ان يصدقوا فان كان من قوم عدو لكم وهو مؤمن فتحرير رقبه مؤمنه وان كان من قوم بينكم وبينهم ميثاق فديه مسلمه الى اهله وتحرير رقبه مؤمنه فمن لم يجد فصيام شهرين متتابعين توبه من الله وكان الله عليما حكيما","dt":"[92] ولا يحق لمؤمن الاعتداء على اخيه المؤمن وقتله بغير حق، الا ان يقع منه ذلك على وجه الخطا الذي لا عمد فيه، ومن وقع منه ذلك الخطا فعليه عتق رقبه مؤمنه، وتسليم ديه مقدره الى اوليائه، الا ان يتصدقوا بها عليه ويعفوا عنه. فان كان المقتول من قوم كفار اعداء للمؤمنين، وهو مؤمن بالله تعالى، وبما انزل من الحق على رسوله محمد -صلى الله عليه وسلم-، فعلى قاتله عتق رقبه مؤمنه، وان كان من قوم بينكم وبينهم عهد وميثاق، فعلى قاتله ديه تسلم الى اوليائه وعتق رقبه مؤمنه، فمن لم يجد القدره على عتق رقبه مؤمنه، فعليه صيام شهرين متتابعين؛ ليتوب الله تعالى عليه. وكان الله تعالى عليما بحقيقه شان عباده، حكيما فيما شرعه لهم."},{"id":"586","s":4,"a":93,"at":"ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خالدا فيها وغضب الله عليه ولعنه واعد له عذابا عظيما","dt":"[93] ومن يعتد على مؤمن فيقتله عن عمد بغير حق فعاقبته جهنم خالدا فيها، مع سخط الله تعالى عليه وطرده من رحمته ان جازاه على ذنبه، واعد الله له اشد العذاب؛ بسبب ما ارتكبه من هذه الجنايه العظيمه، ولكن الله سبحانه يعفو ويتفضل على اهل الايمان، فلا يجازيهم بالخلود في جهنم."},{"id":"587","s":4,"a":94,"at":"ياايها الذين امنوا اذا ضربتم في سبيل الله فتبينوا ولا تقولوا لمن القى اليكم السلام لست مؤمنا تبتغون عرض الحياه الدنيا فعند الله مغانم كثيره كذلك كنتم من قبل فمن الله عليكم فتبينوا ان الله كان بما تعملون خبيرا","dt":"[94] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه اذا خرجتم في الارض مجاهدين في سبيل الله فكونوا على بينه مما تاتون وتتركون، ولا تنفوا الايمان عمن بدا منه شيء من علامات الاسلام ولم يقاتلكم؛ لاحتمال ان يكون مؤمنا يخفي ايمانه، طالبين بذلك متاع الحياه الدنيا، والله تعالى عنده من الفضل والعطاء ما يغنيكم به، كذلك كنتم في بدء الاسلام تخفون ايمانكم عن قومكم من المشركين فمن الله عليكم، واعزكم بالايمان والقوه، فكونوا على بينه ومعرفه في اموركم. ان الله تعالى عليم بكل اعمالكم، مطلع على دقائق اموركم، وسيجازيكم عليها."},{"id":"588","s":4,"a":95,"at":"لا يستوي القاعدون من المؤمنين غير اولي الضرر والمجاهدون في سبيل الله باموالهم وانفسهم فضل الله المجاهدين باموالهم وانفسهم على القاعدين درجه وكلا وعد الله الحسنى وفضل الله المجاهدين على القاعدين اجرا عظيما","dt":"[95] لا يتساوى المتخلفون عن الجهاد في سبيل الله -غير اصحاب الاعذار منهم- والمجاهدون في سبيل الله باموالهم وانفسهم، فضل الله تعالى المجاهدين على القاعدين، ورفع منزلتهم درجه عاليه في الجنه، وقد وعد الله كلا من المجاهدين باموالهم وانفسهم والقاعدين من اهل الاعذار الجنه، لما بذلوا وضحوا في سبيل الحق، وفضل الله تعالى المجاهدين على القاعدين ثوابا جزيلا."},{"id":"589","s":4,"a":96,"at":"درجات منه ومغفره ورحمه وكان الله غفورا رحيما","dt":"[96] هذا الثواب الجزيل منازل عاليه في الجنات من الله تعالى لخاصه عباده المجاهدين في سبيله، ومغفره لذنوبهم ورحمه واسعه ينعمون فيها. وكان الله غفورا لمن تاب اليه واناب، رحيما باهل طاعته، المجاهدين في سبيله."},{"id":"590","s":4,"a":97,"at":"ان الذين توفاهم الملائكه ظالمي انفسهم قالوا فيم كنتم قالوا كنا مستضعفين في الارض قالوا الم تكن ارض الله واسعه فتهاجروا فيها فاولئك ماواهم جهنم وساءت مصيرا","dt":"[97] ان الذين توفاهم الملائكه وقد ظلموا انفسهم بقعودهم في دار الكفر وترك الهجره، تقول لهم الملائكه توبيخا لهم: في اي شيء كنتم من امر دينكم؟ فيقولون: كنا ضعفاء في ارضنا، عاجزين عن دفع الظلم والقهر عنا، فيقولون لهم توبيخا: الم تكن ارض الله واسعه فتخرجوا من ارضكم الى ارض اخرى بحيث تامنون على دينكم؟ فاولئك مثواهم النار، وقبح هذا المرجع والماب."},{"id":"591","s":4,"a":98,"at":"الا المستضعفين من الرجال والنساء والولدان لا يستطيعون حيله ولا يهتدون سبيلا","dt":"[98] ويعذر من ذاك المصير العجزه من الرجال والنساء والصغار، الذين لا يقدرون على دفع القهر والظلم عنهم، ولا يعرفون طريقا يخلصهم مما هم فيه من المعاناه."},{"id":"592","s":4,"a":99,"at":"فاولئك عسى الله ان يعفو عنهم وكان الله عفوا غفورا","dt":"[99] فهؤلاء الضعفاء هم الذين يرجى لهم من الله تعالى العفو؛ لعلمه تعالى بحقيقه امرهم. وكان الله كثير العفو يتجاوز عن سيئاتهم، ويسترها عليهم."},{"id":"593","s":4,"a":100,"at":"ومن يهاجر في سبيل الله يجد في الارض مراغما كثيرا وسعه ومن يخرج من بيته مهاجرا الى الله ورسوله ثم يدركه الموت فقد وقع اجره على الله وكان الله غفورا رحيما","dt":"[100] ومن يخرج من ارض الشرك الى ارض الاسلام فرارا بدينه، راجيا فضل ربه، قاصدا نصره دينه، يجد في الارض مكانا ومتحولا ينعم فيه بما يكون سببا في قوته وذله اعدائه، مع السعه في رزقه وعيشه، ومن يخرج من بيته قاصدا نصره دين الله ورسوله -صلى الله عليه وسلم-، واعلاء كلمه الله، ثم يدركه الموت قبل بلوغه مقصده، فقد ثبت له جزاء عمله على الله، فضلا منه واحسانا. وكان الله غفورا رحيما بعباده."},{"id":"594","s":4,"a":101,"at":"واذا ضربتم في الارض فليس عليكم جناح ان تقصروا من الصلاه ان خفتم ان يفتنكم الذين كفروا ان الكافرين كانوا لكم عدوا مبينا","dt":"[101] واذا سافرتم -ايها المؤمنون- في ارض الله، فلا حرج ولا اثم عليكم في قصر الصلاه ان خفتم من عدوان الكفار عليكم في حال صلاتكم، وكانت غالب اسفار المسلمين في بدء الاسلام مخوفه، والقصر رخصه في السفر حال الامن او الخوف. ان الكافرين مجاهرون لكم بعداوتهم، فاحذروهم."},{"id":"595","s":4,"a":102,"at":"واذا كنت فيهم فاقمت لهم الصلاه فلتقم طائفه منهم معك ولياخذوا اسلحتهم فاذا سجدوا فليكونوا من ورائكم ولتات طائفه اخرى لم يصلوا فليصلوا معك ولياخذوا حذرهم واسلحتهم ود الذين كفروا لو تغفلون عن اسلحتكم وامتعتكم فيميلون عليكم ميله واحده ولا جناح عليكم ان كان بكم اذى من مطر او كنتم مرضى ان تضعوا اسلحتكم وخذوا حذركم ان الله اعد للكافرين عذابا مهينا","dt":"[102] واذا كنت -ايها النبي- في ساحه القتال، فاردت ان تصلي بهم، فلتقم جماعه منهم معك للصلاه، ولياخذوا سلاحهم، فاذا سجد هؤلاء فلتكن الجماعه الاخرى من خلفكم في مواجهه عدوكم، وتتم الجماعه الاولى ركعتهم الثانيه ويسلمون، ثم تاتي الجماعه الاخرى التي لم تبدا الصلاه فلياتموا بك في ركعتهم الاولى، ثم يكملوا بانفسهم ركعتهم الثانيه، وليحذروا من عدوهم ولياخذوا اسلحتهم. ود الجاحدون لدين الله ان تغفلوا عن سلاحكم وزادكم؛ ليحملوا عليكم حمله واحده فيقضوا عليكم، ولا اثم عليكم حينئذ ان كان بكم اذى من مطر، او كنتم في حال مرض ان تتركوا اسلحتكم، مع اخذ الحذر. ان الله تعالى اعد للجاحدين لدينه عذابا يهينهم، ويخزيهم."},{"id":"596","s":4,"a":103,"at":"فاذا قضيتم الصلاه فاذكروا الله قياما وقعودا وعلى جنوبكم فاذا اطماننتم فاقيموا الصلاه ان الصلاه كانت على المؤمنين كتابا موقوتا","dt":"[103] فاذا اديتم الصلاه، فاديموا ذكر الله في جميع احوالكم، فاذا زال الخوف فادوا الصلاه كامله، ولا تفرطوا فيها فانها واجبه في اوقات معلومه في الشرع."},{"id":"597","s":4,"a":104,"at":"ولا تهنوا في ابتغاء القوم ان تكونوا تالمون فانهم يالمون كما تالمون وترجون من الله ما لا يرجون وكان الله عليما حكيما","dt":"[104] ولا تضعفوا في طلب عدوكم وقتاله، ان تكونوا تتالمون من القتال واثاره، فاعداؤكم كذلك يتالمون منه اشد الالم، ومع ذلك لا يكفون عن قتالكم، فانتم اولى بذلك منهم؛ لما ترجونه من الثواب والنصر والتاييد، وهم لا يرجون ذلك. وكان الله عليما بكل احوالكم، حكيما في امره وتدبيره."},{"id":"598","s":4,"a":105,"at":"انا انزلنا اليك الكتاب بالحق لتحكم بين الناس بما اراك الله ولا تكن للخائنين خصيما","dt":"[105] انا انزلنا اليك -ايها الرسول- القران مشتملا على الحق؛ لتفصل بين الناس جميعا بما اوحى الله اليك، وبصرك به، فلا تكن للذين يخونون انفسهم -بكتمان الحق- مدافعا عنهم؛ بما ابدوه لك من القول المخالف للحقيقه."},{"id":"599","s":4,"a":106,"at":"واستغفر الله ان الله كان غفورا رحيما","dt":"[106] واطلب من الله تعالى المغفره في جميع احوالك، ان الله تعالى كان غفورا لمن يرجو فضله ونوال مغفرته، رحيما به."},{"id":"600","s":4,"a":107,"at":"ولا تجادل عن الذين يختانون انفسهم ان الله لا يحب من كان خوانا اثيما","dt":"[107] ولا تدافع عن الذين يخونون انفسهم بمعصيه الله. ان الله -سبحانه- لا يحب من عظمت خيانته، وكثر ذنبه."},{"id":"601","s":4,"a":108,"at":"يستخفون من الناس ولا يستخفون من الله وهو معهم اذ يبيتون ما لا يرضى من القول وكان الله بما يعملون محيطا","dt":"[108] يستترون من الناس خوفا من اطلاعهم على اعمالهم السيئه، ولا يستترون من الله تعالى ولا يستحيون منه، وهو عز شانه معهم بعلمه، مطلع عليهم حين يدبرون -ليلا- ما لا يرضى من القول، وكان الله -تعالى- محيطا بجميع اقوالهم وافعالهم، لا يخفى عليه منها شيء."},{"id":"602","s":4,"a":109,"at":"ها انتم هؤلاء جادلتم عنهم في الحياه الدنيا فمن يجادل الله عنهم يوم القيامه ام من يكون عليهم وكيلا","dt":"[109] ها انتم -ايها المؤمنون- قد حاججتم عن هؤلاء الخائنين لانفسهم في هذه الحياه الدنيا، فمن يحاجج الله تعالى عنهم يوم البعث والحساب؟ ومن ذا الذي يكون على هؤلاء الخائنين وكيلا يوم القيامه؟"},{"id":"603","s":4,"a":110,"at":"ومن يعمل سوءا او يظلم نفسه ثم يستغفر الله يجد الله غفورا رحيما","dt":"[110] ومن يقدم على عمل سيئ قبيح، او يظلم نفسه بارتكاب ما يخالف حكم الله وشرعه، ثم يرجع الى الله نادما على ما عمل، راجيا مغفرته وستر ذنبه، يجد الله تعالى غفورا له، رحيما به."},{"id":"604","s":4,"a":111,"at":"ومن يكسب اثما فانما يكسبه على نفسه وكان الله عليما حكيما","dt":"[111] ومن يعمد الى ارتكاب ذنب فانما يضر بذلك نفسه وحدها، وكان الله تعالى عليما بحقيقه امر عباده، حكيما فيما يقضي به بين خلقه."},{"id":"605","s":4,"a":112,"at":"ومن يكسب خطيئه او اثما ثم يرم به بريئا فقد احتمل بهتانا واثما مبينا","dt":"[112] ومن يعمل خطيئه بغير عمد، او يرتكب ذنبا متعمدا ثم يقذف بما ارتكبه نفسا بريئه لا جنايه لها، فقد تحمل كذبا وذنبا بينا."},{"id":"606","s":4,"a":113,"at":"ولولا فضل الله عليك ورحمته لهمت طائفه منهم ان يضلوك وما يضلون الا انفسهم وما يضرونك من شيء وانزل الله عليك الكتاب والحكمه وعلمك ما لم تكن تعلم وكان فضل الله عليك عظيما","dt":"[113] ولولا ان الله تعالى قد من عليك -ايها الرسول- ورحمك بنعمه النبوه، فعصمك بتوفيقه بما اوحى اليك، لعزمت جماعه من الذين يخونون انفسهم ان يزلوك عن طريق الحق، وما يزلون بذلك الا انفسهم، وما يقدرون على ايذائك لعصمه الله لك، وانزل الله عليك القران والسنه المبينه له، وهداك الى علم ما لم تكن تعلمه من قبل، وكان ما خصك الله به من فضل امرا عظيما."},{"id":"607","s":4,"a":114,"at":"لا خير في كثير من نجواهم الا من امر بصدقه او معروف او اصلاح بين الناس ومن يفعل ذلك ابتغاء مرضات الله فسوف نؤتيه اجرا عظيما","dt":"[114] لا نفع في كثير من كلام الناس سرا فيما بينهم، الا اذا كان حديثا داعيا الى بذل المعروف من الصدقه، او الكلمه الطيبه، او التوفيق بين الناس، ومن يفعل تلك الامور طلبا لرضا الله تعالى راجيا ثوابه، فسوف نؤتيه ثوابا جزيلا واسعا."},{"id":"608","s":4,"a":115,"at":"ومن يشاقق الرسول من بعد ما تبين له الهدى ويتبع غير سبيل المؤمنين نوله ما تولى ونصله جهنم وساءت مصيرا","dt":"[115] ومن يخالف الرسول -صلى الله عليه وسلم- من بعد ما ظهر له الحق، ويسلك طريقا غير طريق المؤمنين، وما هم عليه من الحق، نتركه وما توجه اليه، فلا نوفقه للخير، وندخله نار جهنم يقاسي حرها، وبئس هذا المرجع والمال."},{"id":"609","s":4,"a":116,"at":"ان الله لا يغفر ان يشرك به ويغفر ما دون ذلك لمن يشاء ومن يشرك بالله فقد ضل ضلالا بعيدا","dt":"[116] ان الله تعالى لا يغفر ان يشرك به، ويغفر ما دون الشرك من الذنوب لمن يشاء من عباده. ومن يجعل لله تعالى الواحد الاحد شريكا من خلقه، فقد بعد عن الحق بعدا كبيرا."},{"id":"610","s":4,"a":117,"at":"ان يدعون من دونه الا اناثا وان يدعون الا شيطانا مريدا","dt":"[117] ما يعبد المشركون من دون الله تعالى الا اوثانا لا تنفع ولا تضر، وما يعبدون الا شيطانا متمردا على الله، بلغ في الفساد والافساد حدا كبيرا."},{"id":"611","s":4,"a":118,"at":"لعنه الله وقال لاتخذن من عبادك نصيبا مفروضا","dt":"[118] طرده الله تعالى من رحمته. وقال الشيطان: لاتخذن من عبادك جزءا معلوما في اغوائهم قولا وعملا."},{"id":"612","s":4,"a":119,"at":"ولاضلنهم ولامنينهم ولامرنهم فليبتكن اذان الانعام ولامرنهم فليغيرن خلق الله ومن يتخذ الشيطان وليا من دون الله فقد خسر خسرانا مبينا","dt":"[119] ولاصرفن من تبعني منهم عن الحق، ولاعدنهم بالاماني الكاذبه، ولادعونهم الى تقطيع اذان الانعام وتشقيقها لما ازينه لهم من الباطل، ولادعونهم الى تغيير خلق الله في الفطره، وهيئه ما عليه الخلق. ومن يستجب للشيطان ويتخذه ناصرا له من دون الله القوي العزيز، فقد هلك هلاكا بينا."},{"id":"613","s":4,"a":120,"at":"يعدهم ويمنيهم وما يعدهم الشيطان الا غرورا","dt":"[120] يعد الشيطان اتباعه بالوعود الكاذبه، ويغريهم بالاماني الباطله الخادعه، وما يعدهم الا خديعه لا صحه لها، ولا دليل عليها."},{"id":"614","s":4,"a":121,"at":"اولئك ماواهم جهنم ولا يجدون عنها محيصا","dt":"[121] اولئك مالهم جهنم، ولا يجدون عنها معدلا ولا ملجا."},{"id":"615","s":4,"a":122,"at":"والذين امنوا وعملوا الصالحات سندخلهم جنات تجري من تحتها الانهار خالدين فيها ابدا وعد الله حقا ومن اصدق من الله قيلا","dt":"[122] والذين صدقوا في ايمانهم بالله تعالى، واتبعوا الايمان بالاعمال الصالحه سيدخلهم الله -بفضله- جنات تجري من تحت قصورها واشجارها الانهار ماكثين فيها ابدا، وعدا من الله تعالى الذي لا يخلف وعده. ولا احد اصدق من الله تعالى في قوله ووعده."},{"id":"616","s":4,"a":123,"at":"ليس بامانيكم ولا اماني اهل الكتاب من يعمل سوءا يجز به ولا يجد له من دون الله وليا ولا نصيرا","dt":"[123] لا ينال هذا الفضل العظيم بالاماني التي تتمنونها ايها المسلمون، ولا باماني اهل الكتاب من اليهود والنصارى، وانما ينال بالايمان الصادق بالله تعالى، واحسان العمل الذي يرضيه. ومن يعمل عملا سيئا يجز به، ولا يجد له سوى الله تعالى وليا يتولى امره وشانه، ولا نصيرا ينصره، ويدفع عنه سوء العذاب."},{"id":"617","s":4,"a":124,"at":"ومن يعمل من الصالحات من ذكر او انثى وهو مؤمن فاولئك يدخلون الجنه ولا يظلمون نقيرا","dt":"[124] ومن يعمل من الاعمال الصالحه من ذكر او انثى، وهو مؤمن بالله تعالى وبما انزل من الحق، فاولئك يدخلهم الله الجنه دار النعيم المقيم، ولا ينقصون من ثواب اعمالهم شيئا، ولو كان مقدار النقره في ظهر النواه."},{"id":"618","s":4,"a":125,"at":"ومن احسن دينا ممن اسلم وجهه لله وهو محسن واتبع مله ابراهيم حنيفا واتخذ الله ابراهيم خليلا","dt":"[125] لا احد احسن دينا ممن انقاد بقلبه وسائر جوارحه لله تعالى وحده، وهو محسن في قوله وعمله متبع امر ربه، واتبع دين ابراهيم وشرعه، مائلا عن العقائد الفاسده والشرائع الباطله. وقد اصطفى الله ابراهيم -عليه الصلاه والسلام- واتخذه صفيا من بين سائر خلقه. وفي هذه الايه، اثبات صفه الخله لله -تعالى- وهي اعلى مقامات المحبه والاصطفاء."},{"id":"619","s":4,"a":126,"at":"ولله ما في السموات وما في الارض وكان الله بكل شيء محيطا","dt":"[126] ولله جميع ما في هذا الكون من المخلوقات، فهي ملك له تعالى وحده. وكان الله تعالى بكل شيء محيطا، لا يخفى عليه شيء من امور خلقه."},{"id":"620","s":4,"a":127,"at":"ويستفتونك في النساء قل الله يفتيكم فيهن وما يتلى عليكم في الكتاب في يتامى النساء اللاتي لا تؤتونهن ما كتب لهن وترغبون ان تنكحوهن والمستضعفين من الولدان وان تقوموا لليتامى بالقسط وما تفعلوا من خير فان الله كان به عليما","dt":"[127] يطلب الناس منك -ايها النبي- ان تبين لهم ما اشكل عليهم فهمه من قضايا النساء واحكامهن، قل الله تعالى يبين لكم امورهن، وما يتلى عليكم في الكتاب في يتامى النساء اللاتي لا تعطونهن ما فرض الله تعالى لهن من المهر والميراث، وغير ذلك من الحقوق، وتحبون نكاحهن، او ترغبون عن نكاحهن، ويبين الله لكم امر الضعفاء من الصغار، ووجوب القيام لليتامى -وهم الذين مات اباؤهم وهم دون سن البلوغ- بالعدل وترك الجور عليهم في حقوقهم. وما تفعلوا من خير فان الله تعالى كان به عليما، لا يخفى عليه شيء منه ولا من غيره."},{"id":"621","s":4,"a":128,"at":"وان امراه خافت من بعلها نشوزا او اعراضا فلا جناح عليهما ان يصلحا بينهما صلحا والصلح خير واحضرت الانفس الشح وان تحسنوا وتتقوا فان الله كان بما تعملون خبيرا","dt":"[128] وان علمت امراه من زوجها ترفعا عنها، وتعاليا عليها او انصرافا عنها فلا اثم عليهما ان يتصالحا على ما تطيب به نفوسهما من القسمه او النفقه، والصلح اولى وافضل. وجبلت النفوس على الحرص والبخل، فكان البخل حاضرها لا ينفك عنها. وان تحسنوا معامله زوجاتكم وتخافوا الله فيهن، فان الله كان بما تعملون من ذلك وغيره عالما لا يخفى عليه شيء، وسيجازيكم على ذلك."},{"id":"622","s":4,"a":129,"at":"ولن تستطيعوا ان تعدلوا بين النساء ولو حرصتم فلا تميلوا كل الميل فتذروها كالمعلقه وان تصلحوا وتتقوا فان الله كان غفورا رحيما","dt":"[129] ولن تقدروا -ايها الرجال- على تحقيق العدل التام بين النساء في المحبه وميل القلب، مهما بذلتم في ذلك من الجهد، فلا تعرضوا عن المرغوب عنها كل الاعراض، فتتركوها كالمراه التي ليست بذات زوج ولا هي مطلقه فتاثموا. وان تصلحوا اعمالكم فتعدلوا في قسمكم بين زوجاتكم، وتراقبوا الله تعالى وتخشوه فيهن، فان الله تعالى كان غفورا لعباده، رحيما بهم."},{"id":"623","s":4,"a":130,"at":"وان يتفرقا يغن الله كلا من سعته وكان الله واسعا حكيما","dt":"[130] وان وقعت الفرقه بين الرجل وامراته، فان الله تعالى يغني كلا منهما من فضله وسعته؛ فانه سبحانه وتعالى واسع الفضل والمنه، حكيم فيما يقضي به بين عباده."},{"id":"624","s":4,"a":131,"at":"ولله ما في السموات وما في الارض ولقد وصينا الذين اوتوا الكتاب من قبلكم واياكم ان اتقوا الله وان تكفروا فان لله ما في السموات وما في الارض وكان الله غنيا حميدا","dt":"[131] ولله ملك ما في السموات وما في الارض وما بينهما. ولقد عهدنا الى الذين اعطوا الكتاب من قبلكم من اليهود والنصارى، وعهدنا اليكم كذلك -يا امه محمد- بتقوى الله تعالى، والقيام بامره واجتناب نهيه، وبينا لكم انكم ان تجحدوا وحدانيه الله تعالى وشرعه فانه سبحانه غني عنكم؛ لان له جميع ما في السموات وما في الارض. وكان الله غنيا عن خلقه، حميدا في صفاته وافعاله."},{"id":"625","s":4,"a":132,"at":"ولله ما في السموات وما في الارض وكفى بالله وكيلا","dt":"[132] ولله ملك ما في هذا الكون من الكائنات، وكفى به سبحانه قائما بشؤون خلقه حافظا لها."},{"id":"626","s":4,"a":133,"at":"ان يشا يذهبكم ايها الناس ويات باخرين وكان الله على ذلك قديرا","dt":"[133] ان يشا الله يهلكم ايها الناس، ويات بقوم اخرين غيركم. وكان الله على ذلك قديرا."},{"id":"627","s":4,"a":134,"at":"من كان يريد ثواب الدنيا فعند الله ثواب الدنيا والاخره وكان الله سميعا بصيرا","dt":"[134] من يرغب منكم -ايها الناس- في ثواب الدنيا ويعرض عن الاخره، فعند الله وحده ثواب الدنيا والاخره، فليطلب من الله وحده خيري الدنيا والاخره، فهو الذي يملكهما. وكان الله سميعا لاقوال عباده، بصيرا بنياتهم واعمالهم، وسيجازيهم على ذلك."},{"id":"628","s":4,"a":135,"at":"ياايها الذين امنوا كونوا قوامين بالقسط شهداء لله ولو على انفسكم او الوالدين والاقربين ان يكن غنيا او فقيرا فالله اولى بهما فلا تتبعوا الهوى ان تعدلوا وان تلووا او تعرضوا فان الله كان بما تعملون خبيرا","dt":"[135] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، كونوا قائمين بالعدل، مؤدين للشهاده لوجه الله تعالى، ولو كانت على انفسكم، او على ابائكم وامهاتكم، او على اقاربكم، مهما كان شان المشهود عليه غنيا او فقيرا؛ فان الله تعالى اولى بهما منكم، واعلم بما فيه صلاحهما، فلا يحملنكم الهوى والتعصب على ترك العدل، وان تحرفوا الشهاده بالسنتكم فتاتوا بها على غير حقيقتها، او تعرضوا عنها بترك ادائها او بكتمانها، فان الله تعالى كان عليما بدقائق اعمالكم، وسيجازيكم بها."},{"id":"629","s":4,"a":136,"at":"ياايها الذين امنوا امنوا بالله ورسوله والكتاب الذي نزل على رسوله والكتاب الذي انزل من قبل ومن يكفر بالله وملائكته وكتبه ورسله واليوم الاخر فقد ضل ضلالا بعيدا","dt":"[136] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه داوموا على ما انتم عليه من التصديق الجازم بالله تعالى وبرسوله محمد -صلى الله عليه وسلم-، ومن طاعتهما، وبالقران الذي نزله عليه، وبجميع الكتب التي انزلها الله على الرسل. ومن يكفر بالله تعالى، وملائكته المكرمين، وكتبه التي انزلها لهدايه خلقه، ورسله الذين اصطفاهم لتبليغ رسالته، واليوم الاخر الذي يقوم الناس فيه بعد موتهم للعرض والحساب، فقد خرج من الدين، وبعد بعدا كبيرا عن طريق الحق."},{"id":"630","s":4,"a":137,"at":"ان الذين امنوا ثم كفروا ثم امنوا ثم كفروا ثم ازدادوا كفرا لم يكن الله ليغفر لهم ولا ليهديهم سبيلا","dt":"[137] ان الذين دخلوا في الايمان، ثم رجعوا عنه الى الكفر، ثم عادوا الى الايمان، ثم رجعوا الى الكفر مره اخرى، ثم اصروا على كفرهم واستمروا عليه، لم يكن الله ليغفر لهم، ولا ليدلهم على طريق من طرق الهدايه، التي ينجون بها من سوء العاقبه."},{"id":"631","s":4,"a":138,"at":"بشر المنافقين بان لهم عذابا اليما","dt":"[138] بشر -ايها الرسول- المنافقين -وهم الذين يظهرون الايمان ويبطنون الكفر- بان لهم عذابا موجعا."},{"id":"632","s":4,"a":139,"at":"الذين يتخذون الكافرين اولياء من دون المؤمنين ايبتغون عندهم العزه فان العزه لله جميعا","dt":"[139] الذين يوالون الكافرين، ويتخذونهم اعوانا لهم، ويتركون ولايه المؤمنين، ولا يرغبون في مودتهم. ايطلبون بذلك النصره والمنعه عند الكافرين؟ انهم لا يملكون ذلك، فالنصره والعزه والقوه جميعها لله تعالى وحده."},{"id":"633","s":4,"a":140,"at":"وقد نزل عليكم في الكتاب ان اذا سمعتم ايات الله يكفر بها ويستهزا بها فلا تقعدوا معهم حتى يخوضوا في حديث غيره انكم اذا مثلهم ان الله جامع المنافقين والكافرين في جهنم جميعا","dt":"[140] وقد نزل ربكم عليكم -ايها المؤمنون- في كتابه انه اذا سمعتم الكفر بايات الله والاستهزاء بها فلا تجلسوا مع الكافرين والمستهزئين، الا اذا اخذوا في حديث غير حديث الكفر والاستهزاء بايات الله. انكم اذا جالستموهم، وهم على ما هم عليه، فانتم مثلهم؛ لانكم رضيتم بكفرهم واستهزائهم، والراضي بالمعصيه كالفاعل لها. ان الله تعالى جامع المنافقين والكافرين في نار جهنم جميعا، يلقون فيها سوء العذاب."},{"id":"634","s":4,"a":141,"at":"الذين يتربصون بكم فان كان لكم فتح من الله قالوا الم نكن معكم وان كان للكافرين نصيب قالوا الم نستحوذ عليكم ونمنعكم من المؤمنين فالله يحكم بينكم يوم القيامه ولن يجعل الله للكافرين على المؤمنين سبيلا","dt":"[141] المنافقون هم الذين ينتظرون ما يحل بكم -ايها المؤمنون- من الفتن والحرب، فان من الله عليكم بفضله، ونصركم على عدوكم وغنمتم، قالوا لكم: الم نكن معكم نؤازركم؟ وان كان للجاحدين لهذا الدين قدر من النصر والغنيمه، قالوا لهم: الم نساعدكم بما قدمناه لكم ونحمكم من المؤمنين؟ فالله تعالى يقضي بينكم وبينهم يوم القيامه، ولن يجعل الله للكافرين طريقا للغلبه على عباده الصالحين، فالعاقبه للمتقين في الدنيا والاخره."},{"id":"635","s":4,"a":142,"at":"ان المنافقين يخادعون الله وهو خادعهم واذا قاموا الى الصلاه قاموا كسالى يراءون الناس ولا يذكرون الله الا قليلا","dt":"[142] ان طريقه هؤلاء المنافقين مخادعه الله تعالى، بما يظهرونه من الايمان وما يبطنونه من الكفر، ظنا انه يخفى على الله، والحال ان الله خادعهم ومجازيهم بمثل عملهم، واذا قام هؤلاء المنافقون لاداء الصلاه، قاموا اليها في فتور، يقصدون بصلاتهم الرياء والسمعه، ولا يذكرون الله تعالى الا ذكرا قليلا."},{"id":"636","s":4,"a":143,"at":"مذبذبين بين ذلك لا الى هؤلاء ولا الى هؤلاء ومن يضلل الله فلن تجد له سبيلا","dt":"[143] ان من شان هؤلاء المنافقين التردد والحيره والاضطراب، لا يستقرون على حال، فلا هم مع المؤمنين ولا هم مع الكافرين. ومن يصرف الله قلبه عن الايمان به والاستمساك بهديه، فلن تجد له طريقا الى الهدايه واليقين."},{"id":"637","s":4,"a":144,"at":"ياايها الذين امنوا لا تتخذوا الكافرين اولياء من دون المؤمنين اتريدون ان تجعلوا لله عليكم سلطانا مبينا","dt":"[144] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، لا توالوا الجاحدين لدين الله، وتتركوا موالاه المؤمنين ومودتهم. اتريدون بموده اعدائكم ان تجعلوا لله تعالى عليكم حجه ظاهره على عدم صدقكم في ايمانكم؟"},{"id":"638","s":4,"a":145,"at":"ان المنافقين في الدرك الاسفل من النار ولن تجد لهم نصيرا","dt":"[145] ان المنافقين في اسفل منازل النار يوم القيامه، ولن تجد لهم -ايها الرسول- ناصرا يدفع عنهم سوء هذا المصير."},{"id":"639","s":4,"a":146,"at":"الا الذين تابوا واصلحوا واعتصموا بالله واخلصوا دينهم لله فاولئك مع المؤمنين وسوف يؤت الله المؤمنين اجرا عظيما","dt":"[146] الا الذين رجعوا الى الله تعالى وتابوا اليه، واصلحوا ما افسدوا من احوالهم باطنا وظاهرا، ووالوا عباده المؤمنين، واستمسكوا بدين الله، واخلصوا له سبحانه، فاولئك مع المؤمنين في الدنيا والاخره، وسوف يعطي الله المؤمنين ثوابا عظيما."},{"id":"640","s":4,"a":147,"at":"ما يفعل الله بعذابكم ان شكرتم وامنتم وكان الله شاكرا عليما","dt":"[147] ما يفعل الله بعذابكم ان اصلحتم العمل وامنتم بالله ورسوله، فان الله سبحانه غني عمن سواه، وانما يعذب العباد بذنوبهم. وكان الله شاكرا لعباده على طاعتهم له، عليما بكل شيء."},{"id":"641","s":4,"a":148,"at":"لا يحب الله الجهر بالسوء من القول الا من ظلم وكان الله سميعا عليما","dt":"[148] لا يحب الله ان يجهر احد بقول السوء، لكن يباح للمظلوم ان يذكر ظالمه بما فيه من السوء؛ ليبين مظلمته. وكان الله سميعا لما تجهرون به، عليما بما تخفون من ذلك."},{"id":"642","s":4,"a":149,"at":"ان تبدوا خيرا او تخفوه او تعفوا عن سوء فان الله كان عفوا قديرا","dt":"[149] ندب الله تعالى الى العفو، ومهد له بان المؤمن: اما ان يظهر الخير، واما ان يخفيه، وكذلك مع الاساءه: اما ان يظهرها في حال الانتصاف من المسيء، واما ان يعفو ويصفح، والعفو افضل؛ فان من صفاته تعالى العفو عن عباده مع قدرته عليهم."},{"id":"643","s":4,"a":150,"at":"ان الذين يكفرون بالله ورسله ويريدون ان يفرقوا بين الله ورسله ويقولون نؤمن ببعض ونكفر ببعض ويريدون ان يتخذوا بين ذلك سبيلا","dt":"[150] ان الذين يكفرون بالله ورسله، من اليهود والنصارى، ويريدون ان يفرقوا بين الله ورسله بان يؤمنوا بالله ويكذبوا رسله الذين ارسلهم الى خلقه، او يعترفوا بصدق بعض الرسل دون بعض، ويزعموا ان بعضهم افتروا على ربهم، ويريدون ان يتخذوا طريقا الى الضلاله التي احدثوها والبدعه التي ابتدعوها."},{"id":"644","s":4,"a":151,"at":"اولئك هم الكافرون حقا واعتدنا للكافرين عذابا مهينا","dt":"[151] اولئك هم اهل الكفر المحقق الذي لا شك فيه، واعتدنا للكافرين عذابا يخزيهم ويهينهم."},{"id":"645","s":4,"a":152,"at":"والذين امنوا بالله ورسله ولم يفرقوا بين احد منهم اولئك سوف يؤتيهم اجورهم وكان الله غفورا رحيما","dt":"[152] والذين صدقوا بوحدانيه الله، واقروا بنبوه رسله اجمعين، ولم يفرقوا بين احد منهم، وعملوا بشريعه الله، اولئك سوف يعطيهم جزاءهم وثوابهم على ايمانهم به وبرسله. وكان الله غفورا لعباده رحيما بهم."},{"id":"646","s":4,"a":153,"at":"يسالك اهل الكتاب ان تنزل عليهم كتابا من السماء فقد سالوا موسى اكبر من ذلك فقالوا ارنا الله جهره فاخذتهم الصاعقه بظلمهم ثم اتخذوا العجل من بعد ما جاءتهم البينات فعفونا عن ذلك واتينا موسى سلطانا مبينا","dt":"[153] يسالك اليهود -ايها الرسول- معجزه مثل معجزه موسى تشهد لك بالصدق: بان تنزل عليهم صحفا من الله مكتوبه، مثل مجيء موسى بالالواح من عند الله، فلا تعجب -ايها الرسول- فقد سال اسلافهم موسى -عليه السلام- ما هو اعظم: سالوه ان يريهم الله علانيه، فاخذتهم العقوبه المهلكه؛ بسبب ظلمهم انفسهم حين سالوا امرا ليس من حقهم. وبعد ان احياهم الله بعد الصعق، وشاهدوا الايات البينات -على يد موسى- القاطعه بنفي الشرك، عبدوا العجل من دون الله، فعفونا عن عبادتهم العجل بسبب توبتهم، واتينا موسى حجه عظيمه تؤيد صدق نبوته."},{"id":"647","s":4,"a":154,"at":"ورفعنا فوقهم الطور بميثاقهم وقلنا لهم ادخلوا الباب سجدا وقلنا لهم لا تعدوا في السبت واخذنا منهم ميثاقا غليظا","dt":"[154] ورفعنا فوق رؤوسهم جبل الطور حين امتنعوا عن الالتزام بالعهد المؤكد الذي اعطوه بالعمل باحكام التوراه، وامرناهم ان يدخلوا باب «بيت المقدس» سجدا، فدخلوا يزحفون على استاههم، وامرناهم الا يعتدوا بالصيد في يوم السبت، فاعتدوا وصادوا، واخذنا عليهم عهدا مؤكدا، فنقضوه."},{"id":"648","s":4,"a":155,"at":"فبما نقضهم ميثاقهم وكفرهم بايات الله وقتلهم الانبياء بغير حق وقولهم قلوبنا غلف بل طبع الله عليها بكفرهم فلا يؤمنون الا قليلا","dt":"[155] فلعناهم بسبب نقضهم للعهود، وكفرهم بايات الله الداله على صدق رسله، وقتلهم للانبياء ظلما واعتداء، وقولهم: قلوبنا عليها اغطيه فلا تفقه ما تقول، بل طمس الله عليها بسبب كفرهم، فلا يؤمنون الا ايمانا قليلا لا ينفعهم."},{"id":"649","s":4,"a":156,"at":"وبكفرهم وقولهم على مريم بهتانا عظيما","dt":"[156] وكذلك لعناهم بسبب كفرهم وافترائهم على مريم بما نسبوه اليها من الزنى، وهي بريئه منه."},{"id":"650","s":4,"a":157,"at":"وقولهم انا قتلنا المسيح عيسى ابن مريم رسول الله وما قتلوه وما صلبوه ولكن شبه لهم وان الذين اختلفوا فيه لفي شك منه ما لهم به من علم الا اتباع الظن وما قتلوه يقينا","dt":"[157] وبسبب قولهم -على سبيل التهكم والاستهزاء-: انا قتلنا المسيح عيسى بن مريم رسول الله، وما قتلوا عيسى وما صلبوه، بل صلبوا رجلا شبيها به ظنا منهم انه عيسى. ومن ادعى قتله من اليهود، وكذلك من اسلمه اليهم من النصارى، كلهم واقعون في شك وحيره، لا علم لديهم الا اتباع الظن، وما قتلوه متيقنين بل شاكين متوهمين."},{"id":"651","s":4,"a":158,"at":"بل رفعه الله اليه وكان الله عزيزا حكيما","dt":"[158] بل رفع الله عيسى اليه ببدنه وروحه حيا، وخلصه من الذين كفروا. وكان الله عزيزا في ملكه، حكيما في تدبيره وقضائه."},{"id":"652","s":4,"a":159,"at":"وان من اهل الكتاب الا ليؤمنن به قبل موته ويوم القيامه يكون عليهم شهيدا","dt":"[159] وانه لا يبقى احد من اهل الكتاب بعد نزول عيسى اخر الزمان الا امن به قبل موته عليه السلام، ويوم القيامه يكون عيسى -عليه السلام- شهيدا بتكذيب من كذبه، وتصديق من صدقه."},{"id":"653","s":4,"a":160,"at":"فبظلم من الذين هادوا حرمنا عليهم طيبات احلت لهم وبصدهم عن سبيل الله كثيرا","dt":"[160] فبسبب ظلم اليهود بما ارتكبوه من الذنوب العظيمه حرم الله عليهم طيبات من الماكل كانت حلالا لهم، وبسبب صدهم انفسهم وغيرهم عن دين الله القويم."},{"id":"654","s":4,"a":161,"at":"واخذهم الربا وقد نهوا عنه واكلهم اموال الناس بالباطل واعتدنا للكافرين منهم عذابا اليما","dt":"[161] وبسبب تناولهم الربا الذي نهوا عنه، واستحلالهم اموال الناس بغير استحقاق، واعتدنا للكافرين بالله ورسوله من هؤلاء اليهود عذابا موجعا في الاخره."},{"id":"655","s":4,"a":162,"at":"لكن الراسخون في العلم منهم والمؤمنون يؤمنون بما انزل اليك وما انزل من قبلك والمقيمين الصلاه والمؤتون الزكاه والمؤمنون بالله واليوم الاخر اولئك سنؤتيهم اجرا عظيما","dt":"[162] لكن المتمكنون في العلم باحكام الله من اليهود، والمؤمنون بالله ورسوله، يؤمنون بالذي انزله الله اليك -ايها الرسول- وهو القران، وبالذي انزل الى الرسل من قبلك كالتوراه والانجيل، ويؤدون الصلاه في اوقاتها، ويخرجون زكاه اموالهم، ويؤمنون بالله وبالبعث والجزاء، اولئك سيعطيهم الله ثوابا عظيما، وهو الجنه."},{"id":"656","s":4,"a":163,"at":"انا اوحينا اليك كما اوحينا الى نوح والنبيين من بعده واوحينا الى ابراهيم واسماعيل واسحاق ويعقوب والاسباط وعيسى وايوب ويونس وهارون وسليمان واتينا داود زبورا","dt":"[163] انا اوحينا اليك -ايها الرسول- بتبليغ الرساله كما اوحينا الى نوح والنبيين من بعده، واوحينا الى ابراهيم واسماعيل واسحاق ويعقوب، والاسباط -وهم الانبياء من ولد يعقوب، الذين كانوا في قبائل بني اسرائيل الاثنتي عشره- وعيسى وايوب ويونس وهارون وسليمان. واتينا داود زبورا، وهو كتاب وصحف مكتوبه."},{"id":"657","s":4,"a":164,"at":"ورسلا قد قصصناهم عليك من قبل ورسلا لم نقصصهم عليك وكلم الله موسى تكليما","dt":"[164] وارسلنا رسلا قد قصصناهم عليك في القران من قبل هذه الايه، ورسلا لم نقصصهم عليك لحكمه اردناها. وكلم الله موسى تكليما؛ تشريفا له بهذه الصفه. وفي هذه الايه الكريمه اثبات صفه الكلام لله -تعالى- كما يليق بجلاله، وانه سبحانه كلم نبيه موسى -عليه السلام- حقيقه بلا واسطه."},{"id":"658","s":4,"a":165,"at":"رسلا مبشرين ومنذرين لئلا يكون للناس على الله حجه بعد الرسل وكان الله عزيزا حكيما","dt":"[165] ارسلت رسلا الى خلقي مبشرين بثوابي، ومنذرين بعقابي؛ لئلا يكون للبشر حجه يعتذرون بها بعد ارسال الرسل. وكان الله عزيزا في ملكه، حكيما في تدبيره."},{"id":"659","s":4,"a":166,"at":"لكن الله يشهد بما انزل اليك انزله بعلمه والملائكه يشهدون وكفى بالله شهيدا","dt":"[166] ان يكفر بك اليهود وغيرهم -ايها الرسول- فالله يشهد لك بانك رسوله الذي انزل عليه القران العظيم، انزله بعلمه، وكذلك الملائكه يشهدون بصدق ما اوحي اليك، وشهاده الله وحدها كافيه."},{"id":"660","s":4,"a":167,"at":"ان الذين كفروا وصدوا عن سبيل الله قد ضلوا ضلالا بعيدا","dt":"[167] ان الذين جحدوا نبوتك، وصدوا الناس عن الاسلام، قد بعدوا عن طريق الحق بعدا شديدا."},{"id":"661","s":4,"a":168,"at":"ان الذين كفروا وظلموا لم يكن الله ليغفر لهم ولا ليهديهم طريقا","dt":"[168] ان الذين كفروا بالله وبرسوله؛ وظلموا باستمرارهم على الكفر، لم يكن الله ليغفر ذنوبهم، ولا ليدلهم على طريق ينجيهم."},{"id":"662","s":4,"a":169,"at":"الا طريق جهنم خالدين فيها ابدا وكان ذلك على الله يسيرا","dt":"[169] الا طريق جهنم ماكثين فيها ابدا، وكان ذلك على الله يسيرا، فلا يعجزه شيء."},{"id":"663","s":4,"a":170,"at":"ياايها الناس قد جاءكم الرسول بالحق من ربكم فامنوا خيرا لكم وان تكفروا فان لله ما في السموات والارض وكان الله عليما حكيما","dt":"[170] يا ايها الناس قد جاءكم رسولنا محمد -صلى الله عليه وسلم- بالاسلام دين الحق من ربكم، فصدقوه واتبعوه، فان الايمان به خير لكم، وان تصروا على كفركم فان الله غني عنكم وعن ايمانكم؛ لانه مالك ما في السموات والارض. وكان الله عليما باقوالكم وافعالكم، حكيما في تشريعه وامره. فاذا كانت السموات والارض قد خضعتا لله تعالى كونا وقدرا خضوع سائر ملكه، فاولى بكم ان تؤمنوا بالله وبرسوله محمد -صلى الله عليه وسلم-، وبالقران الذي انزله عليه، وان تنقادوا لذلك شرعا حتى يكون الكون كله خاضعا لله قدرا وشرعا. وفي الايه دليل على عموم رساله نبي الله ورسوله محمد -صلى الله عليه وسلم-."},{"id":"664","s":4,"a":171,"at":"يااهل الكتاب لا تغلوا في دينكم ولا تقولوا على الله الا الحق انما المسيح عيسى ابن مريم رسول الله وكلمته القاها الى مريم وروح منه فامنوا بالله ورسله ولا تقولوا ثلاثه انتهوا خيرا لكم انما الله اله واحد سبحانه ان يكون له ولد له ما في السموات وما في الارض وكفى بالله وكيلا","dt":"[171] يا اهل الانجيل لا تتجاوزوا الاعتقاد الحق في دينكم، ولا تقولوا على الله الا الحق، فلا تجعلوا له صاحبه ولا ولدا. انما المسيح عيسى ابن مريم رسول الله ارسله الله بالحق، وخلقه بالكلمه التي ارسل بها جبريل الى مريم، وهي قوله: «كن»، فكان، وهي نفخه من الله تعالى نفخها جبريل بامر ربه، فصدقوا بان الله واحد واسلموا له، وصدقوا رسله فيما جاؤوكم به من عند الله واعملوا به، ولا تجعلوا عيسى وامه مع الله شريكين. انتهوا عن هذه المقاله خيرا لكم مما انتم عليه، انما الله اله واحد سبحانه. ما في السموات والارض ملكه، فكيف يكون له منهم صاحبه او ولد؟ وكفى بالله وكيلا على تدبير خلقه وتصريف معاشهم، فتوكلوا عليه وحده فهو كافيكم."},{"id":"665","s":4,"a":172,"at":"لن يستنكف المسيح ان يكون عبدا لله ولا الملائكه المقربون ومن يستنكف عن عبادته ويستكبر فسيحشرهم اليه جميعا","dt":"[172] لن يانف ولن يمتنع المسيح ان يكون عبدا لله، وكذلك لن يانف الملائكه المقربون من الاقرار بالعبوديه لله تعالى. ومن يانف عن الانقياد والخضوع ويستكبر فسيحشرهم كلهم اليه يوم القيامه، ويفصل بينهم بحكمه العادل، ويجازي كلا بما يستحق."},{"id":"666","s":4,"a":173,"at":"فاما الذين امنوا وعملوا الصالحات فيوفيهم اجورهم ويزيدهم من فضله واما الذين استنكفوا واستكبروا فيعذبهم عذابا اليما ولا يجدون لهم من دون الله وليا ولا نصيرا","dt":"[173] فاما الذين صدقوا بالله اعتقادا وقولا وعملا، واستقاموا على شريعته فيوفيهم ثواب اعمالهم، ويزيدهم من فضله، واما الذين امتنعوا عن طاعه الله، واستكبروا عن التذلل له فيعذبهم عذابا موجعا، ولا يجدون لهم وليا ينجيهم من عذابه، ولا ناصرا ينصرهم من دون الله."},{"id":"667","s":4,"a":174,"at":"ياايها الناس قد جاءكم برهان من ربكم وانزلنا اليكم نورا مبينا","dt":"[174] يا ايها الناس قد جاءكم برهان من ربكم، وهو رسولنا محمد -صلى الله عليه وسلم-، وما جاء به من البينات والحجج القاطعه، واعظمها القران الكريم، مما يشهد بصدق نبوته ورسالته الخاتمه، وانزلنا اليكم القران هدى ونورا مبينا."},{"id":"668","s":4,"a":175,"at":"فاما الذين امنوا بالله واعتصموا به فسيدخلهم في رحمه منه وفضل ويهديهم اليه صراطا مستقيما","dt":"[175] فاما الذين صدقوا بالله اعتقادا وقولا وعملا، واستمسكوا بالنور الذي انزل اليهم، فسيدخلهم الجنه رحمه منه وفضلا، ويوفقهم الى سلوك الطريق المستقيم المفضي الى روضات الجنات."},{"id":"669","s":4,"a":176,"at":"يستفتونك قل الله يفتيكم في الكلاله ان امرؤ هلك ليس له ولد وله اخت فلها نصف ما ترك وهو يرثها ان لم يكن لها ولد فان كانتا اثنتين فلهما الثلثان مما ترك وان كانوا اخوه رجالا ونساء فللذكر مثل حظ الانثيين يبين الله لكم ان تضلوا والله بكل شيء عليم","dt":"[176] يسالونك -ايها النبي- عن حكم ميراث الكلاله، وهو من مات وليس له ولد ولا والد، قل: الله يبين لكم الحكم فيها: ان مات امرؤ ليس له ولد ولا والد، وله اخت لابيه وامه، او لابيه فقط، فلها نصف تركته، ويرث اخوها، شقيقا كان او لاب جميع مالها اذا ماتت وليس لها ولد ولا والد. فان كان لمن مات كلاله اختان فلهما الثلثان مما ترك. واذا اجتمع الذكور من الاخوه لغير ام مع الاناث فللذكر مثل نصيب الانثيين من اخواته. يبين الله لكم قسمه المواريث وحكم الكلاله؛ لئلا تضلوا عن الحق في امر المواريث. والله عالم بعواقب الامور، وما فيها من الخير لعباده."},{"id":"670","s":5,"a":1,"at":"ياايها الذين امنوا اوفوا بالعقود احلت لكم بهيمه الانعام الا ما يتلى عليكم غير محلي الصيد وانتم حرم ان الله يحكم ما يريد","dt":"[1] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، اتموا عهود الله الموثقه، من الايمان بشرائع الدين، والانقياد لها، وادوا العهود لبعضكم على بعض من الامانات، والبيوع وغيرها، مما لم يخالف كتاب الله، وسنه رسوله محمد -صلى الله عليه وسلم-. وقد احل الله لكم البهيمه من الانعام، وهي الابل والبقر والغنم، الا ما بينه لكم من تحريم الميته والدم وغير ذلك، ومن تحريم الصيد وانتم محرمون بحج او عمره، او كنتم داخل الحرم. ان الله يحكم ما يشاء وفق حكمته وعدله."},{"id":"671","s":5,"a":2,"at":"ياايها الذين امنوا لا تحلوا شعائر الله ولا الشهر الحرام ولا الهدي ولا القلائد ولا امين البيت الحرام يبتغون فضلا من ربهم ورضوانا واذا حللتم فاصطادوا ولا يجرمنكم شنان قوم ان صدوكم عن المسجد الحرام ان تعتدوا وتعاونوا على البر والتقوى ولا تعاونوا على الاثم والعدوان واتقوا الله ان الله شديد العقاب","dt":"[2] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه لا تتعدوا حدود الله ومعالمه، ولا تستحلوا القتال في الاشهر الحرم، وهي: ذو القعده وذو الحجه والمحرم ورجب، وكان ذلك في صدر الاسلام، ولا تستحلوا حرمه الهدي، ولا ما قلد منه؛ اذ كانوا يضعون القلائد، وهي ضفائر من صوف او وبر في الرقاب، علامه على ان البهيمه هدي وان الرجل يريد الحج، ولا تستحلوا قتال قاصدي البيت الحرام الذين يبتغون من فضل الله ما يصلح معايشهم ويرضي ربهم. واذا حللتم من احرامكم حل لكم الصيد، ولا يحملنكم بغض قوم من اجل ان منعوكم من الوصول الى المسجد الحرام -كما حدث عام «الحديبيه»- على ترك العدل فيهم. وتعاونوا -ايها المؤمنون فيما بينكم- على فعل الخير، وتقوى الله، ولا تعاونوا على ما فيه اثم ومعصيه وتجاوز لحدود الله، واحذروا مخالفه امر الله فانه شديد العقاب."},{"id":"672","s":5,"a":3,"at":"حرمت عليكم الميته والدم ولحم الخنزير وما اهل لغير الله به والمنخنقه والموقوذه والمترديه والنطيحه وما اكل السبع الا ما ذكيتم وما ذبح على النصب وان تستقسموا بالازلام ذلكم فسق اليوم يئس الذين كفروا من دينكم فلا تخشوهم واخشون اليوم اكملت لكم دينكم واتممت عليكم نعمتي ورضيت لكم الاسلام دينا فمن اضطر في مخمصه غير متجانف لاثم فان الله غفور رحيم","dt":"[3] حرم الله عليكم الميته، وهي الحيوان الذي تفارقه الحياه بدون ذكاه، وحرم عليكم الدم السائل المراق، ولحم الخنزير، وما ذكر عليه غير اسم الله عند الذبح، والمنخنقه التي حبس نفسها حتى ماتت، والموقوذه وهي التي ضربت بعصا او حجر حتى ماتت، والمترديه وهي التي سقطت من مكان عال او هوت في بئر فماتت، والنطيحه وهي التي ضربتها اخرى بقرنها فماتت، وحرم الله عليكم البهيمه التي اكلها السبع، كالاسد والنمر والذئب، ونحو ذلك. واستثنى -سبحانه- مما حرمه من المنخنقه وما بعدها ما ادركتم ذكاته قبل ان يموت فهو حلال لكم، وحرم الله عليكم ما ذبح لغير الله على ما ينصب للعباده من حجر او غيره، وحرم الله عليكم ان تطلبوا علم ما قسم لكم او لم يقسم بالازلام، وهي القداح التي كانوا يستقسمون بها اذا ارادوا امرا قبل ان يقدموا عليه. ذلكم المذكور في الايه من المحرمات -اذا ارتكبت- خروج عن امر الله وطاعته الى معصيته. الان انقطع طمع الكفار من دينكم ان ترتدوا عنه الى الشرك بعد ان نصرتكم عليهم، فلا تخافوهم وخافوني. اليوم اكملت لكم دينكم دين الاسلام بتحقيق النصر واتمام الشريعه، واتممت عليكم نعمتي باخراجكم من ظلمات الجاهليه الى نور الايمان، ورضيت لكم الاسلام دينا فالزموه، ولا تفارقوه. فمن اضطر في مجاعه الى اكل الميته، وكان غير مائل عمدا لاثم، فله تناوله، فان الله غفور له، رحيم به."},{"id":"673","s":5,"a":4,"at":"يسالونك ماذا احل لهم قل احل لكم الطيبات وما علمتم من الجوارح مكلبين تعلمونهن مما علمكم الله فكلوا مما امسكن عليكم واذكروا اسم الله عليه واتقوا الله ان الله سريع الحساب","dt":"[4] يسالك اصحابك -ايها النبي-: ماذا احل لهم اكله؟ قل لهم: احل لكم الطيبات، وصيد ما دربتموه من ذوات المخالب والانياب من الكلاب والفهود والصقور ونحوها مما يعلم، تعلمونهن طلب الصيد لكم، مما علمكم الله، فكلوا مما امسكن لكم، واذكروا اسم الله عند ارسالها للصيد، وخافوا الله فيما امركم به، وفيما نهاكم عنه. ان الله سريع الحساب."},{"id":"674","s":5,"a":5,"at":"اليوم احل لكم الطيبات وطعام الذين اوتوا الكتاب حل لكم وطعامكم حل لهم والمحصنات من المؤمنات والمحصنات من الذين اوتوا الكتاب من قبلكم اذا اتيتموهن اجورهن محصنين غير مسافحين ولا متخذي اخدان ومن يكفر بالايمان فقد حبط عمله وهو في الاخره من الخاسرين","dt":"[5] ومن تمام نعمه الله عليكم اليوم -ايها المؤمنون- ان احل لكم الحلال الطيب. وذبائح اليهود والنصارى -ان ذكوها حسب شرعهم- حلال لكم وذبائحكم حلال لهم. واحل لكم -ايها المؤمنون- نكاح المحصنات، وهن الحرائر من النساء المؤمنات، العفيفات عن الزنى، وكذلك نكاح الحرائر العفيفات من اليهود والنصارى اذا اعطيتموهن مهورهن، وكنتم اعفاء غير مرتكبين للزنى، ولا متخذي عشيقات، وامنتم من التاثر بدينهن. ومن يجحد شرائع الايمان فقد بطل عمله، وهو يوم القيامه من الخاسرين."},{"id":"675","s":5,"a":6,"at":"ياايها الذين امنوا اذا قمتم الى الصلاه فاغسلوا وجوهكم وايديكم الى المرافق وامسحوا برءوسكم وارجلكم الى الكعبين وان كنتم جنبا فاطهروا وان كنتم مرضى او على سفر او جاء احد منكم من الغائط او لامستم النساء فلم تجدوا ماء فتيمموا صعيدا طيبا فامسحوا بوجوهكم وايديكم منه ما يريد الله ليجعل عليكم من حرج ولكن يريد ليطهركم وليتم نعمته عليكم لعلكم تشكرون","dt":"[6] يا ايها الذين امنوا اذا اردتم القيام الى الصلاه، وانتم على غير طهاره فاغسلوا وجوهكم وايديكم مع المرافق (والمرفق: المفصل الذي بين الذراع والعضد) وامسحوا رؤوسكم، واغسلوا ارجلكم مع الكعبين (وهما العظمان البارزان عند ملتقى الساق بالقدم). وان اصابكم الحدث الاكبر فتطهروا بالاغتسال منه قبل الصلاه. وان كنتم مرضى، او على سفر في حال الصحه، او قضى احدكم حاجته، او جامع زوجته فلم تجدوا ماء فاضربوا بايديكم وجه الارض، وامسحوا وجوهكم وايديكم منه. ما يريد الله في امر الطهاره ان يضيق عليكم، بل اباح التيمم توسعه عليكم، ورحمه بكم، اذ جعله بديلا للماء في الطهاره، فكانت رخصه التيمم من تمام النعم التي تقتضي شكر المنعم؛ بطاعته فيما امر وفيما نهى."},{"id":"676","s":5,"a":7,"at":"واذكروا نعمه الله عليكم وميثاقه الذي واثقكم به اذ قلتم سمعنا واطعنا واتقوا الله ان الله عليم بذات الصدور","dt":"[7] واذكروا نعمه الله عليكم فيما شرعه لكم، واذكروا عهده الذي اخذه تعالى عليكم من الايمان بالله ورسوله محمد -صلى الله عليه وسلم-، والسمع والطاعه لهما، واتقوا الله فيما امركم به ونهاكم عنه. ان الله عليم بما تسرونه في نفوسكم."},{"id":"677","s":5,"a":8,"at":"ياايها الذين امنوا كونوا قوامين لله شهداء بالقسط ولا يجرمنكم شنان قوم على الا تعدلوا اعدلوا هو اقرب للتقوى واتقوا الله ان الله خبير بما تعملون","dt":"[8] يا ايها الذين امنوا بالله ورسوله محمد -صلى الله عليه وسلم- كونوا قوامين بالحق؛ ابتغاء وجه الله، شهداء بالعدل، ولا يحملنكم بغض قوم على الا تعدلوا، اعدلوا بين الاعداء والاحباب على درجه سواء، فذلك العدل اقرب لخشيه الله، واحذروا ان تجوروا. ان الله خبير بما تعملون، وسيجازيكم به."},{"id":"678","s":5,"a":9,"at":"وعد الله الذين امنوا وعملوا الصالحات لهم مغفره واجر عظيم","dt":"[9] وعد الله الذين صدقوا الله ورسوله وعملوا الصالحات ان يغفر لهم ذنوبهم، وان يثيبهم على ذلك الجنه، والله لا يخلف وعده."},{"id":"679","s":5,"a":10,"at":"والذين كفروا وكذبوا باياتنا اولئك اصحاب الجحيم","dt":"[10] والذين جحدوا وحدانيه الله الداله على الحق المبين، وكذبوا بادلته التي جاءت بها الرسل، هم اهل النار الملازمون لها."},{"id":"680","s":5,"a":11,"at":"ياايها الذين امنوا اذكروا نعمه الله عليكم اذ هم قوم ان يبسطوا اليكم ايديهم فكف ايديهم عنكم واتقوا الله وعلى الله فليتوكل المؤمنون","dt":"[11] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه اذكروا ما انعم الله به عليكم من نعمه الامن، والقاء الرعب في قلوب اعدائكم الذين ارادوا ان يبطشوا بكم، فصرفهم الله عنكم، وحال بينهم وبين ما ارادوه بكم، واتقوا الله واحذروه، وتوكلوا على الله وحده في اموركم الدينيه والدنيويه، وثقوا بعونه ونصره."},{"id":"681","s":5,"a":12,"at":"ولقد اخذ الله ميثاق بني اسرائيل وبعثنا منهم اثني عشر نقيبا وقال الله اني معكم لئن اقمتم الصلاه واتيتم الزكاه وامنتم برسلي وعزرتموهم واقرضتم الله قرضا حسنا لاكفرن عنكم سيئاتكم ولادخلنكم جنات تجري من تحتها الانهار فمن كفر بعد ذلك منكم فقد ضل سواء السبيل","dt":"[12] ولقد اخذ الله العهد المؤكد على بني اسرائيل ان يخلصوا له العباده وحده، وامر الله موسى ان يجعل عليهم اثني عشر عريفا بعدد فروعهم، ياخذون عليهم العهد بالسمع والطاعه لله ولرسوله ولكتابه، وقال الله لبني اسرائيل: اني معكم بحفظي ونصري، لئن اقمتم الصلاه، واعطيتم الزكاه المفروضه مستحقيها، وصدقتم برسلي فيما اخبروكم به ونصرتموهم، وانفقتم في سبيلي، لاكفرن عنكم سيئاتكم، ولادخلنكم جنات تجري من تحت قصورها واشجارها الانهار، فمن جحد هذا الميثاق منكم فقد عدل عن طريق الحق الى طريق الضلال."},{"id":"682","s":5,"a":13,"at":"فبما نقضهم ميثاقهم لعناهم وجعلنا قلوبهم قاسيه يحرفون الكلم عن مواضعه ونسوا حظا مما ذكروا به ولا تزال تطلع على خائنه منهم الا قليلا منهم فاعف عنهم واصفح ان الله يحب المحسنين","dt":"[13] فبسبب نقض هؤلاء اليهود لعهودهم المؤكده طردناهم من رحمتنا، وجعلنا قلوبهم غليظه لا تلين للايمان، يبدلون كلام الله الذي انزله على موسى، وهو التوراه، وتركوا نصيبا مما ذكروا به، فلم يعملوا به. ولا تزال -ايها الرسول- تجد من اليهود خيانه وغدرا، فهم على منهاج اسلافهم الا قليلا منهم، فاعف عن سوء معاملتهم لك، واصفح عنهم، فان الله يحب من احسن العفو والصفح الى من اساء اليه. (وهكذا يجد اهل الزيغ سبيلا الى مقاصدهم السيئه بتحريف كلام الله وتاويله على غير وجهه، فان عجزوا عن التحريف والتاويل تركوا ما لا يتفق مع اهوائهم من شرع الله، الذي لا يثبت عليه الا القليل ممن عصمه الله منهم)."},{"id":"683","s":5,"a":14,"at":"ومن الذين قالوا انا نصارى اخذنا ميثاقهم فنسوا حظا مما ذكروا به فاغرينا بينهم العداوه والبغضاء الى يوم القيامه وسوف ينبئهم الله بما كانوا يصنعون","dt":"[14] واخذنا على الذين ادعوا انهم اتباع المسيح عيسى عليه السلام -وليسوا كذلك- العهد المؤكد الذي اخذناه على بني اسرائيل: بان يتابعوا رسولهم وينصروه ويؤازروه، فبدلوا دينهم، وتركوا نصيبا مما ذكروا به، فلم يعملوا به، كما صنع اليهود، فالقينا بينهم العداوه والبغضاء الى يوم القيامه، وسوف ينبئهم الله بما كانوا يصنعون يوم الحساب، وسيعاقبهم على صنيعهم."},{"id":"684","s":5,"a":15,"at":"يااهل الكتاب قد جاءكم رسولنا يبين لكم كثيرا مما كنتم تخفون من الكتاب ويعفو عن كثير قد جاءكم من الله نور وكتاب مبين","dt":"[15] يا اهل الكتاب من اليهود والنصارى، قد جاءكم رسولنا محمد -صلى الله عليه وسلم- يبين لكم كثيرا مما كنتم تخفونه عن الناس مما في التوراه والانجيل، ويترك بيان كثير مما لا تقتضي الحكمه بيانه. قد جاءكم من الله نور وكتاب مبين: وهو القران الكريم."},{"id":"685","s":5,"a":16,"at":"يهدي به الله من اتبع رضوانه سبل السلام ويخرجهم من الظلمات الى النور باذنه ويهديهم الى صراط مستقيم","dt":"[16] يهدي الله بهذا الكتاب المبين من اتبع رضا الله تعالى، طرق الامن والسلامه، ويخرجهم باذنه من ظلمات الكفر الى نور الايمان، ويوفقهم الى دينه القويم."},{"id":"686","s":5,"a":17,"at":"لقد كفر الذين قالوا ان الله هو المسيح ابن مريم قل فمن يملك من الله شيئا ان اراد ان يهلك المسيح ابن مريم وامه ومن في الارض جميعا ولله ملك السموات والارض وما بينهما يخلق ما يشاء والله على كل شيء قدير","dt":"[17] لقد كفر النصارى القائلون بان الله هو المسيح بن مريم، قل -ايها الرسول- لهؤلاء الجهله من النصارى: لو كان المسيح الها كما يدعون لقدر ان يدفع قضاء الله اذا جاءه باهلاكه واهلاك امه ومن في الارض جميعا، وقد ماتت ام عيسى فلم يدفع عنها الموت، كذلك لا يستطيع هو ان يدفع عن نفسه؛ لانهما عبدان من عباد الله لا يقدران على دفع الهلاك عنهما، فهذا دليل على انه بشر كسائر بني ادم. وجميع الموجودات في السموات والارض ملك لله، يخلق ما يشاء ويوجده، وهو على كل شيء قدير. فحقيقه التوحيد توجب تفرد الله تعالى بصفات الربوبيه والالوهيه، فلا يشاركه احد من خلقه في ذلك، وكثيرا ما يقع الناس في الشرك والضلال بغلوهم في الانبياء والصالحين، كما غلا النصارى في المسيح، فالكون كله لله، والخلق بيده وحده، وما يظهر من خوارق وايات مرده الى الله. يخلق سبحانه ما يشاء، ويفعل ما يريد."},{"id":"687","s":5,"a":18,"at":"وقالت اليهود والنصارى نحن ابناء الله واحباؤه قل فلم يعذبكم بذنوبكم بل انتم بشر ممن خلق يغفر لمن يشاء ويعذب من يشاء ولله ملك السموات والارض وما بينهما واليه المصير","dt":"[18] وزعم اليهود والنصارى انهم ابناء الله واحباؤه، قل لهم -ايها الرسول-: فلاي شيء يعذبكم بذنوبكم؟ فلو كنتم احبابه ما عذبكم، فالله لا يحب الا من اطاعه، وقل لهم: بل انتم خلق مثل سائر بني ادم، ان احسنتم جوزيتم باحسانكم خيرا، وان اساتم جوزيتم باساءتكم شرا، فالله يغفر لمن يشاء، ويعذب من يشاء، وهو مالك الملك، يصرفه كما يشاء، واليه المرجع، فيحكم بين عباده، ويجازي كلا بما يستحق."},{"id":"688","s":5,"a":19,"at":"يااهل الكتاب قد جاءكم رسولنا يبين لكم على فتره من الرسل ان تقولوا ما جاءنا من بشير ولا نذير فقد جاءكم بشير ونذير والله على كل شيء قدير","dt":"[19] يا ايها اليهود والنصارى قد جاءكم رسولنا محمد -صلى الله عليه وسلم-، يبين لكم الحق والهدى بعد مده من الزمن بين ارساله وارسال عيسى بن مريم؛ لئلا تقولوا: ما جاءنا من بشير ولا نذير، فلا عذر لكم بعد ارساله اليكم، فقد جاءكم من الله رسول يبشر من امن به، وينذر من عصاه. والله على كل شيء قدير من عقاب العاصي وثواب المطيع."},{"id":"689","s":5,"a":20,"at":"واذ قال موسى لقومه ياقوم اذكروا نعمه الله عليكم اذ جعل فيكم انبياء وجعلكم ملوكا واتاكم ما لم يؤت احدا من العالمين","dt":"[20] واذكر -ايها الرسول- اذ قال موسى عليه السلام لقومه: يا بني اسرائيل اذكروا نعمه الله عليكم، اذ جعل فيكم انبياء، وجعلكم ملوكا تملكون امركم بعد ان كنتم مملوكين لفرعون وقومه، وقد منحكم من نعمه صنوفا لم يمنحها احدا من عالمي زمانكم."},{"id":"690","s":5,"a":21,"at":"ياقوم ادخلوا الارض المقدسه التي كتب الله لكم ولا ترتدوا على ادباركم فتنقلبوا خاسرين","dt":"[21] يا قوم ادخلوا الارض المقدسه -اي المطهره، وهي «بيت المقدس» وما حولها- التي وعد الله ان تدخلوها وتقاتلوا من فيها من الكفار، ولا ترجعوا عن قتال الجبارين، فتخسروا خير الدنيا وخير الاخره."},{"id":"691","s":5,"a":22,"at":"قالوا ياموسى ان فيها قوما جبارين وانا لن ندخلها حتى يخرجوا منها فان يخرجوا منها فانا داخلون","dt":"[22] قالوا: يا موسى، ان فيها قوما اشداء اقوياء، لا طاقه لنا بحربهم، وانا لن نستطيع دخولها وهم فيها، فان يخرجوا منها فانا داخلون."},{"id":"692","s":5,"a":23,"at":"قال رجلان من الذين يخافون انعم الله عليهما ادخلوا عليهم الباب فاذا دخلتموه فانكم غالبون وعلى الله فتوكلوا ان كنتم مؤمنين","dt":"[23] قال رجلان من الذين يخشون الله تعالى، انعم الله عليهما بطاعته وطاعه نبيه، لبني اسرائيل: ادخلوا على هؤلاء الجبارين باب مدينتهم، اخذا بالاسباب، فاذا دخلتم الباب غلبتموهم، وعلى الله وحده فتوكلوا، ان كنتم مصدقين رسوله فيما جاءكم به، عاملين بشرعه."},{"id":"693","s":5,"a":24,"at":"قالوا ياموسى انا لن ندخلها ابدا ما داموا فيها فاذهب انت وربك فقاتلا انا هاهنا قاعدون","dt":"[24] قال قوم موسى له: انا لن ندخل المدينه ابدا ما دام الجبارون فيها، فاذهب انت وربك فقاتلاهم، اما نحن فقاعدون هاهنا ولن نقاتلهم. وهذا اصرار منهم على مخالفه موسى عليه السلام."},{"id":"694","s":5,"a":25,"at":"قال رب اني لا املك الا نفسي واخي فافرق بيننا وبين القوم الفاسقين","dt":"[25] توجه موسى الى ربه داعيا: اني لا اقدر الا على نفسي واخي، فاحكم بيننا وبين القوم الفاسقين."},{"id":"695","s":5,"a":26,"at":"قال فانها محرمه عليهم اربعين سنه يتيهون في الارض فلا تاس على القوم الفاسقين","dt":"[26] قال الله لنبيه موسى عليه السلام: ان الارض المقدسه محرم على هؤلاء اليهود دخولها اربعين سنه، يتيهون في الارض حائرين ، فلا تاسف -يا موسى- على القوم الخارجين عن طاعتي."},{"id":"696","s":5,"a":27,"at":"واتل عليهم نبا ابني ادم بالحق اذ قربا قربانا فتقبل من احدهما ولم يتقبل من الاخر قال لاقتلنك قال انما يتقبل الله من المتقين","dt":"[27] واقصص -ايها الرسول- على بني اسرائيل خبر ابني ادم قابيل وهابيل، وهو خبر حق: حين قدم كل منهما قربانا -وهو ما يتقرب به الى الله تعالى -فتقبل الله قربان هابيل؛ لانه كان تقيا، ولم يتقبل قربان قابيل؛ لانه لم يكن تقيا، فحسد قابيل اخاه، وقال: لاقتلنك، فرد هابيل قائلا: انما يتقبل الله ممن يخشونه."},{"id":"697","s":5,"a":28,"at":"لئن بسطت الي يدك لتقتلني ما انا بباسط يدي اليك لاقتلك اني اخاف الله رب العالمين","dt":"[28] وقال هابيل واعظا اخاه: لئن مددت الي يدك لتقتلني لا تجد مني مثل فعلك، اني اخشى الله رب الخلائق اجمعين."},{"id":"698","s":5,"a":29,"at":"اني اريد ان تبوء باثمي واثمك فتكون من اصحاب النار وذلك جزاء الظالمين","dt":"[29] اني اريد ان ترجع حاملا اثم قتلي، واثمك الذي عليك قبل ذلك، فتكون من اهل النار وملازميها، وذلك جزاء المعتدين."},{"id":"699","s":5,"a":30,"at":"فطوعت له نفسه قتل اخيه فقتله فاصبح من الخاسرين","dt":"[30] فزينت لقابيل نفسه ان يقتل اخاه، فقتله، فاصبح من الخاسرين الذين باعوا اخرتهم بدنياهم."},{"id":"700","s":5,"a":31,"at":"فبعث الله غرابا يبحث في الارض ليريه كيف يواري سواه اخيه قال ياويلتى اعجزت ان اكون مثل هذا الغراب فاواري سواه اخي فاصبح من النادمين","dt":"[31] لما قتل قابيل اخاه لم يعرف ما يصنع بجسده، فارسل الله غرابا يحفر حفره في الارض ليدفن فيها غرابا ميتا؛ ليدل قابيل كيف يدفن جثمان اخيه؟ فتعجب قابيل، وقال: اعجزت ان اصنع مثل صنيع هذا الغراب فاستر عوره اخي؟ فدفن قابيل اخاه، فعاقبه الله بالندامه بعد ان رجع بالخسران."},{"id":"701","s":5,"a":32,"at":"من اجل ذلك كتبنا على بني اسرائيل انه من قتل نفسا بغير نفس او فساد في الارض فكانما قتل الناس جميعا ومن احياها فكانما احيا الناس جميعا ولقد جاءتهم رسلنا بالبينات ثم ان كثيرا منهم بعد ذلك في الارض لمسرفون","dt":"[32] بسبب جنايه القتل هذه شرعنا لبني اسرائيل انه من قتل نفسا بغير سبب من قصاص، او فساد في الارض باي نوع من انواع الفساد الموجب للقتل كالشرك والمحاربه، فكانما قتل الناس جميعا فيما استوجب من عظيم العقوبه من الله، وانه من امتنع عن قتل نفس حرمها الله فكانما احيا الناس جميعا؛ فالحفاظ على حرمه انسان واحد حفاظ على حرمات الناس كلهم. ولقد اتت بني اسرائيل رسلنا بالحجج والدلائل على صحه ما دعوهم اليه من الايمان بربهم، واداء ما فرض عليهم، ثم ان كثيرا منهم بعد مجيء الرسل اليهم لمتجاوزون حدود الله بارتكاب محارم الله وترك اوامره."},{"id":"702","s":5,"a":33,"at":"انما جزاء الذين يحاربون الله ورسوله ويسعون في الارض فسادا ان يقتلوا او يصلبوا او تقطع ايديهم وارجلهم من خلاف او ينفوا من الارض ذلك لهم خزي في الدنيا ولهم في الاخره عذاب عظيم","dt":"[33] انما جزاء الذين يحاربون الله، ويبارزونه بالعداوه، ويعتدون على احكامه، وعلى احكام رسوله، ويفسدون في الارض بقتل الانفس، وسلب الاموال، ان يقتلوا، او يصلبوا مع القتل [والصلب: ان يشد الجاني على خشبه] او تقطع يد المحارب اليمنى ورجله اليسرى، او ينفوا الى بلد غير بلدهم، ويحبسوا في سجن ذلك البلد حتى تظهر توبتهم. وهذا الجزاء الذي اعده الله للمحاربين هو ذل في الدنيا، ولهم في الاخره عذاب شديد ان لم يتوبوا."},{"id":"703","s":5,"a":34,"at":"الا الذين تابوا من قبل ان تقدروا عليهم فاعلموا ان الله غفور رحيم","dt":"[34] لكن من اتى من المحاربين من قبل ان تقدروا عليهم، وجاء طائعا نادما فانه يسقط عنه ما كان لله، فاعلموا -ايها المؤمنون- ان الله غفور لعباده، رحيم بهم."},{"id":"704","s":5,"a":35,"at":"ياايها الذين امنوا اتقوا الله وابتغوا اليه الوسيله وجاهدوا في سبيله لعلكم تفلحون","dt":"[35] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، خافوا الله، وتقربوا اليه بطاعته والعمل بما يرضيه، وجاهدوا في سبيله؛ كي تفوزوا بجناته."},{"id":"705","s":5,"a":36,"at":"ان الذين كفروا لو ان لهم ما في الارض جميعا ومثله معه ليفتدوا به من عذاب يوم القيامه ما تقبل منهم ولهم عذاب اليم","dt":"[36] ان الذين جحدوا وحدانيه الله، وشريعته، لو انهم ملكوا جميع ما في الارض، وملكوا مثله معه، وارادوا ان يفتدوا انفسهم يوم القيامه من عذاب الله بما ملكوا، ما تقبل الله ذلك منهم، ولهم عذاب موجع."},{"id":"706","s":5,"a":37,"at":"يريدون ان يخرجوا من النار وما هم بخارجين منها ولهم عذاب مقيم","dt":"[37] يريد هؤلاء الكافرون الخروج من النار لما يلاقونه من اهوالها، ولا سبيل لهم الى ذلك، ولهم عذاب دائم."},{"id":"707","s":5,"a":38,"at":"والسارق والسارقه فاقطعوا ايديهما جزاء بما كسبا نكالا من الله والله عزيز حكيم","dt":"[38] والسارق والسارقه فاقطعوا -يا ولاه الامر- ايديهما بمقتضى الشرع؛ مجازاه لهما على اخذهما اموال الناس بغير حق، وعقوبه يمنع الله بها غيرهما ان يصنع مثل صنيعهما. والله عزيز في ملكه، حكيم في امره ونهيه."},{"id":"708","s":5,"a":39,"at":"فمن تاب من بعد ظلمه واصلح فان الله يتوب عليه ان الله غفور رحيم","dt":"[39] فمن تاب من بعد سرقته، واصلح في كل اعماله، فان الله يقبل توبته. ان الله غفور لعباده، رحيم بهم."},{"id":"709","s":5,"a":40,"at":"الم تعلم ان الله له ملك السموات والارض يعذب من يشاء ويغفر لمن يشاء والله على كل شيء قدير","dt":"[40] الم تعلم -ايها الرسول- ان الله خالق الكون ومدبره ومالكه، وانه تعالى الفعال لما يريد، يعذب من يشاء، ويغفر لمن يشاء، وهو على كل شيء قدير."},{"id":"710","s":5,"a":41,"at":"ياايها الرسول لا يحزنك الذين يسارعون في الكفر من الذين قالوا امنا بافواههم ولم تؤمن قلوبهم ومن الذين هادوا سماعون للكذب سماعون لقوم اخرين لم ياتوك يحرفون الكلم من بعد مواضعه يقولون ان اوتيتم هذا فخذوه وان لم تؤتوه فاحذروا ومن يرد الله فتنته فلن تملك له من الله شيئا اولئك الذين لم يرد الله ان يطهر قلوبهم لهم في الدنيا خزي ولهم في الاخره عذاب عظيم","dt":"[41] يا ايها الرسول لا يحزنك الذين يسارعون في جحود نبوتك من المنافقين الذين اظهروا الاسلام وقلوبهم خاليه منه، فاني ناصرك عليهم. ولا يحزنك تسرع اليهود الى انكار نبوتك، فانهم قوم يستمعون للكذب، ويقبلون ما يفتريه احبارهم، ويستجيبون لقوم اخرين لا يحضرون مجلسك، وهؤلاء الاخرون يبدلون كلام الله من بعد ما عقلوه، ويقولون: ان جاءكم من محمد ما يوافق الذي بدلناه وحرفناه من احكام التوراه فاعملوا به، وان جاءكم منه ما يخالفه فاحذروا قبوله، والعمل به. ومن يشا الله ضلالته فلن تستطيع -ايها الرسول- دفع ذلك عنه، ولا تقدر على هدايته. وان هؤلاء المنافقين واليهود لم يرد الله ان يطهر قلوبهم من دنس الكفر، لهم الذل والفضيحه في الدنيا، ولهم في الاخره عذاب عظيم."},{"id":"711","s":5,"a":42,"at":"سماعون للكذب اكالون للسحت فان جاءوك فاحكم بينهم او اعرض عنهم وان تعرض عنهم فلن يضروك شيئا وان حكمت فاحكم بينهم بالقسط ان الله يحب المقسطين","dt":"[42] هؤلاء اليهود يجمعون بين استماع الكذب واكل الحرام، فان جاؤوك يتحاكمون اليك فاقض بينهم، او اتركهم، وان لم تحكم بينهم فلن يقدروا على ان يضروك بشيء، وان حكمت فاحكم بينهم بالعدل. ان الله يحب العادلين."},{"id":"712","s":5,"a":43,"at":"وكيف يحكمونك وعندهم التوراه فيها حكم الله ثم يتولون من بعد ذلك وما اولئك بالمؤمنين","dt":"[43] ان صنيع هؤلاء اليهود عجيب، فهم يحتكمون اليك -ايها الرسول- وهم لا يؤمنون بك، ولا بكتابك، مع ان التوراه التي يؤمنون بها عندهم، فيها حكم الله، ثم يتولون من بعد حكمك اذا لم يرضهم، فجمعوا بين الكفر بشرعهم، والاعراض عن حكمك، وليس اولئك المتصفون بتلك الصفات، بالمؤمنين بالله وبك وبما تحكم به."},{"id":"713","s":5,"a":44,"at":"انا انزلنا التوراه فيها هدى ونور يحكم بها النبيون الذين اسلموا للذين هادوا والربانيون والاحبار بما استحفظوا من كتاب الله وكانوا عليه شهداء فلا تخشوا الناس واخشون ولا تشتروا باياتي ثمنا قليلا ومن لم يحكم بما انزل الله فاولئك هم الكافرون","dt":"[44] انا انزلنا التوراه فيها ارشاد من الضلاله، وبيان للاحكام، وقد حكم بها النبيون -الذين انقادوا لحكم الله، واقروا به- بين اليهود، ولم يخرجوا عن حكمها ولم يحرفوها، وحكم بها عباد اليهود وفقهاؤهم الذين يربون الناس بشرع الله؛ ذلك ان انبياءهم قد استامنوهم على تبليغ التوراه، وفقه كتاب الله والعمل به، وكان الربانيون والاحبار شهداء على ان انبياءهم قد قضوا في اليهود بكتاب الله. ويقول تعالى لعلماء اليهود واحبارهم: فلا تخشوا الناس في تنفيذ حكمي؛ فانهم لا يقدرون على نفعكم ولا ضركم، ولكن اخشوني فاني انا النافع الضار، ولا تاخذوا بترك الحكم بما انزلت عوضا حقيرا، فالحكم بغير ما انزل الله من اعمال اهل الكفر، فالذين يبدلون حكم الله الذي انزله في كتابه، فيكتمونه، ويجحدونه، ويحكمون بغيره معتقدين حله وجوازه، فاولئك هم الكافرون."},{"id":"714","s":5,"a":45,"at":"وكتبنا عليهم فيها ان النفس بالنفس والعين بالعين والانف بالانف والاذن بالاذن والسن بالسن والجروح قصاص فمن تصدق به فهو كفاره له ومن لم يحكم بما انزل الله فاولئك هم الظالمون","dt":"[45] وفرضنا عليهم في التوراه ان النفس تقتل بالنفس، والعين تفقا بالعين، والانف يجدع بالانف، والاذن تقطع بالاذن، والسن تقلع بالسن، وانه يقتص في الجروح، فمن تجاوز عن حقه في الاقتصاص من المعتدي فذلك تكفير لبعض ذنوب المعتدى عليه وازاله لها. ومن لم يحكم بما انزل الله في القصاص وغيره، فاولئك هم المتجاوزون حدود الله."},{"id":"715","s":5,"a":46,"at":"وقفينا على اثارهم بعيسى ابن مريم مصدقا لما بين يديه من التوراه واتيناه الانجيل فيه هدى ونور ومصدقا لما بين يديه من التوراه وهدى وموعظه للمتقين","dt":"[46] واتبعنا انبياء بني اسرائيل عيسى بن مريم مؤمنا بما في التوراه، عاملا بما فيها مما لم ينسخه كتابه، وانزلنا اليه الانجيل هاديا الى الحق، ومبينا لما جهله الناس من حكم الله، وشاهدا على صدق التوراه بما اشتمل عليه من احكامها، وقد جعلناه بيانا للذين يخافون الله وزاجرا لهم عن ارتكاب المحرمات."},{"id":"716","s":5,"a":47,"at":"وليحكم اهل الانجيل بما انزل الله فيه ومن لم يحكم بما انزل الله فاولئك هم الفاسقون","dt":"[47] وليحكم اهل الانجيل الذين ارسل اليهم عيسى بما انزل الله فيه. ومن لم يحكم بما انزل الله فاولئك هم الخارجون عن امره، العاصون له."},{"id":"717","s":5,"a":48,"at":"وانزلنا اليك الكتاب بالحق مصدقا لما بين يديه من الكتاب ومهيمنا عليه فاحكم بينهم بما انزل الله ولا تتبع اهواءهم عما جاءك من الحق لكل جعلنا منكم شرعه ومنهاجا ولو شاء الله لجعلكم امه واحده ولكن ليبلوكم في ما اتاكم فاستبقوا الخيرات الى الله مرجعكم جميعا فينبئكم بما كنتم فيه تختلفون","dt":"[48] وانزلنا اليك -ايها الرسول- القران، وكل ما فيه حق يشهد على صدق الكتب قبله، وانها من عند الله، مصدقا لما فيها من صحه، ومبينا لما فيها من تحريف، ناسخا لبعض شرائعها، فاحكم بين المحتكمين اليك من اليهود بما انزل الله اليك في هذا القران، ولا تنصرف عن الحق الذي امرك الله به الى اهوائهم وما اعتادوه، فقد جعلنا لكل امه شريعه، وطريقه واضحه يعملون بها. ولو شاء الله لجعل شرائعكم واحده، ولكنه تعالى خالف بينها ليختبركم، فيظهر المطيع من العاصي، فسارعوا الى ما هو خير لكم في الدارين بالعمل بما في القران، فان مصيركم الى الله، فيخبركم بما كنتم فيه تختلفون، ويجزي كلا بعمله."},{"id":"718","s":5,"a":49,"at":"وان احكم بينهم بما انزل الله ولا تتبع اهواءهم واحذرهم ان يفتنوك عن بعض ما انزل الله اليك فان تولوا فاعلم انما يريد الله ان يصيبهم ببعض ذنوبهم وان كثيرا من الناس لفاسقون","dt":"[49] واحكم -ايها الرسول- بين اليهود بما انزل الله اليك في القران، ولا تتبع اهواء الذين يحتكمون اليك، واحذرهم ان يصدوك عن بعض ما انزل الله اليك فتترك العمل به، فان اعرض هؤلاء عما تحكم به فاعلم ان الله يريد ان يصرفهم عن الهدى؛ بسبب ذنوب اكتسبوها من قبل. وان كثيرا من الناس لخارجون عن طاعه ربهم."},{"id":"719","s":5,"a":50,"at":"افحكم الجاهليه يبغون ومن احسن من الله حكما لقوم يوقنون","dt":"[50] ايريد هؤلاء اليهود ان تحكم بينهم بما تعارف عليه المشركون عبده الاوثان من الضلالات والجهالات؟! لا يكون ذلك ولا يليق ابدا. ومن اعدل من الله في حكمه لمن عقل عن الله شرعه، وامن به، وايقن ان حكم الله هو الحق؟"},{"id":"720","s":5,"a":51,"at":"ياايها الذين امنوا لا تتخذوا اليهود والنصارى اولياء بعضهم اولياء بعض ومن يتولهم منكم فانه منهم ان الله لا يهدي القوم الظالمين","dt":"[51] يا ايها الذين امنوا لا تتخذوا اليهود والنصارى حلفاء وانصارا على اهل الايمان؛ ذلك انهم لا يوادون المؤمنين، فاليهود يوالي بعضهم بعضا، وكذلك النصارى، وكلا الفريقين يجتمع على عداوتكم. وانتم -ايها المؤمنون- اجدر بان ينصر بعضكم بعضا. ومن يتولهم منكم فانه يصير من جملتهم، وحكمه حكمهم. ان الله لا يوفق الظالمين الذين يتولون الكافرين."},{"id":"721","s":5,"a":52,"at":"فترى الذين في قلوبهم مرض يسارعون فيهم يقولون نخشى ان تصيبنا دائره فعسى الله ان ياتي بالفتح او امر من عنده فيصبحوا على ما اسروا في انفسهم نادمين","dt":"[52] يخبر الله تعالى عن جماعه من المنافقين انهم كانوا يبادرون في مواده اليهود؛ لما في قلوبهم من الشك والنفاق، ويقولون: انما نوادهم خشيه ان يظفروا بالمسلمين فيصيبونا معهم، قال الله تعالى ذكره: فعسى الله ان ياتي بالفتح -اي فتح «مكه»- وينصر نبيه، ويظهر الاسلام والمسلمين على الكفار، او يهيئ من الامور ما تذهب به قوه اليهود والنصارى، فيخضعوا للمسلمين، فحينئذ يندم المنافقون على ما اضمروا في انفسهم من موالاتهم."},{"id":"722","s":5,"a":53,"at":"ويقول الذين امنوا اهؤلاء الذين اقسموا بالله جهد ايمانهم انهم لمعكم حبطت اعمالهم فاصبحوا خاسرين","dt":"[53] وحينئذ يقول بعض المؤمنين لبعض متعجبين من حال المنافقين -اذا كشف امرهم-: اهؤلاء الذين اقسموا باغلظ الايمان انهم لمعنا؟! بطلت اعمال المنافقين التي عملوها في الدنيا، فلا ثواب لهم عليها؛ لانهم عملوها على غير ايمان، فخسروا الدنيا والاخره."},{"id":"723","s":5,"a":54,"at":"ياايها الذين امنوا من يرتد منكم عن دينه فسوف ياتي الله بقوم يحبهم ويحبونه اذله على المؤمنين اعزه على الكافرين يجاهدون في سبيل الله ولا يخافون لومه لائم ذلك فضل الله يؤتيه من يشاء والله واسع عليم","dt":"[54] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه من يرجع منكم عن دينه، ويستبدل به اليهوديه او النصرانيه او غير ذلك، فلن يضروا الله شيئا، وسوف ياتي الله بقوم خير منهم يحبهم ويحبونه، رحماء بالمؤمنين اشداء على الكافرين، يجاهدون اعداء الله، ولا يخافون في ذات الله احدا. ذلك الانعام من فضل الله يؤتيه من اراد، والله واسع الفضل، عليم بمن يستحقه من عباده."},{"id":"724","s":5,"a":55,"at":"انما وليكم الله ورسوله والذين امنوا الذين يقيمون الصلاه ويؤتون الزكاه وهم راكعون","dt":"[55] انما ناصركم -ايها المؤمنون- الله ورسوله، والمؤمنون الذين يحافظون على الصلاه المفروضه، ويؤدون الزكاه عن رضا نفس، وهم خاضعون لله."},{"id":"725","s":5,"a":56,"at":"ومن يتول الله ورسوله والذين امنوا فان حزب الله هم الغالبون","dt":"[56] ومن وثق بالله وتولى الله ورسوله والمؤمنين، فهو من حزب الله، وحزب الله هم الغالبون المنتصرون."},{"id":"726","s":5,"a":57,"at":"ياايها الذين امنوا لا تتخذوا الذين اتخذوا دينكم هزوا ولعبا من الذين اوتوا الكتاب من قبلكم والكفار اولياء واتقوا الله ان كنتم مؤمنين","dt":"[57] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه لا تتخذوا الذين يستهزئون ويتلاعبون بدينكم من اهل الكتاب والكفار اولياء، وخافوا الله ان كنتم مؤمنين به وبشرعه."},{"id":"727","s":5,"a":58,"at":"واذا ناديتم الى الصلاه اتخذوها هزوا ولعبا ذلك بانهم قوم لا يعقلون","dt":"[58] واذا اذن مؤذنكم -ايها المؤمنون- بالصلاه سخر اليهود والنصارى والمشركون واستهزؤوا من دعوتكم اليها؛ وذلك بسبب جهلهم بربهم، وانهم لا يعقلون حقيقه العباده."},{"id":"728","s":5,"a":59,"at":"قل يااهل الكتاب هل تنقمون منا الا ان امنا بالله وما انزل الينا وما انزل من قبل وان اكثركم فاسقون","dt":"[59] قل -ايها الرسول- لهؤلاء المستهزئين من اهل الكتاب: ما تجدونه مطعنا او عيبا هو محمده لنا: من ايماننا بالله وكتبه المنزله علينا، وعلى من كان قبلنا، وايماننا بان اكثركم خارجون عن الطريق المستقيم"},{"id":"729","s":5,"a":60,"at":"قل هل انبئكم بشر من ذلك مثوبه عند الله من لعنه الله وغضب عليه وجعل منهم القرده والخنازير وعبد الطاغوت اولئك شر مكانا واضل عن سواء السبيل","dt":"[60] قل -ايها النبي- للمؤمنين: هل اخبركم بمن يجازى يوم القيامه جزاء اشد من جزاء هؤلاء الفاسقين؟انهم اسلافهم الذين طردهم الله من رحمته وغضب عليهم، ومسخ خلقهم، فجعل منهم القرده والخنازير؛ بعصيانهم وافترائهم وتكبرهم، كما كان منهم عباد الطاغوت [وهو كل ما عبد من دون الله وهو راض]، لقد ساء مكانهم في الاخره، وضل سعيهم في الدنيا عن الطريق الصحيح."},{"id":"730","s":5,"a":61,"at":"واذا جاءوكم قالوا امنا وقد دخلوا بالكفر وهم قد خرجوا به والله اعلم بما كانوا يكتمون","dt":"[61] واذا جاءكم -ايها المؤمنون- منافقو اليهود، قالوا: امنا، وهم مقيمون على كفرهم، قد دخلوا عليكم بكفرهم الذي يعتقدونه بقلوبهم، ثم خرجوا وهم مصرون عليه، والله اعلم بسرائرهم، وان اظهروا خلاف ذلك."},{"id":"731","s":5,"a":62,"at":"وترى كثيرا منهم يسارعون في الاثم والعدوان واكلهم السحت لبئس ما كانوا يعملون","dt":"[62] وترى -ايها الرسول- كثيرا من اليهود يبادرون الى المعاصي من قول الكذب والزور، والاعتداء على احكام الله، واكل اموال الناس بالباطل، لقد ساء عملهم واعتداؤهم."},{"id":"732","s":5,"a":63,"at":"لولا ينهاهم الربانيون والاحبار عن قولهم الاثم واكلهم السحت لبئس ما كانوا يصنعون","dt":"[63] هلا ينهى هؤلاء الذين يسارعون في الاثم والعدوان ائمتهم وعلماؤهم، عن قول الكذب والزور، واكل اموال الناس بالباطل، لقد ساء صنيعهم حين تركوا النهي عن المنكر."},{"id":"733","s":5,"a":64,"at":"وقالت اليهود يد الله مغلوله غلت ايديهم ولعنوا بما قالوا بل يداه مبسوطتان ينفق كيف يشاء وليزيدن كثيرا منهم ما انزل اليك من ربك طغيانا وكفرا والقينا بينهم العداوه والبغضاء الى يوم القيامه كلما اوقدوا نارا للحرب اطفاها الله ويسعون في الارض فسادا والله لا يحب المفسدين","dt":"[64] يطلع الله نبيه على شيء من ماثم اليهود -وكان مما يسرونه فيما بينهم- انهم قالوا: يد الله محبوسه عن فعل الخيرات، بخل علينا بالرزق والتوسعه، وذلك حين لحقهم جدب وقحط. غلت ايديهم، اي: حبست ايديهم هم عن فعل الخيرات، وطردهم الله من رحمته بسبب قولهم. وليس الامر كما يفترونه على ربهم، بل يداه مبسوطتان لا حجر عليه، ولا مانع يمنعه من الانفاق، فانه الجواد الكريم، ينفق على مقتضى الحكمه وما فيه مصلحه العباد . لكنهم سوف يزدادون طغيانا وكفرا بسبب حقدهم وحسدهم؛ لان الله قد اصطفاك بالرساله. ويخبر تعالى ان طوائف اليهود سيظلون الى يوم القيامه يعادي بعضهم بعضا، وينفر بعضهم من بعض، كلما تامروا على الكيد للمسلمين باثاره الفتن واشعال نار الحرب رد الله كيدهم، وفرق شملهم، ولا يزال اليهود يعملون بمعاصي الله مما ينشا عنها الفساد والاضطراب في الارض. والله تعالى لا يحب المفسدين. وفي الايه اثبات لصفه اليدين لله سبحانه وتعالى كما يليق به من غير تشبيه ولا تكييف."},{"id":"734","s":5,"a":65,"at":"ولو ان اهل الكتاب امنوا واتقوا لكفرنا عنهم سيئاتهم ولادخلناهم جنات النعيم","dt":"[65] ولو ان اليهود والنصارى صدقوا الله ورسوله، وامتثلوا اوامر الله واجتنبوا نواهيه، لكفرنا عنهم ذنوبهم، ولادخلناهم جنات النعيم في الدار الاخره."},{"id":"735","s":5,"a":66,"at":"ولو انهم اقاموا التوراه والانجيل وما انزل اليهم من ربهم لاكلوا من فوقهم ومن تحت ارجلهم منهم امه مقتصده وكثير منهم ساء ما يعملون","dt":"[66] ولو انهم عملوا بما في التوراه والانجيل، وبما انزل عليك ايها الرسول -وهو القران الكريم- لرزقوا من كل سبيل، فانزلنا عليهم المطر، وانبتنا لهم الثمر، وهذا جزاء الدنيا. وان من اهل الكتاب فريقا معتدلا ثابتا على الحق، وكثير منهم ساء عمله، وضل عن سواء السبيل."},{"id":"736","s":5,"a":67,"at":"ياايها الرسول بلغ ما انزل اليك من ربك وان لم تفعل فما بلغت رسالته والله يعصمك من الناس ان الله لا يهدي القوم الكافرين","dt":"[67] يا ايها الرسول بلغ وحي الله الذي انزل اليك من ربك، وان قصرت في البلاغ فكتمت منه شيئا، فانك لم تبلغ رساله ربك، وقد بلغ -صلى الله عليه وسلم- رساله ربه كامله، فمن زعم انه كتم شيئا مما انزل عليه، فقد اعظم على الله ورسوله الفريه. والله تعالى حافظك وناصرك على اعدائك، فليس عليك الا البلاغ. ان الله لا يوفق للرشد من حاد عن سبيل الحق، وجحد ما جئت به من عند الله."},{"id":"737","s":5,"a":68,"at":"قل يااهل الكتاب لستم على شيء حتى تقيموا التوراه والانجيل وما انزل اليكم من ربكم وليزيدن كثيرا منهم ما انزل اليك من ربك طغيانا وكفرا فلا تاس على القوم الكافرين","dt":"[68] قل -ايها الرسول- لليهود والنصارى: انكم لستم على حظ من الدين ما دمتم لم تعملوا بما في التوراه والانجيل، وما جاءكم به محمد -صلى الله عليه وسلم- من القران، وان كثيرا من اهل الكتاب لا يزيدهم انزال القران اليك الا تجبرا وجحودا، فهم يحسدونك؛ لان الله بعثك بهذه الرساله الخاتمه، التي بين فيها معايبهم، فلا تحزن -ايها الرسول- على تكذيبهم لك."},{"id":"738","s":5,"a":69,"at":"ان الذين امنوا والذين هادوا والصابئون والنصارى من امن بالله واليوم الاخر وعمل صالحا فلا خوف عليهم ولا هم يحزنون","dt":"[69] ان الذين امنوا (وهم المسلمون) واليهود -والصابئون كذلك (وهم قوم باقون على فطرتهم، ولا دين مقرر لهم يتبعونه)- والنصارى (وهم اتباع المسيح) من امن منهم بالله الايمان الكامل، وهو توحيد الله والتصديق بمحمد -صلى الله عليه وسلم- وبما جاء به، وامن باليوم الاخر، وعمل العمل الصالح، فلا خوف عليهم من اهوال يوم القيامه، ولا هم يحزنون على ما تركوه وراءهم في الدنيا."},{"id":"739","s":5,"a":70,"at":"لقد اخذنا ميثاق بني اسرائيل وارسلنا اليهم رسلا كلما جاءهم رسول بما لا تهوى انفسهم فريقا كذبوا وفريقا يقتلون","dt":"[70] لقد اخذنا العهد المؤكد على بني اسرائيل في التوراه بالسمع والطاعه، وارسلنا اليهم بذلك رسلنا، فنقضوا ما اخذ عليهم من العهد، واتبعوا اهواءهم، وكانوا كلما جاءهم رسول من اولئك الرسل بما لا تشتهيه انفسهم عادوه: فكذبوا فريقا من الرسل، وقتلوا فريقا اخر."},{"id":"740","s":5,"a":71,"at":"وحسبوا الا تكون فتنه فعموا وصموا ثم تاب الله عليهم ثم عموا وصموا كثير منهم والله بصير بما يعملون","dt":"[71] وظن هؤلاء العصاه من اليهود ان الله لن ياخذهم بالعذاب جزاء عصيانهم وعتوهم، فمضوا في شهواتهم، وعموا عن الهدى فلم يبصروه، وصموا عن سماع الحق فلم ينتفعوا به، فانزل الله بهم باسه، فتابوا فتاب الله عليهم، ثم عمي كثير منهم، وصموا، بعدما تبين لهم الحق، والله بصير باعمالهم خيرها وشرها وسيجازيهم عليها."},{"id":"741","s":5,"a":72,"at":"لقد كفر الذين قالوا ان الله هو المسيح ابن مريم وقال المسيح يابني اسرائيل اعبدوا الله ربي وربكم انه من يشرك بالله فقد حرم الله عليه الجنه وماواه النار وما للظالمين من انصار","dt":"[72] يقسم الله تعالى بان الذين قالوا: ان الله هو المسيح بن مريم، قد كفروا بمقالتهم هذه، واخبر تعالى ان المسيح قال لبني اسرائيل: اعبدوا الله وحده لا شريك له، فانا وانتم في العبوديه سواء. انه من يعبد مع الله غيره فقد حرم الله عليه الجنه، وجعل النار مستقره، وليس له ناصر ينقذه منها."},{"id":"742","s":5,"a":73,"at":"لقد كفر الذين قالوا ان الله ثالث ثلاثه وما من اله الا اله واحد وان لم ينتهوا عما يقولون ليمسن الذين كفروا منهم عذاب اليم","dt":"[73] لقد كفر من النصارى من قال: ان الله مجموع ثلاثه اشياء: هي الاب، والابن، وروح القدس. اما علم هؤلاء النصارى انه ليس للناس سوى معبود واحد، لم يلد ولم يولد، وان لم ينته اصحاب هذه المقاله عن افترائهم وكذبهم ليصيبنهم عذاب مؤلم موجع بسبب كفرهم بالله."},{"id":"743","s":5,"a":74,"at":"افلا يتوبون الى الله ويستغفرونه والله غفور رحيم","dt":"[74] افلا يرجع هؤلاء النصارى الى الله تعالى، ويتوبون عما قالوا، ويسالون الله تعالى المغفره؟ والله تعالى متجاوز عن ذنوب التائبين، رحيم بهم."},{"id":"744","s":5,"a":75,"at":"ما المسيح ابن مريم الا رسول قد خلت من قبله الرسل وامه صديقه كانا ياكلان الطعام انظر كيف نبين لهم الايات ثم انظر انى يؤفكون","dt":"[75] ما المسيح بن مريم - عليه السلام - الا رسول كمن تقدمه من الرسل، وامه قد صدقت تصديقا جازما علما وعملا، وهما كغيرهما من البشر يحتاجان الى الطعام، ولا يكون الها من يحتاج الى الطعام ليعيش. فتامل -ايها الرسول- حال هؤلاء الكفار. لقد وضحنا العلامات الداله على وحدانيتنا، وبطلان ما يدعونه في انبياء الله. ثم هم مع ذلك يضلون عن الحق الذي نهديهم اليه، ثم انظر كيف يصرفون عن الحق بعد هذا البيان؟"},{"id":"745","s":5,"a":76,"at":"قل اتعبدون من دون الله ما لا يملك لكم ضرا ولا نفعا والله هو السميع العليم","dt":"[76] قل -ايها الرسول- لهؤلاء الكفره: كيف تشركون مع الله من لا يقدر على ضركم، ولا على جلب نفع لكم؟ والله هو السميع لاقوال عباده، العليم باحوالهم."},{"id":"746","s":5,"a":77,"at":"قل يااهل الكتاب لا تغلوا في دينكم غير الحق ولا تتبعوا اهواء قوم قد ضلوا من قبل واضلوا كثيرا وضلوا عن سواء السبيل","dt":"[77] قل -ايها الرسول- للنصارى: لا تتجاوزوا الحق فيما تعتقدونه من امر المسيح، ولا تتبعوا اهواءكم، كما اتبع اليهود اهواءهم في امر الدين، فوقعوا في الضلال، وحملوا كثيرا من الناس على الكفر بالله، وخرجوا عن طريق الاستقامه الى طريق الغوايه والضلال."},{"id":"747","s":5,"a":78,"at":"لعن الذين كفروا من بني اسرائيل على لسان داود وعيسى ابن مريم ذلك بما عصوا وكانوا يعتدون","dt":"[78] يخبر تعالى انه طرد من رحمته الكافرين من بني اسرائيل في الكتاب الذي انزله على داود -عليه السلام- وهو الزبور، وفي الكتاب الذي انزله على عيسى -عليه السلام- وهو الانجيل؛ بسبب عصيانهم واعتدائهم على حرمات الله."},{"id":"748","s":5,"a":79,"at":"كانوا لا يتناهون عن منكر فعلوه لبئس ما كانوا يفعلون","dt":"[79] كان هؤلاء اليهود يجاهرون بالمعاصي ويرضونها، ولا ينهى بعضهم بعضا عن اي منكر فعلوه، وهذا من افعالهم السيئه، وبه استحقوا ان يطردوا من رحمه الله تعالى."},{"id":"749","s":5,"a":80,"at":"ترى كثيرا منهم يتولون الذين كفروا لبئس ما قدمت لهم انفسهم ان سخط الله عليهم وفي العذاب هم خالدون","dt":"[80] ترى -ايها الرسول- كثيرا من هؤلاء اليهود يتخذون المشركين اولياء لهم، ساء ما عملوه من الموالاه التي كانت سببا في غضب الله عليهم، وخلودهم في عذاب الله يوم القيامه."},{"id":"750","s":5,"a":81,"at":"ولو كانوا يؤمنون بالله والنبي وما انزل اليه ما اتخذوهم اولياء ولكن كثيرا منهم فاسقون","dt":"[81] ولو ان هؤلاء اليهود الذين يناصرون المشركين كانوا قد امنوا بالله تعالى والنبي محمد -صلى الله عليه وسلم-، واقروا بما انزل اليه -وهو القران الكريم- ما اتخذوا الكفار اصحابا وانصارا، ولكن كثيرا منهم خارجون عن طاعه الله ورسوله."},{"id":"751","s":5,"a":82,"at":"لتجدن اشد الناس عداوه للذين امنوا اليهود والذين اشركوا ولتجدن اقربهم موده للذين امنوا الذين قالوا انا نصارى ذلك بان منهم قسيسين ورهبانا وانهم لا يستكبرون","dt":"[82] لتجدن -ايها الرسول- اشد الناس عداوه للذين صدقوك وامنوا بك واتبعوك، اليهود؛ لعنادهم، وجحودهم، وغمطهم الحق، والذين اشركوا مع الله غيره، كعبده الاوثان وغيرهم، ولتجدن اقربهم موده للمسلمين الذين قالوا: انا نصارى؛ ذلك بان منهم علماء بدينهم متزهدين وعبادا في الصوامع متنسكين، وانهم متواضعون لا يستكبرون عن قبول الحق، وهؤلاء هم الذين قبلوا رساله محمد -صلى الله عليه وسلم-، وامنوا بها."},{"id":"752","s":5,"a":83,"at":"واذا سمعوا ما انزل الى الرسول ترى اعينهم تفيض من الدمع مما عرفوا من الحق يقولون ربنا امنا فاكتبنا مع الشاهدين","dt":"[83] ومما يدل على قرب مودتهم للمسلمين ان فريقا منهم [وهم وفد الحبشه لما سمعوا القران] فاضت اعينهم من الدمع فايقنوا انه حق منزل من عند الله تعالى، وصدقوا بالله واتبعوا رسوله، وتضرعوا الى الله ان يكرمهم بشرف الشهاده مع امه محمد -عليه السلام- على الامم يوم القيامه."},{"id":"753","s":5,"a":84,"at":"وما لنا لا نؤمن بالله وما جاءنا من الحق ونطمع ان يدخلنا ربنا مع القوم الصالحين","dt":"[84] وقالوا: واي لوم علينا في ايماننا بالله، وتصديقنا بالحق الذي جاءنا به محمد -صلى الله عليه وسلم- من عند الله، واتباعنا له، ونرجو ان يدخلنا ربنا مع اهل طاعته في جنته يوم القيامه؟"},{"id":"754","s":5,"a":85,"at":"فاثابهم الله بما قالوا جنات تجري من تحتها الانهار خالدين فيها وذلك جزاء المحسنين","dt":"[85] فجزاهم الله بما قالوا من الاعتزاز بايمانهم بالاسلام، وطلبهم ان يكونوا مع القوم الصالحين، جنات تجري من تحت قصورها واشجارها الانهار، ماكثين فيها لا يخرجون منها، ولا يحولون عنها، وذلك جزاء احسانهم في القول والعمل."},{"id":"755","s":5,"a":86,"at":"والذين كفروا وكذبوا باياتنا اولئك اصحاب الجحيم","dt":"[86] والذين جحدوا وحدانيه الله وانكروا نبوه محمد -صلى الله عليه وسلم-، وكذبوا باياته المنزله على رسله، اولئك هم اصحاب النار الملازمون لها."},{"id":"756","s":5,"a":87,"at":"ياايها الذين امنوا لا تحرموا طيبات ما احل الله لكم ولا تعتدوا ان الله لا يحب المعتدين","dt":"[87] يا ايها الذين امنوا لا تحرموا طيبات احلها الله لكم من المطاعم والمشارب ونكاح النساء، فتضيقوا ما وسع الله عليكم، ولا تتجاوزوا حدود ما حرم الله. ان الله لا يحب المعتدين."},{"id":"757","s":5,"a":88,"at":"وكلوا مما رزقكم الله حلالا طيبا واتقوا الله الذي انتم به مؤمنون","dt":"[88] وتمتعوا -ايها المؤمنون- بالحلال الطيب مما اعطاكم الله ومنحكم اياه، واتقوا الله بامتثال اوامره، واجتناب نواهيه؛ فان ايمانكم بالله يوجب عليكم تقواه ومراقبته."},{"id":"758","s":5,"a":89,"at":"لا يؤاخذكم الله باللغو في ايمانكم ولكن يؤاخذكم بما عقدتم الايمان فكفارته اطعام عشره مساكين من اوسط ما تطعمون اهليكم او كسوتهم او تحرير رقبه فمن لم يجد فصيام ثلاثه ايام ذلك كفاره ايمانكم اذا حلفتم واحفظوا ايمانكم كذلك يبين الله لكم اياته لعلكم تشكرون","dt":"[89] لا يعاقبكم الله -ايها المسلمون- فيما لا تقصدون عقده من الايمان، مثل قول بعضكم: لا والله، وبلى والله، ولكن يعاقبكم فيما قصدتم عقده بقلوبكم، فاذا لم تفوا باليمين فاثم ذلك يمحوه الله بما تقدمونه مما شرعه الله لكم كفاره من اطعام عشره محتاجين لا يملكون ما يكفيهم ويسد حاجتهم، لكل مسكين نصف صاع من اوسط طعام اهل البلد، او كسوتهم، لكل مسكين ما يكفي في الكسوه عرفا، او اعتاق مملوك من الرق، فالحالف الذي لم يف بيمينه مخير بين هذه الامور الثلاثه، فمن لم يجد شيئا من ذلك فعليه صيام ثلاثه ايام. تلك مكفرات عدم الوفاء بايمانكم، واحفظوا -ايها المسلمون- ايمانكم: باجتناب الحلف، او الوفاء ان حلفتم، او الكفاره اذا لم تفوا بها. كما بين الله لكم حكم الايمان والتحلل منها يبين لكم احكام دينه؛ لتشكروا له على هدايته اياكم الى الطريق المستقيم."},{"id":"759","s":5,"a":90,"at":"ياايها الذين امنوا انما الخمر والميسر والانصاب والازلام رجس من عمل الشيطان فاجتنبوه لعلكم تفلحون","dt":"[90] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه انما الخمر: وهي كل مسكر يغطي العقل، والميسر: وهو القمار، -وذلك يشمل المراهنات ونحوها، مما فيه عوض من الجانبين، وصد عن ذكر الله- والانصاب: وهي الحجاره التي كان المشركون يذبحون عندها تعظيما لها، وما ينصب للعباده تقربا اليه، والازلام: وهي القداح التي يستقسم بها الكفار قبل الاقدام على الامر، او الاحجام عنه، ان ذلك كله اثم من تزيين الشيطان، فابتعدوا عن هذه الاثام، لعلكم تفوزون بالجنه."},{"id":"760","s":5,"a":91,"at":"انما يريد الشيطان ان يوقع بينكم العداوه والبغضاء في الخمر والميسر ويصدكم عن ذكر الله وعن الصلاه فهل انتم منتهون","dt":"[91] انما يريد الشيطان بتزيين الاثام لكم ان يلقي بينكم ما يوجد العداوه والبغضاء؛ بسبب شرب الخمر ولعب الميسر، ويصرفكم عن ذكر الله وعن الصلاه بغياب العقل في شرب الخمر، والاشتغال باللهو في لعب الميسر، فانتهوا عن ذلك."},{"id":"761","s":5,"a":92,"at":"واطيعوا الله واطيعوا الرسول واحذروا فان توليتم فاعلموا انما على رسولنا البلاغ المبين","dt":"[92] وامتثلوا -ايها المسلمون- طاعه الله وطاعه رسوله محمد -صلى الله عليه وسلم- في كل ما تفعلون وتتركون، واتقوا الله وراقبوه في ذلك، فان اعرضتم عن الامتثال فعملتم ما نهيتم عنه، فاعلموا انما على رسولنا محمد -صلى الله عليه وسلم- البلاغ المبين."},{"id":"762","s":5,"a":93,"at":"ليس على الذين امنوا وعملوا الصالحات جناح فيما طعموا اذا ما اتقوا وامنوا وعملوا الصالحات ثم اتقوا وامنوا ثم اتقوا واحسنوا والله يحب المحسنين","dt":"[93] ليس على المؤمنين الذين شربوا الخمر قبل تحريمها اثم في ذلك، اذا تركوها واتقوا سخط الله وامنوا به، وقدموا الاعمال الصالحه التي تدل على ايمانهم ورغبتهم في رضوان الله تعالى عنهم، ثم ازدادوا بذلك مراقبه لله عز وجل وايمانا به، حتى اصبحوا من يقينهم يعبدونه، وكانهم يرونه. وان الله تعالى يحب الذين بلغوا درجه الاحسان حتى اصبح ايمانهم بالغيب كالمشاهده."},{"id":"763","s":5,"a":94,"at":"ياايها الذين امنوا ليبلونكم الله بشيء من الصيد تناله ايديكم ورماحكم ليعلم الله من يخافه بالغيب فمن اعتدى بعد ذلك فله عذاب اليم","dt":"[94] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه ليبلونكم الله بشيء من صيد البر يقترب منكم على غير المعتاد حيث تستطيعون اخذ صغاره بغير سلاح واخذ كباره بالسلاح؛ ليعلم الله علما ظاهرا للخلق الذين يخافون ربهم بالغيب، ليقينهم بكمال علمه بهم، وذلك بامساكهم عن الصيد، وهم محرمون. فمن تجاوز حده بعد هذا البيان فاقدم على الصيد -وهو محرم- فانه يستحق العذاب الشديد."},{"id":"764","s":5,"a":95,"at":"ياايها الذين امنوا لا تقتلوا الصيد وانتم حرم ومن قتله منكم متعمدا فجزاء مثل ما قتل من النعم يحكم به ذوا عدل منكم هديا بالغ الكعبه او كفاره طعام مساكين او عدل ذلك صياما ليذوق وبال امره عفا الله عما سلف ومن عاد فينتقم الله منه والله عزيز ذو انتقام","dt":"[95] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه لا تقتلوا صيد البر، وانتم محرمون بحج او عمره، او كنتم داخل الحرم، ومن قتل اي نوع من صيد البر متعمدا فجزاء ذلك ان يذبح مثل ذلك الصيد من بهيمه الانعام: الابل او البقر او الغنم، بعد ان يقدره اثنان عدلان، وان يهديه لفقراء الحرم، او ان يشتري بقيمه مثله طعاما يهديه لفقراء الحرم، لكل مسكين نصف صاع، او يصوم بدلا من ذلك يوما عن كل نصف صاع من ذلك الطعام، فرض الله عليه هذا الجزاء؛ ليلقى بايجاب الجزاء المذكور عاقبه فعله. والذين وقعوا في شيء من ذلك قبل التحريم فان الله تعالى قد عفا عنهم، ومن عاد الى المخالفه متعمدا بعد التحريم، فانه معرض لانتقام الله منه. والله تعالى عزيز قوي منيع في سلطانه، ومن عزته انه ينتقم ممن عصاه اذا اراد، لا يمنعه من ذلك مانع."},{"id":"765","s":5,"a":96,"at":"احل لكم صيد البحر وطعامه متاعا لكم وللسياره وحرم عليكم صيد البر ما دمتم حرما واتقوا الله الذي اليه تحشرون","dt":"[96] احل الله لكم -ايها المسلمون- في حال احرامكم صيد البحر، وهو ما يصاد منه حيا، وطعامه: وهو الميت منه؛ من اجل انتفاعكم به مقيمين او مسافرين، وحرم عليكم صيد البر ما دمتم محرمين بحج او عمره. واخشوا الله ونفذوا جميع اوامره، واجتنبوا جميع نواهيه؛ حتى تظفروا بعظيم ثوابه، وتسلموا من اليم عقابه عندما تحشرون للحساب والجزاء."},{"id":"766","s":5,"a":97,"at":"جعل الله الكعبه البيت الحرام قياما للناس والشهر الحرام والهدي والقلائد ذلك لتعلموا ان الله يعلم ما في السموات وما في الارض وان الله بكل شيء عليم","dt":"[97] امتن الله على عباده بان جعل الكعبه البيت الحرام صلاحا لدينهم، وامنا لحياتهم؛ وذلك حيث امنوا بالله ورسوله واقاموا فرائضه، وحرم العدوان والقتال في الاشهر الحرم (وهي ذو القعده وذو الحجه والمحرم ورجب) فلا يعتدي فيها احد على احد، وحرم تعالى الاعتداء على ما يهدى الى الحرم من بهيمه الانعام، وحرم كذلك الاعتداء على القلائد، وهي ما قلد اشعارا بانه يقصد به النسك؛ ذلك لتعلموا ان الله يعلم جميع ما في السموات وما في الارض، ومن ذلك ما شرعه لحمايه خلقه بعضهم من بعض، وان الله بكل شيء عليم، فلا تخفى عليه خافيه."},{"id":"767","s":5,"a":98,"at":"اعلموا ان الله شديد العقاب وان الله غفور رحيم","dt":"[98] اعلموا -ايها الناس- ان الله جل وعلا شديد العقاب لمن عصاه، وان الله غفور رحيم لمن تاب واناب."},{"id":"768","s":5,"a":99,"at":"ما على الرسول الا البلاغ والله يعلم ما تبدون وما تكتمون","dt":"[99] يبين الله تعالى ان مهمه رسوله -صلى الله عليه وسلم- هدايه الدلاله والتبليغ، وبيد الله -وحده- هدايه التوفيق، وان ما تنطوي عليه نفوس الناس مما يسرون او يعلنون من الهدايه او الضلال يعلمه الله."},{"id":"769","s":5,"a":100,"at":"قل لا يستوي الخبيث والطيب ولو اعجبك كثره الخبيث فاتقوا الله يااولي الالباب لعلكم تفلحون","dt":"[100] قل -ايها الرسول-: لا يستوي الخبيث والطيب من كل شيء، فالكافر لا يساوي المؤمن، والعاصي لا يساوي المطيع، والجاهل لا يساوي العالم، والمبتدع لا يساوي المتبع، والمال الحرام لا يساوي الحلال، ولو اعجبك -ايها الانسان- كثره الخبيث وعدد اهله. فاتقوا الله يا اصحاب العقول الراجحه باجتناب الخبائث، وفعل الطيبات؛ لتفلحوا بنيل المقصود الاعظم، وهو رضا الله تعالى والفوز بالجنه."},{"id":"770","s":5,"a":101,"at":"ياايها الذين امنوا لا تسالوا عن اشياء ان تبد لكم تسؤكم وان تسالوا عنها حين ينزل القران تبد لكم عفا الله عنها والله غفور حليم","dt":"[101] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه لا تسالوا عن اشياء من امور الدين لم تؤمروا فيها بشيء، كالسؤال عن الامور غير الواقعه، او التي يترتب عليها تشديدات في الشرع، ولو كلفتموها لشقت عليكم، وان تسالوا عنها في حياه رسول الله -صلى الله عليه وسلم- وحين نزول القران عليه تبين لكم، وقد تكلفونها فتعجزون عنها، تركها الله معافيا لعباده منها. والله غفور لعباده اذا تابوا، حليم عليهم فلا يعاقبهم وقد انابوا اليه."},{"id":"771","s":5,"a":102,"at":"قد سالها قوم من قبلكم ثم اصبحوا بها كافرين","dt":"[102] ان مثل تلك الاسئله قد سالها قوم من قبلكم رسلهم، فلما امروا بها جحدوها، ولم ينفذوها، فاحذروا ان تكونوا مثلهم."},{"id":"772","s":5,"a":103,"at":"ما جعل الله من بحيره ولا سائبه ولا وصيله ولا حام ولكن الذين كفروا يفترون على الله الكذب واكثرهم لا يعقلون","dt":"[103] ما شرع الله للمشركين ما ابتدعوه في بهيمه الانعام من ترك الانتفاع ببعضها وجعلها للاصنام، وهي: البحيره التي تقطع اذنها اذا ولدت عددا من البطون، والسائبه وهي التي تترك للاصنام، والوصيله وهي التي تتصل ولادتها بانثى بعد انثى، والحامي وهو الذكر من الابل اذا ولد من صلبه عدد من الابل، ولكن الكفار نسبوا ذلك الى الله تعالى افتراء عليه، واكثر الكافرين لا يميزون الحق من الباطل."},{"id":"773","s":5,"a":104,"at":"واذا قيل لهم تعالوا الى ما انزل الله والى الرسول قالوا حسبنا ما وجدنا عليه اباءنا او لو كان اباؤهم لا يعلمون شيئا ولا يهتدون","dt":"[104] واذا قيل لهؤلاء الكفار المحرمين ما احل الله: تعالوا الى تنزيل الله والى رسوله ليتبين لكم الحلال والحرام، قالوا: يكفينا ما ورثناه عن ابائنا من قول وعمل، ايقولون ذلك ولو كان اباؤهم لا يعلمون شيئا اي: لا يفهمون حقا ولا يعرفونه، ولا يهتدون اليه؟ فكيف يتبعونهم، والحاله هذه؟ فانه لا يتبعهم الا من هو اجهل منهم واضل سبيلا."},{"id":"774","s":5,"a":105,"at":"ياايها الذين امنوا عليكم انفسكم لا يضركم من ضل اذا اهتديتم الى الله مرجعكم جميعا فينبئكم بما كنتم تعملون","dt":"[105] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه الزموا انفسكم بالعمل بطاعه الله واجتناب معصيته، وداوموا على ذلك وان لم يستجب الناس لكم، فاذا فعلتم ذلك فلا يضركم ضلال من ضل اذا لزمتم طريق الاستقامه، وامرتم بالمعروف ونهيتم عن المنكر، الى الله مرجعكم جميعا في الاخره، فيخبركم باعمالكم، ويجازيكم عليها."},{"id":"775","s":5,"a":106,"at":"ياايها الذين امنوا شهاده بينكم اذا حضر احدكم الموت حين الوصيه اثنان ذوا عدل منكم او اخران من غيركم ان انتم ضربتم في الارض فاصابتكم مصيبه الموت تحبسونهما من بعد الصلاه فيقسمان بالله ان ارتبتم لا نشتري به ثمنا ولو كان ذا قربى ولا نكتم شهاده الله انا اذا لمن الاثمين","dt":"[106] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه اذا قرب الموت من احدكم، فليشهد على وصيته اثنين امينين من المسلمين، او اخرين من غير المسلمين عند الحاجه وعدم وجود غيرهما من المسلمين، تشهدونهما ان انتم سافرتم في الارض فحل بكم الموت، وان ارتبتم في شهادتهما فقفوهما من بعد الصلاه -اي صلاه المسلمين، وبخاصه صلاه العصر-، فيقسمان بالله قسما خالصا لا ياخذان به عوضا من الدنيا، ولا يحابيان به ذا قرابه منهما، ولا يكتمان به شهاده لله عندهما، وانهما ان فعلا ذلك فهما من المذنبين."},{"id":"776","s":5,"a":107,"at":"فان عثر على انهما استحقا اثما فاخران يقومان مقامهما من الذين استحق عليهم الاوليان فيقسمان بالله لشهادتنا احق من شهادتهما وما اعتدينا انا اذا لمن الظالمين","dt":"[107] فان اطلع اولياء الميت على ان الشاهدين المذكورين قد اثما بالخيانه في الشهاده او الوصيه، فليقم مقامهما في الشهاده اثنان من اولياء الميت فيقسمان بالله: لشهادتنا الصادقه اولى بالقبول من شهادتهما الكاذبه، وما تجاوزنا الحق في شهادتنا، انا ان اعتدينا وشهدنا بغير الحق لمن الظالمين المتجاوزين حدود الله."},{"id":"777","s":5,"a":108,"at":"ذلك ادنى ان ياتوا بالشهاده على وجهها او يخافوا ان ترد ايمان بعد ايمانهم واتقوا الله واسمعوا والله لا يهدي القوم الفاسقين","dt":"[108] ذلك الحكم عند الارتياب في الشاهدين من الحلف بعد الصلاه وعدم قبول شهادتهما، اقرب الى ان ياتوا بالشهاده على حقيقتها خوفا من عذاب الاخره، او خشيه من ان ترد اليمين الكاذبه من قبل اصحاب الحق بعد حلفهم، فيفتضح الكاذب الذي ردت يمينه في الدنيا وقت ظهور خيانته. وخافوا الله -ايها الناس- وراقبوه ان تحلفوا كذبا، وان تقتطعوا بايمانكم مالا حراما، واسمعوا ما توعظون به. والله لا يهدي القوم الفاسقين الخارجين عن طاعته."},{"id":"778","s":5,"a":109,"at":"يوم يجمع الله الرسل فيقول ماذا اجبتم قالوا لا علم لنا انك انت علام الغيوب","dt":"[109] واذكروا -ايها الناس- يوم القيامه يوم يجمع الله الرسل عليهم السلام، فيسالهم عن جواب اممهم لهم حينما دعوهم الى التوحيد فيجيبون: لا علم لنا، فنحن لا نعلم ما في صدور الناس، ولا ما احدثوا بعدنا. انك انت عليم بكل شيء مما خفي او ظهر."},{"id":"779","s":5,"a":110,"at":"اذ قال الله ياعيسى ابن مريم اذكر نعمتي عليك وعلى والدتك اذ ايدتك بروح القدس تكلم الناس في المهد وكهلا واذ علمتك الكتاب والحكمه والتوراه والانجيل واذ تخلق من الطين كهيئه الطير باذني فتنفخ فيها فتكون طيرا باذني وتبرئ الاكمه والابرص باذني واذ تخرج الموتى باذني واذ كففت بني اسرائيل عنك اذ جئتهم بالبينات فقال الذين كفروا منهم ان هذا الا سحر مبين","dt":"[110] اذ قال الله يوم القيامه: يا عيسى بن مريم اذكر نعمتي عليك اذ خلقتك من غير اب، وعلى والدتك حيث اصطفيتها على نساء العالمين، وبراتها مما نسب اليها، ومن هذه النعم على عيسى انه قواه واعانه بجبريل عليه السلام، يكلم الناس وهو رضيع قبل اوان الكلام، ويدعوهم الى الله وهو كبير قد اجتمعت قوته وكمل شبابه بما اوحاه الله اليه من التوحيد، ومنها ان الله تعالى علمه الكتابه والخط بدون معلم، ووهبه قوه الفهم والادراك، وعلمه التوراه التي انزلها على موسى عليه السلام، والانجيل الذي انزل عليه هدايه للناس، ومن هذه النعم انه يصور من الطين كهيئه الطير فينفخ في تلك الهيئه، فتكون طيرا باذن الله، ومنها انه يشفي الذي ولد اعمى فيبصر، ويشفي الابرص فيعود جلده سليما باذن الله، ومنها انه يدعو الله ان يحيي الموتى فيقوموا من قبورهم احياء، وذلك كله باراده الله تعالى واذنه، وهي معجزات باهره تؤيد نبوه عيسى عليه السلام، ثم يذكره الله جل وعلا نعمته عليه اذ منع بني اسرائيل حين هموا بقتله، وقد جاءهم بالمعجزات الواضحه الداله على نبوته، فقال الذين كفروا منهم: ان ما جاء به عيسى من البينات سحر ظاهر."},{"id":"780","s":5,"a":111,"at":"واذ اوحيت الى الحواريين ان امنوا بي وبرسولي قالوا امنا واشهد باننا مسلمون","dt":"[111] واذكر -يا عيسى- نعمتي عليك، اذ الهمت، والقيت في قلوب جماعه من خلصائك ان يصدقوا بوحدانيه الله تعالى ونبوتك، فقالوا: صدقنا يا ربنا، واشهد باننا خاضعون لك منقادون لامرك."},{"id":"781","s":5,"a":112,"at":"اذ قال الحواريون ياعيسى ابن مريم هل يستطيع ربك ان ينزل علينا مائده من السماء قال اتقوا الله ان كنتم مؤمنين","dt":"[112] واذكر اذ قال الحواريون: يا عيسى بن مريم هل يستطيع ربك ان سالته ان ينزل علينا مائده طعام من السماء؟ فكان جوابه ان امرهم بان يتقوا عذاب الله تعالى، ان كانوا مؤمنين حق الايمان."},{"id":"782","s":5,"a":113,"at":"قالوا نريد ان ناكل منها وتطمئن قلوبنا ونعلم ان قد صدقتنا ونكون عليها من الشاهدين","dt":"[113] قال الحواريون: نريد ان ناكل من المائده وتسكن قلوبنا لرؤيتها، ونعلم يقينا صدقك في نبوتك، وان نكون من الشاهدين على هذه الايه ان الله انزلها حجه له علينا في توحيده وقدرته على ما يشاء، وحجه لك على صدقك في نبوتك."},{"id":"783","s":5,"a":114,"at":"قال عيسى ابن مريم اللهم ربنا انزل علينا مائده من السماء تكون لنا عيدا لاولنا واخرنا وايه منك وارزقنا وانت خير الرازقين","dt":"[114] اجاب عيسى بن مريم طلب الحواريين فدعا ربه جل وعلا قائلا: ربنا انزل علينا مائده طعام من السماء، نتخذ يوم نزولها عيدا لنا، نعظمه نحن ومن بعدنا، وتكون المائده علامه وحجه منك -يا الله- على وحدانيتك وعلى صدق نبوتي، وامنحنا من عطائك الجزيل، وانت خير الرازقين."},{"id":"784","s":5,"a":115,"at":"قال الله اني منزلها عليكم فمن يكفر بعد منكم فاني اعذبه عذابا لا اعذبه احدا من العالمين","dt":"[115] قال الله تعالى: اني منزل مائده الطعام عليكم، فمن يجحد منكم وحدانيتي ونبوه عيسى عليه السلام بعد نزول المائده فاني اعذبه عذابا شديدا، لا اعذبه احدا من العالمين. وقد نزلت المائده كما وعد الله."},{"id":"785","s":5,"a":116,"at":"واذ قال الله ياعيسى ابن مريم اانت قلت للناس اتخذوني وامي الهين من دون الله قال سبحانك ما يكون لي ان اقول ما ليس لي بحق ان كنت قلته فقد علمته تعلم ما في نفسي ولا اعلم ما في نفسك انك انت علام الغيوب","dt":"[116] واذكر اذ قال الله تعالى يوم القيامه: يا عيسى بن مريم اانت قلت للناس اجعلوني وامي معبودين من دون الله؟ فاجاب عيسى -منزها الله تعالى-: ما ينبغي لي ان اقول للناس غير الحق. ان كنت قلت هذا فقد علمته؛ لانه لا يخفى عليك شيء، تعلم ما تضمره نفسي، ولا اعلم انا ما في نفسك. انك انت عالم بكل شيء مما خفي او ظهر."},{"id":"786","s":5,"a":117,"at":"ما قلت لهم الا ما امرتني به ان اعبدوا الله ربي وربكم وكنت عليهم شهيدا ما دمت فيهم فلما توفيتني كنت انت الرقيب عليهم وانت على كل شيء شهيد","dt":"[117] قال عيسى عليه السلام: يا رب ما قلت لهم الا ما اوحيته الي، وامرتني بتبليغه من افرادك بالتوحيد والعباده، وكنت على ما يفعلونه -وانا بين اظهرهم- شاهدا عليهم وعلى افعالهم واقوالهم، فلما وفيتني اجلي على الارض، ورفعتني الى السماء حيا، كنت انت المطلع على سرائرهم، وانت على كل شيء شهيد، لا تخفى عليك خافيه في الارض ولا في السماء."},{"id":"787","s":5,"a":118,"at":"ان تعذبهم فانهم عبادك وان تغفر لهم فانك انت العزيز الحكيم","dt":"[118] انك يا الله ان تعذبهم فانهم عبادك -وانت اعلم باحوالهم-، تفعل بهم ما تشاء بعدلك، وان تغفر برحمتك لمن اتى منهم باسباب المغفره، فانك انت العزيز الذي لا يغالب، الحكيم في تدبيره وامره. وهذه الايه ثناء على الله -تعالى- بحكمته وعدله، وكمال علمه."},{"id":"788","s":5,"a":119,"at":"قال الله هذا يوم ينفع الصادقين صدقهم لهم جنات تجري من تحتها الانهار خالدين فيها ابدا رضي الله عنهم ورضوا عنه ذلك الفوز العظيم","dt":"[119] قال الله تعالى لعيسى عليه السلام يوم القيامه: هذا يوم الجزاء الذي ينفع الموحدين توحيدهم ربهم، وانقيادهم لشرعه، وصدقهم في نياتهم واقوالهم واعمالهم، لهم جنات تجري من تحت قصورها واشجارها الانهار، ماكثين فيها ابدا، رضي الله عنهم فقبل حسناتهم، ورضوا عنه بما اعطاهم من جزيل ثوابه، ذلك الجزاء والرضا منه عليهم هو الفوز العظيم."},{"id":"789","s":5,"a":120,"at":"لله ملك السموات والارض وما فيهن وهو على كل شيء قدير","dt":"[120] لله وحده لا شريك له ملك السموات والارض وما فيهن، وهو -سبحانه- على كل شيء قدير لا يعجزه شيء."},{"id":"790","s":6,"a":1,"at":"الحمد لله الذي خلق السموات والارض وجعل الظلمات والنور ثم الذين كفروا بربهم يعدلون","dt":"[1] الثناء على الله بصفاته التي كلها اوصاف كمال، وبنعمه الظاهره والباطنه، الدينيه والدنيويه، الذي انشا السموات والارض وما فيهن، وخلق الظلمات والنور ، وذلك بتعاقب الليل والنهار. وفي هذا دلاله على عظمه الله تعالى، واستحقاقه وحده العباده، فلا يجوز لاحد ان يشرك به غيره. ومع هذا الوضوح فان الكافرين يسوون بالله غيره، ويشركون به."},{"id":"791","s":6,"a":2,"at":"هو الذي خلقكم من طين ثم قضى اجلا واجل مسمى عنده ثم انتم تمترون","dt":"[2] هو الذي خلق اباكم ادم من طين وانتم سلاله منه، ثم كتب مده بقائكم في هذه الحياه الدنيا، وكتب اجلا اخر محددا لا يعلمه الا هو جل وعلا، وهو يوم القيامه، ثم انتم بعد هذا تشكون في قدره الله تعالى على البعث بعد الموت."},{"id":"792","s":6,"a":3,"at":"وهو الله في السموات وفي الارض يعلم سركم وجهركم ويعلم ما تكسبون","dt":"[3] والله سبحانه هو الاله المعبود بحق في السموات والارض. ومن دلائل الوهيته انه يعلم جميع ما تخفونه -ايها الناس- وما تعلنونه، ويعلم جميع اعمالكم من خير او شر؛ ولهذا فانه -جل وعلا- وحده هو الاله المستحق للعباده."},{"id":"793","s":6,"a":4,"at":"وما تاتيهم من ايه من ايات ربهم الا كانوا عنها معرضين","dt":"[4] هؤلاء الكفار الذين يشركون مع الله تعالى غيره قد جاءتهم الحجج الواضحه والدلالات البينه على وحدانيه الله -جل وعلا-، وصدق محمد -صلى الله عليه وسلم- في نبوته وما جاء به، ولكن ما ان جاءتهم حتى اعرضوا عن قبولها، ولم يؤمنوا بها."},{"id":"794","s":6,"a":5,"at":"فقد كذبوا بالحق لما جاءهم فسوف ياتيهم انباء ما كانوا به يستهزئون","dt":"[5] لقد جحد هؤلاء الكفار الحق الذي جاءهم به محمد -صلى الله عليه وسلم- وسخروا من دعاته؛ جهلا منهم بالله واغترارا بامهاله اياهم، فسوف يرون ما استهزؤوا به انه الحق والصدق، ويبين الله للمكذبين كذبهم وافتراءهم، وسيجازيهم عليه."},{"id":"795","s":6,"a":6,"at":"الم يروا كم اهلكنا من قبلهم من قرن مكناهم في الارض ما لم نمكن لكم وارسلنا السماء عليهم مدرارا وجعلنا الانهار تجري من تحتهم فاهلكناهم بذنوبهم وانشانا من بعدهم قرنا اخرين","dt":"[6] الم يعلم هؤلاء الذين يجحدون وحدانيه الله تعالى واستحقاقه وحده العباده، ويكذبون رسوله محمدا -صلى الله عليه وسلم- ما حل بالامم المكذبه قبلهم من هلاك وتدمير، وقد مكناهم في الارض ما لم نمكن لكم ايها الكافرون، وانعمنا عليهم بانزال الامطار وجريان الانهار من تحت مساكنهم؛ استدراجا واملاء لهم، فكفروا بنعم الله وكذبوا الرسل، فاهلكناهم بسبب ذنوبهم، وانشانا من بعدهم امما اخرى خلفوهم في عماره الارض؟"},{"id":"796","s":6,"a":7,"at":"ولو نزلنا عليك كتابا في قرطاس فلمسوه بايديهم لقال الذين كفروا ان هذا الا سحر مبين","dt":"[7] ولو نزلنا عليك -ايها الرسول- كتابا من السماء في اوراق فلمسه هؤلاء المشركون بايديهم لقالوا: ان ما جئت به -ايها الرسول- سحر واضح بين."},{"id":"797","s":6,"a":8,"at":"وقالوا لولا انزل عليه ملك ولو انزلنا ملكا لقضي الامر ثم لا ينظرون","dt":"[8] وقال هؤلاء المشركون: هلا انزل الله تعالى على محمد ملكا من السماء؛ ليصدقه فيما جاء به من النبوه، ولو انزلنا ملكا من السماء اجابه لطلبهم لقضي الامر باهلاكهم، ثم لا يمهلون لتوبه؛ فقد سبق في علم الله انهم لا يؤمنون."},{"id":"798","s":6,"a":9,"at":"ولو جعلناه ملكا لجعلناه رجلا وللبسنا عليهم ما يلبسون","dt":"[9] ولو جعلنا الرسول المرسل اليهم ملكا اذ لم يقتنعوا بمحمد -صلى الله عليه وسلم-، لجعلنا ذلك الملك في صوره البشر؛ حتى يستطيعوا السماع منه ومخاطبته؛ اذ ليس بامكانهم رؤيه الملك على صورته الملائكيه، ولو جاءهم الملك بصوره رجل لاشتبه الامر عليهم، كما اشتبه عليهم امر محمد -صلى الله عليه وسلم-."},{"id":"799","s":6,"a":10,"at":"ولقد استهزئ برسل من قبلك فحاق بالذين سخروا منهم ما كانوا به يستهزئون","dt":"[10] ولما كان طلبهم انزال الملك على سبيل الاستهزاء بمحمد -صلى الله عليه وسلم-، بين الله تعالى له ان الاستهزاء بالرسل عليهم السلام ليس امرا حادثا، بل قد وقع من الكفار السابقين مع انبيائهم، فاحاط بهم العذاب الذي كانوا يهزؤون به وينكرون وقوعه."},{"id":"800","s":6,"a":11,"at":"قل سيروا في الارض ثم انظروا كيف كان عاقبه المكذبين","dt":"[11] قل لهم -ايها الرسول-: سيروا في الارض ثم انظروا كيف اعقب الله المكذبين الهلاك والخزي؟ فاحذروا مثل مصارعهم، وخافوا ان يحل بكم مثل الذي حل بهم."},{"id":"801","s":6,"a":12,"at":"قل لمن ما في السموات والارض قل لله كتب على نفسه الرحمه ليجمعنكم الى يوم القيامه لا ريب فيه الذين خسروا انفسهم فهم لا يؤمنون","dt":"[12] قل -ايها الرسول- لهؤلاء المشركين: لمن ملك السموات والارض وما فيهن؟ قل: هو لله كما تقرون بذلك وتعلمونه، فاعبدوه وحده. كتب الله على نفسه الرحمه فلا يعجل على عباده بالعقوبه. ليجمعنكم الى يوم القيامه الذي لا شك فيه للحساب والجزاء. الذين اشركوا بالله اهلكوا انفسهم؛ فهم لا يوحدون الله، ولا يصدقون بوعده ووعيده، ولا يقرون بنبوه محمد -صلى الله عليه وسلم-."},{"id":"802","s":6,"a":13,"at":"وله ما سكن في الليل والنهار وهو السميع العليم","dt":"[13] ولله ملك كل شيء في السموات والارض، سكن او تحرك، خفي او ظهر، الجميع عبيده وخلقه، وتحت قهره وتصرفه وتدبيره، وهو السميع لاقوال عباده، العليم بسرائرهم واعمالهم."},{"id":"803","s":6,"a":14,"at":"قل اغير الله اتخذ وليا فاطر السموات والارض وهو يطعم ولا يطعم قل اني امرت ان اكون اول من اسلم ولا تكونن من المشركين","dt":"[14] قل -ايها الرسول- لهؤلاء المشركين مع الله تعالى غيره: اغير الله تعالى اتخذ وليا ونصيرا، وهو خالق السموات والارض وما فيهن، وهو الذي يرزق خلقه ولا يرزقه احد؟ قل -ايها الرسول-: اني امرت ان اكون اول من خضع وانقاد له بالعبوديه من هذه الامه، ونهيت ان اكون من المشركين معه غيره."},{"id":"804","s":6,"a":15,"at":"قل اني اخاف ان عصيت ربي عذاب يوم عظيم","dt":"[15] قل -ايها الرسول- لهؤلاء المشركين مع الله غيره: اني اخاف ان عصيت ربي، فخالفت امره، واشركت معه غيره في عبادته، ان ينزل بي عذاب عظيم يوم القيامه."},{"id":"805","s":6,"a":16,"at":"من يصرف عنه يومئذ فقد رحمه وذلك الفوز المبين","dt":"[16] من يصرف الله عنه ذلك العذاب الشديد فقد رحمه، وذلك الصرف هو الظفر البين بالنجاه من العذاب العظيم."},{"id":"806","s":6,"a":17,"at":"وان يمسسك الله بضر فلا كاشف له الا هو وان يمسسك بخير فهو على كل شيء قدير","dt":"[17] وان يصبك الله تعالى -ايها الانسان- بشيء يضرك كالفقر والمرض فلا كاشف له الا هو، وان يصبك بخير كالغنى والصحه فلا راد لفضله ولا مانع لقضائه، فهو -جل وعلا- القادر على كل شيء."},{"id":"807","s":6,"a":18,"at":"وهو القاهر فوق عباده وهو الحكيم الخبير","dt":"[18] والله سبحانه هو الغالب القاهر فوق عباده؛ خضعت له الرقاب وذلت له الجبابره، وهو الحكيم الذي يضع الاشياء مواضعها وفق حكمته، الخبير الذي لا يخفى عليه شيء. ومن اتصف بهذه الصفات يجب الا يشرك به. وفي هذه الايه اثبات الفوقيه لله -تعالى- على جميع خلقه، فوقيه مطلقه تليق بجلاله سبحانه."},{"id":"808","s":6,"a":19,"at":"قل اي شيء اكبر شهاده قل الله شهيد بيني وبينكم واوحي الي هذا القران لانذركم به ومن بلغ ائنكم لتشهدون ان مع الله الهه اخرى قل لا اشهد قل انما هو اله واحد وانني بريء مما تشركون","dt":"[19] قل -ايها الرسول لهؤلاء المشركين-: اي شيء اعظم شهاده في اثبات صدقي فيما اخبرتكم به اني رسول الله؟ قل: الله شهيد بيني وبينكم، اي: هو العالم بما جئتكم به وما انتم قائلون لي، واوحى الله الي هذا القران من اجل ان انذركم به عذابه ان يحل بكم، وانذر به من وصل اليه من الامم. انكم لتقرون ان مع الله معبودات اخرى تشركونها به. قل لهم -ايها الرسول-: اني لا اشهد على ما اقررتم به، انما الله اله واحد لا شريك له، وانني بريء من كل شريك تعبدونه معه."},{"id":"809","s":6,"a":20,"at":"الذين اتيناهم الكتاب يعرفونه كما يعرفون ابناءهم الذين خسروا انفسهم فهم لا يؤمنون","dt":"[20] الذين اتيناهم التوراه والانجيل، يعرفون محمدا -صلى الله عليه وسلم- بصفاته المكتوبه عندهم كمعرفتهم ابناءهم، فكما ان ابناءهم لا يشتبهون امامهم بغيرهم، فكذلك محمد -صلى الله عليه وسلم- لا يشتبه بغيره لدقه وصفه في كتبهم، ولكنهم اتبعوا اهواءهم، فخسروا انفسهم حين كفروا بمحمد -صلى الله عليه وسلم- وبما جاء به."},{"id":"810","s":6,"a":21,"at":"ومن اظلم ممن افترى على الله كذبا او كذب باياته انه لا يفلح الظالمون","dt":"[21] لا احد اشد ظلما ممن تقول الكذب على الله تعالى، فزعم ان له شركاء في العباده، او ادعى ان له ولدا او صاحبه، او كذب ببراهينه وادلته التي ايد بها رسله عليهم السلام. انه لا يفلح الظالمون الذين افتروا الكذب على الله، ولا يظفرون بمطالبهم في الدنيا ولا في الاخره."},{"id":"811","s":6,"a":22,"at":"ويوم نحشرهم جميعا ثم نقول للذين اشركوا اين شركاؤكم الذين كنتم تزعمون","dt":"[22] وليحذر هؤلاء المشركون المكذبون بايات الله تعالى يوم نحشرهم ثم نقول لهم: اين الهتكم التي كنتم تدعون انهم شركاء مع الله تعالى ليشفعوا لكم؟"},{"id":"812","s":6,"a":23,"at":"ثم لم تكن فتنتهم الا ان قالوا والله ربنا ما كنا مشركين","dt":"[23] ثم لم تكن اجابتهم حين فتنوا واختبروا بالسؤال عن شركائهم الا ان تبرؤوا منهم، واقسموا بالله ربهم انهم لم يكونوا مشركين مع الله غيره."},{"id":"813","s":6,"a":24,"at":"انظر كيف كذبوا على انفسهم وضل عنهم ما كانوا يفترون","dt":"[24] تامل -ايها الرسول- كيف كذب هؤلاء المشركون على انفسهم، وهم في الاخره قد تبرؤوا من الشرك؟ وذهب وغاب عنهم ما كانوا يظنونه من شفاعه الهتهم."},{"id":"814","s":6,"a":25,"at":"ومنهم من يستمع اليك وجعلنا على قلوبهم اكنه ان يفقهوه وفي اذانهم وقرا وان يروا كل ايه لا يؤمنوا بها حتى اذا جاءوك يجادلونك يقول الذين كفروا ان هذا الا اساطير الاولين","dt":"[25] ومن هؤلاء المشركين من يستمع اليك القران -ايها الرسول-، فلا يصل الى قلوبهم؛ لانهم بسبب اتباعهم اهواءهم جعلنا على قلوبهم اغطيه؛ لئلا يفقهوا القران، وجعلنا في اذانهم ثقلا وصمما فلا تسمع ولا تعي شيئا، وان يروا الايات الكثيره الداله على صدق محمد -صلى الله عليه وسلم- لا يصدقوا بها، حتى اذا جاؤوك -ايها الرسول- بعد معاينه الايات الداله على صدقك يخاصمونك: يقول الذين جحدوا ايات الله: ما هذا الذي نسمع الا ما تناقله الاولون من حكايات لا حقيقه لها."},{"id":"815","s":6,"a":26,"at":"وهم ينهون عنه ويناون عنه وان يهلكون الا انفسهم وما يشعرون","dt":"[26] وهؤلاء المشركون ينهون الناس عن اتباع محمد -صلى الله عليه وسلم- والاستماع اليه، ويبتعدون بانفسهم عنه، وما يهلكون -بصدهم عن سبيل الله- الا انفسهم، وما يحسون انهم يعملون لهلاكها."},{"id":"816","s":6,"a":27,"at":"ولو ترى اذ وقفوا على النار فقالوا ياليتنا نرد ولا نكذب بايات ربنا ونكون من المؤمنين","dt":"[27] ولو ترى -ايها الرسول- هؤلاء المشركين يوم القيامه لرايت امرا عظيما، وذلك حين يحبسون على النار، ويشاهدون ما فيها من السلاسل والاغلال، وراوا باعينهم تلك الامور العظام والاهوال، فعند ذلك قالوا: يا ليتنا نعاد الى الحياه الدنيا، فنصدق بايات الله ونعمل بها، ونكون من المؤمنين."},{"id":"817","s":6,"a":28,"at":"بل بدا لهم ما كانوا يخفون من قبل ولو ردوا لعادوا لما نهوا عنه وانهم لكاذبون","dt":"[28] ليس الامر كذلك، بل ظهر لهم يوم القيامه ما كانوا يعلمونه من انفسهم من صدق ما جاءت به الرسل في الدنيا، وان كانوا يظهرون لاتباعهم خلافه. ولو فرض ان اعيدوا الى الدنيا فامهلوا لرجعوا الى العناد بالكفر والتكذيب. وانهم لكاذبون في قولهم: لو رددنا الى الدنيا لم نكذب بايات ربنا، وكنا من المؤمنين."},{"id":"818","s":6,"a":29,"at":"وقالوا ان هي الا حياتنا الدنيا وما نحن بمبعوثين","dt":"[29] وقال هؤلاء المشركون المنكرون للبعث: ما الحياه الا هذه الحياه التي نحن فيها، وما نحن بمبعوثين بعد موتنا."},{"id":"819","s":6,"a":30,"at":"ولو ترى اذ وقفوا على ربهم قال اليس هذا بالحق قالوا بلى وربنا قال فذوقوا العذاب بما كنتم تكفرون","dt":"[30] ولو ترى -ايها الرسول- منكري البعث اذ حبسوا بين يدي الله تعالى لقضائه فيهم يوم القيامه، لرايت اسوا حال، اذ يقول الله جل وعلا: اليس هذا بالحق، اي: اليس هذا البعث الذي كنتم تنكرونه في الدنيا حقا؟ قالوا: بلى وربنا انه لحق، قال الله تعالى: فذوقوا العذاب بما كنتم تكفرون، اي: العذاب الذي كنتم تكذبون به في الدنيا؛ بسبب جحودكم بالله تعالى ورسوله محمد -صلى الله عليه وسلم-."},{"id":"820","s":6,"a":31,"at":"قد خسر الذين كذبوا بلقاء الله حتى اذا جاءتهم الساعه بغته قالوا ياحسرتنا على ما فرطنا فيها وهم يحملون اوزارهم على ظهورهم الا ساء ما يزرون","dt":"[31] قد خسر الكفار الذين انكروا البعث بعد الموت، حتى اذا قامت القيامه وفوجئوا بسوء المصير، نادوا على انفسهم بالحسره على ما ضيعوه في حياتهم الدنيا، وهم يحملون اثامهم على ظهورهم، فما اسوا الاحمال الثقيله السيئه التي يحملونها!"},{"id":"821","s":6,"a":32,"at":"وما الحياه الدنيا الا لعب ولهو وللدار الاخره خير للذين يتقون افلا تعقلون","dt":"[32] وما الحياه الدنيا في غالب احوالها الا غرور وباطل، والعمل الصالح للدار الاخره خير للذين يخشون الله، فيتقون عذابه بطاعته واجتناب معاصيه. افلا تعقلون -ايها المشركون المغترون بزينه الحياه الدنيا- فتقدموا ما يبقى على ما يفنى؟"},{"id":"822","s":6,"a":33,"at":"قد نعلم انه ليحزنك الذي يقولون فانهم لا يكذبونك ولكن الظالمين بايات الله يجحدون","dt":"[33] انا نعلم انه ليدخل الحزن الى قلبك تكذيب قومك لك في الظاهر، فاصبر واطمئن؛ فانهم لا يكذبونك في قراره انفسهم، بل يعتقدون صدقك، ولكنهم لظلمهم وعدوانهم يجحدون البراهين الواضحه على صدقك، فيكذبونك فيما جئت به."},{"id":"823","s":6,"a":34,"at":"ولقد كذبت رسل من قبلك فصبروا على ما كذبوا واوذوا حتى اتاهم نصرنا ولا مبدل لكلمات الله ولقد جاءك من نبا المرسلين","dt":"[34] ولقد كذب الكفار رسلا من قبلك ارسلهم الله تعالى الى اممهم واوذوا في سبيله، فصبروا على ذلك ومضوا في دعوتهم وجهادهم حتى اتاهم نصر الله. ولا مبدل لكلمات الله، وهي ما انزل على نبيه محمد -صلى الله عليه وسلم- من وعده اياه بالنصر على من عاداه. ولقد جاءك -ايها الرسول- من خبر من كان قبلك من الرسل، وما تحقق لهم من نصر الله، وما جرى على مكذبيهم من نقمه الله منهم وغضبه عليهم، فلك فيمن تقدم من الرسل اسوه وقدوه. وفي هذا تسليه للرسول -صلى الله عليه وسلم-."},{"id":"824","s":6,"a":35,"at":"وان كان كبر عليك اعراضهم فان استطعت ان تبتغي نفقا في الارض او سلما في السماء فتاتيهم بايه ولو شاء الله لجمعهم على الهدى فلا تكونن من الجاهلين","dt":"[35] وان كان عظم عليك -ايها الرسول- صدود هؤلاء المشركين وانصرافهم عن الاستجابه لدعوتك، فان استطعت ان تتخذ نفقا في الارض، او مصعدا تصعد فيه الى السماء، فتاتيهم بعلامه وبرهان على صحه قولك غير الذي جئناهم به فافعل. ولو شاء الله لجمعهم على الهدى الذي انتم عليه ووفقهم للايمان، ولكن لم يشا ذلك لحكمه يعلمها سبحانه، فلا تكونن -ايها الرسول- من الجاهلين الذين اشتد حزنهم، وتحسروا حتى اوصلهم ذلك الى الجزع الشديد."},{"id":"825","s":6,"a":36,"at":"انما يستجيب الذين يسمعون والموتى يبعثهم الله ثم اليه يرجعون","dt":"[36] انما يجيبك -ايها الرسول- الى ما دعوت اليه من الهدى الذين يسمعون الكلام سماع قبول. اما الكفار فهم في عداد الموتى؛ لان الحياه الحقيقيه انما تكون بالاسلام. والموتى يخرجهم الله من قبورهم احياء، ثم يعودون اليه يوم القيامه؛ ليوفوا حسابهم وجزاءهم."},{"id":"826","s":6,"a":37,"at":"وقالوا لولا نزل عليه ايه من ربه قل ان الله قادر على ان ينزل ايه ولكن اكثرهم لا يعلمون","dt":"[37] وقال المشركون -تعنتا واستكبارا-: هلا انزل الله علامه تدل على صدق محمد -صلى الله عليه وسلم- من نوع العلامات الخارقه، قل لهم -ايها الرسول-: ان الله قادر على ان ينزل عليهم ايه، ولكن اكثرهم لا يعلمون ان انزال الايات انما يكون وفق حكمته تعالى."},{"id":"827","s":6,"a":38,"at":"وما من دابه في الارض ولا طائر يطير بجناحيه الا امم امثالكم ما فرطنا في الكتاب من شيء ثم الى ربهم يحشرون","dt":"[38] ليس في الارض حيوان يدب على الارض، او طائر يطير في السماء بجناحيه الا جماعات متجانسه الخلق مثلكم. ما تركنا في اللوح المحفوظ شيئا الا اثبتناه، ثم انهم الى ربهم يحشرون يوم القيامه، فيحاسب الله كلا بما عمل."},{"id":"828","s":6,"a":39,"at":"والذين كذبوا باياتنا صم وبكم في الظلمات من يشا الله يضلله ومن يشا يجعله على صراط مستقيم","dt":"[39] والذين كذبوا بحجج الله تعالى صم لا يسمعون ما ينفعهم، بكم لا يتكلمون بالحق، فهم حائرون في الظلمات، لم يختاروا طريقه الاستقامه. من يشا الله اضلاله يضلله، ومن يشا هدايته يجعله على صراط مستقيم."},{"id":"829","s":6,"a":40,"at":"قل ارايتكم ان اتاكم عذاب الله او اتتكم الساعه اغير الله تدعون ان كنتم صادقين","dt":"[40] قل -ايها الرسول- لهؤلاء المشركين: اخبروني ان جاءكم عذاب الله في الدنيا، او جاءتكم الساعه التي تبعثون فيها: اغير الله تدعون هناك لكشف ما نزل بكم من البلاء، ان كنتم محقين في زعمكم ان الهتكم التي تعبدونها من دون الله تنفع او تضر؟"},{"id":"830","s":6,"a":41,"at":"بل اياه تدعون فيكشف ما تدعون اليه ان شاء وتنسون ما تشركون","dt":"[41] بل تدعون -هناك- ربكم الذي خلقكم لا غيره، وتستغيثون به، فيفرج عنكم البلاء العظيم النازل بكم ان شاء؛ لانه القادر على كل شيء، وتتركون حينئذ اصنامكم واوثانكم واولياءكم."},{"id":"831","s":6,"a":42,"at":"ولقد ارسلنا الى امم من قبلك فاخذناهم بالباساء والضراء لعلهم يتضرعون","dt":"[42] ولقد بعثنا -ايها الرسول- الى جماعات من الناس من قبلك رسلا يدعونهم الى الله تعالى، فكذبوهم، فابتليناهم في اموالهم بشده الفقر وضيق المعيشه، وابتليناهم في اجسامهم بالامراض والالام؛ رجاء ان يتذللوا لربهم، ويخضعوا له وحده بالعباده."},{"id":"832","s":6,"a":43,"at":"فلولا اذ جاءهم باسنا تضرعوا ولكن قست قلوبهم وزين لهم الشيطان ما كانوا يعملون","dt":"[43] فهلا اذ جاء هذه الامم المكذبه بلاؤنا تذللوا لنا، ولكن قست قلوبهم، وزين لهم الشيطان ما كانوا يعملون من المعاصي، وياتون من الشرك."},{"id":"833","s":6,"a":44,"at":"فلما نسوا ما ذكروا به فتحنا عليهم ابواب كل شيء حتى اذا فرحوا بما اوتوا اخذناهم بغته فاذا هم مبلسون","dt":"[44] فلما تركوا العمل باوامر الله تعالى معرضين عنها، فتحنا عليهم ابواب كل شيء من الرزق فابدلناهم بالباساء رخاء في العيش، وبالضراء صحه في الاجسام؛ استدراجا منا لهم، حتى اذا بطروا، واعجبوا بما اعطيناهم من الخير والنعمه اخذناهم بالعذاب فجاه، فاذا هم ايسون منقطعون من كل خير."},{"id":"834","s":6,"a":45,"at":"فقطع دابر القوم الذين ظلموا والحمد لله رب العالمين","dt":"[45] فاستؤصل هؤلاء القوم واهلكوا؛ اذ كفروا بالله وكذبوا رسله، فلم يبق منهم احد. والشكر والثناء لله تعالى -خالق كل شيء ومالكه- على نصره اوليائه وهلاك اعدائه."},{"id":"835","s":6,"a":46,"at":"قل ارايتم ان اخذ الله سمعكم وابصاركم وختم على قلوبكم من اله غير الله ياتيكم به انظر كيف نصرف الايات ثم هم يصدفون","dt":"[46] قل -ايها الرسول- لهؤلاء المشركين: اخبروني ان اذهب الله سمعكم فاصمكم، وذهب بابصاركم فاعماكم، وطبع على قلوبكم فاصبحتم لا تفقهون قولا، اي اله غير الله -جل وعلا- يقدر على رد ذلك لكم؟! انظر -ايها الرسول- كيف ننوع لهم الحجج، ثم هم بعد ذلك يعرضون عن التذكر والاعتبار؟"},{"id":"836","s":6,"a":47,"at":"قل ارايتكم ان اتاكم عذاب الله بغته او جهره هل يهلك الا القوم الظالمون","dt":"[47] قل -ايها الرسول- لهؤلاء المشركين: اخبروني ان نزل بكم عقاب الله فجاه وانتم لا تشعرون به، او ظاهرا عيانا وانتم تنظرون اليه: هل يهلك الا القوم الظالمون الذين تجاوزوا الحد، بصرفهم العباده لغير الله تعالى وبتكذيبهم رسله؟"},{"id":"837","s":6,"a":48,"at":"وما نرسل المرسلين الا مبشرين ومنذرين فمن امن واصلح فلا خوف عليهم ولا هم يحزنون","dt":"[48] وما نرسل رسلنا الا مبشرين اهل طاعتنا بالنعيم المقيم، ومنذرين اهل المعصيه بالعذاب الاليم، فمن امن وصدق الرسل وعمل صالحا فاولئك لا يخافون عند لقاء ربهم، ولا يحزنون على شيء فاتهم من حظوظ الدنيا."},{"id":"838","s":6,"a":49,"at":"والذين كذبوا باياتنا يمسهم العذاب بما كانوا يفسقون","dt":"[49] والذين كذبوا باياتنا من القران والمعجزات فاولئك يصيبهم العذاب يوم القيامه؛ بسبب كفرهم وخروجهم عن طاعه الله تعالى."},{"id":"839","s":6,"a":50,"at":"قل لا اقول لكم عندي خزائن الله ولا اعلم الغيب ولا اقول لكم اني ملك ان اتبع الا ما يوحى الي قل هل يستوي الاعمى والبصير افلا تتفكرون","dt":"[50] قل -ايها الرسول- لهؤلاء المشركين: اني لا ادعي اني املك خزائن السموات والارض، فاتصرف فيها، ولا ادعي اني اعلم الغيب، ولا ادعي اني ملك، وانما انا رسول من عند الله، اتبع ما يوحى الي، وابلغ وحيه الى الناس، قل -ايها الرسول- لهؤلاء المشركين: هل يستوي الكافر الذي عمي عن ايات الله تعالى فلم يؤمن بها، والمؤمن الذي ابصر ايات الله فامن بها؟ افلا تتفكرون في ايات الله؛ لتبصروا الحق فتؤمنوا به؟"},{"id":"840","s":6,"a":51,"at":"وانذر به الذين يخافون ان يحشروا الى ربهم ليس لهم من دونه ولي ولا شفيع لعلهم يتقون","dt":"[51] وخوف -ايها الرسول- بالقران الذين يعلمون انهم يحشرون الى ربهم، فهم مصدقون بوعد الله ووعيده، ليس لهم غير الله ولي ينصرهم، ولا شفيع يشفع لهم عنده تعالى، فيخلصهم من عذابه؛ لعلهم يتقون الله تعالى بفعل الاوامر واجتناب النواهي."},{"id":"841","s":6,"a":52,"at":"ولا تطرد الذين يدعون ربهم بالغداه والعشي يريدون وجهه ما عليك من حسابهم من شيء وما من حسابك عليهم من شيء فتطردهم فتكون من الظالمين","dt":"[52] ولا تبعد -ايها النبي- عن مجالستك ضعفاء المسلمين الذين يعبدون ربهم اول النهار واخره، يريدون باعمالهم الصالحه وجه الله، ما عليك من حساب هؤلاء الفقراء من شيء، انما حسابهم على الله، وليس عليهم شيء من حسابك، فان ابعدتهم فانك تكون من المتجاوزين حدود الله، الذين يضعون الشيء في غير موضعه."},{"id":"842","s":6,"a":53,"at":"وكذلك فتنا بعضهم ببعض ليقولوا اهؤلاء من الله عليهم من بيننا اليس الله باعلم بالشاكرين","dt":"[53] وكذلك ابتلى الله تعالى بعض عباده ببعض بتباين حظوظهم من الارزاق والاخلاق، فجعل بعضهم غنيا وبعضهم فقيرا، وبعضهم قويا وبعضهم ضعيفا، فاحوج بعضهم الى بعض اختبارا منه لهم بذلك؛ ليقول الكافرون الاغنياء: اهؤلاء الضعفاء من الله عليهم بالهدايه الى الاسلام من بيننا؟ اليس الله تعالى باعلم بمن يشكرون نعمته، فيوفقهم الى الهدايه لدينه؟"},{"id":"843","s":6,"a":54,"at":"واذا جاءك الذين يؤمنون باياتنا فقل سلام عليكم كتب ربكم على نفسه الرحمه انه من عمل منكم سوءا بجهاله ثم تاب من بعده واصلح فانه غفور رحيم","dt":"[54] واذا جاءك -ايها النبي- الذين صدقوا بايات الله الشاهده على صدقك من القران وغيره مستفتين عن التوبه من ذنوبهم السابقه، فاكرمهم برد السلام عليهم، وبشرهم برحمه الله الواسعه؛ فانه جل وعلا قد كتب على نفسه الرحمه بعباده تفضلا انه من اقترف ذنبا بجهاله منه لعاقبتها وايجابها لسخط الله -فكل عاص لله -مخطئا او متعمدا- فهو جاهل بهذا الاعتبار وان كان عالما بالتحريم- ثم تاب من بعده وداوم على العمل الصالح، فانه تعالى يغفر ذنبه، فهو غفور لعباده التائبين، رحيم بهم."},{"id":"844","s":6,"a":55,"at":"وكذلك نفصل الايات ولتستبين سبيل المجرمين","dt":"[55] ومثل هذا البيان الذي بيناه لك -ايها الرسول- نبين الحجج الواضحه على كل حق ينكره اهل الباطل؛ ليتبين الحق، وليظهر طريق اهل الباطل المخالفين للرسل."},{"id":"845","s":6,"a":56,"at":"قل اني نهيت ان اعبد الذين تدعون من دون الله قل لا اتبع اهواءكم قد ضللت اذا وما انا من المهتدين","dt":"[56] قل -ايها الرسول- لهؤلاء المشركين: ان الله عز وجل نهاني ان اعبد الاوثان التي تعبدونها من دونه، وقل لهم: لا اتبع اهواءكم، قد ضللت عن الصراط المستقيم ان اتبعت اهواءكم، وما انا من المهتدين."},{"id":"846","s":6,"a":57,"at":"قل اني على بينه من ربي وكذبتم به ما عندي ما تستعجلون به ان الحكم الا لله يقص الحق وهو خير الفاصلين","dt":"[57] قل -ايها الرسول لهؤلاء المشركين-: اني على بصيره واضحه من شريعه الله التي اوحاها الي، وذلك بافراده وحده بالعباده، وقد كذبتم بهذا، وليس في قدرتي انزال العذاب الذي تستعجلون به، وما الحكم في تاخر ذلك الا الى الله تعالى، يبين الحق بيانا واضحا، وهو خير من يفصل بين الحق والباطل بقضائه وحكمه."},{"id":"847","s":6,"a":58,"at":"قل لو ان عندي ما تستعجلون به لقضي الامر بيني وبينكم والله اعلم بالظالمين","dt":"[58] قل -ايها الرسول-: لو انني املك انزال العذاب الذي تستعجلونه لانزلته بكم، وقضي الامر بيني وبينكم، ولكن ذلك الى الله تعالى، وهو اعلم بالظالمين الذين تجاوزوا حدهم فاشركوا معه غيره."},{"id":"848","s":6,"a":59,"at":"وعنده مفاتح الغيب لا يعلمها الا هو ويعلم ما في البر والبحر وما تسقط من ورقه الا يعلمها ولا حبه في ظلمات الارض ولا رطب ولا يابس الا في كتاب مبين","dt":"[59] وعند الله -جل وعلا -مفاتح الغيب، اي: خزائن الغيب، لا يعلمها الا هو، ومنها: علم الساعه، ونزول الغيث، وما في الارحام، والكسب في المستقبل، ومكان موت الانسان، ويعلم كل ما في البر والبحر، وما تسقط من ورقه من نبته الا يعلمها، فكل حبه في خفايا الارض، وكل رطب ويابس، مثبت في كتاب واضح لا لبس فيه، وهو اللوح المحفوظ."},{"id":"849","s":6,"a":60,"at":"وهو الذي يتوفاكم بالليل ويعلم ما جرحتم بالنهار ثم يبعثكم فيه ليقضى اجل مسمى ثم اليه مرجعكم ثم ينبئكم بما كنتم تعملون","dt":"[60] وهو سبحانه الذي يقبض ارواحكم بالليل بما يشبه قبضها عند الموت، ويعلم ما اكتسبتم في النهار من الاعمال، ثم يعيد ارواحكم الى اجسامكم باليقظه من النوم نهارا بما يشبه الاحياء بعد الموت؛ لتقضى اجالكم المحدده في الدنيا، ثم الى الله تعالى معادكم بعد بعثكم من قبوركم احياء، ثم يخبركم بما كنتم تعملون في حياتكم الدنيا، ثم يجازيكم بذلك."},{"id":"850","s":6,"a":61,"at":"وهو القاهر فوق عباده ويرسل عليكم حفظه حتى اذا جاء احدكم الموت توفته رسلنا وهم لا يفرطون","dt":"[61] والله تعالى هو القاهر فوق عباده، فوقيه مطلقه من كل وجه، تليق بجلاله سبحانه وتعالى. كل شيء خاضع لجلاله وعظمته، ويرسل على عباده ملائكه، يحفظون اعمالهم ويحصونها، حتى اذا نزل الموت باحدهم قبض روحه ملك الموت واعوانه، وهم لا يضيعون ما امروا به."},{"id":"851","s":6,"a":62,"at":"ثم ردوا الى الله مولاهم الحق الا له الحكم وهو اسرع الحاسبين","dt":"[62] ثم اعيد هؤلاء المتوفون الى الله تعالى مولاهم الحق. الا له القضاء والفصل يوم القيامه بين عباده، وهو اسرع الحاسبين."},{"id":"852","s":6,"a":63,"at":"قل من ينجيكم من ظلمات البر والبحر تدعونه تضرعا وخفيه لئن انجانا من هذه لنكونن من الشاكرين","dt":"[63] قل -ايها الرسول- لهؤلاء المشركين: من ينقذكم من مخاوف ظلمات البر والبحر؟ اليس هو الله تعالى الذي تدعونه في الشدائد متذللين جهرا وسرا؟ تقولون: لئن انجانا ربنا من هذه المخاوف لنكونن من الشاكرين بعبادته عز وجل وحده لا شريك له."},{"id":"853","s":6,"a":64,"at":"قل الله ينجيكم منها ومن كل كرب ثم انتم تشركون","dt":"[64] قل لهم -ايها الرسول-: الله وحده هو الذي ينقذكم من هذه المخاوف ومن كل شده، ثم انتم بعد ذلك تشركون معه في العباده غيره."},{"id":"854","s":6,"a":65,"at":"قل هو القادر على ان يبعث عليكم عذابا من فوقكم او من تحت ارجلكم او يلبسكم شيعا ويذيق بعضكم باس بعض انظر كيف نصرف الايات لعلهم يفقهون","dt":"[65] قل -ايها الرسول-: الله عز وجل هو القادر وحده على ان يرسل عليكم عذابا من فوقكم كالرجم او الطوفان، وما اشبه ذلك، او من تحت ارجلكم كالزلازل والخسف، او يخلط امركم عليكم فتكونوا فرقا متناحره يقتل بعضكم بعضا. انظر -ايها الرسول- كيف ننوع حججنا الواضحات لهؤلاء المشركين لعلهم يفهمون فيعتبروا؟"},{"id":"855","s":6,"a":66,"at":"وكذب به قومك وهو الحق قل لست عليكم بوكيل","dt":"[66] وكذب بهذا القران الكفار من قومك ايها الرسول، وهو الكتاب الصادق في كل ما جاء به. قل لهم: لست عليكم بحفيظ ولا رقيب، وانما انا رسول الله ابلغكم ما ارسلت به اليكم."},{"id":"856","s":6,"a":67,"at":"لكل نبا مستقر وسوف تعلمون","dt":"[67] لكل خبر قرار يستقر عنده، ونهايه ينتهي اليها، فيتبين الحق من الباطل، وسوف تعلمون -ايها الكفار- عاقبه امركم عند حلول عذاب الله بكم."},{"id":"857","s":6,"a":68,"at":"واذا رايت الذين يخوضون في اياتنا فاعرض عنهم حتى يخوضوا في حديث غيره واما ينسينك الشيطان فلا تقعد بعد الذكرى مع القوم الظالمين","dt":"[68] واذا رايت -ايها الرسول- المشركين الذين يتكلمون في ايات القران بالباطل والاستهزاء، فابتعد عنهم حتى ياخذوا في حديث اخر، وان انساك الشيطان هذا الامر فلا تقعد بعد تذكرك مع القوم المعتدين، الذين تكلموا في ايات الله بالباطل."},{"id":"858","s":6,"a":69,"at":"وما على الذين يتقون من حسابهم من شيء ولكن ذكرى لعلهم يتقون","dt":"[69] وما على المؤمنين الذين يخافون الله تعالى، فيطيعون اوامره، ويجتنبون نواهيه من حساب الله للخائضين المستهزئين بايات الله من شيء، ولكن عليهم ان يعظوهم ليمسكوا عن ذلك الكلام الباطل، لعلهم يتقون الله تعالى."},{"id":"859","s":6,"a":70,"at":"وذر الذين اتخذوا دينهم لعبا ولهوا وغرتهم الحياه الدنيا وذكر به ان تبسل نفس بما كسبت ليس لها من دون الله ولي ولا شفيع وان تعدل كل عدل لا يؤخذ منها اولئك الذين ابسلوا بما كسبوا لهم شراب من حميم وعذاب اليم بما كانوا يكفرون","dt":"[70] واترك -ايها الرسول- هؤلاء المشركين الذين جعلوا دين الاسلام لعبا ولهوا؛ مستهزئين بايات الله تعالى، وغرتهم الحياه الدنيا بزينتها، وذكر بالقران هؤلاء المشركين وغيرهم؛ كي لا ترتهن نفس بذنوبها وكفرها بربها، ليس لها غير الله ناصر ينصرها، فينقذها من عذابه، ولا شافع يشفع لها عنده، وان تفتد باي فداء لا يقبل منها. اولئك الذين ارتهنوا بذنوبهم، لهم في النار شراب شديد الحراره وعذاب موجع؛ بسبب كفرهم بالله تعالى، ورسوله محمد -صلى الله عليه وسلم-، وبدين الاسلام."},{"id":"860","s":6,"a":71,"at":"قل اندعوا من دون الله ما لا ينفعنا ولا يضرنا ونرد على اعقابنا بعد اذ هدانا الله كالذي استهوته الشياطين في الارض حيران له اصحاب يدعونه الى الهدى ائتنا قل ان هدى الله هو الهدى وامرنا لنسلم لرب العالمين","dt":"[71] قل -ايها الرسول- لهؤلاء المشركين: انعبد من دون الله تعالى اوثانا لا تنفع ولا تضر؟ ونرجع الى الكفر بعد هدايه الله تعالى لنا الى الاسلام، فنشبه -في رجوعنا الى الكفر- من فسد عقله باستهواء الشياطين له، فضل في الارض، وله رفقه عقلاء مؤمنون يدعونه الى الطريق الصحيح الذي هم عليه فيابى. قل -ايها الرسول- لهؤلاء المشركين: ان هدى الله الذي بعثني به هو الهدى الحق، وامرنا جميعا لنسلم لله تعالى رب العالمين بعبادته وحده لا شريك له، فهو رب كل شيء ومالكه."},{"id":"861","s":6,"a":72,"at":"وان اقيموا الصلاه واتقوه وهو الذي اليه تحشرون","dt":"[72] وكذلك امرنا بان نقيم الصلاه كامله، وان نخشاه بفعل اوامره واجتناب نواهيه. وهو -جل وعلا- الذي اليه تحشر جميع الخلائق يوم القيامه."},{"id":"862","s":6,"a":73,"at":"وهو الذي خلق السموات والارض بالحق ويوم يقول كن فيكون قوله الحق وله الملك يوم ينفخ في الصور عالم الغيب والشهاده وهو الحكيم الخبير","dt":"[73] والله سبحانه هو الذي خلق السموات والارض بالحق، واذكر -ايها الرسول- يوم القيامه اذ يقول الله: «كن»، فيكون عن امره كلمح البصر او هو اقرب، قوله هو الحق الكامل، وله الملك سبحانه وحده، يوم ينفخ الملك في «القرن» النفخه الثانيه التي تكون بها عوده الارواح الى الاجسام. وهو سبحانه الذي يعلم ما غاب عن حواسكم -ايها الناس- وما تشاهدونه، وهو الحكيم الذي يضع الامور في مواضعها، الخبير بامور خلقه. والله تعالى هو الذي يختص بهذه الامور وغيرها بدءا ونهايه، نشاه ومصيرا، وهو وحده الذي يجب على العباد الانقياد لشرعه، والتسليم لحكمه، والتطلع الى رضوانه ومغفرته."},{"id":"863","s":6,"a":74,"at":"واذ قال ابراهيم لابيه ازر اتتخذ اصناما الهه اني اراك وقومك في ضلال مبين","dt":"[74] واذكر -ايها الرسول- محاجه ابراهيم عليه السلام لابيه ازر، اذ قال له: اتجعل من الاصنام الهه تعبدها من دون الله تعالى؟ اني اراك وقومك في ضلال بين عن طريق الحق."},{"id":"864","s":6,"a":75,"at":"وكذلك نري ابراهيم ملكوت السموات والارض وليكون من الموقنين","dt":"[75] وكما هدينا ابراهيم عليه السلام الى الحق في امر العباده نريه ما تحتوي عليه السموات والارض من ملك عظيم، وقدره باهره؛ ليكون من الراسخين في الايمان."},{"id":"865","s":6,"a":76,"at":"فلما جن عليه الليل راى كوكبا قال هذا ربي فلما افل قال لا احب الافلين","dt":"[76] فلما اظلم على ابراهيم -عليه السلام- الليل وغطاه ناظر قومه؛ ليثبت لهم ان دينهم باطل، وكانوا يعبدون النجوم. راى ابراهيم عليه السلام كوكبا، فقال -مستدرجا قومه لالزامهم بالتوحيد-: هذا ربي، فلما غاب الكوكب، قال: لا احب الالهه التي تغيب."},{"id":"866","s":6,"a":77,"at":"فلما راى القمر بازغا قال هذا ربي فلما افل قال لئن لم يهدني ربي لاكونن من القوم الضالين","dt":"[77] فلما راى ابراهيم القمر طالعا قال لقومه -على سبيل استدراج الخصم-: هذا ربي، فلما غاب، قال: -مفتقرا الى هدايه ربه- لئن لم يوفقني ربي الى الصواب في توحيده، لاكونن من القوم الضالين عن سواء السبيل بعباده غير الله تعالى."},{"id":"867","s":6,"a":78,"at":"فلما راى الشمس بازغه قال هذا ربي هذا اكبر فلما افلت قال ياقوم اني بريء مما تشركون","dt":"[78] فلما راى الشمس طالعه قال لقومه: هذا ربي، هذا اكبر من الكوكب والقمر، فلما غابت، قال لقومه: اني بريء مما تشركون من عباده الاوثان والنجوم والاصنام التي تعبدونها من دون الله تعالى."},{"id":"868","s":6,"a":79,"at":"اني وجهت وجهي للذي فطر السموات والارض حنيفا وما انا من المشركين","dt":"[79] اني توجهت بوجهي في العباده لله عز وجل وحده، فهو الذي خلق السموات والارض، مائلا عن الشرك الى التوحيد، وما انا من المشركين مع الله غيره."},{"id":"869","s":6,"a":80,"at":"وحاجه قومه قال اتحاجوني في الله وقد هدان ولا اخاف ما تشركون به الا ان يشاء ربي شيئا وسع ربي كل شيء علما افلا تتذكرون","dt":"[80] وجادله قومه في توحيد الله تعالى قال: اتجادلونني في توحيدي لله بالعباده، وقد وفقني الى معرفه وحدانيته، فان كنتم تخوفونني بالهتكم ان توقع بي ضررا فانني لا ارهبها فلن تضرني، الا ان يشاء ربي شيئا. وسع ربي كل شيء علما. افلا تتذكرون فتعلموا انه وحده المعبود المستحق للعبوديه؟"},{"id":"870","s":6,"a":81,"at":"وكيف اخاف ما اشركتم ولا تخافون انكم اشركتم بالله ما لم ينزل به عليكم سلطانا فاي الفريقين احق بالامن ان كنتم تعلمون","dt":"[81] وكيف اخاف اوثانكم وانتم لا تخافون ربي الذي خلقكم، وخلق اوثانكم التي اشركتموها معه في العباده، من غير حجه لكم على ذلك؟ فاي الفريقين: فريق المشركين وفريق الموحدين احق بالطمانينه والسلامه والامن من عذاب الله؟ ان كنتم تعلمون صدق ما اقول فاخبروني."},{"id":"871","s":6,"a":82,"at":"الذين امنوا ولم يلبسوا ايمانهم بظلم اولئك لهم الامن وهم مهتدون","dt":"[82] الذين صدقوا الله ورسوله وعملوا بشرعه ولم يخلطوا ايمانهم بشرك، اولئك لهم الطمانينه والسلامه، وهم الموفقون الى طريق الحق."},{"id":"872","s":6,"a":83,"at":"وتلك حجتنا اتيناها ابراهيم على قومه نرفع درجات من نشاء ان ربك حكيم عليم","dt":"[83] وتلك الحجه التي حاج بها ابراهيم - عليه السلام - قومه هي حجتنا التي وفقناه اليها حتى انقطعت حجتهم. نرفع من نشاء من عبادنا مراتب في الدنيا والاخره. ان ربك حكيم في تدبير خلقه، عليم بهم."},{"id":"873","s":6,"a":84,"at":"ووهبنا له اسحاق ويعقوب كلا هدينا ونوحا هدينا من قبل ومن ذريته داود وسليمان وايوب ويوسف وموسى وهارون وكذلك نجزي المحسنين","dt":"[84] ومننا على ابراهيم - عليه السلام - بان رزقناه اسحاق ابنا ويعقوب حفيدا، ووفقنا كلا منهما لسبيل الرشاد، وكذلك وفقنا للحق نوحا -من قبل ابراهيم واسحاق ويعقوب- وكذلك وفقنا للحق من ذريه نوح داود وسليمان وايوب ويوسف وموسى وهارون عليهم السلام، وكما جزينا هؤلاء الانبياء باحسانهم نجزي كل محسن."},{"id":"874","s":6,"a":85,"at":"وزكريا ويحيى وعيسى والياس كل من الصالحين","dt":"[85] وكذلك هدينا زكريا ويحيى وعيسى والياس، وكل هؤلاء الانبياء عليهم السلام من الصالحين."},{"id":"875","s":6,"a":86,"at":"واسماعيل واليسع ويونس ولوطا وكلا فضلنا على العالمين","dt":"[86] وهدينا كذلك اسماعيل واليسع ويونس ولوطا، وكل هؤلاء الرسل فضلناهم على اهل زمانهم."},{"id":"876","s":6,"a":87,"at":"ومن ابائهم وذرياتهم واخوانهم واجتبيناهم وهديناهم الى صراط مستقيم","dt":"[87] وكذلك وفقنا للحق من شئنا هدايته من اباء هؤلاء وذرياتهم واخوانهم، واخترناهم لديننا وابلاغ رسالتنا الى من ارسلناهم اليهم، وارشدناهم الى طريق صحيح، لا عوج فيه، وهو توحيد الله تعالى وتنزيهه عن الشرك."},{"id":"877","s":6,"a":88,"at":"ذلك هدى الله يهدي به من يشاء من عباده ولو اشركوا لحبط عنهم ما كانوا يعملون","dt":"[88] ذلك الهدى هو توفيق الله، الذي يوفق به من يشاء من عباده. ولو ان هؤلاء الانبياء اشركوا بالله -على سبيل الفرض والتقدير- لبطل عملهم؛ لان الله تعالى لا يقبل مع الشرك عملا."},{"id":"878","s":6,"a":89,"at":"اولئك الذين اتيناهم الكتاب والحكم والنبوه فان يكفر بها هؤلاء فقد وكلنا بها قوما ليسوا بها بكافرين","dt":"[89] اولئك الانبياء الذين انعمنا عليهم بالهدايه والنبوه هم الذين اتيناهم الكتاب، كصحف ابراهيم وتوراه موسى وزبور داود وانجيل عيسى، واتيناهم فهم هذه الكتب، واخترناهم لابلاغ وحينا، فان يجحد -ايها الرسول- بايات هذا القران الكفار من قومك، فقد وفقنا للايمان بها والقيام بحقوقها قوما اخرين -اي: المهاجرين والانصار واتباعهم الى يوم القيامه- ليسوا بها بكافرين، بل مؤمنون بها، عاملون بما تدل عليه."},{"id":"879","s":6,"a":90,"at":"اولئك الذين هدى الله فبهداهم اقتده قل لا اسالكم عليه اجرا ان هو الا ذكرى للعالمين","dt":"[90] اولئك الانبياء المذكورون هم الذين وفقهم الله تعالى لدينه الحق، فاتبع هداهم -ايها الرسول- واسلك سبيلهم. قل للمشركين: لا اطلب منكم على تبليغ الاسلام عوضا من الدنيا، ان اجري الا على الله، وما الاسلام الا دعوه جميع الناس الى الطريق المستقيم، وتذكير لكم ولكل من كان مثلكم، ممن هو مقيم على باطل، لعلكم تتذكرون به ما ينفعكم."},{"id":"880","s":6,"a":91,"at":"وما قدروا الله حق قدره اذ قالوا ما انزل الله على بشر من شيء قل من انزل الكتاب الذي جاء به موسى نورا وهدى للناس تجعلونه قراطيس تبدونها وتخفون كثيرا وعلمتم ما لم تعلموا انتم ولا اباؤكم قل الله ثم ذرهم في خوضهم يلعبون","dt":"[91] وما عظم هؤلاء المشركون الله حق تعظيمه؛ اذ انكروا ان يكون الله تعالى قد انزل على احد من البشر شيئا من وحيه. قل لهم -ايها الرسول-: اذا كان الامر كما تزعمون، فمن الذي انزل الكتاب الذي جاء به موسى الى قومه نورا للناس وهدايه لهم؟ ثم توجه الخطاب الى اليهود زجرا لهم بقوله: تجعلون هذا الكتاب في قراطيس متفرقه، تظهرون بعضها، وتكتمون كثيرا منها، ومما كتموه الاخبار عن صفه محمد -صلى الله عليه وسلم- ونبوته، وعلمكم الله معشر العرب بالقران -الذي انزله عليكم، فيه خبر من قبلكم ومن بعدكم، وما يكون بعد موتكم- ما لم تعلموه انتم ولا اباؤكم؟ قل: الله هو الذي انزله، ثم دع هؤلاء في حديثهم الباطل يخوضون ويلعبون."},{"id":"881","s":6,"a":92,"at":"وهذا كتاب انزلناه مبارك مصدق الذي بين يديه ولتنذر ام القرى ومن حولها والذين يؤمنون بالاخره يؤمنون به وهم على صلاتهم يحافظون","dt":"[92] وهذا القران كتاب انزلناه اليك -ايها الرسول- عظيم النفع، يشهد على صدق ما تقدمه من الكتب المنزله وانها من عند الله، انزلناه لتخوف به من عذاب الله وباسه اهل «مكه» ومن حولها من اهل اقطار الارض كلها. والذين يصدقون بالحياه الاخره، يصدقون بان القران كلام الله، ويحافظون على اقام الصلاه في اوقاتها."},{"id":"882","s":6,"a":93,"at":"ومن اظلم ممن افترى على الله كذبا او قال اوحي الي ولم يوح اليه شيء ومن قال سانزل مثل ما انزل الله ولو ترى اذ الظالمون في غمرات الموت والملائكه باسطو ايديهم اخرجوا انفسكم اليوم تجزون عذاب الهون بما كنتم تقولون على الله غير الحق وكنتم عن اياته تستكبرون","dt":"[93] ومن اشد ظلما ممن اختلق على الله تعالى قولا كذبا، فادعى انه لم يبعث رسولا من البشر، او ادعى كذبا ان الله اوحى اليه ولم يوح اليه شيئا، او ادعى انه قادر على ان ينزل مثل ما انزل الله من القران؟ ولو انك ابصرت -ايها الرسول- هؤلاء المتجاوزين الحد وهم في اهوال الموت لرايت امرا هائلا، والملائكه الذين يقبضون ارواحهم باسطو ايديهم بالعذاب قائلين لهم: اخرجوا انفسكم، اليوم تهانون غايه الاهانه، كما كنتم تكذبون على الله، وتستكبرون عن اتباع اياته والانقياد لرسله."},{"id":"883","s":6,"a":94,"at":"ولقد جئتمونا فرادى كما خلقناكم اول مره وتركتم ما خولناكم وراء ظهوركم وما نرى معكم شفعاءكم الذين زعمتم انهم فيكم شركاء لقد تقطع بينكم وضل عنكم ما كنتم تزعمون","dt":"[94] ولقد جئتمونا للحساب والجزاء فرادى كما اوجدناكم في الدنيا اول مره حفاه عراه، وتركتم وراء ظهوركم ما مكناكم فيه مما تتباهون به من اموال في الدنيا، وما نرى معكم في الاخره اوثانكم التي كنتم تعتقدون انها تشفع لكم، وتدعون انها شركاء مع الله في العباده، لقد زال تواصلكم الذي كان بينكم في الدنيا، وذهب عنكم ما كنتم تدعون من ان الهتكم شركاء لله في العباده، وظهر انكم الخاسرون لانفسكم واهليكم واموالكم."},{"id":"884","s":6,"a":95,"at":"ان الله فالق الحب والنوى يخرج الحي من الميت ومخرج الميت من الحي ذلكم الله فانى تؤفكون","dt":"[95] ان الله تعالى يشق الحب، فيخرج منه الزرع، ويشق النوى، فيخرج منه الشجر، يخرج الحي من الميت كالانسان والحيوان مثلا من النطفه، ويخرج الميت من الحي كالنطفه من الانسان والحيوان؛ ذلكم الله اي: فاعل هذا هو الله وحده لا شريك له المستحق للعباده، فكيف تصرفون عن الحق الى الباطل فتعبدون معه غيره ؟"},{"id":"885","s":6,"a":96,"at":"فالق الاصباح وجعل الليل سكنا والشمس والقمر حسبانا ذلك تقدير العزيز العليم","dt":"[96] والله سبحانه وتعالى هو الذي شق ضياء الصباح من ظلام الليل، وجعل الليل مستقرا، يسكن فيه من يتعب بالنهار فياخذ نصيبه من الراحه، وجعل الشمس والقمر يجريان في فلكيهما بحساب متقن مقدر، لا يتغير ولا يضطرب، ذلك تقدير العزيز الذي عز سلطانه، العليم بمصالح خلقه وتدبير شؤونهم. والعزيز والعليم من اسماء الله الحسنى يدلان على كمال العزه والعلم."},{"id":"886","s":6,"a":97,"at":"وهو الذي جعل لكم النجوم لتهتدوا بها في ظلمات البر والبحر قد فصلنا الايات لقوم يعلمون","dt":"[97] والله سبحانه هو الذي جعل لكم - ايها الناس - النجوم علامات، تعرفون بها الطرق ليلا اذا ضللتم؛ بسبب الظلمه الشديده في البر والبحر، قد بينا البراهين الواضحه؛ ليتدبرها منكم اولو العلم بالله وشرعه."},{"id":"887","s":6,"a":98,"at":"وهو الذي انشاكم من نفس واحده فمستقر ومستودع قد فصلنا الايات لقوم يفقهون","dt":"[98] والله سبحانه هو الذي ابتدا خلقكم - ايها الناس - من ادم عليه السلام؛ اذ خلقه من طين، ثم كنتم سلاله ونسلا منه، فجعل لكم مستقرا تستقرون فيه، وهو ارحام النساء، ومستودعا تحفظون فيه، وهو اصلاب الرجال، قد بينا الحجج وميزنا الادله، واحكمناها لقوم يفهمون مواقع الحجج ومواضع العبر."},{"id":"888","s":6,"a":99,"at":"وهو الذي انزل من السماء ماء فاخرجنا به نبات كل شيء فاخرجنا منه خضرا نخرج منه حبا متراكبا ومن النخل من طلعها قنوان دانيه وجنات من اعناب والزيتون والرمان مشتبها وغير متشابه انظروا الى ثمره اذا اثمر وينعه ان في ذلكم لايات لقوم يؤمنون","dt":"[99] والله سبحانه هو الذي انزل من السحاب مطرا فاخرج به نبات كل شيء، فاخرج من النبات زرعا وشجرا اخضر، ثم اخرج من الزرع حبا يركب بعضه بعضا، كسنابل القمح والشعير والارز، واخرج من طلع النخل -وهو الغلاف الذي ينشا فيه اول ثمر النخل- عذوقا بما فيها من الرطب قريبه التناول، واخرج سبحانه بساتين من اعناب، واخرج شجر الزيتون والرمان الذي يتشابه في ورقه ويختلف في ثمره شكلا وطعما وطبعا. انظروا ايها الناس الى ثمر هذا النبات اذا اثمر، والى نضجه وبلوغه حين يبلغ. ان في ذلكم -ايها الناس- لدلالات على كمال قدره خالق هذه الاشياء وحكمته ورحمته لقوم يصدقون به تعالى ويعملون بشرعه."},{"id":"889","s":6,"a":100,"at":"وجعلوا لله شركاء الجن وخلقهم وخرقوا له بنين وبنات بغير علم سبحانه وتعالى عما يصفون","dt":"[100] وجعل هؤلاء المشركون الجن شركاء لله تعالى في العباده؛ اعتقادا منهم انهم ينفعون او يضرون، وقد خلقهم الله تعالى وما يعبدون من العدم، فهو المستقل بالخلق وحده، فيجب ان يستقل بالعباده وحده لا شريك له. ولقد كذب هؤلاء المشركون على الله تعالى حين نسبوا اليه البنين والبنات؛ جهلا منهم بما يجب له من صفات الكمال، تنزه وعلا عما نسبه اليه المشركون من ذلك الكذب والافتراء."},{"id":"890","s":6,"a":101,"at":"بديع السموات والارض انى يكون له ولد ولم تكن له صاحبه وخلق كل شيء وهو بكل شيء عليم","dt":"[101] والله تعالى هو الذي اوجد السموات والارض وما فيهن على غير مثال سابق، كيف يكون له ولد ولم تكن له صاحبه؟ تعالى الله عما يقول المشركون علوا كبيرا، وهو الذي خلق كل شيء من العدم، ولا يخفى عليه شيء من امور الخلق."},{"id":"891","s":6,"a":102,"at":"ذلكم الله ربكم لا اله الا هو خالق كل شيء فاعبدوه وهو على كل شيء وكيل","dt":"[102] ذلكم -ايها المشركون- هو ربكم جل وعلا، لا معبود بحق سواه، خالق كل شيء فانقادوا واخضعوا له بالطاعه والعباده. وهو سبحانه على كل شيء وكيل وحفيظ، يدبر امور خلقه."},{"id":"892","s":6,"a":103,"at":"لا تدركه الابصار وهو يدرك الابصار وهو اللطيف الخبير","dt":"[103] لا تحيط الابصار بالله -وان كان المؤمنون في الدار الاخره يرون ربهم بغير احاطه- وهو سبحانه يدرك الابصار ويحيط بها، ويعلمها على ما هي عليه، وهو اللطيف باوليائه الذي يعلم دقائق الاشياء، الخبير الذي يعلم بواطنها."},{"id":"893","s":6,"a":104,"at":"قد جاءكم بصائر من ربكم فمن ابصر فلنفسه ومن عمي فعليها وما انا عليكم بحفيظ","dt":"[104] قل -ايها الرسول- لهؤلاء المشركين: قد جاءتكم براهين ظاهره تبصرون بها الهدى من الضلال، مما اشتمل عليها القران، وجاء بها الرسول عليه الصلاه والسلام، فمن تبين هذه البراهين وامن بمدلولها فنفع ذلك لنفسه، ومن لم يبصر الهدى بعد ظهور الحجه عليه فعلى نفسه جنى، وما انا عليكم بحافظ احصي اعمالكم، وانما انا مبلغ، والله يهدي من يشاء ويضل من يشاء وفق علمه وحكمته."},{"id":"894","s":6,"a":105,"at":"وكذلك نصرف الايات وليقولوا درست ولنبينه لقوم يعلمون","dt":"[105] وكما بينا في هذا القران للمشركين البراهين الظاهره في امر التوحيد والنبوه والمعاد، نبين لهم البراهين في كل ما جهلوه فيقولون عند ذلك كذبا: تعلمت من اهل الكتاب، ولنبين -بتصريفنا الايات- الحق لقوم يعلمونه، فيقبلونه ويتبعونه، وهم المؤمنون برسول الله محمد -صلى الله عليه وسلم- وما انزل عليه."},{"id":"895","s":6,"a":106,"at":"اتبع ما اوحي اليك من ربك لا اله الا هو واعرض عن المشركين","dt":"[106] اتبع -ايها الرسول- ما اوحيناه اليك من الاوامر والنواهي التي اعظمها توحيد الله سبحانه والدعوه اليه، ولا تبال بعناد المشركين، وادعائهم الباطل."},{"id":"896","s":6,"a":107,"at":"ولو شاء الله ما اشركوا وما جعلناك عليهم حفيظا وما انت عليهم بوكيل","dt":"[107] ولو شاء الله تعالى ان لا يشرك هؤلاء المشركون لما اشركوا، لكنه تعالى عليم بما سيكون من سوء اختيارهم واتباعهم اهواءهم المنحرفه. وما جعلناك -ايها الرسول- عليهم رقيبا تحفظ عليهم اعمالهم، وما انت بقيم عليهم تدبر مصالحهم."},{"id":"897","s":6,"a":108,"at":"ولا تسبوا الذين يدعون من دون الله فيسبوا الله عدوا بغير علم كذلك زينا لكل امه عملهم ثم الى ربهم مرجعهم فينبئهم بما كانوا يعملون","dt":"[108] ولا تسبوا -ايها المسلمون- الاوثان التي يعبدها المشركون -سدا للذريعه- حتى لا يتسبب ذلك في سبهم الله جهلا واعتداء بغير علم. وكما حسنا لهؤلاء عملهم السيئ عقوبه لهم على سوء اختيارهم، حسنا لكل امه اعمالها، ثم الى ربهم معادهم جميعا فيخبرهم باعمالهم التي كانوا يعملونها في الدنيا، ثم يجازيهم بها."},{"id":"898","s":6,"a":109,"at":"واقسموا بالله جهد ايمانهم لئن جاءتهم ايه ليؤمنن بها قل انما الايات عند الله وما يشعركم انها اذا جاءت لا يؤمنون","dt":"[109] واقسم هؤلاء المشركون بايمان مؤكده: لئن جاءنا محمد بعلامه خارقه لنصدقن بما جاء به، قل -ايها الرسول-: انما مجيء المعجزات الخارقه من عند الله تعالى، هو القادر على المجيء بها اذا شاء، وما يدريكم ايها المؤمنون: لعل هذه المعجزات اذا جاءت لا يصدق بها هؤلاء المشركون."},{"id":"899","s":6,"a":110,"at":"ونقلب افئدتهم وابصارهم كما لم يؤمنوا به اول مره ونذرهم في طغيانهم يعمهون","dt":"[110] ونقلب افئدتهم وابصارهم، فنحول بينها وبين الانتفاع بايات الله، فلا يؤمنون بها كما لم يؤمنوا بايات القران عند نزولها اول مره، ونتركهم في تمردهم على الله متحيرين، لا يهتدون الى الحق والصواب."},{"id":"900","s":6,"a":111,"at":"ولو اننا نزلنا اليهم الملائكه وكلمهم الموتى وحشرنا عليهم كل شيء قبلا ما كانوا ليؤمنوا الا ان يشاء الله ولكن اكثرهم يجهلون","dt":"[111] ولو اننا اجبنا طلب هؤلاء المشركين، فنزلنا اليهم الملائكه من السماء، واحيينا لهم الموتى، فكلموهم، وجمعنا لهم كل شيء طلبوه فعاينوه مواجهه، لم يصدقوا بما دعوتهم اليه -ايها الرسول- ولم يعملوا به، الا من شاء الله له الهدايه، ولكن اكثر هؤلاء الكفار يجهلون الحق الذي جئت به من عند الله تعالى."},{"id":"901","s":6,"a":112,"at":"وكذلك جعلنا لكل نبي عدوا شياطين الانس والجن يوحي بعضهم الى بعض زخرف القول غرورا ولو شاء ربك ما فعلوه فذرهم وما يفترون","dt":"[112] وكما ابتليناك -ايها الرسول- باعدائك من المشركين ابتلينا جميع الانبياء -عليهم السلام- باعداء من مرده قومهم واعداء من مرده الجن، يلقي بعضهم الى بعض القول الذي زينوه بالباطل؛ ليغتر به سامعه، فيضل عن سبيل الله. ولو اراد ربك -جل وعلا- لحال بينهم وبين تلك العداوه، ولكنه الابتلاء من الله، فدعهم وما يختلقون من كذب وزور."},{"id":"902","s":6,"a":113,"at":"ولتصغى اليه افئده الذين لا يؤمنون بالاخره وليرضوه وليقترفوا ما هم مقترفون","dt":"[113] ولتميل اليه قلوب الكفار الذين لا يصدقون بالحياه الاخره ولا يعملون لها، ولتحبه انفسهم، وليكتسبوا من الاعمال السيئه ما هم مكتسبون. وفي هذا تهديد عظيم لهم."},{"id":"903","s":6,"a":114,"at":"افغير الله ابتغي حكما وهو الذي انزل اليكم الكتاب مفصلا والذين اتيناهم الكتاب يعلمون انه منزل من ربك بالحق فلا تكونن من الممترين","dt":"[114] قل -ايها الرسول- لهؤلاء المشركين: اغير الله الهي والهكم اطلب حكما بيني وبينكم، وهو سبحانه الذي انزل اليكم القران مبينا فيه الحكم فيما تختصمون فيه من امري وامركم؟ وبنو اسرائيل الذين اتاهم الله التوراه والانجيل يعلمون علما يقينا ان هذا القران منزل عليك -ايها الرسول- من ربك بالحق، فلا تكونن من الشاكين في شيء مما اوحينا اليك."},{"id":"904","s":6,"a":115,"at":"وتمت كلمت ربك صدقا وعدلا لا مبدل لكلماته وهو السميع العليم","dt":"[115] وتمت كلمه ربك -وهي القران- صدقا في الاخبار والاقوال، وعدلا في الاحكام، فلا يستطيع احد ان يبدل كلماته الكامله. والله تعالى هو السميع لما يقول عباده، العليم ببواطن امورهم وظواهرها."},{"id":"905","s":6,"a":116,"at":"وان تطع اكثر من في الارض يضلوك عن سبيل الله ان يتبعون الا الظن وان هم الا يخرصون","dt":"[116] ولو فرض -ايها الرسول- انك اطعت اكثر اهل الارض لاضلوك عن دين الله، ما يسيرون الا على ما ظنوه حقا بتقليدهم اسلافهم، وما هم الا يظنون ويكذبون."},{"id":"906","s":6,"a":117,"at":"ان ربك هو اعلم من يضل عن سبيله وهو اعلم بالمهتدين","dt":"[117] ان ربك هو اعلم بالضالين عن سبيل الرشاد، وهو اعلم منكم ومنهم بمن كان على استقامه وسداد، لا يخفى عليه منهم احد."},{"id":"907","s":6,"a":118,"at":"فكلوا مما ذكر اسم الله عليه ان كنتم باياته مؤمنين","dt":"[118] فكلوا من الذبائح التي ذكر اسم الله عليها، ان كنتم ببراهين الله تعالى الواضحه مصدقين."},{"id":"908","s":6,"a":119,"at":"وما لكم الا تاكلوا مما ذكر اسم الله عليه وقد فصل لكم ما حرم عليكم الا ما اضطررتم اليه وان كثيرا ليضلون باهوائهم بغير علم ان ربك هو اعلم بالمعتدين","dt":"[119] واي شيء يمنعكم - ايها المسلمون - من ان تاكلوا مما ذكر اسم الله عليه، وقد بين الله سبحانه لكم جميع ما حرم عليكم؟ لكن ما دعت اليه الضروره بسبب المجاعه، مما هو محرم عليكم كالميته، فانه مباح لكم. وان كثيرا من الضالين ليضلون عن سبيل الله اشياعهم في تحليل الحرام وتحريم الحلال باهوائهم؛ جهلا منهم. ان ربك -ايها الرسول- هو اعلم بمن تجاوز حده في ذلك، وهو الذي يتولى حسابه وجزاءه."},{"id":"909","s":6,"a":120,"at":"وذروا ظاهر الاثم وباطنه ان الذين يكسبون الاثم سيجزون بما كانوا يقترفون","dt":"[120] واتركوا -ايها الناس- جميع المعاصي، ما كان منها علانيه وما كان سرا. ان الذين يفعلون المعاصي سيعاقبهم ربهم؛ بسبب ما كانوا يعملونه من السيئات."},{"id":"910","s":6,"a":121,"at":"ولا تاكلوا مما لم يذكر اسم الله عليه وانه لفسق وان الشياطين ليوحون الى اوليائهم ليجادلوكم وان اطعتموهم انكم لمشركون","dt":"[121] ولا تاكلوا -ايها المسلمون- من الذبائح التي لم يذكر اسم الله عليها عند الذبح، كالميته وما ذبح للاوثان والجن، وغير ذلك، وان الاكل من تلك الذبائح لخروج عن طاعه الله تعالى. وان مرده الجن ليلقون الى اوليائهم من شياطين الانس بالشبهات حول تحريم اكل الميته، فيامرونهم ان يقولوا للمسلمين في جدالهم معهم: انكم بعدم اكلكم الميته لا تاكلون ما قتله الله، بينما تاكلون مما تذبحونه، وان اطعتموهم -ايها المسلمون في تحليل الميته- فانتم وهم في الشرك سواء."},{"id":"911","s":6,"a":122,"at":"او من كان ميتا فاحييناه وجعلنا له نورا يمشي به في الناس كمن مثله في الظلمات ليس بخارج منها كذلك زين للكافرين ما كانوا يعملون","dt":"[122] اومن كان ميتا في الضلاله هالكا حائرا، فاحيينا قلبه بالايمان، وهديناه له، ووفقناه لاتباع رسلنا، فاصبح يعيش في انوار الهدايه، كمن مثله في الجهالات والاهواء والضلالات المتفرقه، لا يهتدي الى منفذ، ولا مخلص له مما هو فيه؟ لا يستويان، وكما خذلت هذا الكافر الذي يجادلكم -ايها المؤمنون- فزينت له سوء عمله، فراه حسنا، زينت للجاحدين اعمالهم السيئه؛ ليستوجبوا بذلك العذاب."},{"id":"912","s":6,"a":123,"at":"وكذلك جعلنا في كل قريه اكابر مجرميها ليمكروا فيها وما يمكرون الا بانفسهم وما يشعرون","dt":"[123] ومثل هذا الذي حصل من زعماء الكفار في «مكه» من الصد عن دين الله تعالى، جعلنا في كل قريه مجرمين يتزعمهم اكابرهم؛ ليمكروا فيها بالصد عن دين الله، وما يكيدون الا انفسهم، وما يحسون بذلك."},{"id":"913","s":6,"a":124,"at":"واذا جاءتهم ايه قالوا لن نؤمن حتى نؤتى مثل ما اوتي رسل الله الله اعلم حيث يجعل رسالته سيصيب الذين اجرموا صغار عند الله وعذاب شديد بما كانوا يمكرون","dt":"[124] واذا جاءت هؤلاء المشركين من اهل «مكه» حجه ظاهره على نبوه محمد -صلى الله عليه وسلم-، قال بعض كبرائهم: لن نصدق بنبوته حتى يعطينا الله من النبوه والمعجزات مثل ما اعطى رسله السابقين. فرد الله تعالى عليهم بقوله: الله اعلم حيث يجعل رسالته، اي: بالذين هم اهل لحمل رسالته وتبليغها الى الناس. سينال هؤلاء الطغاه الذل، ولهم عذاب موجع في نار جهنم؛ بسبب كيدهم للاسلام واهله."},{"id":"914","s":6,"a":125,"at":"فمن يرد الله ان يهديه يشرح صدره للاسلام ومن يرد ان يضله يجعل صدره ضيقا حرجا كانما يصعد في السماء كذلك يجعل الله الرجس على الذين لا يؤمنون","dt":"[125] فمن يشا الله ان يوفقه لقبول الحق يشرح صدره للتوحيد والايمان، ومن يشا ان يضله يجعل صدره في حال شديده من الانقباض عن قبول الهدى، كحال من يصعد في طبقات الجو العليا، فيصاب بضيق شديد في التنفس. وكما يجعل الله صدور الكافرين شديده الضيق والانقباض، كذلك يجعل العذاب على الذين لا يؤمنون به."},{"id":"915","s":6,"a":126,"at":"وهذا صراط ربك مستقيما قد فصلنا الايات لقوم يذكرون","dt":"[126] وهذا الذي بيناه لك -ايها الرسول- هو الطريق الموصل الى رضا ربك وجنته. قد بينا البراهين لمن يتذكر من اهل العقول الراجحه."},{"id":"916","s":6,"a":127,"at":"لهم دار السلام عند ربهم وهو وليهم بما كانوا يعملون","dt":"[127] للمتذكرين عند ربهم جل وعلا يوم القيامه دار السلامه والامان من كل مكروه وهي الجنه، وهو سبحانه ناصرهم وحافظهم جزاء لهم؛ بسبب اعمالهم الصالحه."},{"id":"917","s":6,"a":128,"at":"ويوم يحشرهم جميعا يامعشر الجن قد استكثرتم من الانس وقال اولياؤهم من الانس ربنا استمتع بعضنا ببعض وبلغنا اجلنا الذي اجلت لنا قال النار مثواكم خالدين فيها الا ما شاء الله ان ربك حكيم عليم","dt":"[128] واذكر -ايها الرسول- يوم يحشر الله تعالى الكفار واولياءهم من شياطين الجن فيقول: يا معشر الجن قد اضللتم كثيرا من الانس، وقال اولياؤهم من كفار الانس: ربنا قد انتفع بعضنا من بعض، وبلغنا الاجل الذي اجلته لنا بانقضاء حياتنا الدنيا، قال الله تعالى لهم: النار مثواكم، اي: مكان اقامتكم خالدين فيها، الا من شاء الله عدم خلوده فيها من عصاه الموحدين. ان ربك حكيم في تدبيره وصنعه، عليم بجميع امور عباده."},{"id":"918","s":6,"a":129,"at":"وكذلك نولي بعض الظالمين بعضا بما كانوا يكسبون","dt":"[129] وكما سلطنا شياطين الجن على كفار الانس، فكانوا اولياء لهم، نسلط الظالمين من الانس بعضهم على بعض في الدنيا؛ بسبب ما يعملونه من المعاصي."},{"id":"919","s":6,"a":130,"at":"يامعشر الجن والانس الم ياتكم رسل منكم يقصون عليكم اياتي وينذرونكم لقاء يومكم هذا قالوا شهدنا على انفسنا وغرتهم الحياه الدنيا وشهدوا على انفسهم انهم كانوا كافرين","dt":"[130] ايها المشركون من الجن والانس، الم ياتكم رسل من جملتكم -وظاهر النصوص يدل على ان الرسل من الانس فقط-، يخبرونكم باياتي الواضحه المشتمله على الامر والنهي، وبيان الخير والشر، ويحذرونكم لقاء عذابي في يوم القيامه؟ قال هؤلاء المشركون من الانس والجن: شهدنا على انفسنا بان رسلك قد بلغونا اياتك، وانذرونا لقاء يومنا هذا، فكذبناهم، وخدعت هؤلاء المشركين زينه الحياه الدنيا، وشهدوا على انفسهم انهم كانوا جاحدين وحدانيه الله تعالى ومكذبين لرسله عليهم السلام."},{"id":"920","s":6,"a":131,"at":"ذلك ان لم يكن ربك مهلك القرى بظلم واهلها غافلون","dt":"[131] انما اعذرنا الى الثقلين بارسال الرسل وانزال الكتب؛ لئلا يؤاخذ احد بظلمه، وهو لم تبلغه دعوه، ولكن اعذرنا الى الامم، وما عذبنا احدا الا بعد ارسال الرسل اليهم."},{"id":"921","s":6,"a":132,"at":"ولكل درجات مما عملوا وما ربك بغافل عما يعملون","dt":"[132] ولكل عامل في طاعه الله تعالى او معصيته مراتب من عمله، يبلغه الله اياها، ويجازيه عليها. وما ربك -ايها الرسول- بغافل عما يعمل عباده."},{"id":"922","s":6,"a":133,"at":"وربك الغني ذو الرحمه ان يشا يذهبكم ويستخلف من بعدكم ما يشاء كما انشاكم من ذريه قوم اخرين","dt":"[133] وربك -ايها الرسول- الذي امر الناس بعبادته، هو الغني وحده، وكل خلقه محتاجون اليه، وهو سبحانه ذو الرحمه الواسعه، لو اراد لاهلككم، واوجد قوما غيركم يخلفونكم من بعد فنائكم، ويعملون بطاعته تعالى، كما اوجدكم من نسل قوم اخرين كانوا قبلكم."},{"id":"923","s":6,"a":134,"at":"ان ما توعدون لات وما انتم بمعجزين","dt":"[134] ان الذي يوعدكم به ربكم -ايها المشركون- من العقاب على كفركم واقع بكم، ولن تعجزوا ربكم هربا، فهو قادر على اعادتكم، وان صرتم ترابا وعظاما."},{"id":"924","s":6,"a":135,"at":"قل ياقوم اعملوا على مكانتكم اني عامل فسوف تعلمون من تكون له عاقبه الدار انه لا يفلح الظالمون","dt":"[135] قل -ايها الرسول-: يا قوم اعملوا على طريقتكم فاني عامل على طريقتي التي شرعها لي ربي جل وعلا، فسوف تعلمون -عند حلول النقمه بكم- من الذي تكون له العاقبه الحسنه؟ انه لا يفوز برضوان الله تعالى والجنه من تجاوز حده وظلم، فاشرك مع الله غيره."},{"id":"925","s":6,"a":136,"at":"وجعلوا لله مما ذرا من الحرث والانعام نصيبا فقالوا هذا لله بزعمهم وهذا لشركائنا فما كان لشركائهم فلا يصل الى الله وما كان لله فهو يصل الى شركائهم ساء ما يحكمون","dt":"[136] وجعل المشركون لله -جل وعلا- جزءا مما خلق من الزروع والثمار والانعام يقدمونه للضيوف والمساكين، وجعلوا قسما اخر من هذه الاشياء لشركائهم من الاوثان والانصاب، فما كان مخصصا لشركائهم فانه يصل اليها وحدها، ولا يصل الى الله، وما كان مخصصا لله تعالى فانه يصل الى شركائهم. بئس حكم القوم وقسمتهم."},{"id":"926","s":6,"a":137,"at":"وكذلك زين لكثير من المشركين قتل اولادهم شركاؤهم ليردوهم وليلبسوا عليهم دينهم ولو شاء الله ما فعلوه فذرهم وما يفترون","dt":"[137] وكما زين الشيطان للمشركين ان يجعلوا لله تعالى من الزرع والانعام نصيبا، ولشركائهم نصيبا، زينت الشياطين لكثير من المشركين قتل اولادهم خشيه الفقر؛ ليوقعوا هؤلاء الاباء في الهلاك بقتل النفس التي حرم الله قتلها الا بالحق، وليخلطوا عليهم دينهم فيلتبس، فيضلوا ويهلكوا، ولو شاء الله الا يفعلوا ذلك ما فعلوه، ولكنه قدر ذلك لعلمه بسوء حالهم ومالهم، فاتركهم -ايها الرسول- وشانهم فيما يفترون من كذب، فسيحكم الله بينك وبينهم."},{"id":"927","s":6,"a":138,"at":"وقالوا هذه انعام وحرث حجر لا يطعمها الا من نشاء بزعمهم وانعام حرمت ظهورها وانعام لا يذكرون اسم الله عليها افتراء عليه سيجزيهم بما كانوا يفترون","dt":"[138] وقال المشركون: هذه ابل وزرع حرام، لا ياكلها الا من ياذنون له -حسب ادعائهم- من سدنه الاوثان وغيرهم.وهذه ابل حرمت ظهورها، فلا يحل ركوبها والحمل عليها بحال من الاحوال.وهذه ابل لا يذكرون اسم الله تعالى عليها في اي شان من شؤونها. فعلوا ذلك كذبا منهم على الله، سيجزيهم الله بسبب ما كانوا يفترون من كذب عليه سبحانه."},{"id":"928","s":6,"a":139,"at":"وقالوا ما في بطون هذه الانعام خالصه لذكورنا ومحرم على ازواجنا وان يكن ميته فهم فيه شركاء سيجزيهم وصفهم انه حكيم عليم","dt":"[139] وقال المشركون: ما في بطون الانعام من اجنه مباح لرجالنا، ومحرم على نسائنا، اذا ولد حيا، ويشتركون فيه اذا ولد ميتا. سيعاقبهم الله اذ شرعوا لانفسهم من التحليل والتحريم مالم ياذن به الله. انه تعالى حكيم في تدبير امور خلقه، عليم بهم."},{"id":"929","s":6,"a":140,"at":"قد خسر الذين قتلوا اولادهم سفها بغير علم وحرموا ما رزقهم الله افتراء على الله قد ضلوا وما كانوا مهتدين","dt":"[140] قد خسر وهلك الذين قتلوا اولادهم لضعف عقولهم وجهلهم، وحرموا ما رزقهم الله كذبا على الله. قد بعدوا عن الحق، وما كانوا من اهل الهدى والرشاد. فالحلال ما احله الله، والحرام ما حرمه الله، وليس لاحد من خلقه فردا كان او جماعه ان يشرع لعباده ما لم ياذن به الله."},{"id":"930","s":6,"a":141,"at":"وهو الذي انشا جنات معروشات وغير معروشات والنخل والزرع مختلفا اكله والزيتون والرمان متشابها وغير متشابه كلوا من ثمره اذا اثمر واتوا حقه يوم حصاده ولا تسرفوا انه لا يحب المسرفين","dt":"[141] والله سبحانه وتعالى هو الذي اوجد لكم بساتين: منها ما هو مرفوع عن الارض كالاعناب، ومنها ما هو غير مرفوع، ولكنه قائم على سوقه كالنخل والزرع، متنوعا طعمه، والزيتون والرمان متشابها منظره، ومختلفا ثمره وطعمه. كلوا -ايها الناس- من ثمره اذا اثمر، واعطوا زكاته المفروضه عليكم يوم قطافه وحصاده، ولا تتجاوزوا حدود الاعتدال في اخراج المال واكل الطعام وغير ذلك. انه تعالى لا يحب المتجاوزين حدوده بانفاق المال في غير وجهه."},{"id":"931","s":6,"a":142,"at":"ومن الانعام حموله وفرشا كلوا مما رزقكم الله ولا تتبعوا خطوات الشيطان انه لكم عدو مبين","dt":"[142] واوجد من الانعام ما هو مهيا للحمل عليه لكبره وارتفاعه كالابل، ومنها ما هو مهيا لغير الحمل لصغره وقربه من الارض كالبقر والغنم، كلوا مما اباحه الله لكم واعطاكموه من هذه الانعام، ولا تحرموا ما احل الله منها اتباعا لطرق الشيطان، كما فعل المشركون. ان الشيطان لكم عدو ظاهر العداوه."},{"id":"932","s":6,"a":143,"at":"ثمانيه ازواج من الضان اثنين ومن المعز اثنين قل الذكرين حرم ام الانثيين اما اشتملت عليه ارحام الانثيين نبئوني بعلم ان كنتم صادقين","dt":"[143] هذه الانعام التي رزقها الله عباده من الابل والبقر والغنم ثمانيه اصناف: اربعه منها من الغنم، وهي الضان ذكورا واناثا، والمعز ذكورا واناثا. قل -ايها الرسول- لاولئك المشركين: هل حرم الله الذكرين من الغنم؟ فان قالوا: نعم، فقد كذبوا في ذلك؛ لانهم لا يحرمون كل ذكر من الضان والمعز، وقل لهم: هل حرم الله الانثيين من الغنم؟ فان قالوا: نعم، فقد كذبوا ايضا؛ لانهم لا يحرمون كل انثى من ولد الضان والمعز، وقل لهم: هل حرم الله ما اشتملت عليه ارحام الانثيين من الضان والمعز من الحمل؟ فان قالوا: نعم، فقد كذبوا ايضا؛ لانهم لا يحرمون كل حمل من ذلك، خبروني بعلم يدل على صحه ما ذهبتم اليه، ان كنتم صادقين فيما تنسبونه الى ربكم."},{"id":"933","s":6,"a":144,"at":"ومن الابل اثنين ومن البقر اثنين قل الذكرين حرم ام الانثيين اما اشتملت عليه ارحام الانثيين ام كنتم شهداء اذ وصاكم الله بهذا فمن اظلم ممن افترى على الله كذبا ليضل الناس بغير علم ان الله لا يهدي القوم الظالمين","dt":"[144] والاصناف الاربعه الاخرى: هي اثنان من الابل ذكورا واناثا، واثنان من البقر ذكورا واناثا. قل -ايها الرسول- لاولئك المشركين: احرم الله الذكرين ام الانثيين؟ ام حرم ما اشتملت عليه ارحام الانثيين ذكورا واناثا؟ ام كنتم ايها المشركون حاضرين، اذ وصاكم الله بهذا التحريم للانعام؟ فلا احد اشد ظلما ممن اختلق على الله الكذب؛ ليصرف الناس بجهله عن طريق الهدى. ان الله تعالى لا يوفق للرشد من تجاوز حده، فكذب على ربه، واضل الناس."},{"id":"934","s":6,"a":145,"at":"قل لا اجد في ما اوحي الي محرما على طاعم يطعمه الا ان يكون ميته او دما مسفوحا او لحم خنزير فانه رجس او فسقا اهل لغير الله به فمن اضطر غير باغ ولا عاد فان ربك غفور رحيم","dt":"[145] قل -ايها الرسول-: اني لا اجد فيما اوحى الله الي شيئا محرما على من ياكله مما تذكرون انه حرم من الانعام، الا ان يكون قد مات بغير تذكيه، او يكون دما مراقا، او يكون لحم خنزير فانه نجس، او الذي كانت ذكاته خروجا عن طاعه الله تعالى؛ كما اذا كان المذبوح قد ذكر عليه اسم غير الله عند الذبح. فمن اضطر الى الاكل من هذه المحرمات؛ بسبب الجوع الشديد غير طالب باكله منها تلذذا، ولا متجاوز حد الضروره، فان الله تعالى غفور له، رحيم به. وقد ثبت -فيما بعد- بالسنه تحريم كل ذي ناب من السباع، ومخلب من الطير، والحمر الاهليه، والكلاب."},{"id":"935","s":6,"a":146,"at":"وعلى الذين هادوا حرمنا كل ذي ظفر ومن البقر والغنم حرمنا عليهم شحومهما الا ما حملت ظهورهما او الحوايا او ما اختلط بعظم ذلك جزيناهم ببغيهم وانا لصادقون","dt":"[146] واذكر -ايها الرسول- لهؤلاء المشركين ما حرمنا على اليهود من البهائم والطير: وهو كل ما لم يكن مشقوق الاصابع كالابل والنعام، وشحوم البقر والغنم، الا ما علق من الشحم بظهورها او امعائها، او اختلط بعظم الاليه والجنب ونحو ذلك. ذلك التحريم المذكور على اليهود عقوبه منا لهم بسبب اعمالهم السيئه، وانا لصادقون فيما اخبرنا به عنهم."},{"id":"936","s":6,"a":147,"at":"فان كذبوك فقل ربكم ذو رحمه واسعه ولا يرد باسه عن القوم المجرمين","dt":"[147] فان كذبك -ايها الرسول- مخالفوك من المشركين واليهود، وغيرهم، فقل لهم: ربكم جل وعلا ذو رحمه واسعه، ولا يدفع عقابه عن القوم الذين اجرموا، فاكتسبوا الذنوب، واجترحوا السيئات. وفي هذا تهديد لهم لمخالفتهم الرسول -صلى الله عليه وسلم-."},{"id":"937","s":6,"a":148,"at":"سيقول الذين اشركوا لو شاء الله ما اشركنا ولا اباؤنا ولا حرمنا من شيء كذلك كذب الذين من قبلهم حتى ذاقوا باسنا قل هل عندكم من علم فتخرجوه لنا ان تتبعون الا الظن وان انتم الا تخرصون","dt":"[148] سيقول الذين اشركوا: لو اراد الله ان لا نشرك -نحن واباؤنا- وان لا نحرم شيئا من دونه ما فعلنا ذلك، ورد الله عليهم ببيان ان هذه الشبهه قد اثارها الكفار من قبلهم، وكذبوا بها دعوه رسلهم، واستمروا على ذلك، حتى نزل بهم عذاب الله. قل لهم -ايها الرسول-: هل عندكم -فيما حرمتم من الانعام والزرع، وفيما زعمتم من ان الله قد شاء لكم الكفر، ورضيه منكم واحبه لكم- من علم صحيح فتظهروه لنا؟ ان تتبعون في امور هذا الدين الا مجرد الظن، وان انتم الا تكذبون."},{"id":"938","s":6,"a":149,"at":"قل فلله الحجه البالغه فلو شاء لهداكم اجمعين","dt":"[149] قل -ايها الرسول- لهم: فلله - جل وعلا - الحجه القاطعه التي يقطع بها ظنونكم، فلو شاء لوفقكم جميعا الى طريق الاستقامه."},{"id":"939","s":6,"a":150,"at":"قل هلم شهداءكم الذين يشهدون ان الله حرم هذا فان شهدوا فلا تشهد معهم ولا تتبع اهواء الذين كذبوا باياتنا والذين لا يؤمنون بالاخره وهم بربهم يعدلون","dt":"[150] قل -ايها الرسول- لهؤلاء المشركين: هاتوا شهداءكم الذين يشهدون ان الله تعالى هو الذي حرم ما حرمتم من الزرع والانعام، فان شهدوا -كذبا وزورا- فلا تصدقهم، ولا توافق الذين حكموا اهواءهم، فكذبوا بايات الله فيما ذهبوا اليه من تحريم ما احل الله، وتحليل ما حرم الله، ولا تتبع الذين لا يصدقون بالحياه الاخره ولا يعملون لها، والذين هم بربهم يشركون فيعبدون معه غيره."},{"id":"940","s":6,"a":151,"at":"قل تعالوا اتل ما حرم ربكم عليكم الا تشركوا به شيئا وبالوالدين احسانا ولا تقتلوا اولادكم من املاق نحن نرزقكم واياهم ولا تقربوا الفواحش ما ظهر منها وما بطن ولا تقتلوا النفس التي حرم الله الا بالحق ذلكم وصاكم به لعلكم تعقلون","dt":"[151] قل -ايها الرسول- لهم: تعالوا اتل ما حرم ربكم عليكم: ان لا تشركوا معه شيئا من مخلوقاته في عبادته، بل اصرفوا جميع انواع العباده له وحده، كالخوف والرجاء والدعاء، وغير ذلك، وان تحسنوا الى الوالدين بالبر والدعاء ونحو ذلك من الاحسان، ولا تقتلوا اولادكم من اجل فقر نزل بكم؛ فان الله يرزقكم واياهم، ولا تقربوا ما كان ظاهرا من كبير الاثام، وما كان خفيا، ولا تقتلوا النفس التي حرم الله قتلها الا بالحق، وذلك في حال القصاص من القاتل، او الزنى بعد الاحصان، او الرده عن الاسلام، ذلكم المذكور مما نهاكم الله عنه، وعهد اليكم باجتنابه، ومما امركم به، وصاكم به ربكم؛ لعلكم تعقلون اوامره ونواهيه."},{"id":"941","s":6,"a":152,"at":"ولا تقربوا مال اليتيم الا بالتي هي احسن حتى يبلغ اشده واوفوا الكيل والميزان بالقسط لا نكلف نفسا الا وسعها واذا قلتم فاعدلوا ولو كان ذا قربى وبعهد الله اوفوا ذلكم وصاكم به لعلكم تذكرون","dt":"[152] ولا تقربوا ايها الاوصياء مال من مات ابوه وهو صغير الا بالحال التي تصلح بها امواله وينتفع بها، حتى يصل الى سن البلوغ ويكون راشدا، فاذا بلغ ذلك فسلموا اليه ماله، واوفوا الكيل والوزن بالعدل الذي يكون به تمام الوفاء. واذا بذلتم جهدكم فلا حرج عليكم فيما قد يكون من نقص، لا نكلف نفسا الا وسعها. واذا قلتم فتحروا في قولكم العدل دون ميل عن الحق في خبر او شهاده او حكم او شفاعه، ولو كان الذي تعلق به القول ذا قرابه منكم، فلا تميلوا معه بغير حق ، واوفوا بما عهد الله به اليكم من الالتزام بشريعته. ذلكم المتلو عليكم من الاحكام، وصاكم به ربكم؛ رجاء ان تتذكروا عاقبه امركم."},{"id":"942","s":6,"a":153,"at":"وان هذا صراطي مستقيما فاتبعوه ولا تتبعوا السبل فتفرق بكم عن سبيله ذلكم وصاكم به لعلكم تتقون","dt":"[153] ومما وصاكم الله به ان هذا الاسلام هو طريق الله تعالى المستقيم فاسلكوه، ولا تسلكوا سبل الضلال، فتفرقكم وتبعدكم عن سبيل الله المستقيم. ذلكم التوجه نحو الطريق المستقيم هو الذي وصاكم الله به؛ لتتقوا عذابه بفعل اوامره، واجتناب نواهيه."},{"id":"943","s":6,"a":154,"at":"ثم اتينا موسى الكتاب تماما على الذي احسن وتفصيلا لكل شيء وهدى ورحمه لعلهم بلقاء ربهم يؤمنون","dt":"[154] ثم قل -ايها الرسول- لهؤلاء المشركين: ان الله تعالى هو الذي اتى موسى التوراه تماما لنعمته على المحسنين من اهل ملته، وتفصيلا لكل شيء من امور دينهم، وهدى ودلاله على الطريق المستقيم ورحمه لهم؛ رجاء ان يصدقوا بالبعث بعد الموت والحساب والجزاء، ويعملوا لذلك."},{"id":"944","s":6,"a":155,"at":"وهذا كتاب انزلناه مبارك فاتبعوه واتقوا لعلكم ترحمون","dt":"[155] وهذا القران كتاب انزلناه على نبينا محمد -صلى الله عليه وسلم-، خيره كثير فاتبعوه فيما يامر به وينهى عنه، واتقوا الله ان تخالفوا له امرا؛ رجاء ان ترحموا فتنجوا من عذابه، وتظفروا بثوابه."},{"id":"945","s":6,"a":156,"at":"ان تقولوا انما انزل الكتاب على طائفتين من قبلنا وان كنا عن دراستهم لغافلين","dt":"[156] وانزلنا هذا القران؛ لئلا تقولوا -يا كفار العرب-: انما انزل الكتاب من السماء على اليهود والنصارى، وقد كنا عن قراءه كتبهم في شغل، ونحن ليس لنا بها علم ولا معرفه."},{"id":"946","s":6,"a":157,"at":"او تقولوا لو انا انزل علينا الكتاب لكنا اهدى منهم فقد جاءكم بينه من ربكم وهدى ورحمه فمن اظلم ممن كذب بايات الله وصدف عنها سنجزي الذين يصدفون عن اياتنا سوء العذاب بما كانوا يصدفون","dt":"[157] ولئلا تقولوا -ايها المشركون-: لو انا انزل علينا كتاب من السماء، كما انزل على اليهود والنصارى، لكنا اشد استقامه على طريق الحق منهم، فقد جاءكم كتاب بلسانكم عربي مبين، وذلك حجه واضحه من ربكم وارشاد الى طريق الحق، ورحمه لهذه الامه. فلا احد اشد ظلما وعدوانا ممن كذب بحجج الله تعالى واعرض عنها! فهؤلاء المعرضون سنعاقبهم عقابا شديدا في نار جهنم؛ بسبب اعراضهم عن اياتنا، وصدهم عن سبيلنا."},{"id":"947","s":6,"a":158,"at":"هل ينظرون الا ان تاتيهم الملائكه او ياتي ربك او ياتي بعض ايات ربك يوم ياتي بعض ايات ربك لا ينفع نفسا ايمانها لم تكن امنت من قبل او كسبت في ايمانها خيرا قل انتظروا انا منتظرون","dt":"[158] هل ينتظر الذين اعرضوا وصدوا عن سبيل الله الا ان ياتيهم ملك الموت واعوانه لقبض ارواحهم، او ياتي ربك -ايها الرسول- للفصل بين عباده يوم القيامه، او ياتي بعض اشراط الساعه وعلاماتها الداله على مجيئها، وهي طلوع الشمس من مغربها؟ فحين يكون ذلك لا ينفع نفسا ايمانها، ان لم تكن امنت من قبل، ولا يقبل منها ان كانت مؤمنه كسب عمل صالح ان لم تكن عامله به قبل ذلك. قل لهم -ايها الرسول-: انتظروا مجيء ذلك؛ لتعلموا المحق من المبطل، والمسيء من المحسن، انا منتظرون ذلك."},{"id":"948","s":6,"a":159,"at":"ان الذين فرقوا دينهم وكانوا شيعا لست منهم في شيء انما امرهم الى الله ثم ينبئهم بما كانوا يفعلون","dt":"[159] ان الذين فرقوا دينهم بعد ما كانوا مجتمعين على توحيد الله والعمل بشرعه، فاصبحوا فرقا واحزابا، انك -ايها الرسول- بريء منهم، انما حكمهم الى الله تعالى، ثم يخبرهم باعمالهم، فيجازي من تاب منهم واحسن باحسانه، ويعاقب المسيء باساءته."},{"id":"949","s":6,"a":160,"at":"من جاء بالحسنه فله عشر امثالها ومن جاء بالسيئه فلا يجزى الا مثلها وهم لا يظلمون","dt":"[160] من لقي ربه يوم القيامه بحسنه من الاعمال الصالحه فله عشر حسنات امثالها، ومن لقي ربه بسيئه فلا يعاقب الا بمثلها، وهم لا يظلمون مثقال ذره."},{"id":"950","s":6,"a":161,"at":"قل انني هداني ربي الى صراط مستقيم دينا قيما مله ابراهيم حنيفا وما كان من المشركين","dt":"[161] قل -ايها الرسول- لهؤلاء المشركين: انني ارشدني ربي الى الطريق القويم الموصل الى جنته، وهو دين الاسلام القائم بامر الدنيا والاخره، وهو دين التوحيد دين ابراهيم عليه السلام، وما كان ابراهيم عليه السلام من المشركين مع الله غيره."},{"id":"951","s":6,"a":162,"at":"قل ان صلاتي ونسكي ومحياي ومماتي لله رب العالمين","dt":"[162] قل -ايها الرسول- لهؤلاء المشركين: ان صلاتي، ونسكي، اي: ذبحي لله وحده، لا للاصنام، ولا للاموات، ولا للجن، ولا لغير ذلك مما تذبحونه لغير الله، وعلى غير اسمه كما تفعلون، وحياتي وموتي لله تعالى رب العالمين."},{"id":"952","s":6,"a":163,"at":"لا شريك له وبذلك امرت وانا اول المسلمين","dt":"[163] لا شريك له في الوهيته ولا في ربوبيته ولا في اسمائه وصفاته، وبذلك التوحيد الخالص امرني ربي جل وعلا، وانا اول من اقر وانقاد لله من هذه الامه."},{"id":"953","s":6,"a":164,"at":"قل اغير الله ابغي ربا وهو رب كل شيء ولا تكسب كل نفس الا عليها ولا تزر وازره وزر اخرى ثم الى ربكم مرجعكم فينبئكم بما كنتم فيه تختلفون","dt":"[164] قل -ايها الرسول-: اغير الله اطلب الها، وهو خالق كل شيء ومالكه ومدبره؟ ولا يعمل اي انسان عملا سيئا الا كان اثمه عليه، ولا تحمل نفس اثمه اثم نفس اخرى، ثم الى ربكم معادكم يوم القيامه، فيخبركم بما كنتم تختلفون فيه من امر الدين."},{"id":"954","s":6,"a":165,"at":"وهو الذي جعلكم خلائف الارض ورفع بعضكم فوق بعض درجات ليبلوكم في ما اتاكم ان ربك سريع العقاب وانه لغفور رحيم","dt":"[165] والله سبحانه هو الذي جعلكم تخلفون من سبقكم في الارض بعد ان اهلكهم الله، واستخلفكم فيها؛ لتعمروها بعدهم بطاعه ربكم، ورفع بعضكم في الرزق والقوه فوق بعض درجات؛ ليبلوكم فيما اعطاكم من نعمه، فيظهر للناس الشاكر من غيره. ان ربك سريع العقاب لمن كفر به وعصاه، وانه لغفور لمن امن به وعمل صالحا وتاب من الموبقات، رحيم به، والغفور والرحيم اسمان كريمان من اسماء الله الحسنى."},{"id":"955","s":7,"a":1,"at":"المص","dt":"[1] المص سبق الكلام على الحروف المقطعه في اول سوره البقره."},{"id":"956","s":7,"a":2,"at":"كتاب انزل اليك فلا يكن في صدرك حرج منه لتنذر به وذكرى للمؤمنين","dt":"[2] هذا القران كتاب عظيم انزله الله عليك -ايها الرسول- فلا يكن في صدرك شك منه في انه انزل من عند الله، ولا تتحرج في ابلاغه والانذار به، انزلناه اليك؛ لتخوف به الكافرين وتذكر المؤمنين."},{"id":"957","s":7,"a":3,"at":"اتبعوا ما انزل اليكم من ربكم ولا تتبعوا من دونه اولياء قليلا ما تذكرون","dt":"[3] اتبعوا -ايها الناس- ما انزل اليكم من ربكم من الكتاب والسنه بامتثال الاوامر واجتناب النواهي، ولا تتبعوا من دون الله اولياء كالشياطين والاحبار والرهبان. انكم قليلا ما تتعظون وتعتبرون، فترجعون الى الحق."},{"id":"958","s":7,"a":4,"at":"وكم من قريه اهلكناها فجاءها باسنا بياتا او هم قائلون","dt":"[4] وكثير من القرى اهلكنا اهلها بسبب مخالفه رسلنا وتكذيبهم، فاعقبهم ذلك خزي الدنيا موصولا بذل الاخره، فجاءهم عذابنا مره وهم نائمون ليلا، ومره وهم نائمون نهارا. وخص الله هذين الوقتين بالذكر؛ لانهما وقتان للسكون والاستراحه، فمجيء العذاب فيهما افظع واشد."},{"id":"959","s":7,"a":5,"at":"فما كان دعواهم اذ جاءهم باسنا الا ان قالوا انا كنا ظالمين","dt":"[5] فما كان قولهم عند مجيء العذاب الا الاقرار بالذنوب والاساءه، وانهم حقيقون بالعذاب الذي نزل بهم."},{"id":"960","s":7,"a":6,"at":"فلنسالن الذين ارسل اليهم ولنسالن المرسلين","dt":"[6] فلنسالن الامم الذين ارسل اليهم المرسلون: ماذا اجبتم رسلنا اليكم؟ ولنسالن المرسلين عن تبليغهم لرسالات ربهم، وعما اجابتهم به اممهم."},{"id":"961","s":7,"a":7,"at":"فلنقصن عليهم بعلم وما كنا غائبين","dt":"[7] فلنقصن على الخلق كلهم ما عملوا بعلم منا لاعمالهم في الدنيا فيما امرناهم به، وما نهيناهم عنه، وما كنا غائبين عنهم في حال من الاحوال."},{"id":"962","s":7,"a":8,"at":"والوزن يومئذ الحق فمن ثقلت موازينه فاولئك هم المفلحون","dt":"[8] ووزن اعمال الناس يوم القيامه يكون بميزان حقيقي بالعدل والقسط الذي لا ظلم فيه، فمن ثقلت موازين اعماله -لكثره حسناته- فاولئك هم الفائزون."},{"id":"963","s":7,"a":9,"at":"ومن خفت موازينه فاولئك الذين خسروا انفسهم بما كانوا باياتنا يظلمون","dt":"[9] ومن خفت موازين اعماله -لكثره سيئاته- فاولئك هم الذين اضاعوا حظهم من رضوان الله تعالى؛ بسبب تجاوزهم الحد بجحد ايات الله تعالى وعدم الانقياد لها."},{"id":"964","s":7,"a":10,"at":"ولقد مكناكم في الارض وجعلنا لكم فيها معايش قليلا ما تشكرون","dt":"[10] ولقد مكنا لكم -ايها الناس- في الارض، وجعلناها قرارا لكم، وجعلنا لكم فيها ما تعيشون به من مطاعم ومشارب، ومع ذلك فشكركم لنعم الله قليل."},{"id":"965","s":7,"a":11,"at":"ولقد خلقناكم ثم صورناكم ثم قلنا للملائكه اسجدوا لادم فسجدوا الا ابليس لم يكن من الساجدين","dt":"[11] ولقد انعمنا عليكم بخلق اصلكم -وهو ابوكم ادم من العدم- ثم صورناه على هيئته المفضله على كثير من الخلق، ثم امرنا ملائكتنا عليهم السلام بالسجود له -اكراما واحتراما واظهارا لفضل ادم- فسجدوا جميعا، لكن ابليس الذي كان معهم لم يكن من الساجدين لادم؛ حسدا له على هذا التكريم العظيم."},{"id":"966","s":7,"a":12,"at":"قال ما منعك الا تسجد اذ امرتك قال انا خير منه خلقتني من نار وخلقته من طين","dt":"[12] قال تعالى منكرا على ابليس ترك السجود: ما منعك الا تسجد اذ امرتك؟ فقال ابليس: انا افضل منه خلقا؛ لاني مخلوق من نار، وهو مخلوق من طين. فراى ان النار اشرف من الطين."},{"id":"967","s":7,"a":13,"at":"قال فاهبط منها فما يكون لك ان تتكبر فيها فاخرج انك من الصاغرين","dt":"[13] قال الله لابليس: فاهبط من الجنه، فما يصح لك ان تتكبر فيها، فاخرج من الجنه، انك من الذليلين الحقيرين."},{"id":"968","s":7,"a":14,"at":"قال انظرني الى يوم يبعثون","dt":"[14] قال ابليس لله -جل وعلا- حينما يئس من رحمته: امهلني الى يوم البعث؛ وذلك لاتمكن من اغواء من اقدر عليه من بني ادم."},{"id":"969","s":7,"a":15,"at":"قال انك من المنظرين","dt":"[15] قال الله تعالى: انك ممن كتبت عليهم تاخير الاجل الى النفخه الاولى في «القرن»، اذ يموت الخلق كلهم."},{"id":"970","s":7,"a":16,"at":"قال فبما اغويتني لاقعدن لهم صراطك المستقيم","dt":"[16] قال ابليس لعنه الله: فبسبب ما اضللتني لاجتهدن في اغواء بني ادم عن طريقك القويم، ولاصدنهم عن الاسلام الذي فطرتهم عليه."},{"id":"971","s":7,"a":17,"at":"ثم لاتينهم من بين ايديهم ومن خلفهم وعن ايمانهم وعن شمائلهم ولا تجد اكثرهم شاكرين","dt":"[17] ثم لاتينهم من جميع الجهات والجوانب، فاصدهم عن الحق، واحسن لهم الباطل، وارغبهم في الدنيا، واشككهم في الاخره، ولا تجد اكثر بني ادم شاكرين لك نعمتك."},{"id":"972","s":7,"a":18,"at":"قال اخرج منها مذءوما مدحورا لمن تبعك منهم لاملان جهنم منكم اجمعين","dt":"[18] قال الله تعالى لابليس: اخرج من الجنه ممقوتا مطرودا، لاملان جهنم منك وممن تبعك من بني ادم اجمعين."},{"id":"973","s":7,"a":19,"at":"وياادم اسكن انت وزوجك الجنه فكلا من حيث شئتما ولا تقربا هذه الشجره فتكونا من الظالمين","dt":"[19] ويا ادم اسكن انت وزوجك حواء الجنه، فكلا من ثمارها حيث شئتما، ولا تاكلا من ثمره شجره (عينها لهما)، فان فعلتما ذلك كنتما من الظالمين المتجاوزين حدود الله."},{"id":"974","s":7,"a":20,"at":"فوسوس لهما الشيطان ليبدي لهما ما ووري عنهما من سواتهما وقال ما نهاكما ربكما عن هذه الشجره الا ان تكونا ملكين او تكونا من الخالدين","dt":"[20] فالقى الشيطان لادم وحواء وسوسه لايقاعهما في معصيه الله تعالى بالاكل من تلك الشجره التي نهاهما الله عنها؛ لتكون عاقبتهما انكشاف ما ستر من عوراتهما، وقال لهما في محاوله المكر بهما: انما نهاكما ربكما عن الاكل من ثمر هذه الشجره من اجل ان لا تكونا ملكين، ومن اجل ان لا تكونا من الخالدين في الجنه."},{"id":"975","s":7,"a":21,"at":"وقاسمهما اني لكما لمن الناصحين","dt":"[21] واقسم الشيطان لادم وحواء بالله انه ممن ينصح لهما في مشورته عليهما بالاكل من الشجره، وهو كاذب في ذلك."},{"id":"976","s":7,"a":22,"at":"فدلاهما بغرور فلما ذاقا الشجره بدت لهما سواتهما وطفقا يخصفان عليهما من ورق الجنه وناداهما ربهما الم انهكما عن تلكما الشجره واقل لكما ان الشيطان لكما عدو مبين","dt":"[22] فجراهما وغرهما، فاكلا من الشجره التي نهاهما الله عن الاقتراب منها، فلما اكلا منها انكشفت لهما عوراتهما، وزال ما سترهما الله به قبل المخالفه، فاخذا يلزقان بعض ورق الجنه على عوراتهما، وناداهما ربهما جل وعلا: الم انهكما عن الاكل من تلك الشجره، واقل لكما: ان الشيطان لكما عدو ظاهر العداوه؟ وفي هذه الايه دليل على ان كشف العوره من عظائم الامور، وانه كان ولم يزل مستهجنا في الطباع، مستقبحا في العقول."},{"id":"977","s":7,"a":23,"at":"قالا ربنا ظلمنا انفسنا وان لم تغفر لنا وترحمنا لنكونن من الخاسرين","dt":"[23] قال ادم وحواء: ربنا ظلمنا انفسنا بالاكل من الشجره، وان لم تغفر لنا وترحمنا لنكونن ممن اضاعوا حظهم في دنياهم واخراهم. وهذه الكلمات هي التي تلقاها ادم من ربه، فدعا بها فتاب الله عليه."},{"id":"978","s":7,"a":24,"at":"قال اهبطوا بعضكم لبعض عدو ولكم في الارض مستقر ومتاع الى حين","dt":"[24] قال تعالى مخاطبا ادم وحواء وابليس: اهبطوا من الجنه الى الارض، وسيكون بعضكم لبعض عدوا، ولكم في الارض مكان تستقرون فيه، وتتمتعون الى انقضاء اجالكم."},{"id":"979","s":7,"a":25,"at":"قال فيها تحيون وفيها تموتون ومنها تخرجون","dt":"[25] قال الله تعالى لادم وحواء وذريتهما: فيها تحيون، اي: في الارض تقضون ايام حياتكم الدنيا، وفيها تكون وفاتكم، ومنها يخرجكم ربكم، ويحشركم احياء يوم البعث."},{"id":"980","s":7,"a":26,"at":"يابني ادم قد انزلنا عليكم لباسا يواري سواتكم وريشا ولباس التقوى ذلك خير ذلك من ايات الله لعلهم يذكرون","dt":"[26] يا بني ادم قد جعلنا لكم لباسا يستر عوراتكم، وهو لباس الضروره، ولباسا للزينه والتجمل، وهو من الكمال والتنعم. ولباس تقوى الله تعالى بفعل الاوامر واجتناب النواهي هو خير لباس للمؤمن. ذلك الذي من الله به عليكم من الدلائل على ربوبيه الله تعالى ووحدانيته وفضله ورحمته بعباده؛ لكي تتذكروا هذه النعم، فتشكروا لله عليها. وفي ذلك امتنان من الله تعالى على خلقه بهذه النعم."},{"id":"981","s":7,"a":27,"at":"يابني ادم لا يفتننكم الشيطان كما اخرج ابويكم من الجنه ينزع عنهما لباسهما ليريهما سواتهما انه يراكم هو وقبيله من حيث لا ترونهم انا جعلنا الشياطين اولياء للذين لا يؤمنون","dt":"[27] يا بني ادم لا يخدعنكم الشيطان، فيزين لكم المعصيه، كما زينها لابويكم ادم وحواء، فاخرجهما بسببها من الجنه، ينزع عنهما لباسهما الذي سترهما الله به؛ لتنكشف لهما عوراتهما. ان الشيطان يراكم هو وذريته وجنسه وانتم لا ترونهم فاحذروهم. انا جعلنا الشياطين اولياء للكفار الذين لا يوحدون الله، ولا يصدقون رسله، ولا يعملون بهديه."},{"id":"982","s":7,"a":28,"at":"واذا فعلوا فاحشه قالوا وجدنا عليها اباءنا والله امرنا بها قل ان الله لا يامر بالفحشاء اتقولون على الله ما لا تعلمون","dt":"[28] واذا اتى الكفار قبيحا من الفعل اعتذروا عن فعله بانه مما ورثوه عن ابائهم، وانه مما امر الله به. قل لهم -ايها الرسول-: ان الله تعالى لا يامر عباده بقبائح الافعال ومساوئها، اتقولون على الله -ايها المشركون- ما لا تعلمون كذبا وافتراء؟"},{"id":"983","s":7,"a":29,"at":"قل امر ربي بالقسط واقيموا وجوهكم عند كل مسجد وادعوه مخلصين له الدين كما بداكم تعودون","dt":"[29] قل -ايها الرسول- لهؤلاء المشركين: امر ربي بالعدل، وامركم بان تخلصوا له العباده في كل موضع من مواضعها، وبخاصه في المساجد، وان تدعوه مخلصين له الطاعه والعباده، وان تؤمنوا بالبعث بعد الموت. وكما ان الله اوجدكم من العدم فانه قادر على اعاده الحياه اليكم مره اخرى."},{"id":"984","s":7,"a":30,"at":"فريقا هدى وفريقا حق عليهم الضلاله انهم اتخذوا الشياطين اولياء من دون الله ويحسبون انهم مهتدون","dt":"[30] جعل الله عباده فريقين: فريقا وفقهم للهدايه الى الصراط المستقيم، وفريقا وجبت عليهم الضلاله عن الطريق المستقيم؛ انهم اتخذوا الشياطين اولياء من دون الله، فاطاعوهم جهلا منهم، وظنا انهم قد سلكوا سبيل الهدايه."},{"id":"985","s":7,"a":31,"at":"يابني ادم خذوا زينتكم عند كل مسجد وكلوا واشربوا ولا تسرفوا انه لا يحب المسرفين","dt":"[31] يا بني ادم كونوا عند اداء كل صلاه على حاله من الزينه المشروعه، من ثياب ساتره لعوراتكم ونظافه وطهاره ونحو ذلك، وكلوا واشربوا من طيبات ما رزقكم الله، ولا تتجاوزوا حدود الاعتدال في ذلك. ان الله لا يحب المتجاوزين المسرفين في الطعام والشراب، وغير ذلك."},{"id":"986","s":7,"a":32,"at":"قل من حرم زينه الله التي اخرج لعباده والطيبات من الرزق قل هي للذين امنوا في الحياه الدنيا خالصه يوم القيامه كذلك نفصل الايات لقوم يعلمون","dt":"[32] قل -ايها الرسول- لهؤلاء الجهله من المشركين: من الذي حرم عليكم اللباس الحسن الذي جعله الله تعالى زينه لكم؟ ومن الذي حرم عليكم التمتع بالحلال الطيب من رزق الله تعالى؟ قل -ايها الرسول- لهؤلاء المشركين: ان ما احله الله من الملابس والطيبات من المطاعم والمشارب حق للذين امنوا في الحياه الدنيا يشاركهم فيها غيرهم، خالصه لهم يوم القيامه. مثل ذلك التفصيل يفصل الله الايات لقوم يعلمون ما يبين لهم، ويفقهون ما يميز لهم."},{"id":"987","s":7,"a":33,"at":"قل انما حرم ربي الفواحش ما ظهر منها وما بطن والاثم والبغي بغير الحق وان تشركوا بالله ما لم ينزل به سلطانا وان تقولوا على الله ما لا تعلمون","dt":"[33] قل -ايها الرسول- لهؤلاء المشركين: انما حرم الله القبائح من الاعمال، ما كان منها ظاهرا، وما كان خفيا، وحرم المعاصي كلها، ومن اعظمها الاعتداء على الناس، فان ذلك مجانب للحق، وحرم ان تعبدوا مع الله تعالى غيره مما لم ينزل به دليلا وبرهانا، فانه لا حجه لفاعل ذلك، وحرم ان تنسبوا الى الله تعالى ما لم يشرعه افتراء وكذبا، كدعوى ان لله ولدا، وتحريم بعض الحلال من الملابس والماكل."},{"id":"988","s":7,"a":34,"at":"ولكل امه اجل فاذا جاء اجلهم لا يستاخرون ساعه ولا يستقدمون","dt":"[34] ولكل جماعه اجتمعت على الكفر بالله تعالى وتكذيب رسله -عليهم الصلاه والسلام- وقت لحلول العقوبه بهم، فاذا جاء الوقت الذي وقته الله لاهلاكهم لا يتاخرون عنه لحظه، ولا يتقدمون عليه."},{"id":"989","s":7,"a":35,"at":"يابني ادم اما ياتينكم رسل منكم يقصون عليكم اياتي فمن اتقى واصلح فلا خوف عليهم ولا هم يحزنون","dt":"[35] يا بني ادم اذا جاءكم رسلي من اقوامكم، يتلون عليكم ايات كتابي، ويبينون لكم البراهين على صدق ما جاؤوكم به فاطيعوهم، فانه من اتقى سخطي واصلح عمله فلا خوف عليهم يوم القيامه من عقاب الله تعالى، ولا هم يحزنون على ما فاتهم من حظوظ الدنيا."},{"id":"990","s":7,"a":36,"at":"والذين كذبوا باياتنا واستكبروا عنها اولئك اصحاب النار هم فيها خالدون","dt":"[36] والكفار الذين كذبوا بالدلائل على توحيد الله، واستعلوا عن اتباعها، اولئك اصحاب النار ماكثين فيها، لا يخرجون منها ابدا."},{"id":"991","s":7,"a":37,"at":"فمن اظلم ممن افترى على الله كذبا او كذب باياته اولئك ينالهم نصيبهم من الكتاب حتى اذا جاءتهم رسلنا يتوفونهم قالوا اين ما كنتم تدعون من دون الله قالوا ضلوا عنا وشهدوا على انفسهم انهم كانوا كافرين","dt":"[37] لا احد اشد ظلما ممن اختلق على الله تعالى الكذب، او كذب باياته المنزله، اولئك يصل اليهم حظهم من خير وشر في الدنيا مما كتب لهم في اللوح المحفوظ، حتى اذا جاءهم ملك الموت واعوانه يقبضون ارواحهم قالوا لهم: اين الذين كنتم تعبدونهم من دون الله من الشركاء والاولياء والاوثان ليخلصوكم مما انتم فيه؟ قالوا: ذهبوا عنا، واعترفوا على انفسهم حينئذ انهم كانوا في الدنيا جاحدين مكذبين وحدانيه الله تعالى."},{"id":"992","s":7,"a":38,"at":"قال ادخلوا في امم قد خلت من قبلكم من الجن والانس في النار كلما دخلت امه لعنت اختها حتى اذا اداركوا فيها جميعا قالت اخراهم لاولاهم ربنا هؤلاء اضلونا فاتهم عذابا ضعفا من النار قال لكل ضعف ولكن لا تعلمون","dt":"[38] قال الله تعالى -لهؤلاء المشركين المفترين-: ادخلوا النار في جمله جماعات من امثالكم في الكفر، قد سلفت من قبلكم من الجن والانس، كلما دخلت النار جماعه من اهل مله لعنت نظيرتها التي ضلت بالاقتداء بها، حتى اذا تلاحق في النار الاولون من اهل الملل الكافره والاخرون منهم جميعا، قال الاخرون المتبعون في الدنيا لقادتهم: ربنا هؤلاء هم الذين اضلونا عن الحق، فاتهم عذابا مضاعفا من النار، قال الله تعالى: لكل ضعف، اي: لكل منكم ومنهم عذاب مضاعف من النار، ولكن لا تدركون ايها الاتباع ما لكل فريق منكم من العذاب والالام."},{"id":"993","s":7,"a":39,"at":"وقالت اولاهم لاخراهم فما كان لكم علينا من فضل فذوقوا العذاب بما كنتم تكسبون","dt":"[39] وقال المتبوعون من الرؤساء وغيرهم لاتباعهم: نحن وانتم متساوون في الغي والضلال، وفي فعل اسباب العذاب فلا فضل لكم علينا، قال الله تعالى لهم جميعا: فذوقوا العذاب اي عذاب جهنم؛ بسبب ما كسبتم من المعاصي."},{"id":"994","s":7,"a":40,"at":"ان الذين كذبوا باياتنا واستكبروا عنها لا تفتح لهم ابواب السماء ولا يدخلون الجنه حتى يلج الجمل في سم الخياط وكذلك نجزي المجرمين","dt":"[40] ان الكفار الذين لم يصدقوا بحججنا واياتنا الداله على وحدانيتنا، ولم يعملوا بشرعنا تكبرا واستعلاء، لا تفتح لاعمالهم في الحياه ولا لارواحهم عند الممات ابواب السماء، ولا يمكن ان يدخل هؤلاء الكفار الجنه الا اذا دخل الجمل في ثقب الابره، وهذا مستحيل. ومثل ذلك الجزاء نجزي الذين كثر اجرامهم، واشتد طغيانهم."},{"id":"995","s":7,"a":41,"at":"لهم من جهنم مهاد ومن فوقهم غواش وكذلك نجزي الظالمين","dt":"[41] هؤلاء الكفار مخلدون في النار، لهم من جهنم فراش من تحتهم، ومن فوقهم اغطيه تغشاهم. وبمثل هذا العقاب الشديد يعاقب الله تعالى الظالمين الذين تجاوزوا حدوده فكفروا به وعصوه."},{"id":"996","s":7,"a":42,"at":"والذين امنوا وعملوا الصالحات لا نكلف نفسا الا وسعها اولئك اصحاب الجنه هم فيها خالدون","dt":"[42] والذين امنوا بالله وعملوا الاعمال الصالحه في حدود طاقاتهم -لا يكلف الله نفسا من الاعمال الا ما تطيق- اولئك اهل الجنه، هم فيها ماكثون ابدا لا يخرجون منها."},{"id":"997","s":7,"a":43,"at":"ونزعنا ما في صدورهم من غل تجري من تحتهم الانهار وقالوا الحمد لله الذي هدانا لهذا وما كنا لنهتدي لولا ان هدانا الله لقد جاءت رسل ربنا بالحق ونودوا ان تلكم الجنه اورثتموها بما كنتم تعملون","dt":"[43] واذهب الله تعالى ما في صدور اهل الجنه من حقد وضغائن، ومن كمال نعيمهم ان الانهار تجري في الجنه من تحت غرفهم ومنازلهم. وقال اهل الجنه حينما دخلوها: الحمد لله الذي وفقنا للعمل الصالح الذي اكسبنا ما نحن فيه من النعيم، وما كنا لنوفق الى سلوك الطريق المستقيم لولا ان هدانا الله سبحانه لسلوك هذا الطريق، ووفقنا للثبات عليه، لقد جاءت رسل ربنا بالحق من الاخبار بوعد اهل طاعته ووعيد اهل معصيته، ونودوا تهنئه لهم واكراما: ان تلكم الجنه اورثكم الله اياها برحمته، وبما قدمتموه من الايمان والعمل الصالح."},{"id":"998","s":7,"a":44,"at":"ونادى اصحاب الجنه اصحاب النار ان قد وجدنا ما وعدنا ربنا حقا فهل وجدتم ما وعد ربكم حقا قالوا نعم فاذن مؤذن بينهم ان لعنه الله على الظالمين","dt":"[44] ونادى اصحاب الجنه -بعد دخولهم فيها- اهل النار قائلين لهم: انا قد وجدنا ما وعدنا ربنا على السنه رسله حقا من اثابه اهل طاعته، فهل وجدتم ما وعدكم ربكم على السنه رسله حقا من عقاب اهل معصيته؟ فاجابهم اهل النار قائلين: نعم قد وجدنا ما وعدنا ربنا حقا. فاذن مؤذن بين اهل الجنه واهل النار: ان لعنه الله على الظالمين الذين تجاوزوا حدود الله، وكفروا بالله ورسله."},{"id":"999","s":7,"a":45,"at":"الذين يصدون عن سبيل الله ويبغونها عوجا وهم بالاخره كافرون","dt":"[45] هؤلاء الكافرون هم الذين كانوا يعرضون عن طريق الله المستقيم، ويمنعون الناس من سلوكه، ويطلبون ان تكون السبيل معوجه حتى لا يتبينها احد، وهم بالاخره -وما فيها- جاحدون."},{"id":"1000","s":7,"a":46,"at":"وبينهما حجاب وعلى الاعراف رجال يعرفون كلا بسيماهم ونادوا اصحاب الجنه ان سلام عليكم لم يدخلوها وهم يطمعون","dt":"[46] وبين اصحاب الجنه واصحاب النار حاجز عظيم يقال له الاعراف، وعلى هذا الحاجز رجال يعرفون اهل الجنه واهل النار بعلاماتهم، كبياض وجوه اهل الجنه، وسواد وجوه اهل النار، وهؤلاء الرجال قوم استوت حسناتهم وسيئاتهم يرجون رحمه الله تعالى. ونادى رجال الاعراف اهل الجنه بالتحيه قائلين لهم: سلام عليكم، واهل الاعراف لم يدخلوا الجنه بعد، وهم يرجون دخولها."},{"id":"1001","s":7,"a":47,"at":"واذا صرفت ابصارهم تلقاء اصحاب النار قالوا ربنا لا تجعلنا مع القوم الظالمين","dt":"[47] واذا حولت ابصار رجال الاعراف جهه اهل النار قالوا: ربنا لا تصيرنا مع القوم الظالمين بشركهم وكفرهم."},{"id":"1002","s":7,"a":48,"at":"ونادى اصحاب الاعراف رجالا يعرفونهم بسيماهم قالوا ما اغنى عنكم جمعكم وما كنتم تستكبرون","dt":"[48] ونادى اهل الاعراف رجالا من قاده الكفار الذين في النار، يعرفونهم بعلامات خاصه تميزهم، قالوا لهم: ما نفعكم ما كنتم تجمعون من الاموال والرجال في الدنيا، وما نفعكم استعلاؤكم عن الايمان بالله وقبول الحق."},{"id":"1003","s":7,"a":49,"at":"اهؤلاء الذين اقسمتم لا ينالهم الله برحمه ادخلوا الجنه لا خوف عليكم ولا انتم تحزنون","dt":"[49] اهؤلاء الضعفاء والفقراء من اهل الجنه، الذين اقسمتم في الدنيا ان الله لا يشملهم يوم القيامه برحمه، ولن يدخلهم الجنه؟ ويقال لاصحاب الاعراف: ادخلوا الجنه فقد غفر لكم، لا خوف عليكم من عذاب الله، ولا انتم تحزنون على ما فاتكم من حظوظ الدنيا."},{"id":"1004","s":7,"a":50,"at":"ونادى اصحاب النار اصحاب الجنه ان افيضوا علينا من الماء او مما رزقكم الله قالوا ان الله حرمهما على الكافرين","dt":"[50] واستغاث اهل النار باهل الجنه طالبين منهم ان يفيضوا عليهم من الماء، او مما رزقهم الله من الطعام، فاجابوهم بان الله تعالى قد حرم الشراب والطعام على الذين جحدوا توحيده، وكذبوا رسله."},{"id":"1005","s":7,"a":51,"at":"الذين اتخذوا دينهم لهوا ولعبا وغرتهم الحياه الدنيا فاليوم ننساهم كما نسوا لقاء يومهم هذا وما كانوا باياتنا يجحدون","dt":"[51] الذين حرمهم الله تعالى من نعيم الاخره هم الذين جعلوا الدين الذي امرهم الله باتباعه لهوا وباطلا ، وخدعتهم الحياه الدنيا وشغلوا بزخارفها عن العمل للاخره، فيوم القيامه ينساهم الله تعالى ويتركهم في العذاب الموجع، كما تركوا العمل للقاء يومهم هذا، ولكونهم بادله الله وبراهينه ينكرون مع علمهم بانها حق."},{"id":"1006","s":7,"a":52,"at":"ولقد جئناهم بكتاب فصلناه على علم هدى ورحمه لقوم يؤمنون","dt":"[52] ولقد جئنا الكفار بقران انزلناه عليك -ايها الرسول- بيناه مشتملا على علم عظيم، هاديا من الضلاله الى الرشد ورحمه لقوم يؤمنون بالله ويعملون بشرعه. وخصهم بالذكر دون غيرهم؛ لانهم هم المنتفعون به."},{"id":"1007","s":7,"a":53,"at":"هل ينظرون الا تاويله يوم ياتي تاويله يقول الذين نسوه من قبل قد جاءت رسل ربنا بالحق فهل لنا من شفعاء فيشفعوا لنا او نرد فنعمل غير الذي كنا نعمل قد خسروا انفسهم وضل عنهم ما كانوا يفترون","dt":"[53] هل ينتظر الكفار الا ما وعدوا به في القران من العقاب الذي يؤول اليه امرهم؟ يوم ياتي ما يؤول اليه الامر من الحساب والثواب والعقاب يوم القيامه يقول الكفار الذين تركوا القران، وكفروا به في الحياه الدنيا: قد تبين لنا الان ان رسل ربنا قد جاؤوا بالحق، ونصحوا لنا، فهل لنا من اصدقاء وشفعاء، فيشفعوا لنا عند ربنا، او هل نعاد الى الدنيا مره اخرى فنعمل فيها بما يرضي الله عنا؟ قد خسروا انفسهم بدخولهم النار وخلودهم فيها، وذهب عنهم ما كانوا يعبدونه من دون الله، ويفترونه في الدنيا مما يعدهم به الشيطان."},{"id":"1008","s":7,"a":54,"at":"ان ربكم الله الذي خلق السموات والارض في سته ايام ثم استوى على العرش يغشي الليل النهار يطلبه حثيثا والشمس والقمر والنجوم مسخرات بامره الا له الخلق والامر تبارك الله رب العالمين","dt":"[54] ان ربكم -ايها الناس- هو الله الذي اوجد السموات والارض من العدم في سته ايام، ثم استوى -سبحانه- على العرش -اي: -علا وارتفع- استواء يليق بجلاله وعظمته، يدخل سبحانه الليل على النهار، فيلبسه اياه حتى يذهب نوره، ويدخل النهار على الليل فيذهب ظلامه، وكل واحد منهما يطلب الاخر سريعا دائما، وهو -سبحانه- الذي خلق الشمس والقمر والنجوم مذللات له يسخرهن -سبحانه- كما يشاء، وهن من ايات الله العظيمه. الا له سبحانه وتعالى الخلق كله وله الامر كله، تعالى الله وتعاظم وتنزه عن كل نقص، رب الخلق اجمعين."},{"id":"1009","s":7,"a":55,"at":"ادعوا ربكم تضرعا وخفيه انه لا يحب المعتدين","dt":"[55] ادعوا -ايها المؤمنون- ربكم متذللين له خفيه وسرا، وليكن الدعاء بخشوع وبعد عن الرياء. ان الله تعالى لا يحب المتجاوزين حدود شرعه، واعظم التجاوز الشرك بالله، كدعاء غير الله من الاموات والاوثان، ونحو ذلك."},{"id":"1010","s":7,"a":56,"at":"ولا تفسدوا في الارض بعد اصلاحها وادعوه خوفا وطمعا ان رحمه الله قريب من المحسنين","dt":"[56] ولا تفسدوا في الارض باي نوع من انواع الفساد، بعد اصلاح الله اياها ببعثه الرسل -عليهم السلام- وعمرانها بطاعه الله، وادعوه -سبحانه- مخلصين له الدعاء؛ خوفا من عقابه ورجاء لثوابه. ان رحمه الله قريب من المحسنين."},{"id":"1011","s":7,"a":57,"at":"وهو الذي يرسل الرياح بشرا بين يدي رحمته حتى اذا اقلت سحابا ثقالا سقناه لبلد ميت فانزلنا به الماء فاخرجنا به من كل الثمرات كذلك نخرج الموتى لعلكم تذكرون","dt":"[57] والله تعالى هو الذي يرسل الرياح الطيبه اللينه، مبشرات بالغيث الذي تثيره باذن الله، فيستبشر الخلق برحمه الله، حتى اذا حملت الريح السحاب المحمل بالمطر ساقه الله بها لاحياء بلد، قد اجدبت ارضه، ويبست اشجاره وزرعه، فانزل الله به المطر، فاخرج به الكلا والاشجار والزروع، فعادت اشجاره محمله بانواع الثمرات. كما نحيي هذا البلد الميت بالمطر نخرج الموتى من قبورهم احياء بعد فنائهم؛ لتتعظوا، فتستدلوا على توحيد الله وقدرته على البعث."},{"id":"1012","s":7,"a":58,"at":"والبلد الطيب يخرج نباته باذن ربه والذي خبث لا يخرج الا نكدا كذلك نصرف الايات لقوم يشكرون","dt":"[58] والارض النقيه اذا نزل عليها المطر تخرج نباتا -باذن الله ومشيئته- طيبا ميسرا، وكذلك المؤمن اذا نزلت عليه ايات الله انتفع بها، واثمرت فيه حياه صالحه، اما الارض السبخه الرديئه فانها لا تخرج النبات الا عسرا رديئا لا نفع فيه، ولا تخرج نباتا طيبا، وكذلك الكافر لا ينتفع بايات الله. مثل ذلك التنويع البديع في البيان ننوع الحجج والبراهين لاثبات الحق لاناس يشكرون نعم الله، ويطيعونه."},{"id":"1013","s":7,"a":59,"at":"لقد ارسلنا نوحا الى قومه فقال ياقوم اعبدوا الله ما لكم من اله غيره اني اخاف عليكم عذاب يوم عظيم","dt":"[59] لقد بعثنا نوحا الى قومه؛ ليدعوهم الى توحيد الله سبحانه واخلاص العباده له، فقال: يا قوم اعبدوا الله وحده، واخضعوا له بالطاعه، ليس لكم من اله يستحق العباده غيره جل وعلا، فاخلصوا له العباده، فان لم تفعلوا وبقيتم على عباده اوثانكم، فانني اخاف ان يحل عليكم عذاب يوم يعظم فيه بلاؤكم، وهو يوم القيامه."},{"id":"1014","s":7,"a":60,"at":"قال الملا من قومه انا لنراك في ضلال مبين","dt":"[60] قال له سادتهم وكبراؤهم: انا لنعتقد -يا نوح- انك في ضلال بين عن طريق الصواب."},{"id":"1015","s":7,"a":61,"at":"قال ياقوم ليس بي ضلاله ولكني رسول من رب العالمين","dt":"[61] قال نوح: يا قوم لست ضالا في مساله من المسائل بوجه من الوجوه، ولكني رسول من رب العالمين ربي وربكم ورب جميع الخلق."},{"id":"1016","s":7,"a":62,"at":"ابلغكم رسالات ربي وانصح لكم واعلم من الله ما لا تعلمون","dt":"[62] ابلغكم ما ارسلت به من ربي، وانصح لكم، محذرا لكم من عذاب الله ومبشرا بثوابه، واعلم من شريعته ما لا تعلمون."},{"id":"1017","s":7,"a":63,"at":"او عجبتم ان جاءكم ذكر من ربكم على رجل منكم لينذركم ولتتقوا ولعلكم ترحمون","dt":"[63] وهل اثار عجبكم ان انزل الله تعالى اليكم ما يذكركم بما فيه الخير لكم، على لسان رجل منكم، تعرفون نسبه وصدقه؛ ليخوفكم باس الله تعالى وعقابه، ولتتقوا سخطه بالايمان به، ورجاء ان تظفروا برحمته وجزيل ثوابه؟"},{"id":"1018","s":7,"a":64,"at":"فكذبوه فانجيناه والذين معه في الفلك واغرقنا الذين كذبوا باياتنا انهم كانوا قوما عمين","dt":"[64] فكذبوا نوحا فانجيناه ومن امن معه في السفينه، واغرقنا الكفار الذين كذبوا بحججنا الواضحه. انهم كانوا عمي القلوب عن رؤيه الحق."},{"id":"1019","s":7,"a":65,"at":"والى عاد اخاهم هودا قال ياقوم اعبدوا الله ما لكم من اله غيره افلا تتقون","dt":"[65] ولقد ارسلنا الى قبيله عاد اخاهم هودا حين عبدوا الاوثان من دون الله، فقال لهم: اعبدوا الله وحده، ليس لكم من اله يستحق العباده غيره جل وعلا، فاخلصوا له العباده، افلا تتقون عذاب الله وسخطه عليكم؟"},{"id":"1020","s":7,"a":66,"at":"قال الملا الذين كفروا من قومه انا لنراك في سفاهه وانا لنظنك من الكاذبين","dt":"[66] قال الكبراء الذين كفروا من قوم هود: انا لنعلم انك بدعوتك ايانا الى ترك عباده الهتنا وعباده الله وحده ناقص العقل، وانا لنعتقد انك من الكاذبين على الله فيما تقول."},{"id":"1021","s":7,"a":67,"at":"قال ياقوم ليس بي سفاهه ولكني رسول من رب العالمين","dt":"[67] قال هود: يا قوم ليس بي نقص في عقلي، ولكني رسول اليكم من رب الخلق اجمعين."},{"id":"1022","s":7,"a":68,"at":"ابلغكم رسالات ربي وانا لكم ناصح امين","dt":"[68] ابلغكم ما ارسلني به ربي اليكم، وانا لكم -فيما دعوتكم اليه من توحيد الله والعمل بشريعته- ناصح، امين على وحي الله تعالى."},{"id":"1023","s":7,"a":69,"at":"او عجبتم ان جاءكم ذكر من ربكم على رجل منكم لينذركم واذكروا اذ جعلكم خلفاء من بعد قوم نوح وزادكم في الخلق بسطه فاذكروا الاء الله لعلكم تفلحون","dt":"[69] وهل اثار عجبكم ان انزل الله تعالى اليكم ما يذكركم بما فيه الخير لكم، على لسان رجل منكم، تعرفون نسبه وصدقه؛ ليخوفكم باس الله وعقابه؟ واذكروا نعمه الله عليكم اذ جعلكم تخلفون في الارض من قبلكم من بعد ما اهلك قوم نوح، وزاد في اجسامكم قوه وضخامه، فاذكروا نعم الله الكثيره عليكم؛ رجاء ان تفوزوا الفوز العظيم في الدنيا والاخره."},{"id":"1024","s":7,"a":70,"at":"قالوا اجئتنا لنعبد الله وحده ونذر ما كان يعبد اباؤنا فاتنا بما تعدنا ان كنت من الصادقين","dt":"[70] قالت عاد لهود عليه السلام: ادعوتنا لعباده الله وحده وهجر عباده الاصنام التي ورثنا عبادتها عن ابائنا؟ فاتنا بالعذاب الذي تخوفنا به ان كنت من اهل الصدق فيما تقول."},{"id":"1025","s":7,"a":71,"at":"قال قد وقع عليكم من ربكم رجس وغضب اتجادلونني في اسماء سميتموها انتم واباؤكم ما نزل الله بها من سلطان فانتظروا اني معكم من المنتظرين","dt":"[71] قال هود لقومه: قد حل بكم عذاب وغضب من ربكم جل وعلا، اتجادلونني في هذه الاصنام التي سميتموها الهه انتم واباؤكم؟ ما نزل الله بها من حجه ولا برهان؛ لانها مخلوقه لا تضر ولا تنفع، وانما المعبود وحده هو الخالق سبحانه، فانتظروا نزول العذاب عليكم فاني منتظر معكم نزوله، وهذا غايه في التهديد والوعيد."},{"id":"1026","s":7,"a":72,"at":"فانجيناه والذين معه برحمه منا وقطعنا دابر الذين كذبوا باياتنا وما كانوا مؤمنين","dt":"[72] فوقع عذاب الله بارسال الريح الشديده عليهم، فانجى الله هودا والذين امنوا معه برحمه عظيمه منه تعالى، واهلك الكفار من قومه جميعا ودمرهم عن اخرهم، وما كانوا مؤمنين؛ لجمعهم بين التكذيب بايات الله وترك العمل الصالح."},{"id":"1027","s":7,"a":73,"at":"والى ثمود اخاهم صالحا قال ياقوم اعبدوا الله ما لكم من اله غيره قد جاءتكم بينه من ربكم هذه ناقه الله لكم ايه فذروها تاكل في ارض الله ولا تمسوها بسوء فياخذكم عذاب اليم","dt":"[73] ولقد ارسلنا الى قبيله ثمود اخاهم صالحا لما عبدوا الاوثان من دون الله تعالى، فقال صالح لهم: يا قوم اعبدوا الله وحده؛ ليس لكم من اله يستحق العباده غيره جل وعلا، فاخلصوا له العباده، قد جئتكم بالبرهان على صدق ما ادعوكم اليه، اذ دعوت الله امامكم، فاخرج لكم من الصخره ناقه عظيمه كما سالتم، فاتركوها تاكل في ارض الله من المراعي، ولا تتعرضوا لها باي اذى، فيصيبكم بسبب ذلك عذاب موجع."},{"id":"1028","s":7,"a":74,"at":"واذكروا اذ جعلكم خلفاء من بعد عاد وبواكم في الارض تتخذون من سهولها قصورا وتنحتون الجبال بيوتا فاذكروا الاء الله ولا تعثوا في الارض مفسدين","dt":"[74] واذكروا نعمه الله عليكم، اذ جعلكم تخلفون في الارض من قبلكم، من بعد قبيله عاد، ومكن لكم في الارض الطيبه تنزلونها، فتبنون في سهولها البيوت العظيمه، وتنحتون من جبالها بيوتا اخرى، فاذكروا نعم الله عليكم، ولا تسعوا في الارض بالافساد."},{"id":"1029","s":7,"a":75,"at":"قال الملا الذين استكبروا من قومه للذين استضعفوا لمن امن منهم اتعلمون ان صالحا مرسل من ربه قالوا انا بما ارسل به مؤمنون","dt":"[75] قال الساده والكبراء من الذين استعلوا -من قوم صالح- للمؤمنين الذين استضعفوهم، واستهانوا بهم: اتعلمون حقيقه ان صالحا قد ارسله الله الينا؟ قال الذين امنوا: انا مصدقون بما ارسله الله به، متبعون لشرعه."},{"id":"1030","s":7,"a":76,"at":"قال الذين استكبروا انا بالذي امنتم به كافرون","dt":"[76] قال الذين استعلوا: انا بالذي صدقتم به واتبعتموه من نبوه صالح جاحدون."},{"id":"1031","s":7,"a":77,"at":"فعقروا الناقه وعتوا عن امر ربهم وقالوا ياصالح ائتنا بما تعدنا ان كنت من المرسلين","dt":"[77] فنحروا الناقه استخفافا منهم بوعيد صالح، واستكبروا عن امتثال امر ربهم، وقالوا على سبيل الاستهزاء واستبعاد العذاب: يا صالح ائتنا بما تتوعدنا به من العذاب، ان كنت من رسل الله."},{"id":"1032","s":7,"a":78,"at":"فاخذتهم الرجفه فاصبحوا في دارهم جاثمين","dt":"[78] فاخذت الذين كفروا الزلزله الشديده التي خلعت قلوبهم، فاصبحوا في بلدهم هالكين، لاصقين بالارض على ركبهم ووجوههم، لم يفلت منهم احد."},{"id":"1033","s":7,"a":79,"at":"فتولى عنهم وقال ياقوم لقد ابلغتكم رساله ربي ونصحت لكم ولكن لا تحبون الناصحين","dt":"[79] فاعرض صالح عليه السلام عن قومه -حين عقروا الناقه وحل بهم الهلاك- وقال لهم: يا قوم لقد ابلغتكم ما امرني ربي بابلاغه من امره ونهيه، وبذ لت لكم وسعي في الترغيب والترهيب والنصح، ولكنكم لا تحبون الناصحين، فرددتم قولهم، واطعتم كل شيطان رجيم."},{"id":"1034","s":7,"a":80,"at":"ولوطا اذ قال لقومه اتاتون الفاحشه ما سبقكم بها من احد من العالمين","dt":"[80] واذكر -ايها الرسول- لوطا عليه السلام حين قال لقومه: اتفعلون الفعله المنكره التي بلغت نهايه القبح؟ ما فعلها من احد قبلكم من المخلوقين."},{"id":"1035","s":7,"a":81,"at":"انكم لتاتون الرجال شهوه من دون النساء بل انتم قوم مسرفون","dt":"[81] انكم لتاتون الذكور في ادبارهم، شهوه منكم لذلك، غير مبالين بقبحها، تاركين الذي احله الله لكم من نسائكم، بل انتم قوم متجاوزون لحدود الله في الاسراف في المعاصي والشهوات. ان اتيان الذكور دون الاناث من الفواحش التي ابتدعها قوم لوط، ولم يسبقهم بها احد من الخلق."},{"id":"1036","s":7,"a":82,"at":"وما كان جواب قومه الا ان قالوا اخرجوهم من قريتكم انهم اناس يتطهرون","dt":"[82] وما كان جواب قوم لوط حين انكر عليهم فعلهم الشنيع الا ان قال بعضهم لبعض: اخرجوا لوطا واهله من بلادكم؛ انه ومن تبعه اناس يتنزهون عن اتيان ادبار الرجال."},{"id":"1037","s":7,"a":83,"at":"فانجيناه واهله الا امراته كانت من الغابرين","dt":"[83] فانجى الله لوطا واهله من العذاب حيث امره بمغادره ذلك البلد، الا امراته، فانها كانت من الهالكين الباقين في عذاب الله."},{"id":"1038","s":7,"a":84,"at":"وامطرنا عليهم مطرا فانظر كيف كان عاقبه المجرمين","dt":"[84] وعذب الله الكفار من قوم لوط بان انزل عليهم مطرا من الحجاره، وقلب بلادهم، فجعل عاليها سافلها، فانظر -ايها الرسول- كيف صارت عاقبه الذين اجترؤوا على معاصي الله وكذبوا رسله."},{"id":"1039","s":7,"a":85,"at":"والى مدين اخاهم شعيبا قال ياقوم اعبدوا الله ما لكم من اله غيره قد جاءتكم بينه من ربكم فاوفوا الكيل والميزان ولا تبخسوا الناس اشياءهم ولا تفسدوا في الارض بعد اصلاحها ذلكم خير لكم ان كنتم مؤمنين","dt":"[85] ولقد ارسلنا الى قبيله «مدين» اخاهم شعيبا عليه السلام، فقال لهم: يا قوم اعبدوا الله وحده لا شريك له؛ ليس لكم من اله يستحق العباده غيره جل وعلا، فاخلصوا له العباده، قد جاءكم برهان من ربكم على صدق ما ادعوكم اليه، فادوا للناس حقوقهم بايفاء الكيل والميزان، ولا تنقصوهم حقوقهم فتظلموهم، ولا تفسدوا في الارض -بالكفر والظلم- بعد اصلاحها بشرائع الانبياء السابقين عليهم السلام. ذلك الذي دعوتكم اليه خير لكم في دنياكم واخراكم، ان كنتم مصدقي فيما دعوتكم اليه، عاملين بشرع الله."},{"id":"1040","s":7,"a":86,"at":"ولا تقعدوا بكل صراط توعدون وتصدون عن سبيل الله من امن به وتبغونها عوجا واذكروا اذ كنتم قليلا فكثركم وانظروا كيف كان عاقبه المفسدين","dt":"[86] ولا تقعدوا بكل طريق تتوعدون الناس بالقتل، ان لم يعطوكم اموالهم، وتصدون عن سبيل الله القويم من صدق به عز وجل، وعمل صالحا، وتبغون سبيل الله ان تكون معوجه، وتميلونها اتباعا لاهوائكم، وتنفرون الناس عن اتباعها. واذكروا نعمه الله تعالى عليكم اذ كان عددكم قليلا فكثركم، فاصبحتم اقوياء عزيزين، وانظروا كيف كان عاقبه المفسدين في الارض، وما حل بهم من الهلاك والدمار؟"},{"id":"1041","s":7,"a":87,"at":"وان كان طائفه منكم امنوا بالذي ارسلت به وطائفه لم يؤمنوا فاصبروا حتى يحكم الله بيننا وهو خير الحاكمين","dt":"[87] وان كان جماعه منكم صدقوا بالذي ارسلني الله به، وجماعه لم يصدقوا بذلك، فانتظروا ايها المكذبون قضاء الله الفاصل بيننا وبينكم حين يحل عليكم عذابه الذي انذرتكم به. والله -جل وعلا- هو خير الحاكمين بين عباده."},{"id":"1042","s":7,"a":88,"at":"قال الملا الذين استكبروا من قومه لنخرجنك ياشعيب والذين امنوا معك من قريتنا او لتعودن في ملتنا قال او لو كنا كارهين","dt":"[88] قال الساده والكبراء من قوم شعيب الذين تكبروا عن الايمان بالله واتباع رسوله شعيب عليه السلام: لنخرجنك يا شعيب ومن معك من المؤمنين من ديارنا، الا اذا صرتم الى ديننا، قال شعيب -منكرا ومتعجبا من قولهم-: انتابعكم على دينكم وملتكم الباطله، ولو كنا كارهين لها لعلمنا ببطلانها؟"},{"id":"1043","s":7,"a":89,"at":"قد افترينا على الله كذبا ان عدنا في ملتكم بعد اذ نجانا الله منها وما يكون لنا ان نعود فيها الا ان يشاء الله ربنا وسع ربنا كل شيء علما على الله توكلنا ربنا افتح بيننا وبين قومنا بالحق وانت خير الفاتحين","dt":"[89] وقال شعيب لقومه مستدركا: قد اختلقنا على الله الكذب ان عدنا الى دينكم بعد ان انقذنا الله منه، وليس لنا ان نتحول الى غير دين ربنا الا ان يشاء الله ربنا، وقد وسع ربنا كل شيء علما، فيعلم ما يصلح للعباد، على الله وحده اعتمادنا هدايه ونصره، ربنا احكم بيننا وبين قومنا بالحق، وانت خير الحاكمين."},{"id":"1044","s":7,"a":90,"at":"وقال الملا الذين كفروا من قومه لئن اتبعتم شعيبا انكم اذا لخاسرون","dt":"[90] وقال الساده والكبراء المكذبون الرافضون لدعوه التوحيد امعانا في العتو والتمرد، محذرين من اتباع شعيب: لئن اتبعتم شعيبا انكم اذا لهالكون."},{"id":"1045","s":7,"a":91,"at":"فاخذتهم الرجفه فاصبحوا في دارهم جاثمين","dt":"[91] فاخذت قوم شعيب الزلزله الشديده، فاصبحوا في دارهم صرعى ميتين."},{"id":"1046","s":7,"a":92,"at":"الذين كذبوا شعيبا كان لم يغنوا فيها الذين كذبوا شعيبا كانوا هم الخاسرين","dt":"[92] الذين كذبوا شعيبا كانهم لم يقيموا في ديارهم، ولم يتمتعوا فيها، حيث استؤصلوا، فلم يبق لهم اثر، واصابهم الخسران والهلاك في الدنيا والاخره."},{"id":"1047","s":7,"a":93,"at":"فتولى عنهم وقال ياقوم لقد ابلغتكم رسالات ربي ونصحت لكم فكيف اسى على قوم كافرين","dt":"[93] فاعرض شعيب عنهم حينما ايقن بحلول العذاب بهم، وقال: يا قوم لقد ابلغتكم رسالات ربي، ونصحت لكم بالدخول في دين الله والاقلاع عما انتم عليه، فلم تسمعوا ولم تطيعوا، فكيف احزن على قوم جحدوا وحدانيه الله وكذبوا رسله؟"},{"id":"1048","s":7,"a":94,"at":"وما ارسلنا في قريه من نبي الا اخذنا اهلها بالباساء والضراء لعلهم يضرعون","dt":"[94] وما ارسلنا في قريه من نبي يدعوهم الى عباده الله، وينهاهم عما هم فيه من الشرك، فكذبه قومه، الا ابتليناهم بالباساء والضراء، فاصبناهم في ابدانهم بالامراض والاسقام، وفي اموالهم بالفقر والحاجه؛ رجاء ان يستكينوا، وينيبوا الى الله، ويرجعوا الى الحق."},{"id":"1049","s":7,"a":95,"at":"ثم بدلنا مكان السيئه الحسنه حتى عفوا وقالوا قد مس اباءنا الضراء والسراء فاخذناهم بغته وهم لا يشعرون","dt":"[95] ثم بدلنا الحاله الطيبه الاولى مكان الحاله السيئه، فاصبحوا في عافيه في ابدانهم، وسعه ورخاء في اموالهم؛ امهالا لهم، ولعلهم يشكرون، فلم يفد معهم كل ذلك، ولم يعتبروا ولم ينتهوا عما هم فيه، وقالوا: هذه عاده الدهر في اهله، يوم خير ويوم شر، وهو ما جرى لابائنا من قبل، فاخذناهم بالعذاب فجاه وهم امنون، لا يخطر لهم الهلاك على بال."},{"id":"1050","s":7,"a":96,"at":"ولو ان اهل القرى امنوا واتقوا لفتحنا عليهم بركات من السماء والارض ولكن كذبوا فاخذناهم بما كانوا يكسبون","dt":"[96] ولو ان اهل القرى صدقوا رسلهم واتبعوهم واجتنبوا ما نهاهم الله عنه، لفتح الله لهم ابواب الخير من كل وجه، ولكنهم كذبوا، فعاقبهم الله بالعذاب المهلك بسبب كفرهم ومعاصيهم."},{"id":"1051","s":7,"a":97,"at":"افامن اهل القرى ان ياتيهم باسنا بياتا وهم نائمون","dt":"[97] ايظن اهل القرى انهم في منجاه ومامن من عذاب الله، ان ياتيهم ليلا وهم نائمون؟"},{"id":"1052","s":7,"a":98,"at":"او امن اهل القرى ان ياتيهم باسنا ضحى وهم يلعبون","dt":"[98] او امن اهل القرى ان ياتيهم عذاب الله وقت الضحى، وهم غافلون متشاغلون بامور دنياهم؟ وخص الله هذين الوقتين بالذكر؛ لان الانسان يكون اغفل ما يكون فيهما، فمجيء العذاب فيهما افظع واشد."},{"id":"1053","s":7,"a":99,"at":"افامنوا مكر الله فلا يامن مكر الله الا القوم الخاسرون","dt":"[99] افامن اهل القرى المكذبه مكر الله وامهاله لهم؛ استدراجا لهم بما انعم عليهم في دنياهم عقوبه لمكرهم؟ فلا يامن مكر الله الا القوم الهالكون."},{"id":"1054","s":7,"a":100,"at":"او لم يهد للذين يرثون الارض من بعد اهلها ان لو نشاء اصبناهم بذنوبهم ونطبع على قلوبهم فهم لا يسمعون","dt":"[100] اولم يتبين للذين سكنوا الارض من بعد اهلاك اهلها السابقين بسبب معاصيهم، فساروا سيرتهم، ان لو نشاء اصبناهم بالعذاب بسبب ذنوبهم كما فعلنا باسلافهم، ونختم على قلوبهم، فلا يدخلها الحق، ولا يسمعون موعظه ولا تذكيرا؟"},{"id":"1055","s":7,"a":101,"at":"تلك القرى نقص عليك من انبائها ولقد جاءتهم رسلهم بالبينات فما كانوا ليؤمنوا بما كذبوا من قبل كذلك يطبع الله على قلوب الكافرين","dt":"[101] تلك القرى التي تقدم ذكرها، وهي قرى قوم نوح وهود وصالح ولوط وشعيب، نقص عليك -ايها الرسول- من اخبارها، وما كان من امر رسل الله التي ارسلت اليهم، ما يحصل به عبره للمعتبرين وازدجار للظالمين. ولقد جاءت اهل القرى رسلنا بالحجج البينات على صدقهم، فما كانوا ليؤمنوا بما جاءتهم به الرسل؛ بسبب طغيانهم وتكذيبهم بالحق، ومثل ختم الله على قلوب هؤلاء الكافرين المذكورين يختم الله على قلوب الكافرين بمحمد -صلى الله عليه وسلم-."},{"id":"1056","s":7,"a":102,"at":"وما وجدنا لاكثرهم من عهد وان وجدنا اكثرهم لفاسقين","dt":"[102] وما وجدنا لاكثر الامم الماضيه من امانه ولا وفاء بالعهد، وما وجدنا اكثرهم الا فسقه عن طاعه الله وامتثال امره."},{"id":"1057","s":7,"a":103,"at":"ثم بعثنا من بعدهم موسى باياتنا الى فرعون وملئه فظلموا بها فانظر كيف كان عاقبه المفسدين","dt":"[103] ثم بعثنا من بعد الرسل المتقدم ذكرهم موسى بن عمران بمعجزاتنا البينه الى فرعون وقومه، فجحدوا وكفروا بها ظلما منهم وعنادا، فانظر -ايها الرسول- متبصرا كيف فعلنا بهم واغرقناهم عن اخرهم بمراى من موسى وقومه؟ وتلك نهايه المفسدين."},{"id":"1058","s":7,"a":104,"at":"وقال موسى يافرعون اني رسول من رب العالمين","dt":"[104] وقال موسى لفرعون محاورا مبلغا: اني رسول من الله خالق الخلق اجمعين، ومدبر احوالهم ومالهم."},{"id":"1059","s":7,"a":105,"at":"حقيق على ان لا اقول على الله الا الحق قد جئتكم ببينه من ربكم فارسل معي بني اسرائيل","dt":"[105] جدير بان لا اقول على الله الا الحق، وحري بي ان التزمه، قد جئتكم ببرهان وحجه باهره من ربكم على صدق ما اذكره لكم، فاطلق -يا فرعون- معي بني اسرائيل من اسرك وقهرك، وخل سبيلهم لعباده الله."},{"id":"1060","s":7,"a":106,"at":"قال ان كنت جئت بايه فات بها ان كنت من الصادقين","dt":"[106] قال فرعون لموسى: ان كنت جئت بايه حسب زعمك فاتني بها، واحضرها عندي؛ لتصح دعواك ويثبت صدقك، ان كنت صادقا فيما ادعيت انك رسول رب العالمين."},{"id":"1061","s":7,"a":107,"at":"فالقى عصاه فاذا هي ثعبان مبين","dt":"[107] فالقى موسى عصاه، فتحولت حيه عظيمه ظاهره للعيان."},{"id":"1062","s":7,"a":108,"at":"ونزع يده فاذا هي بيضاء للناظرين","dt":"[108] وجذب يده من فتحه قميصه المفتوحه الى الصدر او من تحت ابطه، فاذا هي بيضاء كاللبن من غير برص ايه لفرعون، فاذا ردها عادت الى لونها الاول، كسائر بدنه."},{"id":"1063","s":7,"a":109,"at":"قال الملا من قوم فرعون ان هذا لساحر عليم","dt":"[109] قال الاشراف من قوم فرعون: ان موسى لساحر ياخذ باعين الناس بخداعه اياهم، حتى يخيل اليهم ان العصا حيه، والشيء بخلاف ما هو عليه، وهو واسع العلم بالسحر ماهر به."},{"id":"1064","s":7,"a":110,"at":"يريد ان يخرجكم من ارضكم فماذا تامرون","dt":"[110] يريد ان يخرجكم جميعا من ارضكم، قال فرعون: فبماذا تشيرون علي ايها الاشراف في امر موسى؟"},{"id":"1065","s":7,"a":111,"at":"قالوا ارجه واخاه وارسل في المدائن حاشرين","dt":"[111] قال من حضر مناظره موسى من ساده قوم فرعون وكبرائهم: اخر موسى واخاه هارون، وابعث في مدائن «مصر» واقاليمها الشرط."},{"id":"1066","s":7,"a":112,"at":"ياتوك بكل ساحر عليم","dt":"[112] ليجمعوا لك كل ساحر واسع العلم بالسحر."},{"id":"1067","s":7,"a":113,"at":"وجاء السحره فرعون قالوا ان لنا لاجرا ان كنا نحن الغالبين","dt":"[113] وجاء السحره فرعون قالوا: ائن لنا لجائزه ومالا ان غلبنا موسى؟"},{"id":"1068","s":7,"a":114,"at":"قال نعم وانكم لمن المقربين","dt":"[114] قال فرعون: نعم لكم الاجر والقرب مني ان غلبتموه."},{"id":"1069","s":7,"a":115,"at":"قالوا ياموسى اما ان تلقي واما ان نكون نحن الملقين","dt":"[115] قال سحره فرعون لموسى على سبيل التكبر وعدم المبالاه: يا موسى اختر ان تلقي عصاك اولا، او نلقي نحن اولا."},{"id":"1070","s":7,"a":116,"at":"قال القوا فلما القوا سحروا اعين الناس واسترهبوهم وجاءو بسحر عظيم","dt":"[116] قال موسى للسحره: القوا انتم، فلما القوا الحبال والعصي سحروا اعين الناس، فخيل الى الابصار ان ما فعلوه حقيقه، ولم يكن الا مجرد صنعه وخيال، وارهبوا الناس ارهابا شديدا، وجاؤوا بسحر قوي كثير."},{"id":"1071","s":7,"a":117,"at":"واوحينا الى موسى ان الق عصاك فاذا هي تلقف ما يافكون","dt":"[117] واوحى الله الى عبده ورسوله موسى عليه السلام في ذلك الموقف العظيم، الذي فرق الله فيه بين الحق والباطل، يامره بان يلقي ما في يمينه وهي عصاه، فالقاها فاذا هي تبلع ما يلقونه، ويوهمون الناس انه حق وهو باطل."},{"id":"1072","s":7,"a":118,"at":"فوقع الحق وبطل ما كانوا يعملون","dt":"[118] فظهر الحق واستبان لمن شهده وحضره في امر موسى عليه السلام، وانه رسول الله يدعو الى الحق، وبطل الكذب الذي كانوا يعملونه."},{"id":"1073","s":7,"a":119,"at":"فغلبوا هنالك وانقلبوا صاغرين","dt":"[119] فغلب جميع السحره في مكان اجتماعهم، وانصرف فرعون وقومه اذلاء مقهورين مغلوبين."},{"id":"1074","s":7,"a":120,"at":"والقي السحره ساجدين","dt":"[120] وخر السحره سجدا على وجوههم لله رب العالمين، لما عاينوا من عظيم قدره الله."},{"id":"1075","s":7,"a":121,"at":"قالوا امنا برب العالمين","dt":"[121] قالوا: امنا برب العالمين."},{"id":"1076","s":7,"a":122,"at":"رب موسى وهارون","dt":"[122] وهو رب موسى وهارون، وهو الذي يجب ان تصرف له العباده وحده دون من سواه."},{"id":"1077","s":7,"a":123,"at":"قال فرعون امنتم به قبل ان اذن لكم ان هذا لمكر مكرتموه في المدينه لتخرجوا منها اهلها فسوف تعلمون","dt":"[123] قال فرعون للسحره: امنتم بالله قبل ان اذن لكم بالايمان به؟ ان ايمانكم بالله وتصديقكم لموسى واقراركم بنبوته لحيله احتلتموها انتم وموسى؛ لتخرجوا اهل مدينتكم منها ، وتكونوا المستاثرين بخيراتها، فسوف تعلمون -ايها السحره- ما يحل بكم من العذاب والنكال."},{"id":"1078","s":7,"a":124,"at":"لاقطعن ايديكم وارجلكم من خلاف ثم لاصلبنكم اجمعين","dt":"[124] لاقطعن ايديكم وارجلكم -ايها السحره- من خلاف: بقطع اليد اليمنى والرجل اليسرى، او اليد اليسرى والرجل اليمنى، ثم لاعلقنكم جميعا على جذوع النخل؛ تنكيلا بكم وارهابا للناس."},{"id":"1079","s":7,"a":125,"at":"قالوا انا الى ربنا منقلبون","dt":"[125] قال السحره لفرعون: قد تحققنا انا الى الله راجعون، وان عذابه اشد من عذابك، فلنصبرن اليوم على عذابك؛ لننجو من عذاب الله يوم القيامه."},{"id":"1080","s":7,"a":126,"at":"وما تنقم منا الا ان امنا بايات ربنا لما جاءتنا ربنا افرغ علينا صبرا وتوفنا مسلمين","dt":"[126] ولست تعيب منا وتنكر -يا فرعون- الا ايماننا وتصديقنا بحجج ربنا وادلته التي جاء بها موسى، ولا تقدر على مثلها انت ولا احد اخر سوى الله الذي له ملك السموات والارض، ربنا افض علينا صبرا عظيما وثباتا عليه، وتوفنا منقادين لامرك متبعين رسولك."},{"id":"1081","s":7,"a":127,"at":"وقال الملا من قوم فرعون اتذر موسى وقومه ليفسدوا في الارض ويذرك والهتك قال سنقتل ابناءهم ونستحيي نساءهم وانا فوقهم قاهرون","dt":"[127] وقال الساده والكبراء من قوم فرعون لفرعون: اتدع موسى وقومه من بني اسرائيل ليفسدوا الناس في ارض «مصر» بتغيير دينهم بعباده الله وحده لا شريك له، وترك عبادتك وعباده الهتك؟ قال فرعون: سنقتل ابناء بني اسرائيل ونستبقي نساءهم احياء للخدمه، وانا عالون عليهم بقهر الملك والسلطان."},{"id":"1082","s":7,"a":128,"at":"قال موسى لقومه استعينوا بالله واصبروا ان الارض لله يورثها من يشاء من عباده والعاقبه للمتقين","dt":"[128] قال موسى لقومه -من بني اسرائيل-: استعينوا بالله على فرعون وقومه، واصبروا على ما نالكم من فرعون من المكاره في انفسكم وابنائكم. ان الارض كلها لله يورثها من يشاء من عباده، والعاقبه المحموده لمن اتقى الله ففعل اوامره واجتنب نواهيه."},{"id":"1083","s":7,"a":129,"at":"قالوا اوذينا من قبل ان تاتينا ومن بعد ما جئتنا قال عسى ربكم ان يهلك عدوكم ويستخلفكم في الارض فينظر كيف تعملون","dt":"[129] قال قوم موسى -من بني اسرائيل- لنبيهم موسى: ابتلينا واوذينا بذبح ابنائنا واستحياء نسائنا على يد فرعون وقومه، من قبل ان تاتينا، ومن بعد ما جئتنا، قال موسى لهم: لعل ربكم ان يهلك عدوكم فرعون وقومه، ويستخلفكم في ارضهم بعد هلاكهم، فينظر كيف تعملون، هل تشكرون او تكفرون؟"},{"id":"1084","s":7,"a":130,"at":"ولقد اخذنا ال فرعون بالسنين ونقص من الثمرات لعلهم يذكرون","dt":"[130] ولقد ابتلينا فرعون وقومه بالقحط والجدب، ونقص ثمارهم وغلاتهم؛ ليتذكروا، وينزجروا عن ضلالاتهم، ويفزعوا الى ربهم بالتوبه."},{"id":"1085","s":7,"a":131,"at":"فاذا جاءتهم الحسنه قالوا لنا هذه وان تصبهم سيئه يطيروا بموسى ومن معه الا انما طائرهم عند الله ولكن اكثرهم لا يعلمون","dt":"[131] فاذا جاء فرعون وقومه الخصب والرزق قالوا: هذا لنا بما نستحقه، وان يصبهم جدب وقحط يتشاءموا، ويقولوا: هذا بسبب موسى ومن معه. الا ان ما يصيبهم من الجدب والقحط انما هو بقضاء الله وقدره، وبسبب ذنوبهم وكفرهم، ولكن اكثر قوم فرعون لا يعلمون ذلك؛ لانغمارهم في الجهل والضلال."},{"id":"1086","s":7,"a":132,"at":"وقالوا مهما تاتنا به من ايه لتسحرنا بها فما نحن لك بمؤمنين","dt":"[132] وقال قوم فرعون لموسى: اي ايه تاتنا بها، ودلاله وحجه اقمتها لتصرفنا عما نحن عليه من دين فرعون، فما نحن لك بمصدقين."},{"id":"1087","s":7,"a":133,"at":"فارسلنا عليهم الطوفان والجراد والقمل والضفادع والدم ايات مفصلات فاستكبروا وكانوا قوما مجرمين","dt":"[133] فارسلنا عليهم سيلا جارفا اغرق الزروع والثمار، وارسلنا الجراد، فاكل زروعهم وثمارهم وابوابهم وسقوفهم وثيابهم، وارسلنا القمل الذي يفسد الثمار ويقضي على الحيوان والنبات، وارسلنا الضفادع فملات انيتهم واطعمتهم ومضاجعهم، وارسلنا ايضا الدم فصارت انهارهم وابارهم دما، ولم يجدوا ماء صالحا للشرب، هذه ايات من ايات الله لا يقدر عليها غيره، مفرقات بعضها عن بعض، ومع كل هذا ترفع قوم فرعون، فاستكبروا عن الايمان بالله، وكانوا قوما يعملون بما ينهى الله عنه من المعاصي والفسق عتوا وتمردا."},{"id":"1088","s":7,"a":134,"at":"ولما وقع عليهم الرجز قالوا ياموسى ادع لنا ربك بما عهد عندك لئن كشفت عنا الرجز لنؤمنن لك ولنرسلن معك بني اسرائيل","dt":"[134] ولما نزل العذاب على فرعون وقومه فزعوا الى موسى وقالوا: يا موسى ادع لنا ربك بما اوحى به اليك من رفع العذاب بالتوبه، لئن رفعت عنا العذاب الذي نحن فيه لنصدقن بما جئت به، ولنتبعن ما دعوت اليه، ولنطلقن معك بني اسرائيل، فلا نمنعهم من ان يذهبوا حيث شاؤوا."},{"id":"1089","s":7,"a":135,"at":"فلما كشفنا عنهم الرجز الى اجل هم بالغوه اذا هم ينكثون","dt":"[135] فلما رفع الله عنهم العذاب الذى انزله بهم الى اجل هم بالغوه لا محاله فيعذبون فيه، لا ينفعهم ما تقدم لهم من الامهال وكشف العذاب الى حلوله، اذا هم ينقضون عهودهم التي عاهدوا عليها ربهم وموسى، ويقيمون على كفرهم وضلالهم."},{"id":"1090","s":7,"a":136,"at":"فانتقمنا منهم فاغرقناهم في اليم بانهم كذبوا باياتنا وكانوا عنها غافلين","dt":"[136] فانتقمنا منهم حين جاء الاجل المحدد لاهلاكهم، وذلك باحلال نقمتنا عليهم، وهي اغراقهم في البحر؛ بسبب تكذيبهم بالمعجزات التي ظهرت على يد موسى، وكانوا عن هذه المعجزات غافلين، وتلك الغفله هي سبب التكذيب."},{"id":"1091","s":7,"a":137,"at":"واورثنا القوم الذين كانوا يستضعفون مشارق الارض ومغاربها التي باركنا فيها وتمت كلمه ربك الحسنى على بني اسرائيل بما صبروا ودمرنا ما كان يصنع فرعون وقومه وما كانوا يعرشون","dt":"[137] واورثنا بني اسرائيل الذين كانوا يستذلون للخدمه، مشارق الارض ومغاربها (وهي بلاد «الشام») التي باركنا فيها، باخراج الزروع والثمار والانهار، وتمت كلمه ربك -ايها الرسول- الحسنى على بني اسرائيل بالتمكين لهم في الارض؛ بسبب صبرهم على اذى فرعون وقومه، ودمرنا ما كان يصنع فرعون وقومه من العمارات والمزارع، وما كانوا يبنون من الابنيه والقصور وغير ذلك."},{"id":"1092","s":7,"a":138,"at":"وجاوزنا ببني اسرائيل البحر فاتوا على قوم يعكفون على اصنام لهم قالوا ياموسى اجعل لنا الها كما لهم الهه قال انكم قوم تجهلون","dt":"[138] وقطعنا ببني اسرائيل البحر، فمروا على قوم يقيمون ويواظبون على عباده اصنام لهم، قال بنو اسرائيل: اجعل لنا يا موسى صنما نعبده ونتخذه الها، كما لهؤلاء القوم اصنام يعبدونها، قال موسى لهم: انكم ايها القوم تجهلون عظمه الله، ولا تعلمون ان العباده لا تنبغي الا لله الواحد القهار."},{"id":"1093","s":7,"a":139,"at":"ان هؤلاء متبر ما هم فيه وباطل ما كانوا يعملون","dt":"[139] ان هؤلاء المقيمين على هذه الاصنام مهلك ما هم فيه من الشرك، ومدمر وباطل ما كانوا يعملون من عبادتهم لتلك الاصنام، التي لا تدفع عنهم عذاب الله اذا نزل بهم."},{"id":"1094","s":7,"a":140,"at":"قال اغير الله ابغيكم الها وهو فضلكم على العالمين","dt":"[140] قال موسى لقومه: اغير الله اطلب لكم معبودا تعبدونه من دونه، والله هو الذي خلقكم، وفضلكم على عالمي زمانكم بكثره الانبياء فيكم، واهلاك عدوكم، وما خصكم به من الايات؟"},{"id":"1095","s":7,"a":141,"at":"واذ انجيناكم من ال فرعون يسومونكم سوء العذاب يقتلون ابناءكم ويستحيون نساءكم وفي ذلكم بلاء من ربكم عظيم","dt":"[141] واذكروا -يا بني اسرائيل- نعمنا عليكم اذ انقذناكم من اسر فرعون واله، وما كنتم فيه من الهوان والذله من تذبيح ابنائكم واستبقاء نسائكم للخدمه والامتهان، وفي حملكم على اقبح العذاب واسوئه، ثم انجائكم، اختبار من الله لكم ونعمه عظيمه."},{"id":"1096","s":7,"a":142,"at":"وواعدنا موسى ثلاثين ليله واتممناها بعشر فتم ميقات ربه اربعين ليله وقال موسى لاخيه هارون اخلفني في قومي واصلح ولا تتبع سبيل المفسدين","dt":"[142] وواعد الله سبحانه وتعالى موسى لمناجاه ربه ثلاثين ليله، ثم زاده في الاجل بعد ذلك عشر ليال، فتم ما وقته الله لموسى لتكليمه اربعين ليله. وقال موسى لاخيه هارون -حين اراد المضي لمناجاه ربه-: كن خليفتي في قومي حتى ارجع، واحملهم على طاعه الله وعبادته، ولا تسلك طريق الذين يفسدون في الارض."},{"id":"1097","s":7,"a":143,"at":"ولما جاء موسى لميقاتنا وكلمه ربه قال رب ارني انظر اليك قال لن تراني ولكن انظر الى الجبل فان استقر مكانه فسوف تراني فلما تجلى ربه للجبل جعله دكا وخر موسى صعقا فلما افاق قال سبحانك تبت اليك وانا اول المؤمنين","dt":"[143] ولما جاء موسى في الوقت المحدد وهو تمام اربعين ليله، وكلمه ربه بما كلمه من وحيه وامره ونهيه، طمع في رؤيه الله فطلب النظر اليه، قال الله له: لن تراني، اي: لن تقدر على رؤيتي في الدنيا، ولكن انظر الى الجبل، فان استقر مكانه اذا تجليت له فسوف تراني، فلما تجلى ربه للجبل جعله دكا مستويا بالارض، وسقط موسى مغشيا عليه، فلما افاق من غشيته قال: تنزيها لك يا رب عما لا يليق بجلالك، اني تبت اليك من مسالتي اياك الرؤيه في هذه الحياه الدنيا، وانا اول المؤمنين بك من قومي."},{"id":"1098","s":7,"a":144,"at":"قال ياموسى اني اصطفيتك على الناس برسالاتي وبكلامي فخذ ما اتيتك وكن من الشاكرين","dt":"[144] قال الله يا موسى: اني اخترتك على الناس برسالاتي الى خلقي الذين ارسلتك اليهم وبكلامي اياك من غير واسطه، فخذ ما اعطيتك من امري ونهيي، وتمسك به، واعمل به، وكن من الشاكرين لله تعالى على ما اتاك من رسالته، وخصك بكلامه."},{"id":"1099","s":7,"a":145,"at":"وكتبنا له في الالواح من كل شيء موعظه وتفصيلا لكل شيء فخذها بقوه وامر قومك ياخذوا باحسنها ساريكم دار الفاسقين","dt":"[145] وكتبنا لموسى في التوراه من كل ما يحتاج اليه في دينه من الاحكام، موعظه للازدجار والاعتبار، وتفصيلا لتكاليف الحلال والحرام والامر والنهي والقصص والعقائد والاخبار والمغيبات، قال الله له: فخذها بقوه، اي: خذ التوراه بجد واجتهاد، وامر قومك يعملوا بما شرع الله فيها؛ فان من اشرك منهم ومن غيرهم فاني ساريه في الاخره دار الفاسقين، وهي نار الله التي اعدها لاعدائه الخارجين عن طاعته."},{"id":"1100","s":7,"a":146,"at":"ساصرف عن اياتي الذين يتكبرون في الارض بغير الحق وان يروا كل ايه لا يؤمنوا بها وان يروا سبيل الرشد لا يتخذوه سبيلا وان يروا سبيل الغي يتخذوه سبيلا ذلك بانهم كذبوا باياتنا وكانوا عنها غافلين","dt":"[146] ساصرف عن فهم الحجج والادله الداله على عظمتي وشريعتي واحكامي قلوب المتكبرين عن طاعتي، والمتكبرين على الناس بغير الحق، فلا يتبعون نبيا ولا يصغون اليه لتكبرهم، وان ير هؤلاء المتكبرون عن الايمان كل ايه لا يؤمنوا بها؛ لاعراضهم ومحادتهم لله ورسوله، وان يروا طريق الصلاح لا يتخذوه طريقا، وان يروا طريق الضلال، اي الكفر يتخذوه طريقا ودينا؛ وذلك بسبب تكذيبهم بايات الله وغفلتهم عن النظر فيها والتفكر في دلالاتها."},{"id":"1101","s":7,"a":147,"at":"والذين كذبوا باياتنا ولقاء الاخره حبطت اعمالهم هل يجزون الا ما كانوا يعملون","dt":"[147] والذين كذبوا بايات الله وحججه وبلقاء الله في الاخره حبطت اعمالهم؛ بسبب فقد شرطها، وهو الايمان بالله والتصديق بجزائه، ما يجزون في الاخره الا جزاء ما كانوا يعملونه في الدنيا من الكفر والمعاصي، وهو الخلود في النار."},{"id":"1102","s":7,"a":148,"at":"واتخذ قوم موسى من بعده من حليهم عجلا جسدا له خوار الم يروا انه لا يكلمهم ولا يهديهم سبيلا اتخذوه وكانوا ظالمين","dt":"[148] واتخذ قوم موسى من بعد ما فارقهم ماضيا لمناجاه ربه، معبودا من ذهبهم عجلا جسدا بلا روح، له صوت يشبه صوت البقر، الم يعلموا انه لا يكلمهم، ولا يرشدهم الى خير؟ اقدموا على ما اقدموا عليه من هذا الامر الشنيع، وكانوا ظالمين لانفسهم واضعين الشيء في غير موضعه."},{"id":"1103","s":7,"a":149,"at":"ولما سقط في ايديهم وراوا انهم قد ضلوا قالوا لئن لم يرحمنا ربنا ويغفر لنا لنكونن من الخاسرين","dt":"[149] ولما ندم الذين عبدوا العجل من دون الله عند رجوع موسى اليهم، وراوا انهم قد ضلوا عن قصد السبيل، وذهبوا عن دين الله، اخذوا في الاقرار بالعبوديه والاستغفار، فقالوا: لئن لم يرحمنا ربنا بقبول توبتنا، ويستر بها ذنوبنا، لنكونن من الهالكين الذين ذهبت اعمالهم."},{"id":"1104","s":7,"a":150,"at":"ولما رجع موسى الى قومه غضبان اسفا قال بئسما خلفتموني من بعدي اعجلتم امر ربكم والقى الالواح واخذ براس اخيه يجره اليه قال ابن ام ان القوم استضعفوني وكادوا يقتلونني فلا تشمت بي الاعداء ولا تجعلني مع القوم الظالمين","dt":"[150] ولما رجع موسى الى قومه من بني اسرائيل غضبان حزينا؛ لان الله قد اخبره انه قد فتن قومه، وان السامري قد اضلهم، قال موسى: بئس الخلافه التي خلفتموني من بعدي، اعجلتم امر ربكم؟ اي: استعجلتم مجيئي اليكم وهو مقدر من الله تعالى؟ والقى موسى الواح التوراه غضبا على قومه الذين عبدوا العجل، وغضبا على اخيه هارون، وامسك براس اخيه يجره اليه، قال هارون مستعطفا: يا بن امي: ان القوم استذلوني وعدوني ضعيفا وقاربوا ان يقتلوني، فلا تسر الاعداء بما تفعل بي، ولا تجعلني في غضبك مع القوم الذين خالفوا امرك وعبدوا العجل."},{"id":"1105","s":7,"a":151,"at":"قال رب اغفر لي ولاخي وادخلنا في رحمتك وانت ارحم الراحمين","dt":"[151] قال موسى لما تبين له عذر اخيه، وعلم انه لم يفرط فيما كان عليه من امر الله: رب اغفر لي غضبي، واغفر لاخي ما سبق بينه وبين بني اسرائيل، وادخلنا في رحمتك الواسعه، فانك ارحم بنا من كل راحم."},{"id":"1106","s":7,"a":152,"at":"ان الذين اتخذوا العجل سينالهم غضب من ربهم وذله في الحياه الدنيا وكذلك نجزي المفترين","dt":"[152] ان الذين اتخذوا العجل الها سينالهم غضب شديد من ربهم وهوان في الحياه الدنيا؛ بسبب كفرهم بربهم، وكما فعلنا بهؤلاء نفعل بالمفترين المبتدعين في دين الله، فكل صاحب بدعه ذليل."},{"id":"1107","s":7,"a":153,"at":"والذين عملوا السيئات ثم تابوا من بعدها وامنوا ان ربك من بعدها لغفور رحيم","dt":"[153] والذين عملوا السيئات من الكفر والمعاصي، ثم رجعوا من بعد فعلها الى الايمان والعمل الصالح، ان ربك من بعد التوبه النصوح لغفور لاعمالهم غير فاضحهم بها، رحيم بهم وبكل من كان مثلهم من التائبين."},{"id":"1108","s":7,"a":154,"at":"ولما سكت عن موسى الغضب اخذ الالواح وفي نسختها هدى ورحمه للذين هم لربهم يرهبون","dt":"[154] ولما سكن عن موسى غضبه اخذ الالواح بعد ان القاها على الارض، وفيها بيان للحق ورحمه للذين يخافون الله، ويخشون عقابه."},{"id":"1109","s":7,"a":155,"at":"واختار موسى قومه سبعين رجلا لميقاتنا فلما اخذتهم الرجفه قال رب لو شئت اهلكتهم من قبل واياي اتهلكنا بما فعل السفهاء منا ان هي الا فتنتك تضل بها من تشاء وتهدي من تشاء انت ولينا فاغفر لنا وارحمنا وانت خير الغافرين","dt":"[155] واختار موسى من قومه سبعين رجلا من خيارهم، وخرج بهم الى طور «سيناء» للوقت والاجل الذي واعده الله ان يلقاه فيه بهم؛ للتوبه مما كان من سفهاء بني اسرائيل من عباده العجل، فلما اتوا ذلك المكان قالوا: لن نؤمن لك –يا موسى- حتى نرى الله جهره فانك قد كلمته فارناه، فاخذتهم الزلزله الشديده فماتوا، فقام موسى يتضرع الى الله ويقول: رب ماذا اقول لبني اسرائيل اذا اتيتهم، وقد اهلكت خيارهم؟ لو شئت اهلكتهم جميعا من قبل هذا الحال وانا معهم، فان ذلك اخف علي، اتهلكنا بما فعله سفهاء الاحلام منا؟ ما هذه الفعله التي فعلها قومي من عبادتهم العجل الا ابتلاء واختبار، تضل بها من تشاء من خلقك، وتهدي بها من تشاء هدايته، انت ولينا وناصرنا، فاغفر ذنوبنا، وارحمنا برحمتك، وانت خير من صفح عن جرم، وستر عن ذنب."},{"id":"1110","s":7,"a":156,"at":"واكتب لنا في هذه الدنيا حسنه وفي الاخره انا هدنا اليك قال عذابي اصيب به من اشاء ورحمتي وسعت كل شيء فساكتبها للذين يتقون ويؤتون الزكاه والذين هم باياتنا يؤمنون","dt":"[156] واجعلنا ممن كتبت له الصالحات من الاعمال في الدنيا وفي الاخره، انا رجعنا تائبين اليك، قال الله تعالى لموسى: عذابي اصيب به من اشاء من خلقي، كما اصبت هؤلاء الذين اصبتهم من قومك، ورحمتي وسعت خلقي كلهم، فساكتبها للذين يخافون الله، ويخشون عقابه، فيؤدون فرائضه، ويجتنبون معاصيه، والذين هم بدلائل التوحيد وبراهينه يصدقون."},{"id":"1111","s":7,"a":157,"at":"الذين يتبعون الرسول النبي الامي الذي يجدونه مكتوبا عندهم في التوراه والانجيل يامرهم بالمعروف وينهاهم عن المنكر ويحل لهم الطيبات ويحرم عليهم الخبائث ويضع عنهم اصرهم والاغلال التي كانت عليهم فالذين امنوا به وعزروه ونصروه واتبعوا النور الذي انزل معه اولئك هم المفلحون","dt":"[157] هذه الرحمه ساكتبها للذين يخافون الله ويجتنبون معاصيه، ويتبعون الرسول النبي الامي الذي لا يقرا ولا يكتب، وهو محمد -صلى الله عليه وسلم-، الذي يجدون صفته وامره مكتوبين عندهم في التوراه والانجيل، يامرهم بالتوحيد والطاعه وكل ما عرف حسنه، وينهاهم عن الشرك والمعصيه وكل ما عرف قبحه، ويحل لهم الطيبات من المطاعم والمشارب والمناكح، ويحرم عليهم الخبائث منها كلحم الخنزير، وما كانوا يستحلونه من المطاعم والمشارب التي حرمها الله، ويذهب عنهم ما كلفوه من الامور الشاقه كقطع موضع النجاسه من الثوب، واحراق الغنائم، والقصاص حتما من القاتل عمدا كان القتل ام خطا، فالذين صدقوا بالنبي الامي محمد -صلى الله عليه وسلم- واقروا بنبوته، ووقروه وعظموه ونصروه، واتبعوا القران المنزل عليه، وعملوا بسنته، اولئك هم الفائزون بما وعد الله به عباده المؤمنين."},{"id":"1112","s":7,"a":158,"at":"قل ياايها الناس اني رسول الله اليكم جميعا الذي له ملك السموات والارض لا اله الا هو يحيي ويميت فامنوا بالله ورسوله النبي الامي الذي يؤمن بالله وكلماته واتبعوه لعلكم تهتدون","dt":"[158] قل -ايها الرسول- للناس كلهم: اني رسول الله اليكم جميعا لا الى بعضكم دون بعض، الذي له ملك السموات والارض وما فيهما، لا ينبغي ان تكون الالوهيه والعباده الا له جل ثناؤه، القادر على ايجاد الخلق وافنائه وبعثه، فصدقوا بالله واقروا بوحدانيته، وصدقوا برسوله محمد -صلى الله عليه وسلم- النبي الامي الذي يؤمن بالله وما انزل اليه من ربه وما انزل على النبيين من قبله، واتبعوا هذا الرسول، والتزموا العمل بما امركم به من طاعه الله؛ رجاء ان توفقوا الى الطريق المستقيم."},{"id":"1113","s":7,"a":159,"at":"ومن قوم موسى امه يهدون بالحق وبه يعدلون","dt":"[159] ومن بني اسرائيل من قوم موسى جماعه يستقيمون على الحق، يهدون الناس به، ويعدلون به في الحكم في قضاياهم."},{"id":"1114","s":7,"a":160,"at":"وقطعناهم اثنتي عشره اسباطا امما واوحينا الى موسى اذ استسقاه قومه ان اضرب بعصاك الحجر فانبجست منه اثنتا عشره عينا قد علم كل اناس مشربهم وظللنا عليهم الغمام وانزلنا عليهم المن والسلوى كلوا من طيبات ما رزقناكم وما ظلمونا ولكن كانوا انفسهم يظلمون","dt":"[160] وفرقنا قوم موسى من بني اسرائيل اثنتي عشره قبيله بعدد الاسباط -وهم ابناء يعقوب- كل قبيله معروفه من جهه نقيبها. واوحينا الى موسى اذ طلب منه قومه السقيا حين عطشوا في التيه: ان اضرب بعصاك الحجر، فضربه فانفجرت منه اثنتا عشره عينا من الماء، قد علمت كل قبيله من القبائل الاثنتي عشره مشربهم، لا تدخل قبيله على غيرها في شربها، وظللنا عليهم السحاب، وانزلنا عليهم المن -وهو شيء يشبه الصمغ، طعمه كالعسل- والسلوى، وهو طائر يشبه السمانى، وقلنا لهم: كلوا من طيبات ما رزقناكم، فكرهوا ذلك وملوه من طول المداومه عليه، وقالوا: لن نصبر على طعام واحد، وطلبوا استبدال الذي هو ادنى بالذي هو خير. وما ظلمونا حين لم يشكروا لله، ولم يقوموا بما اوجب الله عليهم، ولكن كانوا انفسهم يظلمون؛ اذ فوتوا عليها كل خير، وعرضوها للشر والنقمه."},{"id":"1115","s":7,"a":161,"at":"واذ قيل لهم اسكنوا هذه القريه وكلوا منها حيث شئتم وقولوا حطه وادخلوا الباب سجدا نغفر لكم خطيئاتكم سنزيد المحسنين","dt":"[161] واذكر -ايها الرسول- عصيان بني اسرائيل لربهم سبحانه وتعالى ولنبيهم موسى عليه السلام، وتبديلهم القول الذي امروا ان يقولوه حين قال الله لهم: اسكنوا قريه «بيت المقدس»، وكلوا من ثمارها وحبوبها ونباتها اين شئتم ومتى شئتم، وقولوا: حط عنا ذنوبنا، وادخلوا الباب خاضعين لله، نغفر لكم خطاياكم، فلا نؤاخذكم عليها، وسنزيد المحسنين من خيري الدنيا والاخره."},{"id":"1116","s":7,"a":162,"at":"فبدل الذين ظلموا منهم قولا غير الذي قيل لهم فارسلنا عليهم رجزا من السماء بما كانوا يظلمون","dt":"[162] فغير الذين كفروا بالله منهم ما امرهم الله به من القول، ودخلوا الباب يزحفون على استاههم، وقالوا: حبه في شعره، فارسلنا عليهم عذابا من السماء، اهلكناهم به؛ بسبب ظلمهم وعصيانهم."},{"id":"1117","s":7,"a":163,"at":"واسالهم عن القريه التي كانت حاضره البحر اذ يعدون في السبت اذ تاتيهم حيتانهم يوم سبتهم شرعا ويوم لا يسبتون لا تاتيهم كذلك نبلوهم بما كانوا يفسقون","dt":"[163] واسال -ايها الرسول- هؤلاء اليهود عن خبر اهل القريه التي كانت بقرب البحر ، اذ يعتدي اهلها في يوم السبت على حرمات الله، حيث امرهم ان يعظموا يوم السبت ولا يصيدوا فيه سمكا، فابتلاهم الله وامتحنهم؛ فكانت حيتانهم تاتيهم يوم السبت كثيره ظاهره على وجه البحر قريبه من الشاطئ، واذا ذهب يوم السبت تذهب الحيتان في البحر، ولا يرون منها شيئا، فكانوا يحتالون على حبسها في يوم السبت في حفائر، ويصطادونها بعده. وكما وصفنا لكم من الاختبار والابتلاء، باظهار السمك على ظهر الماء في اليوم المحرم عليهم صيده فيه، واخفائه عليهم في اليوم المحلل لهم فيه صيده، كذلك نختبرهم بسبب فسقهم عن طاعه الله وخروجهم عنها."},{"id":"1118","s":7,"a":164,"at":"واذ قالت امه منهم لم تعظون قوما الله مهلكهم او معذبهم عذابا شديدا قالوا معذره الى ربكم ولعلهم يتقون","dt":"[164] واذكر -ايها الرسول- اذ قالت جماعه منهم لجماعه اخرى كانت تعظ المعتدين في يوم السبت، وتنهاهم عن معصيه الله فيه: لم تعظون قوما الله مهلكهم في الدنيا بمعصيتهم اياه او معذبهم عذابا شديدا في الاخره؟ قال الذين كانوا ينهونهم عن معصيه الله: نعظهم وننهاهم لنعذر فيهم، ونؤدي فرض الله علينا في الامر بالمعروف والنهي عن المنكر، ورجاء ان يتقوا الله، فيخافوه، ويتوبوا من معصيتهم ربهم وتعديهم على ما حرم عليهم."},{"id":"1119","s":7,"a":165,"at":"فلما نسوا ما ذكروا به انجينا الذين ينهون عن السوء واخذنا الذين ظلموا بعذاب بئيس بما كانوا يفسقون","dt":"[165] فلما تركت الطائفه التي اعتدت في يوم السبت ما ذكرت به، واستمرت على غيها واعتدائها فيه، ولم تستجب لما وعظتها به الطائفه الواعظه، انجى الله الذين ينهون عن معصيته، واخذ الذين اعتدوا في يوم السبت بعذاب اليم شديد؛ بسبب مخالفتهم امر الله وخروجهم عن طاعته."},{"id":"1120","s":7,"a":166,"at":"فلما عتوا عن ما نهوا عنه قلنا لهم كونوا قرده خاسئين","dt":"[166] فلما تمردت تلك الطائفه، وتجاوزت ما نهاها الله عنه من عدم الصيد في يوم السبت، قال لهم الله: كونوا قرده خاسئين مبعدين من كل خير، فكانوا كذلك."},{"id":"1121","s":7,"a":167,"at":"واذ تاذن ربك ليبعثن عليهم الى يوم القيامه من يسومهم سوء العذاب ان ربك لسريع العقاب وانه لغفور رحيم","dt":"[167] واذكر -ايها الرسول- اذ اعلم ربك اعلاما صريحا ليبعثن على اليهود من يذيقهم سوء العذاب والاذلال الى يوم القيامه. ان ربك -ايها الرسول- لسريع العقاب لمن استحقه بسبب كفره ومعصيته، وانه لغفور عن ذنوب التائبين، رحيم بهم."},{"id":"1122","s":7,"a":168,"at":"وقطعناهم في الارض امما منهم الصالحون ومنهم دون ذلك وبلوناهم بالحسنات والسيئات لعلهم يرجعون","dt":"[168] وفرقنا بني اسرائيل في الارض جماعات، منهم القائمون بحقوق الله وحقوق عباده، ومنهم المقصرون الظالمون لانفسهم، واختبرنا هؤلاء بالرخاء في العيش والسعه في الرزق، واختبرناهم ايضا بالشده في العيش والمصائب والرزايا؛ رجاء ان يرجعوا الى طاعه ربهم ويتوبوا من معاصيه."},{"id":"1123","s":7,"a":169,"at":"فخلف من بعدهم خلف ورثوا الكتاب ياخذون عرض هذا الادنى ويقولون سيغفر لنا وان ياتهم عرض مثله ياخذوه الم يؤخذ عليهم ميثاق الكتاب ان لا يقولوا على الله الا الحق ودرسوا ما فيه والدار الاخره خير للذين يتقون افلا تعقلون","dt":"[169] فجاء من بعد هؤلاء الذين وصفناهم بدل سوء اخذوا الكتاب من اسلافهم، فقرؤوه وعلموه، وخالفوا حكمه، ياخذون ما يعرض لهم من متاع الدنيا من دنيء المكاسب كالرشوه وغيرها؛ وذلك لشده حرصهم ونهمهم، ويقولون مع ذلك: ان الله سيغفر لنا ذنوبنا تمنيا على الله الاباطيل، وان يات هؤلاء اليهود متاع زائل من انواع الحرام ياخذوه ويستحلوه، مصرين على ذنوبهم وتناولهم الحرام، الم يؤخذ على هؤلاء العهود باقامه التوراه والعمل بما فيها، والا يقولوا على الله الا الحق والا يكذبوا عليه، وعلموا ما في الكتاب فضيعوه، وتركوا العمل به، وخالفوا عهد الله اليهم في ذلك؟ والدار الاخره خير للذين يتقون الله، فيمتثلون اوامره، ويجتنبون نواهيه، افلا يعقل هؤلاء الذين ياخذون دنيء المكاسب ان ما عند الله خير وابقى للمتقين؟"},{"id":"1124","s":7,"a":170,"at":"والذين يمسكون بالكتاب واقاموا الصلاه انا لا نضيع اجر المصلحين","dt":"[170] والذين يتمسكون بالكتاب، ويعملون بما فيه من العقائد والاحكام، ويحافظون على الصلاه بحدودها، ولا يضيعون اوقاتها، فان الله يثيبهم على اعمالهم الصالحه، ولا يضيعها."},{"id":"1125","s":7,"a":171,"at":"واذ نتقنا الجبل فوقهم كانه ظله وظنوا انه واقع بهم خذوا ما اتيناكم بقوه واذكروا ما فيه لعلكم تتقون","dt":"[171] واذكر -ايها الرسول- اذ رفعنا الجبل فوق بني اسرائيل كانه سحابه تظلهم، وايقنوا انه واقع بهم ان لم يقبلوا احكام التوراه، وقلنا لهم: خذوا ما اتيناكم بقوه، اي اعملوا بما اعطيناكم باجتهاد منكم، واذكروا ما في كتابنا من العهود والمواثيق التي اخذناها عليكم بالعمل بما فيه؛ كي تتقوا ربكم فتنجوا من عقابه."},{"id":"1126","s":7,"a":172,"at":"واذ اخذ ربك من بني ادم من ظهورهم ذريتهم واشهدهم على انفسهم الست بربكم قالوا بلى شهدنا ان تقولوا يوم القيامه انا كنا عن هذا غافلين","dt":"[172] واذكر -ايها الرسول- اذ استخرج ربك اولاد ادم من اصلاب ابائهم، وقررهم بتوحيده بما اودعه في فطرهم من انه ربهم وخالقهم ومليكهم، فاقروا له بذلك؛ خشيه ان ينكروا يوم القيامه، فلا يقروا بشيء منه، ويزعموا ان حجه الله ما قامت عليهم، ولا عندهم علم بها، بل كانوا عنها غافلين."},{"id":"1127","s":7,"a":173,"at":"او تقولوا انما اشرك اباؤنا من قبل وكنا ذريه من بعدهم افتهلكنا بما فعل المبطلون","dt":"[173] او لئلا تقولوا: انما اشرك اباؤنا من قبلنا ونقضوا العهد، فاقتدينا بهم من بعدهم، افتعذبنا بما فعل الذين ابطلوا اعمالهم بجعلهم مع الله شريكا في العباده؟"},{"id":"1128","s":7,"a":174,"at":"وكذلك نفصل الايات ولعلهم يرجعون","dt":"[174] وكما فصلنا الايات، وبينا فيها ما فعلناه بالامم السابقه، كذلك نفصل الايات ونبينها لقومك ايها الرسول؛ رجاء ان يرجعوا عن شركهم، وينيبوا الى ربهم."},{"id":"1129","s":7,"a":175,"at":"واتل عليهم نبا الذي اتيناه اياتنا فانسلخ منها فاتبعه الشيطان فكان من الغاوين","dt":"[175] واقصص -ايها الرسول- على امتك خبر رجل من بني اسرائيل اعطيناه حججنا وادلتنا، فتعلمها، ثم كفر بها، ونبذها وراء ظهره، فاستحوذ عليه الشيطان، فصار من الضالين الهالكين؛ بسبب مخالفته امر ربه وطاعته الشيطان."},{"id":"1130","s":7,"a":176,"at":"ولو شئنا لرفعناه بها ولكنه اخلد الى الارض واتبع هواه فمثله كمثل الكلب ان تحمل عليه يلهث او تتركه يلهث ذلك مثل القوم الذين كذبوا باياتنا فاقصص القصص لعلهم يتفكرون","dt":"[176] ولو شئنا ان نرفع قدره بما اتيناه من الايات وان نوفقه للعمل بها لفعلنا، ولكنه ركن الى الدنيا واتبع هواه، واثر لذاته وشهواته على الاخره، وامتنع عن طاعه الله وخالف امره. فمثل هذا الرجل مثل الكلب، ان تطرده او تتركه يخرج لسانه في الحالين لاهثا، فكذلك الذي انسلخ من ايات الله يظل على كفره ان اجتهدت في دعوتك له او اهملته، هذا الوصف -ايها الرسول- وصف هؤلاء القوم الذين كانوا ضالين قبل ان تاتيهم بالهدى والرساله، فاقصص -ايها الرسول- اخبار الامم الماضيه، ففي اخبارك بذلك اعظم معجزه؛ لعل قومك يتدبرون فيما جئتهم به فيؤمنوا لك."},{"id":"1131","s":7,"a":177,"at":"ساء مثلا القوم الذين كذبوا باياتنا وانفسهم كانوا يظلمون","dt":"[177] قبح مثلا مثل القوم الذين كذبوا بحجج الله وادلته، فجحدوها، وانفسهم كانوا يظلمونها؛ بسبب تكذيبهم بهذه الحجج والادله."},{"id":"1132","s":7,"a":178,"at":"من يهد الله فهو المهتدي ومن يضلل فاولئك هم الخاسرون","dt":"[178] من يوفقه الله للايمان به وطاعته فهو الموفق، ومن يخذله فلم يوفقه فهو الخاسر الهالك، فالهدايه والاضلال من الله وحده."},{"id":"1133","s":7,"a":179,"at":"ولقد ذرانا لجهنم كثيرا من الجن والانس لهم قلوب لا يفقهون بها ولهم اعين لا يبصرون بها ولهم اذان لا يسمعون بها اولئك كالانعام بل هم اضل اولئك هم الغافلون","dt":"[179] ولقد خلقنا للنار -التي يعذب الله فيها من يستحق العذاب في الاخره- كثيرا من الجن والانس، لهم قلوب لا يعقلون بها، فلا يرجون ثوابا ولا يخافون عقابا، ولهم اعين لا ينظرون بها الى ايات الله وادلته، ولهم اذان لا يسمعون بها ايات كتاب الله فيتفكروا فيها، هؤلاء كالبهائم التي لا تفقه ما يقال لها، ولا تفهم ما تبصره، ولا تعقل بقلوبها الخير والشر فتميز بينهما، بل هم اضل منها؛ لان البهائم تبصر منافعها ومضارها وتتبع راعيها، وهم بخلاف ذلك، اولئك هم الغافلون عن الايمان بالله وطاعته."},{"id":"1134","s":7,"a":180,"at":"ولله الاسماء الحسنى فادعوه بها وذروا الذين يلحدون في اسمائه سيجزون ما كانوا يعملون","dt":"[180] ولله سبحانه وتعالى الاسماء الحسنى، الداله على كمال عظمته، وكل اسمائه حسنى، فاطلبوا منه باسمائه ما تريدون، واتركوا الذين يغيرون في اسمائه بالزياده او النقصان او التحريف، كان يسمى بها من لا يستحقها، كتسميه المشركين بها الهتهم، او ان يجعل لها معنى لم يرده الله ولا رسوله، فسوف يجزون جزاء اعمالهم السيئه التي كانوا يعملونها في الدنيا من الكفر بالله، والالحاد في اسمائه وتكذيب رسوله."},{"id":"1135","s":7,"a":181,"at":"وممن خلقنا امه يهدون بالحق وبه يعدلون","dt":"[181] ومن الذين خلقنا جماعه فاضله يهتدون بالحق ويدعون اليه، وبه يقضون وينصفون الناس، وهم ائمه الهدى ممن انعم الله عليهم بالايمان والعمل الصالح."},{"id":"1136","s":7,"a":182,"at":"والذين كذبوا باياتنا سنستدرجهم من حيث لا يعلمون","dt":"[182] والذين كذبوا باياتنا، فجحدوها، ولم يتذكروا بها، سنفتح لهم ابواب الرزق ووجوه المعاش في الدنيا؛ استدراجا لهم حتى يغتروا بما هم فيه ويعتقدوا انهم على شيء، ثم نعاقبهم على غره من حيث لا يعلمون. وهذه عقوبه من الله على التكذيب بحجج الله واياته."},{"id":"1137","s":7,"a":183,"at":"واملي لهم ان كيدي متين","dt":"[183] وامهل هؤلاء الذين كذبوا باياتنا حتى يظنوا انهم لا يعاقبون، فيزدادوا كفرا وطغيانا، وبذلك يتضاعف لهم العذاب. ان كيدي متين، اي: قوي شديد لا يدفع بقوه ولا بحيله."},{"id":"1138","s":7,"a":184,"at":"او لم يتفكروا ما بصاحبهم من جنه ان هو الا نذير مبين","dt":"[184] او لم يتفكر هؤلاء الذين كذبوا باياتنا فيتدبروا بعقولهم، ويعلموا انه ليس بمحمد جنون؟ ما هو الا نذير لهم من عقاب الله على كفرهم به ان لم يؤمنوا، ناصح مبين."},{"id":"1139","s":7,"a":185,"at":"او لم ينظروا في ملكوت السموات والارض وما خلق الله من شيء وان عسى ان يكون قد اقترب اجلهم فباي حديث بعده يؤمنون","dt":"[185] او لم ينظر هؤلاء المكذبون بايات الله في ملك الله العظيم وسلطانه القاهر في السموات والارض، وما خلق الله -جل ثناؤه- من شيء فيهما، فيتدبروا ذلك ويعتبروا به، وينظروا في اجالهم التي عسى ان تكون قربت فيهلكوا على كفرهم، ويصيروا الى عذاب الله واليم عقابه؟ فباي تخويف وتحذير بعد تحذير القران يصدقون ويعملون؟"},{"id":"1140","s":7,"a":186,"at":"من يضلل الله فلا هادي له ويذرهم في طغيانهم يعمهون","dt":"[186] من يضلله الله عن طريق الرشاد فلا هادي له، ويتركهم في كفرهم يتحيرون ويترددون."},{"id":"1141","s":7,"a":187,"at":"يسالونك عن الساعه ايان مرساها قل انما علمها عند ربي لا يجليها لوقتها الا هو ثقلت في السموات والارض لا تاتيكم الا بغته يسالونك كانك حفي عنها قل انما علمها عند الله ولكن اكثر الناس لا يعلمون","dt":"[187] يسالك -ايها الرسول- كفار «مكه» عن الساعه متى قيامها؟ قل لهم: علم قيامها عند الله، لا يظهرها الا هو، ثقل علمها، وخفي على اهل السموات والارض، فلا يعلم وقت قيامها ملك مقرب ولا نبي مرسل، لا تجيء الساعه الا فجاه، يسالك هؤلاء القوم عنها كانك حريص على العلم بها، مستقص بالسؤال عنها، قل لهم: انما علمها عند الله الذي يعلم غيب السموات والارض، ولكن اكثر الناس لا يعلمون ان ذلك لا يعلمه الا الله."},{"id":"1142","s":7,"a":188,"at":"قل لا املك لنفسي نفعا ولا ضرا الا ما شاء الله ولو كنت اعلم الغيب لاستكثرت من الخير وما مسني السوء ان انا الا نذير وبشير لقوم يؤمنون","dt":"[188] قل -ايها الرسول-: لا اقدر على جلب خير لنفسي ولا دفع شر يحل بها الا ما شاء الله، ولو كنت اعلم الغيب لفعلت الاسباب التي اعلم انها تكثر لي المصالح والمنافع، ولاتقيت ما يكون من الشر قبل ان يقع، ما انا الا رسول الله ارسلني اليكم، اخوف من عقابه، وابشر بثوابه قوما يصدقون باني رسول الله، ويعملون بشرعه."},{"id":"1143","s":7,"a":189,"at":"هو الذي خلقكم من نفس واحده وجعل منها زوجها ليسكن اليها فلما تغشاها حملت حملا خفيفا فمرت به فلما اثقلت دعوا الله ربهما لئن اتيتنا صالحا لنكونن من الشاكرين","dt":"[189] هو الذي خلقكم -ايها الناس- من نفس واحده، وهي ادم عليه السلام وخلق منها زوجها، وهي حواء؛ ليانس بها ويطمئن، فلما جامعها -والمراد جنس الزوجين من ذريه ادم- حملت ماء خفيفا، فقامت به وقعدت واتمت الحمل، فلما قربت ولادتها واثقلت دعا الزوجان ربهما: لئن اعطيتنا بشرا سويا صالحا لنكونن ممن يشكرك على ما وهبت لنا من الولد الصالح."},{"id":"1144","s":7,"a":190,"at":"فلما اتاهما صالحا جعلا له شركاء فيما اتاهما فتعالى الله عما يشركون","dt":"[190] فلما رزق الله الزوجين ولدا صالحا، جعلا لله شركاء في ذلك الولد الذي انفرد الله بخلقه فعبداه لغير الله، فتعالى الله وتنزه عن كل شرك."},{"id":"1145","s":7,"a":191,"at":"ايشركون ما لا يخلق شيئا وهم يخلقون","dt":"[191] ايشرك هؤلاء المشركون في عباده الله مخلوقاته، وهي لا تقدر على خلق شيء، بل هي مخلوقه؟"},{"id":"1146","s":7,"a":192,"at":"ولا يستطيعون لهم نصرا ولا انفسهم ينصرون","dt":"[192] ولا تستطيع ان تنصر عابديها او تدفع عن نفسها سوءا، فاذا كانت لا تخلق شيئا، بل هي مخلوقه، ولا تستطيع ان تدفع المكروه عمن يعبدها، ولا عن نفسها، فكيف تتخذ مع الله الهه؟ ان هذا الا اظلم الظلم واسفه السفه."},{"id":"1147","s":7,"a":193,"at":"وان تدعوهم الى الهدى لا يتبعوكم سواء عليكم ادعوتموهم ام انتم صامتون","dt":"[193] وان تدعوا -ايها المشركون- هذه الاصنام التي عبدتموها من دون الله الى الهدى، لا تسمع دعاءكم ولا تتبعكم، يستوي دعاؤكم لها وسكوتكم عنها؛ لانها لا تسمع ولا تبصر ولا تهدي ولا تهدى."},{"id":"1148","s":7,"a":194,"at":"ان الذين تدعون من دون الله عباد امثالكم فادعوهم فليستجيبوا لكم ان كنتم صادقين","dt":"[194] ان الذين تعبدون من غير الله -ايها المشركون- هم مملوكون لربهم كما انكم مملوكون لربكم، فان كنتم كما تزعمون صادقين في انها تستحق من العباده شيئا فادعوهم فليستجيبوا لكم، فان استجابوا لكم وحصلوا مطلوبكم، والا تبين انكم كاذبون مفترون على الله اعظم الفريه."},{"id":"1149","s":7,"a":195,"at":"الهم ارجل يمشون بها ام لهم ايد يبطشون بها ام لهم اعين يبصرون بها ام لهم اذان يسمعون بها قل ادعوا شركاءكم ثم كيدون فلا تنظرون","dt":"[195] الهذه الالهه والاصنام ارجل يسعون بها معكم في حوائجكم؟ ام لهم ايد يدفعون بها عنكم وينصرونكم على من يريد بكم شرا ومكروها؟ ام لهم اعين ينظرون بها فيعرفونكم ما عاينوا وابصروا مما يغيب عنكم فلا ترونه؟ ام لهم اذان يسمعون بها فيخبرونكم بما لم تسمعوه؟ فاذا كانت الهتكم التي تعبدونها ليس فيها شيء من هذه الالات، فما وجه عبادتكم اياها، وهي خاليه من هذه الاشياء التي بها يتوصل الى جلب النفع او دفع الضر؟ قل -ايها الرسول- لهؤلاء المشركين من عبده الاوثان: ادعوا الهتكم الذين جعلتموهم لله شركاء في العباده، ثم اجتمعوا على ايقاع السوء والمكروه بي، فلا تؤخروني وعجلوا بذلك، فاني لا ابالي بالهتكم؛ لاعتمادي على حفظ الله وحده."},{"id":"1150","s":7,"a":196,"at":"ان وليي الله الذي نزل الكتاب وهو يتولى الصالحين","dt":"[196] ان وليي الله، الذي يتولى حفظي ونصري، هو الذي نزل علي القران بالحق، وهو يتولى الصالحين من عباده، وينصرهم على اعدائهم ولا يخذلهم."},{"id":"1151","s":7,"a":197,"at":"والذين تدعون من دونه لا يستطيعون نصركم ولا انفسهم ينصرون","dt":"[197] والذين تدعون -انتم ايها المشركون- من غير الله من الالهه لا يستطيعون نصركم، ولا يقدرون على نصره انفسهم."},{"id":"1152","s":7,"a":198,"at":"وان تدعوهم الى الهدى لا يسمعوا وتراهم ينظرون اليك وهم لا يبصرون","dt":"[198] وان تدعوا -ايها المشركون- الهتكم الى الاستقامه والسداد لا يسمعوا دعاءكم، وترى -ايها الرسول- الهه هؤلاء المشركين من عبده الاوثان يقابلونك كالناظر اليك وهم لا يبصرون؛ لانهم لا ابصار لهم ولا بصائر."},{"id":"1153","s":7,"a":199,"at":"خذ العفو وامر بالعرف واعرض عن الجاهلين","dt":"[199] اقبل -ايها النبي انت وامتك- الفضل من اخلاق الناس واعمالهم، ولا تطلب منهم ما يشق عليهم حتى لا ينفروا، وامر بكل قول حسن وفعل جميل، واعرض عن منازعه السفهاء ومساواه الجهله الاغبياء."},{"id":"1154","s":7,"a":200,"at":"واما ينزغنك من الشيطان نزغ فاستعذ بالله انه سميع عليم","dt":"[200] واما يصيبنك -ايها النبي- من الشيطان غضب او تحس منه بوسوسه وتثبيط عن الخير او حث على الشر، فالجا الى الله مستعيذا به، انه سميع لكل قول، عليم بكل فعل."},{"id":"1155","s":7,"a":201,"at":"ان الذين اتقوا اذا مسهم طائف من الشيطان تذكروا فاذا هم مبصرون","dt":"[201] ان الذين اتقوا الله من خلقه، فخافوا عقابه باداء فرائضه واجتناب نواهيه، اذا اصابهم عارض من وسوسه الشيطان تذكروا ما اوجب الله عليهم من طاعته، والتوبه اليه، فاذا هم منتهون عن معصيه الله على بصيره، اخذون بامر الله، عاصون للشيطان."},{"id":"1156","s":7,"a":202,"at":"واخوانهم يمدونهم في الغي ثم لا يقصرون","dt":"[202] واخوان الشياطين، وهم الفجار من ضلال الانس تمدهم الشياطين من الجن في الضلاله والغوايه، ولا تدخر شياطين الجن وسعا في مدهم شياطين الانس في الغي، ولا تدخر شياطين الانس وسعا في عمل ما توحي به شياطين الجن."},{"id":"1157","s":7,"a":203,"at":"واذا لم تاتهم بايه قالوا لولا اجتبيتها قل انما اتبع ما يوحى الي من ربي هذا بصائر من ربكم وهدى ورحمه لقوم يؤمنون","dt":"[203] واذا لم تجئ -ايها الرسول- هؤلاء المشركين بايه داله على صدقك قالوا: هلا احدثتها واختلقتها من عند نفسك، قل لهم -ايها الرسول-: ان هذا ليس لي، ولا يجوز لي فعله؛ لان الله انما امرني باتباع ما يوحى الي من عنده، وهو هذا القران الذي اتلوه عليكم حججا وبراهين من ربكم، وبيانا يهدي المؤمنين الى الطريق المستقيم، ورحمه يرحم الله بها عباده المؤمنين."},{"id":"1158","s":7,"a":204,"at":"واذا قرئ القران فاستمعوا له وانصتوا لعلكم ترحمون","dt":"[204] واذا قرئ القران فاستمعوا له - ايها الناس - وانصتوا؛ لتعقلوه رجاء ان يرحمكم الله به."},{"id":"1159","s":7,"a":205,"at":"واذكر ربك في نفسك تضرعا وخيفه ودون الجهر من القول بالغدو والاصال ولا تكن من الغافلين","dt":"[205] واذكر -ايها الرسول- ربك في نفسك تخشعا وتواضعا لله، خائفا وجل القلب منه، وادعه متوسطا بين الجهر والمخافته في اول النهار واخره، ولا تكن من الذين يغفلون عن ذكر الله، ويلهون عنه في سائر اوقاتهم."},{"id":"1160","s":7,"a":206,"at":"ان الذين عند ربك لا يستكبرون عن عبادته ويسبحونه وله يسجدون","dt":"[206] ان الذين عند ربك من الملائكه لا يستكبرون عن عباده الله، بل ينقادون لاوامره، ويسبحونه بالليل والنهار، وينزهونه عما لا يليق به، وله وحده - لا شريك له - يسجدون."},{"id":"1161","s":8,"a":1,"at":"يسالونك عن الانفال قل الانفال لله والرسول فاتقوا الله واصلحوا ذات بينكم واطيعوا الله ورسوله ان كنتم مؤمنين","dt":"[1] يسالك اصحابك -ايها النبي- عن الغنائم يوم «بدر» كيف تقسمها بينهم؟ قل لهم: ان امرها الى الله ورسوله، فالرسول يتولى قسمتها بامر ربه، فاتقوا عقاب الله ولا تقدموا على معصيته، واتركوا المنازعه والمخاصمه بسبب هذه الاموال، واصلحوا الحال بينكم، والتزموا طاعه الله ورسوله ان كنتم مؤمنين؛ فان الايمان يدعو الى طاعه الله ورسوله."},{"id":"1162","s":8,"a":2,"at":"انما المؤمنون الذين اذا ذكر الله وجلت قلوبهم واذا تليت عليهم اياته زادتهم ايمانا وعلى ربهم يتوكلون","dt":"[2] انما المؤمنون بالله حقا هم الذين اذا ذكر الله فزعت قلوبهم، واذا تليت عليهم ايات القران زادتهم ايمانا مع ايمانهم؛ لتدبرهم لمعانيه، وعلى الله تعالى يتوكلون، فلا يرجون غيره، ولا يرهبون سواه."},{"id":"1163","s":8,"a":3,"at":"الذين يقيمون الصلاه ومما رزقناهم ينفقون","dt":"[3] الذين يداومون على اداء الصلوات المفروضه في اوقاتها، ومما رزقناهم من الاموال ينفقون فيما امرناهم به."},{"id":"1164","s":8,"a":4,"at":"اولئك هم المؤمنون حقا لهم درجات عند ربهم ومغفره ورزق كريم","dt":"[4] هؤلاء الذين يفعلون هذه الافعال هم المؤمنون حقا ظاهرا وباطنا بما انزل الله عليهم، لهم منازل عاليه عند الله، وعفو عن ذنوبهم، ورزق كريم، وهو الجنه."},{"id":"1165","s":8,"a":5,"at":"كما اخرجك ربك من بيتك بالحق وان فريقا من المؤمنين لكارهون","dt":"[5] كما انكم لما اختلفتم في المغانم فانتزعها الله منكم، وجعلها الى قسمه وقسم رسوله -صلى الله عليه وسلم-، كذلك امرك ربك -ايها النبي- بالخروج من «المدينه» للقاء عير قريش، وذلك بالوحي الذي اتاك به جبريل مع كراهه فريق من المؤمنين للخروج."},{"id":"1166","s":8,"a":6,"at":"يجادلونك في الحق بعد ما تبين كانما يساقون الى الموت وهم ينظرون","dt":"[6] يجادلك -ايها النبي- فريق من المؤمنين في القتال من بعد ما تبين لهم ان ذلك واقع، كانهم يساقون الى الموت، وهم ينظرون اليه عيانا."},{"id":"1167","s":8,"a":7,"at":"واذ يعدكم الله احدى الطائفتين انها لكم وتودون ان غير ذات الشوكه تكون لكم ويريد الله ان يحق الحق بكلماته ويقطع دابر الكافرين","dt":"[7] واذكروا -ايها المجادلون- وعد الله لكم بالظفر باحدى الطائفتين: العير وما تحمله من ارزاق، او النفير، وهو قتال الاعداء والانتصار عليهم، وانتم تحبون الظفر بالعير دون القتال، ويريد الله ان يحق الاسلام، ويعليه بامره اياكم بقتال الكفار، ويستاصل الكافرين بالهلاك."},{"id":"1168","s":8,"a":8,"at":"ليحق الحق ويبطل الباطل ولو كره المجرمون","dt":"[8] ليعز الله الاسلام واهله، ويذهب الشرك واهله، ولو كره المشركون ذلك."},{"id":"1169","s":8,"a":9,"at":"اذ تستغيثون ربكم فاستجاب لكم اني ممدكم بالف من الملائكه مردفين","dt":"[9] اذكروا نعمه الله عليكم يوم «بدر» اذ تطلبون النصر على عدوكم، فاستجاب الله لدعائكم قائلا: اني ممدكم بالف من الملائكه من السماء، يتبع بعضهم بعضا."},{"id":"1170","s":8,"a":10,"at":"وما جعله الله الا بشرى ولتطمئن به قلوبكم وما النصر الا من عند الله ان الله عزيز حكيم","dt":"[10] وما جعل الله ذلك الامداد الا بشاره لكم بالنصر، ولتسكن به قلوبكم، وتوقنوا بنصر الله لكم، وما النصر الا من عند الله، لا بشده باسكم وقواكم. ان الله عزيز في ملكه، حكيم في تدبيره وشرعه."},{"id":"1171","s":8,"a":11,"at":"اذ يغشيكم النعاس امنه منه وينزل عليكم من السماء ماء ليطهركم به ويذهب عنكم رجز الشيطان وليربط على قلوبكم ويثبت به الاقدام","dt":"[11] اذ يلقي الله عليكم النعاس امانا منه لكم من خوف عدوكم ان يغلبكم، وينزل عليكم من السحاب ماء طهورا؛ ليطهركم به من الاحداث الظاهره، ويزيل عنكم في الباطن وساوس الشيطان وخواطره، وليشد على قلوبكم بالصبر عند القتال، ويثبت به اقدام المؤمنين بتلبيد الارض الرمليه بالمطر حتى لا تنزلق فيها الاقدام."},{"id":"1172","s":8,"a":12,"at":"اذ يوحي ربك الى الملائكه اني معكم فثبتوا الذين امنوا سالقي في قلوب الذين كفروا الرعب فاضربوا فوق الاعناق واضربوا منهم كل بنان","dt":"[12] اذ يوحي ربك -ايها النبي- الى الملائكه الذين امد الله بهم المسلمين في غزوه «بدر» اني معكم اعينكم وانصركم، فقووا عزائم الذين امنوا، سالقي في قلوب الذين كفروا الخوف الشديد والذله والصغار، فاضربوا -ايها المؤمنون- رؤوس الكفار، واضربوا منهم كل طرف ومفصل."},{"id":"1173","s":8,"a":13,"at":"ذلك بانهم شاقوا الله ورسوله ومن يشاقق الله ورسوله فان الله شديد العقاب","dt":"[13] ذلك الذي حدث للكفار من ضرب رؤوسهم واعناقهم واطرافهم؛ بسبب مخالفتهم لامر الله ورسوله، ومن يخالف امر الله ورسوله، فان الله شديد العقاب له في الدنيا والاخره."},{"id":"1174","s":8,"a":14,"at":"ذلكم فذوقوه وان للكافرين عذاب النار","dt":"[14] ذلكم العذاب الذي عجلته لكم -ايها الكافرون المخالفون لاوامر الله ورسوله في الدنيا- فذوقوه في الحياه الدنيا، ولكم في الاخره عذاب النار."},{"id":"1175","s":8,"a":15,"at":"ياايها الذين امنوا اذا لقيتم الذين كفروا زحفا فلا تولوهم الادبار","dt":"[15] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، اذا قابلتم الذين كفروا في القتال متقاربين منكم فلا تولوهم ظهوركم، فتنهزموا عنهم، ولكن اثبتوا لهم، فان الله معكم وناصركم عليهم."},{"id":"1176","s":8,"a":16,"at":"ومن يولهم يومئذ دبره الا متحرفا لقتال او متحيزا الى فئه فقد باء بغضب من الله وماواه جهنم وبئس المصير","dt":"[16] ومن يولهم منكم ظهره وقت الزحف، الا منعطفا لمكيده الكفار، او منحازا الى جماعه المسلمين الحاضري الحرب حيث كانوا، فقد استحق الغضب من الله، ومقامه جهنم، وبئس المصير والمنقلب."},{"id":"1177","s":8,"a":17,"at":"فلم تقتلوهم ولكن الله قتلهم وما رميت اذ رميت ولكن الله رمى وليبلي المؤمنين منه بلاء حسنا ان الله سميع عليم","dt":"[17] فلم تقتلوا -ايها المؤمنون- المشركين يوم «بدر»، ولكن الله قتلهم، حيث اعانكم على ذلك، وما رميت حين رميت -ايها النبي- ولكن الله رمى، حيث اوصل الرميه التي رميتها الى وجوه المشركين؛ وليختبر المؤمنين بالله ورسوله ويوصلهم بالجهاد الى اعلى الدرجات، ويعرفهم نعمته عليهم، فيشكروا له سبحانه على ذلك. ان الله سميع لدعائكم واقوالكم ما اسررتم به وما اعلنتم، عليم بما فيه صلاح عباده."},{"id":"1178","s":8,"a":18,"at":"ذلكم وان الله موهن كيد الكافرين","dt":"[18] هذا الفعل من قتل المشركين ورميهم حين انهزموا، والبلاء الحسن بنصر المؤمنين على اعدائهم، هو من الله للمؤمنين، وان الله -فيما يستقبل- مضعف ومبطل مكر الكافرين حتى يذلوا وينقادوا للحق او يهلكوا."},{"id":"1179","s":8,"a":19,"at":"ان تستفتحوا فقد جاءكم الفتح وان تنتهوا فهو خير لكم وان تعودوا نعد ولن تغني عنكم فئتكم شيئا ولو كثرت وان الله مع المؤمنين","dt":"[19] ان تطلبوا -ايها الكفار- من الله ان يوقع باسه وعذابه على المعتدين الظالمين فقد اجاب الله طلبكم، حين اوقع بكم من عقابه ما كان نكالا لكم وعبره للمتقين، وان تنتهوا -ايها الكفار- عن الكفر بالله ورسوله وقتال نبيه محمد -صلى الله عليه وسلم-، فهو خير لكم في دنياكم واخراكم، وان تعودوا الى الحرب وقتال محمد -صلى الله عليه وسلم- وقتال اتباعه المؤمنين نعد بهزيمتكم كما هزمتم يوم «بدر»، ولن تغني عنكم جماعتكم شيئا، كما لم تغن عنكم يوم «بدر» مع كثره عددكم وعتادكم وقله عدد المؤمنين وعدتهم، وان الله مع المؤمنين بتاييده ونصره."},{"id":"1180","s":8,"a":20,"at":"ياايها الذين امنوا اطيعوا الله ورسوله ولا تولوا عنه وانتم تسمعون","dt":"[20] يا ايها الذين صدقوا الله ورسوله اطيعوا الله ورسوله فيما امركم به ونهاكم عنه، ولا تتركوا طاعه الله وطاعه رسوله، وانتم تسمعون ما يتلى عليكم في القران من الحجج والبراهين."},{"id":"1181","s":8,"a":21,"at":"ولا تكونوا كالذين قالوا سمعنا وهم لا يسمعون","dt":"[21] ولا تكونوا ايها المؤمنون في مخالفه الله ورسوله محمد -صلى الله عليه وسلم- كالمشركين والمنافقين الذين اذا سمعوا كتاب الله يتلى عليهم قالوا: سمعنا باذاننا، وهم في الحقيقه لا يتدبرون ما سمعوا، ولا يفكرون فيه."},{"id":"1182","s":8,"a":22,"at":"ان شر الدواب عند الله الصم البكم الذين لا يعقلون","dt":"[22] ان شر ما دب على الارض -من خلق الله- عند الله الصم الذين انسدت اذانهم عن سماع الحق فلا يسمعون، البكم الذين خرست السنتهم عن النطق به فلا ينطقون، هؤلاء هم الذين لا يعقلون عن الله امره ونهيه."},{"id":"1183","s":8,"a":23,"at":"ولو علم الله فيهم خيرا لاسمعهم ولو اسمعهم لتولوا وهم معرضون","dt":"[23] ولو علم الله في هؤلاء خيرا لاسمعهم مواعظ القران وعبره حتى يعقلوا عن الله عز وجل حججه وبراهينه، ولكنه علم انه لا خير فيهم وانهم لا يؤمنون، ولو اسمعهم -على الفرض والتقدير- لتولوا عن الايمان قصدا وعنادا بعد فهمهم له، وهم معرضون عنه، لا التفات لهم الى الحق بوجه من الوجوه."},{"id":"1184","s":8,"a":24,"at":"ياايها الذين امنوا استجيبوا لله وللرسول اذا دعاكم لما يحييكم واعلموا ان الله يحول بين المرء وقلبه وانه اليه تحشرون","dt":"[24] يا ايها الذين صدقوا بالله ربا وبمحمد نبيا ورسولا، استجيبوا لله وللرسول بالطاعه اذا دعاكم لما يحييكم من الحق، ففي الاستجابه اصلاح حياتكم في الدنيا والاخره، واعلموا -ايها المؤمنون- ان الله تعالى هو المتصرف في جميع الاشياء، والقادر على ان يحول بين الانسان وما يشتهيه قلبه، فهو سبحانه الذي ينبغي ان يستجاب له اذا دعاكم؛ اذ بيده ملكوت كل شيء، واعلموا انكم تجمعون ليوم لا ريب فيه، فيجازي كلا بما يستحق."},{"id":"1185","s":8,"a":25,"at":"واتقوا فتنه لا تصيبن الذين ظلموا منكم خاصه واعلموا ان الله شديد العقاب","dt":"[25] واحذروا -ايها المؤمنون- اختبارا ومحنه يعم بها المسيء وغيره، لا يخص بها اهل المعاصي ولا من باشر الذنب، بل تصيب الصالحين معهم اذا قدروا على انكار الظلم ولم ينكروه، واعلموا ان الله شديد العقاب لمن خالف امره ونهيه."},{"id":"1186","s":8,"a":26,"at":"واذكروا اذ انتم قليل مستضعفون في الارض تخافون ان يتخطفكم الناس فاواكم وايدكم بنصره ورزقكم من الطيبات لعلكم تشكرون","dt":"[26] واذكروا ايها المؤمنون نعم الله عليكم اذ انتم ب«مكه» قليلو العدد مقهورون، تخافون ان ياخذكم كفارها بسرعه، فجعل لكم ماوى تاوون اليه وهو «المدينه»، وقواكم بنصره عليهم يوم «بدر»، واطعمكم من الطيبات -التي من جملتها الغنائم-؛ لكي تشكروا له على ما رزقكم وانعم به عليكم."},{"id":"1187","s":8,"a":27,"at":"ياايها الذين امنوا لا تخونوا الله والرسول وتخونوا اماناتكم وانتم تعلمون","dt":"[27] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه لا تخونوا الله ورسوله بترك ما اوجبه الله عليكم وفعل ما نهاكم عنه، ولا تفرطوا فيما ائتمنكم الله عليه، وانتم تعلمون انه امانه يجب الوفاء بها."},{"id":"1188","s":8,"a":28,"at":"واعلموا انما اموالكم واولادكم فتنه وان الله عنده اجر عظيم","dt":"[28] واعلموا -ايها المؤمنون- ان اموالكم التي استخلفكم الله فيها، واولادكم الذين وهبهم الله لكم اختبار من الله وابتلاء لعباده؛ ليعلم ايشكرونه عليها ويطيعونه فيها، ام ينشغلون بها عنه؟ واعلموا ان الله عنده خير وثواب عظيم لمن اتقاه واطاعه."},{"id":"1189","s":8,"a":29,"at":"ياايها الذين امنوا ان تتقوا الله يجعل لكم فرقانا ويكفر عنكم سيئاتكم ويغفر لكم والله ذو الفضل العظيم","dt":"[29] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه ان تتقوا الله بفعل اوامره واجتناب نواهيه يجعل لكم فصلا بين الحق والباطل، ويمح عنكم ما سلف من ذنوبكم ويسترها عليكم، فلا يؤاخذكم بها. والله ذو الاحسان والعطاء الكثير الواسع."},{"id":"1190","s":8,"a":30,"at":"واذ يمكر بك الذين كفروا ليثبتوك او يقتلوك او يخرجوك ويمكرون ويمكر الله والله خير الماكرين","dt":"[30] واذكر -ايها الرسول- حين يكيد لك مشركو قومك ب«مكه»؛ ليحبسوك او يقتلوك او ينفوك من بلدك. ويكيدون لك، ورد الله مكرهم عليهم جزاء لهم، ويمكر الله، والله خير الماكرين، فهو يعاقبهم على مكرهم من حيث لا يشعرون."},{"id":"1191","s":8,"a":31,"at":"واذا تتلى عليهم اياتنا قالوا قد سمعنا لو نشاء لقلنا مثل هذا ان هذا الا اساطير الاولين","dt":"[31] واذا تتلى على هؤلاء الذين كفروا بالله ايات القران العزيز قالوا جهلا منهم وعنادا للحق: قد سمعنا هذا من قبل، لو نشاء لقلنا مثل هذا القران، ما هذا القران الذي تتلوه علينا -ايها الرسول- الا اكاذيب الاولين."},{"id":"1192","s":8,"a":32,"at":"واذ قالوا اللهم ان كان هذا هو الحق من عندك فامطر علينا حجاره من السماء او ائتنا بعذاب اليم","dt":"[32] واذكر -ايها الرسول- قول المشركين من قومك داعين الله: ان كان ما جاء به محمد هو الحق من عندك فامطر علينا حجاره من السماء، او ائتنا بعذاب شديد موجع."},{"id":"1193","s":8,"a":33,"at":"وما كان الله ليعذبهم وانت فيهم وما كان الله معذبهم وهم يستغفرون","dt":"[33] وما كان الله - سبحانه وتعالى - ليعذب هؤلاء المشركين، وانت -ايها الرسول- بين ظهرانيهم، وما كان الله معذبهم، وهم يستغفرون من ذنوبهم."},{"id":"1194","s":8,"a":34,"at":"وما لهم الا يعذبهم الله وهم يصدون عن المسجد الحرام وما كانوا اولياءه ان اولياؤه الا المتقون ولكن اكثرهم لا يعلمون","dt":"[34] وكيف لا يستحقون عذاب الله، وهم يصدون اولياءه المؤمنين عن الطواف بالكعبه والصلاه في المسجد الحرام؟ وما كانوا اولياء الله، ان اولياء الله الا الذين يتقونه باداء فرائضه واجتناب معاصيه، ولكن اكثر الكفار لا يعلمون؛ فلذلك ادعوا لانفسهم امرا، غيرهم اولى به."},{"id":"1195","s":8,"a":35,"at":"وما كان صلاتهم عند البيت الا مكاء وتصديه فذوقوا العذاب بما كنتم تكفرون","dt":"[35] وما كان صلاتهم عند المسجد الحرام الا صفيرا وتصفيقا. فذوقوا عذاب القتل والاسر يوم «بدر»؛ بسبب جحودكم وافعالكم التي لا يقدم عليها الا الكفره، الجاحدون توحيد ربهم ورساله نبيهم."},{"id":"1196","s":8,"a":36,"at":"ان الذين كفروا ينفقون اموالهم ليصدوا عن سبيل الله فسينفقونها ثم تكون عليهم حسره ثم يغلبون والذين كفروا الى جهنم يحشرون","dt":"[36] ان الذين جحدوا وحدانيه الله وعصوا رسوله ينفقون اموالهم فيعطونها امثالهم من المشركين واهل الضلال؛ ليصدوا عن سبيل الله ويمنعوا المؤمنين عن الايمان بالله ورسوله، فسينفقون اموالهم في ذلك، ثم تكون عاقبه نفقتهم تلك ندامه وحسره عليهم؛ لان اموالهم تذهب، ولا يظفرون بما ياملون من اطفاء نور الله والصد عن سبيله، ثم يهزمهم المؤمنون اخر الامر. والذين كفروا الى جهنم يحشرون فيعذبون فيها."},{"id":"1197","s":8,"a":37,"at":"ليميز الله الخبيث من الطيب ويجعل الخبيث بعضه على بعض فيركمه جميعا فيجعله في جهنم اولئك هم الخاسرون","dt":"[37] يحشر الله ويخزي هؤلاء الذين كفروا بربهم، وانفقوا اموالهم لمنع الناس عن الايمان بالله والصد عن سبيله؛ ليميز الله تعالى الخبيث من الطيب، ويجعل الله المال الحرام الذي انفق للصد عن دين الله بعضه فوق بعض متراكما متراكبا، فيجعله في نار جهنم، هؤلاء الكفار هم الخاسرون في الدنيا والاخره."},{"id":"1198","s":8,"a":38,"at":"قل للذين كفروا ان ينتهوا يغفر لهم ما قد سلف وان يعودوا فقد مضت سنه الاولين","dt":"[38] قل -ايها الرسول- للذين جحدوا وحدانيه الله من مشركي قومك: ان ينزجروا عن الكفر وعداوه النبي -صلى الله عليه وسلم-، ويرجعوا الى الايمان بالله وحده وعدم قتال الرسول والمؤمنين، يغفر الله لهم ما سبق من الذنوب، فالاسلام يجب ما قبله. وان يعد هؤلاء المشركون لقتالك -ايها الرسول- بعد الوقعه التي اوقعتها بهم يوم «بدر» فقد سبقت طريقه الاولين، وهي انهم اذا كذبوا واستمروا على عنادهم عاجلناهم بالعذاب والعقوبه."},{"id":"1199","s":8,"a":39,"at":"وقاتلوهم حتى لا تكون فتنه ويكون الدين كله لله فان انتهوا فان الله بما يعملون بصير","dt":"[39] وقاتلوا -ايها المؤمنون- المشركين حتى لا يكون شرك وصد عن سبيل الله، ولا يعبد الا الله وحده لا شريك له، فيرتفع البلاء عن عباد الله في الارض، وحتى يكون الدين والطاعه والعباده كلها لله خالصه دون غيره، فان انزجروا عن فتنه المؤمنين وعن الشرك بالله وصاروا الى الدين الحق معكم، فان الله لا يخفى عليه ما يعملون من ترك الكفر والدخول في الاسلام."},{"id":"1200","s":8,"a":40,"at":"وان تولوا فاعلموا ان الله مولاكم نعم المولى ونعم النصير","dt":"[40] وان اعرض هؤلاء المشركون عما دعوتموهم اليه -ايها المؤمنون- من الايمان بالله ورسوله وترك قتالكم، وابوا الا الاصرار على الكفر وقتالكم، فايقنوا ان الله معينكم وناصركم عليهم. نعم المعين والناصر لكم ولاوليائه على اعدائكم."},{"id":"1201","s":8,"a":41,"at":"واعلموا انما غنمتم من شيء فان لله خمسه وللرسول ولذي القربى واليتامى والمساكين وابن السبيل ان كنتم امنتم بالله وما انزلنا على عبدنا يوم الفرقان يوم التقى الجمعان والله على كل شيء قدير","dt":"[41] واعلموا -ايها المؤمنون- ان ما ظفرتم به من عدوكم بالجهاد في سبيل الله فاربعه اخماسه للمقاتلين الذين حضروا المعركه، والخمس الباقي يجزا خمسه اقسام: الاول لله وللرسول، فيجعل في مصالح المسلمين العامه، والثاني لذوي قرابه رسول الله -صلى الله عليه وسلم-، وهم بنو هاشم وبنو المطلب، جعل لهم الخمس مكان الصدقه فانها لا تحل لهم، والثالث للاولاد الذين مات اباؤهم وهم دون سن البلوغ، والرابع للمساكين الذين لا يملكون ما يكفيهم ويسد حاجتهم، والخامس للمسافر الذي انقطعت به النفقه، ان كنتم مقرين بتوحيد الله مطيعين له، مؤمنين بما انزل على عبده محمد -صلى الله عليه وسلم- من الايات والمدد والنصر يوم فرق بين الحق والباطل ب«بدر»، يوم التقى جمع المؤمنين وجمع المشركين. والله على كل شيء قدير لا يعجزه شيء."},{"id":"1202","s":8,"a":42,"at":"اذ انتم بالعدوه الدنيا وهم بالعدوه القصوى والركب اسفل منكم ولو تواعدتم لاختلفتم في الميعاد ولكن ليقضي الله امرا كان مفعولا ليهلك من هلك عن بينه ويحيا من حي عن بينه وان الله لسميع عليم","dt":"[42] واذكروا حينما كنتم على جانب الوادي الاقرب الى «المدينه»، وعدوكم نازل بجانب الوادي الاقصى، وعير التجاره في مكان اسفل منكم الى ساحل «البحر الاحمر»، ولو حاولتم ان تضعوا موعدا لهذا اللقاء لاختلفتم، ولكن الله جمعكم على غير ميعاد؛ ليقضي امرا كان مفعولا بنصر اوليائه وخذلان اعدائه بالقتل والاسر؛ وذلك ليهلك من هلك منهم عن حجه لله ثبتت له فعاينها وقطعت عذره، وليحيا من حي عن حجه لله قد ثبتت وظهرت له. وان الله لسميع لاقوال الفريقين، لا يخفى عليه شيء، عليم بنياتهم واعمالهم."},{"id":"1203","s":8,"a":43,"at":"اذ يريكهم الله في منامك قليلا ولو اراكهم كثيرا لفشلتم ولتنازعتم في الامر ولكن الله سلم انه عليم بذات الصدور","dt":"[43] واذكر -ايها النبي- حينما اراك الله قله عدد عدوك في منامك، فاخبرت المؤمنين بذلك، فقويت قلوبهم، واجترؤوا على حربهم، ولو اراك ربك كثره عددهم لتردد اصحابك في ملاقاتهم، وجبنتم واختلفتم في امر القتال، ولكن الله سلم من الفشل، ونجى من عاقبه ذلك. انه عليم بخفايا القلوب وطبائع النفوس."},{"id":"1204","s":8,"a":44,"at":"واذ يريكموهم اذ التقيتم في اعينكم قليلا ويقللكم في اعينهم ليقضي الله امرا كان مفعولا والى الله ترجع الامور","dt":"[44] واذكر ايضا حينما برز الاعداء الى ارض المعركه فرايتموهم قليلا فاجتراتم عليهم، وقللكم في اعينهم؛ ليتركوا الاستعداد لحربكم؛ ليقضي الله امرا كان مفعولا، فيتحقق وعد الله لكم بالنصر والغلبه، فكانت كلمه الله هي العليا وكلمه الذين كفروا السفلى. والى الله مصير الامور كلها، فيجازي كلا بما يستحق."},{"id":"1205","s":8,"a":45,"at":"ياايها الذين امنوا اذا لقيتم فئه فاثبتوا واذكروا الله كثيرا لعلكم تفلحون","dt":"[45] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، اذا لقيتم جماعه من اهل الكفر قد استعدوا لقتالكم، فاثبتوا ولا تنهزموا عنهم، واذكروا الله كثيرا داعين مبتهلين لانزال النصر عليكم والظفر بعدوكم؛ لكي تفوزوا."},{"id":"1206","s":8,"a":46,"at":"واطيعوا الله ورسوله ولا تنازعوا فتفشلوا وتذهب ريحكم واصبروا ان الله مع الصابرين","dt":"[46] والتزموا طاعه الله وطاعه رسوله في كل احوالكم، ولا تختلفوا فتتفرق كلمتكم وتختلف قلوبكم، فتضعفوا وتذهب قوتكم ونصركم، واصبروا عند لقاء العدو. ان الله مع الصابرين بالعون والنصر والتاييد، ولن يخذلهم."},{"id":"1207","s":8,"a":47,"at":"ولا تكونوا كالذين خرجوا من ديارهم بطرا ورئاء الناس ويصدون عن سبيل الله والله بما يعملون محيط","dt":"[47] ولا تكونوا مثل المشركين الذين خرجوا من بلدهم كبرا ورياء؛ ليمنعوا الناس عن الدخول في دين الله. والله بما يعملون محيط لا يغيب عنه شيء."},{"id":"1208","s":8,"a":48,"at":"واذ زين لهم الشيطان اعمالهم وقال لا غالب لكم اليوم من الناس واني جار لكم فلما تراءت الفئتان نكص على عقبيه وقال اني بريء منكم اني ارى ما لا ترون اني اخاف الله والله شديد العقاب","dt":"[48] واذكروا حين حسن الشيطان للمشركين ما جاؤوا له وما هموا به، وقال لهم: لن يغلبكم احد اليوم، واني ناصركم، فلما تقابل الفريقان: المشركون ومعهم الشيطان، والمسلمون ومعهم الملائكه، رجع الشيطان مدبرا، وقال للمشركين: اني بريء منكم، اني ارى ما لا ترون من الملائكه الذين جاؤوا مددا للمسلمين، اني اخاف الله، فخذلهم وتبرا منهم. والله شديد العقاب لمن عصاه ولم يتب توبه نصوحا."},{"id":"1209","s":8,"a":49,"at":"اذ يقول المنافقون والذين في قلوبهم مرض غر هؤلاء دينهم ومن يتوكل على الله فان الله عزيز حكيم","dt":"[49] واذكروا حين يقول اهل الشك والنفاق ومرضى القلوب، وهم يرون قله المسلمين وكثره عدوهم: غر هؤلاء المسلمين دينهم، فاوردهم هذه الموارد، ولم يدرك هؤلاء المنافقون انه من يتوكل على الله ويثق بوعده فان الله لن يخذله، فان الله عزيز لا يعجزه شيء، حكيم في تدبيره وصنعه."},{"id":"1210","s":8,"a":50,"at":"ولو ترى اذ يتوفى الذين كفروا الملائكه يضربون وجوههم وادبارهم وذوقوا عذاب الحريق","dt":"[50] ولو تعاين -ايها الرسول- حال قبض الملائكه ارواح الكفار وانتزاعها، وهم يضربون وجوههم في حال اقبالهم، ويضربون ظهورهم في حال فرارهم، ويقولون لهم: ذوقوا العذاب المحرق، لرايت امرا عظيما. وهذا السياق وان كان سببه وقعه «بدر»، ولكنه عام في حق كل كافر."},{"id":"1211","s":8,"a":51,"at":"ذلك بما قدمت ايديكم وان الله ليس بظلام للعبيد","dt":"[51] ذلك الجزاء الذي اصابكم ايها المشركون فبسبب اعمالكم السيئه في حياتكم الدنيا، ولا يظلم الله احدا من خلقه مثقال ذره، بل هو الحكم العدل الذي لا يجور."},{"id":"1212","s":8,"a":52,"at":"كداب ال فرعون والذين من قبلهم كفروا بايات الله فاخذهم الله بذنوبهم ان الله قوي شديد العقاب","dt":"[52] ان ما نزل بالمشركين يومئذ سنه الله في عقاب الطغاه من الامم السابقه من امثال فرعون والسابقين له، عندما كذبوا رسل الله وجحدوا اياته، فان الله انزل بهم عقابه بسبب ذنوبهم. ان الله قوي لا يقهر، شديد العقاب لمن عصاه ولم يتب من ذنبه."},{"id":"1213","s":8,"a":53,"at":"ذلك بان الله لم يك مغيرا نعمه انعمها على قوم حتى يغيروا ما بانفسهم وان الله سميع عليم","dt":"[53] ذلك الجزاء السيئ بان الله اذا انعم على قوم نعمه لم يسلبها منهم حتى يغيروا حالهم الطيبه الى حال سيئه، وان الله سميع لاقوال خلقه، عليم باحوالهم، فيجري عليهم ما اقتضاه علمه ومشيئته."},{"id":"1214","s":8,"a":54,"at":"كداب ال فرعون والذين من قبلهم كذبوا بايات ربهم فاهلكناهم بذنوبهم واغرقنا ال فرعون وكل كانوا ظالمين","dt":"[54] شان هؤلاء الكافرين في ذلك كشان ال فرعون الذين كذبوا موسى، وشان الذين كذبوا رسلهم من الامم السابقه فاهلكهم الله بسبب ذنوبهم، واغرق ال فرعون في البحر، وكل منهم كان فاعلا ما لم يكن له فعله من تكذيبهم رسل الله وجحودهم اياته، واشراكهم في العباده غيره."},{"id":"1215","s":8,"a":55,"at":"ان شر الدواب عند الله الذين كفروا فهم لا يؤمنون","dt":"[55] ان شر ما دب على الارض عند الله الكفار المصرون على الكفر، فهم لا يصدقون رسل الله، ولا يقرون بوحدانيته، ولا يتبعون شرعه."},{"id":"1216","s":8,"a":56,"at":"الذين عاهدت منهم ثم ينقضون عهدهم في كل مره وهم لا يتقون","dt":"[56] من اولئك الاشرار اليهود الذين دخلوا معك في المعاهدات بان لا يحاربوك ولا يظاهروا عليك احدا، ثم ينقضون عهدهم المره تلو المره، وهم لا يخافون الله."},{"id":"1217","s":8,"a":57,"at":"فاما تثقفنهم في الحرب فشرد بهم من خلفهم لعلهم يذكرون","dt":"[57] فان واجهت هؤلاء الناقضين للعهود والمواثيق في المعركه، فانزل بهم من العذاب ما يدخل الرعب في قلوب الاخرين، ويشتت جموعهم؛ لعلهم يذكرون، فلا يجترئون على مثل الذي اقدم عليه السابقون."},{"id":"1218","s":8,"a":58,"at":"واما تخافن من قوم خيانه فانبذ اليهم على سواء ان الله لا يحب الخائنين","dt":"[58] وان خفت -ايها الرسول- من قوم خيانه ظهرت بوادرها فالق اليهم عهدهم؛ كي يكون الطرفان مستويين في العلم بانه لا عهد بعد اليوم. ان الله لا يحب الخائنين في عهودهم الناقضين للعهد والميثاق."},{"id":"1219","s":8,"a":59,"at":"ولا يحسبن الذين كفروا سبقوا انهم لا يعجزون","dt":"[59] ولا يظنن الذين جحدوا ايات الله انهم فاتوا ونجوا، وان الله لا يقدر عليهم، انهم لن يفلتوا من عذاب الله."},{"id":"1220","s":8,"a":60,"at":"واعدوا لهم ما استطعتم من قوه ومن رباط الخيل ترهبون به عدو الله وعدوكم واخرين من دونهم لا تعلمونهم الله يعلمهم وما تنفقوا من شيء في سبيل الله يوف اليكم وانتم لا تظلمون","dt":"[60] واعدوا -يا معشر المسلمين -لمواجهه اعدائكم كل ما تقدرون عليه من عدد وعده، لتدخلوا بذلك الرهبه في قلوب اعداء الله واعدائكم المتربصين بكم، وتخيفوا اخرين لا تظهر لكم عداوتهم الان، لكن الله يعلمهم ويعلم ما يضمرونه. وما تبذلوا من مال وغيره في سبيل الله قليلا او كثيرا يخلفه الله عليكم في الدنيا، ويدخر لكم ثوابه الى يوم القيامه، وانتم لا تنقصون من اجر ذلك شيئا."},{"id":"1221","s":8,"a":61,"at":"وان جنحوا للسلم فاجنح لها وتوكل على الله انه هو السميع العليم","dt":"[61] وان مالوا الى ترك الحرب ورغبوا في مسالمتكم فمل الى ذلك -ايها النبي- وفوض امرك الى الله، وثق به. انه هو السميع لاقوالهم، العليم بنياتهم."},{"id":"1222","s":8,"a":62,"at":"وان يريدوا ان يخدعوك فان حسبك الله هو الذي ايدك بنصره وبالمؤمنين","dt":"[62] وان اراد الذين عاهدوك المكر بك فان الله سيكفيك خداعهم؛ انه هو الذي انزل عليك نصره وقواك بالمؤمنين من المهاجرين والانصار"},{"id":"1223","s":8,"a":63,"at":"والف بين قلوبهم لو انفقت ما في الارض جميعا ما الفت بين قلوبهم ولكن الله الف بينهم انه عزيز حكيم","dt":"[63] وجمع بين قلوبهم بعد التفرق، لو انفقت مال الدنيا على جمع قلوبهم ما استطعت الى ذلك سبيلا، ولكن الله جمع بينها على الايمان فاصبحوا اخوانا متحابين، انه عزيز في ملكه، حكيم في امره وتدبيره."},{"id":"1224","s":8,"a":64,"at":"ياايها النبي حسبك الله ومن اتبعك من المؤمنين","dt":"[64] يا ايها النبي ان الله كافيك، وكافي الذين معك من المؤمنين شر اعدائكم."},{"id":"1225","s":8,"a":65,"at":"ياايها النبي حرض المؤمنين على القتال ان يكن منكم عشرون صابرون يغلبوا مائتين وان يكن منكم مائه يغلبوا الفا من الذين كفروا بانهم قوم لا يفقهون","dt":"[65] يا ايها النبي حث المؤمنين بك على القتال، ان يكن منكم عشرون صابرون عند لقاء العدو يغلبوا مائتين منهم، وان يكن منكم مائه مجاهده صابره يغلبوا الفا من الكفار؛ لانهم قوم لا علم ولا فهم عندهم لما اعد الله للمجاهدين في سبيله، فهم يقاتلون من اجل العلو في الارض والفساد فيها."},{"id":"1226","s":8,"a":66,"at":"الان خفف الله عنكم وعلم ان فيكم ضعفا فان يكن منكم مائه صابره يغلبوا مائتين وان يكن منكم الف يغلبوا الفين باذن الله والله مع الصابرين","dt":"[66] الان خفف الله عنكم ايها المؤمنون لما فيكم من الضعف، فان يكن منكم مائه صابره يغلبوا مائتين من الكافرين، وان يكن منكم الف يغلبوا الفين منهم باذن الله تعالى. والله مع الصابرين بتاييده ونصره."},{"id":"1227","s":8,"a":67,"at":"ما كان لنبي ان يكون له اسرى حتى يثخن في الارض تريدون عرض الدنيا والله يريد الاخره والله عزيز حكيم","dt":"[67] لا ينبغي لنبي ان يكون له اسرى من اعدائه حتى يبالغ في القتل؛ لادخال الرعب في قلوبهم ويوطد دعائم الدين، تريدون -يا معشر المسلمين- باخذكم الفداء من اسرى «بدر» متاع الدنيا، والله يريد اظهار دينه الذي به تدرك الاخره. والله عزيز لا يقهر، حكيم في شرعه."},{"id":"1228","s":8,"a":68,"at":"لولا كتاب من الله سبق لمسكم فيما اخذتم عذاب عظيم","dt":"[68] لولا كتاب من الله سبق به القضاء والقدر باباحه الغنيمه وفداء الاسرى لهذه الامه، لنالكم عذاب عظيم بسبب اخذكم الغنيمه والفداء قبل ان ينزل بشانهما تشريع."},{"id":"1229","s":8,"a":69,"at":"فكلوا مما غنمتم حلالا طيبا واتقوا الله ان الله غفور رحيم","dt":"[69] فكلوا من الغنائم وفداء الاسرى فهو حلال طيب، وحافظوا على احكام دين الله وتشريعاته. ان الله غفور لعباده، رحيم بهم."},{"id":"1230","s":8,"a":70,"at":"ياايها النبي قل لمن في ايديكم من الاسرى ان يعلم الله في قلوبكم خيرا يؤتكم خيرا مما اخذ منكم ويغفر لكم والله غفور رحيم","dt":"[70] يا ايها النبي قل لمن اسرتموهم في «بدر»: لا تاسوا على الفداء الذي اخذ منكم، ان يعلم الله تعالى في قلوبكم خيرا يؤتكم خيرا مما اخذ منكم من المال، بان ييسر لكم من فضله خيرا كثيرا -وقد انجز الله وعده للعباس رضي الله عنه وغيره-، ويغفر لكم ذنوبكم. والله سبحانه غفور لذنوب عباده اذا تابوا، رحيم بهم."},{"id":"1231","s":8,"a":71,"at":"وان يريدوا خيانتك فقد خانوا الله من قبل فامكن منهم والله عليم حكيم","dt":"[71] وان يرد الذين اطلقت سراحهم -ايها النبي- من الاسرى الغدر بك مره اخرى فلا تيئس، فقد خانوا الله من قبل وحاربوك، فنصرك الله عليهم. والله عليم بما تنطوي عليه الصدور، حكيم في تدبير شؤون عباده."},{"id":"1232","s":8,"a":72,"at":"ان الذين امنوا وهاجروا وجاهدوا باموالهم وانفسهم في سبيل الله والذين اووا ونصروا اولئك بعضهم اولياء بعض والذين امنوا ولم يهاجروا ما لكم من ولايتهم من شيء حتى يهاجروا وان استنصروكم في الدين فعليكم النصر الا على قوم بينكم وبينهم ميثاق والله بما تعملون بصير","dt":"[72] ان الذين صدقوا الله ورسوله وعملوا بشرعه، وهاجروا الى دار الاسلام، او بلد يتمكنون فيه من عباده ربهم، وجاهدوا في سبيل الله بالمال والنفس، والذين انزلوا المهاجرين في دورهم، وواسوهم باموالهم، ونصروا دين الله، اولئك بعضهم نصراء بعض. اما الذين امنوا ولم يهاجروا من دار الكفر فلستم مكلفين بحمايتهم ونصرتهم حتى يهاجروا، وان وقع عليهم ظلم من الكفار فطلبوا نصرتكم فاستجيبوا لهم، الا على قوم بينكم وبينهم عهد مؤكد لم ينقضوه. والله بصير باعمالكم، يجزي كلا على قدر نيته وعمله."},{"id":"1233","s":8,"a":73,"at":"والذين كفروا بعضهم اولياء بعض الا تفعلوه تكن فتنه في الارض وفساد كبير","dt":"[73] والذين كفروا بعضهم نصراء بعض، وان لم تكونوا -ايها المؤمنون- نصراء بعض تكن في الارض فتنه للمؤمنين عن دين الله، وفساد عريض بالصد عن سبيل الله وتقويه دعائم الكفر."},{"id":"1234","s":8,"a":74,"at":"والذين امنوا وهاجروا وجاهدوا في سبيل الله والذين اووا ونصروا اولئك هم المؤمنون حقا لهم مغفره ورزق كريم","dt":"[74] والذين امنوا بالله ورسوله، وتركوا ديارهم قاصدين دار الاسلام، او بلدا يتمكنون فيه من عباده ربهم، وجاهدوا لاعلاء كلمه الله، والذين نصروا اخوانهم المهاجرين واووهم وواسوهم بالمال والتاييد، اولئك هم المؤمنون الصادقون حقا، لهم مغفره لذنوبهم، ورزق كريم واسع في جنات النعيم."},{"id":"1235","s":8,"a":75,"at":"والذين امنوا من بعد وهاجروا وجاهدوا معكم فاولئك منكم واولو الارحام بعضهم اولى ببعض في كتاب الله ان الله بكل شيء عليم","dt":"[75] والذين امنوا من بعد هؤلاء المهاجرين والانصار، وهاجروا وجاهدوا معكم في سبيل الله، فاولئك منكم -ايها المؤمنون- لهم ما لكم وعليهم ما عليكم، واولو القرابه بعضهم اولى ببعض في التوارث في حكم الله من عامه المسلمين. ان الله بكل شيء عليم، يعلم ما يصلح عباده من توريث بعضهم من بعض في القرابه والنسب دون التوارث بالحلف، وغير ذلك مما كان في اول الاسلام."},{"id":"1236","s":9,"a":1,"at":"براءه من الله ورسوله الى الذين عاهدتم من المشركين","dt":"[1] هذه براءه من الله ورسوله، واعلان بالتخلي عن العهود التي كانت بين المسلمين والمشركين."},{"id":"1237","s":9,"a":2,"at":"فسيحوا في الارض اربعه اشهر واعلموا انكم غير معجزي الله وان الله مخزي الكافرين","dt":"[2] فسيروا -ايها المشركون- في الارض مده اربعه اشهر، تذهبون حيث شئتم امنين من المؤمنين، واعلموا انكم لن تفلتوا من العقوبه، وان الله مذل الكافرين ومورثهم العار في الدنيا، والنار في الاخره.وهذه الايه لذوي العهود المطلقه غير المؤقته، او من له عهد دون اربعه اشهر، فيكمل له اربعه اشهر، او من كان له عهد فنقضه."},{"id":"1238","s":9,"a":3,"at":"واذان من الله ورسوله الى الناس يوم الحج الاكبر ان الله بريء من المشركين ورسوله فان تبتم فهو خير لكم وان توليتم فاعلموا انكم غير معجزي الله وبشر الذين كفروا بعذاب اليم","dt":"[3] واعلام من الله ورسوله، وانذار الى الناس يوم النحر ان الله بريء من المشركين، ورسوله بريء منهم كذلك. فان رجعتم -ايها المشركون- الى الحق وتركتم شرككم فهو خير لكم، وان اعرضتم عن قبول الحق وابيتم الدخول في دين الله فاعلموا انكم لن تفلتوا من عذاب الله. وانذر -ايها الرسول- هؤلاء المعرضين عن الاسلام عذاب الله الموجع."},{"id":"1239","s":9,"a":4,"at":"الا الذين عاهدتم من المشركين ثم لم ينقصوكم شيئا ولم يظاهروا عليكم احدا فاتموا اليهم عهدهم الى مدتهم ان الله يحب المتقين","dt":"[4] ويستثنى من الحكم السابق المشركون الذين دخلوا معكم في عهد محدد بمده، ولم يخونوا العهد، ولم يعاونوا عليكم احدا من الاعداء، فاكملوا لهم عهدهم الى نهايته المحدوده. ان الله يحب المتقين الذين ادوا ما امروا به، واتقوا الشرك والخيانه، وغير ذلك من المعاصي."},{"id":"1240","s":9,"a":5,"at":"فاذا انسلخ الاشهر الحرم فاقتلوا المشركين حيث وجدتموهم وخذوهم واحصروهم واقعدوا لهم كل مرصد فان تابوا واقاموا الصلاه واتوا الزكاه فخلوا سبيلهم ان الله غفور رحيم","dt":"[5] فاذا انقضت الاشهر الاربعه التي امنتم فيها المشركين، فاعلنوا الحرب على اعداء الله حيث كانوا، واقصدوهم بالحصار في معاقلهم، وترصدوا لهم في طرقهم، فان رجعوا عن كفرهم ودخلوا الاسلام والتزموا شرائعه من اقام الصلاه واخراج الزكاه، فاتركوهم، فقد اصبحوا اخوانكم في الاسلام. ان الله غفور لمن تاب واناب، رحيم بهم."},{"id":"1241","s":9,"a":6,"at":"وان احد من المشركين استجارك فاجره حتى يسمع كلام الله ثم ابلغه مامنه ذلك بانهم قوم لا يعلمون","dt":"[6] واذا طلب احد من المشركين الذين استبيحت دماؤهم واموالهم الدخول في جوارك -ايها الرسول- ورغب في الامان، فاجبه الى طلبه حتى يسمع القران الكريم ويطلع على هدايته، ثم اعده من حيث اتى امنا؛ وذلك لاقامه الحجه عليه؛ ذلك بسبب ان الكفار قوم جاهلون بحقائق الاسلام، فربما اختاروه اذا زال الجهل عنهم."},{"id":"1242","s":9,"a":7,"at":"كيف يكون للمشركين عهد عند الله وعند رسوله الا الذين عاهدتم عند المسجد الحرام فما استقاموا لكم فاستقيموا لهم ان الله يحب المتقين","dt":"[7] لا ينبغي ان يكون للمشركين عهد عند الله وعند رسوله، الا الذين عاهدتم عند المسجد الحرام في صلح «الحديبيه» فما اقاموا على الوفاء بعهدكم فاقيموا لهم على مثل ذلك. ان الله يحب المتقين الموفين بعهودهم."},{"id":"1243","s":9,"a":8,"at":"كيف وان يظهروا عليكم لا يرقبوا فيكم الا ولا ذمه يرضونكم بافواههم وتابى قلوبهم واكثرهم فاسقون","dt":"[8] ان شان المشركين ان يلتزموا بالعهود ما دامت الغلبه لغيرهم، اما اذا شعروا بالقوه على المؤمنين فانهم لا يراعون القرابه ولا العهد، فلا يغرنكم منهم ما يعاملونكم به وقت الخوف منكم، فانهم يقولون لكم كلاما بالسنتهم؛ لترضوا عنهم، ولكن قلوبهم تابى ذلك، واكثرهم متمردون على الاسلام ناقضون للعهد."},{"id":"1244","s":9,"a":9,"at":"اشتروا بايات الله ثمنا قليلا فصدوا عن سبيله انهم ساء ما كانوا يعملون","dt":"[9] استبدلوا بايات الله عرض الدنيا التافه، فاعرضوا عن الحق ومنعوا الراغبين في الاسلام عن الدخول فيه، لقد قبح فعلهم، وساء صنيعهم."},{"id":"1245","s":9,"a":10,"at":"لا يرقبون في مؤمن الا ولا ذمه واولئك هم المعتدون","dt":"[10] ان هؤلاء المشركين حرب على الايمان واهله، فلا يقيمون وزنا لقرابه المؤمن ولا لعهده، وشانهم العدوان والظلم."},{"id":"1246","s":9,"a":11,"at":"فان تابوا واقاموا الصلاه واتوا الزكاه فاخوانكم في الدين ونفصل الايات لقوم يعلمون","dt":"[11] فان اقلعوا عن عباده غير الله، ونطقوا بكلمه التوحيد، والتزموا شرائع الاسلام من اقام الصلاه وايتاء الزكاه، فانهم اخوانكم في الاسلام. ونبين الايات، ونوضحها لقوم ينتفعون بها."},{"id":"1247","s":9,"a":12,"at":"وان نكثوا ايمانهم من بعد عهدهم وطعنوا في دينكم فقاتلوا ائمه الكفر انهم لا ايمان لهم لعلهم ينتهون","dt":"[12] وان نقض هؤلاء المشركون العهود التي ابرمتموها معهم، واظهروا الطعن في دين الاسلام، فقاتلوهم فانهم رؤساء الضلال، لا عهد لهم ولا ذمه، حتى ينتهوا عن كفرهم وعداوتهم للاسلام."},{"id":"1248","s":9,"a":13,"at":"الا تقاتلون قوما نكثوا ايمانهم وهموا باخراج الرسول وهم بدءوكم اول مره اتخشونهم فالله احق ان تخشوه ان كنتم مؤمنين","dt":"[13] لا تترددوا في قتال هؤلاء القوم الذين نقضوا عهودهم، وعملوا على اخراج الرسول من «مكه»، وهم الذين بدؤوا بايذائكم اول الامر، اتخافونهم او تخافون ملاقاتهم في الحرب؟ فالله احق ان تخافوه ان كنتم مؤمنين حقا."},{"id":"1249","s":9,"a":14,"at":"قاتلوهم يعذبهم الله بايديكم ويخزهم وينصركم عليهم ويشف صدور قوم مؤمنين","dt":"[14] يا معشر المؤمنين: قاتلوا اعداء الله يعذبهم عز وجل بايديكم، ويذلهم بالهزيمه والخزي، وينصركم عليهم، ويعل كلمته، ويشف بهزيمتهم صدوركم التي طالما لحق بها الحزن والغم من كيد هؤلاء المشركين ."},{"id":"1250","s":9,"a":15,"at":"ويذهب غيظ قلوبهم ويتوب الله على من يشاء والله عليم حكيم","dt":"[15] ويذهب عن قلوب المؤمنين الغيظ. ومن تاب من هؤلاء المعاندين فان الله يتوب على من يشاء. والله عليم بصدق توبه التائب، حكيم في تدبيره وصنعه ووضع تشريعاته لعباده."},{"id":"1251","s":9,"a":16,"at":"ام حسبتم ان تتركوا ولما يعلم الله الذين جاهدوا منكم ولم يتخذوا من دون الله ولا رسوله ولا المؤمنين وليجه والله خبير بما تعملون","dt":"[16] من سنه الله الابتلاء، فلا تظنوا يا معشر المؤمنين ان يترككم الله دون اختبار؛ ليعلم الله علما ظاهرا للخلق الذين اخلصوا في جهادهم، ولم يتخذوا غير الله ورسوله والمؤمنين بطانه واولياء. والله خبير بجميع اعمالكم ومجازيكم بها."},{"id":"1252","s":9,"a":17,"at":"ما كان للمشركين ان يعمروا مساجد الله شاهدين على انفسهم بالكفر اولئك حبطت اعمالهم وفي النار هم خالدون","dt":"[17] ليس من شان المشركين اعمار بيوت الله، وهم يعلنون كفرهم بالله ويجعلون له شركاء. هؤلاء المشركون بطلت اعمالهم يوم القيامه، ومصيرهم الخلود في النار."},{"id":"1253","s":9,"a":18,"at":"انما يعمر مساجد الله من امن بالله واليوم الاخر واقام الصلاه واتى الزكاه ولم يخش الا الله فعسى اولئك ان يكونوا من المهتدين","dt":"[18] لا يعتني ببيوت الله ويعمرها الا الذين يؤمنون بالله واليوم الاخر، ويقيمون الصلاه ويؤتون الزكاه، ولا يخافون في الله لومه لائم، هؤلاء العمار هم المهتدون الى الحق."},{"id":"1254","s":9,"a":19,"at":"اجعلتم سقايه الحاج وعماره المسجد الحرام كمن امن بالله واليوم الاخر وجاهد في سبيل الله لا يستوون عند الله والله لا يهدي القوم الظالمين","dt":"[19] اجعلتم -ايها القوم- ما تقومون به من سقي الحجيج وعماره المسجد الحرام كايمان من امن بالله واليوم الاخر وجاهد في سبيل الله؟ لا تتساوى حال المؤمنين وحال الكافرين عند الله؛ لان الله لا يقبل عملا بغير الايمان. والله سبحانه لا يوفق لاعمال الخير القوم الظالمين لانفسهم بالكفر."},{"id":"1255","s":9,"a":20,"at":"الذين امنوا وهاجروا وجاهدوا في سبيل الله باموالهم وانفسهم اعظم درجه عند الله واولئك هم الفائزون","dt":"[20] الذين امنوا بالله وتركوا دار الكفر قاصدين دار الاسلام، وبذلوا اموالهم وانفسهم في الجهاد لاعلاء كلمه الله، هؤلاء اعظم درجه عند الله، واولئك هم الفائزون برضوانه."},{"id":"1256","s":9,"a":21,"at":"يبشرهم ربهم برحمه منه ورضوان وجنات لهم فيها نعيم مقيم","dt":"[21] ان هؤلاء المؤمنين المهاجرين لهم البشرى من ربهم بالرحمه الواسعه والرضوان الذي لا سخط بعده، ومصيرهم الى جنات الخلد والنعيم الدائم."},{"id":"1257","s":9,"a":22,"at":"خالدين فيها ابدا ان الله عنده اجر عظيم","dt":"[22] ماكثين في تلك الجنان لانهايه لاقامتهم وتنعمهم، وذلك ثواب ما قدموه من الطاعات والعمل الصالح في حياتهم الدنيا. ان الله تعالى عنده اجر عظيم لمن امن وعمل صالحا بامتثال اوامره واجتناب نواهيه."},{"id":"1258","s":9,"a":23,"at":"ياايها الذين امنوا لا تتخذوا اباءكم واخوانكم اولياء ان استحبوا الكفر على الايمان ومن يتولهم منكم فاولئك هم الظالمون","dt":"[23] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه لا تتخذوا اقرباءكم -من الاباء والاخوان وغيرهم- اولياء، تفشون اليهم اسرار المسلمين، وتستشيرونهم في اموركم، ما داموا على الكفر معادين للاسلام. ومن يتخذهم اولياء ويلق اليهم الموده فقد عصى الله تعالى، وظلم نفسه ظلما عظيما."},{"id":"1259","s":9,"a":24,"at":"قل ان كان اباؤكم وابناؤكم واخوانكم وازواجكم وعشيرتكم واموال اقترفتموها وتجاره تخشون كسادها ومساكن ترضونها احب اليكم من الله ورسوله وجهاد في سبيله فتربصوا حتى ياتي الله بامره والله لا يهدي القوم الفاسقين","dt":"[24] قل -يا ايها الرسول- للمؤمنين: ان فضلتم الاباء والابناء والاخوان والزوجات والقرابات، والاموال التي جمعتموها والتجاره التي تخافون عدم رواجها والبيوت الفارهه التي اقمتم فيها، ان فضلتم ذلك على حب الله ورسوله والجهاد في سبيله فانتظروا عقاب الله ونكاله بكم. والله لا يوفق الخارجين عن طاعته."},{"id":"1260","s":9,"a":25,"at":"لقد نصركم الله في مواطن كثيره ويوم حنين اذ اعجبتكم كثرتكم فلم تغن عنكم شيئا وضاقت عليكم الارض بما رحبت ثم وليتم مدبرين","dt":"[25] لقد انزل الله نصره عليكم في مواقع كثيره عندما اخذتم بالاسباب وتوكلتم على الله. ويوم غزوه «حنين» قلتم: لن نغلب اليوم من قله، فغرتكم الكثره فلم تنفعكم، وظهر عليكم العدو فلم تجدوا ملجا في الارض الواسعه ففررتم منهزمين."},{"id":"1261","s":9,"a":26,"at":"ثم انزل الله سكينته على رسوله وعلى المؤمنين وانزل جنودا لم تروها وعذب الذين كفروا وذلك جزاء الكافرين","dt":"[26] ثم انزل الله الطمانينه على رسوله وعلى المؤمنين فثبتوا، وامدهم بجنود من الملائكه لم يروها، فنصرهم على عدوهم، وعذب الذين كفروا. وتلك عقوبه الله للصادين عن دينه، المكذبين لرسوله."},{"id":"1262","s":9,"a":27,"at":"ثم يتوب الله من بعد ذلك على من يشاء والله غفور رحيم","dt":"[27] ومن رجع عن كفره بعد ذلك ودخل الاسلام فان الله يقبل توبه من يشاء منهم، فيغفر ذنبه. والله غفور رحيم."},{"id":"1263","s":9,"a":28,"at":"ياايها الذين امنوا انما المشركون نجس فلا يقربوا المسجد الحرام بعد عامهم هذا وان خفتم عيله فسوف يغنيكم الله من فضله ان شاء ان الله عليم حكيم","dt":"[28] يا معشر المؤمنين: انما المشركون رجس وخبث فلا تمكنوهم من الاقتراب من الحرم بعد هذا العام التاسع من الهجره، وان خفتم فقرا لانقطاع تجارتهم عنكم، فان الله سيعوضكم عنها، ويكفيكم من فضله ان شاء، ان الله عليم بحالكم، حكيم في تدبير شؤونكم."},{"id":"1264","s":9,"a":29,"at":"قاتلوا الذين لا يؤمنون بالله ولا باليوم الاخر ولا يحرمون ما حرم الله ورسوله ولا يدينون دين الحق من الذين اوتوا الكتاب حتى يعطوا الجزيه عن يد وهم صاغرون","dt":"[29] ايها المسلمون: قاتلوا الكفار الذين لا يؤمنون بالله، ولا يؤمنون بالبعث والجزاء، ولا يجتنبون ما نهى الله عنه ورسوله، ولا يلتزمون احكام شريعه الاسلام، من اليهود والنصارى، حتى يدفعوا الجزيه التي تفرضونها عليهم بايديهم خاضعين اذلاء."},{"id":"1265","s":9,"a":30,"at":"وقالت اليهود عزير ابن الله وقالت النصارى المسيح ابن الله ذلك قولهم بافواههم يضاهئون قول الذين كفروا من قبل قاتلهم الله انى يؤفكون","dt":"[30] لقد اشرك اليهود بالله عندما زعموا ان عزيرا ابن الله. واشرك النصارى بالله عندما ادعوا ان المسيح ابن الله. وهذا القول اختلقوه من عند انفسهم، وهم بذلك يشابهون قول المشركين من قبلهم. قاتل الله المشركين جميعا كيف يعدلون عن الحق الى الباطل؟"},{"id":"1266","s":9,"a":31,"at":"اتخذوا احبارهم ورهبانهم اربابا من دون الله والمسيح ابن مريم وما امروا الا ليعبدوا الها واحدا لا اله الا هو سبحانه عما يشركون","dt":"[31] اتخذ اليهود والنصارى العلماء والعباد اربابا يشرعون لهم الاحكام، فيلتزمون بها ويتركون شرائع الله، واتخذوا المسيح عيسى بن مريم الها فعبدوه، وقد امرهم الله جميعا بعبادته وحده دون غيره، فهو الاله الحق لا اله الا هو. تنزه وتقدس عما يفتريه اهل الشرك والضلال."},{"id":"1267","s":9,"a":32,"at":"يريدون ان يطفئوا نور الله بافواههم ويابى الله الا ان يتم نوره ولو كره الكافرون","dt":"[32] يريد الكفار بتكذيبهم ان يبطلوا دين الاسلام، ويبطلوا حجج الله وبراهينه على توحيده الذي جاء به محمد -صلى الله عليه وسلم-، ويابى الله الا ان يتم دينه ويظهره، ويعلي كلمته، ولو كره ذلك الجاحدون."},{"id":"1268","s":9,"a":33,"at":"هو الذي ارسل رسوله بالهدى ودين الحق ليظهره على الدين كله ولو كره المشركون","dt":"[33] هو الذي ارسل رسوله محمدا -صلى الله عليه وسلم- بالقران ودين الاسلام؛ ليعليه على الاديان كلها، ولو كره المشركون دين الحق -وهو الاسلام- وظهوره على الاديان."},{"id":"1269","s":9,"a":34,"at":"ياايها الذين امنوا ان كثيرا من الاحبار والرهبان لياكلون اموال الناس بالباطل ويصدون عن سبيل الله والذين يكنزون الذهب والفضه ولا ينفقونها في سبيل الله فبشرهم بعذاب اليم","dt":"[34] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، ان كثيرا من علماء اهل الكتاب وعبادهم لياخذون اموال الناس بغير حق كالرشوه وغيرها، ويمنعون الناس من الدخول في الاسلام، ويصدون عن سبيل الله. والذين يمسكون الاموال، ولا يؤدون زكاتها، ولا يخرجون منها الحقوق الواجبه، فبشرهم بعذاب موجع."},{"id":"1270","s":9,"a":35,"at":"يوم يحمى عليها في نار جهنم فتكوى بها جباههم وجنوبهم وظهورهم هذا ما كنزتم لانفسكم فذوقوا ما كنتم تكنزون","dt":"[35] يوم القيامه توضع قطع الذهب والفضه في النار، فاذا اشتدت حرارتها احرقت بها جباه اصحابها وجنوبهم وظهورهم.وقيل لهم توبيخا: هذا مالكم الذي امسكتموه ومنعتم منه حقوق الله، فذوقوا العذاب الموجع؛ بسبب كنزكم وامساككم."},{"id":"1271","s":9,"a":36,"at":"ان عده الشهور عند الله اثنا عشر شهرا في كتاب الله يوم خلق السموات والارض منها اربعه حرم ذلك الدين القيم فلا تظلموا فيهن انفسكم وقاتلوا المشركين كافه كما يقاتلونكم كافه واعلموا ان الله مع المتقين","dt":"[36] ان عدد الشهور التي يتالف منها العام في حكم الله، وفيما كتب في اللوح المحفوظ اثنا عشر شهرا، يوم خلق السموات والارض، منها اربعه حرم؛ حرم الله فيهن القتال (هي: ذو القعده وذو الحجه والمحرم ورجب)، ذلك هو الدين المستقيم، فلا تظلموا فيهن انفسكم؛ لزياده تحريمها، وكون الظلم فيها اشد منه في غيرها، لا ان الظلم في غيرها جائز. وقاتلوا المشركين جميعا كما يقاتلونكم جميعا، واعلموا ان الله مع اهل التقوى بتاييده ونصره."},{"id":"1272","s":9,"a":37,"at":"انما النسيء زياده في الكفر يضل به الذين كفروا يحلونه عاما ويحرمونه عاما ليواطئوا عده ما حرم الله فيحلوا ما حرم الله زين لهم سوء اعمالهم والله لا يهدي القوم الكافرين","dt":"[37] ان الذي كانت تفعله العرب في الجاهليه من تحريم اربعه اشهر من السنه، عددا لا تحديدا باسماء الاشهر التي حرمها الله، فيؤخرون بعضها او يقدمونه ويجعلون مكانه من اشهر الحل ما ارادوا حسب حاجتهم الى القتال، ان ذلك زياده في الكفر، يضل الشيطان به الذين كفروا، يحلون الذي اخروا تحريمه من الاشهر الاربعه عاما، ويحرمونه عاما؛ ليوافقوا عدد الشهور الاربعه، فيحلوا ما حرم الله منها. زين لهم الشيطان الاعمال السيئه. والله لا يوفق القوم الكافرين الى الحق والصواب."},{"id":"1273","s":9,"a":38,"at":"ياايها الذين امنوا ما لكم اذا قيل لكم انفروا في سبيل الله اثاقلتم الى الارض ارضيتم بالحياه الدنيا من الاخره فما متاع الحياه الدنيا في الاخره الا قليل","dt":"[38] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه ما بالكم اذا قيل لكم: اخرجوا الى الجهاد في سبيل الله لقتال اعدائكم تكاسلتم ولزمتم مساكنكم؟ هل اثرتم حظوظكم الدنيويه على نعيم الاخره؟ فما تستمتعون به في الدنيا قليل زائل، اما نعيم الاخره الذي اعده الله للمؤمنين المجاهدين فكثير دائم."},{"id":"1274","s":9,"a":39,"at":"الا تنفروا يعذبكم عذابا اليما ويستبدل قوما غيركم ولا تضروه شيئا والله على كل شيء قدير","dt":"[39] ان لا تنفروا ايها المؤمنون الى قتال عدوكم ينزل الله عقوبته بكم، ويات بقوم اخرين ينفرون اذا استنفروا، ويطيعون الله ورسوله، ولن تضروا الله شيئا بتوليكم عن الجهاد، فهو الغني عنكم وانتم الفقراء اليه. وما يريده الله يكون لا محاله. والله على كل شيء قدير من نصر دينه ونبيه دونكم."},{"id":"1275","s":9,"a":40,"at":"الا تنصروه فقد نصره الله اذ اخرجه الذين كفروا ثاني اثنين اذ هما في الغار اذ يقول لصاحبه لا تحزن ان الله معنا فانزل الله سكينته عليه وايده بجنود لم تروها وجعل كلمه الذين كفروا السفلى وكلمه الله هي العليا والله عزيز حكيم","dt":"[40] يا معشر اصحاب رسول الله -صلى الله عليه وسلم- ان لا تنفروا معه اذا استنفركم، وان لا تنصروه، فقد ايده الله ونصره يوم اخرجه الكفار -من قريش- من بلده «مكه»، وهو ثاني اثنين (هو وابو بكر الصديق رضي الله عنه)، والجؤوهما الى نقب في جبل ثور ب«مكه»، فمكثا فيه ثلاث ليال، اذ يقول لصاحبه «ابي بكر» لما راى منه الخوف عليه: لا تحزن ان الله معنا بنصره وتاييده، فانزل الله الطمانينه في قلب رسول الله -صلى الله عليه وسلم-، واعانه بجنود لم يرها احد من البشر وهم الملائكه، فانجاه الله من عدوه واذل الله اعداءه، وجعل كلمه الذين كفروا السفلى. وكلمه الله هي العليا، وذلك باعلاء شان الاسلام. والله عزيز في ملكه، حكيم في تدبير شؤون عباده. وفي هذه الايه منقبه عظيمه لابي بكر الصديق رضي الله عنه."},{"id":"1276","s":9,"a":41,"at":"انفروا خفافا وثقالا وجاهدوا باموالكم وانفسكم في سبيل الله ذلكم خير لكم ان كنتم تعلمون","dt":"[41] اخرجوا -ايها المؤمنون- للجهاد في سبيل الله شبابا وشيوخا في العسر واليسر، على اي حال كنتم، وانفقوا اموالكم في سبيل الله، وقاتلوا بايديكم لاعلاء كلمه الله، ذلك الخروج والبذل خير لكم في حالكم ومالكم من التثاقل والامساك والتخلف، ان كنتم من اهل العلم بفضل الجهاد وثوابه عند الله فافعلوا ما امرتم به، واستجيبوا لله ورسوله."},{"id":"1277","s":9,"a":42,"at":"لو كان عرضا قريبا وسفرا قاصدا لاتبعوك ولكن بعدت عليهم الشقه وسيحلفون بالله لو استطعنا لخرجنا معكم يهلكون انفسهم والله يعلم انهم لكاذبون","dt":"[42] وبخ الله - جل جلاله - جماعه من المنافقين استاذنوا رسول الله -صلى الله عليه وسلم- في التخلف عن غزوه «تبوك»، مبينا انه لو كان خروجهم الى غنيمه قريبه سهله المنال، وسفر لا مشقه فيه لاتبعوك، ولكن لما دعوا الى قتال الروم في اطراف بلاد «الشام» في وقت الحر تخاذلوا، وتخلفوا، وسيعتذرون لتخلفهم عن الخروج، حالفين بالله بانهم لا يستطيعون ذلك، يهلكون انفسهم بالكذب والنفاق، والله يعلم انهم لكاذبون فيما يبدون لك من الاعذار."},{"id":"1278","s":9,"a":43,"at":"عفا الله عنك لم اذنت لهم حتى يتبين لك الذين صدقوا وتعلم الكاذبين","dt":"[43] عفا الله عنك -ايها النبي- عما وقع منك من ترك الاولى والاكمل، وهو اذنك للمنافقين في القعود عن الجهاد، لاي سبب اذنت لهؤلاء بالتخلف عن الغزوه، حتى يظهر لك الذين صدقوا في اعتذارهم وتعلم الكاذبين منهم في ذلك؟"},{"id":"1279","s":9,"a":44,"at":"لا يستاذنك الذين يؤمنون بالله واليوم الاخر ان يجاهدوا باموالهم وانفسهم والله عليم بالمتقين","dt":"[44] ليس من شان المؤمنين بالله ورسوله واليوم الاخر ان يستاذنوك -ايها النبي- في التخلف عن الجهاد في سبيل الله بالنفس والمال، وانما هذا من شان المنافقين. والله عليم بمن خافه فاتقاه باداء فرائضه واجتناب نواهيه."},{"id":"1280","s":9,"a":45,"at":"انما يستاذنك الذين لا يؤمنون بالله واليوم الاخر وارتابت قلوبهم فهم في ريبهم يترددون","dt":"[45] انما يطلب الاذن للتخلف عن الجهاد الذين لا يصدقون بالله ولا باليوم الاخر، ولا يعملون صالحا، وشكت قلوبهم في صحه ما جئت به -ايها النبي- من الاسلام وشرائعه، فهم في شكهم يتحيرون."},{"id":"1281","s":9,"a":46,"at":"ولو ارادوا الخروج لاعدوا له عده ولكن كره الله انبعاثهم فثبطهم وقيل اقعدوا مع القاعدين","dt":"[46] ولو اراد المنافقون الخروج معك -ايها النبي- الى الجهاد لتاهبوا له بالزاد والراحله، ولكن الله كره خروجهم فثقل عليهم الخروج؛ قضاء وقدرا، وان كان امرهم به شرعا، وقيل لهم: تخلفوا مع القاعدين من المرضى والضعفاء والنساء والصبيان."},{"id":"1282","s":9,"a":47,"at":"لو خرجوا فيكم ما زادوكم الا خبالا ولاوضعوا خلالكم يبغونكم الفتنه وفيكم سماعون لهم والله عليم بالظالمين","dt":"[47] لو خرج المنافقون معكم -ايها المؤمنون- للجهاد لنشروا الاضطراب في الصفوف والشر والفساد، ولاسرعوا السير بينكم بالنميمه والبغضاء، يريدون فتنتكم بتثبيطكم عن الجهاد في سبيل الله، وفيكم -ايها المؤمنون- عيون لهم يسمعون اخباركم، وينقلونها اليهم. والله عليم بهؤلاء المنافقين الظالمين، وسيجازيهم على ذلك."},{"id":"1283","s":9,"a":48,"at":"لقد ابتغوا الفتنه من قبل وقلبوا لك الامور حتى جاء الحق وظهر امر الله وهم كارهون","dt":"[48] لقد ابتغى المنافقون فتنه المؤمنين عن دينهم وصدهم عن سبيل الله من قبل غزوه «تبوك»، وكشف امرهم، وصرفوا لك -ايها النبي- الامور في ابطال ما جئت به، كما فعلوا يوم «احد» ويوم «الخندق»، ودبروا لك الكيد حتى جاء النصر من عند الله، واعز جنده ونصر دينه، وهم كارهون له."},{"id":"1284","s":9,"a":49,"at":"ومنهم من يقول ائذن لي ولا تفتني الا في الفتنه سقطوا وان جهنم لمحيطه بالكافرين","dt":"[49] ومن هؤلاء المنافقين من يطلب الاذن للقعود عن الجهاد ويقول: لا توقعني في الابتلاء بما يعرض لي -في حاله الخروج- من فتنه النساء. لقد سقط هؤلاء المنافقون في فتنه النفاق الكبرى. وان جهنم لمحيطه بالكافرين بالله واليوم الاخر، فلا يفلت منهم احد."},{"id":"1285","s":9,"a":50,"at":"ان تصبك حسنه تسؤهم وان تصبك مصيبه يقولوا قد اخذنا امرنا من قبل ويتولوا وهم فرحون","dt":"[50] ان يصبك -ايها النبي- سرور وغنيمه يحزن المنافقون، وان يلحق بك مكروه من هزيمه او شده يقولوا: نحن اصحاب راي وتدبير قد احتطنا لانفسنا بتخلفنا عن محمد، وينصرفوا وهم مسرورون بما صنعوا وبما اصابك من السوء."},{"id":"1286","s":9,"a":51,"at":"قل لن يصيبنا الا ما كتب الله لنا هو مولانا وعلى الله فليتوكل المؤمنون","dt":"[51] قل -ايها النبي- لهؤلاء المتخاذلين زجرا لهم وتوبيخا: لن يصيبنا الا ما قدره الله علينا وكتبه في اللوح المحفوظ، هو ناصرنا على اعدائنا، وعلى الله وحده فليعتمد المؤمنون به."},{"id":"1287","s":9,"a":52,"at":"قل هل تربصون بنا الا احدى الحسنيين ونحن نتربص بكم ان يصيبكم الله بعذاب من عنده او بايدينا فتربصوا انا معكم متربصون","dt":"[52] قل لهم -ايها النبي-: هل تنتظرون بنا الا شهاده في سبيل الله او ظفرا بكم؟ ونحن ننتظر بكم ان يصيبكم الله بعقوبه من عنده عاجله تهلككم او بايدينا فنقتلكم، فانتظروا انا معكم منتظرون ما الله فاعل بكل فريق منا ومنكم."},{"id":"1288","s":9,"a":53,"at":"قل انفقوا طوعا او كرها لن يتقبل منكم انكم كنتم قوما فاسقين","dt":"[53] قل -ايها النبي- للمنافقين: انفقوا اموالكم كيف شئتم، وعلى اي حال شئتم طائعين او كارهين، لن يقبل الله منكم نفقاتكم؛ لانكم قوم خارجون عن دين الله وطاعته."},{"id":"1289","s":9,"a":54,"at":"وما منعهم ان تقبل منهم نفقاتهم الا انهم كفروا بالله وبرسوله ولا ياتون الصلاه الا وهم كسالى ولا ينفقون الا وهم كارهون","dt":"[54] وسبب عدم قبول نفقاتهم انهم اضمروا الكفر بالله عز وجل وتكذيب رسوله محمد -صلى الله عليه وسلم-، ولا ياتون الصلاه الا وهم متثاقلون، ولا ينفقون الاموال الا وهم كارهون، فهم لا يرجون ثواب هذه الفرائض، ولا يخشون على تركها عقابا؛ بسبب كفرهم."},{"id":"1290","s":9,"a":55,"at":"فلا تعجبك اموالهم ولا اولادهم انما يريد الله ليعذبهم بها في الحياه الدنيا وتزهق انفسهم وهم كافرون","dt":"[55] فلا تعجبك -ايها النبي- اموال هؤلاء المنافقين ولا اولادهم؛ انما يريد الله ان يعذبهم بها في الحياه الدنيا بالتعب في تحصيلها وبالمصائب التي تقع فيها -حيث لا يحتسبون ذلك عند الله- وتخرج انفسهم، فيموتوا على كفرهم بالله ورسوله."},{"id":"1291","s":9,"a":56,"at":"ويحلفون بالله انهم لمنكم وما هم منكم ولكنهم قوم يفرقون","dt":"[56] ويحلف هؤلاء المنافقون بالله لكم ايها المؤمنون -كذبا وباطلا- انهم لمنكم، وليسوا منكم، ولكنهم قوم يخافون فيحلفون تقيه لكم."},{"id":"1292","s":9,"a":57,"at":"لو يجدون ملجا او مغارات او مدخلا لولوا اليه وهم يجمحون","dt":"[57] لو يجد هؤلاء المنافقون مامنا وحصنا يحفظهم، او كهفا في جبل يؤويهم، او نفقا في الارض ينجيهم منكم، لانصرفوا اليه وهم يسرعون."},{"id":"1293","s":9,"a":58,"at":"ومنهم من يلمزك في الصدقات فان اعطوا منها رضوا وان لم يعطوا منها اذا هم يسخطون","dt":"[58] ومن المنافقين من يعيبك في قسمه الصدقات، فان نالهم نصيب منها رضوا وسكتوا، وان لم يصبهم حظ منها سخطوا عليك وعابوك."},{"id":"1294","s":9,"a":59,"at":"ولو انهم رضوا ما اتاهم الله ورسوله وقالوا حسبنا الله سيؤتينا الله من فضله ورسوله انا الى الله راغبون","dt":"[59] ولو ان هؤلاء الذين يعيبونك في قسمه الصدقات رضوا بما قسم الله ورسوله لهم، وقالوا: حسبنا الله، سيؤتينا الله من فضله، ويعطينا رسوله مما اتاه الله، انا نرغب ان يوسع الله علينا، فيغنينا عن الصدقه وعن صدقات الناس. لو فعلوا ذلك لكان خيرا لهم واجدى."},{"id":"1295","s":9,"a":60,"at":"انما الصدقات للفقراء والمساكين والعاملين عليها والمؤلفه قلوبهم وفي الرقاب والغارمين وفي سبيل الله وابن السبيل فريضه من الله والله عليم حكيم","dt":"[60] انما تعطى الزكوات الواجبه للمحتاجين الذين لا يملكون شيئا، وللمساكين الذين لا يملكون ما يكفيهم و يسد حاجتهم، وللسعاه الذين يجمعونها، وللذين تؤلفون قلوبهم بها ممن يرجى اسلامه او قوه ايمانه او نفعه للمسلمين، او تدفعون بها شر احد عن المسلمين، وتعطى في عتق رقاب الارقاء والمكاتبين، وتعطى للغارمين لاصلاح ذات البين، ولمن اثقلتهم الديون في غير فساد ولا تبذير فاعسروا، وللغزاه في سبيل الله، وللمسافر الذي انقطعت به النفقه، هذه القسمه فريضه فرضها الله وقدرها. والله عليم بمصالح عباده، حكيم في تدبيره وشرعه."},{"id":"1296","s":9,"a":61,"at":"ومنهم الذين يؤذون النبي ويقولون هو اذن قل اذن خير لكم يؤمن بالله ويؤمن للمؤمنين ورحمه للذين امنوا منكم والذين يؤذون رسول الله لهم عذاب اليم","dt":"[61] ومن المنافقين قوم يؤذون رسول الله -صلى الله عليه وسلم- بالكلام، ويقولون: انه يستمع لكل ما يقال له فيصدقه، قل لهم -ايها النبي-: ان محمدا هو اذن تستمع لكل خير، يؤمن بالله ويصدق المؤمنين فيما يخبرونه، وهو رحمه لمن اتبعه واهتدى بهداه. والذين يؤذون رسول الله محمدا -صلى الله عليه وسلم- باي نوع من انواع الايذاء، لهم عذاب مؤلم موجع."},{"id":"1297","s":9,"a":62,"at":"يحلفون بالله لكم ليرضوكم والله ورسوله احق ان يرضوه ان كانوا مؤمنين","dt":"[62] يحلف المنافقون الايمان الكاذبه، ويقدمون الاعذار الملفقه؛ ليرضوا المؤمنين، والله ورسوله احق واولى ان يرضوهما بالايمان بهما وطاعتهما، ان كانوا مؤمنين حقا."},{"id":"1298","s":9,"a":63,"at":"الم يعلموا انه من يحادد الله ورسوله فان له نار جهنم خالدا فيها ذلك الخزي العظيم","dt":"[63] الم يعلم هؤلاء المنافقون ان مصير الذين يحاربون الله ورسوله نار جهنم، لهم العذاب الدائم فيها؟ ذلك المصير هو الهوان والذل العظيم، ومن المحاربه اذيه رسول الله -صلى الله عليه وسلم- بسبه والقدح فيه، عياذا بالله من ذلك."},{"id":"1299","s":9,"a":64,"at":"يحذر المنافقون ان تنزل عليهم سوره تنبئهم بما في قلوبهم قل استهزئوا ان الله مخرج ما تحذرون","dt":"[64] يخاف المنافقون ان تنزل في شانهم سوره تخبرهم بما يضمرونه في قلوبهم من الكفر، قل لهم -ايها النبي-: استمروا على ما انتم عليه من الاستهزاء والسخريه، ان الله مخرج حقيقه ما تحذرون."},{"id":"1300","s":9,"a":65,"at":"ولئن سالتهم ليقولن انما كنا نخوض ونلعب قل ابالله واياته ورسوله كنتم تستهزئون","dt":"[65] ولئن سالتهم -ايها النبي- عما قالوا من القدح في حقك وحق اصحابك ليقولن: انما كنا نتحدث بكلام لا قصد لنا به، قل لهم -ايها النبي-: ابالله عز وجل واياته ورسوله كنتم تستهزئون؟"},{"id":"1301","s":9,"a":66,"at":"لا تعتذروا قد كفرتم بعد ايمانكم ان نعف عن طائفه منكم نعذب طائفه بانهم كانوا مجرمين","dt":"[66] لا تعتذروا -معشر المنافقين- فلا جدوى من اعتذاركم، قد كفرتم بهذا المقال الذي استهزاتم به، ان نعف عن جماعه منكم طلبت العفو واخلصت في توبتها، نعذب جماعه اخرى بسبب اجرامهم بهذه المقاله الفاجره الخاطئه."},{"id":"1302","s":9,"a":67,"at":"المنافقون والمنافقات بعضهم من بعض يامرون بالمنكر وينهون عن المعروف ويقبضون ايديهم نسوا الله فنسيهم ان المنافقين هم الفاسقون","dt":"[67] المنافقون والمنافقات صنف واحد في اعلانهم الايمان واستبطانهم الكفر، يامرون بالكفر بالله ومعصيه رسوله وينهون عن الايمان والطاعه، ويمسكون ايديهم عن النفقه في سبيل الله، نسوا الله فلا يذكرونه، فنسيهم من رحمته، فلم يوفقهم الى خير. ان المنافقين هم الخارجون عن الايمان بالله ورسوله."},{"id":"1303","s":9,"a":68,"at":"وعد الله المنافقين والمنافقات والكفار نار جهنم خالدين فيها هي حسبهم ولعنهم الله ولهم عذاب مقيم","dt":"[68] وعد الله المنافقين والمنافقات والكفار بان مصيرهم الى نار جهنم خالدين فيها ابدا، هي كافيتهم؛ عقابا على كفرهم بالله، وطردهم الله من رحمته، ولهم عذاب دائم."},{"id":"1304","s":9,"a":69,"at":"كالذين من قبلكم كانوا اشد منكم قوه واكثر اموالا واولادا فاستمتعوا بخلاقهم فاستمتعتم بخلاقكم كما استمتع الذين من قبلكم بخلاقهم وخضتم كالذي خاضوا اولئك حبطت اعمالهم في الدنيا والاخره واولئك هم الخاسرون","dt":"[69] ان افعالكم -معشر المنافقين- من الاستهزاء والكفر كافعال الامم السابقه التي كانت على جانب من القوه والمال والاولاد اشد منكم، فاطمانوا الى الحياه الدنيا، وتمتعوا بما فيها من الحظوظ والملذات، فاستمتعتم - ايها المنافقون - بنصيبكم من الشهوات الفانيه كاستمتاع الذين من قبلكم بحظوظهم الفانيه، وخضتم بالكذب على الله كخوض تلك الامم قبلكم؛ اولئك الموصوفون بهذه الاخلاق هم الذين ذهبت حسناتهم في الدنيا والاخره، واولئك هم الخاسرون ببيعهم نعيم الاخره بحظوظهم من الدنيا."},{"id":"1305","s":9,"a":70,"at":"الم ياتهم نبا الذين من قبلهم قوم نوح وعاد وثمود وقوم ابراهيم واصحاب مدين والمؤتفكات اتتهم رسلهم بالبينات فما كان الله ليظلمهم ولكن كانوا انفسهم يظلمون","dt":"[70] الم يات هؤلاء المنافقين خبر الذين مضوا، من قوم نوح وقبيله عاد وقبيله ثمود وقوم ابراهيم واصحاب «مدين» وقوم لوط - الذين انقلبت قراهم بهم - عندما جاءهم المرسلون بالوحي وبايات الله فكذبوهم؟ فانزل الله بهؤلاء جميعا عذابه؛ انتقاما منهم لسوء عملهم، فما كان الله ليظلمهم، ولكن كانوا هم الظالمين لانفسهم بالتكذيب والمخالفه."},{"id":"1306","s":9,"a":71,"at":"والمؤمنون والمؤمنات بعضهم اولياء بعض يامرون بالمعروف وينهون عن المنكر ويقيمون الصلاه ويؤتون الزكاه ويطيعون الله ورسوله اولئك سيرحمهم الله ان الله عزيز حكيم","dt":"[71] والمؤمنون والمؤمنات بالله ورسوله بعضهم انصار بعض، يامرون الناس بالايمان والعمل الصالح، وينهونهم عن الكفر والمعاصي، ويؤدون الصلاه، ويعطون الزكاه، ويطيعون الله ورسوله، وينتهون عما نهوا عنه، اولئك سيرحمهم الله فينقذهم من عذابه ويدخلهم جنته. ان الله عزيز في ملكه، حكيم في تشريعاته واحكامه."},{"id":"1307","s":9,"a":72,"at":"وعد الله المؤمنين والمؤمنات جنات تجري من تحتها الانهار خالدين فيها ومساكن طيبه في جنات عدن ورضوان من الله اكبر ذلك هو الفوز العظيم","dt":"[72] وعد الله المؤمنين والمؤمنات بالله ورسوله جنات تجري من تحت قصورها واشجارها الانهار، ماكثين فيها ابدا، لا يزول عنهم نعيمها، ومساكن حسنه البناء طيبه القرار في جنات اقامه، ورضوان من الله اكبر واعظم مما هم فيه من النعيم. ذلك الوعد بثواب الاخره هو الفلاح العظيم."},{"id":"1308","s":9,"a":73,"at":"ياايها النبي جاهد الكفار والمنافقين واغلظ عليهم وماواهم جهنم وبئس المصير","dt":"[73] يا ايها النبي جاهد الكفار بالسيف والمنافقين باللسان والحجه، واشدد على كلا الفريقين، ومقرهم جهنم، وبئس المصير مصيرهم."},{"id":"1309","s":9,"a":74,"at":"يحلفون بالله ما قالوا ولقد قالوا كلمه الكفر وكفروا بعد اسلامهم وهموا بما لم ينالوا وما نقموا الا ان اغناهم الله ورسوله من فضله فان يتوبوا يك خيرا لهم وان يتولوا يعذبهم الله عذابا اليما في الدنيا والاخره وما لهم في الارض من ولي ولا نصير","dt":"[74] يحلف المنافقون بالله انهم ما قالوا شيئا يسيء الى الرسول والى المسلمين، انهم لكاذبون؛ فلقد قالوا كلمه الكفر وارتدوا بها عن الاسلام، وحاولوا الاضرار برسول الله محمد -صلى الله عليه وسلم-، فلم يمكنهم الله من ذلك، وما وجد المنافقون شيئا يعيبونه، وينتقدونه، الا ان الله -تعالى- تفضل عليهم، فاغناهم بما فتح على نبيه -صلى الله عليه وسلم- من الخير والبركه، فان يرجع هؤلاء الكفار الى الايمان والتوبه فهو خير لهم، وان يعرضوا، او يستمروا على حالهم، يعذبهم الله العذاب الموجع في الدنيا على ايدي المؤمنين، وفي الاخره بنار جهنم، وليس لهم منقذ ينقذهم ولا ناصر يدفع عنهم سوء العذاب."},{"id":"1310","s":9,"a":75,"at":"ومنهم من عاهد الله لئن اتانا من فضله لنصدقن ولنكونن من الصالحين","dt":"[75] ومن فقراء المنافقين من يقطع العهد على نفسه: لئن اعطاه الله المال ليصدقن منه، وليعملن ما يعمل الصالحون في اموالهم، وليسيرن في طريق الصلاح."},{"id":"1311","s":9,"a":76,"at":"فلما اتاهم من فضله بخلوا به وتولوا وهم معرضون","dt":"[76] فلما اعطاهم الله من فضله بخلوا باعطاء الصدقه وبانفاق المال في الخير، وتولوا وهم معرضون عن الاسلام."},{"id":"1312","s":9,"a":77,"at":"فاعقبهم نفاقا في قلوبهم الى يوم يلقونه بما اخلفوا الله ما وعدوه وبما كانوا يكذبون","dt":"[77] فكان جزاء صنيعهم وعاقبتهم ان زادهم نفاقا على نفاقهم، لا يستطيعون التخلص منه الى يوم الحساب؛ وذلك بسبب اخلافهم الوعد الذي قطعوه على انفسهم، وبسبب نفاقهم وكذبهم."},{"id":"1313","s":9,"a":78,"at":"الم يعلموا ان الله يعلم سرهم ونجواهم وان الله علام الغيوب","dt":"[78] الم يعلم هؤلاء المنافقون ان الله يعلم ما يخفونه في انفسهم وما يتحدثون به في مجالسهم من الكيد والمكر، وان الله علام الغيوب؟ فسيجازيهم على اعمالهم التي احصاها عليهم."},{"id":"1314","s":9,"a":79,"at":"الذين يلمزون المطوعين من المؤمنين في الصدقات والذين لا يجدون الا جهدهم فيسخرون منهم سخر الله منهم ولهم عذاب اليم","dt":"[79] ومع بخل المنافقين لا يسلم المتصدقون من اذاهم؛ فاذا تصدق الاغنياء بالمال الكثير عابوهم واتهموهم بالرياء، واذا تصدق الفقراء بما في طاقتهم استهزؤوا بهم، وقالوا -سخريه منهم-: ماذا تجدي صدقتهم هذه؟ سخر الله من هؤلاء المنافقين، ولهم عذاب مؤلم موجع."},{"id":"1315","s":9,"a":80,"at":"استغفر لهم او لا تستغفر لهم ان تستغفر لهم سبعين مره فلن يغفر الله لهم ذلك بانهم كفروا بالله ورسوله والله لا يهدي القوم الفاسقين","dt":"[80] استغفر -ايها الرسول- للمنافقين او لا تستغفر لهم، فلن يغفر الله لهم، مهما كثر استغفارك لهم وتكرر؛ لانهم كفروا بالله ورسوله. والله سبحانه وتعالى لا يوفق للهدى الخارجين عن طاعته."},{"id":"1316","s":9,"a":81,"at":"فرح المخلفون بمقعدهم خلاف رسول الله وكرهوا ان يجاهدوا باموالهم وانفسهم في سبيل الله وقالوا لا تنفروا في الحر قل نار جهنم اشد حرا لو كانوا يفقهون","dt":"[81] فرح المخلفون الذين تخلفوا عن رسول الله -صلى الله عليه وسلم- بقعودهم في «المدينه» مخالفين لرسول الله -صلى الله عليه وسلم-، وكرهوا ان يجاهدوا معه باموالهم وانفسهم في سبيل الله، وقال بعضهم لبعض: لا تنفروا في الحر، وكانت غزوه «تبوك» في وقت شده الحر. قل لهم -ايها الرسول-: نار جهنم اشد حرا، لو كانوا يعلمون ذلك."},{"id":"1317","s":9,"a":82,"at":"فليضحكوا قليلا وليبكوا كثيرا جزاء بما كانوا يكسبون","dt":"[82] فليضحك هؤلاء المنافقون الذين تخلفوا عن رسول الله في غزوه «تبوك» قليلا في حياتهم الدنيا الفانيه، وليبكوا كثيرا في نار جهنم؛ جزاء بما كانوا يكسبون في الدنيا من النفاق والكفر."},{"id":"1318","s":9,"a":83,"at":"فان رجعك الله الى طائفه منهم فاستاذنوك للخروج فقل لن تخرجوا معي ابدا ولن تقاتلوا معي عدوا انكم رضيتم بالقعود اول مره فاقعدوا مع الخالفين","dt":"[83] فان ردك الله -ايها الرسول- من غزوتك الى جماعه من المنافقين الثابتين على النفاق، فاستاذنوك للخروج معك الى غزوه اخرى بعد غزوه «تبوك» فقل لهم: لن تخرجوا معي ابدا في غزوه من الغزوات، ولن تقاتلوا معي عدوا من الاعداء؛ انكم رضيتم بالقعود اول مره، فاقعدوا مع الذين تخلفوا عن الجهاد مع رسول الله -صلى الله عليه وسلم-."},{"id":"1319","s":9,"a":84,"at":"ولا تصل على احد منهم مات ابدا ولا تقم على قبره انهم كفروا بالله ورسوله وماتوا وهم فاسقون","dt":"[84] ولا تصل -ايها الرسول- ابدا على احد مات من المنافقين، ولا تقم على قبره لتدعو له؛ لانهم كفروا بالله تعالى وبرسوله -صلى الله عليه وسلم- وماتوا وهم فاسقون. وهذا حكم عام في كل من علم نفاقه."},{"id":"1320","s":9,"a":85,"at":"ولا تعجبك اموالهم واولادهم انما يريد الله ان يعذبهم بها في الدنيا وتزهق انفسهم وهم كافرون","dt":"[85] ولا تعجبك -ايها الرسول- اموال هؤلاء المنافقين واولادهم، انما يريد الله ان يعذبهم بها في الدنيا بمكابدتهم الشدائد في شانها، وبموتهم على كفرهم بالله ورسوله."},{"id":"1321","s":9,"a":86,"at":"واذا انزلت سوره ان امنوا بالله وجاهدوا مع رسوله استاذنك اولو الطول منهم وقالوا ذرنا نكن مع القاعدين","dt":"[86] واذا انزلت سوره على محمد -صلى الله عليه وسلم- تامر بالايمان بالله والاخلاص له والجهاد مع رسول الله، طلب الاذن منك -ايها الرسول- اولو اليسار من المنافقين، وقالوا: اتركنا مع القاعدين العاجزين عن الخروج."},{"id":"1322","s":9,"a":87,"at":"رضوا بان يكونوا مع الخوالف وطبع على قلوبهم فهم لا يفقهون","dt":"[87] رضي هؤلاء المنافقون لانفسهم بالعار، وهو ان يقعدوا في البيوت مع النساء والصبيان واصحاب الاعذار، وختم الله على قلوبهم؛ بسبب نفاقهم وتخلفهم عن الجهاد والخروج مع رسول الله -صلى الله عليه وسلم- في سبيل الله، فهم لا يفقهون ما فيه صلاحهم ورشادهم."},{"id":"1323","s":9,"a":88,"at":"لكن الرسول والذين امنوا معه جاهدوا باموالهم وانفسهم واولئك لهم الخيرات واولئك هم المفلحون","dt":"[88] ان تخلف هؤلاء المنافقون عن الغزو، فقد جاهد رسول الله -صلى الله عليه وسلم- والمؤمنون معه باموالهم وانفسهم، واولئك لهم النصر والغنيمه في الدنيا، والجنه والكرامه في الاخره، واولئك هم الفائزون."},{"id":"1324","s":9,"a":89,"at":"اعد الله لهم جنات تجري من تحتها الانهار خالدين فيها ذلك الفوز العظيم","dt":"[89] اعد الله لهم يوم القيامه جنات تجري من تحت قصورها واشجارها الانهار ماكثين فيها ابدا. ذلك هو الفلاح العظيم."},{"id":"1325","s":9,"a":90,"at":"وجاء المعذرون من الاعراب ليؤذن لهم وقعد الذين كذبوا الله ورسوله سيصيب الذين كفروا منهم عذاب اليم","dt":"[90] وجاء جماعه من احياء العرب حول «المدينه» يعتذرون الى رسول الله -صلى الله عليه وسلم-، ويبينون له ما هم فيه من الضعف وعدم القدره على الخروج للغزو، وقعد قوم بغير عذر اظهروه، جراه على رسول الله -صلى الله عليه وسلم-. سيصيب الذين كفروا من هؤلاء عذاب اليم في الدنيا بالقتل وغيره، وفي الاخره بالنار."},{"id":"1326","s":9,"a":91,"at":"ليس على الضعفاء ولا على المرضى ولا على الذين لا يجدون ما ينفقون حرج اذا نصحوا لله ورسوله ما على المحسنين من سبيل والله غفور رحيم","dt":"[91] ليس على اهل الاعذار، من الضعفاء والمرضى والفقراء الذين لا يملكون من المال ما يتجهزون به للخروج، اثم في القعود اذا اخلصوا لله ورسوله، وعملوا بشرعه، ما على من احسن ممن منعه العذر عن الجهاد مع رسول الله -صلى الله عليه وسلم-، وهو ناصح لله ولرسوله من طريق يعاقب من قبله ويؤاخذ عليه. والله غفور للمحسنين، رحيم بهم."},{"id":"1327","s":9,"a":92,"at":"ولا على الذين اذا ما اتوك لتحملهم قلت لا اجد ما احملكم عليه تولوا واعينهم تفيض من الدمع حزنا الا يجدوا ما ينفقون","dt":"[92] وكذلك لا اثم على الذين اذا ما جاؤوك يطلبون ان تعينهم بحملهم الى الجهاد قلت لهم: لا اجد ما احملكم عليه من الدواب، فانصرفوا عنك، وقد فاضت اعينهم دمعا اسفا على ما فاتهم من شرف الجهاد وثوابه؛ لانهم لم يجدوا ما ينفقون، وما يحملهم لو خرجوا للجهاد في سبيل الله."},{"id":"1328","s":9,"a":93,"at":"انما السبيل على الذين يستاذنونك وهم اغنياء رضوا بان يكونوا مع الخوالف وطبع الله على قلوبهم فهم لا يعلمون","dt":"[93] انما الاثم واللوم على الاغنياء الذين جاؤوك -ايها الرسول- يطلبون الاذن بالتخلف، وهم المنافقون الاغنياء، اختاروا لانفسهم القعود مع النساء واهل الاعذار، وختم الله على قلوبهم بالنفاق، فلا يدخلها ايمان، فهم لا يعلمون سوء عاقبتهم بتخلفهم عنك وتركهم الجهاد معك."},{"id":"1329","s":9,"a":94,"at":"يعتذرون اليكم اذا رجعتم اليهم قل لا تعتذروا لن نؤمن لكم قد نبانا الله من اخباركم وسيرى الله عملكم ورسوله ثم تردون الى عالم الغيب والشهاده فينبئكم بما كنتم تعملون","dt":"[94] يعتذر اليكم -ايها المؤمنون- هؤلاء المتخلفون عن جهاد المشركين بالاكاذيب عندما تعودون من جهادكم من غزوه «تبوك»، قل لهم -ايها الرسول-: لا تعتذروا لن نصدقكم فيما تقولون، قد نبانا الله من امركم ما حقق لدينا كذبكم، وسيرى الله عملكم ورسوله، ان كنتم تتوبون من نفاقكم، او تقيمون عليه، وسيظهر للناس اعمالكم في الدنيا، ثم ترجعون بعد مماتكم الى الذي لا تخفى عليه بواطن اموركم وظواهرها، فيخبركم باعمالكم كلها، ويجازيكم عليها."},{"id":"1330","s":9,"a":95,"at":"سيحلفون بالله لكم اذا انقلبتم اليهم لتعرضوا عنهم فاعرضوا عنهم انهم رجس وماواهم جهنم جزاء بما كانوا يكسبون","dt":"[95] سيحلف لكم المنافقون بالله -كاذبين معتذرين- اذا رجعتم اليهم من الغزو؛ لتتركوهم دون مساءله، فاجتنبوهم واعرضوا عنهم احتقارا لهم، انهم خبثاء البواطن، ومكانهم الذي ياوون اليه في الاخره نار جهنم؛ جزاء بما كانوا يكسبون من الاثام والخطايا."},{"id":"1331","s":9,"a":96,"at":"يحلفون لكم لترضوا عنهم فان ترضوا عنهم فان الله لا يرضى عن القوم الفاسقين","dt":"[96] يحلف لكم -ايها المؤمنون- هؤلاء المنافقون كذبا؛ لترضوا عنهم، فان رضيتم عنهم -لانكم لا تعلمون كذبهم- فان الله لا يرضى عن هؤلاء ولا غيرهم ممن استمروا على الفسوق والخروج عن طاعه الله ورسوله."},{"id":"1332","s":9,"a":97,"at":"الاعراب اشد كفرا ونفاقا واجدر الا يعلموا حدود ما انزل الله على رسوله والله عليم حكيم","dt":"[97] الاعراب سكان الباديه اشد كفرا ونفاقا من اهل الحاضره، وذلك لجفائهم وقسوه قلوبهم وبعدهم عن العلم والعلماء ومجالس الوعظ والذكر، فهم لذلك احق بان لا يعلموا حدود الدين، وما انزل الله من الشرائع والاحكام. والله عليم بحال هؤلاء جميعا، حكيم في تدبيره لامور عباده."},{"id":"1333","s":9,"a":98,"at":"ومن الاعراب من يتخذ ما ينفق مغرما ويتربص بكم الدوائر عليهم دائره السوء والله سميع عليم","dt":"[98] ومن الاعراب من يحتسب ما ينفق في سبيل الله غرامه وخساره لا يرجو له ثوابا، ولا يدفع عن نفسه عقابا، وينتظر بكم الحوادث والافات، ولكن السوء دائر عليهم لا بالمسلمين. والله سميع لما يقولون عليم بنياتهم الفاسده."},{"id":"1334","s":9,"a":99,"at":"ومن الاعراب من يؤمن بالله واليوم الاخر ويتخذ ما ينفق قربات عند الله وصلوات الرسول الا انها قربه لهم سيدخلهم الله في رحمته ان الله غفور رحيم","dt":"[99] ومن الاعراب من يؤمن بالله ويقر بوحدانيته وبالبعث بعد الموت، والثواب والعقاب، ويحتسب ما ينفق من نفقه في جهاد المشركين قاصدا بها رضا الله ومحبته، ويجعلها وسيله الى دعاء الرسول -صلى الله عليه وسلم- له، الا ان هذه الاعمال تقربهم الى الله تعالى، سيدخلهم الله في جنته. ان الله غفور لما فعلوا من السيئات، رحيم بهم."},{"id":"1335","s":9,"a":100,"at":"والسابقون الاولون من المهاجرين والانصار والذين اتبعوهم باحسان رضي الله عنهم ورضوا عنه واعد لهم جنات تجري تحتها الانهار خالدين فيها ابدا ذلك الفوز العظيم","dt":"[100] والذين سبقوا الناس اولا الى الايمان بالله ورسوله من المهاجرين الذين هجروا قومهم وعشيرتهم وانتقلوا الى دار الاسلام، والانصار الذين نصروا رسول الله -صلى الله عليه وسلم- على اعدائه الكفار، والذين اتبعوهم باحسان في الاعتقاد والاقوال والاعمال؛ طلبا لمرضاه الله سبحانه وتعالى، اولئك الذين رضي الله عنهم لطاعتهم الله ورسوله، ورضوا عنه لما اجزل لهم من الثواب على طاعتهم وايمانهم، واعد لهم جنات تجري تحت قصورها واشجارها الانهار خالدين فيها ابدا، ذلك هو الفلاح العظيم.وفي هذه الايه تزكيه للصحابه -رضي الله عنهم- وتعديل لهم، وثناء عليهم؛ ولهذا فان توقيرهم من اصول الايمان."},{"id":"1336","s":9,"a":101,"at":"وممن حولكم من الاعراب منافقون ومن اهل المدينه مردوا على النفاق لا تعلمهم نحن نعلمهم سنعذبهم مرتين ثم يردون الى عذاب عظيم","dt":"[101] ومن القوم الذين حول «المدينه» اعراب منافقون، ومن اهل «المدينه» منافقون اقاموا على النفاق، وازدادوا فيه طغيانا، بحيث يخفى عليك -ايها الرسول- امرهم، نحن نعلمهم، سنعذبهم مرتين: بالقتل والسبي والفضيحه في الدنيا، وبعذاب القبر بعد الموت، ثم يردون يوم القيامه الى عذاب عظيم في نار جهنم."},{"id":"1337","s":9,"a":102,"at":"واخرون اعترفوا بذنوبهم خلطوا عملا صالحا واخر سيئا عسى الله ان يتوب عليهم ان الله غفور رحيم","dt":"[102] واخرون من اهل «المدينه» وممن حولها، اعترفوا بذنوبهم وندموا عليها وتابوا منها، خلطوا العمل الصالح -وهو التوبه والندم والاعتراف بالذنب، وغير ذلك من الاعمال الصالحه -باخر سيئ- وهو التخلف عن رسول الله -صلى الله عليه وسلم- وغيره من الاعمال السيئه- عسى الله ان يوفقهم للتوبه ويقبلها منهم. ان الله غفور لعباده، رحيم بهم."},{"id":"1338","s":9,"a":103,"at":"خذ من اموالهم صدقه تطهرهم وتزكيهم بها وصل عليهم ان صلاتك سكن لهم والله سميع عليم","dt":"[103] خذ -ايها النبي- من اموال هؤلاء التائبين، الذين خلطوا عملا صالحا واخر سيئا صدقه تطهرهم من دنس ذنوبهم، وترفعهم عن منازل المنافقين الى منازل المخلصين، وادع لهم بالمغفره لذنوبهم واستغفر لهم منها، ان دعاءك واستغفارك رحمه وطمانينه لهم. والله سميع لكل دعاء وقول، عليم باحوال العباد ونياتهم، وسيجازي كل عامل بعمله."},{"id":"1339","s":9,"a":104,"at":"الم يعلموا ان الله هو يقبل التوبه عن عباده وياخذ الصدقات وان الله هو التواب الرحيم","dt":"[104] الم يعلم هؤلاء المتخلفون عن الجهاد وغيرهم ان الله وحده هو الذي يقبل توبه عباده، ويقبل الصدقات ويثيب عليها، وان الله هو التواب على عباده اذا رجعوا الى طاعته، الرحيم بهم اذا انابوا الى رضاه؟"},{"id":"1340","s":9,"a":105,"at":"وقل اعملوا فسيرى الله عملكم ورسوله والمؤمنون وستردون الى عالم الغيب والشهاده فينبئكم بما كنتم تعملون","dt":"[105] وقل -ايها النبي- لهؤلاء المتخلفين عن الجهاد: اعملوا لله بما يرضيه من طاعته، واداء فرائضه، واجتناب المعاصي، فسيرى الله عملكم ورسوله والمؤمنون، وسيتبين امركم، وسترجعون يوم القيامه الى من يعلم سركم وجهركم، فيخبركم بما كنتم تعملون. وفي هذا تهديد ووعيد لمن استمر على باطله وطغيانه."},{"id":"1341","s":9,"a":106,"at":"واخرون مرجون لامر الله اما يعذبهم واما يتوب عليهم والله عليم حكيم","dt":"[106] ومن هؤلاء المتخلفين عنكم -ايها المؤمنون- في غزوه «تبوك» اخرون مؤخرون؛ ليقضي الله فيهم ما هو قاض. وهؤلاء هم الذين ندموا على ما فعلوا، وهم: مراره بن الربيع، وكعب بن مالك، وهلال بن اميه، اما يعذبهم الله، واما يعفو عنهم. والله عليم بمن يستحق العقوبه او العفو، حكيم في كل اقواله وافعاله."},{"id":"1342","s":9,"a":107,"at":"والذين اتخذوا مسجدا ضرارا وكفرا وتفريقا بين المؤمنين وارصادا لمن حارب الله ورسوله من قبل وليحلفن ان اردنا الا الحسنى والله يشهد انهم لكاذبون","dt":"[107] والمنافقون الذين بنوا مسجدا؛ مضاره للمؤمنين وكفرا بالله وتفريقا بين المؤمنين؛ ليصلي فيه بعضهم ويترك مسجد «قباء» الذي يصلي فيه المسلمون، فيختلف المسلمون ويتفرقوا بسبب ذلك، وانتظارا لمن حارب الله ورسوله من قبل -وهو ابو عامر الراهب الفاسق- ليكون مكانا للكيد للمسلمين، وليحلفن هؤلاء المنافقون انهم ما ارادوا ببنائه الا الخير والرفق بالمسلمين، والتوسعه على الضعفاء العاجزين عن السير الى مسجد «قباء»، والله يشهد انهم لكاذبون فيما يحلفون عليه. وقد هدم المسجد واحرق."},{"id":"1343","s":9,"a":108,"at":"لا تقم فيه ابدا لمسجد اسس على التقوى من اول يوم احق ان تقوم فيه فيه رجال يحبون ان يتطهروا والله يحب المطهرين","dt":"[108] لا تقم -ايها النبي- للصلاه في ذلك المسجد ابدا؛ فان المسجد الذي اسس على التقوى من اول يوم -وهو مسجد «قباء»- اولى ان تقوم فيه للصلاه، ففي هذا المسجد رجال يحبون ان يتطهروا بالماء من النجاسات والاقذار، كما يتطهرون بالتورع والاستغفار من الذنوب والمعاصي. والله يحب المتطهرين. واذا كان مسجد «قباء» قد اسس على التقوى من اول يوم، فمسجد رسول الله -صلى الله عليه وسلم-، كذلك بطريق الاولى والاحرى."},{"id":"1344","s":9,"a":109,"at":"افمن اسس بنيانه على تقوى من الله ورضوان خير ام من اسس بنيانه على شفا جرف هار فانهار به في نار جهنم والله لا يهدي القوم الظالمين","dt":"[109] لا يستوي من اسس بنيانه على تقوى الله وطاعته ومرضاته، ومن اسس بنيانه على طرف حفره متداعيه للسقوط، فبنى مسجدا ضرارا وكفرا وتفريقا بين المسلمين، فادى به ذلك الى السقوط في نار جهنم. والله لا يهدي القوم الظالمين المتجاوزين حدوده."},{"id":"1345","s":9,"a":110,"at":"لا يزال بنيانهم الذي بنوا ريبه في قلوبهم الا ان تقطع قلوبهم والله عليم حكيم","dt":"[110] لا يزال بنيان المنافقين الذي بنوه مضاره لمسجد «قباء» شكا ونفاقا ماكثا في قلوبهم، الى ان تتقطع قلوبهم بقتلهم او موتهم، او بندمهم غايه الندم، وتوبتهم الى ربهم، وخوفهم منه غايه الخوف. والله عليم بما عليه هؤلاء المنافقون من الشك وما قصدوا في بنائهم، حكيم في تدبير امور خلقه."},{"id":"1346","s":9,"a":111,"at":"ان الله اشترى من المؤمنين انفسهم واموالهم بان لهم الجنه يقاتلون في سبيل الله فيقتلون ويقتلون وعدا عليه حقا في التوراه والانجيل والقران ومن اوفى بعهده من الله فاستبشروا ببيعكم الذي بايعتم به وذلك هو الفوز العظيم","dt":"[111] ان الله اشترى من المؤمنين انفسهم بان لهم في مقابل ذلك الجنه، وما اعد الله فيها من النعيم، لبذلهم نفوسهم واموالهم في جهاد اعدائه لاعلاء كلمته واظهار دينه، فيقتلون ويقتلون، وعدا عليه حقا في التوراه المنزله على موسى عليه السلام، والانجيل المنزل على عيسى عليه السلام، والقران المنزل على محمد -صلى الله عليه وسلم-. ولا احد اوفى بعهده من الله لمن وفى بما عاهد الله عليه، فاظهروا السرور -ايها المؤمنون- ببيعكم الذي بايعتم الله به، وبما وعدكم به من الجنه والرضوان، وذلك البيع هو الفلاح العظيم."},{"id":"1347","s":9,"a":112,"at":"التائبون العابدون الحامدون السائحون الراكعون الساجدون الامرون بالمعروف والناهون عن المنكر والحافظون لحدود الله وبشر المؤمنين","dt":"[112] ومن صفات هؤلاء المؤمنين الذين لهم البشاره بدخول الجنه: انهم التائبون الراجعون عما كرهه الله الى ما يحبه ويرضاه، الذين اخلصوا العباده لله وحده وجدوا في طاعته، الذين يحمدون الله على كل ما امتحنهم به من خير او شر، الصائمون، الراكعون في صلاتهم، الساجدون فيها، الذين يامرون الناس بكل ما امر الله ورسوله به، وينهونهم عن كل ما نهى الله عنه ورسوله، المؤدون فرائض الله المنتهون الى امره ونهيه، القائمون على طاعته، الواقفون عند حدوده. وبشر -ايها النبي- هؤلاء المؤمنين المتصفين بهذه الصفات برضوان الله وجنته."},{"id":"1348","s":9,"a":113,"at":"ما كان للنبي والذين امنوا ان يستغفروا للمشركين ولو كانوا اولي قربى من بعد ما تبين لهم انهم اصحاب الجحيم","dt":"[113] ما كان ينبغي للنبي محمد -صلى الله عليه وسلم- والذين امنوا ان يدعوا بالمغفره للمشركين، ولو كانوا ذوي قرابه لهم، من بعد ما ماتوا على شركهم بالله وعباده الاوثان، وتبين لهم انهم اصحاب الجحيم لموتهم على الشرك، والله لا يغفر للمشركين، كما قال تعالى: ان الله لا يغفر ان يشرك به وكما قال سبحانه: انه من يشرك بالله فقد حرم الله عليه الجنه"},{"id":"1349","s":9,"a":114,"at":"وما كان استغفار ابراهيم لابيه الا عن موعده وعدها اياه فلما تبين له انه عدو لله تبرا منه ان ابراهيم لاواه حليم","dt":"[114] وما كان استغفار ابراهيم -عليه السلام- لابيه المشرك، الا عن موعده وعدها اياه، وهي قوله: ساستغفر لك ربي انه كان بي حفيا فلما تبين لابراهيم ان اباه عدو لله ولم ينفع فيه الوعظ والتذكير، وانه سيموت كافرا، تركه وترك الاستغفار له، وتبرا منه. ان ابراهيم -عليه السلام- عظيم التضرع لله، كثير الصفح عما يصدر من قومه من الزلات."},{"id":"1350","s":9,"a":115,"at":"وما كان الله ليضل قوما بعد اذ هداهم حتى يبين لهم ما يتقون ان الله بكل شيء عليم","dt":"[115] وما كان الله ليضل قوما بعد ان من عليهم بالهدايه والتوفيق حتى يبين لهم ما يتقونه به، وما يحتاجون اليه في اصول الدين وفروعه. ان الله بكل شيء عليم، فقد علمكم ما لم تكونوا تعلمون، وبين لكم ما به تنتفعون، واقام الحجه عليكم بابلاغكم رسالته."},{"id":"1351","s":9,"a":116,"at":"ان الله له ملك السموات والارض يحيي ويميت وما لكم من دون الله من ولي ولا نصير","dt":"[116] ان الله مالك السموات والارض وما فيهن، لا شريك له في الخلق والتدبير والعباده والتشريع، يحيي من يشاء ويميت من يشاء، وما لكم من احد غير الله يتولى اموركم، ولا نصير ينصركم على عدوكم."},{"id":"1352","s":9,"a":117,"at":"لقد تاب الله على النبي والمهاجرين والانصار الذين اتبعوه في ساعه العسره من بعد ما كاد يزيغ قلوب فريق منهم ثم تاب عليهم انه بهم رءوف رحيم","dt":"[117] لقد وفق الله نبيه محمدا -صلى الله عليه وسلم- الى الانابه اليه وطاعته، وتاب الله على المهاجرين الذين هجروا ديارهم وعشيرتهم الى دار الاسلام، وتاب على انصار رسول الله -صلى الله عليه وسلم- الذين خرجوا معه لقتال الاعداء في غزوه «تبوك» في حر شديد، وضيق من الزاد والظهر، لقد تاب الله عليهم من بعد ما كاد يميل قلوب بعضهم عن الحق، فيميلون الى الدعه والسكون، لكن الله ثبتهم وقواهم وتاب عليهم، انه بهم كثير الرافه والرحمه في عاجلهم واجلهم. ومن رحمته بهم ان من عليهم بالتوبه، وقبلها منهم، وثبتهم عليها."},{"id":"1353","s":9,"a":118,"at":"وعلى الثلاثه الذين خلفوا حتى اذا ضاقت عليهم الارض بما رحبت وضاقت عليهم انفسهم وظنوا ان لا ملجا من الله الا اليه ثم تاب عليهم ليتوبوا ان الله هو التواب الرحيم","dt":"[118] وكذلك تاب الله على الثلاثه من الانصار -الذين تخلفوا عن الجهاد مع رسول الله -صلى الله عليه وسلم- في غزوه \"تبوك\"- وهم كعب بن مالك وهلال بن اميه ومراره بن الربيع-، وحزنوا حزنا شديدا، حتى اذا ضاقت عليهم الارض بسعتها؛ غما وندما بسبب تخلفهم، وضاقت عليهم انفسهم لما اصابهم من الهم، وايقنوا ان لا ملجا من الله الا اليه، وفقهم الله الى التوبه وقبلها منهم؛ ليستمروا ويثبتوا على طاعته."},{"id":"1354","s":9,"a":119,"at":"ياايها الذين امنوا اتقوا الله وكونوا مع الصادقين","dt":"[119] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه امتثلوا اوامر الله واجتنبوا نواهيه في كل ما تفعلون وتتركون، وكونوا مع الصادقين في ايمانهم وعهودهم، وفي كل شان من شؤونهم."},{"id":"1355","s":9,"a":120,"at":"ما كان لاهل المدينه ومن حولهم من الاعراب ان يتخلفوا عن رسول الله ولا يرغبوا بانفسهم عن نفسه ذلك بانهم لا يصيبهم ظما ولا نصب ولا مخمصه في سبيل الله ولا يطئون موطئا يغيظ الكفار ولا ينالون من عدو نيلا الا كتب لهم به عمل صالح ان الله لا يضيع اجر المحسنين","dt":"[120] ما كان ينبغي لاهل مدينه رسول الله -صلى الله عليه وسلم- ومن حولهم من سكان الباديه ان يتخلفوا في اهلهم ودورهم عن رسول الله -صلى الله عليه وسلم-، ولا يرضوا لانفسهم بالراحه، والرسول -صلى الله عليه وسلم- في تعب ومشقه؛ ذلك بانهم لا يصيبهم في سفرهم وجهادهم عطش ولا تعب ولا مجاعه في سبيل الله، ولا يطؤون ارضا يغضب الكفار وطؤهم اياها، ولا يصيبون من عدو الله وعدوهم قتلا او هزيمه الا كتب لهم بذلك كله ثواب عمل صالح. ان الله لا يضيع اجر المحسنين الذين احسنوا في مبادرتهم الى امر الله، وقيامهم بما عليهم من حقه، وحق خلقه."},{"id":"1356","s":9,"a":121,"at":"ولا ينفقون نفقه صغيره ولا كبيره ولا يقطعون واديا الا كتب لهم ليجزيهم الله احسن ما كانوا يعملون","dt":"[121] ولا ينفقون نفقه صغيره ولا كبيره في سبيل الله، ولا يقطعون واديا في سيرهم مع رسول الله -صلى الله عليه وسلم- في جهاده، الا كتب لهم اجر عملهم؛ ليجزيهم الله احسن ما يجزون به على اعمالهم الصالحه."},{"id":"1357","s":9,"a":122,"at":"وما كان المؤمنون لينفروا كافه فلولا نفر من كل فرقه منهم طائفه ليتفقهوا في الدين ولينذروا قومهم اذا رجعوا اليهم لعلهم يحذرون","dt":"[122] وما كان ينبغي للمؤمنين ان يخرجوا جميعا لقتال عدوهم، كما لا يستقيم لهم ان يقعدوا جميعا، فهلا خرج للغزو والجهاد من كل فرقه جماعه تحصل بهم الكفايه والمقصود؛ وذلك ليتفقه القاعدون عن القتال فيعلموا ما تجدد من الاحكام في دين الله وما انزل على رسوله، وينذروا قومهم بما تعلموه عند رجوعهم اليهم، لعلهم يحذرون عذاب الله بامتثال اوامره واجتناب نواهيه."},{"id":"1358","s":9,"a":123,"at":"ياايها الذين امنوا قاتلوا الذين يلونكم من الكفار وليجدوا فيكم غلظه واعلموا ان الله مع المتقين","dt":"[123] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه ابدؤوا بقتال الاقرب فالاقرب الى دار الاسلام من الكفار، وليجد الكفار فيكم غلظه وشده، واعلموا ان الله مع المتقين بتاييده ونصره."},{"id":"1359","s":9,"a":124,"at":"واذا ما انزلت سوره فمنهم من يقول ايكم زادته هذه ايمانا فاما الذين امنوا فزادتهم ايمانا وهم يستبشرون","dt":"[124] واذا ما انزل الله سوره من سور القران على رسوله، فمن هؤلاء المنافقين من يقول: -انكارا واستهزاء - ايكم زادته هذه السوره تصديقا بالله واياته؟فاما الذين امنوا بالله ورسوله فزادهم نزول السوره ايمانا بالعلم بها وتدبرها واعتقادها والعمل بها، وهم يفرحون بما اعطاهم الله من الايمان واليقين."},{"id":"1360","s":9,"a":125,"at":"واما الذين في قلوبهم مرض فزادتهم رجسا الى رجسهم وماتوا وهم كافرون","dt":"[125] واما الذين في قلوبهم نفاق وشك في دين الله، فان نزول السوره يزيدهم نفاقا وشكا الى ما هم عليه من قبل من النفاق والشك، وهلك هؤلاء وهم جاحدون بالله واياته."},{"id":"1361","s":9,"a":126,"at":"او لا يرون انهم يفتنون في كل عام مره او مرتين ثم لا يتوبون ولا هم يذكرون","dt":"[126] اولا يرى المنافقون ان الله يبتليهم بالقحط والشده، وباظهار ما يبطنون من النفاق مره او مرتين في كل عام؟ ثم هم مع ذلك لا يتوبون من كفرهم ونفاقهم، ولا هم يتعظون ولا يتذكرون بما يعاينون من ايات الله."},{"id":"1362","s":9,"a":127,"at":"واذا ما انزلت سوره نظر بعضهم الى بعض هل يراكم من احد ثم انصرفوا صرف الله قلوبهم بانهم قوم لا يفقهون","dt":"[127] واذا ما انزلت سوره تغامز المنافقون بالعيون انكارا لنزولها وسخريه وغيظا؛ لما نزل فيها من ذكر عيوبهم وافعالهم، ثم يقولون: هل يراكم من احد ان قمتم من عند الرسول؟ فان لم يرهم احد قاموا وانصرفوا من عنده عليه الصلاه والسلام مخافه الفضيحه. صرف الله قلوبهم عن الايمان؛ بسبب انهم لا يفهمون ولا يتدبرون."},{"id":"1363","s":9,"a":128,"at":"لقد جاءكم رسول من انفسكم عزيز عليه ما عنتم حريص عليكم بالمؤمنين رءوف رحيم","dt":"[128] لقد جاءكم ايها المؤمنون رسول من قومكم، يشق عليه ما تلقون من المكروه والعنت، حريص على ايمانكم وصلاح شانكم، وهو بالمؤمنين كثير الرافه والرحمه."},{"id":"1364","s":9,"a":129,"at":"فان تولوا فقل حسبي الله لا اله الا هو عليه توكلت وهو رب العرش العظيم","dt":"[129] فان اعرض المشركون والمنافقون عن الايمان بك -ايها الرسول- فقل لهم: حسبي الله، يكفيني جميع ما اهمني، لا معبود بحق الا هو، عليه اعتمدت، واليه فوضت جميع اموري؛ فانه ناصري ومعيني، وهو رب العرش العظيم، فعرش الرحمن اعظم المخلوقات."},{"id":"1365","s":10,"a":1,"at":"الر تلك ايات الكتاب الحكيم","dt":"[1] الر سبق الكلام على الحروف المقطعه في اول سوره البقره.هذه ايات الكتاب المحكم الذي احكمه الله وبينه لعباده."},{"id":"1366","s":10,"a":2,"at":"اكان للناس عجبا ان اوحينا الى رجل منهم ان انذر الناس وبشر الذين امنوا ان لهم قدم صدق عند ربهم قال الكافرون ان هذا لساحر مبين","dt":"[2] اكان امرا عجبا للناس انزالنا الوحي بالقران على رجل منهم ينذرهم عقاب الله، ويبشر الذين امنوا بالله ورسله ان لهم اجرا حسنا بما قدموا من صالح الاعمال؟ فلما اتاهم رسول الله -صلى الله عليه وسلم- بوحي الله وتلاه عليهم، قال المنكرون: ان محمدا ساحر، وما جاء به سحر ظاهر البطلان."},{"id":"1367","s":10,"a":3,"at":"ان ربكم الله الذي خلق السموات والارض في سته ايام ثم استوى على العرش يدبر الامر ما من شفيع الا من بعد اذنه ذلكم الله ربكم فاعبدوه افلا تذكرون","dt":"[3] ان ربكم الله الذي اوجد السموات والارض في سته ايام، ثم استوى -اي: علا وارتفع- على العرش استواء يليق بجلاله وعظمته، يدبر امور خلقه، لا يضاده في قضائه احد، ولا يشفع عنده شافع يوم القيامه الا من بعد ان ياذن له بالشفاعه، فاعبدوا الله ربكم المتصف بهذه الصفات، واخلصوا له العباده. افلا تتعظون وتعتبرون بهذه الايات والحجج؟"},{"id":"1368","s":10,"a":4,"at":"اليه مرجعكم جميعا وعد الله حقا انه يبدا الخلق ثم يعيده ليجزي الذين امنوا وعملوا الصالحات بالقسط والذين كفروا لهم شراب من حميم وعذاب اليم بما كانوا يكفرون","dt":"[4] الى ربكم معادكم يوم القيامه جميعا، وهذا وعد الله الحق، هو الذي يبدا ايجاد الخلق ثم يعيده بعد الموت، فيوجده حيا كهيئته الاولى؛ ليجزي من صدق الله ورسوله، وعمل الاعمال الحسنه احسن الجزاء بالعدل. والذين جحدوا وحدانيه الله ورساله رسوله لهم شراب من ماء شديد الحراره يشوي الوجوه ويقطع الامعاء، ولهم عذاب موجع بسبب كفرهم وضلالهم."},{"id":"1369","s":10,"a":5,"at":"هو الذي جعل الشمس ضياء والقمر نورا وقدره منازل لتعلموا عدد السنين والحساب ما خلق الله ذلك الا بالحق يفصل الايات لقوم يعلمون","dt":"[5] الله هو الذي جعل الشمس ضياء، وجعل القمر نورا، وقدر القمر منازل، فبالشمس تعرف الايام، وبالقمر تعرف الشهور والاعوام، ما خلق الله تعالى الشمس والقمر الا لحكمه عظيمه، ودلاله على كمال قدره الله وعلمه، يبين الحجج والادله لقوم يعلمون الحكمه في ابداع الخلق."},{"id":"1370","s":10,"a":6,"at":"ان في اختلاف الليل والنهار وما خلق الله في السموات والارض لايات لقوم يتقون","dt":"[6] ان في تعاقب الليل والنهار وما خلق الله في السموات والارض من عجائب الخلق وما فيهما من ابداع ونظام، لادله وحججا واضحه لقوم يخشون عقاب الله وسخطه وعذابه."},{"id":"1371","s":10,"a":7,"at":"ان الذين لا يرجون لقاءنا ورضوا بالحياه الدنيا واطمانوا بها والذين هم عن اياتنا غافلون","dt":"[7] ان الذين لا يطمعون في لقائنا في الاخره للحساب، وما يتلوه من الجزاء على الاعمال لانكارهم البعث، ورضوا بالحياه الدنيا عوضا عن الاخره، وركنوا اليها، والذين هم عن اياتنا الكونيه والشرعيه ساهون."},{"id":"1372","s":10,"a":8,"at":"اولئك ماواهم النار بما كانوا يكسبون","dt":"[8] اولئك مقرهم نار جهنم في الاخره؛ جزاء بما كانوا يكسبون في دنياهم من الاثام والخطايا."},{"id":"1373","s":10,"a":9,"at":"ان الذين امنوا وعملوا الصالحات يهديهم ربهم بايمانهم تجري من تحتهم الانهار في جنات النعيم","dt":"[9] ان الذين امنوا بالله ورسوله وعملوا الصالحات يدلهم ربهم الى طريق الجنه، ويوفقهم الى العمل الموصل اليه؛ بسبب ايمانهم، ثم يثيبهم بدخول الجنه واحلال رضوانه عليهم، تجري من تحت غرفهم ومنازلهم الانهار في جنات النعيم."},{"id":"1374","s":10,"a":10,"at":"دعواهم فيها سبحانك اللهم وتحيتهم فيها سلام واخر دعواهم ان الحمد لله رب العالمين","dt":"[10] دعاؤهم في الجنه التسبيح (سبحانك اللهم)، وتحيه الله وملائكته لهم، وتحيه بعضهم بعضا في الجنه (سلام)، واخر دعائهم قولهم: «الحمد لله رب العالمين» اي: الشكر والثناء لله خالق المخلوقات ومربيها بنعمه."},{"id":"1375","s":10,"a":11,"at":"ولو يعجل الله للناس الشر استعجالهم بالخير لقضي اليهم اجلهم فنذر الذين لا يرجون لقاءنا في طغيانهم يعمهون","dt":"[11] ولو يعجل الله للناس اجابه دعائهم في الشر كاستعجاله لهم في الخير بالاجابه لهلكوا، فنترك الذين لا يخافون عقابنا، ولا يوقنون بالبعث والنشور في تمردهم وعتوهم، يترددون حائرين."},{"id":"1376","s":10,"a":12,"at":"واذا مس الانسان الضر دعانا لجنبه او قاعدا او قائما فلما كشفنا عنه ضره مر كان لم يدعنا الى ضر مسه كذلك زين للمسرفين ما كانوا يعملون","dt":"[12] واذا اصاب الانسان الشده استغاث بنا في كشف ذلك عنه، مضطجعا لجنبه او قاعدا او قائما، على حسب الحال التي يكون بها عند نزول ذلك الضر به. فلما كشفنا عنه الشده التي اصابته استمر على طريقته الاولى قبل ان يصيبه الضر، ونسي ما كان فيه من الشده والبلاء، وترك الشكر لربه الذي فرج عنه ما كان قد نزل به من البلاء، كما زين لهذا الانسان استمراره على جحوده وعناده بعد كشف الله عنه ما كان فيه من الضر، زين للذين اسرفوا في الكذب على الله وعلى انبيائه ما كانوا يعملون من معاصي الله والشرك به."},{"id":"1377","s":10,"a":13,"at":"ولقد اهلكنا القرون من قبلكم لما ظلموا وجاءتهم رسلهم بالبينات وما كانوا ليؤمنوا كذلك نجزي القوم المجرمين","dt":"[13] ولقد اهلكنا الامم التي كذبت رسل الله من قبلكم -ايها المشركون بربهم- لما اشركوا، وجاءتهم رسلهم من عند الله بالمعجزات الواضحات والحجج التي تبين صدق من جاء بها، فلم تكن هذه الامم التي اهلكناها لتصدق رسلها وتنقاد لها، فاستحقوا الهلاك، مثل ذلك الاهلاك نجزي كل مجرم متجاوز حدود الله."},{"id":"1378","s":10,"a":14,"at":"ثم جعلناكم خلائف في الارض من بعدهم لننظر كيف تعملون","dt":"[14] ثم جعلناكم -ايها الناس- خلفا في الارض من بعد القرون المهلكه؛ لننظر كيف تعملون: اخيرا ام شرا، فنجازيكم بذلك حسب عملكم."},{"id":"1379","s":10,"a":15,"at":"واذا تتلى عليهم اياتنا بينات قال الذين لا يرجون لقاءنا ائت بقران غير هذا او بدله قل ما يكون لي ان ابدله من تلقاء نفسي ان اتبع الا ما يوحى الي اني اخاف ان عصيت ربي عذاب يوم عظيم","dt":"[15] واذا تتلى على المشركين ايات الله التي انزلناها اليك -ايها الرسول- واضحات، قال الذين لا يخافون الحساب، ولا يرجون الثواب، ولا يؤمنون بيوم البعث والنشور: ائت بقران غير هذا، او بدل هذا القران: بان تجعل الحلال حراما، والحرام حلالا، والوعد وعيدا، والوعيد وعدا، وان تسقط ما فيه من عيب الهتنا وتسفيه احلامنا، قل لهم -ايها الرسول-: ان ذلك ليس الي، وانما اتبع في كل ما امركم به وانهاكم عنه ما ينزله علي ربي ويامرني به، اني اخشى من الله -ان خالفت امره-عذاب يوم عظيم وهو يوم القيامه."},{"id":"1380","s":10,"a":16,"at":"قل لو شاء الله ما تلوته عليكم ولا ادراكم به فقد لبثت فيكم عمرا من قبله افلا تعقلون","dt":"[16] قل لهم -ايها الرسول-: لو شاء الله ما تلوت هذا القران عليكم، ولا اعلمكم الله به، فاعلموا انه الحق من الله، فانكم تعلمون انني مكثت فيكم زمنا طويلا من قبل ان يوحيه الي ربي، ومن قبل ان اتلوه عليكم، افلا تستعملون عقولكم بالتدبر والتفكر؟"},{"id":"1381","s":10,"a":17,"at":"فمن اظلم ممن افترى على الله كذبا او كذب باياته انه لا يفلح المجرمون","dt":"[17] لا احد اشد ظلما ممن اختلق على الله الكذب او كذب باياته، انه لا ينجح من كذب بانبياء الله ورسله، ولا ينالون الفلاح."},{"id":"1382","s":10,"a":18,"at":"ويعبدون من دون الله ما لا يضرهم ولا ينفعهم ويقولون هؤلاء شفعاؤنا عند الله قل اتنبئون الله بما لا يعلم في السموات ولا في الارض سبحانه وتعالى عما يشركون","dt":"[18] ويعبد هؤلاء المشركون من دون الله ما لا يضرهم شيئا، ولا ينفعهم في الدنيا والاخره، ويقولون: انما نعبدهم ليشفعوا لنا عند الله، قل لهم -ايها الرسول-: اتخبرون الله تعالى بشيء لا يعلمه من امر هؤلاء الشفعاء في السموات او في الارض؟ فانه لو كان فيهما شفعاء يشفعون لكم عنده لكان اعلم بهم منكم، فالله تعالى منزه عما يفعله هؤلاء المشركون من اشراكهم في عبادته ما لا يضر ولا ينفع."},{"id":"1383","s":10,"a":19,"at":"وما كان الناس الا امه واحده فاختلفوا ولولا كلمه سبقت من ربك لقضي بينهم فيما فيه يختلفون","dt":"[19] كان الناس على دين واحد وهو الاسلام، ثم اختلفوا بعد ذلك، فكفر بعضهم، وثبت بعضهم على الحق. ولولا كلمه سبقت من الله بامهال العاصين وعدم معاجلتهم بذنوبهم لقضي بينهم: بان يهلك اهل الباطل منهم، وينجي اهل الحق."},{"id":"1384","s":10,"a":20,"at":"ويقولون لولا انزل عليه ايه من ربه فقل انما الغيب لله فانتظروا اني معكم من المنتظرين","dt":"[20] ويقول هؤلاء الكفره المعاندون: هلا انزل على محمد علم ودليل، وايه حسيه من ربه نعلم بها انه على حق فيما يقول، فقل لهم -ايها الرسول-: لا يعلم الغيب احد الا الله، فان شاء فعل وان شاء لم يفعل، فانتظروا -ايها القوم- قضاء الله بيننا وبينكم بتعجيل عقوبته للمبطل منا، ونصره صاحب الحق، اني منتظر ذلك."},{"id":"1385","s":10,"a":21,"at":"واذا اذقنا الناس رحمه من بعد ضراء مستهم اذا لهم مكر في اياتنا قل الله اسرع مكرا ان رسلنا يكتبون ما تمكرون","dt":"[21] واذا اذقنا المشركين يسرا وفرجا ورخاء بعد عسر وشده وكرب اصابهم، اذا هم يكذبون، ويستهزئون بايات الله، قل -ايها الرسول- لهؤلاء المشركين المستهزئين: الله اسرع مكرا واستدراجا وعقوبه لكم. ان حفظتنا الذين نرسلهم اليكم يكتبون عليكم ما تمكرون في اياتنا، ثم نحاسبكم على ذلك."},{"id":"1386","s":10,"a":22,"at":"هو الذي يسيركم في البر والبحر حتى اذا كنتم في الفلك وجرين بهم بريح طيبه وفرحوا بها جاءتها ريح عاصف وجاءهم الموج من كل مكان وظنوا انهم احيط بهم دعوا الله مخلصين له الدين لئن انجيتنا من هذه لنكونن من الشاكرين","dt":"[22] هو الذي يسيركم -ايها الناس- في البر على الدواب وغيرها، وفي البحر في السفن، حتى اذا كنتم فيها وجرت بريح طيبه، وفرح ركاب السفن بالريح الطيبه، جاءت هذه السفن ريح شديده، وجاء الركاب الموج (وهو ما ارتفع من الماء) من كل مكان، وايقنوا ان الهلاك قد احاط بهم، اخلصوا الدعاء لله وحده، وتركوا ما كانوا يعبدون، وقالوا: لئن انجيتنا من هذه الشده التي نحن فيها لنكونن من الشاكرين لك على نعمك."},{"id":"1387","s":10,"a":23,"at":"فلما انجاهم اذا هم يبغون في الارض بغير الحق ياايها الناس انما بغيكم على انفسكم متاع الحياه الدنيا ثم الينا مرجعكم فننبئكم بما كنتم تعملون","dt":"[23] فلما انجاهم الله من الشدائد والاهوال اذا هم يعملون في الارض بالفساد وبالمعاصي. يا ايها الناس انما وبال بغيكم راجع على انفسكم، تمتعون به متاعا غير دائم في الحياه الدنيا الزائله، ثم الينا مصيركم ومرجعكم، فنخبركم بجميع اعمالكم، ونحاسبكم عليها."},{"id":"1388","s":10,"a":24,"at":"انما مثل الحياه الدنيا كماء انزلناه من السماء فاختلط به نبات الارض مما ياكل الناس والانعام حتى اذا اخذت الارض زخرفها وازينت وظن اهلها انهم قادرون عليها اتاها امرنا ليلا او نهارا فجعلناها حصيدا كان لم تغن بالامس كذلك نفصل الايات لقوم يتفكرون","dt":"[24] انما مثل الحياه الدنيا، وما تتفاخرون به فيها من زينه واموال، كمثل مطر انزلناه من السماء الى الارض، فنبتت به انواع من النبات، مختلط بعضها ببعض مما يقتات به الناس من الثمار، وما تاكله الحيوانات من النبات، حتى اذا ظهر حسن هذه الارض وبهاؤها، وظن اهل هذه الارض انهم قادرون على حصادها والانتفاع بها، جاءها امرنا وقضاؤنا بهلاك ما عليها من النبات والزينه، اما ليلا واما نهارا، فجعلنا هذه النباتات والاشجار محصوده مقطوعه لا شيء فيها، كان لم تكن تلك الزروع والنباتات قائمه قبل ذلك على وجه الارض، فكذلك ياتي الفناء على ما تتباهون به من دنياكم وزخارفها فيفنيها الله ويهلكها. وكما بينا لكم -ايها الناس- مثل هذه الدنيا وعرفناكم بحقيقتها، نبين حججنا وادلتنا لقوم يتفكرون في ايات الله، ويتدبرون ما ينفعهم في الدنيا والاخره."},{"id":"1389","s":10,"a":25,"at":"والله يدعو الى دار السلام ويهدي من يشاء الى صراط مستقيم","dt":"[25] والله يدعوكم الى جناته التي اعدها لاوليائه، ويهدي من يشاء من خلقه، فيوفقه لاصابه الطريق المستقيم، وهو الاسلام."},{"id":"1390","s":10,"a":26,"at":"للذين احسنوا الحسنى وزياده ولا يرهق وجوههم قتر ولا ذله اولئك اصحاب الجنه هم فيها خالدون","dt":"[26] للمؤمنين الذين احسنوا عباده الله فاطاعوه فيما امر ونهى، الجنه، وزياده عليها، وهي النظر الى وجه الله تعالى في الجنه، والمغفره والرضوان، ولا يغشى وجوههم غبار ولا ذله، كما يلحق اهل النار. هؤلاء المتصفون بهذه الصفات هم اصحاب الجنه ماكثون فيها ابدا."},{"id":"1391","s":10,"a":27,"at":"والذين كسبوا السيئات جزاء سيئه بمثلها وترهقهم ذله ما لهم من الله من عاصم كانما اغشيت وجوههم قطعا من الليل مظلما اولئك اصحاب النار هم فيها خالدون","dt":"[27] والذين عملوا السيئات في الدنيا فكفروا وعصوا الله لهم جزاء اعمالهم السيئه التي عملوها بمثلها من عقاب الله في الاخره، وتغشاهم ذله وهوان، وليس لهم من عذاب الله من مانع يمنعهم اذا عاقبهم، كانما البست وجوههم اجزاء من سواد الليل المظلم. هؤلاء هم اهل النار ماكثون فيها ابدا."},{"id":"1392","s":10,"a":28,"at":"ويوم نحشرهم جميعا ثم نقول للذين اشركوا مكانكم انتم وشركاؤكم فزيلنا بينهم وقال شركاؤهم ما كنتم ايانا تعبدون","dt":"[28] واذكر -ايها الرسول- يوم نحشر الخلق جميعا للحساب والجزاء، ثم نقول للذين اشركوا بالله: الزموا مكانكم انتم وشركاؤكم الذين كنتم تعبدونهم من دون الله حتى تنظروا ما يفعل بكم، ففرقنا بين المشركين ومعبوديهم، وتبرا من عبدوا من دون الله ممن كانوا يعبدونهم، وقالوا للمشركين: ما كنتم ايانا تعبدون في الدنيا."},{"id":"1393","s":10,"a":29,"at":"فكفى بالله شهيدا بيننا وبينكم ان كنا عن عبادتكم لغافلين","dt":"[29] فكفى بالله شهيدا بيننا وبينكم، اننا لم نكن نعلم ما كنتم تقولون وتفعلون، ولقد كنا عن عبادتكم ايانا غافلين، لا نشعر بها."},{"id":"1394","s":10,"a":30,"at":"هنالك تبلو كل نفس ما اسلفت وردوا الى الله مولاهم الحق وضل عنهم ما كانوا يفترون","dt":"[30] في ذلك الموقف للحساب تتفقد كل نفس احوالها واعمالها التي سلفت وتعاينها، وتجازى بحسبها: ان خيرا فخير، وان شرا فشر، ورد الجميع الى الله الحكم العدل، فادخل اهل الجنه الجنه واهل النار النار، وذهب عن المشركين ما كانوا يعبدون من دون الله افتراء عليه."},{"id":"1395","s":10,"a":31,"at":"قل من يرزقكم من السماء والارض امن يملك السمع والابصار ومن يخرج الحي من الميت ويخرج الميت من الحي ومن يدبر الامر فسيقولون الله فقل افلا تتقون","dt":"[31] قل -ايها الرسول- لهؤلاء المشركين: من يرزقكم من السماء، بما ينزله من المطر، ومن الارض بما ينبته فيها من انواع النبات والشجر تاكلون منه انتم وانعامكم؟ ومن يملك ما تتمتعون به انتم وغيركم من حواس السمع والابصار؟ ومن ذا الذي يملك الحياه والموت في الكون كله، فيخرج الاحياء والاموات بعضها من بعض فيما تعرفون من المخلوقات، وفيما لا تعرفون؟ ومن يدبر امر السماء والارض وما فيهن، وامركم وامر الخليقه جميعا؟ فسوف يجيبونك بان الذي يفعل ذلك كله هو الله، فقل لهم: افلا تخافون عقاب الله ان عبدتم معه غيره؟"},{"id":"1396","s":10,"a":32,"at":"فذلكم الله ربكم الحق فماذا بعد الحق الا الضلال فانى تصرفون","dt":"[32] فذلكم الله ربكم هو الحق الذي لا ريب فيه، المستحق للعباده وحده لا شريك له، فاي شيء سوى الحق الا الضلال؟ فكيف تصرفون عن عبادته الى عباده ما سواه؟"},{"id":"1397","s":10,"a":33,"at":"كذلك حقت كلمت ربك على الذين فسقوا انهم لا يؤمنون","dt":"[33] كما كفر هؤلاء المشركون واستمروا على شركهم، حقت كلمه ربك وحكمه وقضاؤه على الذين خرجوا عن طاعه ربهم الى معصيته وكفروا به انهم لا يصدقون بوحدانيه الله، ولا بنبوه نبيه محمد -صلى الله عليه وسلم-، ولا يعملون بهديه."},{"id":"1398","s":10,"a":34,"at":"قل هل من شركائكم من يبدا الخلق ثم يعيده قل الله يبدا الخلق ثم يعيده فانى تؤفكون","dt":"[34] قل لهم -ايها الرسول-: هل من الهتكم ومعبوداتكم من يبدا خلق اي شيء من غير اصل، ثم يفنيه بعد انشائه، ثم يعيده كهيئته قبل ان يفنيه؟ فانهم لا يقدرون على دعوى ذلك، قل -ايها الرسول-: الله تعالى وحده هو الذي ينشئ الخلق ثم يفنيه ثم يعيده، فكيف تنصرفون عن طريق الحق الى الباطل، وهو عباده غير الله؟"},{"id":"1399","s":10,"a":35,"at":"قل هل من شركائكم من يهدي الى الحق قل الله يهدي للحق افمن يهدي الى الحق احق ان يتبع امن لا يهدي الا ان يهدى فما لكم كيف تحكمون","dt":"[35] قل -ايها الرسول- لهؤلاء المشركين: هل من شركائكم من يرشد الى الطريق المستقيم؟ فانهم لا يقدرون على ذلك، قل لهم: الله وحده يهدي الضال عن الهدى الى الحق. ايهما احق بالاتباع: من يهدي وحده للحق ام من لا يهتدي لعدم علمه ولضلاله، وهم شركاؤكم الذين لا يهدون ولا يهتدون الا ان يهدوا؟ فما بالكم كيف سويتم بين الله وخلقه؟ وهذا حكم باطل."},{"id":"1400","s":10,"a":36,"at":"وما يتبع اكثرهم الا ظنا ان الظن لا يغني من الحق شيئا ان الله عليم بما يفعلون","dt":"[36] وما يتبع اكثر هؤلاء المشركين في جعلهم الاصنام الهه واعتقادهم بانها تقرب الى الله الا تخرصا وظنا، وهو لا يغني من اليقين شيئا. ان الله عليم بما يفعل هؤلاء المشركون من الكفر والتكذيب."},{"id":"1401","s":10,"a":37,"at":"وما كان هذا القران ان يفترى من دون الله ولكن تصديق الذي بين يديه وتفصيل الكتاب لا ريب فيه من رب العالمين","dt":"[37] وما كان يتهيا لاحد ان ياتي بهذا القران من عند غير الله؛ لانه لا يقدر على ذلك احد من الخلق، ولكن الله انزله مصدقا للكتب التي انزلها على انبيائه؛ لان دين الله واحد، وفي هذا القران بيان وتفصيل لما شرعه الله لامه محمد -صلى الله عليه وسلم-، لا شك في ان هذا القران موحى من رب العالمين."},{"id":"1402","s":10,"a":38,"at":"ام يقولون افتراه قل فاتوا بسوره مثله وادعوا من استطعتم من دون الله ان كنتم صادقين","dt":"[38] بل ايقولون: ان هذا القران افتراه محمد من عند نفسه؟ فانهم يعلمون انه بشر مثلهم! قل لهم -ايها الرسول-: فاتوا انتم بسوره واحده من جنس هذا القران في نظمه وهدايته، واستعينوا على ذلك بكل من قدرتم عليه من دون الله من انس وجن، ان كنتم صادقين في دعواكم."},{"id":"1403","s":10,"a":39,"at":"بل كذبوا بما لم يحيطوا بعلمه ولما ياتهم تاويله كذلك كذب الذين من قبلهم فانظر كيف كان عاقبه الظالمين","dt":"[39] بل سارعوا الى التكذيب بالقران اول ما سمعوه، قبل ان يتدبروا اياته، وكفروا بما لم يحيطوا بعلمه من ذكر البعث والجزاء والجنه والنار وغير ذلك، ولم ياتهم بعد حقيقه ما وعدوا به في الكتاب. وكما كذب المشركون بوعيد الله كذبت الامم التي خلت قبلهم، فانظر -ايها الرسول- كيف كانت عاقبه الظالمين؟ فقد اهلك الله بعضهم بالخسف، وبعضهم بالغرق، وبعضهم بغير ذلك."},{"id":"1404","s":10,"a":40,"at":"ومنهم من يؤمن به ومنهم من لا يؤمن به وربك اعلم بالمفسدين","dt":"[40] ومن قومك -ايها الرسول- من يصدق بالقران، ومنهم من لا يصدق به حتى يموت على ذلك ويبعث عليه، وربك اعلم بالمفسدين الذين لا يؤمنون به، على وجه الظلم والعناد والفساد، فيجازيهم على فسادهم باشد العذاب."},{"id":"1405","s":10,"a":41,"at":"وان كذبوك فقل لي عملي ولكم عملكم انتم بريئون مما اعمل وانا بريء مما تعملون","dt":"[41] وان كذبك -ايها الرسول- هؤلاء المشركون فقل لهم: لي ديني وعملي، ولكم دينكم وعملكم، فانتم لا تؤاخذون بعملي، وانا لا اؤاخذ بعملكم."},{"id":"1406","s":10,"a":42,"at":"ومنهم من يستمعون اليك افانت تسمع الصم ولو كانوا لا يعقلون","dt":"[42] و من الكفار من يسمعون كلامك الحق، وتلاوتك القران، ولكنهم لا يهتدون. افانت تقدر على اسماع الصم؟ فكذلك لا تقدر على هدايه هؤلاء الا ان يشاء الله هدايتهم؛ لانهم صم عن سماع الحق، لا يعقلونه."},{"id":"1407","s":10,"a":43,"at":"ومنهم من ينظر اليك افانت تهدي العمي ولو كانوا لا يبصرون","dt":"[43] ومن الكفار من ينظر اليك والى ادله نبوتك الصادقه، ولكنه لا يبصر ما اتاك الله من نور الايمان، افانت -ايها الرسول- تقدر على ان تخلق للعمي ابصارا يهتدون بها؟ فكذلك لا تقدر على هدايتهم اذا كانوا فاقدي البصيره، و انما ذلك كله لله وحده."},{"id":"1408","s":10,"a":44,"at":"ان الله لا يظلم الناس شيئا ولكن الناس انفسهم يظلمون","dt":"[44] ان الله لا يظلم الناس شيئا بزياده في سيئاتهم او نقص من حسناتهم، ولكن الناس هم الذين يظلمون انفسهم بالكفر والمعصيه ومخالفه امر الله ونهيه."},{"id":"1409","s":10,"a":45,"at":"ويوم يحشرهم كان لم يلبثوا الا ساعه من النهار يتعارفون بينهم قد خسر الذين كذبوا بلقاء الله وما كانوا مهتدين","dt":"[45] ويوم يحشر الله هؤلاء المشركين يوم البعث والحساب، كانهم قبل ذلك لم يمكثوا في الحياه الدنيا الا قدر ساعه من النهار، يعرف بعضهم بعضا كحالهم في الدنيا، ثم انقطعت تلك المعرفه وانقضت تلك الساعه. قد خسر الذين كفروا وكذبوا بلقاء الله وثوابه وعقابه، وما كانوا موفقين لاصابه الرشد فيما فعلوا."},{"id":"1410","s":10,"a":46,"at":"واما نرينك بعض الذي نعدهم او نتوفينك فالينا مرجعهم ثم الله شهيد على ما يفعلون","dt":"[46] واما نرينك -ايها الرسول- في حياتك بعض الذي نعدهم من العقاب في الدنيا، او نتوفينك قبل ان نريك ذلك فيهم، فالينا وحدنا يرجع امرهم في الحالتين، ثم الله شهيد على افعالهم التي كانوا يفعلونها في الدنيا، لا يخفى عليه شيء منها، فيجازيهم بها جزاءهم الذي يستحقونه."},{"id":"1411","s":10,"a":47,"at":"ولكل امه رسول فاذا جاء رسولهم قضي بينهم بالقسط وهم لا يظلمون","dt":"[47] ولكل امه خلت قبلكم -ايها الناس- رسول ارسلته اليهم، كما ارسلت محمدا اليكم يدعو الى دين الله وطاعته، فاذا جاء رسولهم في الاخره قضي حينئذ بينهم بالعدل، وهم لا يظلمون من جزاء اعمالهم شيئا."},{"id":"1412","s":10,"a":48,"at":"ويقولون متى هذا الوعد ان كنتم صادقين","dt":"[48] ويقول المشركون من قومك -ايها الرسول-: متى قيام الساعه ان كنت انت ومن تبعك من الصادقين فيما تعدوننا به؟"},{"id":"1413","s":10,"a":49,"at":"قل لا املك لنفسي ضرا ولا نفعا الا ما شاء الله لكل امه اجل اذا جاء اجلهم فلا يستاخرون ساعه ولا يستقدمون","dt":"[49] قل لهم -ايها الرسول-: لا استطيع ان ادفع عن نفسي ضرا، ولا اجلب لها نفعا، الا ما شاء الله ان يدفع عني من ضر او يجلب لي من نفع. لكل قوم وقت لانقضاء مدتهم واجلهم، اذا جاء وقت انقضاء اجلهم وفناء اعمارهم، فلا يستاخرون عنه ساعه فيمهلون، ولا يتقدم اجلهم عن الوقت المعلوم."},{"id":"1414","s":10,"a":50,"at":"قل ارايتم ان اتاكم عذابه بياتا او نهارا ماذا يستعجل منه المجرمون","dt":"[50] قل -ايها الرسول- لهؤلاء المشركين: اخبروني ان اتاكم عذاب الله ليلا او نهارا، فاي شيء تستعجلون ايها المجرمون بنزول العذاب؟"},{"id":"1415","s":10,"a":51,"at":"اثم اذا ما وقع امنتم به الان وقد كنتم به تستعجلون","dt":"[51] ابعدما وقع عذاب الله بكم -ايها المشركون- امنتم في وقت لا ينفعكم فيه الايمان؟ وقيل لكم حينئذ: الان تؤمنون به، وقد كنتم من قبل تستعجلون به؟"},{"id":"1416","s":10,"a":52,"at":"ثم قيل للذين ظلموا ذوقوا عذاب الخلد هل تجزون الا بما كنتم تكسبون","dt":"[52] ثم قيل للذين ظلموا انفسهم بكفرهم بالله: تجرعوا عذاب الله الدائم لكم ابدا، فهل تعاقبون الا بما كنتم تعملون في حياتكم من معاصي الله؟"},{"id":"1417","s":10,"a":53,"at":"ويستنبئونك احق هو قل اي وربي انه لحق وما انتم بمعجزين","dt":"[53] ويستخبرك هؤلاء المشركون من قومك -ايها الرسول- عن العذاب يوم القيامه، احق هو؟ قل لهم -ايها الرسول-: نعم وربي انه لحق لا شك فيه، وما انتم بمعجزين الله ان يبعثكم ويجازيكم، فانتم في قبضته وسلطانه."},{"id":"1418","s":10,"a":54,"at":"ولو ان لكل نفس ظلمت ما في الارض لافتدت به واسروا الندامه لما راوا العذاب وقضي بينهم بالقسط وهم لا يظلمون","dt":"[54] ولو ان لكل نفس اشركت وكفرت بالله جميع ما في الارض، وامكنها ان تجعله فداء لها من ذلك العذاب لافتدت به، واخفى الذين ظلموا حسرتهم حين ابصروا عذاب الله واقعا بهم جميعا، وقضى الله عز وجل بينهم بالعدل، وهم لا يظلمون؛ لان الله تعالى لا يعاقب احدا الا بذنبه."},{"id":"1419","s":10,"a":55,"at":"الا ان لله ما في السموات والارض الا ان وعد الله حق ولكن اكثرهم لا يعلمون","dt":"[55] الا ان كل ما في السموات وما في الارض ملك لله تعالى، لا شيء من ذلك لاحد سواه. الا ان لقاء الله تعالى وعذابه للمشركين كائن، ولكن اكثرهم لا يعلمون حقيقه ذلك."},{"id":"1420","s":10,"a":56,"at":"هو يحيي ويميت واليه ترجعون","dt":"[56] ان الله هو المحيي والمميت لا يتعذر عليه احياء الناس بعد موتهم، كما لا تعجزه اماتتهم اذا اراد ذلك، وهم اليه راجعون بعد موتهم."},{"id":"1421","s":10,"a":57,"at":"ياايها الناس قد جاءتكم موعظه من ربكم وشفاء لما في الصدور وهدى ورحمه للمؤمنين","dt":"[57] يا ايها الناس قد جاءتكم موعظه من ربكم تذكركم عقاب الله وتخوفكم وعيده، وهي القران وما اشتمل عليه من الايات والعظات؛ لاصلاح اخلاقكم واعمالكم، وفيه دواء لما في القلوب من الجهل والشرك وسائر الامراض، ورشد لمن اتبعه من الخلق فينجيه من الهلاك، جعله سبحانه وتعالى نعمه ورحمه للمؤمنين، وخصهم بذلك؛ لانهم المنتفعون بالايمان، واما الكافرون فهو عليهم عمى."},{"id":"1422","s":10,"a":58,"at":"قل بفضل الله وبرحمته فبذلك فليفرحوا هو خير مما يجمعون","dt":"[58] قل -ايها الرسول- لجميع الناس: بفضل الله وبرحمته، وهو ما جاءهم من الله من الهدى ودين الحق وهو الاسلام، فبذلك فليفرحوا؛ فان الاسلام الذي دعاهم الله اليه، والقران الذي انزله على محمد -صلى الله عليه وسلم-، خير مما يجمعون من حطام الدنيا وما فيها من الزهره الفانيه الذاهبه."},{"id":"1423","s":10,"a":59,"at":"قل ارايتم ما انزل الله لكم من رزق فجعلتم منه حراما وحلالا قل الله اذن لكم ام على الله تفترون","dt":"[59] قل -ايها الرسول- لهؤلاء الجاحدين للوحي: اخبروني عن هذا الرزق الذي خلقه الله لكم من الحيوان والنبات والخيرات فحللتم بعض ذلك لانفسكم وحرمتم بعضه، قل لهم: الله اذن لكم بذلك، ام تقولون على الله الباطل وتكذبون؟ وانهم ليقولون على الله الباطل ويكذبون."},{"id":"1424","s":10,"a":60,"at":"وما ظن الذين يفترون على الله الكذب يوم القيامه ان الله لذو فضل على الناس ولكن اكثرهم لا يشكرون","dt":"[60] وما ظن هؤلاء الذين يتخرصون على الله الكذب يوم الحساب، فيضيفون اليه تحريم ما لم يحرمه عليهم من الارزاق والاقوات، ان الله فاعل بهم يوم القيامه بكذبهم وفريتهم عليه؟ ايحسبون انه يصفح عنهم ويغفر لهم؟ ان الله لذو فضل على خلقه؛ بتركه معاجله من افترى عليه الكذب بالعقوبه في الدنيا وامهاله اياه، ولكن اكثر الناس لا يشكرون الله على تفضله عليهم بذلك."},{"id":"1425","s":10,"a":61,"at":"وما تكون في شان وما تتلو منه من قران ولا تعملون من عمل الا كنا عليكم شهودا اذ تفيضون فيه وما يعزب عن ربك من مثقال ذره في الارض ولا في السماء ولا اصغر من ذلك ولا اكبر الا في كتاب مبين","dt":"[61] وما تكون -ايها الرسول -في امر من امورك وما تتلو من كتاب الله من ايات، وما يعمل احد من هذه الامه عملا من خير او شر الا كنا عليكم شهودا مطلعين عليه، اذ تاخذون في ذلك، وتعملونه، فنحفظه عليكم ونجزيكم به، وما يغيب عن علم ربك -ايها الرسول- من زنه نمله صغيره في الارض ولا في السماء، ولا اصغر الاشياء ولا اكبرها، الا في كتاب عند الله واضح جلي، احاط به علمه وجرى به قلمه."},{"id":"1426","s":10,"a":62,"at":"الا ان اولياء الله لا خوف عليهم ولا هم يحزنون","dt":"[62] الا ان اولياء الله لا خوف عليهم في الاخره من عقاب الله، ولا هم يحزنون على ما فاتهم من حظوظ الدنيا."},{"id":"1427","s":10,"a":63,"at":"الذين امنوا وكانوا يتقون","dt":"[63] وصفات هؤلاء الاولياء، انهم الذين صدقوا الله واتبعوا رسوله وما جاء به من عند الله، وكانوا يتقون الله بامتثال اوامره، واجتناب معاصيه."},{"id":"1428","s":10,"a":64,"at":"لهم البشرى في الحياه الدنيا وفي الاخره لا تبديل لكلمات الله ذلك هو الفوز العظيم","dt":"[64] لهؤلاء الاولياء البشاره من الله في الحياه الدنيا بما يسرهم، ومنها الرؤيا الصالحه يراها المؤمن او ترى له، وفي الاخره بالجنه، لا يخلف الله وعده ولا يغيره، ذلك هو الفوز العظيم؛ لانه اشتمل على النجاه من كل محذور، والظفر بكل مطلوب محبوب."},{"id":"1429","s":10,"a":65,"at":"ولا يحزنك قولهم ان العزه لله جميعا هو السميع العليم","dt":"[65] ولا يحزنك -ايها الرسول- قول المشركين في ربهم وافتراؤهم عليه واشراكهم معه الاوثان والاصنام؛ فان الله تعالى هو المتفرد بالقوه الكامله والقدره التامه في الدنيا والاخره، وهو السميع لاقوالهم، العليم بنياتهم وافعالهم."},{"id":"1430","s":10,"a":66,"at":"الا ان لله من في السموات ومن في الارض وما يتبع الذين يدعون من دون الله شركاء ان يتبعون الا الظن وان هم الا يخرصون","dt":"[66] الا ان لله كل من في السموات ومن في الارض من الملائكه، والانس، والجن وغير ذلك. واي شيء يتبع من يدعو غير الله من الشركاء؟ ما يتبعون الا الشك، وان هم الا يكذبون فيما ينسبونه الى الله."},{"id":"1431","s":10,"a":67,"at":"هو الذي جعل لكم الليل لتسكنوا فيه والنهار مبصرا ان في ذلك لايات لقوم يسمعون","dt":"[67] هو الذي جعل لكم -ايها الناس- الليل لتسكنوا فيه وتهدؤوا من عناء الحركه في طلب المعاش، وجعل لكم النهار؛ لتبصروا فيه، ولتسعوا لطلب رزقكم. ان في اختلاف الليل والنهار وحال اهلهما فيهما لدلاله وحججا على ان الله وحده هو المستحق للعباده، لقوم يسمعون هذه الحجج، ويتفكرون فيها."},{"id":"1432","s":10,"a":68,"at":"قالوا اتخذ الله ولدا سبحانه هو الغني له ما في السموات وما في الارض ان عندكم من سلطان بهذا اتقولون على الله ما لا تعلمون","dt":"[68] قال المشركون: اتخذ الله ولدا، كقولهم: الملائكه بنات الله، او المسيح ابن الله. تقدس الله عن ذلك كله وتنزه، هو الغني عن كل ما سواه، له كل ما في السموات والارض، فكيف يكون له ولد ممن خلق وكل شيء مملوك له؟ وليس لديكم دليل على ما تفترونه من الكذب، اتقولون على الله ما لا تعلمون حقيقته وصحته؟"},{"id":"1433","s":10,"a":69,"at":"قل ان الذين يفترون على الله الكذب لا يفلحون","dt":"[69] قل: ان الذين يفترون على الله الكذب باتخاذ الولد واضافه الشريك اليه، لا ينالون مطلوبهم في الدنيا ولا في الاخره."},{"id":"1434","s":10,"a":70,"at":"متاع في الدنيا ثم الينا مرجعهم ثم نذيقهم العذاب الشديد بما كانوا يكفرون","dt":"[70] انما يتمتعون في الدنيا بكفرهم وكذبهم متاعا قصيرا، ثم اذا انقضى اجلهم فالينا مصيرهم، ثم نذيقهم عذاب جهنم؛ بسبب كفرهم بالله وتكذيبهم رسل الله، وجحدهم اياته."},{"id":"1435","s":10,"a":71,"at":"واتل عليهم نبا نوح اذ قال لقومه ياقوم ان كان كبر عليكم مقامي وتذكيري بايات الله فعلى الله توكلت فاجمعوا امركم وشركاءكم ثم لا يكن امركم عليكم غمه ثم اقضوا الي ولا تنظرون","dt":"[71] واقصص -ايها الرسول- على كفار «مكه» خبر نوح -عليه السلام- مع قومه حين قال لهم: ان كان عظم عليكم مقامي فيكم وتذكيري اياكم بحجج الله وبراهينه فعلى الله اعتمادي وبه ثقتي، فاعدوا امركم، وادعوا شركاءكم، ثم لا تجعلوا امركم عليكم مستترا بل ظاهرا منكشفا، ثم اقضوا علي بالعقوبه والسوء الذي في امكانكم، ولا تمهلوني ساعه من نهار."},{"id":"1436","s":10,"a":72,"at":"فان توليتم فما سالتكم من اجر ان اجري الا على الله وامرت ان اكون من المسلمين","dt":"[72] فان اعرضتم عن دعوتي فانني لم اسالكم اجرا؛ لان ثوابي عند ربي واجري عليه سبحانه، وحده لا شريك له، وامرت ان اكون من المنقادين لحكمه."},{"id":"1437","s":10,"a":73,"at":"فكذبوه فنجيناه ومن معه في الفلك وجعلناهم خلائف واغرقنا الذين كذبوا باياتنا فانظر كيف كان عاقبه المنذرين","dt":"[73] فكذب نوحا قومه فيما اخبرهم به عن الله، فنجيناه هو ومن معه في السفينه، وجعلناهم يخلفون المكذبين في الارض، واغرقنا الذين جحدوا حججنا، فتامل -ايها الرسول- كيف كان عاقبه القوم الذين انذرهم رسولهم عذاب الله وباسه؟"},{"id":"1438","s":10,"a":74,"at":"ثم بعثنا من بعده رسلا الى قومهم فجاءوهم بالبينات فما كانوا ليؤمنوا بما كذبوا به من قبل كذلك نطبع على قلوب المعتدين","dt":"[74] ثم بعثنا من بعد نوح رسلا الى اقوامهم (هودا وصالحا وابراهيم ولوطا وشعيبا وغيرهم)، فجاء كل رسول قومه بالمعجزات الداله على رسالته، وعلى صحه ما دعاهم اليه، فما كانوا ليصدقوا ويعملوا بما كذب به قوم نوح ومن سبقهم من الامم الخاليه. وكما ختم الله على قلوب هؤلاء الاقوام فلم يؤمنوا، كذلك يختم على قلوب من شابههم ممن بعدهم من الذين تجاوزوا حدود الله، وخالفوا ما دعاهم اليه رسلهم من طاعته؛ عقوبه لهم على معاصيهم."},{"id":"1439","s":10,"a":75,"at":"ثم بعثنا من بعدهم موسى وهارون الى فرعون وملئه باياتنا فاستكبروا وكانوا قوما مجرمين","dt":"[75] ثم بعثنا من بعد اولئك الرسل موسى وهارون - عليهما السلام - الى فرعون واشراف قومه بالمعجزات الداله على صدقهما، فاستكبروا عن قبول الحق، وكانوا قوما مشركين مجرمين مكذبين."},{"id":"1440","s":10,"a":76,"at":"فلما جاءهم الحق من عندنا قالوا ان هذا لسحر مبين","dt":"[76] فلما اتى فرعون وقومه المعجزات التي جاء بها موسى قالوا: ان الذي جاء به موسى من الايات انما هو سحر ظاهر."},{"id":"1441","s":10,"a":77,"at":"قال موسى اتقولون للحق لما جاءكم اسحر هذا ولا يفلح الساحرون","dt":"[77] قال لهم موسى متعجبا من قولهم: اتقولون للحق لما جاءكم: انه سحر مبين؟ انظروا وصف ما جاءكم وما اشتمل عليه تجدوه الحق، ولا يفلح الساحرون، ولا يفوزون في الدنيا ولا في الاخره."},{"id":"1442","s":10,"a":78,"at":"قالوا اجئتنا لتلفتنا عما وجدنا عليه اباءنا وتكون لكما الكبرياء في الارض وما نحن لكما بمؤمنين","dt":"[78] قال فرعون وملؤه لموسى: اجئتنا لتصرفنا عما وجدنا عليه اباءنا من عباده غير الله، وتكون لكما -انت وهارون- العظمه والسلطان في ارض «مصر»؟ وما نحن لكما بمقرين بانكما رسولان ارسلتما الينا؛ لنعبد الله وحده لا شريك له."},{"id":"1443","s":10,"a":79,"at":"وقال فرعون ائتوني بكل ساحر عليم","dt":"[79] وقال فرعون: جيئوني بكل ساحر متقن للسحر."},{"id":"1444","s":10,"a":80,"at":"فلما جاء السحره قال لهم موسى القوا ما انتم ملقون","dt":"[80] فلما جاء السحره فرعون قال لهم موسى: القوا على الارض ما معكم من حبالكم وعصيكم."},{"id":"1445","s":10,"a":81,"at":"فلما القوا قال موسى ما جئتم به السحر ان الله سيبطله ان الله لا يصلح عمل المفسدين","dt":"[81] فلما القوا حبالهم وعصيهم قال لهم موسى: ان الذي جئتم به والقيتموه هو السحر، ان الله سيذهب ما جئتم به وسيبطله، ان الله لا يصلح عمل من سعى في ارض الله بما يكرهه، وافسد فيها بمعصيته."},{"id":"1446","s":10,"a":82,"at":"ويحق الله الحق بكلماته ولو كره المجرمون","dt":"[82] ويثبت الله الحق الذي جئتكم به من عنده فيعليه على باطلكم بكلماته وامره، ولو كره المجرمون اصحاب المعاصي من ال فرعون."},{"id":"1447","s":10,"a":83,"at":"فما امن لموسى الا ذريه من قومه على خوف من فرعون وملئهم ان يفتنهم وان فرعون لعال في الارض وانه لمن المسرفين","dt":"[83] فما امن لموسى عليه السلام -مع ما اتاهم به من الحجج والادله- الا ذريه من قومه من بني اسرائيل، وهم خائفون من فرعون وملئه ان يفتنوهم بالعذاب، فيصدوهم عن دينهم، وان فرعون لجبار مستكبر في الارض، وانه لمن المتجاوزين الحد في الكفر والفساد."},{"id":"1448","s":10,"a":84,"at":"وقال موسى ياقوم ان كنتم امنتم بالله فعليه توكلوا ان كنتم مسلمين","dt":"[84] وقال موسى: يا قومي ان صدقتم بالله -جل وعلا- وامتثلتم شرعه فثقوا به، وسلموا لامره، وعلى الله توكلوا ان كنتم مذعنين له بالطاعه."},{"id":"1449","s":10,"a":85,"at":"فقالوا على الله توكلنا ربنا لا تجعلنا فتنه للقوم الظالمين","dt":"[85] فقال قوم موسى له: على الله وحده لا شريك له اعتمدنا، واليه فوضنا امرنا، ربنا لا تنصرهم علينا فيكون ذلك فتنه لنا عن الدين، او يفتن الكفار بنصرهم، فيقولوا: لو كانوا على حق لما غلبوا."},{"id":"1450","s":10,"a":86,"at":"ونجنا برحمتك من القوم الكافرين","dt":"[86] ونجنا برحمتك من القوم الكافرين فرعون وملئه؛ لانهم كانوا ياخذونهم بالاعمال الشاقه."},{"id":"1451","s":10,"a":87,"at":"واوحينا الى موسى واخيه ان تبوا لقومكما بمصر بيوتا واجعلوا بيوتكم قبله واقيموا الصلاه وبشر المؤمنين","dt":"[87] واوحينا الى موسى واخيه هارون ان اتخذا لقومكما بيوتا في «مصر» تكون مساكن وملاجئ تعتصمون بها، واجعلوا بيوتكم اماكن تصلون فيها عند الخوف، وادوا الصلاه المفروضه في اوقاتها. وبشر المؤمنين المطيعين لله بالنصر المؤزر، والثواب الجزيل منه سبحانه وتعالى."},{"id":"1452","s":10,"a":88,"at":"وقال موسى ربنا انك اتيت فرعون وملاه زينه واموالا في الحياه الدنيا ربنا ليضلوا عن سبيلك ربنا اطمس على اموالهم واشدد على قلوبهم فلا يؤمنوا حتى يروا العذاب الاليم","dt":"[88] وقال موسى: ربنا انك اعطيت فرعون واشراف قومه زينه من متاع الدنيا، فلم يشكروا لك؛ وانما استعانوا بها على الاضلال عن سبيلك، ربنا اطمس على اموالهم، فلا ينتفعوا بها، واختم على قلوبهم حتى لا تنشرح للايمان، فلا يؤمنوا حتى يروا العذاب الشديد الموجع."},{"id":"1453","s":10,"a":89,"at":"قال قد اجيبت دعوتكما فاستقيما ولا تتبعان سبيل الذين لا يعلمون","dt":"[89] قال الله تعالى لهما: قد اجيبت دعوتكما في فرعون وملئه واموالهم -وكان موسى يدعو، وهارون يؤمن على دعائه، فمن هنا نسبت الدعوه الى الاثنين- فاستقيما على دينكما، واستمرا على دعوتكما فرعون وقومه الى توحيد الله وطاعته، ولا تسلكا طريق من لا يعلم حقيقه وعدي ووعيدي."},{"id":"1454","s":10,"a":90,"at":"وجاوزنا ببني اسرائيل البحر فاتبعهم فرعون وجنوده بغيا وعدوا حتى اذا ادركه الغرق قال امنت انه لا اله الا الذي امنت به بنو اسرائيل وانا من المسلمين","dt":"[90] وقطعنا ببني اسرائيل البحر حتى جاوزوه، فاتبعهم فرعون وجنوده ظلما وعدوانا، فسلكوا البحر وراءهم، حتى اذا احاط بفرعون الغرق قال: امنت انه لا اله الا الذي امنت به بنو اسرائيل، وانا من الموحدين المستسلمين بالانقياد والطاعه."},{"id":"1455","s":10,"a":91,"at":"الان وقد عصيت قبل وكنت من المفسدين","dt":"[91] الان يا فرعون، وقد نزل بك الموت تقر لله بالعبوديه، وقد عصيته قبل نزول عذابه بك، وكنت من المفسدين الصادين عن سبيله! فلا تنفعك التوبه ساعه الاحتضار ومشاهده الموت والعذاب."},{"id":"1456","s":10,"a":92,"at":"فاليوم ننجيك ببدنك لتكون لمن خلفك ايه وان كثيرا من الناس عن اياتنا لغافلون","dt":"[92] فاليوم نجعلك على مرتفع من الارض ببدنك، ينظر اليك من كذب بهلاكك؛ لتكون لمن بعدك من الناس عبره يعتبرون بك. وان كثيرا من الناس عن حججنا وادلتنا لغافلون، لا يتفكرون فيها ولا يعتبرون."},{"id":"1457","s":10,"a":93,"at":"ولقد بوانا بني اسرائيل مبوا صدق ورزقناهم من الطيبات فما اختلفوا حتى جاءهم العلم ان ربك يقضي بينهم يوم القيامه فيما كانوا فيه يختلفون","dt":"[93] ولقد انزلنا بني اسرائيل منزلا صالحا مختارا في بلاد «الشام» و «مصر»، ورزقناهم الرزق الحلال الطيب من خيرات الارض المباركه، فما اختلفوا في امر دينهم الا من بعد ما جاءهم العلم الموجب لاجتماعهم واتلافهم، ومن ذلك ما اشتملت عليه التوراه من الاخبار بنبوه محمد -صلى الله عليه وسلم-. ان ربك -ايها الرسول- يقضي بينهم يوم القيامه، ويفصل فيما كانوا يختلفون فيه من امرك، فيدخل المكذبين النار والمؤمنين الجنه."},{"id":"1458","s":10,"a":94,"at":"فان كنت في شك مما انزلنا اليك فاسال الذين يقرؤون الكتاب من قبلك لقد جاءك الحق من ربك فلا تكونن من الممترين","dt":"[94] فان كنت -ايها الرسول- في ريب من حقيقه ما اخبرناك به فاسال الذين يقرؤون الكتاب من قبلك، من اهل التوراه والانجيل سؤال تقرير واشهاد، فان ذلك ثابت في كتبهم، لقد جاءك الحق اليقين من ربك بانك رسول الله، وان هؤلاء اليهود والنصارى يعلمون صحه ذلك، ويجدون صفتك في كتبهم، ولكنهم ينكرون ذلك مع علمهم به، فلا تكونن من الشاكين في صحه ذلك وحقيقته. والمقصود من الايه اقامه الحجه على المشركين بشهاده اهل الكتاب من اليهود والنصارى؛ قطعا لمعذرتهم."},{"id":"1459","s":10,"a":95,"at":"ولا تكونن من الذين كذبوا بايات الله فتكون من الخاسرين","dt":"[95] ولا تكونن -ايها الرسول- من الذين كذبوا بحجج الله وادلته فتكون من الخاسرين الذين سخط الله عليهم ونالوا عقابه."},{"id":"1460","s":10,"a":96,"at":"ان الذين حقت عليهم كلمت ربك لا يؤمنون","dt":"[96] ان الذين حقت عليهم كلمه ربك -ايها الرسول- بطردهم من رحمته وعذابه لهم، لا يؤمنون بحجج الله، ولا يقرون بوحدانيته، ولا يعملون بشرعه."},{"id":"1461","s":10,"a":97,"at":"ولو جاءتهم كل ايه حتى يروا العذاب الاليم","dt":"[97] ولو جاءتهم كل موعظه وعبره حتى يعاينوا العذاب الموجع، فحينئذ يؤمنون، ولا ينفعهم ايمانهم."},{"id":"1462","s":10,"a":98,"at":"فلولا كانت قريه امنت فنفعها ايمانها الا قوم يونس لما امنوا كشفنا عنهم عذاب الخزي في الحياه الدنيا ومتعناهم الى حين","dt":"[98] لم ينفع الايمان اهل قريه امنوا عند معاينه العذاب الا اهل قريه يونس بن متى، فانهم لما ايقنوا ان العذاب نازل بهم تابوا الى الله تعالى توبه نصوحا، فلما تبين منهم الصدق في توبتهم كشف الله عنهم عذاب الخزي بعد ان اقترب منهم، وتركهم في الدنيا يستمتعون الى وقت انهاء اجالهم."},{"id":"1463","s":10,"a":99,"at":"ولو شاء ربك لامن من في الارض كلهم جميعا افانت تكره الناس حتى يكونوا مؤمنين","dt":"[99] ولو شاء ربك -ايها الرسول- الايمان لاهل الارض كلهم لامنوا جميعا بما جئتهم به، ولكن له حكمه في ذلك؛ فانه يهدي من يشاء ويضل من يشاء وفق حكمته، وليس في استطاعتك ان تكره الناس على الايمان."},{"id":"1464","s":10,"a":100,"at":"وما كان لنفس ان تؤمن الا باذن الله ويجعل الرجس على الذين لا يعقلون","dt":"[100] وما كان لنفس ان تؤمن بالله الا باذنه وتوفيقه، فلا تجهد نفسك في ذلك، فان امرهم الى الله. ويجعل الله العذاب والخزي على الذين لا يعقلون امره ونهيه."},{"id":"1465","s":10,"a":101,"at":"قل انظروا ماذا في السموات والارض وما تغني الايات والنذر عن قوم لا يؤمنون","dt":"[101] قل -ايها الرسول- لقومك: تفكروا واعتبروا بما في السموات والارض من ايات الله البينات، ولكن الايات والعبر والرسل المنذره عباد الله عقابه، لا تنفع قوما لا يؤمنون بشيء من ذلك؛ لاعراضهم وعنادهم."},{"id":"1466","s":10,"a":102,"at":"فهل ينتظرون الا مثل ايام الذين خلوا من قبلهم قل فانتظروا اني معكم من المنتظرين","dt":"[102] فهل ينتظر هؤلاء الا يوما يعاينون فيه عذاب الله مثل ايام اسلافهم المكذبين الذين مضوا قبلهم؟ قل لهم -ايها الرسول-: فانتظروا عقاب الله اني معكم من المنتظرين عقابكم."},{"id":"1467","s":10,"a":103,"at":"ثم ننجي رسلنا والذين امنوا كذلك حقا علينا ننج المؤمنين","dt":"[103] ثم ننجي رسلنا والذين امنوا معهم، وكما نجينا اولئك ننجيك -ايها الرسول- ومن امن بك تفضلا منا ورحمه."},{"id":"1468","s":10,"a":104,"at":"قل ياايها الناس ان كنتم في شك من ديني فلا اعبد الذين تعبدون من دون الله ولكن اعبد الله الذي يتوفاكم وامرت ان اكون من المؤمنين","dt":"[104] قل -ايها الرسول- لهؤلاء الناس: ان كنتم في شك من صحه ديني الذي دعوتكم اليه، وهو الاسلام، ومن ثباتي واستقامتي عليه، وترجون تحويلي عنه، فاني لا اعبد -في حال من الاحوال- احدا من الذين تعبدونهم مما اتخذتم من الاصنام والاوثان، ولكن اعبد الله وحده الذي يميتكم ويقبض ارواحكم، وامرت ان اكون من المصدقين به العاملين بشرعه."},{"id":"1469","s":10,"a":105,"at":"وان اقم وجهك للدين حنيفا ولا تكونن من المشركين","dt":"[105] وان اقم -ايها الرسول- نفسك على دين الاسلام مستقيما عليه، غير مائل عنه الى يهوديه ولا نصرانيه ولا عباده غيره، ولا تكونن ممن يشرك في عباده ربه الالهه والانداد، فتكون من الهالكين. وهذا وان كان خطابا للرسول -صلى الله عليه وسلم- فانه موجه لعموم الامه."},{"id":"1470","s":10,"a":106,"at":"ولا تدع من دون الله ما لا ينفعك ولا يضرك فان فعلت فانك اذا من الظالمين","dt":"[106] ولا تدع -ايها الرسول- من دون الله شيئا من الاوثان والاصنام؛ لانها لا تنفع ولا تضر، فان فعلت ذلك ودعوتها من دون الله فانك اذا من المشركين بالله، الظالمين لانفسهم بالشرك والمعصيه. وهذا وان كان خطابا للرسول -صلى الله عليه وسلم- فانه موجه لعموم الامه."},{"id":"1471","s":10,"a":107,"at":"وان يمسسك الله بضر فلا كاشف له الا هو وان يردك بخير فلا راد لفضله يصيب به من يشاء من عباده وهو الغفور الرحيم","dt":"[107] وان يصبك الله -ايها الرسول- بشده او بلاء فلا كاشف لذلك الا هو جل وعلا، وان يردك برخاء او نعمه لا يمنعه عنك احد، يصيب الله عز وجل بالسراء والضراء من يشاء من عباده، وهو الغفور لذنوب من تاب، الرحيم بمن امن به واطاعه."},{"id":"1472","s":10,"a":108,"at":"قل ياايها الناس قد جاءكم الحق من ربكم فمن اهتدى فانما يهتدي لنفسه ومن ضل فانما يضل عليها وما انا عليكم بوكيل","dt":"[108] قل -ايها الرسول- لهؤلاء الناس: قد جاءكم رسول الله بالقران الذي فيه بيان هدايتكم، فمن اهتدى بهدي الله فانما ثمره عمله راجعه اليه، ومن انحرف عن الحق واصر على الضلال فانما ضلاله وضرره على نفسه، وما انا موكل بكم حتى تكونوا مؤمنين، انما انا رسول مبلغ ابلغكم ما ارسلت به."},{"id":"1473","s":10,"a":109,"at":"واتبع ما يوحى اليك واصبر حتى يحكم الله وهو خير الحاكمين","dt":"[109] واتبع -ايها الرسول- وحي الله الذي يوحيه اليك فاعمل به، واصبر على طاعه الله تعالى، وعن معصيته، وعلى اذى من اذاك في تبليغ رسالته، حتى يقضي الله فيهم وفيك امره، وهو -عز وجل- خير الحاكمين؛ فان حكمه مشتمل على العدل التام."},{"id":"1474","s":11,"a":1,"at":"الر كتاب احكمت اياته ثم فصلت من لدن حكيم خبير","dt":"[1] الر سبق الكلام على الحروف المقطعه في اول سوره البقره.هذا الكتاب الذي انزله الله على محمد -صلى الله عليه وسلم- احكمت اياته من الخلل والباطل، ثم بينت بالامر والنهي وبيان الحلال والحرام من عند الله، الحكيم بتدبير الامور، الخبير بما تؤول اليه عواقبها."},{"id":"1475","s":11,"a":2,"at":"الا تعبدوا الا الله انني لكم منه نذير وبشير","dt":"[2] وانزال القران وبيان احكامه وتفصيلها واحكامها؛ لاجل ان لا تعبدوا الا الله وحده لا شريك له. انني لكم -ايها الناس- من عند الله نذير ينذركم عقابه، وبشير يبشركم بثوابه."},{"id":"1476","s":11,"a":3,"at":"وان استغفروا ربكم ثم توبوا اليه يمتعكم متاعا حسنا الى اجل مسمى ويؤت كل ذي فضل فضله وان تولوا فاني اخاف عليكم عذاب يوم كبير","dt":"[3] واسالوه ان يغفر لكم ذنوبكم، ثم ارجعوا اليه نادمين يمتعكم في دنياكم متاعا حسنا بالحياه الطيبه فيها، الى ان يحين اجلكم، ويعط كل ذي فضل من علم وعمل جزاء فضله كاملا لا نقص فيه، وان تعرضوا عما ادعوكم اليه فاني اخشى عليكم عذاب يوم شديد، وهو يوم القيامه. وهذا تهديد شديد لمن تولى عن اوامر الله تعالى وكذب رسله."},{"id":"1477","s":11,"a":4,"at":"الى الله مرجعكم وهو على كل شيء قدير","dt":"[4] الى الله رجوعكم بعد موتكم جميعا فاحذروا عقابه، وهو سبحانه قادر على بعثكم وحشركم وجزائكم."},{"id":"1478","s":11,"a":5,"at":"الا انهم يثنون صدورهم ليستخفوا منه الا حين يستغشون ثيابهم يعلم ما يسرون وما يعلنون انه عليم بذات الصدور","dt":"[5] ان هؤلاء المشركين يضمرون في صدورهم الكفر؛ ظنا منهم انه يخفى على الله ما تضمره نفوسهم، الا يعلمون حين يغطون اجسادهم بثيابهم ان الله لا يخفى عليه سرهم وعلانيتهم؟ انه عليم بكل ما تكنه صدورهم من النيات والضمائر والسرائر."},{"id":"1479","s":11,"a":6,"at":"وما من دابه في الارض الا على الله رزقها ويعلم مستقرها ومستودعها كل في كتاب مبين","dt":"[6] لقد تكفل الله برزق جميع ما دب على وجه الارض، تفضلا منه، ويعلم مكان استقراره في حياته وبعد موته، ويعلم الموضع الذي يموت فيه، كل ذلك مكتوب في كتاب عند الله مبين عن جميع ذلك."},{"id":"1480","s":11,"a":7,"at":"وهو الذي خلق السموات والارض في سته ايام وكان عرشه على الماء ليبلوكم ايكم احسن عملا ولئن قلت انكم مبعوثون من بعد الموت ليقولن الذين كفروا ان هذا الا سحر مبين","dt":"[7] وهو الذي خلق السموات والارض وما فيهن في سته ايام، وكان عرشه على الماء قبل ذلك؛ ليختبركم ايكم احسن له طاعه وعملا، وهو ما كان خالصا لله موافقا لما كان عليه رسول الله -صلى الله عليه وسلم-. ولئن قلت -ايها الرسول- لهؤلاء المشركين من قومك: انكم مبعوثون احياء بعد موتكم، لسارعوا الى التكذيب وقالوا: ما هذا القران الذي تتلوه علينا الا سحر بين."},{"id":"1481","s":11,"a":8,"at":"ولئن اخرنا عنهم العذاب الى امه معدوده ليقولن ما يحبسه الا يوم ياتيهم ليس مصروفا عنهم وحاق بهم ما كانوا به يستهزئون","dt":"[8] ولئن اخرنا عن هؤلاء المشركين العذاب الى اجل معلوم فاستبطؤوه، ليقولن استهزاء وتكذيبا: اي شيء يمنع هذا العذاب من الوقوع ان كان حقا؟ الا يوم ياتيهم ذلك العذاب لا يستطيع ان يصرفه عنهم صارف، ولا يدفعه دافع، واحاط بهم من كل جانب عذاب ما كانوا يستهزئون به قبل وقوعه بهم."},{"id":"1482","s":11,"a":9,"at":"ولئن اذقنا الانسان منا رحمه ثم نزعناها منه انه ليئوس كفور","dt":"[9] ولئن اعطينا الانسان منا نعمه من صحه وامن وغيرهما، ثم سلبناها منه، انه لشديد الياس من رحمه الله، جحود بالنعم التي انعم الله بها عليه."},{"id":"1483","s":11,"a":10,"at":"ولئن اذقناه نعماء بعد ضراء مسته ليقولن ذهب السيئات عني انه لفرح فخور","dt":"[10] ولئن بسطنا للانسان في دنياه ووسعنا عليه في رزقه بعد ضيق من العيش، ليقولن عند ذلك: ذهب الضيق عني وزالت الشدائد، انه لبطر بالنعم، مبالغ في الفخر والتعالي على الناس."},{"id":"1484","s":11,"a":11,"at":"الا الذين صبروا وعملوا الصالحات اولئك لهم مغفره واجر كبير","dt":"[11] لكن الذين صبروا على ما اصابهم من الضراء، ايمانا بالله واحتسابا للاجر عنده، وعملوا الصالحات؛ شكرا لله على نعمه، هؤلاء لهم مغفره لذنوبهم واجر كبير في الاخره."},{"id":"1485","s":11,"a":12,"at":"فلعلك تارك بعض ما يوحى اليك وضائق به صدرك ان يقولوا لولا انزل عليه كنز او جاء معه ملك انما انت نذير والله على كل شيء وكيل","dt":"[12] فلعلك -ايها الرسول، لعظم ما تراه منهم من الكفر والتكذيب- تارك بعض ما يوحى اليك مما انزله الله عليك وامرك بتبليغه، مما يشق على المشركين سماعه ويثير غضبهم، وضائق به صدرك؛ خشيه ان يطلبوا منك بعض المطالب على وجه التعنت، كان يقولوا: لولا انزل عليه مال كثير، او جاء معه ملك يصدقه في رسالته، فبلغهم ما اوحيته اليك؛ فانه ليس عليك الا الانذار بما اوحي اليك. والله على كل شيء حفيظ يدبر جميع شؤون خلقه."},{"id":"1486","s":11,"a":13,"at":"ام يقولون افتراه قل فاتوا بعشر سور مثله مفتريات وادعوا من استطعتم من دون الله ان كنتم صادقين","dt":"[13] بل ايقول هؤلاء المشركون من اهل «مكه»: ان محمدا قد افترى هذا القران؟ قل لهم: ان كان الامر كما تزعمون فاتوا بعشر سور مثله مفتريات، وادعوا من استطعتم من جميع خلق الله ليساعدوكم على الاتيان بهذه السور العشر، ان كنتم صادقين في دعواكم."},{"id":"1487","s":11,"a":14,"at":"فالم يستجيبوا لكم فاعلموا انما انزل بعلم الله وان لا اله الا هو فهل انتم مسلمون","dt":"[14] فان لم يستجب هؤلاء المشركون لكم -ايها الرسول- ومن امن معك- لما تدعونهم اليه؛ لعجز الجميع عن ذلك، فاعلموا ان هذا القران انما انزله الله على رسوله بعلمه وليس من قول البشر، واعلموا ان لا اله يعبد بحق الا الله، فهل انتم -بعد قيام هذه الحجه عليكم- مسلمون منقادون لله ورسوله؟"},{"id":"1488","s":11,"a":15,"at":"من كان يريد الحياه الدنيا وزينتها نوف اليهم اعمالهم فيها وهم فيها لا يبخسون","dt":"[15] من كان يريد بعمله الحياه الدنيا ومتعها نعطهم ما قسم لهم من ثواب اعمالهم في الحياه الدنيا كاملا غير منقوص."},{"id":"1489","s":11,"a":16,"at":"اولئك الذين ليس لهم في الاخره الا النار وحبط ما صنعوا فيها وباطل ما كانوا يعملون","dt":"[16] اولئك ليس لهم في الاخره الا نار جهنم يقاسون حرها، وذهب عنهم نفع ما عملوه، وكان عملهم باطلا؛ لانه لم يكن لوجه الله."},{"id":"1490","s":11,"a":17,"at":"افمن كان على بينه من ربه ويتلوه شاهد منه ومن قبله كتاب موسى اماما ورحمه اولئك يؤمنون به ومن يكفر به من الاحزاب فالنار موعده فلا تك في مريه منه انه الحق من ربك ولكن اكثر الناس لا يؤمنون","dt":"[17] افمن كان على حجه وبصيره من ربه فيما يؤمن به، ويدعو اليه بالوحي الذي انزل الله فيه هذه البينه، ويتلوها برهان اخر يشهد على كونه من عند الله، وهو جبريل او محمد عليهما السلام، ويؤيد ذلك برهان ثالث من قبل القران، وهو التوراه -الكتاب الذي انزل على موسى اماما ورحمه لمن امن به-، كمن كان همه الحياه الفانيه بزينتها؟ اولئك يصدقون بهذا القران ويعملون باحكامه، ومن يكفر بهذا القران من الذين تحزبوا على رسول الله -صلى الله عليه وسلم- فجزاؤه النار، يردها لا محاله، فلا تك -ايها الرسول- في شك من امر القران وكونه من عند الله تعالى، بعد ما شهدت بذلك الادله والحجج، واعلم ان هذا الدين هو الحق من ربك، ولكن اكثر الناس لا يصدقون ولا يعملون بما امروا به. وهذا توجيه عام لامه محمد -صلى الله عليه وسلم-."},{"id":"1491","s":11,"a":18,"at":"ومن اظلم ممن افترى على الله كذبا اولئك يعرضون على ربهم ويقول الاشهاد هؤلاء الذين كذبوا على ربهم الا لعنه الله على الظالمين","dt":"[18] ولا احد اظلم ممن اختلق على الله كذبا، اولئك سيعرضون على ربهم يوم القيامه؛ ليحاسبهم على اعمالهم. ويقول الاشهاد من الملائكه والنبيين وغيرهم: هؤلاء الذين كذبوا على ربهم في الدنيا، قد سخط الله عليهم، ولعنهم لعنه لا تنقطع؛ لان الظلم الذي اقترفوه صار وصفا ملازما لهم."},{"id":"1492","s":11,"a":19,"at":"الذين يصدون عن سبيل الله ويبغونها عوجا وهم بالاخره هم كافرون","dt":"[19] هؤلاء الظالمون الذين يمنعون الناس عن سبيل الله الموصله الى عبادته، ويريدون ان تكون هذه السبيل عوجاء بموافقتها لاهوائهم، وهم كافرون بالاخره لا يؤمنون ببعث ولا جزاء."},{"id":"1493","s":11,"a":20,"at":"اولئك لم يكونوا معجزين في الارض وما كان لهم من دون الله من اولياء يضاعف لهم العذاب ما كانوا يستطيعون السمع وما كانوا يبصرون","dt":"[20] اولئك الكافرون لم يكونوا ليفوتوا الله في الدنيا هربا، وما كان لهم من انصار يمنعونهم من عقابه. يضاعف لهم العذاب في جهنم؛ لانهم كانوا لا يستطيعون ان يسمعوا القران سماع منتفع، او يبصروا ايات الله في هذا الكون ابصار مهتد؛ لاشتغالهم بالكفر الذي كانوا عليه مقيمين."},{"id":"1494","s":11,"a":21,"at":"اولئك الذين خسروا انفسهم وضل عنهم ما كانوا يفترون","dt":"[21] اولئك الذين خسروا انفسهم بافترائهم على الله، وذهب عنهم ما كانوا يفترون من الالهه التي يدعون انها تشفع لهم."},{"id":"1495","s":11,"a":22,"at":"لا جرم انهم في الاخره هم الاخسرون","dt":"[22] حقا انهم في الاخره اخسر الناس صفقه؛ لانهم استبدلوا الدركات بالدرجات، فكانوا في جهنم، وذلك هو الخسران المبين."},{"id":"1496","s":11,"a":23,"at":"ان الذين امنوا وعملوا الصالحات واخبتوا الى ربهم اولئك اصحاب الجنه هم فيها خالدون","dt":"[23] ان الذين صدقوا الله ورسوله وعملوا الاعمال الصالحه، وخضعوا لله في كل ما امروا به ونهوا عنه، اولئك هم اهل الجنه، لا يموتون فيها، ولا يخرجون منها ابدا."},{"id":"1497","s":11,"a":24,"at":"مثل الفريقين كالاعمى والاصم والبصير والسميع هل يستويان مثلا افلا تذكرون","dt":"[24] مثل فريقي الكفر والايمان كمثل الاعمى الذي لا يرى والاصم الذي لا يسمع والبصير والسميع: ففريق الكفر لا يبصر الحق فيتبعه، ولا يسمع داعي الله فيهتدي به، اما فريق الايمان فقد ابصر حجج الله وسمع داعي الله فاجابه، هل يستوي هذان الفريقان؟ افلا تعتبرون وتتفكرون؟"},{"id":"1498","s":11,"a":25,"at":"ولقد ارسلنا نوحا الى قومه اني لكم نذير مبين","dt":"[25] ولقد ارسلنا نوحا الى قومه فقال لهم: اني نذير لكم من عذاب الله، مبين لكم ما ارسلت به اليكم من امر الله ونهيه."},{"id":"1499","s":11,"a":26,"at":"ان لا تعبدوا الا الله اني اخاف عليكم عذاب يوم اليم","dt":"[26] امركم الا تعبدوا الا الله، اني اخاف عليكم -ان لم تفردوا الله وحده بالعباده- عذاب يوم موجع."},{"id":"1500","s":11,"a":27,"at":"فقال الملا الذين كفروا من قومه ما نراك الا بشرا مثلنا وما نراك اتبعك الا الذين هم اراذلنا بادي الراي وما نرى لكم علينا من فضل بل نظنكم كاذبين","dt":"[27] فقال رؤساء الكفر من قومه: انك لست بملك ولكنك بشر، فكيف اوحي اليك من دوننا؟ وما نراك اتبعك الا الذين هم اسافلنا وانما اتبعوك من غير تفكر ولا رويه، وما نرى لكم علينا من فضل في رزق ولا مال لما دخلتم في دينكم هذا، بل نعتقد انكم كاذبون فيما تدعون."},{"id":"1501","s":11,"a":28,"at":"قال ياقوم ارايتم ان كنت على بينه من ربي واتاني رحمه من عنده فعميت عليكم انلزمكموها وانتم لها كارهون","dt":"[28] قال نوح: يا قومي ارايتم ان كنت على حجه ظاهره من ربي فيما جئتكم به تبين لكم انني على الحق من عنده، واتاني رحمه من عنده، وهي النبوه والرساله فاخفاها عليكم بسبب جهلكم وغروركم، فهل يصح ان نلزمكم اياها بالاكراه وانتم جاحدون بها؟ لا نفعل ذلك، ولكن نكل امركم الى الله حتى يقضي في امركم ما يشاء."},{"id":"1502","s":11,"a":29,"at":"وياقوم لا اسالكم عليه مالا ان اجري الا على الله وما انا بطارد الذين امنوا انهم ملاقو ربهم ولكني اراكم قوما تجهلون","dt":"[29] قال نوح عليه السلام لقومه: يا قوم لا اسالكم على دعوتكم لتوحيد الله واخلاص العباده له مالا تؤدونه الي بعد ايمانكم، ولكن ثواب نصحي لكم على الله وحده، وليس من شاني ان اطرد المؤمنين، فانهم ملاقو ربهم يوم القيامه، ولكني اراكم قوما تجهلون؛ اذ تامرونني بطرد اولياء الله وابعادهم عني."},{"id":"1503","s":11,"a":30,"at":"وياقوم من ينصرني من الله ان طردتهم افلا تذكرون","dt":"[30] ويا قوم من يمنعني من الله ان عاقبني على طردي المؤمنين؟ افلا تتدبرون الامور فتعلموا ما هو الانفع لكم والاصلح؟"},{"id":"1504","s":11,"a":31,"at":"ولا اقول لكم عندي خزائن الله ولا اعلم الغيب ولا اقول اني ملك ولا اقول للذين تزدري اعينكم لن يؤتيهم الله خيرا الله اعلم بما في انفسهم اني اذا لمن الظالمين","dt":"[31] ولا اقول لكم: اني املك التصرف في خزائن الله، ولا اعلم الغيب، ولست بملك من الملائكه، ولا اقول لهؤلاء الذين تحتقرون من ضعفاء المؤمنين: لن يؤتيكم الله ثوابا على اعمالكم، فالله وحده اعلم بما في صدورهم وقلوبهم، ولئن فعلت ذلك اني اذا لمن الظالمين لانفسهم ولغيرهم."},{"id":"1505","s":11,"a":32,"at":"قالوا يانوح قد جادلتنا فاكثرت جدالنا فاتنا بما تعدنا ان كنت من الصادقين","dt":"[32] قالوا: يا نوح قد حاججتنا فاكثرت جدالنا، فاتنا بما تعدنا من العذاب ان كنت من الصادقين في دعواك."},{"id":"1506","s":11,"a":33,"at":"قال انما ياتيكم به الله ان شاء وما انتم بمعجزين","dt":"[33] قال نوح لقومه: ان الله وحده هو الذي ياتيكم بالعذاب اذا شاء، ولستم بفائتيه اذا اراد ان يعذبكم؛ لانه سبحانه لا يعجزه شيء في الارض ولا في السماء."},{"id":"1507","s":11,"a":34,"at":"ولا ينفعكم نصحي ان اردت ان انصح لكم ان كان الله يريد ان يغويكم هو ربكم واليه ترجعون","dt":"[34] ولا ينفعكم نصحي واجتهادي في دعوتكم للايمان، ان كان الله يريد ان يضلكم ويهلككم، هو سبحانه مالككم، واليه ترجعون في الاخره للحساب والجزاء."},{"id":"1508","s":11,"a":35,"at":"ام يقولون افتراه قل ان افتريته فعلي اجرامي وانا بريء مما تجرمون","dt":"[35] بل ايقول هؤلاء المشركون من قوم نوح: افترى نوح هذا القول؟ قل لهم: ان كنت قد افتريت ذلك على الله فعلي وحدي اثم ذلك، واذا كنت صادقا فانتم المجرمون الاثمون، وانا بريء من كفركم وتكذيبكم واجرامكم."},{"id":"1509","s":11,"a":36,"at":"واوحي الى نوح انه لن يؤمن من قومك الا من قد امن فلا تبتئس بما كانوا يفعلون","dt":"[36] واوحى الله سبحانه وتعالى الى نوح -عليه السلام- لما حق على قومه العذاب، انه لن يؤمن بالله الا من قد امن من قبل، فلا تحزن يا نوح على ما كانوا يفعلون."},{"id":"1510","s":11,"a":37,"at":"واصنع الفلك باعيننا ووحينا ولا تخاطبني في الذين ظلموا انهم مغرقون","dt":"[37] واصنع السفينه بمراى منا وبامرنا لك ومعونتنا، وانت في حفظنا وكلاءتنا، ولا تطلب مني امهال هؤلاء الذين ظلموا انفسهم من قومك بكفرهم، فانهم مغرقون بالطوفان. وفي الايه اثبات صفه العين لله تعالى على ما يليق به سبحانه."},{"id":"1511","s":11,"a":38,"at":"ويصنع الفلك وكلما مر عليه ملا من قومه سخروا منه قال ان تسخروا منا فانا نسخر منكم كما تسخرون","dt":"[38] ويصنع نوح السفينه، وكلما مر عليه جماعه من كبراء قومه سخروا منه، قال لهم نوح: ان تسخروا منا اليوم لجهلكم بصدق وعد الله، فانا نسخر منكم غدا عند الغرق كما تسخرون منا."},{"id":"1512","s":11,"a":39,"at":"فسوف تعلمون من ياتيه عذاب يخزيه ويحل عليه عذاب مقيم","dt":"[39] فسوف تعلمون اذا جاء امر الله بذلك: من الذي ياتيه في الدنيا عذاب الله الذي يهينه، وينزل به في الاخره عذاب دائم لا انقطاع له؟"},{"id":"1513","s":11,"a":40,"at":"حتى اذا جاء امرنا وفار التنور قلنا احمل فيها من كل زوجين اثنين واهلك الا من سبق عليه القول ومن امن وما امن معه الا قليل","dt":"[40] حتى اذا جاء امرنا باهلاكهم كما وعدنا نوحا بذلك، ونبع الماء بقوه من التنور -وهو المكان الذي يخبز فيه- علامه على مجيء العذاب، قلنا لنوح: احمل في السفينه من كل نوع من انواع الحيوانات ذكرا وانثى، واحمل فيها اهل بيتك، الا من سبق عليهم القول ممن لم يؤمن بالله كابنه وامراته، واحمل فيها من امن معك من قومك، وما امن معه الا قليل مع طول المده والمقام فيهم."},{"id":"1514","s":11,"a":41,"at":"وقال اركبوا فيها بسم الله مجراها ومرساها ان ربي لغفور رحيم","dt":"[41] وقال نوح لمن امن معه: اركبوا في السفينه، باسم الله يكون جريها على وجه الماء، وباسم الله يكون منتهى سيرها ورسوها. ان ربي لغفور ذنوب من تاب واناب اليه من عباده، رحيم بهم ان يعذبهم بعد التوبه."},{"id":"1515","s":11,"a":42,"at":"وهي تجري بهم في موج كالجبال ونادى نوح ابنه وكان في معزل يابني اركب معنا ولا تكن مع الكافرين","dt":"[42] وهي تجري بهم في موج يعلو ويرتفع حتى يصير كالجبال في علوها، ونادى نوح ابنه -وكان في مكان عزل فيه نفسه عن المؤمنين- فقال له: يا بني اركب معنا في السفينه، ولا تكن مع الكافرين بالله فتغرق."},{"id":"1516","s":11,"a":43,"at":"قال ساوي الى جبل يعصمني من الماء قال لا عاصم اليوم من امر الله الا من رحم وحال بينهما الموج فكان من المغرقين","dt":"[43] قال ابن نوح: سالجا الى جبل اتحصن به من الماء، فيمنعني من الغرق، فاجابه نوح: لا مانع اليوم من امر الله وقضائه الذي قد نزل بالخلق من الغرق والهلاك الا من رحمه الله تعالى، فامن واركب في السفينه معنا، وحال الموج المرتفع بين نوح وابنه، فكان من المغرقين الهالكين."},{"id":"1517","s":11,"a":44,"at":"وقيل ياارض ابلعي ماءك وياسماء اقلعي وغيض الماء وقضي الامر واستوت على الجودي وقيل بعدا للقوم الظالمين","dt":"[44] وقال الله للارض- بعد هلاك قوم نوح-: يا ارض اشربي ماءك، ويا سماء امسكي عن المطر، ونقص الماء ونضب، وقضي امر الله بهلاك قوم نوح، ورست السفينه على جبل الجودي، وقيل: هلاكا وبعدا للقوم الظالمين الذين تجاوزوا حدود الله، ولم يؤمنوا به."},{"id":"1518","s":11,"a":45,"at":"ونادى نوح ربه فقال رب ان ابني من اهلي وان وعدك الحق وانت احكم الحاكمين","dt":"[45] ونادى نوح ربه فقال: رب انك وعدتني ان تنجيني واهلي من الغرق والهلاك، وان ابني هذا من اهلي، وان وعدك الحق الذي لا خلف فيه، وانت احكم الحاكمين واعدلهم."},{"id":"1519","s":11,"a":46,"at":"قال يانوح انه ليس من اهلك انه عمل غير صالح فلا تسالن ما ليس لك به علم اني اعظك ان تكون من الجاهلين","dt":"[46] قال الله: يا نوح ان ابنك الذي هلك ليس من اهلك الذين وعدتك ان انجيهم؛ وذلك بسبب كفره، وعمله عملا غير صالح، واني انهاك ان تسالني امرا لا علم لك به، اني اعظك لئلا تكون من الجاهلين في مسالتك اياي عن ذلك."},{"id":"1520","s":11,"a":47,"at":"قال رب اني اعوذ بك ان اسالك ما ليس لي به علم والا تغفر لي وترحمني اكن من الخاسرين","dt":"[47] قال نوح: يا رب اني اعتصم واستجير بك ان اسالك ما ليس لي به علم، وان لم تغفر لي ذنبي، وترحمني برحمتك، اكن من الذين غبنوا انفسهم حظوظها وهلكوا."},{"id":"1521","s":11,"a":48,"at":"قيل يانوح اهبط بسلام منا وبركات عليك وعلى امم ممن معك وامم سنمتعهم ثم يمسهم منا عذاب اليم","dt":"[48] قال الله: يا نوح اهبط من السفينه الى الارض بامن وسلامه منا وخيرات ونعم دائمه عليك وعلى امم ممن معك. وهناك امم وجماعات من اهل الشقاء سنمتعهم في الحياه الدنيا، الى ان يبلغوا اجالهم، ثم ينالهم منا العذاب الموجع يوم القيامه."},{"id":"1522","s":11,"a":49,"at":"تلك من انباء الغيب نوحيها اليك ما كنت تعلمها انت ولا قومك من قبل هذا فاصبر ان العاقبه للمتقين","dt":"[49] تلك القصه التي قصصناها عليك -ايها الرسول- عن نوح وقومه هي من اخبار الغيب السالفه، نوحيها اليك، ما كنت تعلمها انت ولا قومك من قبل هذا البيان، فاصبر على تكذيب قومك وايذائهم لك، كما صبر الانبياء من قبل، ان العاقبه الطيبه في الدنيا والاخره للمتقين الذين يخشون الله."},{"id":"1523","s":11,"a":50,"at":"والى عاد اخاهم هودا قال ياقوم اعبدوا الله ما لكم من اله غيره ان انتم الا مفترون","dt":"[50] وارسلنا الى عاد اخاهم هودا، قال لهم: يا قوم اعبدوا الله وحده، ليس لكم من اله يستحق العباده غيره جل وعلا، فاخلصوا له العباده، فما انتم الا كاذبون في اشراككم بالله."},{"id":"1524","s":11,"a":51,"at":"ياقوم لا اسالكم عليه اجرا ان اجري الا على الذي فطرني افلا تعقلون","dt":"[51] يا قوم لا اسالكم على ما ادعوكم اليه من اخلاص العباده لله وترك عباده الاوثان اجرا، ما اجري على دعوتي لكم الا على الله الذي خلقني، افلا تعقلون فتميزوا بين الحق والباطل؟"},{"id":"1525","s":11,"a":52,"at":"وياقوم استغفروا ربكم ثم توبوا اليه يرسل السماء عليكم مدرارا ويزدكم قوه الى قوتكم ولا تتولوا مجرمين","dt":"[52] ويا قوم اطلبوا مغفره الله بالايمان به، ثم توبوا اليه من ذنوبكم، فانكم ان فعلتم ذلك يرسل المطر عليكم متتابعا كثيرا، فتكثر خيراتكم، ويزدكم قوه الى قوتكم بكثره ذرياتكم وتتابع النعم عليكم، ولا تعرضوا عما دعوتكم اليه مصرين على اجرامكم."},{"id":"1526","s":11,"a":53,"at":"قالوا ياهود ما جئتنا ببينه وما نحن بتاركي الهتنا عن قولك وما نحن لك بمؤمنين","dt":"[53] قالوا: يا هود ما جئتنا بحجه واضحه على صحه ما تدعونا اليه، وما نحن بتاركي الهتنا التي نعبدها من اجل قولك، وما نحن بمصدقين لك فيما تدعيه."},{"id":"1527","s":11,"a":54,"at":"ان نقول الا اعتراك بعض الهتنا بسوء قال اني اشهد الله واشهدوا اني بريء مما تشركون","dt":"[54] ما نقول الا ان بعض الهتنا اصابك بجنون بسبب نهيك عن عبادتها. قال لهم: اني اشهد الله على ما اقول، واشهدكم على انني بريء مما تشركون."},{"id":"1528","s":11,"a":55,"at":"من دونه فكيدوني جميعا ثم لا تنظرون","dt":"[55]، من دون الله من الانداد والاصنام، فانظروا واجتهدوا انتم ومن زعمتم من الهتكم في الحاق الضرر بي، ثم لا تؤخروا ذلك طرفه عين؛ ذلك ان هودا واثق كل الوثوق انه لا يصيبه منهم ولا من الهتهم اذى."},{"id":"1529","s":11,"a":56,"at":"اني توكلت على الله ربي وربكم ما من دابه الا هو اخذ بناصيتها ان ربي على صراط مستقيم","dt":"[56] اني توكلت على الله ربي وربكم مالك كل شيء والمتصرف فيه، فلا يصيبني شيء الا بامره، وهو القادر على كل شيء، فليس من شيء يدب على هذه الارض الا والله مالكه، وهو في سلطانه وتصرفه. ان ربي على صراط مستقيم، اي عدل في قضائه وشرعه وامره. يجازي المحسن باحسانه والمسيء باساءته."},{"id":"1530","s":11,"a":57,"at":"فان تولوا فقد ابلغتكم ما ارسلت به اليكم ويستخلف ربي قوما غيركم ولا تضرونه شيئا ان ربي على كل شيء حفيظ","dt":"[57] فان تعرضوا عما ادعوكم اليه من توحيد الله واخلاص العباده له فقد ابلغتكم رساله ربي اليكم، وقامت عليكم الحجه، وحيث لم تؤمنوا بالله فسيهلككم وياتي بقوم اخرين يخلفونكم في دياركم واموالكم، ويخلصون لله العباده، ولا تضرونه شيئا، ان ربي على كل شيء حفيظ، فهو الذي يحفظني من ان تنالوني بسوء."},{"id":"1531","s":11,"a":58,"at":"ولما جاء امرنا نجينا هودا والذين امنوا معه برحمه منا ونجيناهم من عذاب غليظ","dt":"[58] ولما جاء امرنا بعذاب قوم هود نجينا منه هودا والمؤمنين بفضل منا عليهم ورحمه، ونجيناهم من عذاب شديد احله الله بعاد فاصبحوا لا يرى الا مساكنهم."},{"id":"1532","s":11,"a":59,"at":"وتلك عاد جحدوا بايات ربهم وعصوا رسله واتبعوا امر كل جبار عنيد","dt":"[59] وتلك عاد كفروا بايات الله وعصوا رسله، واطاعوا امر كل مستكبر على الله لا يقبل الحق ولا يذعن له."},{"id":"1533","s":11,"a":60,"at":"واتبعوا في هذه الدنيا لعنه ويوم القيامه الا ان عادا كفروا ربهم الا بعدا لعاد قوم هود","dt":"[60] واتبعوا في هذه الدنيا لعنه من الله وسخطا منه يوم القيامه. الا ان عادا جحدوا ربهم وكذبوا رسله. الا بعدا وهلاكا لعاد قوم هود؛ بسبب شركهم وكفرهم نعمه ربهم."},{"id":"1534","s":11,"a":61,"at":"والى ثمود اخاهم صالحا قال ياقوم اعبدوا الله ما لكم من اله غيره هو انشاكم من الارض واستعمركم فيها فاستغفروه ثم توبوا اليه ان ربي قريب مجيب","dt":"[61] وارسلنا الى ثمود اخاهم صالحا، فقال لهم: يا قوم اعبدوا الله وحده ليس لكم من اله يستحق العباده غيره جل وعلا، فاخلصوا له العباده، هو الذي بدا خلقكم من الارض بخلق ابيكم ادم منها، وجعلكم عمارا لها، فاسالوه ان يغفر لكم ذنوبكم، وارجعوا اليه بالتوبه النصوح. ان ربي قريب لمن اخلص له العباده، ورغب اليه في التوبه، مجيب له اذا دعاه."},{"id":"1535","s":11,"a":62,"at":"قالوا ياصالح قد كنت فينا مرجوا قبل هذا اتنهانا ان نعبد ما يعبد اباؤنا واننا لفي شك مما تدعونا اليه مريب","dt":"[62] قالت ثمود لنبيهم صالح: لقد كنا نرجو ان تكون فينا سيدا مطاعا قبل هذا القول الذي قلته لنا، اتنهانا ان نعبد الالهه التي كان يعبدها اباؤنا؟ واننا لفي شك مريب من دعوتك لنا الى عباده الله وحده."},{"id":"1536","s":11,"a":63,"at":"قال ياقوم ارايتم ان كنت على بينه من ربي واتاني منه رحمه فمن ينصرني من الله ان عصيته فما تزيدونني غير تخسير","dt":"[63] قال صالح لقومه: يا قوم اخبروني ان كنت على برهان من الله واتاني منه النبوه والحكمه، فمن الذي يدفع عني عقاب الله تعالى ان عصيته فلم ابلغ الرساله وانصح لكم؟ فما تزيدونني غير تضليل وابعاد عن الخير."},{"id":"1537","s":11,"a":64,"at":"وياقوم هذه ناقه الله لكم ايه فذروها تاكل في ارض الله ولا تمسوها بسوء فياخذكم عذاب قريب","dt":"[64] ويا قوم هذه ناقه الله جعلها لكم حجه وعلامه تدل على صدقي فيما ادعوكم اليه، فاتركوها تاكل في ارض الله فليس عليكم رزقها، ولا تمسوها بعقر، فانكم ان فعلتم ذلك ياخذكم من الله عذاب قريب من عقرها."},{"id":"1538","s":11,"a":65,"at":"فعقروها فقال تمتعوا في داركم ثلاثه ايام ذلك وعد غير مكذوب","dt":"[65] فكذبوه ونحروا الناقه، فقال لهم صالح: استمتعوا بحياتكم في بلدكم ثلاثه ايام، فان العذاب نازل بكم بعدها، وذلك وعد من الله غير مكذوب، لابد من وقوعه."},{"id":"1539","s":11,"a":66,"at":"فلما جاء امرنا نجينا صالحا والذين امنوا معه برحمه منا ومن خزي يومئذ ان ربك هو القوي العزيز","dt":"[66] فلما جاء امرنا بهلاك ثمود نجينا صالحا والذين امنوا معه من الهلاك برحمه منا، ونجيناهم من هوان ذلك اليوم وذلته. ان ربك -ايها الرسول- هو القوي العزيز، ومن قوته وعزته ان اهلك الامم الطاغيه، ونجى الرسل واتباعهم."},{"id":"1540","s":11,"a":67,"at":"واخذ الذين ظلموا الصيحه فاصبحوا في ديارهم جاثمين","dt":"[67] واخذت الصيحه القويه ثمود الظالمين، فاصبحوا في ديارهم موتى هامدين ساقطين على وجوههم لا حراك بهم."},{"id":"1541","s":11,"a":68,"at":"كان لم يغنوا فيها الا ان ثمود كفروا ربهم الا بعدا لثمود","dt":"[68] كانهم في سرعه زوالهم وفنائهم لم يعيشوا فيها. الا ان ثمود جحدوا بايات ربهم وحججه. الا بعدا لثمود وطردا لهم من رحمه الله، فما اشقاهم واذلهم!"},{"id":"1542","s":11,"a":69,"at":"ولقد جاءت رسلنا ابراهيم بالبشرى قالوا سلاما قال سلام فما لبث ان جاء بعجل حنيذ","dt":"[69] ولقد جاءت الملائكه ابراهيم - عليه السلام - يبشرونه هو وزوجته باسحاق، ويعقوب بعده، فقالوا: سلاما، قال ردا على تحيتهم: سلام، فذهب سريعا وجاءهم بعجل سمين مشوي لياكلوا منه."},{"id":"1543","s":11,"a":70,"at":"فلما راى ايديهم لا تصل اليه نكرهم واوجس منهم خيفه قالوا لا تخف انا ارسلنا الى قوم لوط","dt":"[70] فلما راى ابراهيم ايديهم لا تصل الى العجل الذي اتاهم به ولا ياكلون منه، انكر ذلك منهم، واحس في نفسه خيفه واضمرها، قالت الملائكه -لما رات ما بابراهيم من الخوف-: لا تخف انا ملائكه ربك ارسلنا الى قوم لوط لاهلاكهم."},{"id":"1544","s":11,"a":71,"at":"وامراته قائمه فضحكت فبشرناها باسحاق ومن وراء اسحاق يعقوب","dt":"[71] وامراه ابراهيم -ساره- كانت قائمه من وراء الستر تسمع الكلام، فضحكت تعجبا مما سمعت، فبشرناها - على السنه الملائكه - بانها ستلد من زوجها ابراهيم ولدا يسمى اسحاق، وسيعيش ولدها، وسيكون لها بعد اسحاق حفيد منه، وهو يعقوب."},{"id":"1545","s":11,"a":72,"at":"قالت ياويلتى االد وانا عجوز وهذا بعلي شيخا ان هذا لشيء عجيب","dt":"[72] قالت ساره لما بشرت باسحاق متعجبه: يا و يلتا كيف يكون لي ولد وانا عجوز، وهذا زوجي في حال الشيخوخه والكبر؟ ان انجاب الولد من مثلي ومثل زوجي مع كبر السن لشيء عجيب."},{"id":"1546","s":11,"a":73,"at":"قالوا اتعجبين من امر الله رحمه الله وبركاته عليكم اهل البيت انه حميد مجيد","dt":"[73] قالت الرسل لها: اتعجبين من امر الله وقضائه؟ رحمه الله وبركاته عليكم معشر اهل بيت النبوه. انه سبحانه وتعالى حميد الصفات والافعال، ذو مجد وعظمه فيها."},{"id":"1547","s":11,"a":74,"at":"فلما ذهب عن ابراهيم الروع وجاءته البشرى يجادلنا في قوم لوط","dt":"[74] فلما ذهب عن ابراهيم الخوف الذي انتابه لعدم اكل الضيوف الطعام، وجاءته البشرى باسحاق ويعقوب، ظل يجادل رسلنا فيما ارسلناهم به من عقاب قوم لوط واهلاكهم."},{"id":"1548","s":11,"a":75,"at":"ان ابراهيم لحليم اواه منيب","dt":"[75] ان ابراهيم كثير الحلم لا يحب المعاجله بالعقاب، كثير التضرع الى الله والدعاء له، تائب يرجع الى الله في اموره كلها."},{"id":"1549","s":11,"a":76,"at":"ياابراهيم اعرض عن هذا انه قد جاء امر ربك وانهم اتيهم عذاب غير مردود","dt":"[76] قالت رسل الله: يا ابراهيم اعرض عن هذا الجدال في امر قوم لوط والتماس الرحمه لهم؛ فانه قد حق عليهم العذاب، وجاء امر ربك الذي قدره عليهم بهلاكهم، وانهم نازل بهم عذاب من الله غير مصروف عنهم ولا مدفوع."},{"id":"1550","s":11,"a":77,"at":"ولما جاءت رسلنا لوطا سيء بهم وضاق بهم ذرعا وقال هذا يوم عصيب","dt":"[77] ولما جاءت ملائكتنا لوطا ساءه مجيئهم واغتم لذلك؛ وذلك لانه لم يكن يعلم انهم رسل الله، فخاف عليهم من قومه، وقال: هذا يوم بلاء وشده."},{"id":"1551","s":11,"a":78,"at":"وجاءه قومه يهرعون اليه ومن قبل كانوا يعملون السيئات قال ياقوم هؤلاء بناتي هن اطهر لكم فاتقوا الله ولا تخزون في ضيفي اليس منكم رجل رشيد","dt":"[78] وجاء قوم لوط يسرعون المشي اليه لطلب الفاحشه، وكانوا من قبل مجيئهم ياتون الرجال شهوه دون النساء، فقال لوط لقومه: هؤلاء بناتي تزوجوهن فهن اطهر لكم مما تريدون، وسماهن بناته؛ لان نبي الامه بمنزله الاب لهم، فاخشوا الله واحذروا عقابه، ولا تفضحوني بالاعتداء على ضيفي، اليس منكم رجل حسن التقدير للامور، ينهى من اراد ركوب الفاحشه، فيحول بينهم وبينها، فاهانه الضيف مسبه لا يفعلها الا اهل السفاهه؟"},{"id":"1552","s":11,"a":79,"at":"قالوا لقد علمت ما لنا في بناتك من حق وانك لتعلم ما نريد","dt":"[79] قال قوم لوط له: لقد علمت من قبل انه ليس لنا في النساء من حاجه او رغبه، وانك لتعلم ما نريد، اي لا نريد الا الرجال ولا رغبه لنا في نكاح النساء."},{"id":"1553","s":11,"a":80,"at":"قال لو ان لي بكم قوه او اوي الى ركن شديد","dt":"[80] قال لهم حين ابوا الا فعل الفاحشه: لو ان لي بكم قوه وانصارا معي، او اركن الى عشيره تمنعني منكم، لحلت بينكم وبين ما تريدون."},{"id":"1554","s":11,"a":81,"at":"قالوا يالوط انا رسل ربك لن يصلوا اليك فاسر باهلك بقطع من الليل ولا يلتفت منكم احد الا امراتك انه مصيبها ما اصابهم ان موعدهم الصبح اليس الصبح بقريب","dt":"[81] قالت الملائكه: يا لوط انا رسل ربك ارسلنا لاهلاك قومك، وانهم لن يصلوا اليك، فاخرج من هذه القريه انت واهلك ببقيه من الليل، ولا يلتفت منكم احد وراءه؛ لئلا يرى العذاب فيصيبه، لكن امراتك التي خانتك بالكفر والنفاق سيصيبها ما اصاب قومك من الهلاك، ان موعد هلاكهم الصبح، وهو موعد قريب الحلول."},{"id":"1555","s":11,"a":82,"at":"فلما جاء امرنا جعلنا عاليها سافلها وامطرنا عليها حجاره من سجيل منضود","dt":"[82] فلما جاء امرنا بنزول العذاب بهم جعلنا عالي قراهم التي كانوا يعيشون فيها سافلها فقلبناها، وامطرنا عليهم حجاره من طين متصلب متين، قد صف بعضها الى بعض متتابعه"},{"id":"1556","s":11,"a":83,"at":"مسومه عند ربك وما هي من الظالمين ببعيد","dt":"[83] معلمه عند الله بعلامه معروفه لا تشاكل حجاره الارض، وما هذه الحجاره التي امطرها الله على قوم لوط من كفار قريش ببعيد ان يمطروا بمثلها. وفي هذا تهديد لكل عاص متمرد على الله."},{"id":"1557","s":11,"a":84,"at":"والى مدين اخاهم شعيبا قال ياقوم اعبدوا الله ما لكم من اله غيره ولا تنقصوا المكيال والميزان اني اراكم بخير واني اخاف عليكم عذاب يوم محيط","dt":"[84] وارسلنا الى «مدين» اخاهم شعيبا، فقال: يا قوم اعبدوا الله وحده، ليس لكم من اله يستحق العباده غيره جل وعلا، فاخلصوا له العباده، ولا تنقصوا الناس حقوقهم في مكاييلهم وموازينهم، اني اراكم في سعه عيش، واني اخاف عليكم -بسبب انقاص المكيال والميزان- عذاب يوم يحيط بكم."},{"id":"1558","s":11,"a":85,"at":"وياقوم اوفوا المكيال والميزان بالقسط ولا تبخسوا الناس اشياءهم ولا تعثوا في الارض مفسدين","dt":"[85] ويا قوم اتموا المكيال والميزان بالعدل، ولا تنقصوا الناس حقهم في عموم اشيائهم، ولا تسيروا في الارض تعملون فيها بمعاصي الله ونشر الفساد."},{"id":"1559","s":11,"a":86,"at":"بقيه الله خير لكم ان كنتم مؤمنين وما انا عليكم بحفيظ","dt":"[86] ان ما يبقى لكم بعد ايفاء الكيل والميزان من الربح الحلال فيه بركه وخير لكم مما تاخذونه بالتطفيف ونحوه من الكسب الحرام، ان كنتم تؤمنون بالله حقا، فامتثلوا امره، وما انا عليكم برقيب احصي عليكم اعمالكم."},{"id":"1560","s":11,"a":87,"at":"قالوا ياشعيب اصلاتك تامرك ان نترك ما يعبد اباؤنا او ان نفعل في اموالنا ما نشاء انك لانت الحليم الرشيد","dt":"[87] قالوا: يا شعيب اهذه الصلاه التي تداوم عليها تامرك بان نترك ما يعبده اباؤنا من الاصنام والاوثان، او ان نمتنع عن التصرف في كسب اموالنا بما نستطيع من احتيال ومكر؟ وقالوا -استهزاء به-: انك لانت العاقل الحسن التدبير في المال."},{"id":"1561","s":11,"a":88,"at":"قال ياقوم ارايتم ان كنت على بينه من ربي ورزقني منه رزقا حسنا وما اريد ان اخالفكم الى ما انهاكم عنه ان اريد الا الاصلاح ما استطعت وما توفيقي الا بالله عليه توكلت واليه انيب","dt":"[88] قال شعيب: يا قوم ارايتم ان كنت على طريق واضح من ربي فيما ادعوكم اليه من اخلاص العباده له، وفيما انهاكم عنه من افساد المال، ورزقني منه رزقا واسعا حلالا طيبا؟ وما اريد ان اخالفكم فارتكب امرا نهيتكم عنه، وما اريد فيما امركم به وانهاكم عنه الا اصلاحكم قدر طاقتي واستطاعتي، وما توفيقي -في اصابه الحق ومحاوله اصلاحكم- الا بالله، على الله وحده توكلت واليه ارجع بالتوبه والانابه."},{"id":"1562","s":11,"a":89,"at":"وياقوم لا يجرمنكم شقاقي ان يصيبكم مثل ما اصاب قوم نوح او قوم هود او قوم صالح وما قوم لوط منكم ببعيد","dt":"[89] ويا قوم لا تحملنكم عداوتي وبغضي وفراق الدين الذي انا عليه على العناد والاصرار على ما انتم عليه من الكفر بالله، فيصيبكم مثل ما اصاب قوم نوح او قوم هود او قوم صالح من الهلاك، وما قوم لوط وما حل بهم من العذاب ببعيدين عنكم لا في الدار ولا في الزمان."},{"id":"1563","s":11,"a":90,"at":"واستغفروا ربكم ثم توبوا اليه ان ربي رحيم ودود","dt":"[90] واطلبوا من ربكم المغفره لذنوبكم، ثم ارجعوا الى طاعته واستمروا عليها. ان ربي رحيم كثير الموده والمحبه لمن تاب اليه واناب، يرحمه ويقبل توبته. وفي الايه اثبات صفه الرحمه والموده لله تعالى، كما يليق به سبحانه."},{"id":"1564","s":11,"a":91,"at":"قالوا ياشعيب ما نفقه كثيرا مما تقول وانا لنراك فينا ضعيفا ولولا رهطك لرجمناك وما انت علينا بعزيز","dt":"[91] قالوا: يا شعيب ما نفقه كثيرا مما تقول، واننا لنراك فينا ضعيفا لست من الكبراء ولا من الرؤساء، ولولا مراعاه عشيرتك لقتلناك رجما بالحجاره -وكان رهطه من اهل ملتهم-، وليس لك قدر واحترام في نفوسنا."},{"id":"1565","s":11,"a":92,"at":"قال ياقوم ارهطي اعز عليكم من الله واتخذتموه وراءكم ظهريا ان ربي بما تعملون محيط","dt":"[92] قال: يا قوم اعشيرتي اعز واكرم عليكم من الله؟ ونبذتم امر ربكم فجعلتموه خلف ظهوركم، لا تاتمرون به ولا تنتهون بنهيه، ان ربي بما تعملون محيط، لا يخفى عليه من اعمالكم مثقال ذره، وسيجازيكم عليها عاجلا واجلا."},{"id":"1566","s":11,"a":93,"at":"وياقوم اعملوا على مكانتكم اني عامل سوف تعلمون من ياتيه عذاب يخزيه ومن هو كاذب وارتقبوا اني معكم رقيب","dt":"[93] ويا قوم اعملوا كل ما تستطيعون على طريقتكم وحالتكم، اني عامل مثابر على طريقتي وما وهبني ربي من دعوتكم الى التوحيد، سوف تعلمون من منا ياتيه عذاب يذله، ومن منا كاذب في قوله، انا ام انتم؟ وانتظروا ما سيحل بكم اني معكم من المنتظرين. وهذا تهديد شديد لهم."},{"id":"1567","s":11,"a":94,"at":"ولما جاء امرنا نجينا شعيبا والذين امنوا معه برحمه منا واخذت الذين ظلموا الصيحه فاصبحوا في ديارهم جاثمين","dt":"[94] ولما جاء امرنا باهلاك قوم شعيب نجينا رسولنا شعيبا والذين امنوا معه برحمه منا، واخذت الذين ظلموا الصيحه من السماء، فاهلكتهم، فاصبحوا في ديارهم باركين على ركبهم ميتين لا حراك بهم."},{"id":"1568","s":11,"a":95,"at":"كان لم يغنوا فيها الا بعدا لمدين كما بعدت ثمود","dt":"[95] كان لم يقيموا في ديارهم وقتا من الاوقات. الا بعدا ل«مدين» -اذ اهلكها الله واخزاها- كما بعدت ثمود، فقد اشتركت هاتان القبيلتان في البعد والهلاك."},{"id":"1569","s":11,"a":96,"at":"ولقد ارسلنا موسى باياتنا وسلطان مبين","dt":"[96] ولقد ارسلنا موسى بادلتنا على توحيدنا وحجه تبين لمن عاينها وتاملها -بقلب صحيح- انها تدل على وحدانيه الله، وكذب كل من ادعى الربوبيه دونه سبحانه وتعالى."},{"id":"1570","s":11,"a":97,"at":"الى فرعون وملئه فاتبعوا امر فرعون وما امر فرعون برشيد","dt":"[97] ارسلنا موسى الى فرعون واكابر اتباعه واشراف قومه، فكفر فرعون، وامر قومه ان يتبعوه فاطاعوه، وخالفوا امر موسى، وليس في امر فرعون رشد ولا هدى، وانما هو جهل وضلال وكفر وعناد."},{"id":"1571","s":11,"a":98,"at":"يقدم قومه يوم القيامه فاوردهم النار وبئس الورد المورود","dt":"[98] يقدم فرعون قومه يوم القيامه حتى يدخلهم النار، وقبح المدخل الذي يدخلونه."},{"id":"1572","s":11,"a":99,"at":"واتبعوا في هذه لعنه ويوم القيامه بئس الرفد المرفود","dt":"[99] واتبعهم الله في هذه الدنيا مع العذاب الذي عجله لهم فيها من الغرق في البحر لعنه، ويوم القيامه كذلك لعنه اخرى بادخالهم النار، وبئس ما اجتمع لهم وترادف عليهم من عذاب الله، ولعنه الدنيا والاخره."},{"id":"1573","s":11,"a":100,"at":"ذلك من انباء القرى نقصه عليك منها قائم وحصيد","dt":"[100] ذلك الذي ذكرناه لك -ايها الرسول- من اخبار القرى التي اهلكنا اهلها نخبرك به، ومن تلك القرى ما له اثار باقيه، ومنها ما قد محيت اثاره، فلم يبق منه شيء."},{"id":"1574","s":11,"a":101,"at":"وما ظلمناهم ولكن ظلموا انفسهم فما اغنت عنهم الهتهم التي يدعون من دون الله من شيء لما جاء امر ربك وما زادوهم غير تتبيب","dt":"[101] وما كان اهلاكهم بغير سبب وذنب يستحقونه، ولكن ظلموا انفسهم بشركهم وافسادهم في الارض، فما نفعتهم الهتهم التي كانوا يدعونها ويطلبون منها ان تدفع عنهم الضر لما جاء امر ربك بعذابهم، وما زادتهم الهتهم غير تدمير واهلاك وخسران."},{"id":"1575","s":11,"a":102,"at":"وكذلك اخذ ربك اذا اخذ القرى وهي ظالمه ان اخذه اليم شديد","dt":"[102] وكما اخذت اهل القرى الظالمه بالعذاب لمخالفتهم امري وتكذيبهم برسلي، اخذ غيرهم من اهل القرى اذا ظلموا انفسهم بكفرهم بالله ومعصيتهم له وتكذيبهم لرسله. ان اخذه بالعقوبه لاليم موجع شديد."},{"id":"1576","s":11,"a":103,"at":"ان في ذلك لايه لمن خاف عذاب الاخره ذلك يوم مجموع له الناس وذلك يوم مشهود","dt":"[103] ان في اخذنا لاهل القرى السابقه الظالمه لعبره وعظه لمن خاف عقاب الله وعذابه في الاخره، ذلك اليوم الذي يجمع له الناس جميعا للمحاسبه والجزاء، ويشهده الخلائق كلهم."},{"id":"1577","s":11,"a":104,"at":"وما نؤخره الا لاجل معدود","dt":"[104] وما نؤخر يوم القيامه عنكم الا لانتهاء مده معدوده في علمنا، لا تزيد ولا تنقص عن تقديرنا لها بحكمتنا."},{"id":"1578","s":11,"a":105,"at":"يوم يات لا تكلم نفس الا باذنه فمنهم شقي وسعيد","dt":"[105] يوم ياتي يوم القيامه، لا تتكلم نفس الا باذن ربها، فمنهم شقي مستحق للعذاب، وسعيد متفضل عليه بالنعيم."},{"id":"1579","s":11,"a":106,"at":"فاما الذين شقوا ففي النار لهم فيها زفير وشهيق","dt":"[106] فاما الذين شقوا في الدنيا لفساد عقيدتهم وسوء اعمالهم، فالنار مستقرهم، لهم فيها -من شده ما هم فيه من العذاب- اخراج النفس من الصدر بدفع ورده اليه بشده، وهما اشنع الاصوات واقبحها"},{"id":"1580","s":11,"a":107,"at":"خالدين فيها ما دامت السموات والارض الا ما شاء ربك ان ربك فعال لما يريد","dt":"[107] ماكثين في النار ابدا ما دامت السموات والارض، فلا ينقطع عذابهم ولا ينتهي، بل هو دائم مؤكد، الا ما شاء ربك من اخراج عصاه الموحدين بعد مده من مكثهم في النار. ان ربك -ايها الرسول- فعال لما يريد."},{"id":"1581","s":11,"a":108,"at":"واما الذين سعدوا ففي الجنه خالدين فيها ما دامت السموات والارض الا ما شاء ربك عطاء غير مجذوذ","dt":"[108] واما الذين رزقهم الله السعاده فيدخلون الجنه خالدين فيها ما دامت السموات والارض، الا الفريق الذي شاء الله تاخيره، وهم عصاه الموحدين، فانهم يبقون في النار فتره من الزمن، ثم يخرجون منها الى الجنه بمشيئه الله ورحمته، ويعطي ربك هؤلاء السعداء في الجنه عطاء غير مقطوع عنهم."},{"id":"1582","s":11,"a":109,"at":"فلا تك في مريه مما يعبد هؤلاء ما يعبدون الا كما يعبد اباؤهم من قبل وانا لموفوهم نصيبهم غير منقوص","dt":"[109] فلا تكن- ايها الرسول- في شك من بطلان ما يعبد هؤلاء المشركون من قومك، ما يعبدون من الاوثان الا مثل ما يعبد اباؤهم من قبل، وانا لموفوهم ما وعدناهم تاما غير منقوص. وهذا توجيه لجميع الامه، وان كان لفظه موجها الى الرسول -صلى الله عليه وسلم-."},{"id":"1583","s":11,"a":110,"at":"ولقد اتينا موسى الكتاب فاختلف فيه ولولا كلمه سبقت من ربك لقضي بينهم وانهم لفي شك منه مريب","dt":"[110] ولقد اتينا موسى الكتاب وهو التوراه، فاختلف فيه قومه، فامن به جماعه وكفر به اخرون، كما فعل قومك بالقران. ولولا كلمه سبقت من ربك بانه لا يعجل لخلقه العذاب، لحل بهم في دنياهم قضاء الله باهلاك المكذبين ونجاه المؤمنين. وان الكفار من اليهود والمشركين -ايها الرسول- لفي شك -من هذا القران- مريب."},{"id":"1584","s":11,"a":111,"at":"وان كلا لما ليوفينهم ربك اعمالهم انه بما يعملون خبير","dt":"[111] وان كل اولئك الاقوام المختلفين الذين ذكرنا لك -ايها الرسول- اخبارهم ليوفينهم ربك جزاء اعمالهم يوم القيامه، ان خيرا فخير، وان شرا فشر، ان ربك بما يعمل هؤلاء المشركون خبير، لا يخفى عليه شيء من عملهم. وفي هذا تهديد ووعيد لهم."},{"id":"1585","s":11,"a":112,"at":"فاستقم كما امرت ومن تاب معك ولا تطغوا انه بما تعملون بصير","dt":"[112] فاستقم -ايها النبي- كما امرك ربك انت ومن تاب معك، ولا تتجاوزوا ما حده الله لكم، ان ربكم بما تعملون من الاعمال كلها بصير، لا يخفى عليه شيء منها، وسيجازيكم عليها."},{"id":"1586","s":11,"a":113,"at":"ولا تركنوا الى الذين ظلموا فتمسكم النار وما لكم من دون الله من اولياء ثم لا تنصرون","dt":"[113] ولا تميلوا الى هؤلاء الكفار الظلمه، فتصيبكم النار، وما لكم من دون الله من ناصر ينصركم، ويتولى اموركم."},{"id":"1587","s":11,"a":114,"at":"واقم الصلاه طرفي النهار وزلفا من الليل ان الحسنات يذهبن السيئات ذلك ذكرى للذاكرين","dt":"[114] واد الصلاه -ايها النبي- على اتم وجه، طرفي النهار في الصباح والمساء، وفي ساعات من الليل. ان فعل الخيرات يكفر الذنوب السالفه ويمحو اثارها، والامر باقامه الصلاه وبيان ان الحسنات يذهبن السيئات، موعظه لمن اتعظ بها وتذكر."},{"id":"1588","s":11,"a":115,"at":"واصبر فان الله لا يضيع اجر المحسنين","dt":"[115] واصبر -ايها النبي- على الصلاه، وعلى ما تلقى من الاذى من مشركي قومك؛ فان الله لا يضيع ثواب المحسنين في اعمالهم."},{"id":"1589","s":11,"a":116,"at":"فلولا كان من القرون من قبلكم اولو بقيه ينهون عن الفساد في الارض الا قليلا ممن انجينا منهم واتبع الذين ظلموا ما اترفوا فيه وكانوا مجرمين","dt":"[116] فهلا وجد من القرون الماضيه بقايا من اهل الخير والصلاح، ينهون اهل الكفر عن كفرهم، وعن الفساد في الارض، لم يوجد من اولئك الاقوام الا قليل ممن امن، فنجاهم الله بسبب ذلك من عذابه حين اخذ الظالمين. واتبع الذين ظلموا انفسهم من كل امه سلفت ما متعوا فيه من لذات الدنيا ونعيمها، وكانوا مجرمين ظالمين باتباعهم ما تنعموا فيه، فحق عليهم العذاب. وفي الايه عبره وموعظه للعصاه من المسلمين؛ لانهم لا يخلون من ظلم انفسهم."},{"id":"1590","s":11,"a":117,"at":"وما كان ربك ليهلك القرى بظلم واهلها مصلحون","dt":"[117] وما كان ربك -ايها الرسول- ليهلك قريه من القرى واهلها مصلحون في الارض، مجتنبون للفساد والظلم، وانما يهلكهم بسبب ظلمهم وفسادهم."},{"id":"1591","s":11,"a":118,"at":"ولو شاء ربك لجعل الناس امه واحده ولا يزالون مختلفين","dt":"[118] ولو شاء ربك لجعل الناس كلهم جماعه واحده على دين واحد وهو دين الاسلام، ولكنه سبحانه لم يشا ذلك، فلا يزال الناس مختلفين في اديانهم؛ وذلك مقتضى حكمته."},{"id":"1592","s":11,"a":119,"at":"الا من رحم ربك ولذلك خلقهم وتمت كلمه ربك لاملان جهنم من الجنه والناس اجمعين","dt":"[119] الا من رحم ربك فامنوا به واتبعوا رسله، فانهم لا يختلفون في توحيد الله وما جاءت به الرسل من عند الله، وقد اقتضت حكمته سبحانه وتعالى انه خلقهم مختلفين: فريق شقي وفريق سعيد، وكل ميسر لما خلق له. وبهذا يتحقق وعد ربك في قضائه وقدره: انه سبحانه سيملا جهنم من الجن والانس الذين اتبعوا ابليس وجنده ولم يهتدوا للايمان."},{"id":"1593","s":11,"a":120,"at":"وكلا نقص عليك من انباء الرسل ما نثبت به فؤادك وجاءك في هذه الحق وموعظه وذكرى للمؤمنين","dt":"[120] ونقص عليك -ايها الرسول- من اخبار الرسل الذين كانوا قبلك، كل ما تحتاج اليه مما يقوي قلبك للقيام باعباء الرساله، وقد جاءك في هذه السوره وما اشتملت عليه من اخبار، بيان الحق الذي انت عليه، وجاءك فيها موعظه يرتدع بها الكافرون، وذكرى يتذكر بها المؤمنون بالله ورسله."},{"id":"1594","s":11,"a":121,"at":"وقل للذين لا يؤمنون اعملوا على مكانتكم انا عاملون","dt":"[121] وقل -ايها الرسول- للكافرين الذين لا يقرون بوحدانيه الله: اعملوا ما انتم عاملون على حالتكم وطريقتكم في مقاومه الدعوه وايذاء الرسول والمستجيبين له، فانا عاملون على مكانتنا وطريقتنا من الثبات على ديننا وتنفيذ امر الله."},{"id":"1595","s":11,"a":122,"at":"وانتظروا انا منتظرون","dt":"[122] وانتظروا عاقبه امرنا، فانا منتظرون عاقبه امركم. وفي هذا تهديد ووعيد لهم."},{"id":"1596","s":11,"a":123,"at":"ولله غيب السموات والارض واليه يرجع الامر كله فاعبده وتوكل عليه وما ربك بغافل عما تعملون","dt":"[123] ولله سبحانه وتعالى علم كل ما غاب في السموات والارض، واليه يرجع الامر كله يوم القيامه، فاعبده -ايها النبي- وفوض امرك اليه، وما ربك بغافل عما تعملون من الخير والشر، وسيجازي كلا بعمله."},{"id":"1597","s":12,"a":1,"at":"الر تلك ايات الكتاب المبين","dt":"[1] الر سبق الكلام على الحروف المقطعه في اول سوره البقره.هذه ايات الكتاب البين الواضح في معانيه وحلاله وحرامه وهداه."},{"id":"1598","s":12,"a":2,"at":"انا انزلناه قرانا عربيا لعلكم تعقلون","dt":"[2] انا انزلنا هذا القران بلغه العرب؛ لعلكم -ايها العرب- تعقلون معانيه وتفهمونها، وتعملون بهديه."},{"id":"1599","s":12,"a":3,"at":"نحن نقص عليك احسن القصص بما اوحينا اليك هذا القران وان كنت من قبله لمن الغافلين","dt":"[3] نحن نقص عليك -ايها الرسول- احسن القصص بوحينا اليك هذا القران، وان كنت قبل انزاله عليك لمن الغافلين عن هذه الاخبار، لا تدري عنها شيئا."},{"id":"1600","s":12,"a":4,"at":"اذ قال يوسف لابيه ياابت اني رايت احد عشر كوكبا والشمس والقمر رايتهم لي ساجدين","dt":"[4] اذكر -ايها الرسول- لقومك قول يوسف لابيه: اني رايت في المنام احد عشر كوكبا، والشمس والقمر رايتهم لي ساجدين. فكانت هذه الرؤيا بشرى لما وصل اليه يوسف عليه السلام من علو المنزله في الدنيا والاخره."},{"id":"1601","s":12,"a":5,"at":"قال يابني لا تقصص رؤياك على اخوتك فيكيدوا لك كيدا ان الشيطان للانسان عدو مبين","dt":"[5] قال يعقوب عليه السلام لابنه يوسف: يا بني لا تذكر لاخوتك هذه الرؤيا فيحسدوك، ويعادوك، ويحتالوا في اهلاكك، ان الشيطان للانسان عدو ظاهر العداوه."},{"id":"1602","s":12,"a":6,"at":"وكذلك يجتبيك ربك ويعلمك من تاويل الاحاديث ويتم نعمته عليك وعلى ال يعقوب كما اتمها على ابويك من قبل ابراهيم واسحاق ان ربك عليم حكيم","dt":"[6] وكما اراك ربك هذه الرؤيا فكذلك يصطفيك ويعلمك تفسير ما يراه الناس في منامهم من الرؤى مما تؤول اليه واقعا، ويتم نعمته عليك وعلى ال يعقوب بالنبوه والرساله، كما اتمها من قبل على ابويك ابراهيم واسحاق بالنبوه والرساله. ان ربك عليم بمن يصطفيه من عباده، حكيم في تدبير امور خلقه."},{"id":"1603","s":12,"a":7,"at":"لقد كان في يوسف واخوته ايات للسائلين","dt":"[7] لقد كان في قصه يوسف واخوته عبر وادله تدل على قدره الله وحكمته لمن يسال عن اخبارهم، ويرغب في معرفتها."},{"id":"1604","s":12,"a":8,"at":"اذ قالوا ليوسف واخوه احب الى ابينا منا ونحن عصبه ان ابانا لفي ضلال مبين","dt":"[8] اذ قال اخوه يوسف من ابيه فيما بينهم: ان يوسف واخاه الشقيق احب الى ابينا منا، يفضلهما علينا، ونحن جماعه ذوو عدد، ان ابانا لفي خطا بين؛ حيث فضلهما علينا من غير موجب نراه."},{"id":"1605","s":12,"a":9,"at":"اقتلوا يوسف او اطرحوه ارضا يخل لكم وجه ابيكم وتكونوا من بعده قوما صالحين","dt":"[9] اقتلوا يوسف او القوا به في ارض مجهوله بعيده عن العمران يخلص لكم حب ابيكم واقباله عليكم، ولا يلتفت عنكم الى غيركم، وتكونوا من بعد قتل يوسف او ابعاده تائبين الى الله، مستغفرين له من بعد ذنبكم."},{"id":"1606","s":12,"a":10,"at":"قال قائل منهم لا تقتلوا يوسف والقوه في غيابت الجب يلتقطه بعض السياره ان كنتم فاعلين","dt":"[10] قال قائل من اخوه يوسف: لا تقتلوا يوسف، والقوه في جوف البئر يلتقطه بعض الماره من المسافرين فتستريحوا منه، ولا حاجه الى قتله، ان كنتم عازمين على فعل ما تقولون."},{"id":"1607","s":12,"a":11,"at":"قالوا ياابانا ما لك لا تامنا على يوسف وانا له لناصحون","dt":"[11] قال اخوه يوسف -بعد اتفاقهم على ابعاده-: يا ابانا ما لك لا تجعلنا امناء على يوسف مع انه اخونا، ونحن نريد له الخير ونشفق عليه ونرعاه، ونخصه بخالص النصح؟"},{"id":"1608","s":12,"a":12,"at":"ارسله معنا غدا يرتع ويلعب وانا له لحافظون","dt":"[12] ارسله معنا غدا عندما نخرج الى مراعينا يسع وينشط ويفرح، ويلعب بالاستباق ونحوه من اللعب المباح، وانا لحافظون له من كل ما تخاف عليه."},{"id":"1609","s":12,"a":13,"at":"قال اني ليحزنني ان تذهبوا به واخاف ان ياكله الذئب وانتم عنه غافلون","dt":"[13] قال يعقوب: اني ليؤلم نفسي مفارقته لي اذا ذهبتم به الى المراعي، واخشى ان ياكله الذئب، وانتم عنه غافلون منشغلون."},{"id":"1610","s":12,"a":14,"at":"قالوا لئن اكله الذئب ونحن عصبه انا اذا لخاسرون","dt":"[14] قال اخوه يوسف لوالدهم: لئن اكله الذئب، ونحن جماعه قويه انا اذا لخاسرون، لا خير فينا، ولا نفع يرجى منا."},{"id":"1611","s":12,"a":15,"at":"فلما ذهبوا به واجمعوا ان يجعلوه في غيابت الجب واوحينا اليه لتنبئنهم بامرهم هذا وهم لا يشعرون","dt":"[15] فارسله معهم. فلما ذهبوا به واجمعوا على القائه في جوف البئر، واوحينا الى يوسف لتخبرن اخوتك مستقبلا بفعلهم هذا الذي فعلوه بك، وهم لا يحسون بذلك الامر ولا يشعرون به."},{"id":"1612","s":12,"a":16,"at":"وجاءوا اباهم عشاء يبكون","dt":"[16] وجاء اخوه يوسف الى ابيهم في وقت العشاء من اول الليل، يبكون ويظهرون الاسف والجزع."},{"id":"1613","s":12,"a":17,"at":"قالوا ياابانا انا ذهبنا نستبق وتركنا يوسف عند متاعنا فاكله الذئب وما انت بمؤمن لنا ولو كنا صادقين","dt":"[17] قالوا: يا ابانا انا ذهبنا نتسابق في الجري والرمي بالسهام، وتركنا يوسف عند زادنا وثيابنا، فلم نقصر في حفظه، بل تركناه في مامننا، وما فارقناه الا وقتا يسيرا، فاكله الذئب، وما انت بمصدق لنا ولو كنا موصوفين بالصدق؛ لشده حبك ليوسف."},{"id":"1614","s":12,"a":18,"at":"وجاءوا على قميصه بدم كذب قال بل سولت لكم انفسكم امرا فصبر جميل والله المستعان على ما تصفون","dt":"[18] وجاؤوا بقميصه ملطخا بدم غير دم يوسف؛ ليشهد على صدقهم، فكان دليلا على كذبهم؛ لان القميص لم يمزق. فقال لهم ابوهم يعقوب عليه السلام: ما الامر كما تقولون، بل زينت لكم انفسكم الاماره بالسوء امرا قبيحا في يوسف، فرايتموه حسنا وفعلتموه، فصبري صبر جميل لا شكوى معه لاحد من الخلق، واستعين بالله على احتمال ما تصفون من الكذب، لا بحولي وقوتي."},{"id":"1615","s":12,"a":19,"at":"وجاءت سياره فارسلوا واردهم فادلى دلوه قال يابشرى هذا غلام واسروه بضاعه والله عليم بما يعملون","dt":"[19] وجاءت جماعه من المسافرين، فارسلوا من يطلب لهم الماء، فلما ارسل دلوه في البئر تعلق بها يوسف، ففرح وارد الماء وابتهج بالعثور على غلام، وقال: يا بشرى هذا غلام نفيس، واخفى الوارد واصحابه يوسف عن بقيه المسافرين فلم يظهروه لهم، وقالوا: ان هذه بضاعه استبضعناها، والله عليم بما يعملونه بيوسف."},{"id":"1616","s":12,"a":20,"at":"وشروه بثمن بخس دراهم معدوده وكانوا فيه من الزاهدين","dt":"[20] وباعه اخوته للواردين من المسافرين بثمن قليل من الدراهم، وكانوا زاهدين فيه راغبين في التخلص منه؛ وذلك انهم لا يعلمون منزلته عند الله."},{"id":"1617","s":12,"a":21,"at":"وقال الذي اشتراه من مصر لامراته اكرمي مثواه عسى ان ينفعنا او نتخذه ولدا وكذلك مكنا ليوسف في الارض ولنعلمه من تاويل الاحاديث والله غالب على امره ولكن اكثر الناس لا يعلمون","dt":"[21] ولما ذهب المسافرون بيوسف الى «مصر» اشتراه منهم عزيزها، وهو الوزير، وقال لامراته: احسني معاملته، واجعلي مقامه عندنا كريما، لعلنا نستفيد من خدمته، او نقيمه عندنا مقام الولد، وكما انجينا يوسف وجعلنا عزيز «مصر» يعطف عليه، فكذلك مكنا له في ارض «مصر»، وجعلناه على خزائنها، ولنعلمه تفسير الرؤى فيعرف منها ما سيقع مستقبلا. والله غالب على امره، فحكمه نافذ لا يبطله مبطل، ولكن اكثر الناس لا يعلمون ان الامر كله بيد الله."},{"id":"1618","s":12,"a":22,"at":"ولما بلغ اشده اتيناه حكما وعلما وكذلك نجزي المحسنين","dt":"[22] ولما بلغ يوسف منتهى قوته في شبابه اعطيناه فهما وعلما، ومثل هذا الجزاء الذي جزينا به يوسف على احسانه نجزي المحسنين على احسانهم. وفي هذا تسليه للرسول -صلى الله عليه وسلم-."},{"id":"1619","s":12,"a":23,"at":"وراودته التي هو في بيتها عن نفسه وغلقت الابواب وقالت هيت لك قال معاذ الله انه ربي احسن مثواي انه لا يفلح الظالمون","dt":"[23] ودعت امراه العزيز -برفق ولين- يوسف الذي هو في بيتها الى نفسها؛ لحبها الشديد له وحسن بهائه، وغلقت الابواب عليها وعلى يوسف، وقالت: هلم الي، فقال: معاذ الله اعتصم به، واستجير من الذي تدعينني اليه، من خيانه سيدي الذي احسن منزلتي واكرمني فلا اخونه في اهله، انه لا يفلح من ظلم ففعل ما ليس له فعله."},{"id":"1620","s":12,"a":24,"at":"ولقد همت به وهم بها لولا ان راى برهان ربه كذلك لنصرف عنه السوء والفحشاء انه من عبادنا المخلصين","dt":"[24] ولقد مالت نفسها لفعل الفاحشه، وحدثت يوسف نفسه حديث خطرات للاستجابه، لولا ان راى ايه من ايات ربه تزجره عما حدثته به نفسه، وانما اريناه ذلك؛ لندفع عنه السوء والفاحشه في جميع اموره، انه من عبادنا المطهرين المصطفين للرساله الذين اخلصوا في عبادتهم لله وتوحيده."},{"id":"1621","s":12,"a":25,"at":"واستبقا الباب وقدت قميصه من دبر والفيا سيدها لدى الباب قالت ما جزاء من اراد باهلك سوءا الا ان يسجن او عذاب اليم","dt":"[25] واسرع يوسف الى الباب يريد الخروج، واسرعت تحاول الامساك به، وجذبت قميصه من خلفه؛ لتحول بينه وبين الخروج فشقته، ووجدا زوجها عند الباب فقالت: ما جزاء من اراد بامراتك فاحشه الا ان يسجن او يعذب العذاب الموجع."},{"id":"1622","s":12,"a":26,"at":"قال هي راودتني عن نفسي وشهد شاهد من اهلها ان كان قميصه قد من قبل فصدقت وهو من الكاذبين","dt":"[26] قال يوسف: هي التي طلبت مني ذلك، وشهد صبي في المهد من اهلها فقال: ان كان قميصه شق من الامام فصدقت في اتهامها له، وهو من الكاذبين."},{"id":"1623","s":12,"a":27,"at":"وان كان قميصه قد من دبر فكذبت وهو من الصادقين","dt":"[27] وان كان قميصه شق من الخلف فكذبت في قولها، وهو من الصادقين."},{"id":"1624","s":12,"a":28,"at":"فلما راى قميصه قد من دبر قال انه من كيدكن ان كيدكن عظيم","dt":"[28] فلما راى الزوج قميص يوسف شق من خلفه علم براءه يوسف، وقال لزوجته: ان هذا الكذب الذي اتهمت به هذا الشاب هو من جمله مكركن -ايتها النساء-، ان مكركن عظيم."},{"id":"1625","s":12,"a":29,"at":"يوسف اعرض عن هذا واستغفري لذنبك انك كنت من الخاطئين","dt":"[29] قال عزيز «مصر»: يا يوسف اترك ذكر ما كان منها فلا تذكره لاحد، واطلبي -ايتها المراه- المغفره لذنبك؛ انك كنت من الاثمين في مراوده يوسف عن نفسه، وفي افترائك عليه."},{"id":"1626","s":12,"a":30,"at":"وقال نسوه في المدينه امراه العزيز تراود فتاها عن نفسه قد شغفها حبا انا لنراها في ضلال مبين","dt":"[30] ووصل الخبر الى نسوه في المدينه فتحدثن به، وقلن منكرات على امراه العزيز: امراه العزيز تحاول غلامها عن نفسه، وتدعوه الى نفسها، وقد بلغ حبها له شغاف قلبها -وهو غلافه-، انا لنراها في هذا الفعل لفي ضلال واضح."},{"id":"1627","s":12,"a":31,"at":"فلما سمعت بمكرهن ارسلت اليهن واعتدت لهن متكا واتت كل واحده منهن سكينا وقالت اخرج عليهن فلما راينه اكبرنه وقطعن ايديهن وقلن حاش لله ما هذا بشرا ان هذا الا ملك كريم","dt":"[31] فلما سمعت امراه العزيز بغيبتهن اياها واحتيالهن في ذمها، ارسلت اليهن تدعوهن لزيارتها، وهيات لهن ما يتكئن عليه من الوسائد، وما ياكلنه من الطعام، واعطت كل واحده منهن سكينا ليقطعن الطعام، ثم قالت ليوسف: اخرج عليهن، فلما راينه اعظمنه واجللنه، واخذهن حسنه وجماله، فجرحن ايديهن وهن يقطعن الطعام من فرط الدهشه والذهول، وقلن متعجبات: معاذ الله، ما هذا من جنس البشر؛ لان جماله غير معهود في البشر، ما هو الا ملك كريم من الملائكه."},{"id":"1628","s":12,"a":32,"at":"قالت فذلكن الذي لمتنني فيه ولقد راودته عن نفسه فاستعصم ولئن لم يفعل ما امره ليسجنن وليكونا من الصاغرين","dt":"[32] قالت امراه العزيز للنسوه اللاتي قطعن ايديهن: فهذا الذي اصابكن في رؤيتكن اياه ما اصابكن هو الفتى الذي لمتنني في الافتتان به، ولقد طلبته وحاولت اغراءه؛ ليستجيب لي فامتنع وابى، ولئن لم يفعل ما امره به مستقبلا ليعاقبن بدخول السجن، وليكونن من الاذلاء."},{"id":"1629","s":12,"a":33,"at":"قال رب السجن احب الي مما يدعونني اليه والا تصرف عني كيدهن اصب اليهن واكن من الجاهلين","dt":"[33] قال يوسف مستعيذا من شرهن ومكرهن: يا رب السجن احب الي مما يدعونني اليه من عمل الفاحشه، وان لم تدفع عني مكرهن امل اليهن، واكن من السفهاء الذين يرتكبون الاثم لجهلهم بعواقبه."},{"id":"1630","s":12,"a":34,"at":"فاستجاب له ربه فصرف عنه كيدهن انه هو السميع العليم","dt":"[34] فاستجاب الله ليوسف دعاءه، فصرف عنه ما ارادت منه امراه العزيز وصواحباتها من معصيه الله. ان الله هو السميع لدعاء يوسف، ودعاء كل داع من خلقه، العليم بمطلبه وحاجته وما يصلحه، وبحاجه جميع خلقه وما يصلحهم."},{"id":"1631","s":12,"a":35,"at":"ثم بدا لهم من بعد ما راوا الايات ليسجننه حتى حين","dt":"[35] ثم ظهر للعزيز واصحابه -من بعد ما راوا الادله على براءه يوسف وعفته- ان يسجنوه الى زمن يطول او يقصر؛ منعا للفضيحه."},{"id":"1632","s":12,"a":36,"at":"ودخل معه السجن فتيان قال احدهما اني اراني اعصر خمرا وقال الاخر اني اراني احمل فوق راسي خبزا تاكل الطير منه نبئنا بتاويله انا نراك من المحسنين","dt":"[36] ودخل السجن مع يوسف فتيان، قال احدهما: اني رايت في المنام اني اعصر عنبا ليصير خمرا، وقال الاخر: اني رايت اني احمل فوق راسي خبزا تاكل الطير منه، اخبرنا -يا يوسف- بتفسير ما راينا، انا نراك من الذين يحسنون في عبادتهم لله، ومعاملتهم لخلقه."},{"id":"1633","s":12,"a":37,"at":"قال لا ياتيكما طعام ترزقانه الا نباتكما بتاويله قبل ان ياتيكما ذلكما مما علمني ربي اني تركت مله قوم لا يؤمنون بالله وهم بالاخره هم كافرون","dt":"[37] قال لهما يوسف: لا ياتيكما طعام ترزقانه في حال من الاحوال الا اخبرتكما بتفسير هذا الطعام قبل ان ياتيكما، ذلكما التعبير الذي ساعبره لكما مما علمني ربي؛ اني امنت به، واخلصت له العباده، وابتعدت عن دين قوم لا يؤمنون بالله، وهم بالبعث والحساب جاحدون."},{"id":"1634","s":12,"a":38,"at":"واتبعت مله ابائي ابراهيم واسحاق ويعقوب ما كان لنا ان نشرك بالله من شيء ذلك من فضل الله علينا وعلى الناس ولكن اكثر الناس لا يشكرون","dt":"[38] واتبعت دين ابائي ابراهيم واسحاق ويعقوب فعبدت الله وحده، ما كان لنا ان نجعل لله شريكا في عبادته، ذلك التوحيد بافراد الله بالعباده، مما تفضل الله به علينا وعلى الناس، ولكن اكثر الناس لا يشكرون الله على نعمه التوحيد والايمان."},{"id":"1635","s":12,"a":39,"at":"ياصاحبي السجن اارباب متفرقون خير ام الله الواحد القهار","dt":"[39] وقال يوسف للفتيين اللذين معه في السجن: اعباده الهه مخلوقه شتى خير ام عباده الله الواحد القهار؟"},{"id":"1636","s":12,"a":40,"at":"ما تعبدون من دونه الا اسماء سميتموها انتم واباؤكم ما انزل الله بها من سلطان ان الحكم الا لله امر الا تعبدوا الا اياه ذلك الدين القيم ولكن اكثر الناس لا يعلمون","dt":"[40] ما تعبدون من دون الله الا اسماء لا معاني وراءها، جعلتموها انتم واباؤكم اربابا جهلا منكم وضلالا، ما انزل الله من حجه او برهان على صحتها، ما الحكم الحق الا لله تعالى وحده، لا شريك له، امر الا تنقادوا ولا تخضعوا لغيره، وان تعبدوه وحده، وهذا هو الدين القيم الذي لا عوج فيه، ولكن اكثر الناس يجهلون ذلك، فلا يعلمون حقيقته."},{"id":"1637","s":12,"a":41,"at":"ياصاحبي السجن اما احدكما فيسقي ربه خمرا واما الاخر فيصلب فتاكل الطير من راسه قضي الامر الذي فيه تستفتيان","dt":"[41] يا صاحبي في السجن، اليكما تفسير رؤياكما: اما الذي راى انه يعصر العنب في رؤياه فانه يخرج من السجن ويكون ساقي الخمر للملك، واما الاخر الذي راى انه يحمل على راسه خبزا فانه يصلب ويترك، وتاكل الطير من راسه، قضي الامر الذي فيه تستفتيان وفرغ منه."},{"id":"1638","s":12,"a":42,"at":"وقال للذي ظن انه ناج منهما اذكرني عند ربك فانساه الشيطان ذكر ربه فلبث في السجن بضع سنين","dt":"[42] وقال يوسف للذي علم انه ناج من صاحبيه: اذكرني عند سيدك الملك، واخبره باني مظلوم محبوس بلا ذنب، فانسى الشيطان ذلك الرجل ان يذكر للملك حال يوسف، فمكث يوسف بعد ذلك في السجن عده سنوات."},{"id":"1639","s":12,"a":43,"at":"وقال الملك اني ارى سبع بقرات سمان ياكلهن سبع عجاف وسبع سنبلات خضر واخر يابسات ياايها الملا افتوني في رؤياي ان كنتم للرؤيا تعبرون","dt":"[43] وقال الملك: اني رايت في منامي سبع بقرات سمان، ياكلهن سبع بقرات نحيلات من الهزال، ورايت سبع سنبلات خضر، وسبع سنبلات يابسات، يا ايها الساده والكبراء اخبروني عن هذه الرؤيا، ان كنتم للرؤيا تفسرون."},{"id":"1640","s":12,"a":44,"at":"قالوا اضغاث احلام وما نحن بتاويل الاحلام بعالمين","dt":"[44] قالوا: رؤياك هذه اخلاط احلام لا تاويل لها، وما نحن بتفسير الاحلام بعالمين."},{"id":"1641","s":12,"a":45,"at":"وقال الذي نجا منهما وادكر بعد امه انا انبئكم بتاويله فارسلون","dt":"[45] وقال الذي نجا من القتل من صاحبي يوسف في السجن، وتذكر بعد مده ما نسي من امر يوسف: انا اخبركم بتاويل هذه الرؤيا، فابعثوني الى يوسف لاتيكم بتفسيرها."},{"id":"1642","s":12,"a":46,"at":"يوسف ايها الصديق افتنا في سبع بقرات سمان ياكلهن سبع عجاف وسبع سنبلات خضر واخر يابسات لعلي ارجع الى الناس لعلهم يعلمون","dt":"[46] وعندما وصل الرجل الى يوسف قال له: يوسف ايها الصديق فسر لنا رؤيا من راى سبع بقرات سمان ياكلهن سبع بقرات هزيلات، وراى سبع سنبلات خضر واخر يابسات؛ لعلي ارجع الى الملك واصحابه فاخبرهم؛ ليعلموا تاويل ما سالتك عنه، وليعلموا مكانتك وفضلك."},{"id":"1643","s":12,"a":47,"at":"قال تزرعون سبع سنين دابا فما حصدتم فذروه في سنبله الا قليلا مما تاكلون","dt":"[47] قال يوسف لسائله عن رؤيا الملك: تفسير هذه الرؤيا انكم تزرعون سبع سنين متتابعه جادين ليكثر العطاء، فما حصدتم منه في كل مره فادخروه، واتركوه في سنبله؛ ليتم حفظه من التسوس، وليكون ابقى، الا قليلا مما تاكلونه من الحبوب."},{"id":"1644","s":12,"a":48,"at":"ثم ياتي من بعد ذلك سبع شداد ياكلن ما قدمتم لهن الا قليلا مما تحصنون","dt":"[48] ثم ياتي بعد هذه السنين الخصبه سبع سنين شديده الجدب، ياكل اهلها كل ما ادخرتم لهن من قبل، الا قليلا مما تحفظونه وتدخرونه ليكون بذورا للزراعه."},{"id":"1645","s":12,"a":49,"at":"ثم ياتي من بعد ذلك عام فيه يغاث الناس وفيه يعصرون","dt":"[49] ثم ياتي من بعد هذه السنين المجدبه عام يغاث فيه الناس بالمطر، فيرفع الله تعالى عنهم الشده، ويعصرون فيه الثمار من كثره الخصب والنماء."},{"id":"1646","s":12,"a":50,"at":"وقال الملك ائتوني به فلما جاءه الرسول قال ارجع الى ربك فاساله ما بال النسوه اللاتي قطعن ايديهن ان ربي بكيدهن عليم","dt":"[50] وقال الملك لاعوانه: اخرجوا الرجل المعبر للرؤيا من السجن واحضروه لي، فلما جاءه رسول الملك يدعوه قال يوسف للرسول: ارجع الى سيدك الملك، واطلب منه ان يسال النسوه اللاتي جرحن ايديهن عن حقيقه امرهن وشانهن معي؛ لتظهر الحقيقه للجميع، وتتضح براءتي، ان ربي عليم بصنيعهن وافعالهن لا يخفى عليه شيء من ذلك."},{"id":"1647","s":12,"a":51,"at":"قال ما خطبكن اذ راودتن يوسف عن نفسه قلن حاش لله ما علمنا عليه من سوء قالت امراه العزيز الان حصحص الحق انا راودته عن نفسه وانه لمن الصادقين","dt":"[51] قال الملك للنسوه اللاتي جرحن ايديهن: ما شانكن حين راودتن يوسف عن نفسه يوم الضيافه؟ فهل رايتن منه ما يريب؟ قلن: معاذ الله ما علمنا عليه ادنى شيء يشينه، عند ذلك قالت امراه العزيز: الان ظهر الحق بعد خفائه، فانا التي حاولت فتنته باغرائه فامتنع، وانه لمن الصادقين في كل ما قاله."},{"id":"1648","s":12,"a":52,"at":"ذلك ليعلم اني لم اخنه بالغيب وان الله لا يهدي كيد الخائنين","dt":"[52] ذلك القول الذي قلته في تنزيه يوسف والاقرار على نفسي ليعلم اني لم اخنه بالكذب عليه، ولم تقع مني الفاحشه مع انني راودته واعترفت بذلك لاظهار براءتي وبراءته، وان الله لا يوفق اهل الخيانه، ولا يرشدهم في خيانتهم."},{"id":"1649","s":12,"a":53,"at":"وما ابرئ نفسي ان النفس لاماره بالسوء الا ما رحم ربي ان ربي غفور رحيم","dt":"[53] قالت امراه العزيز: وما ازكي نفسي ولا ابرئها، ان النفس لكثيره الامر لصاحبها بعمل المعاصي طلبا لملذاتها، الا من عصمه الله. ان الله غفور لذنوب من تاب من عباده، رحيم بهم."},{"id":"1650","s":12,"a":54,"at":"وقال الملك ائتوني به استخلصه لنفسي فلما كلمه قال انك اليوم لدينا مكين امين","dt":"[54] وقال الملك الحاكم ل«مصر» حين بلغته براءه يوسف: جيئوني به اجعله من خلصائي واهل مشورتي، فلما جاء يوسف وكلمه الملك، وعرف براءته، وعظيم امانته، وحسن خلقه، قال له: انك اليوم عندنا عظيم المكانه، ومؤتمن على كل شيء."},{"id":"1651","s":12,"a":55,"at":"قال اجعلني على خزائن الارض اني حفيظ عليم","dt":"[55] واراد يوسف ان ينفع العباد، ويقيم العدل بينهم، فقال للملك: اجعلني واليا على خزائن «مصر»، فاني خازن امين، ذو علم وبصيره بما اتولاه."},{"id":"1652","s":12,"a":56,"at":"وكذلك مكنا ليوسف في الارض يتبوا منها حيث يشاء نصيب برحمتنا من نشاء ولا نضيع اجر المحسنين","dt":"[56] وكما انعم الله على يوسف بالخلاص من السجن مكن له في ارض «مصر» ينزل منها اي منزل شاءه. يصيب الله برحمته من يشاء من عباده المتقين، ولا يضيع اجر من احسن شيئا من العمل الصالح."},{"id":"1653","s":12,"a":57,"at":"ولاجر الاخره خير للذين امنوا وكانوا يتقون","dt":"[57] ولثواب الاخره عند الله اعظم من ثواب الدنيا لاهل الايمان والتقوى الذين يخافون عقاب الله، ويطيعونه في امره ونهيه."},{"id":"1654","s":12,"a":58,"at":"وجاء اخوه يوسف فدخلوا عليه فعرفهم وهم له منكرون","dt":"[58] وقدم اخوه يوسف الى «مصر» -بعد ان حل بهم الجدب في ارضهم-؛ ليجلبوا منها الطعام، فدخلوا عليه فعرفهم لقوه فراسته وذكائه، ولم يعرفوه لطول المده وتغير هيئته."},{"id":"1655","s":12,"a":59,"at":"ولما جهزهم بجهازهم قال ائتوني باخ لكم من ابيكم الا ترون اني اوفي الكيل وانا خير المنزلين","dt":"[59] وقد امر يوسف باكرامهم وحسن ضيافتهم، ثم اعطاهم من الطعام ما طلبوا، وكانوا قد اخبروه ان لهم اخا من ابيهم لم يحضروه معهم -يريدون شقيقه «بنيامين»- فقال: ائتوني باخيكم من ابيكم، الم تروا اني اوفيت لكم الكيل واكرمتكم في الضيافه، وانا خير المضيفين لكم؟"},{"id":"1656","s":12,"a":60,"at":"فان لم تاتوني به فلا كيل لكم عندي ولا تقربون","dt":"[60] فان لم تاتوني به فليس لكم عندي طعام اكيله لكم، ولا تاتوا الي ."},{"id":"1657","s":12,"a":61,"at":"قالوا سنراود عنه اباه وانا لفاعلون","dt":"[61] قالوا: سنبذل جهدنا لاقناع ابيه ان يرسله معنا، ولن نقصر في ذلك."},{"id":"1658","s":12,"a":62,"at":"وقال لفتيانه اجعلوا بضاعتهم في رحالهم لعلهم يعرفونها اذا انقلبوا الى اهلهم لعلهم يرجعون","dt":"[62] وقال يوسف لغلمانه: اجعلوا ثمن ما اخذوه في امتعتهم سرا؛ رجاء ان يعرفوه اذا رجعوا الى اهلهم، ويقدروا اكرامنا لهم؛ ليرجعوا طمعا في عطائنا."},{"id":"1659","s":12,"a":63,"at":"فلما رجعوا الى ابيهم قالوا ياابانا منع منا الكيل فارسل معنا اخانا نكتل وانا له لحافظون","dt":"[63] فلما رجعوا الى ابيهم قصوا عليه ما كان من اكرام العزيز لهم، وقالوا: انه لن يعطينا -مستقبلا- الا اذا كان معنا اخونا الذي اخبرناه به، فارسله معنا نحضر الطعام وافيا، ونتعهد لك بحفظه."},{"id":"1660","s":12,"a":64,"at":"قال هل امنكم عليه الا كما امنتكم على اخيه من قبل فالله خير حافظا وهو ارحم الراحمين","dt":"[64] قال لهم ابوهم: كيف امنكم على «بنيامين» وقد امنتكم على اخيه يوسف من قبل، والتزمتم بحفظه فلم تفوا بذلك؟ فلا اثق بالتزامكم وحفظكم، ولكني اثق بحفظ الله، خير الحافظين وارحم الراحمين، ارجو ان يرحمني فيحفظه ويرده علي."},{"id":"1661","s":12,"a":65,"at":"ولما فتحوا متاعهم وجدوا بضاعتهم ردت اليهم قالوا ياابانا ما نبغي هذه بضاعتنا ردت الينا ونمير اهلنا ونحفظ اخانا ونزداد كيل بعير ذلك كيل يسير","dt":"[65] ولما فتحوا اوعيتهم وجدوا ثمن بضاعتهم الذي دفعوه قد رد اليهم، قالوا: يا ابانا ماذا نطلب اكثر من هذا؟ هذا ثمن بضاعتنا رده العزيز الينا، فكن مطمئنا على اخينا، وارسله معنا؛ لنجلب طعاما وفيرا لاهلنا، ونحفظ اخانا، ونزداد حمل بعير له؛ فان العزيز يكيل لكل واحد حمل بعير، وذلك كيل يسير عليه."},{"id":"1662","s":12,"a":66,"at":"قال لن ارسله معكم حتى تؤتون موثقا من الله لتاتنني به الا ان يحاط بكم فلما اتوه موثقهم قال الله على ما نقول وكيل","dt":"[66] قال لهم يعقوب عليه السلام: لن اتركه يذهب معكم حتى تتعهدوا وتحلفوا لي بالله ان تردوه الي، الا ان تغلبوا عليه فلا تستطيعوا تخليصه، فلما اعطوه عهد الله على ما طلب، قال يعقوب: الله على ما نقول وكيل، اي تكفينا شهادته علينا وحفظه لنا."},{"id":"1663","s":12,"a":67,"at":"وقال يابني لا تدخلوا من باب واحد وادخلوا من ابواب متفرقه وما اغني عنكم من الله من شيء ان الحكم الا لله عليه توكلت وعليه فليتوكل المتوكلون","dt":"[67] وقال لهم ابوهم: يا ابنائي اذا دخلتم ارض «مصر» فلا تدخلوا من باب واحد، ولكن ادخلوها من ابواب متفرقه، حتى لا تصيبكم العين، واني اذ اوصيكم بهذا لا ادفع عنكم شيئا قضاه الله عليكم، فما الحكم الا لله وحده، عليه اعتمدت ووثقت، وعليه وحده يعتمد المؤمنون."},{"id":"1664","s":12,"a":68,"at":"ولما دخلوا من حيث امرهم ابوهم ما كان يغني عنهم من الله من شيء الا حاجه في نفس يعقوب قضاها وانه لذو علم لما علمناه ولكن اكثر الناس لا يعلمون","dt":"[68] ولما دخلوا من ابواب متفرقه كما امرهم ابوهم، ما كان ذلك ليدفع قضاء الله عنهم، ولكن كان شفقه في نفس يعقوب عليهم ان تصيبهم العين، وان يعقوب لصاحب علم عظيم بامر دينه علمه الله له وحيا، ولكن اكثر الناس لا يعلمون عواقب الامور ودقائق الاشياء، ولا ما يعلمه يعقوب -عليه السلام- من امر دينه."},{"id":"1665","s":12,"a":69,"at":"ولما دخلوا على يوسف اوى اليه اخاه قال اني انا اخوك فلا تبتئس بما كانوا يعملون","dt":"[69] ولما دخل اخوه يوسف عليه في منزل ضيافته ومعهم شقيقه «بنيامين»، ضم يوسف اليه شقيقه، وقال له سرا: اني انا اخوك فلا تحزن، ولا تغتم بما صنعوه بي فيما مضى. وامره بكتمان ذلك عنهم."},{"id":"1666","s":12,"a":70,"at":"فلما جهزهم بجهازهم جعل السقايه في رحل اخيه ثم اذن مؤذن ايتها العير انكم لسارقون","dt":"[70] فلما جهزهم يوسف، وحمل ابلهم بالطعام، امر عماله، فوضعوا الاناء الذي كان يكيل للناس به في متاع اخيه «بنيامين» من حيث لا يشعر احد، ولما ركبوا ليسيروا نادى مناد قائلا: يا اصحاب هذه القافله المحمله بالطعام، انكم لسارقون."},{"id":"1667","s":12,"a":71,"at":"قالوا واقبلوا عليهم ماذا تفقدون","dt":"[71] قال اولاد يعقوب مقبلين على المنادي: ما الذي تفقدونه؟"},{"id":"1668","s":12,"a":72,"at":"قالوا نفقد صواع الملك ولمن جاء به حمل بعير وانا به زعيم","dt":"[72] قال المنادي ومن بحضرته: نفقد المكيال الذي يكيل الملك به، ومكافاه من يحضره مقدار حمل بعير من الطعام، وقال المنادي: وانا بحمل البعير من الطعام ضامن وكفيل."},{"id":"1669","s":12,"a":73,"at":"قالوا تالله لقد علمتم ما جئنا لنفسد في الارض وما كنا سارقين","dt":"[73] قال اخوه يوسف: والله لقد تحققتم مما شاهدتموه منا اننا ما جئنا ارض «مصر» من اجل الافساد فيها، وليس من صفاتنا ان نكون سارقين."},{"id":"1670","s":12,"a":74,"at":"قالوا فما جزاؤه ان كنتم كاذبين","dt":"[74] قال المكلفون بالبحث عن المكيال لاخوه يوسف: فما عقوبه السارق عندكم ان كنتم كاذبين في قولكم: لسنا بسارقين؟"},{"id":"1671","s":12,"a":75,"at":"قالوا جزاؤه من وجد في رحله فهو جزاؤه كذلك نجزي الظالمين","dt":"[75] قال اخوه يوسف: جزاء السارق من وجد المسروق في رحله فهو جزاؤه، اي: يسلم بسرقته الى من سرق منه حتى يكون عبدا عنده، مثل هذا الجزاء -وهو الاسترقاق- نجزي الظالمين بالسرقه، وهذا ديننا وسنتنا في اهل السرقه."},{"id":"1672","s":12,"a":76,"at":"فبدا باوعيتهم قبل وعاء اخيه ثم استخرجها من وعاء اخيه كذلك كدنا ليوسف ما كان لياخذ اخاه في دين الملك الا ان يشاء الله نرفع درجات من نشاء وفوق كل ذي علم عليم","dt":"[76] ورجعوا باخوه يوسف اليه، فقام بنفسه يفتش امتعتهم، فبدا بامتعتهم قبل متاع شقيقه؛ احكاما لما دبره لاستبقاء اخيه معه، ثم انتهى بوعاء اخيه، فاستخرج الاناء منه، كذلك يسرنا ليوسف هذا التدبير الذي توصل به لاخذ اخيه، وما كان له ان ياخذ اخاه في حكم ملك «مصر»؛ لانه ليس من دينه ان يتملك السارق، الا ان مشيئه الله اقتضت هذا التدبير والاحتكام الى شريعه اخوه يوسف القاضيه برق السارق. نرفع منازل من نشاء في الدنيا على غيره كما رفعنا منزله يوسف. وفوق كل ذي علم من هو اعلم منه، حتى ينتهي العلم الى الله تعالى عالم الغيب والشهاده."},{"id":"1673","s":12,"a":77,"at":"قالوا ان يسرق فقد سرق اخ له من قبل فاسرها يوسف في نفسه ولم يبدها لهم قال انتم شر مكانا والله اعلم بما تصفون","dt":"[77] قال اخوه يوسف: ان يسرق هذا فقد سرق اخ شقيق له من قبل (يقصدون يوسف عليه السلام) فاخفى يوسف في نفسه ما سمعه من بهتانهم، وحدث نفسه قائلا: انتم اسوا منزله ممن ذكرتم، حيث دبرتم لي ما كان منكم، والله اعلم بما تصفون من الكذب والافتراء."},{"id":"1674","s":12,"a":78,"at":"قالوا ياايها العزيز ان له ابا شيخا كبيرا فخذ احدنا مكانه انا نراك من المحسنين","dt":"[78] قالوا مستعطفين ليوفوا بعهد ابيهم: يا ايها العزيز ان له والدا كبيرا في السن يحبه ولا يطيق بعده، فخذ احدنا بدلا من «بنيامين»، انا نراك من المحسنين في معاملتك لنا ولغيرنا."},{"id":"1675","s":12,"a":79,"at":"قال معاذ الله ان ناخذ الا من وجدنا متاعنا عنده انا اذا لظالمون","dt":"[79] قال يوسف: نعتصم بالله ونستجير به ان ناخذ احدا غير الذي وجدنا المكيال عنده -كما حكمتم انتم-، فاننا ان فعلنا ما تطلبون نكون في عداد الظالمين."},{"id":"1676","s":12,"a":80,"at":"فلما استياسوا منه خلصوا نجيا قال كبيرهم الم تعلموا ان اباكم قد اخذ عليكم موثقا من الله ومن قبل ما فرطتم في يوسف فلن ابرح الارض حتى ياذن لي ابي او يحكم الله لي وهو خير الحاكمين","dt":"[80] فلما يئسوا من اجابته اياهم لما طلبوه انفردوا عن الناس، واخذوا يتشاورون فيما بينهم، قال كبيرهم في السن: الم تعلموا ان اباكم قد اخذ عليكم العهد المؤكد لتردن اخاكم الا ان تغلبوا، ومن قبل هذا كان تقصيركم في يوسف وغدركم به؛ لذلك لن افارق ارض «مصر» حتى ياذن لي ابي في مفارقتها، او يقضي لي ربي بالخروج منها، واتمكن من اخذ اخي، والله خير من حكم، واعدل من فصل بين الناس."},{"id":"1677","s":12,"a":81,"at":"ارجعوا الى ابيكم فقولوا ياابانا ان ابنك سرق وما شهدنا الا بما علمنا وما كنا للغيب حافظين","dt":"[81] ارجعوا انتم الى ابيكم، واخبروه بما جرى، وقولوا له: ان ابنك «بنيامين» قد سرق، وما شهدنا بذلك الا بعد ان تيقنا، فقد راينا المكيال في رحله، وما كان عندنا علم الغيب انه سيسرق حين عاهدناك على رده."},{"id":"1678","s":12,"a":82,"at":"واسال القريه التي كنا فيها والعير التي اقبلنا فيها وانا لصادقون","dt":"[82] ولما رجعوا اخبروا اباهم بما حدث، وطلبوا اليه ان يتوثق مما اخبروه قائلين: واسال -يا ابانا- اهل «مصر»، ومن كان معنا في القافله التي عدنا فيها، و انا لصادقون فيما اخبرناك به."},{"id":"1679","s":12,"a":83,"at":"قال بل سولت لكم انفسكم امرا فصبر جميل عسى الله ان ياتيني بهم جميعا انه هو العليم الحكيم","dt":"[83] قال لهم: بل زينت لكم انفسكم الاماره بالسوء مكيده دبرتموها كما فعلتم من قبل مع يوسف، فصبري صبر جميل لا جزع فيه ولا شكوى معه، عسى الله ان يرد الي ابنائي الثلاثه -وهم يوسف وشقيقه واخوهم الكبير المتخلف من اجل اخيه- انه هو العليم بحالي، الحكيم في تدبيره."},{"id":"1680","s":12,"a":84,"at":"وتولى عنهم وقال يااسفى على يوسف وابيضت عيناه من الحزن فهو كظيم","dt":"[84] واعرض يعقوب عنهم، وقد ضاق صدره بما قالوه، وقال: يا حسرتا على يوسف وابيضت عيناه، بذهاب سوادهما من شده الحزن فهو ممتلئ القلب حزنا، ولكنه شديد الكتمان له."},{"id":"1681","s":12,"a":85,"at":"قالوا تالله تفتا تذكر يوسف حتى تكون حرضا او تكون من الهالكين","dt":"[85] قال بنوه: تالله ما تزال تتذكر يوسف، ويشتد حزنك عليه حتى تشرف على الهلاك او تهلك فعلا، فخفف عن نفسك."},{"id":"1682","s":12,"a":86,"at":"قال انما اشكو بثي وحزني الى الله واعلم من الله ما لا تعلمون","dt":"[86] قال يعقوب مجيبا لهم: لا اظهر همي وحزني الا لله وحده، فهو كاشف الضر والبلاء، واعلم من رحمه الله وفرجه ما لا تعلمونه."},{"id":"1683","s":12,"a":87,"at":"يابني اذهبوا فتحسسوا من يوسف واخيه ولا تياسوا من روح الله انه لا يياس من روح الله الا القوم الكافرون","dt":"[87] قال يعقوب: يا ابنائي عودوا الى «مصر» فاستقصوا اخبار يوسف واخيه، ولا تقطعوا رجاءكم من رحمه الله؛ انه لا يقطع الرجاء من رحمه الله الا الجاحدون لقدرته، الكافرون به."},{"id":"1684","s":12,"a":88,"at":"فلما دخلوا عليه قالوا ياايها العزيز مسنا واهلنا الضر وجئنا ببضاعه مزجاه فاوف لنا الكيل وتصدق علينا ان الله يجزي المتصدقين","dt":"[88] فذهبوا الى «مصر» للمره الثالثه، فلما دخلوا على يوسف قالوا: يا ايها العزيز اصابنا واهلنا القحط والجدب، وجئناك بثمن رديء قليل، فاعطنا به ما كنت تعطينا من قبل بالثمن الجيد، وتصدق علينا بقبض هذه الدراهم الرديئه القليله وتسامح معنا فيها، ان الله تعالى يثيب المتفضلين باموالهم على اهل الحاجه."},{"id":"1685","s":12,"a":89,"at":"قال هل علمتم ما فعلتم بيوسف واخيه اذ انتم جاهلون","dt":"[89] فلما سمع مقالتهم رق لهم، وعرفهم بنفسه وقال: هل تذكرون الذي فعلتموه بيوسف واخيه من الاذى في حال جهلكم بعاقبه ما تفعلون؟"},{"id":"1686","s":12,"a":90,"at":"قالوا ائنك لانت يوسف قال انا يوسف وهذا اخي قد من الله علينا انه من يتق ويصبر فان الله لا يضيع اجر المحسنين","dt":"[90] قالوا: اانك لانت يوسف؟ قال: نعم انا يوسف، وهذا شقيقي، قد تفضل الله علينا، فجمع بيننا بعد الفرقه، انه من يتق الله ويصبر على المحن، فان الله لا يذهب ثواب احسانه، وانما يجزيه احسن الجزاء."},{"id":"1687","s":12,"a":91,"at":"قالوا تالله لقد اثرك الله علينا وان كنا لخاطئين","dt":"[91] قالوا: تالله لقد فضلك الله علينا واعزك بالعلم والحلم والفضل، وان كنا لخاطئين بما فعلناه عمدا بك وباخيك."},{"id":"1688","s":12,"a":92,"at":"قال لا تثريب عليكم اليوم يغفر الله لكم وهو ارحم الراحمين","dt":"[92] قال لهم يوسف: لا تانيب عليكم اليوم، يغفر الله لكم، وهو ارحم الراحمين لمن تاب من ذنبه واناب الى طاعته."},{"id":"1689","s":12,"a":93,"at":"اذهبوا بقميصي هذا فالقوه على وجه ابي يات بصيرا واتوني باهلكم اجمعين","dt":"[93] ولما سالهم عن ابيه اخبروه بذهاب بصره من البكاء عليه، فقال لهم: عودوا الى ابيكم ومعكم قميصي هذا فاطرحوه على وجه ابي يعد اليه بصره، ثم احضروا الي جميع اهلكم."},{"id":"1690","s":12,"a":94,"at":"ولما فصلت العير قال ابوهم اني لاجد ريح يوسف لولا ان تفندون","dt":"[94] ولما خرجت القافله من ارض «مصر» قاصده الشام، ومعهم القميص، قال يعقوب لمن حضره: اني لاشم رائحه يوسف وقميصه، لولا ان تسفهوني وتسخروا مني، وتزعموا ان هذا الكلام صدر مني من غير شعور."},{"id":"1691","s":12,"a":95,"at":"قالوا تالله انك لفي ضلالك القديم","dt":"[95] قال الحاضرون عنده: تالله انك لا تزال في خطئك القديم من حب يوسف، وانك لا تنساه."},{"id":"1692","s":12,"a":96,"at":"فلما ان جاء البشير القاه على وجهه فارتد بصيرا قال الم اقل لكم اني اعلم من الله ما لا تعلمون","dt":"[96] فلما ان جاء من يبشر يعقوب بان يوسف حي، وطرح قميص يوسف على وجهه فعاد يعقوب مبصرا، وعمه السرور فقال لمن عنده: الم اخبركم اني اعلم من الله ما لا تعلمونه من فضل الله ورحمته وكرمه؟"},{"id":"1693","s":12,"a":97,"at":"قالوا ياابانا استغفر لنا ذنوبنا انا كنا خاطئين","dt":"[97] قال بنوه: يا ابانا سل لنا ربك ان يعفو عنا ويستر علينا ذنوبنا، انا كنا خاطئين فيما فعلناه بيوسف وشقيقه."},{"id":"1694","s":12,"a":98,"at":"قال سوف استغفر لكم ربي انه هو الغفور الرحيم","dt":"[98] قال يعقوب: سوف اسال ربي ان يغفر لكم ذنوبكم، انه هو الغفور لذنوب عباده التائبين، الرحيم بهم."},{"id":"1695","s":12,"a":99,"at":"فلما دخلوا على يوسف اوى اليه ابويه وقال ادخلوا مصر ان شاء الله امنين","dt":"[99] وخرج يعقوب واهله الى «مصر» قاصدين يوسف، فلما وصلوا اليه ضم يوسف اليه ابويه، وقال لهم: ادخلوا «مصر» بمشيئه الله، وانتم امنون من الجهد والقحط، ومن كل مكروه."},{"id":"1696","s":12,"a":100,"at":"ورفع ابويه على العرش وخروا له سجدا وقال ياابت هذا تاويل رؤياي من قبل قد جعلها ربي حقا وقد احسن بي اذ اخرجني من السجن وجاء بكم من البدو من بعد ان نزغ الشيطان بيني وبين اخوتي ان ربي لطيف لما يشاء انه هو العليم الحكيم","dt":"[100] واجلس اباه وامه على سرير ملكه بجانبه؛ اكراما لهما، وحياه ابواه واخوته الاحد عشر بالسجود له تحيه وتكريما، لا عباده وخضوعا، وكان ذلك جائزا في شريعتهم، وقد حرم في شريعتنا؛ سدا لذريعه الشرك بالله. وقال يوسف لابيه: هذا السجود هو تفسير رؤياي التي قصصتها عليك من قبل في صغري، قد جعلها ربي صدقا، وقد تفضل علي حين اخرجني من السجن، وجاء بكم الي من الباديه، من بعد ان افسد الشيطان رابطه الاخوه بيني وبين اخوتي. ان ربي لطيف التدبير لما يشاء، انه هو العليم بمصالح عباده، الحكيم في اقواله وافعاله."},{"id":"1697","s":12,"a":101,"at":"رب قد اتيتني من الملك وعلمتني من تاويل الاحاديث فاطر السموات والارض انت وليي في الدنيا والاخره توفني مسلما والحقني بالصالحين","dt":"[101] ثم دعا يوسف ربه قائلا: رب قد اعطيتني من ملك «مصر»، وعلمتني من تفسير الرؤى وغير ذلك من العلم، يا خالق السموات والارض ومبدعهما، انت متولي جميع شاني في الدنيا والاخره، توفني اليك مسلما، والحقني بعبادك الصالحين من الانبياء الابرار والاصفياء الاخيار."},{"id":"1698","s":12,"a":102,"at":"ذلك من انباء الغيب نوحيه اليك وما كنت لديهم اذ اجمعوا امرهم وهم يمكرون","dt":"[102] ذلك المذكور من قصه يوسف هو من اخبار الغيب نخبرك به -ايها الرسول- وحيا، وما كنت حاضرا مع اخوه يوسف حين دبروا له الالقاء في البئر، واحتالوا عليه وعلى ابيه. وهذا يدل على صدقك، وان الله يوحي اليك."},{"id":"1699","s":12,"a":103,"at":"وما اكثر الناس ولو حرصت بمؤمنين","dt":"[103] وما اكثر المشركين من قومك -ايها الرسول- بمصدقيك ولا متبعيك، ولو حرصت على ايمانهم، فلا تحزن على ذلك."},{"id":"1700","s":12,"a":104,"at":"وما تسالهم عليه من اجر ان هو الا ذكر للعالمين","dt":"[104] وما تطلب من قومك اجره على ارشادهم للايمان، ان الذي ارسلت به من القران والهدى عظه للناس اجمعين يتذكرون به ويهتدون."},{"id":"1701","s":12,"a":105,"at":"وكاين من ايه في السموات والارض يمرون عليها وهم عنها معرضون","dt":"[105] وكثير من الدلائل الداله على وحدانيه الله وقدرته منتشره في السموات والارض، كالشمس والقمر والجبال والاشجار، يشاهدونها وهم عنها معرضون، لا يفكرون فيها ولا يعتبرون."},{"id":"1702","s":12,"a":106,"at":"وما يؤمن اكثرهم بالله الا وهم مشركون","dt":"[106] وما يقر هؤلاء المعرضون عن ايات الله بان الله خالقهم ورازقهم وخالق كل شيء، الا وهم مشركون في عبادتهم الاوثان والاصنام. تعالى الله عن ذلك علوا كبيرا."},{"id":"1703","s":12,"a":107,"at":"افامنوا ان تاتيهم غاشيه من عذاب الله او تاتيهم الساعه بغته وهم لا يشعرون","dt":"[107] فهل عندهم ما يجعلهم امنين ان ينزل بهم عذاب من الله في الدنيا يعمهم، او ان تاتيهم القيامه فجاه، وهم لا يشعرون ولا يحسون بذلك."},{"id":"1704","s":12,"a":108,"at":"قل هذه سبيلي ادعو الى الله على بصيره انا ومن اتبعني وسبحان الله وما انا من المشركين","dt":"[108] قل لهم -ايها الرسول-: هذه طريقتي، ادعو الى عباده الله وحده، على حجه من الله ويقين، انا ومن اقتدى بي، وانزه الله سبحانه وتعالى عن الشركاء، ولست من المشركين مع الله غيره."},{"id":"1705","s":12,"a":109,"at":"وما ارسلنا من قبلك الا رجالا نوحي اليهم من اهل القرى افلم يسيروا في الارض فينظروا كيف كان عاقبه الذين من قبلهم ولدار الاخره خير للذين اتقوا افلا تعقلون","dt":"[109] وما ارسلنا من قبلك -ايها الرسول- للناس الا رجالا منهم ننزل عليهم وحينا، وهم من اهل الحاضره، فهم اقدر على فهم الدعوه والرساله، يصدقهم المهتدون للحق، ويكذبهم الضالون عنه، افلم يمشوا في الارض، فيعاينوا كيف كان مال المكذبين السابقين وما حل بهم من الهلاك؟ ولثواب الدار الاخره افضل من الدنيا وما فيها للذين امنوا وخافوا ربهم. افلا تتفكرون فتعتبروا؟"},{"id":"1706","s":12,"a":110,"at":"حتى اذا استياس الرسل وظنوا انهم قد كذبوا جاءهم نصرنا فنجي من نشاء ولا يرد باسنا عن القوم المجرمين","dt":"[110] ولا تستعجل -ايها الرسول- النصر على مكذبيك، فان الرسل قبلك ما كان ياتيهم النصر عاجلا لحكمه نعلمها، حتى اذا يئس الرسل من ايمان قومهم، وظن المرسل اليهم ان الرسل قد كذبوهم فيما اخبروهم عن الله، جاء نصرنا لرسلنا عند شده الكرب، فننجي من نشاء من الرسل واتباعهم، ولا يرد عذابنا عمن اجرم وتجرا على الله. وفي هذا تسليه للنبي -صلى الله عليه وسلم-."},{"id":"1707","s":12,"a":111,"at":"لقد كان في قصصهم عبره لاولي الالباب ما كان حديثا يفترى ولكن تصديق الذي بين يديه وتفصيل كل شيء وهدى ورحمه لقوم يؤمنون","dt":"[111] لقد كان في نبا المرسلين الذي قصصناه عليك وما حل بالمكذبين عظه لاهل العقول السليمه. ما كان هذا القران حديثا مكذوبا مختلقا، ولكن انزلناه شاهدا على صدق ما تقدمه من الكتب المنزله وانها من عند الله، وبيانا لكل ما يحتاج اليه العباد من تحليل وتحريم، ومحبوب ومكروه وغير ذلك، وارشادا من الضلال، ورحمه لاهل الايمان تهتدي به قلوبهم، فيعملون بما فيه من الاوامر والنواهي."},{"id":"1708","s":13,"a":1,"at":"المر تلك ايات الكتاب والذي انزل اليك من ربك الحق ولكن اكثر الناس لا يؤمنون","dt":"[1] المر سبق الكلام على الحروف المقطعه في اول سوره البقره.هذه ايات القران الرفيعه القدر، وهذا القران المنزل عليك -ايها الرسول- هو الحق، لا كما يقول المشركون: انك تاتي به من عند نفسك، ومع هذا فاكثر الناس لا يصدقون به ولا يعملون."},{"id":"1709","s":13,"a":2,"at":"الله الذي رفع السموات بغير عمد ترونها ثم استوى على العرش وسخر الشمس والقمر كل يجري لاجل مسمى يدبر الامر يفصل الايات لعلكم بلقاء ربكم توقنون","dt":"[2] الله تعالى هو الذي رفع السموات السبع بقدرته من غير عمد كما ترونها، ثم استوى -اي: علا وارتفع- على العرش استواء يليق بجلاله وعظمته، وذلل الشمس والقمر لمنافع العباد، كل منهما يدور في فلكه الى يوم القيامه. يدبر سبحانه امور الدنيا والاخره، يوضح لكم الايات الداله على قدرته وانه لا اله الا هو؛ لتوقنوا بالله والمعاد اليه، فتصدقوا بوعده ووعيده وتخلصوا العباده له وحده."},{"id":"1710","s":13,"a":3,"at":"وهو الذي مد الارض وجعل فيها رواسي وانهارا ومن كل الثمرات جعل فيها زوجين اثنين يغشي الليل النهار ان في ذلك لايات لقوم يتفكرون","dt":"[3] وهو سبحانه الذي جعل الارض متسعه ممتده، وهياها لمعاشكم، وجعل فيها جبالا تثبتها وانهارا لشربكم ومنافعكم، وجعل فيها من كل الثمرات صنفين اثنين، فكان منها الابيض والاسود والحلو والحامض، وجعل الليل يغطي النهار بظلمته، ان في ذلك كله لعظات لقوم يتفكرون فيها، فيتعظون."},{"id":"1711","s":13,"a":4,"at":"وفي الارض قطع متجاورات وجنات من اعناب وزرع ونخيل صنوان وغير صنوان يسقى بماء واحد ونفضل بعضها على بعض في الاكل ان في ذلك لايات لقوم يعقلون","dt":"[4] وفي الارض قطع يجاور بعضها بعضا، منها ما هو طيب ينبت ما ينفع الناس، ومنها سبخه ملحه لا تنبت شيئا، وفي الارض الطيبه بساتين من اعناب، وجعل فيها زروعا مختلفه ونخيلا مجتمعا في منبت واحد، وغير مجتمع فيه، كل ذلك في تربه واحده، ويشرب من ماء واحد، ولكنه يختلف في الثمار والحجم والطعم وغير ذلك، فهذا حلو وهذا حامض، وبعضها افضل من بعض في الاكل، ان في ذلك لعلامات لمن كان له قلب يعقل عن الله تعالى امره ونهيه."},{"id":"1712","s":13,"a":5,"at":"وان تعجب فعجب قولهم ائذا كنا ترابا ائنا لفي خلق جديد اولئك الذين كفروا بربهم واولئك الاغلال في اعناقهم واولئك اصحاب النار هم فيها خالدون","dt":"[5] وان تعجب -ايها الرسول- من عدم ايمان الكفار بعد هذه الادله فالعجب الاشد من قولهم: ااذا متنا وكنا ترابا نبعث من جديد؟ اولئك هم الجاحدون بربهم الذي اوجدهم من العدم، واولئك تكون السلاسل من النار في اعناقهم يوم القيامه، واولئك يدخلون النار، ولا يخرجون منها ابدا."},{"id":"1713","s":13,"a":6,"at":"ويستعجلونك بالسيئه قبل الحسنه وقد خلت من قبلهم المثلات وان ربك لذو مغفره للناس على ظلمهم وان ربك لشديد العقاب","dt":"[6] ويستعجلك المكذبون بالعقوبه التي لم اعاجلهم بها قبل الايمان الذي يرجى به الامان والحسنات، وقد مضت عقوبات المكذبين من قبلهم، فكيف لا يعتبرون بهم؟ وان ربك -ايها الرسول- لذو مغفره لذنوب من تاب من ذنوبه من الناس على ظلمهم، يفتح لهم باب المغفره، ويدعوهم اليها، وهم يظلمون انفسهم بعصيانهم ربهم، وان ربك لشديد العقاب على من اصر على الكفر والضلال ومعصيه الله."},{"id":"1714","s":13,"a":7,"at":"ويقول الذين كفروا لولا انزل عليه ايه من ربه انما انت منذر ولكل قوم هاد","dt":"[7] ويقول كفار «مكه»: هلا جاءته معجزه محسوسه كعصا موسى وناقه صالح، وليس ذلك بيدك -ايها الرسول- فما انت الا مبلغ لهم، ومخوف من باس الله. ولكل امه رسول يرشدهم الى الله تعالى."},{"id":"1715","s":13,"a":8,"at":"الله يعلم ما تحمل كل انثى وما تغيض الارحام وما تزداد وكل شيء عنده بمقدار","dt":"[8] الله تعالى يعلم ما تحمل كل انثى في بطنها، اذكر هو ام انثى؟ وشقي هو ام سعيد؟ ويعلم ما تنقصه الارحام، فيسقط او يولد قبل تسعه اشهر، وما يزيد حمله عليها. وكل شيء مقدر عند الله بمقدار من النقصان او الزياده لا يتجاوزه."},{"id":"1716","s":13,"a":9,"at":"عالم الغيب والشهاده الكبير المتعال","dt":"[9] الله عالم بما خفي عن الابصار، وبما هو مشاهد، الكبير في ذاته واسمائه وصفاته، المتعالي على جميع خلقه بذاته وقدرته وقهره."},{"id":"1717","s":13,"a":10,"at":"سواء منكم من اسر القول ومن جهر به ومن هو مستخف بالليل وسارب بالنهار","dt":"[10] يستوي في علمه تعالى من اخفى القول منكم ومن جهر به، ويستوي عنده من استتر باعماله في ظلمه الليل، ومن جهر بها في وضح النهار."},{"id":"1718","s":13,"a":11,"at":"له معقبات من بين يديه ومن خلفه يحفظونه من امر الله ان الله لا يغير ما بقوم حتى يغيروا ما بانفسهم واذا اراد الله بقوم سوءا فلا مرد له وما لهم من دونه من وال","dt":"[11] لله تعالى ملائكه يتعاقبون على الانسان من بين يديه ومن خلفه، يحفظونه بامر الله ويحصون ما يصدر عنه من خير او شر. ان الله سبحانه وتعالى لا يغير نعمه انعمها على قوم الا اذا غيروا ما امرهم به فعصوه. واذا اراد الله بجماعه بلاء فلا مفر منه، وليس لهم من دون الله من وال يتولى امورهم، فيجلب لهم المحبوب، ويدفع عنهم المكروه."},{"id":"1719","s":13,"a":12,"at":"هو الذي يريكم البرق خوفا وطمعا وينشئ السحاب الثقال","dt":"[12] هو الذي يريكم من اياته البرق -وهو النور اللامع من خلال السحاب- فتخافون ان تنزل عليكم منه الصواعق المحرقه، وتطمعون ان ينزل معه المطر، وبقدرته سبحانه يوجد السحاب المحمل بالماء الكثير لمنافعكم."},{"id":"1720","s":13,"a":13,"at":"ويسبح الرعد بحمده والملائكه من خيفته ويرسل الصواعق فيصيب بها من يشاء وهم يجادلون في الله وهو شديد المحال","dt":"[13] ويسبح الرعد بحمد الله تسبيحا يدل على خضوعه لربه، وتنزه الملائكه ربها من خوفها من الله، ويرسل الله الصواعق المهلكه فيهلك بها من يشاء من خلقه، والكفار يجادلون في وحدانيه الله وقدرته على البعث، وهو شديد الحول والقوه والبطش بمن عصاه."},{"id":"1721","s":13,"a":14,"at":"له دعوه الحق والذين يدعون من دونه لا يستجيبون لهم بشيء الا كباسط كفيه الى الماء ليبلغ فاه وما هو ببالغه وما دعاء الكافرين الا في ضلال","dt":"[14] لله سبحانه وتعالى وحده دعوه التوحيد «لا اله الا الله»، فلا يعبد ولا يدعى الا هو؛ والالهه التي يعبدونها من دون الله لا تجيب دعاء من دعاها، وحالهم معها كحال عطشان يبسط كفيه الى الماء من بعيد؛ ليصل الى فمه فلا يصل اليه، وما سؤال الكافرين لها الا غايه في البعد عن الصواب لاشراكهم بالله غيره."},{"id":"1722","s":13,"a":15,"at":"ولله يسجد من في السموات والارض طوعا وكرها وظلالهم بالغدو والاصال","dt":"[15] ولله وحده يسجد - خاضعا منقادا - كل من في السموات والارض، فيسجد ويخضع له المؤمنون طوعا واختيارا، ويخضع له الكافرون رغما عنهم؛ لانهم يستكبرون عن عبادته، وحالهم وفطرتهم تكذبهم في ذلك، وتنقاد لعظمه الله ظلال المخلوقات، فتتحرك بارادته اول النهار واخره."},{"id":"1723","s":13,"a":16,"at":"قل من رب السموات والارض قل الله قل افاتخذتم من دونه اولياء لا يملكون لانفسهم نفعا ولا ضرا قل هل يستوي الاعمى والبصير ام هل تستوي الظلمات والنور ام جعلوا لله شركاء خلقوا كخلقه فتشابه الخلق عليهم قل الله خالق كل شيء وهو الواحد القهار","dt":"[16] قل -ايها الرسول- للمشركين: من خالق السموات والارض ومدبرهما؟ قل: الله هو الخالق المدبر لهما، وانتم تقرون بذلك، ثم قل لهم ملزما بالحجه: اجعلتم غيره معبودين لكم، وهم لا يقدرون على نفع انفسهم او ضرها فضلا عن نفعكم او ضركم، وتركتم عباده مالكها؟ قل لهم -ايها الرسول-: هل يستوي عندكم الكافر -وهو كالاعمى- والمؤمن - وهو كالبصير؟ ام هل يستوي عندكم الكفر -وهو كالظلمات-والايمان-وهو كالنور؟ ام ان اولياءهم الذين جعلوهم شركاء لله يخلقون مثل خلقه، فتشابه عليهم خلق الشركاء بخلق الله، فاعتقدوا استحقاقهم للعباده؟ قل لهم -ايها الرسول-: الله تعالى خالق كل كائن من العدم، وهو المستحق للعباده وحده، وهو الواحد القهار الذي يستحق الالوهيه والعباده، لا الاصنام والاوثان التي لا تضر ولا تنفع."},{"id":"1724","s":13,"a":17,"at":"انزل من السماء ماء فسالت اوديه بقدرها فاحتمل السيل زبدا رابيا ومما يوقدون عليه في النار ابتغاء حليه او متاع زبد مثله كذلك يضرب الله الحق والباطل فاما الزبد فيذهب جفاء واما ما ينفع الناس فيمكث في الارض كذلك يضرب الله الامثال","dt":"[17] ثم ضرب الله سبحانه مثلا للحق والباطل بماء انزله من السماء، فجرت به اوديه الارض بقدر صغرها وكبرها، فحمل السيل غثاء طافيا فوقه لا نفع فيه. وضرب مثلا اخر: هو المعادن يوقدون عليها النار لصهرها؛ طلبا للزينه كما في الذهب والفضه، او طلبا لمنافع ينتفعون بها كما في النحاس، فيخرج منها خبثها مما لا فائده فيه كالذي كان مع الماء، بمثل هذا يضرب الله المثل للحق والباطل: فالباطل كغثاء الماء وخبث المعادن يتلاشى او يرمى؛ اذ لا فائده منه، والحق كالماء الصافي، والمعادن النقيه تبقى في الارض للانتفاع بها، كما بين لكم هذه الامثال، كذلك يضربها للناس؛ ليتضح الحق من الباطل والهدى من الضلال."},{"id":"1725","s":13,"a":18,"at":"للذين استجابوا لربهم الحسنى والذين لم يستجيبوا له لو ان لهم ما في الارض جميعا ومثله معه لافتدوا به اولئك لهم سوء الحساب وماواهم جهنم وبئس المهاد","dt":"[18] للمؤمنين الذين اطاعوا الله ورسوله الجنه، والذين لم يطيعوا وكفروا به لهم النار، ولو كانوا يملكون كل ما في الارض وضعفه معه لبذلوه فداء لانفسهم من عذاب الله يوم القيامه، ولن يتقبل منهم، اولئك يحاسبون على كل ما اسلفوه من عمل سيئ، ومسكنهم ومقامهم جهنم تكون لهم فراشا، وبئس الفراش الذي مهدوه لانفسهم."},{"id":"1726","s":13,"a":19,"at":"افمن يعلم انما انزل اليك من ربك الحق كمن هو اعمى انما يتذكر اولو الالباب","dt":"[19] هل الذي يعلم ان ما جاءك -ايها الرسول- من عند الله هو الحق فيؤمن به، كالاعمى عن الحق الذي لم يؤمن؟ انما يتعظ اصحاب العقول السليمه."},{"id":"1727","s":13,"a":20,"at":"الذين يوفون بعهد الله ولا ينقضون الميثاق","dt":"[20] الذين يوفون بعهد الله الذي امرهم به، ولا ينكثون العهد المؤكد الذي عاهدوا الله عليه."},{"id":"1728","s":13,"a":21,"at":"والذين يصلون ما امر الله به ان يوصل ويخشون ربهم ويخافون سوء الحساب","dt":"[21] وهم الذين يصلون ما امرهم الله بوصله كالارحام والمحتاجين، ويراقبون ربهم، ويخشون ان يحاسبهم على كل ذنوبهم، ولا يغفر لهم منها شيئا."},{"id":"1729","s":13,"a":22,"at":"والذين صبروا ابتغاء وجه ربهم واقاموا الصلاه وانفقوا مما رزقناهم سرا وعلانيه ويدرءون بالحسنه السيئه اولئك لهم عقبى الدار","dt":"[22] وهم الذين صبروا على الاذى وعلى الطاعه، وعن المعصيه طلبا لرضا ربهم، وادوا الصلاه على اتم وجوهها، وادوا من اموالهم زكاتهم المفروضه، والنفقات المستحبه في الخفاء والعلن، ويدفعون بالحسنه السيئه فتمحوها، اولئك الموصوفون بهذه الصفات لهم العاقبه المحموده في الاخره."},{"id":"1730","s":13,"a":23,"at":"جنات عدن يدخلونها ومن صلح من ابائهم وازواجهم وذرياتهم والملائكه يدخلون عليهم من كل باب","dt":"[23] تلك العاقبه هي جنات عدن يقيمون فيها لا يزولون عنها، ومعهم الصالحون من الاباء والزوجات والذريات من الذكور والاناث، وتدخل الملائكه عليهم من كل باب؛ لتهنئتهم بدخول الجنه."},{"id":"1731","s":13,"a":24,"at":"سلام عليكم بما صبرتم فنعم عقبى الدار","dt":"[24] تقول الملائكه لهم: سلام عليكم، تحيه خاصه لكم، وسلمتم من كل سوء؛ بسبب صبركم على طاعه الله، فنعم عاقبه الدار الجنه."},{"id":"1732","s":13,"a":25,"at":"والذين ينقضون عهد الله من بعد ميثاقه ويقطعون ما امر الله به ان يوصل ويفسدون في الارض اولئك لهم اللعنه ولهم سوء الدار","dt":"[25] اما الاشقياء فقد وصفوا بضد صفات المؤمنين، فهم الذين لا يوفون بعهد الله بافراده سبحانه بالعباده بعد ان اكدوه على انفسهم، وهم الذين يقطعون ما امرهم الله بوصله من صله الارحام وغيرها، ويفسدون في الارض بعمل المعاصي، اولئك الموصوفون بهذه الصفات القبيحه لهم الطرد من رحمه الله، ولهم ما يسوءهم من العذاب الشديد في الدار الاخره."},{"id":"1733","s":13,"a":26,"at":"الله يبسط الرزق لمن يشاء ويقدر وفرحوا بالحياه الدنيا وما الحياه الدنيا في الاخره الا متاع","dt":"[26] الله وحده يوسع الرزق لمن يشاء من عباده، ويضيق على من يشاء منهم، وفرح الكفار بالسعه في الحياه الدنيا، وما هذه الحياه الدنيا بالنسبه للاخره الا شيء قليل يتمتع به، سرعان ما يزول."},{"id":"1734","s":13,"a":27,"at":"ويقول الذين كفروا لولا انزل عليه ايه من ربه قل ان الله يضل من يشاء ويهدي اليه من اناب","dt":"[27] ويقول الكفار عنادا: هلا انزل على محمد معجزه محسوسه كمعجزه موسى وعيسى. قل لهم: ان الله يضل من يشاء من المعاندين عن الهدايه ولا تنفعه المعجزات، ويهدي الى دينه الحق من رجع اليه وطلب رضوانه."},{"id":"1735","s":13,"a":28,"at":"الذين امنوا وتطمئن قلوبهم بذكر الله الا بذكر الله تطمئن القلوب","dt":"[28] ويهدي الذين تسكن قلوبهم بتوحيد الله وذكره فتطمئن، الا بطاعه الله وذكره وثوابه تسكن القلوب وتستانس."},{"id":"1736","s":13,"a":29,"at":"الذين امنوا وعملوا الصالحات طوبى لهم وحسن ماب","dt":"[29] الذين صدقوا بالله ورسوله، وعملوا الاعمال الصالحات لهم فرح وقره عين، وحال طيبه، ومرجع حسن الى جنه الله ورضوانه."},{"id":"1737","s":13,"a":30,"at":"كذلك ارسلناك في امه قد خلت من قبلها امم لتتلو عليهم الذي اوحينا اليك وهم يكفرون بالرحمن قل هو ربي لا اله الا هو عليه توكلت واليه متاب","dt":"[30] كما ارسلنا المرسلين قبلك ارسلناك -ايها الرسول- في امه قد مضت من قبلها امم المرسلين؛ لتتلو على هذه الامه القران المنزل عليك، وحال قومك الجحود بوحدانيه الرحمن، قل لهم -ايها الرسول-: الرحمن الذي لم تتخذوه الها واحدا هو ربي وحده لا معبود بحق سواه، عليه اعتمدت ووثقت، واليه مرجعي وانابتي."},{"id":"1738","s":13,"a":31,"at":"ولو ان قرانا سيرت به الجبال او قطعت به الارض او كلم به الموتى بل لله الامر جميعا افلم يياس الذين امنوا ان لو يشاء الله لهدى الناس جميعا ولا يزال الذين كفروا تصيبهم بما صنعوا قارعه او تحل قريبا من دارهم حتى ياتي وعد الله ان الله لا يخلف الميعاد","dt":"[31] يرد الله -تعالى- على الكافرين الذين طلبوا انزال معجزات محسوسه على النبي -صلى الله عليه وسلم- فيقول لهم: ولو ان ثمه قرانا يقرا، فتزول به الجبال عن اماكنها، او تتشقق به الارض انهارا، او يحيا به الموتى وتكلم -كما طلبوا منك- لكان هذا القران هو المتصف بذلك دون غيره، ولما امنوا به. بل لله وحده الامر كله في المعجزات وغيرها. افلم يعلم المؤمنون ان الله لو يشاء لامن اهل الارض كلهم من غير معجزه؟ ولا يزال الكفار تنزل بهم مصيبه بسبب كفرهم كالقتل والاسر في غزوات المسلمين، او تنزل تلك المصيبه قريبا من دارهم، حتى ياتي وعد الله بالنصر عليهم، ان الله لا يخلف الميعاد."},{"id":"1739","s":13,"a":32,"at":"ولقد استهزئ برسل من قبلك فامليت للذين كفروا ثم اخذتهم فكيف كان عقاب","dt":"[32] واذا كانوا قد سخروا من دعوتك -ايها الرسول- فلقد سخرت امم من قبلك برسلهم، فلا تحزن فقد امهلت الذين كفروا، ثم اخذتهم بعقابي، وكان عقابا شديدا."},{"id":"1740","s":13,"a":33,"at":"افمن هو قائم على كل نفس بما كسبت وجعلوا لله شركاء قل سموهم ام تنبئونه بما لا يعلم في الارض ام بظاهر من القول بل زين للذين كفروا مكرهم وصدوا عن السبيل ومن يضلل الله فما له من هاد","dt":"[33] افمن هو قائم على كل نفس يحصي عليها ما تعمل، احق ان يعبد، ام هذه المخلوقات العاجزه؟ وهم -من جهلهم- جعلوا لله شركاء من خلقه يعبدونهم، قل لهم -ايها الرسول-: اذكروا اسماءهم وصفاتهم، ولن يجدوا من صفاتهم ما يجعلهم اهلا للعباده، ام تخبرون الله بشركاء في ارضه لا يعلمهم، ام تسمونهم شركاء بظاهر من اللفظ من غير ان يكون لهم حقيقه. بل حسن الشيطان للكفار قولهم الباطل وصدهم عن سبيل الله. ومن لم يوفقه الله لهدايته فليس له احد يهديه، ويوفقه الى الحق والرشاد."},{"id":"1741","s":13,"a":34,"at":"لهم عذاب في الحياه الدنيا ولعذاب الاخره اشق وما لهم من الله من واق","dt":"[34] لهؤلاء الكفار الصادين عن سبيل الله عذاب شاق في الحياه الدنيا بالقتل والاسر والخزي، ولعذابهم في الاخره اثقل واشد، وليس لهم مانع يمنعهم من عذاب الله."},{"id":"1742","s":13,"a":35,"at":"مثل الجنه التي وعد المتقون تجري من تحتها الانهار اكلها دائم وظلها تلك عقبى الذين اتقوا وعقبى الكافرين النار","dt":"[35] صفه الجنه التي وعد الله بها الذين يخشونه انها تجري من تحت اشجارها وقصورها الانهار، ثمرها لا ينقطع، وظلها لا يزول ولا ينقص، تلك المثوبه بالجنه عاقبه الذين خافوا الله، فاجتنبوا معاصيه وادوا فرائضه، وعاقبه الكافرين بالله النار."},{"id":"1743","s":13,"a":36,"at":"والذين اتيناهم الكتاب يفرحون بما انزل اليك ومن الاحزاب من ينكر بعضه قل انما امرت ان اعبد الله ولا اشرك به اليه ادعو واليه ماب","dt":"[36] والذين اعطيناهم الكتاب من اليهود والنصارى، من امن منهم بك كعبدالله بن سلام والنجاشي، يستبشرون بالقران المنزل عليك لموافقته ما عندهم، ومن المتحزبين على الكفر ضدك، كالسيد والعاقب-اسقفي «نجران»-، وكعب بن الاشرف، من ينكر بعض المنزل عليك، قل لهم: انما امرني الله ان اعبده وحده، ولا اشرك به شيئا، الى عبادته ادعو الناس، واليه مرجعي ومابي."},{"id":"1744","s":13,"a":37,"at":"وكذلك انزلناه حكما عربيا ولئن اتبعت اهواءهم بعد ما جاءك من العلم ما لك من الله من ولي ولا واق","dt":"[37] وكما انزلنا الكتب على الانبياء بلسانهم انزلنا اليك -ايها الرسول- القران بلغه العرب؛ لتحكم به، ولئن اتبعت اهواء المشركين في عباده غير الله -بعد الحق الذي جاءك من الله- ليس لك ناصر ينصرك ويمنعك من عذابه."},{"id":"1745","s":13,"a":38,"at":"ولقد ارسلنا رسلا من قبلك وجعلنا لهم ازواجا وذريه وما كان لرسول ان ياتي بايه الا باذن الله لكل اجل كتاب","dt":"[38] واذا قالوا: ما لك -ايها الرسول- تتزوج النساء؟ فلقد بعثنا قبلك رسلا من البشر وجعلنا لهم ازواجا وذريه، واذا قالوا: لو كان رسولا لاتى بما طلبنا من المعجزات، فليس في وسع رسول ان ياتي بمعجزه ارادها قومه الا باذن الله. لكل امر قضاه الله كتاب واجل قد كتبه الله عنده، لا يتقدم ولا يتاخر."},{"id":"1746","s":13,"a":39,"at":"يمحوا الله ما يشاء ويثبت وعنده ام الكتاب","dt":"[39] يمحو الله ما يشاء من الاحكام وغيرها، ويبقي ما يشاء منها لحكمه يعلمها، وعنده اصل الكتاب، وهو اللوح المحفوظ الذي اثبت فيه جميع احوال الخلق الى يوم القيامه."},{"id":"1747","s":13,"a":40,"at":"وان ما نرينك بعض الذي نعدهم او نتوفينك فانما عليك البلاغ وعلينا الحساب","dt":"[40] وان اريناك -ايها الرسول- بعض العقاب الذي توعدنا به اعداءك من الخزي والنكال في الدنيا فذلك المعجل لهم، وان توفيناك قبل ان ترى ذلك، فما عليك الا تبليغ الدعوه، وعلينا الحساب والجزاء."},{"id":"1748","s":13,"a":41,"at":"او لم يروا انا ناتي الارض ننقصها من اطرافها والله يحكم لا معقب لحكمه وهو سريع الحساب","dt":"[41] اولم يبصر هؤلاء الكفار انا ناتي الارض ننقصها من اطرافها، وذلك بفتح المسلمين بلاد المشركين والحاقها ببلاد المسلمين؟ والله سبحانه يحكم لا راد ولا مبطل لحكمه وقضائه، وهو سريع الحساب، فلا يستعجلوا بالعذاب؛ فان كل ات قريب."},{"id":"1749","s":13,"a":42,"at":"وقد مكر الذين من قبلهم فلله المكر جميعا يعلم ما تكسب كل نفس وسيعلم الكفار لمن عقبى الدار","dt":"[42] ولقد دبر الذين من قبلهم المكايد لرسلهم، كما فعل هؤلاء معك، فلله المكر جميعا، فيبطل مكرهم، ويعيده عليهم بالخيبه والندم، يعلم سبحانه ما تكسب كل نفس من خير او شر فتجازى عليه. وسيعلم الكفار -اذا قدموا على ربهم- لمن تكون العاقبه المحموده بعد هذه الدنيا؟ انها لاتباع الرسل. وفي هذا تهديد ووعيد للكافرين."},{"id":"1750","s":13,"a":43,"at":"ويقول الذين كفروا لست مرسلا قل كفى بالله شهيدا بيني وبينكم ومن عنده علم الكتاب","dt":"[43] ويقول الذين كفروا لنبي الله: -يا محمد- ما ارسلك الله، قل لهم: كفى بالله شهيدا بصدقي وكذبكم، وكفت شهاده من عنده علم الكتاب من اليهود والنصارى ممن امن برسالتي، وما جئت به من عند الله، واتبع الحق فصرح بتلك الشهاده، ولم يكتمها."},{"id":"1751","s":14,"a":1,"at":"الر كتاب انزلناه اليك لتخرج الناس من الظلمات الى النور باذن ربهم الى صراط العزيز الحميد","dt":"[1] الر سبق الكلام على الحروف المقطعه في اول سوره البقره.هذا القران كتاب اوحيناه اليك -ايها الرسول- لتخرج به البشر من الضلال والغي الى الهدى والنور -باذن ربهم وتوفيقه اياهم- الى الاسلام الذي هو طريق الله الغالب المحمود في كل حال،"},{"id":"1752","s":14,"a":2,"at":"الله الذي له ما في السموات وما في الارض وويل للكافرين من عذاب شديد","dt":"[2] الله الذي له ما في السموات وما في الارض، خلقا وملكا وتصرفا، فهو الذي يجب ان تكون العباده له وحده. وسوف يصيب الذين لم يؤمنوا بالله ولم يتبعوا رسله يوم القيامه هلاك وعذاب شديد."},{"id":"1753","s":14,"a":3,"at":"الذين يستحبون الحياه الدنيا على الاخره ويصدون عن سبيل الله ويبغونها عوجا اولئك في ضلال بعيد","dt":"[3] وهؤلاء الذين اعرضوا ولم يؤمنوا بالله ويتبعوا رسله هم الذين يختارون الحياه الدنيا الفانيه، ويتركون الاخره الباقيه، ويمنعون الناس عن اتباع دين الله، ويريدونه طريقا معوجا ليوافق اهواءهم، اولئك الموصوفون بهذه الصفات في ضلال عن الحق بعيد عن كل اسباب الهدايه."},{"id":"1754","s":14,"a":4,"at":"وما ارسلنا من رسول الا بلسان قومه ليبين لهم فيضل الله من يشاء ويهدي من يشاء وهو العزيز الحكيم","dt":"[4] وما ارسلنا من رسول قبلك -ايها النبي- الا بلغه قومه؛ ليوضح لهم شريعه الله، فيضل الله من يشاء عن الهدى، ويوفق من يشاء الى الحق، وهو العزيز في ملكه، الحكيم الذي يضع الامور في مواضعها وفق الحكمه."},{"id":"1755","s":14,"a":5,"at":"ولقد ارسلنا موسى باياتنا ان اخرج قومك من الظلمات الى النور وذكرهم بايام الله ان في ذلك لايات لكل صبار شكور","dt":"[5] ولقد ارسلنا موسى الى بني اسرائيل وايدناه بالمعجزات الداله على صدقه، وامرناه بان يدعوهم الى الايمان؛ ليخرجهم من الضلال الى الهدى، ويذكرهم بنعم الله ونقمه في ايامه، ان في هذا التذكير بها لدلالات لكل صبار على طاعه الله، وعن محارمه، وعلى اقداره، شكور قائم بحقوق الله، يشكر الله على نعمه. وخص هذين الصنفين بالذكر؛ لانهم هم الذين يعتبرون بالايات، ولا يغفلون عنها."},{"id":"1756","s":14,"a":6,"at":"واذ قال موسى لقومه اذكروا نعمه الله عليكم اذ انجاكم من ال فرعون يسومونكم سوء العذاب ويذبحون ابناءكم ويستحيون نساءكم وفي ذلكم بلاء من ربكم عظيم","dt":"[6] واذكر -ايها الرسول- لقومك قصه موسى حين قال لبني اسرائيل: اذكروا نعمه الله عليكم حين انجاكم من فرعون واتباعه يذيقونكم اشد العذاب، ويذبحون ابناءكم الذكور، حتى لا ياتي منهم من يستولي على ملك فرعون، ويستبقون نساءكم للخدمه والامتهان، وفي ذلكم البلاء والانجاء اختبار لكم من ربكم عظيم."},{"id":"1757","s":14,"a":7,"at":"واذ تاذن ربكم لئن شكرتم لازيدنكم ولئن كفرتم ان عذابي لشديد","dt":"[7] وقال لهم موسى: واذكروا حين اعلم ربكم اعلاما مؤكدا: لئن شكرتموه على نعمه ليزيدنكم من فضله، ولئن جحدتم نعمه الله ليعذبنكم عذابا شديدا."},{"id":"1758","s":14,"a":8,"at":"وقال موسى ان تكفروا انتم ومن في الارض جميعا فان الله لغني حميد","dt":"[8] وقال لهم: ان تكفروا بالله انتم وجميع اهل الارض فلن تضروا الله شيئا؛ فان الله لغني عن خلقه، مستحق للحمد والثناء، محمود في كل حال."},{"id":"1759","s":14,"a":9,"at":"الم ياتكم نبا الذين من قبلكم قوم نوح وعاد وثمود والذين من بعدهم لا يعلمهم الا الله جاءتهم رسلهم بالبينات فردوا ايديهم في افواههم وقالوا انا كفرنا بما ارسلتم به وانا لفي شك مما تدعوننا اليه مريب","dt":"[9] الم ياتكم -يا امه محمد- خبر الامم التي سبقتكم، قوم نوح وقوم هود وقوم صالح، والامم التي بعدهم، لا يحصي عددهم الا الله، جاءتهم رسلهم بالبراهين الواضحات، فعضوا ايديهم غيظا واستنكافا عن قبول الايمان، وقالوا لرسلهم: انا لا نصدق بما جئتمونا به، وانا لفي شك مما تدعوننا اليه من الايمان والتوحيد موجب للريبه."},{"id":"1760","s":14,"a":10,"at":"قالت رسلهم افي الله شك فاطر السموات والارض يدعوكم ليغفر لكم من ذنوبكم ويؤخركم الى اجل مسمى قالوا ان انتم الا بشر مثلنا تريدون ان تصدونا عما كان يعبد اباؤنا فاتونا بسلطان مبين","dt":"[10] قالت لهم رسلهم: افي الله وعبادته -وحده- ريب، وهو خالق السموات والارض، ومنشئهما من العدم على غير مثال سابق، وهو يدعوكم الى الايمان؛ ليغفر لكم ما اسلفتم من الشرك، ويدفع عنكم عذاب الاستئصال، فيؤخر بقاءكم في الدنيا الى اجل قدره، وهو نهايه اجالكم، فلا يعذبكم في الدنيا؟ فقالوا لرسلهم: ما نراكم الا بشرا صفاتكم كصفاتنا، لا فضل لكم علينا يؤهلكم ان تكونوا رسلا، تريدون ان تمنعونا من عباده ما كان يعبده اباؤنا من الاصنام والاوثان، فاتونا بحجه ظاهره تشهد على صحه ما تقولون."},{"id":"1761","s":14,"a":11,"at":"قالت لهم رسلهم ان نحن الا بشر مثلكم ولكن الله يمن على من يشاء من عباده وما كان لنا ان ناتيكم بسلطان الا باذن الله وعلى الله فليتوكل المؤمنون","dt":"[11] ولما سمع الرسل ما قاله اقوامهم قالوا لهم: حقا ما نحن الا بشر مثلكم كما قلتم، ولكن الله يتفضل بانعامه على من يشاء من عباده فيصطفيهم لرسالته، وما طلبتم من البرهان المبين، فلا يمكن لنا ولا نستطيع ان ناتيكم به الا باذن الله وتوفيقه، وعلى الله وحده يعتمد المؤمنون في كل امورهم."},{"id":"1762","s":14,"a":12,"at":"وما لنا الا نتوكل على الله وقد هدانا سبلنا ولنصبرن على ما اذيتمونا وعلى الله فليتوكل المتوكلون","dt":"[12] وكيف لا نعتمد على الله، وهو الذي ارشدنا الى طرق النجاه من عذابه، ووفقنا الى اتباع احكام دينه؟ ولنصبرن على ايذائكم لنا بالكلام السيئ وغيره، وعلى الله وحده يجب ان يعتمد المؤمنون في نصرهم، وهزيمه اعدائهم."},{"id":"1763","s":14,"a":13,"at":"وقال الذين كفروا لرسلهم لنخرجنكم من ارضنا او لتعودن في ملتنا فاوحى اليهم ربهم لنهلكن الظالمين","dt":"[13] وضاقت صدور الكفار مما قاله الرسل فقالوا لهم: لنطردنكم من بلادنا حتى تعودوا الى ديننا، فاوحى الله الى رسله انه سيهلك الجاحدين الذين كفروا به وبرسله."},{"id":"1764","s":14,"a":14,"at":"ولنسكننكم الارض من بعدهم ذلك لمن خاف مقامي وخاف وعيد","dt":"[14] ولنجعلن العاقبه الحسنه للرسل واتباعهم باسكانهم ارض الكافرين بعد اهلاكهم، ذلك الاهلاك للكفار، واسكان المؤمنين ارضهم امر مؤكد لمن خاف مقامه بين يدي يوم القيامه، وخشي وعيدي وعذابي."},{"id":"1765","s":14,"a":15,"at":"واستفتحوا وخاب كل جبار عنيد","dt":"[15] ولجا الرسل الى ربهم وسالوه النصر على اعدائهم والحكم بينهم، فاستجاب لهم، وهلك كل متكبر لا يقبل الحق ولا يذعن له، ولا يقر بتوحيد الله واخلاص العباده له."},{"id":"1766","s":14,"a":16,"at":"من ورائه جهنم ويسقى من ماء صديد","dt":"[16] ومن امام هذا الكافر جهنم يلقى عذابها، ويسقى فيها من القيح والدم الذي يخرج من اجسام اهل النار."},{"id":"1767","s":14,"a":17,"at":"يتجرعه ولا يكاد يسيغه وياتيه الموت من كل مكان وما هو بميت ومن ورائه عذاب غليظ","dt":"[17] يحاول المتكبر ابتلاع القيح والدم وغير ذلك مما يسيل من اهل النار مره بعد مره، فلا يستطيع ان يبتلعه؛ لقذارته وحرارته ومرارته، بل يشربه بعد عناء، فيقطع امعاءه، وياتيه العذاب الشديد من كل نوع ومن كل عضو من جسده، وما هو بميت فيستريح، وله من بعد هذا العذاب عذاب اخر مؤلم."},{"id":"1768","s":14,"a":18,"at":"مثل الذين كفروا بربهم اعمالهم كرماد اشتدت به الريح في يوم عاصف لا يقدرون مما كسبوا على شيء ذلك هو الضلال البعيد","dt":"[18] صفه اعمال الكفار في الدنيا كالبر وصله الارحام كصفه رماد اشتدت به الريح في يوم ذي ريح شديده، فلم تترك له اثرا، فكذلك اعمالهم لا يجدون منها ما ينفعهم عند الله، فقد اذهبها الكفر كما اذهبت الريح الرماد، ذلك السعي والعمل على غير اساس، هو الضلال البعيد عن الطريق المستقيم."},{"id":"1769","s":14,"a":19,"at":"الم تر ان الله خلق السموات والارض بالحق ان يشا يذهبكم ويات بخلق جديد","dt":"[19] الم تعلم ايها المخاطب -والمراد عموم الناس- ان الله اوجد السموات والارض على الوجه الصحيح الدال على حكمته، وانه لم يخلقهما عبثا، بل للاستدلال بهما على وحدانيته، وكمال قدرته، فيعبدوه وحده، ولا يشركوا به شيئا؟ ان يشا يذهبكم ويات بقوم غيركم يطيعون الله."},{"id":"1770","s":14,"a":20,"at":"وما ذلك على الله بعزيز","dt":"[20] وما اهلاككم والاتيان بغيركم بممتنع على الله، بل هو سهل يسير."},{"id":"1771","s":14,"a":21,"at":"وبرزوا لله جميعا فقال الضعفاء للذين استكبروا انا كنا لكم تبعا فهل انتم مغنون عنا من عذاب الله من شيء قالوا لو هدانا الله لهديناكم سواء علينا اجزعنا ام صبرنا ما لنا من محيص","dt":"[21] وخرجت الخلائق من قبورهم، وظهروا كلهم يوم القيامه لله الواحد القهار؛ ليحكم بينهم، فيقول الاتباع لقادتهم: انا كنا لكم في الدنيا اتباعا، ناتمر بامركم، فهل انتم -اليوم- دافعون عنا من عذاب الله شيئا كما كنتم تعدوننا؟فيقول الرؤساء: لو وفقنا الله الى الايمان لارشدناكم اليه، ولكنه لم يوفقنا، فضللنا واضللناكم، يستوي علينا وعليكم ضعفنا عن تحمل ما نزل بنا من العذاب والصبر عليه، فليس لنا مهرب من عذاب الله ولا منجى."},{"id":"1772","s":14,"a":22,"at":"وقال الشيطان لما قضي الامر ان الله وعدكم وعد الحق ووعدتكم فاخلفتكم وما كان لي عليكم من سلطان الا ان دعوتكم فاستجبتم لي فلا تلوموني ولوموا انفسكم ما انا بمصرخكم وما انتم بمصرخي اني كفرت بما اشركتمون من قبل ان الظالمين لهم عذاب اليم","dt":"[22] وقال الشيطان -بعد ان قضى الله الامر وحاسب خلقه، ودخل اهل الجنه الجنه واهل النار النار-: ان الله وعدكم وعدا حقا بالبعث والجزاء، ووعدتكم وعدا باطلا انه لا بعث ولا جزاء، فاخلفتكم وعدي، وما كان لي عليكم من قوه اقهركم بها على اتباعي، ولا كانت معي حجه، ولكن دعوتكم الى الكفر والضلال فاتبعتموني، فلا تلوموني ولوموا انفسكم، فالذنب ذنبكم، ما انا بمغيثكم ولا انتم بمغيثي من عذاب الله، اني تبرات من جعلكم لي شريكا مع الله في طاعته في الدنيا. ان الظالمين -في اعراضهم عن الحق واتباعهم الباطل- لهم عذاب مؤلم موجع."},{"id":"1773","s":14,"a":23,"at":"وادخل الذين امنوا وعملوا الصالحات جنات تجري من تحتها الانهار خالدين فيها باذن ربهم تحيتهم فيها سلام","dt":"[23] وادخل الذين صدقوا الله ورسوله وعملوا الصالحات جنات تجري من تحت اشجارها وقصورها الانهار، لا يخرجون منها ابدا -باذن ربهم وحوله وقوته- يحيون فيها بسلام من الله وملائكته والمؤمنين."},{"id":"1774","s":14,"a":24,"at":"الم تر كيف ضرب الله مثلا كلمه طيبه كشجره طيبه اصلها ثابت وفرعها في السماء","dt":"[24] الم تعلم -ايها الرسول- كيف ضرب الله مثلا لكلمه التوحيد «لا اله الا الله» بشجره عظيمه، وهي النخله، اصلها متمكن في الارض، واعلاها مرتفع علوا نحو السماء؟"},{"id":"1775","s":14,"a":25,"at":"تؤتي اكلها كل حين باذن ربها ويضرب الله الامثال للناس لعلهم يتذكرون","dt":"[25] تعطي ثمارها كل وقت وقته الله لاثمارها، وكذلك شجره الايمان اصلها ثابت في قلب المؤمن علما واعتقادا، وفرعها من الاعمال الصالحه والاخلاق المرضيه يرفع الى الله وينال ثوابه في كل وقت. ويضرب الله الامثال للناس؛ ليتذكروا ويتعظوا، فيعتبروا."},{"id":"1776","s":14,"a":26,"at":"ومثل كلمه خبيثه كشجره خبيثه اجتثت من فوق الارض ما لها من قرار","dt":"[26] ومثل كلمه خبيثه -وهي كلمه الكفر- كشجره خبيثه الماكل والمطعم، وهي شجره الحنظل، اقتلعت من اعلى الارض؛ لان عروقها قريبه من سطح الارض ما لها اصل ثابت، ولا فرع صاعد، وكذلك الكافر لا ثبات له ولا خير فيه، ولا يرفع له عمل صالح الى الله."},{"id":"1777","s":14,"a":27,"at":"يثبت الله الذين امنوا بالقول الثابت في الحياه الدنيا وفي الاخره ويضل الله الظالمين ويفعل الله ما يشاء","dt":"[27] يثبت الله الذين امنوا بالقول الحق الراسخ، وهو شهاده ان لا اله الا الله وان محمدا رسول الله، وما جاء به من الدين الحق يثبتهم الله به في الحياه الدنيا، وعند مماتهم بالخاتمه الحسنه، وفي القبر عند سؤال الملكين بهدايتهم الى الجواب الصحيح، ويضل الله الظالمين عن الصواب في الدنيا والاخره، ويفعل الله ما يشاء من توفيق اهل الايمان وخذلان اهل الكفر والطغيان."},{"id":"1778","s":14,"a":28,"at":"الم تر الى الذين بدلوا نعمه الله كفرا واحلوا قومهم دار البوار","dt":"[28] الم تنظر ايها المخاطب -والمراد العموم- الى حال المكذبين من كفار قريش، الذين اختاروا الكفر بالله بدلا عن شكره على نعمه الامن بالحرم وبعثه النبي محمد -صلى الله عليه وسلم- فيهم؟ وقد انزلوا اتباعهم دار الهلاك حين تسببوا باخراجهم الى «بدر» فقتلوا، وصار مصيرهم دار البوار،."},{"id":"1779","s":14,"a":29,"at":"جهنم يصلونها وبئس القرار","dt":"[29] وهي جهنم، يدخلونها ويقاسون حرها، وقبح المستقر مستقرهم."},{"id":"1780","s":14,"a":30,"at":"وجعلوا لله اندادا ليضلوا عن سبيله قل تمتعوا فان مصيركم الى النار","dt":"[30] وجعل هؤلاء الكفار لله شركاء عبدوهم معه؛ ليبعدوا الناس عن دينه. قل لهم -ايها الرسول-: استمتعوا في الحياه الدنيا؛ فانها سريعه الزوال، وان مردكم ومرجعكم الى عذاب جهنم."},{"id":"1781","s":14,"a":31,"at":"قل لعبادي الذين امنوا يقيموا الصلاه وينفقوا مما رزقناهم سرا وعلانيه من قبل ان ياتي يوم لا بيع فيه ولا خلال","dt":"[31] قل -ايها الرسول- لعبادي الذين امنوا: يؤدوا الصلاه بحدودها، ويخرجوا بعض ما اعطيناهم من المال في وجوه الخير الواجبه والمستحبه مسرين ذلك ومعلنين، من قبل ان ياتي يوم القيامه الذي لا ينفع فيه فداء ولا صداقه."},{"id":"1782","s":14,"a":32,"at":"الله الذي خلق السموات والارض وانزل من السماء ماء فاخرج به من الثمرات رزقا لكم وسخر لكم الفلك لتجري في البحر بامره وسخر لكم الانهار","dt":"[32] الله تعالى الذي خلق السموات والارض واوجدهما من العدم، وانزل المطر من السحاب فاحيا به الارض بعد موتها، واخرج لكم منها ارزاقكم، وذلل لكم السفن؛ لتسير في البحر بامره لمنافعكم، وذلل لكم الانهار لسقياكم وسقيا دوابكم وزروعكم وسائر منافعكم."},{"id":"1783","s":14,"a":33,"at":"وسخر لكم الشمس والقمر دائبين وسخر لكم الليل والنهار","dt":"[33] وذلل الله لكم الشمس والقمر لا يفتران عن حركتهما؛ لتتحقق المصالح بهما، وذلل لكم الليل؛ لتسكنوا فيه وتستريحوا، والنهار؛ لتبتغوا من فضله، وتدبروا معايشكم."},{"id":"1784","s":14,"a":34,"at":"واتاكم من كل ما سالتموه وان تعدوا نعمه الله لا تحصوها ان الانسان لظلوم كفار","dt":"[34] واعطاكم من كل ما طلبتموه، وان تعدوا نعم الله عليكم لا تطيقوا عدها ولا احصاءها ولا القيام بشكرها؛ لكثرتها وتنوعها. ان الانسان لكثير الظلم لنفسه، كثير الجحود لنعم ربه."},{"id":"1785","s":14,"a":35,"at":"واذ قال ابراهيم رب اجعل هذا البلد امنا واجنبني وبني ان نعبد الاصنام","dt":"[35] واذكر -ايها الرسول- حين قال ابراهيم داعيا ربه -بعد ان اسكن ابنه اسماعيل وامه «هاجر» وادي «مكه»-: رب اجعل «مكه» بلد امن يامن كل من فيها، وابعدني وابنائي عن عباده الاصنام."},{"id":"1786","s":14,"a":36,"at":"رب انهن اضللن كثيرا من الناس فمن تبعني فانه مني ومن عصاني فانك غفور رحيم","dt":"[36] رب ان الاصنام تسببت في ابعاد كثير من الناس عن طريق الحق، فمن اقتدى بي في التوحيد فهو على ديني وسنتي، ومن خالفني فيما دون الشرك، فانك غفور لذنوب المذنبين -بفضلك- رحيم بهم، تعفو عمن تشاء منهم."},{"id":"1787","s":14,"a":37,"at":"ربنا اني اسكنت من ذريتي بواد غير ذي زرع عند بيتك المحرم ربنا ليقيموا الصلاه فاجعل افئده من الناس تهوي اليهم وارزقهم من الثمرات لعلهم يشكرون","dt":"[37] ربنا اني اسكنت من ذريتي بواد ليس فيه زرع ولا ماء بجوار بيتك المحرم، ربنا انني فعلت ذلك بامرك؛ لكي يؤدوا الصلاه بحدودها، فاجعل قلوب بعض خلقك تنزع اليهم وتحن، وارزقهم في هذا المكان من انواع الثمار؛ لكي يشكروا لك على عظيم نعمك. فاستجاب الله دعاءه."},{"id":"1788","s":14,"a":38,"at":"ربنا انك تعلم ما نخفي وما نعلن وما يخفى على الله من شيء في الارض ولا في السماء","dt":"[38] ربنا انك تعلم كل ما نخفيه وما نظهره. وما يغيب عن علم الله شيء من الكائنات في الارض ولا في السماء."},{"id":"1789","s":14,"a":39,"at":"الحمد لله الذي وهب لي على الكبر اسماعيل واسحاق ان ربي لسميع الدعاء","dt":"[39] يثني ابراهيم على الله تعالى، فيقول: الحمد لله الذي رزقني على كبر سني ولدي اسماعيل واسحاق بعد دعائي ان يهب لي من الصالحين، ان ربي لسميع الدعاء ممن دعاه، وقد دعوته ولم يخيب رجائي."},{"id":"1790","s":14,"a":40,"at":"رب اجعلني مقيم الصلاه ومن ذريتي ربنا وتقبل دعاء","dt":"[40] رب اجعلني مداوما على اداء الصلاه على اتم وجوهها، واجعل من ذريتي من يحافظ عليها، ربنا واستجب دعائي وتقبل عبادتي."},{"id":"1791","s":14,"a":41,"at":"ربنا اغفر لي ولوالدي وللمؤمنين يوم يقوم الحساب","dt":"[41] ربنا اغفر لي ما وقع مني مما لا يسلم منه البشر واغفر لوالدي، (وهذا قبل ان يتبين له ان والده عدو لله) واغفر للمؤمنين جميعا يوم يقوم الناس للحساب والجزاء."},{"id":"1792","s":14,"a":42,"at":"ولا تحسبن الله غافلا عما يعمل الظالمون انما يؤخرهم ليوم تشخص فيه الابصار","dt":"[42] ولا تحسبن -ايها الرسول- ان الله غافل عما يعمله الظالمون: من التكذيب بك وبغيرك من الرسل، وايذاء المؤمنين وغير ذلك من المعاصي، انما يؤخر عقابهم ليوم شديد ترتفع فيه عيونهم ولا تغمض؛ من هول ما تراه. وفي هذا تسليه لرسول الله محمد -صلى الله عليه وسلم-."},{"id":"1793","s":14,"a":43,"at":"مهطعين مقنعي رءوسهم لا يرتد اليهم طرفهم وافئدتهم هواء","dt":"[43] يوم يقوم الظالمون من قبورهم مسرعين لاجابه الداعي للحساب، رافعي رؤوسهم، لا يبصرون شيئا لهول الموقف، وقلوبهم خاليه لا تعي شيئا؛ لكثره الخوف والوجل من هول ما ترى."},{"id":"1794","s":14,"a":44,"at":"وانذر الناس يوم ياتيهم العذاب فيقول الذين ظلموا ربنا اخرنا الى اجل قريب نجب دعوتك ونتبع الرسل او لم تكونوا اقسمتم من قبل ما لكم من زوال","dt":"[44] وانذر -ايها الرسول- الناس الذين ارسلتك اليهم عذاب الله يوم القيامه، وعند ذلك يقول الذين ظلموا انفسهم بالكفر: ربنا امهلنا الى وقت قريب نؤمن بك ونصدق رسلك. فيقال لهم توبيخا: الم تقسموا في حياتكم انه لا زوال لكم عن الحياه الدنيا الى الاخره، فلم تصدقوا بهذا البعث؟"},{"id":"1795","s":14,"a":45,"at":"وسكنتم في مساكن الذين ظلموا انفسهم وتبين لكم كيف فعلنا بهم وضربنا لكم الامثال","dt":"[45] وحللتم في مساكن الكافرين السابقين الذين ظلموا انفسهم كقوم هود وصالح، وعلمتم -بما رايتم واخبرتم- ما انزلناه بهم من الهلاك، وضربنا لكم الامثال في القران، فلم تعتبروا؟"},{"id":"1796","s":14,"a":46,"at":"وقد مكروا مكرهم وعند الله مكرهم وان كان مكرهم لتزول منه الجبال","dt":"[46] وقد دبر المشركون الشر للرسول -صلى الله عليه وسلم- بقتله، وعند الله مكرهم فهو محيط به، وقد عاد مكرهم عليهم، وما كان مكرهم لتزول منه الجبال ولا غيرها لضعفه ووهنه، ولم يضروا الله شيئا، وانما ضروا انفسهم."},{"id":"1797","s":14,"a":47,"at":"فلا تحسبن الله مخلف وعده رسله ان الله عزيز ذو انتقام","dt":"[47] فلا تحسبن -ايها الرسول- ان الله يخلف رسله ما وعدهم من النصر واهلاك مكذبيهم. ان الله عزيز لا يمتنع عليه شيء، منتقم من اعدائه اشد انتقام. والخطاب وان كان خاصا بالنبي -صلى الله عليه وسلم-، فهو موجه لعموم الامه."},{"id":"1798","s":14,"a":48,"at":"يوم تبدل الارض غير الارض والسموات وبرزوا لله الواحد القهار","dt":"[48] وانتقام الله تعالى من اعدائه في يوم القيامه، يوم تبدل هذه الارض بارض اخرى بيضاء نقيه كالفضه، وكذلك تبدل السموات بغيرها، وتخرج الخلائق من قبورها احياء ظاهرين للقاء الله الواحد القهار، المتفرد بعظمته واسمائه وصفاته وافعاله وقهره لكل شيء."},{"id":"1799","s":14,"a":49,"at":"وترى المجرمين يومئذ مقرنين في الاصفاد","dt":"[49] وتبصر -ايها الرسول- المجرمين يوم القيامه مقيدين بالقيود، قد قرنت ايديهم وارجلهم بالسلاسل، وهم في ذل وهوان."},{"id":"1800","s":14,"a":50,"at":"سرابيلهم من قطران وتغشى وجوههم النار","dt":"[50] ثيابهم من القطران الشديد الاشتعال، وتلفح وجوههم النار فتحرقها."},{"id":"1801","s":14,"a":51,"at":"ليجزي الله كل نفس ما كسبت ان الله سريع الحساب","dt":"[51] فعل الله ذلك بهم؛ جزاء لهم بما كسبوا من الاثام في الدنيا، والله يجازي كل انسان بما عمل من خير او شر، ان الله سريع الحساب."},{"id":"1802","s":14,"a":52,"at":"هذا بلاغ للناس ولينذروا به وليعلموا انما هو اله واحد وليذكر اولو الالباب","dt":"[52] هذا القران الذي انزلناه اليك -ايها الرسول- بلاغ واعلام للناس؛ لنصحهم وتخويفهم، ولكي يوقنوا ان الله هو الاله الواحد، فيعبدوه وحده لا شريك له، وليتعظ به اصحاب العقول السليمه."},{"id":"1803","s":15,"a":1,"at":"الر تلك ايات الكتاب وقران مبين","dt":"[1] الر سبق الكلام على الحروف المقطعه في اول سوره البقره.تلك الايات العظيمه هي ايات الكتاب العزيز المنزل على محمد -صلى الله عليه وسلم-، وهي ايات قران موضح للحقائق باحسن لفظ واوضحه وادله على المقصود. فالكتاب هو القران جمع الله له بين الاسمين."},{"id":"1804","s":15,"a":2,"at":"ربما يود الذين كفروا لو كانوا مسلمين","dt":"[2] سيتمنى الكفار حين يرون خروج عصاه المؤمنين من النار ان لو كانوا موحدين؛ ليخرجوا كما خرجوا."},{"id":"1805","s":15,"a":3,"at":"ذرهم ياكلوا ويتمتعوا ويلههم الامل فسوف يعلمون","dt":"[3] اترك -ايها الرسول- الكفار ياكلوا، ويستمتعوا بدنياهم، ويشغلهم الطمع فيها عن طاعه الله، فسوف يعلمون عاقبه امرهم الخاسره في الدنيا والاخره."},{"id":"1806","s":15,"a":4,"at":"وما اهلكنا من قريه الا ولها كتاب معلوم","dt":"[4] واذا طلبوا نزول العذاب بهم؛ تكذيبا لك -ايها الرسول- فانا لا نهلك قريه الا ولاهلاكها اجل مقدر، لا نهلكهم حتى يبلغوه مثل من سبقهم."},{"id":"1807","s":15,"a":5,"at":"ما تسبق من امه اجلها وما يستاخرون","dt":"[5] لا تتجاوز امه اجلها فتزيد عليه، ولا تتقدم عليه، فتنقص منه."},{"id":"1808","s":15,"a":6,"at":"وقالوا ياايها الذي نزل عليه الذكر انك لمجنون","dt":"[6] وقال المكذبون لمحمد -صلى الله عليه وسلم- استهزاء: يا ايها الذي نزل عليه القران انك لذاهب العقل،"},{"id":"1809","s":15,"a":7,"at":"لو ما تاتينا بالملائكه ان كنت من الصادقين","dt":"[7] هلا تاتينا بالملائكه -ان كنت صادقا-؛ لتشهد ان الله ارسلك."},{"id":"1810","s":15,"a":8,"at":"ما ننزل الملائكه الا بالحق وما كانوا اذا منظرين","dt":"[8] ورد الله عليهم: اننا لا ننزل الملائكه الا بالعذاب الذي لا امهال فيه لمن لم يؤمن، وما كانوا حين تنزل الملائكه بالعذاب بممهلين."},{"id":"1811","s":15,"a":9,"at":"انا نحن نزلنا الذكر وانا له لحافظون","dt":"[9] انا نحن نزلنا القران على النبي محمد -صلى الله عليه وسلم-، وانا نتعهد بحفظه من ان يزاد فيه او ينقص منه، او يضيع منه شيء."},{"id":"1812","s":15,"a":10,"at":"ولقد ارسلنا من قبلك في شيع الاولين","dt":"[10] ولقد ارسلنا من قبلك -ايها الرسول- رسلا في فرق الامم السابقه."},{"id":"1813","s":15,"a":11,"at":"وما ياتيهم من رسول الا كانوا به يستهزئون","dt":"[11] فما من رسول جاءهم الا كانوا منه يسخرون. فكما فعل بك هؤلاء المشركون فكذلك فعل بمن قبلك من الرسل. وفي هذا تسليه للرسول -صلى الله عليه وسلم-."},{"id":"1814","s":15,"a":12,"at":"كذلك نسلكه في قلوب المجرمين","dt":"[12] كما ادخلنا الكفر في قلوب الامم السابقه بسبب الاستهزاء بالرسل وتكذيبهم، كذلك نفعل ذلك في قلوب مشركي قومك الذين اجرموا بالكفر بالله وتكذيب رسوله"},{"id":"1815","s":15,"a":13,"at":"لا يؤمنون به وقد خلت سنه الاولين","dt":"[13] لا يصدقون بالذكر الذي انزل اليك، وقد مضت سنه الله في الامم السابقه باهلاك الكفار، وهؤلاء مثلهم، سيهلك المستمرون منهم على الكفر والتكذيب."},{"id":"1816","s":15,"a":14,"at":"ولو فتحنا عليهم بابا من السماء فظلوا فيه يعرجون","dt":"[14] ولو فتحنا على كفار «مكه» بابا من السماء فاستمروا صاعدين فيه حتى يشاهدوا ما في السماء من عجائب ملكوت الله، لما صدقوا"},{"id":"1817","s":15,"a":15,"at":"لقالوا انما سكرت ابصارنا بل نحن قوم مسحورون","dt":"[15] ولقالوا: سحرت ابصارنا، حتى راينا ما لم نر وما نحن الا مسحورون في عقولنا من محمد."},{"id":"1818","s":15,"a":16,"at":"ولقد جعلنا في السماء بروجا وزيناها للناظرين","dt":"[16] ومن ادله قدرتنا: انا جعلنا في السماء الدنيا منازل للكواكب تنزل فيها، ويستدل بذلك على الطرقات والاوقات والخصب والجدب، وزينا هذه السماء بالنجوم لمن ينظرون اليها، ويتاملون فيعتبرون."},{"id":"1819","s":15,"a":17,"at":"وحفظناها من كل شيطان رجيم","dt":"[17] وحفظنا السماء من كل شيطان مرجوم مطرود من رحمه الله؛ كي لا يصل اليها."},{"id":"1820","s":15,"a":18,"at":"الا من استرق السمع فاتبعه شهاب مبين","dt":"[18] الا من اختلس السمع من كلام اهل الملا الاعلى في بعض الاوقات، فادركه ولحقه كوكب مضيء يحرقه. وقد يلقي الشيطان الى وليه بعض ما استرقه قبل ان يحرقه الشهاب."},{"id":"1821","s":15,"a":19,"at":"والارض مددناها والقينا فيها رواسي وانبتنا فيها من كل شيء موزون","dt":"[19] والارض مددناها متسعه، والقينا فيها جبالا تثبتها، وانبتنا فيها من كل انواع النبات ما هو مقدر معلوم مما يحتاج اليه العباد."},{"id":"1822","s":15,"a":20,"at":"وجعلنا لكم فيها معايش ومن لستم له برازقين","dt":"[20] وجعلنا لكم فيها ما به تعيشون من الحرث، ومن الماشيه، ومن انواع المكاسب وغيرها، وخلقنا لكم من الذريه والخدم والدواب ما تنتفعون به، وليس رزقهم عليكم، وانما هو على الله رب العالمين تفضلا منه وتكرما."},{"id":"1823","s":15,"a":21,"at":"وان من شيء الا عندنا خزائنه وما ننزله الا بقدر معلوم","dt":"[21] وما من شيء من منافع العباد الا عندنا خزائنه من جميع الصنوف، وما ننزله الا بمقدار محدد كما نشاء وكما نريد، فالخزائن بيد الله يعطي من يشاء ويمنع من يشاء، بحسب رحمته الواسعه، وحكمته البالغه."},{"id":"1824","s":15,"a":22,"at":"وارسلنا الرياح لواقح فانزلنا من السماء ماء فاسقيناكموه وما انتم له بخازنين","dt":"[22] وارسلنا الرياح وسخرناها تلقح السحاب، فيدر بالماء ويمطر، وتلقح الشجر فيتفتح عن اوراقه واكمامه، وتحمل المطر والخير والنفع، فانزلنا من السحاب ماء اعددناه لشرابكم وارضكم ومواشيكم، وما انتم بقادرين على خزنه وادخاره، ولكن نحفظه لكم رحمه بكم، واحسانا اليكم."},{"id":"1825","s":15,"a":23,"at":"وانا لنحن نحيي ونميت ونحن الوارثون","dt":"[23] وانا لنحن نحيي من كان ميتا بخلقه من العدم، ونميت من كان حيا بعد انقضاء اجله، ونحن الوارثون الارض ومن عليها."},{"id":"1826","s":15,"a":24,"at":"ولقد علمنا المستقدمين منكم ولقد علمنا المستاخرين","dt":"[24] ولقد علمنا من هلك منكم من لدن ادم، ومن هو حي، ومن سياتي الى يوم القيامه."},{"id":"1827","s":15,"a":25,"at":"وان ربك هو يحشرهم انه حكيم عليم","dt":"[25] وان ربك هو يجمعهم للحساب والجزاء، انه حكيم في تدبيره، عليم لا يخفى عليه شيء."},{"id":"1828","s":15,"a":26,"at":"ولقد خلقنا الانسان من صلصال من حما مسنون","dt":"[26] ولقد خلقنا ادم من طين يابس اذا نقر عليه سمع له صوت، وهذا الطين اليابس من طين اسود متغير لونه وريحه؛ من طول مكثه."},{"id":"1829","s":15,"a":27,"at":"والجان خلقناه من قبل من نار السموم","dt":"[27] وخلقنا ابا الجن، وهو ابليس من قبل خلق ادم من نار شديده الحراره لا دخان لها."},{"id":"1830","s":15,"a":28,"at":"واذ قال ربك للملائكه اني خالق بشرا من صلصال من حما مسنون","dt":"[28] واذكر -ايها الرسول- حين قال ربك للملائكه: اني خالق انسانا من طين يابس، وهذا الطين اليابس من طين اسود متغير اللون."},{"id":"1831","s":15,"a":29,"at":"فاذا سويته ونفخت فيه من روحي فقعوا له ساجدين","dt":"[29] فاذا سويته واكملت صورته ونفخت فيه الروح، فخروا له ساجدين سجود تحيه وتكريم، لا سجود عباده."},{"id":"1832","s":15,"a":30,"at":"فسجد الملائكه كلهم اجمعون","dt":"[30] فسجد الملائكه كلهم اجمعون كما امرهم ربهم، لم يمتنع منهم احد."},{"id":"1833","s":15,"a":31,"at":"الا ابليس ابى ان يكون مع الساجدين","dt":"[31] لكن ابليس امتنع ان يسجد لادم مع الملائكه الساجدين."},{"id":"1834","s":15,"a":32,"at":"قال ياابليس ما لك الا تكون مع الساجدين","dt":"[32] قال الله لابليس: ما لك الا تسجد مع الملائكه؟"},{"id":"1835","s":15,"a":33,"at":"قال لم اكن لاسجد لبشر خلقته من صلصال من حما مسنون","dt":"[33] قال ابليس مظهرا كبره وحسده: لا يليق بي ان اسجد لانسان اوجدته من طين يابس كان طينا اسود متغيرا."},{"id":"1836","s":15,"a":34,"at":"قال فاخرج منها فانك رجيم","dt":"[34] قال الله تعالى له: فاخرج من الجنه، فانك مطرود من كل خير"},{"id":"1837","s":15,"a":35,"at":"وان عليك اللعنه الى يوم الدين","dt":"[35] وان عليك اللعنه والبعد من رحمتي الى يوم يبعث الناس للحساب والجزاء."},{"id":"1838","s":15,"a":36,"at":"قال رب فانظرني الى يوم يبعثون","dt":"[36] قال ابليس: رب اخرني في الدنيا الى اليوم الذي تبعث فيه عبادك، وهو يوم القيامه."},{"id":"1839","s":15,"a":37,"at":"قال فانك من المنظرين","dt":"[37] قال الله له: فانك ممن اخرت هلاكهم"},{"id":"1840","s":15,"a":38,"at":"الى يوم الوقت المعلوم","dt":"[38] الى اليوم الذي يموت فيه كل الخلق بعد النفخه الاولى، لا الى يوم البعث، وانما اجيب الى ذلك؛ استدراجا له وامهالا، وفتنه للثقلين."},{"id":"1841","s":15,"a":39,"at":"قال رب بما اغويتني لازينن لهم في الارض ولاغوينهم اجمعين","dt":"[39] قال ابليس: رب بسبب ما اغويتني واضللتني لاحسنن لذريه ادم معاصيك في الارض، ولاضلنهم اجمعين عن طريق الهدى"},{"id":"1842","s":15,"a":40,"at":"الا عبادك منهم المخلصين","dt":"[40] الا عبادك الذين هديتهم فاخلصتهم لطاعتك وطهرتهم من كل ما ينافي ذلك."},{"id":"1843","s":15,"a":41,"at":"قال هذا صراط علي مستقيم","dt":"[41] قال الله: هذا طريق مستقيم معتدل موصل الي والى دار كرامتي."},{"id":"1844","s":15,"a":42,"at":"ان عبادي ليس لك عليهم سلطان الا من اتبعك من الغاوين","dt":"[42] ان عبادي الذين اخلصوا لي لا اجعل لك سلطانا على قلوبهم تضلهم به عن الصراط المستقيم، لكن سلطانك على من اتبعك من الضالين المشركين الذين رضوا بولايتك وطاعتك بدلا من طاعتي."},{"id":"1845","s":15,"a":43,"at":"وان جهنم لموعدهم اجمعين","dt":"[43] وان النار الشديده لموعد ابليس واتباعه اجمعين"},{"id":"1846","s":15,"a":44,"at":"لها سبعه ابواب لكل باب منهم جزء مقسوم","dt":"[44] لها سبعه ابواب كل باب اسفل من الاخر، لكل باب من اتباع ابليس قسم ونصيب بحسب اعمالهم."},{"id":"1847","s":15,"a":45,"at":"ان المتقين في جنات وعيون","dt":"[45] ان الذين اتقوا الله بامتثال ما امر واجتناب ما نهى في بساتين وانهار جاريه"},{"id":"1848","s":15,"a":46,"at":"ادخلوها بسلام امنين","dt":"[46] يقال لهم: ادخلوا هذه الجنات سالمين من كل سوء امنين من كل عذاب"},{"id":"1849","s":15,"a":47,"at":"ونزعنا ما في صدورهم من غل اخوانا على سرر متقابلين","dt":"[47] ونزعنا ما في قلوبهم من حقد وعداوه، يعيشون في الجنه اخوانا متحابين، يجلسون على اسره عظيمه، تتقابل وجوههم تواصلا وتحاببا"},{"id":"1850","s":15,"a":48,"at":"لا يمسهم فيها نصب وما هم منها بمخرجين","dt":"[48] لا يصيبهم فيها تعب ولا اعياء، وهم باقون فيها ابدا."},{"id":"1851","s":15,"a":49,"at":"نبئ عبادي اني انا الغفور الرحيم","dt":"[49] اخبر -ايها الرسول- عبادي اني انا الغفور للمؤمنين التائبين، الرحيم بهم"},{"id":"1852","s":15,"a":50,"at":"وان عذابي هو العذاب الاليم","dt":"[50] وان عذابي هو العذاب المؤلم الموجع لغير التائبين."},{"id":"1853","s":15,"a":51,"at":"ونبئهم عن ضيف ابراهيم","dt":"[51] واخبرهم -ايها الرسول- عن ضيوف ابراهيم من الملائكه الذين بشروه بالولد، وبهلاك قوم لوط."},{"id":"1854","s":15,"a":52,"at":"اذ دخلوا عليه فقالوا سلاما قال انا منكم وجلون","dt":"[52] حين دخلوا عليه فقالوا: سلاما؛ فرد عليهم السلام، ثم قدم لهم الطعام فلم ياكلوا، قال: انا منكم فزعون."},{"id":"1855","s":15,"a":53,"at":"قالوا لا توجل انا نبشرك بغلام عليم","dt":"[53] قالت الملائكه له: لا تفزع انا جئنا نبشرك بولد كثير العلم بالدين، هو اسحاق."},{"id":"1856","s":15,"a":54,"at":"قال ابشرتموني على ان مسني الكبر فبم تبشرون","dt":"[54] قال ابراهيم متعجبا: ابشرتموني بالولد، وانا كبير وزوجتي كذلك، فباي اعجوبه تبشرونني؟"},{"id":"1857","s":15,"a":55,"at":"قالوا بشرناك بالحق فلا تكن من القانطين","dt":"[55] قالوا: بشرناك بالحق الذي اعلمنا به الله، فلا تكن من اليائسين ان يولد لك."},{"id":"1858","s":15,"a":56,"at":"قال ومن يقنط من رحمه ربه الا الضالون","dt":"[56] قال: لا ييئس من رحمه ربه الا الخاطئون المنصرفون عن طريق الحق"},{"id":"1859","s":15,"a":57,"at":"قال فما خطبكم ايها المرسلون","dt":"[57] قال: فما الامر الخطير الذي جئتم من اجله -ايها المرسلون- من عند الله؟"},{"id":"1860","s":15,"a":58,"at":"قالوا انا ارسلنا الى قوم مجرمين","dt":"[58] قالوا: ان الله ارسلنا لاهلاك قوم لوط المشركين الضالين"},{"id":"1861","s":15,"a":59,"at":"الا ال لوط انا لمنجوهم اجمعين","dt":"[59] الا لوطا واهله المؤمنين به، فلن نهلكهم وسننجيهم اجمعين"},{"id":"1862","s":15,"a":60,"at":"الا امراته قدرنا انها لمن الغابرين","dt":"[60] لكن زوجته الكافره قضينا بامر الله باهلاكها مع الباقين في العذاب."},{"id":"1863","s":15,"a":61,"at":"فلما جاء ال لوط المرسلون","dt":"[61] فلما وصل الملائكه المرسلون الى لوط"},{"id":"1864","s":15,"a":62,"at":"قال انكم قوم منكرون","dt":"[62] قال لهم: انكم قوم غير معروفين لي."},{"id":"1865","s":15,"a":63,"at":"قالوا بل جئناك بما كانوا فيه يمترون","dt":"[63] قالوا: لا تخف، فانا جئنا بالعذاب الذي كان يشك فيه قومك ولا يصدقون"},{"id":"1866","s":15,"a":64,"at":"واتيناك بالحق وانا لصادقون","dt":"[64] وجئناك بالحق من عند الله، وانا لصادقون"},{"id":"1867","s":15,"a":65,"at":"فاسر باهلك بقطع من الليل واتبع ادبارهم ولا يلتفت منكم احد وامضوا حيث تؤمرون","dt":"[65] فاخرج من بينهم ومعك اهلك المؤمنون، بعد مرور جزء من الليل، وسر انت وراءهم؛ لئلا يتخلف منهم احد فيناله العذاب، واحذروا ان يلتفت منكم احد وراءه؛ لئلا يرى العذاب فيصيبه كذلك، واسرعوا الى حيث امركم الله؛ لتكونوا في مكان امين."},{"id":"1868","s":15,"a":66,"at":"وقضينا اليه ذلك الامر ان دابر هؤلاء مقطوع مصبحين","dt":"[66] واوحينا الى لوط ان قومك مستاصلون بالهلاك عن اخرهم عند طلوع الصبح."},{"id":"1869","s":15,"a":67,"at":"وجاء اهل المدينه يستبشرون","dt":"[67] وجاء اهل مدينه لوط الى لوط حين علموا بمن عنده من الضيوف، وهم فرحون يستبشرون بضيوفه؛ لياخذوهم ويفعلوا بهم الفاحشه."},{"id":"1870","s":15,"a":68,"at":"قال ان هؤلاء ضيفي فلا تفضحون","dt":"[68] قال لهم لوط: ان هؤلاء ضيفي وهم في حمايتي فلا تفضحوني"},{"id":"1871","s":15,"a":69,"at":"واتقوا الله ولا تخزون","dt":"[69] وخافوا عقاب الله، ولا تتعرضوا لهم، فتوقعوني في الذل والهوان بايذائكم لضيوفي."},{"id":"1872","s":15,"a":70,"at":"قالوا او لم ننهك عن العالمين","dt":"[70] قال قومه: اولم ننهك ان تضيف احدا من العالمين (وكانوا يقطعون السبيل على المسافرين)؛ لانا نريد فعل الفاحشه بهم؟"},{"id":"1873","s":15,"a":71,"at":"قال هؤلاء بناتي ان كنتم فاعلين","dt":"[71] قال لوط لهم: هؤلاء نساؤكم بناتي فتزوجوهن ان كنتم تريدون قضاء وطركم، وسماهن بناته؛ لان نبي الامه بمنزله الاب لهم، ولا تفعلوا ما حرم الله عليكم من اتيان الرجال."},{"id":"1874","s":15,"a":72,"at":"لعمرك انهم لفي سكرتهم يعمهون","dt":"[72] يقسم الخالق بمن يشاء وبما يشاء، اما المخلوق فلا يجوز له القسم الا بالله، وقد اقسم الله تعالى بحياه محمد -صلى الله عليه وسلم- تشريفا له. ان قوم لوط لفي غفله شديده يترددون ويتمادون"},{"id":"1875","s":15,"a":73,"at":"فاخذتهم الصيحه مشرقين","dt":"[73] حتى حلت بهم صاعقه العذاب وقت شروق الشمس."},{"id":"1876","s":15,"a":74,"at":"فجعلنا عاليها سافلها وامطرنا عليهم حجاره من سجيل","dt":"[74] فقلبنا قراهم فجعلنا عاليها سافلها، وامطرنا عليهم حجاره من طين متصلب متين."},{"id":"1877","s":15,"a":75,"at":"ان في ذلك لايات للمتوسمين","dt":"[75] ان فيما اصابهم لعظات للناظرين المعتبرين"},{"id":"1878","s":15,"a":76,"at":"وانها لبسبيل مقيم","dt":"[76] وان قراهم لفي طريق ثابت يراها المسافرون المارون بها.."},{"id":"1879","s":15,"a":77,"at":"ان في ذلك لايه للمؤمنين","dt":"[77] ان في اهلاكنا لهم لدلاله بينه للمصدقين العاملين بشرع الله."},{"id":"1880","s":15,"a":78,"at":"وان كان اصحاب الايكه لظالمين","dt":"[78] وقد كان اصحاب المدينه الملتفه الشجر -وهم قوم شعيب- ظالمين لانفسهم لكفرهم بالله ورسولهم الكريم."},{"id":"1881","s":15,"a":79,"at":"فانتقمنا منهم وانهما لبامام مبين","dt":"[79] فانتقمنا منهم بالرجفه وعذاب يوم الظله، وان مساكن قوم لوط وشعيب لفي طريق واضح يمر بهما الناس في سفرهم فيعتبرون."},{"id":"1882","s":15,"a":80,"at":"ولقد كذب اصحاب الحجر المرسلين","dt":"[80] ولقد كذب سكان «وادي الحجر» صالحا عليه السلام، وهم ثمود فكانوا بذلك مكذبين لكل المرسلين؛ لان من كذب نبيا فقد كذب الانبياء كلهم؛ لانهم على دين واحد."},{"id":"1883","s":15,"a":81,"at":"واتيناهم اياتنا فكانوا عنها معرضين","dt":"[81] واتينا قوم صالح اياتنا الداله على صحه ما جاءهم به صالح من الحق، ومن جملتها الناقه، فلم يعتبروا بها، وكانوا عنها مبتعدين معرضين."},{"id":"1884","s":15,"a":82,"at":"وكانوا ينحتون من الجبال بيوتا امنين","dt":"[82] وكانوا ينحتون الجبال، فيتخذون منها بيوتا، وهم امنون من ان تسقط عليهم او تخرب."},{"id":"1885","s":15,"a":83,"at":"فاخذتهم الصيحه مصبحين","dt":"[83] فاخذتهم صاعقه العذاب وقت الصباح مبكرين."},{"id":"1886","s":15,"a":84,"at":"فما اغنى عنهم ما كانوا يكسبون","dt":"[84] فما دفع عنهم عذاب الله الاموال والحصون في الجبال، ولا ما اعطوه من قوه وجاه."},{"id":"1887","s":15,"a":85,"at":"وما خلقنا السموات والارض وما بينهما الا بالحق وان الساعه لاتيه فاصفح الصفح الجميل","dt":"[85] وما خلقنا السموات والارض وما بينهما الا بالحق، دالتين على كمال خالقهما واقتداره، وانه الذي لا تنبغي العباده الا له وحده لا شريك له. وان الساعه التي تقوم فيها القيامه لاتيه لا محاله؛ لتوفى كل نفس بما عملت، فاعف -ايها الرسول- عفوا حسنا عن المشركين، واعرض عنهم وتجاوز عما يفعلونه."},{"id":"1888","s":15,"a":86,"at":"ان ربك هو الخلاق العليم","dt":"[86] ان ربك هو الخلاق لكل شيء، العليم به، فلا يعجزه شيء في الارض ولا في السماء، ولا يخفى عليه."},{"id":"1889","s":15,"a":87,"at":"ولقد اتيناك سبعا من المثاني والقران العظيم","dt":"[87] ولقد اتيناك -ايها النبي- فاتحه القران، وهي سبع ايات تكرر في كل صلاه، واتيناك القران العظيم."},{"id":"1890","s":15,"a":88,"at":"لا تمدن عينيك الى ما متعنا به ازواجا منهم ولا تحزن عليهم واخفض جناحك للمؤمنين","dt":"[88] لا تنظر بعينيك وتتمن ما متعنا به اصنافا من الكفار من متع الدنيا، ولا تحزن على كفرهم، وتواضع للمؤمنين بالله ورسوله."},{"id":"1891","s":15,"a":89,"at":"وقل اني انا النذير المبين","dt":"[89] وقل: اني انا المنذر الموضح لما يهتدي به الناس الى الايمان بالله رب العالمين، ومنذركم ان يصيبكم العذاب."},{"id":"1892","s":15,"a":90,"at":"كما انزلنا على المقتسمين","dt":"[90] كما انزله الله على الذين قسموا القران، فامنوا ببعضه، وكفروا ببعضه الاخر من اليهود والنصارى وكفار قريش."},{"id":"1893","s":15,"a":91,"at":"الذين جعلوا القران عضين","dt":"[91] وهم الذين جعلوا القران اقساما واجزاء، فمنهم من يقول: سحر، ومنهم من يقول كهانه، ومنهم من يقول غير ذلك، يصرفونه بحسب اهوائهم؛ ليصدوا الناس عن الهدى."},{"id":"1894","s":15,"a":92,"at":"فوربك لنسالنهم اجمعين","dt":"[92] فوربك لنحاسبنهم يوم القيامه ولنجزينهم اجمعين"},{"id":"1895","s":15,"a":93,"at":"عما كانوا يعملون","dt":"[93] عن تقسيمهم للقران بافتراءاتهم، وتحريفه وتبديله، وغير ذلك مما كانوا يعملونه من عباده الاوثان، ومن المعاصي والاثام. وفي هذا ترهيب وزجر لهم من الاقامه على هذه الافعال القبيحه."},{"id":"1896","s":15,"a":94,"at":"فاصدع بما تؤمر واعرض عن المشركين","dt":"[94] فاجهر بدعوه الحق التي امرك الله بها، ولا تبال بالمشركين، فقد براك الله مما يقولون."},{"id":"1897","s":15,"a":95,"at":"انا كفيناك المستهزئين","dt":"[95] انا كفيناك المستهزئين الساخرين من زعماء قريش"},{"id":"1898","s":15,"a":96,"at":"الذين يجعلون مع الله الها اخر فسوف يعلمون","dt":"[96] الذين اتخذوا شريكا مع الله من الاوثان وغيرها، فسوف يعلمون عاقبه عملهم في الدنيا والاخره."},{"id":"1899","s":15,"a":97,"at":"ولقد نعلم انك يضيق صدرك بما يقولون","dt":"[97] ولقد نعلم بانقباض صدرك -ايها الرسول-؛ بسبب ما يقوله المشركون فيك وفي دعوتك."},{"id":"1900","s":15,"a":98,"at":"فسبح بحمد ربك وكن من الساجدين","dt":"[98] فافزع الى ربك عند ضيق صدرك، وسبح بحمده شاكرا له مثنيا عليه، وكن من المصلين لله العابدين له، فان ذلك يكفيك ما اهمك."},{"id":"1901","s":15,"a":99,"at":"واعبد ربك حتى ياتيك اليقين","dt":"[99] واستمر في عباده ربك مده حياتك حتى ياتيك اليقين، وهو الموت.وامتثل رسول الله -صلى الله عليه وسلم- امر ربه، فلم يزل دائبا في عباده الله، حتى اتاه اليقين من ربه."},{"id":"1902","s":16,"a":1,"at":"اتى امر الله فلا تستعجلوه سبحانه وتعالى عما يشركون","dt":"[1] قرب قيام الساعه وقضاء الله بعذابكم -ايها الكفار- فلا تستعجلوا العذاب استهزاء بوعيد الرسول لكم. تنزه الله سبحانه وتعالى عن الشرك والشركاء."},{"id":"1903","s":16,"a":2,"at":"ينزل الملائكه بالروح من امره على من يشاء من عباده ان انذروا انه لا اله الا انا فاتقون","dt":"[2] ينزل الله الملائكه بالوحي من امره على من يشاء من عباده المرسلين: بان خوفوا الناس من الشرك، وانه لا معبود بحق الا انا، فاتقون باداء فرائضي وافرادي بالعباده والاخلاص."},{"id":"1904","s":16,"a":3,"at":"خلق السموات والارض بالحق تعالى عما يشركون","dt":"[3] خلق الله السموات والارض بالحق؛ ليستدل بهما العباد على عظمه خالقهما، وانه وحده المستحق للعباده، تنزه -سبحانه- وتعاظم عن شركهم."},{"id":"1905","s":16,"a":4,"at":"خلق الانسان من نطفه فاذا هو خصيم مبين","dt":"[4] خلق الانسان من ماء مهين فاذا به يقوى ويغتر، فيصبح شديد الخصومه والجدال لربه في انكار البعث، وغير ذلك، كقوله: من يحي العظم وهي رميم، ونسي الله الذي خلقه من العدم."},{"id":"1906","s":16,"a":5,"at":"والانعام خلقها لكم فيها دفء ومنافع ومنها تاكلون","dt":"[5] والانعام من الابل والبقر والغنم خلقها الله لكم -ايها الناس- وجعل في اصوافها واوبارها واشعارها الدفء، ومنافع اخر في البانها وجلودها وركوبها، ومنها ما تاكلون."},{"id":"1907","s":16,"a":6,"at":"ولكم فيها جمال حين تريحون وحين تسرحون","dt":"[6] ولكم فيها زينه تدخل السرور عليكم عندما تردونها الى منازلها في المساء، وعندما تخرجونها للمرعى في الصباح."},{"id":"1908","s":16,"a":7,"at":"وتحمل اثقالكم الى بلد لم تكونوا بالغيه الا بشق الانفس ان ربكم لرءوف رحيم","dt":"[7] وتحمل هذه الانعام ما ثقل من امتعتكم الى بلد بعيد، لم تكونوا مستطيعين الوصول اليه الا بجهد شديد من انفسكم ومشقه عظيمه، ان ربكم ليرحمكم رحمه واسعه في عاجلكم واجلكم؛ حيث سخر لكم ما تحتاجون اليه، فله الحمد وله الشكر."},{"id":"1909","s":16,"a":8,"at":"والخيل والبغال والحمير لتركبوها وزينه ويخلق ما لا تعلمون","dt":"[8] وخلق لكم الخيل والبغال والحمير؛ لكي تركبوها، ولتكون جمالا لكم ومنظرا حسنا، ويخلق لكم من وسائل الركوب وغيرها ما لا علم لكم به؛ لتزدادوا ايمانا به وشكرا له."},{"id":"1910","s":16,"a":9,"at":"وعلى الله قصد السبيل ومنها جائر ولو شاء لهداكم اجمعين","dt":"[9] وعلى الله بيان الطريق المستقيم لهدايتكم، وهو الاسلام، ومن الطرق ما هو مائل لا يوصل الى الهدايه، وهو كل ما خالف الاسلام من الملل والنحل. ولو شاء الله هدايتكم لهداكم جميعا للايمان."},{"id":"1911","s":16,"a":10,"at":"هو الذي انزل من السماء ماء لكم منه شراب ومنه شجر فيه تسيمون","dt":"[10] هو الذي انزل لكم من السحاب مطرا، فجعل لكم منه ماء تشربونه، واخرج لكم به شجرا ترعون فيه دوابكم، ويعود عليكم درها ونفعها."},{"id":"1912","s":16,"a":11,"at":"ينبت لكم به الزرع والزيتون والنخيل والاعناب ومن كل الثمرات ان في ذلك لايه لقوم يتفكرون","dt":"[11] يخرج لكم من الارض بهذا الماء الواحد الزروع المختلفه، ويخرج به الزيتون والنخيل والاعناب، ويخرج به كل انواع الثمار والفواكه. ان في ذلك الاخراج لدلاله واضحه لقوم يتاملون، فيعتبرون."},{"id":"1913","s":16,"a":12,"at":"وسخر لكم اليل والنهار والشمس والقمر والنجوم مسخرات بامره ان في ذلك لايات لقوم يعقلون","dt":"[12] وسخر لكم الليل لراحتكم، والنهار لمعاشكم، وسخر لكم الشمس ضياء، والقمر نورا ولمعرفه السنين والحساب، وغير ذلك من المنافع، والنجوم في السماء مذللات لكم بامر الله لمعرفه الاوقات، ولمعرفه وقت نضج الثمار والزروع، والاهتداء بها في الظلمات. ان في ذلك التسخير لدلائل واضحه لقوم يعقلون عن الله حججه وبراهينه."},{"id":"1914","s":16,"a":13,"at":"وما ذرا لكم في الارض مختلفا الوانه ان في ذلك لايه لقوم يذكرون","dt":"[13] وسخر ما خلقه لكم في الارض من الدواب والثمار والمعادن، وغير ذلك مما تختلف الوانه ومنافعه. ان في ذلك الخلق واختلاف الالوان والمنافع لعبره لقوم يتعظون، ويعلمون ان في تسخير هذه الاشياء علامات على وحدانيه الله تعالى وافراده بالعباده."},{"id":"1915","s":16,"a":14,"at":"وهو الذي سخر البحر لتاكلوا منه لحما طريا وتستخرجوا منه حليه تلبسونها وترى الفلك مواخر فيه ولتبتغوا من فضله ولعلكم تشكرون","dt":"[14] وهو الذي سخر لكم البحر؛ لتاكلوا مما تصطادون من سمكه لحما طريا، وتستخرجوا منه زينه تلبسونها كاللؤلؤ والمرجان، وترى السفن العظيمه تشق وجه الماء تذهب وتجيء، وتركبونها؛ لتطلبوا رزق الله بالتجاره والربح فيها، ولعلكم تشكرون لله تعالى على عظيم انعامه عليكم، فلا تعبدون غيره."},{"id":"1916","s":16,"a":15,"at":"والقى في الارض رواسي ان تميد بكم وانهارا وسبلا لعلكم تهتدون","dt":"[15] وارسى في الارض جبالا تثبتها حتى لا تميل بكم، وجعل فيها انهارا؛ لتشربوا منها، وجعل فيها طرقا؛ لتهتدوا بها في الوصول الى الاماكن التي تقصدونها."},{"id":"1917","s":16,"a":16,"at":"وعلامات وبالنجم هم يهتدون","dt":"[16] وجعل في الارض معالم تستدلون بها على الطرق نهارا، كما جعل النجوم للاهتداء بها ليلا."},{"id":"1918","s":16,"a":17,"at":"افمن يخلق كمن لا يخلق افلا تذكرون","dt":"[17] اتجعلون الله الذي يخلق كل هذه الاشياء وغيرها في استحقاق العباده كالالهه المزعومه التي لا تخلق شيئا؟ افلا تتذكرون عظمه الله، فتفردوه بالعباده؟"},{"id":"1919","s":16,"a":18,"at":"وان تعدوا نعمه الله لا تحصوها ان الله لغفور رحيم","dt":"[18] وان تحاولوا حصر نعم الله عليكم لا تفوا بحصرها؛ لكثرتها وتنوعها. ان الله لغفور لكم رحيم بكم؛ اذ يتجاوز عن تقصيركم في اداء شكر النعم، ولا يقطعها عنكم لتفريطكم، ولا يعاجلكم بالعقوبه."},{"id":"1920","s":16,"a":19,"at":"والله يعلم ما تسرون وما تعلنون","dt":"[19] والله سبحانه يعلم كل اعمالكم، سواء ما تخفونه منها في نفوسكم وما تظهرونه لغيركم، وسيجازيكم عليها."},{"id":"1921","s":16,"a":20,"at":"والذين يدعون من دون الله لا يخلقون شيئا وهم يخلقون","dt":"[20] والالهه التي يعبدها المشركون لا تخلق شيئا وان صغر، فهي مخلوقات صنعها الكفار بايديهم، فكيف يعبدونها؟"},{"id":"1922","s":16,"a":21,"at":"اموات غير احياء وما يشعرون ايان يبعثون","dt":"[21] هم جميعا جمادات لا حياه فيها ولا تشعر بالوقت الذي يبعث الله فيه عابديها، وهي معهم ليلقى بهم جميعا في النار يوم القيامه."},{"id":"1923","s":16,"a":22,"at":"الهكم اله واحد فالذين لا يؤمنون بالاخره قلوبهم منكره وهم مستكبرون","dt":"[22] الهكم المستحق وحده للعباده هو الله الاله الواحد، فالذين لا يؤمنون بالبعث قلوبهم جاحده وحدانيته سبحانه؛ لعدم خوفهم من عقابه، فهم متكبرون عن قبول الحق، وعباده الله وحده."},{"id":"1924","s":16,"a":23,"at":"لا جرم ان الله يعلم ما يسرون وما يعلنون انه لا يحب المستكبرين","dt":"[23] حقا ان الله يعلم ما يخفونه من عقائد واقوال وافعال، وما يظهرونه منها، وسيجازيهم على ذلك، انه عز وجل لا يحب المستكبرين عن عبادته والانقياد له، وسيجازيهم على ذلك."},{"id":"1925","s":16,"a":24,"at":"واذا قيل لهم ماذا انزل ربكم قالوا اساطير الاولين","dt":"[24] واذا سئل هؤلاء المشركون عما نزل على النبي محمد -صلى الله عليه وسلم- قالوا كذبا وزورا: ما اتى الا بقصص السابقين واباطيلهم."},{"id":"1926","s":16,"a":25,"at":"ليحملوا اوزارهم كامله يوم القيامه ومن اوزار الذين يضلونهم بغير علم الا ساء ما يزرون","dt":"[25] ستكون عاقبتهم ان يحملوا اثامهم كامله يوم القيامه -لا يغفر لهم منها شيء- ويحملوا من اثام الذين كذبوا عليهم؛ ليبعدوهم عن الاسلام من غير نقص من اثامهم. الا قبح ما يحملونه من اثام."},{"id":"1927","s":16,"a":26,"at":"قد مكر الذين من قبلهم فاتى الله بنيانهم من القواعد فخر عليهم السقف من فوقهم واتاهم العذاب من حيث لا يشعرون","dt":"[26] قد دبر الكفار من قبل هؤلاء المشركين المكايد لرسلهم، وما جاؤوا به من دعوه الحق، فاتى امر الله بنيانهم من اساسه وقاعدته، فسقط عليهم السقف من فوقهم، واتاهم الهلاك من مامنهم، من حيث لا يحتسبون ولا يتوقعون انه ياتيهم منه."},{"id":"1928","s":16,"a":27,"at":"ثم يوم القيامه يخزيهم ويقول اين شركائي الذين كنتم تشاقون فيهم قال الذين اوتوا العلم ان الخزي اليوم والسوء على الكافرين","dt":"[27] ثم يوم القيامه يفضحهم الله بالعذاب ويذلهم به، ويقول: اين شركائي من الالهه التي عبدتموها من دوني؛ ليدفعوا عنكم العذاب، وقد كنتم تحاربون الانبياء والمؤمنين وتعادونهم لاجلهم؟قال العلماء الربانيون: ان الذل في هذا اليوم والعذاب على الكافرين بالله ورسله"},{"id":"1929","s":16,"a":28,"at":"الذين تتوفاهم الملائكه ظالمي انفسهم فالقوا السلم ما كنا نعمل من سوء بلى ان الله عليم بما كنتم تعملون","dt":"[28] الذين تقبض الملائكه ارواحهم في حال ظلمهم لانفسهم بالكفر، فاستسلموا لامر الله حين راوا الموت، وانكروا ما كانوا يعبدون من دون الله، وقالوا: ما كنا نعمل شيئا من المعاصي، فيقال لهم: كذبتم، قد كنتم تعملونها، ان الله عليم باعمالكم كلها، وسيجازيكم عليها."},{"id":"1930","s":16,"a":29,"at":"فادخلوا ابواب جهنم خالدين فيها فلبئس مثوى المتكبرين","dt":"[29] فادخلوا ابواب جهنم، لا تخرجون منها ابدا، فلبئست مقرا للذين تكبروا عن الايمان بالله وعن عبادته وحده وطاعته."},{"id":"1931","s":16,"a":30,"at":"وقيل للذين اتقوا ماذا انزل ربكم قالوا خيرا للذين احسنوا في هذه الدنيا حسنه ولدار الاخره خير ولنعم دار المتقين","dt":"[30] واذا قيل للمؤمنين الخائفين من الله: ما الذي انزل الله على النبي محمد -صلى الله عليه وسلم-؟ قالوا: انزل الله عليه الخير والهدى. للذين امنوا بالله ورسوله في هذه الدنيا، ودعوا عباد الله الى الايمان والعمل الصالح، مكرمه كبيره من النصر لهم في الدنيا، وسعه الرزق، ولدار الاخره لهم خير واعظم مما اوتوه في الدنيا، ولنعم دار الذين خافوا الله في الدنيا فاتقوا عقابه باداء فرائضه واجتناب نواهيه دار الاخره."},{"id":"1932","s":16,"a":31,"at":"جنات عدن يدخلونها تجري من تحتها الانهار لهم فيها ما يشاءون كذلك يجزي الله المتقين","dt":"[31] جنات اقامه لهم، يستقرون فيها، لا يخرجون منها ابدا، تجري من تحت اشجارها وقصورها الانهار، لهم فيها كل ما تشتهيه انفسهم، بمثل هذا الجزاء الطيب يجزي الله اهل خشيته وتقواه"},{"id":"1933","s":16,"a":32,"at":"الذين تتوفاهم الملائكه طيبين يقولون سلام عليكم ادخلوا الجنه بما كنتم تعملون","dt":"[32] الذين تقبض الملائكه ارواحهم، وقلوبهم طاهره من الكفر، تقول الملائكه لهم: سلام عليكم، تحيه خاصه لكم، وسلمتم من كل افه، ادخلوا الجنه بما كنتم تعملون من الايمان بالله والانقياد لامره."},{"id":"1934","s":16,"a":33,"at":"هل ينظرون الا ان تاتيهم الملائكه او ياتي امر ربك كذلك فعل الذين من قبلهم وما ظلمهم الله ولكن كانوا انفسهم يظلمون","dt":"[33] ما ينتظر المشركون الا ان تاتيهم الملائكه؛ لتقبض ارواحهم وهم على الكفر، او ياتي امر الله بعذاب عاجل يهلكهم، كما كذب هؤلاء كذب الكفار من قبلهم، فاهلكهم الله، وما ظلمهم الله باهلاكهم، وانزال العذاب بهم، ولكنهم هم الذين كانوا يظلمون انفسهم بما جعلهم اهلا للعذاب."},{"id":"1935","s":16,"a":34,"at":"فاصابهم سيئات ما عملوا وحاق بهم ما كانوا به يستهزئون","dt":"[34] فنزلت بهم عقوبه ذنوبهم التي عملوها، واحاط بهم العذاب الذي كانوا يسخرون منه."},{"id":"1936","s":16,"a":35,"at":"وقال الذين اشركوا لو شاء الله ما عبدنا من دونه من شيء نحن ولا اباؤنا ولا حرمنا من دونه من شيء كذلك فعل الذين من قبلهم فهل على الرسل الا البلاغ المبين","dt":"[35] وقال المشركون: لو شاء الله ان نعبده وحده ما عبدنا احدا غيره، لا نحن ولا اباؤنا من قبلنا، ولا حرمنا شيئا لم يحرمه، بمثل هذا الاحتجاج الباطل احتج الكفار السابقون، وهم كاذبون؛ فان الله امرهم ونهاهم ومكنهم من القيام بما كلفهم به، وجعل لهم قوه ومشيئه تصدر عنها افعالهم، فاحتجاجهم بالقضاء والقدر من ابطل الباطل من بعد انذار الرسل لهم، فليس على الرسل المنذرين لهم الا التبليغ الواضح لما كلفوا به."},{"id":"1937","s":16,"a":36,"at":"ولقد بعثنا في كل امه رسولا ان اعبدوا الله واجتنبوا الطاغوت فمنهم من هدى الله ومنهم من حقت عليه الضلاله فسيروا في الارض فانظروا كيف كان عاقبه المكذبين","dt":"[36] ولقد بعثنا في كل امه سبقت رسولا امرا لهم بعباده الله وطاعته وحده وترك عباده غيره من الشياطين والاوثان والاموات وغير ذلك مما يتخذ من دون الله وليا، فكان منهم من هدى الله، فاتبع المرسلين، ومنهم المعاند الذي اتبع سبيل الغي، فوجبت عليه الضلاله، فلم يوفقه الله. فامشوا في الارض، وابصروا باعينكم كيف كان مال هؤلاء المكذبين، وماذا حل بهم من دمار؛ لتعتبروا؟"},{"id":"1938","s":16,"a":37,"at":"ان تحرص على هداهم فان الله لا يهدي من يضل وما لهم من ناصرين","dt":"[37] ان تبذل -ايها الرسول- اقصى جهدك لهدايه هؤلاء المشركين فاعلم ان الله لا يهدي من يضل، وليس لهم من دون الله احد ينصرهم، ويمنع عنهم عذابه."},{"id":"1939","s":16,"a":38,"at":"واقسموا بالله جهد ايمانهم لا يبعث الله من يموت بلى وعدا عليه حقا ولكن اكثر الناس لا يعلمون","dt":"[38] وحلف هؤلاء المشركون بالله ايمانا مغلظه ان الله لا يبعث من يموت بعدما بلي وتفرق، بلى سيبعثهم الله حتما، وعدا عليه حقا، ولكن اكثر الناس لا يعلمون قدره الله على البعث، فينكرونه."},{"id":"1940","s":16,"a":39,"at":"ليبين لهم الذي يختلفون فيه وليعلم الذين كفروا انهم كانوا كاذبين","dt":"[39] يبعث الله جميع العباد؛ ليبين لهم حقيقه البعث الذي اختلفوا فيه، وليعلم الكفار المنكرون له انهم على باطل، وانهم كاذبون حين حلفوا ان لا بعث."},{"id":"1941","s":16,"a":40,"at":"انما قولنا لشيء اذا اردناه ان نقول له كن فيكون","dt":"[40] ان امر البعث يسير علينا، فانا اذا اردنا شيئا فانما نقول له: «كن»، فاذا هو كائن موجود."},{"id":"1942","s":16,"a":41,"at":"والذين هاجروا في الله من بعد ما ظلموا لنبوئنهم في الدنيا حسنه ولاجر الاخره اكبر لو كانوا يعلمون","dt":"[41] والذين تركوا ديارهم من اجل الله، فهاجروا بعدما وقع عليهم الظلم، لنسكننهم في الدنيا دارا حسنه، ولاجر الاخره اكبر؛ لان ثوابهم فيها الجنه. لو كان المتخلفون عن الهجره يعلمون علم يقين ما عند الله من الاجر والثواب للمهاجرين في سبيله، ما تخلف منهم احد عن ذلك."},{"id":"1943","s":16,"a":42,"at":"الذين صبروا وعلى ربهم يتوكلون","dt":"[42] هؤلاء المهاجرون في سبيل الله هم الذين صبروا على اوامر الله وعن نواهيه وعلى اقداره المؤلمه، وعلى ربهم وحده يعتمدون، فاستحقوا هذه المنزله العظيمه."},{"id":"1944","s":16,"a":43,"at":"وما ارسلنا من قبلك الا رجالا نوحي اليهم فاسالوا اهل الذكر ان كنتم لا تعلمون","dt":"[43] وما ارسلنا في السابقين قبلك -ايها الرسول- الا رسلا من الرجال لا من الملائكه، نوحي اليهم، وان كنتم -يا مشركي قريش- لا تصدقون بذلك فاسالوا علماء اهل الكتب السابقه، يخبروكم ان الانبياء كانوا بشرا، ان كنتم لا تعلمون انهم بشر. والايه عامه في كل مساله من مسائل الدين، اذا لم يكن عند الانسان علم منها ان يسال من يعلمها من العلماء الراسخين في العلم."},{"id":"1945","s":16,"a":44,"at":"بالبينات والزبر وانزلنا اليك الذكر لتبين للناس ما نزل اليهم ولعلهم يتفكرون","dt":"[44] وارسلنا الرسل السابقين بالدلائل الواضحه وبالكتب السماويه، وانزلنا اليك -ايها الرسول- القران؛ لتوضح للناس ما خفي من معانيه واحكامه، ولكي يتدبروه ويهتدوا به."},{"id":"1946","s":16,"a":45,"at":"افامن الذين مكروا السيئات ان يخسف الله بهم الارض او ياتيهم العذاب من حيث لا يشعرون","dt":"[45] افامن الكفار المدبرون للمكايد ان يخسف الله بهم الارض كما فعل بقارون، او ياتيهم العذاب من مكان لا يحسونه ولا يتوقعونه."},{"id":"1947","s":16,"a":46,"at":"او ياخذهم في تقلبهم فما هم بمعجزين","dt":"[46] او ياخذهم العذاب، وهم يتقلبون في اسفارهم وتصرفهم؟ فما هم بسابقين الله ولا فائتيه ولا ناجين من عذابه؛ لانه القوي الذي لا يعجزه شيء."},{"id":"1948","s":16,"a":47,"at":"او ياخذهم على تخوف فان ربكم لرءوف رحيم","dt":"[47] او ياخذهم الله بنقص من الاموال والانفس والثمرات، او في حال خوفهم من اخذه لهم، فان ربكم ليرحم خلقه رحمه واسعه في عاجلهم واجلهم."},{"id":"1949","s":16,"a":48,"at":"او لم يروا الى ما خلق الله من شيء يتفيا ظلاله عن اليمين والشمائل سجدا لله وهم داخرون","dt":"[48] اعمي هؤلاء الكفار، فلم ينظروا الى ما خلق الله من شيء له ظل، كالجبال والاشجار، تميل ظلالها تاره يمينا وتاره شمالا؛ تبعا لحركه الشمس نهارا والقمر ليلا، كلها خاضعه لعظمه ربها وجلاله، وهي تحت تسخيره وتدبيره وقهره؟"},{"id":"1950","s":16,"a":49,"at":"ولله يسجد ما في السموات وما في الارض من دابه والملائكه وهم لا يستكبرون","dt":"[49] ولله وحده يسجد كل ما في السموات وما في الارض من دابه، والملائكه يسجدون لله، وهم لا يستكبرون عن عبادته. وخصهم بالذكر بعد العموم لفضلهم وشرفهم وكثره عبادتهم."},{"id":"1951","s":16,"a":50,"at":"يخافون ربهم من فوقهم ويفعلون ما يؤمرون","dt":"[50] يخاف الملائكه ربهم الذي هو فوقهم بالذات والقهر وكمال الصفات، ويفعلون ما يؤمرون به من طاعه الله. وفي الايه اثبات صفه العلو والفوقيه لله على جميع خلقه، كما يليق بجلاله وكماله."},{"id":"1952","s":16,"a":51,"at":"وقال الله لا تتخذوا الهين اثنين انما هو اله واحد فاياي فارهبون","dt":"[51] وقال الله لعباده: لا تعبدوا الهين اثنين، انما معبودكم اله واحد، فخافوني دون سواي."},{"id":"1953","s":16,"a":52,"at":"وله ما في السموات والارض وله الدين واصبا افغير الله تتقون","dt":"[52] ولله كل ما في السموات والارض خلقا وملكا وعبيدا، وله وحده العباده والطاعه والاخلاص دائما، ايليق بكم ان تخافوا غير الله وتعبدوه؟"},{"id":"1954","s":16,"a":53,"at":"وما بكم من نعمه فمن الله ثم اذا مسكم الضر فاليه تجارون","dt":"[53] وما بكم من نعمه هدايه، او صحه جسم، وسعه رزق، وولد، وغير ذلك، فمن الله وحده، فهو المنعم بها عليكم، ثم اذا نزل بكم السقم والبلاء والقحط فالى الله وحده تضجون بالدعاء."},{"id":"1955","s":16,"a":54,"at":"ثم اذا كشف الضر عنكم اذا فريق منكم بربهم يشركون","dt":"[54] ثم اذا كشف عنكم البلاء والسقم، اذا جماعه منكم بربهم المنعم عليهم بالنجاه يتخذون معه الشركاء والاولياء."},{"id":"1956","s":16,"a":55,"at":"ليكفروا بما اتيناهم فتمتعوا فسوف تعلمون","dt":"[55] ليجحدوا نعمنا عليهم، ومنها كشف البلاء عنهم، فاستمتعوا بدنياكم، ومصيرها الى الزوال، فسوف تعلمون عاقبه كفركم وعصيانكم."},{"id":"1957","s":16,"a":56,"at":"ويجعلون لما لا يعلمون نصيبا مما رزقناهم تالله لتسالن عما كنتم تفترون","dt":"[56] ومن قبيح اعمال المشركين انهم يجعلون للاصنام التي اتخذوها الهه -وهي لا تعلم شيئا ولا تنفع ولا تضر- جزءا من اموالهم التي رزقهم الله بها تقربا اليها. تالله لتسالن يوم القيامه عما كنتم تختلقونه من الكذب على الله."},{"id":"1958","s":16,"a":57,"at":"ويجعلون لله البنات سبحانه ولهم ما يشتهون","dt":"[57] ويجعل الكفار لله البنات، فيقولون: الملائكه بنات الله، تنزه الله عن قولهم، ويجعلون لانفسهم ما يحبون من البنين."},{"id":"1959","s":16,"a":58,"at":"واذا بشر احدهم بالانثى ظل وجهه مسودا وهو كظيم","dt":"[58] واذا جاء من يخبر احدهم بولاده انثى اسود وجهه؛ كراهيه لما سمع، وامتلا غما وحزنا."},{"id":"1960","s":16,"a":59,"at":"يتوارى من القوم من سوء ما بشر به ايمسكه على هون ام يدسه في التراب الا ساء ما يحكمون","dt":"[59] يستخفي من قومه كراهه ان يلقاهم متلبسا بما ساءه من الحزن والعار؛ بسبب البنت التي ولدت له، ومتحيرا في امر هذه المولوده: ايبقيها حيه على ذل وهوان، ام يدفنها حيه في التراب؟ الا بئس الحكم الذي حكموه من جعل البنات لله والذكور لهم."},{"id":"1961","s":16,"a":60,"at":"للذين لا يؤمنون بالاخره مثل السوء ولله المثل الاعلى وهو العزيز الحكيم","dt":"[60] للذين لا يؤمنون بالاخره ولا يعملون لها، الصفه القبيحه من العجز والحاجه والجهل والكفر، ولله الصفات العليا من الكمال والاستغناء عن خلقه، وهو العزيز في ملكه، الحكيم في تدبيره."},{"id":"1962","s":16,"a":61,"at":"ولو يؤاخذ الله الناس بظلمهم ما ترك عليها من دابه ولكن يؤخرهم الى اجل مسمى فاذا جاء اجلهم لا يستاخرون ساعه ولا يستقدمون","dt":"[61] ولو يؤاخذ الله الناس بكفرهم وافترائهم ما ترك على الارض من يتحرك، ولكن يبقيهم الى وقت محدد هو نهايه اجالهم، فاذا جاء اجلهم لا يتاخرون عنه وقتا يسيرا، ولا يتقدمون."},{"id":"1963","s":16,"a":62,"at":"ويجعلون لله ما يكرهون وتصف السنتهم الكذب ان لهم الحسنى لا جرم ان لهم النار وانهم مفرطون","dt":"[62] ومن قبائحهم: انهم يجعلون لله ما يكرهونه لانفسهم من البنات، وتقول السنتهم كذبا: ان لهم حسن العاقبه، حقا ان لهم النار، وانهم فيها متروكون منسيون."},{"id":"1964","s":16,"a":63,"at":"تالله لقد ارسلنا الى امم من قبلك فزين لهم الشيطان اعمالهم فهو وليهم اليوم ولهم عذاب اليم","dt":"[63] تالله لقد ارسلنا رسلا الى امم من قبلك -ايها الرسول- فحسن لهم الشيطان ما عملوه من الكفر والتكذيب وعباده غير الله، فهو متول اغواءهم في الدنيا، ولهم في الاخره عذاب اليم موجع."},{"id":"1965","s":16,"a":64,"at":"وما انزلنا عليك الكتاب الا لتبين لهم الذي اختلفوا فيه وهدى ورحمه لقوم يؤمنون","dt":"[64] وما انزلنا عليك القران -ايها الرسول- الا لتوضح للناس ما اختلفوا فيه من الدين والاحكام؛ لتقوم الحجه عليهم ببيانك الذي لا يترك للباطل مسلكا الى النفوس، ولكون القران هدى لا يترك مجالا للحيره، ورحمه للمؤمنين في اتباعهم الهدى ومجانبتهم الضلال."},{"id":"1966","s":16,"a":65,"at":"والله انزل من السماء ماء فاحيا به الارض بعد موتها ان في ذلك لايه لقوم يسمعون","dt":"[65] والله انزل من السحاب مطرا، فاخرج به النبات من الارض بعد ان كانت قاحله يابسه، ان في انزال المطر وانبات النبات لدليلا على قدره الله على البعث وعلى الوحدانيه، لقوم يسمعون، ويتدبرون، ويطيعون الله، ويتقونه."},{"id":"1967","s":16,"a":66,"at":"وان لكم في الانعام لعبره نسقيكم مما في بطونه من بين فرث ودم لبنا خالصا سائغا للشاربين","dt":"[66] وان لكم -ايها الناس- في الانعام -وهي الابل والبقر والغنم- لعظه، فقد شاهدتم اننا نسقيكم من ضروعها لبنا خارجا من بين فرث -وهو ما في الكرش- وبين دم خالصا من كل الشوائب، لذيذا لا يغص به من شربه."},{"id":"1968","s":16,"a":67,"at":"ومن ثمرات النخيل والاعناب تتخذون منه سكرا ورزقا حسنا ان في ذلك لايه لقوم يعقلون","dt":"[67] ومن نعمنا عليكم ما تاخذونه من ثمرات النخيل والاعناب، فتجعلونه خمرا مسكرا -وهذا قبل تحريمها- وطعاما طيبا . ان فيما ذكر لدليلا على قدره الله لقوم يعقلون البراهين فيعتبرون بها."},{"id":"1969","s":16,"a":68,"at":"واوحى ربك الى النحل ان اتخذي من الجبال بيوتا ومن الشجر ومما يعرشون","dt":"[68] والهم ربك -ايها الرسول- النحل بان اجعلي لك بيوتا في الجبال، وفي الشجر، وفيما يبني الناس من البيوت والسقف."},{"id":"1970","s":16,"a":69,"at":"ثم كلي من كل الثمرات فاسلكي سبل ربك ذللا يخرج من بطونها شراب مختلف الوانه فيه شفاء للناس ان في ذلك لايه لقوم يتفكرون","dt":"[69] ثم كلي من كل ثمره تشتهينها، فاسلكي طرق ربك مذلله لك؛ لطلب الرزق في الجبال وخلال الشجر، وقد جعلها سهله عليك، لا تضلي في العود اليها وان بعدت. يخرج من بطون النحل عسل مختلف الالوان من بياض وصفره وحمره وغير ذلك، فيه شفاء للناس من الامراض. ان فيما يصنعه النحل لدلاله قويه على قدره خالقها لقوم يتفكرون، فيعتبرون."},{"id":"1971","s":16,"a":70,"at":"والله خلقكم ثم يتوفاكم ومنكم من يرد الى ارذل العمر لكي لا يعلم بعد علم شيئا ان الله عليم قدير","dt":"[70] والله سبحانه وتعالى خلقكم ثم يميتكم في نهايه اعماركم، ومنكم من يصير الى اردا العمر وهو الهرم، كما كان في طفولته لا يعلم شيئا مما كان يعلمه، ان الله عليم قدير، احاط علمه وقدرته بكل شيء، فالله الذي رد الانسان الى هذه الحاله قادر على ان يميته، ثم يبعثه."},{"id":"1972","s":16,"a":71,"at":"والله فضل بعضكم على بعض في الرزق فما الذين فضلوا برادي رزقهم على ما ملكت ايمانهم فهم فيه سواء افبنعمه الله يجحدون","dt":"[71] والله فضل بعضكم على بعض فيما اعطاكم في الدنيا من الرزق، فمنكم غني ومنكم فقير، ومنكم مالك ومنكم مملوك، فلا يعطي المالكون مملوكيهم مما اعطاهم الله ما يصيرون به شركاء لهم متساوين معهم في المال، فاذا لم يرضوا بذلك لانفسهم، فلماذا رضوا ان يجعلوا لله شركاء من عبيده؟ ان هذا لمن اعظم الظلم والجحود لنعم الله عز وجل."},{"id":"1973","s":16,"a":72,"at":"والله جعل لكم من انفسكم ازواجا وجعل لكم من ازواجكم بنين وحفده ورزقكم من الطيبات افبالباطل يؤمنون وبنعمه الله هم يكفرون","dt":"[72] والله سبحانه جعل من جنسكم ازواجا؛ لتستريح نفوسكم معهن، وجعل لكم منهن الابناء ومن نسلهن الاحفاد، ورزقكم من الاطعمه الطيبه من الثمار والحبوب واللحوم وغير ذلك. افبالباطل من الوهيه شركائهم يؤمنون، وبنعم الله التي لا تحصى يجحدون، ولا يشكرون له بافراده جل وعلا بالعباده؟"},{"id":"1974","s":16,"a":73,"at":"ويعبدون من دون الله ما لا يملك لهم رزقا من السموات والارض شيئا ولا يستطيعون","dt":"[73] ويعبد المشركون اصناما لا تملك ان تعطيهم شيئا من الرزق من السماء كالمطر، ولا من الارض كالزرع، فهم لا يملكون شيئا، ولا يتاتى منهم ان يملكوه؛ لانهم لا يقدرون."},{"id":"1975","s":16,"a":74,"at":"فلا تضربوا لله الامثال ان الله يعلم وانتم لا تعلمون","dt":"[74] واذا علمتم ان الاصنام والاوثان لا تنفع، فلا تجعلوا -ايها الناس- لله اشباها مماثلين له من خلقه تشركونهم معه في العباده. ان الله يعلم ما تفعلون، وانتم غافلون لا تعلمون خطاكم وسوء عاقبتكم."},{"id":"1976","s":16,"a":75,"at":"ضرب الله مثلا عبدا مملوكا لا يقدر على شيء ومن رزقناه منا رزقا حسنا فهو ينفق منه سرا وجهرا هل يستوون الحمد لله بل اكثرهم لا يعلمون","dt":"[75] ضرب الله مثلا بين فيه فساد عقيده اهل الشرك: رجلا مملوكا عاجزا عن التصرف لا يملك شيئا، ورجلا اخر حرا، له مال حلال رزقه الله به، يملك التصرف فيه، ويعطي منه في الخفاء والعلن، فهل يقول عاقل بالتساوي بين الرجلين؟ فكذلك الله الخالق المالك المتصرف لا يستوي مع خلقه وعبيده، فكيف تسوون بينهما؟ الحمد لله وحده، فهو المستحق للحمد والثناء، بل اكثر المشركين لا يعلمون ان الحمد والنعمه لله، وانه وحده المستحق للعباده."},{"id":"1977","s":16,"a":76,"at":"وضرب الله مثلا رجلين احدهما ابكم لا يقدر على شيء وهو كل على مولاه اينما يوجهه لا يات بخير هل يستوي هو ومن يامر بالعدل وهو على صراط مستقيم","dt":"[76] وضرب الله مثلا اخر لبطلان الشرك رجلين: احدهما اخرس اصم لا يفهم ولا يفهم، لا يقدر على منفعه نفسه او غيره، وهو عبء ثقيل على من يلي امره ويعوله، اذا ارسله لامر يقضيه لا ينجح، ولا يعود عليه بخير، ورجل اخر سليم الحواس، ينفع نفسه وغيره، يامر بالانصاف، وهو على طريق واضح لا عوج فيه، فهل يستوي الرجلان في نظر العقلاء؟ فكيف تسوون بين الصنم الابكم الاصم وبين الله القادر المنعم بكل خير؟"},{"id":"1978","s":16,"a":77,"at":"ولله غيب السموات والارض وما امر الساعه الا كلمح البصر او هو اقرب ان الله على كل شيء قدير","dt":"[77] ولله سبحانه وتعالى علم ما غاب في السموات والارض، وما شان القيامه في سرعه مجيئها الا كنظره سريعه بالبصر، بل هو اسرع من ذلك. ان الله على كل شيء قدير."},{"id":"1979","s":16,"a":78,"at":"والله اخرجكم من بطون امهاتكم لا تعلمون شيئا وجعل لكم السمع والابصار والافئده لعلكم تشكرون","dt":"[78] والله سبحانه وتعالى اخرجكم من بطون امهاتكم بعد مده الحمل، لا تدركون شيئا مما حولكم، وجعل لكم وسائل الادراك من السمع والبصر والقلوب؛ لعلكم تشكرون لله تعالى على تلك النعم، وتفردونه عز وجل بالعباده."},{"id":"1980","s":16,"a":79,"at":"الم يروا الى الطير مسخرات في جو السماء ما يمسكهن الا الله ان في ذلك لايات لقوم يؤمنون","dt":"[79] الم ينظر المشركون الى الطير مذللات للطيران في الهواء بين السماء والارض بامر الله؟ ما يمسكهن عن الوقوع الا هو سبحانه بما خلقه لها من الاجنحه والاذناب، واقدرها عليه. ان في ذلك التذليل والامساك لدلالات لقوم يؤمنون بما يرونه من الادله على قدره الله."},{"id":"1981","s":16,"a":80,"at":"والله جعل لكم من بيوتكم سكنا وجعل لكم من جلود الانعام بيوتا تستخفونها يوم ظعنكم ويوم اقامتكم ومن اصوافها واوبارها واشعارها اثاثا ومتاعا الى حين","dt":"[80] والله سبحانه جعل لكم من بيوتكم راحه واستقرارا مع اهلكم، وانتم مقيمون في الحضر، وجعل لكم في سفركم خياما وقبابا من جلود الانعام، يخف عليكم حملها وقت ترحالكم، ويخف عليكم نصبها وقت اقامتكم بعد الترحال، وجعل لكم من اصواف الغنم، واوبار الابل، واشعار المعز اثاثا لكم من اكسيه والبسه واغطيه وفرش وزينه، تتمتعون بها الى اجل مسمى ووقت معلوم."},{"id":"1982","s":16,"a":81,"at":"والله جعل لكم مما خلق ظلالا وجعل لكم من الجبال اكنانا وجعل لكم سرابيل تقيكم الحر وسرابيل تقيكم باسكم كذلك يتم نعمته عليكم لعلكم تسلمون","dt":"[81] والله جعل لكم ما تستظلون به من الاشجار وغيرها، وجعل لكم في الجبال من المغارات والكهوف اماكن تلجؤون اليها عند الحاجه، وجعل لكم ثيابا من القطن والصوف وغيرهما، تحفظكم من الحر والبرد، وجعل لكم من الحديد ما يرد عنكم الطعن والاذى في حروبكم، كما انعم الله عليكم بهذه النعم يتم نعمته عليكم ببيان الدين الحق؛ لتستسلموا لامر الله وحده، ولا تشركوا به شيئا في عبادته."},{"id":"1983","s":16,"a":82,"at":"فان تولوا فانما عليك البلاغ المبين","dt":"[82] فان اعرضوا عنك -ايها الرسول- بعدما راوا من الايات فلا تحزن، فما عليك الا البلاغ الواضح لما ارسلت به، واما الهدايه فالينا."},{"id":"1984","s":16,"a":83,"at":"يعرفون نعمه الله ثم ينكرونها واكثرهم الكافرون","dt":"[83] يعرف هؤلاء المشركون نعمه الله عليهم بارسال محمد -صلى الله عليه وسلم- اليهم، ثم يجحدون نبوته، واكثر قومه الجاحدون لنبوته، لا المقرون بها."},{"id":"1985","s":16,"a":84,"at":"ويوم نبعث من كل امه شهيدا ثم لا يؤذن للذين كفروا ولا هم يستعتبون","dt":"[84] واذكر لهم -ايها الرسول- ما يكون يوم القيامه، حين نبعث من كل امه رسولها شاهدا على ايمان من امن منها، وكفر من كفر، ثم لا يؤذن للذين كفروا بالاعتذار عما وقع منهم، ولا يطلب منهم ارضاء ربهم بالتوبه والعمل الصالح، فقد مضى اوان ذلك."},{"id":"1986","s":16,"a":85,"at":"واذا راى الذين ظلموا العذاب فلا يخفف عنهم ولا هم ينظرون","dt":"[85] واذا شاهد الذين كفروا عذاب الله في الاخره فلا يخفف عنهم منه شيء، ولا يمهلون، ولا يؤخر عذابهم."},{"id":"1987","s":16,"a":86,"at":"واذا راى الذين اشركوا شركاءهم قالوا ربنا هؤلاء شركاؤنا الذين كنا ندعوا من دونك فالقوا اليهم القول انكم لكاذبون","dt":"[86] واذا ابصر المشركون يوم القيامه الهتهم التي عبدوها مع الله، قالوا: ربنا هؤلاء شركاؤنا الذين كنا نعبدهم من دونك، فنطقت الالهه بتكذيب من عبدوها، وقالت: انكم -ايها المشركون- لكاذبون، حين جعلتمونا شركاء لله وعبدتمونا معه، فلم نامركم بذلك، ولا زعمنا اننا مستحقون للالوهيه، فاللوم عليكم."},{"id":"1988","s":16,"a":87,"at":"والقوا الى الله يومئذ السلم وضل عنهم ما كانوا يفترون","dt":"[87] واظهر المشركون الاستسلام والخضوع لله يوم القيامه، وغاب عنهم ما كانوا يختلقونه من الاكاذيب، وان الهتهم تشفع لهم."},{"id":"1989","s":16,"a":88,"at":"الذين كفروا وصدوا عن سبيل الله زدناهم عذابا فوق العذاب بما كانوا يفسدون","dt":"[88] الذين جحدوا وحدانيه الله ونبوتك -ايها الرسول- وكذبوك، ومنعوا غيرهم عن الايمان بالله ورسوله، زدناهم عذابا على كفرهم وعذابا على صدهم الناس عن اتباع الحق؛ وهذا بسبب تعمدهم الافساد واضلال العباد بالكفر والمعصيه."},{"id":"1990","s":16,"a":89,"at":"ويوم نبعث في كل امه شهيدا عليهم من انفسهم وجئنا بك شهيدا على هؤلاء ونزلنا عليك الكتاب تبيانا لكل شيء وهدى ورحمه وبشرى للمسلمين","dt":"[89] واذكر -ايها الرسول- حين نبعث يوم القيامه في كل امه من الامم شهيدا عليهم، وهو الرسول الذي بعثه الله اليهم من انفسهم وبلسانهم، وجئنا بك -ايها الرسول- شهيدا على امتك انك بلغت رساله ربك، وقد نزلنا عليك القران توضيحا لكل امر يحتاج الى بيان، كاحكام الحلال والحرام، والثواب والعقاب، وغير ذلك، وليكون هدايه من الضلال، ورحمه لمن صدق وعمل به، وبشاره طيبه للمؤمنين بحسن مصيرهم."},{"id":"1991","s":16,"a":90,"at":"ان الله يامر بالعدل والاحسان وايتاء ذي القربى وينهى عن الفحشاء والمنكر والبغي يعظكم لعلكم تذكرون","dt":"[90] ان الله سبحانه وتعالى يامر عباده في هذا القران بالعدل والانصاف في حقه بتوحيده وعدم الاشراك به، وفي حق عباده باعطاء كل ذي حق حقه، ويامر بالاحسان في حقه بعبادته واداء فرائضه على الوجه المشروع، والى الخلق في الاقوال والافعال، ويامر باعطاء ذوي القرابه ما به صلتهم وبرهم، وينهى عن كل ما قبح قولا او عملا، وعما ينكره الشرع ولا يرضاه من الكفر والمعاصي، وعن ظلم الناس والتعدي عليهم، والله -بهذا الامر وهذا النهي- يعظكم ويذكركم العواقب؛ لكي تتذكروا اوامر الله وتنتفعوا بها."},{"id":"1992","s":16,"a":91,"at":"واوفوا بعهد الله اذا عاهدتم ولا تنقضوا الايمان بعد توكيدها وقد جعلتم الله عليكم كفيلا ان الله يعلم ما تفعلون","dt":"[91] والتزموا الوفاء بكل عهد اوجبتموه على انفسكم بينكم وبين الله -تعالى-، او بينكم وبين الناس فيما لا يخالف كتاب الله وسنه نبيه، ولا ترجعوا في الايمان بعد ان اكدتموها، وقد جعلتم الله عليكم كفيلا وضامنا حين عاهدتموه. ان الله يعلم ما تفعلونه، وسيجزيكم عليه."},{"id":"1993","s":16,"a":92,"at":"ولا تكونوا كالتي نقضت غزلها من بعد قوه انكاثا تتخذون ايمانكم دخلا بينكم ان تكون امه هي اربى من امه انما يبلوكم الله به وليبينن لكم يوم القيامه ما كنتم فيه تختلفون","dt":"[92] ولا ترجعوا في عهودكم، فيكون مثلكم مثل امراه غزلت غزلا واحكمته، ثم نقضته؛ تجعلون ايمانكم التي حلفتموها عند التعاهد خديعه لمن عاهدتموه، وتنقضون عهدكم اذا وجدتم جماعه اكثر مالا ومنفعه من الذين عاهدتموهم، انما يختبركم الله بما امركم به من الوفاء بالعهود وما نهاكم عنه من نقضها، وليبينن لكم يوم القيامه ما كنتم فيه تختلفون في الدنيا من الايمان بالله ونبوه محمد -صلى الله عليه وسلم-."},{"id":"1994","s":16,"a":93,"at":"ولو شاء الله لجعلكم امه واحده ولكن يضل من يشاء ويهدي من يشاء ولتسالن عما كنتم تعملون","dt":"[93] ولو شاء الله لوفقكم كلكم، فجعلكم على مله واحده، وهي الاسلام والايمان، والزمكم به، ولكنه سبحانه يضل من يشاء ممن علم منه ايثار الضلال، فلا يهديه؛ عدلا منه، ويهدي من يشاء ممن علم منه ايثار الحق، فيوفقه؛ فضلا منه، وليسالنكم الله جميعا يوم القيامه عما كنتم تعملون في الدنيا فيما امركم به، ونهاكم عنه، وسيجازيكم على ذلك."},{"id":"1995","s":16,"a":94,"at":"ولا تتخذوا ايمانكم دخلا بينكم فتزل قدم بعد ثبوتها وتذوقوا السوء بما صددتم عن سبيل الله ولكم عذاب عظيم","dt":"[94] ولا تجعلوا من الايمان التي تحلفونها خديعه لمن حلفتم لهم، فتهلكوا بعد ان كنتم امنين، كمن زلقت قدمه بعد ثبوتها، وتذوقوا ما يسوءكم من العذاب في الدنيا؛ بما تسببتم فيه من منع غيركم عن هذا الدين لما راوه منكم من الغدر، ولكم في الاخره عذاب عظيم."},{"id":"1996","s":16,"a":95,"at":"ولا تشتروا بعهد الله ثمنا قليلا انما عند الله هو خير لكم ان كنتم تعلمون","dt":"[95] ولا تنقضوا عهد الله؛ لتستبدلوا مكانه عرضا قليلا من متاع الدنيا، ان ما عند الله من الثواب على الوفاء افضل لكم من هذا الثمن القليل، ان كنتم من اهل العلم، فتدبروا الفرق بين خيري الدنيا والاخره."},{"id":"1997","s":16,"a":96,"at":"ما عندكم ينفد وما عند الله باق ولنجزين الذين صبروا اجرهم باحسن ما كانوا يعملون","dt":"[96] ما عندكم من حطام الدنيا يذهب، وما عند الله لكم من الرزق والثواب لا يزول. ولنثيبن الذين تحملوا مشاق التكاليف -ومنها الوفاء بالعهد- ثوابهم باحسن اعمالهم، فنعطيهم على ادناها، كما نعطيهم على اعلاها تفضلا."},{"id":"1998","s":16,"a":97,"at":"من عمل صالحا من ذكر او انثى وهو مؤمن فلنحيينه حياه طيبه ولنجزينهم اجرهم باحسن ما كانوا يعملون","dt":"[97] من عمل عملا صالحا، ذكرا كان ام انثى، وهو مؤمن بالله ورسوله، فلنحيينه في الدنيا حياه سعيده مطمئنه، ولو كان قليل المال، ولنجزينهم في الاخره ثوابهم باحسن ما عملوا في الدنيا."},{"id":"1999","s":16,"a":98,"at":"فاذا قرات القران فاستعذ بالله من الشيطان الرجيم","dt":"[98] فاذا اردت -ايها المؤمن- ان تقرا شيئا من القران فاستعذ بالله من شر الشيطان المطرود من رحمه الله قائلا: اعوذ بالله من الشيطان الرجيم."},{"id":"2000","s":16,"a":99,"at":"انه ليس له سلطان على الذين امنوا وعلى ربهم يتوكلون","dt":"[99] ان الشيطان ليس له تسلط على المؤمنين بالله ورسوله، وعلى ربهم وحده يعتمدون"},{"id":"2001","s":16,"a":100,"at":"انما سلطانه على الذين يتولونه والذين هم به مشركون","dt":"[100] انما تسلطه على الذين جعلوه معينا لهم واطاعوه، والذين هم -بسبب طاعته- مشركون بالله تعالى."},{"id":"2002","s":16,"a":101,"at":"واذا بدلنا ايه مكان ايه والله اعلم بما ينزل قالوا انما انت مفتر بل اكثرهم لا يعلمون","dt":"[101] واذا بدلنا ايه بايه اخرى، والله الخالق اعلم بمصلحه خلقه بما ينزله من الاحكام في الاوقات المختلفه، قال الكفار: انما انت -يا محمد- كاذب مختلق على الله ما لم يقله. ومحمد -صلى الله عليه وسلم- ليس كما يزعمون. بل اكثرهم لا علم لهم بربهم ولا بشرعه واحكامه."},{"id":"2003","s":16,"a":102,"at":"قل نزله روح القدس من ربك بالحق ليثبت الذين امنوا وهدى وبشرى للمسلمين","dt":"[102] قل لهم -ايها الرسول-: ليس القران مختلقا من عندي، بل نزله جبريل من ربك بالصدق والعدل؛ تثبيتا للمؤمنين، وهدايه من الضلال، وبشاره طيبه لمن اسلموا وخضعوا لله رب العالمين."},{"id":"2004","s":16,"a":103,"at":"ولقد نعلم انهم يقولون انما يعلمه بشر لسان الذي يلحدون اليه اعجمي وهذا لسان عربي مبين","dt":"[103] ولقد نعلم ان المشركين يقولون: ان النبي يتلقى القران من بشر من بني ادم. كذبوا؛ فان لسان الذي نسبوا اليه تعليم النبي -صلى الله عليه وسلم- اعجمي لا يفصح، والقران عربي غايه في الوضوح والبيان."},{"id":"2005","s":16,"a":104,"at":"ان الذين لا يؤمنون بايات الله لا يهديهم الله ولهم عذاب اليم","dt":"[104] ان الكفار الذين لا يصدقون بالقران لا يوفقهم الله لاصابه الحق، ولهم في الاخره عذاب مؤلم موجع."},{"id":"2006","s":16,"a":105,"at":"انما يفتري الكذب الذين لا يؤمنون بايات الله واولئك هم الكاذبون","dt":"[105] انما يختلق الكذب من لا يؤمن بالله واياته، واولئك هم الكاذبون في قولهم ذلك. اما محمد -صلى الله عليه وسلم- المؤمن بربه الخاضع له فمحال ان يكذب على الله، ويقول عليه ما لم يقله."},{"id":"2007","s":16,"a":106,"at":"من كفر بالله من بعد ايمانه الا من اكره وقلبه مطمئن بالايمان ولكن من شرح بالكفر صدرا فعليهم غضب من الله ولهم عذاب عظيم","dt":"[106] انما يفتري الكذب من نطق بكلمه الكفر وارتد بعد ايمانه، فعليهم غضب من الله، الا من ارغم على النطق بالكفر، فنطق به خوفا من الهلاك، وقلبه ثابت على الايمان، فلا لوم عليه، لكن من نطق بالكفر واطمان قلبه اليه، فعليهم غضب شديد من الله، ولهم عذاب عظيم؛"},{"id":"2008","s":16,"a":107,"at":"ذلك بانهم استحبوا الحياه الدنيا على الاخره وان الله لا يهدي القوم الكافرين","dt":"[107] وذلك بسبب ايثارهم الدنيا وزينتها، وتفضيلهم اياها على الاخره وثوابها، وان الله لا يوفق الكافرين للحق والصواب."},{"id":"2009","s":16,"a":108,"at":"اولئك الذين طبع الله على قلوبهم وسمعهم وابصارهم واولئك هم الغافلون","dt":"[108] اولئك هم الذين ختم الله على قلوبهم بالكفر وايثار الدنيا على الاخره، فلا يصل اليها نور الهدايه، واصم سمعهم عن ايات الله فلا يسمعونها سماع تدبر، واعمى ابصارهم فلا يرون البراهين الداله على الوهيه الله، واولئك هم الغافلون عما اعد الله لهم من العذاب."},{"id":"2010","s":16,"a":109,"at":"لا جرم انهم في الاخره هم الخاسرون","dt":"[109] حقا انهم في الاخره هم الخاسرون الهالكون، الذين صرفوا حياتهم الى ما فيه عذابهم وهلاكهم."},{"id":"2011","s":16,"a":110,"at":"ثم ان ربك للذين هاجروا من بعد ما فتنوا ثم جاهدوا وصبروا ان ربك من بعدها لغفور رحيم","dt":"[110] ثم ان ربك للمستضعفين في «مكه» الذين عذبهم المشركون، حتى وافقوهم على ما هم عليه ظاهرا، ففتنوهم بالتلفظ بما يرضيهم، وقلوبهم مطمئنه بالايمان، ولما امكنهم الخلاص هاجروا الى «المدينه»، ثم جاهدوا في سبيل الله، وصبروا على مشاق التكاليف، ان ربك -من بعد توبتهم- لغفور لهم، رحيم بهم."},{"id":"2012","s":16,"a":111,"at":"يوم تاتي كل نفس تجادل عن نفسها وتوفى كل نفس ما عملت وهم لا يظلمون","dt":"[111] وذكرهم -ايها الرسول- بيوم القيامه حين تاتي كل نفس تخاصم عن ذاتها، وتعتذر بكل المعاذير، ويوفي الله كل نفس جزاء ما عملته من غير ظلم لها، فلا يزيدهم في العقاب، ولا ينقصهم من الثواب."},{"id":"2013","s":16,"a":112,"at":"وضرب الله مثلا قريه كانت امنه مطمئنه ياتيها رزقها رغدا من كل مكان فكفرت بانعم الله فاذاقها الله لباس الجوع والخوف بما كانوا يصنعون","dt":"[112] وضرب الله مثلا بلده «مكه» كانت في امان من الاعتداء، واطمئنان من ضيق العيش، ياتيها رزقها هنيئا سهلا من كل جهه، فجحد اهلها نعم الله عليهم، واشركوا به، ولم يشكروا له، فعاقبهم الله بالجوع، والخوف من سرايا رسول الله -صلى الله عليه وسلم- وجيوشه، التي كانت تخيفهم؛ وذلك بسبب كفرهم وصنيعهم الباطل."},{"id":"2014","s":16,"a":113,"at":"ولقد جاءهم رسول منهم فكذبوه فاخذهم العذاب وهم ظالمون","dt":"[113] ولقد ارسل الله الى اهل «مكه» رسولا منهم، هو النبي محمد -صلى الله عليه وسلم-، يعرفون نسبه وصدقه وامانته، فلم يقبلوا ما جاءهم به، ولم يصدقوه، فاخذهم العذاب من الشدائد والجوع والخوف، وقتل عظمائهم في «بدر»، وهم ظالمون لانفسهم بالشرك بالله، والصد عن سبيله."},{"id":"2015","s":16,"a":114,"at":"فكلوا مما رزقكم الله حلالا طيبا واشكروا نعمه الله ان كنتم اياه تعبدون","dt":"[114] فكلوا -ايها المؤمنون- مما رزقكم الله، وجعله لكم حلالا مستطابا، واشكروا نعمه الله عليكم بالاعتراف بها وصرفها في طاعه الله، ان كنتم حقا منقادين لامره سامعين مطيعين له، تعبدونه وحده لا شريك له."},{"id":"2016","s":16,"a":115,"at":"انما حرم عليكم الميته والدم ولحم الخنزير وما اهل لغير الله به فمن اضطر غير باغ ولا عاد فان الله غفور رحيم","dt":"[115] انما حرم الله عليكم الميته من الحيوان، والدم المسفوح من الذبيح عند ذبحه، ولحم الخنزير، وما ذبح لغير الله، لكن من الجاته ضروره الخوف من الموت الى اكل شيء من هذه المحرمات وهو غير ظالم، ولا متجاوز حد الضروره، فان الله غفور له، رحيم به، لا يعاقبه على ما فعل."},{"id":"2017","s":16,"a":116,"at":"ولا تقولوا لما تصف السنتكم الكذب هذا حلال وهذا حرام لتفتروا على الله الكذب ان الذين يفترون على الله الكذب لا يفلحون","dt":"[116] ولا تقولوا -ايها المشركون- للكذب الذي تصفه السنتكم: هذا حلال لما حرمه الله، وهذا حرام لما احله الله؛ لتختلقوا على الله الكذب بنسبه التحليل والتحريم اليه، ان الذين يختلقون على الله الكذب لا يفوزون بخير في الدنيا ولا في الاخره."},{"id":"2018","s":16,"a":117,"at":"متاع قليل ولهم عذاب اليم","dt":"[117] متاعهم في الدنيا متاع زائل ضئيل، ولهم في الاخره عذاب موجع."},{"id":"2019","s":16,"a":118,"at":"وعلى الذين هادوا حرمنا ما قصصنا عليك من قبل وما ظلمناهم ولكن كانوا انفسهم يظلمون","dt":"[118] وعلى اليهود حرمنا ما اخبرناك به -ايها الرسول- من قبل، وهو كل ذي ظفر، وشحوم البقر والغنم، الا ما حملته ظهورها او امعاؤها او كان مختلطا بعظم، وما ظلمناهم بتحريم ذلك عليهم، ولكن كانوا ظالمين لانفسهم بالكفر والبغي، فاستحقوا التحريم عقوبه لهم."},{"id":"2020","s":16,"a":119,"at":"ثم ان ربك للذين عملوا السوء بجهاله ثم تابوا من بعد ذلك واصلحوا ان ربك من بعدها لغفور رحيم","dt":"[119] ثم ان ربك للذين فعلوا المعاصي في حال جهلهم لعاقبتها وايجابها لسخط الله، وبغفله منهم او ضعف يقين -فكل عاص لله -مخطئا او متعمدا- فهو جاهل بهذا الاعتبار وان كان عالما بالتحريم-، ثم رجعوا الى الله عما كانوا عليه من الذنوب، واصلحوا نفوسهم واعمالهم، ان ربك -من بعد توبتهم واصلاحهم- لغفور لهم، رحيم بهم."},{"id":"2021","s":16,"a":120,"at":"ان ابراهيم كان امه قانتا لله حنيفا ولم يك من المشركين","dt":"[120] ان ابراهيم كان اماما في الخير، وكان طائعا خاضعا لله، لا يميل عن دين الاسلام موحدا لله غير مشرك به"},{"id":"2022","s":16,"a":121,"at":"شاكرا لانعمه اجتباه وهداه الى صراط مستقيم","dt":"[121] وكان شاكرا لنعم الله عليه، اختاره الله لرسالته، وارشده الى الطريق المستقيم، وهو الاسلام،"},{"id":"2023","s":16,"a":122,"at":"واتيناه في الدنيا حسنه وانه في الاخره لمن الصالحين","dt":"[122] ، واتيناه في الدنيا نعمه حسنه من الثناء عليه في الاخرين والقدوه به، والولد الصالح، وانه عند الله في الاخره لمن الصالحين اصحاب المنازل العاليه."},{"id":"2024","s":16,"a":123,"at":"ثم اوحينا اليك ان اتبع مله ابراهيم حنيفا وما كان من المشركين","dt":"[123] ثم اوحينا اليك -ايها الرسول- ان اتبع دين الاسلام كما اتبعه ابراهيم، وان استقم عليه، ولا تحد عنه، فان ابراهيم لم يكن من المشركين مع الله غيره."},{"id":"2025","s":16,"a":124,"at":"انما جعل السبت على الذين اختلفوا فيه وان ربك ليحكم بينهم يوم القيامه فيما كانوا فيه يختلفون","dt":"[124] انما جعل الله تعظيم يوم السبت بالتفرغ للعباده فيه على اليهود الذين اختلفوا فيه على نبيهم، واختاروه بدل يوم الجمعه الذي امروا بتعظيمه. وان ربك -ايها الرسول- ليحكم بين المختلفين يوم القيامه فيما اختلفوا فيه على نبيهم، ويجازي كلا بما يستحقه."},{"id":"2026","s":16,"a":125,"at":"ادع الى سبيل ربك بالحكمه والموعظه الحسنه وجادلهم بالتي هي احسن ان ربك هو اعلم بمن ضل عن سبيله وهو اعلم بالمهتدين","dt":"[125] ادع -ايها الرسول- انت ومن اتبعك الى دين ربك وطريقه المستقيم، بالطريقه الحكيمه التي اوحاها الله اليك في الكتاب والسنه، وخاطب الناس بالاسلوب المناسب لهم، وانصح لهم نصحا حسنا، يرغبهم في الخير، وينفرهم من الشر، وجادلهم باحسن طرق المجادله من الرفق واللين. فما عليك الا البلاغ، وقد بلغت، اما هدايتهم فعلى الله وحده، فهو اعلم بمن ضل عن سبيله، وهو اعلم بالمهتدين."},{"id":"2027","s":16,"a":126,"at":"وان عاقبتم فعاقبوا بمثل ما عوقبتم به ولئن صبرتم لهو خير للصابرين","dt":"[126] وان اردتم -ايها المؤمنون- القصاص ممن اعتدوا عليكم، فلا تزيدوا عما فعلوه بكم، ولئن صبرتم لهو خير لكم في الدنيا بالنصر، وفي الاخره بالاجر العظيم."},{"id":"2028","s":16,"a":127,"at":"واصبر وما صبرك الا بالله ولا تحزن عليهم ولا تك في ضيق مما يمكرون","dt":"[127] واصبر -ايها الرسول- على ما اصابك من اذى في الله حتى ياتيك الفرج، وما صبرك الا بالله، فهو الذي يعينك عليه ويثبتك، ولا تحزن على من خالفك ولم يستجب لدعوتك، ولا تغتم من مكرهم وكيدهم؛ فان ذلك عائد عليهم بالشر والوبال."},{"id":"2029","s":16,"a":128,"at":"ان الله مع الذين اتقوا والذين هم محسنون","dt":"[128] ان الله سبحانه وتعالى -بتوفيقه وعونه وتاييده ونصره- مع الذين اتقوه بامتثال ما امر واجتناب ما نهى، ومع الذين يحسنون اداء فرائضه والقيام بحقوقه ولزوم طاعته."},{"id":"2030","s":17,"a":1,"at":"سبحان الذي اسرى بعبده ليلا من المسجد الحرام الى المسجد الاقصى الذي باركنا حوله لنريه من اياتنا انه هو السميع البصير","dt":"[1] يمجد الله نفسه ويعظم شانه، لقدرته على ما لا يقدر عليه احد سواه، لا اله غيره، ولا رب سواه، فهو الذي اسرى بعبده محمد -صلى الله عليه وسلم- زمنا من الليل بجسده وروحه، يقظه لا مناما، من المسجد الحرام ب«مكه» الى المسجد الاقصى ب«بيت المقدس» الذي بارك الله حوله في الزروع والثمار وغير ذلك، وجعله محلا لكثير من الانبياء؛ ليشاهد عجائب قدره الله وادله وحدانيته. ان الله سبحانه وتعالى هو السميع لجميع الاصوات، البصير بكل مبصر، فيعطي كلا ما يستحقه في الدنيا والاخره."},{"id":"2031","s":17,"a":2,"at":"واتينا موسى الكتاب وجعلناه هدى لبني اسرائيل الا تتخذوا من دوني ‎وكيلا","dt":"[2] وكما كرم الله محمدا -صلى الله عليه وسلم- بالاسراء، كرم موسى عليه السلام باعطائه التوراه، وجعلها بيانا للحق وارشادا لبني اسرائيل، متضمنه نهيهم عن اتخاذ غير الله تعالى وليا او معبودا يفوضون اليه امورهم."},{"id":"2032","s":17,"a":3,"at":"ذريه من حملنا مع نوح انه كان عبدا شكورا","dt":"[3] يا سلاله الذين انجيناهم وحملناهم مع نوح في السفينه لا تشركوا بالله في عبادته، وكونوا شاكرين لنعمه، مقتدين بنوح عليه السلام؛ انه كان عبدا شكورا لله بقلبه ولسانه وجوارحه."},{"id":"2033","s":17,"a":4,"at":"وقضينا الى بني اسرائيل في الكتاب لتفسدن في الارض مرتين ولتعلن علوا كبيرا","dt":"[4] واخبرنا بني اسرائيل في التوراه التي انزلت عليهم بانه لابد ان يقع منهم افساد مرتين في «بيت المقدس» وما والاه بالظلم، وقتل الانبياء، والتكبر والطغيان والعدوان."},{"id":"2034","s":17,"a":5,"at":"فاذا جاء وعد اولاهما بعثنا عليكم عبادا لنا اولي باس شديد فجاسوا خلال الديار وكان وعدا مفعولا","dt":"[5] فاذا وقع منكم الافساد الاول سلطنا عليكم عبادا لنا ذوي شجاعه وقوه شديده، يغلبونكم ويقتلونكم ويشردونكم، فطافوا بين دياركم مفسدين، وكان ذلك وعدا لا بد من وقوعه؛ لوجود سببه منكم."},{"id":"2035","s":17,"a":6,"at":"ثم رددنا لكم الكره عليهم وامددناكم باموال وبنين وجعلناكم اكثر نفيرا","dt":"[6] ثم رددنا لكم -يا بني اسرائيل- الغلبه والظهور على اعدائكم الذين سلطوا عليكم، واكثرنا ارزاقكم واولادكم، وقويناكم وجعلناكم اكثر عددا من عدوكم؛ وذلك بسبب احسانكم وخضوعكم لله."},{"id":"2036","s":17,"a":7,"at":"ان احسنتم احسنتم لانفسكم وان اساتم فلها فاذا جاء وعد الاخره ليسوءوا وجوهكم وليدخلوا المسجد كما دخلوه اول مره وليتبروا ما علوا تتبيرا","dt":"[7] ان احسنتم افعالكم واقوالكم فقد احسنتم لانفسكم؛ لان ثواب ذلك عائد اليكم، وان اساتم فعقاب ذلك عائد عليكم، فاذا حان موعد الافساد الثاني سلطنا عليكم اعداءكم مره اخرى؛ ليذلوكم ويغلبوكم، فتظهر اثار الاهانه والمذله على وجوهكم، وليدخلوا عليكم «بيت المقدس» فيخربوه، كما خربوه اول مره، وليدمروا كل ما وقع تحت ايديهم تدميرا كاملا."},{"id":"2037","s":17,"a":8,"at":"عسى ربكم ان يرحمكم وان عدتم عدنا وجعلنا جهنم للكافرين حصيرا","dt":"[8] عسى ربكم -يا بني اسرائيل- ان يرحمكم بعد انتقامه ان تبتم واصلحتم، وان عدتم الى الافساد والظلم عدنا الى عقابكم ومذلتكم. وجعلنا جهنم لكم وللكافرين عامه سجنا لا خروج منه ابدا. وفي هذه الايه وما قبلها، تحذير لهذه الامه من العمل بالمعاصي؛ لئلا يصيبها مثل ما اصاب بني اسرائيل، فسنن الله واحده لا تبدل ولا تغير."},{"id":"2038","s":17,"a":9,"at":"ان هذا القران يهدي للتي هي اقوم ويبشر المؤمنين الذين يعملون الصالحات ان لهم اجرا كبيرا","dt":"[9] ان هذا القران الذي انزلناه على عبدنا محمد -صلى الله عليه وسلم- يرشد الناس الى احسن الطرق، وهي مله الاسلام، ويبشر المؤمنين الذين يعملون بما امرهم الله به، وينتهون عما نهاهم عنه، بان لهم ثوابا عظيما ."},{"id":"2039","s":17,"a":10,"at":"وان الذين لا يؤمنون بالاخره اعتدنا لهم عذابا اليما","dt":"[10] وان الذين لا يصدقون بالدار الاخره وما فيها من الجزاء اعددنا لهم عذابا موجعا في النار."},{"id":"2040","s":17,"a":11,"at":"ويدع الانسان بالشر دعاءه بالخير وكان الانسان عجولا","dt":"[11] ويدعو الانسان احيانا على نفسه او ولده او ماله بالشر، وذلك عند الغضب، مثل ما يدعو بالخير، وهذا من جهل الانسان وعجلته، ومن رحمه الله به انه يستجيب له في دعائه بالخير دون الشر؛ لانه يعلم منه عدم القصد الى اراده ذلك، وكان الانسان بطبعه عجولا."},{"id":"2041","s":17,"a":12,"at":"وجعلنا الليل والنهار ايتين فمحونا ايه الليل وجعلنا ايه النهار مبصره لتبتغوا فضلا من ربكم ولتعلموا عدد السنين والحساب وكل شيء فصلناه تفصيلا","dt":"[12] وجعلنا الليل والنهار علامتين دالتين على وحدانيتنا وقدرتنا، فمحونا علامه الليل -وهي القمر- وجعلنا علامه النهار -وهي الشمس- مضيئه؛ ليبصر الانسان في ضوء النهار كيف يتصرف في شؤون معاشه، ويخلد في الليل الى السكن والراحه، وليعلم الناس -من تعاقب الليل والنهار- عدد السنين وحساب الاشهر والايام، فيرتبون عليها ما يشاؤون من مصالحهم، وكل شيء بيناه تبيينا كافيا."},{"id":"2042","s":17,"a":13,"at":"وكل انسان الزمناه طائره في عنقه ونخرج له يوم القيامه كتابا يلقاه منشورا","dt":"[13] وكل انسان يجعل الله ما عمله من خير او شر ملازما له، فلا يحاسب بعمل غيره، ولا يحاسب غيره بعمله، ويخرج الله له يوم القيامه كتابا قد سجلت فيه اعماله يراه مفتوحا."},{"id":"2043","s":17,"a":14,"at":"اقرا كتابك كفى بنفسك اليوم عليك حسيبا","dt":"[14] يقال له: اقرا كتاب اعمالك، فيقرا، وان لم يكن يعرف القراءه في الدنيا، تكفيك نفسك اليوم محصيه عليك عملك، فتعرف ما عليها من جزاء. وهذا من اعظم العدل والانصاف ان يقال للعبد: حاسب نفسك، كفى بها حسيبا عليك."},{"id":"2044","s":17,"a":15,"at":"من اهتدى فانما يهتدي لنفسه ومن ضل فانما يضل عليها ولا تزر وازره وزر اخرى وما كنا معذبين حتى نبعث رسولا","dt":"[15] من اهتدى فاتبع طريق الحق فانما يعود ثواب ذلك عليه وحده، ومن حاد واتبع طريق الباطل فانما يعود عقاب ذلك عليه وحده، ولا تحمل نفس مذنبه اثم نفس مذنبه اخرى. ولا يعذب الله احدا الا بعد اقامه الحجه عليه بارسال الرسل وانزال الكتب."},{"id":"2045","s":17,"a":16,"at":"واذا اردنا ان نهلك قريه امرنا مترفيها ففسقوا فيها فحق عليها القول فدمرناها تدميرا","dt":"[16] واذا اردنا اهلاك اهل قريه لظلمهم امرنا مترفيهم بطاعه الله وتوحيده وتصديق رسله، وغيرهم تبع لهم، فعصوا امر ربهم وكذبوا رسله، فحق عليهم القول بالعذاب الذي لا مرد له، فاستاصلناهم بالهلاك التام."},{"id":"2046","s":17,"a":17,"at":"وكم اهلكنا من القرون من بعد نوح وكفى بربك بذنوب عباده خبيرا بصيرا","dt":"[17] وكثيرا اهلكنا من الامم المكذبه رسلها من بعد نبي الله نوح. وكفى بربك -ايها الرسول- انه عالم بجميع اعمال عباده، لا تخفى عليه خافيه."},{"id":"2047","s":17,"a":18,"at":"من كان يريد العاجله عجلنا له فيها ما نشاء لمن نريد ثم جعلنا له جهنم يصلاها مذموما مدحورا","dt":"[18] من كان طلبه الدنيا العاجله، وسعى لها وحدها، ولم يصدق بالاخره، ولم يعمل لها، عجل الله له فيها ما يشاؤه الله ويريده مما كتبه له في اللوح المحفوظ، ثم يجعل الله له في الاخره جهنم، يدخلها ملوما مطرودا من رحمته عز وجل؛ وذلك بسبب ارادته الدنيا وسعيه لها دون الاخره."},{"id":"2048","s":17,"a":19,"at":"ومن اراد الاخره وسعى لها سعيها وهو مؤمن فاولئك كان سعيهم مشكورا","dt":"[19] ومن قصد بعمله الصالح ثواب الدار الاخره الباقيه، وسعى لها بطاعه الله تعالى، وهو مؤمن بالله وثوابه وعظيم جزائه، فاولئك كان عملهم مقبولا مدخرا لهم عند ربهم، وسيثابون عليه."},{"id":"2049","s":17,"a":20,"at":"كلا نمد هؤلاء وهؤلاء من عطاء ربك وما كان عطاء ربك محظورا","dt":"[20] كل فريق من العاملين للدنيا الفانيه، والعاملين للاخره الباقيه نزيده من رزقنا، فنرزق المؤمنين والكافرين في الدنيا؛ فان الرزق من عطاء ربك تفضلا منه، وما كان عطاء ربك ممنوعا من احد مؤمنا كان ام كافرا."},{"id":"2050","s":17,"a":21,"at":"انظر كيف فضلنا بعضهم على بعض وللاخره اكبر درجات واكبر تفضيلا","dt":"[21] تامل -ايها الرسول- في كيفيه تفضيل الله بعض الناس على بعض في الدنيا في الرزق والعمل، وللاخره اكبر درجات للمؤمنين واكبر تفضيلا."},{"id":"2051","s":17,"a":22,"at":"لا تجعل مع الله الها اخر فتقعد مذموما مخذولا","dt":"[22] لا تجعل -ايها الانسان- مع الله شريكا له في عبادته، فتبوء بالمذمه والخذلان."},{"id":"2052","s":17,"a":23,"at":"وقضى ربك الا تعبدوا الا اياه وبالوالدين احسانا اما يبلغن عندك الكبر احدهما او كلاهما فلا تقل لهما اف ولا تنهرهما وقل لهما قولا كريما","dt":"[23] وامر ربك -ايها الانسان- والزم واوجب ان يفرد سبحانه وتعالى وحده بالعباده، وامر بالاحسان الى الاب والام، وبخاصه حاله الشيخوخه اذا كانا في رعايتك، فلا تضجر ولا تستثقل شيئا تراه من احدهما او منهما، ولا تسمعهما قولا سيئا، حتى ولا التافيف الذي هو ادنى مراتب القول السيئ، ولا يصدر منك اليهما فعل قبيح، ولكن ارفق بهما، وقل لهما -دائما- قولا لينا لطيفا."},{"id":"2053","s":17,"a":24,"at":"واخفض لهما جناح الذل من الرحمه وقل رب ارحمهما كما ربياني صغيرا","dt":"[24] وكن لامك وابيك ذليلا متواضعا رحمه بهما، واطلب من ربك ان يرحمهما برحمته الواسعه احياء وامواتا، كما صبرا على تربيتك طفلا ضعيف الحول والقوه."},{"id":"2054","s":17,"a":25,"at":"ربكم اعلم بما في نفوسكم ان تكونوا صالحين فانه كان للاوابين غفورا","dt":"[25] ربكم -ايها الناس- اعلم بما في ضمائركم من خير وشر. ان تكن ارادتكم ومقاصدكم مرضاه الله وما يقربكم اليه، فانه كان -سبحانه- للراجعين اليه في جميع الاوقات غفورا، فمن علم الله انه ليس في قلبه الا الانابه اليه ومحبته، فانه يعفو عنه، ويغفر له ما يعرض من صغائر الذنوب؛ مما هو من مقتضى الطبائع البشريه."},{"id":"2055","s":17,"a":26,"at":"وات ذا القربى حقه والمسكين وابن السبيل ولا تبذر تبذيرا","dt":"[26] واحسن الى كل من له صله قرابه بك، واعطه حقه من الاحسان والبر، واعط المسكين الذي لا يملك ما يكفيه ويسد حاجته، والمسافر المنقطع عن اهله وماله، ولا تنفق مالك في غير طاعه الله، او على وجه الاسراف والتبذير."},{"id":"2056","s":17,"a":27,"at":"ان المبذرين كانوا اخوان الشياطين وكان الشيطان لربه كفورا","dt":"[27] ان المسرفين والمنفقين اموالهم في معاصي الله هم اشباه الشياطين في الشر والفساد والمعصيه، وكان الشيطان كثير الكفران شديد الجحود لنعمه ربه."},{"id":"2057","s":17,"a":28,"at":"واما تعرضن عنهم ابتغاء رحمه من ربك ترجوها فقل لهم قولا ميسورا","dt":"[28] وان اعرضت عن اعطاء هؤلاء الذين امرت باعطائهم؛ لعدم وجود ما تعطيهم منه طلبا لرزق تنتظره من عند ربك، فقل لهم قولا لينا لطيفا، كالدعاء لهم بالغنى وسعه الرزق، وعدهم بان الله اذا ايسر من فضله رزقا انك تعطيهم منه."},{"id":"2058","s":17,"a":29,"at":"ولا تجعل يدك مغلوله الى عنقك ولا تبسطها كل البسط فتقعد ملوما محسورا","dt":"[29] ولا تمسك يدك عن الانفاق في سبيل الخير، مضيقا على نفسك واهلك والمحتاجين، ولا تسرف في الانفاق، فتعطي فوق طاقتك، فتقعد ملوما يلومك الناس ويذمونك، نادما على تبذيرك وضياع مالك."},{"id":"2059","s":17,"a":30,"at":"ان ربك يبسط الرزق لمن يشاء ويقدر انه كان بعباده خبيرا بصيرا","dt":"[30] ان ربك يوسع الرزق على بعض الناس، ويضيقه على بعضهم، وفق علمه وحكمته سبحانه وتعالى. انه هو المطلع على خفايا عباده، لا يغيب عن علمه شيء من احوالهم."},{"id":"2060","s":17,"a":31,"at":"ولا تقتلوا اولادكم خشيه املاق نحن نرزقهم واياكم ان قتلهم كان خطئا كبيرا","dt":"[31] واذا علمتم ان الرزق بيد الله سبحانه فلا تقتلوا -ايها الناس- اولادكم خوفا من الفقر؛ فانه -سبحانه- هو الرزاق لعباده، يرزق الابناء كما يرزق الاباء، ان قتل الاولاد ذنب عظيم."},{"id":"2061","s":17,"a":32,"at":"ولا تقربوا الزنا انه كان فاحشه وساء سبيلا","dt":"[32] ولا تقربوا الزنى ودواعيه؛ كي لا تقعوا فيه، انه كان فعلا بالغ القبح، وبئس الطريق طريقه."},{"id":"2062","s":17,"a":33,"at":"ولا تقتلوا النفس التي حرم الله الا بالحق ومن قتل مظلوما فقد جعلنا لوليه سلطانا فلا يسرف في القتل انه كان منصورا","dt":"[33] ولا تقتلوا النفس التي حرم الله قتلها الا بالحق الشرعي كالقصاص او رجم الزاني المحصن او قتل المرتد. ومن قتل بغير حق شرعي فقد جعلنا لولي امره من وارث او حاكم حجه في طلب قتل قاتله او الديه، ولا يصح لولي امر المقتول ان يجاوز حد الله في القصاص كان يقتل بالواحد اثنين او جماعه، او يمثل بالقاتل، ان الله معين ولي المقتول على القاتل حتى يتمكن من قتله قصاصا."},{"id":"2063","s":17,"a":34,"at":"ولا تقربوا مال اليتيم الا بالتي هي احسن حتى يبلغ اشده واوفوا بالعهد ان العهد كان مسئولا","dt":"[34] ولا تتصرفوا في اموال الاطفال الذين مات اباؤهم وهم دون سن البلوغ، وصاروا في كفالتكم، الا بالطريقه التي هي احسن لهم، وهي التثمير والتنميه، حتى يبلغ الطفل اليتيم سن البلوغ، وحسن التصرف في المال، واتموا الوفاء بكل عهد التزمتم به. ان العهد يسال الله عنه صاحبه يوم القيامه، فيثيبه اذا اتمه ووفاه، ويعاقبه اذا خان فيه."},{"id":"2064","s":17,"a":35,"at":"واوفوا الكيل اذا كلتم وزنوا بالقسطاس المستقيم ذلك خير واحسن تاويلا","dt":"[35] واتموا الكيل، ولا تنقصوه اذا كلتم لغيركم، وزنوا بالميزان السوي، ان العدل في الكيل والوزن خير لكم في الدنيا، واحسن عاقبه عند الله في الاخره."},{"id":"2065","s":17,"a":36,"at":"ولا تقف ما ليس لك به علم ان السمع والبصر والفؤاد كل اولئك كان عنه مسئولا","dt":"[36] ولا تتبع -ايها الانسان- ما لا تعلم، بل تاكد وتثبت. ان الانسان مسؤول عما استعمل فيه سمعه وبصره وفؤاده، فاذا استعملها في الخير نال الثواب، واذا استعملها في الشر نال العقاب."},{"id":"2066","s":17,"a":37,"at":"ولا تمش في الارض مرحا انك لن تخرق الارض ولن تبلغ الجبال طولا","dt":"[37] ولا تمش في الارض مختالا متكبرا؛ فانك لن تخرق الارض بمشيك عليها بهذه الصفه، ولن تبلغ الجبال طولا بخيلائك وفخرك وكبرك."},{"id":"2067","s":17,"a":38,"at":"كل ذلك كان سيئه عند ربك مكروها","dt":"[38] جميع ما تقدم ذكره من اوامر ونواه، يكره الله سيئه، ولا يرضاه لعباده."},{"id":"2068","s":17,"a":39,"at":"ذلك مما اوحى اليك ربك من الحكمه ولا تجعل مع الله الها اخر فتلقى في جهنم ملوما مدحورا","dt":"[39] ذلك الذي بيناه ووضحناه من هذه الاحكام الجليله، من الامر بمحاسن الاعمال، والنهي عن اراذل الاخلاق مما اوحيناه اليك ايها النبي. ولا تجعل -ايها الانسان- مع الله تعالى شريكا له في عبادته، فتقذف في نار جهنم تلومك نفسك والناس، وتكون مطرودا مبعدا من كل خير."},{"id":"2069","s":17,"a":40,"at":"افاصفاكم ربكم بالبنين واتخذ من الملائكه اناثا انكم لتقولون قولا عظيما","dt":"[40] افخصكم ربكم -ايها المشركون- باعطائكم البنين، واتخذ لنفسه الملائكه بنات؟ ان قولكم هذا بالغ القبح والبشاعه، لا يليق بالله سبحانه وتعالى."},{"id":"2070","s":17,"a":41,"at":"ولقد صرفنا في هذا القران ليذكروا وما يزيدهم الا نفورا","dt":"[41] ولقد وضحنا ونوعنا في هذا القران الاحكام والامثال والمواعظ؛ ليتعظ الناس ويتدبروا ما ينفعهم فياخذوه، وما يضرهم فيدعوه، وما يزيد البيان والتوضيح الظالمين الا تباعدا عن الحق، وغفله عن النظر والاعتبار."},{"id":"2071","s":17,"a":42,"at":"قل لو كان معه الهه كما يقولون اذا لابتغوا الى ذي العرش سبيلا","dt":"[42] قل -ايها الرسول- للمشركين: لو ان مع الله الهه اخرى، اذا لطلبت تلك الالهه طريقا الى مغالبه الله ذي العرش العظيم."},{"id":"2072","s":17,"a":43,"at":"سبحانه وتعالى عما يقولون علوا كبيرا","dt":"[43] تنزه الله وتقدس عما يقوله المشركون وتعالى علوا كبيرا."},{"id":"2073","s":17,"a":44,"at":"تسبح له السموات السبع والارض ومن فيهن وان من شيء الا يسبح بحمده ولكن لا تفقهون تسبيحهم انه كان حليما غفورا","dt":"[44] تسبح له -سبحانه- السموات السبع والارضون، ومن فيهن من جميع المخلوقات، وكل شيء في هذا الوجود ينزه الله تعالى تنزيها مقرونا بالثناء والحمد له سبحانه، ولكن لا تدركون -ايها الناس- ذلك. انه سبحانه كان حليما بعباده لا يعاجل من عصاه بالعقوبه، غفورا لهم."},{"id":"2074","s":17,"a":45,"at":"واذا قرات القران جعلنا بينك وبين الذين لا يؤمنون بالاخره حجابا مستورا","dt":"[45] واذا قرات القران فسمعه هؤلاء المشركون، جعلنا بينك وبين الذين لا يؤمنون بالاخره حجابا ساترا يحجب عقولهم عن فهم القران؛ عقابا لهم على كفرهم وانكارهم."},{"id":"2075","s":17,"a":46,"at":"وجعلنا على قلوبهم اكنه ان يفقهوه وفي اذانهم وقرا واذا ذكرت ربك في القران وحده ولوا على ادبارهم نفورا","dt":"[46] وجعلنا على قلوب المشركين اغطيه؛ لئلا يفهموا القران، وجعلنا في اذانهم صمما؛ لئلا يسمعوه، واذا ذكرت ربك في القران داعيا لتوحيده ناهيا عن الشرك به رجعوا على اعقابهم نافرين من قولك؛ استكبارا واستعظاما من ان يوحدوا الله تعالى في عبادته."},{"id":"2076","s":17,"a":47,"at":"نحن اعلم بما يستمعون به اذ يستمعون اليك واذ هم نجوى اذ يقول الظالمون ان تتبعون الا رجلا مسحورا","dt":"[47] نحن اعلم بالذي يستمع به رؤساء قريش، اذ يستمعون اليك ومقاصدهم سيئه، فليس استماعهم لاجل الاسترشاد وقبول الحق، ونعلم تناجيهم حين يقولون: ما تتبعون الا رجلا اصابه السحر فاختلط عقله."},{"id":"2077","s":17,"a":48,"at":"انظر كيف ضربوا لك الامثال فضلوا فلا يستطيعون سبيلا","dt":"[48] تفكر -ايها الرسول- متعجبا من قولهم: ان محمدا ساحر شاعر مجنون ! فجاروا وانحرفوا، ولم يهتدوا الى طريق الحق والصواب."},{"id":"2078","s":17,"a":49,"at":"وقالوا ائذا كنا عظاما ورفاتا ائنا لمبعوثون خلقا جديدا","dt":"[49] وقال المشركون منكرين ان يخلقوا خلقا جديدا بعد ان تبلى عظامهم، وتصير فتاتا: ائنا لمبعوثون يوم القيامه بعثا جديدا؟"},{"id":"2079","s":17,"a":50,"at":"قل كونوا حجاره او حديدا","dt":"[50] قل لهم -ايها الرسول- على جهه التعجيز: كونوا حجاره او حديدا في الشده والقوه، ان قدرتم على ذلك."},{"id":"2080","s":17,"a":51,"at":"او خلقا مما يكبر في صدوركم فسيقولون من يعيدنا قل الذي فطركم اول مره فسينغضون اليك رءوسهم ويقولون متى هو قل عسى ان يكون قريبا","dt":"[51] او كونوا خلقا يعظم ويستبعد في عقولكم قبوله، فسيقولون -منكرين-: من يردنا الى الحياه بعد الموت؟ قل لهم: يعيدكم ويرجعكم الله الذي انشاكم من العدم اول مره، وعند سماعهم هذا الرد فسيهزون رؤوسهم ساخرين متعجبين ويقولون -مستبعدين-: متى يقع هذا البعث؟ قل: وما يدريكم ان هذا البعث الذي تنكرونه وتستبعدونه ربما كان قريب الوقوع؟"},{"id":"2081","s":17,"a":52,"at":"يوم يدعوكم فتستجيبون بحمده وتظنون ان لبثتم الا قليلا","dt":"[52] يوم يناديكم خالقكم للخروج من قبوركم، فتستجيبون لامر الله، وتنقادون له، وله الحمد على كل حال، وتظنون -لهول يوم القيامه- انكم ما اقمتم في الدنيا الا زمنا قليلا؛ لطول لبثكم في الاخره."},{"id":"2082","s":17,"a":53,"at":"وقل لعبادي يقولوا التي هي احسن ان الشيطان ينزغ بينهم ان الشيطان كان للانسان عدوا مبينا","dt":"[53] وقل لعبادي المؤمنين يقولوا في تخاطبهم وتحاورهم الكلام الحسن الطيب؛ فانهم ان لم يفعلوا ذلك القى الشيطان بينهم العداوه والفساد والخصام. ان الشيطان كان للانسان عدوا ظاهر العداوه."},{"id":"2083","s":17,"a":54,"at":"ربكم اعلم بكم ان يشا يرحمكم او ان يشا يعذبكم وما ارسلناك عليهم وكيلا","dt":"[54] ربكم اعلم بكم -ايها الناس- ان يشا يرحمكم فيوفقكم للايمان، او ان يشا يمتكم على الكفر فيعذبكم، وما ارسلناك -ايها الرسول- عليهم وكيلا، تدبر امرهم وتجازيهم على افعالهم، وانما مهمتك تبليغ ما ارسلت به، وبيان الصراط المستقيم."},{"id":"2084","s":17,"a":55,"at":"وربك اعلم بمن في السموات والارض ولقد فضلنا بعض النبيين على بعض واتينا داود زبورا","dt":"[55] وربك -ايها الرسول- اعلم بمن في السموات والارض. ولقد فضلنا بعض النبيين على بعض بالفضائل وكثره الاتباع وانزال الكتب، واعطينا داود عليه السلام الزبور."},{"id":"2085","s":17,"a":56,"at":"قل ادعوا الذين زعمتم من دونه فلا يملكون كشف الضر عنكم ولا تحويلا","dt":"[56] قل -ايها الرسول- لمشركي قومك: ان هذه المعبودات التي تنادونها لكشف الضر عنكم لا تملك ذلك، ولا تقدر على تحويله عنكم الى غيركم، ولا تقدر على تحويله من حال الى حال، فالقادر على ذلك هو الله وحده. وهذه الايه عامه في كل ما يدعى من دون الله، ميتا كان او غائبا، من الانبياء والصالحين وغيرهم، بلفظ الاستغاثه او الدعاء او غيرهما، فلا معبود بحق الا الله."},{"id":"2086","s":17,"a":57,"at":"اولئك الذين يدعون يبتغون الى ربهم الوسيله ايهم اقرب ويرجون رحمته ويخافون عذابه ان عذاب ربك كان محذورا","dt":"[57] اولئك الذين يدعوهم المشركون، من الانبياء والصالحين والملائكه مع الله، يتنافسون في القرب من ربهم بما يقدرون عليه من الاعمال الصالحه، وياملون رحمته ويخافون عذابه، ان عذاب ربك هو ما ينبغي ان يحذره العباد، ويخافوا منه."},{"id":"2087","s":17,"a":58,"at":"وان من قريه الا نحن مهلكوها قبل يوم القيامه او معذبوها عذابا شديدا كان ذلك في الكتاب مسطورا","dt":"[58] ويتوعد الله الكفار بانه ما من قريه كافره مكذبه للرسل الا وسينزل بها عقابه بالهلاك في الدنيا قبل يوم القيامه، او بالعذاب الشديد لاهلها، كتاب كتبه الله وقضاء ابرمه لابد من وقوعه، وهو مسطور في اللوح المحفوظ."},{"id":"2088","s":17,"a":59,"at":"وما منعنا ان نرسل بالايات الا ان كذب بها الاولون واتينا ثمود الناقه مبصره فظلموا بها وما نرسل بالايات الا تخويفا","dt":"[59] وما منعنا من انزال المعجزات التي سالها المشركون الا تكذيب من سبقهم من الامم، فقد اجابهم الله الى ما طلبوا فكذبوا وهلكوا. واعطينا ثمود -وهم قوم صالح- معجزه واضحه وهي الناقه، فكفروا بها فاهلكناهم. وما ارسالنا الرسل بالايات والعبر والمعجزات التي جعلناها على ايديهم الا تخويف للعباد؛ ليعتبروا ويتذكروا."},{"id":"2089","s":17,"a":60,"at":"واذ قلنا لك ان ربك احاط بالناس وما جعلنا الرؤيا التي اريناك الا فتنه للناس والشجره الملعونه في القران ونخوفهم فما يزيدهم الا طغيانا كبيرا","dt":"[60] واذكر -ايها الرسول- حين قلنا لك: ان ربك احاط بالناس علما وقدره. وما جعلنا الرؤيا التي اريناكها عيانا ليله الاسراء والمعراج من عجائب المخلوقات، الا اختبارا للناس؛ ليتميز كافرهم من مؤمنهم، وما جعلنا شجره الزقوم الملعونه التي ذكرت في القران الا ابتلاء للناس. ونخوف المشركين بانواع العذاب والايات، ولا يزيدهم التخويف الا تماديا في الكفر والضلال."},{"id":"2090","s":17,"a":61,"at":"واذ قلنا للملائكه اسجدوا لادم فسجدوا الا ابليس قال ااسجد لمن خلقت طينا","dt":"[61] واذكر قولنا للملائكه: اسجدوا لادم تحيه وتكريما، فسجدوا جميعا الا ابليس، استكبر وامتنع عن السجود قائلا على سبيل الانكار والاستكبار: ااسجد لهذا الضعيف، المخلوق من الطين؟"},{"id":"2091","s":17,"a":62,"at":"قال ارايتك هذا الذي كرمت علي لئن اخرتني الى يوم القيامه لاحتنكن ذريته الا قليلا","dt":"[62] وقال ابليس جراءه على الله وكفرا به: ارايت هذا المخلوق الذي ميزته علي؟ لئن ابقيتني حيا الى يوم القيامه لاستولين على ذريته بالاغواء والافساد، الا المخلصين منهم في الايمان، وهم قليل."},{"id":"2092","s":17,"a":63,"at":"قال اذهب فمن تبعك منهم فان جهنم جزاؤكم جزاء موفورا","dt":"[63] قال الله تعالى مهددا ابليس واتباعه: اذهب فمن تبعك من ذريه ادم فاطاعك، فان عقابك وعقابهم وافر في نار جهنم."},{"id":"2093","s":17,"a":64,"at":"واستفزز من استطعت منهم بصوتك واجلب عليهم بخيلك ورجلك وشاركهم في الاموال والاولاد وعدهم وما يعدهم الشيطان الا غرورا","dt":"[64] واستخفف كل من تستطيع استخفافه منهم بدعوتك اياه الى معصيتي، واجمع عليهم كل ما تقدر عليه من جنودك من كل راكب وراجل، واجعل لنفسك شركه في اموالهم بان يكسبوها من الحرام وينفقوها فيه، وشركه في الاولاد بتزيين الزنى والمعاصي، ومخالفه اوامر الله حتى يكثر الفجور والفساد، وعد اتباعك من ذريه ادم الوعود الكاذبه، فكل وعود الشيطان باطله وغرور."},{"id":"2094","s":17,"a":65,"at":"ان عبادي ليس لك عليهم سلطان وكفى بربك وكيلا","dt":"[65] ان عبادي المؤمنين المخلصين الذين اطاعوني ليس لك قدره على اغوائهم، وكفى بربك -ايها النبي- عاصما وحافظا للمؤمنين من كيد الشيطان وغروره."},{"id":"2095","s":17,"a":66,"at":"ربكم الذي يزجي لكم الفلك في البحر لتبتغوا من فضله انه كان بكم رحيما","dt":"[66] ربكم -ايها الناس- هو الذي يسير لكم السفن في البحر؛ لتطلبوا رزق الله في اسفاركم وتجاراتكم. ان الله سبحانه كان رحيما بعباده."},{"id":"2096","s":17,"a":67,"at":"واذا مسكم الضر في البحر ضل من تدعون الا اياه فلما نجاكم الى البر اعرضتم وكان الانسان كفورا","dt":"[67] واذا اصابتكم شده في البحر حتى اشرفتم على الغرق والهلاك، غاب عن عقولكم الذين تعبدونهم من الالهه، وتذكرتم الله القدير وحده؛ ليغيثكم وينقذكم، فاخلصتم له في طلب العون والاغاثه، فاغاثكم ونجاكم، فلما نجاكم الى البر اعرضتم عن الايمان والاخلاص والعمل الصالح، وهذا من جهل الانسان وكفره. وكان الانسان جحودا لنعم الله عز وجل."},{"id":"2097","s":17,"a":68,"at":"افامنتم ان يخسف بكم جانب البر او يرسل عليكم حاصبا ثم لا تجدوا لكم وكيلا","dt":"[68] اغفلتم -ايها الناس- عن عذاب الله، فامنتم ان تنهار بكم الارض خسفا، او يمطركم الله بحجاره من السماء فتقتلكم، ثم لا تجدوا احدا يحفظكم من عذابه؟"},{"id":"2098","s":17,"a":69,"at":"ام امنتم ان يعيدكم فيه تاره اخرى فيرسل عليكم قاصفا من الريح فيغرقكم بما كفرتم ثم لا تجدوا لكم علينا به تبيعا","dt":"[69] ام امنتم -ايها الناس- ربكم، وقد كفرتم به ان يعيدكم في البحر مره اخرى، فيرسل عليكم ريحا شديده، تكسر كل ما اتت عليه، فيغرقكم بسبب كفركم، ثم لا تجدوا لكم علينا اي تبعه ومطالبه؛ فان الله لم يظلمكم مثقال ذره؟"},{"id":"2099","s":17,"a":70,"at":"ولقد كرمنا بني ادم وحملناهم في البر والبحر ورزقناهم من الطيبات وفضلناهم على كثير ممن خلقنا تفضيلا","dt":"[70] ولقد كرمنا ذريه ادم بالعقل وارسال الرسل، وسخرنا لهم جميع ما في الكون، وسخرنا لهم الدواب في البر والسفن في البحر لحملهم، ورزقناهم من طيبات المطاعم والمشارب، وفضلناهم على كثير من المخلوقات تفضيلا عظيما."},{"id":"2100","s":17,"a":71,"at":"يوم ندعوا كل اناس بامامهم فمن اوتي كتابه بيمينه فاولئك يقرءون كتابهم ولا يظلمون فتيلا","dt":"[71] اذكر -ايها الرسول- يوم البعث مبشرا ومخوفا، حين يدعو الله عز وجل كل جماعه من الناس مع امامهم الذي كانوا يقتدون به في الدنيا، فمن كان منهم صالحا، واعطي كتاب اعماله بيمينه، فهؤلاء يقرؤون كتاب حسناتهم فرحين مستبشرين، ولا ينقصون من ثواب اعمالهم الصالحه شيئا، وان كان مقدار الخيط الذي يكون في شق النواه."},{"id":"2101","s":17,"a":72,"at":"ومن كان في هذه اعمى فهو في الاخره اعمى واضل سبيلا","dt":"[72] ومن كان في هذه الدنيا اعمى القلب عن دلائل قدره الله فلم يؤمن بما جاء به الرسول محمد -صلى الله عليه وسلم- فهو في يوم القيامه اشد عمى عن سلوك طريق الجنه، واضل طريقا عن الهدايه والرشاد."},{"id":"2102","s":17,"a":73,"at":"وان كادوا ليفتنونك عن الذي اوحينا اليك لتفتري علينا غيره واذا لاتخذوك خليلا","dt":"[73] ولقد قارب المشركون ان يصرفوك -ايها الرسول- عن القران الذي انزله الله اليك؛ لتختلق علينا غير ما اوحينا اليك، ولو فعلت ما ارادوه لاتخذوك حبيبا خالصا."},{"id":"2103","s":17,"a":74,"at":"ولولا ان ثبتناك لقد كدت تركن اليهم شيئا قليلا","dt":"[74] ولولا ان ثبتناك على الحق، وعصمناك عن موافقتهم، لقاربت ان تميل اليهم شيئا من الميل فيما اقترحوه عليك؛ لقوه خداعهم وشده احتيالهم، ولرغبتك في هدايتهم."},{"id":"2104","s":17,"a":75,"at":"اذا لاذقناك ضعف الحياه وضعف الممات ثم لا تجد لك علينا نصيرا","dt":"[75] ولو ركنت -ايها الرسول- الى هؤلاء المشركين ركونا قليلا فيما سالوك، اذا لاذقناك مثلي عذاب الحياه في الدنيا ومثلي عذاب الممات في الاخره؛ وذلك لتمام نعمه الله عليك وكمال معرفتك بربك، ثم لا تجد احدا ينصرك ويدفع عنك عذابنا."},{"id":"2105","s":17,"a":76,"at":"وان كادوا ليستفزونك من الارض ليخرجوك منها واذا لا يلبثون خلافك الا قليلا","dt":"[76] ولقد قارب الكفار ان يخرجوك من «مكه» بازعاجهم اياك، ولو اخرجوك منها لم يمكثوا فيها بعدك الا زمنا قليلا، حتى تحل بهم العقوبه العاجله."},{"id":"2106","s":17,"a":77,"at":"سنه من قد ارسلنا قبلك من رسلنا ولا تجد لسنتنا تحويلا","dt":"[77] تلك سنه الله تعالى في اهلاك الامه التي تخرج رسولها من بينها، ولن تجد -ايها الرسول- لسنتنا تغييرا، فلا خلف في وعدنا."},{"id":"2107","s":17,"a":78,"at":"اقم الصلاه لدلوك الشمس الى غسق الليل وقران الفجر ان قران الفجر كان مشهودا","dt":"[78] اقم الصلاه تامه من وقت زوال الشمس عند الظهيره الى وقت ظلمه الليل، ويدخل في هذا صلاه الظهر والعصر والمغرب والعشاء، واقم صلاه الفجر، واطل القراءه فيها؛ ان صلاه الفجر تحضرها ملائكه الليل وملائكه النهار."},{"id":"2108","s":17,"a":79,"at":"ومن الليل فتهجد به نافله لك عسى ان يبعثك ربك مقاما محمودا","dt":"[79] وقم -ايها النبي- من نومك بعض الليل، فاقرا القران في صلاه الليل؛ لتكون صلاه الليل زياده لك في علو القدر ورفع الدرجات، عسى ان يبعثك الله شافعا للناس يوم القيامه؛ ليرحمهم الله مما يكونون فيه، وتقوم مقاما يحمدك فيه الاولون والاخرون."},{"id":"2109","s":17,"a":80,"at":"وقل رب ادخلني مدخل صدق واخرجني مخرج صدق واجعل لي من لدنك سلطانا نصيرا","dt":"[80] وقل: رب ادخلني فيما هو خير لي مدخل صدق، واخرجني مما هو شر لي مخرج صدق، واجعل لي من لدنك حجه ثابته، تنصرني بها على جميع من خالفني."},{"id":"2110","s":17,"a":81,"at":"وقل جاء الحق وزهق الباطل ان الباطل كان زهوقا","dt":"[81] وقل -ايها الرسول- للمشركين: جاء الاسلام وذهب الشرك، ان الباطل لا بقاء له ولا ثبات، والحق هو الثابت الباقي الذي لا يزول."},{"id":"2111","s":17,"a":82,"at":"وننزل من القران ما هو شفاء ورحمه للمؤمنين ولا يزيد الظالمين الا خسارا","dt":"[82] وننزل من ايات القران العظيم ما يشفي القلوب من الامراض، كالشك والنفاق والجهاله، وما يشفي الابدان برقيتها به، وما يكون سببا للفوز برحمه الله بما فيه من الايمان، ولا يزيد هذا القران الكفار عند سماعه الا كفرا وضلالا؛ لتكذيبهم به وعدم ايمانهم."},{"id":"2112","s":17,"a":83,"at":"واذا انعمنا على الانسان اعرض وناى بجانبه واذا مسه الشر كان يئوسا","dt":"[83] واذا انعمنا على الانسان من حيث هو بمال وعافيه ونحوهما، تولى وتباعد عن طاعه ربه، واذا اصابته شده من فقر او مرض كان قنوطا؛ لانه لا يثق بفضل الله تعالى، الا من عصم الله في حالتي سرائه وضرائه."},{"id":"2113","s":17,"a":84,"at":"قل كل يعمل على شاكلته فربكم اعلم بمن هو اهدى سبيلا","dt":"[84] قل -ايها الرسول- للناس: كل واحد منكم يعمل على ما يليق به من الاحوال، فربكم اعلم بمن هو اهدى طريقا الى الحق."},{"id":"2114","s":17,"a":85,"at":"ويسالونك عن الروح قل الروح من امر ربي وما اوتيتم من العلم الا قليلا","dt":"[85] ويسالك الكفار عن حقيقه الروح تعنتا، فاجبهم بان حقيقه الروح واحوالها من الامور التي استاثر الله بعلمها، وما اعطيتم انتم وجميع الناس من العلم الا شيئا قليلا."},{"id":"2115","s":17,"a":86,"at":"ولئن شئنا لنذهبن بالذي اوحينا اليك ثم لا تجد لك به علينا وكيلا","dt":"[86] ولئن شئنا محو القران من قلبك لقدرنا على ذلك، ثم لا تجد لنفسك ناصرا يمنعنا من فعل ذلك، او يرد عليك القران."},{"id":"2116","s":17,"a":87,"at":"الا رحمه من ربك ان فضله كان عليك كبيرا","dt":"[87] لكن الله رحمك، فاثبت ذلك في قلبك، ان فضله كان عليك عظيما؛ فقد اعطاك هذا القران العظيم، والمقام المحمود، وغير ذلك مما لم يؤته احدا من العالمين."},{"id":"2117","s":17,"a":88,"at":"قل لئن اجتمعت الانس والجن على ان ياتوا بمثل هذا القران لا ياتون بمثله ولو كان بعضهم لبعض ظهيرا","dt":"[88] قل: لو اتفقت الانس والجن على محاوله الاتيان بمثل هذا القران المعجز لا يستطيعون الاتيان بمثل بلاغته ومعانيه واحكامه، ولو تعاونوا وتظاهروا على ذلك."},{"id":"2118","s":17,"a":89,"at":"ولقد صرفنا للناس في هذا القران من كل مثل فابى اكثر الناس الا كفورا","dt":"[89] ولقد بينا ونوعنا للناس في هذا القران من كل مثل ينبغي الاعتبار به؛ احتجاجا بذلك عليهم؛ ليتبعوه ويعملوا به، فابى اكثر الناس الا جحودا للحق وانكارا لحجج الله وادلته."},{"id":"2119","s":17,"a":90,"at":"وقالوا لن نؤمن لك حتى تفجر لنا من الارض ينبوعا","dt":"[90] ولما اعجز القران المشركين وغلبهم اخذوا يطلبون معجزات وفق اهوائهم فقالوا: لن نصدقك -يا محمد- ونعمل بما تقول حتى تفجر لنا من ارض «مكه» عينا جاريه."},{"id":"2120","s":17,"a":91,"at":"او تكون لك جنه من نخيل وعنب فتفجر الانهار خلالها تفجيرا","dt":"[91] او تكون لك حديقه فيها انواع النخيل والاعناب، وتجعل الانهار تجري في وسطها بغزاره."},{"id":"2121","s":17,"a":92,"at":"او تسقط السماء كما زعمت علينا كسفا او تاتي بالله والملائكه قبيلا","dt":"[92] او تسقط السماء علينا قطعا كما زعمت، او تاتي لنا بالله وملائكته، فنشاهدهم مقابله وعيانا."},{"id":"2122","s":17,"a":93,"at":"او يكون لك بيت من زخرف او ترقى في السماء ولن نؤمن لرقيك حتى تنزل علينا كتابا نقرؤه قل سبحان ربي هل كنت الا بشرا رسولا","dt":"[93] او يكون لك بيت من ذهب، او تصعد في درج الى السماء، ولن نصدقك في صعودك حتى تعود، ومعك كتاب من الله منشور نقرا فيه انك رسول الله حقا. قل -ايها الرسول- متعجبا من تعنت هؤلاء الكفار: سبحان ربي! هل انا الا عبد من عباده مبلغ رسالته؟ فكيف اقدر على فعل ما تطلبون؟"},{"id":"2123","s":17,"a":94,"at":"وما منع الناس ان يؤمنوا اذ جاءهم الهدى الا ان قالوا ابعث الله بشرا رسولا","dt":"[94] وما منع الكفار من الايمان بالله ورسوله وطاعتهما، حين جاءهم البيان الكافي من عند الله، الا قولهم جهلا وانكارا: ابعث الله رسولا من جنس البشر؟"},{"id":"2124","s":17,"a":95,"at":"قل لو كان في الارض ملائكه يمشون مطمئنين لنزلنا عليهم من السماء ملكا رسولا","dt":"[95] قل -ايها الرسول- ردا على المشركين انكارهم ان يكون الرسول من البشر: لو كان في الارض ملائكه يمشون عليها، ساكنين فيها، لارسلنا اليهم رسولا من جنسهم، ولكن اهل الارض بشر، فالرسول اليهم ينبغي ان يكون من جنسهم؛ ليمكنهم مخاطبته وفهم كلامه."},{"id":"2125","s":17,"a":96,"at":"قل كفى بالله شهيدا بيني وبينكم انه كان بعباده خبيرا بصيرا","dt":"[96] قل لهم: كفى بالله شهيدا بيني وبينكم على صدقي وحقيقه نبوتي. انه سبحانه خبير باحوال عباده، بصير باعمالهم، وسيجازيهم عليها."},{"id":"2126","s":17,"a":97,"at":"ومن يهد الله فهو المهتد ومن يضلل فلن تجد لهم اولياء من دونه ونحشرهم يوم القيامه على وجوههم عميا وبكما وصما ماواهم جهنم كلما خبت زدناهم سعيرا","dt":"[97] ومن يهده الله فهو المهتدي الى الحق، ومن يضلله فيخذله ويكله الى نفسه فلا هادي له من دون الله، وهؤلاء الضلال يبعثهم الله يوم القيامه، ويحشرهم على وجوههم، وهم لا يرون ولا ينطقون ولا يسمعون، مصيرهم الى نار جهنم الملتهبه، كلما سكن لهيبها، وخمدت نارها، زدناهم نارا ملتهبه متاججه."},{"id":"2127","s":17,"a":98,"at":"ذلك جزاؤهم بانهم كفروا باياتنا وقالوا ائذا كنا عظاما ورفاتا ائنا لمبعوثون خلقا جديدا","dt":"[98] هذا الذي وصف من العذاب عقاب للمشركين؛ بسبب كفرهم بايات الله وحججه، وتكذيبهم رسله الذين دعوهم الى عبادته، وقولهم استنكارا -اذا امروا بالتصديق بالبعث-: ااذا متنا وصرنا عظاما باليه واجزاء متفتته نبعث بعد ذلك خلقا جديدا؟"},{"id":"2128","s":17,"a":99,"at":"او لم يروا ان الله الذي خلق السموات والارض قادر على ان يخلق مثلهم وجعل لهم اجلا لا ريب فيه فابى الظالمون الا كفورا","dt":"[99] اغفل هؤلاء المشركون، فلم يتبصروا ويعلموا ان الله الذي خلق السموات والارض وما فيهن من المخلوقات على غير مثال سابق، قادر على ان يخلق امثالهم بعد فنائهم؟ وقد جعل الله لهؤلاء المشركين وقتا محددا لموتهم وعذابهم، لا شك انه اتيهم، ومع وضوح الحق ودلائله ابى الكافرون الا جحودا لدين الله عز وجل."},{"id":"2129","s":17,"a":100,"at":"قل لو انتم تملكون خزائن رحمه ربي اذا لامسكتم خشيه الانفاق وكان الانسان قتورا","dt":"[100] قل -ايها الرسول- لهؤلاء المشركين: لو كنتم تملكون خزائن رحمه ربي التي لا تنفد ولا تبيد اذا لبخلتم بها، فلم تعطوا منها غيركم خوفا من نفادها فتصبحوا فقراء. ومن شان الانسان انه بخيل بما في يده الا من عصم الله بالايمان."},{"id":"2130","s":17,"a":101,"at":"ولقد اتينا موسى تسع ايات بينات فاسال بني اسرائيل اذ جاءهم فقال له فرعون اني لاظنك ياموسى مسحورا","dt":"[101] ولقد اتينا موسى تسع معجزات واضحات شاهدات على صدق نبوته وهي: العصا واليد والسنون ونقص الثمرات والطوفان والجراد والقمل والضفادع والدم، فاسال -ايها الرسول- اليهود سؤال تقرير حين جاء موسى اسلافهم بمعجزاته الواضحات، فقال فرعون لموسى: اني لاظنك -يا موسى- ساحرا، مخدوعا مغلوبا على عقلك بما تاتيه من غرائب الافعال."},{"id":"2131","s":17,"a":102,"at":"قال لقد علمت ما انزل هؤلاء الا رب السموات والارض بصائر واني لاظنك يافرعون مثبورا","dt":"[102] فرد عليه موسى: لقد تيقنت -يا فرعون- انه ما انزل تلك المعجزات التسع الشاهده على صدق نبوتي الا رب السموات والارض؛ لتكون دلالات يستدل بها اولو البصائر على وحدانيه الله تعالى في ربوبيته والوهيته، واني لعلى يقين انك -يا فرعون- هالك ملعون مغلوب."},{"id":"2132","s":17,"a":103,"at":"فاراد ان يستفزهم من الارض فاغرقناه ومن معه جميعا","dt":"[103] فاراد فرعون ان يزعج موسى ويخرجه مع بني اسرائيل من ارض «مصر»، فاغرقناه ومن معه من جند في البحر عقابا لهم."},{"id":"2133","s":17,"a":104,"at":"وقلنا من بعده لبني اسرائيل اسكنوا الارض فاذا جاء وعد الاخره جئنا بكم لفيفا","dt":"[104] وقلنا من بعد هلاك فرعون وجنده لبني اسرائيل: اسكنوا ارض «الشام»، فاذا جاء يوم القيامه جئنا بكم جميعا من قبوركم الى موقف الحساب."},{"id":"2134","s":17,"a":105,"at":"وبالحق انزلناه وبالحق نزل وما ارسلناك الا مبشرا ونذيرا","dt":"[105] وبالحق انزلنا هذا القران على محمد -صلى الله عليه وسلم- لامر العباد ونهيهم وثوابهم وعقابهم، وبالصدق والعدل والحفظ من التغيير والتبديل نزل. وما ارسلناك -ايها الرسول- الا مبشرا بالجنه لمن اطاع، ومخوفا بالنار لمن عصى وكفر."},{"id":"2135","s":17,"a":106,"at":"وقرانا فرقناه لتقراه على الناس على مكث ونزلناه تنزيلا","dt":"[106] وانزلنا اليك -ايها الرسول- قرانا بيناه واحكمناه وفصلناه فارقا بين الهدى والضلال والحق والباطل؛ لتقراه على الناس في تؤده وتمهل، ونزلناه مفرقا، شيئا بعد شيء، على حسب الحوادث ومقتضيات الاحوال."},{"id":"2136","s":17,"a":107,"at":"قل امنوا به او لا تؤمنوا ان الذين اوتوا العلم من قبله اذا يتلى عليهم يخرون للاذقان سجدا","dt":"[107] قل -ايها الرسول- لهؤلاء المكذبين: امنوا بالقران او لا تؤمنوا؛ فان ايمانكم لا يزيده كمالا، وتكذيبكم لا يلحق به نقصا. ان العلماء الذين اوتوا الكتب السابقه من قبل القران، وعرفوا حقيقه الوحي، اذا قرئ عليهم القران يخشعون، فيسجدون على وجوههم تعظيما لله تعالى، وشكرا له."},{"id":"2137","s":17,"a":108,"at":"ويقولون سبحان ربنا ان كان وعد ربنا لمفعولا","dt":"[108] ويقول هؤلاء الذين اوتوا العلم عند سماع القران: تنزيها لربنا وتبرئه له مما يصفه المشركون به، ما كان وعد الله تعالى من ثواب وعقاب الا واقعا حقا."},{"id":"2138","s":17,"a":109,"at":"ويخرون للاذقان يبكون ويزيدهم خشوعا","dt":"[109] ويقع هؤلاء ساجدين على وجوههم، يبكون تاثرا بمواعظ القران، ويزيدهم سماع القران ومواعظه خضوعا لامر الله وعظيم قدرته."},{"id":"2139","s":17,"a":110,"at":"قل ادعوا الله او ادعوا الرحمن ايا ما تدعوا فله الاسماء الحسنى ولا تجهر بصلاتك ولا تخافت بها وابتغ بين ذلك سبيلا","dt":"[110] قل -ايها الرسول- لمشركي قومك الذين انكروا عليك الدعاء بقولك: يا الله يا رحمن، ادعوا الله، او ادعوا الرحمن، فباي اسمائه دعوتموه فانكم تدعون ربا واحدا؛ لان اسماءه كلها حسنى. ولا تجهر بالقراءه في صلاتك، فيسمعك المشركون، ولا تسر بها فلا يسمعك اصحابك، وكن وسطا بين الجهر والهمس."},{"id":"2140","s":17,"a":111,"at":"وقل الحمد لله الذي لم يتخذ ولدا ولم يكن له شريك في الملك ولم يكن له ولي من الذل وكبره تكبيرا","dt":"[111] وقل -ايها الرسول-: الحمد لله الذي له الكمال والثناء، الذي تنزه عن الولد والشريك في الوهيته، ولا يكون له سبحانه ولي من خلقه فهو الغني القوي، وهم الفقراء المحتاجون اليه، وعظمه تعظيما تاما بالثناء عليه وعبادته وحده لا شريك له، واخلاص الدين كله له."},{"id":"2141","s":18,"a":1,"at":"الحمد لله الذي انزل على عبده الكتاب ولم يجعل له عوجا","dt":"[1] الثناء على الله بصفاته التي كلها اوصاف كمال، وبنعمه الظاهره والباطنه، الدينيه والدنيويه، الذي تفضل فانزل على عبده ورسوله محمد -صلى الله عليه وسلم- القران، ولم يجعل فيه شيئا من الميل عن الحق."},{"id":"2142","s":18,"a":2,"at":"قيما لينذر باسا شديدا من لدنه ويبشر المؤمنين الذين يعملون الصالحات ان لهم اجرا حسنا","dt":"[2] جعله الله كتابا مستقيما، لا اختلاف فيه ولا تناقض؛ لينذر الكافرين من عذاب شديد من عنده، ويبشر المصدقين بالله ورسوله الذين يعملون الاعمال الصالحات، بان لهم ثوابا جزيلا هو الجنه،"},{"id":"2143","s":18,"a":3,"at":"ماكثين فيه ابدا","dt":"[3] يقيمون في هذا النعيم لا يفارقونه ابدا."},{"id":"2144","s":18,"a":4,"at":"وينذر الذين قالوا اتخذ الله ولدا","dt":"[4] وينذر به المشركين الذين قالوا: اتخذ الله ولدا."},{"id":"2145","s":18,"a":5,"at":"ما لهم به من علم ولا لابائهم كبرت كلمه تخرج من افواههم ان يقولون الا كذبا","dt":"[5] ليس عند هؤلاء المشركين شيء من العلم على ما يدعونه لله من اتخاذ الولد، كما لم يكن عند اسلافهم الذين قلدوهم، عظمت هذه المقاله الشنيعه التي تخرج من افواههم، ما يقولون الا قولا كاذبا."},{"id":"2146","s":18,"a":6,"at":"فلعلك باخع نفسك على اثارهم ان لم يؤمنوا بهذا الحديث اسفا","dt":"[6] فلعلك -ايها الرسول- مهلك نفسك غما وحزنا على اثر تولي قومك واعراضهم عنك، ان لم يصدقوا بهذا القران ويعملوا به."},{"id":"2147","s":18,"a":7,"at":"انا جعلنا ما على الارض زينه لها لنبلوهم ايهم احسن عملا","dt":"[7] انا جعلنا ما على وجه الارض من المخلوقات جمالا لها، ومنفعه لاهلها؛ لنختبرهم: ايهم احسن عملا بطاعتنا، وايهم اسوا عملا بالمعاصي، ونجزي كلا بما يستحق."},{"id":"2148","s":18,"a":8,"at":"وانا لجاعلون ما عليها صعيدا جرزا","dt":"[8] وانا لجاعلون ما على الارض من تلك الزينه عند انقضاء الدنيا ترابا، لا نبات فيه."},{"id":"2149","s":18,"a":9,"at":"ام حسبت ان اصحاب الكهف والرقيم كانوا من اياتنا عجبا","dt":"[9] لا تظن -ايها الرسول- ان قصه اصحاب الكهف واللوح الذي كتبت فيه اسماؤهم من اياتنا عجيبه وغريبه؛ فان خلق السموات والارض وما فيهما اعجب من ذلك."},{"id":"2150","s":18,"a":10,"at":"اذ اوى الفتيه الى الكهف فقالوا ربنا اتنا من لدنك رحمه وهيئ لنا من امرنا رشدا","dt":"[10] اذكر -ايها الرسول- حين لجا الشبان المؤمنون الى الكهف؛ خشيه من فتنه قومهم لهم، وارغامهم على عباده الاصنام، فقالوا: ربنا اعطنا من عندك رحمه، تثبتنا بها، وتحفظنا من الشر، ويسر لنا الطريق الصواب الذي يوصلنا الى العمل الذي تحب، فنكون راشدين غير ضالين."},{"id":"2151","s":18,"a":11,"at":"فضربنا على اذانهم في الكهف سنين عددا","dt":"[11] فالقينا عليهم النوم العميق، فبقوا في الكهف سنين كثيره."},{"id":"2152","s":18,"a":12,"at":"ثم بعثناهم لنعلم اي الحزبين احصى لما لبثوا امدا","dt":"[12] ثم ايقظناهم من نومهم؛ لنظهر للناس ما علمناه في الازل؛ فتتميز اي الطائفتين المتنازعتين في مده لبثهم اضبط في الاحصاء، وهل لبثوا يوما او بعض يوم، او مده طويله؟"},{"id":"2153","s":18,"a":13,"at":"نحن نقص عليك نباهم بالحق انهم فتيه امنوا بربهم وزدناهم هدى","dt":"[13] نحن نقص عليك -ايها الرسول- خبرهم بالصدق. ان اصحاب الكهف شبان صدقوا ربهم وامتثلوا امره، وزدناهم هدى وثباتا على الحق."},{"id":"2154","s":18,"a":14,"at":"وربطنا على قلوبهم اذ قاموا فقالوا ربنا رب السموات والارض لن ندعوا من دونه الها لقد قلنا اذا شططا","dt":"[14] وقوينا قلوبهم بالايمان، وشددنا عزيمتهم به، حين قاموا بين يدي الملك الكافر، وهو يلومهم على ترك عباده الاصنام فقالوا له: ربنا الذي نعبده هو رب السموات والارض، لن نعبد غيره من الالهه، لو قلنا غير هذا لكنا قد قلنا قولا جائرا بعيدا عن الحق."},{"id":"2155","s":18,"a":15,"at":"هؤلاء قومنا اتخذوا من دونه الهه لولا ياتون عليهم بسلطان بين فمن اظلم ممن افترى على الله كذبا","dt":"[15] ثم قال بعضهم لبعض: هؤلاء قومنا اتخذوا لهم الهه غير الله، فهلا اتوا على عبادتهم لها بدليل واضح، فلا احد اشد ظلما ممن اختلق على الله الكذب بنسبه الشريك اليه في عبادته."},{"id":"2156","s":18,"a":16,"at":"واذ اعتزلتموهم وما يعبدون الا الله فاووا الى الكهف ينشر لكم ربكم من رحمته ويهيئ لكم من امركم مرفقا","dt":"[16] وحين فارقتم قومكم بدينكم، وتركتم ما يعبدون من الالهه الا عباده الله، فالجؤوا الى الكهف في الجبل لعباده ربكم وحده، يبسط لكم ربكم من رحمته ما يستركم به في الدارين، ويسهل لكم من امركم ما تنتفعون به في حياتكم من اسباب العيش."},{"id":"2157","s":18,"a":17,"at":"وترى الشمس اذا طلعت تزاور عن كهفهم ذات اليمين واذا غربت تقرضهم ذات الشمال وهم في فجوه منه ذلك من ايات الله من يهد الله فهو المهتد ومن يضلل فلن تجد له وليا مرشدا","dt":"[17] فلما فعلوا ذلك القى الله عليهم النوم وحفظهم. وترى -ايها المشاهد لهم- الشمس اذا طلعت من المشرق تميل عن مكانهم الى جهه اليمين، واذا غربت تتركهم الى جهه اليسار، وهم في متسع من الكهف، فلا تؤذيهم حراره الشمس، ولا ينقطع عنهم الهواء، ذلك الذي فعلناه بهؤلاء الفتيه من دلائل قدره الله. من يوفقه الله للاهتداء باياته فهو الموفق الى الحق، ومن لم يوفقه لذلك فلن تجد له معينا يرشده لاصابه الحق؛ لان التوفيق والخذلان بيد الله وحده."},{"id":"2158","s":18,"a":18,"at":"وتحسبهم ايقاظا وهم رقود ونقلبهم ذات اليمين وذات الشمال وكلبهم باسط ذراعيه بالوصيد لو اطلعت عليهم لوليت منهم فرارا ولملئت منهم رعبا","dt":"[18] وتظن -ايها الناظر- اهل الكهف ايقاظا، وهم في الواقع نيام، ونتعهدهم بالرعايه، فنقلبهم حال نومهم مره للجنب الايمن ومره للجنب الايسر؛ لئلا تاكلهم الارض، وكلبهم الذي صاحبهم ماد ذراعيه بفناء الكهف، كانه يحرسهم، لو عاينتهم لادبرت عنهم هاربا، ولملئت نفسك منهم فزعا."},{"id":"2159","s":18,"a":19,"at":"وكذلك بعثناهم ليتساءلوا بينهم قال قائل منهم كم لبثتم قالوا لبثنا يوما او بعض يوم قالوا ربكم اعلم بما لبثتم فابعثوا احدكم بورقكم هذه الى المدينه فلينظر ايها ازكى طعاما فلياتكم برزق منه وليتلطف ولا يشعرن بكم احدا","dt":"[19] وكما انمناهم وحفظناهم هذه المده الطويله ايقظناهم من نومهم على هيئتهم دون تغير؛ لكي يسال بعضهم بعضا: كم من الوقت مكثنا نائمين هنا؟ فقال بعضهم: مكثنا يوما او بعض يوم، وقال اخرون التبس عليهم الامر: فوضوا علم ذلك لله، فربكم اعلم بالوقت الذي مكثتموه، فارسلوا احدكم بنقودكم الفضيه هذه الى مدينتنا فلينظر: اي اهل المدينه احل واطيب طعاما؟ فلياتكم بقوت منه، وليتلطف في شرائه مع البائع حتى لا ننكشف ويظهر امرنا، ولا يعلمن بكم احدا من الناس."},{"id":"2160","s":18,"a":20,"at":"انهم ان يظهروا عليكم يرجموكم او يعيدوكم في ملتهم ولن تفلحوا اذا ابدا","dt":"[20] ان قومكم ان يطلعوا عليكم يرجموكم بالحجاره، فيقتلوكم، او يردوكم الى دينهم، فتصيروا كفارا، ولن تفوزوا بمطلبكم من دخول الجنه -ان فعلتم ذلك- ابدا."},{"id":"2161","s":18,"a":21,"at":"وكذلك اعثرنا عليهم ليعلموا ان وعد الله حق وان الساعه لا ريب فيها اذ يتنازعون بينهم امرهم فقالوا ابنوا عليهم بنيانا ربهم اعلم بهم قال الذين غلبوا على امرهم لنتخذن عليهم مسجدا","dt":"[21] وكما انمناهم سنين كثيره، وايقظناهم بعدها، اطلعنا عليهم اهل ذلك الزمان، بعد ان كشف البائع نوع الدراهم التي جاء بها مبعوثهم؛ ليعلم الناس ان وعد الله بالبعث حق، وان القيامه اتيه لا شك فيها، اذ يتنازع المطلعون على اصحاب الكهف في امر القيامه: فمن مثبت لها ومن منكر، فجعل الله اطلاعهم على اصحاب الكهف حجه للمؤمنين على الكافرين. وبعد ان انكشف امرهم، وماتوا قال فريق من المطلعين عليهم: ابنوا على باب الكهف بناء يحجبهم، واتركوهم وشانهم، ربهم اعلم بحالهم، وقال اصحاب الكلمه والنفوذ فيهم: لنتخذن على مكانهم مسجدا للعباده. وقد نهى رسول الله -صلى الله عليه وسلم- عن اتخاذ قبور الانبياء والصالحين مساجد، ولعن من فعل ذلك في اخر وصاياه لامته، كما انه نهى عن البناء على القبور مطلقا، وعن تجصيصها والكتابه عليها؛ لان ذلك من الغلو الذي قد يؤدي الى عباده من فيها."},{"id":"2162","s":18,"a":22,"at":"سيقولون ثلاثه رابعهم كلبهم ويقولون خمسه سادسهم كلبهم رجما بالغيب ويقولون سبعه وثامنهم كلبهم قل ربي اعلم بعدتهم ما يعلمهم الا قليل فلا تمار فيهم الا مراء ظاهرا ولا تستفت فيهم منهم احدا","dt":"[22] سيقول بعض الخائضين في شانهم من اهل الكتاب: هم ثلاثه، رابعهم كلبهم، ويقول فريق اخر: هم خمسه، سادسهم كلبهم، وكلام الفريقين قول بالظن من غير دليل، وتقول جماعه ثالثه: هم سبعه، وثامنهم كلبهم، قل -ايها الرسول-: ربي هو الاعلم بعددهم، ما يعلم عددهم الا قليل من خلقه. فلا تجادل اهل الكتاب في عددهم الا جدالا ظاهرا لا عمق فيه، بان تقص عليهم ما اخبرك به الوحي فحسب، ولا تسالهم عن عددهم واحوالهم؛ فانهم لا يعلمون ذلك."},{"id":"2163","s":18,"a":23,"at":"ولا تقولن لشيء اني فاعل ذلك غدا","dt":"[23] ولا تقولن لشيء تعزم على فعله: اني فاعل ذلك الشيء غدا"},{"id":"2164","s":18,"a":24,"at":"الا ان يشاء الله واذكر ربك اذا نسيت وقل عسى ان يهدين ربي لاقرب من هذا رشدا","dt":"[24] الا ان تعلق قولك بالمشيئه، فتقول: ان شاء الله. واذكر ربك عند النسيان بقول: ان شاء الله، وكلما نسيت فاذكر الله؛ فان ذكر الله يذهب النسيان، وقل: عسى ان يوفقني ربي بان يعطيني من الدلائل على نبوتي ما يكون اقرب واظهر من قصه اصحاب الكهف في هدايه الناس وارشادهم."},{"id":"2165","s":18,"a":25,"at":"ولبثوا في كهفهم ثلاث مائه سنين وازدادوا تسعا","dt":"[25] ومكث الشبان نياما في كهفهم ثلاثمائه سنه وتسع سنين قمريه."},{"id":"2166","s":18,"a":26,"at":"قل الله اعلم بما لبثوا له غيب السموات والارض ابصر به واسمع ما لهم من دونه من ولي ولا يشرك في حكمه احدا","dt":"[26] واذا سئلت -ايها الرسول- عن مده لبثهم في الكهف، وليس عندك علم في ذلك وتوقيف من الله، فلا تتقدم فيه بشيء، بل قل: الله اعلم بمده لبثهم، له غيب السموات والارض، ابصر به واسمع، اي: تعجب من كمال بصره وسمعه واحاطته بكل شيء. ليس للخلق احد غيره يتولى امورهم، وليس له شريك في حكمه وقضائه وتشريعه، سبحانه وتعالى."},{"id":"2167","s":18,"a":27,"at":"واتل ما اوحي اليك من كتاب ربك لا مبدل لكلماته ولن تجد من دونه ملتحدا","dt":"[27] واتل -ايها الرسول- ما اوحاه الله اليك من القران، فانه الكتاب الذي لا مبدل لكلماته لصدقها وعدلها، ولن تجد من دون ربك ملجا تلجا اليه، ولا معاذا تعوذ به."},{"id":"2168","s":18,"a":28,"at":"واصبر نفسك مع الذين يدعون ربهم بالغداه والعشي يريدون وجهه ولا تعد عيناك عنهم تريد زينه الحياه الدنيا ولا تطع من اغفلنا قلبه عن ذكرنا واتبع هواه وكان امره فرطا","dt":"[28] واصبر نفسك -ايها النبي- مع اصحابك من فقراء المؤمنين الذين يعبدون ربهم وحده، ويدعونه في الصباح والمساء، يريدون بذلك وجهه، واجلس معهم وخالطهم، ولا تصرف نظرك عنهم الى غيرهم من الكفار لاراده التمتع بزينه الحياه الدنيا، ولا تطع من جعلنا قلبه غافلا عن ذكرنا، واثر هواه على طاعه مولاه، وصار امره في جميع اعماله ضياعا وهلاكا."},{"id":"2169","s":18,"a":29,"at":"وقل الحق من ربكم فمن شاء فليؤمن ومن شاء فليكفر انا اعتدنا للظالمين نارا احاط بهم سرادقها وان يستغيثوا يغاثوا بماء كالمهل يشوي الوجوه بئس الشراب وساءت مرتفقا","dt":"[29] وقل لهؤلاء الغافلين: ما جئتكم به هو الحق من ربكم، فمن اراد منكم ان يصدق ويعمل به، فليفعل فهو خير له، ومن اراد ان يجحد فليفعل، فما ظلم الا نفسه. انا اعتدنا للكافرين نارا شديده احاط بهم سورها، وان يستغث هؤلاء الكفار في النار بطلب الماء من شده العطش، يؤت لهم بماء كالزيت العكر شديد الحراره يشوي وجوههم. قبح هذا الشراب الذي لا يروي ظماهم بل يزيده، وقبحت النار منزلا لهم ومقاما. وفي هذا وعيد وتهديد شديد لمن اعرض عن الحق، فلم يؤمن برساله محمد -صلى الله عليه وسلم-، ولم يعمل بمقتضاها."},{"id":"2170","s":18,"a":30,"at":"ان الذين امنوا وعملوا الصالحات انا لا نضيع اجر من احسن عملا","dt":"[30] ان الذين امنوا بالله ورسوله وعملوا الاعمال الصالحات لهم اعظم المثوبه، انا لا نضيع اجورهم، ولا ننقصها على ما احسنوه من العمل."},{"id":"2171","s":18,"a":31,"at":"اولئك لهم جنات عدن تجري من تحتهم الانهار يحلون فيها من اساور من ذهب ويلبسون ثيابا خضرا من سندس واستبرق متكئين فيها على الارائك نعم الثواب وحسنت مرتفقا","dt":"[31] اولئك الذين امنوا لهم جنات يقيمون فيها دائما، تجري من تحت غرفهم ومنازلهم الانهار العذبه، يزينون فيها باساور الذهب، ويلبسون ثيابا ذات لون اخضر نسجت من رقيق الحرير وغليظه، يتكئون فيها على الاسره المزدانه بالستائر الجميله، نعم الثواب ثوابهم، وحسنت الجنه منزلا ومكانا لهم."},{"id":"2172","s":18,"a":32,"at":"واضرب لهم مثلا رجلين جعلنا لاحدهما جنتين من اعناب وحففناهما بنخل وجعلنا بينهما زرعا","dt":"[32] واضرب -ايها الرسول- لكفار قومك مثلا رجلين من الامم السابقه: احدهما مؤمن، والاخر كافر، وقد جعلنا للكافر حديقتين من اعناب، واحطناهما بنخل كثير، وانبتنا وسطهما زروعا مختلفه نافعه."},{"id":"2173","s":18,"a":33,"at":"كلتا الجنتين اتت اكلها ولم تظلم منه شيئا وفجرنا خلالهما نهرا","dt":"[33] وقد اثمرت كل واحده من الحديقتين ثمرها، ولم تنقص منه شيئا، وشققنا بينهما نهرا لسقيهما بسهوله ويسر."},{"id":"2174","s":18,"a":34,"at":"وكان له ثمر فقال لصاحبه وهو يحاوره انا اكثر منك مالا واعز نفرا","dt":"[34] وكان لصاحب الحديقتين ثمر واموال اخرى، فقال لصاحبه المؤمن وهو يحاوره في الحديث -والغرور يملؤه-:انا اكثر منك مالا، واعز انصارا واعوانا."},{"id":"2175","s":18,"a":35,"at":"ودخل جنته وهو ظالم لنفسه قال ما اظن ان تبيد هذه ابدا","dt":"[35] ودخل حديقته، وهو ظالم لنفسه بالكفر بالبعث، وشكه في قيام الساعه، فاعجبته ثمارها وقال: ما اعتقد ان تهلك هذه الحديقه مدى الحياه، ."},{"id":"2176","s":18,"a":36,"at":"وما اظن الساعه قائمه ولئن رددت الى ربي لاجدن خيرا منها منقلبا","dt":"[36] وما اعتقد ان القيامه واقعه، وان فرض وقوعها -كما تزعم ايها المؤمن- ورجعت الى ربي لاجدن عنده افضل من هذه الحديقه مرجعا ومردا؛ لكرامتي ومنزلتي عنده."},{"id":"2177","s":18,"a":37,"at":"قال له صاحبه وهو يحاوره اكفرت بالذي خلقك من تراب ثم من نطفه ثم سواك رجلا","dt":"[37] قال له صاحبه المؤمن، وهو يحاوره واعظا له: كيف تكفر بالله الذي خلقك من تراب، ثم من نطفه الابوين، ثم سواك بشرا معتدل القامه والخلق؟ وفي هذه المحاوره دليل على ان القادر على ابتداء الخلق، قادر على اعادتهم."},{"id":"2178","s":18,"a":38,"at":"لكنا هو الله ربي ولا اشرك بربي احدا","dt":"[38] لكن انا لا اقول بمقالتك الداله على كفرك، وانما اقول: المنعم المتفضل هو الله ربي وحده، ولا اشرك في عبادتي له احدا غيره."},{"id":"2179","s":18,"a":39,"at":"ولولا اذ دخلت جنتك قلت ما شاء الله لا قوه الا بالله ان ترن انا اقل منك مالا وولدا","dt":"[39] وهلا حين دخلت حديقتك فاعجبتك حمدت الله، وقلت: هذا ما شاء الله لي، لا قوه لي على تحصيله الا بالله. ان كنت تراني اقل منك مالا واولادا،"},{"id":"2180","s":18,"a":40,"at":"فعسى ربي ان يؤتين خيرا من جنتك ويرسل عليها حسبانا من السماء فتصبح صعيدا زلقا","dt":"[40] فعسى ربي ان يعطيني افضل من حديقتك، ويسلبك النعمه بكفرك، ويرسل على حديقتك عذابا من السماء، فتصبح ارضا ملساء جرداء لا تثبت عليها قدم، ولا ينبت فيها نبات،"},{"id":"2181","s":18,"a":41,"at":"او يصبح ماؤها غورا فلن تستطيع له طلبا","dt":"[41] او يصير ماؤها الذي تسقى منه غائرا في الارض، فلا تقدر على اخراجه."},{"id":"2182","s":18,"a":42,"at":"واحيط بثمره فاصبح يقلب كفيه على ما انفق فيها وهي خاويه على عروشها ويقول ياليتني لم اشرك بربي احدا","dt":"[42] وتحقق ما قاله المؤمن، ووقع الدمار بالحديقه، فهلك كل ما فيها، فصار الكافر يقلب كفيه حسره وندامه على ما انفق فيها، وهي متهدمه قد سقط بعضها على بعض، خاليه مما كان فيها، ويقول: يا ليتني عرفت نعم الله وقدرته فلم اشرك به احدا. وهذا ندم منه حين لا ينفعه الندم."},{"id":"2183","s":18,"a":43,"at":"ولم تكن له فئه ينصرونه من دون الله وما كان منتصرا","dt":"[43] ولم تكن له جماعه ممن افتخر بهم يمنعونه من عقاب الله النازل به، وما كان ممتنعا بنفسه وقوته."},{"id":"2184","s":18,"a":44,"at":"هنالك الولايه لله الحق هو خير ثوابا وخير عقبا","dt":"[44] في مثل هذه الشدائد تكون الولايه والنصره لله الحق، هو خير جزاء، وخير عاقبه لمن تولاهم من عباده المؤمنين."},{"id":"2185","s":18,"a":45,"at":"واضرب لهم مثل الحياه الدنيا كماء انزلناه من السماء فاختلط به نبات الارض فاصبح هشيما تذروه الرياح وكان الله على كل شيء مقتدرا","dt":"[45] واضرب ايها الرسول للناس -وبخاصه ذوو الكبر منهم- صفه الدنيا التي اغتروا بها في بهجتها وسرعه زوالها، فهي كماء انزله الله من السماء فخرج به النبات باذنه، وصار مخضرا، وما هي الا مده يسيره حتى صار هذا النبات يابسا متكسرا تنسفه الرياح الى كل جهه. وكان الله على كل شيء مقتدرا، اي: ذا قدره عظيمه على كل شيء."},{"id":"2186","s":18,"a":46,"at":"المال والبنون زينه الحياه الدنيا والباقيات الصالحات خير عند ربك ثوابا وخير املا","dt":"[46] الاموال والاولاد جمال وقوه في هذه الدنيا الفانيه، والاعمال الصالحه -وبخاصه التسبيح والتحميد والتكبير والتهليل- افضل اجرا عند ربك من المال والبنين، وهذه الاعمال الصالحه افضل ما يرجو الانسان من الثواب عند ربه، فينال بها في الاخره ما كان يامله في الدنيا."},{"id":"2187","s":18,"a":47,"at":"ويوم نسير الجبال وترى الارض بارزه وحشرناهم فلم نغادر منهم احدا","dt":"[47] واذكر لهم يوم نزيل الجبال عن اماكنها، وتبصر الارض ظاهره، ليس عليها ما يسترها مما كان عليها من المخلوقات، وجمعنا الاولين والاخرين لموقف الحساب، فلم نترك منهم احدا."},{"id":"2188","s":18,"a":48,"at":"وعرضوا على ربك صفا لقد جئتمونا كما خلقناكم اول مره بل زعمتم الن نجعل لكم موعدا","dt":"[48] وعرضوا جميعا على ربك مصطفين، لا يحجب منهم احد؛ لقد بعثناكم، وجئتم الينا فرادى لا مال معكم ولا ولد، كما خلقناكم اول مره، بل ظننتم -يا منكري البعث- ان لن نجعل لكم موعدا نبعثكم فيه، ونجازيكم على اعمالكم."},{"id":"2189","s":18,"a":49,"at":"ووضع الكتاب فترى المجرمين مشفقين مما فيه ويقولون ياويلتنا مال هذا الكتاب لا يغادر صغيره ولا كبيره الا احصاها ووجدوا ما عملوا حاضرا ولا يظلم ربك احدا","dt":"[49] ووضع كتاب اعمال كل واحد في يمينه او في شماله، فتبصر العصاه خائفين مما فيه بسبب ما قدموه من جرائمهم، ويقولون حين يعاينونه: يا هلاكنا! ما لهذا الكتاب لم يترك صغيره من افعالنا ولا كبيره الا اثبتها؟! ووجدوا كل ما عملوه في الدنيا حاضرا مثبتا. ولا يظلم ربك احدا مثقال ذره، فلا ينقص طائع من ثوابه، ولا يزاد عاص في عقابه."},{"id":"2190","s":18,"a":50,"at":"واذ قلنا للملائكه اسجدوا لادم فسجدوا الا ابليس كان من الجن ففسق عن امر ربه افتتخذونه وذريته اولياء من دوني وهم لكم عدو بئس للظالمين بدلا","dt":"[50] واذكر حين امرنا الملائكه بالسجود لادم، تحيه له لا عباده، وامرنا ابليس بما امروا به، فسجد الملائكه جميعا، لكن ابليس الذي كان من الجن خرج عن طاعه ربه، ولم يسجد كبرا وحسدا. افتجعلونه -ايها الناس- وذريته اعوانا لكم تطيعونهم وتتركون طاعتي، وهم الد اعدائكم؟ قبحت طاعه الظالمين للشيطان بدلا عن طاعه الرحمن."},{"id":"2191","s":18,"a":51,"at":"ما اشهدتهم خلق السموات والارض ولا خلق انفسهم وما كنت متخذ المضلين عضدا","dt":"[51] ما احضرت ابليس وذريته -الذين اطعتموهم- خلق السموات والارض، فاستعين بهم على خلقهما، ولا اشهدت بعضهم على خلق بعض، بل تفردت بخلق جميع ذلك، بغير معين ولا ظهير، وما كنت متخذ المضلين من الشياطين وغيرهم اعوانا. فكيف تصرفون اليهم حقي، وتتخذونهم اولياء من دوني، وانا خالق كل شيء؟"},{"id":"2192","s":18,"a":52,"at":"ويوم يقول نادوا شركائي الذين زعمتم فدعوهم فلم يستجيبوا لهم وجعلنا بينهم موبقا","dt":"[52] واذكر لهم اذ يقول الله للمشركين يوم القيامه: نادوا شركائي الذين كنتم تزعمون انهم شركاء لي في العباده؛ لينصروكم اليوم مني، فاستغاثوا بهم فلم يغيثوهم، وجعلنا بين العابدين والمعبودين مهلكا في جهنم يهلكون فيه جميعا."},{"id":"2193","s":18,"a":53,"at":"وراى المجرمون النار فظنوا انهم مواقعوها ولم يجدوا عنها مصرفا","dt":"[53] وشاهد المجرمون النار، فايقنوا انهم واقعون فيها لا محاله، ولم يجدوا عنها معدلا للانصراف عنها الى غيرها."},{"id":"2194","s":18,"a":54,"at":"ولقد صرفنا في هذا القران للناس من كل مثل وكان الانسان اكثر شيء جدلا","dt":"[54] ولقد وضحنا ونوعنا في هذا القران للناس انواعا كثيره من الامثال؛ ليتعظوا بها ويؤمنوا. وكان الانسان اكثر المخلوقات خصومه وجدلا."},{"id":"2195","s":18,"a":55,"at":"وما منع الناس ان يؤمنوا اذ جاءهم الهدى ويستغفروا ربهم الا ان تاتيهم سنه الاولين او ياتيهم العذاب قبلا","dt":"[55] وما منع الناس من الايمان -حين جاءهم الرسول محمد -صلى الله عليه وسلم- ومعه القران-، واستغفار ربهم طالبين عفوه عنهم، الا تحديهم للرسول، وطلبهم ان تصيبهم سنه الله في اهلاك السابقين عليهم، او يصيبهم عذاب الله عيانا."},{"id":"2196","s":18,"a":56,"at":"وما نرسل المرسلين الا مبشرين ومنذرين ويجادل الذين كفروا بالباطل ليدحضوا به الحق واتخذوا اياتي وما انذروا هزوا","dt":"[56] وما نبعث الرسل الى الناس الا ليكونوا مبشرين بالجنه لاهل الايمان والعمل الصالح، ومخوفين بالنار لاهل الكفر والعصيان، ومع وضوح الحق يخاصم الذين كفروا رسلهم بالباطل تعنتا؛ ليزيلوا بباطلهم الحق الذي جاءهم به الرسول، واتخذوا كتابي وحججي وما خوفوا به من العذاب سخريه واستهزاء."},{"id":"2197","s":18,"a":57,"at":"ومن اظلم ممن ذكر بايات ربه فاعرض عنها ونسي ما قدمت يداه انا جعلنا على قلوبهم اكنه ان يفقهوه وفي اذانهم وقرا وان تدعهم الى الهدى فلن يهتدوا اذا ابدا","dt":"[57] ولا احد اشد ظلما ممن وعظ بايات ربه الواضحه، فانصرف عنها الى باطله، ونسي ما قدمته يداه من الافعال القبيحه فلم يرجع عنها، انا جعلنا على قلوبهم اغطيه، فلم يفهموا القران، ولم يدركوا ما فيه من الخير، وجعلنا في اذانهم ما يشبه الصمم، فلم يسمعوه ولم ينتفعوا به، وان تدعهم الى الايمان فلن يستجيبوا لك، ولن يهتدوا اليه ابدا."},{"id":"2198","s":18,"a":58,"at":"وربك الغفور ذو الرحمه لو يؤاخذهم بما كسبوا لعجل لهم العذاب بل لهم موعد لن يجدوا من دونه موئلا","dt":"[58] وربك الغفور لذنوب عباده اذا تابوا، ذو الرحمه بهم، لو يعاقب هؤلاء المعرضين عن اياته بما كسبوا من الذنوب والاثام لعجل لهم العذاب، ولكنه تعالى حليم لا يعجل بالعقوبه، بل لهم موعد يجازون فيه باعمالهم، لا مندوحه لهم عنه ولا محيد."},{"id":"2199","s":18,"a":59,"at":"وتلك القرى اهلكناهم لما ظلموا وجعلنا لمهلكهم موعدا","dt":"[59] وتلك القرى القريبه منكم -كقرى قوم هود وصالح ولوط وشعيب- اهلكناها حين ظلم اهلها بالكفر، وجعلنا لهلاكهم ميقاتا واجلا، حين بلغوه جاءهم العذاب فاهلكهم الله به."},{"id":"2200","s":18,"a":60,"at":"واذ قال موسى لفتاه لا ابرح حتى ابلغ مجمع البحرين او امضي حقبا","dt":"[60] واذكر حين قال موسى لخادمه يوشع بن نون: لا ازال اتابع السير حتى اصل الى ملتقى البحرين، او اسير زمنا طويلا حتى اصل الى العبد الصالح؛ لاتعلم منه ما ليس عندي من العلم."},{"id":"2201","s":18,"a":61,"at":"فلما بلغا مجمع بينهما نسيا حوتهما فاتخذ سبيله في البحر سربا","dt":"[61] وجدا في السير، فلما وصلا ملتقى البحرين جلسا عند صخره، ونسيا حوتهما الذي امر موسى باخذه معه قوتا لهما، وحمله يوشع في قفه، فاذا الحوت يصبح حيا وينحدر في البحر، ويتخذ له فيه طريقا مفتوحا."},{"id":"2202","s":18,"a":62,"at":"فلما جاوزا قال لفتاه اتنا غداءنا لقد لقينا من سفرنا هذا نصبا","dt":"[62] فلما فارقا المكان الذي نسيا فيه الحوت وشعر موسى بالجوع، قال لخادمه: احضر الينا طعام اول النهار، لقد لقينا من سفرنا هذا تعبا."},{"id":"2203","s":18,"a":63,"at":"قال ارايت اذ اوينا الى الصخره فاني نسيت الحوت وما انسانيه الا الشيطان ان اذكره واتخذ سبيله في البحر عجبا","dt":"[63] قال له خادمه: اتذكر حين لجانا الى الصخره التي استرحنا عندها؟ فاني نسيت ان اخبرك ما كان من الحوت، وما انساني ان اذكر ذلك لك الا الشيطان، فان الحوت الميت دبت فيه الحياه، وقفز في البحر، واتخذ له فيه طريقا، وكان امره مما يعجب منه."},{"id":"2204","s":18,"a":64,"at":"قال ذلك ما كنا نبغ فارتدا على اثارهما قصصا","dt":"[64] قال موسى: ما حصل هو ما كنا نطلبه، فانه علامه لي على مكان العبد الصالح، فرجعا يقصان اثار مشيهما حتى انتهيا الى الصخره."},{"id":"2205","s":18,"a":65,"at":"فوجدا عبدا من عبادنا اتيناه رحمه من عندنا وعلمناه من لدنا علما","dt":"[65] فوجدا هناك عبدا صالحا من عبادنا هو الخضر عليه السلام -وهو نبي من انبياء الله توفاه الله-، اتيناه رحمه من عندنا، وعلمناه من لدنا علما عظيما."},{"id":"2206","s":18,"a":66,"at":"قال له موسى هل اتبعك على ان تعلمن مما علمت رشدا","dt":"[66] فسلم عليه موسى، وقال له: اتاذن لي ان اتبعك؛ لتعلمني من العلم الذي علمك الله اياه ما استرشد به وانتفع؟"},{"id":"2207","s":18,"a":67,"at":"قال انك لن تستطيع معي صبرا","dt":"[67] قال له الخضر: انك -يا موسى- لن تطيق ان تصبر على اتباعي وملازمتي."},{"id":"2208","s":18,"a":68,"at":"وكيف تصبر على ما لم تحط به خبرا","dt":"[68] وكيف لك الصبر على ما سافعله من امور تخفى عليك مما علمنيه الله تعالى؟"},{"id":"2209","s":18,"a":69,"at":"قال ستجدني ان شاء الله صابرا ولا اعصي لك امرا","dt":"[69] قال له موسى: ستجدني ان شاء الله صابرا على ما اراه منك، ولا اخالف لك امرا تامرني به."},{"id":"2210","s":18,"a":70,"at":"قال فان اتبعتني فلا تسالني عن شيء حتى احدث لك منه ذكرا","dt":"[70] فوافق الخضر وقال له: فان صاحبتني فلا تسالني عن شيء تنكره، حتى ابين لك من امره ما خفي عليك دون سؤال منك."},{"id":"2211","s":18,"a":71,"at":"فانطلقا حتى اذا ركبا في السفينه خرقها قال اخرقتها لتغرق اهلها لقد جئت شيئا امرا","dt":"[71] فانطلقا يمشيان على الساحل، فمرت بهما سفينه، فطلبا من اهلها ان يركبا معهم، فلما ركبا قلع الخضر لوحا من السفينه فخرقها، فقال له موسى: اخرقت السفينه؛ لتغرق اهلها، وقد حملونا بغير اجر؟ لقد فعلت امرا منكرا."},{"id":"2212","s":18,"a":72,"at":"قال الم اقل انك لن تستطيع معي صبرا","dt":"[72] قال له الخضر: لقد قلت من اول الامر: انك لن تستطيع الصبر على صحبتي."},{"id":"2213","s":18,"a":73,"at":"قال لا تؤاخذني بما نسيت ولا ترهقني من امري عسرا","dt":"[73] قال موسى معتذرا: لا تؤاخذني بنسياني شرطك علي، ولا تكلفني مشقه في تعلمي منك، وعاملني بيسر ورفق."},{"id":"2214","s":18,"a":74,"at":"فانطلقا حتى اذا لقيا غلاما فقتله قال اقتلت نفسا زكيه بغير نفس لقد جئت شيئا نكرا","dt":"[74] فقبل الخضر عذره، ثم خرجا من السفينه، فبينما هما يمشيان على الساحل اذ ابصرا غلاما يلعب مع الغلمان، فقتله الخضر، فانكر موسى عليه وقال: كيف قتلت نفسا طاهره لم تبلغ حد التكليف، ولم تقتل نفسا، حتى تستحق القتل بها؟ لقد فعلت امرا منكرا عظيما."},{"id":"2215","s":18,"a":75,"at":"قال الم اقل لك انك لن تستطيع معي صبرا","dt":"[75] قال الخضر لموسى معاتبا ومذكرا: الم اقل لك انك لن تستطيع معي صبرا على ما ترى من افعالي مما لم تحط به خبرا؟"},{"id":"2216","s":18,"a":76,"at":"قال ان سالتك عن شيء بعدها فلا تصاحبني قد بلغت من لدني عذرا","dt":"[76] قال موسى له: ان سالتك عن شيء بعد هذه المره فاتركني ولا تصاحبني، قد بلغت العذر في شاني ولم تقصر؛ حيث اخبرتني اني لن استطيع معك صبرا."},{"id":"2217","s":18,"a":77,"at":"فانطلقا حتى اذا اتيا اهل قريه استطعما اهلها فابوا ان يضيفوهما فوجدا فيها جدارا يريد ان ينقض فاقامه قال لو شئت لتخذت عليه اجرا","dt":"[77] فسار موسى والخضر حتى اتيا اهل قريه، فطلبا منهم طعاما على سبيل الضيافه، فامتنع اهل القريه عن ضيافتهما، فوجدا فيها حائطا مائلا يوشك ان يسقط، فعدل الخضر ميله حتى صار مستويا، قال له موسى: لو شئت لاخذت على هذا العمل اجرا تصرفه في تحصيل طعامنا؛ حيث لم يضيفونا."},{"id":"2218","s":18,"a":78,"at":"قال هذا فراق بيني وبينك سانبئك بتاويل ما لم تستطع عليه صبرا","dt":"[78] قال الخضر لموسى: هذا وقت الفراق بيني وبينك، ساخبرك بما انكرت علي من افعالي التي فعلتها، والتي لم تستطع صبرا على ترك السؤال عنها والانكار علي فيها."},{"id":"2219","s":18,"a":79,"at":"اما السفينه فكانت لمساكين يعملون في البحر فاردت ان اعيبها وكان وراءهم ملك ياخذ كل سفينه غصبا","dt":"[79] اما السفينه التي خرقتها فانها كانت لاناس محتاجين -لا يملكون ما يكفيهم ويسد حاجتهم- يعملون في البحر عليها سعيا وراء الرزق، فاردت ان اعيبها بذلك الخرق؛ لان امامهم ملكا ياخذ كل سفينه صالحه غصبا من اصحابها."},{"id":"2220","s":18,"a":80,"at":"واما الغلام فكان ابواه مؤمنين فخشينا ان يرهقهما طغيانا وكفرا","dt":"[80] واما الغلام الذي قتلته فكان في علم الله كافرا، وكان ابوه وامه مؤمنين، فخشينا - لو بقي الغلام حيا - ان يحمل والديه على تجاوز حدود الله والكفر؛ لاجل محبتهما اياه او للحاجه اليه."},{"id":"2221","s":18,"a":81,"at":"فاردنا ان يبدلهما ربهما خيرا منه زكاه واقرب رحما","dt":"[81] فاردنا ان يبدل الله ابويه من هو خير منه صلاحا ودينا وبرا بهما."},{"id":"2222","s":18,"a":82,"at":"واما الجدار فكان لغلامين يتيمين في المدينه وكان تحته كنز لهما وكان ابوهما صالحا فاراد ربك ان يبلغا اشدهما ويستخرجا كنزهما رحمه من ربك وما فعلته عن امري ذلك تاويل ما لم تسطع عليه صبرا","dt":"[82] واما الحائط الذي عدلت ميله حتى استوى فانه كان لغلامين يتيمين في القريه التي فيها الجدار، وكان تحته كنز لهما من الذهب والفضه، وكان ابوهما رجلا صالحا، فاراد ربك ان يكبرا ويبلغا قوتهما، ويستخرجا كنزهما رحمه من ربك بهما، وما فعلت يا موسى جميع الذي رايتني فعلته عن امري ومن تلقاء نفسي، وانما فعلته عن امر الله، ذلك الذي بينت لك اسبابه هو عاقبه الامور التي لم تستطع صبرا على ترك السؤال عنها والانكار علي فيها."},{"id":"2223","s":18,"a":83,"at":"ويسالونك عن ذي القرنين قل ساتلو عليكم منه ذكرا","dt":"[83] ويسالك -ايها الرسول- هؤلاء المشركون من قومك عن خبر ذي القرنين الملك الصالح، قل لهم: ساقص عليكم منه ذكرا تتذكرونه، وتعتبرون به."},{"id":"2224","s":18,"a":84,"at":"انا مكنا له في الارض واتيناه من كل شيء سببا","dt":"[84] انا مكنا له في الارض، واتيناه من كل شيء اسبابا وطرقا، يتوصل بها الى ما يريد من فتح المدائن وقهر الاعداء وغير ذلك."},{"id":"2225","s":18,"a":85,"at":"فاتبع سببا","dt":"[85] فاخذ بتلك الاسباب والطرق بجد واجتهاد."},{"id":"2226","s":18,"a":86,"at":"حتى اذا بلغ مغرب الشمس وجدها تغرب في عين حمئه ووجد عندها قوما قلنا ياذا القرنين اما ان تعذب واما ان تتخذ فيهم حسنا","dt":"[86] حتى اذا وصل ذو القرنين الى مغرب الشمس، وجدها في مراى العين كانها تغرب في عين حاره ذات طين اسود، ووجد عند مغربها قوما. قلنا: يا ذا القرنين اما ان تعذبهم بالقتل او غيره ان لم يقروا بتوحيد الله، واما ان تحسن اليهم فتعلمهم الهدى وتبصرهم الرشاد."},{"id":"2227","s":18,"a":87,"at":"قال اما من ظلم فسوف نعذبه ثم يرد الى ربه فيعذبه عذابا نكرا","dt":"[87] قال ذو القرنين: اما من ظلم نفسه منهم فكفر بربه، فسوف نعذبه في الدنيا، ثم يرجع الى ربه، فيعذبه عذابا عظيما في نار جهنم."},{"id":"2228","s":18,"a":88,"at":"واما من امن وعمل صالحا فله جزاء الحسنى وسنقول له من امرنا يسرا","dt":"[88] واما من امن منهم بربه فصدق به ووحده وعمل بطاعته فله الجنه ثوابا من الله، وسنحسن اليه، ونلين له في القول ونيسر له المعامله."},{"id":"2229","s":18,"a":89,"at":"ثم اتبع سببا","dt":"[89] ثم رجع ذو القرنين الى المشرق متبعا الاسباب التي اعطاه الله اياها."},{"id":"2230","s":18,"a":90,"at":"حتى اذا بلغ مطلع الشمس وجدها تطلع على قوم لم نجعل لهم من دونها سترا","dt":"[90] حتى اذا وصل الى مطلع الشمس وجدها تطلع على قوم ليس لهم بناء يسترهم، ولا شجر يظلهم من الشمس."},{"id":"2231","s":18,"a":91,"at":"كذلك وقد احطنا بما لديه خبرا","dt":"[91] كذلك وقد احاط علمنا بما عنده من الخير والاسباب العظيمه، حيثما توجه وسار."},{"id":"2232","s":18,"a":92,"at":"ثم اتبع سببا","dt":"[92] ثم سار ذو القرنين اخذا بالطرق والاسباب التي منحناها اياه."},{"id":"2233","s":18,"a":93,"at":"حتى اذا بلغ بين السدين وجد من دونهما قوما لا يكادون يفقهون قولا","dt":"[93] حتى اذا وصل الى ما بين الجبلين الحاجزين لما وراءهما، وجد من دونهما قوما لا يكادون يعرفون كلام غيرهم."},{"id":"2234","s":18,"a":94,"at":"قالوا ياذا القرنين ان ياجوج وماجوج مفسدون في الارض فهل نجعل لك خرجا على ان تجعل بيننا وبينهم سدا","dt":"[94] قالوا يا ذا القرنين: ان ياجوج وماجوج -وهما امتان عظيمتان من بني ادم- مفسدون في الارض باهلاك الحرث والنسل، فهل نجعل لك اجرا، ونجمع لك مالا، على ان تجعل بيننا وبينهم حاجزا يحول بيننا وبينهم؟"},{"id":"2235","s":18,"a":95,"at":"قال ما مكني فيه ربي خير فاعينوني بقوه اجعل بينكم وبينهم ردما","dt":"[95] قال ذو القرنين: ما اعطانيه ربي من الملك والتمكين خير لي من مالكم، فاعينوني بقوه منكم اجعل بينكم وبينهم سدا."},{"id":"2236","s":18,"a":96,"at":"اتوني زبر الحديد حتى اذا ساوى بين الصدفين قال انفخوا حتى اذا جعله نارا قال اتوني افرغ عليه قطرا","dt":"[96] اعطوني قطع الحديد، حتى اذا جاؤوا به ووضعوه وحاذوا به جانبي الجبلين، قال للعمال: اججوا النار، حتى اذا صار الحديد كله نارا، قال: اعطوني نحاسا افرغه عليه."},{"id":"2237","s":18,"a":97,"at":"فما اسطاعوا ان يظهروه وما استطاعوا له نقبا","dt":"[97] فما استطاعت ياجوج وماجوج ان تصعد فوق السد؛ لارتفاعه وملاسته، وما استطاعوا ان ينقبوه من اسفله لبعد عرضه وقوته."},{"id":"2238","s":18,"a":98,"at":"قال هذا رحمه من ربي فاذا جاء وعد ربي جعله دكاء وكان وعد ربي حقا","dt":"[98] قال ذو القرنين: هذا الذي بنيته حاجزا عن فساد ياجوج وماجوج رحمه من ربي بالناس، فاذا جاء وعد ربي بخروج ياجوج وماجوج جعله دكاء منهدما مستويا بالارض، وكان وعد ربي حقا."},{"id":"2239","s":18,"a":99,"at":"وتركنا بعضهم يومئذ يموج في بعض ونفخ في الصور فجمعناهم جمعا","dt":"[99] وتركنا ياجوج وماجوج -يوم ياتيهم وعدنا- يموج بعضهم في بعض مختلطين؛ لكثرتهم، ونفخ في «القرن» للبعث، فجمعنا الخلق جميعا للحساب والجزاء."},{"id":"2240","s":18,"a":100,"at":"وعرضنا جهنم يومئذ للكافرين عرضا","dt":"[100] وعرضنا جهنم للكافرين، وابرزناها لهم لنريهم سوء عاقبتهم."},{"id":"2241","s":18,"a":101,"at":"الذين كانت اعينهم في غطاء عن ذكري وكانوا لا يستطيعون سمعا","dt":"[101] الذين كانت اعينهم في الدنيا في غطاء عن ذكري فلا تبصر اياتي، وكانوا لا يطيقون سماع حججي الموصله الى الايمان بي وبرسولي."},{"id":"2242","s":18,"a":102,"at":"افحسب الذين كفروا ان يتخذوا عبادي من دوني اولياء انا اعتدنا جهنم للكافرين نزلا","dt":"[102] افظن الذين كفروا بي ان يتخذوا عبادي الهه من غيري؛ ليكونوا اولياء لهم؟ انا اعتدنا نار جهنم للكافرين منزلا."},{"id":"2243","s":18,"a":103,"at":"قل هل ننبئكم بالاخسرين اعمالا","dt":"[103] قل -ايها الرسول- للناس محذرا: هل نخبركم باخسر الناس اعمالا؟"},{"id":"2244","s":18,"a":104,"at":"الذين ضل سعيهم في الحياه الدنيا وهم يحسبون انهم يحسنون صنعا","dt":"[104] انهم الذين ضل عملهم في الحياه الدنيا -وهم مشركو قومك وغيرهم ممن ضل سواء السبيل، فلم يكن على هدى ولا صواب- وهم يظنون انهم محسنون في اعمالهم."},{"id":"2245","s":18,"a":105,"at":"اولئك الذين كفروا بايات ربهم ولقائه فحبطت اعمالهم فلا نقيم لهم يوم القيامه وزنا","dt":"[105] اولئك الاخسرون اعمالا، هم الذين جحدوا بايات ربهم وكذبوا بها، وانكروا لقاءه يوم القيامه، فبطلت اعمالهم؛ بسبب كفرهم، فلا نقيم لهم يوم القيامه قدرا."},{"id":"2246","s":18,"a":106,"at":"ذلك جزاؤهم جهنم بما كفروا واتخذوا اياتي ورسلي هزوا","dt":"[106] ذلك الجزاء المعد لهم لحبوط اعمالهم هو نار جهنم؛ بسبب كفرهم بالله واتخاذهم اياته وحجج رسله استهزاء وسخريه."},{"id":"2247","s":18,"a":107,"at":"ان الذين امنوا وعملوا الصالحات كانت لهم جنات الفردوس نزلا","dt":"[107] ان الذين امنوا بي، وصدقوا رسلي، وعملوا الصالحات، لهم اعلى منازل الجنه واوسطها، وهي افضلها منزلا."},{"id":"2248","s":18,"a":108,"at":"خالدين فيها لا يبغون عنها حولا","dt":"[108] خالدين فيها ابدا، لا يريدون عنها تحولا؛ لرغبتهم فيها وحبهم لها."},{"id":"2249","s":18,"a":109,"at":"قل لو كان البحر مدادا لكلمات ربي لنفد البحر قبل ان تنفد كلمات ربي ولو جئنا بمثله مددا","dt":"[109] قل -ايها الرسول-: لو كان ماء البحر حبرا للاقلام التي يكتب بها كلام الله من علمه وحكمه، وما اوحاه الى ملائكته ورسله، لنفد ماء البحر قبل ان تنفد كلمات الله، ولو جئنا بمثل البحر بحارا اخرى مددا له. وفي الايه اثبات صفه الكلام لله -تعالى- حقيقه كما يليق بجلاله وكماله."},{"id":"2250","s":18,"a":110,"at":"قل انما انا بشر مثلكم يوحى الي انما الهكم اله واحد فمن كان يرجو لقاء ربه فليعمل عملا صالحا ولا يشرك بعباده ربه احدا","dt":"[110] قل -ايها الرسول- لهؤلاء المشركين: انما انا بشر مثلكم يوحى الي من ربي انما الهكم اله واحد، فمن كان يخاف عذاب ربه ويرجو ثوابه يوم لقائه، فليعمل عملا صالحا لربه موافقا لشرعه، ولا يشرك في العباده معه احدا غيره."},{"id":"2251","s":19,"a":1,"at":"كهيعص","dt":"[1] كهيعص سبق الكلام على الحروف المقطعه في اول سوره البقره."},{"id":"2252","s":19,"a":2,"at":"ذكر رحمه ربك عبده زكريا","dt":"[2] هذا ذكر رحمه ربك عبده زكريا، سنقصه عليك؛ فان في ذلك عبره للمعتبرين."},{"id":"2253","s":19,"a":3,"at":"اذ نادى ربه نداء خفيا","dt":"[3] اذ دعا ربه سرا؛ ليكون اكمل واتم اخلاصا لله، وارجى للاجابه."},{"id":"2254","s":19,"a":4,"at":"قال رب اني وهن العظم مني واشتعل الراس شيبا ولم اكن بدعائك رب شقيا","dt":"[4] قال: رب اني كبرت، وضعف عظمي، وانتشر الشيب في راسي، ولم اكن من قبل محروما من اجابه الدعاء."},{"id":"2255","s":19,"a":5,"at":"واني خفت الموالي من ورائي وكانت امراتي عاقرا فهب لي من لدنك وليا","dt":"[5] واني خفت اقاربي وعصبتي من بعد موتي ان لا يقوموا بدينك حق القيام، ولا يدعوا عبادك اليك، وكانت زوجتي عاقرا لا تلد، فارزقني من عندك ولدا وارثا ومعينا."},{"id":"2256","s":19,"a":6,"at":"يرثني ويرث من ال يعقوب واجعله رب رضيا","dt":"[6] يرث نبوتي ونبوه ال يعقوب، واجعل هذا الولد مرضيا منك ومن عبادك."},{"id":"2257","s":19,"a":7,"at":"يازكريا انا نبشرك بغلام اسمه يحيى لم نجعل له من قبل سميا","dt":"[7] يا زكريا انا نبشرك باجابه دعائك، قد وهبنا لك غلاما اسمه يحيى، لم نسم احدا قبله بهذا الاسم."},{"id":"2258","s":19,"a":8,"at":"قال رب انى يكون لي غلام وكانت امراتي عاقرا وقد بلغت من الكبر عتيا","dt":"[8] قال زكريا متعجبا: رب كيف يكون لي غلام، وكانت امراتي عاقرا لا تلد، وانا قد بلغت النهايه في الكبر ورقه العظم؟"},{"id":"2259","s":19,"a":9,"at":"قال كذلك قال ربك هو علي هين وقد خلقتك من قبل ولم تك شيئا","dt":"[9] قال الملك مجيبا زكريا عما تعجب منه: هكذا الامر كما تقول من كون امراتك عاقرا، وبلوغك من الكبر عتيا، ولكن ربك قال: خلق يحيى على هذه الكيفيه امر سهل هين علي، ثم ذكر الله سبحانه لزكريا ما هو اعجب مما سال عنه فقال: وقد خلقتك انت من قبل يحيى، ولم تك شيئا مذكورا ولا موجودا."},{"id":"2260","s":19,"a":10,"at":"قال رب اجعل لي ايه قال ايتك الا تكلم الناس ثلاث ليال سويا","dt":"[10] قال زكريا زياده في اطمئنانه: رب اجعل لي علامه على تحقق ما بشرتني به الملائكه، قال: علامتك ان لا تقدر على كلام الناس مده ثلاث ليال وايامها، وانت صحيح معافى."},{"id":"2261","s":19,"a":11,"at":"فخرج على قومه من المحراب فاوحى اليهم ان سبحوا بكره وعشيا","dt":"[11] فخرج زكريا على قومه من مصلاه، وهو المكان الذي بشر فيه بالولد، فاشار اليهم: ان سبحوا الله صباحا ومساء شكرا له تعالى."},{"id":"2262","s":19,"a":12,"at":"يايحيى خذ الكتاب بقوه واتيناه الحكم صبيا","dt":"[12] فلما ولد يحيى، وبلغ مبلغا يفهم فيه الخطاب، امره الله ان ياخذ التوراه بجد واجتهاد بقوله: يا يحيى خذ التوراه بجد واجتهاد بحفظ الفاظها، وفهم معانيها، والعمل بها، واعطيناه الحكمه وحسن الفهم، وهو صغير السن."},{"id":"2263","s":19,"a":13,"at":"وحنانا من لدنا وزكاه وكان تقيا","dt":"[13] واتيناه رحمه ومحبه من عندنا وطهاره من الذنوب، وكان خائفا مطيعا لله تعالى، مؤديا فرائضه، مجتنبا محارمه."},{"id":"2264","s":19,"a":14,"at":"وبرا بوالديه ولم يكن جبارا عصيا","dt":"[14] وكان بارا بوالديه مطيعا لهما، ولم يكن متكبرا عن طاعه ربه، ولا عن طاعه والديه، ولا عاصيا لربه، ولا لوالديه."},{"id":"2265","s":19,"a":15,"at":"وسلام عليه يوم ولد ويوم يموت ويوم يبعث حيا","dt":"[15] وسلام من الله على يحيى وامان له يوم ولد، ويوم يموت، ويوم يبعث من قبره حيا."},{"id":"2266","s":19,"a":16,"at":"واذكر في الكتاب مريم اذ انتبذت من اهلها مكانا شرقيا","dt":"[16] واذكر -ايها الرسول- في هذا القران خبر مريم اذ تباعدت عن اهلها، فاتخذت لها مكانا مما يلي الشرق عنهم."},{"id":"2267","s":19,"a":17,"at":"فاتخذت من دونهم حجابا فارسلنا اليها روحنا فتمثل لها بشرا سويا","dt":"[17] فجعلت من دون اهلها سترا يسترها عنهم وعن الناس، فارسلنا اليها الملك جبريل، فتمثل لها في صوره انسان تام الخلق."},{"id":"2268","s":19,"a":18,"at":"قالت اني اعوذ بالرحمن منك ان كنت تقيا","dt":"[18] قالت مريم له: اني استجير بالرحمن منك ان تنالني بسوء ان كنت ممن يتقي الله."},{"id":"2269","s":19,"a":19,"at":"قال انما انا رسول ربك لاهب لك غلاما زكيا","dt":"[19] قال لها الملك: انما انا رسول ربك بعثني اليك؛ لاهب لك غلاما طاهرا من الذنوب."},{"id":"2270","s":19,"a":20,"at":"قالت انى يكون لي غلام ولم يمسسني بشر ولم اك بغيا","dt":"[20] قالت مريم للملك: كيف يكون لي غلام، ولم يمسسني بشر بنكاح حلال، ولم اك زانيه؟"},{"id":"2271","s":19,"a":21,"at":"قال كذلك قال ربك هو علي هين ولنجعله ايه للناس ورحمه منا وكان امرا مقضيا","dt":"[21] قال لها الملك: هكذا الامر كما تصفين من انه لم يمسسك بشر، ولم تكوني بغيا، ولكن ربك قال: الامر علي سهل؛ وليكون هذا الغلام علامه للناس تدل على قدره الله تعالى، ورحمه منا به وبوالدته وبالناس، وكان وجود عيسى على هذه الحاله قضاء سابقا مقدرا، مسطورا في اللوح المحفوظ، فلا بد من نفوذه."},{"id":"2272","s":19,"a":22,"at":"فحملته فانتبذت به مكانا قصيا","dt":"[22] فحملت مريم بالغلام بعد ان نفخ جبريل في جيب قميصها، فوصلت النفخه الى رحمها، فوقع الحمل بسبب ذلك، فتباعدت به الى مكان بعيد عن الناس."},{"id":"2273","s":19,"a":23,"at":"فاجاءها المخاض الى جذع النخله قالت ياليتني مت قبل هذا وكنت نسيا منسيا","dt":"[23] فالجاها طلق الحمل الى جذع النخله فقالت: يا ليتني مت قبل هذا اليوم، وكنت شيئا لا يعرف، ولا يذكر، ولا يدرى من انا؟"},{"id":"2274","s":19,"a":24,"at":"فناداها من تحتها الا تحزني قد جعل ربك تحتك سريا","dt":"[24] فناداها جبريل او عيسى: ان لا تحزني، قد جعل ربك تحتك جدول ماء."},{"id":"2275","s":19,"a":25,"at":"وهزي اليك بجذع النخله تساقط عليك رطبا جنيا","dt":"[25] وحركي جذع النخله تساقط عليك رطبا غضا جني من ساعته."},{"id":"2276","s":19,"a":26,"at":"فكلي واشربي وقري عينا فاما ترين من البشر احدا فقولي اني نذرت للرحمن صوما فلن اكلم اليوم انسيا","dt":"[26] فكلي من الرطب، واشربي من الماء وطيبي نفسا بالمولود، فان رايت من الناس احدا فسالك عن امرك فقولي له: اني اوجبت على نفسي لله سكوتا، فلن اكلم اليوم احدا من الناس. والسكوت كان تعبدا في شرعهم، دون شريعه محمد -صلى الله عليه وسلم-."},{"id":"2277","s":19,"a":27,"at":"فاتت به قومها تحمله قالوا يامريم لقد جئت شيئا فريا","dt":"[27] فاتت مريم قومها تحمل مولودها من المكان البعيد، فلما راوها كذلك قالوا لها: يا مريم لقد جئت امرا عظيما مفترى."},{"id":"2278","s":19,"a":28,"at":"يااخت هارون ما كان ابوك امرا سوء وما كانت امك بغيا","dt":"[28] يا اخت الرجل الصالح هارون ما كان ابوك رجل سوء ياتي الفواحش، وما كانت امك امراه سوء تاتي البغاء."},{"id":"2279","s":19,"a":29,"at":"فاشارت اليه قالوا كيف نكلم من كان في المهد صبيا","dt":"[29] فاشارت مريم الى مولودها عيسى ليسالوه ويكلموه، فقالوا منكرين عليها: كيف نكلم من لا يزال في مهده طفلا رضيعا؟"},{"id":"2280","s":19,"a":30,"at":"قال اني عبد الله اتاني الكتاب وجعلني نبيا","dt":"[30] قال عيسى وهو في مهده يرضع: اني عبد الله، قضى باعطائي الكتاب، وهو الانجيل، وجعلني نبيا."},{"id":"2281","s":19,"a":31,"at":"وجعلني مباركا اين ما كنت ‎واوصاني بالصلاه والزكاه ما دمت حيا","dt":"[31] وجعلني عظيم الخير والنفع حيثما وجدت، واوصاني بالمحافظه على الصلاه وايتاء الزكاه ما بقيت حيا."},{"id":"2282","s":19,"a":32,"at":"وبرا بوالدتي ولم يجعلني جبارا شقيا","dt":"[32] وجعلني بارا بوالدتي، ولم يجعلني متكبرا، ولا شقيا عاصيا لربي."},{"id":"2283","s":19,"a":33,"at":"والسلام علي يوم ولدت ويوم اموت ويوم ابعث حيا","dt":"[33] والسلامه والامان علي من الله يوم ولدت، ويوم اموت، ويوم ابعث حيا يوم القيامه."},{"id":"2284","s":19,"a":34,"at":"ذلك عيسى ابن مريم قول الحق الذي فيه يمترون","dt":"[34] ذلك الذي قصصنا عليك -ايها الرسول- صفته وخبره هو عيسى بن مريم، من غير شك ولا مريه، حال كونه قول الحق الذي شك فيه اليهود والنصارى."},{"id":"2285","s":19,"a":35,"at":"ما كان لله ان يتخذ من ولد سبحانه اذا قضى امرا فانما يقول له كن فيكون","dt":"[35] ما كان لله تعالى ولا يليق به ان يتخذ من عباده وخلقه ولدا، تنزه وتقدس عن ذلك، اذا قضى امرا من الامور واراده، صغيرا او كبيرا، لم يمتنع عليه، وانما يقول له: «كن»، فيكون كما شاءه واراده."},{"id":"2286","s":19,"a":36,"at":"وان الله ربي وربكم فاعبدوه هذا صراط مستقيم","dt":"[36] وقال عيسى لقومه: وان الله الذي ادعوكم اليه هو وحده ربي وربكم فاعبدوه وحده لا شريك له، فانا وانتم سواء في العبوديه والخضوع له، هذا هو الطريق الذي لا اعوجاج فيه."},{"id":"2287","s":19,"a":37,"at":"فاختلف الاحزاب من بينهم فويل للذين كفروا من مشهد يوم عظيم","dt":"[37] فاختلفت الفرق من اهل الكتاب فيما بينهم في امر عيسى عليه السلام، فمنهم غال فيه وهم النصارى، منهم من قال: هو الله، ومنهم من قال: هو ابن الله، ومنهم من قال: ثالث ثلاثه -تعالى الله عما يقولون-، ومنهم جاف عنه وهم اليهود، قالوا: ساحر، وقالوا: ابن يوسف النجار، فهلاك للذين كفروا من شهود يوم عظيم الهول، وهو يوم القيامه."},{"id":"2288","s":19,"a":38,"at":"اسمع بهم وابصر يوم ياتوننا لكن الظالمون اليوم في ضلال مبين","dt":"[38] ما اشد سمعهم وبصرهم يوم القيامه، يوم يقدمون على الله، حين لا ينفعهم ذلك! لكن الظالمون اليوم في هذه الدنيا في ذهاب بين عن الحق."},{"id":"2289","s":19,"a":39,"at":"وانذرهم يوم الحسره اذ قضي الامر وهم في غفله وهم لا يؤمنون","dt":"[39] وانذر -ايها الرسول- الناس يوم الندامه حين يقضى الامر، ويجاء بالموت كانه كبش املح، فيذبح، ويفصل بين الخلق، فيصير اهل الايمان الى الجنه، واهل الكفر الى النار، وهم اليوم في هذه الدنيا في غفله عما انذروا به، فهم لا يصدقون، ولا يعملون العمل الصالح."},{"id":"2290","s":19,"a":40,"at":"انا نحن نرث الارض ومن عليها والينا يرجعون","dt":"[40] انا نحن الوارثون للارض ومن عليها بفنائهم وبقائنا بعدهم وحكمنا فيهم، والينا مصيرهم وحسابهم، فنجازيهم على اعمالهم."},{"id":"2291","s":19,"a":41,"at":"واذكر في الكتاب ابراهيم انه كان صديقا نبيا","dt":"[41] واذكر -ايها الرسول- لقومك في هذا القران قصه ابراهيم -عليه السلام- انه كان عظيم الصدق، ومن ارفع انبياء الله تعالى منزله."},{"id":"2292","s":19,"a":42,"at":"اذ قال لابيه ياابت لم تعبد ما لا يسمع ولا يبصر ولا يغني عنك شيئا","dt":"[42] اذ قال لابيه ازر: يا ابت لاي شيء تعبد من الاصنام ما لا يسمع ولا يبصر، ولا يدفع عنك شيئا من دون الله؟"},{"id":"2293","s":19,"a":43,"at":"ياابت اني قد جاءني من العلم ما لم ياتك فاتبعني اهدك صراطا سويا","dt":"[43] يا ابت، ان الله اعطاني من العلم ما لم يعطك، فاقبل مني، واتبعني الى ما ادعوك اليه، ارشدك الى الطريق السوي الذي لا تضل فيه."},{"id":"2294","s":19,"a":44,"at":"ياابت لا تعبد الشيطان ان الشيطان كان للرحمن عصيا","dt":"[44] يا ابت، لا تطع الشيطان فتعبد هذه الاصنام؛ ان الشيطان كان للرحمن مخالفا مستكبرا عن طاعه الله."},{"id":"2295","s":19,"a":45,"at":"ياابت اني اخاف ان يمسك عذاب من الرحمن فتكون للشيطان وليا","dt":"[45] يا ابت، اني اخاف ان تموت على كفرك، فيمسك عذاب من الرحمن، فتكون للشيطان قرينا في النار."},{"id":"2296","s":19,"a":46,"at":"قال اراغب انت عن الهتي ياابراهيم لئن لم تنته لارجمنك واهجرني مليا","dt":"[46] قال ابو ابراهيم لابنه: امعرض انت عن عباده الهتي يا ابراهيم؟ لئن لم تنته عن سبها لاقتلنك رميا بالحجاره، واذهب عني فلا تلقني، ولا تكلمني زمانا طويلا من الدهر."},{"id":"2297","s":19,"a":47,"at":"قال سلام عليك ساستغفر لك ربي انه كان بي حفيا","dt":"[47] قال ابراهيم لابيه: سلام عليك مني فلا ينالك مني ما تكره، وسوف ادعو الله لك بالهدايه والمغفره. ان ربي كان رحيما رؤوفا بحالي يجيبني اذا دعوته."},{"id":"2298","s":19,"a":48,"at":"واعتزلكم وما تدعون من دون الله وادعو ربي عسى الا اكون بدعاء ربي شقيا","dt":"[48] وافارقكم والهتكم التي تعبدونها من دون الله، وادعو ربي مخلصا، عسى ان لا اشقى بدعاء ربي، فلا يعطيني ما اساله."},{"id":"2299","s":19,"a":49,"at":"فلما اعتزلهم وما يعبدون من دون الله وهبنا له اسحاق ويعقوب وكلا جعلنا نبيا","dt":"[49] فلما فارقهم والهتهم التي يعبدونها من دون الله رزقناه من الولد: اسحاق، ويعقوب بن اسحاق، وجعلناهما نبيين."},{"id":"2300","s":19,"a":50,"at":"ووهبنا لهم من رحمتنا وجعلنا لهم لسان صدق عليا","dt":"[50] ووهبنا لهم جميعا من رحمتنا فضلا لا يحصى، وجعلنا لهم ذكرا حسنا، وثناء جميلا باقيا في الناس."},{"id":"2301","s":19,"a":51,"at":"واذكر في الكتاب موسى انه كان مخلصا وكان رسولا نبيا","dt":"[51] واذكر -ايها الرسول- في القران قصه موسى -عليه السلام- انه كان مصطفى مختارا، وكان رسولا نبيا من اولي العزم من الرسل."},{"id":"2302","s":19,"a":52,"at":"وناديناه من جانب الطور الايمن وقربناه نجيا","dt":"[52] ونادينا موسى من ناحيه جبل طور «سيناء» اليمنى من موسى، وقربناه فشرفناه بمناجاتنا له. وفي هذا اثبات صفه الكلام لله -تعالى- كما يليق بجلاله وكماله."},{"id":"2303","s":19,"a":53,"at":"ووهبنا له من رحمتنا اخاه هارون نبيا","dt":"[53] ووهبنا لموسى من رحمتنا اخاه هارون نبيا يؤيده ويؤازره."},{"id":"2304","s":19,"a":54,"at":"واذكر في الكتاب اسماعيل انه كان صادق الوعد وكان رسولا نبيا","dt":"[54] واذكر -ايها الرسول- في هذا القران خبر اسماعيل عليه السلام، انه كان صادقا في وعده فلم يعد شيئا الا وفى به، وكان رسولا نبيا."},{"id":"2305","s":19,"a":55,"at":"وكان يامر اهله بالصلاه والزكاه وكان عند ربه مرضيا","dt":"[55] وكان يامر اهله باقام الصلاه وايتاء الزكاه، وكان عند ربه عز وجل مرضيا عنه."},{"id":"2306","s":19,"a":56,"at":"واذكر في الكتاب ادريس انه كان صديقا نبيا","dt":"[56] واذكر -ايها الرسول- في هذا القران خبر ادريس عليه السلام، انه كان عظيم الصدق في قوله وعمله، نبيا يوحى اليه."},{"id":"2307","s":19,"a":57,"at":"ورفعناه مكانا عليا","dt":"[57] ورفعنا ذكره في العالمين، ومنزلته بين المقربين، فكان عالي الذكر، عالي المنزله."},{"id":"2308","s":19,"a":58,"at":"اولئك الذين انعم الله عليهم من النبيين من ذريه ادم وممن حملنا مع نوح ومن ذريه ابراهيم واسرائيل وممن هدينا واجتبينا اذا تتلى عليهم ايات الرحمن خروا سجدا وبكيا","dt":"[58] هؤلاء الذين قصصت عليك خبرهم ايها الرسول، هم الذين انعم الله عليهم بفضله وتوفيقه، فجعلهم انبياء من ذريه ادم، ومن ذريه من حملنا مع نوح في السفينه، ومن ذريه ابراهيم، ومن ذريه يعقوب، وممن هدينا للايمان واصطفينا للرساله والنبوه، اذا تتلى عليهم ايات الرحمن المتضمنه لتوحيده وحججه خروا ساجدين لله خضوعا واستكانه، وبكوا من خشيته سبحانه وتعالى."},{"id":"2309","s":19,"a":59,"at":"فخلف من بعدهم خلف اضاعوا الصلاه واتبعوا الشهوات فسوف يلقون غيا","dt":"[59] فاتى من بعد هؤلاء المنعم عليهم اتباع سوء تركوا الصلاه كلها، او فوتوا وقتها، او تركوا اركانها وواجباتها، واتبعوا ما يوافق شهواتهم ويلائمها، فسوف يلقون شرا وضلالا وخيبه في جهنم."},{"id":"2310","s":19,"a":60,"at":"الا من تاب وامن وعمل صالحا فاولئك يدخلون الجنه ولا يظلمون شيئا","dt":"[60] لكن من تاب منهم من ذنبه وامن بربه وعمل صالحا تصديقا لتوبته، فاولئك يقبل الله توبتهم، ويدخلون الجنه مع المؤمنين، ولا ينقصون شيئا من اعمالهم الصالحه."},{"id":"2311","s":19,"a":61,"at":"جنات عدن التي وعد الرحمن عباده بالغيب انه كان وعده ماتيا","dt":"[61] جنات خلد واقامه دائمه، وهي التي وعد الرحمن بها عباده بالغيب فامنوا بها ولم يروها، ان وعد الله لعباده بهذه الجنه ات لا محاله."},{"id":"2312","s":19,"a":62,"at":"لا يسمعون فيها لغوا الا سلاما ولهم رزقهم فيها بكره وعشيا","dt":"[62] لا يسمع اهل الجنه فيها كلاما باطلا، لكن يسمعون سلاما تحيه لهم، ولهم رزقهم فيها من الطعام والشراب دائما، كلما شاؤوا صباحا ومساء، فهو غير محصور ولا محدد."},{"id":"2313","s":19,"a":63,"at":"تلك الجنه التي نورث من عبادنا من كان تقيا","dt":"[63] تلك الجنه الموصوفه بتلك الصفات، هي التي نورثها ونعطيها عبادنا المتقين لنا، بامتثال اوامرنا واجتناب نواهينا."},{"id":"2314","s":19,"a":64,"at":"وما نتنزل الا بامر ربك له ما بين ايدينا وما خلفنا وما بين ذلك وما كان ربك نسيا","dt":"[64] وقل -يا جبريل- لمحمد -صلى الله عليه وسلم-: وما نتنزل -نحن الملائكه- من السماء الى الارض الا بامر ربك لنا، له ما بين ايدينا مما يستقبل من امر الاخره، وما خلفنا مما مضى من الدنيا، وما بين الدنيا والاخره، فله الامر كله في الزمان والمكان، وما كان ربك ناسيا لشيء من الاشياء."},{"id":"2315","s":19,"a":65,"at":"رب السموات والارض وما بينهما فاعبده واصطبر لعبادته هل تعلم له سميا","dt":"[65] فهو الله رب السموات والارض وما بينهما، ومالك ذلك كله وخالقه ومدبره، فاعبده وحده -ايها النبي- واصبر على طاعته انت ومن تبعك، ليس كمثله شيء في ذاته واسمائه وصفاته وافعاله."},{"id":"2316","s":19,"a":66,"at":"ويقول الانسان ائذا ما مت لسوف اخرج حيا","dt":"[66] ويقول الانسان الكافر منكرا للبعث بعد الموت: ااذا ما مت وفنيت لسوف اخرج من قبري حيا؟"},{"id":"2317","s":19,"a":67,"at":"او لا يذكر الانسان انا خلقناه من قبل ولم يك شيئا","dt":"[67] كيف نسي هذا الانسان الكافر نفسه؟ اولا يذكر انا خلقناه اول مره، ولم يك شيئا موجودا؟"},{"id":"2318","s":19,"a":68,"at":"فوربك لنحشرنهم والشياطين ثم لنحضرنهم حول جهنم جثيا","dt":"[68] فوربك -ايها الرسول- لنجمعن هؤلاء المنكرين للبعث يوم القيامه مع الشياطين، ثم لناتين بهم اجمعين حول جهنم باركين على ركبهم؛ لشده ما هم فيه من الهول، لا يقدرون على القيام."},{"id":"2319","s":19,"a":69,"at":"ثم لننزعن من كل شيعه ايهم اشد على الرحمن عتيا","dt":"[69] ثم لناخذن من كل طائفه اشدهم تمردا وعصيانا لله، فنبدا بعذابهم."},{"id":"2320","s":19,"a":70,"at":"ثم لنحن اعلم بالذين هم اولى بها صليا","dt":"[70] ثم لنحن اعلم بالذين هم اولى بدخول النار ومقاساه حرها."},{"id":"2321","s":19,"a":71,"at":"وان منكم الا واردها كان على ربك حتما مقضيا","dt":"[71] وما منكم -ايها الناس- احد الا وارد النار بالمرور على الصراط المنصوب على متن جهنم، كل بحسب عمله، كان ذلك امرا محتوما، قضى الله -سبحانه- وحكم انه لا بد من وقوعه لا محاله."},{"id":"2322","s":19,"a":72,"at":"ثم ننجي الذين اتقوا ونذر الظالمين فيها جثيا","dt":"[72] ثم ننجي الذين اتقوا ربهم بطاعته والبعد عن معصيته، ونترك الظالمين لانفسهم بالكفر بالله في النار باركين على ركبهم."},{"id":"2323","s":19,"a":73,"at":"واذا تتلى عليهم اياتنا بينات قال الذين كفروا للذين امنوا اي الفريقين خير مقاما واحسن نديا","dt":"[73] واذا تتلى على الناس اياتنا المنزلات الواضحات قال الكفار بالله للمؤمنين به: اي الفريقين منا ومنكم افضل منزلا واحسن مجلسا؟"},{"id":"2324","s":19,"a":74,"at":"وكم اهلكنا قبلهم من قرن هم احسن اثاثا ورئيا","dt":"[74] وكثيرا اهلكنا قبل كفار قومك -ايها الرسول- من الامم كانوا احسن متاعا منهم واجمل منظرا."},{"id":"2325","s":19,"a":75,"at":"قل من كان في الضلاله فليمدد له الرحمن مدا حتى اذا راوا ما يوعدون اما العذاب واما الساعه فسيعلمون من هو شر مكانا واضعف جندا","dt":"[75] قل -ايها الرسول- لهم: من كان ضالا عن الحق غير متبع طريق الهدى، فالله يمهله ويملي له في ضلاله، حتى اذا راى -يقينا- ما توعده الله به: اما العذاب العاجل في الدنيا، واما قيام الساعه، فسيعلم -حينئذ- من هو شر مكانا ومستقرا، واضعف قوه وجندا."},{"id":"2326","s":19,"a":76,"at":"ويزيد الله الذين اهتدوا هدى والباقيات الصالحات خير عند ربك ثوابا وخير مردا","dt":"[76] ويزيد الله عباده الذين اهتدوا لدينه هدى على هداهم بما يتجدد لهم من الايمان بفرائض الله، والعمل بها. والاعمال الباقيات الصالحات خير ثوابا عند الله في الاخره، وخير مرجعا وعاقبه."},{"id":"2327","s":19,"a":77,"at":"افرايت الذي كفر باياتنا وقال لاوتين مالا وولدا","dt":"[77] اعلمت -ايها الرسول- وعجبت من هذا الكافر «العاص بن وائل» وامثاله؟ اذ كفر بايات الله وكذب بها وقال: لاعطين في الاخره اموالا واولادا."},{"id":"2328","s":19,"a":78,"at":"اطلع الغيب ام اتخذ عند الرحمن عهدا","dt":"[78] اطلع الغيب، فراى ان له مالا وولدا، ام له عند الله عهد بذلك؟"},{"id":"2329","s":19,"a":79,"at":"كلا سنكتب ما يقول ونمد له من العذاب مدا","dt":"[79] ليس الامر كما يزعم ذلك الكافر، فلا علم له ولا عهد عنده، سنكتب ما يقول من كذب وافتراء على الله، ونزيده في الاخره من انواع العقوبات، كما ازداد من الغي والضلال."},{"id":"2330","s":19,"a":80,"at":"ونرثه ما يقول وياتينا فردا","dt":"[80] ونرثه ماله وولده، وياتينا يوم القيامه فردا وحده، لا مال معه ولا ولد."},{"id":"2331","s":19,"a":81,"at":"واتخذوا من دون الله الهه ليكونوا لهم عزا","dt":"[81] واتخذ المشركون الهه يعبدونها من دون الله؛ لتنصرهم، ويعتزوا بها."},{"id":"2332","s":19,"a":82,"at":"كلا سيكفرون بعبادتهم ويكونون عليهم ضدا","dt":"[82] ليس الامر كما يزعمون، لن تكون لهم الالهه عزا، بل ستكفر هذه الالهه في الاخره بعبادتهم لها، وتكون عليهم اعوانا في خصومتهم وتكذيبهم بخلاف ما ظنوه فيها."},{"id":"2333","s":19,"a":83,"at":"الم تر انا ارسلنا الشياطين على الكافرين تؤزهم ازا","dt":"[83] الم تر -ايها الرسول- انا سلطنا الشياطين على الكافرين بالله ورسله؛ لتغويهم، وتدفعهم عن الطاعه الى المعصيه؟"},{"id":"2334","s":19,"a":84,"at":"فلا تعجل عليهم انما نعد لهم عدا","dt":"[84] فلا تستعجل -ايها الرسول- بطلب العذاب على هؤلاء الكافرين، انما نحصي اعمارهم واعمالهم احصاء لا تفريط فيه ولا تاخير."},{"id":"2335","s":19,"a":85,"at":"يوم نحشر المتقين الى الرحمن وفدا","dt":"[85] يوم نجمع المتقين الى ربهم الرحيم بهم وفودا مكرمين."},{"id":"2336","s":19,"a":86,"at":"ونسوق المجرمين الى جهنم وردا","dt":"[86] ونسوق الكافرين بالله سوقا شديدا الى النار مشاه عطاشا."},{"id":"2337","s":19,"a":87,"at":"لا يملكون الشفاعه الا من اتخذ عند الرحمن عهدا","dt":"[87] لا يملك هؤلاء الكفار الشفاعه لاحد، انما يملكها من اتخذ عند الرحمن عهدا بذلك، وهم المؤمنون بالله ورسله."},{"id":"2338","s":19,"a":88,"at":"وقالوا اتخذ الرحمن ولدا","dt":"[88] وقال هؤلاء الكفار: اتخذ الرحمن ولدا."},{"id":"2339","s":19,"a":89,"at":"لقد جئتم شيئا ادا","dt":"[89] لقد جئتم -ايها القائلون- بهذه المقاله شيئا عظيما منكرا."},{"id":"2340","s":19,"a":90,"at":"تكاد السموات يتفطرن منه وتنشق الارض وتخر الجبال هدا","dt":"[90] تكاد السموات يتشققن من فظاعه ذلكم القول، وتتصدع الارض، وتسقط الجبال سقوطا شديدا"},{"id":"2341","s":19,"a":91,"at":"ان دعوا للرحمن ولدا","dt":"[91] غضبا لله لنسبتهم اليه الولد. تعالى الله عن ذلك علوا كبيرا."},{"id":"2342","s":19,"a":92,"at":"وما ينبغي للرحمن ان يتخذ ولدا","dt":"[92] وما يصلح للرحمن، ولا يليق بعظمته، ان يتخذ ولدا؛ لان اتخاذ الولد يدل على النقص والحاجه، والله هو الغني الحميد المبرا عن كل النقائص."},{"id":"2343","s":19,"a":93,"at":"ان كل من في السموات والارض الا اتي الرحمن عبدا","dt":"[93] ما كل من في السموات من الملائكه، ومن في الارض من الانس والجن، الا سياتي ربه يوم القيامه عبدا ذليلا خاضعا مقرا له بالعبوديه."},{"id":"2344","s":19,"a":94,"at":"لقد احصاهم وعدهم عدا","dt":"[94] لقد احصى الله سبحانه وتعالى خلقه كلهم، وعلم عددهم، فلا يخفى عليه احد منهم."},{"id":"2345","s":19,"a":95,"at":"وكلهم اتيه يوم القيامه فردا","dt":"[95] وسوف ياتي كل فرد من الخلق ربه يوم القيامه وحده، لا مال له ولا ولد معه."},{"id":"2346","s":19,"a":96,"at":"ان الذين امنوا وعملوا الصالحات سيجعل لهم الرحمن ودا","dt":"[96] ان الذين امنوا بالله واتبعوا رسله وعملوا الصالحات وفق شرعه، سيجعل لهم الرحمن محبه وموده في قلوب عباده."},{"id":"2347","s":19,"a":97,"at":"فانما يسرناه بلسانك لتبشر به المتقين وتنذر به قوما لدا","dt":"[97] فانما يسرنا هذا القران بلسانك العربي ايها الرسول؛ لتبشر به المتقين من اتباعك، وتخوف به المكذبين الشديدي الخصومه بالباطل."},{"id":"2348","s":19,"a":98,"at":"وكم اهلكنا قبلهم من قرن هل تحس منهم من احد او تسمع لهم ركزا","dt":"[98] وكثيرا اهلكنا -ايها الرسول- من الامم السابقه قبل قومك، ما ترى منهم احدا وما تسمع لهم صوتا، فكذلك الكفار من قومك، نهلكهم كما اهلكنا السابقين من قبلهم. وفي هذا تهديد ووعيد باهلاك المكذبين المعاندين."},{"id":"2349","s":20,"a":1,"at":"طه","dt":"[1] طه سبق الكلام على الحروف المقطعه في اول سوره البقره."},{"id":"2350","s":20,"a":2,"at":"ما انزلنا عليك القران لتشقى","dt":"[2] ما انزلنا عليك -ايها الرسول- القران؛ لتشقى بما لا طاقه لك به من العمل."},{"id":"2351","s":20,"a":3,"at":"الا تذكره لمن يخشى","dt":"[3] لكن انزلناه موعظه؛ ليتذكر به من يخاف عقاب الله، فيتقيه باداء الفرائض واجتناب المحارم."},{"id":"2352","s":20,"a":4,"at":"تنزيلا ممن خلق الارض والسموات العلا","dt":"[4] هذا القران تنزيل من الله الذي خلق الارض والسموات العلى."},{"id":"2353","s":20,"a":5,"at":"الرحمن على العرش استوى","dt":"[5] الرحمن على العرش استوى، اي: علا وارتفع، استواء يليق بجلاله وعظمته."},{"id":"2354","s":20,"a":6,"at":"له ما في السموات وما في الارض وما بينهما وما تحت الثرى","dt":"[6] له ما في السموات وما في الارض وما بينهما وما تحت الارض، خلقا وملكا وتدبيرا."},{"id":"2355","s":20,"a":7,"at":"وان تجهر بالقول فانه يعلم السر واخفى","dt":"[7] وان تجهر -ايها الرسول- بالقول، فتعلنه او تخفه، فان الله لا يخفى عليه شيء، يعلم السر وما هو اخفى من السر مما تحدث به نفسك."},{"id":"2356","s":20,"a":8,"at":"الله لا اله الا هو له الاسماء الحسنى","dt":"[8] الله الذي لا معبود بحق الا هو، له وحده الاسماء الكامله في الحسن."},{"id":"2357","s":20,"a":9,"at":"وهل اتاك حديث موسى","dt":"[9] وهل اتاك -ايها الرسول- خبر موسى بن عمران عليه السلام، وهو قادم من «مدين» الى «مصر»؟"},{"id":"2358","s":20,"a":10,"at":"اذ راى نارا فقال لاهله امكثوا اني انست نارا لعلي اتيكم منها بقبس او اجد على النار هدى","dt":"[10] حين راى في الليل نارا موقده فقال لاهله: انتظروا لقد ابصرت نارا، لعلي اجيئكم منها بشعله تستدفئون بها، وتوقدون بها نارا اخرى، او اجد عندها هاديا يدلنا على الطريق."},{"id":"2359","s":20,"a":11,"at":"فلما اتاها نودي ياموسى","dt":"[11] فلما اتى موسى تلك النار ناداه الله: يا موسى،"},{"id":"2360","s":20,"a":12,"at":"اني انا ربك فاخلع نعليك انك بالواد المقدس طوى","dt":"[12] ، اني انا ربك فاخلع نعليك، انك الان بوادي «طوى» الذي باركته، وذلك استعدادا لمناجاه ربه."},{"id":"2361","s":20,"a":13,"at":"وانا اخترتك فاستمع لما يوحى","dt":"[13] واني اخترتك يا موسى لرسالتي، فاستمع لما يوحى اليك مني."},{"id":"2362","s":20,"a":14,"at":"انني انا الله لا اله الا انا فاعبدني واقم الصلاه لذكري","dt":"[14] انني انا الله لا معبود بحق الا انا، لا شريك لي، فاعبدني وحدي، واقم الصلاه لتذكرني فيها."},{"id":"2363","s":20,"a":15,"at":"ان الساعه اتيه اكاد اخفيها لتجزى كل نفس بما تسعى","dt":"[15] ان الساعه التي يبعث فيها الناس اتيه لابد من وقوعها، اكاد اخفيها من نفسي، فكيف يعلمها احد من المخلوقين؟ لكي تجزى كل نفس بما عملت في الدنيا من خير او شر."},{"id":"2364","s":20,"a":16,"at":"فلا يصدنك عنها من لا يؤمن بها واتبع هواه فتردى","dt":"[16] فلا يصرفنك -يا موسى- عن الايمان بها والاستعداد لها من لا يصدق بوقوعها ولا يعمل لها، واتبع هوى نفسه، فكذب بها، فتهلك."},{"id":"2365","s":20,"a":17,"at":"وما تلك بيمينك ياموسى","dt":"[17] وما هذه التي في يمينك يا موسى؟"},{"id":"2366","s":20,"a":18,"at":"قال هي عصاي اتوكا عليها واهش بها على غنمي ولي فيها مارب اخرى","dt":"[18] قال موسى: هي عصاي اعتمد عليها في المشي، واهز بها الشجر؛ لترعى غنمي ما يتساقط من ورقه، ولي فيها منافع اخرى."},{"id":"2367","s":20,"a":19,"at":"قال القها ياموسى","dt":"[19] قال الله لموسى: الق عصاك."},{"id":"2368","s":20,"a":20,"at":"فالقاها فاذا هي حيه تسعى","dt":"[20] فالقاها موسى على الارض، فانقلبت باذن الله حيه تسعى، فراى موسى امرا عظيما وولى هاربا."},{"id":"2369","s":20,"a":21,"at":"قال خذها ولا تخف سنعيدها سيرتها الاولى","dt":"[21] قال الله لموسى: خذ الحيه، ولا تخف منها، سوف نعيدها عصا كما كانت في حالتها الاولى."},{"id":"2370","s":20,"a":22,"at":"واضمم يدك الى جناحك تخرج بيضاء من غير سوء ايه اخرى","dt":"[22] . واضمم يدك الى جنبك تحت العضد تخرج بيضاء كالثلج من غير برص؛ لتكون لك علامه اخرى."},{"id":"2371","s":20,"a":23,"at":"لنريك من اياتنا الكبرى","dt":"[23] فعلنا ذلك؛ لكي نريك -يا موسى- من ادلتنا الكبرى ما يدل على قدرتنا، وعظيم سلطاننا، وصحه رسالتك."},{"id":"2372","s":20,"a":24,"at":"اذهب الى فرعون انه طغى","dt":"[24] اذهب -يا موسى- الى فرعون؛ انه قد تجاوز قدره وتمرد على ربه، فادعه الى توحيد الله وعبادته."},{"id":"2373","s":20,"a":25,"at":"قال رب اشرح لي صدري","dt":"[25] قال موسى: رب وسع لي صدري،"},{"id":"2374","s":20,"a":26,"at":"ويسر لي امري","dt":"[26] وسهل لي امري،"},{"id":"2375","s":20,"a":27,"at":"واحلل عقده من لساني","dt":"[27] واطلق لساني بفصيح المنطق؛"},{"id":"2376","s":20,"a":28,"at":"يفقهوا قولي","dt":"[28] ليفهموا كلامي."},{"id":"2377","s":20,"a":29,"at":"واجعل لي وزيرا من اهلي","dt":"[29] واجعل لي معينا من اهلي،."},{"id":"2378","s":20,"a":30,"at":"هارون اخي","dt":"[30] هارون اخي"},{"id":"2379","s":20,"a":31,"at":"اشدد به ازري","dt":"[31] قوني به وشد به ظهري،"},{"id":"2380","s":20,"a":32,"at":"واشركه في امري","dt":"[32] واشركه معي في النبوه وتبليغ الرساله؛"},{"id":"2381","s":20,"a":33,"at":"كي نسبحك كثيرا","dt":"[33] كي ننزهك بالتسبيح كثيرا."},{"id":"2382","s":20,"a":34,"at":"ونذكرك كثيرا","dt":"[34] ونذكرك كثيرا فنحمدك."},{"id":"2383","s":20,"a":35,"at":"انك كنت بنا بصيرا","dt":"[35] انك كنت بنا بصيرا، لا يخفى عليك شيء من افعالنا."},{"id":"2384","s":20,"a":36,"at":"قال قد اوتيت سؤلك ياموسى","dt":"[36] قال الله: قد اعطيتك كل ما سالت يا موسى."},{"id":"2385","s":20,"a":37,"at":"ولقد مننا عليك مره اخرى","dt":"[37] ولقد انعمنا عليك -يا موسى- قبل هذه النعمه نعمه اخرى، حين كنت رضيعا، فانجيناك من بطش فرعون."},{"id":"2386","s":20,"a":38,"at":"اذ اوحينا الى امك ما يوحى","dt":"[38] وذلك حين الهمنا امك:"},{"id":"2387","s":20,"a":39,"at":"ان اقذفيه في التابوت فاقذفيه في اليم فليلقه اليم بالساحل ياخذه عدو لي وعدو له والقيت عليك محبه مني ولتصنع على عيني","dt":"[39] ان ضعي ابنك موسى بعد ولادته في التابوت ثم اطرحيه في النيل، فسوف يلقيه النيل على الساحل، فياخذه فرعون عدوي وعدوه. والقيت عليك محبه مني فصرت بذلك محبوبا بين العباد، ولتربى على عيني وفي حفظي. وفي الايه اثبات صفه العين لله -سبحانه وتعالى- كما يليق بجلاله وكماله."},{"id":"2388","s":20,"a":40,"at":"اذ تمشي اختك فتقول هل ادلكم على من يكفله فرجعناك الى امك كي تقر عينها ولا تحزن وقتلت نفسا فنجيناك من الغم وفتناك فتونا فلبثت سنين في اهل مدين ثم جئت على قدر ياموسى","dt":"[40] ومننا عليك حين تمشي اختك تتبعك ثم تقول لمن اخذوك: هل ادلكم على من يكفله، ويرضعه لكم؟ فرددناك الى امك بعد ما صرت في ايدي فرعون؛ كي تطيب نفسها بسلامتك من الغرق والقتل، ولا تحزن على فقدك، وقتلت الرجل القبطي خطا فنجيناك من غم فعلك وخوف القتل، وابتليناك ابتلاء، فخرجت خائفا الى اهل «مدين»، فمكثت سنين فيهم، ثم جئت من «مدين» في الموعد الذي قدرناه لارسالك مجيئا موافقا لقدر الله وارادته، والامر كله لله تبارك وتعالى."},{"id":"2389","s":20,"a":41,"at":"واصطنعتك لنفسي","dt":"[41] وانعمت عليك -يا موسى- هذه النعم اجتباء مني لك، واختيارا لرسالتي، والبلاغ عني، والقيام بامري ونهيي."},{"id":"2390","s":20,"a":42,"at":"اذهب انت واخوك باياتي ولا تنيا في ذكري","dt":"[42] اذهب -يا موسى- انت واخوك هارون باياتي الداله على الوهيتي وكمال قدرتي وصدق رسالتك، ولا تضعفا عن مداومه ذكري."},{"id":"2391","s":20,"a":43,"at":"اذهبا الى فرعون انه طغى","dt":"[43] . اذهبا معا الى فرعون؛ انه قد جاوز الحد في الكفر والظلم،"},{"id":"2392","s":20,"a":44,"at":"فقولا له قولا لينا لعله يتذكر او يخشى","dt":"[44] فقولا له قولا لطيفا؛ لعله يتذكر او يخاف ربه."},{"id":"2393","s":20,"a":45,"at":"قالا ربنا اننا نخاف ان يفرط علينا او ان يطغى","dt":"[45] قال موسى وهارون: ربنا اننا نخاف ان يعاجلنا بالعقوبه، او ان يتمرد على الحق فلا يقبله."},{"id":"2394","s":20,"a":46,"at":"قال لا تخافا انني معكما اسمع وارى","dt":"[46] قال الله لموسى وهارون: لا تخافا من فرعون؛ فانني معكما اسمع كلامكما وارى افعالكما،"},{"id":"2395","s":20,"a":47,"at":"فاتياه فقولا انا رسولا ربك فارسل معنا بني اسرائيل ولا تعذبهم قد جئناك بايه من ربك والسلام على من اتبع الهدى","dt":"[47] فاذهبا اليه وقولا له: اننا رسولان اليك من ربك ان اطلق بني اسرائيل، ولا تكلفهم ما لا يطيقون من الاعمال، قد اتيناك بدلاله معجزه من ربك تدل على صدقنا في دعوتنا، والسلامه من عذاب الله تعالى لمن اتبع هداه. ."},{"id":"2396","s":20,"a":48,"at":"انا قد اوحي الينا ان العذاب على من كذب وتولى","dt":"[48] ان ربك قد اوحى الينا ان عذابه على من كذب واعرض عن دعوته وشريعته."},{"id":"2397","s":20,"a":49,"at":"قال فمن ربكما ياموسى","dt":"[49] قال فرعون لهما -على وجه الانكار-: فمن ربكما يا موسى؟"},{"id":"2398","s":20,"a":50,"at":"قال ربنا الذي اعطى كل شيء خلقه ثم هدى","dt":"[50] قال له موسى: ربنا الذي اعطى كل شيء خلقه اللائق به الدال على حسن صنعه، ثم هدى كل مخلوق الهدايه الكامله الى الانتفاع بما خلقه الله له."},{"id":"2399","s":20,"a":51,"at":"قال فما بال القرون الاولى","dt":"[51] قال فرعون لموسى -على وجه المغالطه والمشاغبه-: فما شان الامم السابقه؟ وما خبر القرون الماضيه، فقد سبقونا الى الانكار والكفر؟"},{"id":"2400","s":20,"a":52,"at":"قال علمها عند ربي في كتاب لا يضل ربي ولا ينسى","dt":"[52] قال موسى لفرعون: ما سالت عنه ليس مما نحن بصدده، بل علم تلك القرون فيما فعلت من ذلك عند ربي في اللوح المحفوظ، ولا علم لي به، لا يضل ربي في افعاله واحكامه، ولا ينسى شيئا مما علمه منها."},{"id":"2401","s":20,"a":53,"at":"الذي جعل لكم الارض مهدا وسلك لكم فيها سبلا وانزل من السماء ماء فاخرجنا به ازواجا من نبات شتى","dt":"[53] هو الذي جعل لكم الارض ميسره للانتفاع بها، وجعل لكم فيها طرقا كثيره، وانزل من السماء مطرا، فاخرج به انواعا مختلفه من النبات."},{"id":"2402","s":20,"a":54,"at":"كلوا وارعوا انعامكم ان في ذلك لايات لاولي النهى","dt":"[54] كلوا -ايها الناس- من طيبات ما انبتنا لكم، وارعوا حيواناتكم وبهائمكم. ان في كل ما ذكر لعلامات على قدره الله، ودعوه لوحدانيته وافراده بالعباده، لذوي العقول السليمه."},{"id":"2403","s":20,"a":55,"at":"منها خلقناكم وفيها نعيدكم ومنها نخرجكم تاره اخرى","dt":"[55] من الارض خلقناكم -ايها الناس-، وفيها نعيدكم بعد الموت، ومنها نخرجكم احياء مره اخرى للحساب والجزاء."},{"id":"2404","s":20,"a":56,"at":"ولقد اريناه اياتنا كلها فكذب وابى","dt":"[56] ولقد ارينا فرعون ادلتنا وحججنا جميعها، الداله على الوهيتنا وقدرتنا وصدق رساله موسى فكذب بها، وامتنع عن قبول الحق."},{"id":"2405","s":20,"a":57,"at":"قال اجئتنا لتخرجنا من ارضنا بسحرك ياموسى","dt":"[57] قال فرعون: هل جئتنا -يا موسى- لتخرجنا من ديارنا بسحرك هذا؟"},{"id":"2406","s":20,"a":58,"at":"فلناتينك بسحر مثله فاجعل بيننا وبينك موعدا لا نخلفه نحن ولا انت مكانا سوى","dt":"[58] فسوف ناتيك بسحر مثل سحرك، فاجعل بيننا وبينك موعدا محددا، لا نخلفه نحن ولا تخلفه انت، في مكان مستو معتدل بيننا وبينك."},{"id":"2407","s":20,"a":59,"at":"قال موعدكم يوم الزينه وان يحشر الناس ضحى","dt":"[59] قال موسى لفرعون: موعدكم للاجتماع يوم العيد ، حين يتزين الناس، ويجتمعون من كل فج وناحيه وقت الضحى."},{"id":"2408","s":20,"a":60,"at":"فتولى فرعون فجمع كيده ثم اتى","dt":"[60] فادبر فرعون معرضا عما اتاه به موسى من الحق، فجمع سحرته، ثم جاء بعد ذلك لموعد الاجتماع."},{"id":"2409","s":20,"a":61,"at":"قال لهم موسى ويلكم لا تفتروا على الله كذبا فيسحتكم بعذاب وقد خاب من افترى","dt":"[61] قال موسى لسحره فرعون يعظهم: احذروا، لا تختلقوا على الله الكذب، فيستاصلكم بعذاب من عنده ويبيدكم، وقد خسر من اختلق على الله كذبا."},{"id":"2410","s":20,"a":62,"at":"فتنازعوا امرهم بينهم واسروا النجوى","dt":"[62] فتجاذب السحره امرهم بينهم وتحادثوا سرا،"},{"id":"2411","s":20,"a":63,"at":"قالوا ان هذان لساحران يريدان ان يخرجاكم من ارضكم بسحرهما ويذهبا بطريقتكم المثلى","dt":"[63] ، قالوا: ان موسى وهارون لساحران يريدان ان يخرجاكم من بلادكم بسحرهما، ويذهبا بطريقه السحر العظيمه التي انتم عليها،"},{"id":"2412","s":20,"a":64,"at":"فاجمعوا كيدكم ثم ائتوا صفا وقد افلح اليوم من استعلى","dt":"[64] فاحكموا كيدكم، واعزموا عليه من غير اختلاف بينكم، ثم ائتوا صفا واحدا، والقوا ما في ايديكم مره واحده؛ لتبهروا الابصار، وتغلبوا سحر موسى واخيه، وقد ظفر بحاجته اليوم من علا على صاحبه، فغلبه وقهره."},{"id":"2413","s":20,"a":65,"at":"قالوا ياموسى اما ان تلقي واما ان نكون اول من القى","dt":"[65] قال السحره: يا موسى اما ان تلقي عصاك اولا، واما ان نبدا نحن فنلقي ما معنا."},{"id":"2414","s":20,"a":66,"at":"قال بل القوا فاذا حبالهم وعصيهم يخيل اليه من سحرهم انها تسعى","dt":"[66] قال لهم موسى: بل القوا انتم ما معكم اولا، فالقوا حبالهم وعصيهم، فتخيل موسى من قوه سحرهم انها حيات تسعى،"},{"id":"2415","s":20,"a":67,"at":"فاوجس في نفسه خيفه موسى","dt":"[67] فشعر موسى في نفسه بالخوف."},{"id":"2416","s":20,"a":68,"at":"قلنا لا تخف انك انت الاعلى","dt":"[68] قال الله لموسى حينئذ: لا تخف من شيء، فانك انت الاعلى على هؤلاء السحره وعلى فرعون وجنوده، وستغلبهم."},{"id":"2417","s":20,"a":69,"at":"والق ما في يمينك تلقف ما صنعوا انما صنعوا كيد ساحر ولا يفلح الساحر حيث اتى","dt":"[69] والق عصاك التي في يمينك تبتلع حبالهم وعصيهم، فما عملوه امامك ما هو الا مكر ساحر وتخييل سحر، ولا يظفر الساحر بسحره اين كان."},{"id":"2418","s":20,"a":70,"at":"فالقي السحره سجدا قالوا امنا برب هارون وموسى","dt":"[70] فالقى موسى عصاه، فبلعت ما صنعوا، فظهر الحق وقامت الحجه عليهم. فالقى السحره انفسهم على الارض ساجدين وقالوا: امنا برب هارون وموسى، لو كان هذا سحرا ما غلبنا."},{"id":"2419","s":20,"a":71,"at":"قال امنتم له قبل ان اذن لكم انه لكبيركم الذي علمكم السحر فلاقطعن ايديكم وارجلكم من خلاف ولاصلبنكم في جذوع النخل ولتعلمن اينا اشد عذابا وابقى","dt":"[71] قال فرعون للسحره: اصدقتم بموسى، واتبعتموه، واقررتم له قبل ان اذن لكم بذلك؟ ان موسى لعظيمكم الذي علمكم السحر؛ فلذلك تابعتموه، فلاقطعن ايديكم وارجلكم مخالفا بينها، يدا من جهه ورجلا من الجهه الاخرى، ولاصلبنكم -بربط اجسادكم- على جذوع النخل، ولتعلمن ايها السحره اينا: انا او رب موسى اشد عذابا من الاخر، وادوم له؟"},{"id":"2420","s":20,"a":72,"at":"قالوا لن نؤثرك على ما جاءنا من البينات والذي فطرنا فاقض ما انت قاض انما تقضي هذه الحياه الدنيا","dt":"[72] قال السحره لفرعون: لن نفضلك، فنطيعك ونتبع دينك على ما جاءنا به موسى من البينات الداله على صدقه، ووجوب متابعته وطاعه ربه، ولن نفضل ربوبيتك المزعومه على ربوبيه الله الذي خلقنا، فافعل ما انت فاعل بنا، انما سلطانك في هذه الحياه الدنيا، وما تفعله بنا ما هو الا عذاب منته بانتهائها."},{"id":"2421","s":20,"a":73,"at":"انا امنا بربنا ليغفر لنا خطايانا وما اكرهتنا عليه من السحر والله خير وابقى","dt":"[73] انا امنا بربنا وصدقنا رسوله وعملنا بما جاء به؛ ليعفو ربنا عن ذنوبنا، وما اكرهتنا عليه من عمل السحر في معارضه موسى. والله خير لنا منك –يا فرعون- جزاء لمن اطاعه، وابقى عذابا لمن عصاه وخالف امره."},{"id":"2422","s":20,"a":74,"at":"انه من يات ربه مجرما فان له جهنم لا يموت فيها ولا يحيا","dt":"[74] قال الله تعالى: ان الامر من يات ربه كافرا به فان له نار جهنم يعذب بها، لا يموت فيها فيستريح، ولا يحيا حياه يتلذذ بها."},{"id":"2423","s":20,"a":75,"at":"ومن ياته مؤمنا قد عمل الصالحات فاولئك لهم الدرجات العلا","dt":"[75] ومن يات ربه مؤمنا به قد عمل الاعمال الصالحه فله المنازل العاليه"},{"id":"2424","s":20,"a":76,"at":"جنات عدن تجري من تحتها الانهار خالدين فيها وذلك جزاء من تزكى","dt":"[76] في جنات الاقامه الدائمه، تجري من تحت قصورها واشجارها الانهار ماكثين فيها ابدا، وذلك النعيم المقيم ثواب من الله لمن طهر نفسه من الدنس والخبث والشرك، وعبد الله وحده فاطاعه واجتنب معاصيه، ولقي ربه لا يشرك بعبادته احدا من خلقه."},{"id":"2425","s":20,"a":77,"at":"ولقد اوحينا الى موسى ان اسر بعبادي فاضرب لهم طريقا في البحر يبسا لا تخاف دركا ولا تخشى","dt":"[77] ولقد اوحينا الى موسى: ان اخرج ليلا بعبادي من بني اسرائيل من «مصر»، فاتخذ لهم في البحر طريقا يابسا، لا تخاف من فرعون وجنوده ان يلحقوكم فيدركوكم، ولا تخشى في البحر غرقا."},{"id":"2426","s":20,"a":78,"at":"فاتبعهم فرعون بجنوده فغشيهم من اليم ما غشيهم","dt":"[78] فاسرى موسى ببني اسرائيل، وعبر بهم طريقا في البحر، فاتبعهم فرعون بجنوده، فغمرهم من الماء ما لا يعلم كنهه الا الله، فغرقوا جميعا ونجا موسى وقومه."},{"id":"2427","s":20,"a":79,"at":"واضل فرعون قومه وما هدى","dt":"[79] واضل فرعون قومه بما زينه لهم من الكفر والتكذيب، وما سلك بهم طريق الهدايه."},{"id":"2428","s":20,"a":80,"at":"يابني اسرائيل قد انجيناكم من عدوكم وواعدناكم جانب الطور الايمن ونزلنا عليكم المن والسلوى","dt":"[80] يا بني اسرائيل اذكروا حين انجيناكم من عدوكم فرعون، وجعلنا موعدكم الجانب الايمن من جبل الطور لانزال التوراه عليكم، ونزلنا عليكم في التيه ما تاكلونه، مما يشبه الصمغ طعمه كالعسل والطير الذي يشبه السمانى."},{"id":"2429","s":20,"a":81,"at":"كلوا من طيبات ما رزقناكم ولا تطغوا فيه فيحل عليكم غضبي ومن يحلل عليه غضبي فقد هوى","dt":"[81] كلوا من رزقنا الطيب، ولا تعتدوا فيه بان يظلم بعضكم بعضا، فينزل بكم غضبي، ومن ينزل به غضبي فقد هلك وخسر."},{"id":"2430","s":20,"a":82,"at":"واني لغفار لمن تاب وامن وعمل صالحا ثم اهتدى","dt":"[82] واني لغفار لمن تاب من ذنبه وكفره، وامن بي وعمل الاعمال الصالحه، ثم اهتدى الى الحق واستقام عليه."},{"id":"2431","s":20,"a":83,"at":"وما اعجلك عن قومك ياموسى","dt":"[83] واي شيء اعجلك عن قومك -يا موسى- فسبقتهم الى جانب الطور الايمن، وخلفتهم وراءك؟"},{"id":"2432","s":20,"a":84,"at":"قال هم اولاء على اثري وعجلت اليك رب لترضى","dt":"[84] قال: انهم خلفي سوف يلحقون بي، وسبقتهم اليك -يا ربي- لتزداد عني رضا."},{"id":"2433","s":20,"a":85,"at":"قال فانا قد فتنا قومك من بعدك واضلهم السامري","dt":"[85] قال الله لموسى: فانا قد ابتلينا قومك بعد فراقك اياهم بعباده العجل، وان السامري قد اضلهم."},{"id":"2434","s":20,"a":86,"at":"فرجع موسى الى قومه غضبان اسفا قال ياقوم الم يعدكم ربكم وعدا حسنا افطال عليكم العهد ام اردتم ان يحل عليكم غضب من ربكم فاخلفتم موعدي","dt":"[86] فرجع موسى الى قومه غضبان عليهم حزينا، وقال لهم: يا قوم الم يعدكم ربكم وعدا حسنا بانزال التوراه؟افطال عليكم العهد واستبطاتم الوعد، ام اردتم ان تفعلوا فعلا يحل عليكم بسببه غضب من ربكم، فاخلفتم موعدي وعبدتم العجل، وتركتم الالتزام باوامري؟"},{"id":"2435","s":20,"a":87,"at":"قالوا ما اخلفنا موعدك بملكنا ولكنا حملنا اوزارا من زينه القوم فقذفناها فكذلك القى السامري","dt":"[87] قالوا: يا موسى ما اخلفنا موعدك باختيارنا، ولكنا حملنا اثقالا من حلي قوم فرعون، فالقيناها في حفره فيها نار بامر السامري، فكذلك القى السامري ما كان معه من تربه حافر فرس جبريل عليه السلام."},{"id":"2436","s":20,"a":88,"at":"فاخرج لهم عجلا جسدا له خوار فقالوا هذا الهكم واله موسى فنسي","dt":"[88] فصنع السامري لبني اسرائيل من الذهب عجلا جسدا يخور خوار البقر، فقال المفتونون به منهم للاخرين: هذا هو الهكم واله موسى، نسيه وغفل عنه."},{"id":"2437","s":20,"a":89,"at":"افلا يرون الا يرجع اليهم قولا ولا يملك لهم ضرا ولا نفعا","dt":"[89] افلا يرى الذين عبدوا العجل انه لا يكلمهم ابتداء، ولا يرد عليهم جوابا، ولا يقدر على دفع ضر عنهم، ولا جلب نفع لهم؟"},{"id":"2438","s":20,"a":90,"at":"ولقد قال لهم هارون من قبل ياقوم انما فتنتم به وان ربكم الرحمن فاتبعوني واطيعوا امري","dt":"[90] ولقد قال هارون لبني اسرائيل من قبل رجوع موسى اليهم: يا قوم انما اختبرتم بهذا العجل؛ ليظهر المؤمن منكم من الكافر، وان ربكم الرحمن لا غيره فاتبعوني فيما ادعوكم اليه من عباده الله، واطيعوا امري في اتباع شرعه."},{"id":"2439","s":20,"a":91,"at":"قالوا لن نبرح عليه عاكفين حتى يرجع الينا موسى","dt":"[91] قال عباد العجل منهم: لن نزال مقيمين على عباده العجل حتى يرجع الينا موسى."},{"id":"2440","s":20,"a":92,"at":"قال ياهارون ما منعك اذ رايتهم ضلوا","dt":"[92] قال موسى لاخيه هارون: اي شيء منعك حين رايتهم ضلوا عن دينهم"},{"id":"2441","s":20,"a":93,"at":"الا تتبعن افعصيت امري","dt":"[93] ان لا تتبعني، فتلحق بي وتتركهم؟ افعصيت امري فيما امرتك به من خلافتي والاصلاح بعدي؟"},{"id":"2442","s":20,"a":94,"at":"قال يبنؤم لا تاخذ بلحيتي ولا براسي اني خشيت ان تقول فرقت بين بني اسرائيل ولم ترقب قولي","dt":"[94] ثم اخذ موسى بلحيه هارون وراسه يجره اليه، فقال له هارون: يا بن امي لا تمسك بلحيتي ولا بشعر راسي، اني خفت -ان تركتهم ولحقت بك- ان تقول: فرقت بين بني اسرائيل، ولم تحفظ وصيتي بحسن رعايتهم."},{"id":"2443","s":20,"a":95,"at":"قال فما خطبك ياسامري","dt":"[95] قال موسى للسامري: فما شانك يا سامري؟ وما الذي دعاك الى ما فعلته؟"},{"id":"2444","s":20,"a":96,"at":"قال بصرت بما لم يبصروا به فقبضت قبضه من اثر الرسول فنبذتها وكذلك سولت لي نفسي","dt":"[96] قال السامري: رايت ما لم يروه -وهو جبريل عليه السلام- على فرس، وقت خروجهم من البحر وغرق فرعون وجنوده، فاخذت بكفي ترابا من اثر حافر فرس جبريل، فالقيته على الحلي الذي صنعت منه العجل، فكان عجلا جسدا له خوار؛ بلاء وفتنه، وكذلك زينت لي نفسي الاماره بالسوء هذا الصنيع."},{"id":"2445","s":20,"a":97,"at":"قال فاذهب فان لك في الحياه ان تقول لا مساس وان لك موعدا لن تخلفه وانظر الى الهك الذي ظلت عليه عاكفا لنحرقنه ثم لننسفنه في اليم نسفا","dt":"[97] قال موسى للسامري: فاذهب فان عقوبتك في الحياه الدنيا ان تعيش منبوذا تقول لكل احد: لا امس ولا امس، وان لك موعدا في الاخره لعذابك وعقابك، لن يخلفك الله اياه، وسوف تلقاه، وانظر الى معبودك الذي اقمت على عبادته لنحرقنه بالنار، ثم لنذرونه في البحر ذروا لتذهب به الريح؛ حتى لا يبقى منه اثر."},{"id":"2446","s":20,"a":98,"at":"انما الهكم الله الذي لا اله الا هو وسع كل شيء علما","dt":"[98] انما الهكم -ايها الناس- هو الله الذي لا معبود بحق الا هو، وسع علمه كل شيء."},{"id":"2447","s":20,"a":99,"at":"كذلك نقص عليك من انباء ما قد سبق وقد اتيناك من لدنا ذكرا","dt":"[99] كما قصصنا عليك -ايها الرسول- انباء موسى وفرعون وقومهما، نخبرك بانباء السابقين لك. وقد اتيناك من عندنا هذا القران ذكرى لمن يتذكر."},{"id":"2448","s":20,"a":100,"at":"من اعرض عنه فانه يحمل يوم القيامه وزرا","dt":"[100] من اعرض عن هذا القران، ولم يصدق به، ولم يعمل بما فيه، فانه ياتي ربه يوم القيامه يحمل اثما عظيما."},{"id":"2449","s":20,"a":101,"at":"خالدين فيه وساء لهم يوم القيامه حملا","dt":"[101] خالدين في العذاب، وساءهم ذلك الحمل الثقيل من الاثام؛ حيث اوردهم النار."},{"id":"2450","s":20,"a":102,"at":"يوم ينفخ في الصور ونحشر المجرمين يومئذ زرقا","dt":"[102] يوم ينفخ الملك في «القرن» لصيحه البعث، ونسوق الكافرين ذلكم اليوم وهم زرق، تغيرت الوانهم وعيونهم؛ من شده الاحداث والاهوال."},{"id":"2451","s":20,"a":103,"at":"يتخافتون بينهم ان لبثتم الا عشرا","dt":"[103] يتهامسون بينهم، يقول بعضهم لبعض: ما لبثتم في الحياه الدنيا الا عشره ايام."},{"id":"2452","s":20,"a":104,"at":"نحن اعلم بما يقولون اذ يقول امثلهم طريقه ان لبثتم الا يوما","dt":"[104] نحن اعلم بما يقولون ويسرون حين يقول اعلمهم واوفاهم عقلا: ما لبثتم الا يوما واحدا؛ لقصر مده الدنيا في انفسهم يوم القيامه."},{"id":"2453","s":20,"a":105,"at":"ويسالونك عن الجبال فقل ينسفها ربي نسفا","dt":"[105] ويسالك -ايها الرسول- قومك عن مصير الجبال يوم القيامه، فقل لهم: يزيلها ربي عن اماكنها فيجعلها هباء منبثا."},{"id":"2454","s":20,"a":106,"at":"فيذرها قاعا صفصفا","dt":"[106] فيترك الارض حينئذ منبسطه مستويه ملساء لا نبات فيها،"},{"id":"2455","s":20,"a":107,"at":"لا ترى فيها عوجا ولا امتا","dt":"[107] لا يرى الناظر اليها من استوائها ميلا ولا ارتفاعا ولا انخفاضا."},{"id":"2456","s":20,"a":108,"at":"يومئذ يتبعون الداعي لا عوج له وخشعت الاصوات للرحمن فلا تسمع الا همسا","dt":"[108] في ذلك اليوم يتبع الناس صوت الداعي الى موقف القيامه، لا محيد عن دعوه الداعي؛ لانها حق وصدق لجميع الخلق، وسكنت الاصوات خضوعا للرحمن، فلا تسمع منها الا صوتا خفيا."},{"id":"2457","s":20,"a":109,"at":"يومئذ لا تنفع الشفاعه الا من اذن له الرحمن ورضي له قولا","dt":"[109] في ذلك اليوم لا تنفع الشفاعه احدا من الخلق، الا اذا اذن الرحمن للشافع، ورضي عن المشفوع له، ولا يكون ذلك الا للمؤمن المخلص."},{"id":"2458","s":20,"a":110,"at":"يعلم ما بين ايديهم وما خلفهم ولا يحيطون به علما","dt":"[110] يعلم الله ما بين ايدي الناس من امر القيامه وما خلفهم من امر الدنيا، ولا يحيط خلقه به علما سبحانه وتعالى."},{"id":"2459","s":20,"a":111,"at":"وعنت الوجوه للحي القيوم وقد خاب من حمل ظلما","dt":"[111] وخضعت وجوه الخلائق وذلت لخالقها، الذي له جميع معاني الحياه الكامله كما يليق بجلاله الذي لا يموت، القائم على تدبير كل شيء، المستغني عمن سواه. وقد خسر يوم القيامه من اشرك مع الله احدا من خلقه."},{"id":"2460","s":20,"a":112,"at":"ومن يعمل من الصالحات وهو مؤمن فلا يخاف ظلما ولا هضما","dt":"[112] ومن يعمل صالحات الاعمال وهو مؤمن بربه، فلا يخاف ظلما بزياده سيئاته، ولا هضما بنقص حسناته."},{"id":"2461","s":20,"a":113,"at":"وكذلك انزلناه قرانا عربيا وصرفنا فيه من الوعيد لعلهم يتقون او يحدث لهم ذكرا","dt":"[113] وكما رغبنا اهل الايمان في صالحات الاعمال، وحذرنا اهل الكفر من المقام على معاصيهم وكفرهم باياتنا، انزلنا هذا القران باللسان العربي؛ ليفهموه، وفصلنا فيه انواعا من الوعيد؛ رجاء ان يتقوا ربهم، او يحدث لهم هذا القران تذكره، فيتعظوا، ويعتبروا."},{"id":"2462","s":20,"a":114,"at":"فتعالى الله الملك الحق ولا تعجل بالقران من قبل ان يقضى اليك وحيه وقل رب زدني علما","dt":"[114] فتنزه الله -سبحانه- وارتفع، وتقدس عن كل نقص، الملك الذي قهر سلطانه كل ملك وجبار، المتصرف بكل شيء، الذي هو حق، ووعده حق، ووعيده حق، وكل شيء منه حق. ولا تعجل -ايها الرسول- بمسابقه جبريل في تلقي القران قبل ان يفرغ منه، وقل: رب زدني علما الى ما علمتني."},{"id":"2463","s":20,"a":115,"at":"ولقد عهدنا الى ادم من قبل فنسي ولم نجد له عزما","dt":"[115] ولقد وصينا ادم من قبل ان ياكل من الشجره، الا ياكل منها، وقلنا له: ان ابليس عدو لك ولزوجك، فلا يخرجنكما من الجنه، فتشقى انت وزوجك في الدنيا، فوسوس اليه الشيطان، فاطاعه ادم ونسي الوصيه، ولم نجد له قوه في العزم يحفظ بها ما امر به."},{"id":"2464","s":20,"a":116,"at":"واذ قلنا للملائكه اسجدوا لادم فسجدوا الا ابليس ابى","dt":"[116] واذكر -ايها الرسول- اذ قلنا للملائكه: اسجدوا لادم سجود تحيه واكرام، فاطاعوا وسجدوا، لكن ابليس امتنع من السجود."},{"id":"2465","s":20,"a":117,"at":"فقلنا ياادم ان هذا عدو لك ولزوجك فلا يخرجنكما من الجنه فتشقى","dt":"[117] فقلنا: يا ادم ان ابليس هذا عدو لك ولزوجتك، فاحذرا منه ولا تطيعاه بمعصيتي، فيخرجكما من الجنه، فتشقى اذا اخرجت منها."},{"id":"2466","s":20,"a":118,"at":"ان لك الا تجوع فيها ولا تعرى","dt":"[118] ان لك -يا ادم- نعمه تامه وعطيه مستمره في هذه الجنه ان تاكل فلا تجوع، وان تلبس فلا تعرى."},{"id":"2467","s":20,"a":119,"at":"وانك لا تظما فيها ولا تضحى","dt":"[119] وان لك الا تعطش في هذه الجنه ولا يصيبك حر الشمس."},{"id":"2468","s":20,"a":120,"at":"فوسوس اليه الشيطان قال ياادم هل ادلك على شجره الخلد وملك لا يبلى","dt":"[120] فوسوس الشيطان لادم وقال له: هل ادلك على شجره، ان اكلت منها خلدت فلم تمت، وملكت ملكا لا ينقضي ولا ينقطع؟"},{"id":"2469","s":20,"a":121,"at":"فاكلا منها فبدت لهما سواتهما وطفقا يخصفان عليهما من ورق الجنه وعصى ادم ربه فغوى","dt":"[121] فاكل ادم وحواء من الشجره التي نهاهما الله عنها، فانكشفت لهما عوراتهما، وكانت مستوره عن اعينهما، فاخذا ينزعان من ورق اشجار الجنه ويلصقانه عليهما؛ ليسترا ما انكشف من عوراتهما، وخالف ادم امر ربه، فغوى بالاكل من الشجره التي نهاه الله عن الاقتراب منها."},{"id":"2470","s":20,"a":122,"at":"ثم اجتباه ربه فتاب عليه وهدى","dt":"[122] ثم اصطفى الله ادم وقربه، وقبل توبته، وهداه رشده."},{"id":"2471","s":20,"a":123,"at":"قال اهبطا منها جميعا بعضكم لبعض عدو فاما ياتينكم مني هدى فمن اتبع هداي فلا يضل ولا يشقى","dt":"[123] قال الله تعالى لادم وحواء: اهبطا من الجنه الى الارض جميعا مع ابليس، فانتما وهو اعداء، فان ياتكم مني هدى وبيان فمن اتبع هداي وبياني وعمل بهما فانه يرشد في الدنيا، ويهتدي، ولا يشقى في الاخره بعقاب الله."},{"id":"2472","s":20,"a":124,"at":"ومن اعرض عن ذكري فان له معيشه ضنكا ونحشره يوم القيامه اعمى","dt":"[124] ومن تولى عن ذكري الذي اذكره به فان له في الحياه الاولى معيشه ضيقه شاقه -وان ظهر انه من اهل الفضل واليسار-، ويضيق قبره عليه ويعذب فيه، ونحشره يوم القيامه اعمى عن الرؤيه وعن الحجه."},{"id":"2473","s":20,"a":125,"at":"قال رب لم حشرتني اعمى وقد كنت بصيرا","dt":"[125] قال المعرض عن ذكر الله: رب لم حشرتني اعمى، وقد كنت بصيرا في الدنيا؟"},{"id":"2474","s":20,"a":126,"at":"قال كذلك اتتك اياتنا فنسيتها وكذلك اليوم تنسى","dt":"[126] قال الله تعالى له: حشرتك اعمى؛ لانك اتتك اياتي البينات، فاعرضت عنها، ولم تؤمن بها، وكما تركتها في الدنيا فكذلك اليوم تترك في النار."},{"id":"2475","s":20,"a":127,"at":"وكذلك نجزي من اسرف ولم يؤمن بايات ربه ولعذاب الاخره اشد وابقى","dt":"[127] وهكذا نعاقب من اسرف على نفسه فعصى ربه، ولم يؤمن باياته بعقوبات في الدنيا، ولعذاب الاخره المعد لهم اشد الما وادوم واثبت؛ لانه لا ينقطع ولا ينقضي."},{"id":"2476","s":20,"a":128,"at":"افلم يهد لهم كم اهلكنا قبلهم من القرون يمشون في مساكنهم ان في ذلك لايات لاولي النهى","dt":"[128] افلم يدل قومك -ايها الرسول- على طريق الرشاد كثره من اهلكنا من الامم المكذبه قبلهم، وهم يمشون في ديارهم، ويرون اثار هلاكهم؟ ان في كثره تلك الامم واثار عذابهم لعبرا وعظات لاهل العقول الواعيه."},{"id":"2477","s":20,"a":129,"at":"ولولا كلمه سبقت من ربك لكان لزاما واجل مسمى","dt":"[129] ولولا كلمه سبقت من ربك بتاخير العذاب عنهم، واجل مسمى يقع عنده الهلاك للازمهم في الدنيا عاجلا؛ لانهم يستحقونه؛ بسبب كفرهم."},{"id":"2478","s":20,"a":130,"at":"فاصبر على ما يقولون وسبح بحمد ربك قبل طلوع الشمس وقبل غروبها ومن اناء الليل فسبح واطراف النهار لعلك ترضى","dt":"[130] فاصبر -ايها الرسول- على ما يقوله المكذبون بك من اوصاف واباطيل، وسبح بحمد ربك في صلاه الفجر قبل طلوع الشمس، وفي صلاه العصر قبل غروبها، وفي صلاه العشاء في ساعات الليل، وسبح بحمد ربك اطراف النهار في صلاه الظهر -اذ وقتها طرف النصف الاول والنصف الثاني من النهار- وفي صلاه المغرب؛ كي تثاب على هذه الاعمال بما ترضى به."},{"id":"2479","s":20,"a":131,"at":"ولا تمدن عينيك الى ما متعنا به ازواجا منهم زهره الحياه الدنيا لنفتنهم فيه ورزق ربك خير وابقى","dt":"[131] ولا تنظر الى ما متعنا به هؤلاء المشركين وامثالهم من انواع المتع، فانها زينه زائله في هذه الحياه الدنيا، متعناهم بها؛ لنبتليهم بها، ورزق ربك وثوابه خير لك مما متعناهم به وادوم؛ حيث لا انقطاع له ولا نفاد."},{"id":"2480","s":20,"a":132,"at":"وامر اهلك بالصلاه واصطبر عليها لا نسالك رزقا نحن نرزقك والعاقبه للتقوى","dt":"[132] وامر -ايها النبي- اهلك بالصلاه، واصطبر على ادائها، لا نسالك مالا، نحن نرزقك ونعطيك. والعاقبه الصالحه في الدنيا والاخره لاهل التقوى."},{"id":"2481","s":20,"a":133,"at":"وقالوا لولا ياتينا بايه من ربه او لم تاتهم بينه ما في الصحف الاولى","dt":"[133] وقال مكذبوك -ايها الرسول-: هلا تاتينا بعلامه من ربك تدل على صدقك، او لم ياتهم هذا القران المصدق لما في الكتب السابقه من الحق؟"},{"id":"2482","s":20,"a":134,"at":"ولو انا اهلكناهم بعذاب من قبله لقالوا ربنا لولا ارسلت الينا رسولا فنتبع اياتك من قبل ان نذل ونخزى","dt":"[134] ولو انا اهلكنا هؤلاء المكذبين بعذاب من قبل ان نرسل اليهم رسولا وننزل عليهم كتابا لقالوا: ربنا هلا ارسلت الينا رسولا من عندك، فنصدقه، ونتبع اياتك وشرعك، من قبل ان نذل ونخزى بعذابك."},{"id":"2483","s":20,"a":135,"at":"قل كل متربص فتربصوا فستعلمون من اصحاب الصراط السوي ومن اهتدى","dt":"[135] قل -ايها الرسول- لهؤلاء المشركين بالله: كل منا ومنكم منتظر دوائر الزمان، ولمن يكون النصر والفلاح، فانتظروا، فستعلمون: من اهل الطريق المستقيم، ومن المهتدي للحق منا ومنكم؟"},{"id":"2484","s":21,"a":1,"at":"اقترب للناس حسابهم وهم في غفله معرضون","dt":"[1] دنا وقت حساب الناس على ما قدموا من عمل، ومع ذلك فالكفار يعيشون لاهين عن هذه الحقيقه، معرضين عن هذا الانذار."},{"id":"2485","s":21,"a":2,"at":"ما ياتيهم من ذكر من ربهم محدث الا استمعوه وهم يلعبون","dt":"[2] ما من شيء ينزل من القران يتلى عليهم مجددا لهم التذكير، الا كان سماعهم له سماع لعب واستهزاء."},{"id":"2486","s":21,"a":3,"at":"لاهيه قلوبهم واسروا النجوى الذين ظلموا هل هذا الا بشر مثلكم افتاتون السحر وانتم تبصرون","dt":"[3] قلوبهم غافله عن القران الكريم، مشغوله باباطيل الدنيا وشهواتها، لا يعقلون ما فيه. بل ان الظالمين من قريش اجتمعوا سرا على امر خفي: وهو اشاعه ما يصدون به الناس عن الايمان بمحمد -صلى الله عليه وسلم- من انه بشر مثلهم، لا يختلف عنهم في شيء، وان ما جاء به من القران سحر، فكيف تجيئون اليه وتتبعونه، وانتم تبصرون انه بشر مثلكم؟"},{"id":"2487","s":21,"a":4,"at":"قال ربي يعلم القول في السماء والارض وهو السميع العليم","dt":"[4] رد النبي -صلى الله عليه وسلم- الامر الى ربه سبحانه وتعالى فقال: ربي يعلم القول في السماء والارض، ويعلم ما اسررتموه من حديثكم، وهو السميع لاقوالكم، العليم باحوالكم. وفي هذا تهديد لهم ووعيد."},{"id":"2488","s":21,"a":5,"at":"بل قالوا اضغاث احلام بل افتراه بل هو شاعر فلياتنا بايه كما ارسل الاولون","dt":"[5] بل جحد الكفار القران فمن قائل: انه اخلاط احلام لا حقيقه لها، ومن قائل: انه اختلاق وكذب وليس وحيا، ومن قائل: ان محمدا شاعر، وهذا الذي جاء به شعر، وان اراد منا ان نصدقه فليجئنا بمعجزه محسوسه كناقه صالح، وايات موسى وعيسى، وما جاء به الرسل من قبله."},{"id":"2489","s":21,"a":6,"at":"ما امنت قبلهم من قريه اهلكناها افهم يؤمنون","dt":"[6] ما امنت قبل كفار «مكه» من قريه طلب اهلها المعجزات من رسولهم وتحققت، بل كذبوا، فاهلكناهم، افيؤمن كفار «مكه» اذا تحققت المعجزات التي طلبوها؟ كلا انهم لا يؤمنون."},{"id":"2490","s":21,"a":7,"at":"وما ارسلنا قبلك الا رجالا نوحي اليهم فاسالوا اهل الذكر ان كنتم لا تعلمون","dt":"[7] وما ارسلنا قبلك -ايها الرسول- الا رجالا من البشر نوحي اليهم، ولم نرسل ملائكه، فاسالوا -يا كفار «مكه»- اهل العلم بالكتب المنزله السابقه، ان كنتم تجهلون ذلك."},{"id":"2491","s":21,"a":8,"at":"وما جعلناهم جسدا لا ياكلون الطعام وما كانوا خالدين","dt":"[8] وما جعلنا اولئك المرسلين قبلك خارجين عن طباع البشر لا يحتاجون الى طعام وشراب، وما كانوا خالدين لا يموتون."},{"id":"2492","s":21,"a":9,"at":"ثم صدقناهم الوعد فانجيناهم ومن نشاء واهلكنا المسرفين","dt":"[9] ثم انجزنا للانبياء واتباعهم ما وعدناهم به من النصر والنجاه، واهلكنا المسرفين على انفسهم بكفرهم بربهم."},{"id":"2493","s":21,"a":10,"at":"لقد انزلنا اليكم كتابا فيه ذكركم افلا تعقلون","dt":"[10] لقد انزلنا اليكم هذا القران، فيه عزكم وشرفكم في الدنيا والاخره ان تذكرتم به، افلا تعقلون ما فضلتكم به على غيركم؟"},{"id":"2494","s":21,"a":11,"at":"وكم قصمنا من قريه كانت ظالمه وانشانا بعدها قوما اخرين","dt":"[11] وكثير من القرى كان اهلها ظالمين بكفرهم بما جاءتهم به رسلهم، فاهلكناهم بعذاب ابادهم جميعا، واوجدنا بعدهم قوما اخرين سواهم."},{"id":"2495","s":21,"a":12,"at":"فلما احسوا باسنا اذا هم منها يركضون","dt":"[12] فلما راى هؤلاء الظالمون عذابنا الشديد نازلا بهم، وشاهدوا بوادره، اذا هم من قريتهم يسرعون هاربين."},{"id":"2496","s":21,"a":13,"at":"لا تركضوا وارجعوا الى ما اترفتم فيه ومساكنكم لعلكم تسالون","dt":"[13] فنودوا في هذه الحال: لا تهربوا وارجعوا الى لذاتكم وتنعمكم في دنياكم الملهيه ومساكنكم المشيده، لعلكم تسالون من دنياكم شيئا، وذلك على وجه السخريه والاستهزاء بهم."},{"id":"2497","s":21,"a":14,"at":"قالوا ياويلنا انا كنا ظالمين","dt":"[14] فلم يكن لهم من جواب الا اعترافهم بجرمهم وقولهم: يا هلاكنا، فقد ظلمنا انفسنا بكفرنا."},{"id":"2498","s":21,"a":15,"at":"فما زالت تلك دعواهم حتى جعلناهم حصيدا خامدين","dt":"[15] فما زالت تلك المقاله -وهي الدعاء على انفسهم بالهلاك، والاعتراف بالظلم- دعوتهم يرددونها حتى جعلناهم كالزرع المحصود، خامدين لا حياه فيهم. فاحذروا -ايها المخاطبون- ان تستمروا على تكذيب محمد -صلى الله عليه وسلم-، فيحل بكم ما حل بالامم قبلكم."},{"id":"2499","s":21,"a":16,"at":"وما خلقنا السماء والارض وما بينهما لاعبين","dt":"[16] وما خلقنا السماء والارض وما بينهما عبثا وباطلا، بل لاقامه الحجه عليكم -ايها الناس- ولتعتبروا بذلك كله، فتعلموا ان الذي خلق ذلك لا يشبهه شيء، ولا تصلح العباده الا له."},{"id":"2500","s":21,"a":17,"at":"لو اردنا ان نتخذ لهوا لاتخذناه من لدنا ان كنا فاعلين","dt":"[17] لو اردنا ان نتخذ لهوا من الولد او الصاحبه لاتخذناه من عندنا لا من عندكم، ما كنا فاعلين ذلك؛ لاستحاله ان يكون لنا ولد او صاحبه."},{"id":"2501","s":21,"a":18,"at":"بل نقذف بالحق على الباطل فيدمغه فاذا هو زاهق ولكم الويل مما تصفون","dt":"[18] بل نقذف بالحق ونبينه، فيدحض الباطل، فاذا هو ذاهب مضمحل. ولكم العذاب في الاخره -ايها المشركون- من وصفكم ربكم بغير صفته اللائقه به."},{"id":"2502","s":21,"a":19,"at":"وله من في السموات والارض ومن عنده لا يستكبرون عن عبادته ولا يستحسرون","dt":"[19] ولله سبحانه كل من في السموات والارض، والذين عنده من الملائكه لا يانفون عن عبادته ولا يملونها. فكيف يجوز ان يشرك به ما هو عبده وخلقه؟"},{"id":"2503","s":21,"a":20,"at":"يسبحون الليل والنهار لا يفترون","dt":"[20] يذكرون الله وينزهونه دائما، لا يضعفون ولا يسامون."},{"id":"2504","s":21,"a":21,"at":"ام اتخذوا الهه من الارض هم ينشرون","dt":"[21] كيف يصح للمشركين ان يتخذوا الهه عاجزه من الارض لا تقدر على احياء الموتى؟"},{"id":"2505","s":21,"a":22,"at":"لو كان فيهما الهه الا الله لفسدتا فسبحان الله رب العرش عما يصفون","dt":"[22] لو كان في السموات والارض الهه غير الله سبحانه وتعالى تدبر شؤونهما، لاختل نظامهما، فتنزه الله رب العرش، وتقدس عما يصفه الجاحدون الكافرون، من الكذب والافتراء وكل نقص."},{"id":"2506","s":21,"a":23,"at":"لا يسال عما يفعل وهم يسالون","dt":"[23] ان من دلائل تفرده سبحانه بالخلق والعباده انه لا يسال عن قضائه في خلقه، وجميع خلقه يسالون عن افعالهم."},{"id":"2507","s":21,"a":24,"at":"ام اتخذوا من دونه الهه قل هاتوا برهانكم هذا ذكر من معي وذكر من قبلي بل اكثرهم لا يعلمون الحق فهم معرضون","dt":"[24] هل اتخذ هؤلاء المشركون من غير الله الهه تنفع وتضر وتحيي وتميت؟ قل -ايها الرسول- لهم: هاتوا ما لديكم من البرهان على ما اتخذتموه الهه، فليس في القران الذي جئت به ولا في الكتب السابقه دليل على ما ذهبتم اليه، وما اشركوا الا جهلا وتقليدا، فهم معرضون عن الحق منكرون له."},{"id":"2508","s":21,"a":25,"at":"وما ارسلنا من قبلك من رسول الا نوحي اليه انه لا اله الا انا فاعبدون","dt":"[25] وما ارسلنا من قبلك -ايها الرسول- من رسول الا نوحي اليه انه لا معبود بحق الا الله، فاخلصوا العباده له وحده."},{"id":"2509","s":21,"a":26,"at":"وقالوا اتخذ الرحمن ولدا سبحانه بل عباد مكرمون","dt":"[26] وقال المشركون: اتخذ الرحمن ولدا بزعمهم ان الملائكه بنات الله. تنزه الله عن ذلك؛ فالملائكه عباد الله مقربون مخصوصون بالفضائل،"},{"id":"2510","s":21,"a":27,"at":"لا يسبقونه بالقول وهم بامره يعملون","dt":"[27] وهم في حسن طاعتهم لا يتكلمون الا بما يامرهم به ربهم، ولا يعملون عملا حتى ياذن لهم."},{"id":"2511","s":21,"a":28,"at":"يعلم ما بين ايديهم وما خلفهم ولا يشفعون الا لمن ارتضى وهم من خشيته مشفقون","dt":"[28] وما من اعمال الملائكه عمل سابق او لاحق الا يعلمه الله سبحانه وتعالى، ويحصيه عليهم، ولا يتقدمون بالشفاعه الا لمن ارتضى الله شفاعتهم له، وهم من خوف الله حذرون من مخالفه امره ونهيه."},{"id":"2512","s":21,"a":29,"at":"ومن يقل منهم اني اله من دونه فذلك نجزيه جهنم كذلك نجزي الظالمين","dt":"[29] ومن يدع من الملائكه انه اله مع الله -على سبيل الفرض- فجزاؤه جهنم، مثل ذلك الجزاء نجزي كل ظالم مشرك."},{"id":"2513","s":21,"a":30,"at":"او لم ير الذين كفروا ان السموات والارض كانتا رتقا ففتقناهما وجعلنا من الماء كل شيء حي افلا يؤمنون","dt":"[30] اولم يعلم هؤلاء الذين كفروا ان السموات والارض كانتا ملتصقتين لا فاصل بينهما، فلا مطر من السماء ولا نبات من الارض، ففصلناهما بقدرتنا، وانزلنا المطر من السماء، واخرجنا النبات من الارض، وجعلنا من الماء كل شيء حي، افلا يؤمن هؤلاء الجاحدون فيصدقوا بما يشاهدونه، ويخصوا الله بالعباده؟"},{"id":"2514","s":21,"a":31,"at":"وجعلنا في الارض رواسي ان تميد بهم وجعلنا فيها فجاجا سبلا لعلهم يهتدون","dt":"[31] وخلقنا في الارض جبالا تثبتها حتى لا تضطرب باهلها، وجعلنا فيها طرقا واسعه؛ رجاء اهتداء الخلق الى معايشهم، وتوحيد خالقهم."},{"id":"2515","s":21,"a":32,"at":"وجعلنا السماء سقفا محفوظا وهم عن اياتها معرضون","dt":"[32] وجعلنا السماء سقفا للارض لا يرفعها عماد، وهي محفوظه لا تسقط، ولا تخترقها الشياطين، والكفار عن الاعتبار بايات السماء - الشمس والقمر والنجوم -، غافلون لاهون عن التفكير فيها."},{"id":"2516","s":21,"a":33,"at":"وهو الذي خلق الليل والنهار والشمس والقمر كل في فلك يسبحون","dt":"[33] والله تعالى هو الذي خلق الليل؛ ليسكن الناس فيه، والنهار؛ ليطلبوا فيه المعايش، وخلق الشمس ايه للنهار، والقمر ايه لليل، ولكل منهما مدار يجري فيه ويسبح لا يحيد عنه."},{"id":"2517","s":21,"a":34,"at":"وما جعلنا لبشر من قبلك الخلد افان مت فهم الخالدون","dt":"[34] وما جعلنا لبشر من قبلك -ايها الرسول- دوام البقاء في الدنيا، افان مت فهم يؤملون الخلود بعدك؟ لا يكون هذا. وفي هذه الايه دليل على ان الخضر عليه السلام قد مات؛ لانه بشر."},{"id":"2518","s":21,"a":35,"at":"كل نفس ذائقه الموت ونبلوكم بالشر والخير فتنه والينا ترجعون","dt":"[35] كل نفس ذائقه الموت لا محاله مهما عمرت في الدنيا. وما وجودها في الحياه الا ابتلاء بالتكاليف امرا ونهيا، وبتقلب الاحوال خيرا وشرا، ثم المال والمرجع بعد ذلك الى الله -وحده- للحساب والجزاء."},{"id":"2519","s":21,"a":36,"at":"واذا راك الذين كفروا ان يتخذونك الا هزوا اهذا الذي يذكر الهتكم وهم بذكر الرحمن هم كافرون","dt":"[36] واذا راك الكفار -ايها الرسول- اشاروا اليك ساخرين منك بقول بعضهم لبعض: اهذا الرجل الذي يعيب الهتكم؟ وجحدوا بالرحمن ونعمه، وبما انزله من القران والهدى."},{"id":"2520","s":21,"a":37,"at":"خلق الانسان من عجل ساريكم اياتي فلا تستعجلون","dt":"[37] خلق الانسان عجولا، يبادر الاشياء ويستعجل وقوعها. وقد استعجلت قريش العذاب واستبطات وقوعه، فانذرهم الله بانه سيريهم ما يستعجلونه من العذاب، فلا يسالوا الله تعجيله وسرعته."},{"id":"2521","s":21,"a":38,"at":"ويقولون متى هذا الوعد ان كنتم صادقين","dt":"[38] ويقول الكفار -مستعجلين العذاب مستهزئين-: متى حصول ما تعدنا به يا محمد، ان كنت انت ومن اتبعك من الصادقين؟"},{"id":"2522","s":21,"a":39,"at":"لو يعلم الذين كفروا حين لا يكفون عن وجوههم النار ولا عن ظهورهم ولا هم ينصرون","dt":"[39] لو يعلم هؤلاء الكفار ما يلاقونه عندما لا يستطيعون ان يدفعوا عن وجوههم وظهورهم النار، ولا يجدون لهم ناصرا ينصرهم؛ لما اقاموا على كفرهم، ولما استعجلوا عذابهم."},{"id":"2523","s":21,"a":40,"at":"بل تاتيهم بغته فتبهتهم فلا يستطيعون ردها ولا هم ينظرون","dt":"[40] ولسوف تاتيهم الساعه فجاه، فيتحيرون عند ذلك، ويخافون خوفا عظيما، ولا يستطيعون دفع العذاب عن انفسهم، ولا يمهلون لاستدراك توبه ولا اعتذار."},{"id":"2524","s":21,"a":41,"at":"ولقد استهزئ برسل من قبلك فحاق بالذين سخروا منهم ما كانوا به يستهزئون","dt":"[41] ولقد استهزئ برسل من قبلك ايها الرسول، فحل بالذين كانوا يستهزئون بهم العذاب الذي كان مثار سخريتهم واستهزائهم."},{"id":"2525","s":21,"a":42,"at":"قل من يكلؤكم بالليل والنهار من الرحمن بل هم عن ذكر ربهم معرضون","dt":"[42] قل -ايها الرسول- لهؤلاء المستعجلين بالعذاب: لا احد يحفظكم ويحرسكم في ليلكم او نهاركم، في نومكم او يقظتكم، من باس الرحمن اذا نزل بكم. بل هم عن القران ومواعظ ربهم لاهون غافلون."},{"id":"2526","s":21,"a":43,"at":"ام لهم الهه تمنعهم من دوننا لا يستطيعون نصر انفسهم ولا هم منا يصحبون","dt":"[43] ا لهم الهه تمنعهم من عذابنا؟ ان الهتهم لا يستطيعون ان ينصروا انفسهم، فكيف ينصرون عابديهم؟ وهم منا لا يجارون."},{"id":"2527","s":21,"a":44,"at":"بل متعنا هؤلاء واباءهم حتى طال عليهم العمر افلا يرون انا ناتي الارض ننقصها من اطرافها افهم الغالبون","dt":"[44] لقد اغتر الكفار واباؤهم بالامهال لما راوه من الاموال والبنين وطول الاعمار، فاقاموا على كفرهم لا يبرحونه، وظنوا انهم لا يعذبون وقد غفلوا عن سنه ماضيه، فالله ينقص الارض من جوانبها بما ينزله بالمشركين من باس في كل ناحيه ومن هزيمه، ايكون بوسع كفار «مكه» الخروج عن قدره الله، او الامتناع من الموت؟"},{"id":"2528","s":21,"a":45,"at":"قل انما انذركم بالوحي ولا يسمع الصم الدعاء اذا ما ينذرون","dt":"[45] قل -ايها الرسول- لمن ارسلت اليهم: ما اخوفكم من العذاب الا بوحي من الله، وهو القران، ولكن الكفار لا يسمعون ما يلقى اليهم سماع تدبر اذا انذروا، فلا ينتفعون به."},{"id":"2529","s":21,"a":46,"at":"ولئن مستهم نفحه من عذاب ربك ليقولن ياويلنا انا كنا ظالمين","dt":"[46] لو اصاب الكفار نصيب من عذاب الله لعلموا عاقبه تكذيبهم، وقابلوا ذلك بالدعاء على انفسهم بالهلاك؛ بسبب ظلمهم لانفسهم بعبادتهم غير الله."},{"id":"2530","s":21,"a":47,"at":"ونضع الموازين القسط ليوم القيامه فلا تظلم نفس شيئا وان كان مثقال حبه من خردل اتينا بها وكفى بنا حاسبين","dt":"[47] ويضع الله تعالى الميزان العادل للحساب في يوم القيامه، ولا يظلم هؤلاء ولا غيرهم شيئا، وان كان هذا العمل قدر ذره من خير او شر عدت في حساب صاحبها. وكفى بالله محصيا اعمال عباده، ومجازيا لهم عليها."},{"id":"2531","s":21,"a":48,"at":"ولقد اتينا موسى وهارون الفرقان وضياء وذكرا للمتقين","dt":"[48] ولقد اتينا موسى وهارون حجه ونصرا على عدوهما، وكتابا -وهو التوراه- فرقنا به بين الحق والباطل، ونورا يهتدي به المتقون"},{"id":"2532","s":21,"a":49,"at":"الذين يخشون ربهم بالغيب وهم من الساعه مشفقون","dt":"[49] الذين يخافون عقاب ربهم، وهم من الساعه التي تقوم فيها القيامه خائفون وجلون."},{"id":"2533","s":21,"a":50,"at":"وهذا ذكر مبارك انزلناه افانتم له منكرون","dt":"[50] وهذا القران الذي انزله الله على رسوله محمد -صلى الله عليه وسلم- ذكر لمن تذكر به، وعمل باوامره واجتنب نواهيه، كثير الخير، عظيم النفع، افتنكرونه وهو في غايه الجلاء والظهور؟"},{"id":"2534","s":21,"a":51,"at":"ولقد اتينا ابراهيم رشده من قبل وكنا به عالمين","dt":"[51] ولقد اتينا ابراهيم هداه، الذي دعا الناس اليه من قبل موسى وهارون، وكنا عالمين انه اهل لذلك."},{"id":"2535","s":21,"a":52,"at":"اذ قال لابيه وقومه ما هذه التماثيل التي انتم لها عاكفون","dt":"[52] حين قال لابيه وقومه: ما هذه الاصنام التي صنعتموها، ثم اقمتم على عبادتها ملازمين لها؟"},{"id":"2536","s":21,"a":53,"at":"قالوا وجدنا اباءنا لها عابدين","dt":"[53] قالوا: وجدنا اباءنا عابدين لها، ونحن نعبدها اقتداء بهم."},{"id":"2537","s":21,"a":54,"at":"قال لقد كنتم انتم واباؤكم في ضلال مبين","dt":"[54] قال لهم ابراهيم: لقد كنتم انتم واباؤكم في عبادتكم لهذه الاصنام في بعد واضح بين عن الحق."},{"id":"2538","s":21,"a":55,"at":"قالوا اجئتنا بالحق ام انت من اللاعبين","dt":"[55] قالوا: اهذا القول الذي جئتنا به حق وجد، ام كلامك لنا كلام لاعب مستهزئ لا يدري ما يقول؟"},{"id":"2539","s":21,"a":56,"at":"قال بل ربكم رب السموات والارض الذي فطرهن وانا على ذلكم من الشاهدين","dt":"[56] قال لهم ابراهيم عليه الصلاه والسلام: بل ربكم الذي ادعوكم الى عبادته هو رب السموات والارض الذي خلقهن، وانا من الشاهدين على ذلك."},{"id":"2540","s":21,"a":57,"at":"وتالله لاكيدن اصنامكم بعد ان تولوا مدبرين","dt":"[57] وتالله لامكرن باصنامكم ولاكسرنها بعد ان تتولوا عنها ذاهبين."},{"id":"2541","s":21,"a":58,"at":"فجعلهم جذاذا الا كبيرا لهم لعلهم اليه يرجعون","dt":"[58] فحطم ابراهيم الاصنام وجعلها قطعا صغيره، وترك كبيرها؛ كي يرجع القوم اليه ويسالوه، فيتبين عجزهم وضلالهم، وتقوم الحجه عليهم."},{"id":"2542","s":21,"a":59,"at":"قالوا من فعل هذا بالهتنا انه لمن الظالمين","dt":"[59] ورجع القوم، وراوا اصنامهم محطمه مهانه، فسال بعضهم بعضا: من فعل هذا بالهتنا؟ انه لظالم في اجترائه على الالهه المستحقه للتعظيم والتوقير."},{"id":"2543","s":21,"a":60,"at":"قالوا سمعنا فتى يذكرهم يقال له ابراهيم","dt":"[60] قال من سمع ابراهيم يحلف بانه سيكيد اصنامهم: سمعنا فتى يذكر الاصنام بسوء يقال له ابراهيم."},{"id":"2544","s":21,"a":61,"at":"قالوا فاتوا به على اعين الناس لعلهم يشهدون","dt":"[61] قال رؤساؤهم: فاتوا بابراهيم على مراى من الناس؛ كي يشهدوا على اعترافه بما قال؛ ليكون ذلك حجه عليه."},{"id":"2545","s":21,"a":62,"at":"قالوا اانت فعلت هذا بالهتنا ياابراهيم","dt":"[62] وجيء بابراهيم وسالوه منكرين: اانت الذي كسرت الهتنا؟ يعنون اصنامهم."},{"id":"2546","s":21,"a":63,"at":"قال بل فعله كبيرهم هذا فاسالوهم ان كانوا ينطقون","dt":"[63] وتم لابراهيم ما اراد من اظهار سفههم على مراى منهم. فقال محتجا عليهم معرضا بغباوتهم: بل الذي كسرها هذا الصنم الكبير، فاسالوا الهتكم المزعومه عن ذلك، ان كانت تتكلم او ترد جوابا."},{"id":"2547","s":21,"a":64,"at":"فرجعوا الى انفسهم فقالوا انكم انتم الظالمون","dt":"[64] فاسقط في ايديهم، وبدا لهم ضلالهم؛ كيف يعبدونها، وهي عاجزه عن ان تدفع عن نفسها شيئا او ان تجيب سائلها؟ واقروا على انفسهم بالظلم والشرك."},{"id":"2548","s":21,"a":65,"at":"ثم نكسوا على رءوسهم لقد علمت ما هؤلاء ينطقون","dt":"[65] وسرعان ما عاد اليهم عنادهم بعد افحامهم، فانقلبوا الى الباطل، واحتجوا على ابراهيم بما هو حجه له عليهم، فقالوا: كيف نسالها، وقد علمت انها لا تنطق؟"},{"id":"2549","s":21,"a":66,"at":"قال افتعبدون من دون الله ما لا ينفعكم شيئا ولا يضركم","dt":"[66] قال ابراهيم محقرا لشان الاصنام: كيف تعبدون اصناما لا تنفع اذا عبدت، ولا تضر اذا تركت؟"},{"id":"2550","s":21,"a":67,"at":"اف لكم ولما تعبدون من دون الله افلا تعقلون","dt":"[67] قبحا لكم ولالهتكم التي تعبدونها من دون الله تعالى، افلا تعقلون فتدركون سوء ما انتم عليه؟"},{"id":"2551","s":21,"a":68,"at":"قالوا حرقوه وانصروا الهتكم ان كنتم فاعلين","dt":"[68] لما بطلت حجتهم وظهر الحق عدلوا الى استعمال سلطانهم، وقالوا: حرقوا ابراهيم بالنار؛ غضبا لالهتكم ان كنتم ناصرين لها."},{"id":"2552","s":21,"a":69,"at":"قلنا يانار كوني بردا وسلاما على ابراهيم","dt":"[69] فاشعلوا نارا عظيمه والقوه فيها، فانتصر الله لرسوله وقال للنار: كوني بردا وسلاما على ابراهيم، فلم ينله فيها اذى، ولم يصبه مكروه."},{"id":"2553","s":21,"a":70,"at":"وارادوا به كيدا فجعلناهم الاخسرين","dt":"[70] واراد القوم بابراهيم الهلاك فابطل الله كيدهم، وجعلهم المغلوبين الاسفلين."},{"id":"2554","s":21,"a":71,"at":"ونجيناه ولوطا الى الارض التي باركنا فيها للعالمين","dt":"[71] ونجينا ابراهيم ولوطا الذي امن به من «العراق»، واخرجناهما الى ارض «الشام» التي باركنا فيها بكثره الخيرات، وفيها اكثر الانبياء عليهم الصلاه والسلام."},{"id":"2555","s":21,"a":72,"at":"ووهبنا له اسحاق ويعقوب نافله وكلا جعلنا صالحين","dt":"[72] وانعم الله على ابراهيم، فوهب له ابنه اسحاق حين دعاه، ووهب له من اسحاق يعقوب زياده على ذلك، وكل من ابراهيم واسحاق ويعقوب جعله الله صالحا مطيعا له."},{"id":"2556","s":21,"a":73,"at":"وجعلناهم ائمه يهدون بامرنا واوحينا اليهم فعل الخيرات واقام الصلاه وايتاء الزكاه وكانوا لنا عابدين","dt":"[73] وجعلنا ابراهيم واسحاق ويعقوب قدوه للناس يدعونهم الى عباده الله وطاعته باذنه تعالى، واوحينا اليهم فعل الخيرات من العمل بشرائع الانبياء، واقام الصلاه على وجهها، وايتاء الزكاه، فامتثلوا لذلك، وكانوا منقادين مطيعين لله وحده دون سواه."},{"id":"2557","s":21,"a":74,"at":"ولوطا اتيناه حكما وعلما ونجيناه من القريه التي كانت تعمل الخبائث انهم كانوا قوم سوء فاسقين","dt":"[74] واتينا لوطا النبوه وفصل القضاء بين الخصوم وعلما بامر الله ودينه، ونجيناه من قريته «سدوم» التي كان يعمل اهلها الخبائث. انهم كانوا بسبب الخبائث والمنكرات التي ياتونها اهل سوء وقبح، خارجين عن طاعه الله."},{"id":"2558","s":21,"a":75,"at":"وادخلناه في رحمتنا انه من الصالحين","dt":"[75] واتم الله عليه النعمه فادخله في رحمته بانجائه مما حل بقومه؛ لانه كان من الذين يعملون بطاعه الله."},{"id":"2559","s":21,"a":76,"at":"ونوحا اذ نادى من قبل فاستجبنا له فنجيناه واهله من الكرب العظيم","dt":"[76] واذكر -ايها الرسول- نوحا حين نادى ربه من قبلك ومن قبل ابراهيم ولوط، فاستجبنا له دعاءه، فنجيناه واهله المؤمنين به من الغم الشديد."},{"id":"2560","s":21,"a":77,"at":"ونصرناه من القوم الذين كذبوا باياتنا انهم كانوا قوم سوء فاغرقناهم اجمعين","dt":"[77] ونصرناه من كيد القوم الذين كذبوا باياتنا الداله على صدقه، انهم كانوا اهل قبح، فاغرقناهم بالطوفان اجمعين."},{"id":"2561","s":21,"a":78,"at":"وداود وسليمان اذ يحكمان في الحرث اذ نفشت فيه غنم القوم وكنا لحكمهم شاهدين","dt":"[78] واذكر -ايها الرسول- نبي الله داود وابنه سليمان، اذ يحكمان في قضيه عرضها خصمان، عدت غنم احدهما على زرع الاخر، وانتشرت فيه ليلا، فاتلفت الزرع، فحكم داود بان تكون الغنم لصاحب الزرع ملكا بما اتلفته، فقيمتهما سواء، وكنا لحكمهم شاهدين لم يغب عنا."},{"id":"2562","s":21,"a":79,"at":"ففهمناها سليمان وكلا اتينا حكما وعلما وسخرنا مع داود الجبال يسبحن والطير وكنا فاعلين","dt":"[79] ففهمنا سليمان مراعاه مصلحه الطرفين مع العدل، فحكم على صاحب الغنم باصلاح الزرع التالف في فتره يستفيد فيها صاحب الزرع بمنافع الغنم من لبن وصوف ونحوهما، ثم تعود الغنم الى صاحبها والزرع الى صاحبه؛ لمساواه قيمه ما تلف من الزرع لمنفعه الغنم، وكلا من داود وسليمان اعطيناه حكما وعلما، ومننا على داود بتطويع الجبال تسبح معه اذا سبح، وكذلك الطير تسبح، وكنا فاعلين ذلك."},{"id":"2563","s":21,"a":80,"at":"وعلمناه صنعه لبوس لكم لتحصنكم من باسكم فهل انتم شاكرون","dt":"[80] واختص الله داود عليه السلام بان علمه صناعه الدروع يعملها حلقا متشابكه، تسهل حركه الجسم؛ لتحمي المحاربين من وقع السلاح فيهم، فهل انتم شاكرون نعمه الله عليكم حيث اجراها على يد عبده داود؟"},{"id":"2564","s":21,"a":81,"at":"ولسليمان الريح عاصفه تجري بامره الى الارض التي باركنا فيها وكنا بكل شيء عالمين","dt":"[81] وسخرنا لسليمان الريح شديده الهبوب تحمله ومن معه، تجري بامره الى ارض «بيت المقدس» ب«الشام» التي باركنا فيها بالخيرات الكثيره، وقد احاط علمنا بجميع الاشياء."},{"id":"2565","s":21,"a":82,"at":"ومن الشياطين من يغوصون له ويعملون عملا دون ذلك وكنا لهم حافظين","dt":"[82] وسخرنا لسليمان من الشياطين شياطين يستخدمهم فيما يعجز عنه غيرهم، فكانوا يغوصون في البحر يستخرجون له اللالئ والجواهر، وكانوا يعملون كذلك في صناعه ما يريده منهم، لا يقدرون على الامتناع مما يريده منهم، حفظهم الله له بقوته وعزه سبحانه وتعالى."},{"id":"2566","s":21,"a":83,"at":"وايوب اذ نادى ربه اني مسني الضر وانت ارحم الراحمين","dt":"[83] واذكر -ايها الرسول- عبدنا ايوب، اذ ابتليناه بضر وسقم عظيم في جسده، وفقد اهله وماله وولده، فصبر واحتسب، ونادى ربه عز وجل اني قد اصابني الضر، وانت ارحم الراحمين، فاكشفه عني."},{"id":"2567","s":21,"a":84,"at":"فاستجبنا له فكشفنا ما به من ضر واتيناه اهله ومثلهم معهم رحمه من عندنا وذكرى للعابدين","dt":"[84] فاستجبنا له دعاءه، ورفعنا عنه البلاء، ورددنا عليه ما فقده من اهل وولد ومال مضاعفا، فعلنا به ذلك رحمه منا، وليكون قدوه لكل صابر على البلاء، راج رحمه ربه، عابد له."},{"id":"2568","s":21,"a":85,"at":"واسماعيل وادريس وذا الكفل كل من الصابرين","dt":"[85] واذكر اسماعيل وادريس وذا الكفل، كل هؤلاء من الصابرين على طاعه الله سبحانه وتعالى، وعن معاصيه، وعلى اقداره، فاستحقوا الذكر بالثناء الجميل."},{"id":"2569","s":21,"a":86,"at":"وادخلناهم في رحمتنا انهم من الصالحين","dt":"[86] وادخلناهم في رحمتنا، انهم ممن صلح باطنه وظاهره، فاطاع الله وعمل بما امره به."},{"id":"2570","s":21,"a":87,"at":"وذا النون اذ ذهب مغاضبا فظن ان لن نقدر عليه فنادى في الظلمات ان لا اله الا انت سبحانك اني كنت من الظالمين","dt":"[87] واذكر قصه صاحب الحوت، وهو يونس بن متى عليه السلام، ارسله الله الى قومه فدعاهم فلم يؤمنوا، فتوعدهم بالعذاب فلم ينيبوا، ولم يصبر عليهم كما امره الله، وخرج من بينهم غاضبا عليهم، ضائقا صدره بعصيانهم، وظن ان الله لن يضيق عليه ويؤاخذه بهذه المخالفه، فابتلاه الله بشده الضيق والحبس، والتقمه الحوت في البحر، فنادى ربه في ظلمات الليل والبحر وبطن الحوت -تائبا معترفا بظلمه؛ لتركه الصبر على قومه- قائلا: لا اله الا انت سبحانك، اني كنت من الظالمين."},{"id":"2571","s":21,"a":88,"at":"فاستجبنا له ونجيناه من الغم وكذلك ننجي المؤمنين","dt":"[88] فاستجبنا له دعاءه، وخلصناه من غم هذه الشده، وكذلك ننجي المصدقين العاملين بشرعنا."},{"id":"2572","s":21,"a":89,"at":"وزكريا اذ نادى ربه رب لا تذرني فردا وانت خير الوارثين","dt":"[89] واذكر -ايها الرسول- قصه عبد الله زكريا حين دعا ربه ان يرزقه الذريه لما كبرت سنه قائلا: رب لا تتركني وحيدا لا عقب لي، هب لي وارثا يقوم بامر الدين في الناس من بعدي، وانت خير الباقين وخير من خلفني بخير."},{"id":"2573","s":21,"a":90,"at":"فاستجبنا له ووهبنا له يحيى واصلحنا له زوجه انهم كانوا يسارعون في الخيرات ويدعوننا رغبا ورهبا وكانوا لنا خاشعين","dt":"[90] فاستجبنا له دعاءه ووهبنا له على الكبر ابنه يحيى، وجعلنا زوجته صالحه في اخلاقها وصالحه للحمل والولاده بعد ان كانت عاقرا، انهم كانوا يبادرون الى كل خير، ويدعوننا راغبين فيما عندنا، خائفين من عقوبتنا، وكانوا لنا خاضعين متواضعين."},{"id":"2574","s":21,"a":91,"at":"والتي احصنت فرجها فنفخنا فيها من روحنا وجعلناها وابنها ايه للعالمين","dt":"[91] واذكر -ايها الرسول- قصه مريم بنت عمران التي حفظت فرجها من الحرام، ولم تات فاحشه في حياتها، فارسل الله اليها جبريل عليه السلام، فنفخ في جيب قميصها، فوصلت النفخه الى رحمها، فخلق الله بذلك النفخ المسيح عيسى عليه السلام، فحملت به من غير زوج، فكانت هي وابنها بذلك علامه على قدره الله، وعبره للخلق الى قيام الساعه."},{"id":"2575","s":21,"a":92,"at":"ان هذه امتكم امه واحده وانا ربكم فاعبدون","dt":"[92] هؤلاء الانبياء جميعا دينهم واحد، الاسلام، وهو الاستسلام لله بالطاعه وافراده بالعباده، والله سبحانه وتعالى رب الخلق فاعبدوه -ايها الناس- وحده لا شريك له."},{"id":"2576","s":21,"a":93,"at":"وتقطعوا امرهم بينهم كل الينا راجعون","dt":"[93] لكن الناس اختلفوا على رسلهم، وتفرق كثير من اتباعهم في الدين شيعا واحزابا، فعبدوا المخلوقين والاهواء، وكلهم راجعون الينا ومحاسبون على ما فعلوا."},{"id":"2577","s":21,"a":94,"at":"فمن يعمل من الصالحات وهو مؤمن فلا كفران لسعيه وانا له كاتبون","dt":"[94] فمن التزم الايمان بالله ورسله، وعمل ما يستطيع من صالح الاعمال طاعه لله وعباده له فلا يضيع الله عمله ولا يبطله، بل يضاعفه كله اضعافا كثيره، وسيجد ما عمله في كتابه يوم يبعث بعد موته."},{"id":"2578","s":21,"a":95,"at":"وحرام على قريه اهلكناها انهم لا يرجعون","dt":"[95] وممتنع على اهل القرى التي اهلكناها بسبب كفرهم وظلمهم، رجوعهم الى الدنيا قبل يوم القيامه؛ ليستدركوا ما فرطوا فيه."},{"id":"2579","s":21,"a":96,"at":"حتى اذا فتحت ياجوج وماجوج وهم من كل حدب ينسلون","dt":"[96] فاذا فتح سد ياجوج وماجوج، وانطلقوا من مرتفعات الارض وانتشروا في جنباتها مسرعين،"},{"id":"2580","s":21,"a":97,"at":"واقترب الوعد الحق فاذا هي شاخصه ابصار الذين كفروا ياويلنا قد كنا في غفله من هذا بل كنا ظالمين","dt":"[97] دنا يوم القيامه وبدت اهواله فاذا ابصار الكفار من شده الفزع مفتوحه لا تكاد تطرف، يدعون على انفسهم بالويل في حسره: يا ويلنا قد كنا لاهين غافلين عن هذا اليوم وعن الاعداد له، وكنا بذلك ظالمين."},{"id":"2581","s":21,"a":98,"at":"انكم وما تعبدون من دون الله حصب جهنم انتم لها واردون","dt":"[98] انكم -ايها الكفار- وما كنتم تعبدون من دون الله من الاصنام ومن رضي بعبادتكم اياه من الجن والانس، وقود جهنم وحطبها، انتم وهم فيها داخلون."},{"id":"2582","s":21,"a":99,"at":"لو كان هؤلاء الهه ما وردوها وكل فيها خالدون","dt":"[99] لو كان هؤلاء الذين عبدتموهم من دون الله تعالى الهه تستحق العباده ما دخلوا نار جهنم معكم ايها المشركون، ان كلا من العابدين والمعبودين خالدون في نار جهنم."},{"id":"2583","s":21,"a":100,"at":"لهم فيها زفير وهم فيها لا يسمعون","dt":"[100] لهؤلاء المعذبين في النار الام ينبئ عنها زفيرهم الذي تندفع فيه انفاسهم من صدورهم بشده، وهم في النار لا يسمعون؛ من هول عذابهم."},{"id":"2584","s":21,"a":101,"at":"ان الذين سبقت لهم منا الحسنى اولئك عنها مبعدون","dt":"[101] ان الذين سبقت لهم منا سابقه السعاده الحسنه في علمنا بكونهم من اهل الجنه، اولئك عن النار مبعدون، فلا يدخلونها ولا يكونون قريبا منها."},{"id":"2585","s":21,"a":102,"at":"لا يسمعون حسيسها وهم في ما اشتهت انفسهم خالدون","dt":"[102] لا يسمعون صوت لهيبها واحتراق الاجساد فيها، فقد سكنوا منازلهم في الجنه، واصبحوا فيما تشتهيه نفوسهم من نعيمها ولذاتها مقيمين اقامه دائمه."},{"id":"2586","s":21,"a":103,"at":"لا يحزنهم الفزع الاكبر وتتلقاهم الملائكه هذا يومكم الذي كنتم توعدون","dt":"[103] لا يخيفهم الهول العظيم يوم القيامه، بل تبشرهم الملائكه: هذا يومكم الذي وعدتم فيه الكرامه من الله وجزيل الثواب."},{"id":"2587","s":21,"a":104,"at":"يوم نطوي السماء كطي السجل للكتب كما بدانا اول خلق نعيده وعدا علينا انا كنا فاعلين","dt":"[104] يوم نطوي السماء كما تطوى الصحيفه على ما كتب فيها، ونبعث فيه الخلق على هيئه خلقنا لهم اول مره، كما ولدتهم امهاتهم، ذلك وعد الله الذي لا يخلف، وعدنا بذلك وعدا حقا علينا، انا كنا فاعلين دائما ما نعد به."},{"id":"2588","s":21,"a":105,"at":"ولقد كتبنا في الزبور من بعد الذكر ان الارض يرثها عبادي الصالحون","dt":"[105] ولقد كتبنا في الكتب المنزله من بعد ما كتب في اللوح المحفوظ: ان الارض يرثها عباد الله الصالحون الذين قاموا بما امروا به، واجتنبوا ما نهوا عنه، وهم امه محمد -صلى الله عليه وسلم-."},{"id":"2589","s":21,"a":106,"at":"ان في هذا لبلاغا لقوم عابدين","dt":"[106] ان في هذا المتلو من الموعظه لعبره كافيه لقوم عابدين الله بما شرعه لهم ورضيه منهم."},{"id":"2590","s":21,"a":107,"at":"وما ارسلناك الا رحمه للعالمين","dt":"[107] وما ارسلناك -ايها الرسول- الا رحمه لجميع الناس، فمن امن بك سعد ونجا، ومن لم يؤمن خاب وخسر."},{"id":"2591","s":21,"a":108,"at":"قل انما يوحى الي انما الهكم اله واحد فهل انتم مسلمون","dt":"[108] قل: ان الذي اوحي الي وبعثت به: ان الهكم الذي يستحق العباده وحده هو الله، فاسلموا له، وانقادوا لعبادته."},{"id":"2592","s":21,"a":109,"at":"فان تولوا فقل اذنتكم على سواء وان ادري اقريب ام بعيد ما توعدون","dt":"[109] فان اعرض هؤلاء عن الاسلام فقل لهم: ابلغكم جميعا ما اوحاه الله تعالى الي، فانا وانتم مستوون في العلم لما انذرتكم وحذرتكم، ولست اعلم -بعد ذلك- متى يحل بكم ما وعدتم به من العذاب."},{"id":"2593","s":21,"a":110,"at":"انه يعلم الجهر من القول ويعلم ما تكتمون","dt":"[110] ان الله يعلم ما تجهرون به من اقوالكم، وما تكتمونه في سرائركم، وسيحاسبكم عليه."},{"id":"2594","s":21,"a":111,"at":"وان ادري لعله فتنه لكم ومتاع الى حين","dt":"[111] ولست ادري لعل تاخير العذاب الذي استعجلتموه استدراج لكم وابتلاء، وان تتمتعوا في الدنيا الى حين؛ لتزدادوا كفرا، ثم يكون اعظم لعقوبتكم."},{"id":"2595","s":21,"a":112,"at":"قال رب احكم ‎ بالحق وربنا الرحمن المستعان على ما تصفون","dt":"[112] قال النبي -صلى الله عليه وسلم-: رب افصل بيننا وبين قومنا المكذبين بالقضاء الحق. ونسال ربنا الرحمن، ونستعين به على ما تصفونه -ايها الكفار- من الشرك والتكذيب والافتراء عليه، وما تتوعدوننا به من الظهور والغلبه."},{"id":"2596","s":22,"a":1,"at":"ياايها الناس اتقوا ربكم ان زلزله الساعه شيء عظيم","dt":"[1] يا ايها الناس احذروا عقاب الله بامتثال اوامره واجتناب نواهيه، ان ما يحدث عند قيام الساعه من اهوال وحركه شديده للارض، تتصدع منها كل جوانبها، شيء عظيم، لا يقدر قدره ولا يبلغ كنهه، ولا يعلم كيفيته الا رب العالمين."},{"id":"2597","s":22,"a":2,"at":"يوم ترونها تذهل كل مرضعه عما ارضعت وتضع كل ذات حمل حملها وترى الناس سكارى وما هم بسكارى ولكن عذاب الله شديد","dt":"[2] يوم ترون قيام الساعه تنسى الوالده رضيعها الذي القمته ثديها؛ لما نزل بها من الكرب، وتسقط الحامل حملها من الرعب، وتغيب عقول الناس، فهم كالسكارى من شده الهول والفزع، وليسوا بسكارى من الخمر، ولكن شده الهول افقدتهم عقولهم وادراكهم."},{"id":"2598","s":22,"a":3,"at":"ومن الناس من يجادل في الله بغير علم ويتبع كل شيطان مريد","dt":"[3] وبعض رؤوس الكفر من الناس يخاصمون ويشككون في قدره الله على البعث؛ جهلا منهم بحقيقه هذه القدره، واتباعا لائمه الضلال من كل شيطان متمرد على الله ورسله."},{"id":"2599","s":22,"a":4,"at":"كتب عليه انه من تولاه فانه يضله ويهديه الى عذاب السعير","dt":"[4] قضى الله وقدر على هذا الشيطان انه يضل كل من اتبعه، ولا يهديه الى الحق، بل يسوقه الى عذاب جهنم الموقده جزاء اتباعه اياه."},{"id":"2600","s":22,"a":5,"at":"ياايها الناس ان كنتم في ريب من البعث فانا خلقناكم من تراب ثم من نطفه ثم من علقه ثم من مضغه مخلقه وغير مخلقه لنبين لكم ونقر في الارحام ما نشاء الى اجل مسمى ثم نخرجكم طفلا ثم لتبلغوا اشدكم ومنكم من يتوفى ومنكم من يرد الى ارذل العمر لكيلا يعلم من بعد علم شيئا وترى الارض هامده فاذا انزلنا عليها الماء اهتزت وربت وانبتت من كل زوج بهيج","dt":"[5] يا ايها الناس ان كنتم في شك من ان الله يحيي الموتى فانا خلقنا اباكم ادم من تراب، ثم تناسلت ذريته من نطفه، هي المني يقذفه الرجل في رحم المراه، فيتحول بقدره الله الى علقه، وهي الدم الاحمر الغليظ، ثم الى مضغه، وهي قطعه لحم صغيره قدر ما يمضغ، فتكون تاره مخلقه، اي تامه الخلق تنتهي الى خروج الجنين حيا، وغير تامه الخلق تاره اخرى، فتسقط لغير تمام؛ لنبين لكم تمام قدرتنا بتصريف اطوار الخلق، ونبقي في الارحام ما نشاء، وهو المخلق الى وقت ولادته، وتكتمل الاطوار بولاده الاجنه اطفالا صغارا تكبر حتى تبلغ الاشد، وهو وقت الشباب والقوه واكتمال العقل، وبعض الاطفال قد يموت قبل ذلك، وبعضهم يكبر حتى يبلغ سن الهرم وضعف العقل؛ فلا يعلم هذا المعمر شيئا مما كان يعلمه قبل ذلك. وترى الارض يابسه ميته لا نبات فيها، فاذا انزلنا عليها الماء تحركت بالنبات تتفتح عنه، وارتفعت وزادت لارتوائها، وانبتت من كل نوع من انواع النبات الحسن الذي يسر الناظرين."},{"id":"2601","s":22,"a":6,"at":"ذلك بان الله هو الحق وانه يحى الموتى وانه على كل شيء قدير","dt":"[6] ذلك المذكور مما تقدم من ايات قدره الله تعالى، فيه دلاله قاطعه على ان الله سبحانه وتعالى هو الرب المعبود بحق، الذي لا تنبغي العباده الا له، وهو يحيي الموتى، وهو قادر على كل شيء."},{"id":"2602","s":22,"a":7,"at":"وان الساعه اتيه لا ريب فيها وان الله يبعث من في القبور","dt":"[7] وان ساعه البعث اتيه لا شك في ذلك، وان الله يبعث الموتى من قبورهم لحسابهم وجزائهم."},{"id":"2603","s":22,"a":8,"at":"ومن الناس من يجادل في الله بغير علم ولا هدى ولا كتاب منير","dt":"[8] ومن الكفار من يجادل بالباطل في الله وتوحيده واختياره رسوله -صلى الله عليه وسلم- وانزاله القران، وذلك الجدال بغير علم، ولا بيان، ولا كتاب من الله فيه برهان وحجه واضحه،"},{"id":"2604","s":22,"a":9,"at":"ثاني عطفه ليضل عن سبيل الله له في الدنيا خزي ونذيقه يوم القيامه عذاب الحريق","dt":"[9] لاويا عنقه في تكبر، معرضا عن الحق؛ ليصد غيره عن الدخول في دين الله، فسوف يلقى خزيا في الدنيا باندحاره وافتضاح امره، ونحرقه يوم القيامه بالنار."},{"id":"2605","s":22,"a":10,"at":"ذلك بما قدمت يداك وان الله ليس بظلام للعبيد","dt":"[10] ويقال له: ذلك العذاب بسبب ما فعلت من المعاصي واكتسبت من الاثام، والله لا يعذب احدا بغير ذنب."},{"id":"2606","s":22,"a":11,"at":"ومن الناس من يعبد الله على حرف فان اصابه خير اطمان به وان اصابته فتنه انقلب على وجهه خسر الدنيا والاخره ذلك هو الخسران المبين","dt":"[11] ومن الناس من يدخل في الاسلام على ضعف وشك، فيعبد الله على تردد، كالذي يقف على طرف جبل او حائط لا يتماسك في وقفته، ويربط ايمانه بدنياه، فان عاش في صحه وسعه استمر على عبادته، وان حصل له ابتلاء بمكروه وشده عزا شؤم ذلك الى دينه، فرجع عنه كمن ينقلب على وجهه بعد استقامه، فهو بذلك قد خسر الدنيا؛ اذ لا يغير كفره ما قدر له في دنياه، وخسر الاخره بدخوله النار، وذلك خسران بين واضح. ."},{"id":"2607","s":22,"a":12,"at":"يدعو من دون الله ما لا يضره وما لا ينفعه ذلك هو الضلال البعيد","dt":"[12] يعبد ذلك الخاسر من دون الله ما لا يضره ان تركه، ولا ينفعه اذا عبده، ذلك هو الضلال البعيد عن الحق.."},{"id":"2608","s":22,"a":13,"at":"يدعو لمن ضره اقرب من نفعه لبئس المولى ولبئس العشير","dt":"[13] يدعو من ضرره المحقق اقرب من نفعه، قبح ذلك المعبود نصيرا، وقبح عشيرا."},{"id":"2609","s":22,"a":14,"at":"ان الله يدخل الذين امنوا وعملوا الصالحات جنات تجري من تحتها الانهار ان الله يفعل ما يريد","dt":"[14] ان الله يدخل الذين امنوا بالله ورسوله، وثبتوا على ذلك، وعملوا الصالحات، جنات تجري من تحت قصورها واشجارها الانهار، ان الله يفعل ما يريد من ثواب اهل طاعته تفضلا، وعقاب اهل معصيته عدلا."},{"id":"2610","s":22,"a":15,"at":"من كان يظن ان لن ينصره الله في الدنيا والاخره فليمدد بسبب الى السماء ثم ليقطع فلينظر هل يذهبن كيده ما يغيظ","dt":"[15] من كان يعتقد ان الله تعالى لن يؤيد رسوله محمدا بالنصر في الدنيا باظهار دينه، وفي الاخره باعلاء درجته، وعذاب من كذبه، فليمدد حبلا الى سقف بيته وليخنق به نفسه، ثم ليقطع ذلك الحبل، ثم لينظر: هل يذهبن ذلك ما يجد في نفسه من الغيظ؟ فان الله تعالى ناصر نبيه محمدا -صلى الله عليه وسلم- لا محاله."},{"id":"2611","s":22,"a":16,"at":"وكذلك انزلناه ايات بينات وان الله يهدي من يريد","dt":"[16] وكما اقام الله الحجه من دلائل قدرته على الكافرين بالبعث انزل القران، اياته واضحه في لفظها ومعناها، يهدي بها الله من اراد هدايته؛ لانه لا هادي سواه."},{"id":"2612","s":22,"a":17,"at":"ان الذين امنوا والذين هادوا والصابئين والنصارى والمجوس والذين اشركوا ان الله يفصل بينهم يوم القيامه ان الله على كل شيء شهيد","dt":"[17] ان الذين امنوا بالله ورسوله محمد -صلى الله عليه وسلم-، واليهود، والصابئين (وهم قوم باقون على فطرتهم ولا دين مقرر لهم يتبعونه)، والنصارى، والمجوس (وهم عبده النار)، والذين اشركوا (وهم عبده الاوثان)، ان الله يفصل بينهم جميعا يوم القيامه فيدخل المؤمنين الجنه، ويدخل الكافرين النار، ان الله على كل شيء شهيد، شهد اعمال العباد كلها، واحصاها وحفظها، وسيجازي كلا بما يستحق؛ جزاء وفاقا للاعمال التي عملوها."},{"id":"2613","s":22,"a":18,"at":"الم تر ان الله يسجد له من في السموات ومن في الارض والشمس والقمر والنجوم والجبال والشجر والدواب وكثير من الناس وكثير حق عليه العذاب ومن يهن الله فما له من مكرم ان الله يفعل ما يشاء","dt":"[18] الم تعلم -ايها الرسول- ان الله سبحانه يسجد له خاضعا منقادا من في السموات من الملائكه، ومن في الارض من المخلوقات، والشمس والقمر والنجوم والجبال والشجر والدواب؟ ولله يسجد طاعه واختيارا كثير من الناس، وهم المؤمنون، وكثير من الناس حق عليه العذاب فهو مهين، واي انسان يهنه الله فليس له احد يكرمه. ان الله يفعل في خلقه ما يشاء وفق حكمته."},{"id":"2614","s":22,"a":19,"at":"هذان خصمان اختصموا في ربهم فالذين كفروا قطعت لهم ثياب من نار يصب من فوق رءوسهم الحميم","dt":"[19] هذان فريقان اختلفوا في ربهم: اهل الايمان واهل الكفر، كل يدعي انه محق، فالذين كفروا يحيط بهم العذاب في هيئه ثياب جعلت لهم من نار يلبسونها، فتشوي اجسادهم، ويصب على رؤوسهم الماء المتناهي في حره،"},{"id":"2615","s":22,"a":20,"at":"يصهر به ما في بطونهم والجلود","dt":"[20] وينزل الى اجوافهم فيذيب ما فيها، حتى ينفذ الى جلودهم فيشويها فتسقط،"},{"id":"2616","s":22,"a":21,"at":"ولهم مقامع من حديد","dt":"[21] وتضربهم الملائكه على رؤوسهم بمطارق من حديد."},{"id":"2617","s":22,"a":22,"at":"كلما ارادوا ان يخرجوا منها من غم اعيدوا فيها وذوقوا عذاب الحريق","dt":"[22] كلما حاولوا الخروج من النار -لشده غمهم وكربهم- اعيدوا للعذاب فيها، وقيل لهم: ذوقوا عذاب النار المحرق."},{"id":"2618","s":22,"a":23,"at":"ان الله يدخل الذين امنوا وعملوا الصالحات جنات تجري من تحتها الانهار يحلون فيها من اساور من ذهب ولؤلؤا ولباسهم فيها حرير","dt":"[23] ان الله تعالى يدخل اهل الايمان والعمل الصالح جنات نعيمها دائم، تجري من تحت قصورها واشجارها الانهار، يزينون فيها باساور الذهب وباللؤلؤ، ولباسهم المعتاد في الجنه الحرير رجالا ونساء."},{"id":"2619","s":22,"a":24,"at":"وهدوا الى الطيب من القول وهدوا الى صراط الحميد","dt":"[24] لقد هداهم الله في الدنيا الى طيب القول: من كلمه التوحيد وحمد الله والثناء عليه، وفي الاخره الى حمده على حسن العاقبه، كما هداهم من قبل الى طريق الاسلام المحمود الموصل الى الجنه."},{"id":"2620","s":22,"a":25,"at":"ان الذين كفروا ويصدون عن سبيل الله والمسجد الحرام الذي جعلناه للناس سواء العاكف فيه والباد ومن يرد فيه بالحاد بظلم نذقه من عذاب اليم","dt":"[25] ان الذين كفروا بالله وكذبوا بما جاءهم به محمد -صلى الله عليه وسلم-، ويمنعون غيرهم من الدخول في دين الله، ويصدون رسول الله -صلى الله عليه وسلم- والمؤمنين في عام «الحديبيه» عن المسجد الحرام، الذي جعلناه لجميع المؤمنين، سواء المقيم فيه والقادم اليه، لهم عذاب اليم موجع، ومن يرد في المسجد الحرام الميل عن الحق ظلما فيعص الله فيه، نذقه من عذاب اليم موجع."},{"id":"2621","s":22,"a":26,"at":"واذ بوانا لابراهيم مكان البيت ان لا تشرك بي شيئا وطهر بيتي للطائفين والقائمين والركع السجود","dt":"[26] واذكر -ايها النبي- اذ بينا لابراهيم -عليه السلام- مكان البيت، وهياناه له وقد كان غير معروف، وامرناه ببنائه على تقوى من الله وتوحيده، وتطهيره من الكفر والبدع والنجاسات؛ ليكون رحابا للطائفين به، والقائمين المصلين عنده."},{"id":"2622","s":22,"a":27,"at":"واذن في الناس بالحج ياتوك رجالا وعلى كل ضامر ياتين من كل فج عميق","dt":"[27] واعلم -يا ابراهيم- الناس بوجوب الحج عليهم ياتوك على مختلف احوالهم مشاه وركبانا على كل ضامر من الابل، وهو: (الخفيف اللحم من السير والاعمال لا من الهزال)، ياتين من كل طريق بعيد؛"},{"id":"2623","s":22,"a":28,"at":"ليشهدوا منافع لهم ويذكروا اسم الله في ايام معلومات على ما رزقهم من بهيمه الانعام فكلوا منها واطعموا البائس الفقير","dt":"[28] ليحضروا منافع لهم من: مغفره ذنوبهم، وثواب اداء نسكهم وطاعتهم، وتكسبهم في تجاراتهم، وغير ذلك؛ وليذكروا اسم الله على ذبح ما يتقربون به من الابل والبقر والغنم في ايام معينه هي: عاشر ذي الحجه وثلاثه ايام بعده؛ شكرا لله على نعمه، وهم مامورون ان ياكلوا من هذه الذبائح استحبابا، ويطعموا منها الفقير الذي اشتد فقره."},{"id":"2624","s":22,"a":29,"at":"ثم ليقضوا تفثهم وليوفوا نذورهم وليطوفوا بالبيت العتيق","dt":"[29] ثم ليكمل الحجاج ما بقي عليهم من النسك، باحلالهم وخروجهم من احرامهم، وذلك بازاله ما تراكم من وسخ في ابدانهم، وقص اظفارهم، وحلق شعرهم، وليوفوا بما اوجبوه على انفسهم من الحج والعمره والهدايا، وليطوفوا بالبيت العتيق القديم، الذي اعتقه الله من تسلط الجبارين عليه، وهو الكعبه."},{"id":"2625","s":22,"a":30,"at":"ذلك ومن يعظم حرمات الله فهو خير له عند ربه واحلت لكم الانعام الا ما يتلى عليكم فاجتنبوا الرجس من الاوثان واجتنبوا قول الزور","dt":"[30] ذلك الذي امر الله به من قضاء التفث والوفاء بالنذور والطواف بالبيت، هو ما اوجبه الله عليكم فعظموه، ومن يعظم حرمات الله، ومنها مناسكه بادائها كامله خالصه لله، فهو خير له في الدنيا والاخره. واحل الله لكم اكل الانعام الا ما حرمه فيما يتلى عليكم في القران من الميته وغيرها فاجتنبوه. وفي هذا ابطال ما كانت العرب تحرمه من بعض الانعام. وابتعدوا عن القذاره التي هي الاوثان، وعن الكذب الذي هو الافتراء على الله."},{"id":"2626","s":22,"a":31,"at":"حنفاء لله غير مشركين به ومن يشرك بالله فكانما خر من السماء فتخطفه الطير او تهوي به الريح في مكان سحيق","dt":"[31] مستقيمين لله على اخلاص العمل له، مقبلين عليه بعبادته وحده وافراده بالطاعه، معرضين عما سواه بنبذ الشرك، فانه من يشرك بالله شيئا، فمثله -في بعده عن الهدى، وفي هلاكه وسقوطه من رفيع الايمان الى حضيض الكفر، وتخطف الشياطين له من كل جانب- كمثل من سقط من السماء: فاما ان تخطفه الطير فتقطع اعضاءه، واما ان تاخذه عاصفه شديده من الريح، فتقذفه في مكان بعيد اشد البعد."},{"id":"2627","s":22,"a":32,"at":"ذلك ومن يعظم شعائر الله فانها من تقوى القلوب","dt":"[32] ذلك ما امر الله به من توحيده واخلاص العباده له. ومن يمتثل امر الله ويعظم معالم الدين، ومنها اعمال الحج واماكنه، والذبائح التي تذبح فيه، وذلك باستحسانها واستسمانها، فهذا التعظيم من افعال اصحاب القلوب المتصفه بتقوى الله وخشيته."},{"id":"2628","s":22,"a":33,"at":"لكم فيها منافع الى اجل مسمى ثم محلها الى البيت العتيق","dt":"[33] لكم في هذه الهدايا منافع تنتفعون بها من الصوف واللبن والركوب، وغير ذلك مما لا يضرها الى وقت ذبحها عند البيت العتيق، وهو الحرم كله."},{"id":"2629","s":22,"a":34,"at":"ولكل امه جعلنا منسكا ليذكروا اسم الله على ما رزقهم من بهيمه الانعام فالهكم اله واحد فله اسلموا وبشر المخبتين","dt":"[34] ولكل جماعه مؤمنه سلفت، جعلنا لها مناسك من الذبح واراقه الدماء؛ وذلك ليذكروا اسم الله تعالى عند ذبح ما رزقهم من هذه الانعام ويشكروا له. فالهكم -ايها الناس- اله واحد هو الله فانقادوا لامره وامر رسوله. وبشر –ايها النبي- المتواضعين الخاضعين لربهم بخيري الدنيا والاخره."},{"id":"2630","s":22,"a":35,"at":"الذين اذا ذكر الله وجلت قلوبهم والصابرين على ما اصابهم والمقيمي الصلاه ومما رزقناهم ينفقون","dt":"[35] هؤلاء المتواضعون الخاشعون من صفاتهم انهم اذا ذكر الله وحده خافوا عقابه، وحذروا مخالفته، واذا اصابهم باس وشده صبروا على ذلك مؤملين الثواب من الله عز وجل، وادوا الصلاه تامه، وهم مع ذلك ينفقون مما رزقهم الله في الواجب عليهم من زكاه ونفقه عيال، وعلى من وجبت عليهم نفقته، وفي سبيل الله، والنفقات المستحبه."},{"id":"2631","s":22,"a":36,"at":"والبدن جعلناها لكم من شعائر الله لكم فيها خير فاذكروا اسم الله عليها صواف فاذا وجبت جنوبها فكلوا منها واطعموا القانع والمعتر كذلك سخرناها لكم لعلكم تشكرون","dt":"[36] وجعلنا لكم نحر ما سمن من الابل والبقر من شعائر الدين واعلامه؛ لتتقربوا بها الى الله، لكم فيها -ايها المتقربون- خير في منافعها من الاكل والصدقه والثواب والاجر، فقولوا عند ذبحها: بسم الله. وتنحر الابل واقفه قد صفت ثلاث من قوائمها وقيدت الرابعه، فاذا سقطت على الارض جنوبها فقد حل اكلها، فلياكل منها مقربوها تعبدا ويطعموا منها القانع -وهو الفقير الذي لم يسال تعففا- والمعتر الذي يسال لحاجته، هكذا سخر الله البدن لكم، لعلكم تشكرون الله على تسخيرها لكم."},{"id":"2632","s":22,"a":37,"at":"لن ينال الله لحومها ولا دماؤها ولكن يناله التقوى منكم كذلك سخرها لكم لتكبروا الله على ما هداكم وبشر المحسنين","dt":"[37] لن ينال الله من لحوم هذه الذبائح ولا من دمائها شيء، ولكن يناله الاخلاص فيها، وان يكون القصد بها وجه الله وحده، كذلك ذللها لكم -ايها المتقربون-؛ لتعظموا الله، وتشكروا له على ما هداكم من الحق، فانه اهل لذلك. وبشر -ايها النبي- المحسنين بعباده الله وحده، والمحسنين الى خلقه بكل خير وفلاح."},{"id":"2633","s":22,"a":38,"at":"ان الله يدافع عن الذين امنوا ان الله لا يحب كل خوان كفور","dt":"[38] ان الله تعالى يدفع عن المؤمنين عدوان الكفار، وكيد الاشرار؛ لانه عز وجل لا يحب كل خوان لامانه ربه، جحود لنعمته."},{"id":"2634","s":22,"a":39,"at":"اذن للذين يقاتلون بانهم ظلموا وان الله على نصرهم لقدير","dt":"[39] كان المسلمون في اول امرهم ممنوعين من قتال الكفار، مامورين بالصبر على اذاهم، فلما بلغ اذى المشركين مداه، وخرج النبي -صلى الله عليه وسلم- من «مكه» مهاجرا الى «المدينه»، واصبح للاسلام قوه اذن الله للمسلمين في القتال؛ بسبب ما وقع عليهم من الظلم والعدوان، وان الله تعالى قادر على نصرهم واذلال عدوهم."},{"id":"2635","s":22,"a":40,"at":"الذين اخرجوا من ديارهم بغير حق الا ان يقولوا ربنا الله ولولا دفع الله الناس بعضهم ببعض لهدمت صوامع وبيع وصلوات ومساجد يذكر فيها اسم الله كثيرا ولينصرن الله من ينصره ان الله لقوي عزيز","dt":"[40] الذين الجئوا الى الخروج من ديارهم، لا لشيء فعلوه الا لانهم اسلموا وقالوا: ربنا الله وحده. ولولا ما شرعه الله من دفع الظلم الذي ينتفع به جميع اهل الاديان المنزله، ورد الباطل بالقتال الماذون فيه لهزم الحق في كل امه ولخربت الارض، وهدمت فيها اماكن العباده من صوامع الرهبان، وكنائس النصارى، ومعابد اليهود، ومساجد المسلمين التي يصلون فيها، ويذكرون اسم الله فيها كثيرا. ومن اجتهد في نصره دين الله، فان الله ناصره على عدوه. ان الله لقوي لا يغالب، عزيز لا يرام، قد قهر الخلائق واخذ بنواصيهم."},{"id":"2636","s":22,"a":41,"at":"الذين ان مكناهم في الارض اقاموا الصلاه واتوا الزكاه وامروا بالمعروف ونهوا عن المنكر ولله عاقبه الامور","dt":"[41] الذين وعدناهم بنصرنا هم الذين ان مكناهم في الارض، واستخلفناهم فيها باظهارهم على عدوهم، اقاموا الصلاه بادائها في اوقاتها بحدودها، واخرجوا زكاه اموالهم الى اهلها، وامروا بكل ما امر الله به من حقوقه وحقوق عباده، ونهوا عن كل ما نهى الله عنه ورسوله. ولله وحده مصير الامور كلها، والعاقبه للتقوى."},{"id":"2637","s":22,"a":42,"at":"وان يكذبوك فقد كذبت قبلهم قوم نوح وعاد وثمود","dt":"[42] وان يكذبك قومك -ايها الرسول- فقد سبقهم في تكذيب رسلهم قوم نوح، وعاد، وثمود،"},{"id":"2638","s":22,"a":43,"at":"وقوم ابراهيم وقوم لوط","dt":"[43] وقوم ابراهيم، وقوم لوط،"},{"id":"2639","s":22,"a":44,"at":"واصحاب مدين وكذب موسى فامليت للكافرين ثم اخذتهم فكيف كان نكير","dt":"[44] واصحاب «مدين» الذين كذبوا شعيبا، وكذب فرعون وقومه موسى، فلم اعاجل هذه الامم بالعقوبه، بل امهلتها، ثم اخذت كلا منهم بالعذاب، فكيف كان انكاري عليهم كفرهم وتكذيبهم، وكيف كان تبديل ما كان بهم من نعمه بالعذاب والهلاك؟"},{"id":"2640","s":22,"a":45,"at":"فكاين من قريه اهلكناها وهي ظالمه فهي خاويه على عروشها وبئر معطله وقصر مشيد","dt":"[45] فكثيرا من القرى الظالمه بكفرها اهلكنا اهلها، فديارهم مهدمه خلت من سكانها، وابارها لا يستقى منها، وقصورها العاليه المزخرفه لم تدفع عن اهلها سوء العذاب."},{"id":"2641","s":22,"a":46,"at":"افلم يسيروا في الارض فتكون لهم قلوب يعقلون بها او اذان يسمعون بها فانها لا تعمى الابصار ولكن تعمى القلوب التي في الصدور","dt":"[46] افلم يسر المكذبون من قريش في الارض ليشاهدوا اثار المهلكين، فيتفكروا بعقولهم، فيعتبروا، ويسمعوا اخبارهم سماع تدبر فيتعظوا؟ فان العمى ليس عمى البصر، وانما العمى المهلك هو عمى البصيره عن ادراك الحق والاعتبار."},{"id":"2642","s":22,"a":47,"at":"ويستعجلونك بالعذاب ولن يخلف الله وعده وان يوما عند ربك كالف سنه مما تعدون","dt":"[47] ويستعجلك -ايها الرسول- كفار قريش -لشده جهلهم- بالعذاب الذي انذرتهم به لما اصروا على الكفر، ولن يخلف الله ما وعدهم به من العذاب فلا بد من وقوعه، وقد عجل لهم في الدنيا ذلك في يوم «بدر». وان يوما من الايام عند الله -وهو يوم القيامه- كالف سنه مما تعدون من سني الدنيا."},{"id":"2643","s":22,"a":48,"at":"وكاين من قريه امليت لها وهي ظالمه ثم اخذتها والي المصير","dt":"[48] وكثير من القرى كانت ظالمه باصرار اهلها على الكفر، فامهلتهم ولم اعاجلهم بالعقوبه فاغتروا، ثم اخذتهم بعذابي في الدنيا، والي مرجعهم بعد هلاكهم، فاعذبهم بما يستحقون."},{"id":"2644","s":22,"a":49,"at":"قل ياايها الناس انما انا لكم نذير مبين","dt":"[49] قل -ايها الرسول-: يا ايها الناس ما انا الا منذر لكم مبلغ عن الله رسالته.."},{"id":"2645","s":22,"a":50,"at":"فالذين امنوا وعملوا الصالحات لهم مغفره ورزق كريم","dt":"[50] فالذين امنوا بالله ورسوله، واستقر ذلك في قلوبهم، وعملوا الاعمال الصالحه، لهم عند الله عفو عن ذنوبهم ومغفره يستر بها ما صدر عنهم من معصيه، ورزق حسن لا ينقطع وهو الجنه."},{"id":"2646","s":22,"a":51,"at":"والذين سعوا في اياتنا معاجزين اولئك اصحاب الجحيم","dt":"[51] والذين اجتهدوا في الكيد لابطال ايات القران بالتكذيب مشاقين مغالبين، اولئك هم اهل النار الموقده، يدخلونها ويبقون فيها ابدا."},{"id":"2647","s":22,"a":52,"at":"وما ارسلنا من قبلك من رسول ولا نبي الا اذا تمنى القى الشيطان في امنيته فينسخ الله ما يلقي الشيطان ثم يحكم الله اياته والله عليم حكيم","dt":"[52] وما ارسلنا من قبلك -ايها الرسول- من رسول ولا نبي الا اذا قرا ما ارسل به من الايات القى الشيطان في قراءته الوساوس والشبهات؛ ليصد الناس عن اتباع ما يقرؤه ويتلوه، لكن الله يبطل كيد الشيطان، فيزيل وساوسه، ويثبت اياته الواضحات. والله عليم بما كان ويكون، لا تخفى عليه خافيه، حكيم في تقديره وامره."},{"id":"2648","s":22,"a":53,"at":"ليجعل ما يلقي الشيطان فتنه للذين في قلوبهم مرض والقاسيه قلوبهم وان الظالمين لفي شقاق بعيد","dt":"[53] وما كان هذا الفعل من الشيطان الا ليجعله الله اختبارا للذين في قلوبهم شك ونفاق، ولقساه القلوب من المشركين الذين لا يؤثر فيهم زجر. وان الظالمين من هؤلاء واولئك في عداوه شديده لله ورسوله وخلاف للحق بعيد عن الصواب."},{"id":"2649","s":22,"a":54,"at":"وليعلم الذين اوتوا العلم انه الحق من ربك فيؤمنوا به فتخبت له قلوبهم وان الله لهاد الذين امنوا الى صراط مستقيم","dt":"[54] وليعلم اهل العلم الذين يفرقون بعلمهم بين الحق والباطل ان القران الكريم هو الحق النازل من عند الله عليك ايها الرسول، لا شبهه فيه، ولا سبيل للشيطان اليه، فيزداد به ايمانهم، وتخضع له قلوبهم. وان الله لهادي الذين امنوا به وبرسوله الى طريق الحق الواضح، وهو الاسلام ينقذهم به من الضلال."},{"id":"2650","s":22,"a":55,"at":"ولا يزال الذين كفروا في مريه منه حتى تاتيهم الساعه بغته او ياتيهم عذاب يوم عقيم","dt":"[55] ولا يزال الكافرون المكذبون في شك مما جئتهم به من القران الى ان تاتيهم الساعه فجاه، وهم على تكذيبهم، او ياتيهم عذاب يوم لا خير فيه لهم، وهو يوم القيامه."},{"id":"2651","s":22,"a":56,"at":"الملك يومئذ لله يحكم بينهم فالذين امنوا وعملوا الصالحات في جنات النعيم","dt":"[56] الملك والسلطان في هذا اليوم لله وحده، وهو سبحانه يقضي بين المؤمنين والكافرين. فالذين امنوا بالله ورسوله وعملوا الاعمال الصالحه، لهم النعيم الدائم في الجنات."},{"id":"2652","s":22,"a":57,"at":"والذين كفروا وكذبوا باياتنا فاولئك لهم عذاب مهين","dt":"[57] .والذين جحدوا وحدانيه الله وكذبوا رسوله وانكروا ايات القران، فاولئك لهم عذاب يخزيهم ويهينهم في جهنم."},{"id":"2653","s":22,"a":58,"at":"والذين هاجروا في سبيل الله ثم قتلوا او ماتوا ليرزقنهم الله رزقا حسنا وان الله لهو خير الرازقين","dt":"[58] والذين خرجوا من ديارهم طلبا لرضا الله، ونصره لدينه، من قتل منهم وهو يجاهد الكفار، ومن مات منهم من غير قتال، ليرزقنهم الله الجنه ونعيمها الذي لا ينقطع ولا يزول، وان الله سبحانه وتعالى لهو خير الرازقين."},{"id":"2654","s":22,"a":59,"at":"ليدخلنهم مدخلا يرضونه وان الله لعليم حليم","dt":"[59] ليدخلنهم الله المدخل الذي يحبونه وهو الجنه. وان الله لعليم بمن يخرج في سبيله، ومن يخرج طلبا للدنيا، حليم عمن عصاه، فلا يعاجلهم بالعقوبه."},{"id":"2655","s":22,"a":60,"at":"ذلك ومن عاقب بمثل ما عوقب به ثم بغي عليه لينصرنه الله ان الله لعفو غفور","dt":"[60] ذلك الامر الذي قصصنا عليك من ادخال المهاجرين الجنه، ومن اعتدي عليه وظلم فقد اذن له ان يقابل الجاني بمثل فعلته، ولا حرج عليه، فاذا عاد الجاني الى ايذائه وبغى، فان الله ينصر المظلوم المعتدى عليه؛ اذ لا يجوز ان يعتدى عليه بسبب انتصافه لنفسه. ان الله لعفو غفور، يعفو عن المذنبين فلا يعاجلهم بالعقوبه، ويغفر ذنوبهم."},{"id":"2656","s":22,"a":61,"at":"ذلك بان الله يولج الليل في النهار ويولج النهار في الليل وان الله سميع بصير","dt":"[61] ذلك الذي شرع لكم تلك الاحكام العادله هو الحق، وهو القادر على ما يشاء، ومن قدرته انه يدخل ما ينقص من ساعات الليل في ساعات النهار، ويدخل ما انتقص من ساعات النهار في ساعات الليل، وان الله سميع لكل صوت، بصير بكل فعل، لا يخفى عليه شيء."},{"id":"2657","s":22,"a":62,"at":"ذلك بان الله هو الحق وان ما يدعون من دونه هو الباطل وان الله هو العلي الكبير","dt":"[62] ذلك بان الله هو الاله الحق الذي لا تنبغي العباده الا له، وان ما يعبده المشركون من دونه من الاصنام والانداد هو الباطل الذي لا ينفع ولا يضر، وان الله هو العلي على خلقه ذاتا وقدرا وقهرا، المتعالي عن الاشباه والانداد، الكبير في ذاته، واسمائه، وصفاته، فهو اكبر من كل شيء."},{"id":"2658","s":22,"a":63,"at":"الم تر ان الله انزل من السماء ماء فتصبح الارض مخضره ان الله لطيف خبير","dt":"[63] الم تر -ايها الرسول- ان الله انزل من السماء مطرا، فتصبح الارض مخضره بما ينبت فيها من النبات؟ ان الله لطيف بعباده باستخراج النبات من الارض بذلك الماء، خبير بمصالحهم."},{"id":"2659","s":22,"a":64,"at":"له ما في السموات وما في الارض وان الله لهو الغني الحميد","dt":"[64] لله سبحانه وتعالى ما في السموات والارض خلقا وملكا وعبوديه، كل محتاج الى تدبيره وافضاله. وان الله لهو الغني الذي لا يحتاج الى شيء، المحمود في كل حال."},{"id":"2660","s":22,"a":65,"at":"الم تر ان الله سخر لكم ما في الارض والفلك تجري في البحر بامره ويمسك السماء ان تقع على الارض الا باذنه ان الله بالناس لرءوف رحيم","dt":"[65] الم تر ان الله تعالى ذلل لكم ما في الارض من الدواب والبهائم والزروع والثمار والجماد لركوبكم وطعامكم وكل منافعكم، كما ذلل لكم السفن تجري في البحر بقدرته وامره، فتحملكم مع امتعتكم الى حيث تشاؤون من البلاد والاماكن، وهو الذي يمسك السماء فيحفظها؛ حتى لا تقع على الارض فيهلك من عليها الا باذنه سبحانه بذلك؟ ان الله ليرحم الناس رحمه واسعه في عاجلهم واجلهم، ومن رحمته بهم ما سخره لهم من هذه الاشياء وغيرها؛ تفضلا منه عليهم."},{"id":"2661","s":22,"a":66,"at":"وهو الذي احياكم ثم يميتكم ثم يحييكم ان الانسان لكفور","dt":"[66] وهو الله تعالى الذي احياكم بان اوجدكم من العدم، ثم يميتكم عند انقضاء اعماركم، ثم يحييكم بالبعث لمحاسبتكم على اعمالكم. ان الانسان لجحود لما ظهر من الايات الداله على قدره الله ووحدانيته."},{"id":"2662","s":22,"a":67,"at":"لكل امه جعلنا منسكا هم ناسكوه فلا ينازعنك في الامر وادع الى ربك انك لعلى هدى مستقيم","dt":"[67] لكل امه من الامم الماضيه جعلنا شريعه وعباده امرناهم بها، فهم عاملون بها، فلا ينازعنك -ايها الرسول- مشركو قريش في شريعتك، وما امرك الله به في المناسك وانواع العبادات كلها، وادع الى توحيد ربك واخلاص العباده له واتباع امره، انك لعلى دين قويم، لا اعوجاج فيه."},{"id":"2663","s":22,"a":68,"at":"وان جادلوك فقل الله اعلم بما تعملون","dt":"[68] وان اصروا على مجادلتك بالباطل فيما تدعوهم اليه فلا تجادلهم، بل قل لهم: الله اعلم بما تعملونه من الكفر والتكذيب، فهم معاندون مكابرون."},{"id":"2664","s":22,"a":69,"at":"الله يحكم بينكم يوم القيامه فيما كنتم فيه تختلفون","dt":"[69] الله تعالى يحكم بين المسلمين والكافرين يوم القيامه في امر اختلافهم في الدين. وفي هذه الايه ادب حسن في الرد على من جادل تعنتا واستكبارا."},{"id":"2665","s":22,"a":70,"at":"الم تعلم ان الله يعلم ما في السماء والارض ان ذلك في كتاب ان ذلك على الله يسير","dt":"[70] الم تعلم -ايها الرسول- ان الله يعلم ما في السماء والارض علما كاملا قد اثبته في اللوح المحفوظ؟ ان ذلك العلم امر سهل على الله الذي لا يعجزه شيء."},{"id":"2666","s":22,"a":71,"at":"ويعبدون من دون الله ما لم ينزل به سلطانا وما ليس لهم به علم وما للظالمين من نصير","dt":"[71] ويصر كفار قريش على الشرك بالله مع ظهور بطلان ما هم عليه، فهم يعبدون الهه، لم ينزل في كتاب من كتب الله برهان بانها تصلح للعباده، ولا علم لهم فيما اختلقوه، وافتروه على الله، وانما هو امر اتبعوا فيه اباءهم بلا دليل. فاذا جاء وقت الحساب في الاخره فليس للمشركين ناصر ينصرهم، او يدفع عنهم العذاب."},{"id":"2667","s":22,"a":72,"at":"واذا تتلى عليهم اياتنا بينات تعرف في وجوه الذين كفروا المنكر يكادون يسطون بالذين يتلون عليهم اياتنا قل افانبئكم بشر من ذلكم النار وعدها الله الذين كفروا وبئس المصير","dt":"[72] واذا تتلى ايات القران الواضحه على هؤلاء المشركين ترى الكراهه ظاهره على وجوههم، يكادون يبطشون بالمؤمنين الذين يدعونهم الى الله تعالى، ويتلون عليهم اياته. قل لهم -ايها الرسول-: افلا اخبركم بما هو اشد كراهه اليكم من سماع الحق ورؤيه الداعين اليه؟ النار اعدها الله للكافرين في الاخره، وبئس المكان الذي يصيرون اليه."},{"id":"2668","s":22,"a":73,"at":"ياايها الناس ضرب مثل فاستمعوا له ان الذين تدعون من دون الله لن يخلقوا ذبابا ولو اجتمعوا له وان يسلبهم الذباب شيئا لا يستنقذوه منه ضعف الطالب والمطلوب","dt":"[73] يا ايها الناس ضرب مثل فاستمعوا له وتدبروه: ان الاصنام والانداد التي تعبدونها من دون الله لن تقدر مجتمعه على خلق ذبابه واحده، فكيف بخلق ما هو اكبر؟ ولا تقدر ان تستخلص ما يسلبه الذباب منها، فهل بعد ذلك من عجز؟ فهما ضعيفان معا: ضعف الطالب الذي هو المعبود من دون الله ان يستنقذ ما اخذه الذباب منه، وضعف المطلوب الذي هو الذباب، فكيف تتخذ هذه الاصنام والانداد الهه، وهي بهذا الهوان؟"},{"id":"2669","s":22,"a":74,"at":"ما قدروا الله حق قدره ان الله لقوي عزيز","dt":"[74] هؤلاء المشركون لم يعظموا الله حق تعظيمه، اذ جعلوا له شركاء، وهو القوي الذي خلق كل شيء، العزيز الذي لا يغالب."},{"id":"2670","s":22,"a":75,"at":"الله يصطفي من الملائكه رسلا ومن الناس ان الله سميع بصير","dt":"[75] الله سبحانه وتعالى يختار من الملائكه رسلا الى انبيائه، ويختار من الناس رسلا؛ لتبليغ رسالاته الى الخلق، ان الله سميع لاقوال عباده، بصير بجميع الاشياء، وبمن يختاره للرساله من خلقه."},{"id":"2671","s":22,"a":76,"at":"يعلم ما بين ايديهم وما خلفهم والى الله ترجع الامور","dt":"[76] وهو سبحانه يعلم ما بين ايدي ملائكته ورسله من قبل ان يخلقهم، ويعلم ما هو كائن بعد فنائهم. والى الله وحده ترجع الامور."},{"id":"2672","s":22,"a":77,"at":"ياايها الذين امنوا اركعوا واسجدوا واعبدوا ربكم وافعلوا الخير لعلكم تفلحون","dt":"[77] يا ايها الذين امنوا بالله ورسوله محمد -صلى الله عليه وسلم- اركعوا واسجدوا في صلاتكم، واعبدوا ربكم وحده لا شريك له، وافعلوا الخير؛ لتفلحوا،،"},{"id":"2673","s":22,"a":78,"at":"وجاهدوا في الله حق جهاده هو اجتباكم وما جعل عليكم في الدين من حرج مله ابيكم ابراهيم هو سماكم المسلمين من قبل وفي هذا ليكون الرسول شهيدا عليكم وتكونوا شهداء على الناس فاقيموا الصلاه واتوا الزكاه واعتصموا بالله هو مولاكم فنعم المولى ونعم النصير","dt":"[78] وجاهدوا انفسكم، وقوموا قياما تاما بامر الله، وادعوا الخلق الى سبيله، وجاهدوا باموالكم والسنتكم وانفسكم، مخلصين فيه النيه لله عز وجل، مسلمين له قلوبكم وجوارحكم، هو اصطفاكم لحمل هذا الدين، وقد من عليكم بان جعل شريعتكم سمحه، ليس فيها تضييق ولا تشديد في تكاليفها واحكامها، كما كان في بعض الامم قبلكم، هذه المله السمحه هي مله ابيكم ابراهيم، وقد سماكم الله المسلمين من قبل في الكتب المنزله السابقه، وفي هذا القران، وقد اختصكم بهذا الاختيار؛ ليكون خاتم الرسل محمد -صلى الله عليه وسلم- شاهدا عليكم بانه بلغكم رساله ربه، وتكونوا شهداء على الامم ان رسلهم قد بلغتهم بما اخبركم الله به في كتابه، فعليكم ان تعرفوا لهذه النعمه قدرها، فتشكروها، وتحافظوا على معالم دين الله باداء الصلاه باركانها وشروطها، واخراج الزكاه المفروضه، وان تلجؤوا الى الله سبحانه وتعالى، وتتوكلوا عليه، فهو نعم المولى لمن تولاه، ونعم النصير لمن استنصره."},{"id":"2674","s":23,"a":1,"at":"قد افلح المؤمنون","dt":"[1] قد فاز المصدقون بالله وبرسوله العاملون بشرعه."},{"id":"2675","s":23,"a":2,"at":"الذين هم في صلاتهم خاشعون","dt":"[2] الذين من صفاتهم انهم في صلاتهم خاشعون، تفرغ لها قلوبهم، وتسكن جوارحهم."},{"id":"2676","s":23,"a":3,"at":"والذين هم عن اللغو معرضون","dt":"[3] والذين هم تاركون لكل ما لا خير فيه من الاقوال والافعال."},{"id":"2677","s":23,"a":4,"at":"والذين هم للزكاه فاعلون","dt":"[4] والذين هم مطهرون لنفوسهم واموالهم باداء زكاه اموالهم على اختلاف اجناسها."},{"id":"2678","s":23,"a":5,"at":"والذين هم لفروجهم حافظون","dt":"[5] والذين هم لفروجهم حافظون مما حرم الله من الزنى واللواط وكل الفواحش."},{"id":"2679","s":23,"a":6,"at":"الا على ازواجهم او ما ملكت ايمانهم فانهم غير ملومين","dt":"[6] الا على زوجاتهم او ما ملكت ايمانهم من الاماء، فلا لوم عليهم ولا حرج في جماعهن والاستمتاع بهن؛ لان الله تعالى احلهن."},{"id":"2680","s":23,"a":7,"at":"فمن ابتغى وراء ذلك فاولئك هم العادون","dt":"[7] فمن طلب التمتع بغير زوجته او امته فهو من المجاوزين الحلال الى الحرام، وقد عرض نفسه لعقاب الله وسخطه."},{"id":"2681","s":23,"a":8,"at":"والذين هم لاماناتهم وعهدهم راعون","dt":"[8] والذين هم حافظون لكل ما اؤتمنوا عليه، موفون بكل عهودهم."},{"id":"2682","s":23,"a":9,"at":"والذين هم على صلواتهم يحافظون","dt":"[9] والذين هم يداومون على اداء صلاتهم في اوقاتها على هيئتها المشروعه، الوارده عن النبي -صلى الله عليه وسلم-."},{"id":"2683","s":23,"a":10,"at":"اولئك هم الوارثون","dt":"[10] هؤلاء المؤمنون هم الوارثون الجنه."},{"id":"2684","s":23,"a":11,"at":"الذين يرثون الفردوس هم فيها خالدون","dt":"[11] الذين يرثون اعلى منازل الجنه واوسطها، وهي افضلها منزلا، هم فيها خالدون، لا ينقطع نعيمهم ولا يزول."},{"id":"2685","s":23,"a":12,"at":"ولقد خلقنا الانسان من سلاله من طين","dt":"[12] ولقد خلقنا ادم من طين ماخوذ من جميع الارض."},{"id":"2686","s":23,"a":13,"at":"ثم جعلناه نطفه في قرار مكين","dt":"[13] ثم خلقنا بنيه متناسلين من نطفه: هي مني الرجال تخرج من اصلابهم، فتستقر متمكنه في ارحام النساء."},{"id":"2687","s":23,"a":14,"at":"ثم خلقنا النطفه علقه فخلقنا العلقه مضغه فخلقنا المضغه عظاما فكسونا العظام لحما ثم انشاناه خلقا اخر فتبارك الله احسن الخالقين","dt":"[14] ثم خلقنا النطفه علقه اي: دما احمر، فخلقنا العلقه بعد اربعين يوما مضغه اي: قطعه لحم قدر ما يمضغ، فخلقنا المضغه اللينه عظاما، فكسونا العظام لحما، ثم انشاناه خلقا اخر بنفخ الروح فيه، فتبارك الله، الذي احسن كل شيء خلقه."},{"id":"2688","s":23,"a":15,"at":"ثم انكم بعد ذلك لميتون","dt":"[15] ثم انكم ايها البشر بعد اطوار الحياه وانقضاء الاعمار لميتون."},{"id":"2689","s":23,"a":16,"at":"ثم انكم يوم القيامه تبعثون","dt":"[16] ثم انكم بعد الموت وانقضاء الدنيا تحيون يوم القيامه من قبوركم للحساب والجزاء."},{"id":"2690","s":23,"a":17,"at":"ولقد خلقنا فوقكم سبع طرائق وما كنا عن الخلق غافلين","dt":"[17] ولقد خلقنا فوقكم سبع سموات بعضها فوق بعض، وما كنا عن الخلق غافلين، فلا نغفل مخلوقا، ولا ننساه."},{"id":"2691","s":23,"a":18,"at":"وانزلنا من السماء ماء بقدر فاسكناه في الارض وانا على ذهاب به لقادرون","dt":"[18] وانزلنا من السماء ماء بقدر حاجه الخلائق، وجعلنا الارض مستقرا لهذا الماء، وانا على ذهاب بالماء المستقر لقادرون. وفي هذا تهديد ووعيد للظالمين."},{"id":"2692","s":23,"a":19,"at":"فانشانا لكم به جنات من نخيل واعناب لكم فيها فواكه كثيره ومنها تاكلون","dt":"[19] فانشانا بهذا الماء لكم بساتين النخيل والاعناب، لكم فيها فواكه كثيره الانواع والاشكال، ومنها تاكلون."},{"id":"2693","s":23,"a":20,"at":"وشجره تخرج من طور سيناء تنبت بالدهن وصبغ للاكلين","dt":"[20] وانشانا لكم به شجره الزيتون التي تخرج حول جبل طور «سيناء»، يعصر منها الزيت، فيدهن ويؤتدم به."},{"id":"2694","s":23,"a":21,"at":"وان لكم في الانعام لعبره نسقيكم مما في بطونها ولكم فيها منافع كثيره ومنها تاكلون","dt":"[21] وان لكم -ايها الناس- في الابل والبقر والغنم لعبره تعتبرون بخلقها، نسقيكم مما في بطونها من اللبن، ولكم فيها منافع اخرى كثيره كالصوف والجلود، ونحوهما، ومنها تاكلون."},{"id":"2695","s":23,"a":22,"at":"وعليها وعلى الفلك تحملون","dt":"[22] وعلى الابل والسفن في البر والبحر تحملون."},{"id":"2696","s":23,"a":23,"at":"ولقد ارسلنا نوحا الى قومه فقال ياقوم اعبدوا الله ما لكم من اله غيره افلا تتقون","dt":"[23] ولقد ارسلنا نوحا الى قومه، بدعوه التوحيد فقال لهم: اعبدوا الله وحده، ليس لكم من اله يستحق العباده غيره جل وعلا، فاخلصوا له العباده، افلا تخشون عذابه؟"},{"id":"2697","s":23,"a":24,"at":"فقال الملا الذين كفروا من قومه ما هذا الا بشر مثلكم يريد ان يتفضل عليكم ولو شاء الله لانزل ملائكه ما سمعنا بهذا في ابائنا الاولين","dt":"[24] فكذبه اشراف قومه، وقالوا لعامتهم: انه انسان مثلكم لا يتميز عنكم بشيء، ولا يريد بقوله الا رئاسه وفضلا عليكم، ولو شاء الله ان يرسل الينا رسولا لارسله من الملائكه، ما سمعنا بمثل هذا فيمن سبقنا من اباء واجداد."},{"id":"2698","s":23,"a":25,"at":"ان هو الا رجل به جنه فتربصوا به حتى حين","dt":"[25] وما نوح الا رجل به مس من الجنون، فانتظروا حتى يفيق، فيترك دعوته، او يموت، فتستريحوا منه."},{"id":"2699","s":23,"a":26,"at":"قال رب انصرني بما كذبون","dt":"[26] قال نوح: رب انصرني على قومي؛ بسبب تكذيبهم اياي فيما بلغتهم من رسالتك."},{"id":"2700","s":23,"a":27,"at":"فاوحينا اليه ان اصنع الفلك باعيننا ووحينا فاذا جاء امرنا وفار التنور فاسلك فيها من كل زوجين اثنين واهلك الا من سبق عليه القول منهم ولا تخاطبني في الذين ظلموا انهم مغرقون","dt":"[27] فاوحينا اليه ان اصنع السفينه بمراى منا وبامرنا لك ومعونتنا، وانت في حفظنا وكلاءتنا، فاذا جاء امرنا بعذاب قومك بالغرق، وبدا الطوفان، فنبع الماء بقوه من التنور -وهو المكان الذي يخبز فيه- علامه على مجيء العذاب، فادخل في السفينه من كل الاحياء ذكرا وانثى؛ ليبقى النسل، وادخل اهلك الا من استحق العذاب لكفره كزوجتك وابنك، ولا تسالني نجاه قومك الظالمين، فانهم مغرقون لا محاله. وفي هذه الايه اثبات صفه العين لله سبحانه بما يليق به تعالى دون تشبيه ولا تكييف."},{"id":"2701","s":23,"a":28,"at":"فاذا استويت انت ومن معك على الفلك فقل الحمد لله الذي نجانا من القوم الظالمين","dt":"[28] فاذا علوت السفينه مستقرا عليها انت ومن معك امنين من الغرق، فقل: الحمد لله الذي نجانا من القوم الكافرين."},{"id":"2702","s":23,"a":29,"at":"وقل رب انزلني منزلا مباركا وانت خير المنزلين","dt":"[29] وقل: رب يسر لي النزول المبارك الامن، وانت خير المنزلين. وفي هذا تعليم من الله عز وجل لعباده اذا نزلوا ان يقولوا هذا الدعاء."},{"id":"2703","s":23,"a":30,"at":"ان في ذلك لايات وان كنا لمبتلين","dt":"[30] ان في انجاء المؤمنين واهلاك الكافرين لدلالات واضحات على صدق رسل الله فيما جاؤوا به من الله، وان كنا لمختبرين الامم بارسال الرسل اليهم قبل وقوع العقوبه بهم."},{"id":"2704","s":23,"a":31,"at":"ثم انشانا من بعدهم قرنا اخرين","dt":"[31] ثم انشانا من بعد قوم نوح جيلا اخر هم قوم عاد."},{"id":"2705","s":23,"a":32,"at":"فارسلنا فيهم رسولا منهم ان اعبدوا الله ما لكم من اله غيره افلا تتقون","dt":"[32] فارسلنا فيهم رسولا منهم هو هود عليه السلام، فقال لهم: اعبدوا الله وحده ليس لكم معبود بحق غيره، افلا تخافون عقابه اذا عبدتم غيره؟"},{"id":"2706","s":23,"a":33,"at":"وقال الملا من قومه الذين كفروا وكذبوا بلقاء الاخره واترفناهم في الحياه الدنيا ما هذا الا بشر مثلكم ياكل مما تاكلون منه ويشرب مما تشربون","dt":"[33] وقال الاشراف والوجهاء من قومه الذين كفروا بالله، وانكروا الحياه الاخره، واطغاهم ما انعم به عليهم في الدنيا من ترف العيش: ما هذا الذي يدعوكم الى توحيد الله تعالى الا بشر مثلكم، ياكل من جنس طعامكم، ويشرب من جنس شرابكم."},{"id":"2707","s":23,"a":34,"at":"ولئن اطعتم بشرا مثلكم انكم اذا لخاسرون","dt":"[34] ولئن اتبعتم فردا مثلكم انكم اذا لخاسرون بترككم الهتكم واتباعكم اياه."},{"id":"2708","s":23,"a":35,"at":"ايعدكم انكم اذا متم وكنتم ترابا وعظاما انكم مخرجون","dt":"[35] كيف تصدقون ما يعدكم به من انكم اذا متم، وصرتم ترابا وعظاما مفتته، تخرجون من قبوركم احياء؟"},{"id":"2709","s":23,"a":36,"at":"هيهات هيهات لما توعدون","dt":"[36] بعيد حقا ما توعدون به ايها القوم من انكم بعد موتكم تخرجون احياء من قبوركم."},{"id":"2710","s":23,"a":37,"at":"ان هي الا حياتنا الدنيا نموت ونحيا وما نحن بمبعوثين","dt":"[37] ما حياتنا الا في هذه الدنيا، يموت الاباء منا ويحيا الابناء، وما نحن بمخرجين احياء مره اخرى."},{"id":"2711","s":23,"a":38,"at":"ان هو الا رجل افترى على الله كذبا وما نحن له بمؤمنين","dt":"[38] وما هذا الداعي لكم الى الايمان الا رجل اختلق على الله كذبا، ولسنا بمصدقين ما قاله لنا."},{"id":"2712","s":23,"a":39,"at":"قال رب انصرني بما كذبون","dt":"[39] فدعا رسولهم ربه قائلا: رب انصرني عليهم؛ بسبب تكذيبهم لي."},{"id":"2713","s":23,"a":40,"at":"قال عما قليل ليصبحن نادمين","dt":"[40] وقال الله مجيبا لدعوته: عما قليل ليصبحن نادمين، اي: بعد زمن قريب سيصير هؤلاء المكذبون نادمين."},{"id":"2714","s":23,"a":41,"at":"فاخذتهم الصيحه بالحق فجعلناهم غثاء فبعدا للقوم الظالمين","dt":"[41] ولم يلبثوا ان جاءتهم صيحه شديده مع ريح، اهلكهم الله بها، فماتوا جميعا، واصبحوا كغثاء السيل الذي يطفو على الماء، فهلاكا لهؤلاء الظالمين وبعدا لهم من رحمه الله. فليحذر السامعون ان يكذبوا رسولهم، فيحل بهم ما حل بسابقيهم."},{"id":"2715","s":23,"a":42,"at":"ثم انشانا من بعدهم قرونا اخرين","dt":"[42] ثم انشانا من بعد هؤلاء المكذبين امما وخلائق اخرين كاقوام: لوط وشعيب وايوب ويونس صلوات الله وسلامه عليهم اجمعين."},{"id":"2716","s":23,"a":43,"at":"ما تسبق من امه اجلها وما يستاخرون","dt":"[43] ما تتقدم اي امه من هذه الامم المكذبه الوقت المحدد لهلاكها، ولا تتاخر عنه."},{"id":"2717","s":23,"a":44,"at":"ثم ارسلنا رسلنا تترى كل ما جاء امه رسولها كذبوه فاتبعنا بعضهم بعضا وجعلناهم احاديث فبعدا لقوم لا يؤمنون","dt":"[44] ثم ارسلنا رسلنا الى تلك الامم يتبع بعضهم بعضا، كلما دعا رسول امته كذبوه، فاتبعنا بعضهم بعضا بالهلاك والدمار، ولم يبق الا اخبار هلاكهم، وجعلناها احاديث لمن بعدهم، يتخذونها عبره، فهلاكا وسحقا لقوم لا يصدقون الرسل ولا يطيعونهم."},{"id":"2718","s":23,"a":45,"at":"ثم ارسلنا موسى واخاه هارون باياتنا وسلطان مبين","dt":"[45] ثم ارسلنا موسى واخاه هارون باياتنا التسع وهي: العصا واليد والجراد والقمل والضفادع والدم والطوفان والسنون ونقص من الثمرات، حجه بينه تقهر القلوب فتنقاد لها قلوب المؤمنين، وتقوم الحجه على المعاندين،"},{"id":"2719","s":23,"a":46,"at":"الى فرعون وملئه فاستكبروا وكانوا قوما عالين","dt":"[46] ارسلناهما الى فرعون حاكم «مصر» واشراف قومه، فاستكبروا عن الايمان بموسى واخيه، وكانوا قوما متطاولين على الناس قاهرين لهم بالظلم."},{"id":"2720","s":23,"a":47,"at":"فقالوا انؤمن لبشرين مثلنا وقومهما لنا عابدون","dt":"[47] فقالوا: انصدق فردين مثلنا، وقومهما من بني اسرائيل تحت امرتنا مطيعون متذللون لنا؟"},{"id":"2721","s":23,"a":48,"at":"فكذبوهما فكانوا من المهلكين","dt":"[48] فكذبوهما فيما جاءا به، فكانوا من المهلكين بالغرق في البحر."},{"id":"2722","s":23,"a":49,"at":"ولقد اتينا موسى الكتاب لعلهم يهتدون","dt":"[49] ولقد اتينا موسى التوراه؛ ليهتدي بها قومه الى الحق."},{"id":"2723","s":23,"a":50,"at":"وجعلنا ابن مريم وامه ايه واويناهما الى ربوه ذات قرار ومعين","dt":"[50] وجعلنا عيسى بن مريم وامه علامه داله على قدرتنا؛ اذ خلقناه من غير اب، وجعلنا لهما ماوى في مكان مرتفع من الارض، مستو للاستقرار عليه، فيه خصوبه وماء جار ظاهر للعيون."},{"id":"2724","s":23,"a":51,"at":"ياايها الرسل كلوا من الطيبات واعملوا صالحا اني بما تعملون عليم","dt":"[51] يا ايها الرسل كلوا من طيب الرزق الحلال، واعملوا الاعمال الصالحه، اني بما تعملون عليم، لا يخفى علي شيء من اعمالكم. والخطاب في الايه عام للرسل -عليهم السلام- واتباعهم، وفي الايه دليل على ان اكل الحلال عون على العمل الصالح، وان عاقبه الحرام وخيمه، ومنها رد الدعاء."},{"id":"2725","s":23,"a":52,"at":"وان هذه امتكم امه واحده وانا ربكم فاتقون","dt":"[52] وان دينكم -يا معشر الانبياء- دين واحد وهو الاسلام، وانا ربكم فاتقوني بامتثال اوامري واجتناب زواجري."},{"id":"2726","s":23,"a":53,"at":"فتقطعوا امرهم بينهم زبرا كل حزب بما لديهم فرحون","dt":"[53] فتفرق الاتباع في الدين الى احزاب وشيع، جعلوا دينهم اديانا بعدما امروا بالاجتماع، كل حزب معجب برايه زاعم انه على الحق وغيره على الباطل. وفي هذا تحذير من التحزب والتفرق في الدين."},{"id":"2727","s":23,"a":54,"at":"فذرهم في غمرتهم حتى حين","dt":"[54] فاتركهم -ايها الرسول- في ضلالتهم وجهلهم بالحق الى ان ينزل العذاب بهم."},{"id":"2728","s":23,"a":55,"at":"ايحسبون انما نمدهم به من مال وبنين","dt":"[55] ايظن هؤلاء الكفار ان ما نمدهم به من اموال واولاد في الدنيا هو تعجيل خير لهم يستحقونه؟"},{"id":"2729","s":23,"a":56,"at":"نسارع لهم في الخيرات بل لا يشعرون","dt":"[56] انما نعجل لهم الخير فتنه لهم واستدراجا، ولكنهم لا يحسون بذلك."},{"id":"2730","s":23,"a":57,"at":"ان الذين هم من خشيه ربهم مشفقون","dt":"[57] ان الذين هم من خشيه ربهم مشفقون وجلون مما خوفهم الله تعالى به."},{"id":"2731","s":23,"a":58,"at":"والذين هم بايات ربهم يؤمنون","dt":"[58] والذين هم يصدقون بايات الله في القران، ويعملون بها."},{"id":"2732","s":23,"a":59,"at":"والذين هم بربهم لا يشركون","dt":"[59] والذين هم يخلصون العباده لله وحده، ولا يشركون به غيره."},{"id":"2733","s":23,"a":60,"at":"والذين يؤتون ما اتوا وقلوبهم وجله انهم الى ربهم راجعون","dt":"[60] والذين يجتهدون في اعمال الخير والبر، وقلوبهم خائفه الا تقبل اعمالهم، والا تنجيهم من عذاب ربهم اذا رجعوا اليه للحساب."},{"id":"2734","s":23,"a":61,"at":"اولئك يسارعون في الخيرات وهم لها سابقون","dt":"[61] اولئك المجتهدون في الطاعه، دابهم المسارعه الى كل عمل صالح، وهم الى الخيرات سابقون."},{"id":"2735","s":23,"a":62,"at":"ولا نكلف نفسا الا وسعها ولدينا كتاب ينطق بالحق وهم لا يظلمون","dt":"[62] ولا نكلف عبدا من عبادنا الا بما يسعه العمل به، واعمالهم مسطوره عندنا في كتاب احصاء الاعمال الذي ترفعه الملائكه ينطق بالحق عليهم، ولا يظلم احد منهم."},{"id":"2736","s":23,"a":63,"at":"بل قلوبهم في غمره من هذا ولهم اعمال من دون ذلك هم لها عاملون","dt":"[63] لكن قلوب الكفار في ضلال غامر عن هذا القران وما فيه، ولهم مع شركهم اعمال سيئه، يمهلهم الله ليعملوها، فينالوا غضب الله وعقابه."},{"id":"2737","s":23,"a":64,"at":"حتى اذا اخذنا مترفيهم بالعذاب اذا هم يجارون","dt":"[64] حتى اذا اخذنا المترفين واهل البطر منهم بعذابنا، اذا هم يرفعون اصواتهم يتضرعون مستغيثين."},{"id":"2738","s":23,"a":65,"at":"لا تجاروا اليوم انكم منا لا تنصرون","dt":"[65] فيقال لهم: لا تصرخوا ولا تستغيثوا اليوم، انكم لا تستطيعون نصر انفسكم، ولا ينصركم احد من عذاب الله."},{"id":"2739","s":23,"a":66,"at":"قد كانت اياتي تتلى عليكم فكنتم على اعقابكم تنكصون","dt":"[66] قد كانت ايات القران تقرا عليكم؛ لتؤمنوا بها، فكنتم تنفرون من سماعها والتصديق بها، والعمل بها كما يفعل الناكص على عقبيه برجوعه الى الوراء."},{"id":"2740","s":23,"a":67,"at":"مستكبرين به سامرا تهجرون","dt":"[67] تفعلون ذلك مستكبرين على الناس بغير الحق بسبب بيت الله الحرام، تقولون: نحن اهله لا نغلب فيه، وتتسامرون حوله بالسيئ من القول."},{"id":"2741","s":23,"a":68,"at":"افلم يدبروا القول ام جاءهم ما لم يات اباءهم الاولين","dt":"[68] افلم يتفكروا في القران فيعرفوا صدقه، ام منعهم من الايمان انه جاءهم رسول وكتاب لم يات اباءهم الاولين مثله، فانكروه واعرضوا عنه؟"},{"id":"2742","s":23,"a":69,"at":"ام لم يعرفوا رسولهم فهم له منكرون","dt":"[69] ام منعهم من اتباع الحق ان رسولهم محمدا -صلى الله عليه وسلم- غير معروف عندهم، فهم منكرون له؟"},{"id":"2743","s":23,"a":70,"at":"ام يقولون به جنه بل جاءهم بالحق واكثرهم للحق كارهون","dt":"[70] بل احسبوه مجنونا؟ لقد كذبوا؛ فانما جاءهم بالقران والتوحيد والدين الحق، واكثرهم كارهون للحق حسدا وبغيا."},{"id":"2744","s":23,"a":71,"at":"ولو اتبع الحق اهواءهم لفسدت السموات والارض ومن فيهن بل اتيناهم بذكرهم فهم عن ذكرهم معرضون","dt":"[71] ولو شرع الله لهم ما يوافق اهواءهم لفسدت السموات والارض ومن فيهن، بل اتيناهم بما فيه عزهم وشرفهم، وهو القران، فهم عنه معرضون."},{"id":"2745","s":23,"a":72,"at":"ام تسالهم خرجا فخراج ربك خير وهو خير الرازقين","dt":"[72] بل امنعهم من الايمان انك -ايها الرسول- تسالهم اجرا على دعوتك لهم فبخلوا؟ لم تفعل ذلك، فان ما عند الله من الثواب والعطاء خير، وهو خير الرازقين، فلا يقدر احد ان يرزق مثل رزقه سبحانه وتعالى."},{"id":"2746","s":23,"a":73,"at":"وانك لتدعوهم الى صراط مستقيم","dt":"[73] وانك –ايها الرسول- لتدعو قومك وغيرهم الى دين قويم، وهو دين الاسلام."},{"id":"2747","s":23,"a":74,"at":"وان الذين لا يؤمنون بالاخره عن الصراط لناكبون","dt":"[74] وان الذين لا يصدقون بالبعث والحساب، ولا يعملون لهما، عن طريق الدين القويم لمائلون الى غيره."},{"id":"2748","s":23,"a":75,"at":"ولو رحمناهم وكشفنا ما بهم من ضر للجوا في طغيانهم يعمهون","dt":"[75] ولو رحمناهم وكشفنا عنهم ما بهم من قحط وجوع لتمادوا في الكفر والعناد، يتحيرون ويتخبطون."},{"id":"2749","s":23,"a":76,"at":"ولقد اخذناهم بالعذاب فما استكانوا لربهم وما يتضرعون","dt":"[76] ولقد ابتليناهم بصنوف المصائب فما خضعوا لربهم، وما دعوه خاشعين عند نزولها."},{"id":"2750","s":23,"a":77,"at":"حتى اذا فتحنا عليهم بابا ذا عذاب شديد اذا هم فيه مبلسون","dt":"[77] حتى اذا فتحنا عليهم بابا من العذاب الشديد في الاخره، اذا هم فيه ايسون من كل خير، متحيرون لا يدرون ما يصنعون."},{"id":"2751","s":23,"a":78,"at":"وهو الذي انشا لكم السمع والابصار والافئده قليلا ما تشكرون","dt":"[78] وهو الذي انشا لكم السمع لادراك المسموعات، والابصار لادراك المرئيات، والافئده لتفقهوا بها، ومع ذلك فشكركم لهذه النعم المتواليه عليكم قليل لا يذكر."},{"id":"2752","s":23,"a":79,"at":"وهو الذي ذراكم في الارض واليه تحشرون","dt":"[79] وهو الذي خلق جميع الناس في الارض، واليه تحشرون بعد موتكم، فيجازيكم بما عملتم من خير او شر."},{"id":"2753","s":23,"a":80,"at":"وهو الذي يحيي ويميت وله اختلاف الليل والنهار افلا تعقلون","dt":"[80] وهو وحده الذي يحيي من العدم، ويميت بعد الحياه، وله تعاقب الليل والنهار وتفاوتهما، افلا تعقلون قدرته ووحدانيته؟"},{"id":"2754","s":23,"a":81,"at":"بل قالوا مثل ما قال الاولون","dt":"[81] لكن الكفار لم يصدقوا بالبعث، بل رددوا مقوله اسلافهم المنكرين."},{"id":"2755","s":23,"a":82,"at":"قالوا ائذا متنا وكنا ترابا وعظاما ائنا لمبعوثون","dt":"[82] قالوا: ااذا متنا وتحللت اجسامنا وعظامنا في تراب الارض نحيا مره اخرى؟ هذا لا يكون ولا يتصور."},{"id":"2756","s":23,"a":83,"at":"لقد وعدنا نحن واباؤنا هذا من قبل ان هذا الا اساطير الاولين","dt":"[83] لقد قيل هذا الكلام لابائنا من قبل، كما تقوله لنا يا محمد، فلم نره حقيقه، ما هذا الا اباطيل الاولين."},{"id":"2757","s":23,"a":84,"at":"قل لمن الارض ومن فيها ان كنتم تعلمون","dt":"[84] قل لهم: لمن هذه الارض ومن فيها ان كان لديكم علم؟"},{"id":"2758","s":23,"a":85,"at":"سيقولون لله قل افلا تذكرون","dt":"[85] سيعترفون حتما بانها لله، هو خالقها ومالكها، قل لهم: الا يكون لكم في ذلك تذكر بانه قادر على البعث والنشور؟"},{"id":"2759","s":23,"a":86,"at":"قل من رب السموات السبع ورب العرش العظيم","dt":"[86] قل من رب السموات السبع ورب العرش العظيم، الذي جعله الله اعظم المخلوقات واعلاها؟"},{"id":"2760","s":23,"a":87,"at":"سيقولون لله قل افلا تتقون","dt":"[87] سيقولون حتما: هي ملك لله، فقل لهم: افلا تخافون عذابه اذا عبدتم غيره؟"},{"id":"2761","s":23,"a":88,"at":"قل من بيده ملكوت كل شيء وهو يجير ولا يجار عليه ان كنتم تعلمون","dt":"[88] قل: من مالك كل شيء ومن بيده خزائن كل شيء، ومن يجير من استجار به، ولا يقدر احد ان يجير ويحمي من اراد الله اهلاكه، ولا يدفع الشر الذي قدره الله، ان كنتم تعلمون ذلك؟"},{"id":"2762","s":23,"a":89,"at":"سيقولون لله قل فانى تسحرون","dt":"[89] سيجيبون: بان ذلك كله لله، قل لهم: كيف تذهب عقولكم وتخدعون وتصرفون عن توحيد الله وطاعته، وتصديق امر البعث والنشور؟"},{"id":"2763","s":23,"a":90,"at":"بل اتيناهم بالحق وانهم لكاذبون","dt":"[90] بل اتينا هؤلاء المنكرين بالحق فيما ارسلنا به محمدا -صلى الله عليه وسلم-، وانهم لكاذبون في شركهم وانكارهم البعث."},{"id":"2764","s":23,"a":91,"at":"ما اتخذ الله من ولد وما كان معه من اله اذا لذهب كل اله بما خلق ولعلا بعضهم على بعض سبحان الله عما يصفون","dt":"[91] لم يجعل الله لنفسه ولدا، ولم يكن معه من معبود اخر؛ لانه لو كان ثمه اكثر من معبود لانفرد كل معبود بمخلوقاته، ولكان بينهم مغالبه كشان ملوك الدنيا، فيختل نظام الكون، تنزه الله سبحانه وتعالى وتقدس عن وصفهم له بان له شريكا او ولدا."},{"id":"2765","s":23,"a":92,"at":"عالم الغيب والشهاده فتعالى عما يشركون","dt":"[92] هو وحده يعلم ما غاب عن خلقه وما شاهدوه، فتنزه الله تعالى عن الشريك الذي يزعمون."},{"id":"2766","s":23,"a":93,"at":"قل رب اما تريني ما يوعدون","dt":"[93] قل -ايها الرسول-: رب اما تريني في هؤلاء المشركين ما تعدهم من عذابك فلا تهلكني بما تهلكهم به، ونجني من عذابك وسخطك،"},{"id":"2767","s":23,"a":94,"at":"رب فلا تجعلني في القوم الظالمين","dt":"[94] فلا تجعلني في القوم المشركين الظالمين، ولكن اجعلني ممن رضيت عنهم."},{"id":"2768","s":23,"a":95,"at":"وانا على ان نريك ما نعدهم لقادرون","dt":"[95] واننا لقادرون على ان نريك ما نعدهم من العذاب."},{"id":"2769","s":23,"a":96,"at":"ادفع بالتي هي احسن السيئه نحن اعلم بما يصفون","dt":"[96] اذا اساء اليك اعداؤك -ايها الرسول- بالقول او الفعل فلا تقابلهم بالاساءه، ولكن ادفع اساءتهم بالاحسان منك اليهم، نحن اعلم بما يصفه هؤلاء المشركون من الشرك والتكذيب، وسنجازيهم عليه اسوا الجزاء."},{"id":"2770","s":23,"a":97,"at":"وقل رب اعوذ بك من همزات الشياطين","dt":"[97] وقل -ايها النبي-: رب استجير بك من اغواء الشياطين المغريه على الباطل والفساد والصد عن الحق ووسوستها،"},{"id":"2771","s":23,"a":98,"at":"واعوذ بك رب ان يحضرون","dt":"[98] واستجير بك -يا رب- من حضورهم في شيء من اموري."},{"id":"2772","s":23,"a":99,"at":"حتى اذا جاء احدهم الموت قال رب ارجعون","dt":"[99] يخبر الله تعالى عن حال المحتضر من الكافرين او المفرطين في امره تعالى، حتى اذا اشرف على الموت، وشاهد ما اعد له من العذاب قال: رب ردوني الى الدنيا."},{"id":"2773","s":23,"a":100,"at":"لعلي اعمل صالحا فيما تركت كلا انها كلمه هو قائلها ومن ورائهم برزخ الى يوم يبعثون","dt":"[100] لعلي استدرك ما ضيعت من الايمان والطاعه. ليس له ذلك، فلا يجاب الى ما طلب، ولا يمهل، فانما هي كلمه هو قائلها قولا لا ينفعه، وهو فيه غير صادق، فلو رد الى الدنيا لعاد الى ما نهي عنه، وسيبقى المتوفون في الحاجز والبرزخ الذي بين الدنيا والاخره الى يوم البعث والنشور."},{"id":"2774","s":23,"a":101,"at":"فاذا نفخ في الصور فلا انساب بينهم يومئذ ولا يتساءلون","dt":"[101] فاذا كان يوم القيامه، ونفخ الملك المكلف في «القرن»، وبعث الناس من قبورهم، فلا تفاخر بالانساب حينئذ كما كانوا يفتخرون بها في الدنيا، ولا يسال احد احدا."},{"id":"2775","s":23,"a":102,"at":"فمن ثقلت موازينه فاولئك هم المفلحون","dt":"[102] فمن كثرت حسناته وثقلت بها موازين اعماله عند الحساب، فاولئك هم الفائزون بالجنه."},{"id":"2776","s":23,"a":103,"at":"ومن خفت موازينه فاولئك الذين خسروا انفسهم في جهنم خالدون","dt":"[103] ومن قلت حسناته في الميزان، ورجحت سيئاته، واعظمها الشرك، فاولئك هم الذين خابوا وخسروا انفسهم، في نار جهنم خالدون."},{"id":"2777","s":23,"a":104,"at":"تلفح وجوههم النار وهم فيها كالحون","dt":"[104] تحرق النار وجوههم، وهم فيها عابسون تقلصت شفاههم، وبرزت اسنانهم."},{"id":"2778","s":23,"a":105,"at":"الم تكن اياتي تتلى عليكم فكنتم بها تكذبون","dt":"[105] يقال لهم: الم تكن ايات القران تتلى عليكم في الدنيا، فكنتم بها تكذبون؟"},{"id":"2779","s":23,"a":106,"at":"قالوا ربنا غلبت علينا شقوتنا وكنا قوما ضالين","dt":"[106] لما بلغتهم الرسل وانذرتهم قالوا يوم القيامه: ربنا غلبت علينا لذاتنا واهواؤنا المقدره علينا في سابق علمك، وكنا في فعلنا ضالين عن الهدى."},{"id":"2780","s":23,"a":107,"at":"ربنا اخرجنا منها فان عدنا فانا ظالمون","dt":"[107] ربنا اخرجنا من النار، واعدنا الى الدنيا، فان رجعنا الى الضلال فانا ظالمون نستحق العقوبه."},{"id":"2781","s":23,"a":108,"at":"قال اخسئوا فيها ولا تكلمون","dt":"[108] قال الله عز وجل لهم: امكثوا في النار اذلاء ولا تخاطبوني. فانقطع عند ذلك دعاؤهم ورجاؤهم."},{"id":"2782","s":23,"a":109,"at":"انه كان فريق من عبادي يقولون ربنا امنا فاغفر لنا وارحمنا وانت خير الراحمين","dt":"[109] انه كان فريق من عبادي -وهم المؤمنون- يدعون: ربنا امنا فاستر ذنوبنا، وارحمنا، وانت خير الراحمين."},{"id":"2783","s":23,"a":110,"at":"فاتخذتموهم سخريا حتى انسوكم ذكري وكنتم منهم تضحكون","dt":"[110] فاشتغلتم بالاستهزاء بهم حتى نسيتم ذكر الله، فبقيتم على تكذيبكم، وقد كنتم تضحكون منهم سخريه واستهزاء."},{"id":"2784","s":23,"a":111,"at":"اني جزيتهم اليوم بما صبروا انهم هم الفائزون","dt":"[111] اني جزيت هذا الفريق من عبادي المؤمنين الفوز بالجنه؛ بسبب صبرهم على الاذى وطاعه الله."},{"id":"2785","s":23,"a":112,"at":"قال كم لبثتم في الارض عدد سنين","dt":"[112] ويسال الاشقياء في النار: كم بقيتم في الدنيا من السنين؟ وكم ضيعتم فيها من طاعه الله؟"},{"id":"2786","s":23,"a":113,"at":"قالوا لبثنا يوما او بعض يوم فاسال العادين","dt":"[113] قالوا لهول الموقف وشده العذاب: بقينا فيها يوما او بعض يوم، فاسال الحساب الذين يعدون الشهور والايام."},{"id":"2787","s":23,"a":114,"at":"قال ان لبثتم الا قليلا لو انكم كنتم تعلمون","dt":"[114] قال لهم: ما لبثتم الا وقتا قليلا لو صبرتم فيه على طاعه الله لفزتم بالجنه، لو كان عندكم علم بذلك؛ وذلك لان مده مكثهم في الدنيا قليله جدا بالنسبه الى طول مدتهم خالدين في النار."},{"id":"2788","s":23,"a":115,"at":"افحسبتم انما خلقناكم عبثا وانكم الينا لا ترجعون","dt":"[115] افحسبتم -ايها الخلق- انما خلقناكم مهملين، لا امر ولا نهي ولا ثواب ولا عقاب، وانكم الينا لا ترجعون في الاخره للحساب والجزاء؟"},{"id":"2789","s":23,"a":116,"at":"فتعالى الله الملك الحق لا اله الا هو رب العرش الكريم","dt":"[116] فتعالى الله الملك المتصرف في كل شيء، الذي هو حق، ووعده حق، ووعيده حق، وكل شيء منه حق، وتقدس عن ان يخلق شيئا عبثا او سفها، لا اله غيره رب العرش الكريم، فعرش الرحمن موصوف بالكرم؛ لشرفه، والعرش اعظم المخلوقات."},{"id":"2790","s":23,"a":117,"at":"ومن يدع مع الله الها اخر لا برهان له به فانما حسابه عند ربه انه لا يفلح الكافرون","dt":"[117] ومن يعبد مع الله الواحد الها اخر، لا حجه له على استحقاقه العباده، فانما جزاؤه على عمله السيئ عند ربه في الاخره. انه لا فلاح ولا نجاه للكافرين يوم القيامه."},{"id":"2791","s":23,"a":118,"at":"وقل رب اغفر وارحم وانت خير الراحمين","dt":"[118] وقل -ايها النبي-: رب تجاوز عن الذنوب وارحم؛ وانت خير من رحم ذا ذنب، فقبل توبته ولم يعاقبه على ذنبه."},{"id":"2792","s":24,"a":1,"at":"سوره انزلناها وفرضناها وانزلنا فيها ايات بينات لعلكم تذكرون","dt":"[1] هذه سوره عظيمه من القران انزلناها، واوجبنا العمل باحكامها، وانزلنا فيها دلالات واضحات؛ لتتذكروا -ايها المؤمنون- بهذه الايات البينات، وتعملوا بها."},{"id":"2793","s":24,"a":2,"at":"الزانيه والزاني فاجلدوا كل واحد منهما مائه جلده ولا تاخذكم بهما رافه في دين الله ان كنتم تؤمنون بالله واليوم الاخر وليشهد عذابهما طائفه من المؤمنين","dt":"[2] الزانيه والزاني اللذان لم يسبق لهما الزواج، عقوبه كل منهما مائه جلده بالسوط، وثبت في السنه مع هذا الجلد التغريب لمده عام. ولا تحملكم الرافه بهما على ترك العقوبه او تخفيفها، ان كنتم مصدقين بالله واليوم الاخر عاملين باحكام الاسلام، وليحضر العقوبه عدد من المؤمنين؛ تشنيعا وزجرا وعظه واعتبارا."},{"id":"2794","s":24,"a":3,"at":"الزاني لا ينكح الا زانيه او مشركه والزانيه لا ينكحها الا زان او مشرك وحرم ذلك على المؤمنين","dt":"[3] الزاني لا يرضى الا بنكاح زانيه او مشركه لا تقر بحرمه الزنى، والزانيه لا ترضى الا بنكاح زان او مشرك لا يقر بحرمه الزنى، اما العفيفون والعفيفات فانهم لا يرضون بذلك، وحرم ذلك النكاح على المؤمنين. وهذا دليل صريح على تحريم نكاح الزانيه حتى تتوب، وكذلك تحريم انكاح الزاني حتى يتوب."},{"id":"2795","s":24,"a":4,"at":"والذين يرمون المحصنات ثم لم ياتوا باربعه شهداء فاجلدوهم ثمانين جلده ولا تقبلوا لهم شهاده ابدا واولئك هم الفاسقون","dt":"[4] والذين يتهمون بالفاحشه انفسا عفيفه من النساء والرجال من دون ان يشهد معهم اربعه شهود عدول، فاجلدوهم بالسوط ثمانين جلده، ولا تقبلوا لهم شهاده ابدا، واولئك هم الخارجون عن طاعه الله."},{"id":"2796","s":24,"a":5,"at":"الا الذين تابوا من بعد ذلك واصلحوا فان الله غفور رحيم","dt":"[5] لكن من تاب وندم ورجع عن اتهامه واصلح عمله، فان الله يغفر ذنبه ويرحمه، ويقبل توبته."},{"id":"2797","s":24,"a":6,"at":"والذين يرمون ازواجهم ولم يكن لهم شهداء الا انفسهم فشهاده احدهم اربع شهادات بالله انه لمن الصادقين","dt":"[6] والذين يرمون زوجاتهم بالزنى، ولم يكن لهم شهداء على اتهامهم لهن الا انفسهم، فعلى الواحد منهم ان يشهد امام القاضي اربع مرات بقوله: اشهد بالله اني صادق فيما رميتها به من الزنى، ."},{"id":"2798","s":24,"a":7,"at":"والخامسه ان لعنه الله عليه ان كان من الكاذبين","dt":"[7] ويزيد في الشهاده الخامسه الدعوه على نفسه باستحقاقه لعنه الله ان كان كاذبا في قوله."},{"id":"2799","s":24,"a":8,"at":"ويدرا عنها العذاب ان تشهد اربع شهادات بالله انه لمن الكاذبين","dt":"[8] وبشهادته تستوجب الزوجه عقوبه الزنى، وهي الرجم حتى الموت، ولا يدفع عنها هذه العقوبه الا ان تشهد في مقابل شهادته اربع شهادات بالله انه لكاذب في اتهامه لها بالزنى،"},{"id":"2800","s":24,"a":9,"at":"والخامسه ان غضب الله عليها ان كان من الصادقين","dt":"[9] وتزيد في الشهاده الخامسه الدعوه على نفسها باستحقاقها غضب الله، ان كان زوجها صادقا في اتهامه لها، وفي هذه الحال يفرق بينهما."},{"id":"2801","s":24,"a":10,"at":"ولولا فضل الله عليكم ورحمته وان الله تواب حكيم","dt":"[10] ولولا تفضل الله عليكم ورحمته -ايها المؤمنون- بهذا التشريع للازواج والزوجات، لاحل بالكاذب من المتلاعنين ما دعا به على نفسه، وان الله تواب لمن تاب من عباده، حكيم في شرعه وتدبيره."},{"id":"2802","s":24,"a":11,"at":"ان الذين جاءوا بالافك عصبه منكم لا تحسبوه شرا لكم بل هو خير لكم لكل امرئ منهم ما اكتسب من الاثم والذي تولى كبره منهم له عذاب عظيم","dt":"[11] ان الذين جاؤوا باشنع الكذب، وهو اتهام ام المؤمنين عائشه رضي الله عنها بالفاحشه، جماعه منتسبون اليكم -معشر المسلمين- لا تحسبوا قولهم شرا لكم، بل هو خير لكم، لما تضمن ذلك من تبرئه ام المؤمنين ونزاهتها والتنويه بذكرها، ورفع الدرجات، وتكفير السيئات، وتمحيص المؤمنين. لكل فرد تكلم بالافك جزاء فعله من الذنب، والذي تحمل معظمه، وهو عبدالله بن ابي بن سلول كبير المنافقين -لعنه الله- له عذاب عظيم في الاخره، وهو الخلود في الدرك الاسفل من النار."},{"id":"2803","s":24,"a":12,"at":"لولا اذ سمعتموه ظن المؤمنون والمؤمنات بانفسهم خيرا وقالوا هذا افك مبين","dt":"[12] هلا ظن المؤمنون والمؤمنات بعضهم ببعض خيرا عند سماعهم ذلك الافك، وهو السلامه مما رموا به، وقالوا: هذا كذب ظاهر على عائشه رضي الله عنها."},{"id":"2804","s":24,"a":13,"at":"لولا جاءوا عليه باربعه شهداء فاذ لم ياتوا بالشهداء فاولئك عند الله هم الكاذبون","dt":"[13] هلا اتى القاذفون باربعه شهود عدول على قولهم، فحين لم يفعلوا ذلك فاولئك هم الكاذبون عند الله."},{"id":"2805","s":24,"a":14,"at":"ولولا فضل الله عليكم ورحمته في الدنيا والاخره لمسكم في ما افضتم فيه عذاب عظيم","dt":"[14] ولولا فضل الله عليكم ورحمته لكم؛ بحيث شملكم احسانه في دينكم ودنياكم فلم يعجل عقوبتكم، وتاب على من تاب منكم، لاصابكم بسبب ما خضتم فيه عذاب عظيم."},{"id":"2806","s":24,"a":15,"at":"اذ تلقونه بالسنتكم وتقولون بافواهكم ما ليس لكم به علم وتحسبونه هينا وهو عند الله عظيم","dt":"[15] حين تتلقفون الافك وتتناقلونه بافواهكم، وهو قول باطل، وليس عندكم به علم، وهما محظوران: التكلم بالباطل، والقول بلا علم، وتظنون ذلك شيئا هينا، وهو عند الله عظيم. وفي هذا زجر بليغ عن التهاون في اشاعه الباطل."},{"id":"2807","s":24,"a":16,"at":"ولولا اذ سمعتموه قلتم ما يكون لنا ان نتكلم بهذا سبحانك هذا بهتان عظيم","dt":"[16] وهلا قلتم عند سماعكم اياه: ما يحل لنا الكلام بهذا الكذب، تنزيها لك –يا رب- من قول ذلك على زوجه رسولك محمد -صلى الله عليه وسلم-، فهو كذب عظيم في الوزر واستحقاق الذنب."},{"id":"2808","s":24,"a":17,"at":"يعظكم الله ان تعودوا لمثله ابدا ان كنتم مؤمنين","dt":"[17] يذكركم الله وينهاكم ان تعودوا ابدا لمثل هذا الفعل من الاتهام الكاذب، ان كنتم مؤمنين به."},{"id":"2809","s":24,"a":18,"at":"ويبين الله لكم الايات والله عليم حكيم","dt":"[18] ويبين الله لكم الايات المشتمله على الاحكام الشرعيه والمواعظ، والله عليم بافعالكم، حكيم في شرعه وتدبيره."},{"id":"2810","s":24,"a":19,"at":"ان الذين يحبون ان تشيع الفاحشه في الذين امنوا لهم عذاب اليم في الدنيا والاخره والله يعلم وانتم لا تعلمون","dt":"[19] ان الذين يحبون شيوع الفاحشه في المسلمين من قذف بالزنى او اي قول سيئ لهم عذاب اليم في الدنيا باقامه الحد عليهم، وغيره من البلايا الدنيويه، ولهم في الاخره عذاب النار ان لم يتوبوا، والله -وحده- يعلم كذبهم، ويعلم مصالح عباده، وعواقب الامور، وانتم لا تعلمون ذلك."},{"id":"2811","s":24,"a":20,"at":"ولولا فضل الله عليكم ورحمته وان الله رءوف رحيم","dt":"[20] ولولا فضل الله على من وقع في حديث الافك ورحمته بهم، وان الله يرحم عباده المؤمنين رحمه واسعه في عاجلهم واجلهم، لما بين هذه الاحكام والمواعظ، ولعاجل من خالف امره بالعقوبه."},{"id":"2812","s":24,"a":21,"at":"ياايها الذين امنوا لا تتبعوا خطوات الشيطان ومن يتبع خطوات الشيطان فانه يامر بالفحشاء والمنكر ولولا فضل الله عليكم ورحمته ما زكا منكم من احد ابدا ولكن الله يزكي من يشاء والله سميع عليم","dt":"[21] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه لا تسلكوا طرق الشيطان، ومن يسلك طرق الشيطان فانه يامره بقبيح الافعال ومنكراتها، ولولا فضل الله على المؤمنين ورحمته بهم ما طهر منهم احد ابدا من دنس ذنبه، ولكن الله -بفضله- يطهر من يشاء. والله سميع لاقوالكم، عليم بنياتكم وافعالكم."},{"id":"2813","s":24,"a":22,"at":"ولا ياتل اولو الفضل منكم والسعه ان يؤتوا اولي القربى والمساكين والمهاجرين في سبيل الله وليعفوا وليصفحوا الا تحبون ان يغفر الله لكم والله غفور رحيم","dt":"[22] ولا يحلف اهل الفضل في الدين والسعه في المال على ترك صله اقربائهم الفقراء، والمحتاجين الذين لا يملكون ما يكفيهم ويسد حاجتهم، والمهاجرين في سبيل الله، ومنعهم النفقه؛ بسبب ذنب فعلوه، وليتجاوزوا عن اساءتهم، ولا يعاقبوهم. الا تحبون ان يتجاوز الله عنكم؟ فتجاوزوا عنهم. والله غفور لعباده، رحيم بهم. وفي هذا الحث على العفو والصفح، ولو قوبل بالاساءه."},{"id":"2814","s":24,"a":23,"at":"ان الذين يرمون المحصنات الغافلات المؤمنات لعنوا في الدنيا والاخره ولهم عذاب عظيم","dt":"[23] ان الذين يقذفون بالزنى العفيفات الغافلات المؤمنات اللاتي لم يخطر ذلك بقلوبهن، مطرودون من رحمه الله في الدنيا والاخره، ولهم عذاب عظيم في نار جهنم. وفي هذه الايه دليل على كفر من سب، او اتهم زوجه من زوجات النبي -صلى الله عليه وسلم- بسوء."},{"id":"2815","s":24,"a":24,"at":"يوم تشهد عليهم السنتهم وايديهم وارجلهم بما كانوا يعملون","dt":"[24] ذلك العذاب يوم القيامه يوم تشهد عليهم السنتهم بما نطقت، وتتكلم ايديهم وارجلهم بما عملت."},{"id":"2816","s":24,"a":25,"at":"يومئذ يوفيهم الله دينهم الحق ويعلمون ان الله هو الحق المبين","dt":"[25] في هذا اليوم يوفيهم الله جزاءهم كاملا على اعمالهم بالعدل، ويعلمون في ذلك الموقف العظيم ان الله هو الحق المبين الذي هو حق، ووعده حق، ووعيده حق، وكل شيء منه حق، الذي لا يظلم احدا مثقال ذره."},{"id":"2817","s":24,"a":26,"at":"الخبيثات للخبيثين والخبيثون للخبيثات والطيبات للطيبين والطيبون للطيبات اولئك مبرءون مما يقولون لهم مغفره ورزق كريم","dt":"[26] كل خبيث من الرجال والنساء والاقوال والافعال مناسب للخبيث وموافق له، وكل طيب من الرجال والنساء والاقوال والافعال مناسب للطيب وموافق له، والطيبون والطيبات مبرؤون مما يرميهم به الخبيثون من السوء، لهم من الله مغفره تستغرق الذنوب، ورزق كريم في الجنه."},{"id":"2818","s":24,"a":27,"at":"ياايها الذين امنوا لا تدخلوا بيوتا غير بيوتكم حتى تستانسوا وتسلموا على اهلها ذلكم خير لكم لعلكم تذكرون","dt":"[27] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، لا تدخلوا بيوتا غير بيوتكم حتى تستاذنوا اهلها في الدخول وتسلموا عليهم. وصيغه ذلك من السنه: السلام عليكم اادخل؟ ذلكم الاستئذان خير لكم؛ لعلكم تتذكرون -بفعلكم له- اوامر الله، فتطيعوه."},{"id":"2819","s":24,"a":28,"at":"فان لم تجدوا فيها احدا فلا تدخلوها حتى يؤذن لكم وان قيل لكم ارجعوا فارجعوا هو ازكى لكم والله بما تعملون عليم","dt":"[28] فان لم تجدوا في بيوت الاخرين احدا فلا تدخلوها حتى يوجد من ياذن لكم، فان لم ياذن، بل قال لكم: ارجعوا فارجعوا، ولا تلحوا، فان الرجوع عندئذ اطهر لكم؛ لان للانسان احوالا يكره اطلاع احد عليها. والله بما تعملون عليم، فيجازي كل عامل بعمله."},{"id":"2820","s":24,"a":29,"at":"ليس عليكم جناح ان تدخلوا بيوتا غير مسكونه فيها متاع لكم والله يعلم ما تبدون وما تكتمون","dt":"[29] لكن لا حرج عليكم ان تدخلوا بغير استئذان بيوتا ليست مخصصه لسكنى اناس بذاتهم، بل ليتمتع بها من يحتاج اليها كالبيوت المعده صدقه لابن السبيل في طرق المسافرين وغيرها من المرافق، ففيها منافع وحاجه لمن يدخلها، وفي الاستئذان مشقه. والله يعلم احوالكم الظاهره والخفيه."},{"id":"2821","s":24,"a":30,"at":"قل للمؤمنين يغضوا من ابصارهم ويحفظوا فروجهم ذلك ازكى لهم ان الله خبير بما يصنعون","dt":"[30] قل -ايها النبي- للمؤمنين يغضوا من ابصارهم عما لا يحل لهم من النساء والعورات، ويحفظوا فروجهم عما حرم الله من الزنى واللواط، وكشف العورات، ونحو ذلك، ذلك اطهر لهم. ان الله خبير بما يصنعون فيما يامرهم به وينهاهم عنه."},{"id":"2822","s":24,"a":31,"at":"وقل للمؤمنات يغضضن من ابصارهن ويحفظن فروجهن ولا يبدين زينتهن الا ما ظهر منها وليضربن بخمرهن على جيوبهن ولا يبدين زينتهن الا لبعولتهن او ابائهن او اباء بعولتهن او ابنائهن او ابناء بعولتهن او اخوانهن او بني اخوانهن او بني اخواتهن او نسائهن او ما ملكت ايمانهن او التابعين غير اولي الاربه من الرجال او الطفل الذين لم يظهروا على عورات النساء ولا يضربن بارجلهن ليعلم ما يخفين من زينتهن وتوبوا الى الله جميعا ايها المؤمنون لعلكم تفلحون","dt":"[31] وقل للمؤمنات يغضضن من ابصارهن عما لا يحل لهن من العورات، ويحفظن فروجهن عما حرم الله، ولا يظهرن زينتهن للرجال، بل يجتهدن في اخفائها الا الثياب الظاهره التي جرت العاده بلبسها، اذا لم يكن في ذلك ما يدعو الى الفتنه بها، وليلقين باغطيه رؤوسهن على فتحات اعلى ثيابهن من جهه صدورهن؛ ليكمل سترهن، ولا يظهرن الزينه الخفيه الا لازواجهن؛ اذ يرون منهن ما لا يرى غيرهم. وبعضها كالوجه، والعنق، واليدين، والساعدين يباح رؤيته لابائهن، او اباء ازواجهن، او ابنائهن، او ابناء ازواجهن، او اخوانهن، او ابناء اخوانهن، او ابناء اخواتهن، او نسائهن المسلمات دون الكافرات، او ما ملكن من العبيد، او التابعين من الرجال الذين لا غرض ولا حاجه لهم في النساء، مثل البله الذين يتبعون غيرهم للطعام والشراب فحسب، او الاطفال الصغار الذين ليس لهم علم بامور عورات النساء، ولم توجد فيهم الشهوه بعد، ولا يضرب النساء عند سيرهن بارجلهن ليسمعن صوت ما خفي من زينتهن كالخلخال ونحوه، وارجعوا -ايها المؤمنون- الى طاعه الله فيما امركم به من هذه الصفات الجميله والاخلاق الحميده، واتركوا ما كان عليه اهل الجاهليه من الاخلاق والصفات الرذيله؛ رجاء ان تفوزوا بخيري الدنيا والاخره."},{"id":"2823","s":24,"a":32,"at":"وانكحوا الايامى منكم والصالحين من عبادكم وامائكم ان يكونوا فقراء يغنهم الله من فضله والله واسع عليم","dt":"[32] وزوجوا -ايها المؤمنون- من لا زوج له من الاحرار والحرائر والصالحين من عبيدكم وجواريكم، ان يكن الراغب في الزواج للعفه فقيرا يغنه الله من واسع رزقه. والله واسع كثير الخير عظيم الفضل، عليم باحوال عباده."},{"id":"2824","s":24,"a":33,"at":"وليستعفف الذين لا يجدون نكاحا حتى يغنيهم الله من فضله والذين يبتغون الكتاب مما ملكت ايمانكم فكاتبوهم ان علمتم فيهم خيرا واتوهم من مال الله الذي اتاكم ولا تكرهوا فتياتكم على البغاء ان اردن تحصنا لتبتغوا عرض الحياه الدنيا ومن يكرهن فان الله من بعد اكراههن غفور رحيم","dt":"[33] والذين لا يستطيعون الزواج لفقرهم او غيره فليطلبوا العفه عما حرم الله حتى يغنيهم الله من فضله، وييسر لهم الزواج. والذين يريدون ان يتحرروا من العبيد والاماء بمكاتبه اسيادهم على بعض المال يؤدونه اليهم، فعلى مالكيهم ان يكاتبوهم على ذلك ان علموا فيهم خيرا: من رشد وقدره على الكسب وصلاح في الدين، وعليهم ان يعطوهم شيئا من المال او ان يحطوا عنهم مما كوتبوا عليه. ولا يجوز لكم اكراه جواريكم على الزنى طلبا للمال، وكيف يقع منكم ذلك وهن يردن العفه وانتم تابونها؟ وفي هذا غايه التشنيع لفعلهم القبيح. ومن يكرههن على الزنى فان الله تعالى من بعد اكراههن غفور لهن رحيم بهن، والاثم على من اكرههن."},{"id":"2825","s":24,"a":34,"at":"ولقد انزلنا اليكم ايات مبينات ومثلا من الذين خلوا من قبلكم وموعظه للمتقين","dt":"[34] ولقد انزلنا اليكم -ايها الناس- ايات القران دلالات واضحات على الحق، ومثلا من اخبار الامم السابقه المؤمنين منهم والكافرين، وما جرى لهم وعليهم ما يكون مثلا وعبره لكم، وموعظه يتعظ بها من يتقي الله ويحذر عذابه."},{"id":"2826","s":24,"a":35,"at":"الله نور السموات والارض مثل نوره كمشكاه فيها مصباح المصباح في زجاجه الزجاجه كانها كوكب دري يوقد من شجره مباركه زيتونه لا شرقيه ولا غربيه يكاد زيتها يضيء ولو لم تمسسه نار نور على نور يهدي الله لنوره من يشاء ويضرب الله الامثال للناس والله بكل شيء عليم","dt":"[35] الله نور السموات والارض يدبر الامر فيهما ويهدي اهلهما، فهو -سبحانه- نور، وحجابه نور، به استنارت السموات والارض وما فيهما، وكتاب الله وهدايته نور منه سبحانه، فلولا نوره تعالى لتراكمت الظلمات بعضها فوق بعض. مثل نوره الذي يهدي اليه، وهو الايمان والقران في قلب المؤمن كمشكاه، وهي الكوه في الحائط غير النافذه، فيها مصباح، حيث تجمع الكوه نور المصباح فلا يتفرق، وذلك المصباح في زجاجه، كانها -لصفائها- كوكب مضيء كالدر، يوقد المصباح من زيت شجره مباركه، وهي شجره الزيتون، لا شرقيه فقط، فلا تصيبها الشمس اخر النهار، ولا غربيه فقط فلا تصيبها الشمس اول النهار، بل هي متوسطه في مكان من الارض لا الى الشرق ولا الى الغرب، يكاد زيتها -لصفائه- يضيء من نفسه قبل ان تمسه النار، فاذا مسته النار اضاء اضاءه بليغه، نور على نور، فهو نور من اشراق الزيت على نور من اشعال النار، فذلك مثل الهدى يضيء في قلب المؤمن. والله يهدي ويوفق لاتباع القران من يشاء، ويضرب الامثال للناس؛ ليعقلوا عنه امثاله وحكمه. والله بكل شيء عليم، لا يخفى عليه شيء."},{"id":"2827","s":24,"a":36,"at":"في بيوت اذن الله ان ترفع ويذكر فيها اسمه يسبح له فيها بالغدو والاصال","dt":"[36] هذا النور المضيء في مساجد امر الله ان يرفع شانها وبناؤها، ويذكر فيها اسمه بتلاوه كتابه والتسبيح والتهليل، وغير ذلك من انواع الذكر، يصلي فيها لله في الصباح والمساء:"},{"id":"2828","s":24,"a":37,"at":"رجال لا تلهيهم تجاره ولا بيع عن ذكر الله واقام الصلاه وايتاء الزكاه يخافون يوما تتقلب فيه القلوب والابصار","dt":"[37] رجال لا تشغلهم تجاره ولا بيع عن ذكر الله، واقام الصلاه، وايتاء الزكاه لمستحقيها، يخافون يوم القيامه الذي تتقلب فيه القلوب بين الرجاء في النجاه والخوف من الهلاك، وتتقلب فيه الابصار تنظر الى اي مصير تكون؟"},{"id":"2829","s":24,"a":38,"at":"ليجزيهم الله احسن ما عملوا ويزيدهم من فضله والله يرزق من يشاء بغير حساب","dt":"[38] ليعطيهم الله ثواب احسن اعمالهم، ويزيدهم من فضله بمضاعفه حسناتهم. والله يرزق من يشاء بغير حساب، بل يعطيه من الاجر ما لا يبلغه عمله، وبلا عد ولا كيل."},{"id":"2830","s":24,"a":39,"at":"والذين كفروا اعمالهم كسراب بقيعه يحسبه الظمان ماء حتى اذا جاءه لم يجده شيئا ووجد الله عنده فوفاه حسابه والله سريع الحساب","dt":"[39] والذين كفروا بربهم وكذبوا رسله، اعمالهم التي ظنوها نافعه لهم في الاخره، كصله الارحام وفك الاسرى وغيرها، كسراب، وهو ما يشاهد كالماء على الارض المستويه في الظهيره، يظنه العطشان ماء، فاذا اتاه لم يجده ماء. فالكافر يظن ان اعماله تنفعه، فاذا كان يوم القيامه لم يجد لها ثوابا، ووجد الله سبحانه وتعالى له بالمرصاد فوفاه جزاء عمله كاملا. والله سريع الحساب، فلا يستبطئ الجاهلون ذلك الوعيد، فانه لا بد من اتيانه."},{"id":"2831","s":24,"a":40,"at":"او كظلمات في بحر لجي يغشاه موج من فوقه موج من فوقه سحاب ظلمات بعضها فوق بعض اذا اخرج يده لم يكد يراها ومن لم يجعل الله له نورا فما له من نور","dt":"[40] او تكون اعمالهم مثل ظلمات في بحر عميق يعلوه موج، ومن فوق الموج موج اخر، ومن فوقه سحاب كثيف، ظلمات شديده بعضها فوق بعض، اذا اخرج الناظر يده لم يقارب رؤيتها من شده الظلمات، فالكفار تراكمت عليهم ظلمات الشرك والضلال وفساد الاعمال. ومن لم يجعل الله له نورا من كتابه وسنه نبيه يهتدي به فما له من هاد."},{"id":"2832","s":24,"a":41,"at":"الم تر ان الله يسبح له من في السموات والارض والطير صافات كل قد علم صلاته وتسبيحه والله عليم بما يفعلون","dt":"[41] الم تعلم -ايها الرسول- ان الله يسبح له من في السموات والارض من المخلوقات والطير، صافات اجنحتها في السماء تسبح ربها؟ كل مخلوق قد ارشده الله كيف يصلي له ويسبحه. وهو سبحانه عليم، مطلع على ما يفعله كل عابد ومسبح، لا يخفى عليه منها شيء، وسيجازيهم بذلك."},{"id":"2833","s":24,"a":42,"at":"ولله ملك السموات والارض والى الله المصير","dt":"[42] ولله وحده ملك السموات والارض، له السلطان فيهما، واليه المرجع يوم القيامه."},{"id":"2834","s":24,"a":43,"at":"الم تر ان الله يزجي سحابا ثم يؤلف بينه ثم يجعله ركاما فترى الودق يخرج من خلاله وينزل من السماء من جبال فيها من برد فيصيب به من يشاء ويصرفه عن من يشاء يكاد سنا برقه يذهب بالابصار","dt":"[43] الم تشاهد ان الله سبحانه وتعالى يسوق السحاب الى حيث يشاء، ثم يجمعه بعد تفرقه، ثم يجعله متراكما، فينزل من بينه المطر؟ وينزل من السحاب الذي يشبه الجبال في عظمته بردا، فيصيب به من يشاء من عباده ويصرفه عمن يشاء منهم بحسب حكمته وتقديره، يكاد ضوء ذلك البرق في السحاب من شدته يذهب بابصار الناظرين اليه."},{"id":"2835","s":24,"a":44,"at":"يقلب الله الليل والنهار ان في ذلك لعبره لاولي الابصار","dt":"[44] ومن دلائل قدره الله سبحانه وتعالى انه يقلب الليل والنهار بمجيء احدهما بعد الاخر، واختلافهما طولا وقصرا، ان في ذلك لدلاله يعتبر بها كل من له بصيره."},{"id":"2836","s":24,"a":45,"at":"والله خلق كل دابه من ماء فمنهم من يمشي على بطنه ومنهم من يمشي على رجلين ومنهم من يمشي على اربع يخلق الله ما يشاء ان الله على كل شيء قدير","dt":"[45] والله تعالى خلق كل ما يدب على الارض من ماء، فالماء اصل خلقه، فمن هذه الدواب: من يمشي زحفا على بطنه كالحيات ونحوها، ومنهم من يمشي على رجلين كالانسان، ومنهم من يمشي على اربع كالبهائم ونحوها. والله سبحانه وتعالى يخلق ما يشاء، وهو قادر على كل شيء."},{"id":"2837","s":24,"a":46,"at":"لقد انزلنا ايات مبينات والله يهدي من يشاء الى صراط مستقيم","dt":"[46] لقد انزلنا في القران علامات واضحات مرشدات الى الحق. والله يهدي ويوفق من يشاء من عباده الى الطريق المستقيم، وهو الاسلام."},{"id":"2838","s":24,"a":47,"at":"ويقولون امنا بالله وبالرسول واطعنا ثم يتولى فريق منهم من بعد ذلك وما اولئك بالمؤمنين","dt":"[47] ويقول المنافقون: صدقنا بالله وبما جاء به الرسول، واطعنا امرهما، ثم تعرض طوائف منهم من بعد ذلك فلا تقبل حكم الرسول، وما اولئك بالمؤمنين."},{"id":"2839","s":24,"a":48,"at":"واذا دعوا الى الله ورسوله ليحكم بينهم اذا فريق منهم معرضون","dt":"[48] و اذا دعوا في خصوماتهم الى ما في كتاب الله والى رسوله؛ ليحكم بينهم، اذا فريق منهم معرض لا يقبل حكم الله وحكم رسوله، مع انه الحق الذي لا شك فيه."},{"id":"2840","s":24,"a":49,"at":"وان يكن لهم الحق ياتوا اليه مذعنين","dt":"[49] وان يكن الحق في جانبهم فانهم ياتون الى النبي عليه الصلاه والسلام طائعين منقادين لحكمه؛ لعلمهم انه يقضي بالحق."},{"id":"2841","s":24,"a":50,"at":"افي قلوبهم مرض ام ارتابوا ام يخافون ان يحيف الله عليهم ورسوله بل اولئك هم الظالمون","dt":"[50] اسبب الاعراض ما في قلوبهم من مرض النفاق، ام شكوا في نبوه محمد -صلى الله عليه وسلم-، ام السبب خوفهم ان يكون حكم الله ورسوله جائرا؟ كلا، انهم لا يخافون جورا، بل السبب انهم هم الظالمون الفجره."},{"id":"2842","s":24,"a":51,"at":"انما كان قول المؤمنين اذا دعوا الى الله ورسوله ليحكم بينهم ان يقولوا سمعنا واطعنا واولئك هم المفلحون","dt":"[51] اما المؤمنون حقا فدابهم اذا دعوا الى التحاكم في خصوماتهم الى كتاب الله وحكم رسوله، ان يقبلوا الحكم ويقولوا: سمعنا ما قيل لنا واطعنا من دعانا الى ذلك، واولئك هم المفلحون الفائزون بمطلوبهم في جنات النعيم."},{"id":"2843","s":24,"a":52,"at":"ومن يطع الله ورسوله ويخش الله ويتقه فاولئك هم الفائزون","dt":"[52] ومن يطع الله ورسوله في الامر والنهي، ويخف عواقب العصيان، ويحذر عذاب الله، فهؤلاء هم الفائزون بالنعيم في الجنه."},{"id":"2844","s":24,"a":53,"at":"واقسموا بالله جهد ايمانهم لئن امرتهم ليخرجن قل لا تقسموا طاعه معروفه ان الله خبير بما تعملون","dt":"[53] واقسم المنافقون بالله تعالى غايه اجتهادهم في الايمان المغلظه: لئن امرتنا -ايها الرسول- بالخروج للجهاد معك لنخرجن، قل لهم: لا تحلفوا كذبا، فطاعتكم معروفه بانها باللسان فحسب، ان الله خبير بما تعملونه، وسيجاز يكم عليه."},{"id":"2845","s":24,"a":54,"at":"قل اطيعوا الله واطيعوا الرسول فان تولوا فانما عليه ما حمل وعليكم ما حملتم وان تطيعوه تهتدوا وما على الرسول الا البلاغ المبين","dt":"[54] قل -ايها الرسول- للناس: اطيعوا الله واطيعوا الرسول، فان تعرضوا فانما على الرسول فعل ما امر به من تبليغ الرساله، وعلى الجميع فعل ما كلفوه من الامتثال، وان تطيعوه ترشدوا الى الحق، وليس على الرسول الا ان يبلغ رساله ربه بلاغا بينا."},{"id":"2846","s":24,"a":55,"at":"وعد الله الذين امنوا منكم وعملوا الصالحات ليستخلفنهم في الارض كما استخلف الذين من قبلهم وليمكنن لهم دينهم الذي ارتضى لهم وليبدلنهم من بعد خوفهم امنا يعبدونني لا يشركون بي شيئا ومن كفر بعد ذلك فاولئك هم الفاسقون","dt":"[55] وعد الله بالنصر الذين امنوا منكم وعملوا الاعمال الصالحه، بان يورثهم ارض المشركين، ويجعلهم خلفاء فيها، مثلما فعل مع اسلافهم من المؤمنين بالله ورسله، وان يجعل دينهم الذي ارتضاه لهم -وهو الاسلام- دينا عزيزا مكينا، وان يبدل حالهم من الخوف الى الامن، اذا عبدوا الله وحده، واستقاموا على طاعته، ولم يشركوا معه شيئا، ومن كفر بعد ذلك الاستخلاف والامن والتمكين والسلطنه التامه، وجحد نعم الله، فاولئك هم الخارجون عن طاعه الله."},{"id":"2847","s":24,"a":56,"at":"واقيموا الصلاه واتوا الزكاه واطيعوا الرسول لعلكم ترحمون","dt":"[56] واقيموا الصلاه تامه، واتوا الزكاه لمستحقيها، واطيعوا الرسول -صلى الله عليه وسلم-؛ رجاء ان يرحمكم الله."},{"id":"2848","s":24,"a":57,"at":"لا تحسبن الذين كفروا معجزين في الارض وماواهم النار ولبئس المصير","dt":"[57] لا تظنن الذين كفروا معجزين الله في الارض، بل هو قادر على اهلاكهم، ومرجعهم في الاخره الى النار، وقبح هذا المرجع والمصير. وهو توجيه عام للامه، وان كان الخطاب فيه للرسول -صلى الله عليه وسلم-."},{"id":"2849","s":24,"a":58,"at":"ياايها الذين امنوا ليستاذنكم الذين ملكت ايمانكم والذين لم يبلغوا الحلم منكم ثلاث مرات من قبل صلاه الفجر وحين تضعون ثيابكم من الظهيره ومن بعد صلاه العشاء ثلاث عورات لكم ليس عليكم ولا عليهم جناح بعدهن طوافون عليكم بعضكم على بعض كذلك يبين الله لكم الايات والله عليم حكيم","dt":"[58] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه مروا عبيدكم واماءكم، والاطفال الاحرار دون سن الاحتلام ان يستاذنوا عند الدخول عليكم في اوقات عوراتكم الثلاثه: من قبل صلاه الفجر؛ لانه وقت الخروج من ثياب النوم ولبس ثياب اليقظه، ووقت خلع الثياب للقيلوله في الظهيره، ومن بعد صلاه العشاء؛ لانه وقت للنوم، وهذه الاوقات الثلاثه عورات لكم، يقل فيها التستر، اما فيما سواها فلا حرج اذا دخلوا بغير اذن؛ لحاجتهم في الدخول عليكم، فهم طوافون عليكم للخدمه، ولان العاده جرت بتردد بعضكم الى بعض فيها لقضاء المصالح. كما بين الله لكم احكام الاستئذان يبين لكم اياته واحكامه وحججه وشرائع دينه. والله عليم بما يصلح خلقه، حكيم في تدبيره امورهم."},{"id":"2850","s":24,"a":59,"at":"واذا بلغ الاطفال منكم الحلم فليستاذنوا كما استاذن الذين من قبلهم كذلك يبين الله لكم اياته والله عليم حكيم","dt":"[59] واذا بلغ الاطفال منكم سن الاحتلام والتكليف بالاحكام الشرعيه، فعليهم ان يستاذنوا اذا ارادوا الدخول في كل الاوقات كما يستاذن الكبار، وكما يبين الله اداب الاستئذان يبين الله تعالى لكم اياته. والله عليم بما يصلح عباده، حكيم في تشريعه."},{"id":"2851","s":24,"a":60,"at":"والقواعد من النساء اللاتي لا يرجون نكاحا فليس عليهن جناح ان يضعن ثيابهن غير متبرجات بزينه وان يستعففن خير لهن والله سميع عليم","dt":"[60] والعجائز من النساء اللاتي قعدن عن الاستمتاع والشهوه لكبرهن، فلا يطمعن في الرجال للزواج، ولا يطمع فيهن الرجال كذلك، فهؤلاء لا حرج عليهن ان يضعن بعض ثيابهن كالرداء الذي يكون فوق الثياب غير مظهرات ولا متعرضات للزينه، ولبسهن هذه الثياب -سترا وتعففا- احسن لهن. والله سميع لاقوالكم، عليم بنياتكم واعمالكم."},{"id":"2852","s":24,"a":61,"at":"ليس على الاعمى حرج ولا على الاعرج حرج ولا على المريض حرج ولا على انفسكم ان تاكلوا من بيوتكم او بيوت ابائكم او بيوت امهاتكم او بيوت اخوانكم او بيوت اخواتكم او بيوت اعمامكم او بيوت عماتكم او بيوت اخوالكم او بيوت خالاتكم او ما ملكتم مفاتحه او صديقكم ليس عليكم جناح ان تاكلوا جميعا او اشتاتا فاذا دخلتم بيوتا فسلموا على انفسكم تحيه من عند الله مباركه طيبه كذلك يبين الله لكم الايات لعلكم تعقلون","dt":"[61] ليس على اصحاب الاعذار من العميان وذوي العرج والمرضى اثم في ترك الامور الواجبه التي لا يقدرون على القيام بها، كالجهاد ونحوه مما يتوقف على بصر الاعمى او سلامه الاعرج او صحه المريض، وليس على انفسكم -ايها المؤمنون- حرج في ان تاكلوا من البيوت التي فيها ازواجكم وعيالكم، فيدخل فيها بيوت الاولاد، او من بيوت ابائكم، او امهاتكم، او اخوانكم، او اخواتكم، او اعمامكم، او عماتكم، او اخوالكم، او خالاتكم، او من البيوت التي وكلتم بحفظها في غيبه اصحابها باذنهم، او من بيوت الاصدقاء، ولا حرج عليكم ان تاكلوا مجتمعين او متفرقين، فاذا دخلتم بيوتا مسكونه او غير مسكونه فليسلم بعضكم على بعض بتحيه الاسلام، وهي: السلام عليكم ورحمه الله وبركاته، او السلام علينا وعلى عباد الله الصالحين اذا لم يوجد فيها احد، وهذه التحيه شرعها الله، وهي مباركه تنمي الموده والمحبه، طيبه محبوبه للسامع، بمثل هذا التبيين يبين الله لكم معالم دينه واياته؛ لتعقلوها، وتعملوا بها."},{"id":"2853","s":24,"a":62,"at":"انما المؤمنون الذين امنوا بالله ورسوله واذا كانوا معه على امر جامع لم يذهبوا حتى يستاذنوه ان الذين يستاذنونك اولئك الذين يؤمنون بالله ورسوله فاذا استاذنوك لبعض شانهم فاذن لمن شئت منهم واستغفر لهم الله ان الله غفور رحيم","dt":"[62] انما المؤمنون حقا هم الذين صدقوا الله ورسوله وعملوا بشرعه، واذا كانوا مع النبي -صلى الله عليه وسلم- على امر جمعهم له في مصلحه المسلمين، لم ينصرف احد منهم حتى يستاذنه، ان الذين يستاذنونك -ايها النبي- هم الذين يؤمنون بالله ورسوله حقا، فاذا استاذنوك لبعض حاجتهم فاذن لمن شئت ممن طلب الاذن في الانصراف لعذر، واطلب لهم المغفره من الله. ان الله غفور لذنوب عباده التائبين، رحيم بهم."},{"id":"2854","s":24,"a":63,"at":"لا تجعلوا دعاء الرسول بينكم كدعاء بعضكم بعضا قد يعلم الله الذين يتسللون منكم لواذا فليحذر الذين يخالفون عن امره ان تصيبهم فتنه او يصيبهم عذاب اليم","dt":"[63] لا تقولوا -ايها المؤمنون- عند ندائكم رسول الله: يا محمد، ولا يا محمد بن عبدالله، كما يقول ذلك بعضكم لبعض، ولكن شرفوه، وقولوا: يا نبي الله، يا رسول الله. قد يعلم الله المنافقين الذين يخرجون من مجلس النبي -صلى الله عليه وسلم- خفيه بغير اذنه، يلوذ بعضهم ببعض، فليحذر الذين يخالفون امر رسول الله ان تنزل بهم محنه وشر، او يصيبهم عذاب مؤلم موجع في الاخره."},{"id":"2855","s":24,"a":64,"at":"الا ان لله ما في السموات والارض قد يعلم ما انتم عليه ويوم يرجعون اليه فينبئهم بما عملوا والله بكل شيء عليم","dt":"[64] الا ان لله ما في السموات والارض خلقا وملكا وعباده، قد احاط علمه بجميع ما انتم عليه، ويوم يرجع العباد اليه في الاخره، يخبرهم بعملهم، ويجازيهم عليه، والله بكل شيء عليم، لا تخفى عليه اعمالهم واحوالهم."},{"id":"2856","s":25,"a":1,"at":"تبارك الذي نزل الفرقان على عبده ليكون للعالمين نذيرا","dt":"[1] عظمت بركات الله، وكثرت خيراته، وكملت اوصافه سبحانه وتعالى الذي نزل القران الفارق بين الحق والباطل على عبده محمد -صلى الله عليه وسلم-؛ ليكون رسولا للانس والجن، مخوفا لهم من عذاب الله."},{"id":"2857","s":25,"a":2,"at":"الذي له ملك السموات والارض ولم يتخذ ولدا ولم يكن له شريك في الملك وخلق كل شيء فقدره تقديرا","dt":"[2] الذي له ملك السموات والارض، ولم يتخذ ولدا، ولم يكن له شريك في ملكه، وهو الذي خلق كل شيء فسواه على ما يناسبه من الخلق، وفق ما تقتضيه حكمته دون نقص او خلل."},{"id":"2858","s":25,"a":3,"at":"واتخذوا من دونه الهه لا يخلقون شيئا وهم يخلقون ولا يملكون لانفسهم ضرا ولا نفعا ولا يملكون موتا ولا حياه ولا نشورا","dt":"[3] واتخذ مشركو العرب معبودات من دون الله لا تستطيع خلق شيء، والله خلقها وخلقهم، ولا تملك لنفسها دفع ضر او جلب نفع، ولا تستطيع اماته حي او احياء ميت، او بعث احد من الاموات حيا من قبره."},{"id":"2859","s":25,"a":4,"at":"وقال الذين كفروا ان هذا الا افك افتراه واعانه عليه قوم اخرون فقد جاءوا ظلما وزورا","dt":"[4] وقال الكافرون بالله: ما هذا القران الا كذب وبهتان اختلقه محمد، واعانه على ذلك اناس اخرون، فقد ارتكبوا ظلما فظيعا، واتوا زورا شنيعا؛ فالقران ليس مما يمكن لبشر ان يختلقه."},{"id":"2860","s":25,"a":5,"at":"وقالوا اساطير الاولين اكتتبها فهي تملى عليه بكره واصيلا","dt":"[5] وقالوا عن القران: هو احاديث الاولين المسطره في كتبهم، استنسخها محمد، فهي تقرا عليه صباحا ومساء."},{"id":"2861","s":25,"a":6,"at":"قل انزله الذي يعلم السر في السموات والارض انه كان غفورا رحيما","dt":"[6] قل -ايها الرسول- لهؤلاء الكفار: ان الذي انزل القران هو الله الذي احاط علمه بما في السموات والارض، انه كان غفورا لمن تاب من الذنوب والمعاصي، رحيما بهم حيث لم يعاجلهم بالعقوبه."},{"id":"2862","s":25,"a":7,"at":"وقالوا مال هذا الرسول ياكل الطعام ويمشي في الاسواق لولا انزل اليه ملك فيكون معه نذيرا","dt":"[7] وقال المشركون: ما لهذا الذي يزعم انه رسول الله -يعنون محمدا صلى الله عليه وسلم- ياكل الطعام مثلنا، ويمشي في الاسواق لطلب الرزق؟ فهلا ارسل الله معه ملكا يشهد على صدقه،"},{"id":"2863","s":25,"a":8,"at":"او يلقى اليه كنز او تكون له جنه ياكل منها وقال الظالمون ان تتبعون الا رجلا مسحورا","dt":"[8] او يهبط عليه من السماء كنز من مال، او تكون له حديقه عظيمه ياكل من ثمرها، وقال هؤلاء الظالمون المكذبون: ما تتبعون ايها المؤمنون الا رجلا به سحر غلب على عقله."},{"id":"2864","s":25,"a":9,"at":"انظر كيف ضربوا لك الامثال فضلوا فلا يستطيعون سبيلا","dt":"[9] انظر -ايها الرسول- كيف قال المكذبون في حقك تلك الاقوال العجيبه التي تشبه -لغرابتها- الامثال؛ ليتوصلوا الى تكذيبك؟ فبعدوا بذلك عن الحق، فلا يجدون سبيلا اليه؛ ليصححوا ما قالوه فيك من الكذب والافتراء."},{"id":"2865","s":25,"a":10,"at":"تبارك الذي ان شاء جعل لك خيرا من ذلك جنات تجري من تحتها الانهار ويجعل لك قصورا","dt":"[10] عظمت بركات الله، وكثرت خيراته، الذي ان شاء جعل لك -ايها الرسول- خيرا مما تمنوه لك، فجعل لك في الدنيا حدائق كثيره تتخللها الانهار، ويجعل لك فيها قصورا عظيمه."},{"id":"2866","s":25,"a":11,"at":"بل كذبوا بالساعه واعتدنا لمن كذب بالساعه سعيرا","dt":"[11] وما كذبوك؛ لانك تاكل الطعام، وتمشي في الاسواق، بل كذبوا بيوم القيامه وما فيه من جزاء، واعتدنا لمن كذب بالساعه نارا حاره تسعر بهم."},{"id":"2867","s":25,"a":12,"at":"اذا راتهم من مكان بعيد سمعوا لها تغيظا وزفيرا","dt":"[12] اذا رات النار هؤلاء المكذبين يوم القيامه من مكان بعيد، سمعوا صوت غليانها وزفيرها، من شده تغيظها منهم."},{"id":"2868","s":25,"a":13,"at":"واذا القوا منها مكانا ضيقا مقرنين دعوا هنالك ثبورا","dt":"[13] واذا القوا في مكان شديد الضيق من جهنم -وقد قرنت ايديهم بالسلاسل الى اعناقهم- دعوا على انفسهم بالهلاك للخلاص منها."},{"id":"2869","s":25,"a":14,"at":"لا تدعوا اليوم ثبورا واحدا وادعوا ثبورا كثيرا","dt":"[14] فيقال لهم تيئيسا: لا تدعوا اليوم بالهلاك مره واحده، بل مرات كثيره، فلن يزيدكم ذلك الا غما، فلا خلاص لكم."},{"id":"2870","s":25,"a":15,"at":"قل اذلك خير ام جنه الخلد التي وعد المتقون كانت لهم جزاء ومصيرا","dt":"[15] قل لهم -ايها الرسول-: اهذه النار التي وصفت لكم خير ام جنه النعيم الدائم التي وعد بها الخائفون من عذاب ربهم، كانت لهم ثوابا على عملهم، ومالا يرجعون اليه في الاخره؟"},{"id":"2871","s":25,"a":16,"at":"لهم فيها ما يشاءون خالدين كان على ربك وعدا مسئولا","dt":"[16] لهؤلاء المطيعين في الجنه ما يشتهون من ملاذ النعيم، متاعهم فيه دائم، كان دخولهم اياها على ربك -ايها الرسول- وعدا مسؤولا، يساله عباد الله المتقون، والله لا يخلف وعده."},{"id":"2872","s":25,"a":17,"at":"ويوم يحشرهم وما يعبدون من دون الله فيقول اانتم اضللتم عبادي هؤلاء ام هم ضلوا السبيل","dt":"[17] ويوم القيامه يحشر الله المشركين وما كانوا يعبدونه من دونه، فيقول لهؤلاء المعبودين: اانتم اضللتم عبادي هؤلاء عن طريق الحق، وامرتموهم بعبادتكم، ام هم ضلوا السبيل، فعبدوكم من تلقاء انفسهم؟"},{"id":"2873","s":25,"a":18,"at":"قالوا سبحانك ما كان ينبغي لنا ان نتخذ من دونك من اولياء ولكن متعتهم واباءهم حتى نسوا الذكر وكانوا قوما بورا","dt":"[18] قال المعبودون من دون الله: تنزيها لك -يا ربنا- عما فعل هؤلاء، فما يصح ان نتخذ سواك اولياء نواليهم، ولكن متعت هؤلاء المشركين واباءهم بالمال والعافيه في الدنيا، حتى نسوا ذكرك فاشركوا بك، وكانوا قوما هلكى غلب عليهم الشقاء والخذلان."},{"id":"2874","s":25,"a":19,"at":"فقد كذبوكم بما تقولون فما تستطيعون صرفا ولا نصرا ومن يظلم منكم نذقه عذابا كبيرا","dt":"[19] فيقال للمشركين: لقد كذبكم هؤلاء الذين عبدتموهم في ادعائكم عليهم، فها انتم اولاء لا تستطيعون دفعا للعذاب عن انفسكم، ولا نصرا لها، ومن يشرك بالله فيظلم نفسه ويعبد غير الله، ويمت على ذلك، يعذبه الله عذابا شديدا."},{"id":"2875","s":25,"a":20,"at":"وما ارسلنا قبلك من المرسلين الا انهم لياكلون الطعام ويمشون في الاسواق وجعلنا بعضكم لبعض فتنه اتصبرون وكان ربك بصيرا","dt":"[20] وما ارسلنا قبلك -ايها الرسول- احدا من رسلنا الا كانوا بشرا، ياكلون الطعام، ويمشون في الاسواق. وجعلنا بعضكم -ايها الناس- لبعض ابتلاء واختبارا بالهدى والضلال، والغنى والفقر، والصحه والمرض، هل تصبرون، فتقوموا بما اوجبه الله عليكم، وتشكروا له، فيثيبكم مولاكم، او لا تصبرون فتستحقوا العقوبه؟ وكان ربك -ايها الرسول- بصيرا بمن يجزع او يصبر، وبمن يكفر او يشكر."},{"id":"2876","s":25,"a":21,"at":"وقال الذين لا يرجون لقاءنا لولا انزل علينا الملائكه او نرى ربنا لقد استكبروا في انفسهم وعتوا عتوا كبيرا","dt":"[21] وقال الذين لا يؤملون لقاء ربهم بعد موتهم لانكارهم له: هلا انزل علينا الملائكه، فتخبرنا بان محمدا صادق، او نرى ربنا عيانا، فيخبرنا بصدقه في رسالته. لقد اعجبوا بانفسهم واستعلوا حيث اجترؤوا على هذا القول، وتجاوزوا الحد في طغيانهم وكفرهم."},{"id":"2877","s":25,"a":22,"at":"يوم يرون الملائكه لا بشرى يومئذ للمجرمين ويقولون حجرا محجورا","dt":"[22] يوم يرون الملائكه عند الاحتضار، وفي القبر، ويوم القيامه، على غير الصوره التي اقترحوها لا لتبشرهم بالجنه، ولكن لتقول لهم: جعل الله الجنه مكانا محرما عليكم."},{"id":"2878","s":25,"a":23,"at":"وقدمنا الى ما عملوا من عمل فجعلناه هباء منثورا","dt":"[23] وقدمنا الى ما عملوه من مظاهر الخير والبر، فجعلناه باطلا مضمحلا، لا ينفعهم كالهباء المنثور، وهو ما يرى في ضوء الشمس من خفيف الغبار؛ وذلك ان العمل لا ينفع في الاخره الا اذا توفر في صاحبه: الايمان بالله، والاخلاص له، والمتابعه لرسوله محمد -صلى الله عليه وسلم-."},{"id":"2879","s":25,"a":24,"at":"اصحاب الجنه يومئذ خير مستقرا واحسن مقيلا","dt":"[24] اصحاب الجنه يوم القيامه خير مستقرا من اهل النار واحسن منازل في الجنه، فراحتهم تامه، ونعيمهم لا يشوبه كدر."},{"id":"2880","s":25,"a":25,"at":"ويوم تشقق السماء بالغمام ونزل الملائكه تنزيلا","dt":"[25] واذكر -ايها الرسول- ذلك اليوم الذي تتشقق فيه السماء، ويظهر من فتحاتها السحاب الابيض الرقيق، وينزل الله ملائكه السموات يومئذ، فيحيطون بالخلائق في المحشر، وياتي الله تبارك وتعالى لفصل القضاء بين العباد، اتيانا يليق بجلاله."},{"id":"2881","s":25,"a":26,"at":"الملك يومئذ الحق للرحمن وكان يوما على الكافرين عسيرا","dt":"[26] الملك الحق في هذا اليوم للرحمن وحده دون من سواه، وكان هذا اليوم صعبا شديدا على الكافرين؛ لما ينالهم من العقاب والعذاب الاليم."},{"id":"2882","s":25,"a":27,"at":"ويوم يعض الظالم على يديه يقول ياليتني اتخذت مع الرسول سبيلا","dt":"[27] واذكر -ايها الرسول- يوم يعض الظالم لنفسه على يديه ندما وتحسرا قائلا: يا ليتني صاحبت رسول الله محمدا -صلى الله عليه وسلم- واتبعته في اتخاذ الاسلام طريقا الى الجنه،"},{"id":"2883","s":25,"a":28,"at":"ياويلتى ليتني لم اتخذ فلانا خليلا","dt":"[28] ويتحسر قائلا: يا ليتني لم اتخذ الكافر فلانا صديقا اتبعه واوده."},{"id":"2884","s":25,"a":29,"at":"لقد اضلني عن الذكر بعد اذ جاءني وكان الشيطان للانسان خذولا","dt":"[29] لقد اضلني هذا الصديق عن القران بعد اذ جاءني. وكان الشيطان الرجيم خذولا للانسان دائما. وفي هذه الايات التحذير من مصاحبه قرين السوء؛ فانه قد يكون سببا لادخال قرينه النار."},{"id":"2885","s":25,"a":30,"at":"وقال الرسول يارب ان قومي اتخذوا هذا القران مهجورا","dt":"[30] وقال الرسول شاكيا ما صنع قومه: يا رب ان قومي تركوا هذا القران وهجروه، متمادين في اعراضهم عنه وترك تدبره والعمل به وتبليغه. وفي الايه تخويف عظيم لمن هجر القران فلم يعمل به."},{"id":"2886","s":25,"a":31,"at":"وكذلك جعلنا لكل نبي عدوا من المجرمين وكفى بربك هاديا ونصيرا","dt":"[31] وكما جعلنا لك -ايها الرسول- اعداء من مجرمي قومك، جعلنا لكل نبي من الانبياء عدوا من مجرمي قومه، فاصبر كما صبروا. وكفى بربك هاديا ومرشدا ومعينا يعينك على اعدائك. وفي هذا تسليه لنبيه محمد -صلى الله عليه وسلم-."},{"id":"2887","s":25,"a":32,"at":"وقال الذين كفروا لولا نزل عليه القران جمله واحده كذلك لنثبت به فؤادك ورتلناه ترتيلا","dt":"[32] وقال الذين كفروا: هلا انزل القران على محمد جمله واحده كالتوراه والانجيل والزبور! قال الله سبحانه وتعالى: كذلك انزلناه مفرقا؛ لنقوي به قلبك وتزداد به طمانينه، فتعيه وتحمله، وبيناه في تثبت ومهله."},{"id":"2888","s":25,"a":33,"at":"ولا ياتونك بمثل الا جئناك بالحق واحسن تفسيرا","dt":"[33] ولا ياتيك -ايها الرسول- المشركون بحجه او شبهه الا جئناك بالجواب الحق وباحسن بيان له."},{"id":"2889","s":25,"a":34,"at":"الذين يحشرون على وجوههم الى جهنم اولئك شر مكانا واضل سبيلا","dt":"[34] اولئك الكفار هم الذين يسحبون على وجوههم الى جهنم، واولئك هم شر الناس منزله، وابعدهم طريقا عن الحق."},{"id":"2890","s":25,"a":35,"at":"ولقد اتينا موسى الكتاب وجعلنا معه اخاه هارون وزيرا","dt":"[35] ولقد اتينا موسى التوراه، وجعلنا معه اخاه هارون معينا له،"},{"id":"2891","s":25,"a":36,"at":"فقلنا اذهبا الى القوم الذين كذبوا باياتنا فدمرناهم تدميرا","dt":"[36] فقلنا لهما: اذهبا الى فرعون وقومه الذين كذبوا بدلائل ربوبيتنا والوهيتنا، فذهبا اليهم، فدعواهم الى الايمان بالله وطاعته وعدم الاشراك به، فكذبوهما، فاهلكناهم اهلاكا عظيما."},{"id":"2892","s":25,"a":37,"at":"وقوم نوح لما كذبوا الرسل اغرقناهم وجعلناهم للناس ايه واعتدنا للظالمين عذابا اليما","dt":"[37] واغرقنا قوم نوح بالطوفان حين كذبوه. ومن كذب رسولا فقد كذب الرسل جميعا. وجعلنا اغراقهم للناس عبره، وجعلنا لهم ولمن سلك سبيلهم في التكذيب يوم القيامه عذابا موجعا."},{"id":"2893","s":25,"a":38,"at":"وعادا وثمود واصحاب الرس وقرونا بين ذلك كثيرا","dt":"[38] واهلكنا عادا قوم هود، وثمود قوم صالح، واصحاب البئر وامما كثيره بين قوم نوح وعاد وثمود واصحاب الرس، لا يعلمهم الا الله."},{"id":"2894","s":25,"a":39,"at":"وكلا ضربنا له الامثال وكلا تبرنا تتبيرا","dt":"[39] وكل الامم بينا لهم الحجج، ووضحنا لهم الادله، وازحنا الاعذار عنهم، ومع ذلك لم يؤمنوا، فاهلكناهم بالعذاب اهلاكا."},{"id":"2895","s":25,"a":40,"at":"ولقد اتوا على القريه التي امطرت مطر السوء افلم يكونوا يرونها بل كانوا لا يرجون نشورا","dt":"[40] ولقد كان مشركو «مكه» يمرون في اسفارهم على قريه قوم لوط، وهي قريه «سدوم» التي اهلكت بالحجاره من السماء، فلم يعتبروا بها، بل كانوا لا يرجون معادا يوم القيامه يجازون فيه."},{"id":"2896","s":25,"a":41,"at":"واذا راوك ان يتخذونك الا هزوا اهذا الذي بعث الله رسولا","dt":"[41] واذا راك هؤلاء المكذبون -ايها الرسول- استهزؤوا بك قائلين: اهذا الذي يزعم ان الله بعثه رسولا الينا؟"},{"id":"2897","s":25,"a":42,"at":"ان كاد ليضلنا عن الهتنا لولا ان صبرنا عليها وسوف يعلمون حين يرون العذاب من اضل سبيلا","dt":"[42] انه قارب ان يصرفنا عن عباده اصنامنا بقوه حجته وبيانه، لولا ان ثبتنا على عبادتها، وسوف يعلمون حين يرون ما يستحقون من العذاب: من اضل دينا اهم ام محمد؟"},{"id":"2898","s":25,"a":43,"at":"ارايت من اتخذ الهه هواه افانت تكون عليه وكيلا","dt":"[43] انظر -ايها الرسول- متعجبا الى من اطاع هواه كطاعه الله، افانت تكون عليه حفيظا حتى ترده الى الايمان؟"},{"id":"2899","s":25,"a":44,"at":"ام تحسب ان اكثرهم يسمعون او يعقلون ان هم الا كالانعام بل هم اضل سبيلا","dt":"[44] ام تظن ان اكثرهم يسمعون ايات الله سماع تدبر، او يفهمون ما فيها؟ ما هم الا كالبهائم في عدم الانتفاع بما يسمعونه، بل هم اضل طريقا منها."},{"id":"2900","s":25,"a":45,"at":"الم تر الى ربك كيف مد الظل ولو شاء لجعله ساكنا ثم جعلنا الشمس عليه دليلا","dt":"[45] الم تر كيف مد الله الظل من طلوع الفجر الى طلوع الشمس؟ ولو شاء لجعله ثابتا مستقرا لا تزيله الشمس، ثم جعلنا الشمس علامه يستدل باحوالها على احواله،"},{"id":"2901","s":25,"a":46,"at":"ثم قبضناه الينا قبضا يسيرا","dt":"[46] ثم تقلص الظل يسيرا يسيرا، فكلما ازداد ارتفاع الشمس ازداد نقصانه. وذلك من الادله على قدره الله وعظمته، وانه وحده المستحق للعباده دون سواه."},{"id":"2902","s":25,"a":47,"at":"وهو الذي جعل لكم الليل لباسا والنوم سباتا وجعل النهار نشورا","dt":"[47] والله تعالى هو الذي جعل لكم الليل ساترا لكم بظلامه كما يستركم اللباس، وجعل النوم راحه لابدانكم فيه تهدؤون وتسكنون، وجعل لكم النهار؛ لتنتشروا في الارض، وتطلبوا معايشكم."},{"id":"2903","s":25,"a":48,"at":"وهو الذي ارسل الرياح بشرا بين يدي رحمته وانزلنا من السماء ماء طهورا","dt":"[48] وهو الذي ارسل الرياح التي تحمل السحاب، تبشر الناس بالمطر رحمه منه، وانزلنا من السماء ماء يتطهر به؛"},{"id":"2904","s":25,"a":49,"at":"لنحيي به بلده ميتا ونسقيه مما خلقنا انعاما واناسي كثيرا","dt":"[49] لنخرج به النبات في مكان لا نبات فيه، فيحيا البلد الجدب بعد موات، ونسقي ذلك الماء من خلقنا كثيرا من الانعام والناس."},{"id":"2905","s":25,"a":50,"at":"ولقد صرفناه بينهم ليذكروا فابى اكثر الناس الا كفورا","dt":"[50] ولقد انزلنا المطر على ارض دون اخرى؛ ليذكر الذين انزلنا عليهم المطر نعمه الله عليهم، فيشكروا له، وليذكر الذين منعوا منه، فيسارعوا بالتوبه الى الله -جل وعلا- ليرحمهم ويسقيهم، فابى اكثر الناس الا جحودا لنعمنا عليهم، كقولهم: مطرنا بنوء كذا وكذا."},{"id":"2906","s":25,"a":51,"at":"ولو شئنا لبعثنا في كل قريه نذيرا","dt":"[51] ولو شئنا لبعثنا في كل قريه نذيرا، يدعوهم الى الله عز وجل، وينذرهم عذابه، ولكنا جعلناك -ايها الرسول- مبعوثا الى جميع اهل الارض، وامرناك ان تبلغهم هذا القران،"},{"id":"2907","s":25,"a":52,"at":"فلا تطع الكافرين وجاهدهم به جهادا كبيرا","dt":"[52] فلا تطع الكافرين في ترك شيء مما ارسلت به، بل ابذل جهدك في تبليغ الرساله، وجاهد الكافرين بهذا القران جهادا كبيرا، لا يخالطه فتور."},{"id":"2908","s":25,"a":53,"at":"وهو الذي مرج البحرين هذا عذب فرات وهذا ملح اجاج وجعل بينهما برزخا وحجرا محجورا","dt":"[53] والله هو الذي خلط البحرين: العذب السائغ الشراب، والملح الشديد الملوحه، وجعل بينهما حاجزا يمنع كل واحد منهما من افساد الاخر، ومانعا من ان يصل احدهما الى الاخر."},{"id":"2909","s":25,"a":54,"at":"وهو الذي خلق من الماء بشرا فجعله نسبا وصهرا وكان ربك قديرا","dt":"[54] وهو الذي خلق من مني الرجل والمراه ذريه ذكورا واناثا، فنشا من هذا قرابه النسب وقرابه المصاهره. وكان ربك قديرا على خلق ما يشاء."},{"id":"2910","s":25,"a":55,"at":"ويعبدون من دون الله ما لا ينفعهم ولا يضرهم وكان الكافر على ربه ظهيرا","dt":"[55] ومع كل هذه الدلائل على قدره الله وانعامه على خلقه يعبد الكفار من دون الله ما لا ينفعهم ان عبدوه، ولا يضرهم ان تركوا عبادته، وكان الكافر عونا للشيطان على ربه بالشرك في عباده الله، مظاهرا له على معصيته."},{"id":"2911","s":25,"a":56,"at":"وما ارسلناك الا مبشرا ونذيرا","dt":"[56] وما ارسلناك -ايها الرسول- الا مبشرا للمؤمنين بالجنه ومنذرا للكافرين بالنار."},{"id":"2912","s":25,"a":57,"at":"قل ما اسالكم عليه من اجر الا من شاء ان يتخذ الى ربه سبيلا","dt":"[57] قل لهم: لا اطلب منكم على تبليغ الرساله اي اجر، لكن من اراد ان يهتدي ويسلك سبيل الحق الى ربه وينفق في مرضاته، فلست اجبركم عليه، وانما هو خير لانفسكم."},{"id":"2913","s":25,"a":58,"at":"وتوكل على الحي الذي لا يموت وسبح بحمده وكفى به بذنوب عباده خبيرا","dt":"[58] وتوكل على الله الذي له جميع معاني الحياه الكامله كما يليق بجلاله، الذي لا يموت، ونزهه عن صفات النقصان. وكفى بالله خبيرا بذنوب خلقه، لا يخفى عليه شيء منها، وسيحاسبهم عليها ويجازيهم بها."},{"id":"2914","s":25,"a":59,"at":"الذي خلق السموات والارض وما بينهما في سته ايام ثم استوى على العرش الرحمن فاسال به خبيرا","dt":"[59] الذي خلق السموات والارض وما بينهما في سته ايام، ثم استوى على العرش -اي: علا وارتفع- استواء يليق بجلاله، هو الرحمن، فاسال -ايها النبي- به خبيرا، يعني بذلك سبحانه نفسه الكريمه، فهو الذي يعلم صفاته وعظمته وجلاله. ولا احد من البشر اعلم بالله ولا اخبر به من عبده ورسوله محمد -صلى الله عليه وسلم-."},{"id":"2915","s":25,"a":60,"at":"واذا قيل لهم اسجدوا للرحمن قالوا وما الرحمن انسجد لما تامرنا وزادهم نفورا","dt":"[60] واذا قيل للكافرين: اسجدوا للرحمن واعبدوه قالوا: ما نعرف الرحمن، انسجد لما تامرنا بالسجود له طاعه لامرك؟ وزادهم دعاؤهم الى السجود للرحمن بعدا عن الايمان ونفورا منه."},{"id":"2916","s":25,"a":61,"at":"تبارك الذي جعل في السماء بروجا وجعل فيها سراجا وقمرا منيرا","dt":"[61] عظمت بركات الرحمن وكثر خيره، الذي جعل في السماء النجوم الكبار بمنازلها، وجعل فيها شمسا تضيء وقمرا ينير."},{"id":"2917","s":25,"a":62,"at":"وهو الذي جعل الليل والنهار خلفه لمن اراد ان يذكر او اراد شكورا","dt":"[62] وهو الذي جعل الليل والنهار متعاقبين يخلف احدهما الاخر لمن اراد ان يعتبر بما في ذلك ايمانا بالمدبر الخالق، او اراد ان يشكر لله تعالى على نعمه والائه."},{"id":"2918","s":25,"a":63,"at":"وعباد الرحمن الذين يمشون على الارض هونا واذا خاطبهم الجاهلون قالوا سلاما","dt":"[63] وعباد الرحمن الصالحون يمشون على الارض بسكينه متواضعين، واذا خاطبهم الجهله السفهاء بالاذى اجابوهم بالمعروف من القول، وخاطبوهم خطابا يسلمون فيه من الاثم، ومن مقابله الجاهل بجهله."},{"id":"2919","s":25,"a":64,"at":"والذين يبيتون لربهم سجدا وقياما","dt":"[64] والذين يكثرون من صلاه الليل مخلصين فيها لربهم، متذللين له بالسجود والقيام."},{"id":"2920","s":25,"a":65,"at":"والذين يقولون ربنا اصرف عنا عذاب جهنم ان عذابها كان غراما","dt":"[65] والذين هم مع اجتهادهم في العباده يخافون الله فيدعونه ان ينجيهم من عذاب جهنم، ان عذابها يلازم صاحبه."},{"id":"2921","s":25,"a":66,"at":"انها ساءت مستقرا ومقاما","dt":"[66] ان جهنم شر قرار واقامه."},{"id":"2922","s":25,"a":67,"at":"والذين اذا انفقوا لم يسرفوا ولم يقتروا وكان بين ذلك قواما","dt":"[67] والذين اذا انفقوا من اموالهم لم يتجاوزوا الحد في العطاء، ولم يضيقوا في النفقه، وكان انفاقهم وسطا بين التبذير والتضييق."},{"id":"2923","s":25,"a":68,"at":"والذين لا يدعون مع الله الها اخر ولا يقتلون النفس التي حرم الله الا بالحق ولا يزنون ومن يفعل ذلك يلق اثاما","dt":"[68] والذين يوحدون الله، ولا يدعون ولا يعبدون الها غيره، ولا يقتلون النفس التي حرم الله قتلها الا بما يحق قتلها به: من كفر بعد ايمان، او زنى بعد زواج، او قتل نفس عدوانا، ولا يزنون، بل يحفظون فروجهم الا على ازواجهم او ما ملكت ايمانهم، ومن يفعل شيئا من هذه الكبائر يلق في الاخره عقابا."},{"id":"2924","s":25,"a":69,"at":"يضاعف له العذاب يوم القيامه ويخلد فيه مهانا","dt":"[69] يضاعف له العذاب يوم القيامه، ويخلد فيه ذليلا حقيرا. (والوعيد بالخلود لمن فعلها كلها، او لمن اشرك بالله)."},{"id":"2925","s":25,"a":70,"at":"الا من تاب وامن وعمل عملا صالحا فاولئك يبدل الله سيئاتهم حسنات وكان الله غفورا رحيما","dt":"[70] لكن من تاب من هذه الذنوب توبه نصوحا وامن ايمانا جازما مقرونا بالعمل الصالح، فاولئك يمحو الله عنهم سيئاتهم ويجعل مكانها حسنات؛ بسبب توبتهم وندمهم. وكان الله غفورا لمن تاب، رحيما بعباده حيث دعاهم الى التوبه بعد مبارزته باكبر المعاصي."},{"id":"2926","s":25,"a":71,"at":"ومن تاب وعمل صالحا فانه يتوب الى الله متابا","dt":"[71] ومن تاب عما ارتكب من الذنوب، وعمل عملا صالحا فانه بذلك يرجع الى الله رجوعا صحيحا، فيقبل الله توبته ويكفر ذنوبه."},{"id":"2927","s":25,"a":72,"at":"والذين لا يشهدون الزور واذا مروا باللغو مروا كراما","dt":"[72] والذين لا يشهدون بالكذب ولا يحضرون مجالسه، واذا مروا باهل الباطل واللغو من غير قصد مروا معرضين منكرين يتنزهون عنه، ولا يرضونه لغيرهم."},{"id":"2928","s":25,"a":73,"at":"والذين اذا ذكروا بايات ربهم لم يخروا عليها صما وعميانا","dt":"[73] والذين اذا وعظوا بايات القران ودلائل وحدانيه الله لم يتغافلوا عنها، كانهم صم لم يسمعوها، وعمي لم يبصروها، بل وعتها قلوبهم، وتفتحت لها بصائرهم، فخروا لله ساجدين مطيعين."},{"id":"2929","s":25,"a":74,"at":"والذين يقولون ربنا هب لنا من ازواجنا وذرياتنا قره اعين واجعلنا للمتقين اماما","dt":"[74] والذين يسالون الله تعالى قائلين: ربنا هب لنا من ازواجنا وذرياتنا ما تقر به اعيننا، وفيه انسنا وسرورنا، واجعلنا قدوه يقتدي بنا المتقون في الخير."},{"id":"2930","s":25,"a":75,"at":"اولئك يجزون الغرفه بما صبروا ويلقون فيها تحيه وسلاما","dt":"[75] اولئك الذين اتصفوا بالصفات السابقه من عباد الرحمن، يثابون اعلى منازل الجنه؛ برحمه الله وبسبب صبرهم على الطاعات، وسيلقون في الجنه التحيه والتسليم من الملائكه، والحياه الطيبه والسلامه من الافات،"},{"id":"2931","s":25,"a":76,"at":"خالدين فيها حسنت مستقرا ومقاما","dt":"[76] خالدين فيها ابدا من غير موت، حسنت مستقرا يقرون فيه ومقاما يقيمون به، لا يبغون عنها تحولا."},{"id":"2932","s":25,"a":77,"at":"قل ما يعبا بكم ربي لولا دعاؤكم فقد كذبتم فسوف يكون لزاما","dt":"[77] اخبر الله تعالى انه لا يبالي ولا يعبا بالناس، لولا دعاؤهم اياه دعاء العباده ودعاء المساله، فقد كذبتم -ايها الكافرون- فسوف يكون تكذيبكم مفضيا الى عذاب يلزمكم لزوم الغريم لغريمه، ويهلككم في الدنيا والاخره."},{"id":"2933","s":26,"a":1,"at":"طسم","dt":"[1] طسم سبق الكلام على الحروف المقطعه في اول سوره البقره."},{"id":"2934","s":26,"a":2,"at":"تلك ايات الكتاب المبين","dt":"[2] هذه ايات القران الموضح لكل شيء الفاصل بين الهدى والضلال."},{"id":"2935","s":26,"a":3,"at":"لعلك باخع نفسك الا يكونوا مؤمنين","dt":"[3] لعلك -ايها الرسول- من شده حرصك على هدايتهم مهلك نفسك؛ لانهم لم يصدقوا بك ولم يعملوا بهديك، فلا تفعل ذلك."},{"id":"2936","s":26,"a":4,"at":"ان نشا ننزل عليهم من السماء ايه فظلت اعناقهم لها خاضعين","dt":"[4] ان نشا ننزل على المكذبين من قومك من السماء معجزه مخوفه لهم تلجئهم الى الايمان، فتصير اعناقهم خاضعه ذليله، ولكننا لم نشا ذلك؛ فان الايمان النافع هو الايمان بالغيب اختيارا."},{"id":"2937","s":26,"a":5,"at":"وما ياتيهم من ذكر من الرحمن محدث الا كانوا عنه معرضين","dt":"[5] وما يجيء هؤلاء المشركين المكذبين من ذكر من الرحمن محدث انزاله، شيئا بعد شيء، يامرهم وينهاهم، ويذكرهم بالدين الحق الا اعرضوا عنه ولم يقبلوه."},{"id":"2938","s":26,"a":6,"at":"فقد كذبوا فسياتيهم انباء ما كانوا به يستهزئون","dt":"[6] فقد كذبوا بالقران واستهزؤوا به، فسياتيهم اخبار الامر الذي كانوا يستهزئون به ويسخرون منه، وسيحل بهم العذاب جزاء تمردهم على ربهم."},{"id":"2939","s":26,"a":7,"at":"او لم يروا الى الارض كم انبتنا فيها من كل زوج كريم","dt":"[7] اكذبوا ولم ينظروا الى الارض التي انبتنا فيها من كل نوع حسن نافع من النبات، لا يقدر على انباته الا رب العالمين؟"},{"id":"2940","s":26,"a":8,"at":"ان في ذلك لايه وما كان اكثرهم مؤمنين","dt":"[8] ان في اخراج النبات من الارض لدلاله واضحه على كمال قدره الله، وما كان اكثر القوم مؤمنين."},{"id":"2941","s":26,"a":9,"at":"وان ربك لهو العزيز الرحيم","dt":"[9] . وان ربك لهو العزيز على كل مخلوق، الرحيم الذي وسعت رحمته كل شيء."},{"id":"2942","s":26,"a":10,"at":"واذ نادى ربك موسى ان ائت القوم الظالمين","dt":"[10] واذكر -ايها الرسول- لقومك اذ نادى ربك موسى: ان ائت القوم الظالمين،"},{"id":"2943","s":26,"a":11,"at":"قوم فرعون الا يتقون","dt":"[11] قوم فرعون، وقل لهم: الا يخافون عقاب الله تعالى، ويتركون ما هم عليه من الكفر والضلال؟"},{"id":"2944","s":26,"a":12,"at":"قال رب اني اخاف ان يكذبون","dt":"[12] قال موسى: رب اني اخاف ان يكذبوني في الرساله،"},{"id":"2945","s":26,"a":13,"at":"ويضيق صدري ولا ينطلق لساني فارسل الى هارون","dt":"[13] ويملا صدري الغم لتكذيبهم اياي، ولا ينطلق لساني بالدعوه فارسل جبريل بالوحي الى اخي هارون؛ ليعاونني ويصدقني فيما اقول، ويبين لهم ما اخاطبهم به، فهو افصح مني نطقا."},{"id":"2946","s":26,"a":14,"at":"ولهم علي ذنب فاخاف ان يقتلون","dt":"[14] ولهم علي ذنب في قتل رجل منهم، وهو القبطي، فاخاف ان يقتلوني به."},{"id":"2947","s":26,"a":15,"at":"قال كلا فاذهبا باياتنا انا معكم مستمعون","dt":"[15] قال الله لموسى: كلا لن يقتلوك، وقد اجبت طلبك في هارون، فاذهبا بالمعجزات الداله على صدقكما، انا معكم بالعلم والحفظ والنصره مستمعون."},{"id":"2948","s":26,"a":16,"at":"فاتيا فرعون فقولا انا رسول رب العالمين","dt":"[16] . فاتيا فرعون فقولا له: انا مرسلان اليك والى قومك من رب العالمين:"},{"id":"2949","s":26,"a":17,"at":"ان ارسل معنا بني اسرائيل","dt":"[17] ان اترك بني اسرائيل؛ ليذهبوا معنا."},{"id":"2950","s":26,"a":18,"at":"قال الم نربك فينا وليدا ولبثت فينا من عمرك سنين","dt":"[18] قال فرعون لموسى -ممتنا عليه-: الم نربك في منازلنا صغيرا، ومكثت في رعايتنا سنين من عمرك،"},{"id":"2951","s":26,"a":19,"at":"وفعلت فعلتك التي فعلت وانت من الكافرين","dt":"[19] وارتكبت جنايه بقتلك رجلا من قومي حين ضربته ودفعته، وانت من الجاحدين نعمتي المنكرين ربوبيتي؟"},{"id":"2952","s":26,"a":20,"at":"قال فعلتها اذا وانا من الضالين","dt":"[20] قال موسى مجيبا لفرعون: فعلت ما ذكرت قبل ان يوحي الله الي ويبعثني رسولا،"},{"id":"2953","s":26,"a":21,"at":"ففررت منكم لما خفتكم فوهب لي ربي حكما وجعلني من المرسلين","dt":"[21] فخرجت من بينكم فارا الى «مدين»، لما خفت ان تقتلوني بما فعلت من غير عمد، فوهب لي ربي تفضلا منه النبوه والعلم، وجعلني من المرسلين."},{"id":"2954","s":26,"a":22,"at":"وتلك نعمه تمنها علي ان عبدت بني اسرائيل","dt":"[22] اوتلك التربيه في بيتك تعدها نعمه منك علي، وقد جعلت بني اسرائيل عبيدا تذبح ابناءهم وتستبقي نساءهم للخدمه والامتهان؟"},{"id":"2955","s":26,"a":23,"at":"قال فرعون وما رب العالمين","dt":"[23] قال فرعون لموسى: وما رب العالمين الذي تدعي انك رسوله؟"},{"id":"2956","s":26,"a":24,"at":"قال رب السموات والارض وما بينهما ان كنتم موقنين","dt":"[24] قال موسى: هو مالك ومدبر السموات والارض وما بينهما، ان كنتم موقنين بذلك، فامنوا."},{"id":"2957","s":26,"a":25,"at":"قال لمن حوله الا تستمعون","dt":"[25] قال فرعون لمن حوله من اشراف قومه: الا تسمعون مقاله موسى العجيبه بوجود رب سواي؟"},{"id":"2958","s":26,"a":26,"at":"قال ربكم ورب ابائكم الاولين","dt":"[26] قال موسى: الرب الذي ادعوكم اليه هو الذي خلقكم وخلق اباءكم الاولين، فكيف تعبدون من هو مخلوق مثلكم، وله اباء قد فنوا كابائكم؟"},{"id":"2959","s":26,"a":27,"at":"قال ان رسولكم الذي ارسل اليكم لمجنون","dt":"[27] قال فرعون لخاصته يستثير غضبهم؛ لتكذيب موسى اياه: ان رسولكم الذي ارسل اليكم لمجنون، يتكلم كلاما لا يعقل"},{"id":"2960","s":26,"a":28,"at":"قال رب المشرق والمغرب وما بينهما ان كنتم تعقلون","dt":"[28] قال موسى: رب المشرق والمغرب وما بينهما وما يكون فيهما من نور وظلمه، وهذا يستوجب الايمان به وحده ان كنتم من اهل العقل والتدبر"},{"id":"2961","s":26,"a":29,"at":"قال لئن اتخذت الها غيري لاجعلنك من المسجونين","dt":"[29] قال فرعون لموسى مهددا له: لئن اتخذت الها غيري لاسجننك مع من سجنت."},{"id":"2962","s":26,"a":30,"at":"قال او لو جئتك بشيء مبين","dt":"[30] قال موسى: اتجعلني من المسجونين، ولو جئتك ببرهان قاطع يتبين منه صدقي؟"},{"id":"2963","s":26,"a":31,"at":"قال فات به ان كنت من الصادقين","dt":"[31] قال فرعون: فات به ان كنت من الصادقين في دعواك."},{"id":"2964","s":26,"a":32,"at":"فالقى عصاه فاذا هي ثعبان مبين","dt":"[32] فالقى موسى عصاه فتحولت ثعبانا حقيقيا، ليس تمويها كما يفعل السحره،"},{"id":"2965","s":26,"a":33,"at":"ونزع يده فاذا هي بيضاء للناظرين","dt":"[33] واخرج يده من فتحه قميصه المفتوحه الى الصدر، او من تحت ابطه فاذا هي بيضاء كالثلج من غير برص، تبهر الناظرين."},{"id":"2966","s":26,"a":34,"at":"قال للملا حوله ان هذا لساحر عليم","dt":"[34] قال فرعون لاشراف قومه خشيه ان يؤمنوا: ان موسى لساحر ماهر،"},{"id":"2967","s":26,"a":35,"at":"يريد ان يخرجكم من ارضكم بسحره فماذا تامرون","dt":"[35] يريد ان يخرجكم بسحره من ارضكم، فاي شيء تشيرون به في شانه اتبع رايكم فيه؟"},{"id":"2968","s":26,"a":36,"at":"قالوا ارجه واخاه وابعث في المدائن حاشرين","dt":"[36] قال له قومه: اخر امر موسى وهارون، وارسل في المدائن جندا جامعين للسحره،"},{"id":"2969","s":26,"a":37,"at":"ياتوك بكل سحار عليم","dt":"[37] ياتوك بكل من اجاد السحر، وتفوق في معرفته."},{"id":"2970","s":26,"a":38,"at":"فجمع السحره لميقات يوم معلوم","dt":"[38] فجمع السحره، وحدد لهم وقت معلوم، هو وقت الضحى من يوم الزينه الذي يتفرغون فيه من اشغالهم، ويجتمعون ويتزينون؛ وذلك للاجتماع بموسى"},{"id":"2971","s":26,"a":39,"at":"وقيل للناس هل انتم مجتمعون","dt":"[39] وحث الناس على الاجتماع؛ املا في ان تكون الغلبه للسحره."},{"id":"2972","s":26,"a":40,"at":"لعلنا نتبع السحره ان كانوا هم الغالبين","dt":"[40] اننا نطمع ان تكون الغلبه للسحره، فنثبت على ديننا."},{"id":"2973","s":26,"a":41,"at":"فلما جاء السحره قالوا لفرعون ائن لنا لاجرا ان كنا نحن الغالبين","dt":"[41] فلما جاء السحره فرعون قالوا له: اان لنا لاجرا من مال او جاه، ان كنا نحن الغالبين لموسى؟"},{"id":"2974","s":26,"a":42,"at":"قال نعم وانكم اذا لمن المقربين","dt":"[42] قال فرعون: نعم لكم عندي ما طلبتم من اجر، وانكم حينئذ لمن المقربين لدي."},{"id":"2975","s":26,"a":43,"at":"قال لهم موسى القوا ما انتم ملقون","dt":"[43] قال موسى للسحره مريدا ابطال سحرهم واظهار ان ما جاء به ليس سحرا: القوا ما تريدون القاءه من السحر."},{"id":"2976","s":26,"a":44,"at":"فالقوا حبالهم وعصيهم وقالوا بعزه فرعون انا لنحن الغالبون","dt":"[44] فالقوا حبالهم وعصيهم، وخيل للناس انها حيات تسعى، واقسموا بعزه فرعون قائلين: اننا لنحن الغالبون."},{"id":"2977","s":26,"a":45,"at":"فالقى موسى عصاه فاذا هي تلقف ما يافكون","dt":"[45] فالقى موسى عصاه، فاذا هي حيه عظيمه، تبتلع ما صدر منهم من افك وتزوير."},{"id":"2978","s":26,"a":46,"at":"فالقي السحره ساجدين","dt":"[46] فلما شاهدوا ذلك، وعلموا انه ليس من تمويه السحره، امنوا بالله وسجدوا له،"},{"id":"2979","s":26,"a":47,"at":"قالوا امنا برب العالمين","dt":"[47] وقالوا: امنا برب العالمين"},{"id":"2980","s":26,"a":48,"at":"رب موسى وهارون","dt":"[48] رب موسى وهارون."},{"id":"2981","s":26,"a":49,"at":"قال امنتم له قبل ان اذن لكم انه لكبيركم الذي علمكم السحر فلسوف تعلمون لاقطعن ايديكم وارجلكم من خلاف ولاصلبنكم اجمعين","dt":"[49] قال فرعون للسحره مستنكرا: امنتم لموسى بغير اذن مني، وقال موهما ان فعل موسى سحر: انه لكبيركم الذي علمكم السحر، فلسوف تعلمون ما ينزل بكم من عقاب: لاقطعن ايديكم وارجلكم من خلاف: بقطع اليد اليمنى والرجل اليسرى او عكس ذلك، ولاصلبنكم اجمعين."},{"id":"2982","s":26,"a":50,"at":"قالوا لا ضير انا الى ربنا منقلبون","dt":"[50] قال السحره لفرعون: لا ضرر علينا فيما يلحقنا من عقاب الدنيا، انا راجعون الى ربنا فيعطينا النعيم المقيم."},{"id":"2983","s":26,"a":51,"at":"انا نطمع ان يغفر لنا ربنا خطايانا ان كنا اول المؤمنين","dt":"[51]. انا نرجو ان يغفر لنا ربنا خطايانا من الشرك وغيره؛ لكوننا اول المؤمنين في قومك."},{"id":"2984","s":26,"a":52,"at":"واوحينا الى موسى ان اسر بعبادي انكم متبعون","dt":"[52] واوحى الله الى موسى عليه السلام: ان سر ليلا بمن امن من بني اسرائيل؛ لان فرعون وجنوده متبعوكم حتى لا يدركوكم قبل وصولكم الى البحر."},{"id":"2985","s":26,"a":53,"at":"فارسل فرعون في المدائن حاشرين","dt":"[53] فارسل فرعون جنده -حين بلغه مسير بني اسرائيل- يجمعون جيشه من مدائن مملكته."},{"id":"2986","s":26,"a":54,"at":"ان هؤلاء لشرذمه قليلون","dt":"[54] قال فرعون: ان بني اسرائيل الذين فروا مع موسى لطائفه حقيره قليله العدد،"},{"id":"2987","s":26,"a":55,"at":"وانهم لنا لغائظون","dt":"[55] وانهم لمالئون صدورنا غيظا؛ حيث خالفوا ديننا، وخرجوا بغير اذننا،"},{"id":"2988","s":26,"a":56,"at":"وانا لجميع حاذرون","dt":"[56] وانا لجميع متيقظون مستعدون لهم."},{"id":"2989","s":26,"a":57,"at":"فاخرجناهم من جنات وعيون","dt":"[57] فاخرج الله فرعون وقومه من ارض «مصر» ذات البساتين وعيون الماء"},{"id":"2990","s":26,"a":58,"at":"وكنوز ومقام كريم","dt":"[58] وخزائن المال والمنازل الحسان."},{"id":"2991","s":26,"a":59,"at":"كذلك واورثناها بني اسرائيل","dt":"[59] وكما اخرجناهم، جعلنا هذه الديار من بعدهم لبني اسرائيل."},{"id":"2992","s":26,"a":60,"at":"فاتبعوهم مشرقين","dt":"[60] فلحق فرعون وجنده موسى ومن معه وقت شروق الشمس."},{"id":"2993","s":26,"a":61,"at":"فلما تراءى الجمعان قال اصحاب موسى انا لمدركون","dt":"[61] فلما راى كل واحد من الفريقين الاخر قال اصحاب موسى: ان جمع فرعون مدركنا ومهلكنا."},{"id":"2994","s":26,"a":62,"at":"قال كلا ان معي ربي سيهدين","dt":"[62] قال موسى لهم: كلا ليس الامر كما ذكرتم فلن تدركوا؛ ان معي ربي بالنصر، سيهديني لما فيه نجاتي ونجاتكم."},{"id":"2995","s":26,"a":63,"at":"فاوحينا الى موسى ان اضرب بعصاك البحر فانفلق فكان كل فرق كالطود العظيم","dt":"[63] فاوحينا الى موسى ان اضرب بعصاك البحر، فضرب، فانفلق البحر الى اثني عشر طريقا بعدد قبائل بني اسرائيل، فكانت كل قطعه انفصلت من البحر كالجبل العظيم."},{"id":"2996","s":26,"a":64,"at":"وازلفنا ثم الاخرين","dt":"[64] وقربنا هناك فرعون وقومه حتى دخلوا البحر،"},{"id":"2997","s":26,"a":65,"at":"وانجينا موسى ومن معه اجمعين","dt":"[65] وانجينا موسى ومن معه اجمعين. فاستمر البحر على انفلاقه حتى عبروا الى البر،"},{"id":"2998","s":26,"a":66,"at":"ثم اغرقنا الاخرين","dt":"[66] ثم اغرقنا فرعون ومن معه باطباق البحر عليهم بعد ان دخلوا فيه متبعين موسى وقومه."},{"id":"2999","s":26,"a":67,"at":"ان في ذلك لايه وما كان اكثرهم مؤمنين","dt":"[67] ان في ذلك الذي حدث لعبره عجيبه داله على قدره الله، وما صار اكثر اتباع فرعون مؤمنين مع هذه العلامه الباهره."},{"id":"3000","s":26,"a":68,"at":"وان ربك لهو العزيز الرحيم","dt":"[68] وان ربك لهو العزيز الرحيم، بعزته اهلك الكافرين المكذبين، وبرحمته نجى موسى ومن معه اجمعين."},{"id":"3001","s":26,"a":69,"at":"واتل عليهم نبا ابراهيم","dt":"[69] واقصص على الكافرين -ايها الرسول- خبر ابراهيم"},{"id":"3002","s":26,"a":70,"at":"اذ قال لابيه وقومه ما تعبدون","dt":"[70] حين قال لابيه وقومه: اي شيء تعبدونه؟"},{"id":"3003","s":26,"a":71,"at":"قالوا نعبد اصناما فنظل لها عاكفين","dt":"[71] قالوا: نعبد اصناما، فنعكف على عبادتها."},{"id":"3004","s":26,"a":72,"at":"قال هل يسمعونكم اذ تدعون","dt":"[72] قال ابراهيم منبها على فساد مذهبهم: هل يسمعون دعاءكم اذ تدعونهم،"},{"id":"3005","s":26,"a":73,"at":"او ينفعونكم او يضرون","dt":"[73] او يقدمون لكم نفعا اذا عبدتموهم، او يصيبونكم بضر اذا تركتم عبادتهم؟"},{"id":"3006","s":26,"a":74,"at":"قالوا بل وجدنا اباءنا كذلك يفعلون","dt":"[74] قالوا: لا يكون منهم شيء من ذلك، ولكننا وجدنا اباءنا يعبدونهم، فقلدناهم فيما كانوا يفعلون."},{"id":"3007","s":26,"a":75,"at":"قال افرايتم ما كنتم تعبدون","dt":"[75] قال ابراهيم: افابصرتم بتدبر ما كنتم تعبدون من الاصنام التي لا تسمع ولا تنفع ولا تضر،"},{"id":"3008","s":26,"a":76,"at":"انتم واباؤكم الاقدمون","dt":"[76] انتم واباؤكم الاقدمون من قبلكم؟"},{"id":"3009","s":26,"a":77,"at":"فانهم عدو لي الا رب العالمين","dt":"[77] فان ما تعبدونهم من دون الله اعداء لي، لكن رب العالمين ومالك امرهم هو وحده الذي اعبده."},{"id":"3010","s":26,"a":78,"at":"الذي خلقني فهو يهدين","dt":"[78] هو الذي خلقني في احسن صوره فهو يرشدني الى مصالح الدنيا والاخره،"},{"id":"3011","s":26,"a":79,"at":"والذي هو يطعمني ويسقين","dt":"[79] وهو الذي ينعم علي بالطعام والشراب،"},{"id":"3012","s":26,"a":80,"at":"واذا مرضت فهو يشفين","dt":"[80] واذا اصابني مرض فهو الذي يشفيني ويعافيني منه،"},{"id":"3013","s":26,"a":81,"at":"والذي يميتني ثم يحيين","dt":"[81] وهو الذي يميتني في الدنيا بقبض روحي، ثم يحييني يوم القيامه، لا يقدر على ذلك احد سواه،"},{"id":"3014","s":26,"a":82,"at":"والذي اطمع ان يغفر لي خطيئتي يوم الدين","dt":"[82] والذي اطمع ان يتجاوز عن ذنبي يوم الجزاء."},{"id":"3015","s":26,"a":83,"at":"رب هب لي حكما والحقني بالصالحين","dt":"[83] قال ابراهيم داعيا ربه: رب امنحني العلم والفهم، والحقني بالصالحين، واجمع بيني وبينهم في الجنه."},{"id":"3016","s":26,"a":84,"at":"واجعل لي لسان صدق في الاخرين","dt":"[84] واجعل لي ثناء حسنا وذكرا جميلا في الذين ياتون بعدي الى يوم القيامه."},{"id":"3017","s":26,"a":85,"at":"واجعلني من ورثه جنه النعيم","dt":"[85] واجعلني من عبادك الذين تورثهم نعيم الجنه."},{"id":"3018","s":26,"a":86,"at":"واغفر لابي انه كان من الضالين","dt":"[86] هذا دعاء من ابراهيم -عليه السلام- ان ينقذ الله اباه من الضلال الى الهدى، فيغفر له ويتجاوز عنه، كما وعد ابراهيم اباه بالدعاء له، فلما تبين له انه مستمر في الكفر والشرك الى ان يموت تبرا منه."},{"id":"3019","s":26,"a":87,"at":"ولا تخزني يوم يبعثون","dt":"[87] ولا تلحق بي الذل، يوم يخرج الناس من القبور للحساب والجزاء،"},{"id":"3020","s":26,"a":88,"at":"يوم لا ينفع مال ولا بنون","dt":"[88] يوم لا ينفع المال والبنون احدا من العباد،"},{"id":"3021","s":26,"a":89,"at":"الا من اتى الله بقلب سليم","dt":"[89] الا من اتى الله بقلب سليم من الكفر والنفاق والرذيله."},{"id":"3022","s":26,"a":90,"at":"وازلفت الجنه للمتقين","dt":"[90] وقربت الجنه للذين اجتنبوا الكفر والمعاصي، واقبلوا على الله بالطاعه."},{"id":"3023","s":26,"a":91,"at":"وبرزت الجحيم للغاوين","dt":"[91] واظهرت النار للكافرين الذين ضلوا عن الهدى، وتجرؤوا على محارم الله وكذبوا رسله."},{"id":"3024","s":26,"a":92,"at":"وقيل لهم اين ما كنتم تعبدون","dt":"[92] وقيل لهم توبيخا: اين الهتكم التي كنتم تعبدونها"},{"id":"3025","s":26,"a":93,"at":"من دون الله هل ينصرونكم او ينتصرون","dt":"[93] من دون الله، وتزعمون انها تشفع لكم اليوم؟ هل ينصرونكم، فيدفعون العذاب عنكم، او ينتصرون بدفع العذاب عن انفسهم؟ لا شيء من ذلك."},{"id":"3026","s":26,"a":94,"at":"فكبكبوا فيها هم والغاوون","dt":"[94] فجمعوا والقوا في جهنم على رؤوسهم مره بعد مره الى ان استقروا فيها، هم والذين اضلوهم،"},{"id":"3027","s":26,"a":95,"at":"وجنود ابليس اجمعون","dt":"[95] واعوان ابليس الذين زينوا لهم الشر، لم يفلت منهم احد."},{"id":"3028","s":26,"a":96,"at":"قالوا وهم فيها يختصمون","dt":"[96] قالوا معترفين بخطئهم، وهم يتنازعون في جهنم مع من اضلوهم:"},{"id":"3029","s":26,"a":97,"at":"تالله ان كنا لفي ضلال مبين","dt":"[97] تالله اننا كنا في الدنيا في ضلال واضح لا خفاء فيه؛"},{"id":"3030","s":26,"a":98,"at":"اذ نسويكم برب العالمين","dt":"[98] اذ نسويكم برب العالمين المستحق للعباده وحده."},{"id":"3031","s":26,"a":99,"at":"وما اضلنا الا المجرمون","dt":"99] وما اوقعنا في هذا المصير السيئ الا المجرمون الذين دعونا الى عباده غير الله فاتبعناهم."},{"id":"3032","s":26,"a":100,"at":"فما لنا من شافعين","dt":"[100] فلا احد يشفع لنا، ويخلصنا من العذاب،"},{"id":"3033","s":26,"a":101,"at":"ولا صديق حميم","dt":"[101] ولا من يصدق في مودتنا ويشفق علينا"},{"id":"3034","s":26,"a":102,"at":"فلو ان لنا كره فنكون من المؤمنين","dt":"[102] فليت لنا رجعه الى الدنيا، فنصير من جمله المؤمنين الناجين."},{"id":"3035","s":26,"a":103,"at":"ان في ذلك لايه وما كان اكثرهم مؤمنين","dt":"[103] ان في نبا ابراهيم السابق لعبره لمن يعتبر، وما صار اكثر الذين سمعوا هذا النبا مؤمنين."},{"id":"3036","s":26,"a":104,"at":"وان ربك لهو العزيز الرحيم","dt":"[104] وان ربك لهو العزيز القادر على الانتقام من المكذبين، الرحيم بعباده المؤمنين."},{"id":"3037","s":26,"a":105,"at":"كذبت قوم نوح المرسلين","dt":"[105] كذبت قوم نوح رساله نبيهم، فكانوا بهذا مكذبين لجميع الرسل؛ لان كل رسول يامر بتصديق جميع الرسل."},{"id":"3038","s":26,"a":106,"at":"اذ قال لهم اخوهم نوح الا تتقون","dt":"[106] اذ قال لهم اخوهم نوح: الا تخشون الله بترك عباده غيره؟"},{"id":"3039","s":26,"a":107,"at":"اني لكم رسول امين","dt":"[107] اني لكم رسول امين فيما ابلغكم،"},{"id":"3040","s":26,"a":108,"at":"فاتقوا الله واطيعون","dt":"[108] فاجعلوا الايمان وقايه لكم من عذاب الله واطيعوني فيما امركم به من عبادته وحده."},{"id":"3041","s":26,"a":109,"at":"وما اسالكم عليه من اجر ان اجري الا على رب العالمين","dt":"[109]. وما اطلب منكم اجرا على تبليغ الرساله، ما اجري الا على رب العالمين المتصرف في خلقه،"},{"id":"3042","s":26,"a":110,"at":"فاتقوا الله واطيعون","dt":"[110] فاحذروا عقابه، واطيعوني بامتثال اوامره، واجتناب نواهيه."},{"id":"3043","s":26,"a":111,"at":"قالوا انؤمن لك واتبعك الارذلون","dt":"[111] قال له قومه: كيف نصدقك ونتبعك، والذين اتبعوك اراذل الناس واسافلهم؟"},{"id":"3044","s":26,"a":112,"at":"قال وما علمي بما كانوا يعملون","dt":"[112] فاجابهم نوح -عليه السلام- بقوله: لست مكلفا بمعرفه اعمالهم، انما كلفت ان ادعوهم الى الايمان. والاعتبار بالايمان، لا بالحسب والنسب والحرف والصنائع."},{"id":"3045","s":26,"a":113,"at":"ان حسابهم الا على ربي لو تشعرون","dt":"[113] ما حسابهم للجزاء على اعمالهم وبواطنهم الا على ربي المطلع على السرائر. لو كنتم تشعرون بذلك لما قلتم هذا الكلام."},{"id":"3046","s":26,"a":114,"at":"وما انا بطارد المؤمنين","dt":"[114] وما انا بطارد الذين يؤمنون بدعوتي، مهما تكن حالهم؛ تلبيه لرغبتكم كي تؤمنوا بي"},{"id":"3047","s":26,"a":115,"at":"ان انا الا نذير مبين","dt":"[115] ما انا الا نذير بين الانذار"},{"id":"3048","s":26,"a":116,"at":"قالوا لئن لم تنته يانوح لتكونن من المرجومين","dt":"[116] عدل قوم نوح عن المحاوره الى التهديد، فقالوا له: لئن لم ترجع -يا نوح- عن دعوتك لتكونن من المقتولين رميا بالحجاره."},{"id":"3049","s":26,"a":117,"at":"قال رب ان قومي كذبون","dt":"[117] فلما سمع نوح قولهم هذا دعا ربه بقوله: رب ان قومي اصروا على تكذيبي،"},{"id":"3050","s":26,"a":118,"at":"فافتح بيني وبينهم فتحا ونجني ومن معي من المؤمنين","dt":"[118] فاحكم بيني وبينهم حكما تهلك به من جحد توحيدك وكذب رسولك، ونجني ومن معي من المؤمنين مما تعذب به الكافرين."},{"id":"3051","s":26,"a":119,"at":"فانجيناه ومن معه في الفلك المشحون","dt":"[119] فانجيناه ومن معه في السفينه المملوءه بصنوف المخلوقات التي حملها معه."},{"id":"3052","s":26,"a":120,"at":"ثم اغرقنا بعد الباقين","dt":"[120] ثم اغرقنا -بعد انجاء نوح ومن معه- الباقين الذين لم يؤمنوا من قومه وردوا عليه النصيحه."},{"id":"3053","s":26,"a":121,"at":"ان في ذلك لايه وما كان اكثرهم مؤمنين","dt":"[121] ان في نبا نوح وما كان من انجاء المؤمنين واهلاك المكذبين لعلامه وعبره عظيمه لمن بعدهم، وما كان اكثر الذين سمعوا هذه القصه مؤمنين بالله وبرسوله وشرعه."},{"id":"3054","s":26,"a":122,"at":"وان ربك لهو العزيز الرحيم","dt":"[122] و ان ربك لهو العزيز في انتقامه ممن كفر به وخالف امره، الرحيم بعباده المؤمنين."},{"id":"3055","s":26,"a":123,"at":"كذبت عاد المرسلين","dt":"[123] كذبت قبيله عاد رسولهم هودا -عليه السلام- فكانوا بهذا مكذبين لجميع الرسل؛ لاتحاد دعوتهم في اصولها وغايتها."},{"id":"3056","s":26,"a":124,"at":"اذ قال لهم اخوهم هود الا تتقون","dt":"[124] اذ قال لهم اخوهم هود: الا تخشون الله فتخلصوا له العباده؟"},{"id":"3057","s":26,"a":125,"at":"اني لكم رسول امين","dt":"[125] اني مرسل اليكم لهدايتكم وارشادكم، حفيظ على رساله الله، ابلغها لكم كما امرني ربي،"},{"id":"3058","s":26,"a":126,"at":"فاتقوا الله واطيعون","dt":"[126] فخافوا عقاب الله واطيعوني فيما جئتكم به من عند الله."},{"id":"3059","s":26,"a":127,"at":"وما اسالكم عليه من اجر ان اجري الا على رب العالمين","dt":"[127] . وما اطلب منكم على ارشادكم الى التوحيد اي نوع من انواع الاجر، ما اجري الا على رب العالمين."},{"id":"3060","s":26,"a":128,"at":"اتبنون بكل ريع ايه تعبثون","dt":"[128] اتبنون بكل مكان مرتفع بناء عاليا تشرفون منه فتسخرون من الماره؟ وذلك عبث واسراف لا يعود عليكم بفائده في الدين او الدنيا،"},{"id":"3061","s":26,"a":129,"at":"وتتخذون مصانع لعلكم تخلدون","dt":"[129] وتتخذون قصورا منيعه وحصونا مشيده، كانكم تخلدون في الدنيا ولا تموتون،"},{"id":"3062","s":26,"a":130,"at":"واذا بطشتم بطشتم جبارين","dt":"[130] واذا بطشتم باحد من الخلق قتلا او ضربا، فعلتم ذلك قاهرين ظالمين."},{"id":"3063","s":26,"a":131,"at":"فاتقوا الله واطيعون","dt":"[131] فخافوا الله، وامتثلوا ما ادعوكم اليه فانه انفع لكم،"},{"id":"3064","s":26,"a":132,"at":"واتقوا الذي امدكم بما تعلمون","dt":"[132] واخشوا الله الذي اعطاكم من انواع النعم مالا خفاء فيه عليكم،"},{"id":"3065","s":26,"a":133,"at":"امدكم بانعام وبنين","dt":"[133] اعطاكم الانعام: من الابل والبقر والغنم، واعطاكم الاولاد،"},{"id":"3066","s":26,"a":134,"at":"وجنات وعيون","dt":"[134] واعطاكم البساتين المثمره، وفجر لكم الماء من العيون الجاريه."},{"id":"3067","s":26,"a":135,"at":"اني اخاف عليكم عذاب يوم عظيم","dt":"[135] قال هود -عليه السلام- محذرا لهم: اني اخاف ان اصررتم على ما انتم عليه من التكذيب والظلم وكفر النعم، ان ينزل الله بكم عذابا في يوم تعظم شدته من هول عذابه."},{"id":"3068","s":26,"a":136,"at":"قالوا سواء علينا اوعظت ام لم تكن من الواعظين","dt":"[136] قالوا له: يستوي عندنا تذكيرك وتخويفك لنا وتركه، فلن نؤمن لك."},{"id":"3069","s":26,"a":137,"at":"ان هذا الا خلق الاولين","dt":"[137] وقالوا: ما هذا الذي نحن عليه الا دين الاولين وعاداتهم،"},{"id":"3070","s":26,"a":138,"at":"وما نحن بمعذبين","dt":"[138] وما نحن بمعذبين على ما نفعل مما حذرتنا منه من العذاب."},{"id":"3071","s":26,"a":139,"at":"فكذبوه فاهلكناهم ان في ذلك لايه وما كان اكثرهم مؤمنين","dt":"[139] فاستمروا على تكذيبه، فاهلكهم الله بريح بارده شديده. ان في ذلك الاهلاك لعبره لمن بعدهم، وما كان اكثر الذين سمعوا قصتهم مؤمنين بك."},{"id":"3072","s":26,"a":140,"at":"وان ربك لهو العزيز الرحيم","dt":"[140] . وان ربك لهو العزيز الغالب على ما يريده من اهلاك المكذبين، الرحيم بالمؤمنين."},{"id":"3073","s":26,"a":141,"at":"كذبت ثمود المرسلين","dt":"[141] كذبت قبيله ثمود رسولهم صالحا في رسالته ودعوته الى توحيد الله، فكانوا بهذا مكذبين لجميع الرسل؛ لانهم جميعا يدعون الى توحيد الله."},{"id":"3074","s":26,"a":142,"at":"اذ قال لهم اخوهم صالح الا تتقون","dt":"[142] اذ قال لهم اخوهم صالح: الا تخشون عقاب الله، فتفردوه بالعباده؟"},{"id":"3075","s":26,"a":143,"at":"اني لكم رسول امين","dt":"[143] اني مرسل من الله اليكم، حفيظ على هذه الرساله كما تلقيتها عن الله،"},{"id":"3076","s":26,"a":144,"at":"فاتقوا الله واطيعون","dt":"[144] فاحذروا عقابه تعالى، وامتثلوا ما دعوتكم اليه."},{"id":"3077","s":26,"a":145,"at":"وما اسالكم عليه من اجر ان اجري الا على رب العالمين","dt":"[145] وما اطلب منكم على نصحي وارشادي لكم اي جزاء، ما جزائي الا على رب العالمين."},{"id":"3078","s":26,"a":146,"at":"اتتركون في ما هاهنا امنين","dt":"[146] ايترككم ربكم فيما انتم فيه من النعيم مستقرين في هذه الدنيا امنين من العذاب والزوال والموت؟"},{"id":"3079","s":26,"a":147,"at":"في جنات وعيون","dt":"[147] في حدائق مثمره وعيون جاريه"},{"id":"3080","s":26,"a":148,"at":"وزروع ونخل طلعها هضيم","dt":"[148] وزروع كثيره ونخل ثمرها يانع لين نضيج،"},{"id":"3081","s":26,"a":149,"at":"وتنحتون من الجبال بيوتا فارهين","dt":"[149] وتنحتون من الجبال بيوتا ماهرين بنحتها، اشرين بطرين."},{"id":"3082","s":26,"a":150,"at":"فاتقوا الله واطيعون","dt":"[150] فخافوا عقوبه الله، واقبلوا نصحي،"},{"id":"3083","s":26,"a":151,"at":"ولا تطيعوا امر المسرفين","dt":"[151] ولا تنقادوا لامر المسرفين على انفسهم المتمادين في معصيه الله"},{"id":"3084","s":26,"a":152,"at":"الذين يفسدون في الارض ولا يصلحون","dt":"[152] الذين دابوا على الافساد في الارض افسادا لا اصلاح فيه."},{"id":"3085","s":26,"a":153,"at":"قالوا انما انت من المسحرين","dt":"[153] قالت ثمود لنبيها صالح: ما انت الا من الذين سحروا سحرا كثيرا، حتى غلب السحر على عقلك."},{"id":"3086","s":26,"a":154,"at":"ما انت الا بشر مثلنا فات بايه ان كنت من الصادقين","dt":"[154] ما انت الا فرد مماثل لنا في البشريه من بني ادم، فكيف تتميز علينا بالرساله؟ فات بحجه واضحه تدل على ثبوت رسالتك، ان كنت صادقا في دعواك ان الله ارسلك الينا."},{"id":"3087","s":26,"a":155,"at":"قال هذه ناقه لها شرب ولكم شرب يوم معلوم","dt":"[155] قال لهم صالح -وقد اتاهم بناقه اخرجها الله له من الصخره-: هذه ناقه الله لها نصيب من الماء في يوم معلوم، ولكم نصيب منه في يوم اخر، ليس لكم ان تشربوا في اليوم الذي هو نصيبها، ولا هي تشرب في اليوم الذي هو نصيبكم،"},{"id":"3088","s":26,"a":156,"at":"ولا تمسوها بسوء فياخذكم عذاب يوم عظيم","dt":"[156] ولا تنالوها بشيء مما يسوءها كضرب او قتل او نحو ذلك، فيهلككم الله بعذاب يوم تعظم شدته؛ بسبب ما يقع فيه من الهول والشده."},{"id":"3089","s":26,"a":157,"at":"فعقروها فاصبحوا نادمين","dt":"[157] فنحروا الناقه، فاصبحوا متحسرين على ما فعلوا لما ايقنوا بالعذاب، فلم ينفعهم ندمهم."},{"id":"3090","s":26,"a":158,"at":"فاخذهم العذاب ان في ذلك لايه وما كان اكثرهم مؤمنين","dt":"[158] فنزل بهم عذاب الله الذي توعدهم به صالح عليه السلام، فاهلكهم. ان في اهلاك ثمود لعبره لمن اعتبر بهذا المصير، وما كان اكثرهم مؤمنين."},{"id":"3091","s":26,"a":159,"at":"وان ربك لهو العزيز الرحيم","dt":"[159] وان ربك لهو العزيز القاهر المنتقم من اعدائه المكذبين، الرحيم بمن امن من خلقه."},{"id":"3092","s":26,"a":160,"at":"كذبت قوم لوط المرسلين","dt":"[160] كذبت قوم لوط برسالته، فكانوا بهذا مكذبين لسائر رسل الله؛ لان ما جاؤوا به من التوحيد واصول الشرائع واحد."},{"id":"3093","s":26,"a":161,"at":"اذ قال لهم اخوهم لوط الا تتقون","dt":"[161] اذ قال لهم اخوهم لوط: الا تخشون عذاب الله؟"},{"id":"3094","s":26,"a":162,"at":"اني لكم رسول امين","dt":"[162] اني رسول من ربكم، امين على تبليغ رسالته اليكم،"},{"id":"3095","s":26,"a":163,"at":"فاتقوا الله واطيعون","dt":"[163] فاحذروا عقاب الله على تكذيبكم رسوله، واتبعوني فيما دعوتكم اليه،"},{"id":"3096","s":26,"a":164,"at":"وما اسالكم عليه من اجر ان اجري الا على رب العالمين","dt":"[164] وما اسالكم على دعوتي لهدايتكم اي اجر، ما اجري الا على رب العالمين."},{"id":"3097","s":26,"a":165,"at":"اتاتون الذكران من العالمين","dt":"[165] اتنكحون الذكور من بني ادم،"},{"id":"3098","s":26,"a":166,"at":"وتذرون ما خلق لكم ربكم من ازواجكم بل انتم قوم عادون","dt":"[166] وتتركون ما خلق الله لاستمتاعكم وتناسلكم من ازواجكم؟ بل انتم قوم -بهذه المعصيه- متجاوزون ما اباحه الله لكم من الحلال الى الحرام."},{"id":"3099","s":26,"a":167,"at":"قالوا لئن لم تنته يالوط لتكونن من المخرجين","dt":"[167] قال قوم لوط: لئن لم تترك يا لوط نهينا عن اتيان الذكور وتقبيح فعله، لتكونن من المطرودين من بلادنا."},{"id":"3100","s":26,"a":168,"at":"قال اني لعملكم من القالين","dt":"[168] قال لوط لهم: اني لعملكم الذي تعملونه من اتيان الذكور، لمن المبغضين له بغضا شديدا."},{"id":"3101","s":26,"a":169,"at":"رب نجني واهلي مما يعملون","dt":"[169] ثم دعا لوط ربه حينما يئس من استجابتهم له قائلا: رب انقذني وانقذ اهلي مما يعمله قومي من هذه المعصيه القبيحه، ومن عقوبتك التي ستصيبهم."},{"id":"3102","s":26,"a":170,"at":"فنجيناه واهله اجمعين","dt":"[170] فنجيناه واهل بيته والمستجيبين لدعوته اجمعين"},{"id":"3103","s":26,"a":171,"at":"الا عجوزا في الغابرين","dt":"[171] الا عجوزا من اهله، وهي امراته لم تشاركهم في الايمان، فكانت من الباقين في العذاب والهلاك."},{"id":"3104","s":26,"a":172,"at":"ثم دمرنا الاخرين","dt":"[172] ثم اهلكنا من عداهم من الكفره اشد اهلاك،"},{"id":"3105","s":26,"a":173,"at":"وامطرنا عليهم مطرا فساء مطر المنذرين","dt":"[173] ، وانزلنا عليهم حجاره من السماء كالمطر اهلكتهم، فقبح مطر من انذرهم رسلهم ولم يستجيبوا لهم؛ فقد انزل بهم اشد انواع الهلاك والتدمير."},{"id":"3106","s":26,"a":174,"at":"ان في ذلك لايه وما كان اكثرهم مؤمنين","dt":"[174] ان في ذلك العقاب الذي نزل بقوم لوط لعبره وموعظه، يتعظ بها المكذبون. وما كان اكثرهم مؤمنين."},{"id":"3107","s":26,"a":175,"at":"وان ربك لهو العزيز الرحيم","dt":"[175] وان ربك لهو العزيز الغالب الذي يقهر المكذبين، الرحيم بعباده المؤمنين."},{"id":"3108","s":26,"a":176,"at":"كذب اصحاب الايكه المرسلين","dt":"[176] كذب اصحاب الارض ذات الشجر الملتف رسولهم شعيبا في رسالته، فكانوا بهذا مكذبين لجميع الرسالات."},{"id":"3109","s":26,"a":177,"at":"اذ قال لهم شعيب الا تتقون","dt":"[177] اذ قال لهم شعيب: الا تخشون عقاب الله على شرككم ومعاصيكم؟"},{"id":"3110","s":26,"a":178,"at":"اني لكم رسول امين","dt":"[178] اني مرسل اليكم من الله لهدايتكم، حفيظ على ما اوحى الله به الي من الرساله،"},{"id":"3111","s":26,"a":179,"at":"فاتقوا الله واطيعون","dt":"[179] فخافوا عقاب الله، واتبعوا ما دعوتكم اليه من هدايه الله؛ لترشدوا،"},{"id":"3112","s":26,"a":180,"at":"وما اسالكم عليه من اجر ان اجري الا على رب العالمين","dt":"[180] وما اطلب منكم على دعائي لكم الى الايمان بالله اي جزاء، ما جزائي الا على رب العالمين."},{"id":"3113","s":26,"a":181,"at":"اوفوا الكيل ولا تكونوا من المخسرين","dt":"[181] قال لهم شعيب -وقد كانوا ينقصون الكيل والميزان-: اتموا الكيل للناس وافيا لهم، ولا تكونوا ممن ينقصون الناس حقوقهم،"},{"id":"3114","s":26,"a":182,"at":"وزنوا بالقسطاس المستقيم","dt":"[182] وزنوا بالميزان العدل المستقيم،"},{"id":"3115","s":26,"a":183,"at":"ولا تبخسوا الناس اشياءهم ولا تعثوا في الارض مفسدين","dt":"[183] ولا تنقصوا الناس شيئا من حقوقهم في كيل او وزن او غير ذلك، ولا تكثروا في الارض الفساد، بالشرك والقتل والنهب وتخويف الناس وارتكاب المعاصي."},{"id":"3116","s":26,"a":184,"at":"واتقوا الذي خلقكم والجبله الاولين","dt":"[184] واحذروا عقوبه الله الذي خلقكم وخلق الامم المتقدمه عليكم."},{"id":"3117","s":26,"a":185,"at":"قالوا انما انت من المسحرين","dt":"[185] قالوا: انما انت -يا شعيب- من الذين اصابهم السحر اصابه شديده، فذهب بعقولهم،"},{"id":"3118","s":26,"a":186,"at":"وما انت الا بشر مثلنا وان نظنك لمن الكاذبين","dt":"[186] وما انت الا واحد مثلنا في البشريه، فكيف تختص دوننا بالرساله؟ وان اكبر ظننا انك من الكاذبين فيما تدعيه من الرساله."},{"id":"3119","s":26,"a":187,"at":"فاسقط علينا كسفا من السماء ان كنت من الصادقين","dt":"[187] فان كنت صادقا في دعوى النبوه، فادع الله ان يسقط علينا قطع عذاب من السماء تستاصلنا."},{"id":"3120","s":26,"a":188,"at":"قال ربي اعلم بما تعملون","dt":"[188] قال لهم شعيب: ربي اعلم بما تعملونه من الشرك والمعاصي، وبما تستوجبونه من العقاب."},{"id":"3121","s":26,"a":189,"at":"فكذبوه فاخذهم عذاب يوم الظله انه كان عذاب يوم عظيم","dt":"[189] فاستمروا على تكذيبه، فاصابهم الحر الشديد، وصاروا يبحثون عن ملاذ يستظلون به، فاظلتهم سحابه، وجدوا لها بردا ونسيما، فلما اجتمعوا تحتها التهبت عليهم نارا فاحرقتهم، فكان هلاكهم جميعا في يوم شديد الهول."},{"id":"3122","s":26,"a":190,"at":"ان في ذلك لايه وما كان اكثرهم مؤمنين","dt":"[190] ان في ذلك العقاب الذي نزل بهم، لدلاله واضحه على قدره الله في مؤاخذه المكذبين، وعبره لمن يعتبر، وما كان اكثرهم مؤمنين متعظين بذلك."},{"id":"3123","s":26,"a":191,"at":"وان ربك لهو العزيز الرحيم","dt":"[191] وان ربك -ايها الرسول- لهو العزيز في نقمته ممن انتقم منه من اعدائه، الرحيم بعباده الموحدين."},{"id":"3124","s":26,"a":192,"at":"وانه لتنزيل رب العالمين","dt":"[192] وان هذا القران الذي ذكرت فيه هذه القصص الصادقه، لمنزل من خالق الخلق، ومالك الامر كله،"},{"id":"3125","s":26,"a":193,"at":"نزل به الروح الامين","dt":"[193] نزل به جبريل الامين،"},{"id":"3126","s":26,"a":194,"at":"على قلبك لتكون من المنذرين","dt":"[194] فتلاه عليك -ايها الرسول- حتى وعيته بقلبك حفظا وفهما؛ لتكون من رسل الله الذين يخوفون قومهم عقاب الله، فتنذر بهذا التنزيل الانس والجن اجمعين."},{"id":"3127","s":26,"a":195,"at":"بلسان عربي مبين","dt":"[195] نزل به جبريل عليك بلغه عربيه واضحه المعنى، ظاهره الدلاله، فيما يحتاجون اليه في اصلاح شؤون دينهم ودنياهم."},{"id":"3128","s":26,"a":196,"at":"وانه لفي زبر الاولين","dt":"[196] وان ذكر هذا القران لمثبت في كتب الانبياء السابقين، قد بشرت به وصدقته."},{"id":"3129","s":26,"a":197,"at":"او لم يكن لهم ايه ان يعلمه علماء بني اسرائيل","dt":"[197] او لم يكف هؤلاء -في الدلاله على انك رسول الله، وان القران حق- علم علماء بني اسرائيل صحه ذلك، ومن امن منهم كعبدالله بن سلام؟"},{"id":"3130","s":26,"a":198,"at":"ولو نزلناه على بعض الاعجمين","dt":"[198] ولو نزلنا القران على بعض الذين لا يتكلمون بالعربيه"},{"id":"3131","s":26,"a":199,"at":"فقراه عليهم ما كانوا به مؤمنين","dt":"[199] فقراه على كفار قريش قراءه عربيه صحيحه، لكفروا به ايضا، وانتحلوا لجحودهم عذرا"},{"id":"3132","s":26,"a":200,"at":"كذلك سلكناه في قلوب المجرمين","dt":"[200] كذلك ادخلنا في قلوب المجرمين جحود القران، وصار متمكنا فيها؛ وذلك بسبب ظلمهم واجرامهم،"},{"id":"3133","s":26,"a":201,"at":"لا يؤمنون به حتى يروا العذاب الاليم","dt":"[201] فلا سبيل الى ان يتغيروا عما هم عليه من انكار القران، حتى يعاينوا العذاب الشديد الذي وعدوا به."},{"id":"3134","s":26,"a":202,"at":"فياتيهم بغته وهم لا يشعرون","dt":"[202] فينزل بهم العذاب فجاه، وهم لا يعلمون قبل ذلك بمجيئه،"},{"id":"3135","s":26,"a":203,"at":"فيقولوا هل نحن منظرون","dt":"[203] فيقولون عند مفاجاتهم به تحسرا على ما فاتهم من الايمان: هل نحن ممهلون مؤخرون؛ لنتوب الى الله من شركنا، ونستدرك ما فاتنا؟"},{"id":"3136","s":26,"a":204,"at":"افبعذابنا يستعجلون","dt":"[204] اغر هؤلاء امهالي، فيستعجلون نزول العذاب عليهم من السماء؟"},{"id":"3137","s":26,"a":205,"at":"افرايت ان متعناهم سنين","dt":"[205] افعلمت -ايها الرسول- ان متعناهم بالحياه سنين طويله بتاخير اجالهم،"},{"id":"3138","s":26,"a":206,"at":"ثم جاءهم ما كانوا يوعدون","dt":"[206] ثم نزل بهم العذاب الموعود؟"},{"id":"3139","s":26,"a":207,"at":"ما اغنى عنهم ما كانوا يمتعون","dt":"[207] ما اغنى عنهم تمتعهم بطول العمر، وطيب العيش، اذا لم يتوبوا من شركهم؟ فعذاب الله واقع بهم عاجلا ام اجلا."},{"id":"3140","s":26,"a":208,"at":"وما اهلكنا من قريه الا لها منذرون","dt":"[208] وما اهلكنا من قريه من القرى في الامم جميعا، الا بعد ان نرسل اليهم رسلا ينذرونهم"},{"id":"3141","s":26,"a":209,"at":"ذكرى وما كنا ظالمين","dt":"[209] تذكره لهم وتنبيها على ما فيه نجاتهم، وما كنا ظالمين فنعذب امه قبل ان نرسل اليها رسولا."},{"id":"3142","s":26,"a":210,"at":"وما تنزلت به الشياطين","dt":"[210] وما تنزلت بالقران على محمد صلى الله عليه وسلم الشياطين كما يزعم الكفره"},{"id":"3143","s":26,"a":211,"at":"وما ينبغي لهم وما يستطيعون","dt":"[211] ولا يصح منهم ذلك، وما يستطيعونه؛"},{"id":"3144","s":26,"a":212,"at":"انهم عن السمع لمعزولون","dt":"[212] لانهم عن استماع القران من السماء محجوبون مرجومون بالشهب."},{"id":"3145","s":26,"a":213,"at":"فلا تدع مع الله الها اخر فتكون من المعذبين","dt":"[213] فلا تعبد مع الله معبودا غيره، فينزل بك من العذاب ما نزل بهؤلاء الذين عبدوا مع الله غيره."},{"id":"3146","s":26,"a":214,"at":"وانذر عشيرتك الاقربين","dt":"[214] وحذر -ايها الرسول- الاقرب فالاقرب من قومك، من عذابنا، ان ينزل بهم."},{"id":"3147","s":26,"a":215,"at":"واخفض جناحك لمن اتبعك من المؤمنين","dt":"[215] والن جانبك وكلامك تواضعا ورحمه لمن ظهر لك منه اجابه دعوتك."},{"id":"3148","s":26,"a":216,"at":"فان عصوك فقل اني بريء مما تعملون","dt":"[216] فان خالفوا امرك ولم يتبعوك، فتبرا من اعمالهم، وما هم عليه من الشرك والضلال."},{"id":"3149","s":26,"a":217,"at":"وتوكل على العزيز الرحيم","dt":"[217] وفوض امرك الى الله العزيز الذي لا يغالب ولا يقهر، الرحيم الذي لا يخذل اولياءه،"},{"id":"3150","s":26,"a":218,"at":"الذي يراك حين تقوم","dt":"[218] وهو الذي يراك حين تقوم للصلاه وحدك في جوف الليل"},{"id":"3151","s":26,"a":219,"at":"وتقلبك في الساجدين","dt":"[219] ويرى تقلبك مع الساجدين في صلاتهم معك قائما وراكعا وساجدا وجالسا"},{"id":"3152","s":26,"a":220,"at":"انه هو السميع العليم","dt":"[220] انه -سبحانه- هو السميع لتلاوتك وذكرك، العليم بنيتك وعملك."},{"id":"3153","s":26,"a":221,"at":"هل انبئكم على من تنزل الشياطين","dt":"[221] هل اخبركم -ايها الناس- على من تنزل الشياطين؟"},{"id":"3154","s":26,"a":222,"at":"تنزل على كل افاك اثيم","dt":"[222] تتنزل على كل كذاب كثير الاثام من الكهنه،"},{"id":"3155","s":26,"a":223,"at":"يلقون السمع واكثرهم كاذبون","dt":"[223] يسترق الشياطين السمع، يتخطفونه من الملا الاعلى، فيلقونه الى الكهان، ومن جرى مجراهم من الفسقه، واكثر هؤلاء كاذبون، يصدق احدهم في كلمه، فيزيد فيها اكثر من مائه كذبه."},{"id":"3156","s":26,"a":224,"at":"والشعراء يتبعهم الغاوون","dt":"[224] والشعراء يقوم شعرهم على الباطل والكذب، ويجاريهم الضالون الزائغون من امثالهم"},{"id":"3157","s":26,"a":225,"at":"الم تر انهم في كل واد يهيمون","dt":"[225] الم تر -ايها النبي- انهم يذهبون كالهائم على وجهه، يخوضون في كل فن من فنون الكذب والزور وتمزيق الاعراض والطعن في الانساب وتجريح النساء العفائف"},{"id":"3158","s":26,"a":226,"at":"وانهم يقولون ما لا يفعلون","dt":"[226] وانهم يقولون ما لا يفعلون، يبالغون في مدح اهل الباطل، وينتقصون اهل الحق؟"},{"id":"3159","s":26,"a":227,"at":"الا الذين امنوا وعملوا الصالحات وذكروا الله كثيرا وانتصروا من بعد ما ظلموا وسيعلم الذين ظلموا اي منقلب ينقلبون","dt":"[227] استثنى الله من الشعراء الشعراء الذين اهتدوا بالايمان وعملوا الصالحات، واكثروا من ذكر الله فقالوا الشعر في توحيد الله -سبحانه- والثناء عليه جل ذكره، والدفاع عن رسوله محمد -صلى الله عليه وسلم-، وتكلموا بالحكمه والموعظه والاداب الحسنه، وانتصروا للاسلام، يهجون من يهجوه او يهجو رسوله؛ ردا على الشعراء الكافرين. وسيعلم الذين ظلموا انفسهم بالشرك والمعاصي، وظلموا غيرهم بغمط حقوقهم، او الاعتداء عليهم، او بالتهم الباطله، اي مرجع من مراجع الشر والهلاك يرجعون اليه؟ انه منقلب سوء، نسال الله السلامه والعافيه."},{"id":"3160","s":27,"a":1,"at":"طس تلك ايات القران وكتاب مبين","dt":"[1] طس سبق الكلام على الحروف المقطعه في اول سوره البقره.هذه ايات القران وهي ايات الكتاب العزيز بينه المعنى، واضحه الدلاله، على ما فيه من العلوم والحكم والشرائع.فالقران هو الكتاب، جمع الله له بين الاسمين."},{"id":"3161","s":27,"a":2,"at":"هدى وبشرى للمؤمنين","dt":"[2] وهي ايات ترشد الى طريق الفوز في الدنيا والاخره، وتبشر بحسن الثواب للمؤمنين الذين صدقوا بها، واهتدوا بهديها"},{"id":"3162","s":27,"a":3,"at":"الذين يقيمون الصلاه ويؤتون الزكاه وهم بالاخره هم يوقنون","dt":"[3] الذين يقيمون الصلوات الخمس كامله الاركان، مستوفيه الشروط، ويؤدون الزكاه المفروضه لمستحقيها، وهم يوقنون بالحياه الاخره، وما فيها من ثواب وعقاب."},{"id":"3163","s":27,"a":4,"at":"ان الذين لا يؤمنون بالاخره زينا لهم اعمالهم فهم يعمهون","dt":"[4] ان الذين لا يصدقون بالدار الاخره، ولا يعملون لها، حسنا لهم اعمالهم السيئه، فراوها حسنه، فهم يترددون فيها متحيرين"},{"id":"3164","s":27,"a":5,"at":"اولئك الذين لهم سوء العذاب وهم في الاخره هم الاخسرون","dt":"[5] اولئك الذين لهم العذاب السيئ في الدنيا قتلا واسرا وذلا وهزيمه، وهم في الاخره اشد الناس خسرانا."},{"id":"3165","s":27,"a":6,"at":"وانك لتلقى القران من لدن حكيم عليم","dt":"[6] وانك -ايها الرسول- لتتلقى القران من عند الله، الحكيم في خلقه وتدبيره الذي احاط بكل شيء علما."},{"id":"3166","s":27,"a":7,"at":"اذ قال موسى لاهله اني انست نارا ساتيكم منها بخبر او اتيكم بشهاب قبس لعلكم تصطلون","dt":"[7] اذكر قصه موسى حين قال لاهله في مسيره من «مدين» الى «مصر»: اني ابصرت نارا ساتيكم منها بخبر يدلنا على الطريق، او اتيكم بشعله نار؛ كي تستدفئوا بها من البرد."},{"id":"3167","s":27,"a":8,"at":"فلما جاءها نودي ان بورك من في النار ومن حولها وسبحان الله رب العالمين","dt":"[8] فلما جاء موسى النار ناداه الله واخبره ان هذا مكان قدسه الله وباركه فجعله موضعا لتكليم موسى وارساله، وان الله بارك من في النار ومن حولها من الملائكه، وتنزيها لله رب الخلائق عما لا يليق به"},{"id":"3168","s":27,"a":9,"at":"ياموسى انه انا الله العزيز الحكيم","dt":"[9] . يا موسى انه انا الله المستحق للعباده وحدي، العزيز الغالب في انتقامي من اعدائي، الحكيم في تدبير خلقي"},{"id":"3169","s":27,"a":10,"at":"والق عصاك فلما راها تهتز كانها جان ولى مدبرا ولم يعقب ياموسى لا تخف اني لا يخاف لدي المرسلون","dt":"[10] والق عصاك فالقاها فصارت حيه، فلما راها تتحرك في خفه تحرك الحيه السريعه ولى هاربا ولم يرجع اليها، فطمانه الله بقوله: يا موسى لا تخف، اني لا يخاف لدي من ارسلتهم برسالتي"},{"id":"3170","s":27,"a":11,"at":"الا من ظلم ثم بدل حسنا بعد سوء فاني غفور رحيم","dt":"[11] لكن من تجاوز الحد بذنب، ثم تاب فبدل حسن التوبه بعد قبح الذنب، فاني غفور له رحيم به، فلا ييئس احد من رحمه الله ومغفرته"},{"id":"3171","s":27,"a":12,"at":"وادخل يدك في جيبك تخرج بيضاء من غير سوء في تسع ايات الى فرعون وقومه انهم كانوا قوما فاسقين","dt":"[12] وادخل يدك في فتحه قميصك المفتوحه الى الصدر تخرج بيضاء كالثلج من غير برص في جمله تسع معجزات، وهي مع اليد: العصا، والسنون، ونقص الثمرات، والطوفان، والجراد، والقمل، والضفادع، والدم؛ لتاييدك في رسالتك الى فرعون وقومه، انهم كانوا قوما خارجين عن امر الله كافرين به."},{"id":"3172","s":27,"a":13,"at":"فلما جاءتهم اياتنا مبصره قالوا هذا سحر مبين","dt":"[13] فلما جاءتهم هذه المعجزات ظاهره بينه يبصر بها من نظر اليها حقيقه ما دلت عليه، قالوا: هذا سحر واضح بين."},{"id":"3173","s":27,"a":14,"at":"وجحدوا بها واستيقنتها انفسهم ظلما وعلوا فانظر كيف كان عاقبه المفسدين","dt":"[14] وكذب فرعون وقومه بالمعجزات التسع الواضحه الدلاله على صدق موسى في نبوته وصدق دعوته، وانكروا بالسنتهم ان تكون من عند الله، وقد استيقنوها في قلوبهم اعتداء على الحق، وتكبرا على الاعتراف به، فانظر -ايها الرسول- كيف كان مصير الذين كفروا بايات الله، افسدوا في الارض، فاغرقهم الله في البحر؟ وفي ذلك عبره لمن يعتبر."},{"id":"3174","s":27,"a":15,"at":"ولقد اتينا داود وسليمان علما وقالا الحمد لله الذي فضلنا على كثير من عباده المؤمنين","dt":"[15] ولقد اتينا داود وسليمان علما فعملا به، وقالا: الحمد لله الذي فضلنا بهذا على كثير من عباده المؤمنين. وفي الايه دليل على شرف العلم، وارتفاع اهله."},{"id":"3175","s":27,"a":16,"at":"وورث سليمان داود وقال ياايها الناس علمنا منطق الطير واوتينا من كل شيء ان هذا لهو الفضل المبين","dt":"[16] وورث سليمان اباه داود في النبوه والعلم والملك، وقال سليمان لقومه: يا ايها الناس علمنا وفهمنا كلام الطير، واعطينا من كل شيء تدعو اليه الحاجه، ان هذا الذي اعطانا الله تعالى اياه لهو الفضل الواضح الذي يميزنا على من سوانا."},{"id":"3176","s":27,"a":17,"at":"وحشر لسليمان جنوده من الجن والانس والطير فهم يوزعون","dt":"[17] وجمع لسليمان جنوده من الجن والانس والطير في مسيره لهم، فهم على كثرتهم لم يكونوا مهملين، بل كان على كل جنس من يرد اولهم على اخرهم؛ كي يقفوا جميعا منتظمين."},{"id":"3177","s":27,"a":18,"at":"حتى اذا اتوا على وادي النمل قالت نمله ياايها النمل ادخلوا مساكنكم لا يحطمنكم سليمان وجنوده وهم لا يشعرون","dt":"[18] حتى اذا بلغوا وادي النمل قالت نمله: يا ايها النمل ادخلوا مساكنكم لا يهلكنكم سليمان وجنوده، وهم لا يعلمون بذلك"},{"id":"3178","s":27,"a":19,"at":"فتبسم ضاحكا من قولها وقال رب اوزعني ان اشكر نعمتك التي انعمت علي وعلى والدي وان اعمل صالحا ترضاه وادخلني برحمتك في عبادك الصالحين","dt":"[19] فتبسم ضاحكا من قول هذه النمله لفهمها واهتدائها الى تحذير النمل، واستشعر نعمه الله عليه، فتوجه اليه داعيا: رب الهمني، ووفقني ان اشكر نعمتك التي انعمت علي وعلى والدي، وان اعمل عملا صالحا ترضاه مني، وادخلني برحمتك في نعيم جنتك مع عبادك الصالحين الذين ارتضيت اعمالهم."},{"id":"3179","s":27,"a":20,"at":"وتفقد الطير فقال ما لي لا ارى الهدهد ام كان من الغائبين","dt":"[20] وتفقد سليمان حال الطير المسخره له وحال ما غاب منها، وكان عنده هدهد متميز معروف فلم يجده، فقال: ما لي لا ارى الهدهد الذي اعهده؟ استره ساتر عني، ام انه كان من الغائبين عني، فلم اره لغيبته؟"},{"id":"3180","s":27,"a":21,"at":"لاعذبنه عذابا شديدا او لاذبحنه او لياتيني بسلطان مبين","dt":"[21] فلما ظهر انه غائب قال: لاعذبن هذا الهدهد عذابا شديدا لغيابه تاديبا له، او لاذبحنه عقوبه على ما فعل؛ حيث اخل بما سخر له، او لياتيني بحجه ظاهره فيها عذر لغيبته."},{"id":"3181","s":27,"a":22,"at":"فمكث غير بعيد فقال احطت بما لم تحط به وجئتك من سبا بنبا يقين","dt":"[22] فمكث الهدهد زمنا غير بعيد ثم حضر، فعاتبه سليمان على مغيبه وتخلفه، فقال له الهدهد: علمت ما لم تعلمه من الامر على وجه الاحاطه، وجئتك من مدينه «سبا» ب«اليمن» بخبر خطير الشان، وانا على يقين منه."},{"id":"3182","s":27,"a":23,"at":"اني وجدت امراه تملكهم واوتيت من كل شيء ولها عرش عظيم","dt":"[23] اني وجدت امراه تحكم اهل «سبا»، واوتيت من كل شيء من اسباب الدنيا، ولها سرير عظيم القدر، تجلس عليه لاداره ملكها."},{"id":"3183","s":27,"a":24,"at":"وجدتها وقومها يسجدون للشمس من دون الله وزين لهم الشيطان اعمالهم فصدهم عن السبيل فهم لا يهتدون","dt":"[24] وجدتها هي وقومها يعبدون الشمس معرضين عن عباده الله، وحسن لهم الشيطان اعمالهم السيئه التي كانوا يعملونها، فصرفهم عن الايمان بالله وتوحيده، فهم لا يهتدون الى الله وتوحيده وعبادته وحده."},{"id":"3184","s":27,"a":25,"at":"الا يسجدوا لله الذي يخرج الخبء في السموات والارض ويعلم ما تخفون وما تعلنون","dt":"[25] حسن لهم الشيطان ذلك؛ لئلا يسجدوا لله الذي يخرج المخبوء المستور في السموات والارض من المطر والنبات وغير ذلك، ويعلم ما تسرون وما تظهرون"},{"id":"3185","s":27,"a":26,"at":"الله لا اله الا هو رب العرش العظيم","dt":"[26] الله الذي لا معبود يستحق العباده سواه، رب العرش العظيم، فعرش الرحمن اعظم المخلوقات."},{"id":"3186","s":27,"a":27,"at":"قال سننظر اصدقت ام كنت من الكاذبين","dt":"[27] قال سليمان للهدهد: سنتامل فيما جئتنا به من الخبر اصدقت في ذلك ام كنت من الكاذبين فيه؟"},{"id":"3187","s":27,"a":28,"at":"اذهب بكتابي هذا فالقه اليهم ثم تول عنهم فانظر ماذا يرجعون","dt":"[28] اذهب بكتابي هذا الى اهل «سبا» فاعطهم اياه، ثم تنح عنهم قريبا منهم بحيث تسمع كلامهم، فتامل ما يتردد بينهم من الكلام."},{"id":"3188","s":27,"a":29,"at":"قالت ياايها الملا اني القي الي كتاب كريم","dt":"[29] ذهب الهدهد والقى الكتاب الى الملكه فقراته، فجمعت اشراف قومها، وسمعها تقول لهم: اني وصل الي كتاب جليل المقدار من شخص عظيم الشان."},{"id":"3189","s":27,"a":30,"at":"انه من سليمان وانه بسم الله الرحمن الرحيم","dt":"[30] ثم بينت ما فيه فقالت: انه من سليمان، وانه مفتتح ب «بسم الله الرحمن الرحيم»"},{"id":"3190","s":27,"a":31,"at":"الا تعلوا علي واتوني مسلمين","dt":"[31] الا تتكبروا ولا تتعاظموا عما دعوتكم اليه، واقبلوا الي منقادين لله بالوحدانيه والطاعه مسلمين له."},{"id":"3191","s":27,"a":32,"at":"قالت ياايها الملا افتوني في امري ما كنت قاطعه امرا حتى تشهدون","dt":"[32] قالت: يا ايها الاشراف اشيروا علي في هذا الامر، ما كنت لافصل في امر الا بمحضركم ومشورتكم."},{"id":"3192","s":27,"a":33,"at":"قالوا نحن اولو قوه واولو باس شديد والامر اليك فانظري ماذا تامرين","dt":"[33] قالوا مجيبين لها: نحن اصحاب قوه في العدد والعده واصحاب النجده والشجاعه في شده الحرب، والامر موكول اليك، وانت صاحبه الراي، فتاملي ماذا تامريننا به؟ فنحن سامعون لامرك مطيعون لك."},{"id":"3193","s":27,"a":34,"at":"قالت ان الملوك اذا دخلوا قريه افسدوها وجعلوا اعزه اهلها اذله وكذلك يفعلون","dt":"[34] قالت محذره لهم من مواجهه سليمان بالعداوه، ومبينه لهم سوء مغبه القتال: ان الملوك اذا دخلوا بجيوشهم قريه عنوه وقهرا خربوها وصيروا اعزه اهلها اذله، وقتلوا واسروا، وهذه عادتهم المستمره الثابته لحمل الناس على ان يهابوهم"},{"id":"3194","s":27,"a":35,"at":"واني مرسله اليهم بهديه فناظره بم يرجع المرسلون","dt":"[35] واني مرسله الى سليمان وقومه بهديه مشتمله على نفائس الاموال اصانعه بها، ومنتظره ما يرجع به الرسل."},{"id":"3195","s":27,"a":36,"at":"فلما جاء سليمان قال اتمدونن بمال فما اتاني الله خير مما اتاكم بل انتم بهديتكم تفرحون","dt":"[36] فلما جاء رسول الملكه بالهديه الى سليمان، قال مستنكرا ذلك متحدثا بانعم الله عليه: اتمدونني بمال ترضيه لي؟ فما اعطاني الله من النبوه والملك والاموال الكثيره خير وافضل مما اعطاكم، بل انتم الذين تفرحون بالهديه التي تهدى اليكم؛ لانكم اهل مفاخره بالدنيا ومكاثره بها."},{"id":"3196","s":27,"a":37,"at":"ارجع اليهم فلناتينهم بجنود لا قبل لهم بها ولنخرجنهم منها اذله وهم صاغرون","dt":"[37] وقال سليمان عليه السلام لرسول اهل «سبا»: ارجع اليهم، فوالله لناتينهم بجنود لا طاقه لهم بمقاومتها ومقابلتها، ولنخرجنهم من ارضهم اذله وهم صاغرون مهانون، ان لم ينقادوا لدين الله وحده، ويتركوا عباده من سواه."},{"id":"3197","s":27,"a":38,"at":"قال ياايها الملا ايكم ياتيني بعرشها قبل ان ياتوني مسلمين","dt":"[38] قال سليمان مخاطبا من سخرهم الله له من الجن والانس: ايكم ياتيني بسرير ملكها العظيم قبل ان ياتوني منقادين طائعين؟"},{"id":"3198","s":27,"a":39,"at":"قال عفريت من الجن انا اتيك به قبل ان تقوم من مقامك واني عليه لقوي امين","dt":"[39] قال مارد قوي شديد من الجن: انا اتيك به قبل ان تقوم من مجلسك هذا الذي تجلس فيه للحكم بين الناس، واني لقوي على حمله، امين على ما فيه، اتي به كما هو لا انقص منه شيئا ولا ابدله."},{"id":"3199","s":27,"a":40,"at":"قال الذي عنده علم من الكتاب انا اتيك به قبل ان يرتد اليك طرفك فلما راه مستقرا عنده قال هذا من فضل ربي ليبلوني ااشكر ام اكفر ومن شكر فانما يشكر لنفسه ومن كفر فان ربي غني كريم","dt":"[40] قال الذي عنده علم من الكتاب: انا اتيك بهذا العرش قبل ارتداد اجفانك اذا تحركت للنظر في شيء. فاذن له سليمان فدعا الله، فاتى بالعرش. فلما راه سليمان حاضرا لديه ثابتا عنده قال: هذا من فضل ربي الذي خلقني وخلق الكون كله؛ ليختبرني: ااشكر بذلك اعترافا بنعمته تعالى علي ام اكفر بترك الشكر؟ ومن شكر لله على نعمه فان نفع ذلك يرجع اليه، ومن جحد النعمه وترك الشكر فان ربي غني عن شكره، كريم يعم بخيره في الدنيا الشاكر والكافر، ثم يحاسبهم ويجازيهم في الاخره."},{"id":"3200","s":27,"a":41,"at":"قال نكروا لها عرشها ننظر اتهتدي ام تكون من الذين لا يهتدون","dt":"[41] قال سليمان لمن عنده: غيروا سرير ملكها الذي تجلس عليه الى حال تنكره اذا راته؛ لنرى اتهتدي الى معرفته ام تكون من الذين لا يهتدون؟"},{"id":"3201","s":27,"a":42,"at":"فلما جاءت قيل اهكذا عرشك قالت كانه هو واوتينا العلم من قبلها وكنا مسلمين","dt":"[42] فلما جاءت ملكه «سبا» الى سليمان في مجلسه قيل لها: اهكذا عرشك؟ قالت: انه يشبهه. فظهر لسليمان انها اصابت في جوابها، وقد علمت قدره الله وصحه نبوه سليمان عليه السلام، فقال: واوتينا العلم بالله وبقدرته من قبلها، وكنا منقادين لامر الله متبعين لدين الاسلام."},{"id":"3202","s":27,"a":43,"at":"وصدها ما كانت تعبد من دون الله انها كانت من قوم كافرين","dt":"[43] ومنعها عن عباده الله وحده ما كانت تعبده من دون الله تعالى، انها كانت كافره ونشات بين قوم كافرين، واستمرت على دينهم، والا فلها من الذكاء والفطنه ما تعرف به الحق من الباطل، ولكن العقائد الباطله تذهب بصيره القلب."},{"id":"3203","s":27,"a":44,"at":"قيل لها ادخلي الصرح فلما راته حسبته لجه وكشفت عن ساقيها قال انه صرح ممرد من قوارير قالت رب اني ظلمت نفسي واسلمت مع سليمان لله رب العالمين","dt":"[44] قيل لها: ادخلي القصر، وكان صحنه من زجاج تحته ماء، فلما رات صحن القصر ظنته ماء تتردد امواجه، وكشفت عن ساقيها لتخوض الماء، فقال لها سليمان: انه صحن املس من زجاج صاف والماء تحته. فادركت عظمه ملك سليمان، وقالت: رب اني ظلمت نفسي بما كنت عليه من الشرك، وانقدت متابعه لسليمان داخله في دين رب العالمين اجمعين."},{"id":"3204","s":27,"a":45,"at":"ولقد ارسلنا الى ثمود اخاهم صالحا ان اعبدوا الله فاذا هم فريقان يختصمون","dt":"[45] ولقد ارسلنا الى ثمود اخاهم صالحا: ان وحدوا الله، ولا تجعلوا معه الها اخر، فلما اتاهم صالح داعيا الى توحيد الله وعبادته وحده صار قومه فريقين: احدهما مؤمن به، والاخر كافر بدعوته، وكل منهم يزعم ان الحق معه."},{"id":"3205","s":27,"a":46,"at":"قال ياقوم لم تستعجلون بالسيئه قبل الحسنه لولا تستغفرون الله لعلكم ترحمون","dt":"[46] قال صالح للفريق الكافر: لم تبادرون الكفر وعمل السيئات الذي يجلب لكم العذاب، وتؤخرون الايمان وفعل الحسنات الذي يجلب لكم الثواب؟ هلا تطلبون المغفره من الله ابتداء، وتتوبون اليه؛ رجاء ان ترحموا."},{"id":"3206","s":27,"a":47,"at":"قالوا اطيرنا بك وبمن معك قال طائركم عند الله بل انتم قوم تفتنون","dt":"[47] قال قوم صالح له: تشاءمنا بك وبمن معك ممن دخل في دينك، قال لهم صالح: ما اصابكم الله من خير او شر فهو مقدره عليكم ومجازيكم به، بل انتم قوم تختبرون بالسراء والضراء والخير والشر."},{"id":"3207","s":27,"a":48,"at":"وكان في المدينه تسعه رهط يفسدون في الارض ولا يصلحون","dt":"[48] وكان في مدينه صالح -وهي «الحجر» الواقعه في شمال غرب جزيره العرب-تسعه رجال، شانهم الافساد في الارض، الذي لا يخالطه شيء من الصلاح."},{"id":"3208","s":27,"a":49,"at":"قالوا تقاسموا بالله لنبيتنه واهله ثم لنقولن لوليه ما شهدنا مهلك اهله وانا لصادقون","dt":"[49] قال هؤلاء التسعه بعضهم لبعض: تقاسموا بالله بان يحلف كل واحد للاخرين: لناتين صالحا بغته في الليل فلنقتلنه ولنقتلن اهله، ثم لنقولن لولي الدم من قرابته: ما حضرنا قتلهم، وانا لصادقون فيما قلناه."},{"id":"3209","s":27,"a":50,"at":"ومكروا مكرا ومكرنا مكرا وهم لا يشعرون","dt":"[50] ودبروا هذه الحيله لاهلاك صالح واهله مكرا منهم، فنصرنا نبينا صالحا عليه السلام، واخذناهم بالعقوبه على غره، وهم لا يتوقعون كيدنا لهم جزاء على كيدهم."},{"id":"3210","s":27,"a":51,"at":"فانظر كيف كان عاقبه مكرهم انا دمرناهم وقومهم اجمعين","dt":"[51] فانظر -ايها الرسول- نظره اعتبار الى عاقبه غدر هؤلاء الرهط بنبيهم صالح؟ انا اهلكناهم وقومهم اجمعين."},{"id":"3211","s":27,"a":52,"at":"فتلك بيوتهم خاويه بما ظلموا ان في ذلك لايه لقوم يعلمون","dt":"[52] فتلك مساكنهم خاليه ليس فيها منهم احد، اهلكهم الله؛ بسبب ظلمهم لانفسهم بالشرك، وتكذيب نبيهم. ان في ذلك التدمير والاهلاك لعظه لقوم يعلمون ما فعلناه بهم، وهذه سنتنا فيمن يكذب المرسلين."},{"id":"3212","s":27,"a":53,"at":"وانجينا الذين امنوا وكانوا يتقون","dt":"[53] وانجينا مما حل بثمود من الهلاك صالحا عليه السلام والمؤمنين به، الذين كانوا يتقون بايمانهم عذاب الله."},{"id":"3213","s":27,"a":54,"at":"ولوطا اذ قال لقومه اتاتون الفاحشه وانتم تبصرون","dt":"[54] واذكر لوطا اذ قال لقومه: اتاتون الفعله المتناهيه في القبح، وانتم تعلمون قبحها؟"},{"id":"3214","s":27,"a":55,"at":"ائنكم لتاتون الرجال شهوه من دون النساء بل انتم قوم تجهلون","dt":"[55] اانكم لتاتون الرجال في ادبارهم للشهوه عوضا عن النساء؟ بل انتم قوم تجهلون حق الله عليكم، فخالفتم بذلك امره، وعصيتم رسوله بفعلتكم القبيحه التي لم يسبقكم بها احد من العالمين."},{"id":"3215","s":27,"a":56,"at":"فما كان جواب قومه الا ان قالوا اخرجوا ال لوط من قريتكم انهم اناس يتطهرون","dt":"[56] فما كان لقوم لوط جواب له الا قول بعضهم لبعض: اخرجوا ال لوط من قريتكم، انهم اناس يتنزهون عن اتيان الذكران. قالوا لهم ذلك استهزاء بهم."},{"id":"3216","s":27,"a":57,"at":"فانجيناه واهله الا امراته قدرناها من الغابرين","dt":"[57] فانجينا لوطا واهله من العذاب الذي سيقع بقوم لوط، الا امراته قدرناها من الباقين في العذاب حتى تهلك مع الهالكين؛ لانها كانت عونا لقومها على افعالهم القبيحه راضيه بها."},{"id":"3217","s":27,"a":58,"at":"وامطرنا عليهم مطرا فساء مطر المنذرين","dt":"[58] وامطرنا عليهم من السماء حجاره من طين مهلكه، فقبح مطر المنذرين، الذين قامت عليهم الحجه."},{"id":"3218","s":27,"a":59,"at":"قل الحمد لله وسلام على عباده الذين اصطفى الله خير اما يشركون","dt":"[59] قل -ايها الرسول-: الثناء والشكر لله، وسلام منه، وامنه على عباده الذين تخيرهم لرسالته، ثم اسال مشركي قومك: هل الله الذي يملك النفع والضر خير او الذي يشركون من دونه، ممن لا يملك لنفسه ولا لغيره نفعا ولا ضرا؟"},{"id":"3219","s":27,"a":60,"at":"امن خلق السموات والارض وانزل لكم من السماء ماء فانبتنا به حدائق ذات بهجه ما كان لكم ان تنبتوا شجرها االه مع الله بل هم قوم يعدلون","dt":"[60] واسالهم من خلق السموات والارض، وانزل لكم من السماء ماء، فانبت به حدائق ذات منظر حسن؟ ما كان لكم ان تنبتوا شجرها، لولا ان الله انزل عليكم الماء من السماء. ان عبادته سبحانه هي الحق، وعباده ما سواه هي الباطل. امعبود مع الله فعل هذه الافعال حتى يعبد معه ويشرك به؟ بل هؤلاء المشركون قوم ينحرفون عن طريق الحق والايمان، فيسوون بالله غيره في العباده والتعظيم."},{"id":"3220","s":27,"a":61,"at":"امن جعل الارض قرارا وجعل خلالها انهارا وجعل لها رواسي وجعل بين البحرين حاجزا االه مع الله بل اكثرهم لا يعلمون","dt":"[61] اعباده ما تشركون بربكم خير ام الذي جعل لكم الارض مستقرا وجعل وسطها انهارا، وجعل لها الجبال ثوابت، وجعل بين البحرين العذب والملح حاجزا حتى لا يفسد احدهما الاخر؟ امعبود مع الله فعل ذلك حتى تشركوه معه في عبادتكم؟ بل اكثر هؤلاء المشركين لا يعلمون قدر عظمه الله، فهم يشركون به تقليدا وظلما."},{"id":"3221","s":27,"a":62,"at":"امن يجيب المضطر اذا دعاه ويكشف السوء ويجعلكم خلفاء الارض االه مع الله قليلا ما تذكرون","dt":"[62] اعباده ما تشركون بالله خير ام الذي يجيب المكروب اذا دعاه، ويكشف السوء النازل به، ويجعلكم خلفاء لمن سبقكم في الارض؟ امعبود مع الله ينعم عليكم هذه النعم؟ قليلا ما تذكرون وتعتبرون، فلذلك اشركتم بالله غيره في عبادته."},{"id":"3222","s":27,"a":63,"at":"امن يهديكم في ظلمات البر والبحر ومن يرسل الرياح بشرا بين يدي رحمته االه مع الله تعالى الله عما يشركون","dt":"[63] اعباده ما تشركون بالله خير ام الذي يرشدكم في ظلمات البر والبحر اذا ضللتم فاظلمت عليكم السبل، والذي يرسل الرياح مبشرات بما يرحم به عباده من غيث يحيي موات الارض؟ امعبود مع الله يفعل بكم شيئا من ذلك فتدعونه من دونه؟ تنزه الله وتقدس عما يشركون به غيره."},{"id":"3223","s":27,"a":64,"at":"امن يبدا الخلق ثم يعيده ومن يرزقكم من السماء والارض االه مع الله قل هاتوا برهانكم ان كنتم صادقين","dt":"[64] واسالهم من الذي ينشئ الخلق ثم يفنيه اذا شاء، ثم يعيده، ومن الذي يرزقكم من السماء بانزال المطر، ومن الارض بانبات الزرع وغيره؟ امعبود سوى الله يفعل ذلك؟ قل: هاتوا حجتكم ان كنتم صادقين في زعمكم ان لله تعالى شريكا في ملكه وعبادته."},{"id":"3224","s":27,"a":65,"at":"قل لا يعلم من في السموات والارض الغيب الا الله وما يشعرون ايان يبعثون","dt":"[65] قل -ايها الرسول- لهم: لا يعلم احد في السموات ولا في الارض ما استاثر الله بعلمه من المغيبات، ولا يدرون متى هم مبعوثون من قبورهم عند قيام الساعه؟"},{"id":"3225","s":27,"a":66,"at":"بل ادارك علمهم في الاخره بل هم في شك منها بل هم منها عمون","dt":"[66] بل تكامل علمهم في الاخره، فايقنوا بالدار الاخره، وما فيها من اهوال حين عاينوها، وقد كانوا في الدنيا في شك منها، بل عميت عنها بصائرهم."},{"id":"3226","s":27,"a":67,"at":"وقال الذين كفروا ائذا كنا ترابا واباؤنا ائنا لمخرجون","dt":"[67] وقال الذين جحدوا وحدانيه الله: انحن واباؤنا مبعوثون احياء كهيئتنا من بعد مماتنا بعد ان صرنا ترابا؟"},{"id":"3227","s":27,"a":68,"at":"لقد وعدنا هذا نحن واباؤنا من قبل ان هذا الا اساطير الاولين","dt":"[68] لقد وعدنا هذا البعث نحن واباؤنا من قبل، فلم نر له حقيقه ولا وقوعا، ما هذا الوعد الا مما سطره الاولون من الاكاذيب في كتبهم وافتروه."},{"id":"3228","s":27,"a":69,"at":"قل سيروا في الارض فانظروا كيف كان عاقبه المجرمين","dt":"[69] قل -ايها الرسول- لهؤلاء المكذبين: سيروا في الارض، فانظروا الى ديار من كان قبلكم من المجرمين، كيف كان عاقبه المكذبين للرسل؟ اهلكهم الله بتكذيبهم، والله فاعل بكم مثلهم ان لم تؤمنوا."},{"id":"3229","s":27,"a":70,"at":"ولا تحزن عليهم ولا تكن في ضيق مما يمكرون","dt":"[70] ولا تحزن على اعراض المشركين عنك وتكذيبهم لك، ولا يضق صدرك من مكرهم بك، فان الله ناصرك عليهم."},{"id":"3230","s":27,"a":71,"at":"ويقولون متى هذا الوعد ان كنتم صادقين","dt":"[71] ويقول مشركو قومك -ايها الرسول-: متى يكون هذا الوعد بالعذاب الذي تعدنا به انت واتباعك ان كنتم صادقين فيما تعدوننا به؟"},{"id":"3231","s":27,"a":72,"at":"قل عسى ان يكون ردف لكم بعض الذي تستعجلون","dt":"[72] قل لهم -ايها الرسول-: عسى ان يكون قد اقترب لكم بعض الذي تستعجلون من عذاب الله."},{"id":"3232","s":27,"a":73,"at":"وان ربك لذو فضل على الناس ولكن اكثرهم لا يشكرون","dt":"[73] وان ربك لذو فضل على الناس؛ بتركه معاجلتهم بالعقوبه على معصيتهم اياه وكفرهم به، ولكن اكثرهم لا يشكرون له على ذلك، فيؤمنوا به ويخلصوا له العباده."},{"id":"3233","s":27,"a":74,"at":"وان ربك ليعلم ما تكن صدورهم وما يعلنون","dt":"[74] وان ربك ليعلم ما تخفيه صدور خلقه وما يظهرونه."},{"id":"3234","s":27,"a":75,"at":"وما من غائبه في السماء والارض الا في كتاب مبين","dt":"[75] وما من شيء غائب عن ابصار الخلق في السماء والارض الا في كتاب واضح عند الله وهو اللوح المحفوظ. قد احاط ذلك الكتاب بجميع ما كان وما يكون."},{"id":"3235","s":27,"a":76,"at":"ان هذا القران يقص على بني اسرائيل اكثر الذي هم فيه يختلفون","dt":"[76] ان هذا القران يقص على بني اسرائيل الحق في اكثر الاشياء التي اختلفوا فيها."},{"id":"3236","s":27,"a":77,"at":"وانه لهدى ورحمه للمؤمنين","dt":"[77] وان هذا القران لهدايه من الضلال ورحمه من العذاب، لمن صدق به واهتدى بهداه."},{"id":"3237","s":27,"a":78,"at":"ان ربك يقضي بينهم بحكمه وهو العزيز العليم","dt":"[78] ان ربك يقضي بين المختلفين من بني اسرائيل وغيرهم بحكمه فيهم، فينتقم من المبطل، ويجازي المحسن. وهو العزيز الغالب، فلا يرد قضاؤه، العليم فلا يلتبس عليه حق بباطل."},{"id":"3238","s":27,"a":79,"at":"فتوكل على الله انك على الحق المبين","dt":"[79] فاعتمد -ايها الرسول- في كل امورك على الله، وثق به؛ فانه كافيك، انك على الحق الواضح الذي لا شك فيه."},{"id":"3239","s":27,"a":80,"at":"انك لا تسمع الموتى ولا تسمع الصم الدعاء اذا ولوا مدبرين","dt":"[80] انك -ايها الرسول- لا تقدر ان تسمع الحق من طبع الله على قلبه فاماته، ولا تسمع دعوتك من اصم الله سمعه عن سماع الحق عند ادبارهم معرضين عنك؛ فان الاصم لا يسمع الدعاء اذا كان مقبلا، فكيف اذا كان معرضا عنه موليا مدبرا؟"},{"id":"3240","s":27,"a":81,"at":"وما انت بهادي العمي عن ضلالتهم ان تسمع الا من يؤمن باياتنا فهم مسلمون","dt":"[81] وما انت -ايها الرسول- بهاد عن الضلاله من اعماه الله عن الهدى والرشاد، ولا يمكنك ان تسمع الا من يصدق باياتنا، فهم مسلمون مطيعون، مستجيبون لما دعوتهم اليه."},{"id":"3241","s":27,"a":82,"at":"واذا وقع القول عليهم اخرجنا لهم دابه من الارض تكلمهم ان الناس كانوا باياتنا لا يوقنون","dt":"[82] واذا وجب العذاب عليهم؛ لتماديهم في المعاصي والطغيان، واعراضهم عن شرع الله وحكمه، حتى صاروا من شرار خلقه، اخرجنا لهم من الارض في اخر الزمان علامه من علامات الساعه الكبرى، وهي «الدابه»، تحدثهم ان الناس المنكرين للبعث كانوا بالقران ومحمد -صلى الله عليه وسلم- ودينه لا يصدقون ولا يعملون."},{"id":"3242","s":27,"a":83,"at":"ويوم نحشر من كل امه فوجا ممن يكذب باياتنا فهم يوزعون","dt":"[83] ويوم نجمع يوم الحشر من كل امه جماعه ممن يكذب بادلتنا وحججنا، يحبس اولهم على اخرهم؛ ليجتمعوا كلهم، ثم يساقون الى الحساب."},{"id":"3243","s":27,"a":84,"at":"حتى اذا جاءوا قال اكذبتم باياتي ولم تحيطوا بها علما اماذا كنتم تعملون","dt":"[84] حتى اذا جاء من كل امه فوج ممن يكذب باياتنا فاجتمعوا قال الله: اكذبتم باياتي التي انزلتها على رسلي، وبالايات التي اقمتها دلاله على توحيدي واستحقاقي وحدي للعباده، ولم تحيطوا علما ببطلانها، حتى تعرضوا عنها وتكذبوا بها، ام اي شيء كنتم تعملون؟"},{"id":"3244","s":27,"a":85,"at":"ووقع القول عليهم بما ظلموا فهم لا ينطقون","dt":"[85] وحقت عليهم كلمه العذاب؛ بسبب ظلمهم وتكذيبهم، فهم لا ينطقون بحجه يدفعون بها عن انفسهم ما حل بهم من سوء العذاب."},{"id":"3245","s":27,"a":86,"at":"الم يروا انا جعلنا الليل ليسكنوا فيه والنهار مبصرا ان في ذلك لايات لقوم يؤمنون","dt":"[86] الم ير هؤلاء المكذبون باياتنا انا جعلنا الليل يستقرون فيه وينامون، والنهار يبصرون فيه للسعي في معاشهم؟ ان في تصريفهما لدلاله لقوم يؤمنون بكمال قدره الله ووحدانيته وعظيم نعمه."},{"id":"3246","s":27,"a":87,"at":"ويوم ينفخ في الصور ففزع من في السموات ومن في الارض الا من شاء الله وكل اتوه داخرين","dt":"[87] واذكر -ايها الرسول- يوم ينفخ الملك في «القرن» ففزع من في السموات ومن في الارض فزعا شديدا من هول النفخه، الا من استثناه الله ممن اكرمه وحفظه من الفزع، وكل المخلوقات ياتون الى ربهم صاغرين مطيعين."},{"id":"3247","s":27,"a":88,"at":"وترى الجبال تحسبها جامده وهي تمر مر السحاب صنع الله الذي اتقن كل شيء انه خبير بما تفعلون","dt":"[88] وترى الجبال تظنها واقفه مستقره، وهي تسير سيرا حثيثا كسير السحاب الذي تسيره الرياح، وهذا من صنع الله الذي احسن كل شيء خلقه واتقنه. ان الله خبير بما تفعلون ايها الناس من خير وشر، وسيجازيكم على ذلك."},{"id":"3248","s":27,"a":89,"at":"من جاء بالحسنه فله خير منها وهم من فزع يومئذ امنون","dt":"[89] من جاء بتوحيد الله والايمان به وعبادته وحده، والاعمال الصالحه يوم القيامه، فله عند الله من الاجر العظيم ما هو خير منها وافضل، وهو الجنه، وهم يوم الفزع الاكبر امنون."},{"id":"3249","s":27,"a":90,"at":"ومن جاء بالسيئه فكبت وجوههم في النار هل تجزون الا ما كنتم تعملون","dt":"[90] ومن جاء بالشرك والاعمال السيئه المنكره، فجزاؤهم ان يكبهم الله على وجوههم في النار يوم القيامه، ويقال لهم توبيخا: هل تجزون الا ما كنتم تعملون في الدنيا؟"},{"id":"3250","s":27,"a":91,"at":"انما امرت ان اعبد رب هذه البلده الذي حرمها وله كل شيء وامرت ان اكون من المسلمين","dt":"[91] قل -ايها الرسول- للناس: انما امرت ان اعبد رب هذه البلده -وهي «مكه»- الذي حرمها على خلقه ان يسفكوا فيها دما حراما، او يظلموا فيها احدا، او يصيدوا صيدها، او يقطعوا شجرها، وله سبحانه كل شيء، وامرت ان اعبده وحده دون من سواه، وامرت ان اكون من المنقادين لامره، المبادرين لطاعته،"},{"id":"3251","s":27,"a":92,"at":"وان اتلو القران فمن اهتدى فانما يهتدي لنفسه ومن ضل فقل انما انا من المنذرين","dt":"[92] وان اتلو القران على الناس، فمن اهتدى بما فيه واتبع ما جئت به، فانما خير ذلك وجزاؤه لنفسه، ومن ضل عن الحق فقل -ايها الرسول-: انما انا نذير لكم من عذاب الله وعقابه ان لم تؤمنوا، فانا واحد من الرسل الذين انذروا قومهم، وليس بيدي من الهدايه شيء."},{"id":"3252","s":27,"a":93,"at":"وقل الحمد لله سيريكم اياته فتعرفونها وما ربك بغافل عما تعملون","dt":"[93] وقل -ايها الرسول-: الثناء الجميل لله، سيريكم اياته في انفسكم وفي السماء والارض، فتعرفونها معرفه تدلكم على الحق وتبين لكم الباطل، وما ربك بغافل عما تعملون، وسيجازيكم على ذلك."},{"id":"3253","s":28,"a":1,"at":"طسم","dt":"[1] طسم سبق الكلام على الحروف المقطعه في اول سوره البقره."},{"id":"3254","s":28,"a":2,"at":"تلك ايات الكتاب المبين","dt":"[2] هذه ايات القران الذي انزلته اليك -ايها الرسول-، مبينا لكل ما يحتاج اليه العباد في دنياهم واخراهم."},{"id":"3255","s":28,"a":3,"at":"نتلوا عليك من نبا موسى وفرعون بالحق لقوم يؤمنون","dt":"[3] نقص عليك من خبر موسى وفرعون بالصدق لقوم يؤمنون بهذا القران، ويصدقون بانه من عند الله، ويعملون بهديه."},{"id":"3256","s":28,"a":4,"at":"ان فرعون علا في الارض وجعل اهلها شيعا يستضعف طائفه منهم يذبح ابناءهم ويستحيي نساءهم انه كان من المفسدين","dt":"[4] ان فرعون تكبر وطغى في الارض، وجعل اهلها طوائف متفرقه، يستضعف طائفه منهم، وهم بنو اسرائيل، يذبح ابناءهم، ويستبقي نساءهم؛ للخدمه والامتهان، انه كان من المفسدين في الارض."},{"id":"3257","s":28,"a":5,"at":"ونريد ان نمن على الذين استضعفوا في الارض ونجعلهم ائمه ونجعلهم الوارثين","dt":"[5] ونريد ان نتفضل على الذين استضعفهم فرعون في الارض، ونجعلهم قاده في الخير ودعاه اليه، ونجعلهم يرثون الارض بعد هلاك فرعون وقومه."},{"id":"3258","s":28,"a":6,"at":"ونمكن لهم في الارض ونري فرعون وهامان وجنودهما منهم ما كانوا يحذرون","dt":"[6] ونمكن لهم في الارض، ونجعل فرعون وهامان وجنودهما يرون من هذه الطائفه المستضعفه ما كانوا يخافونه من هلاكهم وذهاب ملكهم، واخراجهم من ديارهم على يد مولود من بني اسرائيل."},{"id":"3259","s":28,"a":7,"at":"واوحينا الى ام موسى ان ارضعيه فاذا خفت عليه فالقيه في اليم ولا تخافي ولا تحزني انا رادوه اليك وجاعلوه من المرسلين","dt":"[7] والهمنا ام موسى حين ولدته وخشيت عليه ان يذبحه فرعون كما يذبح ابناء بني اسرائيل: ان ارضعيه مطمئنه، فاذا خشيت ان يعرف امره فضعيه في صندوق والقيه في النيل، دون خوف من فرعون وقومه ان يقتلوه، ودون حزن على فراقه، انا رادو ولدك اليك وباعثوه رسولا"},{"id":"3260","s":28,"a":8,"at":"فالتقطه ال فرعون ليكون لهم عدوا وحزنا ان فرعون وهامان وجنودهما كانوا خاطئين","dt":"[8] فوضعته في صندوق والقته في النيل، فعثر عليه اعوان فرعون واخذوه، فكانت عاقبه ذلك ما قدره الله بان يكون موسى عدوا لهم بمخالفه دينهم، وموقعا لهم في الحزن باغراقهم وزوال ملكهم على يده. ان فرعون وهامان واعوانهما كانوا اثمين مشركين."},{"id":"3261","s":28,"a":9,"at":"وقالت امراه فرعون قره عين لي ولك لا تقتلوه عسى ان ينفعنا او نتخذه ولدا وهم لا يشعرون","dt":"[9] ولما شاهدته امراه فرعون القى الله محبته في قلبها، وقالت لفرعون: هذا الطفل سيكون مصدر سرور لي ولك، لا تقتلوه؛ فقد نصيب منه خيرا او نتخذه ولدا، وفرعون واله لا يدركون ان هلاكهم على يديه."},{"id":"3262","s":28,"a":10,"at":"واصبح فؤاد ام موسى فارغا ان كادت لتبدي به لولا ان ربطنا على قلبها لتكون من المؤمنين","dt":"[10] واصبح فؤاد ام موسى خاليا من كل شيء في الدنيا الا من هم موسى وذكره، وقاربت ان تظهر انه ابنها لولا ان ثبتناها، فصبرت ولم تبد به؛ لتكون من المؤمنين بوعد الله الموقنين به."},{"id":"3263","s":28,"a":11,"at":"وقالت لاخته قصيه فبصرت به عن جنب وهم لا يشعرون","dt":"[11] وقالت ام موسى لاخته حين القته في اليم: اتبعي اثر موسى كيف يصنع به؟ فتتبعت اثره فابصرته عن بعد، وقوم فرعون لا يعرفون انها اخته، وانها تتبع خبره."},{"id":"3264","s":28,"a":12,"at":"وحرمنا عليه المراضع من قبل فقالت هل ادلكم على اهل بيت يكفلونه لكم وهم له ناصحون","dt":"[12] وحرمنا على موسى المراضع ان يرتضع منهن من قبل ان نرده الى امه، فقالت اخته: هل ادلكم على اهل بيت يحسنون تربيته وارضاعه، وهم مشفقون عليه؟ فاجابوها الى ذلك."},{"id":"3265","s":28,"a":13,"at":"فرددناه الى امه كي تقر عينها ولا تحزن ولتعلم ان وعد الله حق ولكن اكثرهم لا يعلمون","dt":"[13] فرددنا موسى الى امه؛ كي تقر عينها به، ووفينا لها بالوعد؛ اذ رجع اليها سليما من قتل فرعون، ولا تحزن على فراقه، ولتعلم ان وعد الله حق فيما وعدها من رده اليها وجعله من المرسلين. ان الله لا يخلف وعده، ولكن اكثر المشركين لا يعلمون ان وعد الله حق."},{"id":"3266","s":28,"a":14,"at":"ولما بلغ اشده واستوى اتيناه حكما وعلما وكذلك نجزي المحسنين","dt":"[14] ولما بلغ موسى اشد قوته وتكامل عقله، اتيناه حكما وعلما يعرف بهما الاحكام الشرعيه، وكما جزينا موسى على طاعته واحسانه نجزي من احسن من عبادنا."},{"id":"3267","s":28,"a":15,"at":"ودخل المدينه على حين غفله من اهلها فوجد فيها رجلين يقتتلان هذا من شيعته وهذا من عدوه فاستغاثه الذي من شيعته على الذي من عدوه فوكزه موسى فقضى عليه قال هذا من عمل الشيطان انه عدو مضل مبين","dt":"[15] ودخل موسى المدينه مستخفيا وقت غفله اهلها، فوجد فيها رجلين يقتتلان: احدهما من قوم موسى من بني اسرائيل، والاخر من قوم فرعون، فطلب الذي من قوم موسى النصر على الذي من عدوه، فضربه موسى بجمع كفه فمات، قال موسى حين قتله: هذا من نزغ الشيطان، بان هيج غضبي، حتى ضربت هذا فهلك، ان الشيطان عدو لابن ادم، مضل عن سبيل الرشاد، ظاهر العداوه. وهذا العمل من موسى عليه السلام كان قبل النبوه."},{"id":"3268","s":28,"a":16,"at":"قال رب اني ظلمت نفسي فاغفر لي فغفر له انه هو الغفور الرحيم","dt":"[16] قال موسى: رب اني ظلمت نفسي بقتل النفس التي لم تامرني بقتلها فاغفر لي ذلك الذنب، فغفر الله له. ان الله غفور لذنوب عباده، رحيم بهم."},{"id":"3269","s":28,"a":17,"at":"قال رب بما انعمت علي فلن اكون ظهيرا للمجرمين","dt":"[17] قال موسى: رب بما انعمت علي بالتوبه والمغفره والنعم الكثيره، فلن اكون معينا لاحد على معصيته واجرامه."},{"id":"3270","s":28,"a":18,"at":"فاصبح في المدينه خائفا يترقب فاذا الذي استنصره بالامس يستصرخه قال له موسى انك لغوي مبين","dt":"[18] فاصبح موسى في مدينه فرعون خائفا يترقب الاخبار مما يتحدث به الناس في امره وامر قتيله، فراى صاحبه بالامس يقاتل قبطيا اخر، ويطلب منه النصر، قال له موسى: انك لكثير الغوايه ظاهر الضلال."},{"id":"3271","s":28,"a":19,"at":"فلما ان اراد ان يبطش بالذي هو عدو لهما قال ياموسى اتريد ان تقتلني كما قتلت نفسا بالامس ان تريد الا ان تكون جبارا في الارض وما تريد ان تكون من المصلحين","dt":"[19] فلما ان اراد موسى ان يبطش بالقبطي، قال: يا موسى اتريد ان تقتلني كما قتلت نفسا بالامس؟ ما تريد الا ان تكون طاغيه في الارض، وما تريد ان تكون من الذين يصلحون بين الناس."},{"id":"3272","s":28,"a":20,"at":"وجاء رجل من اقصى المدينه يسعى قال ياموسى ان الملا ياتمرون بك ليقتلوك فاخرج اني لك من الناصحين","dt":"[20] وجاء رجل من اخر المدينه يسعى، قال يا موسى: ان اشراف قوم فرعون يتامرون على قتلك ويتشاورون، فاخرج من هذه المدينه، اني لك من الناصحين المشفقين عليك."},{"id":"3273","s":28,"a":21,"at":"فخرج منها خائفا يترقب قال رب نجني من القوم الظالمين","dt":"[21] فخرج موسى من مدينه فرعون خائفا ينتظر الطلب ان يدركه فياخذه، فدعا الله ان ينقذه من القوم الظالمين."},{"id":"3274","s":28,"a":22,"at":"ولما توجه تلقاء مدين قال عسى ربي ان يهديني سواء السبيل","dt":"[22] ولما قصد موسى بلاد «مدين» وخرج من سلطان فرعون قال: عسى ربي ان يرشدني خير طريق الى «مدين»."},{"id":"3275","s":28,"a":23,"at":"ولما ورد ماء مدين وجد عليه امه من الناس يسقون ووجد من دونهم امراتين تذودان قال ما خطبكما قالتا لا نسقي حتى يصدر الرعاء وابونا شيخ كبير","dt":"[23] ولما وصل ماء «مدين» وجد عليه جماعه من الناس يسقون مواشيهم، ووجد من دون تلك الجماعه امراتين منفردتين عن الناس، تحبسان غنمهما عن الماء؛ لعجزهما وضعفهما عن مزاحمه الرجال، وتنتظران حتى تصدر عنه مواشي الناس، ثم تسقيان ماشيتهما، فلما راهما موسى -عليه السلام- رق لهما، ثم قال: ما شانكما؟ قالتا: لا نستطيع مزاحمه الرجال، ولا نسقي حتى يسقي الناس، وابونا شيخ كبير، لا يستطيع ان يسقي ماشيته؛ لضعفه وكبره."},{"id":"3276","s":28,"a":24,"at":"فسقى لهما ثم تولى الى الظل فقال رب اني لما انزلت الي من خير فقير","dt":"[24] فسقى موسى للمراتين ماشيتهما، ثم تولى الى ظل شجره فاستظل بها وقال: رب اني مفتقر الى ما تسوقه الي من اي خير كان، كالطعام. وكان قد اشتد به الجوع."},{"id":"3277","s":28,"a":25,"at":"فجاءته احداهما تمشي على استحياء قالت ان ابي يدعوك ليجزيك اجر ما سقيت لنا فلما جاءه وقص عليه القصص قال لا تخف نجوت من القوم الظالمين","dt":"[25] فجاءت احدى المراتين اللتين سقى لهما تسير اليه في حياء، قالت: ان ابي يدعوك ليعطيك اجر ما سقيت لنا، فمضى موسى معها الى ابيها، فلما جاء اباها وقص عليه قصصه مع فرعون وقومه، قال له ابوها: لا تخف نجوت من القوم الظالمين، وهم فرعون وقومه؛ اذ لا سلطان لهم بارضنا."},{"id":"3278","s":28,"a":26,"at":"قالت احداهما ياابت استاجره ان خير من استاجرت القوي الامين","dt":"[26] قالت احدى المراتين لابيها: يا ابت استاجره ليرعى لك ماشيتك؛ ان خير من تستاجره للرعي القوي على حفظ ماشيتك، الامين الذي لا تخاف خيانته فيما تامنه عليه."},{"id":"3279","s":28,"a":27,"at":"قال اني اريد ان انكحك احدى ابنتي هاتين على ان تاجرني ثماني حجج فان اتممت عشرا فمن عندك وما اريد ان اشق عليك ستجدني ان شاء الله من الصالحين","dt":"[27] قال الشيخ لموسى: اني اريد ان ازوجك احدى ابنتي هاتين، على ان تكون اجيرا لي في رعي ماشيتي ثماني سنين مقابل ذلك، فان اكملت عشر سنين فاحسان من عندك، وما اريد ان اشق عليك بجعلها عشرا، ستجدني ان شاء الله من الصالحين في حسن الصحبه والوفاء بما قلت."},{"id":"3280","s":28,"a":28,"at":"قال ذلك بيني وبينك ايما الاجلين قضيت فلا عدوان علي والله على ما نقول وكيل","dt":"[28] قال موسى: ذلك الذي قلته قائم بيني وبينك، اي المدتين اقضها في العمل اكن قد وفيتك، فلا اطالب بزياده عليها، والله على ما نقول وكيل حافظ يراقبنا، ويعلم ما تعاقدنا عليه."},{"id":"3281","s":28,"a":29,"at":"فلما قضى موسى الاجل وسار باهله انس من جانب الطور نارا قال لاهله امكثوا اني انست نارا لعلي اتيكم منها بخبر او جذوه من النار لعلكم تصطلون","dt":"[29] فلما وفى نبي الله موسى -عليه السلام- صاحبه المده عشر سنين -وهي اكمل المدتين- وسار باهله الى «مصر» ابصر من جانب الطور نارا، قال موسى لاهله: تمهلوا وانتظروا اني ابصرت نارا؛ لعلي اتيكم منها بنبا، او اتيكم بشعله من النار لعلكم تستدفئون بها."},{"id":"3282","s":28,"a":30,"at":"فلما اتاها نودي من شاطئ الواد الايمن في البقعه المباركه من الشجره ان ياموسى اني انا الله رب العالمين","dt":"[30] فلما اتى موسى النار ناداه الله من جانب الوادي الايمن لموسى في البقعه المباركه من جانب الشجره: ان يا موسى اني انا الله رب العالمين،"},{"id":"3283","s":28,"a":31,"at":"وان الق عصاك فلما راها تهتز كانها جان ولى مدبرا ولم يعقب ياموسى اقبل ولا تخف انك من الامنين","dt":"[31] وان الق عصاك، فالقاها موسى، فصارت حيه تسعى، فلما راها موسى تضطرب كانها جان من الحيات ولى هاربا منها، ولم يلتفت من الخوف، فناداه ربه: يا موسى اقبل الي ولا تخف؛ انك من الامنين من كل مكروه."},{"id":"3284","s":28,"a":32,"at":"اسلك يدك في جيبك تخرج بيضاء من غير سوء واضمم اليك جناحك من الرهب فذانك برهانان من ربك الى فرعون وملئه انهم كانوا قوما فاسقين","dt":"[32] ادخل يدك في فتحه قميصك المفتوحه الى الصدر، واخرجها تخرج بيضاء كالثلج من غير مرض ولا برص، واضمم اليك يدك لتامن من الخوف، فهاتان اللتان اريتكهما يا موسى: من تحول العصا حيه، وجعل يدك بيضاء تلمع من غير مرض ولا برص، ايتان من ربك الى فرعون واشراف قومه. ان فرعون وملاه كانوا قوما كافرين."},{"id":"3285","s":28,"a":33,"at":"قال رب اني قتلت منهم نفسا فاخاف ان يقتلون","dt":"[33، 34] قال موسى: رب اني قتلت من قوم فرعون نفسا فاخاف ان يقتلوني، واخي هارون هو افصح مني نطقا، فارسله معي عونا يصدقني، ويبين لهم عني ما اخاطبهم به، اني اخاف ان يكذبوني في قولي لهم: اني ارسلت اليهم."},{"id":"3286","s":28,"a":34,"at":"واخي هارون هو افصح مني لسانا فارسله معي ردءا يصدقني اني اخاف ان يكذبون","dt":"[33، 34] قال موسى: رب اني قتلت من قوم فرعون نفسا فاخاف ان يقتلوني، واخي هارون هو افصح مني نطقا، فارسله معي عونا يصدقني، ويبين لهم عني ما اخاطبهم به، اني اخاف ان يكذبوني في قولي لهم: اني ارسلت اليهم."},{"id":"3287","s":28,"a":35,"at":"قال سنشد عضدك باخيك ونجعل لكما سلطانا فلا يصلون اليكما باياتنا انتما ومن اتبعكما الغالبون","dt":"[35] قال الله لموسى: سنقويك باخيك، ونجعل لكما حجه على فرعون وقومه فلا يصلون اليكما بسوء. انتما -يا موسى وهارون- ومن امن بكما المنتصرون على فرعون وقومه؛ بسبب اياتنا وما دلت عليه من الحق."},{"id":"3288","s":28,"a":36,"at":"فلما جاءهم موسى باياتنا بينات قالوا ما هذا الا سحر مفترى وما سمعنا بهذا في ابائنا الاولين","dt":"[36] فلما جاء موسى فرعون وملاه بادلتنا وحججنا شاهده بحقيقه ما جاء به موسى من عند ربه، قالوا لموسى: ما هذا الذي جئتنا به الا سحر افتريته كذبا وباطلا، وما سمعنا بهذا الذي تدعونا اليه في اسلافنا الذين مضوا قبلنا."},{"id":"3289","s":28,"a":37,"at":"وقال موسى ربي اعلم بمن جاء بالهدى من عنده ومن تكون له عاقبه الدار انه لا يفلح الظالمون","dt":"[37] وقال موسى لفرعون: ربي اعلم بالمحق منا الذي جاء بالرشاد من عنده، ومن الذي له العقبى المحموده في الدار الاخره، انه لا يظفر الظالمون بمطلوبهم."},{"id":"3290","s":28,"a":38,"at":"وقال فرعون ياايها الملا ما علمت لكم من اله غيري فاوقد لي ياهامان على الطين فاجعل لي صرحا لعلي اطلع الى اله موسى واني لاظنه من الكاذبين","dt":"[38] وقال فرعون لاشراف قومه: يا ايها الملا ما علمت لكم من اله غيري يستحق العباده، فاشعل لي -يا هامان- على الطين نارا، حتى يشتد، وابن لي بناء عاليا؛ لعلي انظر الى معبود موسى الذي يعبده ويدعو الى عبادته، واني لاظنه فيما يقول من الكاذبين."},{"id":"3291","s":28,"a":39,"at":"واستكبر هو وجنوده في الارض بغير الحق وظنوا انهم الينا لا يرجعون","dt":"[39] واستعلى فرعون وجنوده في ارض «مصر» بغير الحق عن تصديق موسى واتباعه على ما دعاهم اليه، وحسبوا انهم بعد مماتهم لا يبعثون."},{"id":"3292","s":28,"a":40,"at":"فاخذناه وجنوده فنبذناهم في اليم فانظر كيف كان عاقبه الظالمين","dt":"[40] فاخذنا فرعون وجنوده، فالقيناهم جميعا في البحر واغرقناهم، فانظر -ايها الرسول- كيف كان نهايه هؤلاء الذين ظلموا انفسهم، فكفروا بربهم؟"},{"id":"3293","s":28,"a":41,"at":"وجعلناهم ائمه يدعون الى النار ويوم القيامه لا ينصرون","dt":"[41] وجعلنا فرعون وقومه قاده الى النار، يقتدي بهم اهل الكفر والفسق، ويوم القيامه لا ينصرون؛ وذلك بسبب كفرهم وتكذيبهم رسول ربهم واصرارهم على ذلك."},{"id":"3294","s":28,"a":42,"at":"واتبعناهم في هذه الدنيا لعنه ويوم القيامه هم من المقبوحين","dt":"[42] واتبعنا فرعون وقومه في هذه الدنيا خزيا وغضبا منا عليهم، ويوم القيامه هم من المستقذره افعالهم، المبعدين عن رحمه الله."},{"id":"3295","s":28,"a":43,"at":"ولقد اتينا موسى الكتاب من بعد ما اهلكنا القرون الاولى بصائر للناس وهدى ورحمه لعلهم يتذكرون","dt":"[43] ولقد اتينا موسى التوراه من بعد ما اهلكنا الامم التي كانت من قبله -كقوم نوح وعاد وثمود وقوم لوط واصحاب «مدين»- حال كون التوراه بصائر لبني اسرائيل، يبصرون بها ما ينفعهم وما يضرهم، وفيها رحمه لمن عمل بها منهم؛ لعلهم يتذكرون نعم الله عليهم، فيشكروه عليها، ولا يكفروه."},{"id":"3296","s":28,"a":44,"at":"وما كنت بجانب الغربي اذ قضينا الى موسى الامر وما كنت من الشاهدين","dt":"[44] وما كنت -ايها الرسول- بجانب الجبل الغربي من موسى اذ كلفناه امرنا ونهينا، وما كنت من الشاهدين لذلك، حتى يقال: انه وصل اليك من هذا الطريق."},{"id":"3297","s":28,"a":45,"at":"ولكنا انشانا قرونا فتطاول عليهم العمر وما كنت ثاويا في اهل مدين تتلو عليهم اياتنا ولكنا كنا مرسلين","dt":"[45] ولكنا خلقنا امما من بعد موسى، فمكثوا زمنا طويلا، فنسوا عهد الله، وتركوا امره، وما كنت مقيما في اهل «مدين» تقرا عليهم كتابنا، فتعرف قصتهم وتخبر بها، ولكن ذلك الخبر الذي جئت به عن موسى وحي، وشاهد على رسالتك."},{"id":"3298","s":28,"a":46,"at":"وما كنت بجانب الطور اذ نادينا ولكن رحمه من ربك لتنذر قوما ما اتاهم من نذير من قبلك لعلهم يتذكرون","dt":"[46] وما كنت -ايها الرسول- بجانب جبل الطور حين نادينا موسى، ولم تشهد شيئا من ذلك فتعلمه، ولكنا ارسلناك رحمه من ربك؛ لتنذر قوما لم ياتهم من قبلك من نذير؛ لعلهم يتذكرون الخير الذي جئت به فيفعلوه، والشر الذي نهيت عنه فيجتنبوه."},{"id":"3299","s":28,"a":47,"at":"ولولا ان تصيبهم مصيبه بما قدمت ايديهم فيقولوا ربنا لولا ارسلت الينا رسولا فنتبع اياتك ونكون من المؤمنين","dt":"[47] ولولا ان ينزل بهؤلاء الكفار عذاب بسبب كفرهم بربهم، فيقولوا: ربنا هلا ارسلت الينا رسولا من قبل، فنتبع اياتك المنزله في كتابك، ونكون من المؤمنين بك."},{"id":"3300","s":28,"a":48,"at":"فلما جاءهم الحق من عندنا قالوا لولا اوتي مثل ما اوتي موسى او لم يكفروا بما اوتي موسى من قبل قالوا سحران تظاهرا وقالوا انا بكل كافرون","dt":"[48] فلما جاء محمد هؤلاء القوم نذيرا لهم، قالوا: هلا اوتي هذا الذي ارسل الينا مثل ما اوتي موسى من معجزات حسيه، وكتاب نزل جمله واحده! قل -ايها الرسول- لهم: او لم يكفر اليهود بما اوتي موسى من قبل؟ قالوا: في التوراه والقران سحران تعاونا في سحرهما، وقالوا: نحن بكل منهما كافرون."},{"id":"3301","s":28,"a":49,"at":"قل فاتوا بكتاب من عند الله هو اهدى منهما اتبعه ان كنتم صادقين","dt":"[49] قل -ايها الرسول- لهؤلاء: فاتوا بكتاب من عند الله هو اقوم من التوراه والقران اتبعه، ان كنتم صادقين في زعمكم."},{"id":"3302","s":28,"a":50,"at":"فان لم يستجيبوا لك فاعلم انما يتبعون اهواءهم ومن اضل ممن اتبع هواه بغير هدى من الله ان الله لا يهدي القوم الظالمين","dt":"[50] فان لم يستجيبوا لك بالاتيان بالكتاب، ولم تبق لهم حجه، فاعلم انما يتبعون اهواءهم، ولا احد اكثر ضلالا ممن اتبع هواه بغير هدى من الله. ان الله لا يوفق لاصابه الحق القوم الظالمين الذين خالفوا امر الله، وتجاوزوا حدوده."},{"id":"3303","s":28,"a":51,"at":"ولقد وصلنا لهم القول لعلهم يتذكرون","dt":"[51] ولقد فصلنا وبينا القران رحمه بقومك ايها الرسول؛ لعلهم يتذكرون، فيتعظوا به."},{"id":"3304","s":28,"a":52,"at":"الذين اتيناهم الكتاب من قبله هم به يؤمنون","dt":"[52] الذين اتيناهم الكتاب من قبل القران -وهم اليهود والنصارى الذين لم يبدلوا- يؤمنون بالقران وبمحمد عليه الصلاه والسلام."},{"id":"3305","s":28,"a":53,"at":"واذا يتلى عليهم قالوا امنا به انه الحق من ربنا انا كنا من قبله مسلمين","dt":"[53] واذا يتلى هذا القران على الذين اتيناهم الكتاب، قالوا: صدقنا به، وعملنا بما فيه، انه الحق من عند ربنا، انا كنا من قبل نزوله مسلمين موحدين، فدين الله واحد، وهو الاسلام."},{"id":"3306","s":28,"a":54,"at":"اولئك يؤتون اجرهم مرتين بما صبروا ويدرءون بالحسنه السيئه ومما رزقناهم ينفقون","dt":"[54] هؤلاء الذين تقدمت صفتهم يؤتون ثواب عملهم مرتين: على الايمان بكتابهم، وعلى ايمانهم بالقران بما صبروا، ومن اوصافهم انهم يدفعون السيئه بالحسنه، ومما رزقناهم ينفقون في سبيل الخير والبر"},{"id":"3307","s":28,"a":55,"at":"واذا سمعوا اللغو اعرضوا عنه وقالوا لنا اعمالنا ولكم اعمالكم سلام عليكم لا نبتغي الجاهلين","dt":"[55] . واذا سمع هؤلاء القوم الباطل من القول لم يصغوا اليه، وقالوا: لنا اعمالنا لا نحيد عنها، ولكم اعمالكم ووزرها عليكم، فنحن لا نشغل انفسنا بالرد عليكم، ولا تسمعون منا الا الخير، ولا نخاطبكم بمقتضى جهلكم؛ لاننا لا نريد طريق الجاهلين ولا نحبها. وهذا من خير ما يقوله الدعاه الى الله."},{"id":"3308","s":28,"a":56,"at":"انك لا تهدي من احببت ولكن الله يهدي من يشاء وهو اعلم بالمهتدين","dt":"[56] انك -ايها الرسول- لا تهدي هدايه توفيق من احببت هدايته، ولكن ذلك بيد الله يهدي من يشاء ان يهديه للايمان، ويوفقه اليه، وهو اعلم بمن يصلح للهدايه فيهديه."},{"id":"3309","s":28,"a":57,"at":"وقالوا ان نتبع الهدى معك نتخطف من ارضنا او لم نمكن لهم حرما امنا يجبى اليه ثمرات كل شيء رزقا من لدنا ولكن اكثرهم لا يعلمون","dt":"[57] وقال كفار «مكه»: ان نتبع الحق الذي جئتنا به، ونتبرا من الاولياء والالهه، نتخطف من ارضنا بالقتل والاسر ونهب الاموال، اولم نجعلهم متمكنين في بلد امن، حرمنا على الناس سفك الدماء فيه، يجلب اليه ثمرات كل شيء رزقا من لدنا؟ ولكن اكثر هؤلاء المشركين لا يعلمون قدر هذه النعم عليهم، فيشكروا من انعم عليهم بها ويطيعوه."},{"id":"3310","s":28,"a":58,"at":"وكم اهلكنا من قريه بطرت معيشتها فتلك مساكنهم لم تسكن من بعدهم الا قليلا وكنا نحن الوارثين","dt":"[58] وكثير من اهل القرى اهلكناهم حين الهتهم معيشتهم عن الايمان بالرسل، فكفروا وطغوا، فتلك مساكنهم لم تسكن من بعدهم الا قليلا منها، وكنا نحن الوارثين للعباد نميتهم، ثم يرجعون الينا، فنجازيهم باعمالهم."},{"id":"3311","s":28,"a":59,"at":"وما كان ربك مهلك القرى حتى يبعث في امها رسولا يتلو عليهم اياتنا وما كنا مهلكي القرى الا واهلها ظالمون","dt":"[59] وما كان ربك -ايها الرسول- مهلك القرى التي حول «مكه» في زمانك حتى يبعث في امها -وهي «مكه»- رسولا، يتلو عليهم اياتنا، وما كنا مهلكي القرى الا واهلها ظالمون لانفسهم بكفرهم بالله ومعصيته، فهم بذلك مستحقون للعقوبه والنكال."},{"id":"3312","s":28,"a":60,"at":"وما اوتيتم من شيء فمتاع الحياه الدنيا وزينتها وما عند الله خير وابقى افلا تعقلون","dt":"[60] وما اعطيتم -ايها الناس- من شيء من الاموال والاولاد، فانما هو متاع تتمتعون به في هذه الحياه الدنيا، وزينه يتزين بها، وما عند الله لاهل طاعته وولايته خير وابقى؛ لانه دائم لا نفاد له، افلا تكون لكم عقول -ايها القوم- تتدبرون بها، فتعرفون الخير من الشر؟"},{"id":"3313","s":28,"a":61,"at":"افمن وعدناه وعدا حسنا فهو لاقيه كمن متعناه متاع الحياه الدنيا ثم هو يوم القيامه من المحضرين","dt":"[61] افمن وعدناه من خلقنا على طاعته ايانا الجنه، فهو ملاق ما وعد، وصائر اليه، كمن متعناه في الحياه الدنيا متاعها، فتمتع به، واثر لذه عاجله على اجله، ثم هو يوم القيامه من المحضرين للحساب والجزاء؟ لا يستوي الفريقان، فليختر العاقل لنفسه ما هو اولى بالاختيار، وهو طاعه الله وابتغاء مرضاته."},{"id":"3314","s":28,"a":62,"at":"ويوم يناديهم فيقول اين شركائي الذين كنتم تزعمون","dt":"[62] ويوم ينادي الله عز وجل الذين اشركوا به الاولياء والاوثان في الدنيا، فيقول لهم: اين شركائي الذين كنتم تزعمون انهم لي شركاء؟"},{"id":"3315","s":28,"a":63,"at":"قال الذين حق عليهم القول ربنا هؤلاء الذين اغوينا اغويناهم كما غوينا تبرانا اليك ما كانوا ايانا يعبدون","dt":"[63] قال الذين حق عليهم العذاب، وهم دعاه الكفر: ربنا هؤلاء الذين اضللنا، اضللناهم كما ضللنا، تبرانا اليك من ولايتهم ونصرتهم، ما كانوا ايانا يعبدون، وانما كانوا يعبدون الشياطين."},{"id":"3316","s":28,"a":64,"at":"وقيل ادعوا شركاءكم فدعوهم فلم يستجيبوا لهم وراوا العذاب لو انهم كانوا يهتدون","dt":"[64] وقيل للمشركين بالله يوم القيامه: ادعوا شركاءكم الذين كنتم تعبدونهم من دون الله، فدعوهم فلم يستجيبوا لهم، وعاينوا العذاب، لو انهم كانوا في الدنيا مهتدين للحق لما عذبوا."},{"id":"3317","s":28,"a":65,"at":"ويوم يناديهم فيقول ماذا اجبتم المرسلين","dt":"[65] ويوم ينادي الله هؤلاء المشركين، فيقول: باي شيء اجبتم المرسلين فيما ارسلناهم به اليكم؟"},{"id":"3318","s":28,"a":66,"at":"فعميت عليهم الانباء يومئذ فهم لا يتساءلون","dt":"[66] فخفيت عليهم الحجج، فلم يدروا ما يحتجون به، فهم لا يسال بعضهم بعضا عما يحتجون به سؤال انتفاع."},{"id":"3319","s":28,"a":67,"at":"فاما من تاب وامن وعمل صالحا فعسى ان يكون من المفلحين","dt":"[67] فاما من تاب من المشركين، واخلص لله العباده، وعمل بما امره الله به ورسوله، فهو من الفائزين في الدارين."},{"id":"3320","s":28,"a":68,"at":"وربك يخلق ما يشاء ويختار ما كان لهم الخيره سبحان الله وتعالى عما يشركون","dt":"[68] وربك يخلق ما يشاء ان يخلقه، ويصطفي لولايته من يشاء من خلقه، وليس لاحد من الامر والاختيار شيء، وانما ذلك لله وحده سبحانه، تعالى وتنزه عن شركهم."},{"id":"3321","s":28,"a":69,"at":"وربك يعلم ما تكن صدورهم وما يعلنون","dt":"[69] وربك يعلم ما تخفي صدور خلقه وما يظهرونه."},{"id":"3322","s":28,"a":70,"at":"وهو الله لا اله الا هو له الحمد في الاولى والاخره وله الحكم واليه ترجعون","dt":"[70] وهو الله الذي لا معبود بحق سواه، له الثناء الجميل والشكر في الدنيا والاخره، وله الحكم بين خلقه، واليه تردون بعد مماتكم للحساب والجزاء."},{"id":"3323","s":28,"a":71,"at":"قل ارايتم ان جعل الله عليكم الليل سرمدا الى يوم القيامه من اله غير الله ياتيكم بضياء افلا تسمعون","dt":"[71] قل -ايها الرسول-: اخبروني -ايها الناس- ان جعل الله عليكم الليل دائما الى يوم القيامه، من اله غير الله ياتيكم بضياء تستضيئون به؟ افلا تسمعون سماع فهم وقبول؟"},{"id":"3324","s":28,"a":72,"at":"قل ارايتم ان جعل الله عليكم النهار سرمدا الى يوم القيامه من اله غير الله ياتيكم بليل تسكنون فيه افلا تبصرون","dt":"[72] قل لهم: اخبروني ان جعل الله عليكم النهار دائما الى يوم القيامه، من اله غير الله ياتيكم بليل تستقرون وتهدؤون فيه؟ افلا ترون بابصاركم اختلاف الليل والنهار؟"},{"id":"3325","s":28,"a":73,"at":"ومن رحمته جعل لكم الليل والنهار لتسكنوا فيه ولتبتغوا من فضله ولعلكم تشكرون","dt":"[73] ومن رحمته بكم -ايها الناس- ان جعل لكم الليل والنهار فخالف بينهما، فجعل هذا الليل ظلاما؛ لتستقروا فيه وترتاح ابدانكم، وجعل لكم النهار ضياء؛ لتطلبوا فيه معايشكم، ولتشكروا له على انعامه عليكم بذلك."},{"id":"3326","s":28,"a":74,"at":"ويوم يناديهم فيقول اين شركائي الذين كنتم تزعمون","dt":"[74] ويوم ينادي الله هؤلاء المشركين، فيقول لهم: اين شركائي الذين كنتم تزعمون في الدنيا انهم شركائي؟"},{"id":"3327","s":28,"a":75,"at":"ونزعنا من كل امه شهيدا فقلنا هاتوا برهانكم فعلموا ان الحق لله وضل عنهم ما كانوا يفترون","dt":"[75] ونزعنا من كل امه من الامم المكذبه شهيدا -وهو نبيهم-، يشهد على ما جرى في الدنيا من شركهم وتكذيبهم لرسلهم، فقلنا لتلك الامم التي كذبت رسلها وما جاءت به من عند الله: هاتوا حجتكم على ما اشركتم مع الله، فعلموا حينئذ ان الحجه البالغه لله عليهم، وان الحق لله، وذهب عنهم ما كانوا يفترون على ربهم، فلم ينفعهم ذلك، بل ضرهم واوردهم نار جهنم."},{"id":"3328","s":28,"a":76,"at":"ان قارون كان من قوم موسى فبغى عليهم واتيناه من الكنوز ما ان مفاتحه لتنوا بالعصبه اولي القوه اذ قال له قومه لا تفرح ان الله لا يحب الفرحين","dt":"[76] ان قارون كان من قوم موسى -عليه الصلاه والسلام- فتجاوز حده في الكبر والتجبر عليهم، واتينا قارون من كنوز الاموال شيئا عظيما، حتى ان مفاتيح خزائنه ليثقل حملها على العدد الكثير من الاقوياء، اذ قال له قومه: لا تبطر فرحا بما انت فيه من المال، ان الله لا يحب من خلقه البطرين الذين لا يشكرون لله تعالى ما اعطاهم."},{"id":"3329","s":28,"a":77,"at":"وابتغ فيما اتاك الله الدار الاخره ولا تنس نصيبك من الدنيا واحسن كما احسن الله اليك ولا تبغ الفساد في الارض ان الله لا يحب المفسدين","dt":"[77] والتمس فيما اتاك الله من الاموال ثواب الدار الاخره، بالعمل فيها بطاعه الله في الدنيا، ولا تترك حظك من الدنيا، بان تتمتع فيها بالحلال دون اسراف، واحسن الى الناس بالصدقه، كما احسن الله اليك بهذه الاموال الكثيره، ولا تلتمس ما حرم الله عليك من الفساد في الارض والبغي على قومك، ان الله لا يحب المفسدين، وسيجازيهم على سوء صنيعهم."},{"id":"3330","s":28,"a":78,"at":"قال انما اوتيته على علم عندي او لم يعلم ان الله قد اهلك من قبله من القرون من هو اشد منه قوه واكثر جمعا ولا يسال عن ذنوبهم المجرمون","dt":"[78] قال قارون لقومه الذين وعظوه: انما اعطيت هذه الكنوز بما عندي من العلم والقدره، اولم يعلم قارون ان الله قد اهلك من قبله من الامم من هو اشد منه بطشا، واكثر جمعا للاموال؟ ولا يسال عن ذنوبهم المجرمون؛ لعلم الله تعالى بها، انما يسالون سؤال توبيخ وتقرير، ويعاقبهم الله على ما علمه منهم."},{"id":"3331","s":28,"a":79,"at":"فخرج على قومه في زينته قال الذين يريدون الحياه الدنيا ياليت لنا مثل ما اوتي قارون انه لذو حظ عظيم","dt":"[79] فخرج قارون على قومه في زينته، مريدا بذلك اظهار عظمته وكثره امواله، وحين راه الذين يريدون زينه الحياه الدنيا قالوا: يا ليت لنا مثل ما اعطي قارون من المال والزينه والجاه، ان قارون لذو نصيب عظيم من الدنيا."},{"id":"3332","s":28,"a":80,"at":"وقال الذين اوتوا العلم ويلكم ثواب الله خير لمن امن وعمل صالحا ولا يلقاها الا الصابرون","dt":"[80] وقال الذين اوتوا العلم بالله وشرعه وعرفوا حقائق الامور للذين قالوا: يا ليت لنا مثل ما اوتي قارون: ويلكم اتقوا الله واطيعوه، ثواب الله لمن امن به وبرسله، وعمل الاعمال الصالحه، خير مما اوتي قارون، ولا يتقبل هذه النصيحه ويوفق اليها ويعمل بها الا من يجاهد نفسه، ويصبر على طاعه ربه، ويجتنب معاصيه."},{"id":"3333","s":28,"a":81,"at":"فخسفنا به وبداره الارض فما كان له من فئه ينصرونه من دون الله وما كان من المنتصرين","dt":"[81] فخسفنا بقارون وبداره الارض، فما كان له من جند ينصرونه من دون الله، وما كان ممتنعا من الله اذا احل به نقمته."},{"id":"3334","s":28,"a":82,"at":"واصبح الذين تمنوا مكانه بالامس يقولون ويكان الله يبسط الرزق لمن يشاء من عباده ويقدر لولا ان من الله علينا لخسف بنا ويكانه لا يفلح الكافرون","dt":"[82] وصار الذين تمنوا حاله بالامس يقولون متوجعين ومعتبرين وخائفين من وقوع العذاب بهم: ان الله يوسع الرزق لمن يشاء من عباده، ويضيق على من يشاء منهم، لولا ان الله من علينا فلم يعاقبنا على ما قلنا لخسف بنا كما فعل بقارون، الم تعلم انه لا يفلح الكافرون، لا في الدنيا ولا في الاخره؟"},{"id":"3335","s":28,"a":83,"at":"تلك الدار الاخره نجعلها للذين لا يريدون علوا في الارض ولا فسادا والعاقبه للمتقين","dt":"[83] تلك الدار الاخره نجعل نعيمها للذين لا يريدون تكبرا عن الحق في الارض ولا فسادا فيها. والعاقبه المحموده -وهي الجنه- لمن اتقى عذاب الله وعمل الطاعات، وترك المحرمات."},{"id":"3336","s":28,"a":84,"at":"من جاء بالحسنه فله خير منها ومن جاء بالسيئه فلا يجزى الذين عملوا السيئات الا ما كانوا يعملون","dt":"[84] من جاء يوم القيامه باخلاص التوحيد لله وبالاعمال الصالحه وفق ما شرع الله، فله اجر عظيم خير من ذلك، وذلك الخير هو الجنه والنعيم الدائم، ومن جاء بالاعمال السيئه، فلا يجزى الذين عملوا السيئات على اعمالهم الا بما كانوا يعملون."},{"id":"3337","s":28,"a":85,"at":"ان الذي فرض عليك القران لرادك الى معاد قل ربي اعلم من جاء بالهدى ومن هو في ضلال مبين","dt":"[85] ان الذي انزل عليك -ايها الرسول- القران، وفرض عليك تبليغه والتمسك به، لمرجعك الى الموضع الذي خرجت منه، وهو «مكه»، قل ايها الرسول لهؤلاء المشركين: ربي اعلم من جاء بالهدى، ومن هو في ذهاب واضح عن الحق."},{"id":"3338","s":28,"a":86,"at":"وما كنت ترجو ان يلقى اليك الكتاب الا رحمه من ربك فلا تكونن ظهيرا للكافرين","dt":"[86] وما كنت -ايها الرسول- تؤمل نزول القران عليك، لكن الله سبحانه وتعالى رحمك فانزله عليك، فاشكر لله تعالى على نعمه، ولا تكونن عونا لاهل الشرك والضلال."},{"id":"3339","s":28,"a":87,"at":"ولا يصدنك عن ايات الله بعد اذ انزلت اليك وادع الى ربك ولا تكونن من المشركين","dt":"[87] ولا يصرفنك هؤلاء المشركون عن تبليغ ايات ربك وحججه، بعد ان انزلها اليك، وبلغ رساله ربك، ولا تكونن من المشركين في شيء."},{"id":"3340","s":28,"a":88,"at":"ولا تدع مع الله الها اخر لا اله الا هو كل شيء هالك الا وجهه له الحكم واليه ترجعون","dt":"[88] ولا تعبد مع الله معبودا اخر؛ فلا معبود بحق الا الله، كل شيء هالك وفان الا وجهه، له الحكم، واليه ترجعون من بعد موتكم للحساب والجزاء. وفي هذه الايه اثبات صفه الوجه لله تعالى كما يليق بكماله وعظمه جلاله."},{"id":"3341","s":29,"a":1,"at":"الم","dt":"[1] الم سبق الكلام على الحروف المقطعه في اول سوره البقره."},{"id":"3342","s":29,"a":2,"at":"احسب الناس ان يتركوا ان يقولوا امنا وهم لا يفتنون","dt":"[2] اظن الناس اذ قالوا: امنا، ان الله يتركهم بلا ابتلاء ولا اختبار؟"},{"id":"3343","s":29,"a":3,"at":"ولقد فتنا الذين من قبلهم فليعلمن الله الذين صدقوا وليعلمن الكاذبين","dt":"[3] ولقد فتنا الذين من قبلهم من الامم واختبرناهم، ممن ارسلنا اليهم رسلنا، فليعلمن الله علما ظاهرا للخلق صدق الصادقين في ايمانهم، وكذب الكاذبين؛ ليميز كل فريق من الاخر."},{"id":"3344","s":29,"a":4,"at":"ام حسب الذين يعملون السيئات ان يسبقونا ساء ما يحكمون","dt":"[4] بل اظن الذين يعملون المعاصي من شرك وغيره ان يعجزونا، فيفوتونا بانفسهم فلا نقدر عليهم؟ بئس حكمهم الذي يحكمون به."},{"id":"3345","s":29,"a":5,"at":"من كان يرجو لقاء الله فان اجل الله لات وهو السميع العليم","dt":"[5] من كان يرجو لقاء الله، ويطمع في ثوابه، فان اجل الله الذي اجله لبعث خلقه للجزاء والعقاب لات قريبا، وهو السميع للاقوال، العليم بالافعال."},{"id":"3346","s":29,"a":6,"at":"ومن جاهد فانما يجاهد لنفسه ان الله لغني عن العالمين","dt":"[6] ومن جاهد في سبيل اعلاء كلمه الله تعالى، وجاهد نفسه بحملها على الطاعه، فانما يجاهد لنفسه؛ لانه يفعل ذلك ابتغاء الثواب على جهاده. ان الله لغني عن اعمال جميع خلقه، له الملك والخلق والامر."},{"id":"3347","s":29,"a":7,"at":"والذين امنوا وعملوا الصالحات لنكفرن عنهم سيئاتهم ولنجزينهم احسن الذي كانوا يعملون","dt":"[7] والذين صدقوا الله ورسوله، وعملوا الصالحات لنمحون عنهم خطيئاتهم، ولنثيبنهم على اعمالهم الصالحه احسن ما كانوا يعملون."},{"id":"3348","s":29,"a":8,"at":"ووصينا الانسان بوالديه حسنا وان جاهداك لتشرك بي ما ليس لك به علم فلا تطعهما الي مرجعكم فانبئكم بما كنتم تعملون","dt":"[8] ووصينا الانسان بوالديه ان يبرهما، ويحسن اليهما بالقول والعمل، وان جاهداك -ايها الانسان- على ان تشرك معي في عبادتي، فلا تمتثل امرهما. ويلحق بطلب الاشراك بالله، سائر المعاصي، فلا طاعه لمخلوق كائنا من كان في معصيه الله سبحانه، كما ثبت ذلك عن رسول الله -صلى الله عليه وسلم-. الي مصيركم يوم القيامه، فاخبركم بما كنتم تعملون في الدنيا من صالح الاعمال وسيئها، واجازيكم عليها."},{"id":"3349","s":29,"a":9,"at":"والذين امنوا وعملوا الصالحات لندخلنهم في الصالحين","dt":"[9] والذين صدقوا الله ورسوله وعملوا الصالحات من الاعمال، لندخلنهم الجنه في جمله عباد الله الصالحين."},{"id":"3350","s":29,"a":10,"at":"ومن الناس من يقول امنا بالله فاذا اوذي في الله جعل فتنه الناس كعذاب الله ولئن جاء نصر من ربك ليقولن انا كنا معكم او ليس الله باعلم بما في صدور العالمين","dt":"[10] ومن الناس من يقول: امنا بالله، فاذا اذاه المشركون جزع من عذابهم واذاهم، كما يجزع من عذاب الله ولا يصبر على الاذيه منه، فارتد عن ايمانه، ولئن جاء نصر من ربك -ايها الرسول- لاهل الايمان به ليقولن هؤلاء المرتدون عن ايمانهم: انا كنا معكم -ايها المؤمنون- ننصركم على اعدائكم، اوليس الله باعلم من كل احد بما في صدور جميع خلقه؟"},{"id":"3351","s":29,"a":11,"at":"وليعلمن الله الذين امنوا وليعلمن المنافقين","dt":"[11] وليعلمن الله علما ظاهرا للخلق الذين صدقوا الله ورسوله وعملوا بشرعه، وليعلمن المنافقين؛ ليميز كل فريق من الاخر."},{"id":"3352","s":29,"a":12,"at":"وقال الذين كفروا للذين امنوا اتبعوا سبيلنا ولنحمل خطاياكم وما هم بحاملين من خطاياهم من شيء انهم لكاذبون","dt":"[12] وقال الذين جحدوا وحدانيه الله من قريش، ولم يؤمنوا بوعيد الله ووعده، للذين صدقوا الله منهم وعملوا بشرعه: اتركوا دين محمد، واتبعوا ديننا، فانا نتحمل اثام خطاياكم، وليسوا بحاملين من اثامهم من شيء، انهم لكاذبون فيما قالوا."},{"id":"3353","s":29,"a":13,"at":"وليحملن اثقالهم واثقالا مع اثقالهم وليسالن يوم القيامه عما كانوا يفترون","dt":"[13] وليحملن هؤلاء المشركون اوزار انفسهم واثامها، واوزار من اضلوا وصدوا عن سبيل الله مع اوزارهم، دون ان ينقص من اوزار تابعيهم شيء، وليسالن يوم القيامه عما كانوا يختلقونه من الاكاذيب."},{"id":"3354","s":29,"a":14,"at":"ولقد ارسلنا نوحا الى قومه فلبث فيهم الف سنه الا خمسين عاما فاخذهم الطوفان وهم ظالمون","dt":"[14] ولقد ارسلنا نوحا الى قومه فمكث فيهم الف سنه الا خمسين عاما، يدعوهم الى التوحيد وينهاهم عن الشرك، فلم يستجيبوا له، فاهلكهم الله بالطوفان، وهم ظالمون لانفسهم بكفرهم وطغيانهم."},{"id":"3355","s":29,"a":15,"at":"فانجيناه واصحاب السفينه وجعلناها ايه للعالمين","dt":"[15] فانجينا نوحا ومن تبعه ممن كان معه في السفينه، وجعلنا ذلك عبره وعظه للعالمين."},{"id":"3356","s":29,"a":16,"at":"وابراهيم اذ قال لقومه اعبدوا الله واتقوه ذلكم خير لكم ان كنتم تعلمون","dt":"[16] واذكر -ايها الرسول- ابراهيم عليه السلام حين دعا قومه: ان اخلصوا العباده لله وحده، واتقوا سخطه باداء فرائضه واجتناب معاصيه، ذلكم خير لكم، ان كنتم تعلمون ما هو خير لكم مما هو شر لكم."},{"id":"3357","s":29,"a":17,"at":"انما تعبدون من دون الله اوثانا وتخلقون افكا ان الذين تعبدون من دون الله لا يملكون لكم رزقا فابتغوا عند الله الرزق واعبدوه واشكروا له اليه ترجعون","dt":"[17] ما تعبدون -ايها القوم- من دون الله الا اصناما، وتفترون كذبا بتسميتكم اياها الهه، ان اوثانكم التي تعبدونها من دون الله لا تقدر ان ترزقكم شيئا، فالتمسوا عند الله الرزق لا من عند اوثانكم، واخلصوا له العباده والشكر على رزقه اياكم، الى الله تردون من بعد مماتكم، فيجازيكم على ما عملتم."},{"id":"3358","s":29,"a":18,"at":"وان تكذبوا فقد كذب امم من قبلكم وما على الرسول الا البلاغ المبين","dt":"[18] وان تكذبوا -ايها الناس- رسولنا محمدا -صلى الله عليه وسلم- فيما دعاكم اليه من عباده الله وحده، فقد كذبت جماعات من قبلكم رسلها فيما دعتهم اليه من الحق، فحل بهم سخط الله، وما على الرسول محمد الا ان يبلغكم عن الله رسالته البلاغ الواضح. وقد فعل."},{"id":"3359","s":29,"a":19,"at":"او لم يروا كيف يبدئ الله الخلق ثم يعيده ان ذلك على الله يسير","dt":"[19] اولم يعلم هؤلاء كيف ينشىء الله الخلق من العدم، ثم يعيده من بعد فنائه، كما بداه اول مره خلقا جديدا، لا يتعذر عليه ذلك؟ ان ذلك على الله يسير، كما كان يسيرا عليه انشاؤه."},{"id":"3360","s":29,"a":20,"at":"قل سيروا في الارض فانظروا كيف بدا الخلق ثم الله ينشئ النشاه الاخره ان الله على كل شيء قدير","dt":"[20] قل -ايها الرسول- لمنكري البعث بعد الممات: سيروا في الارض، فانظروا كيف انشا الله الخلق، ولم يتعذر عليه انشاؤه مبتدا؟ فكذلك لا يتعذر عليه اعاده انشائه النشاه الاخره. ان الله على كل شيء قدير، لا يعجزه شيء اراده."},{"id":"3361","s":29,"a":21,"at":"يعذب من يشاء ويرحم من يشاء واليه تقلبون","dt":"[21] يعذب من يشاء من خلقه على ما اسلف من جرمه في ايام حياته، ويرحم من يشاء منهم ممن تاب وامن وعمل صالحا، واليه ترجعون، فيجازيكم بما عملتم."},{"id":"3362","s":29,"a":22,"at":"وما انتم بمعجزين في الارض ولا في السماء وما لكم من دون الله من ولي ولا نصير","dt":"[22] وما انتم -ايها الناس- بمعجزي الله في الارض ولا في السماء ان عصيتموه، وما كان لكم من دون الله من ولي يلي اموركم، ولا نصير ينصركم من الله ان اراد بكم سوءا."},{"id":"3363","s":29,"a":23,"at":"والذين كفروا بايات الله ولقائه اولئك يئسوا من رحمتي واولئك لهم عذاب اليم","dt":"[23] والذين جحدوا حجج الله وانكروا ادلته، ولقاءه يوم القيامه، اولئك ليس لهم مطمع في رحمتي في الاخره لما عاينوا ما اعد لهم من العذاب، واولئك لهم عذاب مؤلم موجع."},{"id":"3364","s":29,"a":24,"at":"فما كان جواب قومه الا ان قالوا اقتلوه او حرقوه فانجاه الله من النار ان في ذلك لايات لقوم يؤمنون","dt":"[24] فلم يكن جواب قوم ابراهيم له الا ان قال بعضهم لبعض: اقتلوه او حرقوه بالنار، فالقوه فيها، فانجاه الله منها، وجعلها عليه بردا وسلاما، ان في انجائنا لابراهيم من النار لادله وحججا لقوم يصدقون الله ويعملون بشرعه."},{"id":"3365","s":29,"a":25,"at":"وقال انما اتخذتم من دون الله اوثانا موده بينكم في الحياه الدنيا ثم يوم القيامه يكفر بعضكم ببعض ويلعن بعضكم بعضا وماواكم النار وما لكم من ناصرين","dt":"[25] وقال ابراهيم لقومه: يا قوم انما عبدتم الهه باطله اتخذتموها من دون الله، تتحابون على عبادتها، وتتوادون على خدمتها في الحياه الدنيا، ثم يوم القيامه، يتبرا بعضكم من بعض، ويلعن بعضكم بعضا، ومصيركم جميعا النار، وليس لكم ناصر يمنعكم من دخولها."},{"id":"3366","s":29,"a":26,"at":"فامن له لوط وقال اني مهاجر الى ربي انه هو العزيز الحكيم","dt":"[26] فصدق لوط ابراهيم وتبع ملته. وقال ابراهيم: اني تارك دار قومي الى الارض المباركه وهي «الشام»، ان الله هو العزيز الذي لا يغالب، الحكيم في تدبيره."},{"id":"3367","s":29,"a":27,"at":"ووهبنا له اسحاق ويعقوب وجعلنا في ذريته النبوه والكتاب واتيناه اجره في الدنيا وانه في الاخره لمن الصالحين","dt":"[27] ووهبنا له اسحاق ولدا، ويعقوب من بعده ولد ولد، وجعلنا في ذريته الانبياء والكتب، واعطيناه ثواب بلائه فينا، في الدنيا الذكر الحسن والولد الصالح، وانه في الاخره لمن الصالحين."},{"id":"3368","s":29,"a":28,"at":"ولوطا اذ قال لقومه انكم لتاتون الفاحشه ما سبقكم بها من احد من العالمين","dt":"[28] واذكر -ايها الرسول- لوطا حين قال لقومه: انكم لتاتون الفعله القبيحه، ما تقدمكم بفعلها احد من العالمين."},{"id":"3369","s":29,"a":29,"at":"ائنكم لتاتون الرجال وتقطعون السبيل وتاتون في ناديكم المنكر فما كان جواب قومه الا ان قالوا ائتنا بعذاب الله ان كنت من الصادقين","dt":"[29] اانكم لتاتون الرجال في ادبارهم، وتقطعون على المسافرين طرقهم بفعلكم الخبيث، وتاتون في مجالسكم الاعمال المنكره كالسخريه من الناس، وحذف الماره بالحجاره، وايذائهم بما لا يليق من الاقوال والافعال؟ وفي هذا اعلام بانه لا يجوز ان يجتمع الناس على المنكر مما نهى الله ورسوله عنه. فلم يكن جواب قوم لوط له الا ان قالوا: جئنا بعذاب الله ان كنت من الصادقين فيما تقول، والمنجزين لما تعد."},{"id":"3370","s":29,"a":30,"at":"قال رب انصرني على القوم المفسدين","dt":"[30] قال: رب انصرني على القوم المفسدين بانزال العذاب عليهم؛ حيث ابتدعوا هذه الفاحشه واصروا عليها، فاستجاب الله دعاءه."},{"id":"3371","s":29,"a":31,"at":"ولما جاءت رسلنا ابراهيم بالبشرى قالوا انا مهلكو اهل هذه القريه ان اهلها كانوا ظالمين","dt":"[31] ولما جاءت الملائكه ابراهيم بالخبر السار من الله باسحاق، ومن وراء اسحاق ولده يعقوب، قالت الملائكه لابراهيم: انا مهلكو اهل قريه قوم لوط، وهي «سدوم»؛ ان اهلها كانوا ظالمي انفسهم بمعصيتهم لله."},{"id":"3372","s":29,"a":32,"at":"قال ان فيها لوطا قالوا نحن اعلم بمن فيها لننجينه واهله الا امراته كانت من الغابرين","dt":"[32] قال ابراهيم للملائكه: ان فيها لوطا وليس من الظالمين، فقالت الملائكه له: نحن اعلم بمن فيها، لننجينه واهله من الهلاك الذي سينزل باهل قريته الا امراته كانت من الباقين الهالكين."},{"id":"3373","s":29,"a":33,"at":"ولما ان جاءت رسلنا لوطا سيء بهم وضاق بهم ذرعا وقالوا لا تخف ولا تحزن انا منجوك واهلك الا امراتك كانت من الغابرين","dt":"[33] ولما جاءت الملائكه لوطا ساءه ذلك؛ لانه ظنهم ضيوفا من البشر، وحزن بسبب وجودهم؛ لعلمه خبث فعل قومه، وقالوا له: لا تخف علينا لن يصل الينا قومك، ولا تحزن مما اخبرناك من انا مهلكوهم، انا منجوك من العذاب النازل بقومك ومنجو اهلك معك الا امراتك، فانها هالكه فيمن يهلك من قومها."},{"id":"3374","s":29,"a":34,"at":"انا منزلون على اهل هذه القريه رجزا من السماء بما كانوا يفسقون","dt":"[34] انا منزلون على اهل هذه القريه عذابا من السماء؛ بسبب معصيتهم لله وارتكابهم الفاحشه."},{"id":"3375","s":29,"a":35,"at":"ولقد تركنا منها ايه بينه لقوم يعقلون","dt":"[35] ولقد ابقينا من ديار قوم لوط اثارا بينه لقوم يعقلون العبر، فينتفعون بها."},{"id":"3376","s":29,"a":36,"at":"والى مدين اخاهم شعيبا فقال ياقوم اعبدوا الله وارجوا اليوم الاخر ولا تعثوا في الارض مفسدين","dt":"[36] وارسلنا الى «مدين» اخاهم شعيبا، فقال لهم: يا قوم اعبدوا الله وحده، واخلصوا له العباده، ما لكم من اله غيره، وارجوا بعبادتكم جزاء اليوم الاخر، ولا تكثروا في الارض الفساد والمعاصي، ولا تقيموا عليها، ولكن توبوا الى الله منها وانيبوا."},{"id":"3377","s":29,"a":37,"at":"فكذبوه فاخذتهم الرجفه فاصبحوا في دارهم جاثمين","dt":"[37] فكذب اهل «مدين» شعيبا فيما جاءهم به عن الله من الرساله، فاخذتهم الزلزله الشديده، فاصبحوا في دارهم صرعى هالكين."},{"id":"3378","s":29,"a":38,"at":"وعادا وثمود وقد تبين لكم من مساكنهم وزين لهم الشيطان اعمالهم فصدهم عن السبيل وكانوا مستبصرين","dt":"[38] واهلكنا عادا وثمود، وقد تبين لكم من مساكنهم خرابها وخلاؤها منهم، وحلول نقمتنا بهم جميعا، وحسن لهم الشيطان اعمالهم القبيحه، فصدهم عن سبيل الله وعن طريق الايمان به وبرسله، وكانوا مستبصرين في كفرهم وضلالهم، معجبين به، يحسبون انهم على هدى وصواب، بينما هم في الضلال غارقون."},{"id":"3379","s":29,"a":39,"at":"وقارون وفرعون وهامان ولقد جاءهم موسى بالبينات فاستكبروا في الارض وما كانوا سابقين","dt":"[39] واهلكنا قارون وفرعون وهامان، ولقد جاءهم جميعا موسى بالادله الواضحه، فتعاظموا في الارض، واستكبروا فيها، ولم يكونوا ليفوتونا، بل كنا مقتدرين عليهم."},{"id":"3380","s":29,"a":40,"at":"فكلا اخذنا بذنبه فمنهم من ارسلنا عليه حاصبا ومنهم من اخذته الصيحه ومنهم من خسفنا به الارض ومنهم من اغرقنا وما كان الله ليظلمهم ولكن كانوا انفسهم يظلمون","dt":"[40] فاخذنا كلا من هؤلاء المذكورين بعذابنا بسبب ذنبه: فمنهم الذين ارسلنا عليهم ريحا شديده ترميهم بحجاره من طين متتابع، وهم قوم لوط، ومنهم من اخذته الصيحه، وهم قوم صالح وقوم شعيب، ومنهم من خسفنا به الارض كقارون، ومنهم من اغرقنا، وهم قوم نوح وفرعون وقومه، ولم يكن الله ليهلك هؤلاء بذنوب غيرهم، فيظلمهم باهلاكه اياهم بغير استحقاق، ولكنهم كانوا انفسهم يظلمون بتنعمهم في نعم ربهم وعبادتهم غيره."},{"id":"3381","s":29,"a":41,"at":"مثل الذين اتخذوا من دون الله اولياء كمثل العنكبوت اتخذت بيتا وان اوهن البيوت لبيت العنكبوت لو كانوا يعلمون","dt":"[41] مثل الذين جعلوا الاوثان من دون الله اولياء يرجون نصرها، كمثل العنكبوت التي عملت بيتا لنفسها ليحفظها، فلم يغن عنها شيئا عند حاجتها اليه، فكذلك هؤلاء المشركون لم يغن عنهم اولياؤهم الذين اتخذوهم من دون الله شيئا، وان اضعف البيوت لبيت العنكبوت، لو كانوا يعلمون ذلك ما اتخذوهم اولياء، فهم لا ينفعونهم ولا يضرونهم."},{"id":"3382","s":29,"a":42,"at":"ان الله يعلم ما يدعون من دونه من شيء وهو العزيز الحكيم","dt":"[42] ان الله يعلم ما يشركون به من الانداد، وانها ليست بشيء في الحقيقه، بل هي مجرد اسماء سموها، لا تنفع ولا تضر. وهو العزيز في انتقامه ممن كفر به، الحكيم في تدبيره وصنعه."},{"id":"3383","s":29,"a":43,"at":"وتلك الامثال نضربها للناس وما يعقلها الا العالمون","dt":"[43] وهذه الامثال نضربها للناس؛ لينتفعوا بها ويتعلموا منها، وما يعقلها الا العالمون بالله واياته وشرعه."},{"id":"3384","s":29,"a":44,"at":"خلق الله السموات والارض بالحق ان في ذلك لايه للمؤمنين","dt":"[44] خلق الله السموات والارض بالعدل والقسط، ان في خلقه ذلك لدلاله عظيمه على قدرته، وتفرده بالالهيه، وخص المؤمنين بالذكر؛ لانهم الذين ينتفعون بذلك."},{"id":"3385","s":29,"a":45,"at":"اتل ما اوحي اليك من الكتاب واقم الصلاه ان الصلاه تنهى عن الفحشاء والمنكر ولذكر الله اكبر والله يعلم ما تصنعون","dt":"[45] اتل ما انزل اليك من هذا القران واعمل به، واد الصلاه بحدودها، ان المحافظه على الصلاه تنهى صاحبها عن الوقوع في المعاصي والمنكرات؛ وذلك لان المقيم لها، المتمم لاركانها وشروطها، يستنير قلبه، ويزداد ايمانه، وتقوى رغبته في الخير، وتقل او تنعدم رغبته في الشر، ولذكر الله في الصلاه وغيرها اعظم واكبر وافضل من كل شيء. والله يعلم ما تصنعون من خير وشر، فيجازيكم على ذلك اكمل الجزاء واوفاه."},{"id":"3386","s":29,"a":46,"at":"ولا تجادلوا اهل الكتاب الا بالتي هي احسن الا الذين ظلموا منهم وقولوا امنا بالذي انزل الينا وانزل اليكم والهنا والهكم واحد ونحن له مسلمون","dt":"[46] ولا تجادلوا -ايها المؤمنون- اليهود والنصارى الا بالاسلوب الحسن، والقول الجميل، والدعوه الى الحق بايسر طريق موصل لذلك، الا الذين حادوا عن وجه الحق وعاندوا وكابروا واعلنوا الحرب عليكم فقاتلوهم حتى يؤمنوا، او يعطوا الجزيه بايديهم وهم اذلاء، وقولوا: امنا بالقران الذي انزل الينا، وامنا بالتوراه والانجيل اللذين انزلا اليكم، والهنا والهكم واحد لا شريك له في الوهيته، ولا في ربوبيته، ولا في اسمائه وصفاته، ونحن له خاضعون متذللون بالطاعه فيما امرنا به، ونهانا عنه."},{"id":"3387","s":29,"a":47,"at":"وكذلك انزلنا اليك الكتاب فالذين اتيناهم الكتاب يؤمنون به ومن هؤلاء من يؤمن به وما يجحد باياتنا الا الكافرون","dt":"[47] وكما انزلنا -ايها الرسول- الكتب على من قبلك من الرسل، انزلنا اليك هذا الكتاب المصدق للكتب السابقه، فالذين اتيناهم الكتاب من بني اسرائيل فعرفوه حق معرفته يؤمنون بالقران، ومن هؤلاء العرب من قريش وغيرهم من يؤمن به، ولا ينكر القران او يتشكك في دلائله وبراهينه البينه الا الكافرون الذين دابهم الجحود والعناد."},{"id":"3388","s":29,"a":48,"at":"وما كنت تتلو من قبله من كتاب ولا تخطه بيمينك اذا لارتاب المبطلون","dt":"[48] ومن معجزاتك البينه -ايها الرسول- انك لم تقرا كتابا ولم تكتب حروفا بيمينك قبل نزول القران عليك، وهم يعرفون ذلك، ولو كنت قارئا او كاتبا من قبل ان يوحى اليك لشك في ذلك المبطلون، وقالوا: تعلمه من الكتب السابقه او استنسخه منها."},{"id":"3389","s":29,"a":49,"at":"بل هو ايات بينات في صدور الذين اوتوا العلم وما يجحد باياتنا الا الظالمون","dt":"[49] بل القران ايات بينات واضحه في الدلاله على الحق يحفظه العلماء، وما يكذب باياتنا ويردها الا الظالمون المعاندون الذين يعلمون الحق ويحيدون عنه."},{"id":"3390","s":29,"a":50,"at":"وقالوا لولا انزل عليه ايات من ربه قل انما الايات عند الله وانما انا نذير مبين","dt":"[50] وقال المشركون: هلا انزل على محمد دلائل وحجج من ربه نشاهدها كناقه صالح، وعصا موسى! قل لهم: ان امر هذه الايات لله، ان شاء انزلها، وان شاء منعها، وانما انا لكم نذير احذركم شده باسه وعقابه، مبين طريق الحق من الباطل."},{"id":"3391","s":29,"a":51,"at":"او لم يكفهم انا انزلنا عليك الكتاب يتلى عليهم ان في ذلك لرحمه وذكرى لقوم يؤمنون","dt":"[51] او لم يكف هؤلاء المشركين في علمهم بصدقك -ايها الرسول- انا انزلنا عليك القران يتلى عليهم؟ ان في هذا القران لرحمه للمؤمنين في الدنيا والاخره، وذكرى يتذكرون بما فيه من عبره وعظه."},{"id":"3392","s":29,"a":52,"at":"قل كفى بالله بيني وبينكم شهيدا يعلم ما في السموات والارض والذين امنوا بالباطل وكفروا بالله اولئك هم الخاسرون","dt":"[52] قل: كفى بالله بيني وبينكم شاهدا على صدقي اني رسوله، وعلى تكذيبكم لي وردكم الحق الذي جئت به من عند الله، يعلم ما في السموات والارض، فلا يخفى عليه شيء فيهما. والذين امنوا بالباطل وكفروا بالله -مع هذه الدلائل الواضحه- اولئك هم الخاسرون في الدنيا والاخره."},{"id":"3393","s":29,"a":53,"at":"ويستعجلونك بالعذاب ولولا اجل مسمى لجاءهم العذاب ولياتينهم بغته وهم لا يشعرون","dt":"[53] ويستعجلك -ايها الرسول- هؤلاء المشركون من قومك بالعذاب استهزاء، ولولا ان الله جعل لعذابهم في الدنيا وقتا لا يتقدم ولا يتاخر، لجاءهم العذاب حين طلبوه، ولياتينهم فجاه، وهم لا يشعرون به ولا يحسون."},{"id":"3394","s":29,"a":54,"at":"يستعجلونك بالعذاب وان جهنم لمحيطه بالكافرين","dt":"[54] يستعجلونك بالعذاب في الدنيا، وهو اتيهم لا محاله اما في الدنيا واما في الاخره، وان عذاب جهنم في الاخره لمحيط بهم، لا مفر لهم منه."},{"id":"3395","s":29,"a":55,"at":"يوم يغشاهم العذاب من فوقهم ومن تحت ارجلهم ويقول ذوقوا ما كنتم تعملون","dt":"[55] يوم القيامه يغشى الكافرين عذاب جهنم من فوق رؤوسهم، ومن تحت اقدامهم، فالنار تغشاهم من سائر جهاتهم، ويقول الله لهم حينئذ: ذوقوا جزاء ما كنتم تعملونه في الدنيا: من الاشراك بالله، وارتكاب الجرائم والاثام."},{"id":"3396","s":29,"a":56,"at":"ياعبادي الذين امنوا ان ارضي واسعه فاياي فاعبدون","dt":"[56] يا عبادي الذين امنوا ان كنتم في ضيق من اظهار الايمان وعباده الله وحده، فهاجروا الى ارض الله الواسعه، واخلصوا العباده لي وحدي."},{"id":"3397","s":29,"a":57,"at":"كل نفس ذائقه الموت ثم الينا ترجعون","dt":"[57] كل نفس حيه ذائقه الموت، ثم الينا ترجعون للحساب والجزاء."},{"id":"3398","s":29,"a":58,"at":"والذين امنوا وعملوا الصالحات لنبوئنهم من الجنه غرفا تجري من تحتها الانهار خالدين فيها نعم اجر العاملين","dt":"[58] والذين صدقوا بالله ورسوله وعملوا ما امروا به من الصالحات لننزلنهم من الجنه غرفا عاليه تجري من تحتها الانهار، ماكثين فيها ابدا، نعم جزاء العاملين بطاعه الله هذه الغرف في جنات النعيم."},{"id":"3399","s":29,"a":59,"at":"الذين صبروا وعلى ربهم يتوكلون","dt":"[59] ان تلك الجنات المذكوره للمؤمنين الذين صبروا على عباده الله، وتمسكوا بدينهم، وعلى الله يعتمدون في ارزاقهم وجهاد اعدائهم."},{"id":"3400","s":29,"a":60,"at":"وكاين من دابه لا تحمل رزقها الله يرزقها واياكم وهو السميع العليم","dt":"[60] وكم من دابه لا تدخر غذاءها لغد، كما يفعل ابن ادم، فالله سبحانه وتعالى يرزقها كما يرزقكم، وهو السميع لاقوالكم، العليم بافعالكم وخطرات قلوبكم."},{"id":"3401","s":29,"a":61,"at":"ولئن سالتهم من خلق السموات والارض وسخر الشمس والقمر ليقولن الله فانى يؤفكون","dt":"[61] ولئن سالت -ايها الرسول- المشركين: من الذي خلق السموات والارض على هذا النظام البديع، وذلل الشمس والقمر؟ ليقولن: خلقهن الله وحده، فكيف يصرفون عن الايمان بالله خالق كل شيء ومدبره، ويعبدون معه غيره؟ فاعجب من افكهم وكذبهم!"},{"id":"3402","s":29,"a":62,"at":"الله يبسط الرزق لمن يشاء من عباده ويقدر له ان الله بكل شيء عليم","dt":"[62] الله سبحانه وتعالى يوسع الرزق لمن يشاء من خلقه، ويضيق على اخرين منهم؛ لعلمه بما يصلح عباده، ان الله بكل شيء من احوالكم واموركم عليم، لا يخفى عليه شيء."},{"id":"3403","s":29,"a":63,"at":"ولئن سالتهم من نزل من السماء ماء فاحيا به الارض من بعد موتها ليقولن الله قل الحمد لله بل اكثرهم لا يعقلون","dt":"[63] ولئن سالت -ايها الرسول- المشركين: من الذي نزل من السحاب ماء فانبت به الارض من بعد جفافها؟ ليقولن لك معترفين: الله وحده هو الذي نزل ذلك، قل: الحمد لله الذي اظهر حجتك عليهم، بل اكثرهم لا يعقلون ما ينفعهم ولا ما يضرهم، ولو عقلوا ما اشركوا مع الله غيره."},{"id":"3404","s":29,"a":64,"at":"وما هذه الحياه الدنيا الا لهو ولعب وان الدار الاخره لهي الحيوان لو كانوا يعلمون","dt":"[64] وما هذه الحياه الدنيا الا لهو ولعب، تلهو بها القلوب وتلعب بها الابدان؛ بسبب ما فيها من الزينه والشهوات ، ثم تزول سريعا، وان الدار الاخره لهي الحياه الحقيقيه الدائمه التي لا موت فيها، لو كان الناس يعلمون ذلك لما اثروا دار الفناء على دار البقاء."},{"id":"3405","s":29,"a":65,"at":"فاذا ركبوا في الفلك دعوا الله مخلصين له الدين فلما نجاهم الى البر اذا هم يشركون","dt":"[65] فاذا ركب الكفار السفن في البحر، وخافوا الغرق، وحدوا الله، واخلصوا له في الدعاء حال شدتهم، فلما نجاهم الى البر، وزالت عنهم الشده، عادوا الى شركهم، انهم بهذا يتناقضون، يوحدون الله ساعه الشده، ويشركون به ساعه الرخاء. وشركهم بعد نعمتنا عليهم بالنجاه من البحر؛"},{"id":"3406","s":29,"a":66,"at":"ليكفروا بما اتيناهم وليتمتعوا فسوف يعلمون","dt":"[66] ليكون عاقبته الكفر بما انعمنا عليهم في انفسهم واموالهم، وليكملوا تمتعهم في هذه الدنيا، فسوف يعلمون فساد عملهم، وما اعده الله لهم من عذاب اليم يوم القيامه. وفي ذلك تهديد ووعيد لهم."},{"id":"3407","s":29,"a":67,"at":"او لم يروا انا جعلنا حرما امنا ويتخطف الناس من حولهم افبالباطل يؤمنون وبنعمه الله يكفرون","dt":"[67] اولم يشاهد كفار «مكه» ان الله جعل «مكه» لهم حرما امنا يامن فيه اهله على انفسهم واموالهم، والناس من حولهم خارج الحرم، يتخطفون غير امنين؟ افبالشرك يؤمنون، وبنعمه الله التي خصهم بها يكفرون، فلا يعبدونه وحده دون سواه؟"},{"id":"3408","s":29,"a":68,"at":"ومن اظلم ممن افترى على الله كذبا او كذب بالحق لما جاءه اليس في جهنم مثوى للكافرين","dt":"[68] لا احد اشد ظلما ممن كذب على الله، فنسب ما هو عليه من الضلال والباطل الى الله، او كذب بالحق الذي بعث الله به رسوله محمدا -صلى الله عليه وسلم-، ان في النار لمسكنا لمن كفر بالله، وجحد توحيده وكذب رسوله محمدا -صلى الله عليه وسلم-."},{"id":"3409","s":29,"a":69,"at":"والذين جاهدوا فينا لنهدينهم سبلنا وان الله لمع المحسنين","dt":"[69] والمؤمنون الذين جاهدوا اعداء الله، والنفس، والشيطان، وصبروا على الفتن والاذى في سبيل الله، سيهديهم الله سبل الخير، ويثبتهم على الصراط المستقيم، ومن هذه صفته فهو محسن الى نفسه والى غيره. وان الله سبحانه وتعالى لمع من احسن من خلقه بالنصره والتاييد والحفظ والهدايه."},{"id":"3410","s":30,"a":1,"at":"الم","dt":"[1] الم سبق الكلام على الحروف المقطعه في اول سوره البقره."},{"id":"3411","s":30,"a":2,"at":"غلبت الروم","dt":"[2] غلبت فارس الروم ."},{"id":"3412","s":30,"a":3,"at":"في ادنى الارض وهم من بعد غلبهم سيغلبون","dt":"[3] غفي ادنى ارض «الشام» الى «فارس»، وسوف يغلب الروم الفرس ."},{"id":"3413","s":30,"a":4,"at":"في بضع سنين لله الامر من قبل ومن بعد ويومئذ يفرح المؤمنون","dt":"[4] في مده من الزمن، لا تزيد على عشر سنوات ولا تنقص عن ثلاث. لله سبحانه وتعالى الامر كله قبل انتصار الروم وبعده، ويوم ينتصر الروم على الفرس يفرح المؤمنون"},{"id":"3414","s":30,"a":5,"at":"بنصر الله ينصر من يشاء وهو العزيز الرحيم","dt":"[5] بنصر الله للروم على الفرس. والله سبحانه وتعالى ينصر من يشاء، ويخذل من يشاء، وهو العزيز الذي لا يغالب، الرحيم بمن شاء من خلقه. وقد تحقق ذلك فغلبت الروم الفرس بعد سبع سنين، وفرح المسلمون بذلك؛ لكون الروم اهل كتاب وان حرفوه."},{"id":"3415","s":30,"a":6,"at":"وعد الله لا يخلف الله وعده ولكن اكثر الناس لا يعلمون","dt":"[6] وعد الله المؤمنين وعدا جازما لا يخلف، بنصر الروم النصارى على الفرس الوثنيين، ولكن اكثر كفار «مكه» لا يعلمون ان ما وعد الله به حق،"},{"id":"3416","s":30,"a":7,"at":"يعلمون ظاهرا من الحياه الدنيا وهم عن الاخره هم غافلون","dt":"[7] وانما يعلمون ظواهر الدنيا وزخرفها، وهم عن امور الاخره وما ينفعهم فيها غافلون، لا يفكرون فيها."},{"id":"3417","s":30,"a":8,"at":"او لم يتفكروا في انفسهم ما خلق الله السموات والارض وما بينهما الا بالحق واجل مسمى وان كثيرا من الناس بلقاء ربهم لكافرون","dt":"[8] اولم يتفكر هؤلاء المكذبون برسل الله ولقائه في خلق الله اياهم، وانه خلقهم، ولم يكونوا شيئا. ما خلق الله السموات والارض وما بينهما الا لاقامه العدل والثواب والعقاب، والدلاله على توحيده وقدرته، واجل مسمى تنتهي اليه وهو يوم القيامه؟ وان كثيرا من الناس بلقاء ربهم لجاحدون منكرون؛ جهلا منهم بان معادهم الى الله بعد فنائهم، وغفله منهم عن الاخره."},{"id":"3418","s":30,"a":9,"at":"او لم يسيروا في الارض فينظروا كيف كان عاقبه الذين من قبلهم كانوا اشد منهم قوه واثاروا الارض وعمروها اكثر مما عمروها وجاءتهم رسلهم بالبينات فما كان الله ليظلمهم ولكن كانوا انفسهم يظلمون","dt":"[9] اولم يسر هؤلاء المكذبون بالله الغافلون عن الاخره في الارض سير تامل واعتبار، فيشاهدوا كيف كان جزاء الامم الذين كذبوا برسل الله كعاد وثمود؟ وقد كانوا اقوى منهم اجساما، واقدر على التمتع بالحياه حيث حرثوا الارض وزرعوها، وبنوا القصور وسكنوها، فعمروا دنياهم اكثر مما عمر اهل «مكه» دنياهم، فلم تنفعهم عمارتهم ولا طول مدتهم، وجاءتهم رسلهم بالحجج الظاهره والبراهين الساطعه، فكذبوهم فاهلكهم الله، ولم يظلمهم الله بذلك الاهلاك، وانما ظلموا انفسهم بالشرك والعصيان."},{"id":"3419","s":30,"a":10,"at":"ثم كان عاقبه الذين اساءوا السواى ان كذبوا بايات الله وكانوا بها يستهزئون","dt":"[10] ثم كانت عاقبه اهل السوء من الطغاه والكفره اسوا العواقب واقبحها؛ لتكذيبهم بالله وسخريتهم باياته التي انزلها على رسله."},{"id":"3420","s":30,"a":11,"at":"الله يبدا الخلق ثم يعيده ثم اليه ترجعون","dt":"[11] الله وحده هو المتفرد بانشاء المخلوقات كلها، وهو القادر وحده على اعادتها مره اخرى، ثم اليه يرجع جميع الخلق، فيجازي المحسن باحسانه والمسيء باساءته."},{"id":"3421","s":30,"a":12,"at":"ويوم تقوم الساعه يبلس المجرمون","dt":"[12] ويوم تقوم الساعه ييئس المجرمون من النجاه من العذاب، وتصيبهم الحيره فتنقطع حجتهم."},{"id":"3422","s":30,"a":13,"at":"ولم يكن لهم من شركائهم شفعاء وكانوا بشركائهم كافرين","dt":"[13] ولم يكن للمشركين في ذلك اليوم من الهتهم التي كانوا يعبدونها من دون الله شفعاء، بل انها تتبرا منهم، ويتبرؤون منها. فالشفاعه لله وحده، ولا تطلب من غيره."},{"id":"3423","s":30,"a":14,"at":"ويوم تقوم الساعه يومئذ يتفرقون","dt":"[14] ويوم تقوم الساعه يفترق اهل الايمان واهل الكفر،"},{"id":"3424","s":30,"a":15,"at":"فاما الذين امنوا وعملوا الصالحات فهم في روضه يحبرون","dt":"[15] فاما المؤمنون بالله ورسوله، العاملون الصالحات فهم في الجنه، يكرمون ويسرون وينعمون."},{"id":"3425","s":30,"a":16,"at":"واما الذين كفروا وكذبوا باياتنا ولقاء الاخره فاولئك في العذاب محضرون","dt":"[16] واما الذين كفروا بالله وكذبوا بما جاءت به الرسل وانكروا البعث بعد الموت، فاولئك في العذاب مقيمون؛ جزاء ما كذبوا به في الدنيا."},{"id":"3426","s":30,"a":17,"at":"فسبحان الله حين تمسون وحين تصبحون","dt":"[17] فيا ايها المؤمنون سبحوا الله ونزهوه عن الشريك والصاحبه والولد، وصفوه بصفات الكمال بالسنتكم، وحققوا ذلك بجوارحكم كلها حين تمسون، وحين تصبحون،"},{"id":"3427","s":30,"a":18,"at":"وله الحمد في السموات والارض وعشيا وحين تظهرون","dt":"[18] ووقت العشي، ووقت الظهيره. وله -سبحانه- الحمد والثناء في السموات والارض وفي الليل والنهار."},{"id":"3428","s":30,"a":19,"at":"يخرج الحي من الميت ويخرج الميت من الحي ويحي الارض بعد موتها وكذلك تخرجون","dt":"[19] يخرج الله الحي من الميت كالانسان من النطفه والطير من البيضه، ويخرج الميت من الحي، كالنطفه من الانسان والبيضه من الطير. ويحيي الارض بالنبات بعد يبسها وجفافها، ومثل هذا الاحياء تخرجون -ايها الناس- من قبوركم احياء للحساب والجزاء."},{"id":"3429","s":30,"a":20,"at":"ومن اياته ان خلقكم من تراب ثم اذا انتم بشر تنتشرون","dt":"[20] ومن ايات الله الداله على عظمته وكمال قدرته ان خلق اباكم ادم من تراب، ثم انتم بشر تتناسلون منتشرين في الارض، تبتغون من فضل الله."},{"id":"3430","s":30,"a":21,"at":"ومن اياته ان خلق لكم من انفسكم ازواجا لتسكنوا اليها وجعل بينكم موده ورحمه ان في ذلك لايات لقوم يتفكرون","dt":"[21] ومن اياته الداله على عظمته وكمال قدرته ان خلق لاجلكم من جنسكم -ايها الرجال- ازواجا؛ لتطمئن نفوسكم اليها وتسكن، وجعل بين المراه وزوجها محبه وشفقه، ان في خلق الله ذلك لايات داله على قدره الله ووحدانيته لقوم يتفكرون، ويتدبرون."},{"id":"3431","s":30,"a":22,"at":"ومن اياته خلق السموات والارض واختلاف السنتكم والوانكم ان في ذلك لايات للعالمين","dt":"[22] ومن دلائل القدره الربانيه: خلق السموات وارتفاعها بغير عمد، وخلق الارض مع اتساعها وامتدادها، واختلاف لغاتكم وتباين الوانكم، ان في هذا لعبره لكل ذي علم وبصيره."},{"id":"3432","s":30,"a":23,"at":"ومن اياته منامكم بالليل والنهار وابتغاؤكم من فضله ان في ذلك لايات لقوم يسمعون","dt":"[23] ومن دلائل هذه القدره ان جعل الله النوم راحه لكم في الليل او النهار؛ اذ في النوم حصول الراحه وذهاب التعب، وجعل لكم النهار تنتشرون فيه لطلب الرزق، ان في ذلك لدلائل على كمال قدره الله ونفوذ مشيئته لقوم يسمعون المواعظ سماع تامل وتفكر واعتبار."},{"id":"3433","s":30,"a":24,"at":"ومن اياته يريكم البرق خوفا وطمعا وينزل من السماء ماء فيحيي به الارض بعد موتها ان في ذلك لايات لقوم يعقلون","dt":"[24] ومن دلائل قدرته سبحانه ان يريكم البرق، فتخافوا من الصواعق، وتطمعوا في الغيث، وينزل من السحاب مطرا فيحيي به الارض بعد جدبها وجفافها، ان في هذا لدليلا على كمال قدره الله وعظيم حكمته واحسانه لكل من لديه عقل يهتدي به."},{"id":"3434","s":30,"a":25,"at":"ومن اياته ان تقوم السماء والارض بامره ثم اذا دعاكم دعوه من الارض اذا انتم تخرجون","dt":"[25] ومن اياته الداله على قدرته قيام السماء والارض واستقرارهما وثباتهما بامره، فلم تتزلزلا، ولم تسقط السماء على الارض، ثم اذا دعاكم الله الى البعث يوم القيامه، اذا انتم تخرجون من القبور مسرعين."},{"id":"3435","s":30,"a":26,"at":"وله من في السموات والارض كل له قانتون","dt":"[26] ولله وحده كل من في السموات والارض من الملائكه والانس والجن والحيوان والنبات والجماد، كل هؤلاء منقادون لامره خاضعون لكماله."},{"id":"3436","s":30,"a":27,"at":"وهو الذي يبدا الخلق ثم يعيده وهو اهون عليه وله المثل الاعلى في السموات والارض وهو العزيز الحكيم","dt":"[27] والله وحده الذي يبدا الخلق من العدم ثم يعيده حيا بعد الموت، واعاده الخلق حيا بعد الموت اهون على الله من ابتداء خلقهم، وكلاهما عليه هين. وله سبحانه الوصف الاعلى في كل ما يوصف به، ليس كمثله شيء، وهو السميع البصير. وهو العزيز الذي لا يغالب، الحكيم في اقواله وافعاله، وتدبير امور خلقه."},{"id":"3437","s":30,"a":28,"at":"ضرب لكم مثلا من انفسكم هل لكم من ما ملكت ايمانكم من شركاء في ما رزقناكم فانتم فيه سواء تخافونهم كخيفتكم انفسكم كذلك نفصل الايات لقوم يعقلون","dt":"[28] ضرب الله مثلا لكم -ايها المشركون- من انفسكم: هل لكم من عبيدكم وامائكم من يشارككم في رزقكم، وترون انكم واياهم متساوون فيه، تخافونهم كما تخافون الاحرار الشركاء في مقاسمه اموالكم؟ انكم لن ترضوا بذلك، فكيف ترضون بذلك في جنب الله بان تجعلوا له شريكا من خلقه؟ بمثل هذا البيان نبين البراهين والحجج لاصحاب العقول السليمه الذين ينتفعون بها."},{"id":"3438","s":30,"a":29,"at":"بل اتبع الذين ظلموا اهواءهم بغير علم فمن يهدي من اضل الله وما لهم من ناصرين","dt":"[29] بل اتبع المشركون اهواءهم بتقليد ابائهم بغير علم، فشاركوهم في الجهل والضلاله، ولا احد يقدر على هدايه من اضله الله بسبب تماديه في الكفر والعناد، وليس لهؤلاء من انصار يخلصونهم من عذاب الله."},{"id":"3439","s":30,"a":30,"at":"فاقم وجهك للدين حنيفا فطره الله التي فطر الناس عليها لا تبديل لخلق الله ذلك الدين القيم ولكن اكثر الناس لا يعلمون","dt":"[30] فاقم -ايها الرسول انت ومن اتبعك- وجهك، واستمر على الدين الذي شرعه الله لك، وهو الاسلام الذي فطر الله الناس عليه، فبقاؤكم عليه، وتمسككم به، تمسك بفطره الله من الايمان بالله وحده، لا تبديل لخلق الله ودينه، فهو الطريق المستقيم الموصل الى رضا الله رب العالمين وجنته، ولكن اكثر الناس لا يعلمون ان الذي امرتك به -ايها الرسول- هو الدين الحق دون سواه."},{"id":"3440","s":30,"a":31,"at":"منيبين اليه واتقوه واقيموا الصلاه ولا تكونوا من المشركين","dt":"[31] وكونوا راجعين الى الله بالتوبه واخلاص العمل له، واتقوه بفعل الاوامر واجتناب النواهي، واقيموا الصلاه تامه باركانها وواجباتها وشروطها، ولا تكونوا من المشركين مع الله غيره في العباده."},{"id":"3441","s":30,"a":32,"at":"من الذين فرقوا دينهم وكانوا شيعا كل حزب بما لديهم فرحون","dt":"[32] ولا تكونوا من المشركين واهل الاهواء والبدع الذين بدلوا دينهم وغيروه، فاخذوا بعضه وتركوا بعضه؛ تبعا لاهوائهم، فصاروا فرقا واحزابا، يتشيعون لرؤسائهم واحزابهم وارائهم، يعين بعضهم بعضا على الباطل، كل حزب بما لديهم فرحون مسرورون، يحكمون لانفسهم بانهم على الحق وغيرهم على الباطل."},{"id":"3442","s":30,"a":33,"at":"واذا مس الناس ضر دعوا ربهم منيبين اليه ثم اذا اذاقهم منه رحمه اذا فريق منهم بربهم يشركون","dt":"[33] واذا اصاب الناس شده وبلاء دعوا ربهم مخلصين له ان يكشف عنهم الضر، فاذا رحمهم وكشف عنهم ضرهم اذا فريق منهم يعودون الى الشرك مره اخرى، فيعبدون مع الله غيره."},{"id":"3443","s":30,"a":34,"at":"ليكفروا بما اتيناهم فتمتعوا فسوف تعلمون","dt":"[34] ليكفروا بما اتيناهم ومننا به عليهم من كشف الضر، وزوال الشده عنهم، فتمتعوا -ايها المشركون- بالرخاء والسعه في هذه الدنيا، فسوف تعلمون ما تلقونه من العذاب والعقاب."},{"id":"3444","s":30,"a":35,"at":"ام انزلنا عليهم سلطانا فهو يتكلم بما كانوا به يشركون","dt":"[35] ام انزلنا على هؤلاء المشركين برهانا ساطعا وكتابا قاطعا، ينطق بصحه شركهم وكفرهم بالله واياته."},{"id":"3445","s":30,"a":36,"at":"واذا اذقنا الناس رحمه فرحوا بها وان تصبهم سيئه بما قدمت ايديهم اذا هم يقنطون","dt":"[36] واذا اذقنا الناس منا نعمه من صحه وعافيه ورخاء، فرحوا بذلك فرح بطر واشر، لا فرح شكر، وان يصبهم مرض وفقر وخوف وضيق بسبب ذنوبهم ومعاصيهم، اذا هم ييئسون من زوال ذلك، وهذا طبيعه اكثر الناس في الرخاء والشده."},{"id":"3446","s":30,"a":37,"at":"او لم يروا ان الله يبسط الرزق لمن يشاء ويقدر ان في ذلك لايات لقوم يؤمنون","dt":"[37] اولم يعلموا ان الله يوسع الرزق لمن يشاء امتحانا، هل يشكر او يكفر؟ ويضيقه على من يشاء اختبارا، هل يصبر او يجزع؟ ان في ذلك التوسيع والتضييق لايات لقوم يؤمنون بالله ويعرفون حكمه الله ورحمته."},{"id":"3447","s":30,"a":38,"at":"فات ذا القربى حقه والمسكين وابن السبيل ذلك خير للذين يريدون وجه الله واولئك هم المفلحون","dt":"[38] فاعط -ايها المؤمن- قريبك حقه من الصله والصدقه وسائر اعمال البر، واعط الفقير الذي لا يملك ما يكفيه ويسد حاجته، والمحتاج الذي انقطع به السبيل من الزكاه والصدقه، ذلك الاعطاء خير للذين يريدون بعملهم وجه الله، والذين يعملون هذه الاعمال وغيرها من اعمال الخير، اولئك هم الفائزون بثواب الله الناجون من عقابه."},{"id":"3448","s":30,"a":39,"at":"وما اتيتم من ربا ليربو في اموال الناس فلا يربو عند الله وما اتيتم من زكاه تريدون وجه الله فاولئك هم المضعفون","dt":"[39] وما اعطيتم قرضا من المال بقصد الربا، وطلب زياده ذلك القرض؛ ليزيد وينمو في اموال الناس، فلا يزيد عند الله، بل يمحقه ويبطله. وما اعطيتم من زكاه وصدقه للمستحقين ابتغاء مرضاه الله وطلبا لثوابه، فهذا هو الذي يقبله الله ويضاعفه لكم اضعافا كثيره."},{"id":"3449","s":30,"a":40,"at":"الله الذي خلقكم ثم رزقكم ثم يميتكم ثم يحييكم هل من شركائكم من يفعل من ذلكم من شيء سبحانه وتعالى عما يشركون","dt":"[40] الله وحده هو الذي خلقكم -ايها الناس- ثم رزقكم في هذه الحياه، ثم يميتكم بانتهاء اجالكم، ثم يبعثكم من القبور احياء للحساب والجزاء، هل من شركائكم من يفعل من ذلكم من شيء؟ تنزه الله وتقدس عن شرك هؤلاء المشركين به."},{"id":"3450","s":30,"a":41,"at":"ظهر الفساد في البر والبحر بما كسبت ايدي الناس ليذيقهم بعض الذي عملوا لعلهم يرجعون","dt":"[41] ظهر الفساد في البر والبحر، كالجدب وقله الامطار وكثره الامراض والاوبئه؛ وذلك بسبب المعاصي التي يقترفها البشر؛ ليصيبهم بعقوبه بعض اعمالهم التي عملوها في الدنيا؛ كي يتوبوا الى الله -سبحانه- ويرجعوا عن المعاصي، فتصلح احوالهم، وتستقيم امورهم."},{"id":"3451","s":30,"a":42,"at":"قل سيروا في الارض فانظروا كيف كان عاقبه الذين من قبل كان اكثرهم مشركين","dt":"[42] قل -ايها الرسول- للمكذبين بما جئت به: سيروا في انحاء الارض سير اعتبار وتامل، فانظروا كيف كان عاقبه الامم السابقه المكذبه كقوم نوح، وعاد وثمود، تجدوا عاقبتهم شر العواقب ومالهم شر مال؟ فقد كان اكثرهم مشركين بالله."},{"id":"3452","s":30,"a":43,"at":"فاقم وجهك للدين القيم من قبل ان ياتي يوم لا مرد له من الله يومئذ يصدعون","dt":"[43] فوجه وجهك -ايها الرسول- نحو الدين المستقيم، وهو الاسلام، منفذا اوامره مجتنبا نواهيه، واستمسك به من قبل مجيء يوم القيامه، فاذا جاء ذلك اليوم الذي لا يقدر احد على رده تفرقت الخلائق اشتاتا متفاوتين؛ ليروا اعمالهم."},{"id":"3453","s":30,"a":44,"at":"من كفر فعليه كفره ومن عمل صالحا فلانفسهم يمهدون","dt":"[44] من كفر فعليه عقوبه كفره، وهي خلوده في النار، ومن امن وعمل صالحا فلانفسهم يهيئون منازل الجنه؛ بسبب تمسكهم بطاعه ربهم."},{"id":"3454","s":30,"a":45,"at":"ليجزي الذين امنوا وعملوا الصالحات من فضله انه لا يحب الكافرين","dt":"[45] ليجزي الله الذين امنوا بالله ورسوله وعملوا الصالحات من فضله واحسانه. انه لا يحب الكافرين لسخطه وغضبه عليهم."},{"id":"3455","s":30,"a":46,"at":"ومن اياته ان يرسل الرياح مبشرات وليذيقكم من رحمته ولتجري الفلك بامره ولتبتغوا من فضله ولعلكم تشكرون","dt":"[46] ومن ايات الله الداله على انه الاله الحق وحده لا شريك له وعلى عظيم قدرته ارسال الرياح امام المطر مبشرات باثارتها للسحاب، فتستبشر بذلك النفوس؛ وليذيقكم من رحمته بانزاله المطر الذي تحيا به البلاد والعباد، ولتجري السفن في البحر بامر الله ومشيئته، ولتبتغوا من فضله بالتجاره وغيرها؛ فعل الله ذلك من اجل ان تشكروا له نعمه وتعبدوه وحده."},{"id":"3456","s":30,"a":47,"at":"ولقد ارسلنا من قبلك رسلا الى قومهم فجاءوهم بالبينات فانتقمنا من الذين اجرموا وكان حقا علينا نصر المؤمنين","dt":"[47] ولقد ارسلنا من قبلك -ايها الرسول- رسلا الى قومهم مبشرين ومنذرين يدعونهم الى التوحيد، ويحذرونهم من الشرك، فجاؤوهم بالمعجزات والبراهين الساطعه، فكفر اكثرهم بربهم، فانتقمنا من الذين اكتسبوا السيئات منهم، فاهلكناهم، ونصرنا المؤمنين اتباع الرسل، وكذلك نفعل بالمكذبين بك ان استمروا على تكذيبك، ولم يؤمنوا."},{"id":"3457","s":30,"a":48,"at":"الله الذي يرسل الرياح فتثير سحابا فيبسطه في السماء كيف يشاء ويجعله كسفا فترى الودق يخرج من خلاله فاذا اصاب به من يشاء من عباده اذا هم يستبشرون","dt":"[48] الله -سبحانه- هو الذي يرسل الرياح فتثير سحابا مثقلا بالماء، فينشره الله في السماء كيف يشاء، ويجعله قطعا متفرقه، فترى المطر يخرج من بين السحاب، فاذا ساقه الله الى عباده اذا هم يستبشرون ويفرحون بان الله صرف ذلك اليهم."},{"id":"3458","s":30,"a":49,"at":"وان كانوا من قبل ان ينزل عليهم من قبله لمبلسين","dt":"[49] وان كانوا من قبل نزول المطر لفي ياس وقنوط؛ بسبب احتباسه عنهم."},{"id":"3459","s":30,"a":50,"at":"فانظر الى اثار رحمه الله كيف يحي الارض بعد موتها ان ذلك لمحي الموتى وهو على كل شيء قدير","dt":"[50] فانظر -ايها المشاهد- نظر تامل وتدبر الى اثار المطر في النبات والزروع والشجر، كيف يحيي به الله الارض بعد موتها، فينبتها ويعشبها؟ ان الذي قدر على احياء هذه الارض لمحيي الموتى، وهو على كل شيء قدير لا يعجزه شيء."},{"id":"3460","s":30,"a":51,"at":"ولئن ارسلنا ريحا فراوه مصفرا لظلوا من بعده يكفرون","dt":"[51] ولئن ارسلنا على زروعهم ونباتهم ريحا مفسده، فراوا نباتهم قد فسد بتلك الريح، فصار من بعد خضرته مصفرا، لمكثوا من بعد رؤيتهم له يكفرون بالله ويجحدون نعمه."},{"id":"3461","s":30,"a":52,"at":"فانك لا تسمع الموتى ولا تسمع الصم الدعاء اذا ولوا مدبرين","dt":"[52] فانك -ايها الرسول- لا تسمع من مات قلبه، او سد اذنه عن سماع الحق، فلا تجزع ولا تحزن على عدم ايمان هؤلاء المشركين بك، فانهم كالصم والموتى لا يسمعون، ولا يشعرون ولو كانوا حاضرين، فكيف اذا كانوا غائبين عنك مدبرين؟"},{"id":"3462","s":30,"a":53,"at":"وما انت بهاد العمي عن ضلالتهم ان تسمع الا من يؤمن باياتنا فهم مسلمون","dt":"[53] وما انت -ايها الرسول- بمرشد من اعماه الله عن طريق الهدى، ما تسمع سماع انتفاع الا من يؤمن باياتنا، فهم خاضعون ممتثلون لامر الله."},{"id":"3463","s":30,"a":54,"at":"الله الذي خلقكم من ضعف ثم جعل من بعد ضعف قوه ثم جعل من بعد قوه ضعفا وشيبه يخلق ما يشاء وهو العليم القدير","dt":"[54] الله تعالى هو الذي خلقكم من ماء ضعيف مهين، وهو النطفه، ثم جعل من بعد ضعف الطفوله قوه الشباب واكتماله، ثم جعل من بعد هذه القوه ضعف الكبر والهرم، يخلق الله ما يشاء من الضعف والقوه، وهو العليم بخلقه، القادر على كل شيء."},{"id":"3464","s":30,"a":55,"at":"ويوم تقوم الساعه يقسم المجرمون ما لبثوا غير ساعه كذلك كانوا يؤفكون","dt":"[55] ويوم تجيء القيامه ويبعث الله الخلق من قبورهم يقسم المشركون ما مكثوا في الدنيا غير فتره قصيره من الزمن، كذبوا في قسمهم كما كانوا يكذبون في الدنيا، ويصرفون عن الحق الذي جاءت به الرسل."},{"id":"3465","s":30,"a":56,"at":"وقال الذين اوتوا العلم والايمان لقد لبثتم في كتاب الله الى يوم البعث فهذا يوم البعث ولكنكم كنتم لا تعلمون","dt":"[56] وقال الذين اوتوا العلم والايمان بالله من الملائكه والانبياء والمؤمنين: لقد مكثتم فيما كتب الله مما سبق في علمه من يوم خلقتم الى ان بعثتم، فهذا يوم البعث، ولكنكم كنتم لا تعلمون، فانكرتموه في الدنيا، وكذبتم به."},{"id":"3466","s":30,"a":57,"at":"فيومئذ لا ينفع الذين ظلموا معذرتهم ولا هم يستعتبون","dt":"[57] فيوم القيامه لا ينفع الظالمين ما يقدمونه من اعذار، ولا يطلب منهم ارضاء الله تعالى بالتوبه والطاعه، بل يعاقبون بسيئاتهم ومعاصيهم."},{"id":"3467","s":30,"a":58,"at":"ولقد ضربنا للناس في هذا القران من كل مثل ولئن جئتهم بايه ليقولن الذين كفروا ان انتم الا مبطلون","dt":"[58] ولقد بينا للناس في هذا القران من كل مثل من اجل اقامه الحجه عليهم واثبات وحدانيه الله جل وعلا، ولئن جئتهم -ايها الرسول- باي حجه تدل على صدقك ليقولن الذين كفروا بك: ما انتم -ايها الرسول واتباعك- الا مبطلون فيما تجيئوننا به من الامور."},{"id":"3468","s":30,"a":59,"at":"كذلك يطبع الله على قلوب الذين لا يعلمون","dt":"[59] مثل ذلك الختم يختم الله على قلوب الذين لا يعلمون حقيقه ما تاتيهم به -ايها الرسول- من عند الله من هذه العبر والايات البينات."},{"id":"3469","s":30,"a":60,"at":"فاصبر ان وعد الله حق ولا يستخفنك الذين لا يوقنون","dt":"[60] فاصبر -ايها الرسول- على ما ينالك من اذى قومك وتكذيبهم لك، ان ما وعدك الله به من نصر وتمكين وثواب حق لا شك فيه، ولا يستفزنك عن دينك الذين لا يوقنون بالميعاد، ولا يصدقون بالبعث والجزاء."},{"id":"3470","s":31,"a":1,"at":"الم","dt":"[1] الم سبق الكلام على الحروف المقطعه في اول سوره البقره."},{"id":"3471","s":31,"a":2,"at":"تلك ايات الكتاب الحكيم","dt":"[2] هذه الايات ايات القران ذي الحكمه البالغه."},{"id":"3472","s":31,"a":3,"at":"هدى ورحمه للمحسنين","dt":"[3] هذه الايات هدى ورحمه للذين احسنوا العمل بما انزل الله في القران، وما امرهم به رسوله محمد -صلى الله عليه وسلم-."},{"id":"3473","s":31,"a":4,"at":"الذين يقيمون الصلاه ويؤتون الزكاه وهم بالاخره هم يوقنون","dt":"[4] الذين يؤدون الصلاه كامله في اوقاتها ويؤتون الزكاه المفروضه عليهم لمستحقيها، وهم بالبعث والجزاء في الدار الاخره يوقنون."},{"id":"3474","s":31,"a":5,"at":"اولئك على هدى من ربهم واولئك هم المفلحون","dt":"[5] اولئك المتصفون بالصفات السابقه على بيان من ربهم ونور، واولئك هم الفائزون في الدنيا والاخره."},{"id":"3475","s":31,"a":6,"at":"ومن الناس من يشتري لهو الحديث ليضل عن سبيل الله بغير علم ويتخذها هزوا اولئك لهم عذاب مهين","dt":"[6] ومن الناس من يشتري لهو الحديث -وهو كل ما يلهي عن طاعه الله ويصد عن مرضاته- ليضل الناس عن طريق الهدى الى طريق الهوى، ويتخذ ايات الله سخريه، اولئك لهم عذاب يهينهم ويخزيهم."},{"id":"3476","s":31,"a":7,"at":"واذا تتلى عليه اياتنا ولى مستكبرا كان لم يسمعها كان في اذنيه وقرا فبشره بعذاب اليم","dt":"[7] واذا تتلى عليه ايات القران اعرض عن طاعه الله، وتكبر غير معتبر، كانه لم يسمع شيئا، كان في اذنيه صمما، ومن هذه حاله فبشره -ايها الرسول- بعذاب مؤلم موجع في النار يوم القيامه."},{"id":"3477","s":31,"a":8,"at":"ان الذين امنوا وعملوا الصالحات لهم جنات النعيم","dt":"[8] ان الذين امنوا بالله ورسوله وعملوا الصالحات التي امروا بها، اولئك لهم نعيم مقيم في الجنات."},{"id":"3478","s":31,"a":9,"at":"خالدين فيها وعد الله حقا وهو العزيز الحكيم","dt":"[9] وحياتهم في تلك الجنات حياه ابديه لا تنقطع ولا تزول، وعدهم الله بذلك وعدا حقا. وهو سبحانه لا يخلف وعده، وهو العزيز في امره، الحكيم في تدبيره."},{"id":"3479","s":31,"a":10,"at":"خلق السموات بغير عمد ترونها والقى في الارض رواسي ان تميد بكم وبث فيها من كل دابه وانزلنا من السماء ماء فانبتنا فيها من كل زوج كريم","dt":"[10] خلق الله السموات ورفعها بغير عمد كما تشاهدونها، والقى في الارض جبالا ثابته؛ لئلا تضطرب وتتحرك فتفسد حياتكم، ونشر في الارض مختلف انواع الدواب، وانزلنا من السحاب مطرا، فانبتنا به في الارض من كل زوج بهيج نافع حسن المنظر."},{"id":"3480","s":31,"a":11,"at":"هذا خلق الله فاروني ماذا خلق الذين من دونه بل الظالمون في ضلال مبين","dt":"[11] وكل ما تشاهدونه هو خلق الله، فاروني -ايها المشركون-: ماذا خلقت الهتكم التي تعبدونها من دون الله؟ بل المشركون في ذهاب بين عن الحق والاستقامه."},{"id":"3481","s":31,"a":12,"at":"ولقد اتينا لقمان الحكمه ان اشكر لله ومن يشكر فانما يشكر لنفسه ومن كفر فان الله غني حميد","dt":"[12] ولقد اعطينا عبدا صالحا من عبادنا -وهو لقمان-الحكمه، وهي الفقه في الدين والعقل والاصابه في القول، وقلنا له: اشكر لله نعمه عليك، ومن يشكر لربه فانما يعود نفع ذلك عليه، ومن جحد نعمه فان الله غني عن شكره، غير محتاج اليه، له الحمد والثناء على كل حال."},{"id":"3482","s":31,"a":13,"at":"واذ قال لقمان لابنه وهو يعظه يابني لا تشرك بالله ان الشرك لظلم عظيم","dt":"[13] واذكر -ايها الرسول- نصيحه لقمان لابنه حين قال له واعظا: يا بني لا تشرك بالله فتظلم نفسك؛ ان الشرك لاعظم الكبائر وابشعها."},{"id":"3483","s":31,"a":14,"at":"ووصينا الانسان بوالديه حملته امه وهنا على وهن وفصاله في عامين ان اشكر لي ولوالديك الي المصير","dt":"[14] وامرنا الانسان ببر والديه والاحسان اليهما، حملته امه ضعفا على ضعف، وتمام فطامه عن الرضاعه في مده عامين، وقلنا له: اشكر لله، ثم اشكر لوالديك، الي المرجع فاجازي كلا بما يستحق."},{"id":"3484","s":31,"a":15,"at":"وان جاهداك على ان تشرك بي ما ليس لك به علم فلا تطعهما وصاحبهما في الدنيا معروفا واتبع سبيل من اناب الي ثم الي مرجعكم فانبئكم بما كنتم تعملون","dt":"[15] وان جاهدك -ايها الولد المؤمن- والداك على ان تشرك بي غيري في عبادتك اياي مما ليس لك به علم، او امراك بمعصيه من معاصي الله فلا تطعهما؛ لانه لا طاعه لمخلوق في معصيه الخالق، وصاحبهما في الدنيا بالمعروف فيما لا اثم فيه، واسلك -ايها الابن المؤمن- طريق من تاب من ذنبه، ورجع الي وامن برسولي محمد -صلى الله عليه وسلم-، ثم الي مرجعكم، فاخبركم بما كنتم تعملونه في الدنيا، واجازي كل عامل بعمله."},{"id":"3485","s":31,"a":16,"at":"يابني انها ان تك مثقال حبه من خردل فتكن في صخره او في السموات او في الارض يات بها الله ان الله لطيف خبير","dt":"[16] يا بني اعلم ان السيئه او الحسنه ان كانت قدر حبه خردل -وهي المتناهيه في الصغر- في باطن جبل، او في اي مكان في السموات او في الارض، فان الله ياتي بها يوم القيامه، ويحاسب عليها. ان الله لطيف بعباده خبير باعمالهم."},{"id":"3486","s":31,"a":17,"at":"يابني اقم الصلاه وامر بالمعروف وانه عن المنكر واصبر على ما اصابك ان ذلك من عزم الامور","dt":"[17] يا بني اقم الصلاه تامه باركانها وشروطها وواجباتها، وامر بالمعروف، وانه عن المنكر بلطف ولين وحكمه بحسب جهدك، وتحمل ما يصيبك من الاذى مقابل امرك بالمعروف ونهيك عن المنكر، واعلم ان هذه الوصايا مما امر الله به من الامور التي ينبغي الحرص عليها."},{"id":"3487","s":31,"a":18,"at":"ولا تصعر خدك للناس ولا تمش في الارض مرحا ان الله لا يحب كل مختال فخور","dt":"[18] ولا تمل وجهك عن الناس اذا كلمتهم او كلموك؛ احتقارا منك لهم واستكبارا عليهم، ولا تمش في الارض بين الناس مختالا متبخترا، ان الله لا يحب كل متكبر متباه في نفسه وهيئته وقوله."},{"id":"3488","s":31,"a":19,"at":"واقصد في مشيك واغضض من صوتك ان انكر الاصوات لصوت الحمير","dt":"[19] وتواضع في مشيك، واخفض من صوتك فلا ترفعه، ان اقبح الاصوات وابغضها لصوت الحمير المعروفه ببلادتها واصواتها المرتفعه."},{"id":"3489","s":31,"a":20,"at":"الم تروا ان الله سخر لكم ما في السموات وما في الارض واسبغ عليكم نعمه ظاهره وباطنه ومن الناس من يجادل في الله بغير علم ولا هدى ولا كتاب منير","dt":"[20] الم تروا -ايها الناس- ان الله ذلل لكم ما في السموات من الشمس والقمر والسحاب وغير ذلك، وما في الارض من الدواب والشجر والماء، وغير ذلك مما لا يحصى، وعمكم بنعمه الظاهره على الابدان والجوارح، والباطنه في العقول والقلوب، وما ادخره لكم مما لا تعلمونه؟ ومن الناس من يجادل في توحيد الله واخلاص العباده له بغير حجه ولا بيان، ولا كتاب مبين يبين حقيقه دعواه."},{"id":"3490","s":31,"a":21,"at":"واذا قيل لهم اتبعوا ما انزل الله قالوا بل نتبع ما وجدنا عليه اباءنا اولو كان الشيطان يدعوهم الى عذاب السعير","dt":"[21] واذا قيل لهؤلاء المجادلين في توحيد الله وافراده بالعباده: اتبعوا ما انزل الله على نبيه محمد -صلى الله عليه وسلم- قالوا: بل نتبع ما كان عليه اباؤنا من الشرك وعباده الاصنام، ايفعلون ذلك، ولو كان الشيطان يدعوهم؛ بتزيينه لهم سوء اعمالهم، وكفرهم بالله الى عذاب النار المستعره؟"},{"id":"3491","s":31,"a":22,"at":"ومن يسلم وجهه الى الله وهو محسن فقد استمسك بالعروه الوثقى والى الله عاقبه الامور","dt":"[22] ومن يخلص عبادته لله وقصده الى ربه تعالى، وهو محسن في اقواله متقن لاعماله، فقد اخذ باوثق سبب موصل الى رضوان الله وجنته. والى الله وحده تصير كل الامور، فيجازي المحسن على احسانه، والمسيء على اساءته."},{"id":"3492","s":31,"a":23,"at":"ومن كفر فلا يحزنك كفره الينا مرجعهم فننبئهم بما عملوا ان الله عليم بذات الصدور","dt":"[23] ومن كفر فلا تاس عليه -ايها الرسول- ولا تحزن؛ لانك اديت ما عليك من الدعوه والبلاغ، الينا مرجعهم ومصيرهم يوم القيامه، فنخبرهم باعمالهم الخبيثه التي عملوها في الدنيا، ثم نجازيهم عليها، ان الله عليم بما تكنه صدورهم من الكفر بالله وايثار طاعه الشيطان."},{"id":"3493","s":31,"a":24,"at":"نمتعهم قليلا ثم نضطرهم الى عذاب غليظ","dt":"[24] نمتعهم في هذه الدنيا الفانيه مده قليله، ثم يوم القيامه نلجئهم ونسوقهم الى عذاب فظيع، وهو عذاب جهنم."},{"id":"3494","s":31,"a":25,"at":"ولئن سالتهم من خلق السموات والارض ليقولن الله قل الحمد لله بل اكثرهم لا يعلمون","dt":"[25] ولئن سالت -ايها الرسول- هؤلاء المشركين بالله: من خلق السموات والارض؟ ليقولن الله، فاذا قالوا ذلك فقل لهم: الحمد لله الذي اظهر الاستدلال عليكم من انفسكم، بل اكثر هؤلاء المشركين لا ينظرون ولا يتدبرون من الذي له الحمد والشكر، فلذلك اشركوا معه غيره."},{"id":"3495","s":31,"a":26,"at":"لله ما في السموات والارض ان الله هو الغني الحميد","dt":"[26] لله -سبحانه- كل ما في السموات والارض ملكا وعبيدا وايجادا وتقديرا، فلا يستحق العباده احد غيره. ان الله هو الغني عن خلقه، له الحمد والثناء على كل حال."},{"id":"3496","s":31,"a":27,"at":"ولو انما في الارض من شجره اقلام والبحر يمده من بعده سبعه ابحر ما نفدت كلمات الله ان الله عزيز حكيم","dt":"[27] ولو ان اشجار الارض كلها بريت اقلاما والبحر مداد لها، ويمد بسبعه ابحر اخرى، وكتب بتلك الاقلام وذلك المداد كلمات الله من علمه وحكمه، وما اوحاه الى ملائكته ورسله؛ لتكسرت تلك الاقلام ولنفد ذلك المداد، ولم تنفد كلمات الله التامه التي لا يحيط بها احد. ان الله عزيز في انتقامه ممن اشرك به، حكيم في تدبير خلقه. وفي الايه اثبات صفه الكلام لله -تعالى- حقيقه كما يليق بجلاله وكماله سبحانه."},{"id":"3497","s":31,"a":28,"at":"ما خلقكم ولا بعثكم الا كنفس واحده ان الله سميع بصير","dt":"[28] ما خلقكم -ايها الناس- ولا بعثكم يوم القيامه في السهوله واليسر الا كخلق نفس واحده وبعثها. ان الله سميع لاقوالكم، بصير باعمالكم، وسيجازيكم عليها."},{"id":"3498","s":31,"a":29,"at":"الم تر ان الله يولج الليل في النهار ويولج النهار في الليل وسخر الشمس والقمر كل يجري الى اجل مسمى وان الله بما تعملون خبير","dt":"[29] الم تر ان الله ياخذ من ساعات الليل، فيطول النهار ويقصر الليل، وياخذ من ساعات النهار، فيطول الليل ويقصر النهار، وذلل لكم الشمس والقمر، يجري كل منهما في مداره الى اجل معلوم محدد، وان الله مطلع على كل اعمال الخلق من خير او شر، لا يخفى عليه منها شيء؟"},{"id":"3499","s":31,"a":30,"at":"ذلك بان الله هو الحق وان ما يدعون من دونه الباطل وان الله هو العلي الكبير","dt":"[30] ذلك كله من عظيم قدره الله؛ لتعلموا وتقروا ان الله هو الحق في ذاته وصفاته وافعاله، وان ما يدعون من دونه الباطل، وان الله هو العلي بذاته وقدره وقهره فوق جميع مخلوقاته، الكبير على كل شيء، وكل ما عداه خاضع له، فهو وحده المستحق ان يعبد دون من سواه."},{"id":"3500","s":31,"a":31,"at":"الم تر ان الفلك تجري في البحر بنعمه الله ليريكم من اياته ان في ذلك لايات لكل صبار شكور","dt":"[31] الم تر -ايها المشاهد- ان السفن تجري في البحر بامر الله نعمه منه على خلقه؛ ليريكم من عبره وحججه عليكم ما تعتبرون به؟ ان في جري السفن في البحر لدلالات لكل صبار عن محارم الله وعلى طاعته وعلى اقداره، شكور لنعمه."},{"id":"3501","s":31,"a":32,"at":"واذا غشيهم موج كالظلل دعوا الله مخلصين له الدين فلما نجاهم الى البر فمنهم مقتصد وما يجحد باياتنا الا كل ختار كفور","dt":"[32] واذا ركب المشركون السفن وعلتهم الامواج من حولهم كالسحب والجبال، اصابهم الخوف والذعر من الغرق، ففزعوا الى الله، واخلصوا دعاءهم له، فلما نجاهم الى البر فمنهم متوسط لم يقم بشكر الله على وجه الكمال، ومنهم كافر بنعمه الله جاحد لها، وما يكفر باياتنا وحججنا الداله على كمال قدرتنا ووحدانيتنا الا كل غدار ناقض للعهد، جحود لنعم الله عليه."},{"id":"3502","s":31,"a":33,"at":"ياايها الناس اتقوا ربكم واخشوا يوما لا يجزي والد عن ولده ولا مولود هو جاز عن والده شيئا ان وعد الله حق فلا تغرنكم الحياه الدنيا ولا يغرنكم بالله الغرور","dt":"[33] يا ايها الناس اتقوا ربكم واطيعوه بامتثال اوامره واجتناب نواهيه، واحذروا يوم القيامه الذي لا يغني فيه والد عن ولده ولا مولود عن ابيه شيئا، ان وعد الله حق لا ريب فيه، فلا تنخدعوا بالحياه الدنيا وزخرفها فتنسيكم الاخرى، ولا يخدعنكم بالله خادع من شياطين الجن والانس."},{"id":"3503","s":31,"a":34,"at":"ان الله عنده علم الساعه وينزل الغيث ويعلم ما في الارحام وما تدري نفس ماذا تكسب غدا وما تدري نفس باي ارض تموت ان الله عليم خبير","dt":"[34] ان الله -وحده لا غيره- يعلم متى تقوم الساعه، وهو الذي ينزل المطر من السحاب، لا يقدر على ذلك احد غيره، ويعلم ما في ارحام الاناث، ويعلم ما تكسبه كل نفس في غدها، وما تعلم نفس باي ارض تموت. بل الله تعالى هو المختص بعلم ذلك جميعه. ان الله عليم خبير محيط بالظواهر والبواطن، لا يخفى عليه شيء منها."},{"id":"3504","s":32,"a":1,"at":"الم","dt":"[1] الم سبق الكلام على الحروف المقطعه في اول سوره البقره."},{"id":"3505","s":32,"a":2,"at":"تنزيل الكتاب لا ريب فيه من رب العالمين","dt":"[2] هذا القران الذي جاء به محمد -صلى الله عليه وسلم- لا شك انه منزل من عند الله، رب الخلائق اجمعين."},{"id":"3506","s":32,"a":3,"at":"ام يقولون افتراه بل هو الحق من ربك لتنذر قوما ما اتاهم من نذير من قبلك لعلهم يهتدون","dt":"[3] بل ايقول المشركون: اختلق محمد -صلى الله عليه وسلم- القران؟ كذبوا، بل هو الحق الثابت المنزل عليك -ايها الرسول- من ربك؛ لتنذر به اناسا لم ياتهم نذير من قبلك لعلهم يهتدون، فيعرفوا الحق ويؤمنوا به ويؤثروه، ويؤمنوا بك."},{"id":"3507","s":32,"a":4,"at":"الله الذي خلق السموات والارض وما بينهما في سته ايام ثم استوى على العرش ما لكم من دونه من ولي ولا شفيع افلا تتذكرون","dt":"[4] الله الذي خلق السموات والارض وما بينهما في سته ايام؛ لحكمه يعلمها، وهو قادر ان يخلقها بكلمه «كن» فتكون، ثم استوى سبحانه وتعالى -اي: علا وارتفع-على عرشه، استواء يليق بجلاله، لا يكيف، ولا يشبه باستواء المخلوقين. ليس لكم -ايها الناس- من ولي يلي اموركم، او شفيع يشفع لكم عند الله؛ لتنجوا من عذابه، افلا تتعظون وتتفكرون -ايها الناس-، فتفردوا الله بالالوهيه وتخلصوا له العباده؟"},{"id":"3508","s":32,"a":5,"at":"يدبر الامر من السماء الى الارض ثم يعرج اليه في يوم كان مقداره الف سنه مما تعدون","dt":"[5] يدبر الله تعالى امر المخلوقات من السماء الى الارض، ثم يصعد ذلك الامر والتدبير الى الله في يوم مقداره الف سنه من ايام الدنيا التي تعدونها."},{"id":"3509","s":32,"a":6,"at":"ذلك عالم الغيب والشهاده العزيز الرحيم","dt":"[6] ذلك الخالق المدبر لشؤون العالمين، عالم بكل ما يغيب عن الابصار، مما تكنه الصدور وتخفيه النفوس، وعالم بما شاهدته الابصار، وهو القوي الظاهر الذي لا يغالب، الرحيم بعباده المؤمنين."},{"id":"3510","s":32,"a":7,"at":"الذي احسن كل شيء خلقه وبدا خلق الانسان من طين","dt":"[7] الله الذي احكم خلق كل شيء، وبدا خلق الانسان، وهو ادم عليه السلام من طين."},{"id":"3511","s":32,"a":8,"at":"ثم جعل نسله من سلاله من ماء مهين","dt":"[8] ثم جعل ذريه ادم متناسله من نطفه ضعيفه رقيقه مهينه."},{"id":"3512","s":32,"a":9,"at":"ثم سواه ونفخ فيه من روحه وجعل لكم السمع والابصار والافئده قليلا ما تشكرون","dt":"[9] ثم اتم خلق الانسان وابدعه، واحسن خلقته، ونفخ فيه من روحه بارسال الملك له؛ لينفخ فيه الروح، وجعل لكم -ايها الناس- نعمه السمع والابصار، يميز بها بين الاصوات والالوان والذوات والاشخاص، ونعمه العقل يميز بها بين الخير والشر والنافع والضار. قليلا ما تشكرون ربكم على ما انعم به عليكم."},{"id":"3513","s":32,"a":10,"at":"وقالوا ائذا ضللنا في الارض ائنا لفي خلق جديد بل هم بلقاء ربهم كافرون","dt":"[10] وقال المشركون بالله المكذبون بالبعث: ااذا صارت لحومنا وعظامنا ترابا في الارض انبعث خلقا جديدا؟ يستبعدون ذلك غير طالبين الوصول الى الحق، وانما هو منهم ظلم وعناد؛ لانهم بلقاء ربهم -يوم القيامه- كافرون."},{"id":"3514","s":32,"a":11,"at":"قل يتوفاكم ملك الموت الذي وكل بكم ثم الى ربكم ترجعون","dt":"[11] قل -ايها الرسول- لهؤلاء المشركين: يتوفاكم ملك الموت الذي وكل بكم، فيقبض ارواحكم اذا انتهت اجالكم، ولن تتاخروا لحظه واحده، ثم تردون الى ربكم، فيجازيكم على جميع اعمالكم: ان خيرا فخير وان شرا فشر."},{"id":"3515","s":32,"a":12,"at":"ولو ترى اذ المجرمون ناكسوا رءوسهم عند ربهم ربنا ابصرنا وسمعنا فارجعنا نعمل صالحا انا موقنون","dt":"[12] ولو ترى -ايها المخاطب- اذ المجرمون الذين انكروا البعث قد خفضوا رؤوسهم عند ربهم من الخزي والعار قائلين: ربنا ابصرنا قبائحنا، وسمعنا منك تصديق ما كانت رسلك تامرنا به في الدنيا، وقد تبنا اليك، فارجعنا الى الدنيا لنعمل فيها بطاعتك، انا قد ايقنا الان ما كنا به في الدنيا مكذبين من وحدانيتك، وانك تبعث من في القبور. ولو رايت -ايها المخاطب- ذلك كله، لرايت امرا عظيما، وخطبا جسيما."},{"id":"3516","s":32,"a":13,"at":"ولو شئنا لاتينا كل نفس هداها ولكن حق القول مني لاملان جهنم من الجنه والناس اجمعين","dt":"[13] ولو شئنا لاتينا هؤلاء المشركين بالله رشدهم وتوفيقهم للايمان، ولكن حق القول مني ووجب لاملان جهنم من اهل الكفر والمعاصي، من صنفي الجن والانس اجمعين؛ وذلك لاختيارهم الضلاله على الهدى."},{"id":"3517","s":32,"a":14,"at":"فذوقوا بما نسيتم لقاء يومكم هذا انا نسيناكم وذوقوا عذاب الخلد بما كنتم تعملون","dt":"[14] يقال لهؤلاء المشركين -عند دخولهم النار على سبيل التوبيخ-: فذوقوا العذاب؛ بسبب غفلتكم عن الاخره وانغماسكم في لذائذ الدنيا، انا تركناكم اليوم في العذاب، وذوقوا عذاب جهنم الذي لا ينقطع؛ بما كنتم تعملون في الدنيا من الكفر بالله ومعاصيه."},{"id":"3518","s":32,"a":15,"at":"انما يؤمن باياتنا الذين اذا ذكروا بها خروا سجدا وسبحوا بحمد ربهم وهم لا يستكبرون","dt":"[15] انما يصدق بايات القران ويعمل بها الذين اذا وعظوا بها او تليت عليهم سجدوا لربهم خاشعين مطيعين، وسبحوا الله في سجودهم بحمده، وهم لا يستكبرون عن السجود والتسبيح له، وعبادته وحده لا شريك له."},{"id":"3519","s":32,"a":16,"at":"تتجافى جنوبهم عن المضاجع يدعون ربهم خوفا وطمعا ومما رزقناهم ينفقون","dt":"[16] ترتفع جنوب هؤلاء الذين يؤمنون بايات الله عن فراش النوم، يتهجدون لربهم في صلاه الليل، يدعون ربهم خوفا من العذاب وطمعا في الثواب، ومما رزقناهم ينفقون في طاعه الله وفي سبيله."},{"id":"3520","s":32,"a":17,"at":"فلا تعلم نفس ما اخفي لهم من قره اعين جزاء بما كانوا يعملون","dt":"[17] فلا تعلم نفس ما ادخر الله لهؤلاء المؤمنين مما تقر به العين، وينشرح له الصدر؛ جزاء لهم على اعمالهم الصالحه."},{"id":"3521","s":32,"a":18,"at":"افمن كان مؤمنا كمن كان فاسقا لا يستوون","dt":"[18] افمن كان مطيعا لله ورسوله مصدقا بوعده ووعيده، مثل من كفر بالله ورسله وكذب باليوم الاخر؟ لا يستوون عند الله."},{"id":"3522","s":32,"a":19,"at":"اما الذين امنوا وعملوا الصالحات فلهم جنات الماوى نزلا بما كانوا يعملون","dt":"[19] اما الذين امنوا بالله وعملوا بما امروا به فجزاؤهم جنات ياوون اليها، ويقيمون في نعيمها ضيافه لهم؛ جزاء لهم بما كانوا يعملون في الدنيا بطاعته."},{"id":"3523","s":32,"a":20,"at":"واما الذين فسقوا فماواهم النار كلما ارادوا ان يخرجوا منها اعيدوا فيها وقيل لهم ذوقوا عذاب النار الذي كنتم به تكذبون","dt":"[20] واما الذين خرجوا عن طاعه الله وعملوا بمعاصيه فمستقرهم جهنم، كلما ارادوا ان يخرجوا منها اعيدوا فيها، وقيل لهم -توبيخا وتقريعا-: ذوقوا عذاب النار الذي كنتم به تكذبون في الدنيا."},{"id":"3524","s":32,"a":21,"at":"ولنذيقنهم من العذاب الادنى دون العذاب الاكبر لعلهم يرجعون","dt":"[21] ولنذيقن هؤلاء الفاسقين المكذبين من العذاب الادنى من البلاء والمحن والمصائب في الدنيا قبل العذاب الاكبر يوم القيامه، حيث يعذبون في نار جهنم؛ لعلهم يرجعون ويتوبون من ذنوبهم."},{"id":"3525","s":32,"a":22,"at":"ومن اظلم ممن ذكر بايات ربه ثم اعرض عنها انا من المجرمين منتقمون","dt":"[22] ولا احد اشد ظلما لنفسه ممن وعظ بدلائل الله، ثم اعرض عن ذلك كله، فلم يتعظ بمواعظه، ولكنه استكبر عنها، انا من المجرمين الذين اعرضوا عن ايات الله وحججه، ولم ينتفعوا بها، منتقمون."},{"id":"3526","s":32,"a":23,"at":"ولقد اتينا موسى الكتاب فلا تكن في مريه من لقائه وجعلناه هدى لبني اسرائيل","dt":"[23] ولقد اتينا موسى التوراه كما اتيناك -ايها الرسول- القران، فلا تكن في شك من لقاء موسى ليله الاسراء والمعراج، وجعلنا التوراه هدايه لبني اسرائيل، تدعوهم الى الحق والى طريق مستقيم."},{"id":"3527","s":32,"a":24,"at":"وجعلنا منهم ائمه يهدون بامرنا لما صبروا وكانوا باياتنا يوقنون","dt":"[24] وجعلنا من بني اسرائيل هداه ودعاه الى الخير ياتم بهم الناس، ويدعونهم الى التوحيد وعباده الله وحده وطاعته، وانما نالوا هذه الدرجه العاليه حين صبروا على اوامر الله، وترك زواجره، والدعوه اليه، وتحمل الاذى في سبيله، وكانوا بايات الله وحججه مصدقين على وجه اليقين."},{"id":"3528","s":32,"a":25,"at":"ان ربك هو يفصل بينهم يوم القيامه فيما كانوا فيه يختلفون","dt":"[25] ان ربك -ايها الرسول- يقضي بين المؤمنين والكافرين من بني اسرائيل وغيرهم يوم القيامه بالعدل فيما اختلفوا فيه من امور الدين، ويجازي كل انسان بعمله بادخال اهل الجنه الجنه واهل النار النار."},{"id":"3529","s":32,"a":26,"at":"او لم يهد لهم كم اهلكنا من قبلهم من القرون يمشون في مساكنهم ان في ذلك لايات افلا يسمعون","dt":"[26] اولم يتبين لهؤلاء المكذبين للرسول: كم اهلكنا من قبلهم من الامم السابقه يمشون في مساكنهم، فيشاهدونها عيانا كقوم هود وصالح ولوط؟ ان في ذلك لايات وعظات يستدل بها على صدق الرسل التي جاءتهم، وبطلان ما هم عليه من الشرك، افلا يسمع هؤلاء المكذبون بالرسل مواعظ الله وحججه، فينتفعون بها؟"},{"id":"3530","s":32,"a":27,"at":"او لم يروا انا نسوق الماء الى الارض الجرز فنخرج به زرعا تاكل منه انعامهم وانفسهم افلا يبصرون","dt":"[27] اولم ير المكذبون بالبعث بعد الموت اننا نسوق الماء الى الارض اليابسه الغليظه التي لا نبات فيها، فنخرج به زرعا مختلفا الوانه تاكل منه انعامهم، وتتغذى به ابدانهم فيعيشون به؟ افلا يرون هذه النعم باعينهم، فيعلموا ان الله الذي فعل ذلك قادر على احياء الاموات ونشرهم من قبورهم؟"},{"id":"3531","s":32,"a":28,"at":"ويقولون متى هذا الفتح ان كنتم صادقين","dt":"[28] يستعجل هؤلاء المشركون بالله العذاب، فيقولون: متى هذا الحكم الذي يقضي بيننا وبينكم بتعذيبنا على زعمكم ان كنتم صادقين في دعواكم؟"},{"id":"3532","s":32,"a":29,"at":"قل يوم الفتح لا ينفع الذين كفروا ايمانهم ولا هم ينظرون","dt":"[29] قل لهم -ايها الرسول-: يوم القضاء الذي يقع فيه عقابكم، وتعاينون فيه الموت لا ينفع الكفار ايمانهم، ولا هم يؤخرون للتوبه والمراجعه."},{"id":"3533","s":32,"a":30,"at":"فاعرض عنهم وانتظر انهم منتظرون","dt":"[30] فاعرض -ايها الرسول- عن هؤلاء المشركين، ولا تبال بتكذيبهم، وانتظر ما الله صانع بهم، انهم منتظرون ومتربصون بكم دوائر السوء، فسيخزيهم الله ويذلهم، وينصرك عليهم. وقد فعل فله الحمد والمنه."},{"id":"3534","s":33,"a":1,"at":"ياايها النبي اتق الله ولا تطع الكافرين والمنافقين ان الله كان عليما حكيما","dt":"[1] يا ايها النبي دم على تقوى الله بالعمل باوامره واجتناب محارمه، وليقتد بك المؤمنون؛ لانهم احوج الى ذلك منك، ولا تطع الكافرين واهل النفاق. ان الله كان عليما بكل شيء، حكيما في خلقه وامره وتدبيره."},{"id":"3535","s":33,"a":2,"at":"واتبع ما يوحى اليك من ربك ان الله كان بما تعملون خبيرا","dt":"[2] واتبع ما يوحى اليك من ربك من القران والسنه، ان الله مطلع على كل ما تعملون ومجازيكم به، لا يخفى عليه شيء من ذلك."},{"id":"3536","s":33,"a":3,"at":"وتوكل على الله وكفى بالله وكيلا","dt":"[3] واعتمد على ربك، وفوض جميع امورك اليه، وحسبك به حافظا لمن توكل عليه واناب اليه."},{"id":"3537","s":33,"a":4,"at":"ما جعل الله لرجل من قلبين في جوفه وما جعل ازواجكم اللائي تظاهرون منهن امهاتكم وما جعل ادعياءكم ابناءكم ذلكم قولكم بافواهكم والله يقول الحق وهو يهدي السبيل","dt":"[4] ما جعل الله لاحد من البشر من قلبين في صدره، وما جعل زوجاتكم اللاتي تظاهرون منهن (في الحرمه) كحرمه امهاتكم، (والظهار ان يقول الرجل لامراته: انت علي كظهر امي، وقد كان هذا طلاقا في الجاهليه، فبين الله ان الزوجه لا تصير اما بحال)، وما جعل الله الاولاد المتبنين ابناء في الشرع، بل ان الظهار والتبني لا حقيقه لهما في التحريم الابدي، فلا تكون الزوجه المظاهر منها كالام في الحرمه، ولا يثبت النسب بالتبني من قول الشخص للدعي: هذا ابني، فهو كلام بالفم لا حقيقه له، ولا يعتد به، والله سبحانه يقول الحق ويبين لعباده سبيله، ويرشدهم الى طريق الرشاد."},{"id":"3538","s":33,"a":5,"at":"ادعوهم لابائهم هو اقسط عند الله فان لم تعلموا اباءهم فاخوانكم في الدين ومواليكم وليس عليكم جناح فيما اخطاتم به ولكن ما تعمدت قلوبكم وكان الله غفورا رحيما","dt":"[5] انسبوا ادعياءكم لابائهم، هو اعدل واقوم عند الله، فان لم تعلموا اباءهم الحقيقيين فادعوهم -اذا- باخوه الدين التي تجمعكم بهم، فانهم اخوانكم في الدين ومواليكم فيه، وليس عليكم اثم فيما وقعتم فيه من خطا لم تتعمدوه، وانما يؤاخذكم الله اذا تعمدتم ذلك. وكان الله غفورا لمن اخطا، رحيما لمن تاب من ذنبه."},{"id":"3539","s":33,"a":6,"at":"النبي اولى بالمؤمنين من انفسهم وازواجه امهاتهم واولو الارحام بعضهم اولى ببعض في كتاب الله من المؤمنين والمهاجرين الا ان تفعلوا الى اوليائكم معروفا كان ذلك في الكتاب مسطورا","dt":"[6] النبي محمد -صلى الله عليه وسلم- اولى بالمؤمنين، واقرب لهم من انفسهم في امور الدين والدنيا، وحرمه ازواج النبي -صلى الله عليه وسلم- على امته كحرمه امهاتهم، فلا يجوز نكاح زوجات الرسول -صلى الله عليه وسلم- من بعده. وذوو القرابه من المسلمين بعضهم احق بميراث بعض في حكم الله وشرعه من الارث بالايمان والهجره (وكان المسلمون في اول الاسلام يتوارثون بالهجره والايمان دون الرحم، ثم نسخ ذلك بايه المواريث) الا ان تفعلوا -ايها المسلمون- الى غير الورثه معروفا بالنصر والبر والصله والاحسان والوصيه، كان هذا الحكم المذكور مقدرا مكتوبا في اللوح المحفوظ، فيجب عليكم العمل به. وفي الايه وجوب كون النبي -صلى الله عليه وسلم- احب الى العبد من نفسه، ووجوب كمال الانقياد له، وفيها وجوب احترام امهات المؤمنين زوجاته -صلى الله عليه وسلم-، وان من سبهن فقد باء بالخسران."},{"id":"3540","s":33,"a":7,"at":"واذ اخذنا من النبيين ميثاقهم ومنك ومن نوح وابراهيم وموسى وعيسى ابن مريم واخذنا منهم ميثاقا غليظا","dt":"[7] واذكر -ايها النبي- حين اخذنا من النبيين العهد المؤكد بتبليغ الرساله، واخذنا الميثاق منك ومن نوح وابراهيم وموسى وعيسى بن مريم (وهم اولو العزم من الرسل على المشهور)، واخذنا منهم عهدا مؤكدا بتبليغ الرساله واداء الامانه، وان يصدق بعضهم بعضا."},{"id":"3541","s":33,"a":8,"at":"ليسال الصادقين عن صدقهم واعد للكافرين عذابا اليما","dt":"[8] اخذ الله ذلك العهد من اولئك الرسل؛ ليسال المرسلين عما اجابتهم به اممهم، فيجزي الله المؤمنين الجنه، واعد للكافرين يوم القيامه عذابا شديدا في جهنم."},{"id":"3542","s":33,"a":9,"at":"ياايها الذين امنوا اذكروا نعمه الله عليكم اذ جاءتكم جنود فارسلنا عليهم ريحا وجنودا لم تروها وكان الله بما تعملون بصيرا","dt":"[9] يا معشر المؤمنين اذكروا نعمه الله تعالى التي انعمها عليكم في «المدينه» ايام غزوه الاحزاب-وهي غزوه الخندق-، حين اجتمع عليكم المشركون من خارج «المدينه»، واليهود والمنافقون من «المدينه» وما حولها، فاحاطوا بكم، فارسلنا على الاحزاب ريحا شديده اقتلعت خيامهم ورمت قدورهم، وارسلنا ملائكه من السماء لم تروها، فوقع الرعب في قلوبهم. وكان الله بما تعملون بصيرا، لا يخفى عليه من ذلك شيء."},{"id":"3543","s":33,"a":10,"at":"اذ جاءوكم من فوقكم ومن اسفل منكم واذ زاغت الابصار وبلغت القلوب الحناجر وتظنون بالله الظنونا","dt":"[10] اذكروا اذ جاؤوكم من فوقكم من اعلى الوادي من جهه المشرق، ومن اسفل منكم من بطن الوادي من جهه المغرب، واذ شخصت الابصار من شده الحيره والدهشه، وبلغت القلوب الحناجر من شده الرعب، وغلب الياس المنافقين، وكثرت الاقاويل، وتظنون بالله الظنون السيئه انه لا ينصر دينه، ولا يعلي كلمته."},{"id":"3544","s":33,"a":11,"at":"هنالك ابتلي المؤمنون وزلزلوا زلزالا شديدا","dt":"[11] في ذلك الموقف العصيب اختبر ايمان المؤمنين ومحص القوم، وعرف المؤمن من المنافق، واضطربوا اضطرابا شديدا بالخوف والقلق؛ ليتبين ايمانهم ويزيد يقينهم."},{"id":"3545","s":33,"a":12,"at":"واذ يقول المنافقون والذين في قلوبهم مرض ما وعدنا الله ورسوله الا غرورا","dt":"[12] واذ يقول المنافقون والذين في قلوبهم شك، وهم ضعفاء الايمان: ما وعدنا الله ورسوله من النصر والتمكين الا باطلا من القول وغرورا، فلا تصدقوه."},{"id":"3546","s":33,"a":13,"at":"واذ قالت طائفه منهم يااهل يثرب لا مقام لكم فارجعوا ويستاذن فريق منهم النبي يقولون ان بيوتنا عوره وما هي بعوره ان يريدون الا فرارا","dt":"[13] واذكر -ايها النبي- قول طائفه من المنافقين منادين المؤمنين من اهل «المدينه»: يا اهل «يثرب» (وهو الاسم القديم «للمدينه») لا اقامه لكم في معركه خاسره، فارجعوا الى منازلكم داخل «المدينه»، ويستاذن فريق اخر من المنافقين الرسول -صلى الله عليه وسلم- بالعوده الى منازلهم بحجه انها غير محصنه، فيخشون عليها، والحق انها ليست كذلك، وما قصدوا بذلك الا الفرار من القتال."},{"id":"3547","s":33,"a":14,"at":"ولو دخلت عليهم من اقطارها ثم سئلوا الفتنه لاتوها وما تلبثوا بها الا يسيرا","dt":"[14] ولو دخل جيش الاحزاب «المدينه» من جوانبها، ثم سئل هؤلاء المنافقون الشرك بالله والرجوع عن الاسلام، لاجابوا الى ذلك مبادرين، وما تاخروا عن الشرك الا يسيرا."},{"id":"3548","s":33,"a":15,"at":"ولقد كانوا عاهدوا الله من قبل لا يولون الادبار وكان عهد الله مسئولا","dt":"[15] ولقد كان هؤلاء المنافقون عاهدوا الله على يد رسوله من قبل غزوه الخندق، لا يفرون ان شهدوا الحرب، ولا يتاخرون اذا دعوا الى الجهاد، ولكنهم خانوا عهدهم، وسيحاسبهم الله على ذلك، ويسالهم عن ذلك العهد، وكان عهد الله مسؤولا عنه، محاسبا عليه."},{"id":"3549","s":33,"a":16,"at":"قل لن ينفعكم الفرار ان فررتم من الموت او القتل واذا لا تمتعون الا قليلا","dt":"[16] قل -ايها النبي- لهؤلاء المنافقين: لن ينفعكم الفرار من المعركه خوفا من الموت او القتل؛ فان ذلك لا يؤخر اجالكم، وان فررتم فلن تتمتعوا في هذه الدنيا الا بقدر اعماركم المحدوده، وهو زمن يسير جدا بالنسبه الى الاخره."},{"id":"3550","s":33,"a":17,"at":"قل من ذا الذي يعصمكم من الله ان اراد بكم سوءا او اراد بكم رحمه ولا يجدون لهم من دون الله وليا ولا نصيرا","dt":"[17] قل -ايها النبي- لهم: من ذا الذي يمنعكم من الله، او يجيركم من عذابه، ان اراد بكم سوءا، او اراد بكم رحمه، فانه المعطي المانع الضار النافع؟ ولا يجد هؤلاء المنافقون لهم من دون الله وليا يواليهم، ولا نصيرا ينصرهم."},{"id":"3551","s":33,"a":18,"at":"قد يعلم الله المعوقين منكم والقائلين لاخوانهم هلم الينا ولا ياتون الباس الا قليلا","dt":"[18] ان الله يعلم المثبطين عن الجهاد في سبيل الله، والقائلين لاخوانهم: تعالوا وانضموا الينا، واتركوا محمدا، فلا تشهدوا معه قتالا؛ فانا نخاف عليكم الهلاك بهلاكه، وهم مع تخذيلهم هذا لا ياتون القتال الا نادرا؛ رياء وسمعه وخوف الفضيحه."},{"id":"3552","s":33,"a":19,"at":"اشحه عليكم فاذا جاء الخوف رايتهم ينظرون اليك تدور اعينهم كالذي يغشى عليه من الموت فاذا ذهب الخوف سلقوكم بالسنه حداد اشحه على الخير اولئك لم يؤمنوا فاحبط الله اعمالهم وكان ذلك على الله يسيرا","dt":"[19] بخلاء عليكم -ايها المؤمنون- بالمال والنفس والجهد والموده لما في نفوسهم من العداوه والحقد؛ حبا في الحياه وكراهه للموت، فاذا حضر القتال خافوا الهلاك ورايتهم ينظرون اليك، تدور اعينهم لذهاب عقولهم؛ خوفا من القتل وفرارا منه، كدوران عين من حضره الموت، فاذا انتهت الحرب وذهب الرعب رموكم بالسنه حاده مؤذيه، وتراهم عند قسمه الغنائم بخلاء وحسده، اولئك لم يؤمنوا بقلوبهم، فاذهب الله ثواب اعمالهم، وكان ذلك على الله يسيرا."},{"id":"3553","s":33,"a":20,"at":"يحسبون الاحزاب لم يذهبوا وان يات الاحزاب يودوا لو انهم بادون في الاعراب يسالون عن انبائكم ولو كانوا فيكم ما قاتلوا الا قليلا","dt":"[20] يظن المنافقون ان الاحزاب الذين هزمهم الله تعالى شر هزيمه لم يذهبوا؛ ذلك من شده الخوف والجبن، ولو عاد الاحزاب الى «المدينه» لتمنى اولئك المنافقون انهم كانوا غائبين عن «المدينه» بين اعراب الباديه، يستخبرون عن اخباركم ويسالون عن انبائكم من بعيد، ولو كانوا فيكم ما قاتلوا معكم الا قليلا؛ لكثره جبنهم وذلتهم وضعف يقينهم."},{"id":"3554","s":33,"a":21,"at":"لقد كان لكم في رسول الله اسوه حسنه لمن كان يرجو الله واليوم الاخر وذكر الله كثيرا","dt":"[21] لقد كان لكم -ايها المؤمنون- في اقوال رسول الله -صلى الله عليه وسلم- وافعاله واحواله قدوه حسنه تتاسون بها، فالزموا سنته، فانما يسلكها ويتاسى بها من كان يرجو الله واليوم الاخر، واكثر من ذكر الله واستغفاره، وشكره في كل حال."},{"id":"3555","s":33,"a":22,"at":"ولما راى المؤمنون الاحزاب قالوا هذا ما وعدنا الله ورسوله وصدق الله ورسوله وما زادهم الا ايمانا وتسليما","dt":"[22] ولما شاهد المؤمنون الاحزاب الذين تحزبوا حول «المدينه» واحاطوا بها، تذكروا ان موعد النصر قد قرب، فقالوا: هذا ما وعدنا الله ورسوله، من الابتلاء والمحنه والنصر، فانجز الله وعده، وصدق رسوله فيما بشر به، وما زادهم النظر الى الاحزاب الا ايمانا بالله وتسليما لقضائه وانقيادا لامره."},{"id":"3556","s":33,"a":23,"at":"من المؤمنين رجال صدقوا ما عاهدوا الله عليه فمنهم من قضى نحبه ومنهم من ينتظر وما بدلوا تبديلا","dt":"[23] من المؤمنين رجال اوفوا بعهودهم مع الله تعالى، وصبروا على الباساء والضراء وحين الباس: فمنهم من وفى بنذره، فاستشهد في سبيل الله، او مات على الصدق والوفاء، ومنهم من ينتظر احدى الحسنيين: النصر او الشهاده، وما غيروا عهد الله، ولا نقضوه ولا بدلوه، كما غير المنافقون."},{"id":"3557","s":33,"a":24,"at":"ليجزي الله الصادقين بصدقهم ويعذب المنافقين ان شاء او يتوب عليهم ان الله كان غفورا رحيما","dt":"[24] ليثيب الله اهل الصدق بسبب صدقهم وبلائهم وهم المؤمنون، ويعذب المنافقين ان شاء تعذيبهم، بان لا يوفقهم للتوبه النصوح قبل الموت، فيموتوا على الكفر، فيستوجبوا النار، او يتوب عليهم بان يوفقهم للتوبه والانابه، ان الله كان غفورا لذنوب المسرفين على انفسهم اذا تابوا، رحيما بهم؛ حيث وفقهم للتوبه النصوح."},{"id":"3558","s":33,"a":25,"at":"ورد الله الذين كفروا بغيظهم لم ينالوا خيرا وكفى الله المؤمنين القتال وكان الله قويا عزيزا","dt":"[25] ورد الله احزاب الكفر عن «المدينه» خائبين خاسرين مغتاظين، لم ينالوا خيرا في الدنيا ولا في الاخره، وكفى الله المؤمنين القتال بما ايدهم به من الاسباب. وكان الله قويا لا يغالب ولا يقهر، عزيزا في ملكه وسلطانه."},{"id":"3559","s":33,"a":26,"at":"وانزل الذين ظاهروهم من اهل الكتاب من صياصيهم وقذف في قلوبهم الرعب فريقا تقتلون وتاسرون فريقا","dt":"[26] وانزل الله يهود بني قريظه من حصونهم؛ لاعانتهم الاحزاب في قتال المسلمين، والقى في قلوبهم الخوف فهزموا، تقتلون منهم فريقا، وتاسرون فريقا اخر."},{"id":"3560","s":33,"a":27,"at":"واورثكم ارضهم وديارهم واموالهم وارضا لم تطئوها وكان الله على كل شيء قديرا","dt":"[27] وملككم الله -ايها المؤمنون- ارضهم ومساكنهم واموالهم المنقوله كالحلي والسلاح والمواشي، وغير المنقوله كالمزارع والبيوت والحصون المنيعه، واورثكم ارضا لم تتمكنوا من وطئها من قبل؛ لمنعتها وعزتها عند اهلها. وكان الله على كل شيء قديرا، لا يعجزه شيء."},{"id":"3561","s":33,"a":28,"at":"ياايها النبي قل لازواجك ان كنتن تردن الحياه الدنيا وزينتها فتعالين امتعكن واسرحكن سراحا جميلا","dt":"[28] يا ايها النبي قل لازواجك اللاتي اجتمعن عليك، يطلبن منك زياده النفقه: ان كنتن تردن الحياه الدنيا وزينتها فاقبلن امتعكن شيئا مما عندي من الدنيا، وافارقكن دون ضرر او ايذاء."},{"id":"3562","s":33,"a":29,"at":"وان كنتن تردن الله ورسوله والدار الاخره فان الله اعد للمحسنات منكن اجرا عظيما","dt":"[29] وان كنتن تردن رضا الله ورضا رسوله، وما اعد الله لكن في الدار الاخره، فاصبرن على ما انتن عليه، واطعن الله ورسوله، فان الله اعد للمحسنات منكن ثوابا عظيما. (وقد اخترن الله ورسوله، وما اعد الله لهن في الدار الاخره)."},{"id":"3563","s":33,"a":30,"at":"يانساء النبي من يات منكن بفاحشه مبينه يضاعف لها العذاب ضعفين وكان ذلك على الله يسيرا","dt":"[30] يا نساء النبي من يات منكن بمعصيه ظاهره يضاعف لها العذاب مرتين. فلما كانت مكانتهن رفيعه ناسب ان يجعل الله الذنب الواقع منهن عقوبته مغلظه؛ صيانه لجنابهن وجناب رسول الله -صلى الله عليه وسلم-. وكان ذلك العقاب على الله يسيرا."},{"id":"3564","s":33,"a":31,"at":"ومن يقنت منكن لله ورسوله وتعمل صالحا نؤتها اجرها مرتين واعتدنا لها رزقا كريما","dt":"[31] ومن تطع منكن الله ورسوله، وتعمل بما امر الله به، نعطها ثواب عملها مثلي ثواب عمل غيرها من سائر النساء، واعددنا لها رزقا كريما، وهو الجنه."},{"id":"3565","s":33,"a":32,"at":"يانساء النبي لستن كاحد من النساء ان اتقيتن فلا تخضعن بالقول فيطمع الذي في قلبه مرض وقلن قولا معروفا","dt":"[32] يا نساء النبي لستن في الفضل والمنزله كغيركن من النساء، ان عملتن بطاعه الله ورسوله وابتعدتن عن معاصيه فلا تتحدثن مع الاجانب بصوت لين يطمع الذي في قلبه فجور ومرض في الشهوه الحرام، وهذا ادب واجب على كل امراه تؤمن بالله واليوم الاخر، وقلن قولا بعيدا عن الريبه، لا تنكره الشريعه."},{"id":"3566","s":33,"a":33,"at":"وقرن في بيوتكن ولا تبرجن تبرج الجاهليه الاولى واقمن الصلاه واتين الزكاه واطعن الله ورسوله انما يريد الله ليذهب عنكم الرجس اهل البيت ويطهركم تطهيرا","dt":"[33] والزمن بيوتكن، ولا تخرجن منها الا لحاجه، ولا تظهرن محاسنكن، كما كان يفعل نساء الجاهليه الاولى في الازمنه السابقه على الاسلام، وهو خطاب للنساء المؤمنات في كل عصر. وادين -يا نساء النبي- الصلاه كامله في اوقاتها، واعطين الزكاه كما شرع الله، واطعن الله ورسوله في امرهما ونهيهما، انما اوصاكن الله بهذا؛ ليزكيكن، ويبعد عنكن الاذى والسوء والشر يا اهل بيت النبي -ومنهم زوجاته وذريته عليه الصلاه والسلام-، ويطهر نفوسكم غايه الطهاره."},{"id":"3567","s":33,"a":34,"at":"واذكرن ما يتلى في بيوتكن من ايات الله والحكمه ان الله كان لطيفا خبيرا","dt":"[34] واذكرن ما يتلى في بيوتكن من القران وحديث الرسول -صلى الله عليه وسلم-، واعملن به، واقدرنه حق قدره، فهو من نعم الله عليكن، ان الله كان لطيفا بكن؛ اذ جعلكن في البيوت التي تتلى فيها ايات الله والسنه، خبيرا بكن اذ اختاركن لرسوله -صلى الله عليه وسلم- ازواجا."},{"id":"3568","s":33,"a":35,"at":"ان المسلمين والمسلمات والمؤمنين والمؤمنات والقانتين والقانتات والصادقين والصادقات والصابرين والصابرات والخاشعين والخاشعات والمتصدقين والمتصدقات والصائمين والصائمات والحافظين فروجهم والحافظات والذاكرين الله كثيرا والذاكرات اعد الله لهم مغفره واجرا عظيما","dt":"[35] ان المنقادين لاوامر الله والمنقادات، والمصدقين والمصدقات، والمطيعين لله ورسوله والمطيعات، والصادقين في اقوالهم وافعالهم والصادقات، والصابرين عن الشهوات وعلى الطاعات وعلى المكاره والصابرات، والخائفين من الله والخائفات، والمتصدقين بالفرض والنفل والمتصدقات، والصائمين في الفرض والنفل والصائمات، والحافظين فروجهم عن الزنى ومقدماته، وعن كشف العورات والحافظات، والذاكرين الله كثيرا بقلوبهم والسنتهم والذاكرات، اعد الله لهؤلاء مغفره لذنوبهم وثوابا عظيما، وهو الجنه."},{"id":"3569","s":33,"a":36,"at":"وما كان لمؤمن ولا مؤمنه اذا قضى الله ورسوله امرا ان يكون لهم الخيره من امرهم ومن يعص الله ورسوله فقد ضل ضلالا مبينا","dt":"[36] ولا ينبغي لمؤمن ولا مؤمنه اذا حكم الله ورسوله فيهم حكما ان يخالفوه، بان يختاروا غير الذي قضى فيهم. ومن يعص الله ورسوله فقد بعد عن طريق الصواب بعدا ظاهرا."},{"id":"3570","s":33,"a":37,"at":"واذ تقول للذي انعم الله عليه وانعمت عليه امسك عليك زوجك واتق الله وتخفي في نفسك ما الله مبديه وتخشى الناس والله احق ان تخشاه فلما قضى زيد منها وطرا زوجناكها لكي لا يكون على المؤمنين حرج في ازواج ادعيائهم اذا قضوا منهن وطرا وكان امر الله مفعولا","dt":"[37] واذ تقول -ايها النبي- للذي انعم الله عليه بالاسلام -وهو زيد بن حارثه الذي اعتقه وتبناه النبي -صلى الله عليه وسلم-- وانعمت عليه بالعتق: ابق زوجك زينب بنت جحش ولا تطلقها، واتق الله يا زيد، وتخفي –ايها النبي- في نفسك ما اوحى الله به اليك من طلاق زيد لزوجه وزواجك منها، والله تعالى مظهر ما اخفيت، وتخاف المنافقين ان يقولوا: تزوج محمد مطلقه متبناه، والله تعالى احق ان تخافه، فلما قضى زيد منها حاجته وطلقها، ثم انقضت عدتها، زوجناكها؛ لتكون اسوه في ابطال عاده تحريم الزواج بزوجه المتبنى بعد طلاقها، ولا يكون على المؤمنين اثم وذنب في ان يتزوجوا من زوجات من كانوا يتبنونهم بعد طلاقهن اذا قضوا منهن حاجتهم. وكان امر الله مفعولا، لا عائق له ولا مانع. وكانت عاده التبني في الجاهليه، ثم ابطلت بقوله تعالى: ادعوهم لابائهم."},{"id":"3571","s":33,"a":38,"at":"ما كان على النبي من حرج فيما فرض الله له سنه الله في الذين خلوا من قبل وكان امر الله قدرا مقدورا","dt":"[38] ما كان على النبي محمد -صلى الله عليه وسلم- من ذنب فيما احل الله له من زواج امراه من تبناه بعد طلاقها، كما اباحه للانبياء قبله، سنه الله في الذين خلوا من قبل، وكان امر الله قدرا مقدورا لا بد من وقوعه."},{"id":"3572","s":33,"a":39,"at":"الذين يبلغون رسالات الله ويخشونه ولا يخشون احدا الا الله وكفى بالله حسيبا","dt":"[39]ثم ذكر سبحانه الانبياء الماضين، واثنى عليهم بانهم: الذين يبلغون رسالات الله الى الناس، ويخافون الله وحده، ولا يخافون احدا سواه. وكفى بالله محاسبا عباده على جميع اعمالهم ومراقبا لها."},{"id":"3573","s":33,"a":40,"at":"ما كان محمد ابا احد من رجالكم ولكن رسول الله وخاتم النبيين وكان الله بكل شيء عليما","dt":"[40] ما كان محمد ابا لاحد من رجالكم، ولكنه رسول الله وخاتم النبيين، فلا نبوه بعده الى يوم القيامه. وكان الله بكل شيء من اعمالكم عليما، لا يخفى عليه شيء."},{"id":"3574","s":33,"a":41,"at":"ياايها الذين امنوا اذكروا الله ذكرا كثيرا","dt":"[41] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، اذكروا الله بقلوبكم والسنتكم وجوارحكم ذكرا كثيرا،"},{"id":"3575","s":33,"a":42,"at":"وسبحوه بكره واصيلا","dt":"[42] واشغلوا اوقاتكم بذكر الله تعالى عند الصباح والمساء، وادبار الصلوات المفروضات، وعند العوارض والاسباب، فان ذلك عباده مشروعه، تدعو الى محبه الله، وكف اللسان عن الاثام، وتعين على كل خير."},{"id":"3576","s":33,"a":43,"at":"هو الذي يصلي عليكم وملائكته ليخرجكم من الظلمات الى النور وكان بالمؤمنين رحيما","dt":"[43] هو الذي يرحمكم ويثني عليكم، وتدعو لكم ملائكته؛ ليخرجكم من ظلمات الجهل والضلال الى نور الاسلام، وكان بالمؤمنين رحيما في الدنيا والاخره، لا يعذبهم ما داموا مطيعين مخلصين له."},{"id":"3577","s":33,"a":44,"at":"تحيتهم يوم يلقونه سلام واعد لهم اجرا كريما","dt":"[44] تحيه هؤلاء المؤمنين من الله في الجنه يوم يلقونه سلام، وامان لهم من عذاب الله، وقد اعد لهم ثوابا حسنا، وهو الجنه."},{"id":"3578","s":33,"a":45,"at":"ياايها النبي انا ارسلناك شاهدا ومبشرا ونذيرا","dt":"[45] يا ايها النبي انا ارسلناك شاهدا على امتك بابلاغهم الرساله، ومبشرا المؤمنين منهم بالرحمه والجنه، ونذيرا للعصاه والمكذبين من النار،"},{"id":"3579","s":33,"a":46,"at":"وداعيا الى الله باذنه وسراجا منيرا","dt":"[46] وداعيا الى توحيد الله وعبادته وحده بامره اياك، وسراجا منيرا لمن استنار بك، فامرك ظاهر فيما جئت به من الحق كالشمس في اشراقها واضاءتها، لا يجحدها الا معاند."},{"id":"3580","s":33,"a":47,"at":"وبشر المؤمنين بان لهم من الله فضلا كبيرا","dt":"[47] وبشر -ايها النبي- اهل الايمان بان لهم من الله ثوابا عظيما، وهو روضات الجنات."},{"id":"3581","s":33,"a":48,"at":"ولا تطع الكافرين والمنافقين ودع اذاهم وتوكل على الله وكفى بالله وكيلا","dt":"[48] ولا تطع -ايها الرسول- قول كافر او منافق واترك اذاهم، ولا يمنعك ذلك من تبليغ الرساله، وثق بالله في كل امورك واعتمد عليه؛ فانه يكفيك ما اهمك من كل امور الدنيا والاخره."},{"id":"3582","s":33,"a":49,"at":"ياايها الذين امنوا اذا نكحتم المؤمنات ثم طلقتموهن من قبل ان تمسوهن فما لكم عليهن من عده تعتدونها فمتعوهن وسرحوهن سراحا جميلا","dt":"[49] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، اذا عقدتم على النساء ولم تدخلوا بهن ثم طلقتموهن من قبل ان تجامعوهن، فما لكم عليهن من عده تحصونها عليهن، فاعطوهن من اموالكم متعه يتمتعن بها بحسب الوسع؛ جبرا لخواطرهن، وخلوا سبيلهن مع الستر الجميل، دون اذى او ضرر."},{"id":"3583","s":33,"a":50,"at":"ياايها النبي انا احللنا لك ازواجك اللاتي اتيت اجورهن وما ملكت يمينك مما افاء الله عليك وبنات عمك وبنات عماتك وبنات خالك وبنات خالاتك اللاتي هاجرن معك وامراه مؤمنه ان وهبت نفسها للنبي ان اراد النبي ان يستنكحها خالصه لك من دون المؤمنين قد علمنا ما فرضنا عليهم في ازواجهم وما ملكت ايمانهم لكيلا يكون عليك حرج وكان الله غفورا رحيما","dt":"[50] يا ايها النبي انا ابحنا لك ازواجك اللاتي اعطيتهن مهورهن، وابحنا لك ما ملكت يمينك من الاماء، مما انعم الله به عليك، وابحنا لك الزواج من بنات عمك وبنات عماتك، وبنات خالك وبنات خالاتك اللاتي هاجرن معك، وابحنا لك امراه مؤمنه منحت نفسها لك من غير مهر، ان كنت تريد الزواج منها خالصه لك، وليس لغيرك ان يتزوج امراه بالهبه. قد علمنا ما اوجبنا على المؤمنين في ازواجهم وامائهم بالا يتزوجوا الا اربع نسوه، وما شاؤوا من الاماء، واشتراط الولي والمهر والشهود عليهم، ولكنا رخصنا لك فيما اوجبنا عليهم، ووسعنا عليك ما لم نوسع على غيرك؛ لئلا يضيق صدرك في نكاح من نكحت من هؤلاء الاصناف. وهذا من زياده اعتناء الله برسوله -صلى الله عليه وسلم- وتكريمه له. وكان الله غفورا لذنوب عباده المؤمنين، رحيما بالتوسعه عليهم."},{"id":"3584","s":33,"a":51,"at":"ترجي من تشاء منهن وتؤوي اليك من تشاء ومن ابتغيت ممن عزلت فلا جناح عليك ذلك ادنى ان تقر اعينهن ولا يحزن ويرضين بما اتيتهن كلهن والله يعلم ما في قلوبكم وكان الله عليما حليما","dt":"[51] تؤخر من تشاء من نسائك في القسم في المبيت، وتضم اليك من تشاء منهن، ومن طلبت ممن اخرت قسمها، فلا اثم عليك في هذا، ذلك التخيير اقرب الى ان يفرحن ولا يحزن، ويرضين كلهن بما قسمت لهن، والله يعلم ما في قلوب الرجال من ميلها الى بعض النساء دون بعض. وكان الله عليما بما في القلوب، حليما لا يعجل بالعقوبه على من عصاه."},{"id":"3585","s":33,"a":52,"at":"لا يحل لك النساء من بعد ولا ان تبدل بهن من ازواج ولو اعجبك حسنهن الا ما ملكت يمينك وكان الله على كل شيء رقيبا","dt":"[52] لا يحل لك تزوج النساء من بعد زوجاتك امهات المؤمنين، ولا ان تطلقهن وتتزوج بدلهن غيرهن -اكراما لهن، وشكرا على حسن صنيعهن من اختيارهن الله ورسوله والدار الاخره- ولو اعجبك حسن غيرهن من النساء، الا ما ملكت يمينك من الاماء، فهن حلال لك. وكان الله على كل شيء رقيبا، لا يغيب عنه علم شيء."},{"id":"3586","s":33,"a":53,"at":"ياايها الذين امنوا لا تدخلوا بيوت النبي الا ان يؤذن لكم الى طعام غير ناظرين اناه ولكن اذا دعيتم فادخلوا فاذا طعمتم فانتشروا ولا مستانسين لحديث ان ذلكم كان يؤذي النبي فيستحيي منكم والله لا يستحيي من الحق واذا سالتموهن متاعا فاسالوهن من وراء حجاب ذلكم اطهر لقلوبكم وقلوبهن وما كان لكم ان تؤذوا رسول الله ولا ان تنكحوا ازواجه من بعده ابدا ان ذلكم كان عند الله عظيما","dt":"[53] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه لا تدخلوا بيوت النبي الا باذنه لتناول طعام غير منتظرين نضجه، ولكن اذا دعيتم فادخلوا، فاذا اكلتم فانصرفوا غير مستانسين لحديث بينكم؛ فان انتظاركم واستئناسكم يؤذي النبي، فيستحيي من اخراجكم من البيوت مع ان ذلك حق له، والله لا يستحيي من بيان الحق واظهاره. واذا سالتم نساء رسول الله -صلى الله عليه وسلم- حاجه من اواني البيت ونحوها فاسالوهن من وراء ستر؛ ذلكم اطهر لقلوبكم وقلوبهن من الخواطر التي تعرض للرجال في امر النساء، وللنساء في امر الرجال؛ فالرؤيه سبب الفتنه، وما ينبغي لكم ان تؤذوا رسول الله، ولا ان تتزوجوا ازواجه من بعد موته ابدا؛ لانهن امهاتكم، ولا يحل للرجل ان يتزوج امه، ان اذاكم رسول الله -صلى الله عليه وسلم- ونكاحكم ازواجه من بعده اثم عظيم عند الله.وقد امتثلت هذه الامه هذا الامر، واجتنبت ما نهى الله عنه منه."},{"id":"3587","s":33,"a":54,"at":"ان تبدوا شيئا او تخفوه فان الله كان بكل شيء عليما","dt":"[54] ان تظهروا شيئا على السنتكم -ايها الناس- مما يؤذي رسول الله مما نهاكم الله عنه، او تخفوه في نفوسكم، فان الله تعالى يعلم ما في قلوبكم وما اظهرتموه، وسيجازيكم على ذلك."},{"id":"3588","s":33,"a":55,"at":"لا جناح عليهن في ابائهن ولا ابنائهن ولا اخوانهن ولا ابناء اخوانهن ولا ابناء اخواتهن ولا نسائهن ولا ما ملكت ايمانهن واتقين الله ان الله كان على كل شيء شهيدا","dt":"[55] لا اثم على النساء في عدم الاحتجاب من ابائهن وابنائهن واخوانهن وابناء اخوانهن وابناء اخواتهن والنساء المؤمنات والعبيد المملوكين لهن؛ لشده الحاجه اليهم في الخدمه. وخفن الله -ايتها النساء- ان تتعدين ما حد لكن، فتبدين من زينتكن ما ليس لكن ان تبدينه، او تتركن الحجاب امام من يجب عليكن الاحتجاب منه. ان الله كان على كل شيء شهيدا، يشهد اعمال العباد باطنها وظاهرها، وسيجزيهم عليها."},{"id":"3589","s":33,"a":56,"at":"ان الله وملائكته يصلون على النبي ياايها الذين امنوا صلوا عليه وسلموا تسليما","dt":"[56] ان الله تعالى يثني على النبي -صلى الله عليه وسلم- عند الملائكه المقربين، وملائكته يثنون على النبي ويدعون له، يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، صلوا على رسول الله وسلموا تسليما، تحيه وتعظيما له. وصفه الصلاه على النبي -صلى الله عليه وسلم- ثبتت في السنه على انواع، منها: «اللهم صل على محمد وعلى ال محمد، كما صليت على ال ابراهيم، انك حميد مجيد، اللهم بارك على محمد وعلى ال محمد، كما باركت على ال ابراهيم، انك حميد مجيد»."},{"id":"3590","s":33,"a":57,"at":"ان الذين يؤذون الله ورسوله لعنهم الله في الدنيا والاخره واعد لهم عذابا مهينا","dt":"[57] ان الذين يؤذون الله بالشرك او غيره من المعاصي، ويؤذون رسول الله بالاقوال او الافعال، ابعدهم الله وطردهم من كل خير في الدنيا والاخره، واعد لهم في الاخره عذابا يذلهم ويهينهم."},{"id":"3591","s":33,"a":58,"at":"والذين يؤذون المؤمنين والمؤمنات بغير ما اكتسبوا فقد احتملوا بهتانا واثما مبينا","dt":"[58] والذين يؤذون المؤمنين والمؤمنات بقول او فعل من غير ذنب عملوه، فقد ارتكبوا افحش الكذب والزور، واتوا ذنبا ظاهر القبح يستحقون به العذاب في الاخره."},{"id":"3592","s":33,"a":59,"at":"ياايها النبي قل لازواجك وبناتك ونساء المؤمنين يدنين عليهن من جلابيبهن ذلك ادنى ان يعرفن فلا يؤذين وكان الله غفورا رحيما","dt":"[59] يا ايها النبي قل لازواجك وبناتك ونساء المؤمنين يرخين على رؤوسهن ووجوههن من ارديتهن وملاحفهن؛ لستر وجوههن وصدورهن ورؤوسهن؛ ذلك اقرب ان يميزن بالستر والصيانه، فلا يتعرض لهن بمكروه او اذى. وكان الله غفورا رحيما حيث غفر لكم ما سلف، ورحمكم بما اوضح لكم من الحلال والحرام."},{"id":"3593","s":33,"a":60,"at":"لئن لم ينته المنافقون والذين في قلوبهم مرض والمرجفون في المدينه لنغرينك بهم ثم لا يجاورونك فيها الا قليلا","dt":"[60] لئن لم يكف الذين يضمرون الكفر ويظهرون الايمان والذين في قلوبهم شك وريبه، والذين ينشرون الاخبار الكاذبه في مدينه الرسول -صلى الله عليه وسلم- عن قبائحهم وشرورهم، لنسلطنك عليهم، ثم لا يسكنون معك فيها الا زمنا قليلا"},{"id":"3594","s":33,"a":61,"at":"ملعونين اينما ثقفوا اخذوا وقتلوا تقتيلا","dt":"[61] مطرودين من رحمه الله، في اي مكان وجدوا فيه اسروا وقتلوا تقتيلا ما داموا مقيمين على النفاق ونشر الاخبار الكاذبه بين المسلمين بغرض الفتنه والفساد."},{"id":"3595","s":33,"a":62,"at":"سنه الله في الذين خلوا من قبل ولن تجد لسنه الله تبديلا","dt":"[62] سنه الله وطريقته في منافقي الامم السابقه ان يؤسروا ويقتلوا اينما كانوا، ولن تجد -ايها النبي- لطريقه الله تحويلا ولا تغييرا."},{"id":"3596","s":33,"a":63,"at":"يسالك الناس عن الساعه قل انما علمها عند الله وما يدريك لعل الساعه تكون قريبا","dt":"[63] يسالك الناس -ايها الرسول- عن وقت القيامه استبعادا وتكذيبا، قل لهم: انما علم الساعه عند الله، وما يدر يك -ايها الرسول- لعل زمانها قريب؟"},{"id":"3597","s":33,"a":64,"at":"ان الله لعن الكافرين واعد لهم سعيرا","dt":"[64] ان الله طرد الكافرين من رحمته في الدنيا والاخره، واعد لهم في الاخره نارا موقده شديده الحراره،"},{"id":"3598","s":33,"a":65,"at":"خالدين فيها ابدا لا يجدون وليا ولا نصيرا","dt":"[65] ماكثين فيها ابدا، لا يجدون وليا يتولاهم و يدافع عنهم، ولا نصيرا ينصرهم، فيخرجهم من النار."},{"id":"3599","s":33,"a":66,"at":"يوم تقلب وجوههم في النار يقولون ياليتنا اطعنا الله واطعنا الرسولا","dt":"[66] يوم تقلب وجوه الكافرين في النار يقولون نادمين متحير ين: يا ليتنا اطعنا الله واطعنا رسوله في الدنيا، فكنا من اهل الجنه."},{"id":"3600","s":33,"a":67,"at":"وقالوا ربنا انا اطعنا سادتنا وكبراءنا فاضلونا السبيلا","dt":"[67] وقال الكافرون يوم القيامه: ربنا انا اطعنا ائمتنا في الضلال وكبراءنا في الشرك، فازالونا عن طريق الهدى والايمان"},{"id":"3601","s":33,"a":68,"at":"ربنا اتهم ضعفين من العذاب والعنهم لعنا كبيرا","dt":"[68] ربنا عذبهم من العذاب مثلي عذابنا الذي تعذبنا به، واطردهم من رحمتك طردا شديدا. وفي هذا دليل على ان طاعه غير الله في مخالفه امره وامر رسوله، موجبه لسخط الله وعقابه، وان التابع والمتبوع في العذاب مشتركون، فليحذر المسلم ذلك."},{"id":"3602","s":33,"a":69,"at":"ياايها الذين امنوا لا تكونوا كالذين اذوا موسى فبراه الله مما قالوا وكان عند الله وجيها","dt":"[69] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه لا تؤذوا رسول الله بقول او فعل، ولا تكونوا امثال الذين اذوا نبي الله موسى، فبراه الله مما قالوا فيه من الكذب والزور، وكان عند الله عظيم القدر والجاه."},{"id":"3603","s":33,"a":70,"at":"ياايها الذين امنوا اتقوا الله وقولوا قولا سديدا","dt":"[70] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، اعملوا بطاعته، واجتنبوا معصيته؛ لئلا تستحقوا بذلك العقاب، وقولوا في جميع احوالكم وشؤونكم قولا مستقيما موافقا للصواب خاليا من الكذب والباطل."},{"id":"3604","s":33,"a":71,"at":"يصلح لكم اعمالكم ويغفر لكم ذنوبكم ومن يطع الله ورسوله فقد فاز فوزا عظيما","dt":"[71] اذا اتقيتم الله وقلتم قولا سديدا اصلح الله لكم اعمالكم، وغفر ذنوبكم. ومن يطع الله ورسوله فيما امر ونهى فقد فاز بالكرامه العظمى في الدنيا والاخره."},{"id":"3605","s":33,"a":72,"at":"انا عرضنا الامانه على السموات والارض والجبال فابين ان يحملنها واشفقن منها وحملها الانسان انه كان ظلوما جهولا","dt":"[72] انا عرضنا الامانه -التي ائتمن الله عليها المكلفين من امتثال الاوامر واجتناب النواهي- على السموات والارض والجبال، فابين ان يحملنها، وخفن ان لا يقمن بادائها، وحملها الانسان والتزم بها على ضعفه، انه كان شديد الظلم والجهل لنفسه."},{"id":"3606","s":33,"a":73,"at":"ليعذب الله المنافقين والمنافقات والمشركين والمشركات ويتوب الله على المؤمنين والمؤمنات وكان الله غفورا رحيما","dt":"[73] لتكون عاقبه حمل الانسان الامانه ان يعذب الله المنافقين الذين يظهرون الاسلام ويخفون الكفر، والمنافقات، والمشركين في عباده الله غيره، والمشركات، ويتوب الله على المؤمنين والمؤمنات بستر ذنوبهم وترك عقابهم. وكان الله غفورا للتائبين من عباده، رحيما بهم."},{"id":"3607","s":34,"a":1,"at":"الحمد لله الذي له ما في السموات وما في الارض وله الحمد في الاخره وهو الحكيم الخبير","dt":"[1] الثناء على الله بصفاته التي كلها اوصاف كمال، وبنعمه الظاهره والباطنه، الدينيه والدنيويه، الذي له ملك ما في السموات وما في الارض، وله الثناء التام في الاخره، وهو الحكيم في فعله، الخبير بشؤون خلقه."},{"id":"3608","s":34,"a":2,"at":"يعلم ما يلج في الارض وما يخرج منها وما ينزل من السماء وما يعرج فيها وهو الرحيم الغفور","dt":"[2] يعلم كل ما يدخل في الارض من قطرات الماء، وما يخرج منها من النبات والمعادن والمياه، وما ينزل من السماء من الامطار والملائكه والكتب، وما يصعد اليها من الملائكه وافعال الخلق. وهو الرحيم بعباده فلا يعاجل عصاتهم بالعقوبه، الغفور لذنوب التائبين اليه المتوكلين عليه."},{"id":"3609","s":34,"a":3,"at":"وقال الذين كفروا لا تاتينا الساعه قل بلى وربي لتاتينكم عالم الغيب لا يعزب عنه مثقال ذره في السموات ولا في الارض ولا اصغر من ذلك ولا اكبر الا في كتاب مبين","dt":"[3] وقال الكافرون المنكرون للبعث: لا تاتينا القيامه، قل لهم -ايها الرسول-: بلى وربي لتاتينكم، ولكن لا يعلم وقت مجيئها احد سوى الله علام الغيوب، الذي لا يغيب عنه وزن نمله صغيره في السموات والارض، ولا اصغر من ذلك ولا اكبر الا هو مسطور في كتاب واضح، وهو اللوح المحفوظ؛"},{"id":"3610","s":34,"a":4,"at":"ليجزي الذين امنوا وعملوا الصالحات اولئك لهم مغفره ورزق كريم","dt":"[4] ليثيب الذين صدقوا بالله، واتبعوا رسوله، وعملوا الصالحات. اولئك لهم مغفره لذنوبهم ورزق كريم، وهو الجنه."},{"id":"3611","s":34,"a":5,"at":"والذين سعوا في اياتنا معاجزين اولئك لهم عذاب من رجز اليم","dt":"[5] والذين سعوا في الصد عن سبيل الله وتكذيب رسله وابطال اياتنا مشاقين الله مغالبين امره، اولئك لهم اسوا العذاب واشده الما."},{"id":"3612","s":34,"a":6,"at":"ويرى الذين اوتوا العلم الذي انزل اليك من ربك هو الحق ويهدي الى صراط العزيز الحميد","dt":"[6] ويعلم الذين اعطوا العلم ان القران الذي انزل اليك من ربك هو الحق، ويرشد الى طريق الله، العزيز الذي لا يغالب ولا يمانع، بل قهر كل شيء وغلبه، المحمود في اقواله وافعاله وشرعه."},{"id":"3613","s":34,"a":7,"at":"وقال الذين كفروا هل ندلكم على رجل ينبئكم اذا مزقتم كل ممزق انكم لفي خلق جديد","dt":"[7] وقال الذين كفروا بعضهم لبعض استهزاء: هل ندلكم على رجل -يريدون محمدا صلى الله عليه وسلم- يخبركم انكم اذا متم وتفرقت اجسامكم كل تفرق، انكم ستحيون وتبعثون من قبوركم؟ قالوا ذلك من فرط انكارهم."},{"id":"3614","s":34,"a":8,"at":"افترى على الله كذبا ام به جنه بل الذين لا يؤمنون بالاخره في العذاب والضلال البعيد","dt":"[8] هذا الرجل اختلق على الله كذبا ام به جنون، فهو يتكلم بما لا يدري؟ ليس الامر كما قال الكفار، بل محمد اصدق الصادقين. والذين لا يصدقون بالبعث ولا يعملون من اجله في العذاب الدائم في الاخره، والضلال البعيد عن الصواب في الدنيا."},{"id":"3615","s":34,"a":9,"at":"افلم يروا الى ما بين ايديهم وما خلفهم من السماء والارض ان نشا نخسف بهم الارض او نسقط عليهم كسفا من السماء ان في ذلك لايه لكل عبد منيب","dt":"[9] افلم ير هؤلاء الكفار الذين لا يؤمنون بالاخره عظيم قدره الله فيما بين ايديهم وما خلفهم من السماء والارض مما يبهر العقول، وانهما قد احاطتا بهم؟ ان نشا نخسف بهم الارض، كما فعلنا بقارون، او ننزل عليهم قطعا من العذاب، كما فعلنا بقوم شعيب، فقد امطرت السماء عليهم نارا فاحرقتهم. ان في ذلك الذي ذكرنا من قدرتنا لدلاله ظاهره لكل عبد راجع الى ربه بالتوبه، ومقر له بتوحيده، ومخلص له في العباده."},{"id":"3616","s":34,"a":10,"at":"ولقد اتينا داود منا فضلا ياجبال اوبي معه والطير والنا له الحديد","dt":"[10] ولقد اتينا داود نبوه وكتابا وعلما، وقلنا للجبال والطير: سبحي معه ، والنا له الحديد، فكان كالعجين يتصرف فيه كيف يشاء."},{"id":"3617","s":34,"a":11,"at":"ان اعمل سابغات وقدر في السرد واعملوا صالحا اني بما تعملون بصير","dt":"[11] ان اعمل دروعا تامات واسعات، وقدر المسامير في حلق الدروع، فلا تعمل الحلقه صغيره فتضعف، فلا تقوى الدروع على الدفاع، ولا تجعلها كبيره فتثقل على لابسها، واعمل يا داود انت واهلك بطاعه الله، اني بما تعملون بصير لا يخفى علي شيء منها."},{"id":"3618","s":34,"a":12,"at":"ولسليمان الريح غدوها شهر ورواحها شهر واسلنا له عين القطر ومن الجن من يعمل بين يديه باذن ربه ومن يزغ منهم عن امرنا نذقه من عذاب السعير","dt":"[12] وسخرنا لسليمان الريح تجري من اول النهار الى انتصافه مسيره شهر، ومن منتصف النهار الى الليل مسيره شهر بالسير المعتاد، واسلنا له النحاس كما يسيل الماء، يعمل به ما يشاء، وسخرنا له من الجن من يعمل بين يديه باذن ربه، ومن يعدل منهم عن امرنا الذي امرناه به من طاعه سليمان نذقه من عذاب النار المستعره."},{"id":"3619","s":34,"a":13,"at":"يعملون له ما يشاء من محاريب وتماثيل وجفان كالجواب وقدور راسيات اعملوا ال داود شكرا وقليل من عبادي الشكور","dt":"[13] يعمل الجن لسليمان ما يشاء من مساجد للعباده، وصور من نحاس وزجاج، وقصاع كبيره كالاحواض التي يجتمع فيها الماء، وقدور ثابتات لا تتحرك من اماكنها لعظمهن، وقلنا يا ال داود: اعملوا شكرا لله على ما اعطاكم، وذلك بطاعته وامتثال امره، وقليل من عبادي من يشكر الله كثيرا، وكان داود واله من القليل."},{"id":"3620","s":34,"a":14,"at":"فلما قضينا عليه الموت ما دلهم على موته الا دابه الارض تاكل منساته فلما خر تبينت الجن ان لو كانوا يعلمون الغيب ما لبثوا في العذاب المهين","dt":"[14] فلما قضينا على سليمان بالموت ما دل الجن على موته الا الارضه تاكل عصاه التي كان متكئا عليها، فوقع سليمان على الارض، عند ذلك علمت الجن انهم لو كانوا يعلمون الغيب ما اقاموا في العذاب المذل والعمل الشاق لسليمان؛ ظنا منهم انه من الاحياء. وفي الايه ابطال لاعتقاد بعض الناس ان الجن يعلمون الغيب؛ اذ لو كانوا يعلمون الغيب لعلموا وفاه سليمان عليه السلام، ولما اقاموا في العذاب المهين."},{"id":"3621","s":34,"a":15,"at":"لقد كان لسبا في مسكنهم ايه جنتان عن يمين وشمال كلوا من رزق ربكم واشكروا له بلده طيبه ورب غفور","dt":"[15] لقد كان لقبيله سبا ب«اليمن» في مسكنهم دلاله على قدرتنا: بستانان عن يمين وشمال، كلوا من رزق ربكم، واشكروا له نعمه عليكم؛ فان بلدتكم كريمه التربه حسنه الهواء، وربكم غفور لكم."},{"id":"3622","s":34,"a":16,"at":"فاعرضوا فارسلنا عليهم سيل العرم وبدلناهم بجنتيهم جنتين ذواتي اكل خمط واثل وشيء من سدر قليل","dt":"[16] فاعرضوا عن امر الله وشكره وكذبوا الرسل، فارسلنا عليهم السيل الجارف الشديد الذي خرب السد واغرق زروعهم، وبدلناهم ببستانيهم المثمرين بستانين ذوي ثمر مر كريه الطعم، وشجر شبيه بالطرفاء لا ثمر له، وقليل من شجر النبق كثير الشوك."},{"id":"3623","s":34,"a":17,"at":"ذلك جزيناهم بما كفروا وهل نجازي الا الكفور","dt":"[17] ذلك التبديل من خير الى شر بسبب كفرهم، وعدم شكرهم نعم الله، وما نعاقب بهذا العقاب الشديد الا الجحود المبالغ في الكفر، يجازى بفعله مثلا بمثل."},{"id":"3624","s":34,"a":18,"at":"وجعلنا بينهم وبين القرى التي باركنا فيها قرى ظاهره وقدرنا فيها السير سيروا فيها ليالي واياما امنين","dt":"[18] وجعلنا بين اهل «سبا» -وهم «باليمن»- والقرى التي باركنا فيها -وهي «الشام»- مدنا متصله يرى بعضها من بعض، وجعلنا السير فيها سيرا مقدرا من منزل الى منزل لا مشقه فيه، وقلنا لهم: سيروا في تلك القرى في اي وقت شئتم من ليل او نهار، امنين لا تخافون عدوا، ولا جوعا ولا عطشا."},{"id":"3625","s":34,"a":19,"at":"فقالوا ربنا باعد بين اسفارنا وظلموا انفسهم فجعلناهم احاديث ومزقناهم كل ممزق ان في ذلك لايات لكل صبار شكور","dt":"[19] فبطغيانهم ملوا الراحه والامن ورغد العيش، وقالوا: ربنا اجعل قرانا متباعده؛ ليبعد سفرنا بينها، فلا نجد قرى عامره في طريقنا، وظلموا انفسهم بكفرهم فاهلكناهم، وجعلناهم عبرا واحاديث لمن ياتي بعدهم، وفرقناهم كل تفريق وخربت بلادهم، ان فيما حل «بسبا» لعبره لكل صبار على المكاره والشدائد، شكور لنعم الله تعالى."},{"id":"3626","s":34,"a":20,"at":"ولقد صدق عليهم ابليس ظنه فاتبعوه الا فريقا من المؤمنين","dt":"[20] ولقد ظن ابليس ظنا غير يقين انه سيضل بني ادم، وانهم سيطيعونه في معصيه الله، فصدق ظنه عليهم، فاطاعوه وعصوا ربهم الا فريقا من المؤمنين بالله، فانهم ثبتوا على طاعه الله."},{"id":"3627","s":34,"a":21,"at":"وما كان له عليهم من سلطان الا لنعلم من يؤمن بالاخره ممن هو منها في شك وربك على كل شيء حفيظ","dt":"[21] وما كان لابليس على هؤلاء الكفار من قهر على الكفر، ولكن حكمه الله اقتضت تسويله لبني ادم؛ ليظهر ما علمه سبحانه في الازل؛ لنميز من يصدق بالبعث والثواب والعقاب ممن هو في شك من ذلك. وربك على كل شيء حفيظ، يحفظه ويجازي عليه."},{"id":"3628","s":34,"a":22,"at":"قل ادعوا الذين زعمتم من دون الله لا يملكون مثقال ذره في السموات ولا في الارض وما لهم فيهما من شرك وما له منهم من ظهير","dt":"[22] قل -ايها الرسول- للمشركين: ادعوا الذين زعمتموهم شركاء لله فعبدتموهم من دونه من الاصنام والملائكه والبشر، واقصدوهم في حوائجكم، فانهم لن يجيبوكم، فهم لا يملكون وزن نمله صغيره في السموات ولا في الارض، وليس لهم شركه فيهما، وليس لله من هؤلاء المشركين معين على خلق شيء، بل الله -سبحانه وتعالى- هو المتفرد بالايجاد، فهو الذي يعبد وحده، ولا يستحق العباده احد سواه."},{"id":"3629","s":34,"a":23,"at":"ولا تنفع الشفاعه عنده الا لمن اذن له حتى اذا فزع عن قلوبهم قالوا ماذا قال ربكم قالوا الحق وهو العلي الكبير","dt":"[23] ولا تنفع شفاعه الشافع عند الله تعالى الا لمن اذن له. ومن عظمته وجلاله عز وجل انه اذا تكلم سبحانه بالوحي فسمع اهل السموات كلامه اهتزت اجسامهم من الهيبه، حتى يلحقهم مثل الغيبوبه، فاذا زال الفزع عن قلوبهم سال بعضهم بعضا: ماذا قال ربكم؟ قالت الملائكه: قال الحق، وهو العلي بذاته وقهره وعلو قدره، الكبير على كل شيء."},{"id":"3630","s":34,"a":24,"at":"قل من يرزقكم من السموات والارض قل الله وانا او اياكم لعلى هدى او في ضلال مبين","dt":"[24] قل -ايها الرسول- للمشركين: من يرزقكم من السموات بالمطر، ومن الارض بالنبات والمعادن وغير ذلك؟ فانهم لابد ان يقروا بانه الله، وان لم يقروا بذلك فقل لهم: الله هو الرزاق، وان احد الفريقين منا ومنكم لعلى هدى متمكن منه، او في ضلال بين منغمس فيه."},{"id":"3631","s":34,"a":25,"at":"قل لا تسالون عما اجرمنا ولا نسال عما تعملون","dt":"[25] قل: لا تسالون عن ذنوبنا، ولا نسال عن اعمالكم؛ لاننا بريئون منكم ومن كفركم."},{"id":"3632","s":34,"a":26,"at":"قل يجمع بيننا ربنا ثم يفتح بيننا بالحق وهو الفتاح العليم","dt":"[26] قل: ربنا يجمع بيننا وبينكم يوم القيامه، ثم يقضي بيننا بالعدل، وهو الفتاح الحاكم بين خلقه، العليم بما ينبغي ان يقضى به، وباحوال خلقه، لا تخفى عليه خافيه."},{"id":"3633","s":34,"a":27,"at":"قل اروني الذين الحقتم به شركاء كلا بل هو الله العزيز الحكيم","dt":"[27] قل: اروني بالحجه والدليل الذين الحقتموهم بالله وجعلتموهم شركاء له في العباده، هل خلقوا شيئا؟ ليس الامر كما وصفوا، بل هو المعبود بحق الذي لا شريك له، العزيز في انتقامه ممن اشرك به، الحكيم في اقواله وافعاله وتدبير امور خلقه."},{"id":"3634","s":34,"a":28,"at":"وما ارسلناك الا كافه للناس بشيرا ونذيرا ولكن اكثر الناس لا يعلمون","dt":"[28] وما ارسلناك -ايها الرسول- الا للناس اجمعين مبشرا بثواب الله، ومنذرا عقابه، ولكن اكثر الناس لا يعلمون الحق، فهم معرضون عنه."},{"id":"3635","s":34,"a":29,"at":"ويقولون متى هذا الوعد ان كنتم صادقين","dt":"[29] ويقول هؤلاء المشركون مستهزئين: متى هذا الوعد الذي تعدوننا ان يجمعنا الله فيه، ثم يقضي بيننا، ان كنتم صادقين فيما تعدوننا به؟"},{"id":"3636","s":34,"a":30,"at":"قل لكم ميعاد يوم لا تستاخرون عنه ساعه ولا تستقدمون","dt":"[30] قل لهم -ايها الرسول-: لكم ميعاد هو اتيكم لا محاله، وهو ميعاد يوم القيامه، لا تستاخرون عنه ساعه للتوبه، ولا تستقدمون ساعه قبله للعذاب. فاحذروا ذلك اليوم، واعدوا له عدته."},{"id":"3637","s":34,"a":31,"at":"وقال الذين كفروا لن نؤمن بهذا القران ولا بالذي بين يديه ولو ترى اذ الظالمون موقوفون عند ربهم يرجع بعضهم الى بعض القول يقول الذين استضعفوا للذين استكبروا لولا انتم لكنا مؤمنين","dt":"[31] وقال الذين كفروا: لن نصدق بهذا القران ولا بالذي تقدمه من التوراه والانجيل والزبور، فقد كذبوا بجميع كتب الله. ولو ترى -ايها الرسول- اذ الظالمون محبوسون عند ربهم للحساب، يتراجعون الكلام فيما بينهم، كل يلقي بالعتاب على الاخر، لرايت شيئا فظيعا، يقول المستضعفون للذين استكبروا -وهم القاده والرؤساء الضالون المضلون-: لولا انتم اضللتمونا عن الهدى لكنا مؤمنين بالله ورسوله."},{"id":"3638","s":34,"a":32,"at":"قال الذين استكبروا للذين استضعفوا انحن صددناكم عن الهدى بعد اذ جاءكم بل كنتم مجرمين","dt":"[32] قال الرؤساء للذين استضعفوا: انحن منعناكم من الهدى بعد اذ جاءكم؟ بل كنتم مجرمين اذ دخلتم في الكفر بارادتكم مختارين."},{"id":"3639","s":34,"a":33,"at":"وقال الذين استضعفوا للذين استكبروا بل مكر الليل والنهار اذ تامروننا ان نكفر بالله ونجعل له اندادا واسروا الندامه لما راوا العذاب وجعلنا الاغلال في اعناق الذين كفروا هل يجزون الا ما كانوا يعملون","dt":"[33] وقال المستضعفون لرؤسائهم في الضلال: بل تدبيركم الشر لنا في الليل والنهار هو الذي اوقعنا في التهلكه، فكنتم تطلبون منا ان نكفر بالله، ونجعل له شركاء في العباده، واسر كل من الفريقين الحسره حين راوا العذاب الذي اعد لهم، وجعلنا الاغلال في اعناق الذين كفروا، لا يعاقبون بهذا العقاب الا بسبب كفرهم بالله وعملهم السيئات في الدنيا. وفي الايه تحذير شديد من متابعه دعاه الضلال وائمه الطغيان."},{"id":"3640","s":34,"a":34,"at":"وما ارسلنا في قريه من نذير الا قال مترفوها انا بما ارسلتم به كافرون","dt":"[34] وما ارسلنا في قريه من رسول يدعو الى توحيد الله وافراده بالعباده، الا قال المنغمسون في اللذات والشهوات من اهلها: انا بالذي جئتم به -ايها الرسل- جاحدون."},{"id":"3641","s":34,"a":35,"at":"وقالوا نحن اكثر اموالا واولادا وما نحن بمعذبين","dt":"[35] وقالوا: نحن اكثر منكم اموالا واولادا، والله لم يعطنا هذه النعم الا لرضاه عنا، وما نحن بمعذبين في الدنيا ولا في الاخره."},{"id":"3642","s":34,"a":36,"at":"قل ان ربي يبسط الرزق لمن يشاء ويقدر ولكن اكثر الناس لا يعلمون","dt":"[36] قل لهم -ايها الرسول-: ان ربي يوسع الرزق في الدنيا لمن يشاء من عباده، ويضيق على من يشاء، لا لمحبه ولا لبغض، ولكن يفعل ذلك اختبارا، ولكن اكثر الناس لا يعلمون ان ذلك اختبار لعباده؛ لانهم لا يتاملون."},{"id":"3643","s":34,"a":37,"at":"وما اموالكم ولا اولادكم بالتي تقربكم عندنا زلفى الا من امن وعمل صالحا فاولئك لهم جزاء الضعف بما عملوا وهم في الغرفات امنون","dt":"[37] وليست اموالكم ولا اولادكم بالتي تقربكم عندنا قربى وترفع درجاتكم، لكن من امن بالله وعمل صالحا فهؤلاء لهم ثواب الضعف من الحسنات، فالحسنه بعشر امثالها الى ما يشاء الله من الزياده، وهم في اعالي الجنه امنون من العذاب والموت والاحزان."},{"id":"3644","s":34,"a":38,"at":"والذين يسعون في اياتنا معاجزين اولئك في العذاب محضرون","dt":"[38] والذين يسعون في ابطال حججنا، ويصدون عن سبيل الله مشاقين مغالبين، هؤلاء في عذاب جهنم يوم القيامه، تحضرهم الزبانيه، فلا يخرجون منها."},{"id":"3645","s":34,"a":39,"at":"قل ان ربي يبسط الرزق لمن يشاء من عباده ويقدر له وما انفقتم من شيء فهو يخلفه وهو خير الرازقين","dt":"[39] قل -ايها الرسول- لهؤلاء المغترين بالاموال والاولاد: ان ربي يوسع الرزق على من يشاء من عباده، ويضيقه على من يشاء؛ لحكمه يعلمها، ومهما اعطيتم من شيء فيما امركم به فهو يعوضه لكم في الدنيا بالبدل، وفي الاخره بالثواب، وهو -سبحانه- خير الرازقين، فاطلبوا الرزق منه وحده، واسعوا في الاسباب التي امركم بها."},{"id":"3646","s":34,"a":40,"at":"ويوم يحشرهم جميعا ثم يقول للملائكه اهؤلاء اياكم كانوا يعبدون","dt":"[40] واذكر -ايها الرسول- يوم يحشر الله المشركين والمعبودين من دونه من الملائكه، ثم يقول للملائكه على وجه التوبيخ لمن عبدهم: اهؤلاء اياكم كانوا يعبدون من دوننا؟"},{"id":"3647","s":34,"a":41,"at":"قالوا سبحانك انت ولينا من دونهم بل كانوا يعبدون الجن اكثرهم بهم مؤمنون","dt":"[41] قالت الملائكه: ننزهك يا الله عن ان يكون لك شريك في العباده، انت ولينا الذي نطيعه ونعبده وحده، بل كان هؤلاء يعبدون الشياطين، اكثرهم بهم مصدقون ومطيعون."},{"id":"3648","s":34,"a":42,"at":"فاليوم لا يملك بعضكم لبعض نفعا ولا ضرا ونقول للذين ظلموا ذوقوا عذاب النار التي كنتم بها تكذبون","dt":"[42] ففي يوم الحشر لا يملك المعبودون للعابدين نفعا ولا ضرا، ونقول للذين ظلموا انفسهم بالشرك والمعاصي: ذوقوا عذاب النار التي كنتم بها تكذبون."},{"id":"3649","s":34,"a":43,"at":"واذا تتلى عليهم اياتنا بينات قالوا ما هذا الا رجل يريد ان يصدكم عما كان يعبد اباؤكم وقالوا ما هذا الا افك مفترى وقال الذين كفروا للحق لما جاءهم ان هذا الا سحر مبين","dt":"[43] واذا تتلى على كفار «مكه» ايات الله واضحات قالوا: ما محمد الا رجل يرغب ان يمنعكم عن عباده الالهه التي كان يعبدها اباؤكم، وقالوا: ما هذا القران الذي تتلوه علينا -يا محمد- الا كذب مختلق، جئت به من عند نفسك، وليس من عند الله، وقال الكفار عن القران لما جاءهم: ما هذا الا سحر واضح."},{"id":"3650","s":34,"a":44,"at":"وما اتيناهم من كتب يدرسونها وما ارسلنا اليهم قبلك من نذير","dt":"[44] وما انزلنا على الكفار من كتب يقرؤونها قبل القران فتدلهم على ما يزعمون من ان ما جاءهم به محمد سحر، وما ارسلنا اليهم قبلك -ايها الرسول- من رسول ينذرهم باسنا."},{"id":"3651","s":34,"a":45,"at":"وكذب الذين من قبلهم وما بلغوا معشار ما اتيناهم فكذبوا رسلي فكيف كان نكير","dt":"[45] وكذب الذين من قبلهم كعاد وثمود رسلنا، وما بلغ اهل «مكه» عشر ما اتينا الامم السابقه من القوه، وكثره المال، وطول العمر، وغير ذلك من النعم، فكذبوا رسلي فيما جاؤوهم به فاهلكناهم، فانظر -ايها الرسول- كيف كان انكاري عليهم وعقوبتي اياهم؟"},{"id":"3652","s":34,"a":46,"at":"قل انما اعظكم بواحده ان تقوموا لله مثنى وفرادى ثم تتفكروا ما بصاحبكم من جنه ان هو الا نذير لكم بين يدي عذاب شديد","dt":"[46] قل -ايها الرسول- لهؤلاء المكذبين المعاندين: انما انصح لكم بخصله واحده ان تنهضوا في طاعه الله اثنين اثنين وواحدا واحدا، ثم تتفكروا في حال صاحبكم رسول الله -صلى الله عليه وسلم- وفيما نسب اليه، فما به من جنون، ما هو الا مخوف لكم، ونذير من عذاب جهنم قبل ان تقاسوا حرها."},{"id":"3653","s":34,"a":47,"at":"قل ما سالتكم من اجر فهو لكم ان اجري الا على الله وهو على كل شيء شهيد","dt":"[47] قل -ايها الرسول- للكفار: ما سالتكم على الخير الذي جئتكم به من اجر فهو لكم، ما اجري الذي انتظره الا على الله المطلع على اعمالي واعمالكم، لا يخفى عليه شيء فهو يجازي الجميع، كل بما يستحقه."},{"id":"3654","s":34,"a":48,"at":"قل ان ربي يقذف بالحق علام الغيوب","dt":"[48] قل –ايها الرسول- لمن انكر التوحيد ورساله الاسلام: ان ربي يقذف الباطل بحجج من الحق، فيفضحه ويهلكه، والله علام الغيوب، لا يخفى عليه شيء في الارض ولا في السماء."},{"id":"3655","s":34,"a":49,"at":"قل جاء الحق وما يبدئ الباطل وما يعيد","dt":"[49] قل -ايها الرسول-: جاء الحق والشرع العظيم من الله، وذهب الباطل واضمحل سلطانه، فلم يبق للباطل شيء يبدؤه ويعيده."},{"id":"3656","s":34,"a":50,"at":"قل ان ضللت فانما اضل على نفسي وان اهتديت فبما يوحي الي ربي انه سميع قريب","dt":"[50] قل: ان ملت عن الحق فاثم ضلالي على نفسي، وان استقمت عليه فبوحي الله الذي يوحيه الي، ان ربي سميع لما اقول لكم، قريب ممن دعاه وساله."},{"id":"3657","s":34,"a":51,"at":"ولو ترى اذ فزعوا فلا فوت واخذوا من مكان قريب","dt":"[51] ولو ترى -ايها الرسول- اذ فزع الكفار حين معاينتهم عذاب الله، لرايت امرا عظيما، فلا نجاه لهم ولا مهرب، واخذوا الى النار من موضع قريب التناول."},{"id":"3658","s":34,"a":52,"at":"وقالوا امنا به وانى لهم التناوش من مكان بعيد","dt":"[52] وقال الكفار -عندما راوا العذاب في الاخره-: امنا بالله وكتبه ورسله، وكيف لهم تناول الايمان في الاخره ووصولهم له من مكان بعيد؟ قد حيل بينهم وبينه، فمكانه الدنيا، وقد كفروا فيها."},{"id":"3659","s":34,"a":53,"at":"وقد كفروا به من قبل ويقذفون بالغيب من مكان بعيد","dt":"[53] وقد كفروا بالحق في الدنيا، وكذبوا الرسل، ويرمون بالظن من جهه بعيده عن اصابه الحق، ليس لهم فيها مستند لظنهم الباطل، فلا سبيل لاصابتهم الحق، كما لا سبيل للرامي الى اصابه الغرض من مكان بعيد."},{"id":"3660","s":34,"a":54,"at":"وحيل بينهم وبين ما يشتهون كما فعل باشياعهم من قبل انهم كانوا في شك مريب","dt":"[54] وحيل بين الكفار وما يشتهون من التوبه والعوده الى الدنيا ليؤمنوا، كما فعل الله بامثالهم من كفره الامم السابقه، انهم كانوا في الدنيا في شك من امر الرسل والبعث والحساب، محدث للريبه والقلق، فلذلك لم يؤمنوا."},{"id":"3661","s":35,"a":1,"at":"الحمد لله فاطر السموات والارض جاعل الملائكه رسلا اولي اجنحه مثنى وثلاث ورباع يزيد في الخلق ما يشاء ان الله على كل شيء قدير","dt":"[1] الثناء على الله بصفاته التي كلها اوصاف كمال، وبنعمه الظاهره والباطنه، الدينيه والدنيويه، خالق السموات والارض ومبدعهما، جاعل الملائكه رسلا الى من يشاء من عباده، وفيما شاء من امره ونهيه، ومن عظيم قدره الله ان جعل الملائكه اصحاب اجنحه مثنى وثلاث ورباع تطير بها؛ للقيام بما امر الله به، يزيد الله في خلقه ما يشاء. ان الله على كل شيء قدير، لا يستعصي عليه شيء."},{"id":"3662","s":35,"a":2,"at":"ما يفتح الله للناس من رحمه فلا ممسك لها وما يمسك فلا مرسل له من بعده وهو العزيز الحكيم","dt":"[2] ما يفتح الله للناس من رزق ومطر وصحه وعلم وغير ذلك من النعم، فلا احد يقدر ان يمسك هذه الرحمه، وما يمسك منها فلا احد يستطيع ان يرسلها بعده سبحانه وتعالى. وهو العزيز القاهر لكل شيء، الحكيم الذي يرسل الرحمه ويمسكها وفق حكمته."},{"id":"3663","s":35,"a":3,"at":"ياايها الناس اذكروا نعمه الله عليكم هل من خالق غير الله يرزقكم من السماء والارض لا اله الا هو فانى تؤفكون","dt":"[3] يا ايها الناس اذكروا نعمه الله عليكم بقلوبكم والسنتكم وجوارحكم، فلا خالق لكم غير الله يرزقكم من السماء بالمطر، ومن الارض بالماء والمعادن وغير ذلك. لا اله الا هو وحده لا شريك له، فكيف تصرفون عن توحيده وعبادته؟"},{"id":"3664","s":35,"a":4,"at":"وان يكذبوك فقد كذبت رسل من قبلك والى الله ترجع الامور","dt":"[4] وان يكذبك قومك -ايها الرسول- فقد كذب رسل من قبلك، والى الله تصير الامور في الاخره، فيجازي كلا بما يستحق. وفي هذا تسليه للرسول -صلى الله عليه وسلم-."},{"id":"3665","s":35,"a":5,"at":"ياايها الناس ان وعد الله حق فلا تغرنكم الحياه الدنيا ولا يغرنكم بالله الغرور","dt":"[5] يا ايها الناس ان وعد الله بالبعث والثواب والعقاب حق ثابت، فلا تخدعنكم الحياه الدنيا بشهواتها ومطالبها، ولا يخدعنكم بالله الشيطان."},{"id":"3666","s":35,"a":6,"at":"ان الشيطان لكم عدو فاتخذوه عدوا انما يدعو حزبه ليكونوا من اصحاب السعير","dt":"[6] ان الشيطان لبني ادم عدو، فاتخذوه عدوا ولا تطيعوه، انما يدعو اتباعه الى الضلال؛ ليكونوا من اصحاب النار الموقده."},{"id":"3667","s":35,"a":7,"at":"الذين كفروا لهم عذاب شديد والذين امنوا وعملوا الصالحات لهم مغفره واجر كبير","dt":"[7] الذين جحدوا ان الله هو وحده الاله الحق وجحدوا ما جاءت به رسله لهم عذاب شديد في الاخره، والذين صدقوا الله ورسوله وعملوا الصالحات لهم عفو من ربهم، وتجاوز عن ذنوبهم بعد سترها عليهم، ولهم اجر كبير، وهو الجنه."},{"id":"3668","s":35,"a":8,"at":"افمن زين له سوء عمله فراه حسنا فان الله يضل من يشاء ويهدي من يشاء فلا تذهب نفسك عليهم حسرات ان الله عليم بما يصنعون","dt":"[8] افمن حسن له الشيطان اعماله السيئه من معاصي الله والكفر وعباده ما دونه من الالهه والاوثان فراه حسنا جميلا، كمن هداه الله تعالى، فراى الحسن حسنا والسيئ سيئا؟ فان الله يضل من يشاء من عباده، ويهدي من يشاء، فلا تهلك نفسك حزنا على كفر هؤلاء الضالين، ان الله عليم بقبائحهم وسيجازيهم عليها اسوا الجزاء."},{"id":"3669","s":35,"a":9,"at":"والله الذي ارسل الرياح فتثير سحابا فسقناه الى بلد ميت فاحيينا به الارض بعد موتها كذلك النشور","dt":"[9] والله هو الذي ارسل الرياح فتحرك سحابا، فسقناه الى بلد جدب، فينزل الماء فاحيينا به الارض بعد يبسها فتخضر بالنبات، مثل ذلك الاحياء يحيي الله الموتى يوم القيامه."},{"id":"3670","s":35,"a":10,"at":"من كان يريد العزه فلله العزه جميعا اليه يصعد الكلم الطيب والعمل الصالح يرفعه والذين يمكرون السيئات لهم عذاب شديد ومكر اولئك هو يبور","dt":"[10] من كان يطلب عزه في الدنيا او الاخره فليطلبها من الله، ولا تنال الا بطاعته، فلله العزه جميعا، فمن اعتز بالمخلوق اذله الله، ومن اعتز بالخالق اعزه الله، اليه سبحانه يصعد ذكره والعمل الصالح يرفعه. والذين يكتسبون السيئات لهم عذاب شديد، ومكر اولئك يهلك ويفسد، ولا يفيدهم شيئا."},{"id":"3671","s":35,"a":11,"at":"والله خلقكم من تراب ثم من نطفه ثم جعلكم ازواجا وما تحمل من انثى ولا تضع الا بعلمه وما يعمر من معمر ولا ينقص من عمره الا في كتاب ان ذلك على الله يسير","dt":"[11] والله خلق اباكم ادم من تراب، ثم جعل نسله من سلاله من ماء مهين، ثم جعلكم رجالا ونساء. وما تحمل من انثى ولا تضع الا بعلمه، وما يعمر من معمر فيطول عمره، ولا ينقص من عمره الا في كتاب عنده، وهو اللوح المحفوظ، قبل ان تحمل به امه وقبل ان تضعه. قد احصى الله ذلك كله، وعلمه قبل ان يخلقه، لا يزاد فيما كتب له ولا ينقص. ان خلقكم وعلم احوالكم وكتابتها في اللوح المحفوظ سهل يسير على الله."},{"id":"3672","s":35,"a":12,"at":"وما يستوي البحران هذا عذب فرات سائغ شرابه وهذا ملح اجاج ومن كل تاكلون لحما طريا وتستخرجون حليه تلبسونها وترى الفلك فيه مواخر لتبتغوا من فضله ولعلكم تشكرون","dt":"[12] وما يستوي البحران: هذا عذب شديد العذوبه، سهل مروره في الحلق يزيل العطش، وهذا ملح شديد الملوحه، ومن كل من البحرين تاكلون سمكا طريا شهي الطعم، وتستخرجون زينه هي اللؤلؤ والمرجان تلبسونها، وترى السفن فيه شاقات المياه؛ لتبتغوا من فضله من التجاره وغيرها. وفي هذا دلاله على قدره الله ووحدانيته؛ ولعلكم تشكرون لله على هذه النعم التي انعم بها عليكم."},{"id":"3673","s":35,"a":13,"at":"يولج الليل في النهار ويولج النهار في الليل وسخر الشمس والقمر كل يجري لاجل مسمى ذلكم الله ربكم له الملك والذين تدعون من دونه ما يملكون من قطمير","dt":"[13] والله يدخل من ساعات الليل في النهار، فيزيد النهار بقدر ما نقص من الليل، ويدخل من ساعات النهار في الليل، فيزيد الليل بقدر ما نقص من النهار، وذلل الشمس والقمر يجريان لوقت معلوم، ذلكم الذي فعل هذا هو الله ربكم له الملك كله، والذين تعبدون من دون الله ما يملكون من قطمير، وهي القشره الرقيقه البيضاء تكون على النواه."},{"id":"3674","s":35,"a":14,"at":"ان تدعوهم لا يسمعوا دعاءكم ولو سمعوا ما استجابوا لكم ويوم القيامه يكفرون بشرككم ولا ينبئك مثل خبير","dt":"[14] ان تدعوا -ايها الناس- هذه المعبودات من دون الله لا يسمعوا دعاءكم، ولو سمعوا على سبيل الفرض ما اجابوكم، ويوم القيامه يتبرؤون منكم، ولا احد يخبرك -ايها الرسول- اصدق من الله العليم الخبير."},{"id":"3675","s":35,"a":15,"at":"ياايها الناس انتم الفقراء الى الله والله هو الغني الحميد","dt":"[15] يا ايها الناس انتم المحتاجون الى الله في كل شيء، لا تستغنون عنه طرفه عين، وهو سبحانه الغني عن الناس وعن كل شيء من مخلوقاته، الحميد في ذاته واسمائه وصفاته، المحمود على نعمه؛ فان كل نعمه بالناس منه، فله الحمد والشكر على كل حال."},{"id":"3676","s":35,"a":16,"at":"ان يشا يذهبكم ويات بخلق جديد","dt":"[16] ان يشا الله يهلككم ايها الناس، ويات بقوم اخرين يطيعونه ويعبدونه وحده."},{"id":"3677","s":35,"a":17,"at":"وما ذلك على الله بعزيز","dt":"[17] وما اهلاككم والاتيان بخلق سواكم على الله بممتنع، بل ذلك على الله سهل يسير."},{"id":"3678","s":35,"a":18,"at":"ولا تزر وازره وزر اخرى وان تدع مثقله الى حملها لا يحمل منه شيء ولو كان ذا قربى انما تنذر الذين يخشون ربهم بالغيب واقاموا الصلاه ومن تزكى فانما يتزكى لنفسه والى الله المصير","dt":"[18] ولا تحمل نفس مذنبه ذنب نفس اخرى، وان تسال نفس مثقله بالخطايا من يحمل عنها من ذنوبها لم تجد من يحمل عنها شيئا، ولو كان الذي سالته ذا قرابه منها من اب او اخ ونحوهما. انما تحذر -ايها الرسول- الذين يخافون عذاب ربهم بالغيب، وادوا الصلاه حق ادائها. ومن تطهر من الشرك وغيره من المعاصي فانما يتطهر لنفسه. والى الله سبحانه مال الخلائق ومصيرهم، فيجازي كلا بما يستحق."},{"id":"3679","s":35,"a":19,"at":"وما يستوي الاعمى والبصير","dt":"[19] وما يستوي الاعمى عن دين الله، والبصير الذي ابصر طريق الحق واتبعه،"},{"id":"3680","s":35,"a":20,"at":"ولا الظلمات ولا النور","dt":"[20] وما تستوي ظلمات الكفر ونور الايمان،"},{"id":"3681","s":35,"a":21,"at":"ولا الظل ولا الحرور","dt":"[21] ولا الظل ولا الريح الحاره،"},{"id":"3682","s":35,"a":22,"at":"وما يستوي الاحياء ولا الاموات ان الله يسمع من يشاء وما انت بمسمع من في القبور","dt":"[22] وما يستوي احياء القلوب بالايمان واموات القلوب بالكفر. ان الله يسمع من يشاء سماع فهم وقبول، وما انت -ايها الرسول- بمسمع من في القبور، فكما لا تسمع الموتى في قبورهم فكذلك لا تسمع هؤلاء الكفار لموت قلوبهم،"},{"id":"3683","s":35,"a":23,"at":"ان انت الا نذير","dt":"[23] ان انت الا نذير لهم غضب الله وعقابه."},{"id":"3684","s":35,"a":24,"at":"انا ارسلناك بالحق بشيرا ونذيرا وان من امه الا خلا فيها نذير","dt":"[24] انا ارسلناك بالحق، وهو الايمان بالله وشرائع الدين، مبشرا بالجنه من صدقك وعمل بهديك، ومحذرا من كذبك وعصاك النار. وما من امه من الامم الا جاءها نذير يحذرها عاقبه كفرها وضلالها."},{"id":"3685","s":35,"a":25,"at":"وان يكذبوك فقد كذب الذين من قبلهم جاءتهم رسلهم بالبينات وبالزبر وبالكتاب المنير","dt":"[25] وان يكذبك هؤلاء المشركون فقد كذب الذين من قبلهم رسلهم الذين جاؤوهم بالمعجزات الواضحات الداله على نبوتهم، وجاؤوهم بالكتب المجموع فيها كثير من الاحكام، وبالكتاب المنير الموضح لطريق الخير والشر."},{"id":"3686","s":35,"a":26,"at":"ثم اخذت الذين كفروا فكيف كان نكير","dt":"[26] ثم اخذت الذين كفروا بانواع العذاب، فانظر كيف كان انكاري لعملهم وحلول عقوبتي بهم؟"},{"id":"3687","s":35,"a":27,"at":"الم تر ان الله انزل من السماء ماء فاخرجنا به ثمرات مختلفا الوانها ومن الجبال جدد بيض وحمر مختلف الوانها وغرابيب سود","dt":"[27] الم تر ان الله انزل من السماء ماء، فسقينا به اشجارا في الارض، فاخرجنا من تلك الاشجار ثمرات مختلفا الوانها، منها الاحمر ومنها الاسود والاصفر وغير ذلك؟ وخلقنا من الجبال طرائق بيضا وحمرا مختلفا الوانها، وخلقنا من الجبال جبالا شديده السواد."},{"id":"3688","s":35,"a":28,"at":"ومن الناس والدواب والانعام مختلف الوانه كذلك انما يخشى الله من عباده العلماء ان الله عزيز غفور","dt":"[28] وخلقنا من الناس والدواب والابل والبقر والغنم ما هو مختلف الوانه كذلك، فمن ذلك الاحمر والابيض والاسود وغير ذلك كاختلاف الوان الثمار والجبال. انما يخشى الله ويتقي عقابه بطاعته واجتناب معصيته العلماء به سبحانه، وبصفاته، وبشرعه، وقدرته على كل شيء، ومنها اختلاف هذه المخلوقات مع اتحاد سببها، ويتدبرون ما فيها من عظات وعبر. ان الله عزيز قوي لا يغالب، غفور يثيب اهل الطاعه، ويعفو عنهم."},{"id":"3689","s":35,"a":29,"at":"ان الذين يتلون كتاب الله واقاموا الصلاه وانفقوا مما رزقناهم سرا وعلانيه يرجون تجاره لن تبور","dt":"[29] ان الذين يقرؤون القران ويعملون به، وداوموا على الصلاه في اوقاتها، وانفقوا مما رزقناهم من انواع النفقات الواجبه والمستحبه سرا وجهرا، هؤلاء يرجون بذلك تجاره لن تكسد ولن تهلك، الا وهي رضا ربهم، والفوز بجزيل ثوابه؛"},{"id":"3690","s":35,"a":30,"at":"ليوفيهم اجورهم ويزيدهم من فضله انه غفور شكور","dt":"[30] ليوفيهم الله تعالى ثواب اعمالهم كاملا غير منقوص، ويضاعف لهم الحسنات من فضله، ان الله غفور لسيئاتهم، شكور لحسناتهم، يثيبهم عليها الجزيل من الثواب."},{"id":"3691","s":35,"a":31,"at":"والذي اوحينا اليك من الكتاب هو الحق مصدقا لما بين يديه ان الله بعباده لخبير بصير","dt":"[31] والذي انزلناه اليك -ايها الرسول- من القران هو الحق المصدق للكتب التي انزلها الله على رسله قبلك. ان الله لخبير بشؤون عباده، بصير باعمالهم، وسيجازيهم عليها."},{"id":"3692","s":35,"a":32,"at":"ثم اورثنا الكتاب الذين اصطفينا من عبادنا فمنهم ظالم لنفسه ومنهم مقتصد ومنهم سابق بالخيرات باذن الله ذلك هو الفضل الكبير","dt":"[32] ثم اعطينا -بعد هلاك الامم- القران من اخترناهم من امه محمد -صلى الله عليه وسلم-: فمنهم ظالم لنفسه بفعل بعض المعاصي، ومنهم مقتصد، وهو المؤدي للواجبات المجتنب للمحرمات، ومنهم سابق بالخيرات باذن الله، اي مسارع مجتهد في الاعمال الصالحه، فرضها ونفلها، ذلك الاعطاء للكتاب واصطفاء هذه الامه هو الفضل الكبير."},{"id":"3693","s":35,"a":33,"at":"جنات عدن يدخلونها يحلون فيها من اساور من ذهب ولؤلؤا ولباسهم فيها حرير","dt":"[33] جنات اقامه دائمه للذين اورثهم الله كتابه، يزينون فيها باساور الذهب وباللؤلؤ، ولباسهم المعتاد في الجنه حرير اي: ثياب رقيقه."},{"id":"3694","s":35,"a":34,"at":"وقالوا الحمد لله الذي اذهب عنا الحزن ان ربنا لغفور شكور","dt":"[34] وقالوا حين دخلوا الجنه: الحمد لله الذي اذهب عنا كل حزن، ان ربنا لغفور؛ حيث غفر لنا الزلات، شكور؛ حيث قبل منا الحسنات وضاعفها"},{"id":"3695","s":35,"a":35,"at":"الذي احلنا دار المقامه من فضله لا يمسنا فيها نصب ولا يمسنا فيها لغوب","dt":"[35] وهو الذي انزلنا دار الجنه من فضله، لا يمسنا فيها تعب ولا اعياء."},{"id":"3696","s":35,"a":36,"at":"والذين كفروا لهم نار جهنم لا يقضى عليهم فيموتوا ولا يخفف عنهم من عذابها كذلك نجزي كل كفور","dt":"[36] والذين كفروا بالله ورسوله لهم نار جهنم الموقده، لا يقضى عليهم بالموت، فيموتوا ويستريحوا، ولا يخفف عنهم من عذابها، مثل ذلك الجزاء يجزي الله كل من هو مبالغ في الكفر متماد فيه مصر عليه."},{"id":"3697","s":35,"a":37,"at":"وهم يصطرخون فيها ربنا اخرجنا نعمل صالحا غير الذي كنا نعمل او لم نعمركم ما يتذكر فيه من تذكر وجاءكم النذير فذوقوا فما للظالمين من نصير","dt":"[37] وهؤلاء الكفار يصرخون من شده العذاب في نار جهنم مستغيثين: ربنا اخرجنا من نار جهنم، وردنا الى الدنيا نعمل صالحا غير الذي كنا نعمله في حياتنا الدنيا، فنؤمن بدل الكفر، فيقول لهم: اولم نمهلكم في الحياه قدرا وافيا من العمر، يتعظ فيه من اتعظ، وجاءكم النبي -صلى الله عليه وسلم-، ومع ذلك لم تتذكروا ولم تتعظوا؟ فذوقوا عذاب جهنم، فليس للكافرين من ناصر ينصرهم من عذاب الله."},{"id":"3698","s":35,"a":38,"at":"ان الله عالم غيب السموات والارض انه عليم بذات الصدور","dt":"[38] ان الله مطلع على كل غائب في السموات والارض، وانه عليم بخفايا الصدور، فاتقوه ان يطلع عليكم، وانتم تضمرون الشك او الشرك في وحدانيته، او في نبوه محمد -صلى الله عليه وسلم-، او ان تعصوه بما دون ذلك."},{"id":"3699","s":35,"a":39,"at":"هو الذي جعلكم خلائف في الارض فمن كفر فعليه كفره ولا يزيد الكافرين كفرهم عند ربهم الا مقتا ولا يزيد الكافرين كفرهم الا خسارا","dt":"[39] الله هو الذي جعلكم -ايها الناس- يخلف بعضكم بعضا في الارض، فمن جحد وحدانيه الله منكم فعلى نفسه ضرره وكفره، ولا يزيد الكافرين كفرهم عند ربهم الا بغضا وغضبا، ولا يزيدهم كفرهم بالله الا ضلالا وهلاكا."},{"id":"3700","s":35,"a":40,"at":"قل ارايتم شركاءكم الذين تدعون من دون الله اروني ماذا خلقوا من الارض ام لهم شرك في السموات ام اتيناهم كتابا فهم على بينه منه بل ان يعد الظالمون بعضهم بعضا الا غرورا","dt":"[40] قل -ايها الرسول- للمشركين: اخبروني اي شيء خلق شركاؤكم من الارض، ام ان لشركائكم الذين تعبدونهم من دون الله شركا مع الله في خلق السموات، ام اعطيناهم كتابا فهم على حجه منه؟ بل ما يعد الكافرون بعضهم بعضا الا غرورا وخداعا."},{"id":"3701","s":35,"a":41,"at":"ان الله يمسك السموات والارض ان تزولا ولئن زالتا ان امسكهما من احد من بعده انه كان حليما غفورا","dt":"[41] ان الله يمسك السموات والارض ان تزولا عن مكانهما، ولئن زالت السموات والارض عن مكانهما ما يمسكهما من احد من بعده. ان الله كان حليما في تاخير العقوبه عن الكافرين والعصاه، غفورا لمن تاب من ذنبه ورجع اليه."},{"id":"3702","s":35,"a":42,"at":"واقسموا بالله جهد ايمانهم لئن جاءهم نذير ليكونن اهدى من احدى الامم فلما جاءهم نذير ما زادهم الا نفورا","dt":"[42] واقسم كفار قريش بالله اشد الايمان: لئن جاءهم رسول من عند الله يخوفهم عقاب الله ليكونن اكثر استقامه واتباعا للحق من اليهود والنصارى وغيرهم، فلما جاءهم محمد -صلى الله عليه وسلم- ما زادهم ذلك الا بعدا عن الحق ونفورا منه."},{"id":"3703","s":35,"a":43,"at":"استكبارا في الارض ومكر السيئ ولا يحيق المكر السيئ الا باهله فهل ينظرون الا سنه الاولين فلن تجد لسنه الله تبديلا ولن تجد لسنه الله تحويلا","dt":"[43] ليس اقسامهم لقصد حسن وطلبا للحق، وانما هو استكبار في الارض على الخلق، يريدون به المكر السيئ والخداع والباطل، ولا يحيق المكر السيئ الا باهله، فهل ينتظر المستكبرون الماكرون الا العذاب الذي نزل بامثالهم الذين سبقوهم، فلن تجد لطريقه الله تبديلا ولا تحويلا، فلا يستطيع احد ان يبدل، ولا ان يحول العذاب عن نفسه او غيره."},{"id":"3704","s":35,"a":44,"at":"او لم يسيروا في الارض فينظروا كيف كان عاقبه الذين من قبلهم وكانوا اشد منهم قوه وما كان الله ليعجزه من شيء في السموات ولا في الارض انه كان عليما قديرا","dt":"[44] اولم يسر كفار «مكه» في الارض، فينظروا كيف كان عاقبه الذين من قبلهم كعاد وثمود وامثالهم، وما حل بهم من الدمار، وبديارهم من الخراب حين كذبوا الرسل، وكان اولئك الكفره اشد قوه وبطشا من كفار «مكه»؟ وما كان الله تعالى ليعجزه ويفوته من شيء في السموات ولا في الارض، انه كان عليما بافعالهم، قديرا على اهلاكهم."},{"id":"3705","s":35,"a":45,"at":"ولو يؤاخذ الله الناس بما كسبوا ما ترك على ظهرها من دابه ولكن يؤخرهم الى اجل مسمى فاذا جاء اجلهم فان الله كان بعباده بصيرا","dt":"[45] ولو يعاقب الله الناس بما عملوا من الذنوب والمعاصي ما ترك على ظهر الارض من دابه تدب عليها، ولكن يمهلهم ويؤخر عقابهم الى وقت معلوم عنده، فاذا جاء وقت عقابهم فان الله كان بعباده بصيرا، لا يخفى عليه احد منهم، ولا يعزب عنه علم شيء من امورهم، وسيجازيهم بما عملوا من خير او شر."},{"id":"3706","s":36,"a":1,"at":"يس","dt":"[1] يس سبق الكلام على الحروف المقطعه في اول سوره البقره."},{"id":"3707","s":36,"a":2,"at":"والقران الحكيم","dt":"[2] يقسم الله تعالى بالقران المحكم بما فيه من الاحكام والحكم والحجج"},{"id":"3708","s":36,"a":3,"at":"انك لمن المرسلين","dt":"[3] انك -ايها الرسول- لمن المرسلين بوحي الله الى عباده،"},{"id":"3709","s":36,"a":4,"at":"على صراط مستقيم","dt":"[4] على طريق مستقيم معتدل، وهو الاسلام."},{"id":"3710","s":36,"a":5,"at":"تنزيل العزيز الرحيم","dt":"[5] نزل الله هذا القران تنزيل العزيز في انتقامه من اهل الكفر والمعاصي، الرحيم بمن تاب من عباده وعمل صالحا."},{"id":"3711","s":36,"a":6,"at":"لتنذر قوما ما انذر اباؤهم فهم غافلون","dt":"[6] انزلناه عليك -ايها الرسول- لتحذر به قوما لم ينذر اباؤهم من قبلك، وهم العرب، فهؤلاء القوم ساهون عن الايمان والاستقامه على العمل الصالح. وكل امه ينقطع عنها الانذار تقع في الغفله، وفي هذا دليل على وجوب الدعوه والتذكير على العلماء بالله وشرعه؛ لايقاظ المسلمين من غفلتهم."},{"id":"3712","s":36,"a":7,"at":"لقد حق القول على اكثرهم فهم لا يؤمنون","dt":"[7] لقد وجب العذاب على اكثر هؤلاء الكافرين، بعد ان عرض عليهم الحق فرفضوه، فهم لا يصدقون بالله ولا برسوله، ولا يعملون بشرعه"},{"id":"3713","s":36,"a":8,"at":"انا جعلنا في اعناقهم اغلالا فهي الى الاذقان فهم مقمحون","dt":"[8] انا جعلنا هؤلاء الكفار الذين عرض عليهم الحق فردوه، واصروا على الكفر وعدم الايمان، كمن جعل في اعناقهم اغلال، فجمعت ايديهم مع اعناقهم تحت اذقانهم، فاضطروا الى رفع رؤوسهم الى السماء، فهم مغلولون عن كل خير، لا يبصرون الحق ولا يهتدون اليه."},{"id":"3714","s":36,"a":9,"at":"وجعلنا من بين ايديهم سدا ومن خلفهم سدا فاغشيناهم فهم لا يبصرون","dt":"[9] وجعلنا من امام الكافرين سدا ومن ورائهم سدا، فهم بمنزله من سد طريقه من بين يديه ومن خلفه، فاعمينا ابصارهم؛ بسبب كفرهم واستكبارهم، فهم لا يبصرون رشدا، ولا يهتدون. وكل من قابل دعوه الاسلام بالاعراض والعناد، فهو حقيق بهذا العقاب."},{"id":"3715","s":36,"a":10,"at":"وسواء عليهم اانذرتهم ام لم تنذرهم لا يؤمنون","dt":"[10] يستوي عند هؤلاء الكفار المعاندين تحذيرك لهم -ايها الرسول- وعدم تحذيرك، فهم لا يصدقون ولا يعملون."},{"id":"3716","s":36,"a":11,"at":"انما تنذر من اتبع الذكر وخشي الرحمن بالغيب فبشره بمغفره واجر كريم","dt":"[11] انما ينفع تحذيرك من امن بالقران واتبع ما فيه من احكام الله، وخاف الرحمن، حيث لا يراه احد الا الله، فبشره بمغفره من الله لذنوبه، وثواب منه في الاخره على اعماله الصالحه، وهو دخوله الجنه."},{"id":"3717","s":36,"a":12,"at":"انا نحن نحيي الموتى ونكتب ما قدموا واثارهم وكل شيء احصيناه في امام مبين","dt":"[12] انا نحن نحيي الاموات جميعا ببعثهم يوم القيامه، ونكتب ما عملوا من الخير والشر، واثارهم التي كانوا سببا فيها في حياتهم وبعد مماتهم من خير، كالولد الصالح، والعلم النافع، والصدقه الجاريه، ومن شر، كالشرك والعصيان، وكل شيء احصيناه في كتاب واضح هو ام الكتب، واليه مرجعها، وهو اللوح المحفوظ. فعلى العاقل محاسبه نفسه؛ ليكون قدوه في الخير في حياته وبعد مماته."},{"id":"3718","s":36,"a":13,"at":"واضرب لهم مثلا اصحاب القريه اذ جاءها المرسلون","dt":"[13] واضرب -ايها الرسول- لمشركي قومك الرادين لدعوتك مثلا يعتبرون به، وهو قصه اهل القريه، حين ذهب اليهم المرسلون،"},{"id":"3719","s":36,"a":14,"at":"اذ ارسلنا اليهم اثنين فكذبوهما فعززنا بثالث فقالوا انا اليكم مرسلون","dt":"[14] اذ ارسلنا اليهم رسولين لدعوتهم الى الايمان بالله وترك عباده غيره، فكذب اهل القريه الرسولين، فقويناهما برسول ثالث، فقال الثلاثه لاهل القريه: انا اليكم -ايها القوم- مرسلون."},{"id":"3720","s":36,"a":15,"at":"قالوا ما انتم الا بشر مثلنا وما انزل الرحمن من شيء ان انتم الا تكذبون","dt":"[15] قال اهل القريه للمرسلين: ما انتم الا اناس مثلنا، وما انزل الرحمن شيئا من الوحي، وما انتم -ايها الرسل- الا تكذبون."},{"id":"3721","s":36,"a":16,"at":"قالوا ربنا يعلم انا اليكم لمرسلون","dt":"[16] قال المرسلون مؤكدين: ربنا الذي ارسلنا يعلم انا اليكم لمرسلون،"},{"id":"3722","s":36,"a":17,"at":"وما علينا الا البلاغ المبين","dt":"[17] وما علينا الا تبليغ الرساله بوضوح، ولا نملك هدايتكم، فالهدايه بيد الله وحده."},{"id":"3723","s":36,"a":18,"at":"قالوا انا تطيرنا بكم لئن لم تنتهوا لنرجمنكم وليمسنكم منا عذاب اليم","dt":"[18] قال اهل القريه: انا تشاءمنا بكم، لئن لم تكفوا عن دعوتكم لنا لنقتلنكم رميا بالحجاره، وليصيبنكم منا عذاب اليم موجع."},{"id":"3724","s":36,"a":19,"at":"قالوا طائركم معكم اان ذكرتم بل انتم قوم مسرفون","dt":"[19] قال المرسلون: شؤمكم واعمالكم من الشرك والشر معكم ومردوده عليكم، اان وعظتم بما فيه خيركم تشاءمتم وتوعدتمونا بالرجم والتعذيب؟ بل انتم قوم عادتكم الاسراف في العصيان والتكذيب."},{"id":"3725","s":36,"a":20,"at":"وجاء من اقصى المدينه رجل يسعى قال ياقوم اتبعوا المرسلين","dt":"[20] وجاء من مكان بعيد في المدينه رجل مسرع (وذلك حين علم ان اهل القريه هموا بقتل الرسل او تعذيبهم)، قال: يا قوم اتبعوا المرسلين اليكم من الله،"},{"id":"3726","s":36,"a":21,"at":"اتبعوا من لا يسالكم اجرا وهم مهتدون","dt":"[21] اتبعوا الذين لا يطلبون منكم اموالا على ابلاغ الرساله، وهم مهتدون فيما يدعونكم اليه من عباده الله وحده. وفي هذا بيان فضل من سعى الى الامر بالمعروف والنهي عن المنكر."},{"id":"3727","s":36,"a":22,"at":"وما لي لا اعبد الذي فطرني واليه ترجعون","dt":"[22] واي شيء يمنعني من ان اعبد الله الذي خلقني، واليه تصيرون جميعا؟"},{"id":"3728","s":36,"a":23,"at":"ااتخذ من دونه الهه ان يردن الرحمن بضر لا تغن عني شفاعتهم شيئا ولا ينقذون","dt":"[23] ااعبد من دون الله الهه اخرى لا تملك من الامر شيئا، ان يردني الرحمن بسوء فهذه الالهه لا تملك دفع ذلك ولا منعه، ولا تستطيع انقاذي مما انا فيه؟"},{"id":"3729","s":36,"a":24,"at":"اني اذا لفي ضلال مبين","dt":"[24] اني ان فعلت ذلك لفي خطا واضح ظاهر."},{"id":"3730","s":36,"a":25,"at":"اني امنت بربكم فاسمعون","dt":"[25] اني امنت بربكم فاستمعوا الى ما قلته لكم، واطيعوني بالايمان. فلما قال ذلك وثب اليه قومه وقتلوه، فادخله الله الجنه."},{"id":"3731","s":36,"a":26,"at":"قيل ادخل الجنه قال ياليت قومي يعلمون","dt":"[26] قيل له بعد قتله: ادخل الجنه، اكراما له."},{"id":"3732","s":36,"a":27,"at":"بما غفر لي ربي وجعلني من المكرمين","dt":"[27] قال وهو في النعيم والكرامه: يا ليت قومي يعلمون بغفران ربي لي واكرامه اياي؛ بسبب ايماني بالله وصبري على طاعته، واتباع رسله حتى قتلت، فيؤمنوا بالله فيدخلوا الجنه مثلي."},{"id":"3733","s":36,"a":28,"at":"وما انزلنا على قومه من بعده من جند من السماء وما كنا منزلين","dt":"[28] وما احتاج الامر الى انزال جند من السماء لعذابهم بعد قتلهم الرجل الناصح لهم وتكذيبهم رسلهم، فهم اضعف من ذلك واهون، وما كنا منزلين الملائكه على الامم اذا اهلكناهم، بل نبعث عليهم عذابا يدمرهم."},{"id":"3734","s":36,"a":29,"at":"ان كانت الا صيحه واحده فاذا هم خامدون","dt":"[29] ما كان هلاكهم الا بصيحه واحده، فاذا هم ميتون لم تبق منهم باقيه."},{"id":"3735","s":36,"a":30,"at":"ياحسره على العباد ما ياتيهم من رسول الا كانوا به يستهزئون","dt":"[30] يا حسره العباد وندامتهم يوم القيامه اذا عاينوا العذاب، ما ياتيهم من رسول من الله تعالى الا كانوا به يستهزئون ويسخرون."},{"id":"3736","s":36,"a":31,"at":"الم يروا كم اهلكنا قبلهم من القرون انهم اليهم لا يرجعون","dt":"[31] الم ير هؤلاء المستهزئون ويعتبروا بمن قبلهم من القرون التي اهلكناها انهم لا يرجعون الى هذه الدنيا؟"},{"id":"3737","s":36,"a":32,"at":"وان كل لما جميع لدينا محضرون","dt":"[32] وما كل هذه القرون التي اهلكناها وغيرهم، الا محضرون جميعا عندنا يوم القيامه للحساب والجزاء."},{"id":"3738","s":36,"a":33,"at":"وايه لهم الارض الميته احييناها واخرجنا منها حبا فمنه ياكلون","dt":"[33] ودلاله لهؤلاء المشركين على قدره الله على البعث والنشور: هذه الارض الميته التي لا نبات فيها، احييناها بانزال الماء، واخرجنا منها انواع النبات مما ياكل الناس والانعام، ومن احيا الارض بالنبات احيا الخلق بعد الممات."},{"id":"3739","s":36,"a":34,"at":"وجعلنا فيها جنات من نخيل واعناب وفجرنا فيها من العيون","dt":"[34] وجعلنا في هذه الارض بساتين من نخيل واعناب، وفجرنا فيها من عيون المياه ما يسقيها."},{"id":"3740","s":36,"a":35,"at":"لياكلوا من ثمره وما عملته ايديهم افلا يشكرون","dt":"[35] كل ذلك؛ لياكل العباد من ثمره، وما ذلك الا من رحمه الله بهم لا بسعيهم ولا بكدهم، ولا بحولهم وبقوتهم، افلا يشكرون الله على ما انعم به عليهم من هذه النعم التي لا تعد ولا تحصى؟"},{"id":"3741","s":36,"a":36,"at":"سبحان الذي خلق الازواج كلها مما تنبت الارض ومن انفسهم ومما لا يعلمون","dt":"[36] تنزه الله العظيم الذي خلق الاصناف جميعها من انواع نبات الارض، ومن انفسهم ذكورا واناثا، ومما لا يعلمون من مخلوقات الله الاخرى. قد انفرد سبحانه بالخلق، فلا ينبغي ان يشرك به غيره."},{"id":"3742","s":36,"a":37,"at":"وايه لهم الليل نسلخ منه النهار فاذا هم مظلمون","dt":"[37] وعلامه لهم داله على توحيد الله وكمال قدرته: هذا الليل ننزع منه النهار، فاذا الناس مظلمون."},{"id":"3743","s":36,"a":38,"at":"والشمس تجري لمستقر لها ذلك تقدير العزيز العليم","dt":"[38] وايه لهم الشمس تجري لمستقر لها، قدره الله لها لا تتعداه ولا تقصر عنه، ذلك تقدير العزيز الذي لا يغالب، العليم الذي لا يغيب عن علمه شيء."},{"id":"3744","s":36,"a":39,"at":"والقمر قدرناه منازل حتى عاد كالعرجون القديم","dt":"[39] وجعلنا القمر ايه في خلقه، وقدرناه منازل كل ليله: يبدا هلالا ضئيلا حتى يكمل قمرا مستديرا، ثم يرجع ضئيلا مثل عذق النخله المتقوس في الرقه والانحناء والصفره؛ لقدمه ويبسه."},{"id":"3745","s":36,"a":40,"at":"لا الشمس ينبغي لها ان تدرك القمر ولا الليل سابق النهار وكل في فلك يسبحون","dt":"[40] لكل من الشمس والقمر والليل والنهار وقت قدره الله له لا يتعداه، فلا يمكن للشمس ان تلحق القمر فتمحو نوره، او تغير مجراه، ولا يمكن لليل ان يسبق النهار، فيدخل عليه قبل انقضاء وقته، وكل من الشمس والقمر والكواكب في فلك يجرون."},{"id":"3746","s":36,"a":41,"at":"وايه لهم انا حملنا ذريتهم في الفلك المشحون","dt":"[41] ودليل لهم وبرهان على ان الله وحده المستحق للعباده، المنعم بالنعم، انا حملنا من نجا من ولد ادم في سفينه نوح المملوءه باجناس المخلوقات؛ لاستمرار الحياه بعد الطوفان."},{"id":"3747","s":36,"a":42,"at":"وخلقنا لهم من مثله ما يركبون","dt":"[42] وخلقنا لهؤلاء المشركين وغيرهم مثل سفينه نوح من السفن وغيرها من المراكب التي يركبونها وتبلغهم اوطانهم."},{"id":"3748","s":36,"a":43,"at":"وان نشا نغرقهم فلا صريخ لهم ولا هم ينقذون","dt":"[43] وان نشا نغرقهم، فلا يجدون مغيثا لهم من غرقهم، ولا هم يخلصون من الغرق."},{"id":"3749","s":36,"a":44,"at":"الا رحمه منا ومتاعا الى حين","dt":"[44] الا ان نرحمهم فننجيهم ونمتعهم الى اجل؛ لعلهم يرجعون ويستدركون ما فرطوا فيه."},{"id":"3750","s":36,"a":45,"at":"واذا قيل لهم اتقوا ما بين ايديكم وما خلفكم لعلكم ترحمون","dt":"[45] واذا قيل للمشركين: احذروا امر الاخره واهوالها واحوال الدنيا وعقابها؛ رجاء رحمه الله لكم، اعرضوا ولم يجيبوا الى ذلك."},{"id":"3751","s":36,"a":46,"at":"وما تاتيهم من ايه من ايات ربهم الا كانوا عنها معرضين","dt":"[46] وما تجيء هؤلاء المشركين من علامه واضحه من عند ربهم؛ لتهديهم للحق، وتبين لهم صدق الرسول، الا اعرضوا عنها، ولم ينتفعوا بها."},{"id":"3752","s":36,"a":47,"at":"واذا قيل لهم انفقوا مما رزقكم الله قال الذين كفروا للذين امنوا انطعم من لو يشاء الله اطعمه ان انتم الا في ضلال مبين","dt":"[47] واذا قيل للكافرين: انفقوا من الرزق الذي من به الله عليكم، قالوا للمؤمنين محتجين: انطعم من لو شاء الله اطعمه؟ ما انتم -ايها المؤمنون- الا في بعد واضح عن الحق؛ اذ تامروننا بذلك."},{"id":"3753","s":36,"a":48,"at":"ويقولون متى هذا الوعد ان كنتم صادقين","dt":"[48] ويقول هؤلاء الكفار على وجه التكذيب والاستعجال: متى يكون البعث ان كنتم صادقين فيما تقولونه عنه؟"},{"id":"3754","s":36,"a":49,"at":"ما ينظرون الا صيحه واحده تاخذهم وهم يخصمون","dt":"[49] ما ينتظر هؤلاء المشركون الذين يستعجلون بوعيد الله اياهم الا نفخه الفزع عند قيام الساعه، تاخذهم فجاه، وهم يختصمون في شؤون حياتهم."},{"id":"3755","s":36,"a":50,"at":"فلا يستطيعون توصيه ولا الى اهلهم يرجعون","dt":"[50] فلا يستطيع هؤلاء المشركون عند النفخ في «القرن» ان يوصوا احدا بشيء، ولا يستطيعون الرجوع الى اهلهم، بل يموتون في اسواقهم ومواضعهم."},{"id":"3756","s":36,"a":51,"at":"ونفخ في الصور فاذا هم من الاجداث الى ربهم ينسلون","dt":"[51] ونفخ في «القرن» النفخه الثانيه، فترد ارواحهم الى اجسادهم، فاذا هم من قبورهم يخرجون الى ربهم سراعا."},{"id":"3757","s":36,"a":52,"at":"قالوا ياويلنا من بعثنا من مرقدنا هذا ما وعد الرحمن وصدق المرسلون","dt":"[52] قال المكذبون بالبعث نادمين: يا هلاكنا من اخرجنا من قبورنا؟ فيجابون ويقال لهم: هذا ما وعد به الرحمن، واخبر عنه المرسلون الصادقون."},{"id":"3758","s":36,"a":53,"at":"ان كانت الا صيحه واحده فاذا هم جميع لدينا محضرون","dt":"[53] ما كان البعث من القبور الا نتيجه نفخه واحده في «القرن»، فاذا جميع الخلق لدينا ماثلون للحساب والجزاء."},{"id":"3759","s":36,"a":54,"at":"فاليوم لا تظلم نفس شيئا ولا تجزون الا ما كنتم تعملون","dt":"[54] في ذلك اليوم يتم الحساب بالعدل، فلا تظلم نفس شيئا بنقص حسناتها او زياده سيئاتها، ولا تجزون الا بما كنتم تعملونه في الدنيا."},{"id":"3760","s":36,"a":55,"at":"ان اصحاب الجنه اليوم في شغل فاكهون","dt":"[55] ان اهل الجنه في ذلك اليوم مشغولون عن غيرهم بانواع النعيم التي يتفكهون بها."},{"id":"3761","s":36,"a":56,"at":"هم وازواجهم في ظلال على الارائك متكئون","dt":"[56] هم وازواجهم متنعمون بالجلوس على الاسره المزينه، تحت الظلال الوارفه."},{"id":"3762","s":36,"a":57,"at":"لهم فيها فاكهه ولهم ما يدعون","dt":"[57] لهم في الجنه انواع الفواكه اللذيذه، ولهم كل ما يطلبون من انواع النعيم."},{"id":"3763","s":36,"a":58,"at":"سلام قولا من رب رحيم","dt":"[58] ولهم نعيم اخر اكبر حين يكلمهم ربهم، الرحيم بهم بالسلام عليهم. وعند ذلك تحصل لهم السلامه التامه من جميع الوجوه."},{"id":"3764","s":36,"a":59,"at":"وامتازوا اليوم ايها المجرمون","dt":"[59] ويقال للكفار في ذلك اليوم : تميزوا عن المؤمنين، وانفصلوا عنهم."},{"id":"3765","s":36,"a":60,"at":"الم اعهد اليكم يابني ادم ان لا تعبدوا الشيطان انه لكم عدو مبين","dt":"[60] ويقول الله لهم -توبيخا وتذكيرا-: الم اوصكم على السنه رسلي ان لا تعبدوا الشيطان ولا تطيعوه؟ انه لكم عدو ظاهر العداوه."},{"id":"3766","s":36,"a":61,"at":"وان اعبدوني هذا صراط مستقيم","dt":"[61] وامرتكم بعبادتي وحدي، فعبادتي وطاعتي ومعصيه الشيطان هي الدين القويم الموصل لمرضاتي وجناتي."},{"id":"3767","s":36,"a":62,"at":"ولقد اضل منكم جبلا كثيرا افلم تكونوا تعقلون","dt":"[62] ولقد اضل الشيطان عن الحق منكم خلقا كثيرا، افما كان لكم عقل -ايها المشركون- ينهاكم عن اتباعه؟"},{"id":"3768","s":36,"a":63,"at":"هذه جهنم التي كنتم توعدون","dt":"[63] هذه جهنم التي كنتم توعدون بها في الدنيا على كفركم بالله وتكذيبكم رسله."},{"id":"3769","s":36,"a":64,"at":"اصلوها اليوم بما كنتم تكفرون","dt":"[64] ادخلوها اليوم وقاسوا حرها؛ بسبب كفركم."},{"id":"3770","s":36,"a":65,"at":"اليوم نختم على افواههم وتكلمنا ايديهم وتشهد ارجلهم بما كانوا يكسبون","dt":"[65] اليوم نطبع على افواه المشركين فلا ينطقون، وتكلمنا ايديهم بما بطشت به، وتشهد ارجلهم بما سعت اليه في الدنيا، وكسبت من الاثام."},{"id":"3771","s":36,"a":66,"at":"ولو نشاء لطمسنا على اعينهم فاستبقوا الصراط فانى يبصرون","dt":"[66] ولو نشاء لطمسنا على اعينهم بان نذهب ابصارهم، كما ختمنا على افواههم، فبادروا الى الصراط ليجوزوه، فكيف يتحقق لهم ذلك وقد طمست ابصارهم؟"},{"id":"3772","s":36,"a":67,"at":"ولو نشاء لمسخناهم على مكانتهم فما استطاعوا مضيا ولا يرجعون","dt":"[67] ولو شئنا لغيرنا خلقهم واقعدناهم في اماكنهم، فلا يستطيعون ان يمضوا امامهم، ولا يرجعوا وراءهم."},{"id":"3773","s":36,"a":68,"at":"ومن نعمره ننكسه في الخلق افلا يعقلون","dt":"[68] ومن نطل عمره حتى يهرم نعده الى الحاله التي ابتدا منها حاله ضعف العقل وضعف الجسد، افلا يعقلون ان من فعل مثل هذا بهم قادر على بعثهم؟"},{"id":"3774","s":36,"a":69,"at":"وما علمناه الشعر وما ينبغي له ان هو الا ذكر وقران مبين","dt":"[69] وما علمنا رسولنا محمدا الشعر، وما ينبغي له ان يكون شاعرا، ما هذا الذي جاء به الا ذكر يتذكر به اولو الالباب، وقران بين الدلاله على الحق والباطل، واضحه احكامه وحكمه ومواعظه؛"},{"id":"3775","s":36,"a":70,"at":"لينذر من كان حيا ويحق القول على الكافرين","dt":"[70] لينذر من كان حي القلب مستنير البصيره، ويحق العذاب على الكافرين بالله؛ لانهم قامت عليهم بالقران حجه الله البالغه."},{"id":"3776","s":36,"a":71,"at":"او لم يروا انا خلقنا لهم مما عملت ايدينا انعاما فهم لها مالكون","dt":"[71] اولم ير الخلق انا خلقنا لاجلهم انعاما ذللناها لهم، فهم مالكون امرها؟"},{"id":"3777","s":36,"a":72,"at":"وذللناها لهم فمنها ركوبهم ومنها ياكلون","dt":"[72] وسخرناها لهم، فمنها ما يركبون في الاسفار، ويحملون عليها الاثقال، ومنها ما ياكلون."},{"id":"3778","s":36,"a":73,"at":"ولهم فيها منافع ومشارب افلا يشكرون","dt":"[73] ولهم فيها منافع اخرى ينتفعون بها، كالانتفاع باصوافها واوبارها واشعارها اثاثا ولباسا، وغير ذلك، ويشربون البانها، افلا يشكرون الله الذي انعم عليهم بهذه النعم، ويخلصون له العباده؟"},{"id":"3779","s":36,"a":74,"at":"واتخذوا من دون الله الهه لعلهم ينصرون","dt":"[74] واتخذ المشركون من دون الله الهه يعبدونها؛ طمعا في نصرها لهم وانقاذهم من عذاب الله."},{"id":"3780","s":36,"a":75,"at":"لا يستطيعون نصرهم وهم لهم جند محضرون","dt":"[75] لا تستطيع تلك الالهه نصر عابديها ولا انفسهم ينصرون، والمشركون والهتهم جميعا محضرون في العذاب، متبرئ بعضهم من بعض."},{"id":"3781","s":36,"a":76,"at":"فلا يحزنك قولهم انا نعلم ما يسرون وما يعلنون","dt":"[76] فلا يحزنك -ايها الرسول- كفرهم بالله وتكذيبهم لك واستهزاؤهم بك؛ انا نعلم ما يخفون وما يظهرون، وسنجازيهم على ذلك."},{"id":"3782","s":36,"a":77,"at":"او لم ير الانسان انا خلقناه من نطفه فاذا هو خصيم مبين","dt":"[77] اولم ير الانسان المنكر للبعث ابتداء خلقه فيستدل به على معاده، انا خلقناه من نطفه مرت باطوار حتى كبر، فاذا هو كثير الخصام واضح الجدال؟"},{"id":"3783","s":36,"a":78,"at":"وضرب لنا مثلا ونسي خلقه قال من يحيي العظام وهي رميم","dt":"[78] وضرب لنا المنكر للبعث مثلا لا ينبغي ضربه، وهو قياس قدره الخالق بقدره المخلوق، ونسي ابتداء خلقه، قال: من يحيي العظام الباليه المتفتته؟"},{"id":"3784","s":36,"a":79,"at":"قل يحييها الذي انشاها اول مره وهو بكل خلق عليم","dt":"[79] قل له: يحييها الذي خلقها اول مره، وهو بجميع خلقه عليم، لا يخفى عليه شيء."},{"id":"3785","s":36,"a":80,"at":"الذي جعل لكم من الشجر الاخضر نارا فاذا انتم منه توقدون","dt":"[80] الذي اخرج لكم من الشجر الاخضر الرطب نارا محرقه، فاذا انتم من الشجر توقدون النار، فهو القادر على اخراج الضد من الضد. وفي ذلك دليل على وحدانيه الله وكمال قدرته، ومن ذلك اخراج الموتى من قبورهم احياء."},{"id":"3786","s":36,"a":81,"at":"او ليس الذي خلق السموات والارض بقادر على ان يخلق مثلهم بلى وهو الخلاق العليم","dt":"[81] اوليس الذي خلق السموات والارض وما فيهما بقادر على ان يخلق مثلهم، فيعيدهم كما بداهم؟ بلى، انه قادر على ذلك، وهو الخلاق لجميع المخلوقات، العليم بكل ما خلق ويخلق، لا يخفى عليه شيء."},{"id":"3787","s":36,"a":82,"at":"انما امره اذا اراد شيئا ان يقول له كن فيكون","dt":"[82] انما امره سبحانه وتعالى اذا اراد شيئا ان يقول له: «كن» فيكون، ومن ذلك الاماته والاحياء، والبعث والنشور."},{"id":"3788","s":36,"a":83,"at":"فسبحان الذي بيده ملكوت كل شيء واليه ترجعون","dt":"[83] فتنزه الله تعالى وتقدس عن العجز والشرك، فهو المالك لكل شيء، المتصرف في شؤون خلقه بلا منازع او ممانع، وقد ظهرت دلائل قدرته، وتمام نعمته، واليه ترجعون للحساب والجزاء."},{"id":"3789","s":37,"a":1,"at":"والصافات صفا","dt":"[1] اقسم الله تعالى بالملائكه تصف في عبادتها صفوفا متراصه،"},{"id":"3790","s":37,"a":2,"at":"فالزاجرات زجرا","dt":"[2] وبالملائكه تزجر السحاب وتسوقه بامر الله،"},{"id":"3791","s":37,"a":3,"at":"فالتاليات ذكرا","dt":"[3] وبالملائكه تتلو ذكر الله وكلامه تعالى."},{"id":"3792","s":37,"a":4,"at":"ان الهكم لواحد","dt":"[4] ان معبودكم -ايها الناس- لواحد لا شريك له، فاخلصوا له العباده والطاعه. ويقسم الله بما شاء من خلقه، اما المخلوق فلا يجوز له القسم الا بالله، فالحلف بغير الله شرك."},{"id":"3793","s":37,"a":5,"at":"رب السموات والارض وما بينهما ورب المشارق","dt":"[5] هو خالق السموات والارض وما بينهما، ومدبر الشمس في مطالعها ومغاربها."},{"id":"3794","s":37,"a":6,"at":"انا زينا السماء الدنيا بزينه الكواكب","dt":"[6] انا زينا السماء الدنيا بزينه هي النجوم."},{"id":"3795","s":37,"a":7,"at":"وحفظا من كل شيطان مارد","dt":"[7] وحفظنا السماء بالنجوم من كل شيطان متمرد عات رجيم."},{"id":"3796","s":37,"a":8,"at":"لا يسمعون الى الملا الاعلى ويقذفون من كل جانب","dt":"[8] لا تستطيع الشياطين ان تصل الى الملا الاعلى، وهي السموات ومن فيها من الملائكه، فتستمع اليهم اذا تكلموا بما يوحيه الله تعالى من شرعه وقدره، ويرجمون بالشهب من كل جهه؛"},{"id":"3797","s":37,"a":9,"at":"دحورا ولهم عذاب واصب","dt":"[9] طردا لهم عن الاستماع، ولهم في الدار الاخره عذاب دائم موجع."},{"id":"3798","s":37,"a":10,"at":"الا من خطف الخطفه فاتبعه شهاب ثاقب","dt":"[10] الا من اختطف من الشياطين الخطفه، وهي الكلمه يسمعها من السماء بسرعه، فيلقيها الى الذي تحته، ويلقيها الاخر الى الذي تحته، فربما ادركه الشهاب المضيء قبل ان يلقيها، وربما القاها بقدر الله تعالى قبل ان ياتيه الشهاب، فيحرقه فيذهب بها الاخر الى الكهنه، فيكذبوا معها مائه كذبه."},{"id":"3799","s":37,"a":11,"at":"فاستفتهم اهم اشد خلقا ام من خلقنا انا خلقناهم من طين لازب","dt":"[11] فاسال -ايها الرسول- منكري البعث اهم اشد خلقا ام من خلقنا من هذه المخلوقات؟ انا خلقنا اباهم ادم من طين لزج، يلتصق بعضه ببعض."},{"id":"3800","s":37,"a":12,"at":"بل عجبت ويسخرون","dt":"[12] بل عجبت -ايها الرسول- من تكذيبهم وانكارهم البعث، واعجب من انكارهم وابلغ انهم يستهزئون بك، ويسخرون من قولك."},{"id":"3801","s":37,"a":13,"at":"واذا ذكروا لا يذكرون","dt":"[13] واذا ذكروا بما نسوه او غفلوا عنه لا ينتفعون بهذا الذكر ولا يتدبرون."},{"id":"3802","s":37,"a":14,"at":"واذا راوا ايه يستسخرون","dt":"[14] واذا راوا معجزه داله على نبوتك يسخرون منها ويعجبون."},{"id":"3803","s":37,"a":15,"at":"وقالوا ان هذا الا سحر مبين","dt":"[15] وقالوا: ما هذا الذي جئت به الا سحر ظاهر بين."},{"id":"3804","s":37,"a":16,"at":"ائذا متنا وكنا ترابا وعظاما ائنا لمبعوثون","dt":"[16] ااذا متنا وصرنا ترابا وعظاما باليه اانا لمبعوثون من قبورنا احياء،"},{"id":"3805","s":37,"a":17,"at":"او اباؤنا الاولون","dt":"[17] او يبعث اباؤنا الذين مضوا من قبلنا؟"},{"id":"3806","s":37,"a":18,"at":"قل نعم وانتم داخرون","dt":"[18] قل لهم -ايها الرسول-: نعم سوف تبعثون، وانتم اذلاء صاغرون."},{"id":"3807","s":37,"a":19,"at":"فانما هي زجره واحده فاذا هم ينظرون","dt":"[19] فانما هي نفخه واحده، فاذا هم قائمون من قبورهم ينظرون اهوال يوم القيامه."},{"id":"3808","s":37,"a":20,"at":"وقالوا ياويلنا هذا يوم الدين","dt":"[20] وقالوا: يا هلاكنا هذا يوم الحساب والجزاء."},{"id":"3809","s":37,"a":21,"at":"هذا يوم الفصل الذي كنتم به تكذبون","dt":"[21] فيقال لهم: هذا يوم القضاء بين الخلق بالعدل الذي كنتم تكذبون به في الدنيا وتنكرونه."},{"id":"3810","s":37,"a":22,"at":"احشروا الذين ظلموا وازواجهم وما كانوا يعبدون","dt":"[22] ويقال للملائكه: اجمعوا الذين كفروا بالله ونظراءهم، والهتهم التي كانوا يعبدونها"},{"id":"3811","s":37,"a":23,"at":"من دون الله فاهدوهم الى صراط الجحيم","dt":"[23] من دون الله، فسوقوهم سوقا عنيفا الى جهنم"},{"id":"3812","s":37,"a":24,"at":"وقفوهم انهم مسئولون","dt":"[24] واحبسوهم قبل ان يصلوا الى جهنم؛ انهم مسؤولون عن اعمالهم واقوالهم التي صدرت عنهم في الدنيا، مساءله انكار عليهم وتبكيت لهم."},{"id":"3813","s":37,"a":25,"at":"ما لكم لا تناصرون","dt":"[25] ويقال لهم توبيخا: ما لكم لا ينصر بعضكم بعضا؟"},{"id":"3814","s":37,"a":26,"at":"بل هم اليوم مستسلمون","dt":"[26] بل هم اليوم منقادون لامر الله، لا يخالفونه ولا يحيدون عنه، غير منتصرين لانفسهم."},{"id":"3815","s":37,"a":27,"at":"واقبل بعضهم على بعض يتساءلون","dt":"[27] واقبل بعض الكفار على بعض يتلاومون ويتخاصمون."},{"id":"3816","s":37,"a":28,"at":"قالوا انكم كنتم تاتوننا عن اليمين","dt":"[28] قال الاتباع للمتبوعين: انكم كنتم تاتوننا من قبل الدين والحق، فتهونون علينا امر الشريعه، وتنفروننا عنها، وتزينون لنا الضلال."},{"id":"3817","s":37,"a":29,"at":"قالوا بل لم تكونوا مؤمنين","dt":"[29] وقال المتبوعون للتابعين: ما الامر كما تزعمون، بل كانت قلوبكم منكره للايمان، قابله للكفر والعصيان."},{"id":"3818","s":37,"a":30,"at":"وما كان لنا عليكم من سلطان بل كنتم قوما طاغين","dt":"[30] وما كان لنا عليكم من حجه او قوه، فنصدكم بها عن الايمان، بل كنتم -ايها المشركون- قوما طاغين متجاوزين للحق."},{"id":"3819","s":37,"a":31,"at":"فحق علينا قول ربنا انا لذائقون","dt":"[31] فلزمنا جميعا وعيد ربنا، انا لذائقو العذاب، نحن وانتم، بما قدمنا من ذنوبنا ومعاصينا في الدنيا."},{"id":"3820","s":37,"a":32,"at":"فاغويناكم انا كنا غاوين","dt":"[32] فاضللناكم عن سبيل الله والايمان به، انا كنا ضالين من قبلكم، فهلكنا؛ بسبب كفرنا، واهلكناكم معنا."},{"id":"3821","s":37,"a":33,"at":"فانهم يومئذ في العذاب مشتركون","dt":"[33] فان الاتباع والمتبوعين مشتركون يوم القيامه في العذاب، كما اشتركوا في الدنيا في معصيه الله."},{"id":"3822","s":37,"a":34,"at":"انا كذلك نفعل بالمجرمين","dt":"[34] انا هكذا نفعل بالذين اختاروا معاصي الله في الدنيا على طاعته، فنذيقهم العذاب الاليم."},{"id":"3823","s":37,"a":35,"at":"انهم كانوا اذا قيل لهم لا اله الا الله يستكبرون","dt":"[35] ان اولئك المشركين كانوا في الدنيا اذا قيل لهم: لا اله الا الله، ودعوا اليها، وامروا بترك ما ينافيها، يستكبرون عنها وعلى من جاء بها."},{"id":"3824","s":37,"a":36,"at":"ويقولون ائنا لتاركوا الهتنا لشاعر مجنون","dt":"[36] ويقولون: انترك عباده الهتنا لقول رجل شاعر مجنون؟ يعنون رسول الله -صلى الله عليه وسلم-."},{"id":"3825","s":37,"a":37,"at":"بل جاء بالحق وصدق المرسلين","dt":"[37] كذبوا، ما محمد كما وصفوه به، بل جاء بالقران والتوحيد، وصدق المرسلين فيما اخبروا به عنه من شرع الله وتوحيده."},{"id":"3826","s":37,"a":38,"at":"انكم لذائقوا العذاب الاليم","dt":"[38] انكم -ايها المشركون- بقولكم وكفركم وتكذيبكم لذائقو العذاب الاليم الموجع."},{"id":"3827","s":37,"a":39,"at":"وما تجزون الا ما كنتم تعملون","dt":"[39] وما تجزون في الاخره الا بما كنتم تعملونه في الدنيا من المعاصي."},{"id":"3828","s":37,"a":40,"at":"الا عباد الله المخلصين","dt":"[40] الا عباد الله تعالى الذين اخلصوا له في عبادته، فاخلصهم واختصهم برحمته؛ فانهم ناجون من العذاب الاليم."},{"id":"3829","s":37,"a":41,"at":"اولئك لهم رزق معلوم","dt":"[41] . اولئك المخلصون لهم في الجنه رزق معلوم لا ينقطع."},{"id":"3830","s":37,"a":42,"at":"فواكه وهم مكرمون","dt":"[42] . ذلك الرزق فواكه متنوعه، وهم مكرمون بكرامه الله لهم"},{"id":"3831","s":37,"a":43,"at":"في جنات النعيم","dt":"[43] في جنات النعيم الدائم."},{"id":"3832","s":37,"a":44,"at":"على سرر متقابلين","dt":"[44] ومن كرامتهم عند ربهم واكرام بعضهم بعضا انهم على سرر متقابلين فيما بينهم."},{"id":"3833","s":37,"a":45,"at":"يطاف عليهم بكاس من معين","dt":"[45] يدار عليهم في مجالسهم بكؤوس خمر، من انهار جاريه، لا يخافون انقطاعها،"},{"id":"3834","s":37,"a":46,"at":"بيضاء لذه للشاربين","dt":"[46] بيضاء في لونها، لذيذه في شربها،"},{"id":"3835","s":37,"a":47,"at":"لا فيها غول ولا هم عنها ينزفون","dt":"[47] ليس فيها اذى للجسم ولا للعقل."},{"id":"3836","s":37,"a":48,"at":"وعندهم قاصرات الطرف عين","dt":"[48] وعندهم في مجالسهم نساء عفيفات، لا ينظرن الى غير ازواجهن، حسان الاعين،"},{"id":"3837","s":37,"a":49,"at":"كانهن بيض مكنون","dt":"[49] كانهن بيض مصون لم تمسه الايدي."},{"id":"3838","s":37,"a":50,"at":"فاقبل بعضهم على بعض يتساءلون","dt":"[50] فاقبل بعضهم على بعض يتساءلون عن احوالهم في الدنيا وما كانوا يعانون فيها، وما انعم الله به عليهم في الجنه، وهذا من تمام الانس."},{"id":"3839","s":37,"a":51,"at":"قال قائل منهم اني كان لي قرين","dt":"[51] قال قائل من اهل الجنه: لقد كان لي في الدنيا صاحب ملازم لي."},{"id":"3840","s":37,"a":52,"at":"يقول ائنك لمن المصدقين","dt":"[52] يقول: كيف تصدق بالبعث الذي هو في غايه الاستغراب؟"},{"id":"3841","s":37,"a":53,"at":"ائذا متنا وكنا ترابا وعظاما ائنا لمدينون","dt":"[53] ااذا متنا وتمزقنا وصرنا ترابا وعظاما، نبعث ونحاسب ونجازى باعمالنا؟"},{"id":"3842","s":37,"a":54,"at":"قال هل انتم مطلعون","dt":"[54] قال هذا المؤمن الذي ادخل الجنه لاصحابه: هل انتم مطلعون لنرى مصير ذلك القرين؟"},{"id":"3843","s":37,"a":55,"at":"فاطلع فراه في سواء الجحيم","dt":"[55] فاطلع فراى قرينه في وسط النار."},{"id":"3844","s":37,"a":56,"at":"قال تالله ان كدت لتردين","dt":"[56] قال المؤمن لقرينه المنكر للبعث: لقد قاربت ان تهلكني بصدك اياي عن الايمان لو اطعتك."},{"id":"3845","s":37,"a":57,"at":"ولولا نعمه ربي لكنت من المحضرين","dt":"[57] ولولا فضل ربي بهدايتي الى الايمان وتثبيتي عليه، لكنت من المحضرين في العذاب معك."},{"id":"3846","s":37,"a":58,"at":"افما نحن بميتين","dt":"[58] احقا اننا مخلدون منعمون، فما نحن بميتين"},{"id":"3847","s":37,"a":59,"at":"الا موتتنا الاولى وما نحن بمعذبين","dt":"[59] الا موتتنا الاولى في الدنيا، وما نحن بمعذبين بعد دخولنا الجنه؟"},{"id":"3848","s":37,"a":60,"at":"ان هذا لهو الفوز العظيم","dt":"[60] ان ما نحن فيه من نعيم لهو الظفر العظيم."},{"id":"3849","s":37,"a":61,"at":"لمثل هذا فليعمل العاملون","dt":"[61] لمثل هذا النعيم الكامل، والخلود الدائم، والفوز العظيم، فليعمل العاملون في الدنيا؛ ليصيروا اليه في الاخره."},{"id":"3850","s":37,"a":62,"at":"اذلك خير نزلا ام شجره الزقوم","dt":"[62] اذلك الذي سبق وصفه من نعيم الجنه خير ضيافه وعطاء من الله، ام شجره الزقوم الخبيثه الملعونه، طعام اهل النار؟"},{"id":"3851","s":37,"a":63,"at":"انا جعلناها فتنه للظالمين","dt":"[63] انا جعلناها فتنه افتتن بها الظالمون لانفسهم بالكفر والمعاصي، وقالوا مستنكرين: ان صاحبكم ينبئكم ان في النار شجره، والنار تاكل الشجر."},{"id":"3852","s":37,"a":64,"at":"انها شجره تخرج في اصل الجحيم","dt":"[64] انها شجره تنبت في قعر جهنم،"},{"id":"3853","s":37,"a":65,"at":"طلعها كانه رءوس الشياطين","dt":"[65] ثمرها قبيح المنظر كانه رؤوس الشياطين، فاذا كانت كذلك فلا تسال بعد هذا عن طعمها،"},{"id":"3854","s":37,"a":66,"at":"فانهم لاكلون منها فمالئون منها البطون","dt":"[66] فان المشركين لاكلون من تلك الشجره فمالئون منها بطونهم."},{"id":"3855","s":37,"a":67,"at":"ثم ان لهم عليها لشوبا من حميم","dt":"[67] . ثم انهم بعد الاكل منها لشاربون شرابا خليطا قبيحا حارا"},{"id":"3856","s":37,"a":68,"at":"ثم ان مرجعهم لالى الجحيم","dt":"[68] ثم ان مردهم بعد هذا العذاب الى عذاب النار."},{"id":"3857","s":37,"a":69,"at":"انهم الفوا اباءهم ضالين","dt":"[69] انهم وجدوا اباءهم على الشرك والضلال،"},{"id":"3858","s":37,"a":70,"at":"فهم على اثارهم يهرعون","dt":"[70] فسارعوا الى متابعتهم على ذلك."},{"id":"3859","s":37,"a":71,"at":"ولقد ضل قبلهم اكثر الاولين","dt":"[71] ولقد ضل عن الحق قبل قومك -ايها الرسول- اكثر الامم السابقه."},{"id":"3860","s":37,"a":72,"at":"ولقد ارسلنا فيهم منذرين","dt":"[72] ولقد ارسلنا في تلك الامم مرسلين انذروهم بالعذاب فكفروا."},{"id":"3861","s":37,"a":73,"at":"فانظر كيف كان عاقبه المنذرين","dt":"[73] فتامل كيف كانت نهايه تلك الامم التي انذرت، فكفرت؟ فقد عذبت، وصارت للناس عبره."},{"id":"3862","s":37,"a":74,"at":"الا عباد الله المخلصين","dt":"[74] الا عباد الله الذين اخلصهم الله، وخصهم برحمته لاخلاصهم له."},{"id":"3863","s":37,"a":75,"at":"ولقد نادانا نوح فلنعم المجيبون","dt":"[75] ولقد نادانا نبينا نوح؛ لننصره على قومه، فلنعم المجيبون له نحن."},{"id":"3864","s":37,"a":76,"at":"ونجيناه واهله من الكرب العظيم","dt":"[76] ونجيناه واهله والمؤمنين معه من اذى المشركين، ومن الغرق بالطوفان العظيم."},{"id":"3865","s":37,"a":77,"at":"وجعلنا ذريته هم الباقين","dt":"[77] وجعلنا ذريه نوح هم الباقين بعد غرق قومه."},{"id":"3866","s":37,"a":78,"at":"وتركنا عليه في الاخرين","dt":"[78] وابقينا له ذكرا جميلا وثناء حسنا فيمن جاء بعده من الناس يذكرونه به."},{"id":"3867","s":37,"a":79,"at":"سلام على نوح في العالمين","dt":"[79] امان لنوح وسلامه له من ان يذكر بسوء في الاخرين، بل تثني عليه الاجيال من بعده."},{"id":"3868","s":37,"a":80,"at":"انا كذلك نجزي المحسنين","dt":"[80] مثل جزاء نوح نجزي كل من احسن من العباد في طاعه الله."},{"id":"3869","s":37,"a":81,"at":"انه من عبادنا المؤمنين","dt":"[81] ان نوحا من عبادنا المصدقين المخلصين العاملين باوامر الله."},{"id":"3870","s":37,"a":82,"at":"ثم اغرقنا الاخرين","dt":"[82] ثم اغرقنا الاخرين المكذبين من قومه بالطوفان، فلم تبق منهم عين تطرف."},{"id":"3871","s":37,"a":83,"at":"وان من شيعته لابراهيم","dt":"[83] وان من اشياع نوح على منهاجه وملته نبي الله ابراهيم،"},{"id":"3872","s":37,"a":84,"at":"اذ جاء ربه بقلب سليم","dt":"[84] حين جاء ربه بقلب بريء من كل اعتقاد باطل وخلق ذميم،"},{"id":"3873","s":37,"a":85,"at":"اذ قال لابيه وقومه ماذا تعبدون","dt":"[85] حين قال لابيه وقومه منكرا عليهم: ما الذي تعبدونه من دون الله؟"},{"id":"3874","s":37,"a":86,"at":"ائفكا الهه دون الله تريدون","dt":"[86] اتريدون الهه مختلقه تعبدونها، وتتركون عباده الله المستحق للعباده وحده؟"},{"id":"3875","s":37,"a":87,"at":"فما ظنكم برب العالمين","dt":"[87] فما ظنكم برب العالمين انه فاعل بكم اذا اشركتم به وعبدتم معه غيره؟"},{"id":"3876","s":37,"a":88,"at":"فنظر نظره في النجوم","dt":"[88] فنظر ابراهيم نظره في النجوم -على عاده قومه في ذلك- متفكرا فيما يعتذر به عن الخروج معهم الى اعيادهم،"},{"id":"3877","s":37,"a":89,"at":"فقال اني سقيم","dt":"[89] فقال لهم: اني مريض. وهذا تعريض منه،"},{"id":"3878","s":37,"a":90,"at":"فتولوا عنه مدبرين","dt":"[90] فتركوه وراء ظهورهم."},{"id":"3879","s":37,"a":91,"at":"فراغ الى الهتهم فقال الا تاكلون","dt":"[91] فمال مسرعا الى اصنام قومه فقال مستهزئا بها: الا تاكلون هذا الطعام الذي يقدمه لكم سدنتكم؟"},{"id":"3880","s":37,"a":92,"at":"ما لكم لا تنطقون","dt":"[92] ما لكم لا تنطقون ولا تجيبون من يسالكم؟"},{"id":"3881","s":37,"a":93,"at":"فراغ عليهم ضربا باليمين","dt":"[93] فاقبل على الهتهم يضربها ويكسرها بيده اليمنى؛ ليثبت لقومه خطا عبادتهم لها."},{"id":"3882","s":37,"a":94,"at":"فاقبلوا اليه يزفون","dt":"[94] فاقبلوا اليه يعدون مسرعين غاضبين."},{"id":"3883","s":37,"a":95,"at":"قال اتعبدون ما تنحتون","dt":"[95] فلقيهم ابراهيم بثبات قائلا: كيف تعبدون اصناما تنحتونها انتم، وتصنعونها بايديكم،"},{"id":"3884","s":37,"a":96,"at":"والله خلقكم وما تعملون","dt":"[96] وتتركون عباده ربكم الذي خلقكم، وخلق عملكم؟"},{"id":"3885","s":37,"a":97,"at":"قالوا ابنوا له بنيانا فالقوه في الجحيم","dt":"[97] فلما قامت عليهم الحجه لجؤوا الى القوه، وقالوا: ابنوا له بنيانا، واملؤوه حطبا، ثم القوه فيه."},{"id":"3886","s":37,"a":98,"at":"فارادوا به كيدا فجعلناهم الاسفلين","dt":"[98] فاراد قوم ابراهيم به كيدا لاهلاكه، فجعلناهم المقهورين المغلوبين، ورد الله كيدهم في نحورهم، وجعل النار على ابراهيم بردا وسلاما."},{"id":"3887","s":37,"a":99,"at":"وقال اني ذاهب الى ربي سيهدين","dt":"[99] وقال ابراهيم: اني مهاجر الى ربي من بلد قومي الى حيث اتمكن من عباده ربي؛ فانه سيدلني على الخير في ديني ودنياي."},{"id":"3888","s":37,"a":100,"at":"رب هب لي من الصالحين","dt":"[100] رب اعطني ولدا صالحا."},{"id":"3889","s":37,"a":101,"at":"فبشرناه بغلام حليم","dt":"[101] فاجبنا له دعوته، وبشرناه بغلام حليم، اي: يكون حليما في كبره، وهو اسماعيل."},{"id":"3890","s":37,"a":102,"at":"فلما بلغ معه السعي قال يابني اني ارى في المنام اني اذبحك فانظر ماذا ترى قال ياابت افعل ما تؤمر ستجدني ان شاء الله من الصابرين","dt":"[102] فلما كبر اسماعيل ومشى مع ابيه قال له ابوه: اني ارى في المنام اني اذبحك، فما رايك؟ (ورؤيا الانبياء حق) فقال اسماعيل مرضيا ربه، بارا بوالده، معينا له على طاعه الله: امض ما امرك الله به من ذبحي، ستجدني -ان شاء الله- صابرا طائعا محتسبا."},{"id":"3891","s":37,"a":103,"at":"فلما اسلما وتله للجبين","dt":"[103] فلما استسلما لامر الله وانقادا له، والقى ابراهيم ابنه على جبينه -وهو جانب الجبهه- على الارض؛ ليذبحه."},{"id":"3892","s":37,"a":104,"at":"وناديناه ان ياابراهيم","dt":"[104] ونادينا ابراهيم في تلك الحاله العصيبه: ان يا ابراهيم،"},{"id":"3893","s":37,"a":105,"at":"قد صدقت الرؤيا انا كذلك نجزي المحسنين","dt":"[105] قد فعلت ما امرت به وصدقت رؤياك، انا كما جزيناك على تصديقك نجزي الذين احسنوا مثلك، فنخلصهم من الشدائد في الدنيا والاخره."},{"id":"3894","s":37,"a":106,"at":"ان هذا لهو البلاء المبين","dt":"[106] ان الامر بذبح ابنك هو الابتلاء الشاق الذي ابان عن صدق ايمانك."},{"id":"3895","s":37,"a":107,"at":"وفديناه بذبح عظيم","dt":"[107] واستنقذنا اسماعيل، فجعلنا بديلا عنه كبشا عظيما."},{"id":"3896","s":37,"a":108,"at":"وتركنا عليه في الاخرين","dt":"[108] وابقينا لابراهيم ثناء حسنا في الامم بعده."},{"id":"3897","s":37,"a":109,"at":"سلام على ابراهيم","dt":"[109] تحيه لابراهيم من عند الله، ودعاء له بالسلامه من كل افه."},{"id":"3898","s":37,"a":110,"at":"كذلك نجزي المحسنين","dt":"[110] كما جزينا ابراهيم على طاعته لنا وامتثاله امرنا، نجزي المحسنين من عبادنا."},{"id":"3899","s":37,"a":111,"at":"انه من عبادنا المؤمنين","dt":"[111] انه من عبادنا المؤمنين الذين اعطوا العبوديه حقها."},{"id":"3900","s":37,"a":112,"at":"وبشرناه باسحاق نبيا من الصالحين","dt":"[112] وبشرنا ابراهيم بولده اسحاق نبيا من الصالحين؛ جزاء له على صبره ورضاه بامر ربه، وطاعته له."},{"id":"3901","s":37,"a":113,"at":"وباركنا عليه وعلى اسحاق ومن ذريتهما محسن وظالم لنفسه مبين","dt":"[113] وانزلنا عليهما البركه. ومن ذريتهما من هو مطيع لربه، محسن لنفسه، ومن هو ظالم لها ظلما بينا بكفره ومعصيته."},{"id":"3902","s":37,"a":114,"at":"ولقد مننا على موسى وهارون","dt":"[114] ولقد مننا على موسى وهارون بالنبوه والرساله،"},{"id":"3903","s":37,"a":115,"at":"ونجيناهما وقومهما من الكرب العظيم","dt":"[115] ونجيناهما وقومهما من الغرق، وما كانوا فيه من عبوديه ومذله."},{"id":"3904","s":37,"a":116,"at":"ونصرناهم فكانوا هم الغالبين","dt":"[116] ونصرناهم، فكانت لهم العزه والنصره والغلبه على فرعون واله."},{"id":"3905","s":37,"a":117,"at":"واتيناهما الكتاب المستبين","dt":"[117] واتيناهما التوراه البينه،"},{"id":"3906","s":37,"a":118,"at":"وهديناهما الصراط المستقيم","dt":"[118] وهديناهما الطريق المستقيم الذي لا اعوجاج فيه، وهو الاسلام دين الله الذي ابتعث به انبياءه،"},{"id":"3907","s":37,"a":119,"at":"وتركنا عليهما في الاخرين","dt":"[119] وابقينا لهما ثناء حسنا وذكرا جميلا فيمن بعدهما."},{"id":"3908","s":37,"a":120,"at":"سلام على موسى وهارون","dt":"[120] تحيه لموسى وهارون من عند الله، وثناء ودعاء لهما بالسلامه من كل افه،"},{"id":"3909","s":37,"a":121,"at":"انا كذلك نجزي المحسنين","dt":"[121] كما جزيناهما الجزاء الحسن نجزي المحسنين من عبادنا المخلصين لنا بالصدق والايمان والعمل."},{"id":"3910","s":37,"a":122,"at":"انهما من عبادنا المؤمنين","dt":"[122] . انهما من عبادنا الراسخين في الايمان."},{"id":"3911","s":37,"a":123,"at":"وان الياس لمن المرسلين","dt":"[123] وان عبدنا الياس لمن الذين اكرمناهم بالنبوه والرساله،"},{"id":"3912","s":37,"a":124,"at":"اذ قال لقومه الا تتقون","dt":"[124] ، اذ قال لقومه من بني اسرائيل: اتقوا الله وحده وخافوه، ولا تشركوا معه غيره،"},{"id":"3913","s":37,"a":125,"at":"اتدعون بعلا وتذرون احسن الخالقين","dt":"[125] كيف تعبدون صنما ضعيفا مخلوقا، وتتركون احسن الخالقين -المتصف باحسن الصفات واكملها، فلا تعبدونه-"},{"id":"3914","s":37,"a":126,"at":"الله ربكم ورب ابائكم الاولين","dt":"[126] الله ربكم الذي خلقكم، وخلق اباءكم الماضين قبلكم؟"},{"id":"3915","s":37,"a":127,"at":"فكذبوه فانهم لمحضرون","dt":"[127] فكذب قوم الياس نبيهم، فليجمعنهم الله يوم القيامه للحساب والعقاب،"},{"id":"3916","s":37,"a":128,"at":"الا عباد الله المخلصين","dt":"[128] الا عباد الله الذين اخلصوا دينهم لله، فانهم ناجون من عذابه."},{"id":"3917","s":37,"a":129,"at":"وتركنا عليه في الاخرين","dt":"[129] وجعلنا لالياس ثناء جميلا في الامم بعده."},{"id":"3918","s":37,"a":130,"at":"سلام على ال ياسين","dt":"[130] تحيه من الله، وثناء على الياس."},{"id":"3919","s":37,"a":131,"at":"انا كذلك نجزي المحسنين","dt":"[131] وكما جزينا الياس الجزاء الحسن على طاعته، نجزي المحسنين من عبادنا المؤمنين"},{"id":"3920","s":37,"a":132,"at":"انه من عبادنا المؤمنين","dt":"[132] انه من عباد الله المؤمنين المخلصين له العاملين باوامره."},{"id":"3921","s":37,"a":133,"at":"وان لوطا لمن المرسلين","dt":"[133] وان عبدنا لوطا اصطفيناه، فجعلناه من المرسلين،"},{"id":"3922","s":37,"a":134,"at":"اذ نجيناه واهله اجمعين","dt":"[134] اذ نجيناه واهله اجمعين من العذاب،"},{"id":"3923","s":37,"a":135,"at":"الا عجوزا في الغابرين","dt":"[135] الا عجوزا هرمه، هي زوجته، هلكت مع الذين هلكوا من قومها لكفرها."},{"id":"3924","s":37,"a":136,"at":"ثم دمرنا الاخرين","dt":"[136] ثم اهلكنا الباقين المكذبين من قومه."},{"id":"3925","s":37,"a":137,"at":"وانكم لتمرون عليهم مصبحين","dt":"[137] وانكم -يا اهل «مكه»- لتمرون في اسفاركم على منازل قوم لوط واثارهم وقت الصباح،"},{"id":"3926","s":37,"a":138,"at":"وبالليل افلا تعقلون","dt":"[138] وتمرون عليها ليلا. افلا تعقلون، فتخافوا ان يصيبكم مثل ما اصابهم؟"},{"id":"3927","s":37,"a":139,"at":"وان يونس لمن المرسلين","dt":"[139] وان عبدنا يونس اصطفيناه وجعلناه من المرسلين،"},{"id":"3928","s":37,"a":140,"at":"اذ ابق الى الفلك المشحون","dt":"[140] اذ هرب من بلده غاضبا على قومه، وركب سفينه مملوءه ركابا وامتعه."},{"id":"3929","s":37,"a":141,"at":"فساهم فكان من المدحضين","dt":"[141] واحاطت بها الامواج العظيمه، فاقترع ركاب السفينه لتخفيف الحموله خوف الغرق، فكان يونس من المغلوبين بالقرعه."},{"id":"3930","s":37,"a":142,"at":"فالتقمه الحوت وهو مليم","dt":"[142] فالقي في البحر، فابتلعه الحوت، ويونس عليه السلام ات بما يلام عليه."},{"id":"3931","s":37,"a":143,"at":"فلولا انه كان من المسبحين","dt":"[143] فلولا ما تقدم له من كثره العباده والعمل الصالح قبل وقوعه في بطن الحوت، وتسبيحه، وهو في بطن الحوت بقوله:لا اله الا انت سبحنك اني كنت من الظلمين؛"},{"id":"3932","s":37,"a":144,"at":"للبث في بطنه الى يوم يبعثون","dt":"[144] لمكث في بطن الحوت، وصار له قبرا الى يوم القيامه."},{"id":"3933","s":37,"a":145,"at":"فنبذناه بالعراء وهو سقيم","dt":"[145] فطرحناه من بطن الحوت، والقيناه في ارض خاليه عاريه من الشجر والبناء، وهو ضعيف البدن."},{"id":"3934","s":37,"a":146,"at":"وانبتنا عليه شجره من يقطين","dt":"[146] وانبتنا عليه شجره من القرع تظله، وينتفع بها."},{"id":"3935","s":37,"a":147,"at":"وارسلناه الى مائه الف او يزيدون","dt":"[147] وارسلناه الى مائه الف من قومه بل يزيدون،"},{"id":"3936","s":37,"a":148,"at":"فامنوا فمتعناهم الى حين","dt":"[148] فصدقوا وعملوا بما جاء به، فمتعناهم بحياتهم الى وقت بلوغ اجالهم."},{"id":"3937","s":37,"a":149,"at":"فاستفتهم الربك البنات ولهم البنون","dt":"[149] فاسال -ايها الرسول- قومك: كيف جعلوا لله البنات اللاتي يكرهونهن، ولانفسهم البنين الذين يريدونهم؟"},{"id":"3938","s":37,"a":150,"at":"ام خلقنا الملائكه اناثا وهم شاهدون","dt":"[150] واسالهم اخلقنا الملائكه اناثا، وهم حاضرون؟"},{"id":"3939","s":37,"a":151,"at":"الا انهم من افكهم ليقولون","dt":"[151] وان من كذبهم قولهم:"},{"id":"3940","s":37,"a":152,"at":"ولد الله وانهم لكاذبون","dt":"[152] ولد الله، وانهم لكاذبون؛ لانهم يقولون ما لا يعلمون."},{"id":"3941","s":37,"a":153,"at":"اصطفى البنات على البنين","dt":"[153] لاي شيء يختار الله البنات دون البنين؟"},{"id":"3942","s":37,"a":154,"at":"ما لكم كيف تحكمون","dt":"[154] بئس الحكم ما تحكمونه -ايها القوم- ان يكون لله البنات ولكم البنون، وانتم لا ترضون البنات لانفسكم."},{"id":"3943","s":37,"a":155,"at":"افلا تذكرون","dt":"[155] افلا تذكرون انه لا يجوز ولا ينبغي ان يكون له ولد؟ تعالى الله عن ذلك علوا كبيرا."},{"id":"3944","s":37,"a":156,"at":"ام لكم سلطان مبين","dt":"[156] بل الكم حجه بينه على قولكم وافترائكم؟"},{"id":"3945","s":37,"a":157,"at":"فاتوا بكتابكم ان كنتم صادقين","dt":"[157] ان كانت لكم حجه في كتاب من عند الله فاتوا بها، ان كنتم صادقين في قولكم؟"},{"id":"3946","s":37,"a":158,"at":"وجعلوا بينه وبين الجنه نسبا ولقد علمت الجنه انهم لمحضرون","dt":"[158] وجعل المشركون بين الله والملائكه قرابه ونسبا، ولقد علمت الملائكه ان المشركين محضرون للعذاب يوم القيامه."},{"id":"3947","s":37,"a":159,"at":"سبحان الله عما يصفون","dt":"[159] تنزه الله عن كل ما لا يليق به مما يصفه به الكافرون."},{"id":"3948","s":37,"a":160,"at":"الا عباد الله المخلصين","dt":"[160] لكن عباد الله الذين اصطفاهم لعبادته لا يصفونه الا بما يليق بجلاله سبحانه."},{"id":"3949","s":37,"a":161,"at":"فانكم وما تعبدون","dt":"[161] فانكم -ايها المشركون بالله- وما تعبدون من دون الله من الهه،"},{"id":"3950","s":37,"a":162,"at":"ما انتم عليه بفاتنين","dt":"[162] ما انتم بمضلين احدا"},{"id":"3951","s":37,"a":163,"at":"الا من هو صال الجحيم","dt":"[163] الا من قدر الله عز وجل عليه ان يصلى الجحيم؛ لكفره وظلمه."},{"id":"3952","s":37,"a":164,"at":"وما منا الا له مقام معلوم","dt":"[164] قالت الملائكه: وما منا احد الا له مقام في السماء معلوم،"},{"id":"3953","s":37,"a":165,"at":"وانا لنحن الصافون","dt":"[165] وانا لنحن الواقفون صفوفا في عباده الله وطاعته،"},{"id":"3954","s":37,"a":166,"at":"وانا لنحن المسبحون","dt":"[166] وانا لنحن المنزهون الله عن كل ما لا يليق به."},{"id":"3955","s":37,"a":167,"at":"وان كانوا ليقولون","dt":"[167] وان كفار «مكه» ليقولون قبل بعثتك -ايها الرسول-"},{"id":"3956","s":37,"a":168,"at":"لو ان عندنا ذكرا من الاولين","dt":"[168] لو جاءنا من الكتب والانبياء ما جاء الاولين قبلنا،"},{"id":"3957","s":37,"a":169,"at":"لكنا عباد الله المخلصين","dt":"[169] لكنا عباد الله الصادقين في الايمان، المخلصين في العباده."},{"id":"3958","s":37,"a":170,"at":"فكفروا به فسوف يعلمون","dt":"[170] فلما جاءهم ذكر الاولين، وعلم الاخرين، واكمل الكتب، وافضل الرسل، وهو محمد -صلى الله عليه وسلم-، كفروا به، فسوف يعلمون ما لهم من العذاب في الاخره."},{"id":"3959","s":37,"a":171,"at":"ولقد سبقت كلمتنا لعبادنا المرسلين","dt":"[171] ولقد سبقت كلمتنا -التي لا مرد لها- لعبادنا المرسلين،"},{"id":"3960","s":37,"a":172,"at":"انهم لهم المنصورون","dt":"[172] ان لهم النصره على اعدائهم بالحجه والقوه،"},{"id":"3961","s":37,"a":173,"at":"وان جندنا لهم الغالبون","dt":"[173] وان جندنا المجاهدين في سبيلنا لهم الغالبون لاعدائهم في كل مقام باعتبار العاقبه والمال."},{"id":"3962","s":37,"a":174,"at":"فتول عنهم حتى حين","dt":"[174] فاعرض -ايها الرسول- عمن عاند، ولم يقبل الحق حتى تنقضي المده التي امهلهم فيها، وياتي امر الله بعذابهم،"},{"id":"3963","s":37,"a":175,"at":"وابصرهم فسوف يبصرون","dt":"[175] وانظرهم وارتقب ماذا يحل بهم من العذاب بمخالفتك؟ فسوف يرون ما يحل بهم من عذاب الله."},{"id":"3964","s":37,"a":176,"at":"افبعذابنا يستعجلون","dt":"[176] افبنزول عذابنا بهم يستعجلونك ايها الرسول؟"},{"id":"3965","s":37,"a":177,"at":"فاذا نزل بساحتهم فساء صباح المنذرين","dt":"[177] فاذا نزل عذابنا بهم، فبئس الصباح صباحهم."},{"id":"3966","s":37,"a":178,"at":"وتول عنهم حتى حين","dt":"[178] واعرض عنهم حتى ياذن الله بعذابهم،"},{"id":"3967","s":37,"a":179,"at":"وابصر فسوف يبصرون","dt":"[179] وانظرهم فسوف يرون ما يحل بهم من العذاب والنكال."},{"id":"3968","s":37,"a":180,"at":"سبحان ربك رب العزه عما يصفون","dt":"[180] تنزه الله وتعالى رب العزه عما يصفه هؤلاء المفترون عليه."},{"id":"3969","s":37,"a":181,"at":"وسلام على المرسلين","dt":"[181] وتحيه الله الدائمه وثناؤه وامانه لجميع المرسلين."},{"id":"3970","s":37,"a":182,"at":"والحمد لله رب العالمين","dt":"[182] والحمد لله رب العالمين في الاولى والاخره، فهو المستحق لذلك وحده لا شريك له."},{"id":"3971","s":38,"a":1,"at":"ص والقران ذي الذكر","dt":"[1] ص سبق الكلام على الحروف المقطعه في البقره.يقسم الله سبحانه بالقران المشتمل على تذكير الناس بما هم عنه غافلون.اول سوره البقره."},{"id":"3972","s":38,"a":2,"at":"بل الذين كفروا في عزه وشقاق","dt":"[2] ولكن الكافرين متكبرون على الحق مخالفون له."},{"id":"3973","s":38,"a":3,"at":"كم اهلكنا من قبلهم من قرن فنادوا ولات حين مناص","dt":"[3] كثيرا من الامم اهلكناها قبل هؤلاء المشركين، فاستغاثوا حين جاءهم العذاب ونادوا بالتوبه، وليس الوقت وقت قبول توبه، ولا وقت فرار وخلاص مما اصابهم."},{"id":"3974","s":38,"a":4,"at":"وعجبوا ان جاءهم منذر منهم وقال الكافرون هذا ساحر كذاب","dt":"[4] وعجب هؤلاء الكفار من بعث الله اليهم بشرا منهم؛ ليدعوهم الى الله ويخوفهم عذابه، وقالوا: انه ليس رسولا بل هو كاذب في قوله، ساحر لقومه،"},{"id":"3975","s":38,"a":5,"at":"اجعل الالهه الها واحدا ان هذا لشيء عجاب","dt":"[5] كيف يصير الالهه الكثيره الها واحدا؟ ان هذا الذي جاء به ودعا اليه لشيء عجيب."},{"id":"3976","s":38,"a":6,"at":"وانطلق الملا منهم ان امشوا واصبروا على الهتكم ان هذا لشيء يراد","dt":"[6] وانطلق رؤساء القوم وكبراؤهم يحرضون قومهم على الاستمرار على الشرك والصبر على تعدد الالهه، ويقولون ان ما جاء به هذا الرسول شيء مدبر يقصد منه الرئاسه والسياده،"},{"id":"3977","s":38,"a":7,"at":"ما سمعنا بهذا في المله الاخره ان هذا الا اختلاق","dt":"[7] ما سمعنا بما يدعو اليه في دين ابائنا من قريش، ولا في النصرانيه، ما هذا الا كذب وافتراء."},{"id":"3978","s":38,"a":8,"at":"اؤنزل عليه الذكر من بيننا بل هم في شك من ذكري بل لما يذوقوا عذاب","dt":"[8] اخص محمد بنزول القران عليه من دوننا؟ بل هم في ريب من وحيي اليك -ايها الرسول- وارسالي لك، بل قالوا ذلك؛ لانهم لم يذوقوا عذاب الله، فلو ذاقوا عذابه لما تجرؤوا على ما قالوا."},{"id":"3979","s":38,"a":9,"at":"ام عندهم خزائن رحمه ربك العزيز الوهاب","dt":"[9] ام هم يملكون خزائن فضل ربك العزيز في سلطانه، الوهاب ما يشاء من رزقه وفضله لمن يشاء من خلقه؟"},{"id":"3980","s":38,"a":10,"at":"ام لهم ملك السموات والارض وما بينهما فليرتقوا في الاسباب","dt":"[10] ام لهؤلاء المشركين ملك السموات والارض وما بينهما، فيعطوا ويمنعوا؟ فلياخذوا بالاسباب الموصله لهم الى السماء، حتى يحكموا بما يريدون من عطاء ومنع."},{"id":"3981","s":38,"a":11,"at":"جند ما هنالك مهزوم من الاحزاب","dt":"[11] هؤلاء الجند المكذبون جند مهزومون، كما هزم غيرهم من الاحزاب قبلهم،"},{"id":"3982","s":38,"a":12,"at":"كذبت قبلهم قوم نوح وعاد وفرعون ذو الاوتاد","dt":"[12] كذبت قبلهم قوم نوح وعاد وفرعون صاحب القوه العظيمه،"},{"id":"3983","s":38,"a":13,"at":"وثمود وقوم لوط واصحاب الايكه اولئك الاحزاب","dt":"[13] وثمود وقوم لوط واصحاب الاشجار والبساتين وهم قوم شعيب. اولئك الامم الذين تحزبوا على الكفر والتكذيب واجتمعوا عليه."},{"id":"3984","s":38,"a":14,"at":"ان كل الا كذب الرسل فحق عقاب","dt":"[14] ان كل من هؤلاء الا كذب الرسل، فاستحقوا عذاب الله، وحل بهم عقابه."},{"id":"3985","s":38,"a":15,"at":"وما ينظر هؤلاء الا صيحه واحده ما لها من فواق","dt":"[15] وما ينتظر هؤلاء المشركون لحلول العذاب عليهم ان بقوا على شركهم، الا نفخه واحده ما لها من رجوع."},{"id":"3986","s":38,"a":16,"at":"وقالوا ربنا عجل لنا قطنا قبل يوم الحساب","dt":"[16] وقالوا: ربنا عجل لنا نصيبنا من العذاب في الدنيا قبل يوم القيامه، وكان هذا استهزاء منهم."},{"id":"3987","s":38,"a":17,"at":"اصبر على ما يقولون واذكر عبدنا داود ذا الايد انه اواب","dt":"[17] اصبر -ايها الرسول- على ما يقولونه مما تكره، واذكر عبدنا داود صاحب القوه على اعداء الله والصبر على طاعته، انه تواب كثير الرجوع الى ما يرضي الله. وفي هذا تسليه للرسول -صلى الله عليه وسلم-."},{"id":"3988","s":38,"a":18,"at":"انا سخرنا الجبال معه يسبحن بالعشي والاشراق","dt":"[18] انا سخرنا الجبال مع داود يسبحن بتسبيحه اول النهار واخره،"},{"id":"3989","s":38,"a":19,"at":"والطير محشوره كل له اواب","dt":"[19] وسخرنا الطير معه مجموعه تسبح، وتطيع تبعا له."},{"id":"3990","s":38,"a":20,"at":"وشددنا ملكه واتيناه الحكمه وفصل الخطاب","dt":"[20] وقوينا له ملكه بالهيبه والقوه والنصر، واتيناه النبوه، والفصل في الكلام والحكم."},{"id":"3991","s":38,"a":21,"at":"وهل اتاك نبا الخصم اذ تسوروا المحراب","dt":"[21] وهل جاءك -ايها الرسول- خبر المتخاصمين اللذين تسورا على داود في مكان عبادته،"},{"id":"3992","s":38,"a":22,"at":"اذ دخلوا على داود ففزع منهم قالوا لا تخف خصمان بغى بعضنا على بعض فاحكم بيننا بالحق ولا تشطط واهدنا الى سواء الصراط","dt":"[22] فارتاع من دخولهما عليه؟ قالوا له: لا تخف، فنحن خصمان ظلم احدنا الاخر، فاقض بيننا بالعدل، ولا تجر علينا في الحكم، وارشدنا الى سواء السبيل."},{"id":"3993","s":38,"a":23,"at":"ان هذا اخي له تسع وتسعون نعجه ولي نعجه واحده فقال اكفلنيها وعزني في الخطاب","dt":"[23] قال احدهما: ان هذا اخي له تسع وتسعون من النعاج، وليس عندي الا نعجه واحده، فطمع فيها، وقال: اعطنيها، وغلبني بحجته."},{"id":"3994","s":38,"a":24,"at":"قال لقد ظلمك بسؤال نعجتك الى نعاجه وان كثيرا من الخلطاء ليبغي بعضهم على بعض الا الذين امنوا وعملوا الصالحات وقليل ما هم وظن داود انما فتناه فاستغفر ربه وخر راكعا واناب","dt":"[24] قال داود: لقد ظلمك اخوك بسؤاله ضم نعجتك الى نعاجه، وان كثيرا من الشركاء ليعتدي بعضهم على بعض، ويظلمه باخذ حقه وعدم انصافه من نفسه الا المؤمنين الصالحين، فلا يبغي بعضهم على بعض، وهم قليل. وايقن داود اننا فتناه بهذه الخصومه، فاستغفر ربه، وسجد تقربا لله، ورجع اليه وتاب."},{"id":"3995","s":38,"a":25,"at":"فغفرنا له ذلك وان له عندنا لزلفى وحسن ماب","dt":"[25] فغفرنا له ذلك، وجعلناه من المقربين عندنا، واعددنا له حسن المصير في الاخره."},{"id":"3996","s":38,"a":26,"at":"ياداود انا جعلناك خليفه في الارض فاحكم بين الناس بالحق ولا تتبع الهوى فيضلك عن سبيل الله ان الذين يضلون عن سبيل الله لهم عذاب شديد بما نسوا يوم الحساب","dt":"[26] يا داود انا استخلفناك في الارض وملكناك فيها، فاحكم بين الناس بالعدل والانصاف، ولا تتبع الهوى في الاحكام، فيضلك ذلك عن دين الله وشرعه، ان الذين يضلون عن سبيل الله لهم عذاب اليم في النار؛ بغفلتهم عن يوم الجزاء والحساب. وفي هذا توصيه لولاه الامر ان يحكموا بالحق المنزل من الله تبارك وتعالى، ولا يعدلوا عنه، فيضلوا عن سبيله."},{"id":"3997","s":38,"a":27,"at":"وما خلقنا السماء والارض وما بينهما باطلا ذلك ظن الذين كفروا فويل للذين كفروا من النار","dt":"[27] وما خلقنا السماء والارض وما بينهما عبثا ولهوا، ذلك ظن الذين كفروا، فويل لهم من النار يوم القيامه؛ لظنهم الباطل، وكفرهم بالله."},{"id":"3998","s":38,"a":28,"at":"ام نجعل الذين امنوا وعملوا الصالحات كالمفسدين في الارض ام نجعل المتقين كالفجار","dt":"[28] انجعل الذين امنوا وعملوا الصالحات كالمفسدين في الارض، ام نجعل اهل التقوى المؤمنين كاصحاب الفجور الكافرين؟ هذه التسويه غير لائقه بحكمه الله وحكمه، فلا يستوون عند الله، بل يثيب الله المؤمنين الاتقياء، ويعاقب المفسدين الاشقياء."},{"id":"3999","s":38,"a":29,"at":"كتاب انزلناه اليك مبارك ليدبروا اياته وليتذكر اولو الالباب","dt":"[29] هذا الموحى به اليك -ايها الرسول- كتاب انزلناه اليك مبارك؛ ليتفكروا في اياته، ويعملوا بهداياته ودلالاته، وليتذكر اصحاب العقول السليمه ما كلفهم الله به."},{"id":"4000","s":38,"a":30,"at":"ووهبنا لداود سليمان نعم العبد انه اواب","dt":"[30] ووهبنا لداود ابنه سليمان، فانعمنا به عليه، واقررنا به عينه، نعم العبد سليمان، انه كان كثير الرجوع الى الله والانابه اليه."},{"id":"4001","s":38,"a":31,"at":"اذ عرض عليه بالعشي الصافنات الجياد","dt":"[31] اذكر حين عرضت عليه عصرا الخيول الاصيله السريعه، تقف على ثلاث قوائم وترفع الرابعه؛ لنجابتها وخفتها، فما زالت تعرض عليه حتى غابت الشمس."},{"id":"4002","s":38,"a":32,"at":"فقال اني احببت حب الخير عن ذكر ربي حتى توارت بالحجاب","dt":"[32] فقال: انني اثرت حب الخيل عن ذكر ربي حتى غابت الشمس عن عينيه،"},{"id":"4003","s":38,"a":33,"at":"ردوها علي فطفق مسحا بالسوق والاعناق","dt":"[33] ردوا علي الخيل التي عرضت من قبل، فردت عليه، فشرع يضرب سيقانها ورقابها بالسيف؛ قربه لله، لانها كانت سبب فوات صلاته. وكان التقرب بذبح الخيل مشروعا في شريعته."},{"id":"4004","s":38,"a":34,"at":"ولقد فتنا سليمان والقينا على كرسيه جسدا ثم اناب","dt":"[34] ولقد ابتلينا سليمان والقينا على كرسيه شق ولد، ولد له حين اقسم ليطوفن على نسائه، وكلهن تاتي بفارس يجاهد في سبيل الله، ولم يقل: ان شاء الله، فطاف عليهن جميعا، فلم تحمل منهن الا امراه واحده جاءت بشق ولد، ثم رجع سليمان الى ربه وتاب،"},{"id":"4005","s":38,"a":35,"at":"قال رب اغفر لي وهب لي ملكا لا ينبغي لاحد من بعدي انك انت الوهاب","dt":"[35] ، قال: رب اغفر لي ذنبي، واعطني ملكا عظيما خاصا لا يكون مثله لاحد من البشر بعدي، انك -سبحانك- كثير الجود والعطاء."},{"id":"4006","s":38,"a":36,"at":"فسخرنا له الريح تجري بامره رخاء حيث اصاب","dt":"[36] فاستجبنا له، وذللنا الريح تجري بامره طيعه مع قوتها وشدتها حيث اراد."},{"id":"4007","s":38,"a":37,"at":"والشياطين كل بناء وغواص","dt":"[37] وسخرنا له الشياطين يستعملهم في اعمال: فمنهم البناؤون والغواصون في البحار،"},{"id":"4008","s":38,"a":38,"at":"واخرين مقرنين في الاصفاد","dt":"[38] واخرون وهم مرده الشياطين، موثوقون في الاغلال."},{"id":"4009","s":38,"a":39,"at":"هذا عطاؤنا فامنن او امسك بغير حساب","dt":"[39] هذا الملك العظيم والتسخير الخاص عطاؤنا لك يا سليمان، فاعط من شئت او امنع من شئت، لا حساب عليك."},{"id":"4010","s":38,"a":40,"at":"وان له عندنا لزلفى وحسن ماب","dt":"[40] وان لسليمان عندنا في الدار الاخره لقربه وحسن مرجع."},{"id":"4011","s":38,"a":41,"at":"واذكر عبدنا ايوب اذ نادى ربه اني مسني الشيطان بنصب وعذاب","dt":"[41] واذكر -ايها الرسول- عبدنا ايوب، حين دعا ربه ان الشيطان تسبب لي بتعب ومشقه، والم في جسدي ومالي واهلي."},{"id":"4012","s":38,"a":42,"at":"اركض برجلك هذا مغتسل بارد وشراب","dt":"[42] فقلنا له: اضرب برجلك الارض ينبع لك منها ماء بارد، فاشرب منه، واغتسل فيذهب عنك الضر والاذى."},{"id":"4013","s":38,"a":43,"at":"ووهبنا له اهله ومثلهم معهم رحمه منا وذكرى لاولي الالباب","dt":"[43] فكشفنا عنه ضره واكرمناه ووهبنا له اهله من زوجه وولد، وزدناه مثلهم بنين وحفده، كل ذلك رحمه منا به واكراما له على صبره، وعبره وذكرى لاصحاب العقول السليمه؛ ليعلموا ان عاقبه الصبر الفرج وكشف الضر."},{"id":"4014","s":38,"a":44,"at":"وخذ بيدك ضغثا فاضرب به ولا تحنث انا وجدناه صابرا نعم العبد انه اواب","dt":"[44] وقلنا له: خذ بيدك حزمه من الحشيش ونحوه، فاضرب بها زوجك ابرارا بيمينك، فلا تحنث؛ اذ اقسم ليضربنها مائه جلده اذا شفاه الله، لما غضب عليها من امر يسير اثناء مرضه، وكانت امراه صالحه، فرحمها الله ورحمه بهذه الفتوى. انا وجدنا ايوب صابرا على البلاء، نعم العبد هو، انه رجاع الى طاعه الله."},{"id":"4015","s":38,"a":45,"at":"واذكر عبادنا ابراهيم واسحاق ويعقوب اولي الايدي والابصار","dt":"[45] واذكر -ايها الرسول- عبادنا وانبياءنا: ابراهيم واسحاق ويعقوب؛ فانهم اصحاب قوه في طاعه الله، وبصيره في دينه."},{"id":"4016","s":38,"a":46,"at":"انا اخلصناهم بخالصه ذكرى الدار","dt":"[46] انا خصصناهم بخاصه عظيمه، حيث جعلنا ذكرى الدار الاخره في قلوبهم، فعملوا لها بطاعتنا، ودعوا الناس اليها، وذكروهم بها."},{"id":"4017","s":38,"a":47,"at":"وانهم عندنا لمن المصطفين الاخيار","dt":"[47] وانهم عندنا لمن الذين اصطفيناهم لرسالتنا، واخترناهم لطاعتنا."},{"id":"4018","s":38,"a":48,"at":"واذكر اسماعيل واليسع وذا الكفل وكل من الاخيار","dt":"[48] واذكر -ايها الرسول- عبادنا: اسماعيل، واليسع، وذا الكفل، باحسن الذكر؛ ان كلا منهم من الاخيار الذين اختارهم الله من الخلق، واختار لهم اكمل الاحوال والصفات."},{"id":"4019","s":38,"a":49,"at":"هذا ذكر وان للمتقين لحسن ماب","dt":"[49] هذا القران ذكر وشرف لك -ايها الرسول- ولقومك. وان لاهل تقوى الله وطاعته لحسن مصير عندنا"},{"id":"4020","s":38,"a":50,"at":"جنات عدن مفتحه لهم الابواب","dt":"[50] في جنات اقامه، مفتحه لهم ابوابها،"},{"id":"4021","s":38,"a":51,"at":"متكئين فيها يدعون فيها بفاكهه كثيره وشراب","dt":"[51] متكئين فيها على الارائك المزينات، يطلبون ما يشتهون من انواع الفواكه الكثيره والشراب، من كل ما تشتهيه نفوسهم، وتلذه اعينهم."},{"id":"4022","s":38,"a":52,"at":"وعندهم قاصرات الطرف اتراب","dt":"[52] وعندهم نساء قاصرات ابصارهن على ازواجهن متساويات في السن."},{"id":"4023","s":38,"a":53,"at":"هذا ما توعدون ليوم الحساب","dt":"[53] هذا النعيم هو ما توعدون به -ايها المتقون- يوم القيامه،"},{"id":"4024","s":38,"a":54,"at":"ان هذا لرزقنا ما له من نفاد","dt":"[54] انه لرزقنا لكم، ليس له فناء ولا انقطاع."},{"id":"4025","s":38,"a":55,"at":"هذا وان للطاغين لشر ماب","dt":"[55] هذا الذي سبق وصفه للمتقين. واما المتجاوزون الحد في الكفر والمعاصي، فلهم شر مرجع ومصير،"},{"id":"4026","s":38,"a":56,"at":"جهنم يصلونها فبئس المهاد","dt":"[56] وهو النار يعذبون فيها، تغمرهم من جميع جوانبهم، فبئس الفراش فراشهم."},{"id":"4027","s":38,"a":57,"at":"هذا فليذوقوه حميم وغساق","dt":"[57] هذا العذاب ماء شديد الحراره، وصديد سائل من اجساد اهل النار فليشربوه،"},{"id":"4028","s":38,"a":58,"at":"واخر من شكله ازواج","dt":"[58] ولهم عذاب اخر من هذا القبيل اصناف والوان."},{"id":"4029","s":38,"a":59,"at":"هذا فوج مقتحم معكم لا مرحبا بهم انهم صالو النار","dt":"[59] وعند توارد الطاغين على النار يشتم بعضهم بعضا، ويقول بعضهم لبعض: هذه جماعه عظيمه من اهل النار داخله معكم، فيجيبون: لا مرحبا بهم، ولا اتسعت منازلهم في النار، انهم مقاسون حر النار كما قاسيناها."},{"id":"4030","s":38,"a":60,"at":"قالوا بل انتم لا مرحبا بكم انتم قدمتموه لنا فبئس القرار","dt":"[60] قال فوج الاتباع للطاغين: بل انتم لا مرحبا بكم؛ لانكم قدمتم لنا سكنى النار لاضلالكم لنا في الدنيا، فبئس دار الاستقرار جهنم."},{"id":"4031","s":38,"a":61,"at":"قالوا ربنا من قدم لنا هذا فزده عذابا ضعفا في النار","dt":"[61] قال فوج الاتباع: ربنا من اضلنا في الدنيا عن الهدى فضاعف عذابه في النار."},{"id":"4032","s":38,"a":62,"at":"وقالوا ما لنا لا نرى رجالا كنا نعدهم من الاشرار","dt":"[62] وقال الطاغون: ما بالنا لا نرى معنا في النار رجالا كنا نعدهم في الدنيا من الاشرار الاشقياء؟"},{"id":"4033","s":38,"a":63,"at":"اتخذناهم سخريا ام زاغت عنهم الابصار","dt":"[63] هل تحقيرنا لهم واستهزاؤنا بهم خطا، او انهم معنا في النار، لكن لم تقع عليهم الابصار؟"},{"id":"4034","s":38,"a":64,"at":"ان ذلك لحق تخاصم اهل النار","dt":"[64] ان ذلك من جدال اهل النار وخصامهم حق واقع لا مريه فيه."},{"id":"4035","s":38,"a":65,"at":"قل انما انا منذر وما من اله الا الله الواحد القهار","dt":"[65] قل -ايها الرسول- لقومك: انما انا منذر لكم من عذاب الله ان يحل بكم؛ بسبب كفركم به، ليس هناك اله مستحق للعباده الا الله وحده، فهو المتفرد بعظمته واسمائه وصفاته وافعاله، القهار الذي قهر كل شيء وغلبه."},{"id":"4036","s":38,"a":66,"at":"رب السموات والارض وما بينهما العزيز الغفار","dt":"[66] مالك السموات والارض وما بينهما العزيز في انتقامه، الغفار لذنوب من تاب واناب الى مرضاته."},{"id":"4037","s":38,"a":67,"at":"قل هو نبا عظيم","dt":"[67] قل -ايها الرسول- لقومك: ان هذا القران خبر عظيم النفع."},{"id":"4038","s":38,"a":68,"at":"انتم عنه معرضون","dt":"[68] انتم عنه غافلون منصرفون، لا تعملون به."},{"id":"4039","s":38,"a":69,"at":"ما كان لي من علم بالملا الاعلى اذ يختصمون","dt":"[69] ليس لي علم باختصام ملائكه السماء في شان خلق ادم، لولا تعليم الله اياي، وايحاؤه الي."},{"id":"4040","s":38,"a":70,"at":"ان يوحى الي الا انما انا نذير مبين","dt":"[70] ما يوحي الله الي من علم ما لا علم لي به الا لاني نذير لكم من عذابه، مبين لكم شرعه."},{"id":"4041","s":38,"a":71,"at":"اذ قال ربك للملائكه اني خالق بشرا من طين","dt":"[71] اذكر لهم -ايها الرسول-: حين قال ربك للملائكه: اني خالق بشرا من طين."},{"id":"4042","s":38,"a":72,"at":"فاذا سويته ونفخت فيه من روحي فقعوا له ساجدين","dt":"[72] فاذا سويت جسده وخلقه ونفخت فيه الروح، فدبت فيه الحياه، فاسجدوا له سجود تحيه واكرام، لا سجود عباده وتعظيم؛ فالعباده لا تكون الا لله وحده. وقد حرم الله في شريعه الاسلام السجود للتحيه."},{"id":"4043","s":38,"a":73,"at":"فسجد الملائكه كلهم اجمعون","dt":"[73] فسجد الملائكه كلهم اجمعون طاعه وامتثالا"},{"id":"4044","s":38,"a":74,"at":"الا ابليس استكبر وكان من الكافرين","dt":"[74] غير ابليس؛ فانه لم يسجد انفه وتكبرا، وكان من الكافرين في علم الله تعالى."},{"id":"4045","s":38,"a":75,"at":"قال ياابليس ما منعك ان تسجد لما خلقت بيدي استكبرت ام كنت من العالين","dt":"[75] قال الله لابليس: ما الذي منعك من السجود لمن اكرمته فخلقته بيدي؟ استكبرت على ادم، ام كنت من المتكبرين على ربك؟ وفي الايه اثبات صفه اليدين لله تبارك وتعالى، على الوجه اللائق به سبحانه."},{"id":"4046","s":38,"a":76,"at":"قال انا خير منه خلقتني من نار وخلقته من طين","dt":"[76] قال ابليس معارضا لربه: لم اسجد له؛ لانني افضل منه، حيث خلقتني من نار، وخلقته من طين. والنار خير من الطين."},{"id":"4047","s":38,"a":77,"at":"قال فاخرج منها فانك رجيم","dt":"[77]قال الله له: فاخرج من الجنه فانك مرجوم بالقول، مدحور ملعون،"},{"id":"4048","s":38,"a":78,"at":"وان عليك لعنتي الى يوم الدين","dt":"[78] وان عليك طردي وابعادي الى يوم الجزاء والحساب."},{"id":"4049","s":38,"a":79,"at":"قال رب فانظرني الى يوم يبعثون","dt":"[79] قال ابليس: رب فاخر اجلي، ولا تهلكني الى حين تبعث الخلق من قبورهم."},{"id":"4050","s":38,"a":80,"at":"قال فانك من المنظرين","dt":"[80] قال الله له: فانك من المؤخرين"},{"id":"4051","s":38,"a":81,"at":"الى يوم الوقت المعلوم","dt":"[81] الى يوم الوقت المعلوم، وهو يوم النفخه الاولى عندما تموت الخلائق."},{"id":"4052","s":38,"a":82,"at":"قال فبعزتك لاغوينهم اجمعين","dt":"[82] قال ابليس: فبعزتك -يا رب- وعظمتك لاضلن بني ادم اجمعين،"},{"id":"4053","s":38,"a":83,"at":"الا عبادك منهم المخلصين","dt":"83] الا من اخلصته منهم لعبادتك، وعصمته من اضلالي، فلم تجعل لي عليهم سبيلا."},{"id":"4054","s":38,"a":84,"at":"قال فالحق والحق اقول","dt":"[84] قال الله: فالحق مني، ولا اقول الا الحق،"},{"id":"4055","s":38,"a":85,"at":"لاملان جهنم منك وممن تبعك منهم اجمعين","dt":"[85] لاملان جهنم منك ومن ذريتك وممن تبعك من بني ادم اجمعين."},{"id":"4056","s":38,"a":86,"at":"قل ما اسالكم عليه من اجر وما انا من المتكلفين","dt":"[86] قل -ايها الرسول- لهؤلاء المشركين من قومك: لا اطلب منكم اجرا او جزاء على دعوتكم وهدايتكم، ولا ادعي امرا ليس لي، بل اتبع ما يوحى الي، ولا اتكلف تخرصا وافتراء."},{"id":"4057","s":38,"a":87,"at":"ان هو الا ذكر للعالمين","dt":"[87] ما هذا القران الا تذكير للعالمين من الجن والانس، يتذكرون به ما ينفعهم من مصالح دينهم ودنياهم."},{"id":"4058","s":38,"a":88,"at":"ولتعلمن نباه بعد حين","dt":"[88] ولتعلمن -ايها المشركون- خبر هذا القران وصدقه، حين يغلب الاسلام، ويدخل الناس فيه افواجا، وكذلك حين يقع عليكم العذاب، وتنقطع عنكم الاسباب."},{"id":"4059","s":39,"a":1,"at":"تنزيل الكتاب من الله العزيز الحكيم","dt":"[1] تنزيل القران انما هو من الله العزيز في قدرته وانتقامه، الحكيم في تدبيره واحكامه."},{"id":"4060","s":39,"a":2,"at":"انا انزلنا اليك الكتاب بالحق فاعبد الله مخلصا له الدين","dt":"[2] انا انزلنا اليك -ايها الرسول- القران يامر بالحق والعدل، فاعبد الله وحده، واخلص له جميع دينك."},{"id":"4061","s":39,"a":3,"at":"الا لله الدين الخالص والذين اتخذوا من دونه اولياء ما نعبدهم الا ليقربونا الى الله زلفى ان الله يحكم بينهم في ما هم فيه يختلفون ان الله لا يهدي من هو كاذب كفار","dt":"[3] الا لله وحده الطاعه التامه السالمه من الشرك، والذين اشركوا مع الله غيره واتخذوا من دونه اولياء، قالوا: ما نعبد تلك الالهه مع الله الا لتشفع لنا عند الله، وتقربنا عنده منزله، فكفروا بذلك؛ لان العباده والشفاعه لله وحده، ان الله يفصل بين المؤمنين المخلصين والمشركين مع الله غيره يوم القيامه فيما يختلفون فيه من عبادتهم، فيجازي كلا بما يستحق. ان الله لا يوفق للهدايه الى الصراط المستقيم من هو مفتر على الله، كفار باياته وحججه."},{"id":"4062","s":39,"a":4,"at":"لو اراد الله ان يتخذ ولدا لاصطفى مما يخلق ما يشاء سبحانه هو الله الواحد القهار","dt":"[4] لو اراد الله ان يتخذ ولدا لاختار من مخلوقاته ما يشاء، تنزه الله وتقدس عن ان يكون له ولد، فانه الواحد الاحد، الفرد الصمد، القهار الذي قهر خلقه بقدرته، فكل شيء له متذلل خاضع."},{"id":"4063","s":39,"a":5,"at":"خلق السموات والارض بالحق يكور الليل على النهار ويكور النهار على الليل وسخر الشمس والقمر كل يجري لاجل مسمى الا هو العزيز الغفار","dt":"[5] خلق الله السموات والارض وما فيهما بالحق، يجيء بالليل ويذهب بالنهار، ويجيء بالنهار ويذهب بالليل، وذلل الشمس والقمر بانتظام لمنافع العباد، كل منهما يجري في مداره الى حين قيام الساعه. الا ان الله الذي فعل هذه الافعال، وانعم على خلقه بهذه النعم هو العزيز على خلقه، الغفار لذنوب عباده التائبين."},{"id":"4064","s":39,"a":6,"at":"خلقكم من نفس واحده ثم جعل منها زوجها وانزل لكم من الانعام ثمانيه ازواج يخلقكم في بطون امهاتكم خلقا من بعد خلق في ظلمات ثلاث ذلكم الله ربكم له الملك لا اله الا هو فانى تصرفون","dt":"[6] خلقكم ربكم -ايها الناس- من ادم، وخلق منه زوجه، وخلق لكم من الانعام ثمانيه انواع ذكرا وانثى من الابل والبقر والضان والمعز، يخلقكم في بطون امهاتكم طورا بعد طور من الخلق في ظلمات البطن، والرحم، والمشيمه، ذلكم الله الذي خلق هذه الاشياء، ربكم المتفرد بالملك المتوحد بالالوهيه المستحق للعباده وحده، فكيف تعدلون عن عبادته الى عباده غيره من خلقه؟"},{"id":"4065","s":39,"a":7,"at":"ان تكفروا فان الله غني عنكم ولا يرضى لعباده الكفر وان تشكروا يرضه لكم ولا تزر وازره وزر اخرى ثم الى ربكم مرجعكم فينبئكم بما كنتم تعملون انه عليم بذات الصدور","dt":"[7] ان تكفروا -ايها الناس- بربكم ولم تؤمنوا به، ولم تتبعوا رسله، فانه غني عنكم، ليس بحاجه اليكم، وانتم الفقراء اليه، ولا يرضى لعباده الكفر، ولا يامرهم به، وانما يرضى لهم شكر نعمه عليهم. ولا تحمل نفس اثم نفس اخرى، ثم الى ربكم مصيركم، فيخبركم بعملكم، ويحاسبكم عليه. انه عليم باسرار النفوس وما تخفي الصدور."},{"id":"4066","s":39,"a":8,"at":"واذا مس الانسان ضر دعا ربه منيبا اليه ثم اذا خوله نعمه منه نسي ما كان يدعو اليه من قبل وجعل لله اندادا ليضل عن سبيله قل تمتع بكفرك قليلا انك من اصحاب النار","dt":"[8] واذا اصاب الانسان بلاء وشده ومرض تذكر ربه، فاستغاث به ودعاه، ثم اذا اجابه وكشف عنه ضره، ومنحه نعمه، نسي دعاءه لربه عند حاجته اليه، واشرك معه غيره؛ ليضل غيره عن الايمان بالله وطاعته، قل له -ايها الرسول- متوعدا: تمتع بكفرك قليلا حتى موتك وانتهاء اجلك، انك من اهل النار المخلدين فيها."},{"id":"4067","s":39,"a":9,"at":"امن هو قانت اناء الليل ساجدا وقائما يحذر الاخره ويرجو رحمه ربه قل هل يستوي الذين يعلمون والذين لا يعلمون انما يتذكر اولو الالباب","dt":"[9] اهذا الكافر المتمتع بكفره خير، ام من هو عابد لربه طائع له، يقضي ساعات الليل في القيام والسجود لله، يخاف عذاب الاخره، ويطمع في رحمه ربه؟ قل -ايها الرسول-: هل يستوي الذين يعلمون ربهم ودينهم الحق والذين لا يعلمون شيئا من ذلك؟ لا يستوون. انما يتذكر ويعرف الفرق اصحاب العقول السليمه."},{"id":"4068","s":39,"a":10,"at":"قل ياعباد الذين امنوا اتقوا ربكم للذين احسنوا في هذه الدنيا حسنه وارض الله واسعه انما يوفى الصابرون اجرهم بغير حساب","dt":"[10] قل -ايها النبي- لعبادي المؤمنين بالله ورسوله: اتقوا ربكم بطاعته واجتناب معصيته. للذين احسنوا في هذه الدنيا بعباده ربهم وطاعته حسنه في الاخره، وهي الجنه، وحسنه في الدنيا من صحه ورزق ونصر وغير ذلك. وارض الله واسعه، فهاجروا فيها الى حيث تعبدون ربكم، وتتمكنون من اقامه دينكم. انما يعطى الصابرون ثوابهم في الاخره بغير حد ولا عد ولا مقدار، وهذا تعظيم لجزاء الصابرين وثوابهم."},{"id":"4069","s":39,"a":11,"at":"قل اني امرت ان اعبد الله مخلصا له الدين","dt":"[11] قل -ايها الرسول- للناس: ان الله امرني ومن تبعني باخلاص العباده له وحده دون سواه،"},{"id":"4070","s":39,"a":12,"at":"وامرت لان اكون اول المسلمين","dt":"[12] وامرني بان اكون اول من اسلم من امتي، فخضع له بالتوحيد، واخلص له العباده، وبرئ من كل ما دونه من الالهه."},{"id":"4071","s":39,"a":13,"at":"قل اني اخاف ان عصيت ربي عذاب يوم عظيم","dt":"[13] قل -ايها الرسول- للناس: اني اخاف ان عصيت ربي فيما امرني به من عبادته والاخلاص في طاعته عذاب يوم القيامه، ذلك اليوم الذي يعظم هوله."},{"id":"4072","s":39,"a":14,"at":"قل الله اعبد مخلصا له ديني","dt":"[14] قل -ايها الرسول-: اني اعبد الله وحده لا شريك له مخلصا له عبادتي وطاعتي،"},{"id":"4073","s":39,"a":15,"at":"فاعبدوا ما شئتم من دونه قل ان الخاسرين الذين خسروا انفسهم واهليهم يوم القيامه الا ذلك هو الخسران المبين","dt":"[15] فاعبدوا انتم -ايها المشركون- ما شئتم من دون الله من الاوثان والاصنام وغير ذلك من مخلوقاته، فلا يضرني ذلك شيئا. وهذا تهديد ووعيد لمن عبد غير الله، واشرك معه غيره. قل -ايها الرسول-: ان الخاسرين -حقا- هم الذين خسروا انفسهم واهليهم يوم القيامه، وذلك باغوائهم في الدنيا واضلالهم عن الايمان. الا ان خسران هؤلاء المشركين انفسهم واهليهم يوم القيامه هو الخسران البين الواضح."},{"id":"4074","s":39,"a":16,"at":"لهم من فوقهم ظلل من النار ومن تحتهم ظلل ذلك يخوف الله به عباده ياعباد فاتقون","dt":"[16] اولئك الخاسرون لهم يوم القيامه في جهنم من فوقهم قطع عذاب من النار كهيئه الظلل المبنيه، ومن تحتهم كذلك. ذلك العذاب الموصوف يخوف الله به عباده؛ ليحذروه. يا عباد فاتقوني بامتثال اوامري واجتناب معاصي."},{"id":"4075","s":39,"a":17,"at":"والذين اجتنبوا الطاغوت ان يعبدوها وانابوا الى الله لهم البشرى فبشر عباد","dt":"[17] والذين اجتنبوا طاعه الشيطان وعباده غير الله، وتابوا الى الله بعبادته واخلاص الدين له، لهم البشرى في الحياه الدنيا بالثناء الحسن والتوفيق من الله، وفي الاخره رضوان الله والنعيم الدائم في الجنه. فبشر -ايها النبي- عبادي"},{"id":"4076","s":39,"a":18,"at":"الذين يستمعون القول فيتبعون احسنه اولئك الذين هداهم الله واولئك هم اولو الالباب","dt":"[18] الذين يستمعون القول فيتبعون ارشده. واحسن الكلام وارشده كلام الله ثم كلام رسوله صلى الله عليه وسلم. اولئك هم الذين وفقهم الله للرشاد والسداد، وهداهم لاحسن الاخلاق والاعمال، واولئك هم اصحاب العقول السليمه."},{"id":"4077","s":39,"a":19,"at":"افمن حق عليه كلمه العذاب افانت تنقذ من في النار","dt":"[19] افمن وجبت عليه كلمه العذاب؛ باستمراره على غيه وعناده، فانه لا حيله لك -ايها الرسول- في هدايته، افتقدر ان تنقذ من في النار؟ لست بقادر على ذلك."},{"id":"4078","s":39,"a":20,"at":"لكن الذين اتقوا ربهم لهم غرف من فوقها غرف مبنيه تجري من تحتها الانهار وعد الله لا يخلف الله الميعاد","dt":"[20] لكن الذين اتقوا ربهم -بطاعته واخلاص عبادته- لهم في الجنه غرف مبنيه بعضها فوق بعض، تجري من تحت غرفهم ومنازلهم الانهار، وعدها الله عباده المتقين وعدا متحققا، لا يخلف الله الميعاد."},{"id":"4079","s":39,"a":21,"at":"الم تر ان الله انزل من السماء ماء فسلكه ينابيع في الارض ثم يخرج به زرعا مختلفا الوانه ثم يهيج فتراه مصفرا ثم يجعله حطاما ان في ذلك لذكرى لاولي الالباب","dt":"[21] الم تر -ايها الرسول- ان الله انزل من السحاب مطرا فادخله في الارض، وجعله عيونا نابعه ومياها جاريه، ثم يخرج بهذا الماء زرعا مختلفا الوانه وانواعه، ثم ييبس بعد خضرته ونضارته، فتراه مصفرا لونه، ثم يجعله حطاما متكسرا متفتتا؟ ان في فعل الله ذلك لذكرى وموعظه لاصحاب العقول السليمه."},{"id":"4080","s":39,"a":22,"at":"افمن شرح الله صدره للاسلام فهو على نور من ربه فويل للقاسيه قلوبهم من ذكر الله اولئك في ضلال مبين","dt":"[22] افمن وسع الله صدره، فسعد بقبول الاسلام والانقياد له والايمان به، فهو على بصيره من امره وهدى من ربه، كمن ليس كذلك؟ لا يستوون. فويل وهلاك للذين قست قلوبهم، واعرضت عن ذكر الله، اولئك في ضلال بين عن الحق."},{"id":"4081","s":39,"a":23,"at":"الله نزل احسن الحديث كتابا متشابها مثاني تقشعر منه جلود الذين يخشون ربهم ثم تلين جلودهم وقلوبهم الى ذكر الله ذلك هدى الله يهدي به من يشاء ومن يضلل الله فما له من هاد","dt":"[23] الله تعالى هو الذي نزل احسن الحديث، وهو القران العظيم، متشابها في حسنه واحكامه وعدم اختلافه، تكرر فيه القصص، والاحكام، والحجج والبينات، وتعاد تلاوته فلا يمل على كثره الترداد، تقشعر من سماعه، وتضطرب جلود الذين يخافون ربهم؛ تاثرا بما فيه من ترهيب ووعيد، ثم تلين جلودهم وقلوبهم؛ استبشارا بما فيه من وعد وترغيب، ذلك التاثر بالقران هدايه من الله لعباده. والله يهدي بالقران من يشاء من عباده. ومن يضلله الله عن الايمان بهذا القران؛ لكفره وعناده، فما له من هاد يهديه ويوفقه."},{"id":"4082","s":39,"a":24,"at":"افمن يتقي بوجهه سوء العذاب يوم القيامه وقيل للظالمين ذوقوا ما كنتم تكسبون","dt":"[24] افمن يلقى في النار مغلولا -فلا يتهيا له ان يتقي النار الا بوجهه؛ لكفره وضلاله- خير ام من ينعم في الجنه؛ لان الله هداه؟ وقيل يومئذ للظالمين: ذوقوا وبال ما كنتم في الدنيا تكسبون من معاصي الله."},{"id":"4083","s":39,"a":25,"at":"كذب الذين من قبلهم فاتاهم العذاب من حيث لا يشعرون","dt":"[25] كذب الذين من قبل قومك -ايها الرسول- رسلهم، فجاءهم العذاب من حيث لا يشعرون بمجيئه،"},{"id":"4084","s":39,"a":26,"at":"فاذاقهم الله الخزي في الحياه الدنيا ولعذاب الاخره اكبر لو كانوا يعلمون","dt":"[26] فاذاق الله الامم المكذبه العذاب والهوان في الدنيا، واعد لهم عذابا اشد واشق في الاخره، لو كان هؤلاء المشركون يعلمون ان ما حل بهم؛ بسبب كفرهم وتكذيبهم لاتعظوا."},{"id":"4085","s":39,"a":27,"at":"ولقد ضربنا للناس في هذا القران من كل مثل لعلهم يتذكرون","dt":"[27] ولقد ضربنا لهؤلاء المشركين بالله في هذا القران من كل مثل من امثال القرون الخاليه تخويفا وتحذيرا؛ ليتذكروا فينزجروا عما هم عليه مقيمون من الكفر بالله."},{"id":"4086","s":39,"a":28,"at":"قرانا عربيا غير ذي عوج لعلهم يتقون","dt":"[28] وجعلنا هذا القران عربيا واضح الالفاظ سهل المعاني، لا لبس فيه ولا انحراف؛ لعلهم يتقون الله بامتثال اوامره واجتناب نواهيه."},{"id":"4087","s":39,"a":29,"at":"ضرب الله مثلا رجلا فيه شركاء متشاكسون ورجلا سلما لرجل هل يستويان مثلا الحمد لله بل اكثرهم لا يعلمون","dt":"[29] ضرب الله مثلا عبدا مملوكا لشركاء متنازعين، فهو حيران في ارضائهم، وعبدا خالصا لمالك واحد يعرف مراده وما يرضيه، هل يستويان مثلا؟ لا يستويان، كذلك المشرك هو في حيره وشك، والمؤمن في راحه واطمئنان. فالثناء الكامل التام لله وحده، بل المشركون لا يعلمون الحق فيتبعونه."},{"id":"4088","s":39,"a":30,"at":"انك ميت وانهم ميتون","dt":"[30] انك -ايها الرسول- ميت وانهم ميتون،"},{"id":"4089","s":39,"a":31,"at":"ثم انكم يوم القيامه عند ربكم تختصمون","dt":"[31] ثم انكم جميعا -ايها الناس- يوم القيامه عند ربكم تتنازعون، فيحكم بينكم بالعدل والانصاف."},{"id":"4090","s":39,"a":32,"at":"فمن اظلم ممن كذب على الله وكذب بالصدق اذ جاءه اليس في جهنم مثوى للكافرين","dt":"[32] لا احد اظلم ممن افترى على الله الكذب: بان نسب اليه ما لا يليق به كالشريك والولد، او قال: اوحي الي، ولم يوح اليه شيء، ولا احد اظلم ممن كذب بالحق الذي نزل على محمد -صلى الله عليه وسلم-. اليس في النار ماوى ومسكن لمن كفر بالله، ولم يصدق محمدا -صلى الله عليه وسلم- ولم يعمل بما جاء به؟ بلى."},{"id":"4091","s":39,"a":33,"at":"والذي جاء بالصدق وصدق به اولئك هم المتقون","dt":"[33] والذي جاء بالصدق في قوله وعمله من الانبياء واتباعهم، وصدق به ايمانا وعملا، اولئك هم الذين جمعوا خصال التقوى، وفي مقدمه هؤلاء خاتم الانبياء والمرسلين محمد -صلى الله عليه وسلم- والمؤمنون به، العاملون بشريعته من الصحابه، رضي الله عنهم، فمن بعدهم الى يوم الدين."},{"id":"4092","s":39,"a":34,"at":"لهم ما يشاءون عند ربهم ذلك جزاء المحسنين","dt":"[34] لهم ما يشاؤون عند ربهم من اصناف اللذات والمشتهيات؛ ذلك جزاء من اطاع ربه حق الطاعه، وعبده حق العباده."},{"id":"4093","s":39,"a":35,"at":"ليكفر الله عنهم اسوا الذي عملوا ويجزيهم اجرهم باحسن الذي كانوا يعملون","dt":"[35] ليكفر الله عنهم اسوا الذي عملوا في الدنيا من الاعمال؛ بسبب ما كان منهم من توبه وانابه مما اجترحوا من السيئات فيها، ويثيبهم الله على طاعتهم في الدنيا باحسن ما كانوا يعملون، وهو الجنه."},{"id":"4094","s":39,"a":36,"at":"اليس الله بكاف عبده ويخوفونك بالذين من دونه ومن يضلل الله فما له من هاد","dt":"[36] اليس الله بكاف عبده محمدا وعيد المشركين وكيدهم من ان ينالوه بسوء؟ بلى انه سيكفيه في امر دينه ودنياه، ويدفع عنه من اراده بسوء، ويخوفونك -ايها الرسول- بالهتهم التي زعموا انها ستؤذيك. ومن يخذله الله فيضله عن طريق الحق، فما له من هاد يهديه اليه."},{"id":"4095","s":39,"a":37,"at":"ومن يهد الله فما له من مضل اليس الله بعزيز ذي انتقام","dt":"[37] ومن يوفقه الله للايمان به والعمل بكتابه واتباع رسوله فما له من مضل عن الحق الذي هو عليه. اليس الله بعزيز في انتقامه من كفره خلقه، وممن عصاه؟"},{"id":"4096","s":39,"a":38,"at":"ولئن سالتهم من خلق السموات والارض ليقولن الله قل افرايتم ما تدعون من دون الله ان ارادني الله بضر هل هن كاشفات ضره او ارادني برحمه هل هن ممسكات رحمته قل حسبي الله عليه يتوكل المتوكلون","dt":"[38] ولئن سالت -ايها الرسول- هؤلاء المشركين الذين يعبدون غير الله: من خلق هذه السموات والارض؟ ليقولن: خلقهن الله، فهم يقرون بالخالق. قل لهم: هل تستطيع هذه الالهه التي تشركونها مع الله ان تبعد عني اذى قدره الله علي، او تزيل مكروها لحق بي؟ وهل تستطيع ان تمنع نفعا يسره الله لي، او تحبس رحمه الله عني؟ انهم سيقولون: لا تستطيع ذلك. قل لهم: حسبي الله وكافي، عليه يعتمد المعتمدون في جلب مصالحهم ودفع مضارهم، فالذي بيده وحده الكفايه هو حسبي، وسيكفيني كل ما اهمني."},{"id":"4097","s":39,"a":39,"at":"قل ياقوم اعملوا على مكانتكم اني عامل فسوف تعلمون","dt":"[39] قل -ايها الرسول- لقومك المعاندين: اعملوا على حالتكم التي رضيتموها لانفسكم، حيث عبدتم من لا يستحق العباده، وليس له من الامر شيء، اني عامل على ما امرت به من التوجه لله وحده في اقوالي وافعالي، فسوف تعلمون"},{"id":"4098","s":39,"a":40,"at":"من ياتيه عذاب يخزيه ويحل عليه عذاب مقيم","dt":"[40] من ياتيه عذاب يهينه في الحياه الدنيا، ويحل عليه في الاخره عذاب دائم، لا يحول عنه ولا يزول."},{"id":"4099","s":39,"a":41,"at":"انا انزلنا عليك الكتاب للناس بالحق فمن اهتدى فلنفسه ومن ضل فانما يضل عليها وما انت عليهم بوكيل","dt":"[41] انا انزلنا عليك -ايها الرسول- القران بالحق هدايه للعالمين، الى طريق الرشاد، فمن اهتدى بنوره، وعمل بما فيه، واستقام على منهجه، فنفع ذلك يعود على نفسه، ومن ضل بعد ما تبين له الهدى، فانما يعود ضرره على نفسه، ولن يضر الله شيئا، وما انت -ايها الرسول- عليهم بوكيل تحفظ اعمالهم، وتحاسبهم عليها، وتجبرهم على ما تشاء، ما عليك الا البلاغ."},{"id":"4100","s":39,"a":42,"at":"الله يتوفى الانفس حين موتها والتي لم تمت في منامها فيمسك التي قضى عليها الموت ويرسل الاخرى الى اجل مسمى ان في ذلك لايات لقوم يتفكرون","dt":"[42] الله -سبحانه وتعالى- هو الذي يقبض الانفس حين موتها، وهذه الوفاه الكبرى وفاه الموت بانقضاء الاجل، ويقبض التي لم تمت في منامها، وهي الموته الصغرى، فيحبس من هاتين النفسين النفس التي قضى عليها الموت، وهي نفس من مات، ويرسل النفس الاخرى الى استكمال اجلها ورزقها، وذلك باعادتها الى جسم صاحبها، ان في قبض الله نفس الميت والنائم وارساله نفس النائم، وحبسه نفس الميت لدلائل واضحه على قدره الله لمن تفكر وتدبر."},{"id":"4101","s":39,"a":43,"at":"ام اتخذوا من دون الله شفعاء قل او لو كانوا لا يملكون شيئا ولا يعقلون","dt":"[43] ام اتخذ هؤلاء المشركون بالله من دونه الهتهم التي يعبدونها شفعاء، تشفع لهم عند الله في حاجاتهم؟ قل -ايها الرسول- لهم: اتتخذونها شفعاء كما تزعمون، ولو كانت الالهه لا تملك شيئا، ولا تعقل عبادتكم لها؟"},{"id":"4102","s":39,"a":44,"at":"قل لله الشفاعه جميعا له ملك السموات والارض ثم اليه ترجعون","dt":"[44] قل -ايها الرسول- لهؤلاء المشركين: لله الشفاعه جميعا، له ملك السموات والارض وما فيهما، فالامر كله لله وحده، ولا يشفع عنده احد الا باذنه، ورضاه عن المشفوع له، فهو الذي يملك السموات والارض ويتصرف فيهما، فالواجب ان تطلب الشفاعه ممن يملكها، وان تخلص له العباده، ولا تطلب من هذه الالهه التي لا تضر ولا تنفع، ثم اليه ترجعون بعد مماتكم للحساب والجزاء."},{"id":"4103","s":39,"a":45,"at":"واذا ذكر الله وحده اشمازت قلوب الذين لا يؤمنون بالاخره واذا ذكر الذين من دونه اذا هم يستبشرون","dt":"[45] واذا ذكر الله وحده نفرت قلوب الذين لا يؤمنون بالمعاد والبعث بعد الممات، واذا ذكر الذين من دونه من الاصنام والاوثان والاولياء اذا هم يفرحون؛ لكون الشرك موافقا لاهوائهم."},{"id":"4104","s":39,"a":46,"at":"قل اللهم فاطر السموات والارض عالم الغيب والشهاده انت تحكم بين عبادك في ما كانوا فيه يختلفون","dt":"[46] قل: اللهم يا خالق السموات والارض ومبدعهما على غير مثال سبق، عالم السر والعلانيه، انت تفصل بين عبادك يوم القيامه فيما كانوا فيه يختلفون من القول فيك، وفي عظمتك وسلطانك والايمان بك وبرسولك، اهدني لما اختلف فيه من الحق باذنك، انك تهدي من تشاء الى صراط مستقيم. وكان هذا من دعائه -صلى الله عليه وسلم-، وهو تعليم للعباد بالالتجاء الى الله تعالى، ودعائه باسمائه الحسنى وصفاته العلى."},{"id":"4105","s":39,"a":47,"at":"ولو ان للذين ظلموا ما في الارض جميعا ومثله معه لافتدوا به من سوء العذاب يوم القيامه وبدا لهم من الله ما لم يكونوا يحتسبون","dt":"[47] ولو ان لهؤلاء المشركين بالله ما في الارض جميعا من مال وذخائر، ومثله معه مضاعفا، لبذلوه يوم القيامه؛ ليفتدوا به من سوء العذاب، ولو بذلوه وافتدوا به ما قبل منهم، ولا اغنى عنهم من عذاب الله شيئا، وظهر لهم يومئذ من امر الله وعذابه ما لم يكونوا يحتسبون في الدنيا انه نازل بهم."},{"id":"4106","s":39,"a":48,"at":"وبدا لهم سيئات ما كسبوا وحاق بهم ما كانوا به يستهزئون","dt":"[48] وظهر لهؤلاء المكذبين يوم الحساب جزاء سيئاتهم التي اقترفوها، حيث نسبوا الى الله ما لا يليق به، وارتكبوا المعاصي في حياتهم، واحاط بهم من كل جانب عذاب اليم؛ عقابا لهم على استهزائهم بالانذار بالعذاب الذي كان الرسول يعدهم به، ولا يابهون له."},{"id":"4107","s":39,"a":49,"at":"فاذا مس الانسان ضر دعانا ثم اذا خولناه نعمه منا قال انما اوتيته على علم بل هي فتنه ولكن اكثرهم لا يعلمون","dt":"[49] فاذا اصاب الانسان شده وضر، طلب من ربه ان يفرج عنه، فاذا كشفنا عنه ما اصابه واعطيناه نعمه منا عاد بربه كافرا، ولفضله منكرا، وقال: ان الذي اوتيته انما هو على علم من الله اني له اهل ومستحق، بل ذلك فتنه يبتلي الله بها عباده؛ لينظر من يشكره ممن يكفره، ولكن اكثرهم -لجهلهم وسوء ظنهم- لا يعلمون ان ذلك استدراج لهم من الله، وامتحان لهم على شكر النعم."},{"id":"4108","s":39,"a":50,"at":"قد قالها الذين من قبلهم فما اغنى عنهم ما كانوا يكسبون","dt":"[50] قد قال مقالتهم هذه من قبلهم من الامم الخاليه المكذبه، فما اغنى عنهم حين جاءهم العذاب ما كانوا يكسبونه من الاموال والاولاد."},{"id":"4109","s":39,"a":51,"at":"فاصابهم سيئات ما كسبوا والذين ظلموا من هؤلاء سيصيبهم سيئات ما كسبوا وما هم بمعجزين","dt":"[51] فاصاب الذين قالوا هذه المقاله من الامم الخاليه وبال سيئات ما كسبوا من الاعمال، فعوجلوا بالخزي في الحياه الدنيا، والذين ظلموا انفسهم من قومك -ايها الرسول-، وقالوا هذه المقاله، سيصيبهم ايضا وبال سيئات ما كسبوا، كما اصاب الذين من قبلهم، وما هم بفائتين الله ولا سابقيه."},{"id":"4110","s":39,"a":52,"at":"او لم يعلموا ان الله يبسط الرزق لمن يشاء ويقدر ان في ذلك لايات لقوم يؤمنون","dt":"[52] اولم يعلم هؤلاء ان رزق الله للانسان لا يدل على حسن حال صاحبه، فان الله لبالغ حكمته يوسع الرزق لمن يشاء من عباده، صالحا كان او طالحا، ويضيقه على من يشاء منهم؟ ان في ذلك التوسيع والتضييق في الرزق لدلالات واضحات لقوم يصدقون امر الله ويعملون به."},{"id":"4111","s":39,"a":53,"at":"قل ياعبادي الذين اسرفوا على انفسهم لا تقنطوا من رحمه الله ان الله يغفر الذنوب جميعا انه هو الغفور الرحيم","dt":"[53] قل -ايها الرسول- لعبادي الذين تمادوا في المعاصي، واسرفوا على انفسهم باتيان ما تدعوهم اليه نفوسهم من الذنوب: لا تيئسوا من رحمه الله؛ لكثره ذنوبكم، ان الله يغفر الذنوب جميعا لمن تاب منها ورجع عنها مهما كانت، انه هو الغفور لذنوب التائبين من عباده، الرحيم بهم."},{"id":"4112","s":39,"a":54,"at":"وانيبوا الى ربكم واسلموا له من قبل ان ياتيكم العذاب ثم لا تنصرون","dt":"[54] وارجعوا الى ربكم -ايها الناس- بالطاعه والتوبه، واخضعوا له من قبل ان يقع بكم عقابه، ثم لا ينصركم احد من دون الله."},{"id":"4113","s":39,"a":55,"at":"واتبعوا احسن ما انزل اليكم من ربكم من قبل ان ياتيكم العذاب بغته وانتم لا تشعرون","dt":"[55] واتبعوا احسن ما انزل اليكم من ربكم، وهو القران العظيم، وكله حسن، فامتثلوا اوامره، واجتنبوا نواهيه من قبل ان ياتيكم العذاب فجاه، وانتم لا تعلمون به."},{"id":"4114","s":39,"a":56,"at":"ان تقول نفس ياحسرتا على ما فرطت في جنب الله وان كنت لمن الساخرين","dt":"[56] واطيعوا ربكم وتوبوا اليه حتى لا تندم نفس وتقول: يا حسرتا على ما ضيعت في الدنيا من العمل بما امر الله به، وقصرت في طاعته وحقه، وان كنت في الدنيا لمن المستهزئين بامر الله وكتابه ورسوله والمؤمنين به."},{"id":"4115","s":39,"a":57,"at":"او تقول لو ان الله هداني لكنت من المتقين","dt":"[57] او تقول: لو ان الله ارشدني الى دينه لكنت من المتقين الشرك والمعاصي."},{"id":"4116","s":39,"a":58,"at":"او تقول حين ترى العذاب لو ان لي كره فاكون من المحسنين","dt":"[58] او تقول حين ترى عقاب الله قد احاط بها يوم الحساب: ليت لي رجعه الى الحياه الدنيا، فاكون فيها من الذين احسنوا بطاعه ربهم، والعمل بما امرتهم به الرسل."},{"id":"4117","s":39,"a":59,"at":"بلى قد جاءتك اياتي فكذبت بها واستكبرت وكنت من الكافرين","dt":"[59] ما القول كما تقول، قد جاءتك اياتي الواضحه الداله على الحق، فكذبت بها، واستكبرت عن قبولها واتباعها، وكنت من الكافرين بالله ورسله."},{"id":"4118","s":39,"a":60,"at":"ويوم القيامه ترى الذين كذبوا على الله وجوههم مسوده اليس في جهنم مثوى للمتكبرين","dt":"[60] ويوم القيامه ترى هؤلاء المكذبين الذين وصفوا ربهم بما لا يليق به، ونسبوا اليه الشريك والولد وجوههم مسوده. اليس في جهنم ماوى ومسكن لمن تكبر على الله، فامتنع من توحيده وطاعته؟ بلى."},{"id":"4119","s":39,"a":61,"at":"وينجي الله الذين اتقوا بمفازتهم لا يمسهم السوء ولا هم يحزنون","dt":"[61] وينجي الله من جهنم وعذابها الذين اتقوا ربهم باداء فرائضه واجتناب نواهيه بفوزهم وتحقق امنيتهم، وهي الظفر بالجنه، لا يمسهم من عذاب جهنم شيء، ولا هم يحزنون على ما فاتهم من حظوظ الدنيا."},{"id":"4120","s":39,"a":62,"at":"الله خالق كل شيء وهو على كل شيء وكيل","dt":"[62] الله تعالى هو خالق الاشياء كلها، وربها ومليكها والمتصرف فيها، وهو على كل شيء حفيظ يدبر جميع شؤون خلقه."},{"id":"4121","s":39,"a":63,"at":"له مقاليد السموات والارض والذين كفروا بايات الله اولئك هم الخاسرون","dt":"[63] لله مفاتيح خزائن السموات والارض، يعطي منها خلقه كيف يشاء. والذين جحدوا بايات القران وما فيها من الدلائل الواضحه، اولئك هم الخاسرون في الدنيا بخذلانهم عن الايمان، وفي الاخره بخلودهم في النار."},{"id":"4122","s":39,"a":64,"at":"قل افغير الله تامروني اعبد ايها الجاهلون","dt":"[64] قل -ايها الرسول- لمشركي قومك: افغير الله ايها الجاهلون بالله تامروني ان اعبد، ولا تصلح العباده لشيء سواه؟"},{"id":"4123","s":39,"a":65,"at":"ولقد اوحي اليك والى الذين من قبلك لئن اشركت ليحبطن عملك ولتكونن من الخاسرين","dt":"[65] ولقد اوحي اليك -ايها الرسول- والى من قبلك من الرسل: لئن اشركت بالله غيره ليبطلن عملك، ولتكونن من الهالكين الخاسرين دينك واخرتك؛ لانه لا يقبل مع الشرك عمل صالح."},{"id":"4124","s":39,"a":66,"at":"بل الله فاعبد وكن من الشاكرين","dt":"[66] بل الله فاعبد -ايها النبي- مخلصا له العباده وحده لا شريك له، وكن من الشاكرين لله نعمه."},{"id":"4125","s":39,"a":67,"at":"وما قدروا الله حق قدره والارض جميعا قبضته يوم القيامه والسموات مطويات بيمينه سبحانه وتعالى عما يشركون","dt":"[67] وما عظم هؤلاء المشركون الله حق تعظيمه؛ اذ عبدوا معه غيره مما لا ينفع ولا يضر، فسووا المخلوق مع عجزه بالخالق العظيم، الذي من عظيم قدرته ان جميع الارض في قبضته يوم القيامه، والسموات مطويات بيمينه، تنزه وتعاظم سبحانه وتعالى عما يشرك به هؤلاء المشركون. وفي الايه دليل على اثبات القبضه، واليمين، والطي، لله كما يليق بجلاله وعظمته، من غير تكييف ولا تشبيه."},{"id":"4126","s":39,"a":68,"at":"ونفخ في الصور فصعق من في السموات ومن في الارض الا من شاء الله ثم نفخ فيه اخرى فاذا هم قيام ينظرون","dt":"[68] ونفخ في «القرن» فمات كل من في السموات والارض، الا من شاء الله عدم موته، ثم نفخ الملك فيه نفخه ثانيه مؤذنا باحياء جميع الخلائق للحساب امام ربهم، فاذا هم قيام من قبورهم ينظرون ماذا يفعل الله بهم؟"},{"id":"4127","s":39,"a":69,"at":"واشرقت الارض بنور ربها ووضع الكتاب وجيء بالنبيين والشهداء وقضي بينهم بالحق وهم لا يظلمون","dt":"[69] واضاءت الارض يوم القيامه اذا تجلى الحق جل وعلا للخلائق لفصل القضاء، ونشرت الملائكه صحيفه كل فرد، وجيء بالنبيين والشهود على الامم؛ ليسال الله النبيين عن التبليغ وعما اجابتهم به اممهم، كما تاتي امه محمد -صلى الله عليه وسلم-؛ لتشهد بتبليغ الرسل السابقين لاممهم اذا انكرت هذا التبليغ، فتقوم الحجه على الامم، وقضى رب العالمين بين العباد بالعدل التام، وهم لا يظلمون شيئا بنقص ثواب او زياده عقاب."},{"id":"4128","s":39,"a":70,"at":"ووفيت كل نفس ما عملت وهو اعلم بما يفعلون","dt":"[70] ووفى الله كل نفس جزاء عملها من خير وشر، وهو سبحانه وتعالى اعلم بما يفعلون في الدنيا من طاعه او معصيه."},{"id":"4129","s":39,"a":71,"at":"وسيق الذين كفروا الى جهنم زمرا حتى اذا جاءوها فتحت ابوابها وقال لهم خزنتها الم ياتكم رسل منكم يتلون عليكم ايات ربكم وينذرونكم لقاء يومكم هذا قالوا بلى ولكن حقت كلمه العذاب على الكافرين","dt":"[71] وسيق الذين كفروا بالله ورسله الى جهنم جماعات، حتى اذا جاؤوها فتح الخزنه الموكلون بها ابوابها السبعه، وزجروهم قائلين: كيف تعصون الله وتجحدون انه الاله الحق وحده؟ الم يرسل اليكم رسلا منكم يتلون عليكم ايات ربكم، ويحذرونكم اهوال هذا اليوم؟ قالوا مقرين بذنبهم: بلى قد جاءت رسل ربنا بالحق، وحذرونا هذا اليوم، ولكن وجبت كلمه الله ان عذابه لاهل الكفر به."},{"id":"4130","s":39,"a":72,"at":"قيل ادخلوا ابواب جهنم خالدين فيها فبئس مثوى المتكبرين","dt":"[72] قيل للجاحدين ان الله هو الاله الحق اهانه لهم واذلالا: ادخلوا ابواب جهنم ماكثين فيها ابدا، فقبح مصير المتعالين على الايمان بالله والعمل بشرعه."},{"id":"4131","s":39,"a":73,"at":"وسيق الذين اتقوا ربهم الى الجنه زمرا حتى اذا جاءوها وفتحت ابوابها وقال لهم خزنتها سلام عليكم طبتم فادخلوها خالدين","dt":"[73] وسيق الذين اتقوا ربهم بتوحيده والعمل بطاعته الى الجنه جماعات، حتى اذا جاؤوها وشفع لهم بدخولها، فتحت ابوابها، فترحب بهم الملائكه الموكلون بالجنه، ويحيونهم بالبشر والسرور؛ لطهارتهم من اثار المعاصي قائلين لهم: سلام عليكم، وسلمتم من كل افه، طابت احوالكم، فادخلوا الجنه خالدين فيها."},{"id":"4132","s":39,"a":74,"at":"وقالوا الحمد لله الذي صدقنا وعده واورثنا الارض نتبوا من الجنه حيث نشاء فنعم اجر العاملين","dt":"[74] وقال المؤمنون: الحمد لله الذي صدقنا وعده الذي وعدنا اياه على السنه رسله، واورثنا ارض الجنه ننزل منها في اي مكان شئنا، فنعم ثواب المحسنين الذين اجتهدوا في طاعه ربهم."},{"id":"4133","s":39,"a":75,"at":"وترى الملائكه حافين من حول العرش يسبحون بحمد ربهم وقضي بينهم بالحق وقيل الحمد لله رب العالمين","dt":"[75] وترى -ايها النبي- الملائكه محيطين بعرش الرحمن، ينزهون ربهم عن كل ما لا يليق به، وقضى الله سبحانه وتعالى بين الخلائق بالحق والعدل، فاسكن اهل الايمان الجنه، واهل الكفر النار، وقيل: الحمد لله رب العالمين على ما قضى به بين اهل الجنه واهل النار، حمد فضل واحسان، وحمد عدل وحكمه."},{"id":"4134","s":40,"a":1,"at":"حم","dt":"[1] حم سبق الكلام على الحروف المقطعه في اول سوره البقره."},{"id":"4135","s":40,"a":2,"at":"تنزيل الكتاب من الله العزيز العليم","dt":"[2] تنزيل القران على النبي محمد -صلى الله عليه وسلم- من عند الله -عز وجل- العزيز الذي قهر بعزته كل مخلوق، العليم بكل شيء."},{"id":"4136","s":40,"a":3,"at":"غافر الذنب وقابل التوب شديد العقاب ذي الطول لا اله الا هو اليه المصير","dt":"[3] غافر الذنب للمذنبين، وقابل التوب من التائبين، شديد العقاب على من تجرا على الذنوب ولم يتب منها، وهو سبحانه وتعالى صاحب الانعام والتفضل على عباده الطائعين، لا معبود يستحق العباده سواه، اليه مصير جميع الخلائق يوم الحساب، فيجازي كلا بما يستحق."},{"id":"4137","s":40,"a":4,"at":"ما يجادل في ايات الله الا الذين كفروا فلا يغررك تقلبهم في البلاد","dt":"[4] ما يخاصم في ايات القران وادلته على وحدانيه الله، ويقابلها بالباطل الا الجاحدون الذين جحدوا انه الاله الحق المستحق للعباده وحده، فلا يغررك -ايها الرسول- ترددهم في البلاد بانواع التجارات والمكاسب، ونعيم الدنيا وزهرتها."},{"id":"4138","s":40,"a":5,"at":"كذبت قبلهم قوم نوح والاحزاب من بعدهم وهمت كل امه برسولهم لياخذوه وجادلوا بالباطل ليدحضوا به الحق فاخذتهم فكيف كان عقاب","dt":"[5] كذبت قبل هؤلاء الكفار قوم نوح ومن تلاهم من الامم التي اعلنت حربها على الرسل كعاد وثمود، حيث عزموا على ايذائهم وتجمعوا عليهم بالتعذيب او القتل، وهمت كل امه من هذه الامم المكذبه برسولهم ليقتلوه، وخاصموا بالباطل؛ ليبطلوا بجدالهم الحق فعاقبتهم، فكيف كان عقابي اياهم عبره للخلق، وعظه لمن ياتي بعدهم؟"},{"id":"4139","s":40,"a":6,"at":"وكذلك حقت كلمه ربك على الذين كفروا انهم اصحاب النار","dt":"[6] وكما حق العقاب على الامم السابقه التي كذبت رسلها، حق على الذين كفروا انهم اصحاب النار."},{"id":"4140","s":40,"a":7,"at":"الذين يحملون العرش ومن حوله يسبحون بحمد ربهم ويؤمنون به ويستغفرون للذين امنوا ربنا وسعت كل شيء رحمه وعلما فاغفر للذين تابوا واتبعوا سبيلك وقهم عذاب الجحيم","dt":"[7] الذين يحملون عرش الرحمن من الملائكه ومن حول العرش ممن يحف به منهم، ينزهون الله عن كل نقص، ويحمدونه بما هو اهل له، ويؤمنون به حق الايمان، ويطلبون منه ان يعفو عن المؤمنين، قائلين: ربنا وسعت كل شيء رحمه وعلما، فاغفر للذين تابوا من الشرك والمعاصي، وسلكوا الطريق الذي امرتهم ان يسلكوه وهو الاسلام، وجنبهم عذاب النار واهوالها."},{"id":"4141","s":40,"a":8,"at":"ربنا وادخلهم جنات عدن التي وعدتهم ومن صلح من ابائهم وازواجهم وذرياتهم انك انت العزيز الحكيم","dt":"[8] ربنا وادخل المؤمنين جنات عدن التي وعدتهم، ومن صلح بالايمان والعمل الصالح من ابائهم وازواجهم واولادهم. انك انت العزيز القاهر لكل شيء، الحكيم في تدبيره وصنعه."},{"id":"4142","s":40,"a":9,"at":"وقهم السيئات ومن تق السيئات يومئذ فقد رحمته وذلك هو الفوز العظيم","dt":"[9] واصرف عنهم سوء عاقبه سيئاتهم، فلا تؤاخذهم بها، ومن تصرف عنه السيئات يوم الحساب فقد رحمته، وانعمت عليه بالنجاه من عذابك، وذلك هو الظفر العظيم الذي لا فوز مثله."},{"id":"4143","s":40,"a":10,"at":"ان الذين كفروا ينادون لمقت الله اكبر من مقتكم انفسكم اذ تدعون الى الايمان فتكفرون","dt":"[10] ان الذين جحدوا ان الله هو الاله الحق، وصرفوا العباده لغيره عندما يعاينون اهوال النار بانفسهم، يمقتون انفسهم اشد المقت، وعند ذلك يناديهم خزنه جهنم: لمقت الله لكم في الدنيا -حين طلب منكم الايمان به واتباع رسله، فابيتم- اكبر من بغضكم لانفسكم الان، بعد ان ادركتم انكم تستحقون سخط الله وعذابه."},{"id":"4144","s":40,"a":11,"at":"قالوا ربنا امتنا اثنتين واحييتنا اثنتين فاعترفنا بذنوبنا فهل الى خروج من سبيل","dt":"[11] قال الكافرون: ربنا امتنا مرتين: حين كنا في بطون امهاتنا نطفا قبل نفخ الروح، وحين انقضى اجلنا في الحياه الدنيا، واحييتنا مرتين: في دار الدنيا يوم ولدنا، ويوم بعثنا من قبورنا، فنحن الان نقر باخطائنا السابقه، فهل لنا من طريق نخرج به من النار، وتعيدنا به الى الدنيا؛ لنعمل بطاعتك؟ ولكن هيهات ان ينفعهم هذا الاعتراف."},{"id":"4145","s":40,"a":12,"at":"ذلكم بانه اذا دعي الله وحده كفرتم وان يشرك به تؤمنوا فالحكم لله العلي الكبير","dt":"[12] ذلكم العذاب الذي لكم -ايها الكافرون- بسبب انكم كنتم اذا دعيتم لتوحيد الله واخلاص العمل له كفرتم به، وان يجعل لله شريك تصدقوا به وتتبعوه. فالله سبحانه وتعالى هو الحاكم في خلقه، العادل الذي لا يجور، يهدي من يشاء ويضل من يشاء، ويرحم من يشاء ويعذب من يشاء، لا اله الا هو الذي له علو الذات والقدر والقهر، وله الكبرياء والعظمه."},{"id":"4146","s":40,"a":13,"at":"هو الذي يريكم اياته وينزل لكم من السماء رزقا وما يتذكر الا من ينيب","dt":"[13] هو الذي يظهر لكم -ايها الناس- قدرته بما تشاهدونه من الايات العظيمه الداله على كمال خالقها ومبدعها، وينزل لكم من السماء مطرا ترزقون به، وما يتذكر بهذه الايات الا من يرجع الى طاعه الله، ويخلص له العباده."},{"id":"4147","s":40,"a":14,"at":"فادعوا الله مخلصين له الدين ولو كره الكافرون","dt":"[14] فاخلصوا -ايها المؤمنون- لله وحده العباده والدعاء، وخالفوا المشركين في مسلكهم، ولو اغضبهم ذلك، فلا تبالوا بهم."},{"id":"4148","s":40,"a":15,"at":"رفيع الدرجات ذو العرش يلقي الروح من امره على من يشاء من عباده لينذر يوم التلاق","dt":"[15] ان الله هو العلي الاعلى الذي ارتفعت درجاته ارتفاعا مختلفا عن مخلوقاته، وارتفع به قدره، وهو صاحب العرش العظيم، ومن رحمته بعباده ان يرسل اليهم رسلا يلقي اليهم الوحي الذي يحيون به، فيكونون على بصيره من امرهم؛ لتخوف الرسل عباد الله، وتنذرهم يوم القيامه الذي يلتقي فيه الاولون والاخرون."},{"id":"4149","s":40,"a":16,"at":"يوم هم بارزون لا يخفى على الله منهم شيء لمن الملك اليوم لله الواحد القهار","dt":"[16] يوم القيامه تظهر الخلائق امام ربهم، لا يخفى على الله منهم ولا من اعمالهم التي عملوها في الدنيا شيء، يقول الله سبحانه: لمن الملك والتصرف في هذا اليوم؟ فيجيب نفسه: لله المتفرد باسمائه وصفاته وافعاله، القهار الذي قهر جميع الخلائق بقدرته وعزته."},{"id":"4150","s":40,"a":17,"at":"اليوم تجزى كل نفس بما كسبت لا ظلم اليوم ان الله سريع الحساب","dt":"[17] اليوم تثاب كل نفس بما كسبت في الدنيا من خير وشر، لا ظلم لاحد اليوم بزياده في سيئاته او نقص من حسناته. ان الله سبحانه وتعالى سريع الحساب، فلا تستبطئوا ذلك اليوم؛ فانه قريب."},{"id":"4151","s":40,"a":18,"at":"وانذرهم يوم الازفه اذ القلوب لدى الحناجر كاظمين ما للظالمين من حميم ولا شفيع يطاع","dt":"[18] وحذر -ايها الرسول- الناس من يوم القيامه القريب، وان استبعدوه، اذ قلوب العباد من مخافه عقاب الله قد ارتفعت من صدورهم، فتعلقت بحلوقهم، وهم ممتلئون غما وحزنا. ما للظالمين من قريب ولا صاحب، ولا شفيع يشفع لهم عند ربهم، فيستجاب له."},{"id":"4152","s":40,"a":19,"at":"يعلم خائنه الاعين وما تخفي الصدور","dt":"[19] يعلم الله سبحانه ما تختلسه العيون من نظرات، وما يضمره الانسان في نفسه من خير او شر."},{"id":"4153","s":40,"a":20,"at":"والله يقضي بالحق والذين يدعون من دونه لا يقضون بشيء ان الله هو السميع البصير","dt":"[20] والله سبحانه يقضي بين الناس بالعدل فيما يستحقونه، والذين يعبدون من دون الله من الالهه لا يقضون بشيء؛ لعجزهم عن ذلك. ان الله هو السميع لاقوال خلقه، البصير بافعالهم واعمالهم، وسيجازيهم عليها."},{"id":"4154","s":40,"a":21,"at":"او لم يسيروا في الارض فينظروا كيف كان عاقبه الذين كانوا من قبلهم كانوا هم اشد منهم قوه واثارا في الارض فاخذهم الله بذنوبهم وما كان لهم من الله من واق","dt":"[21] او لم يسر هؤلاء المكذبون برسالتك -ايها الرسول- في الارض، فينظروا كيف كان خاتمه الامم السابقه قبلهم؟ كانوا اشد منهم بطشا، وابقى في الارض اثارا، فلم تنفعهم شده قواهم وعظم اجسامهم، فاخذهم الله بعقوبته؛ بسبب كفرهم واكتسابهم الاثام، وما كان لهم من عذاب الله من واق يقيهم منه، فيدفعه عنهم."},{"id":"4155","s":40,"a":22,"at":"ذلك بانهم كانت تاتيهم رسلهم بالبينات فكفروا فاخذهم الله انه قوي شديد العقاب","dt":"[22] ذلك العذاب الذي حل بالمكذبين السابقين، كان بسبب موقفهم من رسل الله الذين جاؤوا بالدلائل القاطعه على صدق دعواهم، فكفروا بهم وكذبوهم، فاخذهم الله بعقابه، انه سبحانه قوي لا يغلبه احد، شديد العقاب لمن كفر به وعصاه."},{"id":"4156","s":40,"a":23,"at":"ولقد ارسلنا موسى باياتنا وسلطان مبين","dt":"[23] ولقد ارسلنا موسى باياتنا العظيمه الداله على حقيقه ما ارسل به، وحجه واضحه بينه على صدقه في دعوته، وبطلان ما كان عليه من ارسل اليهم."},{"id":"4157","s":40,"a":24,"at":"الى فرعون وهامان وقارون فقالوا ساحر كذاب","dt":"[24] الى فرعون ملك «مصر»، وهامان وزيره، وقارون صاحب الاموال والكنوز، فانكروا رسالته واستكبروا، وقالوا عنه: انه ساحر كذاب، فكيف يزعم انه ارسل للناس رسولا؟"},{"id":"4158","s":40,"a":25,"at":"فلما جاءهم بالحق من عندنا قالوا اقتلوا ابناء الذين امنوا معه واستحيوا نساءهم وما كيد الكافرين الا في ضلال","dt":"[25] فلما جاء موسى فرعون وهامان وقارون بالمعجزات الظاهره من عندنا، لم يكتفوا بمعارضتها وانكارها، بل قالوا: اقتلوا ابناء الذين امنوا معه، واستبقوا نساءهم للخدمه والاسترقاق. وما تدبير اهل الكفر الا في ذهاب وهلاك."},{"id":"4159","s":40,"a":26,"at":"وقال فرعون ذروني اقتل موسى وليدع ربه اني اخاف ان يبدل دينكم او ان يظهر في الارض الفساد","dt":"[26] وقال فرعون لاشراف قومه: اتركوني اقتل موسى، وليدع ربه الذي يزعم انه ارسله الينا، فيمنعه منا، اني اخاف ان يبدل دينكم الذي انتم عليه، او ان يظهر في ارض «مصر» الفساد."},{"id":"4160","s":40,"a":27,"at":"وقال موسى اني عذت بربي وربكم من كل متكبر لا يؤمن بيوم الحساب","dt":"[27] وقال موسى لفرعون وملئه: اني استجرت بربي وربكم -ايها القوم- من كل مستكبر عن توحيد الله وطاعته، لا يؤمن بيوم يحاسب الله فيه خلقه."},{"id":"4161","s":40,"a":28,"at":"وقال رجل مؤمن من ال فرعون يكتم ايمانه اتقتلون رجلا ان يقول ربي الله وقد جاءكم بالبينات من ربكم وان يك كاذبا فعليه كذبه وان يك صادقا يصبكم بعض الذي يعدكم ان الله لا يهدي من هو مسرف كذاب","dt":"[28] وقال رجل مؤمن بالله من ال فرعون، يكتم ايمانه منكرا على قومه: كيف تستحلون قتل رجل لا جرم له عندكم الا ان يقول ربي الله، وقد جاءكم بالبراهين القاطعه من ربكم على صدق ما يقول؟ وان يك موسى كاذبا فان وبال كذبه عائد عليه وحده، وان يك صادقا لحقكم بعض الذي يتوعدكم به، ان الله لا يوفق للحق من هو متجاوز للحد، بترك الحق والاقبال على الباطل، كذاب بنسبته ما اسرف فيه الى الله."},{"id":"4162","s":40,"a":29,"at":"ياقوم لكم الملك اليوم ظاهرين في الارض فمن ينصرنا من باس الله ان جاءنا قال فرعون ما اريكم الا ما ارى وما اهديكم الا سبيل الرشاد","dt":"[29] يا قوم لكم السلطان اليوم ظاهرين في ارض «مصر» على رعيتكم من بني اسرائيل وغيرهم، فمن يدفع عنا عذاب الله ان حل بنا؟ قال فرعون لقومه مجيبا: ما اريكم -ايها الناس- من الراي والنصيحه الا ما ارى لنفسي ولكم صلاحا وصوابا، وما ادعوكم الا الى طريق الحق والصواب."},{"id":"4163","s":40,"a":30,"at":"وقال الذي امن ياقوم اني اخاف عليكم مثل يوم الاحزاب","dt":"[30] وقال الرجل المؤمن من ال فرعون لفرعون وملئه واعظا ومحذرا: اني اخاف عليكم ان قتلتم موسى، مثل يوم الاحزاب الذين تحزبوا على انبيائهم."},{"id":"4164","s":40,"a":31,"at":"مثل داب قوم نوح وعاد وثمود والذين من بعدهم وما الله يريد ظلما للعباد","dt":"[31] مثل عاده قوم نوح وعاد وثمود ومن جاء بعدهم في الكفر والتكذيب، اهلكهم الله بسبب ذلك. وما الله سبحانه يريد ظلما للعباد، فيعذبهم بغير ذنب اذنبوه. تعالى الله عن الظلم والنقص علوا كبيرا."},{"id":"4165","s":40,"a":32,"at":"وياقوم اني اخاف عليكم يوم التناد","dt":"[32] ويا قوم اني اخاف عليكم عقاب يوم القيامه، يوم ينادي فيه بعض الناس بعضا؛ من هول الموقف في ذلك اليوم."},{"id":"4166","s":40,"a":33,"at":"يوم تولون مدبرين ما لكم من الله من عاصم ومن يضلل الله فما له من هاد","dt":"[33] يوم تولون ذاهبين هاربين، ما لكم من الله من مانع يمنعكم وناصر ينصركم. ومن يخذله الله ولم يوفقه الى رشده، فما له من هاد يهديه الى الحق والصواب."},{"id":"4167","s":40,"a":34,"at":"ولقد جاءكم يوسف من قبل بالبينات فما زلتم في شك مما جاءكم به حتى اذا هلك قلتم لن يبعث الله من بعده رسولا كذلك يضل الله من هو مسرف مرتاب","dt":"[34] ولقد ارسل الله اليكم النبي الكريم يوسف بن يعقوب عليهما السلام من قبل موسى، بالدلائل الواضحه على صدقه، وامركم بعباده الله وحده لا شريك له، فما زلتم مرتابين مما جاءكم به في حياته، حتى اذا مات ازداد شككم وشرككم، وقلتم: ان الله لن يرسل من بعده رسولا، مثل ذلك الضلال يضل الله كل متجاوز للحق، شاك في وحدانيه الله تعالى، فلا يوفقه الى الهدى والرشاد."},{"id":"4168","s":40,"a":35,"at":"الذين يجادلون في ايات الله بغير سلطان اتاهم كبر مقتا عند الله وعند الذين امنوا كذلك يطبع الله على كل قلب متكبر جبار","dt":"[35] الذين يخاصمون في ايات الله وحججه لدفعها من غير ان يكون لديهم حجه مقبوله، كبر ذلك الجدال مقتا عند الله وعند الذين امنوا، كما ختم بالضلال وحجب عن الهدى قلوب هؤلاء المخاصمين، يختم الله على قلب كل مستكبر عن توحيد الله وطاعته، جبار بكثره ظلمه وعدوانه."},{"id":"4169","s":40,"a":36,"at":"وقال فرعون ياهامان ابن لي صرحا لعلي ابلغ الاسباب","dt":"[36] وقال فرعون مكذبا لموسى في دعوته الى الاقرار برب العالمين والتسليم له: يا هامان ابن لي بناء عظيما؛ لعلي ابلغ ابواب السموات."},{"id":"4170","s":40,"a":37,"at":"اسباب السموات فاطلع الى اله موسى واني لاظنه كاذبا وكذلك زين لفرعون سوء عمله وصد عن السبيل وما كيد فرعون الا في تباب","dt":"[37] وما يوصلني اليها، فانظر الى اله موسى بنفسي، واني لاظن موسى كاذبا في دعواه ان لنا ربا، وانه فوق السموات، وهكذا زين لفرعون عمله السيئ فراه حسنا، وصد عن سبيل الحق؛ بسبب الباطل الذي زين له، وما احتيال فرعون وتدبيره لايهام الناس انه محق، وموسى مبطل الا في خسار وبوار، لا يفيده الا الشقاء في الدنيا والاخره."},{"id":"4171","s":40,"a":38,"at":"وقال الذي امن ياقوم اتبعون اهدكم سبيل الرشاد","dt":"[38] وقال الذي امن معيدا نصيحته لقومه: يا قوم اتبعون اهدكم طريق الرشد والصواب."},{"id":"4172","s":40,"a":39,"at":"ياقوم انما هذه الحياه الدنيا متاع وان الاخره هي دار القرار","dt":"[39] يا قوم ان هذه الحياه الدنيا حياه يتنعم الناس فيها قليلا، ثم تنقطع وتزول، فينبغي الا تركنوا اليها، وان الدار الاخره بما فيها من النعيم المقيم هي محل الاقامه التي تستقرون فيها، فينبغي لكم ان تؤثروها، وتعملوا لها العمل الصالح الذي يسعدكم فيها."},{"id":"4173","s":40,"a":40,"at":"من عمل سيئه فلا يجزى الا مثلها ومن عمل صالحا من ذكر او انثى وهو مؤمن فاولئك يدخلون الجنه يرزقون فيها بغير حساب","dt":"[40] من عصى الله في حياته وانحرف عن طريق الهدى، فلا يجزى في الاخره الا عقابا يساوي معصيته، ومن اطاع الله وعمل صالحا بامتثال اوامره واجتناب نواهيه، ذكرا كان او انثى، وهو مؤمن بالله موحد له، فاولئك يدخلون الجنه، يرزقهم الله فيها من ثمارها ونعيمها ولذاتها بغير حساب."},{"id":"4174","s":40,"a":41,"at":"وياقوم ما لي ادعوكم الى النجاه وتدعونني الى النار","dt":"[41] ويا قوم كيف ادعوكم الى الايمان بالله واتباع رسوله موسى، وهي دعوه تنتهي بكم الى الجنه والبعد عن اهوال النار، وانتم تدعونني الى عمل يؤدي الى عذاب الله وعقوبته في النار؟"},{"id":"4175","s":40,"a":42,"at":"تدعونني لاكفر بالله واشرك به ما ليس لي به علم وانا ادعوكم الى العزيز الغفار","dt":"[42] تدعونني لاكفر بالله، واشرك به ما ليس لي به علم انه يستحق العباده من دونه -وهذا من اكبر الذنوب واقبحها- وانا ادعوكم الى الطريق الموصل الى الله العزيز في انتقامه، الغفار لمن تاب اليه بعد معصيته."},{"id":"4176","s":40,"a":43,"at":"لا جرم انما تدعونني اليه ليس له دعوه في الدنيا ولا في الاخره وان مردنا الى الله وان المسرفين هم اصحاب النار","dt":"[43] حقا ان ما تدعونني الى الاعتقاد به لا يستحق الدعوه اليه، ولا يلجا اليه في الدنيا ولا في الاخره لعجزه ونقصه، واعلموا ان مصير الخلائق كلها الى الله سبحانه، وهو يجازي كل عامل بعمله، وان الذين تعدوا حدوده بالمعاصي وسفك الدماء والكفر هم اهل النار."},{"id":"4177","s":40,"a":44,"at":"فستذكرون ما اقول لكم وافوض امري الى الله ان الله بصير بالعباد","dt":"[44] فلما نصحهم ولم يطيعوه قال لهم: فستذكرون اني نصحت لكم وذكرتكم، وسوف تندمون حيث لا ينفع الندم، والجا الى الله، واعتصم به، واتوكل عليه. ان الله سبحانه وتعالى بصير باحوال العباد، وما يستحقونه من جزاء، لا يخفى عليه شيء منها."},{"id":"4178","s":40,"a":45,"at":"فوقاه الله سيئات ما مكروا وحاق بال فرعون سوء العذاب","dt":"[45] فوقى الله سبحانه ذلك الرجل المؤمن الموفق عقوبات مكر فرعون واله، وحل بهم سوء العذاب حيث اغرقهم الله عن اخرهم."},{"id":"4179","s":40,"a":46,"at":"النار يعرضون عليها غدوا وعشيا ويوم تقوم الساعه ادخلوا ال فرعون اشد العذاب","dt":"[46] لقد اصابهم الغرق اولا وهلكوا، ثم يعذبون في قبورهم حيث النار، يعرضون عليها صباحا ومساء الى وقت الحساب، ويوم تقوم الساعه يقال: ادخلوا ال فرعون النار؛ جزاء ما اقترفوه من اعمال السوء. وهذه الايه اصل في اثبات عذاب القبر."},{"id":"4180","s":40,"a":47,"at":"واذ يتحاجون في النار فيقول الضعفاء للذين استكبروا انا كنا لكم تبعا فهل انتم مغنون عنا نصيبا من النار","dt":"[47] واذ يتخاصم اهل النار، ويعاتب بعضهم بعضا، فيحتج الاتباع المقلدون على رؤسائهم المستكبرين الذين اضلوهم، وزينوا لهم طريق الشقاء، قائلين لهم: هل انتم مغنون عنا نصيبا من النار بتحملكم قسطا من عذابنا؟"},{"id":"4181","s":40,"a":48,"at":"قال الذين استكبروا انا كل فيها ان الله قد حكم بين العباد","dt":"[48] قال الرؤساء المستكبرون مبينين عجزهم: لا نتحمل عنكم شيئا من عذاب النار، وكلنا فيها، لا خلاص لنا منها، ان الله قد قسم بيننا العذاب بقدر ما يستحق كل منا بقضائه العادل."},{"id":"4182","s":40,"a":49,"at":"وقال الذين في النار لخزنه جهنم ادعوا ربكم يخفف عنا يوما من العذاب","dt":"[49] وقال الذين في النار من المستكبرين والضعفاء لخزنه جهنم: ادعوا ربكم يخفف عنا يوما واحدا من العذاب؛ كي تحصل لنا بعض الراحه."},{"id":"4183","s":40,"a":50,"at":"قالوا او لم تك تاتيكم رسلكم بالبينات قالوا بلى قالوا فادعوا وما دعاء الكافرين الا في ضلال","dt":"[50] قال خزنه جهنم لهم توبيخا: هذا الدعاء لا ينفعكم في شيء، اولم تاتكم رسلكم بالحجج الواضحه من الله فكذبتموهم؟ فاعترف الجاحدون بذلك وقالوا: بلى. فتبرا خزنه جهنم منهم وقالوا: نحن لا ندعو لكم، ولا نشفع فيكم، فادعوا انتم، ولكن هذا الدعاء لا يغني شيئا؛ لانكم كافرون. وما دعاء الكافرين الا في ضياع لا يقبل، ولا يستجاب."},{"id":"4184","s":40,"a":51,"at":"انا لننصر رسلنا والذين امنوا في الحياه الدنيا ويوم يقوم الاشهاد","dt":"[51] انا لننصر رسلنا ومن تبعهم من المؤمنين، ونؤيدهم على من اذاهم في حياتهم الدنيا، ويوم القيامه، يوم تشهد فيه الملائكه والانبياء والمؤمنون على الامم التي كذبت رسلها، فتشهد بان الرسل قد بلغوا رسالات ربهم، وان الامم كذبتهم."},{"id":"4185","s":40,"a":52,"at":"يوم لا ينفع الظالمين معذرتهم ولهم اللعنه ولهم سوء الدار","dt":"[52] يوم الحساب لا ينتفع الكافرون الذين تعدوا حدود الله بما يقدمونه من عذر لتكذيبهم رسل الله، ولهم الطرد من رحمه الله، ولهم الدار السيئه في الاخره، وهي النار."},{"id":"4186","s":40,"a":53,"at":"ولقد اتينا موسى الهدى واورثنا بني اسرائيل الكتاب","dt":"[53] ولقد اتينا موسى ما يهدي الى الحق من التوراه والمعجزات، وجعلنا بني اسرائيل يتوارثون التوراه خلفا عن سلف،"},{"id":"4187","s":40,"a":54,"at":"هدى وذكرى لاولي الالباب","dt":"[54] هاديه الى سبيل الرشاد، وموعظه لاصحاب العقول السليمه."},{"id":"4188","s":40,"a":55,"at":"فاصبر ان وعد الله حق واستغفر لذنبك وسبح بحمد ربك بالعشي والابكار","dt":"[55] فاصبر -ايها الرسول- على اذى المشركين، فقد وعدناك باعلاء كلمتك، ووعدنا حق لا يخلف، واستغفر لذنبك، ودم على تنزيه ربك عما لا يليق به، في اخر النهار واوله."},{"id":"4189","s":40,"a":56,"at":"ان الذين يجادلون في ايات الله بغير سلطان اتاهم ان في صدورهم الا كبر ما هم ببالغيه فاستعذ بالله انه هو السميع البصير","dt":"[56] ان الذين يدفعون الحق بالباطل، ويردون الحجج الصحيحه بالشبه الفاسده بلا برهان ولا حجه من الله، ليس في صدور هؤلاء الا تكبر عن الحق؛ حسدا منهم على الفضل الذي اتاه الله نبيه، وكرامه النبوه التي اكرمه بها، وهو امر ليسوا بمدركيه ولا نائليه، فاعتصم بالله من شرهم؛ انه هو السميع لاقوالهم، البصير بافعالهم، وسيجازيهم عليها."},{"id":"4190","s":40,"a":57,"at":"لخلق السموات والارض اكبر من خلق الناس ولكن اكثر الناس لا يعلمون","dt":"[57] لخلق الله السموات والارض اكبر من خلق الناس واعادتهم بعد موتهم، ولكن اكثر الناس لا يعلمون ان خلق جميع ذلك هين على الله."},{"id":"4191","s":40,"a":58,"at":"وما يستوي الاعمى والبصير والذين امنوا وعملوا الصالحات ولا المسيء قليلا ما تتذكرون","dt":"[58] وما يستوي الاعمى والبصير، وكذلك لا يستوي المؤمنون الذين يقرون بان الله هو الاله الحق لا شريك له، ويستجيبون لرسله ويعملون بشرعه، والجاحدون الذين ينكرون ان الله هو الاله الحق، ويكذبون رسله، ولا يعملون بشرعه. قليلا ما تتذكرون -ايها الناس- حجج الله، فتعتبرون، وتتعظون بها."},{"id":"4192","s":40,"a":59,"at":"ان الساعه لاتيه لا ريب فيها ولكن اكثر الناس لا يؤمنون","dt":"[59] ان الساعه لاتيه لا شك فيها، فايقنوا بمجيئها، كما اخبرت بذلك الرسل، ولكن اكثر الناس لا يصدقون بمجيئها، ولا يعملون لها."},{"id":"4193","s":40,"a":60,"at":"وقال ربكم ادعوني استجب لكم ان الذين يستكبرون عن عبادتي سيدخلون جهنم داخرين","dt":"[60] وقال ربكم -ايها العباد-: ادعوني وحدي وخصوني بالعباده استجب لكم، ان الذين يتكبرون عن افرادي بالعبوديه والالوهيه، سيدخلون جهنم صاغرين حقيرين."},{"id":"4194","s":40,"a":61,"at":"الله الذي جعل لكم الليل لتسكنوا فيه والنهار مبصرا ان الله لذو فضل على الناس ولكن اكثر الناس لا يشكرون","dt":"[61] الله وحده هو الذي جعل لكم الليل؛ لتسكنوا فيه وتحققوا راحتكم، والنهار مضيئا؛ لتصرفوا فيه امور معاشكم. ان الله لذو فضل عظيم على الناس، ولكن اكثرهم لا يشكرون له بالطاعه واخلاص العباده."},{"id":"4195","s":40,"a":62,"at":"ذلكم الله ربكم خالق كل شيء لا اله الا هو فانى تؤفكون","dt":"[62] الذي انعم عليكم بهذه النعم انما هو ربكم خالق الاشياء كلها، لا اله يستحق العباده غيره، فكيف تعدلون عن الايمان به، وتعبدون غيره من الاوثان، بعد ان تبينت لكم دلائله؟"},{"id":"4196","s":40,"a":63,"at":"كذلك يؤفك الذين كانوا بايات الله يجحدون","dt":"[63] كما كذبتم بالحق –يا كفار قريش- واعرضتم عنه الى الباطل، يصرف عن الحق والايمان به الذين كانوا بحجج الله وادلته يجحدون."},{"id":"4197","s":40,"a":64,"at":"الله الذي جعل لكم الارض قرارا والسماء بناء وصوركم فاحسن صوركم ورزقكم من الطيبات ذلكم الله ربكم فتبارك الله رب العالمين","dt":"[64] الله الذي جعل لكم الارض؛ لتستقروا فيها، ويسر لكم الاقامه عليها، وجعل السماء سقفا للارض، وبث فيها من العلامات الهاديه، وخلقكم في اكمل هيئه واحسن تقويم، وانعم عليكم بحلال الرزق ولذيذ المطاعم والمشارب، ذلكم الذي انعم عليكم بهذه النعم هو ربكم، فتكاثر خيره وفضله وبركته، وتنزه عما لا يليق به، وهو رب الخلائق اجمعين."},{"id":"4198","s":40,"a":65,"at":"هو الحي لا اله الا هو فادعوه مخلصين له الدين الحمد لله رب العالمين","dt":"[65] هو الله سبحانه الحي الذي له الحياه الكامله التامه لا اله غيره، فاسالوه واصرفوا عبادتكم له وحده، مخلصين له دينكم وطاعتكم. فالحمد لله والثناء الكامل له رب الخلائق اجمعين."},{"id":"4199","s":40,"a":66,"at":"قل اني نهيت ان اعبد الذين تدعون من دون الله لما جاءني البينات من ربي وامرت ان اسلم لرب العالمين","dt":"[66] قل -ايها الرسول- لمشركي قومك: اني نهيت ان اعبد الذين تدعون من دون الله، لما جاءني الايات الواضحات من عند ربي، وامرني ان اخضع وانقاد بالطاعه التامه له، سبحانه رب العالمين."},{"id":"4200","s":40,"a":67,"at":"هو الذي خلقكم من تراب ثم من نطفه ثم من علقه ثم يخرجكم طفلا ثم لتبلغوا اشدكم ثم لتكونوا شيوخا ومنكم من يتوفى من قبل ولتبلغوا اجلا مسمى ولعلكم تعقلون","dt":"[67] هو الله الذي خلق اباكم ادم من تراب، ثم اوجدكم من المني بقدرته، وبعد ذلك تنتقلون الى طور الدم الغليظ الاحمر، ثم تجري عليكم اطوار متعدده في الارحام، الى ان تولدوا اطفالا صغارا، ثم تقوى بنيتكم الى ان تصيروا شيوخا، ومنكم من يموت قبل ذلك، ولتبلغوا بهذه الاطوار المقدره اجلا مسمى تنتهي عنده اعماركم، ولعلكم تعقلون حجج الله عليكم بذلك، وتتدبرون اياته، فتعرفون انه لا اله غيره يفعل ذلك، وانه الذي لا تنبغي العباده الا له."},{"id":"4201","s":40,"a":68,"at":"هو الذي يحيي ويميت فاذا قضى امرا فانما يقول له كن فيكون","dt":"[68] هو سبحانه المتفرد بالاحياء والاماته، فاذا قضى امرا فانما يقول له: «كن»، فيكون، لا راد لقضائه."},{"id":"4202","s":40,"a":69,"at":"الم تر الى الذين يجادلون في ايات الله انى يصرفون","dt":"[69] الا تعجب -ايها الرسول- من هؤلاء المكذبين بايات الله يخاصمون فيها، وهي واضحه الدلاله على توحيد الله وقدرته، كيف يعدلون عنها مع صحتها؟ والى اي شيء يذهبون بعد البيان التام؟"},{"id":"4203","s":40,"a":70,"at":"الذين كذبوا بالكتاب وبما ارسلنا به رسلنا فسوف يعلمون","dt":"[70] هؤلاء المشركون الذين كذبوا بالقران والكتب السماويه التي انزلها الله على رسله لهدايه الناس، فسوف يعلم هؤلاء المكذبون عاقبه تكذيبهم"},{"id":"4204","s":40,"a":71,"at":"اذ الاغلال في اعناقهم والسلاسل يسحبون","dt":"[71] حين تجعل الاغلال في اعناقهم، والسلاسل في ارجلهم، وتسحبهم زبانيه العذاب"},{"id":"4205","s":40,"a":72,"at":"في الحميم ثم في النار يسجرون","dt":"[72] في الماء الحار الذي اشتد غليانه وحره، ثم في نار جهنم يوقد بهم."},{"id":"4206","s":40,"a":73,"at":"ثم قيل لهم اين ما كنتم تشركون","dt":"[73] ثم قيل لهم توبيخا، وهم في هذه الحال التعيسه: اين الالهه التي كنتم تعبدونها"},{"id":"4207","s":40,"a":74,"at":"من دون الله قالوا ضلوا عنا بل لم نكن ندعوا من قبل شيئا كذلك يضل الله الكافرين","dt":"[74] من دون الله؟ هل ينصرونكم اليوم؟ فادعوهم؛ لينقذوكم من هذا البلاء الذي حل بكم ان استطاعوا، قال المكذبون: غابوا عن عيوننا، فلم ينفعونا بشيء، ويعترفون بانهم كانوا في جهاله من امرهم، وان عبادتهم لهم كانت باطله لا تساوي شيئا، كما اضل الله هؤلاء الذين ضل عنهم في جهنم ما كانوا يعبدون في الدنيا من دون الله، يضل الله الكافرين به."},{"id":"4208","s":40,"a":75,"at":"ذلكم بما كنتم تفرحون في الارض بغير الحق وبما كنتم تمرحون","dt":"[75] ذلكم العذاب الذي اصابكم انما هو بسبب ما كنتم عليه في حياتكم الدنيا من غفله، حيث كنتم تفرحون بما تقترفونه من المعاصي والاثام، وبما انتم عليه من الاشر والبطر والبغي على عباد الله."},{"id":"4209","s":40,"a":76,"at":"ادخلوا ابواب جهنم خالدين فيها فبئس مثوى المتكبرين","dt":"[76] ادخلوا ابواب جهنم عقوبه لكم على كفركم بالله ومعصيتكم له خالدين فيها، فبئست جهنم نزلا للمتكبرين في الدنيا على الله."},{"id":"4210","s":40,"a":77,"at":"فاصبر ان وعد الله حق فاما نرينك بعض الذي نعدهم او نتوفينك فالينا يرجعون","dt":"[77] فاصبر -ايها الرسول-، وامض في طريق الدعوه، ان وعد الله حق، وسينجز لك ما وعدك، فاما نرينك في حياتك بعض الذي نعد هؤلاء المشركين من العذاب، او نتوفينك قبل ان يحل ذلك بهم، فالينا مصيرهم يوم القيامه، وسنذيقهم العذاب الشديد بما كانوا يكفرون."},{"id":"4211","s":40,"a":78,"at":"ولقد ارسلنا رسلا من قبلك منهم من قصصنا عليك ومنهم من لم نقصص عليك وما كان لرسول ان ياتي بايه الا باذن الله فاذا جاء امر الله قضي بالحق وخسر هنالك المبطلون","dt":"[78] ولقد ارسلنا من قبلك -ايها الرسول- رسلا كثيرين الى قومهم يدعونهم، ويصبرون على اذاهم: منهم من قصصنا عليك خبرهم، ومنهم من لم نقصص عليك، وكلهم مامورون بتبليغ وحي الله اليهم. وما كان لاحد منهم ان ياتي بايه من الايات الحسيه او العقليه الا باذن الله ومشيئته، فاذا جاء امر الله بعذاب المكذبين قضي بالعدل بين الرسل ومكذبيهم، وخسر هنالك المبطلون؛ لافترائهم على الله الكذب، وعبادتهم غيره."},{"id":"4212","s":40,"a":79,"at":"الله الذي جعل لكم الانعام لتركبوا منها ومنها تاكلون","dt":"[79] الله سبحانه هو الذي جعل لكم الانعام؛ لتنتفعوا بها: من منافع الركوب والاكل"},{"id":"4213","s":40,"a":80,"at":"ولكم فيها منافع ولتبلغوا عليها حاجه في صدوركم وعليها وعلى الفلك تحملون","dt":"[80] وغيرها من انواع المنافع، ولتبلغوا بالحموله على بعضها حاجه في صدوركم من الوصول الى الاقطار البعيده، وعلى هذه الانعام تحملون في البر، وعلى السفن في البحر تحملون كذلك."},{"id":"4214","s":40,"a":81,"at":"ويريكم اياته فاي ايات الله تنكرون","dt":"[81] ويريكم الله تعالى دلائله الكثيره الواضحه الداله على قدرته وتدبيره في خلقه، فاي ايه من اياته تنكرونها، ولا تعترفون بها؟"},{"id":"4215","s":40,"a":82,"at":"افلم يسيروا في الارض فينظروا كيف كان عاقبه الذين من قبلهم كانوا اكثر منهم واشد قوه واثارا في الارض فما اغنى عنهم ما كانوا يكسبون","dt":"[82] افلم يسر هؤلاء المكذبون في الارض ويتفكروا في مصارع الامم المكذبه من قبلهم، كيف كانت عاقبتهم؟ وكانت هذه الامم السابقه اكثر منهم عددا وعده واثارا في الارض من الابنيه والمصانع والغراس وغير ذلك، فما اغنى عنهم ما كانوا يكسبونه حين حل بهم باس الله."},{"id":"4216","s":40,"a":83,"at":"فلما جاءتهم رسلهم بالبينات فرحوا بما عندهم من العلم وحاق بهم ما كانوا به يستهزئون","dt":"[83] فلما جاءت هؤلاء الامم المكذبه رسلها بالدلائل الواضحات، فرحوا جهلا منهم بما عندهم من العلم المناقض لما جاءت به الرسل، وحل بهم من العذاب ما كانوا يستعجلون به رسلهم على سبيل السخريه والاستهزاء. وفي الايه دليل على ان كل علم يناقض الاسلام، او يقدح فيه، او يشكك في صحته، فانه مذموم ممقوت، ومعتقده ليس من اتباع محمد -صلى الله عليه وسلم-."},{"id":"4217","s":40,"a":84,"at":"فلما راوا باسنا قالوا امنا بالله وحده وكفرنا بما كنا به مشركين","dt":"[84] فلما راوا عذابنا اقروا حين لا ينفع الاقرار، وقالوا: امنا بالله وحده، وكفرنا بما كنا به مشركين في عباده الله."},{"id":"4218","s":40,"a":85,"at":"فلم يك ينفعهم ايمانهم لما راوا باسنا سنه الله التي قد خلت في عباده وخسر هنالك الكافرون","dt":"[85] فلم يك ينفعهم ايمانهم هذا حين راوا عذابنا؛ وذلك لانه ايمان قد اضطروا اليه، لا ايمان اختيار ورغبه، سنه الله وطريقته التي سنها في الامم كلها الا ينفعها الايمان اذا راوا العذاب، وهلك عند مجيء باس الله الكافرون بربهم، الجاحدون توحيده وطاعته."},{"id":"4219","s":41,"a":1,"at":"حم","dt":"[1] حم سبق الكلام على الحروف المقطعه في اول سوره البقره."},{"id":"4220","s":41,"a":2,"at":"تنزيل من الرحمن الرحيم","dt":"[2] هذا القران الكريم تنزيل من الرحمن الرحيم، نزله على نبيه محمد -صلى الله عليه وسلم-."},{"id":"4221","s":41,"a":3,"at":"كتاب فصلت اياته قرانا عربيا لقوم يعلمون","dt":"[3] كتاب بينت اياته تمام البيان، ووضحت معانيه واحكامه، قرانا عربيا ميسرا فهمه لقوم يعلمون اللسان العربي."},{"id":"4222","s":41,"a":4,"at":"بشيرا ونذيرا فاعرض اكثرهم فهم لا يسمعون","dt":"[4] بشيرا بالثواب العاجل والاجل لمن امن به وعمل بمقتضاه، ونذيرا بالعقاب العاجل والاجل لمن كفر به، فاعرض عنه اكثر الناس، فهم لا يسمعون له سماع قبول واجابه."},{"id":"4223","s":41,"a":5,"at":"وقالوا قلوبنا في اكنه مما تدعونا اليه وفي اذاننا وقر ومن بيننا وبينك حجاب فاعمل اننا عاملون","dt":"[5] وقال هؤلاء المعرضون الكافرون للنبي محمد -صلى الله عليه وسلم-: قلوبنا في اغطيه مانعه لنا من فهم ما تدعونا اليه، وفي اذاننا صمم فلا نسمع، ومن بيننا وبينك -يا محمد- ساتر يحجبنا عن اجابه دعوتك، فاعمل على وفق دينك، كما اننا عاملون على وفق ديننا."},{"id":"4224","s":41,"a":6,"at":"قل انما انا بشر مثلكم يوحى الي انما الهكم اله واحد فاستقيموا اليه واستغفروه وويل للمشركين","dt":"[6] قل لهم -ايها الرسول-: انما انا بشر مثلكم يوحي الله الي انما الهكم الذي يستحق العباده اله واحد لا شريك له، فاسلكوا الطريق الموصل اليه، واطلبوا مغفرته. وهلاك وعذاب للمشركين الذين عبدوا من دون الله اوثانا لا تنفع ولا تضر، والذين لم يطهروا انفسهم بتوحيد ربهم، والاخلاص له،"},{"id":"4225","s":41,"a":7,"at":"الذين لا يؤتون الزكاه وهم بالاخره هم كافرون","dt":"[7] ولا يؤدون الصدقه الى مستحقيها، فلا اخلاص منهم للخالق ولا نفع فيهم للخلق، وهم لا يؤمنون بالبعث، ولا بالجنه والنار."},{"id":"4226","s":41,"a":8,"at":"ان الذين امنوا وعملوا الصالحات لهم اجر غير ممنون","dt":"[8] ان الذين امنوا بالله ورسوله وكتابه وعملوا الاعمال الصالحه مخلصين لله فيها، لهم ثواب عظيم غير مقطوع ولا ممنوع."},{"id":"4227","s":41,"a":9,"at":"قل ائنكم لتكفرون بالذي خلق الارض في يومين وتجعلون له اندادا ذلك رب العالمين","dt":"[9] قل -ايها الرسول- لهؤلاء المشركين موبخا لهم ومتعجبا من فعلهم: اانكم لتكفرون بالله الذي خلق الارض في يومين اثنين، وتجعلون له نظراء وشركاء تعبدونهم معه؟ ذلك الخالق هو رب العالمين كلهم."},{"id":"4228","s":41,"a":10,"at":"وجعل فيها رواسي من فوقها وبارك فيها وقدر فيها اقواتها في اربعه ايام سواء للسائلين","dt":"[10] وجعل سبحانه في الارض جبالا ثوابت من فوقها، وبارك فيها فجعلها دائمه الخير لاهلها، وقدر فيها ارزاق اهلها من الغذاء، وما يصلحهم من المعاش في تمام اربعه ايام: يومان خلق فيهما الارض، ويومان جعل فيها رواسي وقدر فيها اقواتها، سواء للسائلين اي: لمن اراد السؤال عن ذلك؛ ليعلمه."},{"id":"4229","s":41,"a":11,"at":"ثم استوى الى السماء وهي دخان فقال لها وللارض ائتيا طوعا او كرها قالتا اتينا طائعين","dt":"[11] ثم استوى سبحانه وتعالى، اي قصد الى السماء وكانت دخانا من قبل، فقال للسماء وللارض: انقادا لامري مختارتين او مجبرتين. قالتا: اتينا مذعنين لك، ليس لنا اراده تخالف ارادتك."},{"id":"4230","s":41,"a":12,"at":"فقضاهن سبع سموات في يومين واوحى في كل سماء امرها وزينا السماء الدنيا بمصابيح وحفظا ذلك تقدير العزيز العليم","dt":"[12] فقضى الله خلق السموات السبع وتسويتهن في يومين، فتم بذلك خلق السموات والارض في سته ايام، لحكمه يعلمها الله، مع قدرته سبحانه على خلقهما في لحظه واحده، واوحى في كل سماء ما اراده وما امر به فيها، وزينا السماء الدنيا بالنجوم المضيئه، وحفظا لها من الشياطين الذين يسترقون السمع، ذلك الخلق البديع تقدير العزيز في ملكه، العليم الذي احاط علمه بكل شيء."},{"id":"4231","s":41,"a":13,"at":"فان اعرضوا فقل انذرتكم صاعقه مثل صاعقه عاد وثمود","dt":"[13] فان اعرض هؤلاء المكذبون بعدما بين لهم من اوصاف القران الحميده، ومن صفات الاله العظيم، فقل لهم: قد انذرتكم عذابا يستاصلكم مثل عذاب عاد وثمود حين كفروا بربهم وعصوا رسله."},{"id":"4232","s":41,"a":14,"at":"اذ جاءتهم الرسل من بين ايديهم ومن خلفهم الا تعبدوا الا الله قالوا لو شاء ربنا لانزل ملائكه فانا بما ارسلتم به كافرون","dt":"[14] حين جاءت الرسل عادا وثمود، يتبع بعضهم بعضا متوالين، يامرونهم بعباده الله وحده لا شريك له، قالوا لرسلهم: لو شاء ربنا ان نوحده ولا نعبد من دونه شيئا غيره، لانزل الينا ملائكه من السماء رسلا بما تدعوننا اليه، ولم يرسلكم وانتم بشر مثلنا، فانا بما ارسلكم الله به الينا من الايمان بالله وحده جاحدون."},{"id":"4233","s":41,"a":15,"at":"فاما عاد فاستكبروا في الارض بغير الحق وقالوا من اشد منا قوه او لم يروا ان الله الذي خلقهم هو اشد منهم قوه وكانوا باياتنا يجحدون","dt":"[15] فاما عاد قوم هود فقد استعلوا في الارض على العباد بغير حق، وقالوا في غرور: من اشد منا قوه؟ اولم يروا ان الله تعالى الذي خلقهم هو اشد منهم قوه وبطشا؟ وكانوا بادلتنا وحججنا يجحدون."},{"id":"4234","s":41,"a":16,"at":"فارسلنا عليهم ريحا صرصرا في ايام نحسات لنذيقهم عذاب الخزي في الحياه الدنيا ولعذاب الاخره اخزى وهم لا ينصرون","dt":"[16] فارسلنا عليهم ريحا شديده البروده عاليه الصوت في ايام مشؤومات عليهم؛ لنذيقهم عذاب الذل والهوان في الحياه الدنيا، ولعذاب الاخره اشد ذلا وهوانا، وهم لا ينصرون بمنع العذاب عنهم."},{"id":"4235","s":41,"a":17,"at":"واما ثمود فهديناهم فاستحبوا العمى على الهدى فاخذتهم صاعقه العذاب الهون بما كانوا يكسبون","dt":"[17] واما ثمود قوم صالح فقد بينا لهم سبيل الحق وطريق الرشد، فاختاروا العمى على الهدى، فاهلكتهم صاعقه العذاب المهين؛ بسبب ما كانوا يقترفون من الاثام بكفرهم بالله وتكذيبهم رسله."},{"id":"4236","s":41,"a":18,"at":"ونجينا الذين امنوا وكانوا يتقون","dt":"[18] ونجينا الذين امنوا من العذاب الذي اخذ عادا وثمود، وكان هؤلاء الناجون يخافون الله ويتقونه."},{"id":"4237","s":41,"a":19,"at":"ويوم يحشر اعداء الله الى النار فهم يوزعون","dt":"[19] ويوم يحشر اعداء الله الى نار جهنم ترد زبانيه العذاب اولهم على اخرهم،"},{"id":"4238","s":41,"a":20,"at":"حتى اذا ما جاءوها شهد عليهم سمعهم وابصارهم وجلودهم بما كانوا يعملون","dt":"[20] حتى اذا ما جاؤوا النار، وانكروا جرائمهم شهد عليهم سمعهم وابصارهم وجلودهم بما كانوا يعملون في الدنيا من الذنوب والاثام."},{"id":"4239","s":41,"a":21,"at":"وقالوا لجلودهم لم شهدتم علينا قالوا انطقنا الله الذي انطق كل شيء وهو خلقكم اول مره واليه ترجعون","dt":"[21] وقال هؤلاء الذين يحشرون الى النار من اعداء الله لجلودهم معاتبين: لم شهدتم علينا؟ فاجابتهم جلودهم: انطقنا الله الذي انطق كل شيء، وهو الذي خلقكم اول مره ولم تكونوا شيئا، واليه مصيركم بعد الموت للحساب والجزاء."},{"id":"4240","s":41,"a":22,"at":"وما كنتم تستترون ان يشهد عليكم سمعكم ولا ابصاركم ولا جلودكم ولكن ظننتم ان الله لا يعلم كثيرا مما تعملون","dt":"[22] وما كنتم تستخفون عند ارتكابكم المعاصي؛ خوفا من ان يشهد عليكم سمعكم ولا ابصاركم ولا جلودكم يوم القيامه، ولكن ظننتم بارتكابكم المعاصي ان الله لا يعلم كثيرا من اعمالكم التي تعصون الله بها."},{"id":"4241","s":41,"a":23,"at":"وذلكم ظنكم الذي ظننتم بربكم ارداكم فاصبحتم من الخاسرين","dt":"[23] . وذلكم ظنكم السيئ الذي ظننتموه بربكم اهلككم، فاوردكم النار، فاصبحتم اليوم من الخاسرين الذين خسروا انفسهم واهليهم."},{"id":"4242","s":41,"a":24,"at":"فان يصبروا فالنار مثوى لهم وان يستعتبوا فما هم من المعتبين","dt":"[24] فان يصبروا على العذاب فالنار ماواهم، وان يسالوا الرجوع الى الدنيا؛ ليستانفوا العمل الصالح لا يجابوا الى ذلك، ولا تقبل لهم اعذار."},{"id":"4243","s":41,"a":25,"at":"وقيضنا لهم قرناء فزينوا لهم ما بين ايديهم وما خلفهم وحق عليهم القول في امم قد خلت من قبلهم من الجن والانس انهم كانوا خاسرين","dt":"[25] وهيانا لهؤلاء الظالمين الجاحدين قرناء فاسدين من شياطين الانس والجن، فزينوا لهم قبائح اعمالهم في الدنيا، ودعوهم الى لذاتها وشهواتها المحرمه، وزينوا لهم ما خلفهم من امور الاخره، فانسوهم ذكرها، ودعوهم الى التكذيب بالمعاد، وبذلك استحقوا دخول النار في جمله امم سابقه من كفره الجن والانس، انهم كانوا خاسرين اعمالهم في الدنيا وانفسهم واهليهم يوم القيامه."},{"id":"4244","s":41,"a":26,"at":"وقال الذين كفروا لا تسمعوا لهذا القران والغوا فيه لعلكم تغلبون","dt":"[26] وقال الكافرون بعضهم لبعض متواصين فيما بينهم: لا تسمعوا لهذا القران، ولا تطيعوه، ولا تنقادوا لاوامره، وارفعوا اصواتكم بالصياح والصفير والتخليط على محمد اذا قرا القران؛ لعلكم تغلبونه، فيترك القراءه، وننتصر عليه."},{"id":"4245","s":41,"a":27,"at":"فلنذيقن الذين كفروا عذابا شديدا ولنجزينهم اسوا الذي كانوا يعملون","dt":"[27] فلنذيقن الذين قالوا هذا القول عذابا شديدا في الدنيا والاخره، ولنجزينهم اسوا ما كانوا يعملون من السيئات."},{"id":"4246","s":41,"a":28,"at":"ذلك جزاء اعداء الله النار لهم فيها دار الخلد جزاء بما كانوا باياتنا يجحدون","dt":"[28] ذلك العذاب الشديد جزاء عادل لاعداء الله، هو نار جهنم، لهم فيها دار الخلود الدائم؛ جزاء بما كانوا بحججنا وادلتنا يجحدون في الدنيا. والايه داله على عظم جريمه من صرف الناس عن القران العظيم، وصدهم عن تدبره وهدايته باي وسيله كانت."},{"id":"4247","s":41,"a":29,"at":"وقال الذين كفروا ربنا ارنا اللذين اضلانا من الجن والانس نجعلهما تحت اقدامنا ليكونا من الاسفلين","dt":"[29] وقال الذين كفروا بالله ورسوله، وهم في النار: ربنا ارنا اللذين اضلانا من خلقك من الجن والانس نجعلهما تحت اقدامنا؛ ليكونا في الدرك الاسفل من النار."},{"id":"4248","s":41,"a":30,"at":"ان الذين قالوا ربنا الله ثم استقاموا تتنزل عليهم الملائكه الا تخافوا ولا تحزنوا وابشروا بالجنه التي كنتم توعدون","dt":"[30] ان الذين قالوا ربنا الله تعالى وحده لا شريك له، ثم استقاموا على شريعته، تتنزل عليهم الملائكه عند الموت قائلين لهم: لا تخافوا من الموت وما بعده، ولا تحزنوا على ما تخلفونه وراءكم من امور الدنيا، وابشروا بالجنه التي كنتم توعدون بها."},{"id":"4249","s":41,"a":31,"at":"نحن اولياؤكم في الحياه الدنيا وفي الاخره ولكم فيها ما تشتهي انفسكم ولكم فيها ما تدعون","dt":"[31] وتقول لهم الملائكه: نحن انصاركم في الحياه الدنيا، نسددكم ونحفظكم بامر الله، وكذلك نكون معكم في الاخره، ولكم في الجنه كل ما تشتهيه انفسكم مما تختارونه، وتقر به اعينكم، ومهما طلبتم من شيء وجدتموه بين ايديكم؛"},{"id":"4250","s":41,"a":32,"at":"نزلا من غفور رحيم","dt":"[32] ضيافه وانعاما لكم من غفور لذنوبكم، رحيم بكم."},{"id":"4251","s":41,"a":33,"at":"ومن احسن قولا ممن دعا الى الله وعمل صالحا وقال انني من المسلمين","dt":"[33] لا احد احسن قولا ممن دعا الى توحيد الله وعبادته وحده وعمل صالحا وقال: انني من المسلمين المنقادين لامر الله وشرعه. وفي الايه حث على الدعوه الى الله سبحانه، وبيان فضل العلماء الداعين اليه على بصيره، وفق ما جاء عن رسول الله محمد -صلى الله عليه وسلم-."},{"id":"4252","s":41,"a":34,"at":"ولا تستوي الحسنه ولا السيئه ادفع بالتي هي احسن فاذا الذي بينك وبينه عداوه كانه ولي حميم","dt":"[34] ولا تستوي حسنه الذين امنوا بالله واستقاموا على شرعه، واحسنوا الى خلقه، وسيئه الذين كفروا به وخالفوا امره، واساؤوا الى خلقه. ادفع -ايها الرسول- بعفوك وحلمك واحسانك من اساء اليك، وقابل اساءته لك بالاحسان اليه، فبذلك يصير المسيء اليك الذي بينك وبينه عداوه كانه محب مناصر لك وقريب شفيق عليك."},{"id":"4253","s":41,"a":35,"at":"وما يلقاها الا الذين صبروا وما يلقاها الا ذو حظ عظيم","dt":"[35] وما يوفق لهذه الخصله الحميده الا الذين صبروا على المكاره والاذى، وحملوا انفسهم على ما يحبه الله، وما يوفق لها الا ذو نصيب وافر من السعاده في الدنيا والاخره."},{"id":"4254","s":41,"a":36,"at":"واما ينزغنك من الشيطان نزغ فاستعذ بالله انه هو السميع العليم","dt":"[36] واما يلقين الشيطان في نفسك وسوسه من حديث النفس لحملك على مجازاه المسيء بالاساءه، فاستجر بالله واعتصم به، ان الله هو السميع لاستعاذتك به، العليم بامور خلقه جميعها."},{"id":"4255","s":41,"a":37,"at":"ومن اياته الليل والنهار والشمس والقمر لا تسجدوا للشمس ولا للقمر واسجدوا لله الذي خلقهن ان كنتم اياه تعبدون","dt":"[37] ومن حجج الله على خلقه، ودلائله على وحدانيته وكمال قدرته اختلاف الليل والنهار، وتعاقبهما، واختلاف الشمس والقمر وتعاقبهما، كل ذلك تحت تسخيره وقهره. لا تسجدوا للشمس ولا للقمر -فانهما مدبران مخلوقان- واسجدوا لله الذي خلقهن، ان كنتم حقا منقادين لامره، سامعين مطيعين له، تعبدونه وحده لا شريك له."},{"id":"4256","s":41,"a":38,"at":"فان استكبروا فالذين عند ربك يسبحون له بالليل والنهار وهم لا يسامون","dt":"[38] فان استكبر هؤلاء المشركون عن السجود لله، فان الملائكه الذين عند ربك لا يستكبرون عن ذلك، بل يسبحون له، وينزهونه عن كل نقص بالليل والنهار، وهم لا يفترون عن ذلك، ولا يملون."},{"id":"4257","s":41,"a":39,"at":"ومن اياته انك ترى الارض خاشعه فاذا انزلنا عليها الماء اهتزت وربت ان الذي احياها لمحي الموتى انه على كل شيء قدير","dt":"[39] ومن علامات وحدانيه الله وقدرته: انك ترى الارض يابسه لا نبات فيها، فاذا انزلنا عليها المطر دبت فيها الحياه، وتحركت بالنبات، وانتفخت وعلت، ان الذي احيا هذه الارض بعد همودها، قادر على احياء الخلق بعد موتهم، انه على كل شيء قدير، فكما لا تعجز قدرته عن احياء الارض بعد موتها، فكذلك لا تعجز عن احياء الموتى."},{"id":"4258","s":41,"a":40,"at":"ان الذين يلحدون في اياتنا لا يخفون علينا افمن يلقى في النار خير ام من ياتي امنا يوم القيامه اعملوا ما شئتم انه بما تعملون بصير","dt":"[40] ان الذين يميلون عن الحق، فيكفرون بالقران ويحرفونه، لا يخفون علينا، بل نحن مطلعون عليهم. افهذا الملحد في ايات الله الذي يلقى في النار خير، ام الذي ياتي يوم القيامه امنا من عذاب الله، مستحقا لثوابه؛ لايمانه به وتصديقه باياته؟ اعملوا -ايها الملحدون- ما شئتم، فان الله تعالى باعمالكم بصير، لا يخفى عليه شيء منها، وسيجازيكم على ذلك. وفي هذا وعيد وتهديد لهم."},{"id":"4259","s":41,"a":41,"at":"ان الذين كفروا بالذكر لما جاءهم وانه لكتاب عزيز","dt":"[41] ان الذين جحدوا بهذا القران وكذبوا به حين جاءهم هالكون ومعذبون، وان هذا القران لكتاب عزيز باعزاز الله اياه وحفظه له من كل تغيير او تبديل،"},{"id":"4260","s":41,"a":42,"at":"لا ياتيه الباطل من بين يديه ولا من خلفه تنزيل من حكيم حميد","dt":"[42] لا ياتيه الباطل من اي ناحيه من نواحيه ولا يبطله شيء، فهو محفوظ من ان ينقص منه، او يزاد فيه، تنزيل من حكيم بتدبير امور عباده، محمود على ما له من صفات الكمال."},{"id":"4261","s":41,"a":43,"at":"ما يقال لك الا ما قد قيل للرسل من قبلك ان ربك لذو مغفره وذو عقاب اليم","dt":"[43] ما يقول لك هؤلاء المشركون -ايها الرسول- الا ما قد قاله من قبلهم من الامم لرسلهم، فاصبر على ما ينالك في سبيل الدعوه الى الله. ان ربك لذو مغفره لذنوب التائبين، وذو عقاب مؤلم لمن اصر على كفره وتكذيبه."},{"id":"4262","s":41,"a":44,"at":"ولو جعلناه قرانا اعجميا لقالوا لولا فصلت اياته ااعجمي وعربي قل هو للذين امنوا هدى وشفاء والذين لا يؤمنون في اذانهم وقر وهو عليهم عمى اولئك ينادون من مكان بعيد","dt":"[44] ولو جعلنا هذا القران الذي انزلناه عليك -ايها الرسول- اعجميا، لقال المشركون: هلا بينت اياته، فنفقهه ونعلمه، ااعجمي هذا القران، ولسان الذي انزل عليه عربي؟ هذا لا يكون. قل لهم -ايها الرسول-: هذا القران للذين امنوا بالله ورسوله هدى من الضلاله، وشفاء لما في الصدور من الشكوك والامراض، والذين لا يؤمنون بالقران في اذانهم صمم من سماعه وتدبره، وهو على قلوبهم عمى، فلا يهتدون به، اولئك المشركون كمن ينادى وهو في مكان بعيد، لا يسمع داعيا، ولا يجيب مناديا."},{"id":"4263","s":41,"a":45,"at":"ولقد اتينا موسى الكتاب فاختلف فيه ولولا كلمه سبقت من ربك لقضي بينهم وانهم لفي شك منه مريب","dt":"[45] ولقد اتينا موسى التوراه كما اتيناك -ايها الرسول- القران فاختلف فيها قومه: فمنهم من امن، ومنهم من كذب. ولولا كلمه سبقت من ربك بتاجيل العذاب عن قومك لفصل بينهم باهلاك الكافرين في الحال، وان المشركين لفي شك من القران شديد الريبه."},{"id":"4264","s":41,"a":46,"at":"من عمل صالحا فلنفسه ومن اساء فعليها وما ربك بظلام للعبيد","dt":"[46] من عمل صالحا فاطاع الله ورسوله فلنفسه ثواب عمله، ومن اساء فعصى الله ورسوله فعلى نفسه وزر عمله. وما ربك بظلام للعبيد، بنقص حسنه او زياده سيئه."},{"id":"4265","s":41,"a":47,"at":"اليه يرد علم الساعه وما تخرج من ثمرات من اكمامها وما تحمل من انثى ولا تضع الا بعلمه ويوم يناديهم اين شركائي قالوا اذناك ما منا من شهيد","dt":"[47] الى الله تعالى وحده لا شريك له يرجع علم الساعه، فانه لا يعلم احد متى قيامها غيره، وما تخرج من ثمرات من اوعيتها، وما تحمل من انثى ولا تضع حملها الا بعلم من الله، لا يخفى عليه شيء من ذلك. ويوم ينادي الله تعالى المشركين يوم القيامه توبيخا لهم واظهارا لكذبهم: اين شركائي الذين كنتم تشركونهم في عبادتي؟ قالوا: اعلمناك الان ما منا من احد يشهد اليوم ان معك شريكا."},{"id":"4266","s":41,"a":48,"at":"وضل عنهم ما كانوا يدعون من قبل وظنوا ما لهم من محيص","dt":"[48] وذهب عن هؤلاء المشركين شركاؤهم الذين كانوا يعبدونهم من دون الله، فلم ينفعوهم، وايقنوا ان لا ملجا لهم من عذاب الله، ولا محيد عنه."},{"id":"4267","s":41,"a":49,"at":"لا يسام الانسان من دعاء الخير وان مسه الشر فيئوس قنوط","dt":"[49] لا يمل الانسان من دعاء ربه طالبا الخير الدنيوي، وان اصابه فقر وشده فهو يؤوس من رحمه الله، قنوط بسوء الظن بربه."},{"id":"4268","s":41,"a":50,"at":"ولئن اذقناه رحمه منا من بعد ضراء مسته ليقولن هذا لي وما اظن الساعه قائمه ولئن رجعت الى ربي ان لي عنده للحسنى فلننبئن الذين كفروا بما عملوا ولنذيقنهم من عذاب غليظ","dt":"[50] ولئن اذقنا الانسان نعمه منا من بعد شده وبلاء لم يشكر الله تعالى، بل يطغى ويقول: اتاني هذا؛ لاني مستحق له، وما اعتقد ان الساعه اتيه، وذلك انكار منه للبعث، وعلى تقدير اتيان الساعه واني سارجع الى ربي، فان لي عنده الجنه، فلنخبرن الذين كفروا يوم القيامه بما عملوا من سيئات، ولنذيقنهم من العذاب الشديد."},{"id":"4269","s":41,"a":51,"at":"واذا انعمنا على الانسان اعرض وناى بجانبه واذا مسه الشر فذو دعاء عريض","dt":"[51] واذا انعمنا على الانسان بصحه او رزق او غيرهما اعرض وترفع عن الانقياد الى الحق، وان اصابه ضر فهو ذو دعاء كثير بان يكشف الله ضره، فهو يعرف ربه في الشده، ولا يعرفه في الرخاء."},{"id":"4270","s":41,"a":52,"at":"قل ارايتم ان كان من عند الله ثم كفرتم به من اضل ممن هو في شقاق بعيد","dt":"[52] قل -ايها الرسول- لهؤلاء المكذبين: اخبروني ان كان هذا القران من عند الله ثم جحدتم وكذبتم به، لا احد اضل منكم؛ لانكم في خلاف بعيد عن الحق بكفركم بالقران وتكذيبكم به."},{"id":"4271","s":41,"a":53,"at":"سنريهم اياتنا في الافاق وفي انفسهم حتى يتبين لهم انه الحق او لم يكف بربك انه على كل شيء شهيد","dt":"[53] سنري هؤلاء المكذبين اياتنا من الفتوحات وظهور الاسلام على الاقاليم وسائر الاديان، وفي اقطار السموات والارض، وما يحدثه الله فيهما من الحوادث العظيمه، وفي انفسهم وما اشتملت عليه من بديع ايات الله وعجائب صنعه، حتى يتبين لهم من تلك الايات بيان لا يقبل الشك ان القران الكريم هو الحق الموحى به من رب العالمين. اولم يكفهم دليلا على ان القران حق، ومن جاء به صادق، شهاده الله تعالى؟ فانه قد شهد له بالتصديق، وهو على كل شيء شهيد، ولا شيء اكبر شهاده من شهادته سبحانه وتعالى."},{"id":"4272","s":41,"a":54,"at":"الا انهم في مريه من لقاء ربهم الا انه بكل شيء محيط","dt":"[54] الا ان هؤلاء الكافرين في شك عظيم من البعث بعد الممات. الا ان الله -جل وعلا- بكل شيء محيط علما وقدره وعزه، لا يخفى عليه شيء في الارض ولا في السماء."},{"id":"4273","s":42,"a":1,"at":"حم","dt":"[1] حم سبق الكلام على الحروف المقطعه في اول سوره البقره."},{"id":"4274","s":42,"a":2,"at":"عسق","dt":"[2] عسق سبق الكلام على الحروف المقطعه في اول سوره البقره."},{"id":"4275","s":42,"a":3,"at":"كذلك يوحي اليك والى الذين من قبلك الله العزيز الحكيم","dt":"[3] كما انزل الله اليك -ايها النبي- هذا القران انزل الكتب والصحف على الانبياء من قبلك، وهو العزيز في انتقامه، الحكيم في اقواله وافعاله."},{"id":"4276","s":42,"a":4,"at":"له ما في السموات وما في الارض وهو العلي العظيم","dt":"[4] لله وحده ما في السموات وما في الارض، وهو العلي بذاته وقدره وقهره، العظيم الذي له العظمه والكبرياء."},{"id":"4277","s":42,"a":5,"at":"تكاد السموات يتفطرن من فوقهن والملائكه يسبحون بحمد ربهم ويستغفرون لمن في الارض الا ان الله هو الغفور الرحيم","dt":"[5] تكاد السموات يتشققن، كل واحده فوق التي تليها؛ من عظمه الرحمن وجلاله تبارك وتعالى، والملائكه يسبحون بحمد ربهم، وينزهونه عما لا يليق به، ويسالون ربهم المغفره لذنوب من في الارض من اهل الايمان به. الا ان الله هو الغفور لذنوب مؤمني عباده، الرحيم بهم."},{"id":"4278","s":42,"a":6,"at":"والذين اتخذوا من دونه اولياء الله حفيظ عليهم وما انت عليهم بوكيل","dt":"[6] والذين اتخذوا غير الله الهه من دونه يتولونها، ويعبدونها، الله تعالى يحفظ عليهم افعالهم؛ ليجازيهم بها يوم القيامه، وما انت -ايها الرسول- بالوكيل عليهم بحفظ اعمالهم، انما انت منذر، فعليك البلاغ وعلينا الحساب."},{"id":"4279","s":42,"a":7,"at":"وكذلك اوحينا اليك قرانا عربيا لتنذر ام القرى ومن حولها وتنذر يوم الجمع لا ريب فيه فريق في الجنه وفريق في السعير","dt":"[7] وكما اوحينا الى الانبياء قبلك اوحينا اليك قرانا عربيا؛ لتنذر اهل «مكه» ومن حولها من سائر الناس، وتنذر عذاب يوم الجمع، وهو يوم القيامه، لا شك في مجيئه. الناس فيه فريقان: فريق في الجنه، وهم الذين امنوا بالله واتبعوا ما جاءهم به رسوله محمد -صلى الله عليه وسلم-، وفريق في النار المستعره، وهم الذين كفروا بالله، وخالفوا ما جاءهم به رسوله محمد -صلى الله عليه وسلم-."},{"id":"4280","s":42,"a":8,"at":"ولو شاء الله لجعلهم امه واحده ولكن يدخل من يشاء في رحمته والظالمون ما لهم من ولي ولا نصير","dt":"[8] ولو شاء الله ان يجمع خلقه على الهدى ويجعلهم على مله واحده مهتديه لفعل، ولكنه اراد ان يدخل في رحمته من يشاء من خواص خلقه. والظالمون انفسهم بالشرك ما لهم من ولي يتولى امورهم يوم القيامه، ولا نصير ينصرهم من عقاب الله تعالى."},{"id":"4281","s":42,"a":9,"at":"ام اتخذوا من دونه اولياء فالله هو الولي وهو يحيي الموتى وهو على كل شيء قدير","dt":"[9] بل اتخذ هؤلاء المشركون اولياء من دون الله يتولونهم، فالله وحده هو الولي يتولاه عبده بالعباده والطاعه، ويتولى عباده المؤمنين باخراجهم من الظلمات الى النور واعانتهم في جميع امورهم، وهو يحيي الموتى عند البعث، وهو على كل شيء قدير، لا يعجزه شيء."},{"id":"4282","s":42,"a":10,"at":"وما اختلفتم فيه من شيء فحكمه الى الله ذلكم الله ربي عليه توكلت واليه انيب","dt":"[10] وما اختلفتم فيه -ايها الناس- من شيء من امور دينكم، فالحكم فيه مرده الى الله في كتابه وسنه رسوله -صلى الله عليه وسلم-. ذلكم الله ربي وربكم، عليه وحده توكلت في اموري، واليه ارجع في جميع شؤوني."},{"id":"4283","s":42,"a":11,"at":"فاطر السموات والارض جعل لكم من انفسكم ازواجا ومن الانعام ازواجا يذرؤكم فيه ليس كمثله شيء وهو السميع البصير","dt":"[11] الله سبحانه وتعالى هو خالق السموات والارض ومبدعهما بقدرته ومشيئته وحكمته، جعل لكم من انفسكم ازواجا؛ لتسكنوا اليها، وجعل لكم من الانعام ازواجا ذكورا واناثا، يكثركم بسبب هذا التزاوج بالتوالد، ليس يشبهه تعالى ولا يماثله شيء من مخلوقاته، لا في ذاته ولا في اسمائه ولا في صفاته ولا في افعاله؛ لان اسماءه كلها حسنى، وصفاته صفات كمال وعظمه، وافعاله تعالى اوجد بها المخلوقات العظيمه من غير مشارك، وهو السميع البصير، لا يخفى عليه من اعمال خلقه واقوالهم شيء، وسيجازيهم على ذلك."},{"id":"4284","s":42,"a":12,"at":"له مقاليد السموات والارض يبسط الرزق لمن يشاء ويقدر انه بكل شيء عليم","dt":"[12] له سبحانه وتعالى ملك السموات والارض، وبيده مفاتيح الرحمه والارزاق، يوسع رزقه على من يشاء من عباده ويضيقه على من يشاء، انه تبارك وتعالى بكل شيء عليم، لا يخفى عليه شيء من امور خلقه."},{"id":"4285","s":42,"a":13,"at":"شرع لكم من الدين ما وصى به نوحا والذي اوحينا اليك وما وصينا به ابراهيم وموسى وعيسى ان اقيموا الدين ولا تتفرقوا فيه كبر على المشركين ما تدعوهم اليه الله يجتبي اليه من يشاء ويهدي اليه من ينيب","dt":"[13] شرع الله لكم -ايها الناس- من الدين الذي اوحيناه اليك -ايها الرسول، وهو الاسلام- ما وصى به نوحا ان يعمله ويبلغه، وما وصينا به ابراهيم وموسى وعيسى -هؤلاء الخمسه هم اولو العزم من الرسل على المشهور- ان اقيموا الدين بالتوحيد وطاعه الله وعبادته دون من سواه، ولا تختلفوا في الدين الذي امرتكم به، عظم على المشركين ما تدعوهم اليه من توحيد الله واخلاص العباده له، الله يصطفي للتوحيد من يشاء من خلقه، ويوفق للعمل بطاعته من يرجع اليه."},{"id":"4286","s":42,"a":14,"at":"وما تفرقوا الا من بعد ما جاءهم العلم بغيا بينهم ولولا كلمه سبقت من ربك الى اجل مسمى لقضي بينهم وان الذين اورثوا الكتاب من بعدهم لفي شك منه مريب","dt":"[14] وما تفرق المشركون بالله في اديانهم فصاروا شيعا واحزابا الا من بعدما جاءهم العلم وقامت الحجه عليهم، وما حملهم على ذلك الا البغي والعناد، ولولا كلمه سبقت من ربك -ايها الرسول- بتاخير العذاب عنهم الى اجل مسمى وهو يوم القيامه، لقضي بينهم بتعجيل عذاب الكافرين منهم. وان الذين اورثوا التوراه والانجيل من بعد هؤلاء المختلفين في الحق لفي شك من الدين والايمان موقع في الريبه والاختلاف المذموم."},{"id":"4287","s":42,"a":15,"at":"فلذلك فادع واستقم كما امرت ولا تتبع اهواءهم وقل امنت بما انزل الله من كتاب وامرت لاعدل بينكم الله ربنا وربكم لنا اعمالنا ولكم اعمالكم لا حجه بيننا وبينكم الله يجمع بيننا واليه المصير","dt":"[15] فالى ذلك الدين القيم الذي شرعه الله للانبياء ووصاهم به، فادع -ايها الرسول- عباد الله، واستقم كما امرك الله، ولا تتبع اهواء الذين شكوا في الحق وانحرفوا عن الدين، وقل: صدقت بجميع الكتب المنزله من السماء على الانبياء، وامرني ربي ان اعدل بينكم في الحكم، الله ربنا وربكم، لنا ثواب اعمالنا الصالحه، ولكم جزاء اعمالكم السيئه، لا خصومه ولا جدال بيننا وبينكم بعدما تبين الحق، الله يجمع بيننا وبينكم يوم القيامه، فيقضي بيننا بالحق فيما اختلفنا فيه، واليه المرجع والماب، فيجازي كلا بما يستحق."},{"id":"4288","s":42,"a":16,"at":"والذين يحاجون في الله من بعد ما استجيب له حجتهم داحضه عند ربهم وعليهم غضب ولهم عذاب شديد","dt":"[16] والذين يجادلون في دين الله الذي ارسلت به محمدا -صلى الله عليه وسلم-، من بعد ما استجاب الناس له واسلموا، حجتهم ومجادلتهم باطله ذاهبه عند ربهم، وعليهم من الله غضب في الدنيا، ولهم في الاخره عذاب شديد، وهو النار."},{"id":"4289","s":42,"a":17,"at":"الله الذي انزل الكتاب بالحق والميزان وما يدريك لعل الساعه قريب","dt":"[17] الله الذي انزل القران وسائر الكتب المنزله بالصدق، وانزل الميزان وهو العدل؛ ليحكم بين الناس بالانصاف. واي شيء يدريك ويعلمك لعل الساعه التي تقوم فيها القيامه قريب؟"},{"id":"4290","s":42,"a":18,"at":"يستعجل بها الذين لا يؤمنون بها والذين امنوا مشفقون منها ويعلمون انها الحق الا ان الذين يمارون في الساعه لفي ضلال بعيد","dt":"[18] يستعجل بمجيء الساعه الذين لا يؤمنون بها؛ تهكما واستهزاء، والذين امنوا بها خائفون من قيامها، ويعلمون انها الحق الذي لا شك فيه. الا ان الذين يخاصمون في قيام الساعه لفي ضلال بعيد عن الحق."},{"id":"4291","s":42,"a":19,"at":"الله لطيف بعباده يرزق من يشاء وهو القوي العزيز","dt":"[19] الله لطيف بعباده، يوسع الرزق على من يشاء، ويضيقه على من يشاء وفق حكمته سبحانه، وهو القوي الذي له القوه كلها، العزيز في انتقامه من اهل معاصيه."},{"id":"4292","s":42,"a":20,"at":"من كان يريد حرث الاخره نزد له في حرثه ومن كان يريد حرث الدنيا نؤته منها وما له في الاخره من نصيب","dt":"[20] من كان يريد بعمله ثواب الاخره فادى حقوق الله وانفق في الدعوه الى الدين، نزد له في عمله الحسن، فنضاعف له ثواب الحسنه الى عشر امثالها الى ما شاء الله من الزياده، ومن كان يريد بعمله الدنيا وحدها، نؤته منها ما قسمناه له، وليس له في الاخره شيء من الثواب."},{"id":"4293","s":42,"a":21,"at":"ام لهم شركاء شرعوا لهم من الدين ما لم ياذن به الله ولولا كلمه الفصل لقضي بينهم وان الظالمين لهم عذاب اليم","dt":"[21] بل الهؤلاء المشركين بالله شركاء في شركهم وضلالتهم، ابتدعوا لهم من الدين والشرك ما لم ياذن به الله؟ ولولا قضاء الله وقدره بامهالهم، وان لا يعجل لهم العذاب في الدنيا، لقضي بينهم بتعجيل العذاب لهم. وان الكافرين بالله لهم يوم القيامه عذاب مؤلم موجع."},{"id":"4294","s":42,"a":22,"at":"ترى الظالمين مشفقين مما كسبوا وهو واقع بهم والذين امنوا وعملوا الصالحات في روضات الجنات لهم ما يشاءون عند ربهم ذلك هو الفضل الكبير","dt":"[22] ترى -ايها الرسول- الكافرين يوم القيامه خائفين من عقاب الله على ما كسبوا في الدنيا من اعمال خبيثه، والعذاب نازل بهم، وهم ذائقوه لا محاله. والذين امنوا بالله واطاعوه في بساتين الجنات وقصورها ونعيم الاخره، لهم ما تشتهيه انفسهم عند ربهم، ذلك الذي اعطاه الله لهم من الفضل والكرامه هو الفضل الذي لا يوصف، ولا تهتدي اليه العقول."},{"id":"4295","s":42,"a":23,"at":"ذلك الذي يبشر الله عباده الذين امنوا وعملوا الصالحات قل لا اسالكم عليه اجرا الا الموده في القربى ومن يقترف حسنه نزد له فيها حسنا ان الله غفور شكور","dt":"[23] ذلك الذي اخبرتكم به -ايها الناس- من النعيم والكرامه في الاخره هو البشرى التي يبشر الله بها عباده الذين امنوا به في الدنيا واطاعوه. قل -ايها الرسول- للذين يشكون في الساعه من مشركي قومك: لا اسالكم على ما ادعوكم اليه من الحق الذي جئتكم به عوضا من اموالكم، الا ان تودوني في قرابتي منكم، وتصلوا الرحم التي بيني وبينكم. ومن يكتسب حسنه نضاعفها له بعشر فصاعدا. ان الله غفور لذنوب عباده، شكور لحسناتهم وطاعتهم اياه."},{"id":"4296","s":42,"a":24,"at":"ام يقولون افترى على الله كذبا فان يشا الله يختم على قلبك ويمح الله الباطل ويحق الحق بكلماته انه عليم بذات الصدور","dt":"[24] بل ايقول هؤلاء المشركون: اختلق محمد الكذب على الله، فجاء بالذي يتلوه علينا اختلاقا من عند نفسه؟ فان يشا الله يطبع على قلبك -ايها الرسول- لو فعلت ذلك. ويذهب الله الباطل فيمحقه، ويحق الحق بكلماته التي لا تتبدل ولا تتغير، وبوعده الصادق الذي لا يخلف. ان الله عليم بما في قلوب العباد، لا يخفى عليه شيء منه."},{"id":"4297","s":42,"a":25,"at":"وهو الذي يقبل التوبه عن عباده ويعفو عن السيئات ويعلم ما تفعلون","dt":"[25] والله سبحانه وتعالى هو الذي يقبل التوبه عن عباده اذا رجعوا الى توحيد الله وطاعته، ويعفو عن السيئات، ويعلم ما تصنعون من خير وشر، لا يخفى عليه شيء من ذلك، وهو مجازيكم به."},{"id":"4298","s":42,"a":26,"at":"ويستجيب الذين امنوا وعملوا الصالحات ويزيدهم من فضله والكافرون لهم عذاب شديد","dt":"[26] ويستجيب الذين امنوا بالله ورسوله لربهم لما دعاهم اليه وينقادون له، ويزيدهم من فضله توفيقا ومضاعفه في الاجر والثواب. والكافرون بالله ورسوله لهم يوم القيامه عذاب شديد موجع مؤلم."},{"id":"4299","s":42,"a":27,"at":"ولو بسط الله الرزق لعباده لبغوا في الارض ولكن ينزل بقدر ما يشاء انه بعباده خبير بصير","dt":"[27] ولو بسط الله الرزق لعباده فوسعه عليهم، لبغوا في الارض اشرا وبطرا، ولطغى بعضهم على بعض، ولكن الله ينزل ارزاقهم بقدر ما يشاء لكفايتهم. انه بعباده خبير بما يصلحهم، بصير بتدبيرهم وتصريف احوالهم."},{"id":"4300","s":42,"a":28,"at":"وهو الذي ينزل الغيث من بعد ما قنطوا وينشر رحمته وهو الولي الحميد","dt":"[28] والله وحده هو الذي ينزل المطر من السماء، فيغيثهم به من بعد ما يئسوا من نزوله، وينشر رحمته في خلقه، فيعمهم بالغيث، وهو الولي الذي يتولى عباده باحسانه وفضله، الحميد في ولايته وتدبيره."},{"id":"4301","s":42,"a":29,"at":"ومن اياته خلق السموات والارض وما بث فيهما من دابه وهو على جمعهم اذا يشاء قدير","dt":"[29] ومن اياته الداله على عظمته وقدرته وسلطانه، خلق السموات والارض على غير مثال سابق، وما نشر فيهما من اصناف الدواب، وهو على جمع الخلق بعد موتهم لموقف القيامه اذا يشاء قدير، لا يتعذر عليه شيء."},{"id":"4302","s":42,"a":30,"at":"وما اصابكم من مصيبه فبما كسبت ايديكم ويعفو عن كثير","dt":"[30] وما اصابكم -ايها الناس- من مصيبه في دينكم ودنياكم فبما كسبتم من الذنوب والاثام، ويعفو لكم ربكم عن كثير من السيئات، فلا يؤاخذكم بها."},{"id":"4303","s":42,"a":31,"at":"وما انتم بمعجزين في الارض وما لكم من دون الله من ولي ولا نصير","dt":"[31] وما انتم -ايها الناس- بمعجزين قدره الله عليكم، ولا فائتيه، وما لكم من دون الله من ولي يتولى اموركم، فيوصل لكم المنافع، ولا نصير يدفع عنكم المضار."},{"id":"4304","s":42,"a":32,"at":"ومن اياته الجوار في البحر كالاعلام","dt":"[32] ومن اياته الداله على قدرته الباهره وسلطانه القاهر السفن العظيمه كالجبال تجري في البحر."},{"id":"4305","s":42,"a":33,"at":"ان يشا يسكن الريح فيظللن رواكد على ظهره ان في ذلك لايات لكل صبار شكور","dt":"[33] ان يشا الله الذي اجرى هذه السفن في البحر يسكن الريح، فتبق السفن سواكن على ظهر البحر لا تجري، ان في جري هذه السفن ووقوفها في البحر بقدره الله لعظات وحججا بينه على قدره الله لكل صبار على طاعه الله، وعن المعاصي، وعلى اقدار الله المؤلمه، شكور لنعمه وافضاله."},{"id":"4306","s":42,"a":34,"at":"او يوبقهن بما كسبوا ويعف عن كثير","dt":"[34] او يهلك السفن بالغرق بسبب ذنوب اهلها، ويعف عن كثير من الذنوب فلا يعاقب عليها."},{"id":"4307","s":42,"a":35,"at":"ويعلم الذين يجادلون في اياتنا ما لهم من محيص","dt":"[35] ويعلم الذين يجادلون بالباطل في اياتنا الداله على توحيدنا، ما لهم من محيد ولا ملجا من عقاب الله، اذا عاقبهم على ذنوبهم وكفرهم به."},{"id":"4308","s":42,"a":36,"at":"فما اوتيتم من شيء فمتاع الحياه الدنيا وما عند الله خير وابقى للذين امنوا وعلى ربهم يتوكلون","dt":"[36] فما اوتيتم -ايها الناس- من شيء من المال او البنين وغير ذلك فهو متاع لكم في الحياه الدنيا، سرعان ما يزول، وما عند الله تعالى من نعيم الجنه المقيم خير وابقى للذين امنوا بالله ورسله، وعلى ربهم يتوكلون."},{"id":"4309","s":42,"a":37,"at":"والذين يجتنبون كبائر الاثم والفواحش واذا ما غضبوا هم يغفرون","dt":"[37] والذين يجتنبون كبائر ما نهى الله عنه، وما فحش وقبح من انواع المعاصي، واذا ما غضبوا على من اساء اليهم هم يغفرون الاساءه، ويصفحون عن عقوبه المسيء؛ طلبا لثواب الله تعالى وعفوه، وهذا من محاسن الاخلاق."},{"id":"4310","s":42,"a":38,"at":"والذين استجابوا لربهم واقاموا الصلاه وامرهم شورى بينهم ومما رزقناهم ينفقون","dt":"[38] والذين استجابوا لربهم حين دعاهم الى توحيده وطاعته، واقاموا الصلاه المفروضه بحدودها في اوقاتها، واذا ارادوا امرا تشاوروا فيه، ومما اعطيناهم من الاموال يتصدقون في سبيل الله، ويؤدون ما فرض الله عليهم من الحقوق لاهلها من زكاه ونفقه وغير ذلك من وجوه الانفاق."},{"id":"4311","s":42,"a":39,"at":"والذين اذا اصابهم البغي هم ينتصرون","dt":"[39] والذين اذا اصابهم الظلم هم ينتصرون ممن بغى عليهم من غير ان يعتدوا، وان صبروا ففي عاقبه صبرهم خير كثير."},{"id":"4312","s":42,"a":40,"at":"وجزاء سيئه سيئه مثلها فمن عفا واصلح فاجره على الله انه لا يحب الظالمين","dt":"[40] وجزاء سيئه المسيء عقوبته بسيئه مثلها من غير زياده، فمن عفا عن المسيء، وترك عقابه، واصلح الود بينه وبين المعفو عنه ابتغاء وجه الله، فاجر عفوه عن ذلك على الله. ان الله لا يحب الظالمين الذين يبدؤون بالعدوان على الناس، ويسيئون اليهم."},{"id":"4313","s":42,"a":41,"at":"ولمن انتصر بعد ظلمه فاولئك ما عليهم من سبيل","dt":"[41] ولمن انتصر ممن ظلمه من بعد ظلمه له فاولئك ما عليهم من مؤاخذه."},{"id":"4314","s":42,"a":42,"at":"انما السبيل على الذين يظلمون الناس ويبغون في الارض بغير الحق اولئك لهم عذاب اليم","dt":"[42] انما المؤاخذه على الذين يتعدون على الناس ظلما وعدوانا، ويتجاوزون الحد الذي اباحه لهم ربهم الى ما لم ياذن لهم فيه، فيفسدون في الارض بغير الحق، اولئك لهم يوم القيامه عذاب مؤلم موجع."},{"id":"4315","s":42,"a":43,"at":"ولمن صبر وغفر ان ذلك لمن عزم الامور","dt":"[43] ولمن صبر على الاذى، وقابل الاساءه بالعفو والصفح والستر ، ان ذلك لمن عزائم الامور المشكوره والافعال الحميده التي امر الله بها، ورتب لها ثوابا جزيلا وثناء حميدا."},{"id":"4316","s":42,"a":44,"at":"ومن يضلل الله فما له من ولي من بعده وترى الظالمين لما راوا العذاب يقولون هل الى مرد من سبيل","dt":"[44] ومن يضلله الله عن الرشاد بسبب ظلمه فليس له من ناصر يهديه سبيل الرشاد. وترى -ايها الرسول- الكافرين بالله يوم القيامه -حين راوا العذاب- يقولون لربهم: هل لنا من سبيل الى الرجوع الى الدنيا؛ لنعمل بطاعتك؟ فلا يجابون الى ذلك."},{"id":"4317","s":42,"a":45,"at":"وتراهم يعرضون عليها خاشعين من الذل ينظرون من طرف خفي وقال الذين امنوا ان الخاسرين الذين خسروا انفسهم واهليهم يوم القيامه الا ان الظالمين في عذاب مقيم","dt":"[45] وترى -ايها الرسول- هؤلاء الظالمين يعرضون على النار خاضعين متذللين، ينظرون الى النار من عين ذليله ضعيفه من الخوف والهوان. وقال الذين امنوا بالله ورسوله في الجنه، لما عاينوا ما حل بالكفار من خسران: ان الخاسرين حقا هم الذين خسروا انفسهم واهليهم يوم القيامه بدخول النار. الا ان الظالمين -يوم القيامه- في عذاب دائم، لا ينقطع عنهم ولا يزول."},{"id":"4318","s":42,"a":46,"at":"وما كان لهم من اولياء ينصرونهم من دون الله ومن يضلل الله فما له من سبيل","dt":"[46] وما كان لهؤلاء الكافرين حين يعذبهم الله يوم القيامه من اعوان ونصراء ينصرونهم من عذاب الله. ومن يضلله الله بسبب كفره وظلمه، فما له من طريق يصل به الى الحق في الدنيا، والى الجنه في الاخره؛ لانه قد سدت عليه طرق النجاه، فالهدايه والاضلال بيده سبحانه وتعالى دون سواه."},{"id":"4319","s":42,"a":47,"at":"استجيبوا لربكم من قبل ان ياتي يوم لا مرد له من الله ما لكم من ملجا يومئذ وما لكم من نكير","dt":"[47] استجيبوا لربكم -ايها الكافرون- بالايمان والطاعه من قبل ان ياتي يوم القيامه، الذي لا يمكن رده، ما لكم من ملجا يومئذ ينجيكم من العذاب، ولا مكان يستركم، وتتنكرون فيه. وفي الايه دليل على ذم التسويف، وفيها الامر بالمبادره الى كل عمل صالح يعرض للعبد، فان للتاخير افات وموانع."},{"id":"4320","s":42,"a":48,"at":"فان اعرضوا فما ارسلناك عليهم حفيظا ان عليك الا البلاغ وانا اذا اذقنا الانسان منا رحمه فرح بها وان تصبهم سيئه بما قدمت ايديهم فان الانسان كفور","dt":"[48] فان اعرض هؤلاء المشركون -ايها الرسول- عن الايمان بالله فما ارسلناك عليهم حافظا لاعمالهم حتى تحاسبهم عليها، ما عليك الا البلاغ. وانا اذا اعطينا الانسان منا رحمه من غنى وسعه في المال وغير ذلك، فرح وسر، وان تصبهم مصيبه من فقر ومرض وغير ذلك بسبب ما قدمته ايديهم من معاصي الله، فان الانسان جحود يعدد المصائب، وينسى النعم."},{"id":"4321","s":42,"a":49,"at":"لله ملك السموات والارض يخلق ما يشاء يهب لمن يشاء اناثا ويهب لمن يشاء الذكور","dt":"[49] لله سبحانه وتعالى ملك السموات والارض وما فيهما، يخلق ما يشاء من الخلق، يهب لمن يشاء من عباده اناثا لا ذكور معهن، ويهب لمن يشاء الذكور لا اناث معهم،"},{"id":"4322","s":42,"a":50,"at":"او يزوجهم ذكرانا واناثا ويجعل من يشاء عقيما انه عليم قدير","dt":"[50] ويعطي سبحانه وتعالى لمن يشاء من الناس الذكر والانثى، ويجعل من يشاء عقيما لا يولد له، انه عليم بما يخلق، قدير على خلق ما يشاء، لا يعجزه شيء اراد خلقه."},{"id":"4323","s":42,"a":51,"at":"وما كان لبشر ان يكلمه الله الا وحيا او من وراء حجاب او يرسل رسولا فيوحي باذنه ما يشاء انه علي حكيم","dt":"[51] وما ينبغي لبشر من بني ادم ان يكلمه الله الا وحيا يوحيه الله اليه، او يكلمه من وراء حجاب، كما كلم سبحانه موسى عليه السلام، او يرسل رسولا، كما ينزل جبر يل - عليه السلام - الى المرسل اليه، فيوحي باذن ربه -لا بمجرد هواه- ما يشاء الله ايحاءه، انه تعالى علي بذاته واسمائه وصفاته وافعاله، قد قهر كل شيء، ودانت له المخلوقات، حكيم في تدبير امور خلقه. وفي الايه اثبات صفه الكلام لله تعالى على الوجه اللائق بجلاله وعظيم سلطانه."},{"id":"4324","s":42,"a":52,"at":"وكذلك اوحينا اليك روحا من امرنا ما كنت تدري ما الكتاب ولا الايمان ولكن جعلناه نورا نهدي به من نشاء من عبادنا وانك لتهدي الى صراط مستقيم","dt":"[52] وكما اوحينا الى الانبياء من قبلك -ايها النبي- اوحينا اليك قرانا من عندنا، ما كنت تدري قبله ما الكتب السابقه ولا الايمان ولا الشرائع الالهيه؟ ولكن جعلنا القران ضياء للناس نهدي به من نشاء من عبادنا الى الصراط المستقيم. وانك -ايها الرسول- لتدل وترشد باذن الله الى صراط مستقيم -وهو الاسلام-،"},{"id":"4325","s":42,"a":53,"at":"صراط الله الذي له ما في السموات وما في الارض الا الى الله تصير الامور","dt":"[53] صراط الله الذي له ملك جميع ما في السموات وما في الارض، لا شريك له في ذلك. الا الى الله -ايها الناس- ترجع جميع اموركم من الخير والشر، فيجازي كلا بعمله: ان خيرا فخير، وان شرا فشر."},{"id":"4326","s":43,"a":1,"at":"حم","dt":"[1] حم سبق الكلام على الحروف المقطعه في اول سوره البقره."},{"id":"4327","s":43,"a":2,"at":"والكتاب المبين","dt":"[2] اقسم الله تعالى بالقران الواضح لفظا ومعنى."},{"id":"4328","s":43,"a":3,"at":"انا جعلناه قرانا عربيا لعلكم تعقلون","dt":"[3] انا انزلنا القران على محمد -صلى الله عليه وسلم- بلسان العرب؛ لعلكم تفهمون، وتتدبرون معانيه وحججه"},{"id":"4329","s":43,"a":4,"at":"وانه في ام الكتاب لدينا لعلي حكيم","dt":"[4] وانه في اللوح المحفوظ لدينا لعلي في قدره وشرفه، محكم لا اختلاف فيه ولا تناقض."},{"id":"4330","s":43,"a":5,"at":"افنضرب عنكم الذكر صفحا ان كنتم قوما مسرفين","dt":"[5] افنعرض عنكم، ونترك انزال القران اليكم لاجل اعراضكم وعدم انقيادكم، واسرافكم في عدم الايمان به؟"},{"id":"4331","s":43,"a":6,"at":"وكم ارسلنا من نبي في الاولين","dt":"[6] كثيرا من الانبياء ارسلنا في القرون الاولى التي مضت قبل قومك ايها النبي،"},{"id":"4332","s":43,"a":7,"at":"وما ياتيهم من نبي الا كانوا به يستهزئون","dt":"[7] وما ياتيهم من نبي الا كانوا به يستهزئون كاستهزاء قومك بك،"},{"id":"4333","s":43,"a":8,"at":"فاهلكنا اشد منهم بطشا ومضى مثل الاولين","dt":"[8] فاهلكنا من كذبوا رسلنا، وكانوا اشد قوه وباسا من قومك ايها النبي، ومضت عقوبه الاولين بان اهلكوا؛ بسبب كفرهم وطغيانهم واستهزائهم بانبيائهم. وفي هذا تسليه للنبي -صلى الله عليه وسلم-."},{"id":"4334","s":43,"a":9,"at":"ولئن سالتهم من خلق السموات والارض ليقولن خلقهن العزيز العليم","dt":"[9] ولئن سالت -ايها الرسول- هؤلاء المشركين من قومك: من خلق السموات والارض؟ ليقولن: خلقهن العزيز في سلطانه، العليم بهن وما فيهن من الاشياء، لا يخفى عليه شيء."},{"id":"4335","s":43,"a":10,"at":"الذي جعل لكم الارض مهدا وجعل لكم فيها سبلا لعلكم تهتدون","dt":"[10] الذي جعل لكم الارض فراشا وبساطا، وسهل لكم فيها طرقا لمعاشكم ومتاجركم؛ لكي تهتدوا بتلك السبل الى مصالحكم الدينيه والدنيويه."},{"id":"4336","s":43,"a":11,"at":"والذي نزل من السماء ماء بقدر فانشرنا به بلده ميتا كذلك تخرجون","dt":"[11] والذي نزل من السماء مطرا بقدر، ليس طوفانا مغرقا ولا قاصرا عن الحاجه؛ حتى يكون معاشا لكم ولانعامكم، فاحيينا بالماء قطعه واسعه من الارض مقفره من النبات، كما اخرجنا بهذا الماء الذي نزلناه من السماء من هذه البلده الميته النبات والزرع، تخرجون -ايها الناس- من قبوركم بعد فنائكم."},{"id":"4337","s":43,"a":12,"at":"والذي خلق الازواج كلها وجعل لكم من الفلك والانعام ما تركبون","dt":"[12] والذي خلق الاصناف كلها من حيوان ونبات، وجعل لكم من السفن ما تركبون في البحر، ومن البهائم كالابل والخيل والبغال والحمير ما تركبون في البر."},{"id":"4338","s":43,"a":13,"at":"لتستووا على ظهوره ثم تذكروا نعمه ربكم اذا استويتم عليه وتقولوا سبحان الذي سخر لنا هذا وما كنا له مقرنين","dt":"[13] لكي تستووا على ظهور ما تركبون، ثم تتذكروا نعمه ربكم اذا ركبتم عليه، فتشكروا الله في نفوسكم، ثم تظهروا شكره بالسنتكم وتقولوا: سبحان الذي سخر لنا هذا، وما كنا له مطيقين،"},{"id":"4339","s":43,"a":14,"at":"وانا الى ربنا لمنقلبون","dt":"[14] ولتقولوا ايضا: وانا الى ربنا بعد مماتنا لصائرون اليه راجعون. وفي هذا بيان ان الله المنعم على عباده بشتى النعم، هو المستحق للعباده في كل حال."},{"id":"4340","s":43,"a":15,"at":"وجعلوا له من عباده جزءا ان الانسان لكفور مبين","dt":"[15] وجعل هؤلاء المشركون لله من خلقه نصيبا، وذلك قولهم للملائكه: بنات الله. ان الانسان لجحود لنعم ربه التي انعم بها عليه، مظهر لجحوده وكفره، يعدد المصائب، وينسى النعم."},{"id":"4341","s":43,"a":16,"at":"ام اتخذ مما يخلق بنات واصفاكم بالبنين","dt":"[16] بل اتزعمون -ايها الجاهلون- ان ربكم اتخذ مما يخلق بنات، وانتم لا ترضون ذلك لانفسكم، وخصكم بالبنين فجعلهم لكم؟ وفي هذا توبيخ لهم."},{"id":"4342","s":43,"a":17,"at":"واذا بشر احدهم بما ضرب للرحمن مثلا ظل وجهه مسودا وهو كظيم","dt":"[17] واذا بشر احدهم بالانثى -التي نسبها الى الرحمن حين زعم ان الملائكه بنات الله- صار وجهه مسودا من سوء البشاره بالانثى، وهو حزين مملوء من الهم والكرب. فكيف يرضون لله ما لا يرضونه لانفسهم؟ تعالى الله وتقدس عما يقول الكافرون علوا كبيرا."},{"id":"4343","s":43,"a":18,"at":"او من ينشا في الحليه وهو في الخصام غير مبين","dt":"[18] اتجترئون وتنسبون الى الله تعالى من يربى في الزينه، وهو في الجدال غير مبين لحجته؛ بسبب نشاته في الزينه والنعمه؟"},{"id":"4344","s":43,"a":19,"at":"وجعلوا الملائكه الذين هم عباد الرحمن اناثا اشهدوا خلقهم ستكتب شهادتهم ويسالون","dt":"[19] وجعل هؤلاء المشركون بالله الملائكه الذين هم عباد الرحمن اناثا، احضروا حين خلقهم الله حتى يحكموا بانهم اناث؟ ستكتب شهادتهم، ويسالون عنها في الاخره."},{"id":"4345","s":43,"a":20,"at":"وقالوا لو شاء الرحمن ما عبدناهم ما لهم بذلك من علم ان هم الا يخرصون","dt":"[20] وقال هؤلاء المشركون من قريش: لو شاء الرحمن ما عبدنا احدا من دونه، وهذه حجه باطله، فقد اقام الله الحجه على العباد بارسال الرسل وانزال الكتب، فاحتجاجهم بالقضاء والقدر من ابطل الباطل من بعد انذار الرسل لهم. ما لهم بحقيقه ما يقولون من ذلك من علم، وانما يقولونه تخرصا وكذبا؛ لانه لا خبر عندهم من الله بذلك ولا برهان."},{"id":"4346","s":43,"a":21,"at":"ام اتيناهم كتابا من قبله فهم به مستمسكون","dt":"[21] احضروا خلق الملائكه، ام اعطيناهم كتابا من قبل القران الذي انزلناه، فهم به مستمسكون يعملون بما فيه، ويحتجون به عليك ايها الرسول؟"},{"id":"4347","s":43,"a":22,"at":"بل قالوا انا وجدنا اباءنا على امه وانا على اثارهم مهتدون","dt":"[22] بل قالوا: انا وجدنا اباءنا على طريقه ومذهب ودين، وانا على اثار ابائنا فيما كانوا عليه متبعون لهم، ومقتدون بهم."},{"id":"4348","s":43,"a":23,"at":"وكذلك ما ارسلنا من قبلك في قريه من نذير الا قال مترفوها انا وجدنا اباءنا على امه وانا على اثارهم مقتدون","dt":"[23] وكذلك ما ارسلنا من قبلك -ايها الرسول- في قريه من نذير ينذرهم عقابنا على كفرهم بنا، فانذروهم وحذروهم سخطنا وحلول عقوبتنا، الا قال الذين ابطرتهم النعمه من الرؤساء والكبراء: انا وجدنا اباءنا على مله ودين، وانا على منهاجهم وطريقتهم مقتدون."},{"id":"4349","s":43,"a":24,"at":"قال او لو جئتكم باهدى مما وجدتم عليه اباءكم قالوا انا بما ارسلتم به كافرون","dt":"[24] قال محمد -صلى الله عليه وسلم- ومن سبقه من الرسل لمن عارضه بهذه الشبهه الباطله: اتتبعون اباءكم، ولو جئتكم من عند ربكم باهدى الى طريق الحق وادل على سبيل الرشاد مما وجدتم عليه اباءكم من الدين والمله؟ قالوا -في عناد-: انا بما ارسلتم به جاحدون كافرون."},{"id":"4350","s":43,"a":25,"at":"فانتقمنا منهم فانظر كيف كان عاقبه المكذبين","dt":"[25] فانتقمنا من هذه الامم المكذبه رسلها باحلالنا العقوبه بهم خسفا وغرقا وغير ذلك، فانظر -ايها الرسول- كيف كان عاقبه امرهم اذ كذبوا بايات الله ورسله؟ وليحذر قومك ان يستمروا على تكذيبهم، فيصيبهم مثل ما اصابهم."},{"id":"4351","s":43,"a":26,"at":"واذ قال ابراهيم لابيه وقومه انني براء مما تعبدون","dt":"[26] واذكر -ايها الرسول- اذ قال ابراهيم لابيه وقومه الذين كانوا يعبدون ما يعبده قومك: انني براء مما تعبدون من دون الله."},{"id":"4352","s":43,"a":27,"at":"الا الذي فطرني فانه سيهدين","dt":"[27] الا الذي خلقني، فانه سيوفقني لاتباع سبيل الرشاد."},{"id":"4353","s":43,"a":28,"at":"وجعلها كلمه باقيه في عقبه لعلهم يرجعون","dt":"[28] وجعل ابراهيم عليه السلام كلمه التوحيد (لا اله الا الله) باقيه فيمن بعده؛ لعلهم يرجعون الى طاعه ربهم وتوحيده، ويتوبون من كفرهم وذنوبهم."},{"id":"4354","s":43,"a":29,"at":"بل متعت هؤلاء واباءهم حتى جاءهم الحق ورسول مبين","dt":"[29] بل متعت -ايها الرسول- هؤلاء المشركين من قومك واباءهم من قبلهم بالحياه، فلم اعاجلهم بالعقوبه على كفرهم، حتى جاءهم القران ورسول يبين لهم ما يحتاجون اليه من امور دينهم."},{"id":"4355","s":43,"a":30,"at":"ولما جاءهم الحق قالوا هذا سحر وانا به كافرون","dt":"[30] ولما جاءهم القران من عند الله قالوا: هذا الذي جاءنا به هذا الرسول سحر يسحرنا به، وليس بوحي من عند الله، وانا به مكذبون."},{"id":"4356","s":43,"a":31,"at":"وقالوا لولا نزل هذا القران على رجل من القريتين عظيم","dt":"[31] وقال هؤلاء المشركون من قريش: ان كان هذا القران من عند الله حقا، فهلا نزل على رجل عظيم من احدى هاتين القريتين «مكه» او «الطائف»."},{"id":"4357","s":43,"a":32,"at":"اهم يقسمون رحمه ربك نحن قسمنا بينهم معيشتهم في الحياه الدنيا ورفعنا بعضهم فوق بعض درجات ليتخذ بعضهم بعضا سخريا ورحمه ربك خير مما يجمعون","dt":"[32] اهم يقسمون النبوه فيضعونها حيث شاؤوا؟ نحن قسمنا بينهم معيشتهم في حياتهم الدنيا من الارزاق والاقوات، ورفعنا بعضهم فوق بعض درجات: هذا غني وهذا فقير، وهذا قوي وهذا ضعيف؛ ليكون بعضهم مسخرا لبعض في المعاش. ورحمه ربك -ايها الرسول- بادخالهم الجنه خير مما يجمعون من حطام الدنيا الفاني."},{"id":"4358","s":43,"a":33,"at":"ولولا ان يكون الناس امه واحده لجعلنا لمن يكفر بالرحمن لبيوتهم سقفا من فضه ومعارج عليها يظهرون","dt":"[33] ولولا ان يكون الناس جماعه واحده على الكفر، لجعلنا لمن يكفر بالرحمن لبيوتهم سقفا من فضه وسلالم عليها يصعدون."},{"id":"4359","s":43,"a":34,"at":"ولبيوتهم ابوابا وسررا عليها يتكئون","dt":"[34] وجعلنا لبيوتهم ابوابا من فضه، وجعلنا لهم سررا عليها يتكئون،"},{"id":"4360","s":43,"a":35,"at":"وزخرفا وان كل ذلك لما متاع الحياه الدنيا والاخره عند ربك للمتقين","dt":"[35] وجعلنا لهم ذهبا، وما كل ذلك الا متاع الحياه الدنيا، وهو متاع قليل زائل، ونعيم الاخره مدخر عند ربك للمتقين ليس لغيرهم."},{"id":"4361","s":43,"a":36,"at":"ومن يعش عن ذكر الرحمن نقيض له شيطانا فهو له قرين","dt":"[36] ومن يعرض عن ذكر الرحمن، وهو القران، فلم يخف عقابه، ولم يهتد بهدايته، نجعل له شيطانا في الدنيا يغويه؛ جزاء له على اعراضه عن ذكر الله، فهو له ملازم ومصاحب يمنعه الحلال، ويبعثه على الحرام."},{"id":"4362","s":43,"a":37,"at":"وانهم ليصدونهم عن السبيل ويحسبون انهم مهتدون","dt":"[37] وان الشياطين ليصدون عن سبيل الحق هؤلاء الذين يعرضون عن ذكر الله، فيزينون لهم الضلاله، ويكرهون لهم الايمان بالله والعمل بطاعته، ويظن هؤلاء المعرضون بتحسين الشياطين لهم ما هم عليه من الضلال انهم على الحق والهدى."},{"id":"4363","s":43,"a":38,"at":"حتى اذا جاءنا قال ياليت بيني وبينك بعد المشرقين فبئس القرين","dt":"[38] حتى اذا جاءنا الذي اعرض عن ذكر الرحمن للحساب والجزاء، قال لقرينه: وددت ان بيني وبينك بعد ما بين المشرق والمغرب، فبئس القرين لي انت؛ حيث اغويتني."},{"id":"4364","s":43,"a":39,"at":"ولن ينفعكم اليوم اذ ظلمتم انكم في العذاب مشتركون","dt":"[39] ولن ينفعكم اليوم -ايها المعرضون- عن ذكر الله اذ اشركتم في الدنيا انكم في العذاب مشتركون انتم وقرناؤكم، فلكل واحد نصيبه الاوفر من العذاب، كما اشتركتم في الكفر."},{"id":"4365","s":43,"a":40,"at":"افانت تسمع الصم او تهدي العمي ومن كان في ضلال مبين","dt":"[40] افانت -ايها الرسول- تسمع من اصمه الله عن سماع الحق، او تهدي الى طريق الهدى من اعمى قلبه عن ابصاره، او تهدي من كان في ضلال عن الحق بين واضح؟ ليس ذلك اليك، انما عليك البلاغ، وليس عليك هداهم، ولكن الله يهدي من يشاء، ويضل من يشاء."},{"id":"4366","s":43,"a":41,"at":"فاما نذهبن بك فانا منهم منتقمون","dt":"[41] فان توفيناك -ايها الرسول- قبل نصرك على المكذبين من قومك، فانا منهم منتقمون في الاخره،"},{"id":"4367","s":43,"a":42,"at":"او نرينك الذي وعدناهم فانا عليهم مقتدرون","dt":"[42] او نرينك الذي وعدناهم من العذاب النازل بهم كيوم «بدر»، فانا عليهم مقتدرون نظهرك عليهم، ونخزيهم بيدك وايدي المؤمنين بك."},{"id":"4368","s":43,"a":43,"at":"فاستمسك بالذي اوحي اليك انك على صراط مستقيم","dt":"[43] فاستمسك -ايها الرسول- بما يامرك به الله في هذا القران الذي اوحاه اليك؛ انك على صراط مستقيم، وذلك هو دين الله الذي امر به، وهو الاسلام. وفي هذا تثبيت للرسول -صلى الله عليه وسلم-، وثناء عليه."},{"id":"4369","s":43,"a":44,"at":"وانه لذكر لك ولقومك وسوف تسالون","dt":"[44] وان هذا القران لشرف لك ولقومك من قريش؛ حيث انزل بلغتهم، فهم افهم الناس له، فينبغي ان يكونوا اقوم الناس به، واعملهم بمقتضاه، وسوف تسال انت ومن معك عن الشكر لله عليه، والعمل به، والدعوه اليه."},{"id":"4370","s":43,"a":45,"at":"واسال من ارسلنا من قبلك من رسلنا اجعلنا من دون الرحمن الهه يعبدون","dt":"[45]واسال -ايها الرسول- اتباع من ارسلنا من قبلك من رسلنا وحمله شرائعهم: اجاءت رسلهم بعباده غير الله؟ فانهم يخبرونك ان ذلك لم يقع؛ فان جميع الرسل دعوا الى ما دعوت الناس اليه من عباده الله وحده لا شريك له، ونهوا عن عباده ما سوى الله."},{"id":"4371","s":43,"a":46,"at":"ولقد ارسلنا موسى باياتنا الى فرعون وملئه فقال اني رسول رب العالمين","dt":"[46] ولقد ارسلنا موسى بحججنا الى فرعون واشراف قومه، كما ارسلناك -ايها الرسول- الى هؤلاء المشركين من قومك، فقال لهم موسى: اني رسول رب العالمين،"},{"id":"4372","s":43,"a":47,"at":"فلما جاءهم باياتنا اذا هم منها يضحكون","dt":"[47] فلما جاءهم بالبينات الواضحات الداله على صدقه في دعوته، اذا فرعون وملؤه مما جاءهم به موسى من الايات والعبر يضحكون."},{"id":"4373","s":43,"a":48,"at":"وما نريهم من ايه الا هي اكبر من اختها واخذناهم بالعذاب لعلهم يرجعون","dt":"[48] وما نري فرعون وملاه من حجه الا هي اعظم من التي قبلها، وادل على صحه ما يدعوهم موسى اليه، واخذناهم بصنوف العذاب كالجراد والقمل والضفادع والطوفان، وغير ذلك؛ لعلهم يرجعون عن كفرهم بالله الى توحيده وطاعته."},{"id":"4374","s":43,"a":49,"at":"وقالوا ياايها الساحر ادع لنا ربك بما عهد عندك اننا لمهتدون","dt":"[49] وقال فرعون وملؤه لموسى: يا ايها العالم -وكان الساحر فيهم عظيما يوقرونه، ولم يكن السحر صفه ذم- ادع لنا ربك بعهده الذي عهد اليك وما خصك به من الفضائل ان يكشف عنا العذاب، فان كشف عنا العذاب فاننا لمهتدون مؤمنون بما جئتنا به."},{"id":"4375","s":43,"a":50,"at":"فلما كشفنا عنهم العذاب اذا هم ينكثون","dt":"[50] فلما دعا موسى برفع العذاب عنهم، ورفعناه عنهم اذا هم يغدرون، ويصرون على ضلالهم."},{"id":"4376","s":43,"a":51,"at":"ونادى فرعون في قومه قال ياقوم اليس لي ملك مصر وهذه الانهار تجري من تحتي افلا تبصرون","dt":"[51] ونادى فرعون في عظماء قومه متبجحا مفتخرا بملك «مصر»: اليس لي ملك «مصر»، وهذه فروع نهر النيل تجري من تحت قصري ومن بين يدي في بساتيني، افلا تبصرون عظمتي وقوتي، وضعف موسى وفقره؟"},{"id":"4377","s":43,"a":52,"at":"ام انا خير من هذا الذي هو مهين ولا يكاد يبين","dt":"[52] بل انا خير من هذا الذي لا عز معه، فهو يمتهن نفسه في حاجاته لضعفه وحقارته، ولا يكاد يبين الكلام لعي لسانه، وقد حمل فرعون على هذا القول الكفر والعناد والصد عن سبيل الله."},{"id":"4378","s":43,"a":53,"at":"فلولا القي عليه اسوره من ذهب او جاء معه الملائكه مقترنين","dt":"[53] فهلا القي على موسى -ان كان صادقا انه رسول رب العالمين- اسوره من ذهب، او جاء معه الملائكه قد اقترن بعضهم ببعض، فتتابعوا يشهدون له بانه رسول الله الينا."},{"id":"4379","s":43,"a":54,"at":"فاستخف قومه فاطاعوه انهم كانوا قوما فاسقين","dt":"[54] فاستخف فرعون عقول قومه فدعاهم الى الضلاله، فاطاعوه وكذبوا موسى، انهم كانوا قوما خارجين عن طاعه الله وصراطه المستقيم."},{"id":"4380","s":43,"a":55,"at":"فلما اسفونا انتقمنا منهم فاغرقناهم اجمعين","dt":"[55] فلما اغضبونا -بعصياننا، وتكذيب موسى وما جاء به من الايات- انتقمنا منهم بعاجل العذاب الذي عجلناه لهم، فاغرقناهم اجمعين في البحر."},{"id":"4381","s":43,"a":56,"at":"فجعلناهم سلفا ومثلا للاخرين","dt":"[56] فجعلنا هؤلاء الذين اغرقناهم في البحر سلفا لمن يعمل مثل عملهم ممن ياتي بعدهم في استحقاق العذاب، وعبره وعظه للاخرين."},{"id":"4382","s":43,"a":57,"at":"ولما ضرب ابن مريم مثلا اذا قومك منه يصدون","dt":"[57] ولما ضرب المشركون عيسى بن مريم مثلا حين خاصموا محمدا -صلى الله عليه وسلم-، وحاجوه بعباده النصارى اياه، اذا قومك من ذلك ولاجله يرتفع لهم جلبه وضجيج فرحا وسرورا، وذلك عندما نزل قوله تعالى:انكم وما تعبدون من دون الله حصب جهنم انتم لها وردون، وقال المشركون: رضينا ان تكون الهتنا بمنزله عيسى، فانزل الله قوله:ان الذين سبقت لهم منا الحسنى اولئك عنها مبعدون، فالذي يلقى في النار من الهه المشركين من رضي بعبادتهم اياه."},{"id":"4383","s":43,"a":58,"at":"وقالوا االهتنا خير ام هو ما ضربوه لك الا جدلا بل هم قوم خصمون","dt":"[58] وقال مشركو قومك -ايها الرسول-: ا الهتنا التي نعبدها خير ام عيسى الذي يعبده قومه؟ فاذا كان عيسى في النار، فلنكن نحن والهتنا معه، ما ضربوا لك هذا المثل الا جدلا، بل هم قوم مخاصمون بالباطل."},{"id":"4384","s":43,"a":59,"at":"ان هو الا عبد انعمنا عليه وجعلناه مثلا لبني اسرائيل","dt":"[59] ما عيسى بن مريم الا عبد انعمنا عليه بالنبوه، وجعلناه ايه وعبره لبني اسرائيل يستدل بها على قدرتنا."},{"id":"4385","s":43,"a":60,"at":"ولو نشاء لجعلنا منكم ملائكه في الارض يخلفون","dt":"[60] ولو نشاء لجعلنا بدلا منكم ملائكه يخلف بعضهم بعضا بدلا من بني ادم."},{"id":"4386","s":43,"a":61,"at":"وانه لعلم للساعه فلا تمترن بها واتبعون هذا صراط مستقيم","dt":"[61] وان نزول عيسى عليه السلام قبل يوم القيامه لدليل على قرب وقوع الساعه، فلا تشكوا انها واقعه لا محاله، واتبعون فيما اخبركم به عن الله تعالى، هذا طريق قويم الى الجنه، لا اعوجاج فيه."},{"id":"4387","s":43,"a":62,"at":"ولا يصدنكم الشيطان انه لكم عدو مبين","dt":"[62] ولا يصدنكم الشيطان بوساوسه عن طاعتي فيما امركم به وانهاكم عنه، انه لكم عدو بين العداوه."},{"id":"4388","s":43,"a":63,"at":"ولما جاء عيسى بالبينات قال قد جئتكم بالحكمه ولابين لكم بعض الذي تختلفون فيه فاتقوا الله واطيعون","dt":"[63] ولما جاء عيسى بني اسرائيل بالبينات الواضحات من الادله قال: قد جئتكم بالنبوه، ولابين لكم بعض الذي تختلفون فيه من امور الدين، فاتقوا الله بامتثال اوامره واجتناب نواهيه، واطيعون فيما امرتكم به من تقوى الله وطاعته."},{"id":"4389","s":43,"a":64,"at":"ان الله هو ربي وربكم فاعبدوه هذا صراط مستقيم","dt":"[64] ان الله - سبحانه وتعالى - هو ربي وربكم جميعا فاعبدوه وحده، ولا تشركوا به شيئا، هذا الذي امرتكم به من تقوى الله و افراده بالالوهيه هو الطريق المستقيم، وهو دين الله الحق الذي لا يقبل من احد سواه."},{"id":"4390","s":43,"a":65,"at":"فاختلف الاحزاب من بينهم فويل للذين ظلموا من عذاب يوم اليم","dt":"[65] فاختلفت فرق النصارى في امر عيسى عليه السلام، وصاروا فيه شيعا: منهم من يقر بانه عبد الله ورسوله، وهو الحق، ومنهم من يزعم انه ابن الله، ومنهم من يقول: انه الله، تعالى الله عن قولهم علوا كبيرا، فهلاك وعذاب اليم يوم القيامه لمن وصفوا عيسى بغير ما وصفه الله به."},{"id":"4391","s":43,"a":66,"at":"هل ينظرون الا الساعه ان تاتيهم بغته وهم لا يشعرون","dt":"[66] هل ينتظر هؤلاء الاحزاب المختلفون في عيسى بن مريم الا الساعه ان تاتيهم فجاه، وهم لا يشعرون ولا يفطنون؟"},{"id":"4392","s":43,"a":67,"at":"الاخلاء يومئذ بعضهم لبعض عدو الا المتقين","dt":"[67] الاصدقاء على معاصي الله في الدنيا يتبرا بعضهم من بعض يوم القيامه، لكن الذين تصادقوا على تقوى الله، فان صداقتهم دائمه في الدنيا والاخره."},{"id":"4393","s":43,"a":68,"at":"ياعباد لا خوف عليكم اليوم ولا انتم تحزنون","dt":"[68] يقال لهؤلاء المتقين: يا عبادي لا خوف عليكم اليوم من عقابي، ولا انتم تحزنون على ما فاتكم من حظوظ الدنيا."},{"id":"4394","s":43,"a":69,"at":"الذين امنوا باياتنا وكانوا مسلمين","dt":"[69] الذين امنوا باياتنا وعملوا بما جاءتهم به رسلهم، وكانوا منقادين لله رب العالمين بقلوبهم وجوارحهم،"},{"id":"4395","s":43,"a":70,"at":"ادخلوا الجنه انتم وازواجكم تحبرون","dt":"[70] يقال لهم: ادخلوا الجنه انتم وقرناؤكم المؤمنون تنعمون وتسرون."},{"id":"4396","s":43,"a":71,"at":"يطاف عليهم بصحاف من ذهب واكواب وفيها ما تشتهيه الانفس وتلذ الاعين وانتم فيها خالدون","dt":"[71] يطاف على هؤلاء الذين امنوا بالله ورسله في الجنه بالطعام في اوان من ذهب، وبالشراب في اكواب من ذهب، وفيها لهم ما تشتهيه انفسهم وتسر به اعينهم، وهم ماكثون فيها ابدا."},{"id":"4397","s":43,"a":72,"at":"وتلك الجنه التي اورثتموها بما كنتم تعملون","dt":"[72] وهذه الجنه التي اورثكم الله اياها؛ بسبب ما كنتم تعملون في الدنيا من الخيرات والاعمال الصالحات، وجعلها من فضله ورحمته جزاء لكم."},{"id":"4398","s":43,"a":73,"at":"لكم فيها فاكهه كثيره منها تاكلون","dt":"[73] لكم في الجنه فاكهه كثيره من كل نوع منها تاكلون."},{"id":"4399","s":43,"a":74,"at":"ان المجرمين في عذاب جهنم خالدون","dt":"[74] ان الذين اكتسبوا الذنوب بكفرهم، في عذاب جهنم ماكثون،"},{"id":"4400","s":43,"a":75,"at":"لا يفتر عنهم وهم فيه مبلسون","dt":"[75] لا يخفف عنهم، وهم فيه ايسون من رحمه الله،"},{"id":"4401","s":43,"a":76,"at":"وما ظلمناهم ولكن كانوا هم الظالمين","dt":"[76] وما ظلمنا هؤلاء المجرمين بالعذاب، ولكن كانوا هم الظالمين انفسهم بشركهم وجحودهم ان الله هو الاله الحق وحده لا شريك له، وترك اتباعهم لرسل ربهم."},{"id":"4402","s":43,"a":77,"at":"ونادوا يامالك ليقض علينا ربك قال انكم ماكثون","dt":"[77] ونادى هؤلاء المجرمون بعد ان ادخلهم الله جهنم «مالكا» خازن جهنم: يا مالك ليمتنا ربك، فنستريح مما نحن فيه، فاجابهم مالك: انكم ماكثون، لا خروج لكم منها، ولا محيد لكم عنها،"},{"id":"4403","s":43,"a":78,"at":"لقد جئناكم بالحق ولكن اكثركم للحق كارهون","dt":"[78] لفد جئناكم بالحق ووضحناه لكم، ولكن اكثركم لما جاء به الرسل من الحق كارهون."},{"id":"4404","s":43,"a":79,"at":"ام ابرموا امرا فانا مبرمون","dt":"[79] بل ااحكم هؤلاء المشركون امرا يكيدون به الحق الذي جئناهم به؟ فانا مدبرون لهم ما يجزيهم من العذاب والنكال."},{"id":"4405","s":43,"a":80,"at":"ام يحسبون انا لا نسمع سرهم ونجواهم بلى ورسلنا لديهم يكتبون","dt":"[80] ام يظن هؤلاء المشركون بالله انا لا نسمع ما يسرونه في انفسهم، ويتناجون به بينهم؟ بلى نسمع ونعلم، ورسلنا الملائكه الكرام الحفظه يكتبون عليهم كل ما عملوا."},{"id":"4406","s":43,"a":81,"at":"قل ان كان للرحمن ولد فانا اول العابدين","dt":"[81] قل -ايها الرسول- لمشركي قومك الزاعمين ان الملائكه بنات الله: ان كان للرحمن ولد كما تزعمون، فانا اول العابدين لهذا الولد الذي تزعمونه، ولكن هذا لم يكن ولا يكون، فتقدس الله عن الصاحبه والولد."},{"id":"4407","s":43,"a":82,"at":"سبحان رب السموات والارض رب العرش عما يصفون","dt":"[82] تنزيها وتقديسا لرب السموات والارض رب العرش العظيم عما يصفون من الكذب والافتراء من نسبه المشركين الولد الى الله، وغير ذلك مما يزعمون من الباطل."},{"id":"4408","s":43,"a":83,"at":"فذرهم يخوضوا ويلعبوا حتى يلاقوا يومهم الذي يوعدون","dt":"[83] فاترك -ايها الرسول- هؤلاء المفترين على الله يخوضوا في باطلهم، ويلعبوا في دنياهم، حتى يلاقوا يومهم الذي فيه يوعدون بالعذاب: اما في الدنيا واما في الاخره واما فيهما معا."},{"id":"4409","s":43,"a":84,"at":"وهو الذي في السماء اله وفي الارض اله وهو الحكيم العليم","dt":"[84] وهو الله وحده المعبود بحق في السماء وفي الارض، وهو الحكيم الذي احكم خلقه، واتقن شرعه، العليم بكل شيء من احوال خلقه، لا يخفى عليه شيء منها."},{"id":"4410","s":43,"a":85,"at":"وتبارك الذي له ملك السموات والارض وما بينهما وعنده علم الساعه واليه ترجعون","dt":"[85] وتكاثرت بركه الله، وكثر خيره، وعظم ملكه، الذي له وحده سلطان السموات السبع والارضين السبع وما بينهما من الاشياء كلها، وعنده علم الساعه التي تقوم فيها القيامه، ويحشر فيها الخلق من قبورهم لموقف الحساب، واليه تردون -ايها الناس- بعد مماتكم، فيجازي كلا بما يستحق."},{"id":"4411","s":43,"a":86,"at":"ولا يملك الذين يدعون من دونه الشفاعه الا من شهد بالحق وهم يعلمون","dt":"[86] ولا يملك الذين يعبدهم المشركون الشفاعه عنده لاحد الا من شهد بالحق، واقر بتوحيد الله وبنبوه محمد -صلى الله عليه وسلم-، وهم يعلمون حقيقه ما اقروا وشهدوا به."},{"id":"4412","s":43,"a":87,"at":"ولئن سالتهم من خلقهم ليقولن الله فانى يؤفكون","dt":"[87] ولئن سالت -ايها الرسول- هؤلاء المشركين من قومك من خلقهم؟ ليقولن: الله خلقنا، فكيف ينقلبون وينصرفون عن عباده الله، ويشركون به غيره؟"},{"id":"4413","s":43,"a":88,"at":"وقيله يارب ان هؤلاء قوم لا يؤمنون","dt":"[88] وقال محمد -صلى الله عليه وسلم- شاكيا الى ربه قومه الذين كذبوه: يا رب ان هؤلاء قوم لا يؤمنون بك وبما ارسلتني به اليهم."},{"id":"4414","s":43,"a":89,"at":"فاصفح عنهم وقل سلام فسوف يعلمون","dt":"[89] فامره الله بالاعراض عنهم وعن اذاهم، وتركهم بسبب كفرهم وعنادهم، ولا يبدر منك -ايها الرسول- الا السلام لهم الذي يقوله اولو الالباب والبصائر للجاهلين، فهم لا يسافهونهم ولا يعاملونهم بمثل اعمالهم السيئه، فسوف يعلمون ما يلقونه من البلاء والنكال. وفي هذا تهديد ووعيد شديد لهؤلاء الكافرين المعاندين وامثالهم."},{"id":"4415","s":44,"a":1,"at":"حم","dt":"[1] حم سبق الكلام على الحروف المقطعه في اول سوره البقره."},{"id":"4416","s":44,"a":2,"at":"والكتاب المبين","dt":"[2] اقسم الله تعالى بالقران الواضح لفظا ومعنى."},{"id":"4417","s":44,"a":3,"at":"انا انزلناه في ليله مباركه انا كنا منذرين","dt":"[3] انا انزلناه في ليله القدر المباركه الكثيره الخيرات، وهي في رمضان. انا كنا منذرين الناس بما ينفعهم و يضرهم، وذلك بارسال الرسل وانزال الكتب؛ لتقوم حجه الله على عباده."},{"id":"4418","s":44,"a":4,"at":"فيها يفرق كل امر حكيم","dt":"[4] فيها يقضى ويفصل من اللوح المحفوظ الى الكتبه من الملائكه كل امر محكم من الاجال والارزاق في تلك السنه، وغير ذلك مما يكون فيها الى اخرها، لا يبدل ولا يغير."},{"id":"4419","s":44,"a":5,"at":"امرا من عندنا انا كنا مرسلين","dt":"[5] هذا الامر الحكيم امر من عندنا، فجميع ما يكون ويقدره الله تعالى وما يوحيه فبامره واذنه وعلمه. انا كنا مرسلين الى الناس الرسل محمدا ومن قبله؛"},{"id":"4420","s":44,"a":6,"at":"رحمه من ربك انه هو السميع العليم","dt":"[6] رحمه من ربك -ايها الرسول- بالمرسل اليهم. انه هو السميع يسمع جميع الاصوات، العليم بجميع امور خلقه الظاهره والباطنه."},{"id":"4421","s":44,"a":7,"at":"رب السموات والارض وما بينهما ان كنتم موقنين","dt":"[7] خالق السموات والارض وما بينهما من الاشياء كلها، ان كنتم موقنين بذلك فاعلموا ان رب المخلوقات هو الهها الحق."},{"id":"4422","s":44,"a":8,"at":"لا اله الا هو يحيي ويميت ربكم ورب ابائكم الاولين","dt":"[8] لا اله يستحق العباده الا هو وحده لا شريك له، يحيي ويميت، ربكم ورب ابائكم الاولين، فاعبدوه دون الهتكم التي لا تقدر على ضر ولا نفع."},{"id":"4423","s":44,"a":9,"at":"بل هم في شك يلعبون","dt":"[9] بل هؤلاء المشركون في شك من الحق، فهم يلهون ويلعبون، ولا يصدقون به."},{"id":"4424","s":44,"a":10,"at":"فارتقب يوم تاتي السماء بدخان مبين","dt":"[10] فانتظر -ايها الرسول- بهؤلاء المشركين يوم تاتي السماء بدخان مبين واضح يعم الناس،"},{"id":"4425","s":44,"a":11,"at":"يغشى الناس هذا عذاب اليم","dt":"[11] ويقال لهم: هذا عذاب مؤلم موجع،"},{"id":"4426","s":44,"a":12,"at":"ربنا اكشف عنا العذاب انا مؤمنون","dt":"[12] ثم يقولون سائلين رفعه وكشفه عنهم: ربنا اكشف عنا العذاب، فان كشفته عنا فانا مؤمنون بك. وقد تحقق ذلك، فلم يؤمنوا كما وعدوا."},{"id":"4427","s":44,"a":13,"at":"انى لهم الذكرى وقد جاءهم رسول مبين","dt":"[13] كيف يكون لهم التذكر والاتعاظ بعد نزول العذاب بهم، وقد جاءهم رسول مبين، وهو محمد عليه الصلاه والسلام،"},{"id":"4428","s":44,"a":14,"at":"ثم تولوا عنه وقالوا معلم مجنون","dt":"[14] ثم اعرضوا عنه وقالوا: علمه بشر او الكهنه او الشياطين، هو مجنون وليس برسول؟"},{"id":"4429","s":44,"a":15,"at":"انا كاشفوا العذاب قليلا انكم عائدون","dt":"[15] سنرفع عنكم العذاب قليلا، وسترون انكم تعودون الى ما كنتم فيه من الكفر والضلال والتكذيب، واننا سنعاقبكم على ذلك."},{"id":"4430","s":44,"a":16,"at":"يوم نبطش البطشه الكبرى انا منتقمون","dt":"[16] يوم نعذب جميع الكفار العذاب الاكبر يوم القيامه وهو يوم انتقامنا منهم."},{"id":"4431","s":44,"a":17,"at":"ولقد فتنا قبلهم قوم فرعون وجاءهم رسول كريم","dt":"[17] ولقد اختبرنا وابتلينا قبل هؤلاء المشركين قوم فرعون، وجاءهم رسول كريم، وهو موسى عليه السلام، فكذبوه فهلكوا، فهكذا نفعل باعدائك ايها الرسول، ان لم يؤمنوا."},{"id":"4432","s":44,"a":18,"at":"ان ادوا الي عباد الله اني لكم رسول امين","dt":"[18] وقال لهم موسى: ان سلموا الي عباد الله من بني اسرائيل وارسلوهم معي؛ ليعبدوا الله وحده لا شريك له، اني لكم رسول امين على وحيه ورسالته."},{"id":"4433","s":44,"a":19,"at":"وان لا تعلوا على الله اني اتيكم بسلطان مبين","dt":"[19] والا تتكبروا على الله بتكذيب رسله، اني اتيكم ببرهان واضح على صدق رسالتي،"},{"id":"4434","s":44,"a":20,"at":"واني عذت بربي وربكم ان ترجمون","dt":"[20] واني استجرت بالله ربي وربكم ان تقتلوني رجما بالحجاره،"},{"id":"4435","s":44,"a":21,"at":"وان لم تؤمنوا لي فاعتزلون","dt":"[21] وان لم تصدقوني على ما جئتكم به فخلوا سبيلي، وكفوا عن اذاي."},{"id":"4436","s":44,"a":22,"at":"فدعا ربه ان هؤلاء قوم مجرمون","dt":"[22] فدعا موسى ربه -حين كذبه فرعون وقومه ولم يؤمنوا به- قائلا: ان هؤلاء قوم مشركون بالله كافرون."},{"id":"4437","s":44,"a":23,"at":"فاسر بعبادي ليلا انكم متبعون","dt":"[23] فاسر -يا موسى- بعبادي -الذين صدقوك، وامنوا بك، واتبعوك، دون الذين كذبوك منهم- ليلا، انكم متبعون من فرعون وجنوده فتنجون، ويغرق فرعون وجنوده."},{"id":"4438","s":44,"a":24,"at":"واترك البحر رهوا انهم جند مغرقون","dt":"[24] واترك البحر كما هو على حالته التي كان عليها حين سلكته، ساكنا غير مضطرب، ان فرعون وجنوده مغرقون في البحر."},{"id":"4439","s":44,"a":25,"at":"كم تركوا من جنات وعيون","dt":"[25] كم ترك فرعون وقومه بعد مهلكهم واغراق الله اياهم من بساتين وجنات ناضره، وعيون من الماء جاريه،"},{"id":"4440","s":44,"a":26,"at":"وزروع ومقام كريم","dt":"[26] وزروع ومنازل جميله،"},{"id":"4441","s":44,"a":27,"at":"ونعمه كانوا فيها فاكهين","dt":"[27] وعيشه كانوا فيها متنعمين مترفين."},{"id":"4442","s":44,"a":28,"at":"كذلك واورثناها قوما اخرين","dt":"[28] مثل ذلك العقاب يعاقب الله من كذب وبدل نعمه الله كفرا، واورثنا تلك النعم من بعد فرعون وقومه قوما اخرين خلفوهم من بني اسرائيل."},{"id":"4443","s":44,"a":29,"at":"فما بكت عليهم السماء والارض وما كانوا منظرين","dt":"[29] فما بكت السماء والارض حزنا على فرعون وقومه، وما كانوا مؤخرين عن العقوبه التي حلت بهم."},{"id":"4444","s":44,"a":30,"at":"ولقد نجينا بني اسرائيل من العذاب المهين","dt":"[30] ولقد نجينا بني اسرائيل من العذاب المذل لهم بقتل ابنائهم واستخدام نسائهم."},{"id":"4445","s":44,"a":31,"at":"من فرعون انه كان عاليا من المسرفين","dt":"[31] من فرعون، انه كان جبارا من المشركين، مسرفا في العلو والتكبر على عباد الله."},{"id":"4446","s":44,"a":32,"at":"ولقد اخترناهم على علم على العالمين","dt":"[32] ولقد اصطفينا بني اسرائيل على علم منا بهم على عالمي زمانهم."},{"id":"4447","s":44,"a":33,"at":"واتيناهم من الايات ما فيه بلاء مبين","dt":"[33] واتيناهم من المعجزات على يد موسى ما فيه ابتلاؤهم واختبارهم؛ رخاء وشده."},{"id":"4448","s":44,"a":34,"at":"ان هؤلاء ليقولون","dt":"[34] ان هؤلاء المشركين من قومك -ايها الرسول- ليقولون:"},{"id":"4449","s":44,"a":35,"at":"ان هي الا موتتنا الاولى وما نحن بمنشرين","dt":"[35] ما هي الا موتتنا التي نموتها، وهي الموته الاولى والاخيره، وما نحن بعد مماتنا بمبعوثين للحساب والثواب والعقاب."},{"id":"4450","s":44,"a":36,"at":"فاتوا بابائنا ان كنتم صادقين","dt":"[36] ويقولون ايضا: فات -يا محمد انت ومن معك- بابائنا الذين قد ماتوا، ان كنتم صادقين في ان الله يبعث من في القبور احياء."},{"id":"4451","s":44,"a":37,"at":"اهم خير ام قوم تبع والذين من قبلهم اهلكناهم انهم كانوا مجرمين","dt":"[37] اهؤلاء المشركون خير ام قوم تبع الحميري والذين من قبلهم من الامم الكافره بربها؟ اهلكناهم لاجرامهم وكفرهم، ليس هؤلاء المشركون بخير من اولئكم فنصفح عنهم ولا نهلكهم، وهم بالله كافرون."},{"id":"4452","s":44,"a":38,"at":"وما خلقنا السموات والارض وما بينهما لاعبين","dt":"[38] وما خلقنا السموات والارض وما بينهما لعبا،"},{"id":"4453","s":44,"a":39,"at":"ما خلقناهما الا بالحق ولكن اكثرهم لا يعلمون","dt":"[39] ما خلقناهما الا بالحق الذي هو سنه الله في خلقه وتدبيره، ولكن اكثر هؤلاء المشركين لا يعلمون ذلك، فلهذا لم يتفكروا فيهما؛ لانهم لا يرجون ثوابا ولا يخافون عقابا."},{"id":"4454","s":44,"a":40,"at":"ان يوم الفصل ميقاتهم اجمعين","dt":"[40] ان يوم القضاء بين الخلق بما قدموا في دنياهم من خير او شر هو ميقاتهم اجمعين."},{"id":"4455","s":44,"a":41,"at":"يوم لا يغني مولى عن مولى شيئا ولا هم ينصرون","dt":"[41] يوم لا يدفع صاحب عن صاحبه شيئا، ولا ينصر بعضهم بعضا،"},{"id":"4456","s":44,"a":42,"at":"الا من رحم الله انه هو العزيز الرحيم","dt":"[42] الا من رحم الله من المؤمنين، فانه قد يشفع له عند ربه بعد اذن الله له. ان الله هو العزيز في انتقامه من اعدائه، الرحيم باوليائه واهل طاعته."},{"id":"4457","s":44,"a":43,"at":"ان شجره الزقوم","dt":"[43] ان شجره الزقوم التي تخرج في اصل الجحيم،"},{"id":"4458","s":44,"a":44,"at":"طعام الاثيم","dt":"[44] ثمرها طعام صاحب الاثام الكثيره، واكبر الاثام الشرك بالله."},{"id":"4459","s":44,"a":45,"at":"كالمهل يغلي في البطون","dt":"[45] ثمر شجره الزقوم كالمعدن المذاب يغلي في بطون المشركين،"},{"id":"4460","s":44,"a":46,"at":"كغلي الحميم","dt":"[46] كغلي الماء الذي بلغ الغايه في الحراره."},{"id":"4461","s":44,"a":47,"at":"خذوه فاعتلوه الى سواء الجحيم","dt":"[47] خذوا هذا الاثيم الفاجر فادفعوه، وسوقوه بعنف الى وسط الجحيم يوم القيامه."},{"id":"4462","s":44,"a":48,"at":"ثم صبوا فوق راسه من عذاب الحميم","dt":"[48] ثم صبوا فوق راس هذا الاثيم الماء الذي تناهت شده حرارته، فلا يفارقه العذاب."},{"id":"4463","s":44,"a":49,"at":"ذق انك انت العزيز الكريم","dt":"[49] يقال لهذا الاثيم الشقي -على وجه التهكم والتوبيخ-: ذق هذا العذاب الذي تعذب به اليوم، انك انت العزيز في قومك، الكريم عليهم."},{"id":"4464","s":44,"a":50,"at":"ان هذا ما كنتم به تمترون","dt":"[50] ان هذا العذاب الذي تعذبون به اليوم هو العذاب الذي كنتم تشكون فيه في الدنيا، ولا توقنون به."},{"id":"4465","s":44,"a":51,"at":"ان المتقين في مقام امين","dt":"[51] ان الذين اتقوا الله بامتثال اوامره واجتناب نواهيه في الدنيا، في موضع اقامه في الاخره امنين من الافات والاحزان وغير ذلك."},{"id":"4466","s":44,"a":52,"at":"في جنات وعيون","dt":"[52] في جنات وعيون جاريه."},{"id":"4467","s":44,"a":53,"at":"يلبسون من سندس واستبرق متقابلين","dt":"[53] يلبسون ما رق من الديباج وما غلظ منه، يقابل بعضهم بعضا بالوجوه، ولا ينظر بعضهم في قفا بعض، يدور بهم مجلسهم حيث داروا."},{"id":"4468","s":44,"a":54,"at":"كذلك وزوجناهم بحور عين","dt":"[54] كما اعطينا هؤلاء المتقين في الاخره من الكرامه بادخالهم الجنات والباسهم فيها السندس والاستبرق، كذلك اكرمناهم بان زوجناهم بالحسان من النساء واسعات الاعين الجميلاتها."},{"id":"4469","s":44,"a":55,"at":"يدعون فيها بكل فاكهه امنين","dt":"[55] يطلب هؤلاء المتقون في الجنه كل نوع من فواكه الجنه اشتهوه، امنين من انقطاع ذلك عنهم وفنائه."},{"id":"4470","s":44,"a":56,"at":"لا يذوقون فيها الموت الا الموته الاولى ووقاهم عذاب الجحيم","dt":"[56] لا يذوق هؤلاء المتقون في الجنه الموت بعد الموته الاولى التي ذاقوها في الدنيا، ووقى الله هؤلاء المتقين عذاب الجحيم؛"},{"id":"4471","s":44,"a":57,"at":"فضلا من ربك ذلك هو الفوز العظيم","dt":"[57] تفضلا واحسانا منه سبحانه وتعالى، هذا الذي اعطيناه المتقين في الاخره من الكرامات هو الفوز العظيم الذي لا فوز بعده."},{"id":"4472","s":44,"a":58,"at":"فانما يسرناه بلسانك لعلهم يتذكرون","dt":"[58] فانما سهلنا لفظ القران ومعناه بلغتك ايها الرسول؛ لعلهم يتعظون وينزجرون."},{"id":"4473","s":44,"a":59,"at":"فارتقب انهم مرتقبون","dt":"[59] فانتظر -ايها الرسول- ما وعدتك من النصر على هؤلاء المشركين بالله، وما يحل بهم من العقاب، انهم منتظرون موتك وقهرك، وسيعلمون لمن تكون النصره والظفر وعلو الكلمه في الدنيا والاخره، انها لك -ايها الرسول- ولمن اتبعك من المؤمنين."},{"id":"4474","s":45,"a":1,"at":"حم","dt":"[1] حم سبق الكلام على الحروف المقطعه في اول سوره البقره."},{"id":"4475","s":45,"a":2,"at":"تنزيل الكتاب من الله العزيز الحكيم","dt":"[2] هذا القران منزل من الله العزيز في انتقامه من اعدائه، الحكيم في تدبير امور خلقه."},{"id":"4476","s":45,"a":3,"at":"ان في السموات والارض لايات للمؤمنين","dt":"[3] ان في السموات السبع، والارض التي منها خروج الخلق، وما فيها من المخلوقات المختلفه الاجناس والانواع، لادله وحججا للمؤمنين بها."},{"id":"4477","s":45,"a":4,"at":"وفي خلقكم وما يبث من دابه ايات لقوم يوقنون","dt":"[4] وفي خلقكم-ايها الناس- وخلق ما تفرق في الارض من دابه تدب عليها، حجج وادله لقوم يوقنون بالله وشرعه."},{"id":"4478","s":45,"a":5,"at":"واختلاف الليل والنهار وما انزل الله من السماء من رزق فاحيا به الارض بعد موتها وتصريف الرياح ايات لقوم يعقلون","dt":"[5] وفي اختلاف الليل والنهار وتعاقبهما عليكم، وما انزل الله من السماء من مطر فاحيا به الارض بعد يبسها، فاهتزت بالنبات والزرع، وفي تصريف الرياح لكم من جميع الجهات وتصريفها لمنافعكم، ادله وحجج لقوم يعقلون عن الله حججه وادلته."},{"id":"4479","s":45,"a":6,"at":"تلك ايات الله نتلوها عليك بالحق فباي حديث بعد الله واياته يؤمنون","dt":"[6] هذه الايات والحجج نتلوها عليك -ايها الرسول- بالحق، فباي حديث بعد الله واياته وادلته على انه الاله الحق وحده لا شريك له يؤمنون ويصدقون ويعملون؟"},{"id":"4480","s":45,"a":7,"at":"ويل لكل افاك اثيم","dt":"[7] هلاك شديد لكل كذاب كثير الاثام."},{"id":"4481","s":45,"a":8,"at":"يسمع ايات الله تتلى عليه ثم يصر مستكبرا كان لم يسمعها فبشره بعذاب اليم","dt":"[8] يسمع ايات كتاب الله تقرا عليه، ثم يتمادى في كفره متعاليا في نفسه عن الانقياد لله ورسوله، كانه لم يسمع ما تلي عليه من ايات الله، فبشر -ايها الرسول- هذا الافاك الاثيم بعذاب مؤلم موجع في نار جهنم يوم القيامه."},{"id":"4482","s":45,"a":9,"at":"واذا علم من اياتنا شيئا اتخذها هزوا اولئك لهم عذاب مهين","dt":"[9] واذا علم هذا الافاك الاثيم من اياتنا شيئا اتخذها هزوا وسخريه، اولئك لهم عذاب يهينهم ويخزيهم يوم القيامه؛ جزاء استهزائهم بالقران."},{"id":"4483","s":45,"a":10,"at":"من ورائهم جهنم ولا يغني عنهم ما كسبوا شيئا ولا ما اتخذوا من دون الله اولياء ولهم عذاب عظيم","dt":"[10] من امام هؤلاء المستهزئين بايات الله جهنم، ولا يغني عنهم ما كسبوا شيئا من المال والولد، ولا الهتهم التي عبدوها من دون الله، ولهم عذاب عظيم مؤلم."},{"id":"4484","s":45,"a":11,"at":"هذا هدى والذين كفروا بايات ربهم لهم عذاب من رجز اليم","dt":"[11] هذا القران الذي انزلناه عليك -ايها الرسول- هدى من الضلاله، ودليل على الحق، يهدي من اتبعه وعمل به الى طريق مستقيم، والذين جحدوا بما في القران من الايات الداله على الحق ولم يصدقوا بها، لهم عذاب مؤلم موجع من اسوا انواع العذاب يوم القيامه."},{"id":"4485","s":45,"a":12,"at":"الله الذي سخر لكم البحر لتجري الفلك فيه بامره ولتبتغوا من فضله ولعلكم تشكرون","dt":"[12] الله سبحانه وتعالى هو الذي سخر لكم البحر؛ لتجري السفن فيه بامره، ولتبتغوا من فضله بانواع التجارات والمكاسب، ولعلكم تشكرون ربكم على تسخيره ذلك لكم، فتعبدوه وحده، وتطيعوه فيما يامركم به وينهاكم عنه."},{"id":"4486","s":45,"a":13,"at":"وسخر لكم ما في السموات وما في الارض جميعا منه ان في ذلك لايات لقوم يتفكرون","dt":"[13] وسخر لكم كل ما في السموات من شمس وقمر ونجوم، وكل ما في الارض من دابه وشجر وسفن وغير ذلك لمنافعكم، جميع هذه النعم منه من الله وحده انعم بها عليكم، وفضل منه تفضل به، فاياه فاعبدوا، ولا تجعلوا له شريكا. ان فيما سخره الله لكم لعلامات ودلالات على وحدانيه الله لقوم يتفكرون في ايات الله وحججه وادلته، فيعتبرون بها."},{"id":"4487","s":45,"a":14,"at":"قل للذين امنوا يغفروا للذين لا يرجون ايام الله ليجزي قوما بما كانوا يكسبون","dt":"[14] قل -ايها الرسول- للذين صدقوا بالله واتبعوا رسوله يعفوا، ويتجاوزوا عن الذين لا يرجون ثواب الله، ولا يخافون باسه اذا هم نالوا الذين امنوا بالاذى والمكروه؛ ليجزي الله هؤلاء المشركين بما كانوا يكسبون في الدنيا من الاثام وايذاء المؤمنين."},{"id":"4488","s":45,"a":15,"at":"من عمل صالحا فلنفسه ومن اساء فعليها ثم الى ربكم ترجعون","dt":"[15] من عمل من عباد الله بطاعته فلنفسه عمل، ومن اساء عمله في الدنيا بمعصيه الله فعلى نفسه جنى، ثم انكم -ايها الناس- الى ربكم تصيرون بعد موتكم، فيجازي المحسن باحسانه، والمسيء باساءته."},{"id":"4489","s":45,"a":16,"at":"ولقد اتينا بني اسرائيل الكتاب والحكم والنبوه ورزقناهم من الطيبات وفضلناهم على العالمين","dt":"[16] ولقد اتينا بني اسرائيل التوراه والانجيل والحكم بما فيهما، وجعلنا اكثر الانبياء من ذريه ابراهيم عليه السلام فيهم، ورزقناهم من الطيبات من الاقوات والثمار والاطعمه، وفضلناهم على عالمي زمانهم."},{"id":"4490","s":45,"a":17,"at":"واتيناهم بينات من الامر فما اختلفوا الا من بعد ما جاءهم العلم بغيا بينهم ان ربك يقضي بينهم يوم القيامه فيما كانوا فيه يختلفون","dt":"[17] واتينا بني اسرائيل شرائع واضحات في الحلال والحرام، ودلالات تبين الحق من الباطل، فما اختلفوا الا من بعد ما جاءهم العلم، وقامت الحجه عليهم، وانما حملهم على ذلك بغي بعضهم على بعض؛ طلبا للرفعه والرئاسه، ان ربك -ايها الرسول- يحكم بين المختلفين من بني اسرائيل يوم القيامه فيما كانوا فيه يختلفون في الدنيا. وفي هذا تحذير لهذه الامه ان تسلك مسلكهم."},{"id":"4491","s":45,"a":18,"at":"ثم جعلناك على شريعه من الامر فاتبعها ولا تتبع اهواء الذين لا يعلمون","dt":"[18] ثم جعلناك -ايها الرسول- على منهاج واضح من امر الدين، فاتبع الشريعه التي جعلناك عليها، ولا تتبع اهواء الجاهلين بشرع الله الذين لا يعلمون الحق. وفي الايه دلاله عظيمه على كمال هذا الدين وشرفه، ووجوب الانقياد لحكمه، وعدم الميل الى اهواء الكفره والملحدين."},{"id":"4492","s":45,"a":19,"at":"انهم لن يغنوا عنك من الله شيئا وان الظالمين بعضهم اولياء بعض والله ولي المتقين","dt":"[19] ان هؤلاء المشركين بربهم الذين يدعونك الى اتباع اهوائهم لن يغنوا عنك -ايها الرسول- من عقاب الله شيئا ان اتبعت اهواءهم، وان الظالمين المتجاوزين حدود الله من المنافقين واليهود وغيرهم بعضهم انصار بعض على المؤمنين بالله واهل طاعته، والله ناصر المتقين ربهم باداء فرائضه واجتناب نواهيه."},{"id":"4493","s":45,"a":20,"at":"هذا بصائر للناس وهدى ورحمه لقوم يوقنون","dt":"[20] هذا القران الذي انزلناه اليك -ايها الرسول- بصائر يبصر به الناس الحق من الباطل، ويعرفون به سبيل الرشاد، وهدى ورحمه لقوم يوقنون بحقيقه صحته، وانه تنزيل من الله العزيز الحكيم."},{"id":"4494","s":45,"a":21,"at":"ام حسب الذين اجترحوا السيئات ان نجعلهم كالذين امنوا وعملوا الصالحات سواء محياهم ومماتهم ساء ما يحكمون","dt":"[21] بل اظن الذين اكتسبوا السيئات، وكذبوا رسل الله، وخالفوا امر ربهم، وعبدوا غيره، ان نجعلهم كالذين امنوا بالله، وصدقوا رسله وعملوا الصالحات، واخلصوا له العباده دون سواه، ونساويهم بهم في الدنيا والاخره؟ ساء حكمهم بالمساواه بين الفجار والابرار."},{"id":"4495","s":45,"a":22,"at":"وخلق الله السموات والارض بالحق ولتجزى كل نفس بما كسبت وهم لا يظلمون","dt":"[22] وخلق الله السموات والارض بالحق والعدل والحكمه؛ ولكي تجزى كل نفس في الاخره بما كسبت من خير او شر، وهم لا يظلمون جزاء اعمالهم."},{"id":"4496","s":45,"a":23,"at":"افرايت من اتخذ الهه هواه واضله الله على علم وختم على سمعه وقلبه وجعل على بصره غشاوه فمن يهديه من بعد الله افلا تذكرون","dt":"[23] افرايت -ايها الرسول- من اتخذ هواه الها له، فلا يهوى شيئا الا فعله، واضله الله بعد بلوغ العلم اليه وقيام الحجه عليه، فلا يسمع مواعظ الله، ولا يعتبر بها، وطبع على قلبه، فلا يعقل به شيئا، وجعل على بصره غطاء، فلا يبصر به حجج الله؟ فمن يوفقه لاصابه الحق والرشد بعد اضلال الله اياه؟ افلا تذكرون -ايها الناس- فتعلموا ان من فعل الله به ذلك فلن يهتدي ابدا، ولن يجد لنفسه وليا مرشدا؟والايه اصل في التحذير من ان يكون الهوى هو الباعث للمؤمنين على اعمالهم."},{"id":"4497","s":45,"a":24,"at":"وقالوا ما هي الا حياتنا الدنيا نموت ونحيا وما يهلكنا الا الدهر وما لهم بذلك من علم ان هم الا يظنون","dt":"[24] وقال هؤلاء المشركون: ما الحياه الا حياتنا الدنيا التي نحن فيها، لا حياه سواها؛ تكذيبا منهم بالبعث بعد الممات، وما يهلكنا الا مر الليالي والايام وطول العمر؛ انكارا منهم ان يكون لهم رب يفنيهم ويهلكهم، وما لهؤلاء المشركين من علم بذلك، ما هم الا يتكلمون بالظن والوهم والخيال."},{"id":"4498","s":45,"a":25,"at":"واذا تتلى عليهم اياتنا بينات ما كان حجتهم الا ان قالوا ائتوا بابائنا ان كنتم صادقين","dt":"[25] واذا تتلى على هؤلاء المشركين المكذبين بالبعث اياتنا واضحات، لم يكن لهم حجه الا قولهم للرسول -صلى الله عليه وسلم-: احي انت والمؤمنون معك اباءنا الذين قد هلكوا، ان كنتم صادقين فيما تقولون."},{"id":"4499","s":45,"a":26,"at":"قل الله يحييكم ثم يميتكم ثم يجمعكم الى يوم القيامه لا ريب فيه ولكن اكثر الناس لا يعلمون","dt":"[26] قل -ايها الرسول- لهؤلاء المشركين المكذبين بالبعث: الله سبحانه وتعالى يحييكم في الدنيا ما شاء لكم الحياه، ثم يميتكم فيها، ثم يجمعكم جميعا احياء الى يوم القيامه لا شك فيه، ولكن اكثر الناس لا يعلمون قدره الله على اماتتهم، ثم بعثهم يوم القيامه."},{"id":"4500","s":45,"a":27,"at":"ولله ملك السموات والارض ويوم تقوم الساعه يومئذ يخسر المبطلون","dt":"[27] ولله سبحانه سلطان السموات السبع والارض خلقا وملكا وعبوديه. ويوم تجيء الساعه التي يبعث فيها الموتى من قبورهم ويحاسبون، يخسر الكافرون بالله الجاحدون بما انزله على رسوله من الايات البينات والدلائل الواضحات."},{"id":"4501","s":45,"a":28,"at":"وترى كل امه جاثيه كل امه تدعى الى كتابها اليوم تجزون ما كنتم تعملون","dt":"[28] وترى -ايها الرسول- يوم تقوم الساعه اهل كل مله ودين جاثمين على ركبهم، كل امه تدعى الى كتاب اعمالها، ويقال لهم: اليوم تجزون ما كنتم تعملون من خير او شر."},{"id":"4502","s":45,"a":29,"at":"هذا كتابنا ينطق عليكم بالحق انا كنا نستنسخ ما كنتم تعملون","dt":"[29] هذا كتابنا ينطق عليكم بجميع اعمالكم من غير زياده ولا نقص، انا كنا نامر الحفظه ان تكتب اعمالكم عليكم."},{"id":"4503","s":45,"a":30,"at":"فاما الذين امنوا وعملوا الصالحات فيدخلهم ربهم في رحمته ذلك هو الفوز المبين","dt":"[30] فاما الذين امنوا بالله ورسوله في الدنيا، وامتثلوا اوامره واجتنبوا نواهيه، فيدخلهم ربهم في جنته برحمته، ذلك الدخول هو الفوز المبين الذي لا فوز بعده."},{"id":"4504","s":45,"a":31,"at":"واما الذين كفروا افلم تكن اياتي تتلى عليكم فاستكبرتم وكنتم قوما مجرمين","dt":"[31] واما الذين جحدوا ان الله هو الاله الحق وكذبوا رسله ولم يعملوا بشرعه، فيقال لهم -تقريعا وتوبيخا-: افلم تكن اياتي في الدنيا تتلى عليكم، فاستكبرتم عن استماعها والايمان بها، وكنتم قوما مشركين تكسبون المعاصي ولا تؤمنون بثواب ولا عقاب؟"},{"id":"4505","s":45,"a":32,"at":"واذا قيل ان وعد الله حق والساعه لا ريب فيها قلتم ما ندري ما الساعه ان نظن الا ظنا وما نحن بمستيقنين","dt":"[32] واذا قيل لكم: ان وعد الله ببعث الناس من قبورهم حق، والساعه لا شك فيها، قلتم: ما ندري ما الساعه؟ وما نتوقع وقوعها الا توهما، وما نحن بمتحققين ان الساعه اتيه."},{"id":"4506","s":45,"a":33,"at":"وبدا لهم سيئات ما عملوا وحاق بهم ما كانوا به يستهزئون","dt":"[33] وظهر لهؤلاء الذين كانوا يكذبون بايات الله ما عملوا في الدنيا من الاعمال القبيحه، ونزل بهم من عذاب الله جزاء ما كانوا به يستهزئون."},{"id":"4507","s":45,"a":34,"at":"وقيل اليوم ننساكم كما نسيتم لقاء يومكم هذا وماواكم النار وما لكم من ناصرين","dt":"[34] وقيل لهؤلاء الكفره: اليوم نترككم في عذاب جهنم، كما تركتم الايمان بربكم والعمل للقاء يومكم هذا، ومسكنكم نار جهنم، وما لكم من ناصرين ينصرونكم من عذاب الله."},{"id":"4508","s":45,"a":35,"at":"ذلكم بانكم اتخذتم ايات الله هزوا وغرتكم الحياه الدنيا فاليوم لا يخرجون منها ولا هم يستعتبون","dt":"[35] هذا الذي حل بكم من عذاب الله؛ بسبب انكم اتخذتم ايات الله وحججه هزوا ولعبا، وخدعتكم زينه الحياه الدنيا، فاليوم لا يخرجون من النار، ولا هم يردون الى الدنيا؛ ليتوبوا ويعملوا صالحا."},{"id":"4509","s":45,"a":36,"at":"فلله الحمد رب السموات ورب الارض رب العالمين","dt":"[36] فلله سبحانه وتعالى وحده الحمد على نعمه التي لا تحصى على خلقه، رب السموات والارض وخالقهما ومدبرهما، رب الخلائق اجمعين."},{"id":"4510","s":45,"a":37,"at":"وله الكبرياء في السموات والارض وهو العزيز الحكيم","dt":"[37] وله وحده سبحانه العظمه والجلال والكبرياء والسلطان والقدره والكمال في السموات والارض، وهو العزيز الذي لا يغالب، الحكيم في اقواله وافعاله وقدره وشرعه، تعالى وتقدس، لا اله الا هو."},{"id":"4511","s":46,"a":1,"at":"حم","dt":"[1] حم سبق الكلام على الحروف المقطعه في اول سوره البقره."},{"id":"4512","s":46,"a":2,"at":"تنزيل الكتاب من الله العزيز الحكيم","dt":"[2] هذا القران تنزيل من الله العزيز الذي لا يغالب، الحكيم في تدبيره وصنعه."},{"id":"4513","s":46,"a":3,"at":"ما خلقنا السموات والارض وما بينهما الا بالحق واجل مسمى والذين كفروا عما انذروا معرضون","dt":"[3] ما خلقنا السموات والارض وما بينهما الا بالحق، لا عبثا ولا سدى؛ بل ليعرف العباد عظمه خالقهما فيعبدوه وحده، ويعلموا انه قادر على ان يعيد العباد بعد موتهم، وليقيموا الحق والعدل فيما بينهم والى اجل معلوم عنده. والذين جحدوا ان الله هو الاله الحق، عما انذرهم به القران معرضون، لا يتعظون ولا يتفكرون."},{"id":"4514","s":46,"a":4,"at":"قل ارايتم ما تدعون من دون الله اروني ماذا خلقوا من الارض ام لهم شرك في السموات ائتوني بكتاب من قبل هذا او اثاره من علم ان كنتم صادقين","dt":"[4] قل -ايها الرسول- لهؤلاء الكفار: ارايتم الالهه، والاوثان التي تعبدونها من دون الله، اروني اي شيء خلقوا من الارض، ام لهم مع الله نصيب من خلق السموات؟ ائتوني بكتاب من عند الله من قبل هذا القران او ببقيه من علم، ان كنتم صادقين فيما تزعمون."},{"id":"4515","s":46,"a":5,"at":"ومن اضل ممن يدعو من دون الله من لا يستجيب له الى يوم القيامه وهم عن دعائهم غافلون","dt":"[5] لا احد اضل واجهل ممن يدعو من دون الله الهه لا تستجيب دعاءه ابدا؛ لانها من الاموات او الاحجار والاشجار ونحوها، وهي غافله عن دعاء من يعبدها، عاجزه عن نفعه او ضره."},{"id":"4516","s":46,"a":6,"at":"واذا حشر الناس كانوا لهم اعداء وكانوا بعبادتهم كافرين","dt":"[6] واذا حشر الناس يوم القيامه للحساب والجزاء كانت الالهه التي يدعونها في الدنيا لهم اعداء، تلعنهم وتتبرا منهم، وتنكر علمها بعبادتهم اياها."},{"id":"4517","s":46,"a":7,"at":"واذا تتلى عليهم اياتنا بينات قال الذين كفروا للحق لما جاءهم هذا سحر مبين","dt":"[7] واذا تتلى على هؤلاء المشركين اياتنا واضحات، قال الذين كفروا حين جاءهم القران: هذا سحر ظاهر."},{"id":"4518","s":46,"a":8,"at":"ام يقولون افتراه قل ان افتريته فلا تملكون لي من الله شيئا هو اعلم بما تفيضون فيه كفى به شهيدا بيني وبينكم وهو الغفور الرحيم","dt":"[8] بل ايقول هؤلاء المشركون: ان محمدا اختلق هذا القران؟ قل لهم -ايها الرسول-: ان اختلقته على الله فانكم لا تقدرون ان تدفعوا عني من عقاب الله شيئا، ان عاقبني على ذلك. هو سبحانه اعلم من كل شيء سواه بما تقولون في هذا القران، كفى بالله شاهدا علي وعليكم، وهو الغفور لمن تاب اليه، الرحيم بعباده المؤمنين."},{"id":"4519","s":46,"a":9,"at":"قل ما كنت بدعا من الرسل وما ادري ما يفعل بي ولا بكم ان اتبع الا ما يوحى الي وما انا الا نذير مبين","dt":"[9] قل -ايها الرسول- لمشركي قومك: ما كنت اول رسل الله الى خلقه، وما ادري ما يفعل الله بي ولا بكم في الدنيا، ما اتبع فيما امركم به وفيما افعله الا وحي الله الذي يوحيه الي، وما انا الا نذير بين الانذار."},{"id":"4520","s":46,"a":10,"at":"قل ارايتم ان كان من عند الله وكفرتم به وشهد شاهد من بني اسرائيل على مثله فامن واستكبرتم ان الله لا يهدي القوم الظالمين","dt":"[10] قل -ايها الرسول- لمشركي قومك: اخبروني ان كان هذا القران من عند الله وكفرتم به، وشهد شاهد من بني اسرائيل كعبدالله بن سلام على مثل هذا القران، وهو ما في التوراه من التصديق بنبوه محمد -صلى الله عليه وسلم-، فصدق وعمل بما جاء في القران، وجحدتم ذلك استكبارا، فهل هذا الا اعظم الظلم واشد الكفر؟ ان الله لا يوفق الى الاسلام واصابه الحق القوم الذين ظلموا انفسهم بكفرهم بالله."},{"id":"4521","s":46,"a":11,"at":"وقال الذين كفروا للذين امنوا لو كان خيرا ما سبقونا اليه واذ لم يهتدوا به فسيقولون هذا افك قديم","dt":"[11] وقال الذين جحدوا نبوه محمد -صلى الله عليه وسلم- للذين امنوا به: لو كان تصديقكم محمدا على ما جاء به خيرا ما سبقتمونا الى التصديق به، واذ لم يهتدوا بالقران ولم ينتفعوا بما فيه من الحق فسيقولون: هذا كذب، ماثور عن الناس الاقدمين."},{"id":"4522","s":46,"a":12,"at":"ومن قبله كتاب موسى اماما ورحمه وهذا كتاب مصدق لسانا عربيا لينذر الذين ظلموا وبشرى للمحسنين","dt":"[12] ومن قبل هذا القران انزلنا التوراه اماما لبني اسرائيل يقتدون بها، ورحمه لمن امن بها وعمل بما فيها، وهذا القران مصدق لما قبله من الكتب، انزلناه بلسان عربي؛ لينذر الذين ظلموا انفسهم بالكفر والمعصيه، وبشرى للذين اطاعوا الله، فاحسنوا في ايمانهم وطاعتهم في الدنيا."},{"id":"4523","s":46,"a":13,"at":"ان الذين قالوا ربنا الله ثم استقاموا فلا خوف عليهم ولا هم يحزنون","dt":"[13] ان الذين قالوا: ربنا الله، ثم استقاموا على الايمان به، فلا خوف عليهم من فزع يوم القيامه واهواله، ولا هم يحزنون على ما خلفوا وراءهم بعد مماتهم من حظوظ الدنيا."},{"id":"4524","s":46,"a":14,"at":"اولئك اصحاب الجنه خالدين فيها جزاء بما كانوا يعملون","dt":"[14] اولئك اهل الجنه ماكثين فيها ابدا برحمه الله تعالى لهم، وبما قدموا من عمل صالح في دنياهم."},{"id":"4525","s":46,"a":15,"at":"ووصينا الانسان بوالديه احسانا حملته امه كرها ووضعته كرها وحمله وفصاله ثلاثون شهرا حتى اذا بلغ اشده وبلغ اربعين سنه قال رب اوزعني ان اشكر نعمتك التي انعمت علي وعلى والدي وان اعمل صالحا ترضاه واصلح لي في ذريتي اني تبت اليك واني من المسلمين","dt":"[15] ووصينا الانسان ان يحسن في صحبته لوالديه برا بهما في حياتهما وبعد مماتهما، فقد حملته امه جنينا في بطنها على مشقه وتعب، وولدته على مشقه وتعب ايضا، ومده حمله وفطامه ثلاثون شهرا. وفي ذكر هذه المشاق التي تتحملها الام دون الاب، دليل على ان حقها على ولدها اعظم من حق الاب. حتى اذا بلغ هذا الانسان كمال قوته البدنيه والعقليه، وبلغ اربعين سنه دعا ربه قائلا: ربي الهمني ان اشكر نعمتك التي انعمتها علي وعلى والدي، واجعلني اعمل صالحا ترضاه، واصلح لي في ذريتي، اني تبت اليك من ذنوبي، واني من الخاضعين لك بالطاعه والمستسلمين لامرك ونهيك، المنقادين لحكمك."},{"id":"4526","s":46,"a":16,"at":"اولئك الذين نتقبل عنهم احسن ما عملوا ونتجاوز عن سيئاتهم في اصحاب الجنه وعد الصدق الذي كانوا يوعدون","dt":"[16] اولئك الذين نتقبل منهم احسن ما عملوا من صالحات الاعمال، ونصفح عن سيئاتهم في جمله اصحاب الجنه، هذا الوعد الذي وعدناهم به هو وعد الصدق الحق الذي لا شك فيه."},{"id":"4527","s":46,"a":17,"at":"والذي قال لوالديه اف لكما اتعدانني ان اخرج وقد خلت القرون من قبلي وهما يستغيثان الله ويلك امن ان وعد الله حق فيقول ما هذا الا اساطير الاولين","dt":"[17] والذي قال لوالديه اذ دعواه الى الايمان بالله والاقرار بالبعث: قبحا لكما اتعدانني ان اخرج من قبري حيا، وقد مضت القرون من الامم من قبلي، فهلكوا فلم يبعث منهم احد؟ ووالداه يسالان الله هدايته قائلين له: ويلك، امن وصدق واعمل صالحا، ان وعد الله بالبعث حق لا شك فيه، فيقول لهما: ما هذا الذي تقولانه الا ما سطره الاولون من الاباطيل، منقول من كتبهم."},{"id":"4528","s":46,"a":18,"at":"اولئك الذين حق عليهم القول في امم قد خلت من قبلهم من الجن والانس انهم كانوا خاسرين","dt":"[18] اولئك الذين هذه صفتهم وجب عليهم عذاب الله، وحلت بهم عقوبته وسخطه في جمله امم مضت من قبلهم من الجن والانس على الكفر والتكذيب، انهم كانوا خاسرين ببيعهم الهدى بالضلال، والنعيم بالعذاب."},{"id":"4529","s":46,"a":19,"at":"ولكل درجات مما عملوا وليوفيهم اعمالهم وهم لا يظلمون","dt":"[19] ولكل فريق من اهل الخير واهل الشر منازل عند الله يوم القيامه؛ باعمالهم التي عملوها في الدنيا، كل على وفق مرتبته؛ وليوفيهم الله جزاء اعمالهم، وهم لا يظلمون بزياده في سيئاتهم، ولا بنقص من حسناتهم."},{"id":"4530","s":46,"a":20,"at":"ويوم يعرض الذين كفروا على النار اذهبتم طيباتكم في حياتكم الدنيا واستمتعتم بها فاليوم تجزون عذاب الهون بما كنتم تستكبرون في الارض بغير الحق وبما كنتم تفسقون","dt":"[20] ويوم يعرض الذين كفروا على النار للعذاب، فيقال لهم توبيخا: لقد اذهبتم طيباتكم في حياتكم الدنيا واستمتعتم بها، فاليوم -ايها الكفار- تجزون عذاب الخزي والهوان في النار؛ بما كنتم تتكبرون في الارض بغير الحق، وبما كنتم تخرجون عن طاعه الله."},{"id":"4531","s":46,"a":21,"at":"واذكر اخا عاد اذ انذر قومه بالاحقاف وقد خلت النذر من بين يديه ومن خلفه الا تعبدوا الا الله اني اخاف عليكم عذاب يوم عظيم","dt":"[21] واذكر -ايها الرسول- نبي الله هودا اخا عاد في النسب لا في الدين، حين انذر قومه ان يحل بهم عقاب الله، وهم في منازلهم المعروفه ب«الاحقاف» -وهي الرمال الكثيره جنوب الجزيره العربيه- وقد مضت الرسل بانذار قومها قبل هود وبعده: بان لا تشركوا مع الله شيئا في عبادتكم له، اني اخاف عليكم عذاب الله في يوم يعظم هوله، وهو يوم القيامه."},{"id":"4532","s":46,"a":22,"at":"قالوا اجئتنا لتافكنا عن الهتنا فاتنا بما تعدنا ان كنت من الصادقين","dt":"[22] قالوا: اجئتنا بدعوتك؛ لتصرفنا عن عباده الهتنا؟ فاتنا بما تعدنا به من العذاب، ان كنت من اهل الصدق في قولك ووعدك."},{"id":"4533","s":46,"a":23,"at":"قال انما العلم عند الله وابلغكم ما ارسلت به ولكني اراكم قوما تجهلون","dt":"[23] قال هود عليه السلام: انما العلم بوقت مجيء ما وعدتم به من العذاب عند الله، وانما انا رسول الله اليكم، ابلغكم عنه ما ارسلني به، ولكني اراكم قوما تجهلون في استعجالكم العذاب، وجراتكم على الله."},{"id":"4534","s":46,"a":24,"at":"فلما راوه عارضا مستقبل اوديتهم قالوا هذا عارض ممطرنا بل هو ما استعجلتم به ريح فيها عذاب اليم","dt":"[24] فلما راوا العذاب الذي استعجلوه عارضا في السماء متجها الى اوديتهم قالوا: هذا سحاب ممطر لنا، فقال لهم هود عليه السلام: ليس هو بعارض غيث ورحمه كما ظننتم، بل هو عارض العذاب الذي استعجلتموه، فهو ريح فيها عذاب مؤلم موجع."},{"id":"4535","s":46,"a":25,"at":"تدمر كل شيء بامر ربها فاصبحوا لا يرى الا مساكنهم كذلك نجزي القوم المجرمين","dt":"[25] تدمر كل شيء تمر به مما ارسلت بهلاكه بامر ربها ومشيئته، فاصبحوا لا يرى في بلادهم شيء الا مساكنهم التي كانوا يسكنونها. مثل هذا الجزاء نجزي القوم المجرمين؛ بسبب جرمهم وطغيانهم."},{"id":"4536","s":46,"a":26,"at":"ولقد مكناهم فيما ان مكناكم فيه وجعلنا لهم سمعا وابصارا وافئده فما اغنى عنهم سمعهم ولا ابصارهم ولا افئدتهم من شيء اذ كانوا يجحدون بايات الله وحاق بهم ما كانوا به يستهزئون","dt":"[26] ولقد يسرنا لعاد اسباب التمكين في الدنيا على نحو لم نمكنكم فيه معشر كفار قريش، وجعلنا لهم سمعا يسمعون به، وابصارا يبصرون بها، وافئده يعقلون بها، فاستعملوها فيما يسخط الله عليهم، فلم تغن عنهم شيئا اذ كانوا يكذبون بحجج الله، ونزل بهم من العذاب ما سخروا به واستعجلوه. وهذا وعيد من الله جل شانه، وتحذير للكافرين."},{"id":"4537","s":46,"a":27,"at":"ولقد اهلكنا ما حولكم من القرى وصرفنا الايات لعلهم يرجعون","dt":"[27] ولقد اهلكنا ما حولكم يا اهل «مكه» من القرى كعاد وثمود، فجعلناها خاويه على عروشها، وبينا لهم انواع الحجج والدلالات؛ لعلهم يرجعون عما كانوا عليه من الكفر بالله واياته."},{"id":"4538","s":46,"a":28,"at":"فلولا نصرهم الذين اتخذوا من دون الله قربانا الهه بل ضلوا عنهم وذلك افكهم وما كانوا يفترون","dt":"[28] فهلا نصر هؤلاء الذين اهلكناهم من الامم الخاليه الهتهم التي اتخذوا عبادتها قربانا يتقربون بها الى ربهم؛ لتشفع لهم عنده، بل ضلت عنهم الهتهم، فلم يجيبوهم، ولا دافعوا عنهم، وذلك كذبهم وما كانوا يفترون في اتخاذهم اياهم الهه."},{"id":"4539","s":46,"a":29,"at":"واذ صرفنا اليك نفرا من الجن يستمعون القران فلما حضروه قالوا انصتوا فلما قضي ولوا الى قومهم منذرين","dt":"[29] واذكر -ايها الرسول- حين بعثنا اليك، طائفه من الجن يستمعون منك القران، فلما حضروا ورسول الله -صلى الله عليه وسلم- يقرا، قال بعضهم لبعض: انصتوا؛ لنستمع القران، فلما فرغ الرسول من تلاوه القران، وقد وعوه واثر فيهم، رجعوا الى قومهم منذرين ومحذرين لهم باس الله، ان لم يؤمنوا به."},{"id":"4540","s":46,"a":30,"at":"قالوا ياقومنا انا سمعنا كتابا انزل من بعد موسى مصدقا لما بين يديه يهدي الى الحق والى طريق مستقيم","dt":"[30] قالوا: يا قومنا انا سمعنا كتابا انزل من بعد موسى، مصدقا لما قبله من كتب الله التي انزلها على رسله، يهدي الى الحق والصواب، والى طريق صحيح مستقيم."},{"id":"4541","s":46,"a":31,"at":"ياقومنا اجيبوا داعي الله وامنوا به يغفر لكم من ذنوبكم ويجركم من عذاب اليم","dt":"[31] يا قومنا اجيبوا رسول الله محمدا الى ما يدعوكم اليه، وصدقوه واعملوا بما جاءكم به، يغفر الله لكم من ذنوبكم، و ينقذكم من عذاب مؤلم موجع."},{"id":"4542","s":46,"a":32,"at":"ومن لا يجب داعي الله فليس بمعجز في الارض وليس له من دونه اولياء اولئك في ضلال مبين","dt":"[32] ومن لا يجب رسول الله الى ما دعا اليه فليس بمعجز الله في الارض اذا اراد عقوبته، وليس له من دون الله انصار يمنعونه من عذابه، اولئك في ذهاب واضح عن الحق."},{"id":"4543","s":46,"a":33,"at":"او لم يروا ان الله الذي خلق السموات والارض ولم يعي بخلقهن بقادر على ان يحيي الموتى بلى انه على كل شيء قدير","dt":"[33] اغفلوا ولم يعلموا ان الله الذي خلق السموات والارض على غير مثال سبق، ولم يعجز عن خلقهن، قادر على احياء الموتى الذين خلقهم اولا؟ بلى، ذلك امر يسير على الله تعالى الذي لا يعجزه شيء، انه على كل شيء قدير."},{"id":"4544","s":46,"a":34,"at":"ويوم يعرض الذين كفروا على النار اليس هذا بالحق قالوا بلى وربنا قال فذوقوا العذاب بما كنتم تكفرون","dt":"[34] ويوم القيامه يعرض الذين كفروا على نار جهنم للعذاب فيقال لهم: اليس هذا العذاب بالحق؟ فيجيبون قائلين: بلى وربنا هو الحق، فيقال لهم: فذوقوا العذاب بما كنتم تجحدون عذاب النار وتنكرونه في الدنيا."},{"id":"4545","s":46,"a":35,"at":"فاصبر كما صبر اولو العزم من الرسل ولا تستعجل لهم كانهم يوم يرون ما يوعدون لم يلبثوا الا ساعه من نهار بلاغ فهل يهلك الا القوم الفاسقون","dt":"[35] فاصبر -ايها الرسول- على ما اصابك من اذى قومك المكذبين لك، كما صبر اولو العزم من الرسل من قبلك -وهم على المشهور: نوح وابراهيم وموسى وعيسى وانت منهم- ولا تستعجل لقومك العذاب؛ فحين يقع ويرونه كانهم لم يمكثوا في الدنيا الا ساعه من نهار، هذا بلاغ لهم ولغيرهم. ولا يهلك بعذاب الله الا القوم الخارجون عن امره وطاعته."},{"id":"4546","s":47,"a":1,"at":"الذين كفروا وصدوا عن سبيل الله اضل اعمالهم","dt":"[1] الذين جحدوا ان الله هو الاله الحق وحده لا شريك له، وصدوا الناس عن دينه، اذهب الله اعمالهم وابطلها، واشقاهم بسببها."},{"id":"4547","s":47,"a":2,"at":"والذين امنوا وعملوا الصالحات وامنوا بما نزل على محمد وهو الحق من ربهم كفر عنهم سيئاتهم واصلح بالهم","dt":"[2] والذين صدقوا الله واتبعوا شرعه وصدقوا بالكتاب الذي انزل على محمد -صلى الله عليه وسلم-، وهو الحق الذي لا شك فيه من ربهم، عفا عنهم وستر عليهم ما عملوا من السيئات، فلم يعاقبهم عليها، واصلح شانهم في الدنيا والاخره."},{"id":"4548","s":47,"a":3,"at":"ذلك بان الذين كفروا اتبعوا الباطل وان الذين امنوا اتبعوا الحق من ربهم كذلك يضرب الله للناس امثالهم","dt":"[3] ذلك الاضلال والهدى سببه ان الذين كفروا اتبعوا الشيطان فاطاعوه، وان الذين امنوا اتبعوا الرسول -صلى الله عليه وسلم- وما جاء به من النور والهدى، كما بين الله تعالى فعله بالفريقين اهل الكفر واهل الايمان بما يستحقان يضرب سبحانه للناس امثالهم، فيلحق بكل قوم من الامثال والاشكال ما يناسبه."},{"id":"4549","s":47,"a":4,"at":"فاذا لقيتم الذين كفروا فضرب الرقاب حتى اذا اثخنتموهم فشدوا الوثاق فاما منا بعد واما فداء حتى تضع الحرب اوزارها ذلك ولو يشاء الله لانتصر منهم ولكن ليبلو بعضكم ببعض والذين قتلوا في سبيل الله فلن يضل اعمالهم","dt":"[4] فاذا لقيتم -ايها المؤمنون- الذين كفروا في ساحات الحرب فاصدقوهم القتال، واضربوا منهم الاعناق، حتى اذا اضعفتموهم بكثره القتل، وكسرتم شوكتهم، فاحكموا قيد الاسرى: فاما ان تمنوا عليهم بفك اسرهم بغير عوض، واما ان يفادوا انفسهم بالمال او غيره، واما ان يسترقوا او يقتلوا، واستمروا على ذلك حتى تنتهي الحرب. ذلك الحكم المذكور في ابتلاء المؤمنين بالكافرين ومداوله الايام بينهم، ولو يشاء الله لانتصر للمؤمنين من الكافرين بغير قتال، ولكن جعل عقوبتهم على ايديكم، فشرع الجهاد؛ ليختبركم بهم، ولينصر بكم دينه. والذين قتلوا في سبيل الله من المؤمنين فلن يبطل الله ثواب اعمالهم،"},{"id":"4550","s":47,"a":5,"at":"سيهديهم ويصلح بالهم","dt":"[5] سيوفقهم ايام حياتهم في الدنيا الى طاعته ومرضاته، ويصلح حالهم وامورهم وثوابهم في الدنيا والاخره،"},{"id":"4551","s":47,"a":6,"at":"ويدخلهم الجنه عرفها لهم","dt":"[6] ويدخلهم الجنه عرفهم بها ونعتها لهم، ووفقهم للقيام بما امرهم به -ومن جملته الشهاده في سبيله-، ثم عرفهم اذا دخلوا الجنه منازلهم بها."},{"id":"4552","s":47,"a":7,"at":"ياايها الذين امنوا ان تنصروا الله ينصركم ويثبت اقدامكم","dt":"[7] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، ان تنصروا دين الله بالجهاد في سبيله، والحكم بكتابه، وامتثال اوامره، واجتناب نواهيه، ينصركم الله على اعدائكم، ويثبت اقدامكم عند القتال."},{"id":"4553","s":47,"a":8,"at":"والذين كفروا فتعسا لهم واضل اعمالهم","dt":"[8] والذين كفروا فهلاكا لهم، واذهب الله ثواب اعمالهم؛"},{"id":"4554","s":47,"a":9,"at":"ذلك بانهم كرهوا ما انزل الله فاحبط اعمالهم","dt":"[9] ذلك بسبب انهم كرهوا كتاب الله المنزل على نبيه محمد -صلى الله عليه وسلم-، فكذبوا به، فابطل اعمالهم؛ لانها كانت في طاعه الشيطان."},{"id":"4555","s":47,"a":10,"at":"افلم يسيروا في الارض فينظروا كيف كان عاقبه الذين من قبلهم دمر الله عليهم وللكافرين امثالها","dt":"[10] افلم يسر هؤلاء الكفار في ارض الله معتبرين بما حل بالامم المكذبه قبلهم من العقاب؟ دمر الله عليهم ديارهم، وللكافرين امثال تلك العاقبه التي حلت بتلك الامم."},{"id":"4556","s":47,"a":11,"at":"ذلك بان الله مولى الذين امنوا وان الكافرين لا مولى لهم","dt":"[11] ذلك الذي فعلناه بالفريقين فريق الايمان وفريق الكفر؛ بسبب ان الله ولي المؤمنين ونصيرهم، وان الكافرين لا ولي لهم ولا نصير."},{"id":"4557","s":47,"a":12,"at":"ان الله يدخل الذين امنوا وعملوا الصالحات جنات تجري من تحتها الانهار والذين كفروا يتمتعون وياكلون كما تاكل الانعام والنار مثوى لهم","dt":"[12] ان الله يدخل الذين امنوا بالله ورسوله وعملوا الصالحات جنات تجري من تحت قصورها واشجارها الانهار تكرمه لهم، ومثل الذين كفروا في اكلهم وتمتعهم بالدنيا، كمثل الانعام من البهائم التي لا هم لها الا في الاعتلاف دون غيره، ونار جهنم مسكن لهم وماوى."},{"id":"4558","s":47,"a":13,"at":"وكاين من قريه هي اشد قوه من قريتك التي اخرجتك اهلكناهم فلا ناصر لهم","dt":"[13] وكثير من اهل قرى كانوا اشد باسا من اهل قريتك -ايها الرسول، وهي «مكه»- التي اخرجتك، دمرناهم بانواع من العذاب، فلم يكن لهم نصير ينصرهم من عذاب الله."},{"id":"4559","s":47,"a":14,"at":"افمن كان على بينه من ربه كمن زين له سوء عمله واتبعوا اهواءهم","dt":"[14] افمن كان على برهان واضح من ربه والعلم بوحدانيته، كمن حسن له الشيطان قبيح عمله، واتبع ما دعته اليه نفسه من معصيه الله وعباده غيره من غير حجه ولا برهان؟ لا يستوون."},{"id":"4560","s":47,"a":15,"at":"مثل الجنه التي وعد المتقون فيها انهار من ماء غير اسن وانهار من لبن لم يتغير طعمه وانهار من خمر لذه للشاربين وانهار من عسل مصفى ولهم فيها من كل الثمرات ومغفره من ربهم كمن هو خالد في النار وسقوا ماء حميما فقطع امعاءهم","dt":"[15] صفه الجنه التي وعدها الله المتقين: فيها انهار عظيمه من ماء غير متغير، وانهار من لبن لم يتغير طعمه، وانهار من خمر يتلذذ به الشاربون، وانهار من عسل قد صفي مما يخالطه من الشوائب، ولهؤلاء المتقين في هذه الجنه جميع الثمرات من مختلف الفواكه وغيرها، واعظم من ذلك الستر والتجاوز عن ذنوبهم، هل من هو في هذه الجنه كمن هو ماكث في النار لا يخرج منها، وسقوا ماء تناهى في شده حره فقطع امعاءهم؟"},{"id":"4561","s":47,"a":16,"at":"ومنهم من يستمع اليك حتى اذا خرجوا من عندك قالوا للذين اوتوا العلم ماذا قال انفا اولئك الذين طبع الله على قلوبهم واتبعوا اهواءهم","dt":"[16] ومن هؤلاء المنافقين من يستمع اليك -ايها النبي- بغير فهم؛ تهاونا منهم واستخفافا، حتى اذا انصرفوا من مجلسك قالوا لمن حضروا مجلسك من اهل العلم بكتاب الله -على سبيل الاستهزاء-: ماذا قال محمد الان؟ اولئك الذين ختم الله على قلوبهم، فلا تفقه الحق ولا تهتدي اليه، واتبعوا اهواءهم في الكفر والضلال."},{"id":"4562","s":47,"a":17,"at":"والذين اهتدوا زادهم هدى واتاهم تقواهم","dt":"[17] والذين اهتدوا لاتباع الحق زادهم الله هدى، فقوي بذلك ايمانهم، ووفقهم للتقوى، ويسرها لهم."},{"id":"4563","s":47,"a":18,"at":"فهل ينظرون الا الساعه ان تاتيهم بغته فقد جاء اشراطها فانى لهم اذا جاءتهم ذكراهم","dt":"[18] ما ينتظر هؤلاء المكذبون الا الساعه التي وعدوا بها ان تجيئهم فجاه، فقد ظهرت علاماتها ولم ينتفعوا بذلك، فمن اين لهم التذكر اذا جاءتهم الساعه؟"},{"id":"4564","s":47,"a":19,"at":"فاعلم انه لا اله الا الله واستغفر لذنبك وللمؤمنين والمؤمنات والله يعلم متقلبكم ومثواكم","dt":"[19] فاعلم -ايها النبي- انه لا معبود بحق الا الله، واستغفر لذنبك، واستغفر للمؤمنين والمؤمنات. والله يعلم تصرفكم في يقظتكم نهارا، ومستقركم في نومكم ليلا."},{"id":"4565","s":47,"a":20,"at":"ويقول الذين امنوا لولا نزلت سوره فاذا انزلت سوره محكمه وذكر فيها القتال رايت الذين في قلوبهم مرض ينظرون اليك نظر المغشي عليه من الموت فاولى لهم","dt":"[20] ويقول الذين امنوا بالله ورسوله: هلا نزلت سوره من الله تامرنا بجهاد الكفار، فاذا انزلت سوره محكمه بالبيان والفرائض وذكر فيها الجهاد، رايت الذين في قلوبهم شك في دين الله ونفاق ينظرون اليك -ايها النبي- نظر الذي قد غشي عليه خوف الموت، فاولى لهؤلاء الذين في قلوبهم مرض"},{"id":"4566","s":47,"a":21,"at":"طاعه وقول معروف فاذا عزم الامر فلو صدقوا الله لكان خيرا لهم","dt":"[21] ان يطيعوا الله، وان يقولوا قولا موافقا للشرع. فاذا وجب القتال وجاء امر الله بفرضه كره هؤلاء المنافقون ذلك، فلو صدقوا الله في الايمان والعمل لكان خيرا لهم من المعصيه والمخالفه."},{"id":"4567","s":47,"a":22,"at":"فهل عسيتم ان توليتم ان تفسدوا في الارض وتقطعوا ارحامكم","dt":"[22] فلعلكم ان اعرضتم عن كتاب الله وسنه نبيه محمد -صلى الله عليه وسلم- ان تعصوا الله في الارض، فتكفروا به وتسفكوا الدماء، وتقطعوا ارحامكم."},{"id":"4568","s":47,"a":23,"at":"اولئك الذين لعنهم الله فاصمهم واعمى ابصارهم","dt":"[23] اولئك الذين ابعدهم الله من رحمته، فجعلهم لا يسمعون ما ينفعهم ولا يبصرونه، فلم يتبينوا حجج الله مع كثرتها."},{"id":"4569","s":47,"a":24,"at":"افلا يتدبرون القران ام على قلوب اقفالها","dt":"[24] افلا يتدبر هؤلاء المنافقون مواعظ القران ويتفكرون في حججه؟ بل هذه القلوب مغلقه لا يصل اليها شيء من معاني هذا القران، فلا تتدبر مواعظ الله وعبره."},{"id":"4570","s":47,"a":25,"at":"ان الذين ارتدوا على ادبارهم من بعد ما تبين لهم الهدى الشيطان سول لهم واملى لهم","dt":"[25] ان الذين ارتدوا عن الهدى والايمان، ورجعوا على اعقابهم كفارا بالله من بعد ما وضح لهم الحق، الشيطان زين لهم خطاياهم، ومد لهم في الامل."},{"id":"4571","s":47,"a":26,"at":"ذلك بانهم قالوا للذين كرهوا ما نزل الله سنطيعكم في بعض الامر والله يعلم اسرارهم","dt":"[26] ذلك الامداد لهم حتى يتمادوا في الكفر؛ بسبب انهم قالوا لليهود الذين كرهوا ما نزل الله: سنطيعكم في بعض الامر الذي هو خلاف لامر الله وامر رسوله، والله تعالى يعلم ما يخفيه هؤلاء ويسرونه. فليحذر المسلم من طاعه غير الله فيما يخالف امر الله سبحانه، وامر رسوله محمد -صلى الله عليه وسلم-."},{"id":"4572","s":47,"a":27,"at":"فكيف اذا توفتهم الملائكه يضربون وجوههم وادبارهم","dt":"[27] فكيف حالهم اذا قبضت الملائكه ارواحهم وهم يضربون وجوههم وادبارهم؟"},{"id":"4573","s":47,"a":28,"at":"ذلك بانهم اتبعوا ما اسخط الله وكرهوا رضوانه فاحبط اعمالهم","dt":"[28] ذلك العذاب الذي استحقوه ونالوه؛ بسبب انهم اتبعوا ما اسخط الله عليهم من طاعه الشيطان، وكرهوا ما يرضيه عنهم من العمل الصالح، ومنه قتال الكفار بعدما افترضه عليهم، فابطل الله ثواب اعمالهم من صدقه وصله رحم وغير ذلك."},{"id":"4574","s":47,"a":29,"at":"ام حسب الذين في قلوبهم مرض ان لن يخرج الله اضغانهم","dt":"[29] بل اظن المنافقون ان الله لن يخرج ما في قلوبهم من الحسد والحقد للاسلام واهله؟ بلى فان الله يميز الصادق من الكاذب."},{"id":"4575","s":47,"a":30,"at":"ولو نشاء لاريناكهم فلعرفتهم بسيماهم ولتعرفنهم في لحن القول والله يعلم اعمالكم","dt":"[30] ولو نشاء -ايها النبي- لاريناك اشخاصهم، فلعرفتهم بعلامات ظاهره فيهم، ولتعرفنهم فيما يبدو من كلامهم الدال على مقاصدهم. والله تعالى لا تخفى عليه اعمال من اطاعه ولا اعمال من عصاه، وسيجازي كلا بما يستحق."},{"id":"4576","s":47,"a":31,"at":"ولنبلونكم حتى نعلم المجاهدين منكم والصابرين ونبلوا اخباركم","dt":"[31] ولنختبرنكم -ايها المؤمنون- بالقتال والجهاد لاعداء الله حتى يظهر ما علمه سبحانه في الازل؛ لنميز اهل الجهاد منكم والصبر على قتال اعداء الله، ونختبر اقوالكم وافعالكم، فيظهر الصادق منكم من الكاذب."},{"id":"4577","s":47,"a":32,"at":"ان الذين كفروا وصدوا عن سبيل الله وشاقوا الرسول من بعد ما تبين لهم الهدى لن يضروا الله شيئا وسيحبط اعمالهم","dt":"[32] ان الذين جحدوا ان الله هو الاله الحق وحده لا شريك له، وصدوا الناس عن دينه، وخالفوا رسول الله -صلى الله عليه وسلم-، فحاربوه من بعد ما جاءتهم الحجج والايات انه نبي من عند الله، لن يضروا دين الله شيئا، وسيبطل ثواب اعمالهم التي عملوها في الدنيا؛ لانهم لم يريدوا بها وجه الله تعالى."},{"id":"4578","s":47,"a":33,"at":"ياايها الذين امنوا اطيعوا الله واطيعوا الرسول ولا تبطلوا اعمالكم","dt":"[33] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه اطيعوا الله واطيعوا الرسول في امرهما ونهيهما، ولا تبطلوا ثواب اعمالكم بالكفر والمعاصي."},{"id":"4579","s":47,"a":34,"at":"ان الذين كفروا وصدوا عن سبيل الله ثم ماتوا وهم كفار فلن يغفر الله لهم","dt":"[34] ان الذين جحدوا ان الله هو الاله الحق وحده لا شريك له وصدوا الناس عن دينه، ثم ماتوا على ذلك، فلن يغفر الله لهم، وسيعذبهم عقابا لهم على كفرهم، ويفضحهم على رؤوس الاشهاد."},{"id":"4580","s":47,"a":35,"at":"فلا تهنوا وتدعوا الى السلم وانتم الاعلون والله معكم ولن يتركم اعمالكم","dt":"[35] فلا تضعفوا -ايها المؤمنون بالله ورسوله- عن جهاد المشركين، وتجبنوا عن قتالهم، وتدعوهم الى الصلح والمسالمه، وانتم القاهرون لهم والعالون عليهم، والله تعالى معكم بنصره وتاييده. وفي ذلك بشاره عظيمه بالنصر والظفر على الاعداء. ولن ينقصكم الله ثواب اعمالكم."},{"id":"4581","s":47,"a":36,"at":"انما الحياه الدنيا لعب ولهو وان تؤمنوا وتتقوا يؤتكم اجوركم ولا يسالكم اموالكم","dt":"[36] انما الحياه الدنيا لعب وغرور. وان تؤمنوا بالله ورسوله، وتتقوا الله باداء فرائضه واجتناب معاصيه، يؤتكم ثواب اعمالكم، ولا يسالكم اخراج اموالكم جميعها في الزكاه، بل يسالكم اخراج بعضها."},{"id":"4582","s":47,"a":37,"at":"ان يسالكموها فيحفكم تبخلوا ويخرج اضغانكم","dt":"[37] ان يسالكم اموالكم، فيلح عليكم ويجهدكم، تبخلوا بها وتمنعوه اياها، ويظهر ما في قلوبكم من الحقد اذا طلب منكم ما تكرهون بذله."},{"id":"4583","s":47,"a":38,"at":"هاانتم هؤلاء تدعون لتنفقوا في سبيل الله فمنكم من يبخل ومن يبخل فانما يبخل عن نفسه والله الغني وانتم الفقراء وان تتولوا يستبدل قوما غيركم ثم لا يكونوا امثالكم","dt":"[38] ها انتم -ايها المؤمنون- تدعون الى النفقه في جهاد اعداء الله ونصره دينه، فمنكم من يبخل بالنفقه في سبيل الله، ومن يبخل فانما يبخل عن نفسه، والله تعالى هو الغني عنكم وانتم الفقراء اليه، وان تتولوا عن الايمان بالله وامتثال امره يهلككم، ويات بقوم اخرين، ثم لا يكونوا امثالكم في التولي عن امر الله، بل يطيعونه ويطيعون رسوله، ويجاهدون في سبيله باموالهم وانفسهم."},{"id":"4584","s":48,"a":1,"at":"انا فتحنا لك فتحا مبينا","dt":"[1] انا فتحنا لك -ايها الرسول- فتحا مبينا، يظهر الله فيه دينك، وينصرك على عدوك، وهو هدنه «الحديبيه» التي امن الناس بسببها بعضهم بعضا، فاتسعت دائره الدعوه لدين الله، وتمكن من يريد الوقوف على حقيقه الاسلام من معرفته، فدخل الناس في تلك المده في دين الله افواجا؛ ولذلك سماه الله فتحا مبينا، اي ظاهرا جليا."},{"id":"4585","s":48,"a":2,"at":"ليغفر لك الله ما تقدم من ذنبك وما تاخر ويتم نعمته عليك ويهديك صراطا مستقيما","dt":"[2] فتحنا لك ذلك الفتح، ويسرناه لك؛ ليغفر لك الله ما تقدم من ذنبك وما تاخر؛ بسبب ما حصل من هذا الفتح من الطاعات الكثيره وبما تحملته من المشقات، ويتم نعمته عليك باظهار دينك ونصرك على اعدائك، ويرشدك طريقا مستقيما من الدين لا عوج فيه،"},{"id":"4586","s":48,"a":3,"at":"وينصرك الله نصرا عزيزا","dt":"[3] وينصرك الله نصرا قويا لا يضعف فيه الاسلام."},{"id":"4587","s":48,"a":4,"at":"هو الذي انزل السكينه في قلوب المؤمنين ليزدادوا ايمانا مع ايمانهم ولله جنود السموات والارض وكان الله عليما حكيما","dt":"[4] هو الله الذي انزل الطمانينه في قلوب المؤمنين بالله ورسوله يوم «الحديبيه» فسكنت، ورسخ اليقين فيها؛ ليزدادوا تصديقا لله واتباعا لرسوله مع تصديقهم واتباعهم. ولله سبحانه وتعالى جنود السموات والارض ينصر بهم عباده المؤمنين. وكان الله عليما بمصالح خلقه، حكيما في تدبيره وصنعه."},{"id":"4588","s":48,"a":5,"at":"ليدخل المؤمنين والمؤمنات جنات تجري من تحتها الانهار خالدين فيها ويكفر عنهم سيئاتهم وكان ذلك عند الله فوزا عظيما","dt":"[5] ليدخل الله المؤمنين والمؤمنات جنات تجري من تحت قصورها واشجارها الانهار، ماكثين فيها ابدا، ويمحو عنهم سيئ ما عملوا، فلا يعاقبهم عليه، وكان ذلك الجزاء عند الله نجاه من كل غم، وظفرا بكل مطلوب."},{"id":"4589","s":48,"a":6,"at":"ويعذب المنافقين والمنافقات والمشركين والمشركات الظانين بالله ظن السوء عليهم دائره السوء وغضب الله عليهم ولعنهم واعد لهم جهنم وساءت مصيرا","dt":"[6] ويعذب الله المنافقين والمنافقات والمشركين والمشركات الذين يظنون ظنا سيئا بالله انه لن ينصر نبيه والمؤمنين معه على اعدائهم، ولن يظهر دينه، فعلى هؤلاء تدور دائره العذاب وكل ما يسوءهم، وغضب الله عليهم، وطردهم من رحمته، واعد لهم نار جهنم، وساءت منزلا يصيرون اليه."},{"id":"4590","s":48,"a":7,"at":"ولله جنود السموات والارض وكان الله عزيزا حكيما","dt":"[7] ولله سبحانه وتعالى جنود السموات والارض يؤيد بهم عباده المؤمنين. وكان الله عزيزا على خلقه، حكيما في تدبير امورهم."},{"id":"4591","s":48,"a":8,"at":"انا ارسلناك شاهدا ومبشرا ونذيرا","dt":"[8] انا ارسلناك -ايها الرسول- شاهدا على امتك بالبلاغ، مبينا لهم ما ارسلناك به اليهم، ومبشرا لمن اطاعك بالجنه، ونذيرا لمن عصاك بالعقاب العاجل والاجل؛"},{"id":"4592","s":48,"a":9,"at":"لتؤمنوا بالله ورسوله وتعزروه وتوقروه وتسبحوه بكره واصيلا","dt":"[9] لتؤمنوا بالله ورسوله، وتنصروا الله بنصر دينه، وتعظموا الله، وتسبحوه اول النهار واخره."},{"id":"4593","s":48,"a":10,"at":"ان الذين يبايعونك انما يبايعون الله يد الله فوق ايديهم فمن نكث فانما ينكث على نفسه ومن اوفى بما عاهد عليه الله فسيؤتيه اجرا عظيما","dt":"[10] ان الذين يبايعونك -ايها النبي- ب«الحديبيه» على القتال انما يبايعون الله، ويعقدون العقد معه ابتغاء جنته ورضوانه، يد الله فوق ايديهم، فهو معهم يسمع اقوالهم، ويرى مكانهم، ويعلم ضمائرهم وظواهرهم، فمن نقض بيعته فانما يعود وبال ذلك على نفسه، ومن اوفى بما عاهد الله عليه من الصبر عند لقاء العدو في سبيل الله ونصره نبيه محمد -صلى الله عليه وسلم-، فسيعطيه الله ثوابا جزيلا، وهو الجنه. وفي الايه اثبات صفه اليد لله تعالى بما يليق به سبحانه، دون تشبيه ولا تكييف."},{"id":"4594","s":48,"a":11,"at":"سيقول لك المخلفون من الاعراب شغلتنا اموالنا واهلونا فاستغفر لنا يقولون بالسنتهم ما ليس في قلوبهم قل فمن يملك لكم من الله شيئا ان اراد بكم ضرا او اراد بكم نفعا بل كان الله بما تعملون خبيرا","dt":"[11] سيقول لك -ايها النبي- الذين تخلفوا من الاعراب عن الخروج معك الى «مكه» اذا عاتبتهم: شغلتنا اموالنا واهلونا، فاسال ربك ان يغفر لنا تخلفنا، يقولون ذلك بالسنتهم، ولا حقيقه له في قلوبهم، قل لهم: فمن يملك لكم من الله شيئا ان اراد بكم شرا او خيرا؟ ليس الامر كما ظن هؤلاء المنافقون ان الله لا يعلم ما انطوت عليه بواطنهم من النفاق، بل انه سبحانه كان بما يعملون خبيرا، لا يخفى عليه شيء من اعمال خلقه."},{"id":"4595","s":48,"a":12,"at":"بل ظننتم ان لن ينقلب الرسول والمؤمنون الى اهليهم ابدا وزين ذلك في قلوبكم وظننتم ظن السوء وكنتم قوما بورا","dt":"[12] وليس الامر كما زعمتم من انشغالكم بالاموال والاهل، بل انكم ظننتم ان رسول الله -صلى الله عليه وسلم- ومن معه من اصحابه سيهلكون، ولا يرجعون اليكم ابدا، وحسن الشيطان ذلك في قلوبكم، وظننتم ظنا سيئا ان الله لن ينصر نبيه محمدا -صلى الله عليه وسلم- واصحابه على اعدائهم، وكنتم قوما هلكى لا خير فيكم."},{"id":"4596","s":48,"a":13,"at":"ومن لم يؤمن بالله ورسوله فانا اعتدنا للكافرين سعيرا","dt":"[13] ومن لم يصدق بالله وبما جاء به رسوله -صلى الله عليه وسلم- ويعمل بشرعه، فانه كافر مستحق للعقاب، فانا اعددنا للكافرين عذاب السعير في النار."},{"id":"4597","s":48,"a":14,"at":"ولله ملك السموات والارض يغفر لمن يشاء ويعذب من يشاء وكان الله غفورا رحيما","dt":"[14] ولله ملك السموات والارض وما فيهما، يتجاوز برحمته عمن يشاء فيستر ذنبه، ويعذب بعدله من يشاء. وكان الله سبحانه وتعالى غفورا لمن تاب اليه، رحيما به."},{"id":"4598","s":48,"a":15,"at":"سيقول المخلفون اذا انطلقتم الى مغانم لتاخذوها ذرونا نتبعكم يريدون ان يبدلوا كلام الله قل لن تتبعونا كذلكم قال الله من قبل فسيقولون بل تحسدوننا بل كانوا لا يفقهون الا قليلا","dt":"[15] سيقول المخلفون اذا انطلقت -ايها النبي- انت واصحابك الى غنائم «خيبر» التي وعدكم الله بها: اتركونا نذهب معكم الى «خيبر»، يريدون ان يغيروا بذلك وعد الله لكم. قل لهم: لن تخرجوا معنا الى «خيبر»؛ لان الله تعالى قال لنا من قبل رجوعنا الى «المدينه»: ان غنائم «خيبر» هي لمن شهد «الحديبيه» معنا، فسيقولون: ليس الامر كما تقولون، ان الله لم يامركم بهذا، انكم تمنعوننا من الخروج معكم حسدا منكم؛ لئلا نصيب معكم الغنيمه، وليس الامر كما زعموا، بل كانوا لا يفقهون عن الله ما لهم وما عليهم من امر الدين الا يسيرا."},{"id":"4599","s":48,"a":16,"at":"قل للمخلفين من الاعراب ستدعون الى قوم اولي باس شديد تقاتلونهم او يسلمون فان تطيعوا يؤتكم الله اجرا حسنا وان تتولوا كما توليتم من قبل يعذبكم عذابا اليما","dt":"[16] قل للذين تخلفوا من الاعراب -وهم البدو- عن القتال: ستدعون الى قتال قوم اصحاب باس شديد في القتال، تقاتلونهم او يسلمون من غير قتال، فان تطيعوا الله فيما دعاكم اليه من قتال هؤلاء القوم يؤتكم الجنه، وان تعصوه كما فعلتم حين تخلفتم عن السير مع رسول الله -صلى الله عليه وسلم- الى «مكه»، يعذبكم عذابا موجعا."},{"id":"4600","s":48,"a":17,"at":"ليس على الاعمى حرج ولا على الاعرج حرج ولا على المريض حرج ومن يطع الله ورسوله يدخله جنات تجري من تحتها الانهار ومن يتول يعذبه عذابا اليما","dt":"[17] ليس على الاعمى منكم -ايها الناس- اثم، ولا على الاعرج اثم، ولا على المريض اثم في ان يتخلفوا عن الجهاد مع المؤمنين؛ لعدم استطاعتهم. ومن يطع الله ورسوله يدخله جنات تجري من تحت قصورها واشجارها الانهار، ومن يعص الله ورسوله، فيتخلف عن الجهاد مع المؤمنين، يعذبه عذابا مؤلما موجعا."},{"id":"4601","s":48,"a":18,"at":"لقد رضي الله عن المؤمنين اذ يبايعونك تحت الشجره فعلم ما في قلوبهم فانزل السكينه عليهم واثابهم فتحا قريبا","dt":"[18] لقد رضي الله عن المؤمنين حين بايعوك -ايها النبي- تحت الشجره -وهذه هي بيعه الرضوان في «الحديبيه»- فعلم الله ما في قلوب هؤلاء المؤمنين من الايمان والصدق والوفاء، فانزل الله الطمانينه عليهم وثبت قلوبهم، وعوضهم عما فاتهم بصلح «الحديبيه» فتحا قريبا، وهو فتح «خيبر»،"},{"id":"4602","s":48,"a":19,"at":"ومغانم كثيره ياخذونها وكان الله عزيزا حكيما","dt":"[19] ومغانم كثيره ياخذونها من اموال يهود «خيبر». وكان الله عزيزا في انتقامه من اعدائه، حكيما في تدبير امور خلقه."},{"id":"4603","s":48,"a":20,"at":"وعدكم الله مغانم كثيره تاخذونها فعجل لكم هذه وكف ايدي الناس عنكم ولتكون ايه للمؤمنين ويهديكم صراطا مستقيما","dt":"[20] وعدكم الله مغانم كثيره تاخذونها في اوقاتها التي قدرها الله لكم فعجل لكم غنائم «خيبر»، وكف ايدي الناس عنكم، فلم ينلكم سوء مما كان اعداؤكم اضمروه لكم من المحاربه والقتال، ومن ان ينالوا ممن تركتموهم وراءكم في «المدينه»، ولتكون هزيمتهم وسلامتكم وغنيمتكم علامه تعتبرون بها، وتستدلون على ان الله حافظكم وناصركم، ويرشدكم طريقا مستقيما لا اعوجاج فيه."},{"id":"4604","s":48,"a":21,"at":"واخرى لم تقدروا عليها قد احاط الله بها وكان الله على كل شيء قديرا","dt":"[21] وقد وعدكم الله غنيمه اخرى لم تقدروا عليها، الله سبحانه وتعالى قادر عليها، وهي تحت تدبيره وملكه، وقد وعدكموها، ولا بد من وقوع ما وعد به. وكان الله على كل شيء قديرا لا يعجزه شيء."},{"id":"4605","s":48,"a":22,"at":"ولو قاتلكم الذين كفروا لولوا الادبار ثم لا يجدون وليا ولا نصيرا","dt":"[22] ولو قاتلكم كفار قريش ب«مكه» لانهزموا عنكم وولوكم ظهورهم، كما يفعل المنهزم في القتال، ثم لا يجدون لهم من دون الله وليا يواليهم على حربكم، ولا نصيرا يعينهم على قتالكم."},{"id":"4606","s":48,"a":23,"at":"سنه الله التي قد خلت من قبل ولن تجد لسنه الله تبديلا","dt":"[23] سنه الله التي سنها في خلقه من قبل بنصر جنده وهزيمه اعدائه، ولن تجد -ايها النبي- لسنه الله تغييرا."},{"id":"4607","s":48,"a":24,"at":"وهو الذي كف ايديهم عنكم وايديكم عنهم ببطن مكه من بعد ان اظفركم عليهم وكان الله بما تعملون بصيرا","dt":"[24] وهو الذي كف ايدي المشركين عنكم، وايديكم عنهم ب«الحديبيه» غرب «مكه» من بعد ما قدرتم عليهم، فصاروا تحت سلطانكم، وهؤلاء المشركون هم الذين خرجوا على عسكر رسول الله -صلى الله عليه وسلم- ب«الحديبيه»، فامسكهم المسلمون ثم تركوهم ولم يقتلوهم، وكانوا نحو ثمانين رجلا، وكان الله باعمالكم بصيرا، لا تخفى عليه خافيه."},{"id":"4608","s":48,"a":25,"at":"هم الذين كفروا وصدوكم عن المسجد الحرام والهدي معكوفا ان يبلغ محله ولولا رجال مؤمنون ونساء مؤمنات لم تعلموهم ان تطئوهم فتصيبكم منهم معره بغير علم ليدخل الله في رحمته من يشاء لو تزيلوا لعذبنا الذين كفروا منهم عذابا اليما","dt":"[25] كفار قريش هم الذين جحدوا توحيد الله، وصدوكم يوم «الحديبيه» عن دخول المسجد الحرام، ومنعوا الهدي، وحبسوه ان يبلغ محل نحره، وهو الحرم. ولولا رجال مؤمنون مستضعفون ونساء مؤمنات بين اظهر هؤلاء الكافرين ب«مكه»، يكتمون ايمانهم خيفه على انفسهم لم تعرفوهم؛ خشيه ان تطؤوهم بجيشكم فتقتلوهم، فيصيبكم بذلك القتل اثم وعيب وغرامه بغير علم، لكنا سلطناكم على المشركين؛ ليدخل الله في رحمته من يشاء فيمن عليهم بالايمان بعد الكفر، لو تميز هؤلاء المؤمنون والمؤمنات عن مشركي «مكه» وخرجوا من بينهم، لعذبنا الذين كفروا وكذبوا منهم عذابا مؤلما موجعا."},{"id":"4609","s":48,"a":26,"at":"اذ جعل الذين كفروا في قلوبهم الحميه حميه الجاهليه فانزل الله سكينته على رسوله وعلى المؤمنين والزمهم كلمه التقوى وكانوا احق بها واهلها وكان الله بكل شيء عليما","dt":"[26] اذ جعل الذين كفروا في قلوبهم الانفه انفه الجاهليه؛ لئلا يقروا برساله محمد -صلى الله عليه وسلم-، ومن ذلك امتناعهم ان يكتبوا في صلح «الحديبيه» «بسم الله الرحمن الرحيم» وابوا ان يكتبوا «هذا ما قاضى عليه محمد رسول الله»، فانزل الله الطمانينه على رسوله وعلى المؤمنين معه، والزمهم قول «لا اله الا الله» التي هي راس كل تقوى، وكان الرسول -صلى الله عليه وسلم- والمؤمنون معه احق بكلمه التقوى من المشركين، وكانوا كذلك اهل هذه الكلمه دون المشركين. وكان الله بكل شيء عليما لا يخفى عليه شيء."},{"id":"4610","s":48,"a":27,"at":"لقد صدق الله رسوله الرؤيا بالحق لتدخلن المسجد الحرام ان شاء الله امنين محلقين رءوسكم ومقصرين لا تخافون فعلم ما لم تعلموا فجعل من دون ذلك فتحا قريبا","dt":"[27] لقد صدق الله رسوله محمدا -صلى الله عليه وسلم- رؤياه التي اراها اياه بالحق لتدخلن انت واصحابك بيت الله الحرام امنين، لا تخافون اهل الشرك، محلقين رؤوسكم ومقصرين، فعلم الله من الخير والمصلحه -في صرفكم عن «مكه» عامكم ذلك ودخولكم اليها فيما بعد- ما لم تعلموا انتم، فجعل من دون دخولكم «مكه» الذي وعدتم به، فتحا قريبا، وهو هدنه «الحديبيه» وفتح «خيبر»."},{"id":"4611","s":48,"a":28,"at":"هو الذي ارسل رسوله بالهدى ودين الحق ليظهره على الدين كله وكفى بالله شهيدا","dt":"[28] هو الذي ارسل رسوله محمدا -صلى الله عليه وسلم-، بالبيان الواضح ودين الاسلام؛ ليعليه على الملل كلها، وحسبك -ايها الرسول- بالله شاهدا على انه ناصرك ومظهر دينك على كل دين."},{"id":"4612","s":48,"a":29,"at":"محمد رسول الله والذين معه اشداء على الكفار رحماء بينهم تراهم ركعا سجدا يبتغون فضلا من الله ورضوانا سيماهم في وجوههم من اثر السجود ذلك مثلهم في التوراه ومثلهم في الانجيل كزرع اخرج شطاه فازره فاستغلظ فاستوى على سوقه يعجب الزراع ليغيظ بهم الكفار وعد الله الذين امنوا وعملوا الصالحات منهم مغفره واجرا عظيما","dt":"[29] محمد رسول الله، والذين معه على دينه اشداء على الكفار، رحماء فيما بينهم، تراهم ركعا سجدا لله في صلاتهم، يرجون ربهم ان يتفضل عليهم، فيدخلهم الجنه، ويرضى عنهم، علامه طاعتهم لله ظاهره في وجوههم من اثر السجود والعباده، هذه صفتهم في التوراه. وصفتهم في الانجيل كصفه زرع اخرج ساقه وفرعه، ثم تكاثرت فروعه بعد ذلك، وشدت الزرع، فقوي واستوى قائما على سيقانه جميلا منظره، يعجب الزراع؛ ليغيظ بهؤلاء المؤمنين في كثرتهم وجمال منظرهم الكفار. وفي هذا دليل على كفر من ابغض الصحابه -رضي الله عنهم-؛ لان من غاظه الله بالصحابه، فقد وجد في حقه موجب الغيظ، وهو الكفر. وعد الله الذين امنوا منهم بالله ورسوله وعملوا ما امرهم الله به، واجتنبوا ما نهاهم عنه، مغفره لذنوبهم، وثوابا جزيلا لا ينقطع، وهو الجنه. ووعد الله حق مصدق لا يخلف، وكل من اقتفى اثر الصحابه رضي الله عنهم فهو في حكمهم في استحقاق المغفره والاجر العظيم، ولهم الفضل والسبق والكمال الذي لا يلحقهم فيه احد من هذه الامه، رضي الله عنهم وارضاهم."},{"id":"4613","s":49,"a":1,"at":"ياايها الذين امنوا لا تقدموا بين يدي الله ورسوله واتقوا الله ان الله سميع عليم","dt":"[1] يا ايها الذين امنوا بالله ورسوله لا تقضوا امرا دون امر الله ورسوله من شرائع دينكم فتبتدعوا، وخافوا الله في قولكم وفعلكم ان يخالف امر الله ورسوله، ان الله سميع لاقوالكم، عليم بنياتكم وافعالكم. وفي هذا تحذير للمؤمنين ان يبتدعوا في الدين، او يشرعوا ما لم ياذن به الله."},{"id":"4614","s":49,"a":2,"at":"ياايها الذين امنوا لا ترفعوا اصواتكم فوق صوت النبي ولا تجهروا له بالقول كجهر بعضكم لبعض ان تحبط اعمالكم وانتم لا تشعرون","dt":"[2] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، لا ترفعوا اصواتكم فوق صوت النبي عند مخاطبتكم له، ولا تجهروا بمناداته كما يجهر بعضكم لبعض، وميزوه في خطابه كما تميز عن غيره في اصطفائه لحمل رساله ربه، ووجوب الايمان به، ومحبته وطاعته والاقتداء به؛ خشيه ان تبطل اعمالكم، وانتم لا تشعرون، ولا تحسون بذلك."},{"id":"4615","s":49,"a":3,"at":"ان الذين يغضون اصواتهم عند رسول الله اولئك الذين امتحن الله قلوبهم للتقوى لهم مغفره واجر عظيم","dt":"[3] ان الذين يخفضون اصواتهم عند رسول الله اولئك الذين اختبر الله قلوبهم، واخلصها لتقواه، لهم من الله مغفره لذنوبهم وثواب جزيل، وهو الجنه."},{"id":"4616","s":49,"a":4,"at":"ان الذين ينادونك من وراء الحجرات اكثرهم لا يعقلون","dt":"[4] ان الذين ينادونك -ايها النبي- من وراء حجراتك بصوت مرتفع، اكثرهم ليس لهم من العقل ما يحملهم على حسن الادب مع رسول الله -صلى الله عليه وسلم-، وتوقيره."},{"id":"4617","s":49,"a":5,"at":"ولو انهم صبروا حتى تخرج اليهم لكان خيرا لهم والله غفور رحيم","dt":"[5] ولو انهم صبروا حتى تخرج اليهم لكان خيرا لهم عند الله؛ لان الله قد امرهم بتوقيرك، والله غفور لما صدر عنهم جهلا منهم من الذنوب والاخلال بالاداب، رحيم بهم حيث لم يعاجلهم بالعقوبه."},{"id":"4618","s":49,"a":6,"at":"ياايها الذين امنوا ان جاءكم فاسق بنبا فتبينوا ان تصيبوا قوما بجهاله فتصبحوا على ما فعلتم نادمين","dt":"[6] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، ان جاءكم فاسق بخبر فتثبتوا من خبره قبل تصديقه ونقله حتى تعرفوا صحته؛ خشيه ان تصيبوا قوما براء بجنايه منكم، فتندموا على ذلك."},{"id":"4619","s":49,"a":7,"at":"واعلموا ان فيكم رسول الله لو يطيعكم في كثير من الامر لعنتم ولكن الله حبب اليكم الايمان وزينه في قلوبكم وكره اليكم الكفر والفسوق والعصيان اولئك هم الراشدون","dt":"[7] واعلموا ان بين اظهركم رسول الله فتادبوا معه؛ فانه اعلم منكم بما يصلح لكم، يريد بكم الخير، وقد تريدون لانفسكم من الشر والمضره ما لا يوافقكم الرسول عليه، لو يطيعكم في كثير من الامر مما تختارونه لادى ذلك الى مشقتكم، ولكن الله حبب اليكم الايمان وحسنه في قلوبكم، فامنتم، وكره اليكم الكفر بالله والخروج عن طاعته، ومعصيته، اولئك المتصفون بهذه الصفات هم الراشدون السالكون طريق الحق."},{"id":"4620","s":49,"a":8,"at":"فضلا من الله ونعمه والله عليم حكيم","dt":"[8] وهذا الخير الذي حصل لهم فضل من الله عليهم ونعمه. والله عليم بمن يشكر نعمه، حكيم في تدبير امور خلقه."},{"id":"4621","s":49,"a":9,"at":"وان طائفتان من المؤمنين اقتتلوا فاصلحوا بينهما فان بغت احداهما على الاخرى فقاتلوا التي تبغي حتى تفيء الى امر الله فان فاءت فاصلحوا بينهما بالعدل واقسطوا ان الله يحب المقسطين","dt":"[9] وان طائفتان من اهل الايمان اقتتلوا فاصلحوا -ايها المؤمنون- بينهما بدعوتهما الى الاحتكام الى كتاب الله وسنه رسوله -صلى الله عليه وسلم-، والرضا بحكمهما، فان اعتدت احدى الطائفتين وابت الاجابه الى ذلك، فقاتلوها حتى ترجع الى حكم الله ورسوله، فان رجعت فاصلحوا بينهما بالانصاف، واعدلوا في حكمكم بان لا تتجاوزوا في احكامكم حكم الله وحكم رسوله، ان الله يحب العادلين في احكامهم القاضين بين خلقه بالقسط. وفي الايه اثبات صفه المحبه لله على الحقيقه، كما يليق بجلاله سبحانه."},{"id":"4622","s":49,"a":10,"at":"انما المؤمنون اخوه فاصلحوا بين اخويكم واتقوا الله لعلكم ترحمون","dt":"[10] انما المؤمنون اخوه في الدين، فاصلحوا بين اخويكم اذا اقتتلا، وخافوا الله في جميع اموركم؛ رجاء ان ترحموا."},{"id":"4623","s":49,"a":11,"at":"ياايها الذين امنوا لا يسخر قوم من قوم عسى ان يكونوا خيرا منهم ولا نساء من نساء عسى ان يكن خيرا منهن ولا تلمزوا انفسكم ولا تنابزوا بالالقاب بئس الاسم الفسوق بعد الايمان ومن لم يتب فاولئك هم الظالمون","dt":"[11] يا ايها الذين صدقوا الله ورسوله وعملوا بشريعته لا يهزا قوم مؤمنون من قوم مؤمنين؛ عسى ان يكون المهزوء به منهم خيرا من الهازئين، ولا يهزا نساء مؤمنات من نساء مؤمنات؛ عسى ان يكون المهزوء به منهن خيرا من الهازئات، ولا يعب بعضكم بعضا، ولا يدع بعضكم بعضا بما يكره من الالقاب، بئس الصفه والاسم الفسوق، وهو السخريه واللمز والتنابز بالالقاب، بعد ما دخلتم في الاسلام وعقلتموه، ومن لم يتب من هذه السخريه واللمز والتنابز والفسوق فاولئك هم الذين ظلموا انفسهم بارتكاب هذه المناهي."},{"id":"4624","s":49,"a":12,"at":"ياايها الذين امنوا اجتنبوا كثيرا من الظن ان بعض الظن اثم ولا تجسسوا ولا يغتب بعضكم بعضا ايحب احدكم ان ياكل لحم اخيه ميتا فكرهتموه واتقوا الله ان الله تواب رحيم","dt":"[12] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه اجتنبوا كثيرا من ظن السوء بالمؤمنين؛ ان بعض ذلك الظن اثم، ولا تفتشوا عن عورات المسلمين، ولا يقل بعضكم في بعض بظهر الغيب ما يكره. ايحب احدكم اكل لحم اخيه وهو ميت؟ فانتم تكرهون ذلك، فاكرهوا اغتيابه. وخافوا الله فيما امركم به ونهاكم عنه. ان الله تواب على عباده المؤمنين، رحيم بهم."},{"id":"4625","s":49,"a":13,"at":"ياايها الناس انا خلقناكم من ذكر وانثى وجعلناكم شعوبا وقبائل لتعارفوا ان اكرمكم عند الله اتقاكم ان الله عليم خبير","dt":"[13] يا ايها الناس انا خلقناكم من اب واحد هو ادم، وام واحده هي حواء، فلا تفاضل بينكم في النسب، وجعلناكم بالتناسل شعوبا وقبائل متعدده؛ ليعرف بعضكم بعضا، ان اكرمكم عند الله اشدكم اتقاء له. ان الله عليم بالمتقين، خبير بهم."},{"id":"4626","s":49,"a":14,"at":"قالت الاعراب امنا قل لم تؤمنوا ولكن قولوا اسلمنا ولما يدخل الايمان في قلوبكم وان تطيعوا الله ورسوله لا يلتكم من اعمالكم شيئا ان الله غفور رحيم","dt":"[14] قالت الاعراب -وهم البدو-: امنا بالله ورسوله ايمانا كاملا، قل لهم -ايها النبي-: لا تدعوا لانفسكم الايمان الكامل، ولكن قولوا: اسلمنا، ولم يدخل بعد الايمان في قلوبكم، وان تطيعوا الله ورسوله لا ينقصكم من ثواب اعمالكم شيئا. ان الله غفور لمن تاب من ذنوبه، رحيم به. وفي الايه زجر لمن يظهر الايمان، ومتابعه السنه، واعماله تشهد بخلاف ذلك."},{"id":"4627","s":49,"a":15,"at":"انما المؤمنون الذين امنوا بالله ورسوله ثم لم يرتابوا وجاهدوا باموالهم وانفسهم في سبيل الله اولئك هم الصادقون","dt":"[15] انما المؤمنون الذين صدقوا بالله وبرسوله وعملوا بشرعه، ثم لم يرتابوا في ايمانهم، وبذلوا نفائس اموالهم وارواحهم في الجهاد في سبيل الله وطاعته ورضوانه، اولئك هم الصادقون في ايمانهم."},{"id":"4628","s":49,"a":16,"at":"قل اتعلمون الله بدينكم والله يعلم ما في السموات وما في الارض والله بكل شيء عليم","dt":"[16] قل -ايها النبي- لهؤلاء الاعراب: اتخبرون الله بدينكم وبما في ضمائركم، والله يعلم ما في السموات وما في الارض؟ والله بكل شيء عليم، لا يخفى عليه ما في قلوبكم من الايمان او الكفر، والبر او الفجور."},{"id":"4629","s":49,"a":17,"at":"يمنون عليك ان اسلموا قل لا تمنوا علي اسلامكم بل الله يمن عليكم ان هداكم للايمان ان كنتم صادقين","dt":"[17] يمن هؤلاء الاعراب عليك -ايها النبي- باسلامهم ومتابعتهم ونصرتهم لك، قل لهم: لا تمنوا علي دخولكم في الاسلام؛ فان نفع ذلك انما يعود عليكم، ولله المنه عليكم فيه ان وفقكم للايمان به وبرسوله، ان كنتم صادقين في ايمانكم."},{"id":"4630","s":49,"a":18,"at":"ان الله يعلم غيب السموات والارض والله بصير بما تعملون","dt":"[18] ان الله يعلم غيب السموات والارض، لا يخفى عليه شيء من ذلك، والله بصير باعمالكم وسيجازيكم عليها، ان خيرا فخير، وان شرا فشر."},{"id":"4631","s":50,"a":1,"at":"ق والقران المجيد","dt":"[1] ق سبق الكلام على الحروف المقطعه في اول سوره البقره.اقسم الله تعالى بالقران الكريم ذي المجد والشرف."},{"id":"4632","s":50,"a":2,"at":"بل عجبوا ان جاءهم منذر منهم فقال الكافرون هذا شيء عجيب","dt":"[2] بل عجب المكذبون للرسول -صلى الله عليه وسلم- ان جاءهم منذر منهم ينذرهم عقاب الله، فقال الكافرون بالله ورسوله: هذا شيء مستغرب يتعجب منه."},{"id":"4633","s":50,"a":3,"at":"ائذا متنا وكنا ترابا ذلك رجع بعيد","dt":"[3] ااذا متنا وصرنا ترابا، كيف يمكن الرجوع بعد ذلك الى ما كنا عليه؟ ذلك رجع بعيد الوقوع."},{"id":"4634","s":50,"a":4,"at":"قد علمنا ما تنقص الارض منهم وعندنا كتاب حفيظ","dt":"[4] قد علمنا ما تنقص الارض وتفني من اجسامهم، وعندنا كتاب محفوظ من التغيير والتبديل، بكل ما يجري عليهم في حياتهم وبعد مماتهم."},{"id":"4635","s":50,"a":5,"at":"بل كذبوا بالحق لما جاءهم فهم في امر مريج","dt":"[5] بل كذب هؤلاء المشركون بالقران حين جاءهم، فهم في امر مضطرب مختلط، لا يثبتون على شيء، ولا يستقر لهم قرار."},{"id":"4636","s":50,"a":6,"at":"افلم ينظروا الى السماء فوقهم كيف بنيناها وزيناها وما لها من فروج","dt":"[6] اغفلوا حين كفروا بالبعث، فلم ينظروا الى السماء فوقهم، كيف بنيناها مستويه الارجاء، ثابته البناء، وزيناها بالنجوم، وما لها من شقوق وفتوق، فهي سليمه من التفاوت والعيوب؟"},{"id":"4637","s":50,"a":7,"at":"والارض مددناها والقينا فيها رواسي وانبتنا فيها من كل زوج بهيج","dt":"[7] والارض وسعناها وفرشناها، وجعلنا فيها جبالا ثوابت؛ لئلا تميل باهلها، وانبتنا فيها من كل نوع حسن المنظر نافع، يسر ويبهج الناظر اليه."},{"id":"4638","s":50,"a":8,"at":"تبصره وذكرى لكل عبد منيب","dt":"[8] خلق الله السموات والارض وما فيهما من الايات العظيمه عبره يتبصر بها من عمى الجهل، وذكرى لكل عبد خاضع خائف وجل، رجاع الى الله عز وجل."},{"id":"4639","s":50,"a":9,"at":"ونزلنا من السماء ماء مباركا فانبتنا به جنات وحب الحصيد","dt":"[9] ونزلنا من السماء مطرا كثير المنافع، فانبتنا به بساتين كثيره الاشجار، وحب الزرع المحصود."},{"id":"4640","s":50,"a":10,"at":"والنخل باسقات لها طلع نضيد","dt":"[10] وانبتنا النخل طوالا، لها طلع متراكب بعضه فوق بعض."},{"id":"4641","s":50,"a":11,"at":"رزقا للعباد واحيينا به بلده ميتا كذلك الخروج","dt":"[11] انبتنا ذلك رزقا للعباد يقتاتون به حسب حاجاتهم، واحيينا بهذا الماء الذي انزلناه من السماء بلده قد اجدبت وقحطت، فلا زرع فيها ولا نبات، كما احيينا بذلك الماء الارض الميته نخرجكم يوم القيامه احياء بعد الموت."},{"id":"4642","s":50,"a":12,"at":"كذبت قبلهم قوم نوح واصحاب الرس وثمود","dt":"[12] كذبت قبل هؤلاء المشركين من قريش قوم نوح واصحاب البئر وثمود،"},{"id":"4643","s":50,"a":13,"at":"وعاد وفرعون واخوان لوط","dt":"[13] وعاد وفرعون وقوم لوط،"},{"id":"4644","s":50,"a":14,"at":"واصحاب الايكه وقوم تبع كل كذب الرسل فحق وعيد","dt":"[14] ، واصحاب الايكه قوم شعيب، وقوم تبع الحميري، كل هؤلاء الاقوام كذبوا رسلهم، فحق عليهم الوعيد الذي توعدهم الله به على كفرهم."},{"id":"4645","s":50,"a":15,"at":"افعيينا بالخلق الاول بل هم في لبس من خلق جديد","dt":"[15] افعجزنا عن ابتداع الخلق الاول الذي خلقناه ولم يكن شيئا، فنعجز عن اعادتهم خلقا جديدا بعد فنائهم؟ لا يعجزنا ذلك، بل نحن عليه قادرون، ولكنهم في حيره وشك من امر البعث والنشور."},{"id":"4646","s":50,"a":16,"at":"ولقد خلقنا الانسان ونعلم ما توسوس به نفسه ونحن اقرب اليه من حبل الوريد","dt":"[16] ولقد خلقنا الانسان، ونعلم ما تحدث به نفسه، ونحن اقرب اليه من حبل الوريد، وهو عرق في العنق متصل بالقلب."},{"id":"4647","s":50,"a":17,"at":"اذ يتلقى المتلقيان عن اليمين وعن الشمال قعيد","dt":"[17] حين يكتب الملكان المترصدان عن يمينه وعن شماله اعماله. فالذي عن اليمين يكتب الحسنات، والذي عن الشمال يكتب السيئات."},{"id":"4648","s":50,"a":18,"at":"ما يلفظ من قول الا لديه رقيب عتيد","dt":"[18] ما يلفظ من قول فيتكلم به الا لديه ملك يرقب قوله، ويكتبه، وهو ملك حاضر معد لذلك."},{"id":"4649","s":50,"a":19,"at":"وجاءت سكره الموت بالحق ذلك ما كنت منه تحيد","dt":"[19] وجاءت شده الموت وغمرته بالحق الذي لا مرد له ولا مناص، ذلك ما كنت منه -ايها الانسان- تهرب وتروغ."},{"id":"4650","s":50,"a":20,"at":"ونفخ في الصور ذلك يوم الوعيد","dt":"[20] ونفخ في «القرن» نفخه البعث الثانيه، ذلك النفخ في يوم وقوع الوعيد الذي توعد الله به الكفار."},{"id":"4651","s":50,"a":21,"at":"وجاءت كل نفس معها سائق وشهيد","dt":"[21] وجاءت كل نفس معها ملكان، احدهما يسوقها الى المحشر، والاخر يشهد عليها بما عملت في الدنيا من خير وشر."},{"id":"4652","s":50,"a":22,"at":"لقد كنت في غفله من هذا فكشفنا عنك غطاءك فبصرك اليوم حديد","dt":"[22] لقد كنت في غفله من هذا الذي عاينت اليوم ايها الانسان، فكشفنا عنك غطاءك الذي غطى قلبك، فزالت الغفله عنك، فبصرك اليوم فيما تشهد قوي شديد."},{"id":"4653","s":50,"a":23,"at":"وقال قرينه هذا ما لدي عتيد","dt":"[23] وقال الملك الكاتب الشهيد عليه: هذا ما عندي من ديوان عمله، وهو لدي معد محفوظ حاضر."},{"id":"4654","s":50,"a":24,"at":"القيا في جهنم كل كفار عنيد","dt":"[24] يقول الله للملكين السائق والشهيد بعد ان يفصل بين الخلائق: القيا في جهنم كل جاحد، كثير الكفر والتكذيب بالله، معاند للحق،"},{"id":"4655","s":50,"a":25,"at":"مناع للخير معتد مريب","dt":"[25] مناع لاداء ما عليه من الحقوق في ماله، معتد على عباد الله وعلى حدوده، شاك في وعده ووعيده،"},{"id":"4656","s":50,"a":26,"at":"الذي جعل مع الله الها اخر فالقياه في العذاب الشديد","dt":"[26] الذي اشرك بالله، فعبد معه معبودا اخر من خلقه، فالقياه في عذاب جهنم الشديد."},{"id":"4657","s":50,"a":27,"at":"قال قرينه ربنا ما اطغيته ولكن كان في ضلال بعيد","dt":"[27] قال شيطانه الذي كان معه في الدنيا: ربنا ما اضللته، ولكن كان في طريق بعيد عن سبيل الهدى."},{"id":"4658","s":50,"a":28,"at":"قال لا تختصموا لدي وقد قدمت اليكم بالوعيد","dt":"[28] قال الله تعالى: لا تختصموا لدي اليوم في موقف الجزاء والحساب؛ اذ لا فائده من ذلك، وقد قدمت اليكم في الدنيا بالوعيد لمن كفر بي وعصاني."},{"id":"4659","s":50,"a":29,"at":"ما يبدل القول لدي وما انا بظلام للعبيد","dt":"[29] ما يغير القول لدي، ولست اعذب احدا بذنب احد، فلا اعذب احدا الا بذنبه بعد قيام الحجه عليه."},{"id":"4660","s":50,"a":30,"at":"يوم نقول لجهنم هل امتلات وتقول هل من مزيد","dt":"[30] اذكر -ايها الرسول- لقومك يوم نقول لجهنم يوم القيامه: هل امتلات؟ وتقول جهنم: هل من زياده من الجن والانس؟ فيضع الرب -جل جلاله- قدمه فيها، فينزوي بعضها الى بعض، وتقول: قط قط، اي: حسبي، قد امتلات ليس في مزيد."},{"id":"4661","s":50,"a":31,"at":"وازلفت الجنه للمتقين غير بعيد","dt":"[31] وقربت الجنه للمتقين مكانا غير بعيد منهم، فهم يشاهدونها زياده في المسره لهم."},{"id":"4662","s":50,"a":32,"at":"هذا ما توعدون لكل اواب حفيظ","dt":"[32] يقال لهم: هذا الذي كنتم توعدون به -ايها المتقون- لكل تائب من ذنوبه، حافظ لكل ما قربه الى ربه، من الفرائض والطاعات،"},{"id":"4663","s":50,"a":33,"at":"من خشي الرحمن بالغيب وجاء بقلب منيب","dt":"[33] من خاف الله في الدنيا ولقيه يوم القيامه بقلب تائب من ذنوبه."},{"id":"4664","s":50,"a":34,"at":"ادخلوها بسلام ذلك يوم الخلود","dt":"[34] ويقال لهؤلاء المؤمنين: ادخلوا الجنه دخولا مقرونا بالسلامه من الافات والشرور، مامونا فيه جميع المكاره، ذلك هو يوم الخلود بلا انقطاع."},{"id":"4665","s":50,"a":35,"at":"لهم ما يشاءون فيها ولدينا مزيد","dt":"[35] لهؤلاء المؤمنين في الجنه ما يريدون، ولدينا على ما اعطيناهم زياده نعيم، اعظمه النظر الى وجه الله الكريم."},{"id":"4666","s":50,"a":36,"at":"وكم اهلكنا قبلهم من قرن هم اشد منهم بطشا فنقبوا في البلاد هل من محيص","dt":"[36] واهلكنا قبل هؤلاء المشركين من قريش امما كثيره، كانوا اشد منهم قوه وسطوه، فطوفوا في البلاد وسلكوا كل طريق؛ طلبا للهرب من الهلاك، ، هل من مهرب من عذاب الله حين جاءهم؟"},{"id":"4667","s":50,"a":37,"at":"ان في ذلك لذكرى لمن كان له قلب او القى السمع وهو شهيد","dt":"[37] ان في اهلاك القرون الماضيه لعبره لمن كان له قلب يعقل به، او اصغى السمع، وهو حاضر بقلبه، غير غافل ولا ساه."},{"id":"4668","s":50,"a":38,"at":"ولقد خلقنا السموات والارض وما بينهما في سته ايام وما مسنا من لغوب","dt":"[38] ولقد خلقنا السموات السبع والارض وما بينهما من اصناف المخلوقات في سته ايام، وما اصابنا من ذلك الخلق تعب ولا نصب. وفي هذه القدره العظيمه دليل على قدرته -سبحانه- على احياء الموتى من باب اولى."},{"id":"4669","s":50,"a":39,"at":"فاصبر على ما يقولون وسبح بحمد ربك قبل طلوع الشمس وقبل الغروب","dt":"[39] فاصبر -ايها الرسول- على ما يقوله المكذبون، فان الله لهم بالمرصاد، وصل -لربك حامدا له- صلاه الصبح قبل طلوع الشمس وصلاه العصر قبل الغروب،"},{"id":"4670","s":50,"a":40,"at":"ومن الليل فسبحه وادبار السجود","dt":"[40] وصل من الليل، وسبح بحمد ربك عقب الصلوات."},{"id":"4671","s":50,"a":41,"at":"واستمع يوم يناد المناد من مكان قريب","dt":"[41] واستمع -ايها الرسول- يوم ينادي الملك بنفخه في «القرن» من مكان قريب،"},{"id":"4672","s":50,"a":42,"at":"يوم يسمعون الصيحه بالحق ذلك يوم الخروج","dt":"[42] يوم يسمعون صيحه البعث بالحق الذي لا شك فيه ولا امتراء، ذلك يوم خروج اهل القبور من قبورهم."},{"id":"4673","s":50,"a":43,"at":"انا نحن نحيي ونميت والينا المصير","dt":"[43] انا نحن نحيي الخلق ونميتهم في الدنيا، والينا مصيرهم جميعا يوم القيامه للحساب والجزاء،"},{"id":"4674","s":50,"a":44,"at":"يوم تشقق الارض عنهم سراعا ذلك حشر علينا يسير","dt":"44] يوم تتصدع الارض عن الموتى المقبورين بها، فيخرجون مسرعين الى الداعي، ذلك الجمع في موقف الحساب علينا سهل يسير."},{"id":"4675","s":50,"a":45,"at":"نحن اعلم بما يقولون وما انت عليهم بجبار فذكر بالقران من يخاف وعيد","dt":"[45] نحن اعلم بما يقول هؤلاء المشركون من افتراء على الله وتكذيب باياته، وما انت -ايها الرسول- عليهم بمسلط؛ لتجبرهم على الاسلام، وانما بعثت مبلغا، فذكر بالقران من يخشى وعيدي؛ لان من لا يخاف الوعيد لا يذكر."},{"id":"4676","s":51,"a":1,"at":"والذاريات ذروا","dt":"[1] اقسم الله تعالى بالرياح المثيرات للتراب،"},{"id":"4677","s":51,"a":2,"at":"فالحاملات وقرا","dt":"[2] فالسحب الحاملات ثقلا عظيما من الماء"},{"id":"4678","s":51,"a":3,"at":"فالجاريات يسرا","dt":"[3] فالسفن التي تجري في البحار جريا ذا يسر وسهوله،"},{"id":"4679","s":51,"a":4,"at":"فالمقسمات امرا","dt":"[4] فالملائكه التي تقسم امر الله في خلقه."},{"id":"4680","s":51,"a":5,"at":"انما توعدون لصادق","dt":"[5] ان الذي توعدون به -ايها الناس- من البعث والحساب لكائن حق يقين،"},{"id":"4681","s":51,"a":6,"at":"وان الدين لواقع","dt":"[6] وان الحساب والثواب على الاعمال لكائن لا محاله."},{"id":"4682","s":51,"a":7,"at":"والسماء ذات الحبك","dt":"[7] واقسم الله تعالى بالسماء ذات الخلق الحسن،"},{"id":"4683","s":51,"a":8,"at":"انكم لفي قول مختلف","dt":"[8] انكم -ايها المكذبون- لفي قول مضطرب في هذا القران، وفي الرسول -صلى الله عليه وسلم-"},{"id":"4684","s":51,"a":9,"at":"يؤفك عنه من افك","dt":"[9] يصرف عن القران والرسول -صلى الله عليه وسلم- من صرف عن الايمان بهما؛ لاعراضه عن ادله الله وبراهينه اليقينيه فلم يوفق الى الخير."},{"id":"4685","s":51,"a":10,"at":"قتل الخراصون","dt":"[10] لعن الكذابون الظانون غير الحق،"},{"id":"4686","s":51,"a":11,"at":"الذين هم في غمره ساهون","dt":"[11] الذين هم في لجه من الكفر والضلاله غافلون متمادون."},{"id":"4687","s":51,"a":12,"at":"يسالون ايان يوم الدين","dt":"[12] يسال هؤلاء الكذابون سؤال استبعاد وتكذيب: متى يوم الحساب والجزاء؟"},{"id":"4688","s":51,"a":13,"at":"يوم هم على النار يفتنون","dt":"[13] يوم الجزاء يوم يعذبون بالاحراق بالنار،"},{"id":"4689","s":51,"a":14,"at":"ذوقوا فتنتكم هذا الذي كنتم به تستعجلون","dt":"[14] ويقال لهم: ذوقوا عذابكم الذي كنتم به تستعجلون في الدنيا."},{"id":"4690","s":51,"a":15,"at":"ان المتقين في جنات وعيون","dt":"[15] ان الذين اتقوا الله في جنات عظيمه، وعيون ماء جاريه، اعطاهم الله جميع مناهم من اصناف النعيم،"},{"id":"4691","s":51,"a":16,"at":"اخذين ما اتاهم ربهم انهم كانوا قبل ذلك محسنين","dt":"[16] فاخذوا ذلك راضين به، فرحه به نفوسهم، انهم كانوا قبل ذلك النعيم محسنين في الدنيا باعمالهم الصالحه."},{"id":"4692","s":51,"a":17,"at":"كانوا قليلا من الليل ما يهجعون","dt":"[17] كان هؤلاء المحسنون قليلا من الليل ما ينامون، يصلون لربهم قانتين له،"},{"id":"4693","s":51,"a":18,"at":"وبالاسحار هم يستغفرون","dt":"[18] وفي اواخر الليل قبيل الفجر يستغفرون الله من ذنوبهم."},{"id":"4694","s":51,"a":19,"at":"وفي اموالهم حق للسائل والمحروم","dt":"[19] وفي اموالهم حق واجب ومستحب للمحتاجين: الذين يسالون الناس، والذين لا يسالونهم حياء."},{"id":"4695","s":51,"a":20,"at":"وفي الارض ايات للموقنين","dt":"[20] وفي الارض عبر ودلائل واضحه على قدره خالقها لاهل اليقين بان الله هو الاله الحق وحده لا شريك له، والمصدقين لرسوله -صلى الله عليه وسلم-."},{"id":"4696","s":51,"a":21,"at":"وفي انفسكم افلا تبصرون","dt":"[21] وفي خلق انفسكم دلائل على قدره الله تعالى، وعبر تدلكم على وحدانيه خالقكم، وانه لا اله لكم يستحق العباده سواه، اغفلتم عنها، فلا تبصرون ذلك، فتعتبرون به؟"},{"id":"4697","s":51,"a":22,"at":"وفي السماء رزقكم وما توعدون","dt":"[22] وفي السماء رزقكم وما توعدون من الخير والشر والثواب والعقاب، وغير ذلك كله مكتوب مقدر."},{"id":"4698","s":51,"a":23,"at":"فورب السماء والارض انه لحق مثل ما انكم تنطقون","dt":"[23] اقسم الله تعالى بنفسه الكريمه ان ما وعدكم به حق، فلا تشكوا فيه كما لا تشكون في نطقكم."},{"id":"4699","s":51,"a":24,"at":"هل اتاك حديث ضيف ابراهيم المكرمين","dt":"[24] هل اتاك -ايها الرسول- حديث ضيف ابراهيم الذين اكرمهم -وكانوا من الملائكه الكرام-"},{"id":"4700","s":51,"a":25,"at":"اذ دخلوا عليه فقالوا سلاما قال سلام قوم منكرون","dt":"[25] حين دخلوا عليه في بيته، فحيوه قائلين له: سلاما، فرد عليهم التحيه قائلا: سلام عليكم، انتم قوم غرباء لا نعرفكم."},{"id":"4701","s":51,"a":26,"at":"فراغ الى اهله فجاء بعجل سمين","dt":"[26] فعدل ومال خفيه الى اهله، فعمد الى عجل سمين فذبحه، وشواه بالنار،"},{"id":"4702","s":51,"a":27,"at":"فقربه اليهم قال الا تاكلون","dt":"[27] ثم وضعه امامهم، وتلطف في دعوتهم الى الطعام قائلا: الا تاكلون؟"},{"id":"4703","s":51,"a":28,"at":"فاوجس منهم خيفه قالوا لا تخف وبشروه بغلام عليم","dt":"[28] فلما راهم لا ياكلون احس في نفسه خوفا منهم، قالوا له: لا تخف انا رسل الله، وبشروه بان زوجته «ساره» ستلد له ولدا، سيكون من اهل العلم بالله وبدينه، وهو اسحاق عليه السلام."},{"id":"4704","s":51,"a":29,"at":"فاقبلت امراته في صره فصكت وجهها وقالت عجوز عقيم","dt":"[29] فلما سمعت زوجه ابراهيم مقاله هؤلاء الملائكه بالبشاره اقبلت نحوهم في صيحه، فلطمت وجهها تعجبا من هذا الامر، وقالت: كيف الد وانا عجوز عقيم لا الد؟"},{"id":"4705","s":51,"a":30,"at":"قالوا كذلك قال ربك انه هو الحكيم العليم","dt":"[30] قالت لها ملائكه الله: هكذا قال ربك كما اخبرناك، وهو القادر على ذلك، فلا عجب من قدرته. انه سبحانه وتعالى هو الحكيم الذي يضع الاشياء مواضعها، العليم بمصالح عباده."},{"id":"4706","s":51,"a":31,"at":"قال فما خطبكم ايها المرسلون","dt":"[31] قال ابراهيم عليه السلام لملائكه الله: ما شانكم وفيم ارسلتم؟"},{"id":"4707","s":51,"a":32,"at":"قالوا انا ارسلنا الى قوم مجرمين","dt":"[32] قالوا: ان الله ارسلنا الى قوم قد اجرموا لكفرهم بالله؛"},{"id":"4708","s":51,"a":33,"at":"لنرسل عليهم حجاره من طين","dt":"[33] لنهلكهم بحجاره من طين متحجر،"},{"id":"4709","s":51,"a":34,"at":"مسومه عند ربك للمسرفين","dt":"[34] معلمه عند ربك لهؤلاء المتجاوزين الحد في الفجور والعصيان."},{"id":"4710","s":51,"a":35,"at":"فاخرجنا من كان فيها من المؤمنين","dt":"[35] فاخرجنا من كان في قريه قوم لوط من اهل الايمان."},{"id":"4711","s":51,"a":36,"at":"فما وجدنا فيها غير بيت من المسلمين","dt":"[36] فما وجدنا في تلك القريه غير بيت من المسلمين، وهو بيت لوط عليه السلام."},{"id":"4712","s":51,"a":37,"at":"وتركنا فيها ايه للذين يخافون العذاب الاليم","dt":"[37] وتركنا في القريه المذكوره اثرا من العذاب باقيا علامه على قدره الله تعالى وانتقامه من الكفره، وذلك عبره لمن يخافون عذاب الله المؤلم الموجع."},{"id":"4713","s":51,"a":38,"at":"وفي موسى اذ ارسلناه الى فرعون بسلطان مبين","dt":"[38] وفي ارسالنا موسى الى فرعون وملئه بالايات والمعجزات الظاهره ايه للذين يخافون العذاب الاليم."},{"id":"4714","s":51,"a":39,"at":"فتولى بركنه وقال ساحر او مجنون","dt":"[39] فاعرض فرعون مغترا بقوته وجانبه، وقال عن موسى: انه ساحر او مجنون."},{"id":"4715","s":51,"a":40,"at":"فاخذناه وجنوده فنبذناهم في اليم وهو مليم","dt":"[40] فاخذنا فرعون وجنوده، فطرحناهم في البحر، وهو ات ما يلام عليه؛ بسبب كفره وجحوده وفجوره."},{"id":"4716","s":51,"a":41,"at":"وفي عاد اذ ارسلنا عليهم الريح العقيم","dt":"[41] وفي شان عاد واهلاكهم ايات وعبر لمن تامل، اذ ارسلنا عليهم الريح التي لا بركه فيها ولا تاتي بخير،"},{"id":"4717","s":51,"a":42,"at":"ما تذر من شيء اتت عليه الا جعلته كالرميم","dt":"[42] ما تدع شيئا مرت عليه الا صيرته كالشيء البالي."},{"id":"4718","s":51,"a":43,"at":"وفي ثمود اذ قيل لهم تمتعوا حتى حين","dt":"[43] وفي شان ثمود واهلاكهم ايات وعبر، اذ قيل لهم-والقائل نبيهم صالح عليه السلام-: تمتعوا في داركم ثلاثه ايام حتى تنتهي اجالكم."},{"id":"4719","s":51,"a":44,"at":"فعتوا عن امر ربهم فاخذتهم الصاعقه وهم ينظرون","dt":"[44] . فعصوا امر ربهم، فاخذتهم صاعقه العذاب، وهم ينظرون الى عقوبتهم باعينهم."},{"id":"4720","s":51,"a":45,"at":"فما استطاعوا من قيام وما كانوا منتصرين","dt":"[45] فما امكنهم الهرب ولا النهوض مما هم فيه من العذاب، وما كانوا منتصرين لانفسهم."},{"id":"4721","s":51,"a":46,"at":"وقوم نوح من قبل انهم كانوا قوما فاسقين","dt":"[46] واهلكنا قوم نوح من قبل هؤلاء، انهم كانوا قوما مخالفين لامر الله، خارجين عن طاعته."},{"id":"4722","s":51,"a":47,"at":"والسماء بنيناها بايد وانا لموسعون","dt":"[47] والسماء خلقناها واتقناها، وجعلناها سقفا للارض بقوه وقدره عظيمه، وانا لموسعون لارجائها وانحائها."},{"id":"4723","s":51,"a":48,"at":"والارض فرشناها فنعم الماهدون","dt":"[48] والارض جعلناها فراشا للخلق للاستقرار عليها، فنعم الماهدون نحن."},{"id":"4724","s":51,"a":49,"at":"ومن كل شيء خلقنا زوجين لعلكم تذكرون","dt":"[49] ومن كل شيء من اجناس الموجودات خلقنا نوعين مختلفين؛ لكي تتذكروا قدره الله، وتعتبروا."},{"id":"4725","s":51,"a":50,"at":"ففروا الى الله اني لكم منه نذير مبين","dt":"[50] ففروا -ايها الناس- من عقاب الله الى رحمته بالايمان به وبرسوله، واتباع امره والعمل بطاعته، اني لكم نذير بين الانذار. وكان رسول الله -صلى الله عليه وسلم- اذا حزبه امر، فزع الى الصلاه، وهذا فرار الى الله."},{"id":"4726","s":51,"a":51,"at":"ولا تجعلوا مع الله الها اخر اني لكم منه نذير مبين","dt":"[51] ولا تجعلوا مع الله معبودا اخر، اني لكم من الله نذير بين الانذار."},{"id":"4727","s":51,"a":52,"at":"كذلك ما اتى الذين من قبلهم من رسول الا قالوا ساحر او مجنون","dt":"[52] كما كذبت قريش نبيها محمدا -صلى الله عليه وسلم-، وقالوا: هو شاعر او ساحر او مجنون، فعلت الامم المكذبه رسلها من قبل قريش، فاحل الله بهم نقمته."},{"id":"4728","s":51,"a":53,"at":"اتواصوا به بل هم قوم طاغون","dt":"[53] اتواصى الاولون والاخرون بالتكذيب بالرسول حين قالوا ذلك جميعا؟ بل هم قوم طغاه تشابهت قلوبهم واعمالهم بالكفر والطغيان، فقال متاخروهم ذلك، كما قاله متقدموهم."},{"id":"4729","s":51,"a":54,"at":"فتول عنهم فما انت بملوم","dt":"[54] فاعرض -ايها الرسول- عن المشركين حتى ياتيك فيهم امر الله، فما انت بملوم من احد، فقد بلغت ما ارسلت به."},{"id":"4730","s":51,"a":55,"at":"وذكر فان الذكرى تنفع المؤمنين","dt":"[55] ومع اعراضك -ايها الرسول- عنهم، وعدم الالتفات الى تخذيلهم، داوم على الدعوه الى الله، وعلى وعظ من ارسلت اليهم؛ فان التذكير والموعظه ينتفع بهما اهل القلوب المؤمنه، وفيهما اقامه الحجه على المعرضين."},{"id":"4731","s":51,"a":56,"at":"وما خلقت الجن والانس الا ليعبدون","dt":"[56] وما خلقت الجن والانس وبعثت جميع الرسل الا لغايه ساميه، هي عبادتي وحدي دون من سواي."},{"id":"4732","s":51,"a":57,"at":"ما اريد منهم من رزق وما اريد ان يطعمون","dt":"[57] ما اريد منهم من رزق وما اريد ان يطعمون، فانا الرزاق المعطي. فهو سبحانه غير محتاج الى الخلق، بل هم الفقراء اليه في جميع احوالهم، فهو خالقهم ورازقهم والغني عنهم."},{"id":"4733","s":51,"a":58,"at":"ان الله هو الرزاق ذو القوه المتين","dt":"[58] ان الله وحده هو الرزاق لخلقه، المتكفل باقواتهم، ذو القوه المتين، لا يقهر ولا يغالب، فله القدره والقوه كلها."},{"id":"4734","s":51,"a":59,"at":"فان للذين ظلموا ذنوبا مثل ذنوب اصحابهم فلا يستعجلون","dt":"[59] فان للذين ظلموا بتكذيبهم الرسول محمدا -صلى الله عليه وسلم- نصيبا من عذاب الله نازلا بهم مثل نصيب اصحابهم الذين مضوا من قبلهم، فلا يستعجلون بالعذاب، فهو اتيهم لا محاله."},{"id":"4735","s":51,"a":60,"at":"فويل للذين كفروا من يومهم الذي يوعدون","dt":"[60] فهلاك وشقاء للذين كفروا بالله ورسوله من يومهم الذي يوعدون فيه بنزول العذاب بهم، وهو يوم القيامه."},{"id":"4736","s":52,"a":1,"at":"والطور","dt":"[1] اقسم الله بالطور، وهو الجبل الذي كلم الله سبحانه وتعالى موسى عليه،"},{"id":"4737","s":52,"a":2,"at":"وكتاب مسطور","dt":"[2] وبكتاب مكتوب، وهو القران"},{"id":"4738","s":52,"a":3,"at":"في رق منشور","dt":"[3] في صحف منشوره،"},{"id":"4739","s":52,"a":4,"at":"والبيت المعمور","dt":"[4] وبالبيت المعمور في السماء بالملائكه الكرام الذين يطوفون به دائما،"},{"id":"4740","s":52,"a":5,"at":"والسقف المرفوع","dt":"[5] وبالسقف المرفوع وهو السماء الدنيا،"},{"id":"4741","s":52,"a":6,"at":"والبحر المسجور","dt":"[6] وبالبحر المسجور المملوء بالمياه."},{"id":"4742","s":52,"a":7,"at":"ان عذاب ربك لواقع","dt":"[7] ان عذاب ربك -ايها الرسول- بالكفار لواقع،"},{"id":"4743","s":52,"a":8,"at":"ما له من دافع","dt":"[8] ليس له من مانع يمنعه حين وقوعه،"},{"id":"4744","s":52,"a":9,"at":"يوم تمور السماء مورا","dt":"[9] يوم تتحرك السماء فيختل نظامها وتضطرب اجزاؤها، وذلك عند نهايه الحياه الدنيا،"},{"id":"4745","s":52,"a":10,"at":"وتسير الجبال سيرا","dt":"[10] وتزول الجبال عن اماكنها، وتسير كسير السحاب."},{"id":"4746","s":52,"a":11,"at":"فويل يومئذ للمكذبين","dt":"[11] فهلاك في هذا اليوم واقع بالمكذبين"},{"id":"4747","s":52,"a":12,"at":"الذين هم في خوض يلعبون","dt":"[12] الذين هم في خوض بالباطل يلعبون به، ويتخذون دينهم هزوا ولعبا."},{"id":"4748","s":52,"a":13,"at":"يوم يدعون الى نار جهنم دعا","dt":"[13] يوم يدفع هؤلاء المكذبون دفعا بعنف ومهانه الى نار جهنم،"},{"id":"4749","s":52,"a":14,"at":"هذه النار التي كنتم بها تكذبون","dt":"[14] ويقال توبيخا لهم: هذه هي النار التي كنتم بها تكذبون."},{"id":"4750","s":52,"a":15,"at":"افسحر هذا ام انتم لا تبصرون","dt":"[15] افسحر ما تشاهدونه من العذاب ام انتم لا تنظرون؟"},{"id":"4751","s":52,"a":16,"at":"اصلوها فاصبروا او لا تصبروا سواء عليكم انما تجزون ما كنتم تعملون","dt":"[16] ذوقوا حر هذه النار، فاصبروا على المها وشدتها، اولا تصبروا على ذلك، فلن يخفف عنكم العذاب، ولن تخرجوا منها، سواء عليكم صبرتم ام لم تصبروا، انما تجزون ما كنتم تعملون في الدنيا."},{"id":"4752","s":52,"a":17,"at":"ان المتقين في جنات ونعيم","dt":"[17] ان المتقين في جنات ونعيم عظيم،"},{"id":"4753","s":52,"a":18,"at":"فاكهين بما اتاهم ربهم ووقاهم ربهم عذاب الجحيم","dt":"[18] يتفكهون بما اتاهم الله من النعيم من اصناف الملاذ المختلفه، ونجاهم الله من عذاب النار."},{"id":"4754","s":52,"a":19,"at":"كلوا واشربوا هنيئا بما كنتم تعملون","dt":"[19] كلوا طعاما هنيئا، واشربوا شرابا سائغا؛ جزاء بما عملتم من اعمال صالحه في الدنيا."},{"id":"4755","s":52,"a":20,"at":"متكئين على سرر مصفوفه وزوجناهم بحور عين","dt":"[20] وهم متكئون على سرر متقابله، وزوجناهم بنساء بيض واسعات العيون حسانهن."},{"id":"4756","s":52,"a":21,"at":"والذين امنوا واتبعتهم ذريتهم بايمان الحقنا بهم ذريتهم وما التناهم من عملهم من شيء كل امرئ بما كسب رهين","dt":"[21] والذين امنوا واتبعتهم ذريتهم في الايمان، الحقنا بهم ذريتهم في منزلتهم في الجنه، وان لم يبلغوا عمل ابائهم؛ لتقر اعين الاباء بالابناء عندهم في منازلهم، فيجمع بينهم على احسن الاحوال، وما نقصناهم شيئا من ثواب اعمالهم. كل انسان مرهون بعمله، لا يحمل ذنب غيره من الناس."},{"id":"4757","s":52,"a":22,"at":"وامددناهم بفاكهه ولحم مما يشتهون","dt":"[22] وزدناهم على ما ذكر من النعيم فواكه ولحوما مما يستطاب ويشتهى،"},{"id":"4758","s":52,"a":23,"at":"يتنازعون فيها كاسا لا لغو فيها ولا تاثيم","dt":"[23] ومن هذا النعيم انهم يتعاطون في الجنه كاسا من الخمر، يناول احدهم صاحبه؛ ليتم بذلك سرورهم، وهذا الشراب مخالف لخمر الدنيا، فلا يزول به عقل صاحبه، ولا يحصل بسببه لغو، ولا كلام فيه اثم او معصيه."},{"id":"4759","s":52,"a":24,"at":"ويطوف عليهم غلمان لهم كانهم لؤلؤ مكنون","dt":"[24] ويطوف عليهم غلمان معدون لخدمتهم، كانهم في الصفاء والبياض والتناسق لؤلؤ مصون في اصدافه."},{"id":"4760","s":52,"a":25,"at":"واقبل بعضهم على بعض يتساءلون","dt":"[25] واقبل اهل الجنه يسال بعضهم بعضا عن عظيم ما هم فيه وسببه،"},{"id":"4761","s":52,"a":26,"at":"قالوا انا كنا قبل في اهلنا مشفقين","dt":"[26] قالوا: انا كنا قبل في الدنيا -ونحن بين اهلينا- خائفين ربنا، مشفقين من عذابه وعقابه يوم القيامه."},{"id":"4762","s":52,"a":27,"at":"فمن الله علينا ووقانا عذاب السموم","dt":"[27] فمن الله علينا بالهدايه والتوفيق، ووقانا عذاب سموم جهنم، وهو نارها وحرارتها."},{"id":"4763","s":52,"a":28,"at":"انا كنا من قبل ندعوه انه هو البر الرحيم","dt":"[28] انا كنا من قبل نضرع اليه وحده لا نشرك معه غيره ان يقينا عذاب السموم ويوصلنا الى النعيم، فاستجاب لنا واعطانا سؤالنا، انه هو البر الرحيم. فمن بره ورحمته ايانا انالنا رضاه والجنه، ووقانا من سخطه والنار."},{"id":"4764","s":52,"a":29,"at":"فذكر فما انت بنعمه ربك بكاهن ولا مجنون","dt":"[29] فذكر -ايها الرسول- من ارسلت اليهم بالقران، فما انت بانعام الله عليك بالنبوه ورجاحه العقل بكاهن يخبر بالغيب دون علم، ولا مجنون لا يعقل ما يقول كما يدعون."},{"id":"4765","s":52,"a":30,"at":"ام يقولون شاعر نتربص به ريب المنون","dt":"[30] ام يقول المشركون لك -ايها الرسول-: هو شاعر ننتظر به نزول الموت؟"},{"id":"4766","s":52,"a":31,"at":"قل تربصوا فاني معكم من المتربصين","dt":"[31] قل لهم: انتظروا موتي فاني معكم من المنتظرين بكم العذاب، وسترون لمن تكون العاقبه."},{"id":"4767","s":52,"a":32,"at":"ام تامرهم احلامهم بهذا ام هم قوم طاغون","dt":"[32] بل اتامر هؤلاء المكذبين عقولهم بهذا القول المتناقض؟ ذلك ان صفات الكهانه والشعر والجنون لا يمكن اجتماعها في ان واحد، بل هم قوم متجاوزون الحد في الطغيان."},{"id":"4768","s":52,"a":33,"at":"ام يقولون تقوله بل لا يؤمنون","dt":"[33] بل ايقول هؤلاء المشركون: اختلق محمد القران من تلقاء نفسه؟ بل هم لا يؤمنون، فلو امنوا لم يقولوا ما قالوه."},{"id":"4769","s":52,"a":34,"at":"فلياتوا بحديث مثله ان كانوا صادقين","dt":"[34] فلياتوا بكلام مثل القران، ان كانوا صادقين -في زعمهم- ان محمدا اختلقه."},{"id":"4770","s":52,"a":35,"at":"ام خلقوا من غير شيء ام هم الخالقون","dt":"[35] اخلق هؤلاء المشركون من غير خالق لهم وموجد، ام هم الخالقون لانفسهم؟ وكلا الامرين باطل ومستحيل. وبهذا يتعين ان الله سبحانه هو الذي خلقهم، وهو وحده الذي يستحق العباده ولا تصلح الا له."},{"id":"4771","s":52,"a":36,"at":"ام خلقوا السموات والارض بل لا يوقنون","dt":"[36] ام خلقوا السموات والارض على هذا الصنع البديع؟ بل هم لا يوقنون بعذاب الله، فهم مشركون."},{"id":"4772","s":52,"a":37,"at":"ام عندهم خزائن ربك ام هم المصيطرون","dt":"[37] ام عندهم خزائن ربك يتصرفون فيها، ام هم الجبارون المتسلطون على خلق الله بالقهر والغلبه؟ ليس الامر كذلك، بل هم العاجزون الضعفاء."},{"id":"4773","s":52,"a":38,"at":"ام لهم سلم يستمعون فيه فليات مستمعهم بسلطان مبين","dt":"[38] ام لهم مصعد الى السماء يستمعون فيه الوحي بان الذي هم عليه حق؟ فليات من يزعم انه استمع ذلك بحجه بينه تصدق دعواه."},{"id":"4774","s":52,"a":39,"at":"ام له البنات ولكم البنون","dt":"[39] الله سبحانه البنات ولكم البنون كما تزعمون افتراء وكذبا؟"},{"id":"4775","s":52,"a":40,"at":"ام تسالهم اجرا فهم من مغرم مثقلون","dt":"[40] بل اتسال -ايها الرسول- هؤلاء المشركين اجرا على تبليغ الرساله، فهم في جهد ومشقه من التزام غرامه تطلبها منهم؟"},{"id":"4776","s":52,"a":41,"at":"ام عندهم الغيب فهم يكتبون","dt":"[41] ام عندهم علم الغيب فهم يكتبونه للناس ويخبرونهم به؟ ليس الامر كذلك؛ فانه لا يعلم الغيب في السموات والارض الا الله."},{"id":"4777","s":52,"a":42,"at":"ام يريدون كيدا فالذين كفروا هم المكيدون","dt":"[42] بل يريدون برسول الله وبالمؤمنين مكرا، فالذين كفروا يرجع كيدهم ومكرهم على انفسهم."},{"id":"4778","s":52,"a":43,"at":"ام لهم اله غير الله سبحان الله عما يشركون","dt":"[43] ام لهم معبود يستحق العباده غير الله؟ تنزه وتعالى عما يشركون، فليس له شريك في الملك، ولا شريك في الوحدانيه والعباده."},{"id":"4779","s":52,"a":44,"at":"وان يروا كسفا من السماء ساقطا يقولوا سحاب مركوم","dt":"[44] وان ير هؤلاء المشركون قطعا من السماء ساقطا عليهم عذابا لهم لم ينتقلوا عما هم عليه من التكذيب، ولقالوا: هذا سحاب متراكم بعضه فوق بعض."},{"id":"4780","s":52,"a":45,"at":"فذرهم حتى يلاقوا يومهم الذي فيه يصعقون","dt":"[45] فدع -ايها الرسول- هؤلاء المشركين حتى يلاقوا يومهم الذي فيه يهلكون، وهو يوم القيامه."},{"id":"4781","s":52,"a":46,"at":"يوم لا يغني عنهم كيدهم شيئا ولا هم ينصرون","dt":"[46] وفي ذلك اليوم لا يدفع عنهم كيدهم من عذاب الله شيئا، ولا ينصرهم ناصر من عذاب الله."},{"id":"4782","s":52,"a":47,"at":"وان للذين ظلموا عذابا دون ذلك ولكن اكثرهم لا يعلمون","dt":"[47] وان لهؤلاء الظلمه عذابا يلقونه في الدنيا قبل عذاب يوم القيامه من القتل والسبي وعذاب البرزخ وغير ذلك، ولكن اكثرهم لا يعلمون ذلك."},{"id":"4783","s":52,"a":48,"at":"واصبر لحكم ربك فانك باعيننا وسبح بحمد ربك حين تقوم","dt":"[48] واصبر -ايها الرسول- لحكم ربك وامره فيما حملك من الرساله، وعلى ما يلحقك من اذى قومك، فانك بمراى منا وحفظ واعتناء، وسبح بحمد ربك حين تقوم الى الصلاه، وحين تقوم من نومك،"},{"id":"4784","s":52,"a":49,"at":"ومن الليل فسبحه وادبار النجوم","dt":"[49] ومن الليل فسبح بحمد ربك وعظمه، وصل له، وافعل ذلك عند صلاه الصبح وقت ادبار النجوم.وفي هذه الايه اثبات لصفه العينين لله تعالى بما يليق به، دون تشبيه بخلقه او تكييف لذاته، سبحانه وبحمده، كما ثبت ذلك بالسنه، واجمع عليه سلف الامه، واللفظ ورد هنا بصيغه الجمع للتعظيم."},{"id":"4785","s":53,"a":1,"at":"والنجم اذا هوى","dt":"[1] اقسم الله تعالى بالنجوم اذا غابت،"},{"id":"4786","s":53,"a":2,"at":"ما ضل صاحبكم وما غوى","dt":"[2] ما حاد محمد -صلى الله عليه وسلم- عن طريق الهدايه والحق، وما خرج عن الرشاد، بل هو في غايه الاستقامه والاعتدال والسداد،"},{"id":"4787","s":53,"a":3,"at":"وما ينطق عن الهوى","dt":"[3] وليس نطقه صادرا عن هوى نفسه."},{"id":"4788","s":53,"a":4,"at":"ان هو الا وحي يوحى","dt":"[4] ما القران وما السنه الا وحي من الله الى نبيه محمد -صلى الله عليه وسلم-."},{"id":"4789","s":53,"a":5,"at":"علمه شديد القوى","dt":"[5] علم محمدا -صلى الله عليه وسلم- ملك شديد القوه،"},{"id":"4790","s":53,"a":6,"at":"ذو مره فاستوى","dt":"[6] ذو منظر حسن، وهو جبريل عليه السلام"},{"id":"4791","s":53,"a":7,"at":"وهو بالافق الاعلى","dt":"[7] ، الذي ظهر واستوى على صورته الحقيقيه للرسول -صلى الله عليه وسلم- في الافق الاعلى، وهو افق الشمس عند مطلعها"},{"id":"4792","s":53,"a":8,"at":"ثم دنا فتدلى","dt":"[8] ثم دنا جبريل من الرسول -صلى الله عليه وسلم-، فزاد في القرب،"},{"id":"4793","s":53,"a":9,"at":"فكان قاب قوسين او ادنى","dt":"[9] فكان دنوه مقدار قوسين او اقرب من ذلك."},{"id":"4794","s":53,"a":10,"at":"فاوحى الى عبده ما اوحى","dt":"[10] فاوحى الله سبحانه وتعالى الى عبده محمد -صلى الله عليه وسلم- ما اوحى بواسطه جبريل عليه السلام."},{"id":"4795","s":53,"a":11,"at":"ما كذب الفؤاد ما راى","dt":"[11] ما كذب قلب محمد -صلى الله عليه وسلم- ما راه بصره."},{"id":"4796","s":53,"a":12,"at":"افتمارونه على ما يرى","dt":"[12] اتكذبون محمدا -صلى الله عليه وسلم-، فتجادلونه على ما يراه ويشاهده من ايات ربه؟"},{"id":"4797","s":53,"a":13,"at":"ولقد راه نزله اخرى","dt":"[13] ولقد راى محمد -صلى الله عليه وسلم- جبريل على صورته الحقيقيه التي خلقه الله عليها مره اخرى"},{"id":"4798","s":53,"a":14,"at":"عند سدره المنتهى","dt":"[14] عند سدره المنتهى -شجره نبق- وهي في السماء السابعه، ينتهي اليها ما يعرج به من الارض، وينتهي اليها ما يهبط به من فوقها"},{"id":"4799","s":53,"a":15,"at":"عندها جنه الماوى","dt":"[15] عندها جنه الماوى التي وعد بها المتقون."},{"id":"4800","s":53,"a":16,"at":"اذ يغشى السدره ما يغشى","dt":"[16] اذ يغشى السدره من امر الله شيء عظيم، لا يعلم وصفه الا الله عز وجل."},{"id":"4801","s":53,"a":17,"at":"ما زاغ البصر وما طغى","dt":"[17] وكان النبي -صلى الله عليه وسلم- على صفه عظيمه من الثبات والطاعه، فما مال بصره يمينا ولا شمالا، ولا جاوز ما امر برؤيته."},{"id":"4802","s":53,"a":18,"at":"لقد راى من ايات ربه الكبرى","dt":"[18] لقد راى محمد -صلى الله عليه وسلم- ليله المعراج من ايات ربه الكبرى الداله على قدره الله وعظمته من الجنه والنار وغير ذلك."},{"id":"4803","s":53,"a":19,"at":"افرايتم اللات والعزى","dt":"[19] افرايتم -ايها المشركون- هذه الالهه التي تعبدونها: اللات والعزى"},{"id":"4804","s":53,"a":20,"at":"ومناه الثالثه الاخرى","dt":"[20] ومناه الثالثه الاخرى، هل نفعت او ضرت حتى تكون شركاء لله؟"},{"id":"4805","s":53,"a":21,"at":"الكم الذكر وله الانثى","dt":"[21] اتجعلون لكم الذكر الذي ترضونه، وتجعلون لله بزعمكم الانثى التي لا ترضونها لانفسكم؟"},{"id":"4806","s":53,"a":22,"at":"تلك اذا قسمه ضيزى","dt":"[22] تلك اذا قسمه جائره."},{"id":"4807","s":53,"a":23,"at":"ان هي الا اسماء سميتموها انتم واباؤكم ما انزل الله بها من سلطان ان يتبعون الا الظن وما تهوى الانفس ولقد جاءهم من ربهم الهدى","dt":"[23] ما هذه الاوثان الا اسماء ليس لها من اوصاف الكمال شيء، انما هي اسماء سميتموها انتم واباؤكم بمقتضى اهوائكم الباطله، ما انزل الله بها من حجه تصدق دعواكم فيها. ما يتبع هؤلاء المشركون الا الظن، وهوى انفسهم المنحرفه عن الفطره السليمه، ولقد جاءهم من ربهم على لسان النبي -صلى الله عليه وسلم- ما فيه هدايتهم، فما انتفعوا به."},{"id":"4808","s":53,"a":24,"at":"ام للانسان ما تمنى","dt":"[24] ليس للانسان ما تمناه من شفاعه هذه المعبودات او غيرها مما تهواه نفسه،"},{"id":"4809","s":53,"a":25,"at":"فلله الاخره والاولى","dt":"[25] فلله امر الدنيا والاخره."},{"id":"4810","s":53,"a":26,"at":"وكم من ملك في السموات لا تغني شفاعتهم شيئا الا من بعد ان ياذن الله لمن يشاء ويرضى","dt":"[26] وكثير من الملائكه في السموات مع علو منزلتهم، لا تنفع شفاعتهم شيئا الا من بعد ان ياذن الله لهم بالشفاعه، ويرضى عن المشفوع له."},{"id":"4811","s":53,"a":27,"at":"ان الذين لا يؤمنون بالاخره ليسمون الملائكه تسميه الانثى","dt":"[27] ان الذين لا يصدقون بالحياه الاخره من كفار العرب ولا يعملون لها ليسمون الملائكه تسميه الاناث؛ لاعتقادهم جهلا ان الملائكه اناث، وانهم بنات الله."},{"id":"4812","s":53,"a":28,"at":"وما لهم به من علم ان يتبعون الا الظن وان الظن لا يغني من الحق شيئا","dt":"[28] وما لهم بذلك من علم صحيح يصدق ما قالوه، ما يتبعون الا الظن الذي لا يجدي شيئا، ولا يقوم ابدا مقام الحق."},{"id":"4813","s":53,"a":29,"at":"فاعرض عن من تولى عن ذكرنا ولم يرد الا الحياه الدنيا","dt":"[29] فاعرض عمن تولى عن ذكرنا، وهو القران، ولم يرد الا الحياه الدنيا."},{"id":"4814","s":53,"a":30,"at":"ذلك مبلغهم من العلم ان ربك هو اعلم بمن ضل عن سبيله وهو اعلم بمن اهتدى","dt":"[30] ذلك الذي هم عليه هو منتهى علمهم وغايتهم. ان ربك هو اعلم بمن حاد عن طريق الهدى، وهو اعلم بمن اهتدى وسلك طريق الاسلام.وفي هذا انذار شديد للعصاه المعرضين عن العمل بكتاب الله، وسنه رسوله -صلى الله عليه وسلم-، المؤثرين لهوى النفس وحظوظ الدنيا على الاخره."},{"id":"4815","s":53,"a":31,"at":"ولله ما في السموات وما في الارض ليجزي الذين اساءوا بما عملوا ويجزي الذين احسنوا بالحسنى","dt":"[31] ولله سبحانه وتعالى ملك ما في السموات وما في الارض؛ ليجزي الذين اساؤوا بعقابهم على ما عملوا من السوء، ويجزي الذي احسنوا بالجنه،"},{"id":"4816","s":53,"a":32,"at":"الذين يجتنبون كبائر الاثم والفواحش الا اللمم ان ربك واسع المغفره هو اعلم بكم اذ انشاكم من الارض واذ انتم اجنه في بطون امهاتكم فلا تزكوا انفسكم هو اعلم بمن اتقى","dt":"[32] وهم الذين يبتعدون عن كبائر الذنوب والفواحش الا اللمم، وهي الذنوب الصغار التي لا يصر صاحبها عليها، او يلم بها العبد على وجه الندره، فان هذه مع الاتيان بالواجبات وترك المحرمات، يغفرها الله لهم ويسترها عليهم، ان ربك واسع المغفره، هو اعلم باحوالكم حين خلق اباكم ادم من تراب، وحين انتم اجنه في بطون امهاتكم، فلا تزكوا انفسكم فتمدحوها وتصفوها بالتقوى، هو اعلم بمن اتقى عقابه من عباده فاجتنب معاصيه."},{"id":"4817","s":53,"a":33,"at":"افرايت الذي تولى","dt":"[33] افرايت -ايها الرسول- الذي اعرض عن طاعه الله"},{"id":"4818","s":53,"a":34,"at":"واعطى قليلا واكدى","dt":"[34] واعطى قليلا من ماله، ثم توقف عن العطاء وقطع معروفه؟"},{"id":"4819","s":53,"a":35,"at":"اعنده علم الغيب فهو يرى","dt":"[35] اعند هذا الذي قطع عطاءه علم الغيب انه سينفد ما في يده حتى امسك معروفه، فهو يرى ذلك عيانا؟ ليس الامر كذلك، وانما امسك عن الصدقه والمعروف والبر والصله؛ بخلا وشحا."},{"id":"4820","s":53,"a":36,"at":"ام لم ينبا بما في صحف موسى","dt":"[36] ام لم يخبر بما جاء في اسفار التوراه"},{"id":"4821","s":53,"a":37,"at":"وابراهيم الذي وفى","dt":"[37] وصحف ابراهيم الذي وفى ما امر به وبلغه؟"},{"id":"4822","s":53,"a":38,"at":"الا تزر وازره وزر اخرى","dt":"[38] انه لا تؤخذ نفس بماثم غيرها، ووزرها لا يحمله عنها احد،"},{"id":"4823","s":53,"a":39,"at":"وان ليس للانسان الا ما سعى","dt":"[39] وانه لا يحصل للانسان من الاجر الا ما كسب هو لنفسه بسعيه."},{"id":"4824","s":53,"a":40,"at":"وان سعيه سوف يرى","dt":"[40] وان سعيه سوف يرى في الاخره، فيميز حسنه من سيئه؛ تشريفا للمحسن وتوبيخا للمسيء."},{"id":"4825","s":53,"a":41,"at":"ثم يجزاه الجزاء الاوفى","dt":"[41] ثم يجزى الانسان على سعيه الجزاء المستكمل لجميع عمله،"},{"id":"4826","s":53,"a":42,"at":"وان الى ربك المنتهى","dt":"[42] وان الى ربك -ايها الرسول- انتهاء جميع خلقه يوم القيامه."},{"id":"4827","s":53,"a":43,"at":"وانه هو اضحك وابكى","dt":"[43] وانه سبحانه وتعالى اضحك من شاء في الدنيا بان سره، وابكى من شاء بان غمه."},{"id":"4828","s":53,"a":44,"at":"وانه هو امات واحيا","dt":"[44] وانه سبحانه امات من اراد موته من خلقه، واحيا من اراد حياته منهم، فهو المتفرد سبحانه بالاحياء والاماته."},{"id":"4829","s":53,"a":45,"at":"وانه خلق الزوجين الذكر والانثى","dt":"[45] وانه خلق الزوجين: الذكر والانثى من الانسان والحيوان،"},{"id":"4830","s":53,"a":46,"at":"من نطفه اذا تمنى","dt":"[46] من نطفه تصب في الرحم."},{"id":"4831","s":53,"a":47,"at":"وان عليه النشاه الاخرى","dt":"[47] وان على ربك -ايها الرسول- اعاده خلقهم بعد مماتهم، وهي النشاه الاخرى يوم القيامه."},{"id":"4832","s":53,"a":48,"at":"وانه هو اغنى واقنى","dt":"[48] وانه هو اغنى من شاء من خلقه بالمال، وملكه لهم وارضاهم به."},{"id":"4833","s":53,"a":49,"at":"وانه هو رب الشعرى","dt":"[49] وانه سبحانه وتعالى هو رب الشعرى، وهو نجم مضيء، كان بعض اهل الجاهليه يعبدونه من دون الله."},{"id":"4834","s":53,"a":50,"at":"وانه اهلك عادا الاولى","dt":"[50] وانه سبحانه وتعالى اهلك عادا الاولى، وهم قوم هود،"},{"id":"4835","s":53,"a":51,"at":"وثمود فما ابقى","dt":"[51] واهلك ثمود، وهم قوم صالح، فلم يبق منهم احدا،"},{"id":"4836","s":53,"a":52,"at":"وقوم نوح من قبل انهم كانوا هم اظلم واطغى","dt":"[52] واهلك قوم نوح قبل. هؤلاء كانوا اشد تمردا واعظم كفرا من الذين جاؤوا من بعدهم."},{"id":"4837","s":53,"a":53,"at":"والمؤتفكه اهوى","dt":"[53] ومدائن قوم لوط قلبها الله عليهم، وجعل عاليها سافلها،"},{"id":"4838","s":53,"a":54,"at":"فغشاها ما غشى","dt":"[54] فالبسها ما البسها من الحجاره المتتابعه النازله عليهم من السماء كالمطر."},{"id":"4839","s":53,"a":55,"at":"فباي الاء ربك تتمارى","dt":"[55] فباي نعم ربك عليك -ايها الانسان المكذب- تشك؟"},{"id":"4840","s":53,"a":56,"at":"هذا نذير من النذر الاولى","dt":"[56] هذا محمد -صلى الله عليه وسلم-، نذير بالحق الذي انذر به الانبياء قبله، فليس ببدع من الرسل."},{"id":"4841","s":53,"a":57,"at":"ازفت الازفه","dt":"[57] قربت القيامه ودنا وقتها،"},{"id":"4842","s":53,"a":58,"at":"ليس لها من دون الله كاشفه","dt":"[58] لا يدفعها اذا من دون الله احد، ولا يطلع على وقت وقوعها الا الله."},{"id":"4843","s":53,"a":59,"at":"افمن هذا الحديث تعجبون","dt":"[59] افمن هذا القران تعجبون -ايها المشركون- من ان يكون صحيحا،"},{"id":"4844","s":53,"a":60,"at":"وتضحكون ولا تبكون","dt":"[60] وتضحكون منه سخريه واستهزاء، ولا تبكون خوفا من وعيده،"},{"id":"4845","s":53,"a":61,"at":"وانتم سامدون","dt":"[61] وانتم لاهون معرضون عنه؟"},{"id":"4846","s":53,"a":62,"at":"فاسجدوا لله واعبدوا","dt":"[62] فاسجدوا لله واخلصوا العباده له ,وحده وسلموا له اموركم."},{"id":"4847","s":54,"a":1,"at":"اقتربت الساعه وانشق القمر","dt":"[1] دنت القيامه، وانفلق القمر فلقتين، حين سال كفار «مكه» النبي -صلى الله عليه وسلم- ان يريهم ايه، فدعا الله، فاراهم تلك الايه."},{"id":"4848","s":54,"a":2,"at":"وان يروا ايه يعرضوا ويقولوا سحر مستمر","dt":"[2] وان ير المشركون دليلا وبرهانا على صدق الرسول محمد -صلى الله عليه وسلم-، يعرضوا عن الايمان به وتصديقه مكذبين منكرين، ويقولوا بعد ظهور الدليل: هذا سحر باطل ذاهب مضمحل لا دوام له."},{"id":"4849","s":54,"a":3,"at":"وكذبوا واتبعوا اهواءهم وكل امر مستقر","dt":"[3] وكذبوا النبي -صلى الله عليه وسلم-، واتبعوا ضلالتهم وما دعتهم اليه اهواؤهم من التكذيب، وكل امر من خير او شر واقع باهله يوم القيامه عند ظهور الثواب والعقاب."},{"id":"4850","s":54,"a":4,"at":"ولقد جاءهم من الانباء ما فيه مزدجر","dt":"[4]ولقد جاء كفار قريش من انباء الامم المكذبه برسلها، وما حل بها من العذاب، ما فيه كفايه لردعهم عن كفرهم وضلالهم."},{"id":"4851","s":54,"a":5,"at":"حكمه بالغه فما تغن النذر","dt":"[5] هذا القران الذي جاءهم حكمه عظيمه بالغه غايتها، فاي شيء تغني النذر عن قوم اعرضوا وكذبوا بها؟"},{"id":"4852","s":54,"a":6,"at":"فتول عنهم يوم يدع الداع الى شيء نكر","dt":"[6] فاعرض -ايها الرسول- عنهم، وانتظر بهم يوما عظيما. يوم يدعو الملك بنفخه في «القرن» الى امر فظيع منكر، وهو موقف الحساب."},{"id":"4853","s":54,"a":7,"at":"خشعا ابصارهم يخرجون من الاجداث كانهم جراد منتشر","dt":"[7] ذليله ابصارهم يخرجون من القبور كانهم في انتشارهم وسرعه سيرهم للحساب جراد منتشر في الافاق،"},{"id":"4854","s":54,"a":8,"at":"مهطعين الى الداع يقول الكافرون هذا يوم عسر","dt":"[8] مسرعين الى ما دعوا اليه، يقول الكافرون: هذا يوم عسر شديد الهول."},{"id":"4855","s":54,"a":9,"at":"كذبت قبلهم قوم نوح فكذبوا عبدنا وقالوا مجنون وازدجر","dt":"[9] كذبت قبل قومك -ايها الرسول- قوم نوح فكذبوا عبدنا نوحا، وقالوا: هو مجنون، وانتهروه متوعدين اياه بانواع الاذى، ان لم ينته عن دعوته."},{"id":"4856","s":54,"a":10,"at":"فدعا ربه اني مغلوب فانتصر","dt":"[10] فدعا نوح ربه اني ضعيف عن مقاومه هؤلاء، فانتصر لي بعقاب من عندك على كفرهم بك."},{"id":"4857","s":54,"a":11,"at":"ففتحنا ابواب السماء بماء منهمر","dt":"[11] فاجبنا دعاءه، ففتحنا ابواب السماء بماء كثير متدفق،"},{"id":"4858","s":54,"a":12,"at":"وفجرنا الارض عيونا فالتقى الماء على امر قد قدر","dt":"[12] وشققنا الارض عيونا متفجره بالماء، فالتقى ماء السماء وماء الارض على اهلاكهم الذي قدره الله لهم؛ جزاء شركهم."},{"id":"4859","s":54,"a":13,"at":"وحملناه على ذات الواح ودسر","dt":"[13] وحملنا نوحا ومن معه على سفينه ذات الواح ومسامير شدت بها،"},{"id":"4860","s":54,"a":14,"at":"تجري باعيننا جزاء لمن كان كفر","dt":"[14] تجري بمراى منا وحفظ، واغرقنا المكذبين؛ جزاء لهم على كفرهم وانتصارا لنوح عليه السلام.وفي هذه الايه دليل على اثبات صفه العينين لله سبحانه وتعالى، كما يليق به."},{"id":"4861","s":54,"a":15,"at":"ولقد تركناها ايه فهل من مدكر","dt":"[15] ولقد ابقينا قصه نوح مع قومه عبره ودليلا على قدرتنا لمن بعد نوح؛ ليعتبروا ويتعظوا بما حل بهذه الامه التي كفرت بربها، فهل من متعظ يتعظ؟"},{"id":"4862","s":54,"a":16,"at":"فكيف كان عذابي ونذر","dt":"[16] فكيف كان عذابي ونذري لمن كفر بي وكذب رسلي، ولم يتعظ بما جاءت به؟ انه كان عظيما مؤلما."},{"id":"4863","s":54,"a":17,"at":"ولقد يسرنا القران للذكر فهل من مدكر","dt":"[17] ولقد سهلنا لفظ القران للتلاوه والحفظ، ومعانيه للفهم والتدبر، لمن اراد ان يتذكر ويعتبر، فهل من متعظ به؟وفي هذه الايه وما ناظرها من السوره حث على الاستكثار من تلاوه القران وتعلمه وتعليمه."},{"id":"4864","s":54,"a":18,"at":"كذبت عاد فكيف كان عذابي ونذر","dt":"[18] كذبت عاد هودا فعاقبناهم، فكيف كان عذابي لهم على كفرهم، ونذري على تكذيب رسولهم، وعدم الايمان به؟ انه كان عظيما مؤلما."},{"id":"4865","s":54,"a":19,"at":"انا ارسلنا عليهم ريحا صرصرا في يوم نحس مستمر","dt":"[19] انا ارسلنا عليهم ريحا شديده البرد، في يوم شؤم مستمر عليهم بالعذاب والهلاك،"},{"id":"4866","s":54,"a":20,"at":"تنزع الناس كانهم اعجاز نخل منقعر","dt":"[20] تقتلع الناس من مواضعهم على الارض، فترمي بهم على رؤوسهم فتدق اعناقهم، وتفصل رؤوسهم عن اجسادهم، فتتركهم كالنخل المنقلع من اصله."},{"id":"4867","s":54,"a":21,"at":"فكيف كان عذابي ونذر","dt":"[21] فكيف كان عذابي ونذري لمن كفر بي، وكذب رسلي ولم يؤمن بهم؟ انه كان عظيما مؤلما."},{"id":"4868","s":54,"a":22,"at":"ولقد يسرنا القران للذكر فهل من مدكر","dt":"[22] ولقد سهلنا لفظ القران للتلاوه والحفظ، ومعانيه للفهم والتدبر، لمن اراد ان يتذكر ويعتبر، فهل من متعظ به؟"},{"id":"4869","s":54,"a":23,"at":"كذبت ثمود بالنذر","dt":"[23] كذبت ثمود -وهم قوم صالح- بالايات التي انذروا بها،"},{"id":"4870","s":54,"a":24,"at":"فقالوا ابشرا منا واحدا نتبعه انا اذا لفي ضلال وسعر","dt":"[24] فقالوا: ابشرا منا واحدا نتبعه نحن الجماعه الكثيره وهو واحد؟ انا اذا لفي بعد عن الصواب وجنون."},{"id":"4871","s":54,"a":25,"at":"اؤلقي الذكر عليه من بيننا بل هو كذاب اشر","dt":"[25] اانزل عليه الوحي وخص بالنبوه من بيننا، وهو واحد منا؟ بل هو كثير الكذب والتجبر."},{"id":"4872","s":54,"a":26,"at":"سيعلمون غدا من الكذاب الاشر","dt":"[26] سيرون عند نزول العذاب بهم في الدنيا ويوم القيامه من الكذاب المتجبر؟"},{"id":"4873","s":54,"a":27,"at":"انا مرسلوا الناقه فتنه لهم فارتقبهم واصطبر","dt":"[27] انا مخرجو الناقه التي سالوها من الصخره؛ اختبارا لهم، فانتظر -يا صالح- ما يحل بهم من العذاب، واصطبر على دعوتك اياهم واذاهم لك."},{"id":"4874","s":54,"a":28,"at":"ونبئهم ان الماء قسمه بينهم كل شرب محتضر","dt":"[28] واخبرهم ان الماء مقسوم بين قومك والناقه: للناقه يوم، ولهم يوم، كل شرب يحضره من كانت قسمته، ويحظر على من ليس بقسمه له."},{"id":"4875","s":54,"a":29,"at":"فنادوا صاحبهم فتعاطى فعقر","dt":"[29] فنادوا صاحبهم بالحض على عقرها، فتناول الناقه بيده، فنحرها فعاقبتهم،"},{"id":"4876","s":54,"a":30,"at":"فكيف كان عذابي ونذر","dt":"[30] فكيف كان عقابي لهم على كفرهم، وانذاري لمن عصى رسلي؟ انه كان عظيما مؤلما."},{"id":"4877","s":54,"a":31,"at":"انا ارسلنا عليهم صيحه واحده فكانوا كهشيم المحتظر","dt":"[31] انا ارسلنا عليهم جبريل، فصاح بهم صيحه واحده، فبادوا عن اخرهم، فكانوا كالزرع اليابس السريع الانكسار الذي يجعله صاحب الحظيره سياجا لحفظ المواشي."},{"id":"4878","s":54,"a":32,"at":"ولقد يسرنا القران للذكر فهل من مدكر","dt":"[32] ولقد سهلنا لفظ القران للتلاوه والحفظ، ومعانيه للفهم والتدبر لمن اراد ان يتذكر ويعتبر، فهل من متعظ به؟"},{"id":"4879","s":54,"a":33,"at":"كذبت قوم لوط بالنذر","dt":"[33] كذبت قوم لوط بايات الله التي انذروا بها."},{"id":"4880","s":54,"a":34,"at":"انا ارسلنا عليهم حاصبا الا ال لوط نجيناهم بسحر","dt":"[34] انا ارسلنا عليهم ريحا شديده ترميهم بالحجاره الا ال لوط، نجيناهم من العذاب في اخر الليل،"},{"id":"4881","s":54,"a":35,"at":"نعمه من عندنا كذلك نجزي من شكر","dt":"[35] نعمه من عندنا عليهم، كما اثبنا لوطا واله وانعمنا عليهم، فانجيناهم من عذابنا، نثيب من امن بنا وشكرنا."},{"id":"4882","s":54,"a":36,"at":"ولقد انذرهم بطشتنا فتماروا بالنذر","dt":"[36] ولقد خوف لوط قومه باس الله وعذابه، فلم يسمعوا له، بل شكوا في ذلك، وكذبوه."},{"id":"4883","s":54,"a":37,"at":"ولقد راودوه عن ضيفه فطمسنا اعينهم فذوقوا عذابي ونذر","dt":"[37] ولقد طلبوا منه ان يفعلوا الفاحشه بضيوفه من الملائكه، فطمسنا اعينهم فلم يبصروا شيئا، فقيل لهم: ذوقوا عذابي ونتيجه انذاري الذي انذركم به لوط عليه السلام."},{"id":"4884","s":54,"a":38,"at":"ولقد صبحهم بكره عذاب مستقر","dt":"[38] ولقد جاءهم وقت الصباح عذاب دائم استقر فيهم حتى يفضي بهم الى عذاب الاخره، وذلك العذاب هو رجمهم بالحجاره وقلب قراهم وجعل اعلاها اسفلها،"},{"id":"4885","s":54,"a":39,"at":"فذوقوا عذابي ونذر","dt":"[39] فقيل لهم: ذوقوا عذابي الذي انزلته بكم؛ لكفركم وتكذيبكم، ونتيجه انذاري الذي انذركم به لوط عليه السلام."},{"id":"4886","s":54,"a":40,"at":"ولقد يسرنا القران للذكر فهل من مدكر","dt":"[40] ولقد سهلنا لفظ القران للتلاوه والحفظ، ومعانيه للفهم والتدبر لمن اراد ان يتذكر، فهل من متعظ به؟"},{"id":"4887","s":54,"a":41,"at":"ولقد جاء ال فرعون النذر","dt":"[41] ولقد جاء اتباع فرعون وقومه انذارنا بالعقوبه لهم على كفرهم."},{"id":"4888","s":54,"a":42,"at":"كذبوا باياتنا كلها فاخذناهم اخذ عزيز مقتدر","dt":"[42] كذبوا بادلتنا كلها الداله على وحدانيتنا ونبوه انبيائنا، فعاقبناهم بالعذاب عقوبه عزيز لا يغالب، مقتدر على ما يشاء."},{"id":"4889","s":54,"a":43,"at":"اكفاركم خير من اولئكم ام لكم براءه في الزبر","dt":"[43] اكفاركم -يا معشر قريش- خير من الذين تقدم ذكرهم ممن هلكوا بسبب تكذيبهم، ام لكم براءه من عقاب الله في الكتب المنزله على الانبياء بالسلامه من العقوبه؟"},{"id":"4890","s":54,"a":44,"at":"ام يقولون نحن جميع منتصر","dt":"[44] بل ايقول كفار «مكه»: نحن اولو حزم وراي وامرنا مجتمع، فنحن جماعه منتصره لا يغلبنا من ارادنا بسوء؟"},{"id":"4891","s":54,"a":45,"at":"سيهزم الجمع ويولون الدبر","dt":"[45] سيهزم جمع كفار «مكه» امام المؤمنين، ويولون الادبار، وقد حدث هذا يوم «بدر»."},{"id":"4892","s":54,"a":46,"at":"بل الساعه موعدهم والساعه ادهى وامر","dt":"[46] والساعه موعدهم الذي يجازون فيه بما يستحقون، والساعه اعظم واقسى مما لحقهم من العذاب يوم «بدر»."},{"id":"4893","s":54,"a":47,"at":"ان المجرمين في ضلال وسعر","dt":"[47] ان المجرمين في تيه عن الحق وعناء وعذاب."},{"id":"4894","s":54,"a":48,"at":"يوم يسحبون في النار على وجوههم ذوقوا مس سقر","dt":"[48] يوم يجرون في النار على وجوههم، ويقال لهم: ذوقوا شده عذاب جهنم."},{"id":"4895","s":54,"a":49,"at":"انا كل شيء خلقناه بقدر","dt":"[49] انا كل شيء خلقناه بمقدار قدرناه وقضيناه، وسبق علمنا به، وكتابتنا له في اللوح المحفوظ."},{"id":"4896","s":54,"a":50,"at":"وما امرنا الا واحده كلمح بالبصر","dt":"[50] وما امرنا للشيء اذا اردناه الا ان نقول قوله واحده وهي «كن»، فيكون كلمح البصر، لا يتاخر طرفه عين."},{"id":"4897","s":54,"a":51,"at":"ولقد اهلكنا اشياعكم فهل من مدكر","dt":"[51] ولقد اهلكنا اشباهكم في الكفر من الامم الخاليه، فهل من متعظ بما حل بهم من النكال والعذاب؟"},{"id":"4898","s":54,"a":52,"at":"وكل شيء فعلوه في الزبر","dt":"[52] وكل شيء فعله اشباهكم الماضون من خير او شر مكتوب في الكتب التي كتبتها الحفظه."},{"id":"4899","s":54,"a":53,"at":"وكل صغير وكبير مستطر","dt":"[53] وكل صغير وكبير من اعمالهم مسطر في صحائفهم، وسيجازون به."},{"id":"4900","s":54,"a":54,"at":"ان المتقين في جنات ونهر","dt":"[54] ان المتقين في بساتين عظيمه، وانهار واسعه يوم القيامه."},{"id":"4901","s":54,"a":55,"at":"في مقعد صدق عند مليك مقتدر","dt":"[55] في مجلس حق، لا لغو فيه ولا تاثيم عند الله الملك العظيم، الخالق للاشياء كلها، المقتدر على كل شيء تبارك وتعالى."},{"id":"4902","s":55,"a":1,"at":"الرحمن","dt":"[1] الرحمن"},{"id":"4903","s":55,"a":2,"at":"علم القران","dt":"[2] علم الانسان القران؛ بتيسير تلاوته وحفظه وفهم معانيه."},{"id":"4904","s":55,"a":3,"at":"خلق الانسان","dt":"[3] خلق الانسان"},{"id":"4905","s":55,"a":4,"at":"علمه البيان","dt":"[4] علمه البيان عما في نفسه تمييزا له عن غيره."},{"id":"4906","s":55,"a":5,"at":"الشمس والقمر بحسبان","dt":"[5] الشمس والقمر يجريان متعاقبين بحساب متقن، لا يختلف ولا يضطرب."},{"id":"4907","s":55,"a":6,"at":"والنجم والشجر يسجدان","dt":"[6] والنجوم التي في السماء او النبات الذي ينجم ويطلع من الارض ولا ساق له، واشجار الارض التي لها ساق، تعرف ربها وتسجد له، وتنقاد لما سخرها له من مصالح عباده ومنافعهم."},{"id":"4908","s":55,"a":7,"at":"والسماء رفعها ووضع الميزان","dt":"[7] والسماء رفعها فوق الارض، ووضع في الارض العدل الذي امر به وشرعه لعباده."},{"id":"4909","s":55,"a":8,"at":"الا تطغوا في الميزان","dt":"[8] لئلا تعتدوا وتخونوا من وزنتم له،"},{"id":"4910","s":55,"a":9,"at":"واقيموا الوزن بالقسط ولا تخسروا الميزان","dt":"[9] واقيموا الوزن بالعدل، ولا تنقصوا الميزان اذا وزنتم للناس."},{"id":"4911","s":55,"a":10,"at":"والارض وضعها للانام","dt":"[10] والارض وضعها ومهدها؛ ليستقر عليها الخلق."},{"id":"4912","s":55,"a":11,"at":"فيها فاكهه والنخل ذات الاكمام","dt":"[11] فيها فاكهه والنخل ذات الاوعيه التي يكون منها الثمر،"},{"id":"4913","s":55,"a":12,"at":"والحب ذو العصف والريحان","dt":"[12] وفيها الحب ذو القشر؛ رزقا لكم ولانعامكم، وفيها كل نبت طيب الرائحه."},{"id":"4914","s":55,"a":13,"at":"فباي الاء ربكما تكذبان","dt":"[13] فباي نعم ربكما الدينيه والدنيويه -يا معشر الجن والانس- تكذبان؟ وما احسن جواب الجن حين تلا عليهم النبي -صلى الله عليه وسلم- هذه السوره، فكلما مر بهذه الايه، قالوا: «ولا بشيء من الائك ربنا نكذب، فلك الحمد»، وهكذا ينبغي للعبد اذا تليت عليه نعم الله والاؤه، ان يقر بها، ويشكر الله ويحمده عليها."},{"id":"4915","s":55,"a":14,"at":"خلق الانسان من صلصال كالفخار","dt":"[14] خلق ابا الانسان، وهو ادم من طين يابس كالفخار،"},{"id":"4916","s":55,"a":15,"at":"وخلق الجان من مارج من نار","dt":"[15] وخلق ابليس، وهو من الجن من لهب النار المختلط بعضه ببعض."},{"id":"4917","s":55,"a":16,"at":"فباي الاء ربكما تكذبان","dt":"[16] فباي نعم ربكما -يا معشر الانس والجن- تكذبان؟"},{"id":"4918","s":55,"a":17,"at":"رب المشرقين ورب المغربين","dt":"[17] هو سبحانه وتعالى رب مشرقي الشمس في الشتاء والصيف، ورب مغربيها فيهما، فالجميع تحت تدبيره وربوبيته."},{"id":"4919","s":55,"a":18,"at":"فباي الاء ربكما تكذبان","dt":"[18] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4920","s":55,"a":19,"at":"مرج البحرين يلتقيان","dt":"[19] خلط الله ماء البحرين -العذب والملح- متلاقيين، لا فاصل بينهما في مراى العين،"},{"id":"4921","s":55,"a":20,"at":"بينهما برزخ لا يبغيان","dt":"[20] ومع ذلك بينهما حاجز، فلا يطغى احدهما على الاخر، ويذهب بخصائصه، بل يبقى العذب عذبا، والملح ملحا مع تلاقيهما."},{"id":"4922","s":55,"a":21,"at":"فباي الاء ربكما تكذبان","dt":"[21] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4923","s":55,"a":22,"at":"يخرج منهما اللؤلؤ والمرجان","dt":"[22] يخرج من البحرين بقدره الله اللؤلؤ والمرجان."},{"id":"4924","s":55,"a":23,"at":"فباي الاء ربكما تكذبان","dt":"[23] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4925","s":55,"a":24,"at":"وله الجوار المنشات في البحر كالاعلام","dt":"[24] وله تعالى ملك تسخير السفن الضخمه التي تجري في البحر بمنافع الناس، رافعه سواريها واشرعتها كالجبال."},{"id":"4926","s":55,"a":25,"at":"فباي الاء ربكما تكذبان","dt":"[25] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4927","s":55,"a":26,"at":"كل من عليها فان","dt":"[26] كل من على وجه الارض من الخلق هالك،"},{"id":"4928","s":55,"a":27,"at":"ويبقى وجه ربك ذو الجلال والاكرام","dt":"[27] ويبقى وجه ربك ذو العظمه والكبرياء والفضل والجود. وفي الايه اثبات صفه الوجه لله تعالى بما يليق به سبحانه، دون تشبيه ولا تكييف."},{"id":"4929","s":55,"a":28,"at":"فباي الاء ربكما تكذبان","dt":"[28] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4930","s":55,"a":29,"at":"يساله من في السموات والارض كل يوم هو في شان","dt":"[29] يساله من في السموات والارض حاجاتهم، فلا غنى لاحد منهم عنه سبحانه. كل يوم هو في شان: يعز ويذل، ويعطي ويمنع"},{"id":"4931","s":55,"a":30,"at":"فباي الاء ربكما تكذبان","dt":"[30] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4932","s":55,"a":31,"at":"سنفرغ لكم ايها الثقلان","dt":"[31] سنغرغ لحسابكم ومجازاتكم باعمالكم التي عملتموها في الدنيا، ايها الثقلان -الانس والجن- فنعاقب اهل المعاصي، ونثيب اهل الطاعه."},{"id":"4933","s":55,"a":32,"at":"فباي الاء ربكما تكذبان","dt":"[32] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4934","s":55,"a":33,"at":"يامعشر الجن والانس ان استطعتم ان تنفذوا من اقطار السموات والارض فانفذوا لا تنفذون الا بسلطان","dt":"[33] يا معشر الجن والانس، ان قدرتم على النفاذ من امر الله وحكمه هاربين من اطراف السموات والارض فافعلوا، ولستم قادرين على ذلك الا بقوه وحجه، وامر من الله تعالى، وانى لكم ذلك، وانتم لا تملكون لانفسكم نفعا ولا ضرا؟"},{"id":"4935","s":55,"a":34,"at":"فباي الاء ربكما تكذبان","dt":"[34] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4936","s":55,"a":35,"at":"يرسل عليكما شواظ من نار ونحاس فلا تنتصران","dt":"[35] يرسل عليكم لهب من نار، ونحاس مذاب يصب على رؤوسكم، فلا ينصر بعضكم بعضا يا معشر الجن والانس."},{"id":"4937","s":55,"a":36,"at":"فباي الاء ربكما تكذبان","dt":"[36] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4938","s":55,"a":37,"at":"فاذا انشقت السماء فكانت ورده كالدهان","dt":"[37] فاذا انشقت السماء وتفطرت يوم القيامه، فكانت حمراء كلون الورد، وكالزيت المغلي والرصاص المذاب؛ من شده الامر وهول يوم القيامه."},{"id":"4939","s":55,"a":38,"at":"فباي الاء ربكما تكذبان","dt":"[38] . فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4940","s":55,"a":39,"at":"فيومئذ لا يسال عن ذنبه انس ولا جان","dt":"[39] ففي ذلك اليوم لا تسال الملائكه المجرمين من الانس والجن عن ذنوبهم."},{"id":"4941","s":55,"a":40,"at":"فباي الاء ربكما تكذبان","dt":"[40] . فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4942","s":55,"a":41,"at":"يعرف المجرمون بسيماهم فيؤخذ بالنواصي والاقدام","dt":"[41] تعرف الملائكه المجرمين بعلاماتهم، فتاخذهم بمقدمه رؤوسهم وباقدامهم، فترميهم في النار."},{"id":"4943","s":55,"a":42,"at":"فباي الاء ربكما تكذبان","dt":"[42] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4944","s":55,"a":43,"at":"هذه جهنم التي يكذب بها المجرمون","dt":"[43] يقال لهؤلاء المجرمين -توبيخا وتحقيرا لهم-: هذه جهنم التي يكذب بها المجرمون في الدنيا"},{"id":"4945","s":55,"a":44,"at":"يطوفون بينها وبين حميم ان","dt":"[44] تاره يعذبون في الجحيم، وتاره يسقون من الحميم، وهو شراب بلغ منتهى الحراره، يقطع الامعاء والاحشاء."},{"id":"4946","s":55,"a":45,"at":"فباي الاء ربكما تكذبان","dt":"[45] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4947","s":55,"a":46,"at":"ولمن خاف مقام ربه جنتان","dt":"[46] ولمن اتقى الله من عباده من الانس والجن، فخاف مقامه بين يديه، فاطاعه وترك معاصيه، جنتان."},{"id":"4948","s":55,"a":47,"at":"فباي الاء ربكما تكذبان","dt":"[47] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4949","s":55,"a":48,"at":"ذواتا افنان","dt":"[48] الجنتان ذواتا اغصان نضره من الفواكه والثمار."},{"id":"4950","s":55,"a":49,"at":"فباي الاء ربكما تكذبان","dt":"[49] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4951","s":55,"a":50,"at":"فيهما عينان تجريان","dt":"[50] في هاتين الجنتين عينان من الماء تجريان خلالهما."},{"id":"4952","s":55,"a":51,"at":"فباي الاء ربكما تكذبان","dt":"[51] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4953","s":55,"a":52,"at":"فيهما من كل فاكهه زوجان","dt":"[52] في هاتين الجنتين من كل نوع من الفواكه صنفان."},{"id":"4954","s":55,"a":53,"at":"فباي الاء ربكما تكذبان","dt":"[53] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4955","s":55,"a":54,"at":"متكئين على فرش بطائنها من استبرق وجنى الجنتين دان","dt":"[54] وللذين خافوا مقام ربهم جنتان يتنعمون فيهما، متكئين على فرش مبطنه من غليظ الديباج، وثمر الجنتين قريب اليهم."},{"id":"4956","s":55,"a":55,"at":"فباي الاء ربكما تكذبان","dt":"[55] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4957","s":55,"a":56,"at":"فيهن قاصرات الطرف لم يطمثهن انس قبلهم ولا جان","dt":"[56] في هذه الفرش زوجات قاصرات ابصارهن على ازواجهن، لا ينظرن الى غيرهم متعلقات بهم، لم يطاهن انس قبلهم ولا جان."},{"id":"4958","s":55,"a":57,"at":"فباي الاء ربكما تكذبان","dt":"[57] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4959","s":55,"a":58,"at":"كانهن الياقوت والمرجان","dt":"[58] كان هؤلاء الزوجات من الحور الياقوت والمرجان في صفائهن وجمالهن."},{"id":"4960","s":55,"a":59,"at":"فباي الاء ربكما تكذبان","dt":"[59] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4961","s":55,"a":60,"at":"هل جزاء الاحسان الا الاحسان","dt":"[60] هل جزاء من احسن بعمله في الدنيا الا الاحسان اليه بالجنه في الاخره؟"},{"id":"4962","s":55,"a":61,"at":"فباي الاء ربكما تكذبان","dt":"[61] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4963","s":55,"a":62,"at":"ومن دونهما جنتان","dt":"[62] ومن دون الجنتين السابقتين جنتان اخريان."},{"id":"4964","s":55,"a":63,"at":"فباي الاء ربكما تكذبان","dt":"[63] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4965","s":55,"a":64,"at":"مدهامتان","dt":"[64] هاتان الجنتان خضراوان، قد اشتدت خضرتهما حتى مالت الى السواد."},{"id":"4966","s":55,"a":65,"at":"فباي الاء ربكما تكذبان","dt":"[65] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4967","s":55,"a":66,"at":"فيهما عينان نضاختان","dt":"[66] فيهما عينان فوارتان بالماء لا تنقطعان."},{"id":"4968","s":55,"a":67,"at":"فباي الاء ربكما تكذبان","dt":"[67] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4969","s":55,"a":68,"at":"فيهما فاكهه ونخل ورمان","dt":"[68] في هاتين الجنتين انواع الفواكه ونخل ورمان."},{"id":"4970","s":55,"a":69,"at":"فباي الاء ربكما تكذبان","dt":"[69] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4971","s":55,"a":70,"at":"فيهن خيرات حسان","dt":"[70] في هذه الجنان الاربع زوجات طيبات الاخلاق حسان الوجوه."},{"id":"4972","s":55,"a":71,"at":"فباي الاء ربكما تكذبان","dt":"[71] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4973","s":55,"a":72,"at":"حور مقصورات في الخيام","dt":"[72] حور مستورات مصونات في الخيام."},{"id":"4974","s":55,"a":73,"at":"فباي الاء ربكما تكذبان","dt":"[73] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4975","s":55,"a":74,"at":"لم يطمثهن انس قبلهم ولا جان","dt":"[74] لم يطا هؤلاء الحور انس قبل ازواجهن ولا جان."},{"id":"4976","s":55,"a":75,"at":"فباي الاء ربكما تكذبان","dt":"[75] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4977","s":55,"a":76,"at":"متكئين على رفرف خضر وعبقري حسان","dt":"[76] متكئين على وسائد ذوات اغطيه خضر، وفرش بديعه فائقه الصنع في غايه الحسن."},{"id":"4978","s":55,"a":77,"at":"فباي الاء ربكما تكذبان","dt":"[77] فباي نعم ربكما -ايها الثقلان- تكذبان؟"},{"id":"4979","s":55,"a":78,"at":"تبارك اسم ربك ذي الجلال والاكرام","dt":"[78] تكاثرت بركه اسم ربك وكثر خيره، ذي الجلال الباهر، والمجد الكامل، والاكرام لاوليائه."},{"id":"4980","s":56,"a":1,"at":"اذا وقعت الواقعه","dt":"[1] اذا قامت القيامه،"},{"id":"4981","s":56,"a":2,"at":"ليس لوقعتها كاذبه","dt":"[2] ليس لقيامها احد يكذب به،"},{"id":"4982","s":56,"a":3,"at":"خافضه رافعه","dt":"[3] هي خافضه لاعداء الله في النار، رافعه لاوليائه في الجنه."},{"id":"4983","s":56,"a":4,"at":"اذا رجت الارض رجا","dt":"[4] اذا حركت الارض تحريكا شديدا،"},{"id":"4984","s":56,"a":5,"at":"وبست الجبال بسا","dt":"[5] وفتتت الجبال تفتيتا دقيقا،"},{"id":"4985","s":56,"a":6,"at":"فكانت هباء منبثا","dt":"[6] فصارت غبارا متطايرا في الجو قد ذرته الريح."},{"id":"4986","s":56,"a":7,"at":"وكنتم ازواجا ثلاثه","dt":"[7] وكنتم -ايها الخلق- اصنافا ثلاثه:"},{"id":"4987","s":56,"a":8,"at":"فاصحاب الميمنه ما اصحاب الميمنه","dt":"[8] فاصحاب اليمين اهل المنزله العاليه، ما اعظم مكانتهم!"},{"id":"4988","s":56,"a":9,"at":"واصحاب المشامه ما اصحاب المشامه","dt":"[9] واصحاب الشمال اهل المنزله الدنيئه، ما اسوا حالهم!"},{"id":"4989","s":56,"a":10,"at":"والسابقون السابقون","dt":"[10] والسابقون الى الخيرات في الدنيا هم السابقون الى الدرجات في الاخره،"},{"id":"4990","s":56,"a":11,"at":"اولئك المقربون","dt":"[11] اولئك هم المقربون عند الله،"},{"id":"4991","s":56,"a":12,"at":"في جنات النعيم","dt":"[12] يدخلهم ربهم في جنات النعيم."},{"id":"4992","s":56,"a":13,"at":"ثله من الاولين","dt":"[13] يدخلها جماعه كثيره من صدر هذه الامه، وغيرهم من الامم الاخرى،"},{"id":"4993","s":56,"a":14,"at":"وقليل من الاخرين","dt":"[14] وقليل من اخر هذه الامه"},{"id":"4994","s":56,"a":15,"at":"على سرر موضونه","dt":"[15] على سرر منسوجه بالذهب،"},{"id":"4995","s":56,"a":16,"at":"متكئين عليها متقابلين","dt":"[16] متكئين عليها يقابل بعضهم بعضا."},{"id":"4996","s":56,"a":17,"at":"يطوف عليهم ولدان مخلدون","dt":"[17] يطوف عليهم لخدمتهم غلمان لا يهرمون ولا يموتون،"},{"id":"4997","s":56,"a":18,"at":"باكواب واباريق وكاس من معين","dt":"[18] باقداح واباريق وكاس من عين خمر جاريه في الجنه،"},{"id":"4998","s":56,"a":19,"at":"لا يصدعون عنها ولا ينزفون","dt":"[19] لا تصدع منها رؤوسهم، ولا تذهب بعقولهم."},{"id":"4999","s":56,"a":20,"at":"وفاكهه مما يتخيرون","dt":"[20] ويطوف عليهم الغلمان بما يتخيرون من الفواكه،"},{"id":"5000","s":56,"a":21,"at":"ولحم طير مما يشتهون","dt":"[21] وبلحم طير مما ترغب فيه نفوسهم."},{"id":"5001","s":56,"a":22,"at":"وحور عين","dt":"[22] ولهم نساء ذوات عيون واسعه،"},{"id":"5002","s":56,"a":23,"at":"كامثال اللؤلؤ المكنون","dt":"[23] كامثال اللؤلؤ المصون في اصدافه صفاء وجمالا؛"},{"id":"5003","s":56,"a":24,"at":"جزاء بما كانوا يعملون","dt":"[24] جزاء لهم بما كانوا يعملون من الصالحات في الدنيا."},{"id":"5004","s":56,"a":25,"at":"لا يسمعون فيها لغوا ولا تاثيما","dt":"[25] لا يسمعون في الجنه باطلا، ولا ما يتاثمون بسماعه،"},{"id":"5005","s":56,"a":26,"at":"الا قيلا سلاما سلاما","dt":"[26] الا قولا سالما من هذه العيوب، وتسليم بعضهم على بعض."},{"id":"5006","s":56,"a":27,"at":"واصحاب اليمين ما اصحاب اليمين","dt":"[27] واصحاب اليمين، ما اعظم مكانتهم وجزاءهم!"},{"id":"5007","s":56,"a":28,"at":"في سدر مخضود","dt":"[28] هم في سدر لا شوك فيه،"},{"id":"5008","s":56,"a":29,"at":"وطلح منضود","dt":"[29] وموز متراكب بعضه على بعض،"},{"id":"5009","s":56,"a":30,"at":"وظل ممدود","dt":"[30] وظل دائم لا يزول،"},{"id":"5010","s":56,"a":31,"at":"وماء مسكوب","dt":"[31] وماء جار لا ينقطع،"},{"id":"5011","s":56,"a":32,"at":"وفاكهه كثيره","dt":"[32] ، وفاكهه كثيره لا تنفد"},{"id":"5012","s":56,"a":33,"at":"لا مقطوعه ولا ممنوعه","dt":"[33] ولا تنقطع عنهم، ولا يمنعهم منها مانع،"},{"id":"5013","s":56,"a":34,"at":"وفرش مرفوعه","dt":"[34] وفرش مرفوعه على السرر."},{"id":"5014","s":56,"a":35,"at":"انا انشاناهن انشاء","dt":"[35] انا انشانا نساء اهل الجنه نشاه غير النشاه التي كانت في الدنيا، نشاه كامله لا تقبل الفناء،"},{"id":"5015","s":56,"a":36,"at":"فجعلناهن ابكارا","dt":"[36] فجعلناهن ابكارا،"},{"id":"5016","s":56,"a":37,"at":"عربا اترابا","dt":"[37] متحببات الى ازواجهن، في سن واحده،"},{"id":"5017","s":56,"a":38,"at":"لاصحاب اليمين","dt":"[38] خلقناهن لاصحاب اليمين."},{"id":"5018","s":56,"a":39,"at":"ثله من الاولين","dt":"[39] وهم جماعه كثيره من الاولين،"},{"id":"5019","s":56,"a":40,"at":"وثله من الاخرين","dt":"[40] وجماعه كثيره من الاخرين."},{"id":"5020","s":56,"a":41,"at":"واصحاب الشمال ما اصحاب الشمال","dt":"[41] واصحاب الشمال ما اسوا حالهم وجزاءهم!"},{"id":"5021","s":56,"a":42,"at":"في سموم وحميم","dt":"[42] في ريح حاره من حر نار جهنم تاخذ بانفاسهم، وماء حار يغلي،"},{"id":"5022","s":56,"a":43,"at":"وظل من يحموم","dt":"[43] وظل من دخان شديد السواد،"},{"id":"5023","s":56,"a":44,"at":"لا بارد ولا كريم","dt":"[44] لا بارد المنزل، ولا كريم المنظر."},{"id":"5024","s":56,"a":45,"at":"انهم كانوا قبل ذلك مترفين","dt":"[45] انهم كانوا في الدنيا متنعمين بالحرام، معرضين عما جاءتهم به الرسل."},{"id":"5025","s":56,"a":46,"at":"وكانوا يصرون على الحنث العظيم","dt":"[46] وكانوا يقيمون على الكفر بالله والاشراك به ومعصيته، ولا ينوون التوبه من ذلك."},{"id":"5026","s":56,"a":47,"at":"وكانوا يقولون ائذا متنا وكنا ترابا وعظاما ائنا لمبعوثون","dt":"[47] وكانوا يقولون انكارا للبعث: انبعث اذا متنا وصرنا ترابا وعظاما باليه؟ وهذا استبعاد منهم لامر البعث وتكذيب له."},{"id":"5027","s":56,"a":48,"at":"او اباؤنا الاولون","dt":"[48] انبعث نحن واباؤنا الاقدمون الذين صاروا ترابا، قد تفرق في الارض؟"},{"id":"5028","s":56,"a":49,"at":"قل ان الاولين والاخرين","dt":"[49] قل لهم -ايها الرسول-: ان الاولين والاخرين من بني ادم"},{"id":"5029","s":56,"a":50,"at":"لمجموعون الى ميقات يوم معلوم","dt":"[50] سيجمعون في يوم مؤقت بوقت محدد، وهو يوم القيامه."},{"id":"5030","s":56,"a":51,"at":"ثم انكم ايها الضالون المكذبون","dt":"[51] ثم انكم ايها الضالون عن طريق الهدى المكذبون بوعيد الله ووعده،"},{"id":"5031","s":56,"a":52,"at":"لاكلون من شجر من زقوم","dt":"[52] لاكلون من شجر من زقوم، وهو من اقبح الشجر،"},{"id":"5032","s":56,"a":53,"at":"فمالئون منها البطون","dt":"[53] فمالئون منها بطونكم؛ لشده الجوع،"},{"id":"5033","s":56,"a":54,"at":"فشاربون عليه من الحميم","dt":"[54] فشاربون عليه ماء متناهيا في الحراره لا يروي ظما،"},{"id":"5034","s":56,"a":55,"at":"فشاربون شرب الهيم","dt":"[55] فشاربون منه بكثره، كشرب الابل العطاش التي لا تروى لداء يصيبها."},{"id":"5035","s":56,"a":56,"at":"هذا نزلهم يوم الدين","dt":"[56] هذا الذي يلقونه من العذاب هو ما اعد لهم من الزاد يوم القيامه. وفي هذا توبيخ لهم وتهكم بهم."},{"id":"5036","s":56,"a":57,"at":"نحن خلقناكم فلولا تصدقون","dt":"[57] نحن خلقناكم -ايها الناس- ولم تكونوا شيئا، فهلا تصدقون بالبعث."},{"id":"5037","s":56,"a":58,"at":"افرايتم ما تمنون","dt":"[58] افرايتم النطف التي تقذفونها في ارحام نسائكم،"},{"id":"5038","s":56,"a":59,"at":"اانتم تخلقونه ام نحن الخالقون","dt":"[59] هل انتم تخلقون ذلك بشرا ام نحن الخالقون؟"},{"id":"5039","s":56,"a":60,"at":"نحن قدرنا بينكم الموت وما نحن بمسبوقين","dt":"[60] نحن قدرنا بينكم الموت، وما نحن بعاجزين"},{"id":"5040","s":56,"a":61,"at":"على ان نبدل امثالكم وننشئكم في ما لا تعلمون","dt":"[61] عن ان نغير خلقكم يوم القيامه، وننشئكم فيما لا تعلمونه من الصفات والاحوال."},{"id":"5041","s":56,"a":62,"at":"ولقد علمتم النشاه الاولى فلولا تذكرون","dt":"[62] ولقد علمتم ان الله انشاكم النشاه الاولى ولم تكونوا شيئا، فهلا تذكرون قدره الله على انشائكم مره اخرى."},{"id":"5042","s":56,"a":63,"at":"افرايتم ما تحرثون","dt":"[63] افرايتم الحرث الذي تحرثونه"},{"id":"5043","s":56,"a":64,"at":"اانتم تزرعونه ام نحن الزارعون","dt":"[64] هل انتم تنبتونه في الارض ام نحن نقر قراره وننبته في الارض؟"},{"id":"5044","s":56,"a":65,"at":"لو نشاء لجعلناه حطاما فظلتم تفكهون","dt":"[65] لو نشاء لجعلنا ذلك الزرع هشيما، لا ينتفع به في مطعم، فاصبحتم تتعجبون مما نزل بزرعكم،"},{"id":"5045","s":56,"a":66,"at":"انا لمغرمون","dt":"[66] وتقولون: انا لخاسرون معذبون،"},{"id":"5046","s":56,"a":67,"at":"بل نحن محرومون","dt":"[67] بل نحن محرومون من الرزق."},{"id":"5047","s":56,"a":68,"at":"افرايتم الماء الذي تشربون","dt":"[68] افرايتم الماء الذي تشربونه لتحيوا به،"},{"id":"5048","s":56,"a":69,"at":"اانتم انزلتموه من المزن ام نحن المنزلون","dt":"[69] اانتم انزلتموه من السحاب الى قرار الارض، ام نحن الذين انزلناه رحمه بكم؟"},{"id":"5049","s":56,"a":70,"at":"لو نشاء جعلناه اجاجا فلولا تشكرون","dt":"[70] لو نشاء جعلنا هذا الماء شديد الملوحه، لا ينتفع به في شرب ولا زرع، فهلا تشكرون ربكم على انزاله الماء العذب لنفعكم."},{"id":"5050","s":56,"a":71,"at":"افرايتم النار التي تورون","dt":"[71] افرايتم النار التي توقدون،"},{"id":"5051","s":56,"a":72,"at":"اانتم انشاتم شجرتها ام نحن المنشئون","dt":"[72] اانتم اوجدتم شجرتها التي تقدح منها النار، ام نحن الموجدون لها؟"},{"id":"5052","s":56,"a":73,"at":"نحن جعلناها تذكره ومتاعا للمقوين","dt":"[73] نحن جعلنا ناركم التي توقدون تذكيرا لكم بنار جهنم ومنفعه للمسافرين."},{"id":"5053","s":56,"a":74,"at":"فسبح باسم ربك العظيم","dt":"[74] فنزه -ايها النبي- ربك العظيم الكامل الاسماء والصفات، الكثير الاحسان والخيرات."},{"id":"5054","s":56,"a":75,"at":"فلا اقسم بمواقع النجوم","dt":"[75] اقسم الله تعالى بمساقط النجوم في مغاربها في السماء،"},{"id":"5055","s":56,"a":76,"at":"وانه لقسم لو تعلمون عظيم","dt":"[76] وانه لقسم لو تعلمون قدره عظيم."},{"id":"5056","s":56,"a":77,"at":"انه لقران كريم","dt":"[77] ان هذا القران الذي نزل على محمد -صلى الله عليه وسلم- لقران عظيم المنافع، كثير الخير، غزير العلم،"},{"id":"5057","s":56,"a":78,"at":"في كتاب مكنون","dt":"[78] في كتاب مصون مستور عن اعين الخلق، وهو اللوح المحفوظ."},{"id":"5058","s":56,"a":79,"at":"لا يمسه الا المطهرون","dt":"[79] . لا يمس القران الا الملائكه الكرام الذين طهرهم الله من الافات والذنوب، ولا يمسه ايضا الا المتطهرون من الشرك والجنابه والحدث."},{"id":"5059","s":56,"a":80,"at":"تنزيل من رب العالمين","dt":"[80] وهذا القران الكريم منزل من رب العالمين، فهو الحق الذي لا مريه فيه."},{"id":"5060","s":56,"a":81,"at":"افبهذا الحديث انتم مدهنون","dt":"[81] افبهذا القران انتم -ايها المشركون- مكذبون؟"},{"id":"5061","s":56,"a":82,"at":"وتجعلون رزقكم انكم تكذبون","dt":"[82] وتجعلون شكركم لنعم الله عليكم انكم تكذبون بها وتكفرون؟وفي هذا انكار على من يتهاون بامر القران ولا يبالي بدعوته."},{"id":"5062","s":56,"a":83,"at":"فلولا اذا بلغت الحلقوم","dt":"[83] فهل تستطيعون اذا بلغت نفس احدكم الحلقوم عند النزع،"},{"id":"5063","s":56,"a":84,"at":"وانتم حينئذ تنظرون","dt":"[84] وانتم حضور تنظرون اليه، ان تمسكوا روحه في جسده؟ لن تستطيعوا ذلك،"},{"id":"5064","s":56,"a":85,"at":"ونحن اقرب اليه منكم ولكن لا تبصرون","dt":"[85] ونحن اقرب اليه منكم بملائكتنا، ولكنكم لا ترونهم."},{"id":"5065","s":56,"a":86,"at":"فلولا ان كنتم غير مدينين","dt":"[86] وهل تستطيعون ان كنتم غير محاسبين ولا مجزيين باعمالكم"},{"id":"5066","s":56,"a":87,"at":"ترجعونها ان كنتم صادقين","dt":"[87] ان تعيدوا الروح الى الجسد، ان كنتم صادقين؟ لن ترجعوها."},{"id":"5067","s":56,"a":88,"at":"فاما ان كان من المقربين","dt":"[88] فاما ان كان الميت من السابقين المقربين،"},{"id":"5068","s":56,"a":89,"at":"فروح وريحان وجنه نعيم","dt":"[89] فله عند موته الرحمه الواسعه والفرح وما تطيب به نفسه، وله جنه النعيم في الاخره."},{"id":"5069","s":56,"a":90,"at":"واما ان كان من اصحاب اليمين","dt":"[90] واما ان كان الميت من اصحاب اليمين،"},{"id":"5070","s":56,"a":91,"at":"فسلام لك من اصحاب اليمين","dt":"[91] فيقال له: سلامه لك وامن؛ لكونك من اصحاب اليمين."},{"id":"5071","s":56,"a":92,"at":"واما ان كان من المكذبين الضالين","dt":"[92] واما ان كان الميت من المكذبين بالبعث، الضالين عن الهدى،"},{"id":"5072","s":56,"a":93,"at":"فنزل من حميم","dt":"[93] فله ضيافه من شراب جهنم المغلي المتناهي الحراره"},{"id":"5073","s":56,"a":94,"at":"وتصليه جحيم","dt":"[94] والنار يحرق بها، ويقاسي عذابها الشديد"},{"id":"5074","s":56,"a":95,"at":"ان هذا لهو حق اليقين","dt":"[95] ان هذا الذي قصصناه عليك -ايها الرسول- لهو حق اليقين الذي لا مريه فيه،"},{"id":"5075","s":56,"a":96,"at":"فسبح باسم ربك العظيم","dt":"[96] فسبح باسم ربك العظيم، ونزهه عما يقول الظالمون والجاحدون، تعالى الله عما يقولون علوا كبيرا."},{"id":"5076","s":57,"a":1,"at":"سبح لله ما في السموات والارض وهو العزيز الحكيم","dt":"[1] نزه الله عن السوء كل ما في السموات والارض من جميع مخلوقاته، وهو العزيز على خلقه، الحكيم في تدبير امورهم."},{"id":"5077","s":57,"a":2,"at":"له ملك السموات والارض يحيي ويميت وهو على كل شيء قدير","dt":"[2] له ملك السموات والارض وما فيهما، فهو المالك المتصرف في خلقه، يحيي ويميت، وهو على كل شيء قدير، لا يتعذر عليه شيء اراده، فما شاءه كان، وما لم يشا لم يكن."},{"id":"5078","s":57,"a":3,"at":"هو الاول والاخر والظاهر والباطن وهو بكل شيء عليم","dt":"[3] هو الاول الذي ليس قبله شيء، والاخر الذي ليس بعده شيء، والظاهر الذي ليس فوقه شيء، والباطن الذي ليس دونه شيء، ولا تخفى عليه خافيه في الارض ولا في السماء، وهو بكل شيء عليم."},{"id":"5079","s":57,"a":4,"at":"هو الذي خلق السموات والارض في سته ايام ثم استوى على العرش يعلم ما يلج في الارض وما يخرج منها وما ينزل من السماء وما يعرج فيها وهو معكم اين ما كنتم والله بما تعملون بصير","dt":"[4] هو الذي خلق السموات والارض وما بينهما في سته ايام، ثم استوى -اي: علا وارتفع- على عرشه فوق جميع خلقه استواء يليق بجلاله، يعلم ما يدخل في الارض من حب ومطر وغير ذلك، وما يخرج منها من نبات وزرع وثمار، وما ينزل من السماء من مطر وغيره، وما يعرج فيها من الملائكه والاعمال، وهو سبحانه معكم بعلمه اينما كنتم، والله بصير باعمالكم التي تعملونها، وسيجازيكم عليها."},{"id":"5080","s":57,"a":5,"at":"له ملك السموات والارض والى الله ترجع الامور","dt":"[5] له ملك السموات والارض، والى الله مصير امور الخلائق في الاخره، وسيجازيهم على اعمالهم."},{"id":"5081","s":57,"a":6,"at":"يولج الليل في النهار ويولج النهار في الليل وهو عليم بذات الصدور","dt":"[6] يدخل ما نقص من ساعات الليل في النهار فيزيد النهار، ويدخل ما نقص من ساعات النهار في الليل فيزيد الليل، وهو سبحانه عليم بالسرائر وما تكنه الصدور، لا يخفى عليه من ذلك خافيه."},{"id":"5082","s":57,"a":7,"at":"امنوا بالله ورسوله وانفقوا مما جعلكم مستخلفين فيه فالذين امنوا منكم وانفقوا لهم اجر كبير","dt":"[7] امنوا بالله ورسوله محمد -صلى الله عليه وسلم-، وانفقوا مما رزقكم الله من المال واستخلفكم فيه، فالذين امنوا منكم ايها الناس، وانفقوا من مالهم، لهم ثواب عظيم."},{"id":"5083","s":57,"a":8,"at":"وما لكم لا تؤمنون بالله والرسول يدعوكم لتؤمنوا بربكم وقد اخذ ميثاقكم ان كنتم مؤمنين","dt":"[8] واي عذر لكم في ان لا تصدقوا بوحدانيه الله وتعملوا بشرعه، والرسول يدعوكم الى ذلك، وقد اخذ الله ميثاقكم على ذلك، ان كنتم مؤمنين بالله خالقكم؟"},{"id":"5084","s":57,"a":9,"at":"هو الذي ينزل على عبده ايات بينات ليخرجكم من الظلمات الى النور وان الله بكم لرءوف رحيم","dt":"[9] هو الذي ينزل على عبده محمد -صلى الله عليه وسلم- ايات مفصلات واضحات من القران؛ ليخرجكم بذلك من ظلمه الكفر الى نور الايمان، وان الله في اخراجكم من الظلمات الى النور ليرحمكم رحمه واسعه في عاجلكم واجلكم، فيجازيكم احسن الجزاء."},{"id":"5085","s":57,"a":10,"at":"وما لكم الا تنفقوا في سبيل الله ولله ميراث السموات والارض لا يستوي منكم من انفق من قبل الفتح وقاتل اولئك اعظم درجه من الذين انفقوا من بعد وقاتلوا وكلا وعد الله الحسنى والله بما تعملون خبير","dt":"[10] واي شيء يمنعكم من الانفاق في سبيل الله؟ ولله ميراث السموات والارض يرث كل ما فيهما، ولا يبقى احد مالكا لشيء فيهما. لا يستوي في الاجر والمثوبه منكم من انفق من قبل فتح «مكه» وقاتل الكفار، اولئك اعظم درجه عند الله من الذين انفقوا في سبيل الله من بعد الفتح وقاتلوا الكفار، وكلا من الفريقين وعد الله الجنه، والله باعمالكم خبير لا يخفى عليه شيء منها، وسيجازيكم عليها."},{"id":"5086","s":57,"a":11,"at":"من ذا الذي يقرض الله قرضا حسنا فيضاعفه له وله اجر كريم","dt":"[11] من ذا الذي ينفق في سبيل الله محتسبا من قلبه بلا من ولا اذى، فيضاعف له ربه الاجر والثواب، وله جزاء كريم، وهو الجنه؟"},{"id":"5087","s":57,"a":12,"at":"يوم ترى المؤمنين والمؤمنات يسعى نورهم بين ايديهم وبايمانهم بشراكم اليوم جنات تجري من تحتها الانهار خالدين فيها ذلك هو الفوز العظيم","dt":"[12] يوم ترى المؤمنين والمؤمنات يسعى نورهم على الصراط بين ايديهم وعن ايمانهم، بقدر اعمالهم، ويقال لهم: بشراكم اليوم دخول جنات واسعه تجري من تحت قصورها واشجارها الانهار، لا تخرجون منها ابدا، ذلك الجزاء هو الفوز العظيم لكم في الاخره."},{"id":"5088","s":57,"a":13,"at":"يوم يقول المنافقون والمنافقات للذين امنوا انظرونا نقتبس من نوركم قيل ارجعوا وراءكم فالتمسوا نورا فضرب بينهم بسور له باب باطنه فيه الرحمه وظاهره من قبله العذاب","dt":"[13] يوم يقول المنافقون والمنافقات للذين امنوا، وهم على الصراط: انتظرونا نستضئ من نوركم، فتقول لهم الملائكه -على وجه السخريه منهم-: ارجعوا وراءكم فاطلبوا نورا، ففصل بينهم بسور له باب، باطنه مما يلي المؤمنين فيه الرحمه، وظاهره مما يلي المنافقين من جهته العذاب."},{"id":"5089","s":57,"a":14,"at":"ينادونهم الم نكن معكم قالوا بلى ولكنكم فتنتم انفسكم وتربصتم وارتبتم وغرتكم الاماني حتى جاء امر الله وغركم بالله الغرور","dt":"[14] ينادي المنافقون المؤمنين قائلين: الم نكن معكم في الدنيا، نؤدي شعائر الدين مثلكم؟ قال المؤمنون لهم: بلى قد كنتم معنا في الظاهر، ولكنكم اهلكتم انفسكم بالنفاق والمعاصي، وتربصتم بالنبي الموت وبالمؤمنين الدوائر، وشككتم في البعث بعد الموت، وخدعتكم امانيكم الباطله، وبقيتم على ذلك حتى جاءكم الموت وخدعكم بالله الشيطان."},{"id":"5090","s":57,"a":15,"at":"فاليوم لا يؤخذ منكم فديه ولا من الذين كفروا ماواكم النار هي مولاكم وبئس المصير","dt":"[15] فاليوم لا يقبل من احد منكم -ايها المنافقون- عوض؛ ليفتدي به من عذاب الله، ولا من الذين كفروا بالله ورسوله، مصيركم جميعا النار، هي اولى بكم من كل منزل، وبئس المصير هي."},{"id":"5091","s":57,"a":16,"at":"الم يان للذين امنوا ان تخشع قلوبهم لذكر الله وما نزل من الحق ولا يكونوا كالذين اوتوا الكتاب من قبل فطال عليهم الامد فقست قلوبهم وكثير منهم فاسقون","dt":"[16] الم يحن الوقت للذين صدقوا الله ورسوله واتبعوا هديه، ان تلين قلوبهم عند ذكر الله وسماع القران، ولا يكونوا في قسوه القلوب كالذين اوتوا الكتاب من قبلهم -من اليهود والنصارى- الذين طال عليهم الزمان فبدلوا كلام الله، فقست قلوبهم، وكثير منهم خارجون عن طاعه الله؟ وفي الايه الحث على الرقه والخشوع لله سبحانه عند سماع ما انزله من الكتاب والحكمه، والحذر من التشبه باليهود والنصارى في قسوه قلوبهم، وخروجهم عن طاعه الله."},{"id":"5092","s":57,"a":17,"at":"اعلموا ان الله يحيي الارض بعد موتها قد بينا لكم الايات لعلكم تعقلون","dt":"[17] اعلموا ان الله سبحانه وتعالى يحيي الارض بالمطر بعد موتها، فتخرج النبات، فكذلك الله قادر على احياء الموتى يوم القيامه، وهو القادر على تليين القلوب بعد قسوتها. قد بينا لكم دلائل قدرتنا؛ لعلكم تعقلونها فتتعظوا."},{"id":"5093","s":57,"a":18,"at":"ان المصدقين والمصدقات واقرضوا الله قرضا حسنا يضاعف لهم ولهم اجر كريم","dt":"[18] ان المتصدقين من اموالهم والمتصدقات، وانفقوا في سبيل الله نفقات طيبه بها نفوسهم؛ ابتغاء وجه الله تعالى، يضاعف لهم ثواب ذلك، ولهم فوق ذلك ثواب جزيل، وهو الجنه."},{"id":"5094","s":57,"a":19,"at":"والذين امنوا بالله ورسله اولئك هم الصديقون والشهداء عند ربهم لهم اجرهم ونورهم والذين كفروا وكذبوا باياتنا اولئك اصحاب الجحيم","dt":"[19] والذين امنوا بالله ورسله ولم يفرقوا بين احد منهم، اولئك هم الصديقون الذين كمل تصديقهم بما جاءت به الرسل، اعتقادا وقولا وعملا، والشهداء عند ربهم لهم ثوابهم الجزيل عند الله، ونورهم العظيم يوم القيامه، والذين كفروا وكذبوا بادلتنا وحججنا اولئك اصحاب الجحيم، فلا اجر لهم ولا نور."},{"id":"5095","s":57,"a":20,"at":"اعلموا انما الحياه الدنيا لعب ولهو وزينه وتفاخر بينكم وتكاثر في الاموال والاولاد كمثل غيث اعجب الكفار نباته ثم يهيج فتراه مصفرا ثم يكون حطاما وفي الاخره عذاب شديد ومغفره من الله ورضوان وما الحياه الدنيا الا متاع الغرور","dt":"[20] اعلموا -ايها الناس- انما الحياه الدنيا لعب ولهو، تلعب بها الابدان وتلهو بها القلوب، وزينه تتزينون بها، وتفاخر بينكم بمتاعها، وتكاثر بالعدد في الاموال والاولاد، مثلها كمثل مطر اعجب الزراع نباته، ثم يهيج هذا النبات فييبس، فتراه مصفرا بعد خضرته، ثم يكون فتاتا يابسا متهشما، وفي الاخره عذاب شديد للكفار ومغفره من الله ورضوان لاهل الايمان. وما الحياه الدنيا لمن عمل لها ناسيا اخرته الا متاع الغرور."},{"id":"5096","s":57,"a":21,"at":"سابقوا الى مغفره من ربكم وجنه عرضها كعرض السماء والارض اعدت للذين امنوا بالله ورسله ذلك فضل الله يؤتيه من يشاء والله ذو الفضل العظيم","dt":"[21] سابقوا -ايها الناس- في السعي الى اسباب المغفره من التوبه النصوح والابتعاد عن المعاصي؛ لتجزوا مغفره من ربكم وجنه عرضها كعرض السماء والارض، وهي معده للذين وحدوا الله واتبعوا رسله، ذلك فضل الله الذي يؤتيه من يشاء من خلقه، فالجنه لا تنال الا برحمه الله وفضله، والعمل الصالح. والله ذو الاحسان والعطاء الكثير الواسع على عباده المؤمنين."},{"id":"5097","s":57,"a":22,"at":"ما اصاب من مصيبه في الارض ولا في انفسكم الا في كتاب من قبل ان نبراها ان ذلك على الله يسير","dt":"[22] ما اصابكم -ايها الناس- من مصيبه في الارض ولا في انفسكم من الامراض والجوع والاسقام الا هو مكتوب في اللوح المحفوظ من قبل ان تخلق الخليقه. ان ذلك على الله تعالى يسير."},{"id":"5098","s":57,"a":23,"at":"لكيلا تاسوا على ما فاتكم ولا تفرحوا بما اتاكم والله لا يحب كل مختال فخور","dt":"[23] لكي لا تحزنوا على ما فاتكم من الدنيا، ولا تفرحوا بما اتاكم فرح بطر واشر. والله لا يحب كل متكبر بما اوتي من الدنيا فخور به على غيره."},{"id":"5099","s":57,"a":24,"at":"الذين يبخلون ويامرون الناس بالبخل ومن يتول فان الله هو الغني الحميد","dt":"[24] هؤلاء المتكبرون هم الذين يبخلون بمالهم، ولا ينفقونه في سبيل الله، ويامرون الناس بالبخل بتحسينه لهم. ومن يتول عن طاعه الله لا يضر الا نفسه، ولن يضر الله شيئا، فان الله هو الغني عن خلقه، الحميد الذي له كل وصف حسن كامل، وفعل جميل يستحق ان يحمد عليه."},{"id":"5100","s":57,"a":25,"at":"لقد ارسلنا رسلنا بالبينات وانزلنا معهم الكتاب والميزان ليقوم الناس بالقسط وانزلنا الحديد فيه باس شديد ومنافع للناس وليعلم الله من ينصره ورسله بالغيب ان الله قوي عزيز","dt":"[25] لقد ارسلنا رسلنا بالحجج الواضحات، وانزلنا معهم الكتاب بالاحكام والشرائع، وانزلنا الميزان؛ ليتعامل الناس بينهم بالعدل، وانزلنا لهم الحديد، فيه قوه شديده، ومنافع للناس متعدده، وليعلم الله علما ظاهرا للخلق من ينصر دينه ورسله بالغيب. ان الله قوي لا يقهر، عزيز لا يغالب."},{"id":"5101","s":57,"a":26,"at":"ولقد ارسلنا نوحا وابراهيم وجعلنا في ذريتهما النبوه والكتاب فمنهم مهتد وكثير منهم فاسقون","dt":"[26] ولقد ارسلنا نوحا وابراهيم الى قومهما، وجعلنا في ذريتهما النبوه والكتب المنزله، فمن ذريتهما مهتد الى الحق، وكثير منهم خارجون عن طاعه الله."},{"id":"5102","s":57,"a":27,"at":"ثم قفينا على اثارهم برسلنا وقفينا بعيسى ابن مريم واتيناه الانجيل وجعلنا في قلوب الذين اتبعوه رافه ورحمه ورهبانيه ابتدعوها ما كتبناها عليهم الا ابتغاء رضوان الله فما رعوها حق رعايتها فاتينا الذين امنوا منهم اجرهم وكثير منهم فاسقون","dt":"[27] ثم اتبعنا على اثار نوح وابراهيم برسلنا الذين ارسلناهم بالبينات، وقفينا بعيسى بن مريم، واتيناه الانجيل، وجعلنا في قلوب الذين اتبعوه على دينه لينا وشفقه، فكانوا متوادين فيما بينهم، وابتدعوا رهبانيه بالغلو في العباده ما فرضناها عليهم، بل هم الذين التزموا بها من تلقاء انفسهم، قصدهم بذلك رضا الله، فما قاموا بها حق القيام، فاتينا الذين امنوا منهم بالله ورسله اجرهم حسب ايمانهم، وكثير منهم خارجون عن طاعه الله مكذبون بنبيه محمد -صلى الله عليه وسلم-."},{"id":"5103","s":57,"a":28,"at":"ياايها الذين امنوا اتقوا الله وامنوا برسوله يؤتكم كفلين من رحمته ويجعل لكم نورا تمشون به ويغفر لكم والله غفور رحيم","dt":"[28] يا ايها الذين امنوا امتثلوا اوامر الله واجتنبوا نواهيه، وامنوا برسوله، يؤتكم ضعفين من رحمته، ويجعل لكم نورا تهتدون به، ويغفر لكم ذنوبكم، والله غفور لعباده، رحيم بهم."},{"id":"5104","s":57,"a":29,"at":"لئلا يعلم اهل الكتاب الا يقدرون على شيء من فضل الله وان الفضل بيد الله يؤتيه من يشاء والله ذو الفضل العظيم","dt":"[29] اعطاكم الله تعالى ذلك كله؛ ليعلم اهل الكتاب الذين لم يؤمنوا بمحمد -صلى الله عليه وسلم-، انهم لا يقدرون على شيء من فضل الله يكسبونه لانفسهم او يمنحونه لغيرهم، وان الفضل كله بيد الله وحده يؤتيه من يشاء من عباده، والله ذو الاحسان والعطاء الكثير الواسع على خلقه."},{"id":"5105","s":58,"a":1,"at":"قد سمع الله قول التي تجادلك في زوجها وتشتكي الى الله والله يسمع تحاوركما ان الله سميع بصير","dt":"[1] قد سمع الله قول خوله بنت ثعلبه التي تراجعك في شان زوجها اوس بن الصامت، وفيما صدر عنه في حقها من الظهار، وهو قوله لها: «انت علي كظهر امي»، اي: في حرمه النكاح، وهي تتضرع الى الله تعالى؛ لتفريج كربتها، والله يسمع تخاطبكما ومراجعتكما. ان الله سميع لكل قول، بصير بكل شيء، لا تخفى عليه خافيه."},{"id":"5106","s":58,"a":2,"at":"الذين يظاهرون منكم من نسائهم ما هن امهاتهم ان امهاتهم الا اللائي ولدنهم وانهم ليقولون منكرا من القول وزورا وان الله لعفو غفور","dt":"[2] الذين يظاهرون منكم من نسائهم، فيقول الرجل منهم لزوجته: «انت علي كظهر امي»، -اي في حرمه النكاح- قد عصوا الله وخالفوا الشرع، ونساؤهم لسن في الحقيقه امهاتهم، وانما هن زوجاتهم، ما امهاتهم الا اللائي ولدنهم. وان هؤلاء المظاهرين ليقولون قولا كاذبا فظيعا لا تعرف صحته. وان الله لعفو غفور عمن صدر منه بعض المخالفات، فتداركها بالتوبه النصوح."},{"id":"5107","s":58,"a":3,"at":"والذين يظاهرون من نسائهم ثم يعودون لما قالوا فتحرير رقبه من قبل ان يتماسا ذلكم توعظون به والله بما تعملون خبير","dt":"[3] والذين يحرمون نساءهم على انفسهم بالمظاهره منهن، ثم يرجعون عن قولهم ويعزمون على وطء نسائهم، فعلى الزوج المظاهر -والحاله هذه- كفاره التحريم، وهي عتق رقبه مؤمنه عبد او امه قبل ان يطا زوجته التي ظاهر منها، ذلكم هو حكم الله -فيمن ظاهر من زوجته- توعظون به ايها المؤمنون؛ لكي لا تقعوا في الظهار وقول الزور، وتكفروا ان وقعتم فيه، ولكي لا تعودوا اليه، والله لا يخفى عليه شيء من اعمالكم، وهو مجازيكم عليها."},{"id":"5108","s":58,"a":4,"at":"فمن لم يجد فصيام شهرين متتابعين من قبل ان يتماسا فمن لم يستطع فاطعام ستين مسكينا ذلك لتؤمنوا بالله ورسوله وتلك حدود الله وللكافرين عذاب اليم","dt":"[4] فمن لم يجد رقبه يعتقها، فالواجب عليه صيام شهرين متواليين من قبل ان يطا زوجه، فمن لم يستطع صيام الشهرين لعذر شرعي، فعليه ان يطعم ستين مسكينا -ممن لا يملكون ما يكفيهم ويسد حاجتهم- ما يشبعهم، ذلك الذي بيناه لكم من احكام الظهار؛ من اجل ان تصدقوا بالله وتتبعوا رسوله وتعملوا بما شرعه الله، وتتركوا ما كنتم عليه في جاهليتكم، وتلك الاحكام المذكوره هي اوامر الله وحدوده فلا تتجاوزوها، وللجاحدين بها عذاب موجع."},{"id":"5109","s":58,"a":5,"at":"ان الذين يحادون الله ورسوله كبتوا كما كبت الذين من قبلهم وقد انزلنا ايات بينات وللكافرين عذاب مهين","dt":"[5] ان الذين يشاقون الله ورسوله ويخالفون امرهما خذلوا واهينوا، كما خذل الذين من قبلهم من الامم الذين حادوا الله ورسله، وقد انزلنا ايات واضحات الحجه تدل على ان شرع الله وحدوده حق، ولجاحدي تلك الايات عذاب مذل في جهنم."},{"id":"5110","s":58,"a":6,"at":"يوم يبعثهم الله جميعا فينبئهم بما عملوا احصاه الله ونسوه والله على كل شيء شهيد","dt":"[6] واذكر -ايها الرسول- يوم القيامه، يوم يحيي الله الموتى جميعا، ويجمع الاولين والاخرين في صعيد واحد، فيخبرهم بما عملوا من خير وشر، احصاه الله وكتبه في اللوح المحفوظ، وحفظه عليهم في صحائف اعمالهم، وهم قد نسوه. والله على كل شيء شهيد، لا يخفى عليه شيء."},{"id":"5111","s":58,"a":7,"at":"الم تر ان الله يعلم ما في السموات وما في الارض ما يكون من نجوى ثلاثه الا هو رابعهم ولا خمسه الا هو سادسهم ولا ادنى من ذلك ولا اكثر الا هو معهم اين ما كانوا ثم ينبئهم بما عملوا يوم القيامه ان الله بكل شيء عليم","dt":"[7] الم تعلم ان الله تعالى يعلم كل شيء في السموات والارض؟ ما يتناجى ثلاثه من خلقه بحديث سر الا هو رابعهم بعلمه واحاطته، ولا خمسه الا هو سادسهم، ولا اقل من هذه الاعداد المذكوره ولا اكثر منها الا هو معهم بعلمه في اي مكان كانوا، لا يخفى عليه شيء من امرهم، ثم يخبرهم تعالى يوم القيامه بما عملوا من خير وشر ويجازيهم عليه. ان الله بكل شيء عليم لا تخفى عليه خافيه."},{"id":"5112","s":58,"a":8,"at":"الم تر الى الذين نهوا عن النجوى ثم يعودون لما نهوا عنه ويتناجون بالاثم والعدوان ومعصيه الرسول واذا جاءوك حيوك بما لم يحيك به الله ويقولون في انفسهم لولا يعذبنا الله بما نقول حسبهم جهنم يصلونها فبئس المصير","dt":"[8] الم تر -ايها الرسول- الى اليهود الذين نهوا عن الحديث سرا بما يثير الشك في نفوس المؤمنين، ثم يرجعون الى ما نهوا عنه، ويتحدثون سرا بما هو اثم وعدوان ومخالفه لامر الرسول؟ واذا جاءك -ايها الرسول- هؤلاء اليهود لامر من الامور حيوك بغير التحيه التي جعلها الله لك تحيه، فقالوا: (السام عليك) اي: الموت لك، ويقولون فيما بينهم: هلا يعاقبنا الله بما نقول لمحمد ان كان رسولا حقا، تكفيهم جهنم يدخلونها، ويقاسون حرها، فبئس المرجع هي."},{"id":"5113","s":58,"a":9,"at":"ياايها الذين امنوا اذا تناجيتم فلا تتناجوا بالاثم والعدوان ومعصيه الرسول وتناجوا بالبر والتقوى واتقوا الله الذي اليه تحشرون","dt":"[9] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، اذا تحدثتم فيما بينكم سرا، فلا تتحدثوا بما فيه اثم من القول، او بما هو عدوان على غيركم، او مخالفه لامر الرسول، وتحدثوا بما فيه خير وطاعه واحسان، وخافوا الله بامتثالكم اوامره واجتنابكم نواهيه، فاليه وحده مرجعكم بجميع اعمالكم واقوالكم التي احصاها عليكم، وسيجازيكم بها."},{"id":"5114","s":58,"a":10,"at":"انما النجوى من الشيطان ليحزن الذين امنوا وليس بضارهم شيئا الا باذن الله وعلى الله فليتوكل المؤمنون","dt":"[10] انما التحدث خفيه بالاثم والعدوان من وسوسه الشيطان، فهو المزين لها، والحامل عليها؛ ليدخل الحزن على قلوب المؤمنين، وليس ذلك بمؤذي المؤمنين شيئا الا بمشيئه الله تعالى وارادته. وعلى الله وحده فليفوض المؤمنون به جميع امورهم."},{"id":"5115","s":58,"a":11,"at":"ياايها الذين امنوا اذا قيل لكم تفسحوا في المجالس فافسحوا يفسح الله لكم واذا قيل انشزوا فانشزوا يرفع الله الذين امنوا منكم والذين اوتوا العلم درجات والله بما تعملون خبير","dt":"[11] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، اذا طلب منكم ان يوسع بعضكم لبعض المجالس فاوسعوا، يوسع الله عليكم في الدنيا والاخره، واذا طلب منكم -ايها المؤمنون- ان تقوموا من مجالسكم لامر من الامور التي يكون فيها خير لكم فقوموا، يرفع الله مكانه المؤمنين المخلصين منكم، ويرفع مكانه اهل العلم درجات كثيره في الثواب ومراتب الرضوان، والله تعالى خبير باعمالكم لا يخفى عليه شيء منها، وهو مجازيكم عليها.وفي الايه تنويه بمكانه العلماء وفضلهم، ورفع درجاتهم."},{"id":"5116","s":58,"a":12,"at":"ياايها الذين امنوا اذا ناجيتم الرسول فقدموا بين يدي نجواكم صدقه ذلك خير لكم واطهر فان لم تجدوا فان الله غفور رحيم","dt":"[12] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، اذا اردتم ان تكلموا رسول الله -صلى الله عليه وسلم- سرا بينكم وبينه، فقدموا قبل ذلك صدقه لاهل الحاجه، ذلك خير لكم لما فيه من الثواب، وازكى لقلوبكم من الماثم، فان لم تجدوا ما تتصدقون به فلا حرج عليكم؛ فان الله غفور لعباده المؤمنين، رحيم بهم."},{"id":"5117","s":58,"a":13,"at":"ااشفقتم ان تقدموا بين يدي نجواكم صدقات فاذ لم تفعلوا وتاب الله عليكم فاقيموا الصلاه واتوا الزكاه واطيعوا الله ورسوله والله خبير بما تعملون","dt":"[13] اخشيتم الفقر اذا قدمتم صدقه قبل مناجاتكم رسول الله؟ فاذ لم تفعلوا ما امرتم به، وتاب الله عليكم، ورخص لكم في الا تفعلوه، فاثبتوا وداوموا على اقام الصلاه وايتاء الزكاه وطاعه الله ورسوله في كل ما امرتم به، والله سبحانه خبير باعمالكم، ومجازيكم عليها."},{"id":"5118","s":58,"a":14,"at":"الم تر الى الذين تولوا قوما غضب الله عليهم ما هم منكم ولا منهم ويحلفون على الكذب وهم يعلمون","dt":"[14] الم تر الى المنافقين الذين اتخذوا اليهود اصدقاء ووالوهم؟ والمنافقون في الحقيقه ليسوا من المسلمين ولا من اليهود، ويحلفون كذبا انهم مسلمون، وانك رسول الله، وهم يعلمون انهم كاذبون فيما حلفوا عليه."},{"id":"5119","s":58,"a":15,"at":"اعد الله لهم عذابا شديدا انهم ساء ما كانوا يعملون","dt":"[15] اعد الله لهؤلاء المنافقين عذابا بالغ الشده والالم، انهم ساء ما كانوا يعملون من النفاق والحلف على الكذب."},{"id":"5120","s":58,"a":16,"at":"اتخذوا ايمانهم جنه فصدوا عن سبيل الله فلهم عذاب مهين","dt":"[16] اتخذ المنافقون ايمانهم الكاذبه وقايه لهم من القتل بسبب كفرهم، ولمنع المسلمين عن قتالهم واخذ اموالهم، فبسبب ذلك صدوا انفسهم وغيرهم عن سبيل الله وهو الاسلام، فلهم عذاب مذل في النار؛ لاستكبارهم عن الايمان بالله ورسوله وصدهم عن سبيله."},{"id":"5121","s":58,"a":17,"at":"لن تغني عنهم اموالهم ولا اولادهم من الله شيئا اولئك اصحاب النار هم فيها خالدون","dt":"[17] لن تدفع عن المنافقين اموالهم ولا اولادهم من عذاب الله شيئا، اولئك اهل النار يدخلونها فيبقون فيها ابدا، لا يخرجون منها. وهذا الجزاء يعم كل من صد عن دين الله بقوله او فعله."},{"id":"5122","s":58,"a":18,"at":"يوم يبعثهم الله جميعا فيحلفون له كما يحلفون لكم ويحسبون انهم على شيء الا انهم هم الكاذبون","dt":"[18] يوم القيامه يبعث الله المنافقين جميعا من قبورهم احياء، فيحلفون له انهم كانوا مؤمنين، كما كانوا يحلفون لكم -ايها المؤمنون- في الدنيا، ويعتقدون ان ذلك ينفعهم عند الله كما كان ينفعهم في الدنيا عند المسلمين، الا انهم هم البالغون في الكذب حدا لم يبلغه غيرهم."},{"id":"5123","s":58,"a":19,"at":"استحوذ عليهم الشيطان فانساهم ذكر الله اولئك حزب الشيطان الا ان حزب الشيطان هم الخاسرون","dt":"[19] غلب عليهم الشيطان واستولى عليهم، حتى تركوا اوامر الله والعمل بطاعته، اولئك حزب الشيطان واتباعه. الا ان حزب الشيطان هم الخاسرون في الدنيا والاخره."},{"id":"5124","s":58,"a":20,"at":"ان الذين يحادون الله ورسوله اولئك في الاذلين","dt":"[20] ان الذين يخالفون امر الله ورسوله، اولئك من جمله الاذلاء المغلوبين المهانين في الدنيا والاخره."},{"id":"5125","s":58,"a":21,"at":"كتب الله لاغلبن انا ورسلي ان الله قوي عزيز","dt":"[21] كتب الله في اللوح المحفوظ وحكم بان النصره له ولكتابه ورسله وعباده المؤمنين. ان الله سبحانه قوي لا يعجزه شيء، عزيز على خلقه."},{"id":"5126","s":58,"a":22,"at":"لا تجد قوما يؤمنون بالله واليوم الاخر يوادون من حاد الله ورسوله ولو كانوا اباءهم او ابناءهم او اخوانهم او عشيرتهم اولئك كتب في قلوبهم الايمان وايدهم بروح منه ويدخلهم جنات تجري من تحتها الانهار خالدين فيها رضي الله عنهم ورضوا عنه اولئك حزب الله الا ان حزب الله هم المفلحون","dt":"[22] لا تجد -ايها الرسول- قوما يصدقون بالله واليوم الاخر، ويعملون بما شرع الله لهم، يحبون ويوالون من عادى الله ورسوله وخالف امرهما، ولو كانوا اباءهم او ابناءهم او اخوانهم او اقرباءهم، اولئك الموالون في الله والمعادون فيه ثبت في قلوبهم الايمان، وقواهم بنصر منه وتاييد على عدوهم في الدنيا، ويدخلهم في الاخره جنات تجري من تحت قصورها واشجارها الانهار، ماكثين فيها زمانا ممتدا لا ينقطع، احل الله عليهم رضوانه فلا يسخط عليهم، ورضوا عن ربهم بما اعطاهم من الكرامات ورفيع الدرجات، اولئك حزب الله واولياؤه، واولئك هم الفائزون بسعاده الدنيا والاخره."},{"id":"5127","s":59,"a":1,"at":"سبح لله ما في السموات وما في الارض وهو العزيز الحكيم","dt":"[1] نزه الله عن كل ما لا يليق به كل ما في السموات وما في الارض، وهو العزيز الذي لا يغالب، الحكيم في قدره وتدبيره وصنعه وتشريعه، يضع الامور في مواضعها."},{"id":"5128","s":59,"a":2,"at":"هو الذي اخرج الذين كفروا من اهل الكتاب من ديارهم لاول الحشر ما ظننتم ان يخرجوا وظنوا انهم مانعتهم حصونهم من الله فاتاهم الله من حيث لم يحتسبوا وقذف في قلوبهم الرعب يخربون بيوتهم بايديهم وايدي المؤمنين فاعتبروا يااولي الابصار","dt":"[2] هو -سبحانه- الذي اخرج الذين جحدوا نبوه محمد -صلى الله عليه وسلم-، من اهل الكتاب، وهم يهود بني النضير، من مساكنهم التي جاوروا بها المسلمين حول «المدينه»، وذلك اول اخراج لهم من «جزيره العرب» الى «الشام»، ما ظننتم -ايها المسلمون- ان يخرجوا من ديارهم بهذا الذل والهوان؛ لشده باسهم وقوه منعتهم، وظن اليهود ان حصونهم تدفع عنهم باس الله ولا يقدر عليها احد، فجاءهم من امر الله ما لم يخطر لهم ببال، والقى الله في قلوبهم الخوف والفزع الشديد، يخربون بيوتهم بايديهم وايدي المؤمنين، فاتعظوا يا اصحاب البصائر السليمه والعقول الراجحه بما جرى لهم."},{"id":"5129","s":59,"a":3,"at":"ولولا ان كتب الله عليهم الجلاء لعذبهم في الدنيا ولهم في الاخره عذاب النار","dt":"[3] ولولا ان كتب الله عليهم الخروج من ديارهم وقضاه، لعذبهم في الدنيا بالقتل والسبي، ولهم في الاخره عذاب النار."},{"id":"5130","s":59,"a":4,"at":"ذلك بانهم شاقوا الله ورسوله ومن يشاق الله فان الله شديد العقاب","dt":"[4] ذلك -الذي اصاب اليهود في الدنيا وما ينتظرهم في الاخره- لانهم خالفوا امر الله وامر رسوله اشد المخالفه، وحاربوهما وسعوا في معصيتهما، ومن يخالف الله ورسوله فان الله شديد العقاب له."},{"id":"5131","s":59,"a":5,"at":"ما قطعتم من لينه او تركتموها قائمه على اصولها فباذن الله وليخزي الفاسقين","dt":"[5] اي شيء قطعتم -ايها المؤمنون- من نخله او تركتموها قائمه على ساقها، من غير ان تتعرضوا لها، فباذن الله وامره؛ وليذل بذلك الخارجين عن طاعته المخالفين امره ونهيه، حيث سلطكم على قطع نخيلهم وتحريقها."},{"id":"5132","s":59,"a":6,"at":"وما افاء الله على رسوله منهم فما اوجفتم عليه من خيل ولا ركاب ولكن الله يسلط رسله على من يشاء والله على كل شيء قدير","dt":"[6] والذي افاءه الله على رسوله من اموال يهود بني النضير، فلم تركبوا لتحصيله خيلا ولا ابلا، ولكن الله يسلط رسله على من يشاء من اعدائه، فيستسلمون لهم بلا قتال، والفيء ما اخذ من اموال الكفار بحق من غير قتال. والله على كل شيء قدير لا يعجزه شيء."},{"id":"5133","s":59,"a":7,"at":"ما افاء الله على رسوله من اهل القرى فلله وللرسول ولذي القربى واليتامى والمساكين وابن السبيل كي لا يكون دوله بين الاغنياء منكم وما اتاكم الرسول فخذوه وما نهاكم عنه فانتهوا واتقوا الله ان الله شديد العقاب","dt":"[7] الذي افاءه الله على رسوله من اموال مشركي اهل القرى من غير ركوب خيل ولا ابل فلله ولرسوله، يصرف في مصالح المسلمين العامه، ولذي قرابه رسول الله -صلى الله عليه وسلم-، وهم بنو هاشم وبنو المطلب، واليتامى وهم الاطفال الفقراء الذين مات اباؤهم وهم دون سن البلوغ، والمساكين وهم اهل الحاجه الذين لا يملكون ما يكفيهم ويسد حاجتهم، وابن السبيل، وهو الغريب المسافر الذي نفدت نفقته وانقطع عنه ماله؛ وذلك حتى لا يكون المال ملكا متداولا بين الاغنياء وحدهم، ويحرم منه الفقراء والمساكين. وما اعطاكم الرسول من مال، او شرعه لكم من شرع، فخذوه، وما نهاكم عن اخذه او فعله فانتهوا عنه، واتقوا الله بامتثال اوامره وترك نواهيه. ان الله شديد العقاب لمن عصاه وخالف امره ونهيه. والايه اصل في وجوب العمل بالسنه: قولا او فعلا او تقريرا."},{"id":"5134","s":59,"a":8,"at":"للفقراء المهاجرين الذين اخرجوا من ديارهم واموالهم يبتغون فضلا من الله ورضوانا وينصرون الله ورسوله اولئك هم الصادقون","dt":"[8] وكذلك يعطى من المال الذي افاءه الله على رسوله الفقراء المهاجرون، الذين اضطرهم كفار «مكه» الى الخروج من ديارهم واموالهم يطلبون من الله ان يتفضل عليهم بالرزق في الدنيا والرضوان في الاخره، وينصرون دين الله ورسوله بالجهاد في سبيل الله، اولئك هم الصادقون الذين صدقوا قولهم بفعلهم."},{"id":"5135","s":59,"a":9,"at":"والذين تبوءوا الدار والايمان من قبلهم يحبون من هاجر اليهم ولا يجدون في صدورهم حاجه مما اوتوا ويؤثرون على انفسهم ولو كان بهم خصاصه ومن يوق شح نفسه فاولئك هم المفلحون","dt":"[9] والذين استوطنوا «المدينه»، وامنوا من قبل هجره المهاجرين -وهم الانصار- يحبون المهاجرين، ويواسونهم باموالهم، ولا يجدون في انفسهم حسدا لهم مما اعطوا من مال الفيء وغيره، ويقدمون المهاجرين وذوي الحاجه على انفسهم، ولو كان بهم حاجه وفقر، ومن سلم من البخل ومنع الفضل من المال فاولئك هم الفائزون الذين فازوا بمطلوبهم."},{"id":"5136","s":59,"a":10,"at":"والذين جاءوا من بعدهم يقولون ربنا اغفر لنا ولاخواننا الذين سبقونا بالايمان ولا تجعل في قلوبنا غلا للذين امنوا ربنا انك رءوف رحيم","dt":"[10] والذين جاؤوا من المؤمنين من بعد الانصار والمهاجرين الاولين يقولون: ربنا اغفر لنا ذنوبنا، واغفر لاخواننا في الدين الذين سبقونا بالايمان، ولا تجعل في قلوبنا حسدا وحقدا لاحد من اهل الايمان، ربنا انك ترحم عبادك رحمه واسعه في عاجلهم واجلهم.وفي الايه دلاله على انه ينبغي للمسلم ان يذكر سلفه بخير، ويدعو لهم، وان يحب صحابه رسول الله -صلى الله عليه وسلم-، ويذكرهم بخير، ويترضى عنهم."},{"id":"5137","s":59,"a":11,"at":"الم تر الى الذين نافقوا يقولون لاخوانهم الذين كفروا من اهل الكتاب لئن اخرجتم لنخرجن معكم ولا نطيع فيكم احدا ابدا وان قوتلتم لننصرنكم والله يشهد انهم لكاذبون","dt":"[11] الم تنظر الى المنافقين، يقولون لاخوانهم في الكفر من يهود بني النضير: لئن اخرجكم محمد ومن معه من منازلكم لنخرجن معكم، ولا نطيع فيكم احدا ابدا سالنا خذلانكم او ترك الخروج معكم، ولئن قاتلوكم لنعاوننكم عليهم؟ والله يشهد ان المنافقين لكاذبون فيما وعدوا به يهود بني النضير."},{"id":"5138","s":59,"a":12,"at":"لئن اخرجوا لا يخرجون معهم ولئن قوتلوا لا ينصرونهم ولئن نصروهم ليولن الادبار ثم لا ينصرون","dt":"[12] لئن اخرج اليهود من «المدينه» لا يخرج المنافقون معهم، ولئن قوتلوا لا يقاتلون معهم كما وعدوا، ولئن قاتلوا معهم ليولن الادبار فرارا منهزمين، ثم لا ينصرهم الله، بل يخذلهم، ويذلهم."},{"id":"5139","s":59,"a":13,"at":"لانتم اشد رهبه في صدورهم من الله ذلك بانهم قوم لا يفقهون","dt":"[13] لخوف اليهود والمنافقين وخشيتهم اياكم -ايها المؤمنون- اعظم واشد في صدورهم من خوفهم وخشيتهم من الله؛ وذلك بسبب انهم قوم لا يفقهون عظمه الله والايمان به، ولا يرهبون عقابه."},{"id":"5140","s":59,"a":14,"at":"لا يقاتلونكم جميعا الا في قرى محصنه او من وراء جدر باسهم بينهم شديد تحسبهم جميعا وقلوبهم شتى ذلك بانهم قوم لا يعقلون","dt":"[14] لا يواجهكم اليهود بقتال مجتمعين الا في قرى محصنه بالاسوار والخنادق، او من خلف الحيطان التي يتسترون بها؛ لجبنهم وللرعب الذي تمكن من قلوبهم، عداوتهم فيما بينهم شديده، تظن انهم مجتمعون على كلمه واحده، ولكن قلوبهم متفرقه؛ وذلك بسبب انهم قوم لا يعقلون امر الله ولا يتدبرون اياته."},{"id":"5141","s":59,"a":15,"at":"كمثل الذين من قبلهم قريبا ذاقوا وبال امرهم ولهم عذاب اليم","dt":"[15] مثل هؤلاء اليهود فيما حل بهم من عقوبه الله كمثل كفار قريش يوم «بدر»، ويهود بني قينقاع، حيث ذاقوا سوء عاقبه كفرهم وعداوتهم لرسول الله -صلى الله عليه وسلم- في الدنيا، ولهم في الاخره عذاب اليم موجع."},{"id":"5142","s":59,"a":16,"at":"كمثل الشيطان اذ قال للانسان اكفر فلما كفر قال اني بريء منك اني اخاف الله رب العالمين","dt":"[16] ومثل هؤلاء المنافقين في اغراء اليهود على القتال ووعدهم بالنصر على رسول الله -صلى الله عليه وسلم-، كمثل الشيطان حين زين للانسان الكفر ودعاه اليه، فلما كفر قال: اني بريء منك، اني اخاف الله رب الخلق اجمعين."},{"id":"5143","s":59,"a":17,"at":"فكان عاقبتهما انهما في النار خالدين فيها وذلك جزاء الظالمين","dt":"[17] فكان عاقبه امر الشيطان والانسان الذي اطاعه فكفر، انهما في النار، ماكثين فيها ابدا، وذلك جزاء المعتدين المتجاوزين حدود الله."},{"id":"5144","s":59,"a":18,"at":"ياايها الذين امنوا اتقوا الله ولتنظر نفس ما قدمت لغد واتقوا الله ان الله خبير بما تعملون","dt":"[18] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، خافوا الله، واحذروا عقابه بفعل ما امركم به وترك ما نهاكم عنه، ولتتدبر كل نفس ما قدمت من الاعمال ليوم القيامه، وخافوا الله في كل ما تاتون وما تذرون، ان الله سبحانه خبير بما تعملون، لا يخفى عليه شيء من اعمالكم، وهو مجازيكم عليها."},{"id":"5145","s":59,"a":19,"at":"ولا تكونوا كالذين نسوا الله فانساهم انفسهم اولئك هم الفاسقون","dt":"[19] ولا تكونوا -ايها المؤمنون- كالذين تركوا اداء حق الله الذي اوجبه عليهم، فانساهم بسبب ذلك حظوظ انفسهم من الخيرات التي تنجيهم من عذاب يوم القيامه، اولئك هم الموصوفون بالفسق، الخارجون عن طاعه الله وطاعه رسوله."},{"id":"5146","s":59,"a":20,"at":"لا يستوي اصحاب النار واصحاب الجنه اصحاب الجنه هم الفائزون","dt":"[20] لا يستوي اصحاب النار المعذبون، واصحاب الجنه المنعمون، اصحاب الجنه هم الظافرون بكل مطلوب، الناجون من كل مكروه."},{"id":"5147","s":59,"a":21,"at":"لو انزلنا هذا القران على جبل لرايته خاشعا متصدعا من خشيه الله وتلك الامثال نضربها للناس لعلهم يتفكرون","dt":"[21] لو انزلنا هذا القران على جبل من الجبال، ففهم ما فيه من وعد ووعيد، لابصرته على قوته وشده صلابته وضخامته، خاضعا ذليلا متشققا من خشيه الله تعالى. وتلك الامثال نضربها، ونوضحها للناس؛ لعلهم يتفكرون في قدره الله وعظمته. وفي الايه حث على تدبر القران، وتفهم معانيه، والعمل به."},{"id":"5148","s":59,"a":22,"at":"هو الله الذي لا اله الا هو عالم الغيب والشهاده هو الرحمن الرحيم","dt":"[22] هو الله سبحانه وتعالى المعبود بحق الذي لا اله سواه، عالم السر والعلن، يعلم ما غاب وما حضر، هو الرحمن الذي وسعت رحمته كل شيء، الرحيم باهل الايمان به."},{"id":"5149","s":59,"a":23,"at":"هو الله الذي لا اله الا هو الملك القدوس السلام المؤمن المهيمن العزيز الجبار المتكبر سبحان الله عما يشركون","dt":"[23] هو الله المعبود بحق الذي لا اله الا هو، الملك لجميع الاشياء، المتصرف فيها بلا ممانعه ولا مدافعه، المنزه عن كل نقص، الذي سلم من كل عيب، المصدق رسله وانبياءه بما ارسلهم به من الايات البينات، الرقيب على كل خلقه في اعمالهم، العزيز الذي لا يغالب، الجبار الذي قهر جميع العباد، واذعن له سائر الخلق، المتكبر الذي له الكبرياء والعظمه. تنزه الله تعالى عن كل ما يشركونه به في عبادته."},{"id":"5150","s":59,"a":24,"at":"هو الله الخالق البارئ المصور له الاسماء الحسنى يسبح له ما في السموات والارض وهو العزيز الحكيم","dt":"[24] هو الله سبحانه وتعالى الخالق المقدر للخلق، البارئ المنشئ الموجد لهم على مقتضى حكمته، المصور خلقه كيف يشاء، له سبحانه الاسماء الحسنى والصفات العلى، يسبح له جميع ما في السموات والارض، وهو العزيز الشديد الانتقام من اعدائه، الحكيم في تدبيره امور خلقه."},{"id":"5151","s":60,"a":1,"at":"ياايها الذين امنوا لا تتخذوا عدوي وعدوكم اولياء تلقون اليهم بالموده وقد كفروا بما جاءكم من الحق يخرجون الرسول واياكم ان تؤمنوا بالله ربكم ان كنتم خرجتم جهادا في سبيلي وابتغاء مرضاتي تسرون اليهم بالموده وانا اعلم بما اخفيتم وما اعلنتم ومن يفعله منكم فقد ضل سواء السبيل","dt":"[1] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، لا تتخذوا عدوي وعدوكم خلصاء واحباء، تفضون اليهم بالموده، فتخبرونهم باخبار الرسول -صلى الله عليه وسلم-، وسرائر المسلمين، وهم قد كفروا بما جاءكم من الحق من الايمان بالله ورسوله وما نزل عليه من القران، يخرجون الرسول ويخرجونكم -ايها المؤمنون- من «مكه»؛ لانكم تصدقون بالله ربكم، وتوحدونه، ان كنتم -ايها المؤمنون- هاجرتم مجاهدين في سبيلي، طالبين مرضاتي عنكم، فلا توالوا اعدائي واعداءكم، تفضون اليهم بالموده سرا، وانا اعلم بما اخفيتم وما اظهرتم، ومن يفعل ذلك منكم فقد اخطا طريق الحق والصواب، وضل عن قصد السبيل."},{"id":"5152","s":60,"a":2,"at":"ان يثقفوكم يكونوا لكم اعداء ويبسطوا اليكم ايديهم والسنتهم بالسوء وودوا لو تكفرون","dt":"[2] ان يظفر بكم هؤلاء الذين تسرون اليهم بالموده يكونوا حربا عليكم، ويمدوا اليكم ايديهم بالقتل والسبي، والسنتهم بالسب والشتم، وهم قد تمنوا -على كل حال- لو تكفرون مثلهم."},{"id":"5153","s":60,"a":3,"at":"لن تنفعكم ارحامكم ولا اولادكم يوم القيامه يفصل بينكم والله بما تعملون بصير","dt":"[3] لن تنفعكم قراباتكم ولا اولادكم شيئا حين توالون الكفار من اجلهم، يوم القيامه يفرق الله بينكم، فيدخل اهل طاعته الجنه، واهل معصيته النار. والله بما تعملون بصير، لا يخفى عليه شيء من اقوالكم واعمالكم."},{"id":"5154","s":60,"a":4,"at":"قد كانت لكم اسوه حسنه في ابراهيم والذين معه اذ قالوا لقومهم انا براء منكم ومما تعبدون من دون الله كفرنا بكم وبدا بيننا وبينكم العداوه والبغضاء ابدا حتى تؤمنوا بالله وحده الا قول ابراهيم لابيه لاستغفرن لك وما املك لك من الله من شيء ربنا عليك توكلنا واليك انبنا واليك المصير","dt":"[4] قد كانت لكم -ايها المؤمنون- قدوه حسنه في ابراهيم عليه السلام والذين معه من المؤمنين، حين قالوا لقومهم الكافرين بالله: انا بريئون منكم ومما تعبدون من دون الله من الالهه والانداد، كفرنا بكم، وانكرنا ما انتم عليه من الكفر، وظهر بيننا وبينكم العداوه والبغضاء ابدا ما دمتم على كفركم، حتى تؤمنوا بالله وحده، لكن لا يدخل في الاقتداء استغفار ابراهيم لابيه؛ فان ذلك انما كان قبل ان يتبين لابراهيم ان اباه عدو لله، فلما تبين له انه عدو لله تبرا منه، ربنا عليك اعتمدنا، واليك رجعنا بالتوبه، واليك المرجع يوم القيامه."},{"id":"5155","s":60,"a":5,"at":"ربنا لا تجعلنا فتنه للذين كفروا واغفر لنا ربنا انك انت العزيز الحكيم","dt":"[5] ربنا لا تجعلنا فتنه للذين كفروا بعذابك لنا او تسليط الكافرين علينا، فيفتنونا عن ديننا، او يظهروا علينا فيفتنوا بذلك، ويقولوا: لو كان هؤلاء على حق، ما اصابهم هذا العذاب، فيزدادوا كفرا، واستر علينا ذنوبنا بعفوك عنها ربنا، انك انت العزيز الذي لا يغالب، الحكيم في اقواله وافعاله."},{"id":"5156","s":60,"a":6,"at":"لقد كان لكم فيهم اسوه حسنه لمن كان يرجو الله واليوم الاخر ومن يتول فان الله هو الغني الحميد","dt":"[6] لقد كان لكم -ايها المؤمنون- في ابراهيم عليه السلام والذين معه قدوه حميده لمن يطمع في الخير من الله في الدنيا والاخره، ومن يعرض عما ندبه الله اليه من التاسي بانبيائه، ويوال اعداء الله، فان الله هو الغني عن عباده، الحميد في ذاته وصفاته، المحمود على كل حال."},{"id":"5157","s":60,"a":7,"at":"عسى الله ان يجعل بينكم وبين الذين عاديتم منهم موده والله قدير والله غفور رحيم","dt":"[7] عسى الله ان يجعل بينكم -ايها المؤمنون- وبين الذين عاديتموهم من اقاربكم من المشركين محبه بعد البغضاء، والفه بعد الشحناء بانشراح صدورهم للاسلام، والله قدير على كل شيء، والله غفور لعباده، رحيم بهم."},{"id":"5158","s":60,"a":8,"at":"لا ينهاكم الله عن الذين لم يقاتلوكم في الدين ولم يخرجوكم من دياركم ان تبروهم وتقسطوا اليهم ان الله يحب المقسطين","dt":"[8] لا ينهاكم الله -ايها المؤمنون- عن الذين لم يقاتلوكم من الكفار بسبب الدين، ولم يخرجوكم من دياركم ان تكرموهم بالخير، وتعدلوا فيهم باحسانكم اليهم وبركم بهم. ان الله يحب الذين يعدلون في اقوالهم وافعالهم."},{"id":"5159","s":60,"a":9,"at":"انما ينهاكم الله عن الذين قاتلوكم في الدين واخرجوكم من دياركم وظاهروا على اخراجكم ان تولوهم ومن يتولهم فاولئك هم الظالمون","dt":"[9] انما ينهاكم الله عن الذين قاتلوكم بسبب الدين واخرجوكم من دياركم، وعاونوا الكفار على اخراجكم ان تولوهم بالنصره والموده، ومن يتخذهم انصارا على المؤمنين واحبابا، فاولئك هم الظالمون لانفسهم، الخارجون عن حدود الله."},{"id":"5160","s":60,"a":10,"at":"ياايها الذين امنوا اذا جاءكم المؤمنات مهاجرات فامتحنوهن الله اعلم بايمانهن فان علمتموهن مؤمنات فلا ترجعوهن الى الكفار لا هن حل لهم ولا هم يحلون لهن واتوهم ما انفقوا ولا جناح عليكم ان تنكحوهن اذا اتيتموهن اجورهن ولا تمسكوا بعصم الكوافر واسالوا ما انفقتم وليسالوا ما انفقوا ذلكم حكم الله يحكم بينكم والله عليم حكيم","dt":"[10] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، اذا جاءكم النساء المؤمنات مهاجرات من دار الكفر الى دار الاسلام، فاختبروهن؛ لتعلموا صدق ايمانهن، الله اعلم بحقيقه ايمانهن، فان علمتموهن مؤمنات بحسب ما يظهر لكم من العلامات والبينات، فلا تردوهن الى ازواجهن الكافرين، فالنساء المؤمنات لا يحل لهن ان يتزوجن الكفار، ولا يحل للكفار ان يتزوجوا المؤمنات، واعطوا ازواج اللاتي اسلمن مثل ما انفقوا عليهن من المهور، ولا اثم عليكم ان تتزوجوهن اذا دفعتم لهن مهورهن. ولا تمسكوا بنكاح ازواجكم الكافرات، واطلبوا من المشركين ما انفقتم من مهور نسائكم اللاتي ارتددن عن الاسلام ولحقن بهم، وليطلبوا هم ما انفقوا من مهور نسائهم المسلمات اللاتي اسلمن ولحقن بكم، ذلكم الحكم المذكور في الايه هو حكم الله يحكم به بينكم فلا تخالفوه. والله عليم لا يخفى عليه شيء، حكيم في اقواله وافعاله."},{"id":"5161","s":60,"a":11,"at":"وان فاتكم شيء من ازواجكم الى الكفار فعاقبتم فاتوا الذين ذهبت ازواجهم مثل ما انفقوا واتقوا الله الذي انتم به مؤمنون","dt":"[11] وان لحقت بعض زوجاتكم مرتدات الى الكفار، ولم يعطكم الكفار مهورهن التي دفعتموها لهن، ثم ظفرتم بهؤلاء الكفار او غيرهم وانتصرتم عليهم، فاعطوا الذين ذهبت ازواجهم من المسلمين من الغنائم او غيرها مثل ما اعطوهن من المهور قبل ذلك، وخافوا الله الذي انتم به مؤمنون."},{"id":"5162","s":60,"a":12,"at":"ياايها النبي اذا جاءك المؤمنات يبايعنك على ان لا يشركن بالله شيئا ولا يسرقن ولا يزنين ولا يقتلن اولادهن ولا ياتين ببهتان يفترينه بين ايديهن وارجلهن ولا يعصينك في معروف فبايعهن واستغفر لهن الله ان الله غفور رحيم","dt":"[12] يا ايها النبي اذا جاءك النساء المؤمنات بالله ورسوله يعاهدنك على الا يجعلن مع الله شريكا في عبادته، ولا يسرقن شيئا، ولا يزنين، ولا يقتلن اولادهن بعد الولاده او قبلها، ولا يلحقن بازواجهن اولادا ليسوا منهم، ولا يخالفنك في معروف تامرهن به، فعاهدهن على ذلك، واطلب لهن المغفره من الله. ان الله غفور لذنوب عباده التائبين، رحيم بهم."},{"id":"5163","s":60,"a":13,"at":"ياايها الذين امنوا لا تتولوا قوما غضب الله عليهم قد يئسوا من الاخره كما يئس الكفار من اصحاب القبور","dt":"[13] يا ايها الذين امنوا بالله ورسوله، لا تتخذوا الذين غضب الله عليهم؛ لكفرهم اصدقاء واخلاء، قد يئسوا من ثواب الله في الاخره، كما يئس الكفار المقبورون، من رحمه الله في الاخره؛ حين شاهدوا حقيقه الامر، وعلموا علم اليقين انهم لا نصيب لهم منها، او كما يئس الكفار من بعث موتاهم - اصحاب القبور-؛ لاعتقادهم عدم البعث."},{"id":"5164","s":61,"a":1,"at":"سبح لله ما في السموات وما في الارض وهو العزيز الحكيم","dt":"[1] نزه الله عن كل ما لا يليق به كل ما في السموات وما في الارض، وهو العزيز الذي لا يغالب، الحكيم في اقواله وافعاله."},{"id":"5165","s":61,"a":2,"at":"ياايها الذين امنوا لم تقولون ما لا تفعلون","dt":"[2] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، لم تعدون وعدا، او تقولون قولا ولا تفون به؟! وهذا انكار على من يخالف فعله قوله."},{"id":"5166","s":61,"a":3,"at":"كبر مقتا عند الله ان تقولوا ما لا تفعلون","dt":"[3] عظم بغضا عند الله ان تقولوا بالسنتكم ما لا تفعلونه."},{"id":"5167","s":61,"a":4,"at":"ان الله يحب الذين يقاتلون في سبيله صفا كانهم بنيان مرصوص","dt":"[4] ان الله يحب الذين يقاتلون في سبيله صفا كانهم بنيان متراص محكم لا ينفذ منه العدو. وفي الايه بيان فضل الجهاد والمجاهدين؛ لمحبه الله سبحانه لعباده المؤمنين اذا صفوا مواجهين لاعداء الله، يقاتلونهم في سبيله."},{"id":"5168","s":61,"a":5,"at":"واذ قال موسى لقومه ياقوم لم تؤذونني وقد تعلمون اني رسول الله اليكم فلما زاغوا ازاغ الله قلوبهم والله لا يهدي القوم الفاسقين","dt":"[5] واذكر لقومك -ايها الرسول- حين قال نبي الله موسى عليه السلام لقومه: لم تؤذونني بالقول والفعل، وانتم تعلمون اني رسول الله اليكم؟ فلما عدلوا عن الحق مع علمهم به، واصروا على ذلك، صرف الله قلوبهم عن قبول الهدايه؛ عقوبه لهم على زيغهم الذي اختاروه لانفسهم. والله لا يهدي القوم الخارجين عن الطاعه ومنهاج الحق."},{"id":"5169","s":61,"a":6,"at":"واذ قال عيسى ابن مريم يابني اسرائيل اني رسول الله اليكم مصدقا لما بين يدي من التوراه ومبشرا برسول ياتي من بعدي اسمه احمد فلما جاءهم بالبينات قالوا هذا سحر مبين","dt":"[6] واذكر -ايها الرسول لقومك- حين قال عيسى بن مريم لقومه: اني رسول الله اليكم، مصدقا لما جاء قبلي من التوراه، وشاهدا بصدق رسول ياتي من بعدي اسمه «احمد»، وهو محمد -صلى الله عليه وسلم-، وداعيا الى التصديق به، فلما جاءهم محمد -صلى الله عليه وسلم- بالايات الواضحات، قالوا: هذا الذي جئتنا به سحر بين."},{"id":"5170","s":61,"a":7,"at":"ومن اظلم ممن افترى على الله الكذب وهو يدعى الى الاسلام والله لا يهدي القوم الظالمين","dt":"[7] ولا احد اشد ظلما وعدوانا ممن اختلق على الله الكذب، وجعل له شركاء في عبادته، وهو يدعى الى الدخول في الاسلام واخلاص العباده لله وحده. والله لا يوفق الذين ظلموا انفسهم بالكفر والشرك، الى ما فيه فلاحهم."},{"id":"5171","s":61,"a":8,"at":"يريدون ليطفئوا نور الله بافواههم والله متم نوره ولو كره الكافرون","dt":"[8] يريد هؤلاء الظالمون ان يبطلوا الحق الذي بعث به محمد -صلى الله عليه وسلم- -وهو القران- باقوالهم الكاذبه، والله مظهر الحق باتمام دينه ولو كره الجاحدون المكذبون."},{"id":"5172","s":61,"a":9,"at":"هو الذي ارسل رسوله بالهدى ودين الحق ليظهره على الدين كله ولو كره المشركون","dt":"[9] الله هو الذي ارسل رسوله محمدا -صلى الله عليه وسلم- بالقران ودين الاسلام؛ ليعليه على كل الاديان المخالفه له، ولو كره المشركون ذلك."},{"id":"5173","s":61,"a":10,"at":"ياايها الذين امنوا هل ادلكم على تجاره تنجيكم من عذاب اليم","dt":"[10] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، هل ارشدكم الى تجاره عظيمه الشان تنجيكم من عذاب موجع؟"},{"id":"5174","s":61,"a":11,"at":"تؤمنون بالله ورسوله وتجاهدون في سبيل الله باموالكم وانفسكم ذلكم خير لكم ان كنتم تعلمون","dt":"[11] تداومون على ايمانكم بالله ورسوله، وتجاهدون في سبيل الله؛ لنصره دينه بما تملكون من الاموال والانفس، ذلك خير لكم من تجاره الدنيا، ان كنتم تعلمون مضار الاشياء ومنافعها، فامتثلوا ذلك."},{"id":"5175","s":61,"a":12,"at":"يغفر لكم ذنوبكم ويدخلكم جنات تجري من تحتها الانهار ومساكن طيبه في جنات عدن ذلك الفوز العظيم","dt":"[12] ان فعلتم -ايها المؤمنون- ما امركم الله به يستر عليكم ذنوبكم، ويدخلكم جنات تجري من تحت قصورها واشجارها الانهار، ومساكن طاهره زكيه في جنات اقامه دائمه لا تنقطع، ذلك هو الفوز الذي لا فوز بعده."},{"id":"5176","s":61,"a":13,"at":"واخرى تحبونها نصر من الله وفتح قريب وبشر المؤمنين","dt":"[13] ونعمه اخرى لكم -ايها المؤمنون- تحبونها هي نصر من الله ياتيكم، وفتح عاجل يتم على ايديكم. وبشر المؤمنين -ايها النبي- بالنصر والفتح في الدنيا، والجنه في الاخره."},{"id":"5177","s":61,"a":14,"at":"ياايها الذين امنوا كونوا انصار الله كما قال عيسى ابن مريم للحواريين من انصاري الى الله قال الحواريون نحن انصار الله فامنت طائفه من بني اسرائيل وكفرت طائفه فايدنا الذين امنوا على عدوهم فاصبحوا ظاهرين","dt":"[14] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، كونوا انصار دين الله، كما كان اصفياء عيسى وخلص اصحابه انصار دين الله حين قال لهم عيسى: من يتولى منكم نصري واعانتي فيما يقرب الى الله؟ قالوا: نحن انصار دين الله، فاهتدت طائفه من بني اسرائيل، وضلت طائفه، فايدنا الذين امنوا بالله ورسوله، ونصرناهم على من عاداهم من فرق النصارى، فاصبحوا ظاهرين عليهم؛ وذلك ببعثه محمد -صلى الله عليه وسلم-."},{"id":"5178","s":62,"a":1,"at":"يسبح لله ما في السموات وما في الارض الملك القدوس العزيز الحكيم","dt":"[1] ينزه الله تعالى عن كل ما لا يليق به كل ما في السموات وما في الارض، وهو وحده المالك لكل شيء، المتصرف فيه بلا منازع، المنزه عن كل نقص، العزيز الذي لا يغالب، الحكيم في تدبيره وصنعه."},{"id":"5179","s":62,"a":2,"at":"هو الذي بعث في الاميين رسولا منهم يتلو عليهم اياته ويزكيهم ويعلمهم الكتاب والحكمه وان كانوا من قبل لفي ضلال مبين","dt":"[2] الله سبحانه هو الذي ارسل في العرب الذين لا يقرؤون، ولا كتاب عندهم ولا اثر رساله لديهم، رسولا منهم الى الناس جميعا، يقرا عليهم القران، ويطهرهم من العقائد الفاسده والاخلاق السيئه، ويعلمهم القران والسنه، وانهم كانوا من قبل بعثته لفي انحراف واضح عن الحق."},{"id":"5180","s":62,"a":3,"at":"واخرين منهم لما يلحقوا بهم وهو العزيز الحكيم","dt":"[3] وارسله سبحانه الى قوم اخرين لم يجيئوا بعد، وسيجيئون من العرب ومن غيرهم. والله تعالى -وحده- هو العزيز الغالب على كل شيء، الحكيم في اقواله وافعاله."},{"id":"5181","s":62,"a":4,"at":"ذلك فضل الله يؤتيه من يشاء والله ذو الفضل العظيم","dt":"[4] ذلك البعث للرسول -صلى الله عليه وسلم-، في امه العرب وغيرهم فضل من الله، يعطيه من يشاء من عباده. وهو -وحده- ذو الاحسان والعطاء الجزيل."},{"id":"5182","s":62,"a":5,"at":"مثل الذين حملوا التوراه ثم لم يحملوها كمثل الحمار يحمل اسفارا بئس مثل القوم الذين كذبوا بايات الله والله لا يهدي القوم الظالمين","dt":"[5] شبه اليهود الذين كلفوا العمل بالتوراه ثم لم يعملوا بها، كشبه الحمار الذي يحمل كتبا لا يدري ما فيها، قبح مثل القوم الذين كذبوا بايات الله، ولم ينتفعوا بها، والله لا يوفق القوم الظالمين الذين يتجاوزون حدوده، ويخرجون عن طاعته."},{"id":"5183","s":62,"a":6,"at":"قل ياايها الذين هادوا ان زعمتم انكم اولياء لله من دون الناس فتمنوا الموت ان كنتم صادقين","dt":"[6] قل -ايها الرسول- للذين تمسكوا بالمله اليهوديه المحرفه: ان ادعيتم -كذبا- انكم احباء الله دون غيركم من الناس، فتمنوا الموت ان كنتم صادقين في ادعائكم حب الله لكم."},{"id":"5184","s":62,"a":7,"at":"ولا يتمنونه ابدا بما قدمت ايديهم والله عليم بالظالمين","dt":"[7] ولا يتمنى هؤلاء اليهود الموت ابدا ايثارا للحياه الدنيا على الاخره، وخوفا من عقاب الله لهم؛ بسبب ما قدموه من الكفر وسوء الفعال. والله عليم بالظالمين، لا يخفى عليه من ظلمهم شيء."},{"id":"5185","s":62,"a":8,"at":"قل ان الموت الذي تفرون منه فانه ملاقيكم ثم تردون الى عالم الغيب والشهاده فينبئكم بما كنتم تعملون","dt":"[8] قل: ان الموت الذي تهربون منه لا مفر منه، فانه ات اليكم عند مجيء اجالكم، ثم ترجعون يوم البعث الى الله العالم بما غاب وما حضر، فيخبركم باعمالكم، وسيجازيكم عليها."},{"id":"5186","s":62,"a":9,"at":"ياايها الذين امنوا اذا نودي للصلاه من يوم الجمعه فاسعوا الى ذكر الله وذروا البيع ذلكم خير لكم ان كنتم تعلمون","dt":"[9] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، اذا نادى المؤذن للصلاه في يوم الجمعه، فامضوا الى سماع الخطبه واداء الصلاه، واتركوا البيع، وكذلك الشراء وجميع ما يشغلكم عنها، ذلك الذي امرتم به خير لكم؛ لما فيه من غفران ذنوبكم ومثوبه الله لكم، ان كنتم تعلمون مصالح انفسكم فافعلوا ذلك.وفي الايه دليل على وجوب حضور الجمعه واستماع الخطبه."},{"id":"5187","s":62,"a":10,"at":"فاذا قضيت الصلاه فانتشروا في الارض وابتغوا من فضل الله واذكروا الله كثيرا لعلكم تفلحون","dt":"[10] فاذا سمعتم الخطبه، واديتم الصلاه، فانتشروا في الارض، واطلبوا من رزق الله بسعيكم، واذكروا الله كثيرا في جميع احوالكم؛ لعلكم تفوزون بخيري الدنيا والاخره."},{"id":"5188","s":62,"a":11,"at":"واذا راوا تجاره او لهوا انفضوا اليها وتركوك قائما قل ما عند الله خير من اللهو ومن التجاره والله خير الرازقين","dt":"[11] واذا راى بعض المسلمين تجاره او شيئا من لهو الدنيا وزينتها تفرقوا اليها، وتركوك -ايها النبي- قائما على المنبر تخطب، قل لهم -ايها النبي-: ما عند الله من الثواب والنعيم انفع لكم من اللهو ومن التجاره، والله -وحده- خير من رزق واعطى، فاطلبوا منه، واستعينوا بطاعته على نيل ما عنده من خيري الدنيا والاخره."},{"id":"5189","s":63,"a":1,"at":"اذا جاءك المنافقون قالوا نشهد انك لرسول الله والله يعلم انك لرسوله والله يشهد ان المنافقين لكاذبون","dt":"[1] اذا حضر مجلسك المنافقون -ايها الرسول- قالوا بالسنتهم: نشهد انك لرسول الله، والله يعلم انك لرسول الله، والله يشهد ان المنافقين لكاذبون فيما اظهروه من شهادتهم لك، وحلفوا عليه بالسنتهم، واضمروا الكفر به."},{"id":"5190","s":63,"a":2,"at":"اتخذوا ايمانهم جنه فصدوا عن سبيل الله انهم ساء ما كانوا يعملون","dt":"[2] انما جعل المنافقون ايمانهم التي اقسموها ستره ووقايه لهم من المؤاخذه والعذاب، ومنعوا انفسهم، ومنعوا الناس عن طريق الله المستقيم، انهم بئس ما كانوا يعملون؛"},{"id":"5191","s":63,"a":3,"at":"ذلك بانهم امنوا ثم كفروا فطبع على قلوبهم فهم لا يفقهون","dt":"[3] ذلك لانهم امنوا في الظاهر، ثم كفروا في الباطن، فختم الله على قلوبهم بسبب كفرهم، فهم لا يفهمون ما فيه صلاحهم."},{"id":"5192","s":63,"a":4,"at":"واذا رايتهم تعجبك اجسامهم وان يقولوا تسمع لقولهم كانهم خشب مسنده يحسبون كل صيحه عليهم هم العدو فاحذرهم قاتلهم الله انى يؤفكون","dt":"[4] واذا نظرت الى هؤلاء المنافقين تعجبك هيئاتهم ومناظرهم، وان يتحدثوا تسمع لحديثهم؛ لفصاحه السنتهم، وهم لفراغ قلوبهم من الايمان، وعقولهم من الفهم والعلم النافع كالاخشاب الملقاه على الحائط، التي لا حياه فيها، يظنون كل صوت عال واقعا عليهم وضارا بهم؛ لعلمهم بحقيقه حالهم، ولشده جبنهم، والرعب الذي تمكن من قلوبهم، هم الاعداء الحقيقيون الشديدو العداوه لك وللمؤمنين، فخذ حذرك منهم، اخزاهم الله وطردهم من رحمته، كيف ينصرفون عن الحق الى ما هم فيه من النفاق والضلال؟"},{"id":"5193","s":63,"a":5,"at":"واذا قيل لهم تعالوا يستغفر لكم رسول الله لووا رءوسهم ورايتهم يصدون وهم مستكبرون","dt":"[5] واذا قيل لهؤلاء المنافقين: اقبلوا تائبين معتذرين عما بدر منكم من سيئ القول وسفه الحديث، يستغفر لكم رسول الله ويسال الله لكم المغفره والعفو عن ذنوبكم، امالوا رؤوسهم وحركوها استهزاء واستكبارا، وابصرتهم -ايها الرسول- يعرضون عنك، وهم مستكبرون عن الامتثال لما طلب اليهم."},{"id":"5194","s":63,"a":6,"at":"سواء عليهم استغفرت لهم ام لم تستغفر لهم لن يغفر الله لهم ان الله لا يهدي القوم الفاسقين","dt":"[6] سواء على هؤلاء المنافقين اطلبت لهم المغفره من الله -ايها الرسول- ام لم تطلب لهم، ان الله لن يصفح عن ذنوبهم ابدا؛ لاصرارهم على الفسق ورسوخهم في الكفر. ان الله لا يوفق للايمان القوم الكافرين به، الخارجين عن طاعته."},{"id":"5195","s":63,"a":7,"at":"هم الذين يقولون لا تنفقوا على من عند رسول الله حتى ينفضوا ولله خزائن السموات والارض ولكن المنافقين لا يفقهون","dt":"[7] هؤلاء المنافقون هم الذين يقولون لاهل «المدينه»: لا تنفقوا على اصحاب رسول الله من المهاجرين حتى يتفرقوا عنه. ولله وحده خزائن السموات والارض وما فيهما من ارزاق، يعطيها من يشاء ويمنعها عمن يشاء، ولكن المنافقين لا يفهمون ان الرزق من عند الله؛ لجهلهم به سبحانه وتعالى."},{"id":"5196","s":63,"a":8,"at":"يقولون لئن رجعنا الى المدينه ليخرجن الاعز منها الاذل ولله العزه ولرسوله وللمؤمنين ولكن المنافقين لا يعلمون","dt":"[8] يقول هؤلاء المنافقون: لئن عدنا الى «المدينه» ليخرجن فريقنا الاعز منها فريق المؤمنين الاذل، ولله تعالى العزه ولرسوله -صلى الله عليه وسلم-، وللمؤمنين بالله ورسوله لا لغيرهم، ولكن المنافقين لا يعلمون ذلك؛ لكثره جهلهم."},{"id":"5197","s":63,"a":9,"at":"ياايها الذين امنوا لا تلهكم اموالكم ولا اولادكم عن ذكر الله ومن يفعل ذلك فاولئك هم الخاسرون","dt":"[9] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، لا تشغلكم اموالكم ولا اولادكم عن عباده الله وطاعته، ومن تشغله امواله واولاده عن ذلك، فاولئك هم الذين تغبن حظوظهم من كرامه الله ورحمته."},{"id":"5198","s":63,"a":10,"at":"وانفقوا من ما رزقناكم من قبل ان ياتي احدكم الموت فيقول رب لولا اخرتني الى اجل قريب فاصدق واكن من الصالحين","dt":"[10] وانفقوا -ايها المؤمنون- بالله ورسوله بعض ما اعطيناكم في طرق الخير، مبادرين بذلك من قبل ان يجيء احدكم الموت، ويرى دلائله وعلاماته، فيقول نادما: رب هلا امهلتني، واجلت موتي الى وقت قصير، فاتصدق من مالي، واكن من الصالحين الاتقياء."},{"id":"5199","s":63,"a":11,"at":"ولن يؤخر الله نفسا اذا جاء اجلها والله خبير بما تعملون","dt":"[11] ولن يؤخر الله نفسا اذا جاء وقت موتها، وانقضى عمرها، والله سبحانه خبير بالذي تعملونه من خير وشر، وسيجازيكم على ذلك."},{"id":"5200","s":64,"a":1,"at":"يسبح لله ما في السموات وما في الارض له الملك وله الحمد وهو على كل شيء قدير","dt":"[1] ينزه الله عما لا يليق به كل ما في السموات وما في الارض، له سبحانه التصرف المطلق في كل شيء، وله الثناء الحسن الجميل، وهو على كل شيء قدير."},{"id":"5201","s":64,"a":2,"at":"هو الذي خلقكم فمنكم كافر ومنكم مؤمن والله بما تعملون بصير","dt":"[2] الله هو الذي اوجدكم من العدم، فبعضكم جاحد لالوهيته، وبعضكم مصدق به عامل بشرعه، وهو سبحانه بصير باعمالكم لا يخفى عليه شيء منها، وسيجازيكم بها."},{"id":"5202","s":64,"a":3,"at":"خلق السموات والارض بالحق وصوركم فاحسن صوركم واليه المصير","dt":"[3] خلق الله السموات والارض بالحكمه البالغه، وخلقكم في احسن صوره، واليه المرجع يوم القيامه، فيجازي كلا بعمله."},{"id":"5203","s":64,"a":4,"at":"يعلم ما في السموات والارض ويعلم ما تسرون وما تعلنون والله عليم بذات الصدور","dt":"[4] يعلم سبحانه وتعالى كل ما في السموات والارض، ويعلم ما تخفونه -ايها الناس- فيما بينكم وما تظهرونه. والله عليم بما تضمره الصدور وما تخفيه النفوس."},{"id":"5204","s":64,"a":5,"at":"الم ياتكم نبا الذين كفروا من قبل فذاقوا وبال امرهم ولهم عذاب اليم","dt":"[5] الم ياتكم -ايها المشركون- خبر الذين كفروا من الامم الماضيه قبلكم، اذ حل بهم سوء عاقبه كفرهم وسوء افعالهم في الدنيا، ولهم في الاخره عذاب اليم موجع؟"},{"id":"5205","s":64,"a":6,"at":"ذلك بانه كانت تاتيهم رسلهم بالبينات فقالوا ابشر يهدوننا فكفروا وتولوا واستغنى الله والله غني حميد","dt":"[6] ذلك الذي اصابهم في الدنيا، وما يصيبهم في الاخره؛ بسبب انهم كانت تاتيهم رسل الله بالايات البينات والمعجزات الواضحات، فقالوا منكرين: ابشر مثلنا يرشدوننا؟ فكفروا بالله وجحدوا رساله رسله، واعرضوا عن الحق فلم يقبلوه، واستغنى الله عن ايمانهم وعبادتهم، والله غني، له الغنى التام المطلق، حميد في اقواله وافعاله وصفاته لا يبالي بهم، ولا يضره ضلالهم شيئا."},{"id":"5206","s":64,"a":7,"at":"زعم الذين كفروا ان لن يبعثوا قل بلى وربي لتبعثن ثم لتنبؤن بما عملتم وذلك على الله يسير","dt":"[7] ادعى الذين كفروا بالله باطلا انهم لن يخرجوا من قبورهم بعد الموت، قل لهم -ايها الرسول-: بلى وربي لتخرجن من قبوركم احياء، ثم لتخبرن بالذي عملتم في الدنيا، وذلك على الله يسير هين."},{"id":"5207","s":64,"a":8,"at":"فامنوا بالله ورسوله والنور الذي انزلنا والله بما تعملون خبير","dt":"[8] فامنوا بالله ورسوله -ايها المشركون- واهتدوا بالقران الذي انزله على رسوله، والله بما تفعلون خبير لا يخفى عليه شيء من اعمالكم واقوالكم، وهو مجازيكم عليها يوم القيامه."},{"id":"5208","s":64,"a":9,"at":"يوم يجمعكم ليوم الجمع ذلك يوم التغابن ومن يؤمن بالله ويعمل صالحا يكفر عنه سيئاته ويدخله جنات تجري من تحتها الانهار خالدين فيها ابدا ذلك الفوز العظيم","dt":"[9] اذكروا يوم الحشر الذي يحشر الله فيه الاولين والاخرين، ذلك اليوم الذي يظهر فيه الغبن والتفاوت بين الخلق، فيغبن المؤمنون الكفار والفاسقين: فاهل الايمان يدخلون الجنه برحمه الله، واهل الكفر يدخلون النار بعدل الله. ومن يؤمن بالله ويعمل بطاعته، يمح عنه ذنوبه، ويدخله جنات تجري من تحت قصورها واشجارها الانهار، خالدين فيها ابدا، ذلك الخلود في الجنات هو الفوز العظيم الذي لا فوز بعده."},{"id":"5209","s":64,"a":10,"at":"والذين كفروا وكذبوا باياتنا اولئك اصحاب النار خالدين فيها وبئس المصير","dt":"[10] والذين جحدوا ان الله هو الاله الحق وكذبوا بدلائل ربوبيته وبراهين الوهيته التي ارسل بها رسله، اولئك اهل النار ماكثين فيها ابدا، وساء المرجع الذي صاروا اليه، وهو جهنم."},{"id":"5210","s":64,"a":11,"at":"ما اصاب من مصيبه الا باذن الله ومن يؤمن بالله يهد قلبه والله بكل شيء عليم","dt":"[11] ما اصاب احدا شيء من مكروه يحل به الا باذن الله وقضائه وقدره. ومن يؤمن بالله يهد قلبه للتسليم بامره والرضا بقضائه، ويهده لاحسن الاقوال والافعال والاحوال؛ لان اصل الهدايه للقلب، والجوارح تبع. والله بكل شيء عليم، لا يخفى عليه شيء من ذلك."},{"id":"5211","s":64,"a":12,"at":"واطيعوا الله واطيعوا الرسول فان توليتم فانما على رسولنا البلاغ المبين","dt":"[12] واطيعوا الله -ايها الناس- وانقادوا اليه فيما امر به ونهى عنه، واطيعوا الرسول -صلى الله عليه وسلم-، فيما بلغكم به عن ربه، فان اعرضتم عن طاعه الله ورسوله، فليس على رسولنا ضرر في اعراضكم، وانما عليه ان يبلغكم ما ارسل به بلاغا واضح البيان."},{"id":"5212","s":64,"a":13,"at":"الله لا اله الا هو وعلى الله فليتوكل المؤمنون","dt":"[13] الله وحده لا معبود بحق سواه، وعلى الله فليعتمد المؤمنون بوحدانيته في كل امورهم."},{"id":"5213","s":64,"a":14,"at":"ياايها الذين امنوا ان من ازواجكم واولادكم عدوا لكم فاحذروهم وان تعفوا وتصفحوا وتغفروا فان الله غفور رحيم","dt":"[14] يا ايها الذين امنوا بالله ورسوله، ان من ازواجكم واولادكم اعداء لكم يصدونكم عن سبيل الله، ويثبطونكم عن طاعته، فكونوا منهم على حذر، ولا تطيعوهم، وان تتجاوزوا عن سيئاتهم وتعرضوا عنها، وتستروها عليهم، فان الله غفور رحيم، يغفر لكم ذنوبكم؛ لانه سبحانه عظيم الغفران واسع الرحمه."},{"id":"5214","s":64,"a":15,"at":"انما اموالكم واولادكم فتنه والله عنده اجر عظيم","dt":"[15] ما اموالكم ولا اولادكم الا بلاء واختبار لكم. والله عنده ثواب عظيم لمن اثر طاعته على طاعه غيره، وادى حق الله في ماله."},{"id":"5215","s":64,"a":16,"at":"فاتقوا الله ما استطعتم واسمعوا واطيعوا وانفقوا خيرا لانفسكم ومن يوق شح نفسه فاولئك هم المفلحون","dt":"[16] فابذلوا -ايها المؤمنون- في تقوى الله جهدكم وطاقتكم، واسمعوا لرسول الله -صلى الله عليه وسلم- سماع تدبر وتفكر، واطيعوا اوامره واجتنبوا نواهيه، وانفقوا مما رزقكم الله يكن خيرا لكم. ومن سلم من البخل ومنع الفضل من المال، فاولئك هم الظافرون بكل خير، الفائزون بكل مطلب."},{"id":"5216","s":64,"a":17,"at":"ان تقرضوا الله قرضا حسنا يضاعفه لكم ويغفر لكم والله شكور حليم","dt":"[17] ان تنفقوا اموالكم في سبيل الله باخلاص وطيب نفس، يضاعف الله ثواب ما انفقتم، ويغفر لكم ذنوبكم. والله شكور لاهل الانفاق بحسن الجزاء على ما انفقوا، حليم لا يعجل بالعقوبه على من عصاه."},{"id":"5217","s":64,"a":18,"at":"عالم الغيب والشهاده العزيز الحكيم","dt":"[18] وهو سبحانه العالم بكل ما غاب وما حضر، العزيز الذي لا يغالب، الحكيم في اقواله وافعاله."},{"id":"5218","s":65,"a":1,"at":"ياايها النبي اذا طلقتم النساء فطلقوهن لعدتهن واحصوا العده واتقوا الله ربكم لا تخرجوهن من بيوتهن ولا يخرجن الا ان ياتين بفاحشه مبينه وتلك حدود الله ومن يتعد حدود الله فقد ظلم نفسه لا تدري لعل الله يحدث بعد ذلك امرا","dt":"[1] يا ايها النبي اذا اردتم -انت والمؤمنون- ان تطلقوا نساءكم فطلقوهن مستقبلات لعدتهن -اي في طهر لم يقع فيه جماع، او في حمل ظاهر- واحفظوا العده؛ لتعلموا وقت الرجعه ان اردتم ان تراجعوهن، وخافوا الله ربكم، لا تخرجوا المطلقات من البيوت التي يسكن فيها الى ان تنقضي عدتهن، وهي ثلاث حيضات لغير الصغيره والايسه والحامل، ولا يجوز لهن الخروج منها بانفسهن، الا اذا فعلن فعله منكره ظاهره كالزنى، وتلك احكام الله التي شرعها لعباده، ومن يتجاوز احكام الله فقد ظلم نفسه، واوردها مورد الهلاك. لا تدري -ايها المطلق-: لعل الله يحدث بعد ذلك الطلاق امرا لا تتوقعه فتراجعها."},{"id":"5219","s":65,"a":2,"at":"فاذا بلغن اجلهن فامسكوهن بمعروف او فارقوهن بمعروف واشهدوا ذوي عدل منكم واقيموا الشهاده لله ذلكم يوعظ به من كان يؤمن بالله واليوم الاخر ومن يتق الله يجعل له مخرجا","dt":"[2] فاذا قاربت المطلقات نهايه عدتهن فراجعوهن مع حسن المعاشره، والانفاق عليهن، او فارقوهن مع ايفاء حقهن، دون المضاره بهن، واشهدوا على الرجعه او المفارقه رجلين عدلين منكم، وادوا -ايها الشهود- الشهاده خالصه لله لا لشيء اخر، ذلك الذي امركم الله به يوعظ به من كان يؤمن بالله واليوم الاخر. ومن يخف الله فيعمل بما امره به، ويجتنب ما نهاه عنه، يجعل له مخرجا من كل ضيق،"},{"id":"5220","s":65,"a":3,"at":"ويرزقه من حيث لا يحتسب ومن يتوكل على الله فهو حسبه ان الله بالغ امره قد جعل الله لكل شيء قدرا","dt":"[3] وييسر له اسباب الرزق من حيث لا يخطر على باله، ولا يكون في حسبانه. ومن يتوكل على الله فهو كافيه ما اهمه في جميع اموره. ان الله بالغ امره، لا يفوته شيء، ولا يعجزه مطلوب، قد جعل الله لكل شيء اجلا ينتهي اليه، وتقديرا لا يجاوزه."},{"id":"5221","s":65,"a":4,"at":"واللائي يئسن من المحيض من نسائكم ان ارتبتم فعدتهن ثلاثه اشهر واللائي لم يحضن واولات الاحمال اجلهن ان يضعن حملهن ومن يتق الله يجعل له من امره يسرا","dt":"[4] والنساء المطلقات اللاتي انقطع عنهن دم الحيض؛ لكبر سنهن، ان شككتم فلم تدروا ما الحكم فيهن؟ فعدتهن ثلاثه اشهر، والصغيرات اللاتي لم يحضن، فعدتهن ثلاثه اشهر كذلك. وذوات الحمل من النساء عدتهن ان يضعن حملهن. ومن يخف الله، فينفذ احكامه، يجعل له من امره يسرا في الدنيا والاخره."},{"id":"5222","s":65,"a":5,"at":"ذلك امر الله انزله اليكم ومن يتق الله يكفر عنه سيئاته ويعظم له اجرا","dt":"[5] ذلك الذي ذكر من امر الطلاق والعده امر الله الذي انزله اليكم -ايها الناس-؛ لتعملوا به. ومن يخف الله فيتقه باجتناب معاصيه، واداء فرائضه، يمح عنه ذنوبه، ويجزل له الثواب في الاخره، ويدخله الجنه."},{"id":"5223","s":65,"a":6,"at":"اسكنوهن من حيث سكنتم من وجدكم ولا تضاروهن لتضيقوا عليهن وان كن اولات حمل فانفقوا عليهن حتى يضعن حملهن فان ارضعن لكم فاتوهن اجورهن واتمروا بينكم بمعروف وان تعاسرتم فسترضع له اخرى","dt":"[6] اسكنوا المطلقات من نسائكم في اثناء عدتهن مثل سكناكم على قدر سعتكم وطاقتكم، ولا تلحقوا بهن ضررا؛ لتضيقوا عليهن في المسكن، وان كان نساؤكم المطلقات ذوات حمل، فانفقوا عليهن في عدتهن حتى يضعن حملهن، فان ارضعن لكم اولادهن منكم باجره، فوفوهن اجورهن، وليامر بعضكم بعضا بما عرف من سماحه وطيب نفس، وان لم تتفقوا على ارضاع الام، فسترضع للاب مرضعه اخرى غير الام المطلقه."},{"id":"5224","s":65,"a":7,"at":"لينفق ذو سعه من سعته ومن قدر عليه رزقه فلينفق مما اتاه الله لا يكلف الله نفسا الا ما اتاها سيجعل الله بعد عسر يسرا","dt":"[7] لينفق الزوج مما وسع الله عليه على زوجته المطلقه، وعلى ولده اذا كان الزوج ذا سعه في الرزق، ومن ضيق عليه في الرزق وهو الفقير، فلينفق مما اعطاه الله من الرزق، لا يكلف الفقير مثل ما يكلف الغني، سيجعل الله بعد ضيق وشده سعه وغنى."},{"id":"5225","s":65,"a":8,"at":"وكاين من قريه عتت عن امر ربها ورسله فحاسبناها حسابا شديدا وعذبناها عذابا نكرا","dt":"[8] وكثير من القرى عصى اهلها امر الله وامر رسله وتمادوا في طغيانهم وكفرهم، فحاسبناهم على اعمالهم في الدنيا حسابا شديدا، وعذبناهم عذابا عظيما منكرا،"},{"id":"5226","s":65,"a":9,"at":"فذاقت وبال امرها وكان عاقبه امرها خسرا","dt":"[9] فتجرعوا سوء عاقبه عتوهم وكفرهم، وكان عاقبه كفرهم هلاكا وخسرانا لا خسران بعده."},{"id":"5227","s":65,"a":10,"at":"اعد الله لهم عذابا شديدا فاتقوا الله يااولي الالباب الذين امنوا قد انزل الله اليكم ذكرا","dt":"[10] اعد الله لهؤلاء القوم الذين طغوا، وخالفوا امره وامر رسله، عذابا بالغ الشده، فخافوا الله واحذروا سخطه يا اصحاب العقول الراجحه الذين صدقوا الله ورسله وعملوا بشرعه. قد انزل الله اليكم -ايها المؤمنون- ذكرا يذكركم به، وينبهكم على حظكم من الايمان بالله والعمل بطاعته."},{"id":"5228","s":65,"a":11,"at":"رسولا يتلو عليكم ايات الله مبينات ليخرج الذين امنوا وعملوا الصالحات من الظلمات الى النور ومن يؤمن بالله ويعمل صالحا يدخله جنات تجري من تحتها الانهار خالدين فيها ابدا قد احسن الله له رزقا","dt":"[11] وهذا الذكر هو الرسول يقرا عليكم ايات الله موضحات لكم الحق من الباطل؛ كي يخرج الذين صدقوا الله ورسوله، وعملوا بما امرهم الله به واطاعوه من ظلمات الكفر الى نور الايمان، ومن يؤمن بالله ويعمل عملا صالحا، يدخله جنات تجري من تحت قصورها واشجارها الانهار، ماكثين فيها ابدا، قد احسن الله للمؤمن الصالح رزقه في الجنه."},{"id":"5229","s":65,"a":12,"at":"الله الذي خلق سبع سموات ومن الارض مثلهن يتنزل الامر بينهن لتعلموا ان الله على كل شيء قدير وان الله قد احاط بكل شيء علما","dt":"[12] الله وحده هو الذي خلق سبع سموات، وخلق سبعا من الارضين، وانزل الامر مما اوحاه الله الى رسله وما يدبر به احوال خلقه بين السموات والارض؛ لتعلموا -ايها الناس- ان الله على كل شيء قدير لا يعجزه شيء، وان الله قد احاط بكل شيء علما، فلا يخرج شيء عن علمه وقدرته."},{"id":"5230","s":66,"a":1,"at":"ياايها النبي لم تحرم ما احل الله لك تبتغي مرضات ازواجك والله غفور رحيم","dt":"[1] يا ايها النبي لم تمنع نفسك عن الحلال الذي احله الله لك، تبتغي ارضاء زوجاتك؟ والله غفور لك، رحيم بك."},{"id":"5231","s":66,"a":2,"at":"قد فرض الله لكم تحله ايمانكم والله مولاكم وهو العليم الحكيم","dt":"[2] قد شرع الله لكم -ايها المؤمنون- تحليل ايمانكم باداء الكفاره عنها، وهي: اطعام عشره مساكين، او كسوتهم، او تحرير رقبه، فمن لم يجد فصيام ثلاثه ايام. والله ناصركم ومتولي اموركم، وهو العليم بما يصلحكم فيشرعه لكم، الحكيم في اقواله وافعاله."},{"id":"5232","s":66,"a":3,"at":"واذ اسر النبي الى بعض ازواجه حديثا فلما نبات به واظهره الله عليه عرف بعضه واعرض عن بعض فلما نباها به قالت من انباك هذا قال نباني العليم الخبير","dt":"[3] واذ اسر النبي الى زوجته حفصه -رضي الله عنها- حديثا، فلما اخبرت به عائشه رضي الله عنها، واطلعه الله على افشائها سره، اعلم حفصه بعض ما اخبرت به، واعرض عن اعلامها بعضه تكرما، فلما اخبرها بما افشت من الحديث، قالت: من اخبرك بهذا؟ قال: اخبرني به الله العليم الخبير، الذي لا تخفى عليه خافيه."},{"id":"5233","s":66,"a":4,"at":"ان تتوبا الى الله فقد صغت قلوبكما وان تظاهرا عليه فان الله هو مولاه وجبريل وصالح المؤمنين والملائكه بعد ذلك ظهير","dt":"[4] ان ترجعا -يا حفصه وعائشه- الى الله فقد وجد منكما ما يوجب التوبه، حيث مالت قلوبكما الى محبه ما كرهه رسول الله -صلى الله عليه وسلم- من افشاء سره، وان تتعاونا عليه بما يسوءه، فان الله وليه وناصره، وجبريل، وصالح المؤمنين، والملائكه بعد نصره الله اعوان له ونصراء على من يؤذيه ويعاديه."},{"id":"5234","s":66,"a":5,"at":"عسى ربه ان طلقكن ان يبدله ازواجا خيرا منكن مسلمات مؤمنات قانتات تائبات عابدات سائحات ثيبات وابكارا","dt":"[5] عسى ربه ان طلقكن -ايتها الزوجات- ان يزوجه بدلا منكن زوجات خاضعات لله بالطاعه، مؤمنات بالله ورسوله، مطيعات لله، راجعات الى ما يحبه الله من طاعته، كثيرات العباده له، صائمات، منهن الثيبات، ومنهن الابكار."},{"id":"5235","s":66,"a":6,"at":"ياايها الذين امنوا قوا انفسكم واهليكم نارا وقودها الناس والحجاره عليها ملائكه غلاظ شداد لا يعصون الله ما امرهم ويفعلون ما يؤمرون","dt":"[6] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، احفظوا انفسكم بفعل ما امركم الله به وترك ما نهاكم عنه، واحفظوا اهليكم بما تحفظون به انفسكم من نار وقودها الناس والحجاره، يقوم على تعذيب اهلها ملائكه اقوياء قساه في معاملاتهم، لا يخالفون الله في امره، وينفذون ما يؤمرون به."},{"id":"5236","s":66,"a":7,"at":"ياايها الذين كفروا لا تعتذروا اليوم انما تجزون ما كنتم تعملون","dt":"[7] ويقال للذين جحدوا ان الله هو الاله الحق وكفروا به عند ادخالهم النار: لا تلتمسوا المعاذير في هذا اليوم؛ انما تعطون جزاء الذي كنتم تعملونه في الدنيا."},{"id":"5237","s":66,"a":8,"at":"ياايها الذين امنوا توبوا الى الله توبه نصوحا عسى ربكم ان يكفر عنكم سيئاتكم ويدخلكم جنات تجري من تحتها الانهار يوم لا يخزي الله النبي والذين امنوا معه نورهم يسعى بين ايديهم وبايمانهم يقولون ربنا اتمم لنا نورنا واغفر لنا انك على كل شيء قدير","dt":"[8] يا ايها الذين صدقوا الله ورسوله وعملوا بشرعه، ارجعوا عن ذنوبكم الى طاعه الله رجوعا لا معصيه بعده، عسى ربكم ان يمحو عنكم سيئات اعمالكم، وان يدخلكم جنات تجري من تحت قصورها واشجارها الانهار، يوم لا يخزي الله النبي والذين امنوا معه، ولا يعذبهم، بل يعلي شانهم، نور هؤلاء يسير امامهم وبايمانهم حال مشيهم على الصراط بقدر اعمالهم، يقولون: ربنا اتمم لنا نورنا حتى نجوز الصراط، ونهتدي الى الجنه، واعف عنا وتجاوز عن ذنوبنا واسترها علينا، انك على كل شيء قدير."},{"id":"5238","s":66,"a":9,"at":"ياايها النبي جاهد الكفار والمنافقين واغلظ عليهم وماواهم جهنم وبئس المصير","dt":"[9] يا ايها النبي جاهد الذين اظهروا الكفر واعلنوه، وقاتلهم بالسيف، وجاهد الذين ابطنوا الكفر واخفوه بالحجه واقامه الحدود وشعائر الدين، واستعمل مع الفريقين الشده والخشونه في جهادهما. ومسكنهم الذي يصيرون اليه في الاخره جهنم، وقبح ذلك المرجع الذي يرجعون اليه."},{"id":"5239","s":66,"a":10,"at":"ضرب الله مثلا للذين كفروا امراه نوح وامراه لوط كانتا تحت عبدين من عبادنا صالحين فخانتاهما فلم يغنيا عنهما من الله شيئا وقيل ادخلا النار مع الداخلين","dt":"[10] ضرب الله مثلا لحال الكفره -في مخالطتهم المسلمين وقربهم منهم ومعاشرتهم لهم، وان ذلك لا ينفعهم لكفرهم بالله- بحال زوجه نبي الله نوح، وزوجه نبي الله لوط: حيث كانتا في عصمه عبدين من عبادنا صالحين، فوقعت منهما الخيانه لهما في الدين، فقد كانتا كافرتين، فلم يدفع هذان الرسولان عن زوجتيهما من عذاب الله شيئا، وقيل للزوجتين: ادخلا النار مع الداخلين فيها.وفي ضرب هذا المثل دليل على ان القرب من الانبياء، والصالحين، لا يفيد شيئا مع العمل السيئ."},{"id":"5240","s":66,"a":11,"at":"وضرب الله مثلا للذين امنوا امراه فرعون اذ قالت رب ابن لي عندك بيتا في الجنه ونجني من فرعون وعمله ونجني من القوم الظالمين","dt":"[11] وضرب الله مثلا لحال المؤمنين -الذين صدقوا الله، وعبدوه وحده، وعملوا بشرعه، وانهم لا تضرهم مخالطه الكافرين في معاملتهم- بحال زوجه فرعون التي كانت في عصمه اشد الكافرين بالله، وهي مؤمنه بالله، حين قالت: رب ابن لي دارا عندك في الجنه، وانقذني من سلطان فرعون وفتنته ، ومما يصدر عنه من اعمال الشر، وانقذني من القوم التابعين له في الظلم والضلال، ومن عذابهم."},{"id":"5241","s":66,"a":12,"at":"ومريم ابنه عمران التي احصنت فرجها فنفخنا فيه من روحنا وصدقت بكلمات ربها وكتبه وكانت من القانتين","dt":"[12] وضرب الله مثلا للذين امنوا مريم بنت عمران التي حفظت فرجها، وصانته عن الزنى، فامر الله تعالى جبريل عليه السلام ان ينفخ في جيب قميصها، فوصلت النفخه الى رحمها، فحملت بعيسى عليه السلام، وصدقت بكلمات ربها، وعملت بشرائعه التي شرعها لعباده، وكتبه المنزله على رسله، وكانت من المطيعين له."},{"id":"5242","s":67,"a":1,"at":"تبارك الذي بيده الملك وهو على كل شيء قدير","dt":"[1] تكاثر خير الله وبره على جميع خلقه، الذي بيده ملك الدنيا والاخره وسلطانهما، نافذ فيهما امره وقضاؤه، وهو على كل شيء قدير.ويستفاد من الايه ثبوت صفه اليد لله سبحانه وتعالى على ما يليق بجلاله."},{"id":"5243","s":67,"a":2,"at":"الذي خلق الموت والحياه ليبلوكم ايكم احسن عملا وهو العزيز الغفور","dt":"[2] الذي خلق الموت والحياه؛ ليختبركم -ايها الناس-: ايكم خير عملا واخلصه؟ وهو العزيز الذي لا يعجزه شيء، الغفور لمن تاب من عباده.وفي الايه ترغيب في فعل الطاعات، وزجر عن اقتراف المعاصي."},{"id":"5244","s":67,"a":3,"at":"الذي خلق سبع سموات طباقا ما ترى في خلق الرحمن من تفاوت فارجع البصر هل ترى من فطور","dt":"[3] الذي خلق سبع سموات متناسقه، بعضها فوق بعض، ما ترى في خلق الرحمن -ايها الناظر- من اختلاف ولا تباين، فاعد النظر الى السماء: هل ترى فيها من شقوق او صدوع؟"},{"id":"5245","s":67,"a":4,"at":"ثم ارجع البصر كرتين ينقلب اليك البصر خاسئا وهو حسير","dt":"[4] ثم اعد النظر مره بعد مره، يرجع اليك البصر ذليلا صاغرا عن ان يرى نقصا، وهو متعب كليل."},{"id":"5246","s":67,"a":5,"at":"ولقد زينا السماء الدنيا بمصابيح وجعلناها رجوما للشياطين واعتدنا لهم عذاب السعير","dt":"[5] ولقد زينا السماء القريبه التي تراها العيون بنجوم عظيمه مضيئه، وجعلناها شهبا محرقه لمسترقي السمع من الشياطين، واعتدنا لهم في الاخره عذاب النار الموقده يقاسون حرها."},{"id":"5247","s":67,"a":6,"at":"وللذين كفروا بربهم عذاب جهنم وبئس المصير","dt":"[6] وللكافرين بخالقهم عذاب جهنم، وساء المرجع لهم جهنم."},{"id":"5248","s":67,"a":7,"at":"اذا القوا فيها سمعوا لها شهيقا وهي تفور","dt":"[7] اذا طرح هؤلاء الكافرون في جهنم سمعوا لها صوتا شديدا منكرا، وهي تغلي غليانا شديدا."},{"id":"5249","s":67,"a":8,"at":"تكاد تميز من الغيظ كلما القي فيها فوج سالهم خزنتها الم ياتكم نذير","dt":"[8] تكاد جهنم تتمزق من شده غضبها على الكفار، كلما طرح فيها جماعه من الناس سالهم الموكلون بامرها على سبيل التوبيخ: الم ياتكم في الدنيا رسول يحذركم هذا العذاب الذي انتم فيه؟"},{"id":"5250","s":67,"a":9,"at":"قالوا بلى قد جاءنا نذير فكذبنا وقلنا ما نزل الله من شيء ان انتم الا في ضلال كبير","dt":"[9] اجابوهم قائلين: بلى قد جاءنا رسول من عند الله وحذرنا، فكذبناه، وقلنا فيما جاء به من الايات: ما نزل الله على احد من البشر شيئا، ما انتم -ايها الرسل- الا في ذهاب بعيد عن الحق."},{"id":"5251","s":67,"a":10,"at":"وقالوا لو كنا نسمع او نعقل ما كنا في اصحاب السعير","dt":"[10] وقالوا معترفين: لو كنا نسمع سماع من يطلب الحق، او نفكر فيما ندعى اليه، ما كنا في عداد اهل النار."},{"id":"5252","s":67,"a":11,"at":"فاعترفوا بذنبهم فسحقا لاصحاب السعير","dt":"[11] فاعترفوا بتكذيبهم وكفرهم الذي استحقوا به عذاب النار، فبعدا لاهل النار عن رحمه الله."},{"id":"5253","s":67,"a":12,"at":"ان الذين يخشون ربهم بالغيب لهم مغفره واجر كبير","dt":"[12] ان الذين يخافون ربهم، فيعبدونه، ولا يعصونه وهم غائبون عن اعين الناس، ويخشون العذاب في الاخره قبل معاينته، لهم عفو من الله عن ذنوبهم، وثواب عظيم وهو الجنه."},{"id":"5254","s":67,"a":13,"at":"واسروا قولكم او اجهروا به انه عليم بذات الصدور","dt":"[13] واخفوا قولكم -ايها الناس- في اي امر من اموركم او اعلنوه، فهما عند الله سواء، انه سبحانه عليم بمضمرات الصدور، فكيف تخفى عليه اقوالكم واعمالكم؟"},{"id":"5255","s":67,"a":14,"at":"الا يعلم من خلق وهو اللطيف الخبير","dt":"[14] الا يعلم رب العالمين خلقه وشؤونهم، وهو الذي خلقهم واتقن خلقهم واحسنه؟ وهو اللطيف بعباده، الخبير بهم وباعمالهم."},{"id":"5256","s":67,"a":15,"at":"هو الذي جعل لكم الارض ذلولا فامشوا في مناكبها وكلوا من رزقه واليه النشور","dt":"[15] الله وحده هو الذي جعل لكم الارض سهله ممهده تستقرون عليها، فامشوا في نواحيها وجوانبها، وكلوا من رزق الله الذي يخرجه لكم منها، واليه وحده البعث من قبوركم للحساب والجزاء.وفي الايه حث على طلب الرزق والمكاسب، وفيها دلاله على ان الله هو الاله الحق وحده لا شريك له، وعلى قدرته، والتذكير بنعمه، والتحذير من الركون الى الدنيا."},{"id":"5257","s":67,"a":16,"at":"اامنتم من في السماء ان يخسف بكم الارض فاذا هي تمور","dt":"[16] هل امنتم -يا كفار «مكه»- الله الذي فوق السماء ان يخسف بكم الارض، فاذا هي تضطرب بكم حتى تهلكوا؟"},{"id":"5258","s":67,"a":17,"at":"ام امنتم من في السماء ان يرسل عليكم حاصبا فستعلمون كيف نذير","dt":"[17] هل امنتم الله الذي فوق السماء ان يرسل عليكم ريحا ترجمكم بالحجاره الصغيره، فستعلمون -ايها الكافرون- كيف تحذيري لكم اذا عاينتم العذاب؟ ولا ينفعكم العلم حين ذلك.وفي الايه اثبات العلو لله تعالى، كما يليق بجلاله سبحانه."},{"id":"5259","s":67,"a":18,"at":"ولقد كذب الذين من قبلهم فكيف كان نكير","dt":"[18] ولقد كذب الذين كانوا قبل كفار «مكه» كقوم نوح وعاد وثمود رسلهم، فكيف كان انكاري عليهم، وتغييري ما بهم من نعمه بانزال العذاب بهم واهلاكهم؟"},{"id":"5260","s":67,"a":19,"at":"او لم يروا الى الطير فوقهم صافات ويقبضن ما يمسكهن الا الرحمن انه بكل شيء بصير","dt":"[19] اغفل هؤلاء الكافرون، ولم ينظروا الى الطير فوقهم، باسطات اجنحتها عند طيرانها في الهواء، ويضممنها الى جنوبها احيانا؟ ما يحفظها من الوقوع عند ذلك الا الرحمن. انه بكل شيء بصير، لا يرى في خلقه نقص ولا تفاوت."},{"id":"5261","s":67,"a":20,"at":"امن هذا الذي هو جند لكم ينصركم من دون الرحمن ان الكافرون الا في غرور","dt":"[20] بل من هذا الذي هو في زعمكم -ايها الكافرون- حزب لكم ينصركم من غير الرحمن، ان اراد بكم سوءا؟ ما الكافرون في زعمهم هذا الا في خداع وضلال من الشيطان."},{"id":"5262","s":67,"a":21,"at":"امن هذا الذي يرزقكم ان امسك رزقه بل لجوا في عتو ونفور","dt":"[21] بل من هذا الرازق المزعوم الذي يرزقكم ان امسك الله رزقه ومنعه عنكم؟ بل استمر الكافرون في طغيانهم وضلالهم في معانده واستكبار ونفور عن الحق، لا يسمعون له، ولا يتبعونه."},{"id":"5263","s":67,"a":22,"at":"افمن يمشي مكبا على وجهه اهدى امن يمشي سويا على صراط مستقيم","dt":"[22] افمن يمشي منكسا على وجهه لا يدري اين يسلك ولا كيف يذهب، اشد استقامه على الطريق واهدى، ام من يمشي مستويا منتصب القامه سالما على طريق واضح لا اعوجاج فيه؟ وهذا مثل ضربه الله للكافر والمؤمن."},{"id":"5264","s":67,"a":23,"at":"قل هو الذي انشاكم وجعل لكم السمع والابصار والافئده قليلا ما تشكرون","dt":"[23] قل لهم -ايها الرسول-: الله هو الذي اوجدكم من العدم، وجعل لكم السمع لتسمعوا به، والابصار لتبصروا بها، والقلوب لتعقلوا بها، قليلا -ايها الكافرون- ما تؤدون شكر هذه النعم لربكم الذي انعم بها عليكم."},{"id":"5265","s":67,"a":24,"at":"قل هو الذي ذراكم في الارض واليه تحشرون","dt":"[24] قل لهم: الله هو الذي خلقكم ونشركم في الارض، واليه وحده تجمعون بعد هذا التفرق للحساب والجزاء."},{"id":"5266","s":67,"a":25,"at":"ويقولون متى هذا الوعد ان كنتم صادقين","dt":"[25] ويقول الكافرون: متى يتحقق هذا الوعد بالحشر يا محمد؟ اخبرونا بزمانه ايها المؤمنون، ان كنتم صادقين فيما تدعون،"},{"id":"5267","s":67,"a":26,"at":"قل انما العلم عند الله وانما انا نذير مبين","dt":"[26] قل -ايها الرسول- لهؤلاء: ان العلم بوقت قيام الساعه اختص الله به، وانما انا نذير لكم اخوفكم عاقبه كفركم، وابين لكم ما امرني الله ببيانه غايه البيان."},{"id":"5268","s":67,"a":27,"at":"فلما راوه زلفه سيئت وجوه الذين كفروا وقيل هذا الذي كنتم به تدعون","dt":"[27] فلما راى الكفار عذاب الله قريبا منهم وعاينوه، ظهرت الذله والكابه على وجوههم، وقيل توبيخا لهم: هذا الذي كنتم تطلبون تعجيله في الدنيا."},{"id":"5269","s":67,"a":28,"at":"قل ارايتم ان اهلكني الله ومن معي او رحمنا فمن يجير الكافرين من عذاب اليم","dt":"[28] قل -ايها الرسول- لهؤلاء الكافرين: اخبروني ان اماتني الله ومن معي من المؤمنين كما تتمنون، او رحمنا فاخر اجالنا، وعافانا من عذابه، فمن هذا الذي يحميكم، ويمنعكم من عذاب اليم موجع؟"},{"id":"5270","s":67,"a":29,"at":"قل هو الرحمن امنا به وعليه توكلنا فستعلمون من هو في ضلال مبين","dt":"[29] قل: الله هو الرحمن صدقنا به وعملنا بشرعه، واطعناه، وعليه وحده اعتمدنا في كل امورنا، فستعلمون -ايها الكافرون- اذا نزل العذاب: اي الفريقين منا ومنكم في بعد واضح عن صراط الله المستقيم؟"},{"id":"5271","s":67,"a":30,"at":"قل ارايتم ان اصبح ماؤكم غورا فمن ياتيكم بماء معين","dt":"[30] قل -ايها الرسول- لهؤلاء المشركين: اخبروني ان صار ماؤكم الذي تشربون منه ذاهبا في الارض لا تصلون اليه بوسيله، فمن غير الله يجيئكم بماء جار على وجه الارض ظاهر للعيون؟"},{"id":"5272","s":68,"a":1,"at":"ن والقلم وما يسطرون","dt":"[1] ن سبق الكلام على الحروف المقطعه في اول سوره البقره.اقسم الله بالقلم الذي يكتب به الملائكه والناس، وبما يكتبون من الخير والنفع والعلوم."},{"id":"5273","s":68,"a":2,"at":"ما انت بنعمه ربك بمجنون","dt":"[2] ما انت -ايها الرسول- بسبب نعمه الله عليك بالنبوه والرساله بضعيف العقل، ولا سفيه الراي،"},{"id":"5274","s":68,"a":3,"at":"وان لك لاجرا غير ممنون","dt":"[3] وان لك على ما تلقاه من شدائد على تبليغ الرساله لثوابا عظيما غير منقوص ولا مقطوع،"},{"id":"5275","s":68,"a":4,"at":"وانك لعلى خلق عظيم","dt":"[4] وانك -ايها الرسول- لعلى خلق عظيم، وهو ما اشتمل عليه القران من مكارم الاخلاق؛ فقد كان امتثال القران سجيه له ياتمر بامره، وينتهي عما ينهى عنه."},{"id":"5276","s":68,"a":5,"at":"فستبصر ويبصرون","dt":"[5] فعن قريب سترى -ايها الرسول-، ويرى الكافرون"},{"id":"5277","s":68,"a":6,"at":"بايكم المفتون","dt":"[6] في ايكم الفتنه والجنون؟"},{"id":"5278","s":68,"a":7,"at":"ان ربك هو اعلم بمن ضل عن سبيله وهو اعلم بالمهتدين","dt":"[7] ان ربك -سبحانه- هو اعلم بالشقي المنحرف عن دين الله وطريق الهدى، وهو اعلم بالتقي المهتدي الى دين الحق."},{"id":"5279","s":68,"a":8,"at":"فلا تطع المكذبين","dt":"[8] فاثبت على ما انت عليه -ايها الرسول- من مخالفه المكذبين ولا تطعهم."},{"id":"5280","s":68,"a":9,"at":"ودوا لو تدهن فيدهنون","dt":"[9] تمنوا واحبوا لو تلاينهم، وتصانعهم على بعض ما هم عليه، فيلينون لك."},{"id":"5281","s":68,"a":10,"at":"ولا تطع كل حلاف مهين","dt":"[10] ولا تطع -ايها الرسول- كل انسان كثير الحلف كذاب حقير،"},{"id":"5282","s":68,"a":11,"at":"هماز مشاء بنميم","dt":"[11] مغتاب للناس، يمشي بينهم بالنميمه، وينقل حديث بعضهم الى بعض على وجه الافساد بينهم،"},{"id":"5283","s":68,"a":12,"at":"مناع للخير معتد اثيم","dt":"[12] بخيل بالمال ضنين به عن الحق، شديد المنع للخير، متجاوز حده في العدوان على الناس وتناول المحرمات، كثير الاثام،"},{"id":"5284","s":68,"a":13,"at":"عتل بعد ذلك زنيم","dt":"[13] شديد في كفره، فاحش لئيم، منسوب الى غير ابيه."},{"id":"5285","s":68,"a":14,"at":"ان كان ذا مال وبنين","dt":"[14] ومن اجل انه كان صاحب مال وبنين،"},{"id":"5286","s":68,"a":15,"at":"اذا تتلى عليه اياتنا قال اساطير الاولين","dt":"[15] طغى وتكبر عن الحق، فاذا قرا عليه احد ايات القران كذب بها، وقال: هذا اباطيل الاولين وخرافاتهم. وهذه الايات وان نزلت في بعض المشركين كالوليد بن المغيره، الا ان فيها تحذيرا للمسلم من موافقه من اتصف بهذه الصفات الذميمه."},{"id":"5287","s":68,"a":16,"at":"سنسمه على الخرطوم","dt":"[16] سنجعل على انفه علامه لازمه لا تفارقه عقوبه له؛ ليكون مفتضحا بها امام الناس."},{"id":"5288","s":68,"a":17,"at":"انا بلوناهم كما بلونا اصحاب الجنه اذ اقسموا ليصرمنها مصبحين","dt":"[17] انا اختبرنا اهل «مكه» بالجوع والقحط، كما اختبرنا اصحاب الحديقه حين حلفوا فيما بينهم، ليقطعن ثمار حديقتهم مبكرين في الصباح، فلا يطعم منها غيرهم من المساكين ونحوهم،"},{"id":"5289","s":68,"a":18,"at":"ولا يستثنون","dt":"[18] ولم يقولوا: ان شاء الله."},{"id":"5290","s":68,"a":19,"at":"فطاف عليها طائف من ربك وهم نائمون","dt":"[19] فانزل الله عليها نارا احرقتها ليلا، وهم نائمون،"},{"id":"5291","s":68,"a":20,"at":"فاصبحت كالصريم","dt":"[20] فاصبحت محترقه سوداء كالليل المظلم."},{"id":"5292","s":68,"a":21,"at":"فتنادوا مصبحين","dt":"[21] فنادى بعضهم بعضا وقت الصباح"},{"id":"5293","s":68,"a":22,"at":"ان اغدوا على حرثكم ان كنتم صارمين","dt":"[21، 22] ان اذهبوا مبكرين الى زرعكم، ان كنتم مصرين على قطع الثمار."},{"id":"5294","s":68,"a":23,"at":"فانطلقوا وهم يتخافتون","dt":"[23] فاندفعوا مسرعين، وهم يتسارون بالحديث فيما بينهم"},{"id":"5295","s":68,"a":24,"at":"ان لا يدخلنها اليوم عليكم مسكين","dt":"[24] بان لا تمكنوا اليوم احدا من المحتاجين من دخول حديقتكم."},{"id":"5296","s":68,"a":25,"at":"وغدوا على حرد قادرين","dt":"[25] وساروا في اول النهار الى حديقتهم على قصدهم السيئ في منع المساكين من ثمار الحديقه، وهم في غايه القدره على تنفيذه في زعمهم."},{"id":"5297","s":68,"a":26,"at":"فلما راوها قالوا انا لضالون","dt":"[26] فلما راوا حديقتهم محترقه انكروها، وقالوا: لقد اخطانا الطريق اليها، فلما عرفوا انها هي جنتهم،"},{"id":"5298","s":68,"a":27,"at":"بل نحن محرومون","dt":"[27] ، قالوا: بل نحن محرومون خيرها؛ بسبب عزمنا على البخل ومنع المساكين."},{"id":"5299","s":68,"a":28,"at":"قال اوسطهم الم اقل لكم لولا تسبحون","dt":"[28] . قال اعدلهم: الم اقل لكم هلا تستثنون وتقولون: ان شاء الله؟"},{"id":"5300","s":68,"a":29,"at":"قالوا سبحان ربنا انا كنا ظالمين","dt":"[29] قالوا بعد ان عادوا الى رشدهم: تنزه الله ربنا عن الظلم فيما اصابنا، بل نحن كنا الظالمين لانفسنا بترك الاستثناء وقصدنا السيئ."},{"id":"5301","s":68,"a":30,"at":"فاقبل بعضهم على بعض يتلاومون","dt":"[30] فاقبل بعضهم على بعض، يلوم كل منهم الاخر على تركهم الاستثناء وعلى قصدهم السيئ،"},{"id":"5302","s":68,"a":31,"at":"قالوا ياويلنا انا كنا طاغين","dt":"[31] قالوا: يا ويلنا انا كنا متجاوزين الحد في منعنا الفقراء ومخالفه امر الله،"},{"id":"5303","s":68,"a":32,"at":"عسى ربنا ان يبدلنا خيرا منها انا الى ربنا راغبون","dt":"[32] عسى ربنا ان يعطينا افضل من حديقتنا؛ بسبب توبتنا واعترافنا بخطيئتنا. انا الى ربنا وحده راغبون، راجون العفو، طالبون الخير"},{"id":"5304","s":68,"a":33,"at":"كذلك العذاب ولعذاب الاخره اكبر لو كانوا يعلمون","dt":"[33] مثل ذلك العقاب الذي عاقبنا به اهل الحديقه يكون عقابنا في الدنيا لكل من خالف امر الله، وبخل بما اتاه الله من النعم فلم يؤد حق الله فيها، ولعذاب الاخره اعظم واشد من عذاب الدنيا، لو كانوا يعلمون لانزجروا عن كل سبب يوجب العقاب."},{"id":"5305","s":68,"a":34,"at":"ان للمتقين عند ربهم جنات النعيم","dt":"[34] ان الذين اتقوا عقاب الله بفعل ما امرهم به وترك ما نهاهم عنه، لهم عند ربهم في الاخره جنات فيها النعيم المقيم."},{"id":"5306","s":68,"a":35,"at":"افنجعل المسلمين كالمجرمين","dt":"[35] افنجعل الخاضعين لله بالطاعه كالكافرين؟"},{"id":"5307","s":68,"a":36,"at":"ما لكم كيف تحكمون","dt":"[36] ما لكم كيف حكمتم هذا الحكم الجائر، فساويتم بينهم في الثواب؟"},{"id":"5308","s":68,"a":37,"at":"ام لكم كتاب فيه تدرسون","dt":"[37] ام لكم كتاب منزل من السماء تجدون فيه المطيع كالعاصي، فانتم تدرسون فيه ما تقولون؟"},{"id":"5309","s":68,"a":38,"at":"ان لكم فيه لما تخيرون","dt":"[38] ان لكم في هذا الكتاب اذا ما تشتهون، ليس لكم ذلك."},{"id":"5310","s":68,"a":39,"at":"ام لكم ايمان علينا بالغه الى يوم القيامه ان لكم لما تحكمون","dt":"[39] ام لكم عهود ومواثيق علينا في انه سيحصل لكم ما تريدون وتشتهون؟"},{"id":"5311","s":68,"a":40,"at":"سلهم ايهم بذلك زعيم","dt":"[40] سل المشركين -ايها الرسول-: ايهم بذلك الحكم كفيل وضامن بان يكون له ذلك؟"},{"id":"5312","s":68,"a":41,"at":"ام لهم شركاء فلياتوا بشركائهم ان كانوا صادقين","dt":"[41] ام لهم الهه تكفل لهم ما يقولون، وتعينهم على ادراك ما طلبوا، فلياتوا بها ان كانوا صادقين في دعواهم؟"},{"id":"5313","s":68,"a":42,"at":"يوم يكشف عن ساق ويدعون الى السجود فلا يستطيعون","dt":"[42] يوم القيامه يشتد الامر ويصعب هوله، وياتي الله تعالى لفصل القضاء بين الخلائق، فيكشف عن ساقه الكريمه التي لا يشبهها شيء، قال -صلى الله عليه وسلم-: «يكشف ربنا عن ساقه، فيسجد له كل مؤمن ومؤمنه، ويبقى من كان يسجد في الدنيا؛ رياء وسمعه، فيذهب ليسجد، فيعود ظهره طبقا واحدا» رواه البخاري ومسلم."},{"id":"5314","s":68,"a":43,"at":"خاشعه ابصارهم ترهقهم ذله وقد كانوا يدعون الى السجود وهم سالمون","dt":"[43] منكسره ابصارهم لا يرفعونها، تغشاهم ذله شديده من عذاب الله، وقد كانوا في الدنيا يدعون الى الصلاه لله وعبادته، وهم اصحاء قادرون عليها فلا يسجدون؛ تعظما واستكبارا."},{"id":"5315","s":68,"a":44,"at":"فذرني ومن يكذب بهذا الحديث سنستدرجهم من حيث لا يعلمون","dt":"[44] فذرني -ايها الرسول- ومن يكذب بهذا القران، فان علي جزاءهم والانتقام منهم، سنمدهم بالاموال والاولاد والنعم؛ استدراجا لهم من حيث لا يشعرون انه سبب لاهلاكهم،"},{"id":"5316","s":68,"a":45,"at":"واملي لهم ان كيدي متين","dt":"[45] وامهلهم واطيل اعمارهم؛ ليزدادوا اثما. ان كيدي باهل الكفر قوي شديد."},{"id":"5317","s":68,"a":46,"at":"ام تسالهم اجرا فهم من مغرم مثقلون","dt":"[46] ام تسال -ايها الرسول- هؤلاء المشركين اجرا دنيويا على تبليغ الرساله فهم من غرامه ذلك مكلفون حملا ثقيلا؟"},{"id":"5318","s":68,"a":47,"at":"ام عندهم الغيب فهم يكتبون","dt":"[47] بل اعندهم علم الغيب، فهم يكتبون عنه ما يحكمون به لانفسهم من انهم افضل منزله عند الله من اهل الايمان به؟"},{"id":"5319","s":68,"a":48,"at":"فاصبر لحكم ربك ولا تكن كصاحب الحوت اذ نادى وهو مكظوم","dt":"[48] فاصبر -ايها الرسول- لما حكم به ربك وقضاه، ومن ذلك امهالهم وتاخير نصرتك عليهم، ولا تكن كصاحب الحوت، وهو يونس -عليه السلام- في غضبه وعدم صبره على قومه، حين نادى ربه -في ظلمه البحر وظلمه بطن الحوت-، وهو مملوء غما طالبا تعجيل العذاب لهم،"},{"id":"5320","s":68,"a":49,"at":"لولا ان تداركه نعمه من ربه لنبذ بالعراء وهو مذموم","dt":"[49] لولا ان تداركه نعمه من ربه بتوفيقه للتوبه وقبولها لطرح من بطن الحوت بالارض الفضاء المهلكه، وهو ات بما يلام عليه،"},{"id":"5321","s":68,"a":50,"at":"فاجتباه ربه فجعله من الصالحين","dt":"[50] فاصطفاه ربه لرسالته، فجعله من الصالحين الذين صلحت نياتهم واقوالهم واعمالهم."},{"id":"5322","s":68,"a":51,"at":"وان يكاد الذين كفروا ليزلقونك بابصارهم لما سمعوا الذكر ويقولون انه لمجنون","dt":"[51] وان يكاد الكفار حين سمعوا القران ليصيبونك -ايها الرسول- بالعين؛ لبغضهم اياك، لولا وقايه الله وحمايته لك، ويقولون: -حسب اهوائهم- انه لمجنون."},{"id":"5323","s":68,"a":52,"at":"وما هو الا ذكر للعالمين","dt":"[52] وما القران الا موعظه وتذكير للعالمين من الانس والجن."},{"id":"5324","s":69,"a":1,"at":"الحاقه","dt":"[1] القيامه الواقعه حقا التي يتحقق فيها الوعد والوعيد،"},{"id":"5325","s":69,"a":2,"at":"ما الحاقه","dt":"[2] ما القيامه الواقعه حقا في صفتها وحالها؟"},{"id":"5326","s":69,"a":3,"at":"وما ادراك ما الحاقه","dt":"[3] واي شيء ادراك -ايها الرسول- وعرفك حقيقه القيامه، وصور لك هولها وشدتها؟"},{"id":"5327","s":69,"a":4,"at":"كذبت ثمود وعاد بالقارعه","dt":"[4] كذبت ثمود وهم قوم صالح، وعاد وهم قوم هود بالقيامه التي تقرع القلوب باهوالها."},{"id":"5328","s":69,"a":5,"at":"فاما ثمود فاهلكوا بالطاغيه","dt":"[5] فاما ثمود فاهلكوا بالصيحه العظيمه التي جاوزت الحد في شدتها،"},{"id":"5329","s":69,"a":6,"at":"واما عاد فاهلكوا بريح صرصر عاتيه","dt":"[6] واما عاد فاهلكوا بريح بارده شديده الهبوب،"},{"id":"5330","s":69,"a":7,"at":"سخرها عليهم سبع ليال وثمانيه ايام حسوما فترى القوم فيها صرعى كانهم اعجاز نخل خاويه","dt":"[7] سلطها الله عليهم سبع ليال وثمانيه ايام متتابعه، لا تفتر ولا تنقطع، فترى القوم في تلك الليالي والايام موتى كانهم اصول نخل خربه متاكله الاجواف."},{"id":"5331","s":69,"a":8,"at":"فهل ترى لهم من باقيه","dt":"[8] فهل ترى لهؤلاء القوم من نفس باقيه دون هلاك؟"},{"id":"5332","s":69,"a":9,"at":"وجاء فرعون ومن قبله والمؤتفكات بالخاطئه","dt":"[9] وجاء الطاغيه فرعون، ومن سبقه من الامم التي كفرت برسلها، واهل قرى قوم لوط الذين انقلبت بهم ديارهم بسبب الفعله المنكره من الكفر والشرك والفواحش،"},{"id":"5333","s":69,"a":10,"at":"فعصوا رسول ربهم فاخذهم اخذه رابيه","dt":"[10] فعصت كل امه منهم رسول ربهم الذي ارسله اليهم، فاخذهم الله اخذه بالغه في الشده."},{"id":"5334","s":69,"a":11,"at":"انا لما طغى الماء حملناكم في الجاريه","dt":"[11] انا لما جاوز الماء حده، حتى علا وارتفع فوق كل شيء، حملنا اصولكم مع نوح في السفينه التي تجري في الماء"},{"id":"5335","s":69,"a":12,"at":"لنجعلها لكم تذكره وتعيها اذن واعيه","dt":"[12] لنجعل الواقعه التي كان فيها نجاه المؤمنين واغراق الكافرين عبره وعظه، وتحفظها كل اذن من شانها ان تحفظ، وتعقل عن الله ما سمعت."},{"id":"5336","s":69,"a":13,"at":"فاذا نفخ في الصور نفخه واحده","dt":"[13] فاذا نفخ الملك في «القرن» نفخه واحده، وهي النفخه الاولى التي يكون عندها هلاك العالم،"},{"id":"5337","s":69,"a":14,"at":"وحملت الارض والجبال فدكتا دكه واحده","dt":"[14] ورفعت الارض والجبال عن اماكنها فكسرتا، ودقتا دقه واحده"},{"id":"5338","s":69,"a":15,"at":"فيومئذ وقعت الواقعه","dt":"[15] ففي ذلك الحين قامت القيامه"},{"id":"5339","s":69,"a":16,"at":"وانشقت السماء فهي يومئذ واهيه","dt":"[16] وانصدعت السماء، فهي يومئذ ضعيفه مسترخيه، لا تماسك فيها ولا صلابه"},{"id":"5340","s":69,"a":17,"at":"والملك على ارجائها ويحمل عرش ربك فوقهم يومئذ ثمانيه","dt":"[17] والملائكه على جوانبها واطرافها، ويحمل عرش ربك فوقهم يوم القيامه ثمانيه من الملائكه العظام"},{"id":"5341","s":69,"a":18,"at":"يومئذ تعرضون لا تخفى منكم خافيه","dt":"[18] في ذلك اليوم تعرضون على الله -ايها الناس- للحساب والجزاء، لا يخفى عليه شيء من اسراركم."},{"id":"5342","s":69,"a":19,"at":"فاما من اوتي كتابه بيمينه فيقول هاؤم اقرءوا كتابيه","dt":"[19] فاما من اعطي كتاب اعماله بيمينه، فيقول ابتهاجا وسرورا: خذوا اقرؤوا كتابي"},{"id":"5343","s":69,"a":20,"at":"اني ظننت اني ملاق حسابيه","dt":"[20] اني ايقنت في الدنيا باني سالقى جزائي يوم القيامه، فاعددت له العده من الايمان والعمل الصالح"},{"id":"5344","s":69,"a":21,"at":"فهو في عيشه راضيه","dt":"[21] فهو في عيشه هنيئه مرضيه"},{"id":"5345","s":69,"a":22,"at":"في جنه عاليه","dt":"[22] في جنه مرتفعه المكان والدرجات"},{"id":"5346","s":69,"a":23,"at":"قطوفها دانيه","dt":"[23] ثمارها قريبه يتناولها القائم والقاعد والمضطجع"},{"id":"5347","s":69,"a":24,"at":"كلوا واشربوا هنيئا بما اسلفتم في الايام الخاليه","dt":"[24] يقال لهم: كلوا اكلا، واشربوا شربا بعيدا عن كل اذى، سالمين من كل مكروه؛ بسبب ما قدمتم من الاعمال الصالحه في ايام الدنيا الماضيه."},{"id":"5348","s":69,"a":25,"at":"واما من اوتي كتابه بشماله فيقول ياليتني لم اوت كتابيه","dt":"[25] واما من اعطي كتاب اعماله بشماله، فيقول نادما متحسرا: يا ليتني لم اعط كتابي"},{"id":"5349","s":69,"a":26,"at":"ولم ادر ما حسابيه","dt":"[26] ولم اعلم ما جزائي؟"},{"id":"5350","s":69,"a":27,"at":"يا‎ليتها كانت القاضيه","dt":"[27] يا ليت الموته التي متها في الدنيا كانت القاطعه لامري، ولم ابعث بعدها"},{"id":"5351","s":69,"a":28,"at":"ما اغنى عني ماليه","dt":"[28] ما نفعني مالي الذي جمعته في الدنيا"},{"id":"5352","s":69,"a":29,"at":"هلك عني سلطانيه","dt":"[29] ذهبت عني حجتي، ولم يعد لي حجه احتج بها."},{"id":"5353","s":69,"a":30,"at":"خذوه فغلوه","dt":"[30] يقال لخزنه جهنم: خذوا هذا المجرم الاثيم، فاجمعوا يديه الى عنقه بالاغلال"},{"id":"5354","s":69,"a":31,"at":"ثم الجحيم صلوه","dt":"[31] ثم ادخلوه الجحيم ليقاسي حرها"},{"id":"5355","s":69,"a":32,"at":"ثم في سلسله ذرعها سبعون ذراعا فاسلكوه","dt":"[32] ثم في سلسله من حديد طولها سبعون ذراعا فادخلوه فيها"},{"id":"5356","s":69,"a":33,"at":"انه كان لا يؤمن بالله العظيم","dt":"[33] انه كان لا يصدق بان الله هو الاله الحق وحده لا شريك له، ولا يعمل بهديه"},{"id":"5357","s":69,"a":34,"at":"ولا يحض على طعام المسكين","dt":"[34] ولا يحث الناس في الدنيا على اطعام اهل الحاجه من المساكين وغيرهم."},{"id":"5358","s":69,"a":35,"at":"فليس له اليوم هاهنا حميم","dt":"[35] فليس لهذا الكافر يوم القيامه قريب يدفع عنه العذاب."},{"id":"5359","s":69,"a":36,"at":"ولا طعام الا من غسلين","dt":"[36] وليس له طعام الا من صديد اهل النار"},{"id":"5360","s":69,"a":37,"at":"لا ياكله الا الخاطئون","dt":"[37] لا ياكله الا المذنبون المصرون على الكفر بالله."},{"id":"5361","s":69,"a":38,"at":"فلا اقسم بما تبصرون","dt":"[38] اقسم الله بما تبصرون من المرئيات"},{"id":"5362","s":69,"a":39,"at":"وما لا تبصرون","dt":"[39] وما لا تبصرون مما غاب عنكم"},{"id":"5363","s":69,"a":40,"at":"انه لقول رسول كريم","dt":"[40] ان القران لكلام الله ، يتلوه رسول عظيم الشرف والفضل"},{"id":"5364","s":69,"a":41,"at":"وما هو بقول شاعر قليلا ما تؤمنون","dt":"[41] وليس بقول شاعر كما تزعمون، قليلا ما تؤمنون"},{"id":"5365","s":69,"a":42,"at":"ولا بقول كاهن قليلا ما تذكرون","dt":"[42] وليس بسجع كسجع الكهان، قليلا ما يكون منكم تذكر وتامل للفرق بينهما"},{"id":"5366","s":69,"a":43,"at":"تنزيل من رب العالمين","dt":"[43] ولكنه كلام رب العالمين الذي انزله على رسوله محمد -صلى الله عليه وسلم-."},{"id":"5367","s":69,"a":44,"at":"ولو تقول علينا بعض الاقاويل","dt":"[44] ولو ادعى محمد علينا شيئا لم نقله"},{"id":"5368","s":69,"a":45,"at":"لاخذنا منه باليمين","dt":"[45] لانتقمنا منه واخذناه بالقوه والقدره؛ لان قوه كل شيء في ميامنه"},{"id":"5369","s":69,"a":46,"at":"ثم لقطعنا منه الوتين","dt":"[46] ثم لقطعنا منه نياط قلبه"},{"id":"5370","s":69,"a":47,"at":"فما منكم من احد عنه حاجزين","dt":"[47] فلا يقدر احد منكم ان يحجز عنه عقابنا"},{"id":"5371","s":69,"a":48,"at":"وانه لتذكره للمتقين","dt":"[48] وان هذا القران لعظه للمتقين الذين يمتثلون اوامر الله ويجتنبون نواهيه."},{"id":"5372","s":69,"a":49,"at":"وانا لنعلم ان منكم مكذبين","dt":"[49] وانا لنعلم ان منكم من يكذب بهذا القران مع وضوح اياته"},{"id":"5373","s":69,"a":50,"at":"وانه لحسره على الكافرين","dt":"[50] وان التكذيب به لندامه عظيمه على الكافرين به حين يرون عذابهم ويرون نعيم المؤمنين به"},{"id":"5374","s":69,"a":51,"at":"وانه لحق اليقين","dt":"[51] وانه لحق ثابت ويقين لا شك فيه"},{"id":"5375","s":69,"a":52,"at":"فسبح باسم ربك العظيم","dt":"[52] فنزه الله سبحانه عما لا يليق بجلاله، واذكره باسمه العظيم."},{"id":"5376","s":70,"a":1,"at":"سال سائل بعذاب واقع","dt":"[1] دعا داع من المشركين على نفسه وقومه بنزول العذاب عليهم، وهو واقع بهم يوم القيامه لا محاله،"},{"id":"5377","s":70,"a":2,"at":"للكافرين ليس له دافع","dt":"[2] ليس له مانع يمنعه"},{"id":"5378","s":70,"a":3,"at":"من الله ذي المعارج","dt":"[3] من الله ذي العلو والجلال"},{"id":"5379","s":70,"a":4,"at":"تعرج الملائكه والروح اليه في يوم كان مقداره خمسين الف سنه","dt":"[4] تصعد الملائكه وجبريل اليه تعالى في يوم كان مقداره خمسين الف سنه من سني الدنيا، وهو على المؤمن مثل صلاه مكتوبه."},{"id":"5380","s":70,"a":5,"at":"فاصبر صبرا جميلا","dt":"[5] فاصبر -ايها الرسول- على استهزائهم واستعجالهم العذاب صبرا لا جزع فيه، ولا شكوى منه الى غير الله."},{"id":"5381","s":70,"a":6,"at":"انهم يرونه بعيدا","dt":"[6] ان الكافرين يستبعدون العذاب ويرونه غير واقع"},{"id":"5382","s":70,"a":7,"at":"ونراه قريبا","dt":"[7] ونحن نراه واقعا قريبا لا محاله."},{"id":"5383","s":70,"a":8,"at":"يوم تكون السماء كالمهل","dt":"[8] يوم تكون السماء سائله مثل حثاله الزيت"},{"id":"5384","s":70,"a":9,"at":"وتكون الجبال كالعهن","dt":"[9] وتكون الجبال كالصوف المصبوغ المنفوش الذي ذرته الريح."},{"id":"5385","s":70,"a":10,"at":"ولا يسال حميم حميما","dt":"[10] ولا يسال قريب قريبه عن شانه؛ لان كل واحد منهما مشغول بنفسه."},{"id":"5386","s":70,"a":11,"at":"يبصرونهم يود المجرم لو يفتدي من عذاب يومئذ ببنيه","dt":"[11] يرونهم ويعرفونهم، ولا يستطيع احد ان ينفع احدا. يتمنى الكافر لو يفدي نفسه من عذاب يوم القيامه بابنائه"},{"id":"5387","s":70,"a":12,"at":"وصاحبته واخيه","dt":"[12] وزوجه واخيه"},{"id":"5388","s":70,"a":13,"at":"وفصيلته التي تؤويه","dt":"[13] وعشيرته التي تضمه وينتمي اليها في القرابه"},{"id":"5389","s":70,"a":14,"at":"ومن في الارض جميعا ثم ينجيه","dt":"[14] وبجميع من في الارض من البشر وغيرهم، ثم ينجو من عذاب الله."},{"id":"5390","s":70,"a":15,"at":"كلا انها لظى","dt":"[15] ليس الامر كما تتمناه -ايها الكافر- من الافتداء، انها جهنم تتلظى نارها وتلتهب"},{"id":"5391","s":70,"a":16,"at":"نزاعه للشوى","dt":"[16] تنزع بشده حرها جلده الراس وسائر اطراف البدن"},{"id":"5392","s":70,"a":17,"at":"تدعو من ادبر وتولى","dt":"[17] تنادي من اعرض عن الحق في الدنيا، وترك طاعه الله ورسوله"},{"id":"5393","s":70,"a":18,"at":"وجمع فاوعى","dt":"[18] وجمع المال، فوضعه في خزائنه، ولم يؤد حق الله فيه."},{"id":"5394","s":70,"a":19,"at":"ان الانسان خلق هلوعا","dt":"[19] ان الانسان جبل على الجزع وشده الحرص"},{"id":"5395","s":70,"a":20,"at":"اذا مسه الشر جزوعا","dt":"[20] اذا اصابه المكروه والعسر فهو كثير الجزع والاسى"},{"id":"5396","s":70,"a":21,"at":"واذا مسه الخير منوعا","dt":"[21] ، واذا اصابه الخير واليسر فهو كثير المنع والامساك"},{"id":"5397","s":70,"a":22,"at":"الا المصلين","dt":"[22] الا المقيمين للصلاه"},{"id":"5398","s":70,"a":23,"at":"الذين هم على صلاتهم دائمون","dt":"[23] الذين يحافظون على ادائها في جميع الاوقات، ولا يشغلهم عنها شاغل"},{"id":"5399","s":70,"a":24,"at":"والذين في اموالهم حق معلوم","dt":"[24] والذين في اموالهم نصيب معين فرضه الله عليهم، وهو الزكاه"},{"id":"5400","s":70,"a":25,"at":"للسائل والمحروم","dt":"[25] لمن يسالهم المعونه، ولمن يتعفف عن سؤالها"},{"id":"5401","s":70,"a":26,"at":"والذين يصدقون بيوم الدين","dt":"[26] والذين يؤمنون بيوم الحساب والجزاء فيستعدون له بالاعمال الصالحه"},{"id":"5402","s":70,"a":27,"at":"والذين هم من عذاب ربهم مشفقون","dt":"[27] والذين هم خائفون من عذاب الله"},{"id":"5403","s":70,"a":28,"at":"ان عذاب ربهم غير مامون","dt":"[28] ان عذاب ربهم لا ينبغي ان يامنه احد"},{"id":"5404","s":70,"a":29,"at":"والذين هم لفروجهم حافظون","dt":"[29] والذين هم حافظون لفروجهم عن كل ما حرم الله عليهم"},{"id":"5405","s":70,"a":30,"at":"الا على ازواجهم او ما ملكت ايمانهم فانهم غير ملومين","dt":"[30] الا على ازواجهم وامائهم، فانهم غير مؤاخذين."},{"id":"5406","s":70,"a":31,"at":"فمن ابتغى وراء ذلك فاولئك هم العادون","dt":"[31] فمن طلب لقضاء شهوته غير الزوجات والمملوكات، فاولئك هم المتجاوزون الحلال الى الحرام"},{"id":"5407","s":70,"a":32,"at":"والذين هم لاماناتهم وعهدهم راعون","dt":"[32] والذين هم حافظون لامانات الله وامانات العباد، وحافظون لعهودهم مع الله تعالى ومع العباد"},{"id":"5408","s":70,"a":33,"at":"والذين هم بشهاداتهم قائمون","dt":"[33] ، والذين يؤدون شهاداتهم بالحق دون تغيير او كتمان"},{"id":"5409","s":70,"a":34,"at":"والذين هم على صلاتهم يحافظون","dt":"[34] ، والذين يحافظون على اداء الصلاه ولا يخلون بشيء من واجباتها"},{"id":"5410","s":70,"a":35,"at":"اولئك في جنات مكرمون","dt":"[35] اولئك المتصفون بتلك الاوصاف الجليله مستقرون في جنات النعيم، مكرمون فيها بكل انواع التكريم."},{"id":"5411","s":70,"a":36,"at":"فمال الذين كفروا قبلك مهطعين","dt":"[36] فاي دافع دفع هؤلاء الكفره الى ان يسيروا نحوك -ايها الرسول- مسرعين، وقد مدوا اعناقهم اليك مقبلين بابصارهم عليك"},{"id":"5412","s":70,"a":37,"at":"عن اليمين وعن الشمال عزين","dt":"[37] يتجمعون عن يمينك وعن شمالك حلقا متعدده وجماعات متفرقه يتحدثون ويتعجبون؟"},{"id":"5413","s":70,"a":38,"at":"ايطمع كل امرئ منهم ان يدخل جنه نعيم","dt":"[38] ايطمع كل واحد من هؤلاء الكفار ان يدخله الله جنه النعيم الدائم؟"},{"id":"5414","s":70,"a":39,"at":"كلا انا خلقناهم مما يعلمون","dt":"[39] ليس الامر كما يطمعون، فانهم لا يدخلونها ابدا. انا خلقناهم مما يعلمون من ماء مهين كغيرهم، فلم يؤمنوا، فمن اين يتشرفون بدخول جنه النعيم؟"},{"id":"5415","s":70,"a":40,"at":"فلا اقسم برب المشارق والمغارب انا لقادرون","dt":"[40] اقسم تعالى بنفسه، وهو رب المشارق والمغارب للشمس والقمر وسائر الكواكب؛ لما فيها من الايات الباهرات الداله على البعث، انا لقادرون قدره تامه."},{"id":"5416","s":70,"a":41,"at":"على ان نبدل خيرا منهم وما نحن بمسبوقين","dt":"[41] على ان نستبدل بهم قوما افضل منهم واطوع لله، وما احد يسبقنا ويفوتنا ويعجزنا اذا اردنا ان ناتي بقوم اخرين خير منهم."},{"id":"5417","s":70,"a":42,"at":"فذرهم يخوضوا ويلعبوا حتى يلاقوا يومهم الذي يوعدون","dt":"[42] لكن سبق في علمنا ومشيئتنا تاخير عقوبه هؤلاء الكفار، وعدم تبديلهم بقوم اخرين، فاتركهم يخوضوا في باطلهم، ويلعبوا في دنياهم حتى يلاقوا يوم القيامه الذي يوعدون فيه بالعذاب"},{"id":"5418","s":70,"a":43,"at":"يوم يخرجون من الاجداث سراعا كانهم الى نصب يوفضون","dt":"[43] يوم يخرجون من القبور مسرعين، كما كانوا في الدنيا يذهبون الى الهتهم التي اختلقوها للعباده من دون الله، يهرولون ويسرعون"},{"id":"5419","s":70,"a":44,"at":"خاشعه ابصارهم ترهقهم ذله ذلك اليوم الذي كانوا يوعدون","dt":"[44] ذليله ابصارهم منكسره الى الارض، تغشاهم الحقاره والمهانه، ذلك هو اليوم الذي وعدوا به في الدنيا، وكانوا به يهزؤون ويكذبون."},{"id":"5420","s":71,"a":1,"at":"انا ارسلنا نوحا الى قومه ان انذر قومك من قبل ان ياتيهم عذاب اليم","dt":"[1] انا بعثنا نوحا الى قومه، وقلنا له: حذر قومك من قبل ان ياتيهم عذاب موجع"},{"id":"5421","s":71,"a":2,"at":"قال ياقوم اني لكم نذير مبين","dt":"[2] قال نوح: يا قومي اني نذير لكم بين الانذار من عذاب الله ان عصيتموه"},{"id":"5422","s":71,"a":3,"at":"ان اعبدوا الله واتقوه واطيعون","dt":"[3] واني رسول الله اليكم فاعبدوه وحده، وخافوا عقابه، واطيعوني فيما امركم به، وانهاكم عنه"},{"id":"5423","s":71,"a":4,"at":"يغفر لكم من ذنوبكم ويؤخركم الى اجل مسمى ان اجل الله اذا جاء لا يؤخر لو كنتم تعلمون","dt":"[4] فان اطعتموني واستجبتم لي، يصفح الله عن ذنوبكم ويغفر لكم، ويمدد في اعماركم الى وقت مقدر في علم الله تعالى، ان الموت اذا جاء لا يؤخر ابدا، لو كنتم تعلمون ذلك لسارعتم الى الايمان والطاعه."},{"id":"5424","s":71,"a":5,"at":"قال رب اني دعوت قومي ليلا ونهارا","dt":"[5] قال نوح: رب اني دعوت قومي الى الايمان بك وطاعتك في الليل والنهار"},{"id":"5425","s":71,"a":6,"at":"فلم يزدهم دعائي الا فرارا","dt":"[6] فلم يزدهم دعائي لهم الى الايمان الا هربا واعراضا عنه"},{"id":"5426","s":71,"a":7,"at":"واني كلما دعوتهم لتغفر لهم جعلوا اصابعهم في اذانهم واستغشوا ثيابهم واصروا واستكبروا استكبارا","dt":"[7] واني كلما دعوتهم الى الايمان بك؛ ليكون سببا في غفرانك ذنوبهم، وضعوا اصابعهم في اذانهم؛ كي لا يسمعوا دعوه الحق، وتغطوا بثيابهم؛ كي لا يروني، واقاموا على كفرهم، واستكبروا عن قبول الايمان استكبارا شديدا"},{"id":"5427","s":71,"a":8,"at":"ثم اني دعوتهم جهارا","dt":"[8] ثم اني دعوتهم الى الايمان ظاهرا علنا في غير خفاء"},{"id":"5428","s":71,"a":9,"at":"ثم اني اعلنت لهم واسررت لهم اسرارا","dt":"[9] ، ثم اني اعلنت لهم الدعوه بصوت مرتفع في حال، واسررت بها بصوت خفي في حال اخرى"},{"id":"5429","s":71,"a":10,"at":"فقلت استغفروا ربكم انه كان غفارا","dt":"[10] فقلت لقومي: سلوا ربكم غفران ذنوبكم، وتوبوا اليه من كفركم، انه تعالى كان غفارا لمن تاب من عباده ورجع اليه."},{"id":"5430","s":71,"a":11,"at":"يرسل السماء عليكم مدرارا","dt":"[11] ان تتوبوا وتستغفروا ينزل الله عليكم المطر غزيرا متتابعا"},{"id":"5431","s":71,"a":12,"at":"ويمددكم باموال وبنين ويجعل لكم جنات ويجعل لكم انهارا","dt":"[12] ويكثر اموالكم واولادكم، ويجعل لكم حدائق تنعمون بثمارها وجمالها، ويجعل لكم الانهار التي تسقون منها زرعكم ومواشيكم"},{"id":"5432","s":71,"a":13,"at":"ما لكم لا ترجون لله وقارا","dt":"[13] ما لكم -ايها القوم- لا تخافون عظمه الله وسلطانه"},{"id":"5433","s":71,"a":14,"at":"وقد خلقكم اطوارا","dt":"[14] وقد خلقكم في اطوار متدرجه: نطفه ثم علقه ثم مضغه ثم عظاما ولحما؟"},{"id":"5434","s":71,"a":15,"at":"الم تروا كيف خلق الله سبع سموات طباقا","dt":"[15] الم تنظروا كيف خلق الله سبع سموات متطابقه بعضها فوق بعض"},{"id":"5435","s":71,"a":16,"at":"وجعل القمر فيهن نورا وجعل الشمس سراجا","dt":"[16] وجعل القمر في هذه السموات نورا، وجعل الشمس مصباحا مضيئا يستضيء به اهل الارض؟"},{"id":"5436","s":71,"a":17,"at":"والله انبتكم من الارض نباتا","dt":"[17] والله انشا اصلكم من الارض انشاء"},{"id":"5437","s":71,"a":18,"at":"ثم يعيدكم فيها ويخرجكم اخراجا","dt":"[18] ثم يعيدكم في الارض بعد الموت، ويخرجكم يوم البعث اخراجا محققا"},{"id":"5438","s":71,"a":19,"at":"والله جعل لكم الارض بساطا","dt":"[19] والله جعل لكم الارض ممهده كالبساط"},{"id":"5439","s":71,"a":20,"at":"لتسلكوا منها سبلا فجاجا","dt":"[20] لتسلكوا فيها طرقا واسعه."},{"id":"5440","s":71,"a":21,"at":"قال نوح رب انهم عصوني واتبعوا من لم يزده ماله وولده الا خسارا","dt":"[21] قال نوح: رب ان قومي بالغوا في عصياني وتكذيبي، واتبع الضعفاء منهم الرؤساء الضالين الذين لم تزدهم اموالهم واولادهم الا ضلالا في الدنيا وعقابا في الاخره"},{"id":"5441","s":71,"a":22,"at":"ومكروا مكرا كبارا","dt":"[22] ومكر رؤساء الضلال بتابعيهم من الضعفاء مكرا عظيما"},{"id":"5442","s":71,"a":23,"at":"وقالوا لا تذرن الهتكم ولا تذرن ودا ولا سواعا ولا يغوث ويعوق ونسرا","dt":"[23] وقالوا لهم: لا تتركوا عباده الهتكم الى عباده الله وحده، التي يدعو اليها نوح، ولا تتركوا ودا ولا سواعا ولا يغوث ويعوق ونسرا، وهي اسماء اصنامهم التي كانوا يعبدونها من دون الله، وكانت اسماء رجال صالحين، لما ماتوا اوحى الشيطان الى قومهم ان يقيموا لهم التماثيل والصور؛ لينشطوا -بزعمهم- على الطاعه اذا راوها، فلما ذهب هؤلاء القوم وطال الامد، وخلفهم غيرهم، وسوس لهم الشيطان بان اسلافهم كانوا يعبدون التماثيل والصور، ويتوسلون بها. وهذا من حكم تحريم التماثيل، وتحريم بناء القباب على القبور؛ لانها تصير مع تطاول الزمن معبوده للجهال"},{"id":"5443","s":71,"a":24,"at":"وقد اضلوا كثيرا ولا تزد الظالمين الا ضلالا","dt":"[24] وقد اضل هؤلاء المتبوعون كثيرا من الناس بما زينوا لهم من طرق الغوايه والضلال. ثم قال نوح عليه السلام: ولا تزد -يا ربنا- هؤلاء الظالمين لانفسهم بالكفر والعناد الا بعدا عن الحق"},{"id":"5444","s":71,"a":25,"at":"مما خطيئاتهم اغرقوا فادخلوا نارا فلم يجدوا لهم من دون الله انصارا","dt":"[25] فبسبب ذنوبهم واصرارهم على الكفر والطغيان اغرقوا بالطوفان، وادخلوا عقب الاغراق نارا عظيمه اللهب والاحراق، فلم يجدوا من دون الله من ينصرهم، او يدفع عنهم عذاب الله."},{"id":"5445","s":71,"a":26,"at":"وقال نوح رب لا تذر على الارض من الكافرين ديارا","dt":"[26] وقال نوح -عليه السلام- بعد ياسه من قومه: رب لا تترك من الكافرين بك احدا حيا على الارض يدور ويتحرك"},{"id":"5446","s":71,"a":27,"at":"انك ان تذرهم يضلوا عبادك ولا يلدوا الا فاجرا كفارا","dt":"[27] انك ان تتركهم دون اهلاك يضلوا عبادك الذين قد امنوا بك عن طريق الحق، ولا يات من اصلابهم وارحامهم الا مائل عن الحق شديد الكفر بك والعصيان لك"},{"id":"5447","s":71,"a":28,"at":"رب اغفر لي ولوالدي ولمن دخل بيتي مؤمنا وللمؤمنين والمؤمنات ولا تزد الظالمين الا تبارا","dt":"[28] رب اغفر لي، ولوالدي، ولمن دخل بيتي مؤمنا، وللمؤمنين والمؤمنات بك، ولا تزد الكافرين الا هلاكا وخسرانا في الدنيا والاخره."},{"id":"5448","s":72,"a":1,"at":"قل اوحي الي انه استمع نفر من الجن فقالوا انا سمعنا قرانا عجبا","dt":"[1] قل -ايها الرسول-: اوحى الله الي ان جماعه من الجن قد استمعوا لتلاوتي للقران، فلما سمعوه قالوا لقومهم: انا سمعنا قرانا بديعا في بلاغته وفصاحته، وحكمه واحكامه واخباره"},{"id":"5449","s":72,"a":2,"at":"يهدي الى الرشد فامنا به ولن نشرك بربنا احدا","dt":"[2] يدعو الى الحق والهدى، فصدقنا بهذا القران وعملنا به، ولن نشرك بربنا الذي خلقنا احدا في عبادته."},{"id":"5450","s":72,"a":3,"at":"وانه تعالى جد ربنا ما اتخذ صاحبه ولا ولدا","dt":"[3] وانه تعالت عظمه ربنا وجلاله، ما اتخذ زوجه ولا ولدا."},{"id":"5451","s":72,"a":4,"at":"وانه كان يقول سفيهنا على الله شططا","dt":"[4] وان سفيهنا -وهو ابليس- كان يقول على الله تعالى قولا بعيدا عن الحق والصواب، من دعوى الصاحبه والولد."},{"id":"5452","s":72,"a":5,"at":"وانا ظننا ان لن تقول الانس والجن على الله كذبا","dt":"[5] وانا حسبنا ان احدا لن يكذب على الله تعالى، لا من الانس ولا من الجن في نسبه الصاحبه والولد اليه."},{"id":"5453","s":72,"a":6,"at":"وانه كان رجال من الانس يعوذون برجال من الجن فزادوهم رهقا","dt":"[6] وانه كان رجال من الانس يستجيرون برجال من الجن، فزاد رجال الجن الانس باستعاذتهم بهم خوفا وارهابا ورعبا.وهذه الاستعاذه بغير الله التي نعاها الله على اهل الجاهليه، من الشرك الاكبر، الذي لا يغفره الله الا بالتوبه النصوح منه. وفي الايه تحذير شديد من اللجوء الى السحره والمشعوذين واشباههم."},{"id":"5454","s":72,"a":7,"at":"وانهم ظنوا كما ظننتم ان لن يبعث الله احدا","dt":"[7] وان كفار الانس حسبوا كما حسبتم -يا معشر الجن- ان الله تعالى لن يبعث احدا بعد الموت."},{"id":"5455","s":72,"a":8,"at":"وانا لمسنا السماء فوجدناها ملئت حرسا شديدا وشهبا","dt":"[8] وانا -معشر الجن- طلبنا بلوغ السماء؛ لاستماع كلام اهلها، فوجدناها ملئت بالملائكه الكثيرين الذين يحرسونها، وبالشهب المحرقه التي يرمى بها من يقترب منها."},{"id":"5456","s":72,"a":9,"at":"وانا كنا نقعد منها مقاعد للسمع فمن يستمع الان يجد له شهابا رصدا","dt":"[9] وانا كنا قبل ذلك نتخذ من السماء مواضع؛ لنستمع الى اخبارها، فمن يحاول الان استراق السمع يجد له شهابا بالمرصاد، يحرقه ويهلكه. وفي هاتين الايتين ابطال مزاعم السحره والمشعوذين، الذين يدعون علم الغيب، ويغررون بضعفه العقول؛ بكذبهم وافترائهم."},{"id":"5457","s":72,"a":10,"at":"وانا لا ندري اشر اريد بمن في الارض ام اراد بهم ربهم رشدا","dt":"[10] واننا -معشر الجن- لا نعلم: اشرا اراد الله ان ينزله باهل الارض، ام اراد بهم خيرا وهدى؟"},{"id":"5458","s":72,"a":11,"at":"وانا منا الصالحون ومنا دون ذلك كنا طرائق قددا","dt":"[11] وانا منا الابرار المتقون، ومنا قوم دون ذلك كفار وفساق، كنا فرقا ومذاهب مختلفه."},{"id":"5459","s":72,"a":12,"at":"وانا ظننا ان لن نعجز الله في الارض ولن نعجزه هربا","dt":"[12] وانا ايقنا ان الله قادر علينا، واننا في قبضته وسلطانه، فلن نفوته اذا اراد بنا امرا اينما كنا، ولن نستطيع ان نفلت من عقابه هربا الى السماء، ان اراد بنا سوءا."},{"id":"5460","s":72,"a":13,"at":"وانا لما سمعنا الهدى امنا به فمن يؤمن بربه فلا يخاف بخسا ولا رهقا","dt":"[13] وانا لما سمعنا القران امنا به، واقررنا انه حق من عند الله، فمن يؤمن بربه، فانه لا يخشى نقصانا من حسناته، ولا ظلما يلحقه بزياده في سيئاته."},{"id":"5461","s":72,"a":14,"at":"وانا منا المسلمون ومنا القاسطون فمن اسلم فاولئك تحروا رشدا","dt":"[14] وانا منا الخاضعون لله بالطاعه، ومنا الجائرون الظالمون الذين حادوا عن طريق الحق، فمن اسلم وخضع لله بالطاعه، فاولئك الذين قصدوا طريق الحق والصواب، واجتهدوا في اختياره فهداهم الله اليه"},{"id":"5462","s":72,"a":15,"at":"واما القاسطون فكانوا لجهنم حطبا","dt":"[15] واما الجائرون عن طريق الاسلام فكانوا وقودا لجهنم."},{"id":"5463","s":72,"a":16,"at":"والو استقاموا على الطريقه لاسقيناهم ماء غدقا","dt":"[16] وانه لو سار الكفار من الانس والجن على طريقه الاسلام، ولم يحيدوا عنها لانزلنا عليهم ماء كثيرا، ولوسعنا عليهم الرزق في الدنيا"},{"id":"5464","s":72,"a":17,"at":"لنفتنهم فيه ومن يعرض عن ذكر ربه يسلكه عذابا صعدا","dt":"[17] لنختبرهم: كيف يشكرون نعم الله عليهم؟ ومن يعرض عن طاعه ربه واستماع القران وتدبره، والعمل به يدخله عذابا شديدا شاقا."},{"id":"5465","s":72,"a":18,"at":"وان المساجد لله فلا تدعوا مع الله احدا","dt":"[18] وان المساجد لعباده الله وحده، فلا تعبدوا فيها غيره، واخلصوا له الدعاء والعباده فيها؛ فان المساجد لم تبن الا ليعبد الله وحده فيها، دون من سواه. وفي الايه وجوب تنزيه المساجد من كل ما يشوب الاخلاص لله، ومتابعه رسوله محمد -صلى الله عليه وسلم-."},{"id":"5466","s":72,"a":19,"at":"وانه لما قام عبد الله يدعوه كادوا يكونون عليه لبدا","dt":"[19] وانه لما قام محمد -صلى الله عليه وسلم-، يعبد ربه، كاد الجن يكونون عليه جماعات متراكمه، بعضها فوق بعض؛ من شده ازدحامهم لسماع القران منه."},{"id":"5467","s":72,"a":20,"at":"قل انما ادعو ربي ولا اشرك به احدا","dt":"[20] قل -ايها الرسول- لهؤلاء الكفار: انما اعبد ربي وحده، ولا اشرك معه في العباده احدا."},{"id":"5468","s":72,"a":21,"at":"قل اني لا املك لكم ضرا ولا رشدا","dt":"[21] قل -ايها الرسول- لهم: اني لا اقدر ان ادفع عنكم ضرا، ولا اجلب لكم نفعا"},{"id":"5469","s":72,"a":22,"at":"قل اني لن يجيرني من الله احد ولن اجد من دونه ملتحدا","dt":"[22] قل: اني لن ينقذني من عذاب الله احد ان عصيته، ولن اجد من دونه ملجا افر اليه من عذابه"},{"id":"5470","s":72,"a":23,"at":"الا بلاغا من الله ورسالاته ومن يعص الله ورسوله فان له نار جهنم خالدين فيها ابدا","dt":"[23] لكن املك ان ابلغكم عن الله ما امرني بتبليغه لكم، ورسالته التي ارسلني بها اليكم. ومن يعص الله ورسوله، ويعرض عن دين الله، فان جزاءه نار جهنم لا يخرج منها ابدا."},{"id":"5471","s":72,"a":24,"at":"حتى اذا راوا ما يوعدون فسيعلمون من اضعف ناصرا واقل عددا","dt":"[24] حتى اذا ابصر المشركون ما يوعدون به من العذاب، فسيعلمون عند حلوله بهم: من اضعف ناصرا ومعينا واقل جندا؟"},{"id":"5472","s":72,"a":25,"at":"قل ان ادري اقريب ما توعدون ام يجعل له ربي امدا","dt":"[25] قل -ايها الرسول- لهؤلاء المشركين: ما ادري اهذا العذاب الذي وعدتم به قريب زمنه، ام يجعل له ربي مده طويله؟"},{"id":"5473","s":72,"a":26,"at":"عالم الغيب فلا يظهر على غيبه احدا","dt":"[26] وهو سبحانه عالم بما غاب عن الابصار، فلا يظهر على غيبه احدا من خلقه"},{"id":"5474","s":72,"a":27,"at":"الا من ارتضى من رسول فانه يسلك من بين يديه ومن خلفه رصدا","dt":"[27] الا من اختاره الله لرسالته وارتضاه، فانه يطلعهم على بعض الغيب، ويرسل من امام الرسول ومن خلفه ملائكه يحفظونه من الجن؛ لئلا يسترقوه ويهمسوا به الى الكهنه"},{"id":"5475","s":72,"a":28,"at":"ليعلم ان قد ابلغوا رسالات ربهم واحاط بما لديهم واحصى كل شيء عددا","dt":"[28] ليعلم الرسول -صلى الله عليه وسلم-، ان الرسل قبله كانوا على مثل حاله من التبليغ بالحق والصدق، وانه حفظ كما حفظوا من الجن، وان الله سبحانه احاط علمه بما عندهم ظاهرا وباطنا من الشرائع والاحكام وغيرها، لا يفوته منها شيء، وانه تعالى احصى كل شيء عددا، فلم يخف عليه منه شيء."},{"id":"5476","s":73,"a":1,"at":"ياايها المزمل","dt":"[1] يا ايها المتغطي بثيابه"},{"id":"5477","s":73,"a":2,"at":"قم الليل الا قليلا","dt":"[2] قم للصلاه في الليل الا يسيرا منه"},{"id":"5478","s":73,"a":3,"at":"نصفه او انقص منه قليلا","dt":"[3] قم نصف الليل او انقص من النصف قليلا حتى تصل الى الثلث"},{"id":"5479","s":73,"a":4,"at":"او زد عليه ورتل القران ترتيلا","dt":"[4] او زد على النصف حتى تصل الى الثلثين، واقرا القران بتؤده وتمهل مبينا الحروف والوقوف."},{"id":"5480","s":73,"a":5,"at":"انا سنلقي عليك قولا ثقيلا","dt":"[5] انا سننزل عليك -ايها النبي- قرانا عظيما مشتملا على الاوامر والنواهي والاحكام الشرعيه."},{"id":"5481","s":73,"a":6,"at":"ان ناشئه الليل هي اشد وطئا واقوم قيلا","dt":"[6] ان العباده التي تنشا في جوف الليل هي اشد تاثيرا في القلب، وابين قولا؛ لفراغ القلب من مشاغل الدنيا."},{"id":"5482","s":73,"a":7,"at":"ان لك في النهار سبحا طويلا","dt":"[7] ان لك في النهار تصرفا وتقلبا في مصالحك، واشتغالا واسعا بامور الرساله، ففرغ نفسك ليلا لعباده ربك."},{"id":"5483","s":73,"a":8,"at":"واذكر اسم ربك وتبتل اليه تبتيلا","dt":"[8] واذكر -ايها النبي- اسم ربك، فادعه به، وانقطع اليه انقطاعا تاما في عبادتك، وتوكل عليه"},{"id":"5484","s":73,"a":9,"at":"رب المشرق والمغرب لا اله الا هو فاتخذه وكيلا","dt":"[9] هو مالك المشرق والمغرب لا معبود بحق الا هو، فاعتمد عليه، وفوض امورك اليه."},{"id":"5485","s":73,"a":10,"at":"واصبر على ما يقولون واهجرهم هجرا جميلا","dt":"[10] واصبر على ما يقوله المشركون فيك وفي دينك، وخالفهم في افعالهم الباطله، مع الاعراض عنهم، وترك الانتقام منهم."},{"id":"5486","s":73,"a":11,"at":"وذرني والمكذبين اولي النعمه ومهلهم قليلا","dt":"[11] ودعني -ايها الرسول- وهؤلاء المكذبين باياتي اصحاب النعيم والترف في الدنيا، ومهلهم زمنا قليلا بتاخير العذاب عنهم حتى يبلغ الكتاب اجله بعذابهم."},{"id":"5487","s":73,"a":12,"at":"ان لدينا انكالا وجحيما","dt":"[12] ان لهم عندنا في الاخره قيودا ثقيله ونارا مستعره يحرقون بها"},{"id":"5488","s":73,"a":13,"at":"وطعاما ذا غصه وعذابا اليما","dt":"[13] وطعاما كريها ينشب في الحلوق لا يستساغ، وعذابا موجعا."},{"id":"5489","s":73,"a":14,"at":"يوم ترجف الارض والجبال وكانت الجبال كثيبا مهيلا","dt":"[14] يوم تضطرب الارض والجبال وتتزلزل حتى تصير الجبال تلا من الرمل سائلا متناثرا، بعد ان كانت صلبه جامده."},{"id":"5490","s":73,"a":15,"at":"انا ارسلنا اليكم رسولا شاهدا عليكم كما ارسلنا الى فرعون رسولا","dt":"[15] انا ارسلنا اليكم -يا اهل «مكه»- محمدا رسولا، شاهدا عليكم بما صدر منكم من الكفر والعصيان، كما ارسلنا موسى رسولا الى الطاغيه فرعون"},{"id":"5491","s":73,"a":16,"at":"فعصى فرعون الرسول فاخذناه اخذا وبيلا","dt":"[16] فكذب فرعون بموسى، ولم يؤمن برسالته، وعصى امره، فاهلكناه اهلاكا شديدا.وفي الايه تحذير من معصيه الرسول محمد -صلى الله عليه وسلم-؛ خشيه ان يصيب العاصي مثل ما اصاب فرعون وقومه."},{"id":"5492","s":73,"a":17,"at":"فكيف تتقون ان كفرتم يوما يجعل الولدان شيبا","dt":"[17] فكيف تقون انفسكم -ان كفرتم- عذاب يوم القيامه الذي يشيب فيه الولدان الصغار؛ من شده هوله وكربه؟"},{"id":"5493","s":73,"a":18,"at":"السماء منفطر به كان وعده مفعولا","dt":"[18] السماء متصدعه في ذلك اليوم؛ لشده هوله، كان وعد الله تعالى بمجيء ذلك اليوم واقعا لا محاله."},{"id":"5494","s":73,"a":19,"at":"ان هذه تذكره فمن شاء اتخذ الى ربه سبيلا","dt":"[19] ان هذه الايات المخوفه التي فيها القوارع والزواجر عظه وعبره للناس، فمن اراد الاتعاظ والانتفاع بها اتخذ الطاعه والتقوى طريقا توصله الى رضوان ربه الذي خلقه ورباه."},{"id":"5495","s":73,"a":20,"at":"ان ربك يعلم انك تقوم ادنى من ثلثي الليل ونصفه وثلثه وطائفه من الذين معك والله يقدر الليل والنهار علم ان لن تحصوه فتاب عليكم فاقرءوا ما تيسر من القران علم ان سيكون منكم مرضى واخرون يضربون في الارض يبتغون من فضل الله واخرون يقاتلون في سبيل الله فاقرءوا ما تيسر منه واقيموا الصلاه واتوا الزكاه واقرضوا الله قرضا حسنا وما تقدموا لانفسكم من خير تجدوه عند الله هو خيرا واعظم اجرا واستغفروا الله ان الله غفور رحيم","dt":"[20] ان ربك -ايها النبي- يعلم انك تقوم للتهجد من الليل اقل من ثلثيه حينا، وتقوم نصفه حينا، وتقوم ثلثه حينا اخر، ويقوم معك طائفه من اصحابك. والله وحده هو الذي يقدر الليل والنهار، ويعلم مقاديرهما ، وما يمضي ويبقى منهما. علم الله انه لا يمكنكم قيام الليل كله، فخفف عليكم، فاقرؤوا في الصلاه بالليل ما تيسر لكم قراءته من القران، علم الله انه سيوجد فيكم من يعجزه المرض عن قيام الليل، ويوجد قوم اخرون يتنقلون في الارض للتجاره والعمل يطلبون من رزق الله الحلال، وقوم اخرون يجاهدون في سبيل الله؛ لاعلاء كلمته ونشر دينه، فاقرؤوا في صلاتكم ما تيسر لكم من القران، وواظبوا على فرائض الصلاه، واعطوا الزكاه الواجبه عليكم، وتصدقوا في وجوه البر والاحسان من اموالكم؛ ابتغاء وجه الله، وما تفعلوا من وجوه البر والخير وعمل الطاعات، تلقوا اجره وثوابه عند الله يوم القيامه خيرا مما قدمتم في الدنيا، واعظم منه ثوابا، واطلبوا مغفره الله في جميع احوالكم، ان الله غفور لكم، رحيم بكم."},{"id":"5496","s":74,"a":1,"at":"ياايها المدثر","dt":"[1] يا ايها المتغطي بثيابه"},{"id":"5497","s":74,"a":2,"at":"قم فانذر","dt":"[2] قم من مضجعك، فحذر الناس من عذاب الله"},{"id":"5498","s":74,"a":3,"at":"وربك فكبر","dt":"[3] وخص ربك وحده بالتعظيم والتوحيد والعباده"},{"id":"5499","s":74,"a":4,"at":"وثيابك فطهر","dt":"[4] وطهر ثيابك من النجاسات؛ فان طهاره الظاهر من تمام طهاره الباطن"},{"id":"5500","s":74,"a":5,"at":"والرجز فاهجر","dt":"[5] ودم على هجر الاصنام والاوثان واعمال الشرك كلها، فلا تقربها"},{"id":"5501","s":74,"a":6,"at":"ولا تمنن تستكثر","dt":"[6] ولا تعط العطيه؛ كي تلتمس اكثر منها"},{"id":"5502","s":74,"a":7,"at":"ولربك فاصبر","dt":"[7] ولمرضاه ربك فاصبر على الاوامر والنواهي."},{"id":"5503","s":74,"a":8,"at":"فاذا نقر في الناقور","dt":"[8] فاذا نفخ في «القرن» نفخه البعث والنشور"},{"id":"5504","s":74,"a":9,"at":"فذلك يومئذ يوم عسير","dt":"[9] فذلك الوقت يومئذ شديد"},{"id":"5505","s":74,"a":10,"at":"على الكافرين غير يسير","dt":"[10] على الكافرين، غير سهل ان يخلصوا مما هم فيه من مناقشه الحساب وغيره من الاهوال."},{"id":"5506","s":74,"a":11,"at":"ذرني ومن خلقت وحيدا","dt":"[11] دعني -ايها الرسول- انا والذي خلقته في بطن امه وحيدا فريدا لا مال له ولا ولد"},{"id":"5507","s":74,"a":12,"at":"وجعلت له مالا ممدودا","dt":"[12] وجعلت له مالا مبسوطا واسعا"},{"id":"5508","s":74,"a":13,"at":"وبنين شهودا","dt":"[13] واولادا حضورا معه في «مكه» لا يغيبو عنه"},{"id":"5509","s":74,"a":14,"at":"ومهدت له تمهيدا","dt":"[14] ويسرت له سبل العيش تيسيرا"},{"id":"5510","s":74,"a":15,"at":"ثم يطمع ان ازيد","dt":"[15] ثم يامل بعد هذا العطاء ان ازيد له في ماله وولده، وقد كفر بي"},{"id":"5511","s":74,"a":16,"at":"كلا انه كان لاياتنا عنيدا","dt":"[16] . ليس الامر كما يزعم هذا الفاجر الاثيم، لا ازيده على ذلك؛ انه كان للقران وحجج الله على خلقه معاندا مكذبا"},{"id":"5512","s":74,"a":17,"at":"سارهقه صعودا","dt":"[17] ساكلفه مشقه من العذاب والارهاق لا راحه له منها. والمراد بهذا الوعيد الوليد بن المغيره المعاند للحق المبارز لله ولرسوله بالمحاربه. وهذا جزاء كل من عاند الحق ونابذه."},{"id":"5513","s":74,"a":18,"at":"انه فكر وقدر","dt":"[18] انه فكر في نفسه، وهيا ما يقوله من الطعن في محمد -صلى الله عليه وسلم- والقران."},{"id":"5514","s":74,"a":19,"at":"فقتل كيف قدر","dt":"[19] فلعن، واستحق بذلك الهلاك، كيف اعد في نفسه هذا الطعن؟"},{"id":"5515","s":74,"a":20,"at":"ثم قتل كيف قدر","dt":"[20] ثم لعن كذلك"},{"id":"5516","s":74,"a":21,"at":"ثم نظر","dt":"[21] ثم تامل فيما قدر وهيا من الطعن في القران"},{"id":"5517","s":74,"a":22,"at":"ثم عبس وبسر","dt":"[22] ثم قطب وجهه، واشتد في العبوس والكلوح لما ضاقت عليه الحيل، ولم يجد مطعنا يطعن به في القران"},{"id":"5518","s":74,"a":23,"at":"ثم ادبر واستكبر","dt":"[23] ثم رجع معرضا عن الحق، وتعاظم ان يعتر به"},{"id":"5519","s":74,"a":24,"at":"فقال ان هذا الا سحر يؤثر","dt":"[24] فقال عن القران: ما هذا الذي يقوله محمد الا سحر ينقل عن الاولين"},{"id":"5520","s":74,"a":25,"at":"ان هذا الا قول البشر","dt":"[25] ما هذا الا كلام المخلوقين تعلمه محمد منهم، ثم ادعى انه من عند الله."},{"id":"5521","s":74,"a":26,"at":"ساصليه سقر","dt":"[26] سادخله جهنم؛ كي يصلى حرها ويحترق بنارها"},{"id":"5522","s":74,"a":27,"at":"وما ادراك ما سقر","dt":"[27] وما اعلمك اي شيء جهنم؟"},{"id":"5523","s":74,"a":28,"at":"لا تبقي ولا تذر","dt":"[28] لا تبقي لحما ولا تترك عظما الا احرقته"},{"id":"5524","s":74,"a":29,"at":"لواحه للبشر","dt":"[29] مغيره للبشره، مسوده للجلود، محرقه لها"},{"id":"5525","s":74,"a":30,"at":"عليها تسعه عشر","dt":"[30] يلي امرها ويتسلط على اهلها بالعذاب تسعه عشر ملكا من الزبانيه الاشداء."},{"id":"5526","s":74,"a":31,"at":"وما جعلنا اصحاب النار الا ملائكه وما جعلنا عدتهم الا فتنه للذين كفروا ليستيقن الذين اوتوا الكتاب ويزداد الذين امنوا ايمانا ولا يرتاب الذين اوتوا الكتاب والمؤمنون وليقول الذين في قلوبهم مرض والكافرون ماذا اراد الله بهذا مثلا كذلك يضل الله من يشاء ويهدي من يشاء وما يعلم جنود ربك الا هو وما هي الا ذكرى للبشر","dt":"[31] وما جعلنا خزنه النار الا من الملائكه الغلاظ، وما جعلنا ذلك العدد الا اختبارا للذين كفروا بالله؛ وليحصل اليقين للذين اعطوا الكتاب من اليهود والنصارى بان ما جاء في القران عن خزنه جهنم انما هو حق من الله تعالى، حيث وافق ذلك كتبهم، ويزداد المؤمنون تصديقا بالله ورسوله وعملا بشرعه، ولا يشك في ذلك الذين اعطوا الكتاب من اليهود والنصارى ولا المؤمنون بالله ورسوله؛ وليقول الذين في قلوبهم نفاق والكافرون: ما الذي اراده الله بهذا العدد المستغرب؟ بمثل ذلك الذي ذكر يضل الله من اراد اضلاله، ويهدي من اراد هدايته، وما يعلم عدد جنود ربك -ومنهم الملائكه- الا الله وحده. وما النار الا تذكره وموعظه للناس."},{"id":"5527","s":74,"a":32,"at":"كلا والقمر","dt":"[32] ليس الامر كما ذكروا من التكذيب للرسول فيما جاء به، اقسم الله سبحانه بالقمر"},{"id":"5528","s":74,"a":33,"at":"والليل اذ ادبر","dt":"[33] وبالليل اذ ولى وذهب"},{"id":"5529","s":74,"a":34,"at":"والصبح اذا اسفر","dt":"[34] وبالصبح اذا اضاء وانكشف"},{"id":"5530","s":74,"a":35,"at":"انها لاحدى الكبر","dt":"[35] ان النار لاحدى العظائم"},{"id":"5531","s":74,"a":36,"at":"نذيرا للبشر","dt":"[36] انذارا وتخويفا للناس"},{"id":"5532","s":74,"a":37,"at":"لمن شاء منكم ان يتقدم او يتاخر","dt":"[37] لمن اراد منكم ان يتقرب الى ربه بفعل الطاعات، او يتاخر بفعل المعاصي."},{"id":"5533","s":74,"a":38,"at":"كل نفس بما كسبت رهينه","dt":"[38] كل نفس بما كسبت من اعمال الشر والسوء محبوسه مرهونه بكسبها، لا تفك حتى تؤدي ما عليها من الحقوق والعقوبات"},{"id":"5534","s":74,"a":39,"at":"الا اصحاب اليمين","dt":"[39] الا المسلمين المخلصين اصحاب اليمين الذين فكوا رقابهم بالطاعه"},{"id":"5535","s":74,"a":40,"at":"في جنات يتساءلون","dt":"[40] هم في جنات لا يدرك وصفها، يسال بعضهم بعضا"},{"id":"5536","s":74,"a":41,"at":"عن المجرمين","dt":"[41] عن الكافرين الذين اجرموا في حق انفسهم"},{"id":"5537","s":74,"a":42,"at":"ما سلككم في سقر","dt":"[42] ما الذي ادخلكم جهنم، وجعلكم تذوقون سعيرها؟"},{"id":"5538","s":74,"a":43,"at":"قالوا لم نك من المصلين","dt":"[43] قال المجرمون: لم نكن من المصلين في الدنيا"},{"id":"5539","s":74,"a":44,"at":"ولم نك نطعم المسكين","dt":"[44] ولم نكن نتصدق ونحسن الى الفقراء والمساكين"},{"id":"5540","s":74,"a":45,"at":"وكنا نخوض مع الخائضين","dt":"[45] وكنا نتحدث بالباطل مع اهل الغوايه والضلاله"},{"id":"5541","s":74,"a":46,"at":"وكنا نكذب بيوم الدين","dt":"[46] وكنا نكذب بيوم الحساب والجزاء"},{"id":"5542","s":74,"a":47,"at":"حتى اتانا اليقين","dt":"[47] حتى جاءنا الموت، ونحن في تلك الضلالات والمنكرات."},{"id":"5543","s":74,"a":48,"at":"فما تنفعهم شفاعه الشافعين","dt":"[48] فما تنفعهم شفاعه الشافعين جميعا من الملائكه والنبيين وغيرهم؛ لان الشفاعه انما تكون لمن ارتضاه الله، واذن لشفيعه ان يشفع له."},{"id":"5544","s":74,"a":49,"at":"فما لهم عن التذكره معرضين","dt":"[49] فما لهؤلاء المشركين عن القران وما فيه من المواعظ منصرفين؟"},{"id":"5545","s":74,"a":50,"at":"كانهم حمر مستنفره","dt":"[50] كانهم حمر وحشيه شديده النفار"},{"id":"5546","s":74,"a":51,"at":"فرت من قسوره","dt":"[51] فرت من اسد كاسر."},{"id":"5547","s":74,"a":52,"at":"بل يريد كل امرئ منهم ان يؤتى صحفا منشره","dt":"[52] بل يطمع كل واحد من هؤلاء المشركين ان ينزل الله عليه كتابا من السماء منشورا، كما انزل على محمد -صلى الله عليه وسلم-."},{"id":"5548","s":74,"a":53,"at":"كلا بل لا يخافون الاخره","dt":"[53] ليس الامر كما زعموا، بل الحقيقه انهم لا يخافون الاخره، ولا يصدقون بالبعث والجزاء."},{"id":"5549","s":74,"a":54,"at":"كلا انه تذكره","dt":"[54] حقا ان القران موعظه بليغه كافيه لاتعاظهم"},{"id":"5550","s":74,"a":55,"at":"فمن شاء ذكره","dt":"[55] فمن اراد الاتعاظ اتعظ بما فيه وانتفع بهداه"},{"id":"5551","s":74,"a":56,"at":"وما يذكرون الا ان يشاء الله هو اهل التقوى واهل المغفره","dt":"[56] وما يتعظون به الا ان يشاء الله لهم الهدى. هو سبحانه اهل لان يتقى ويطاع، واهل لان يغفر لمن امن به واطاعه."},{"id":"5552","s":75,"a":1,"at":"لا اقسم بيوم القيامه","dt":"[1] اقسم الله سبحانه بيوم الحساب والجزاء"},{"id":"5553","s":75,"a":2,"at":"ولا اقسم بالنفس اللوامه","dt":"[2] واقسم بالنفس المؤمنه التقيه التي تلوم صاحبها على ترك الطاعات وفعل الموبقات، ان الناس سيبعثون"},{"id":"5554","s":75,"a":3,"at":"ايحسب الانسان الن نجمع عظامه","dt":"[3] ايظن هذا الانسان الكافر ان لن نقدر على جمع عظامه بعد تفرقها؟"},{"id":"5555","s":75,"a":4,"at":"بلى قادرين على ان نسوي بنانه","dt":"[4] بلى سنجمعها، قادرين على ان نجعل اصابعه او انامله -بعد جمعها وتاليفها- خلقا سويا، كما كانت قبل الموت."},{"id":"5556","s":75,"a":5,"at":"بل يريد الانسان ليفجر امامه","dt":"[5] بل ينكر الانسان البعث، يريد ان يبقى على الفجور فيما يستقبل من ايام عمره"},{"id":"5557","s":75,"a":6,"at":"يسال ايان يوم القيامه","dt":"[6] يسال هذا الكافر مستبعدا قيام الساعه: متى يكون يوم القيامه؟"},{"id":"5558","s":75,"a":7,"at":"فاذا برق البصر","dt":"[7] فاذا تحير البصر ودهش فزعا مما راى من اهوال يوم القيامه"},{"id":"5559","s":75,"a":8,"at":"وخسف القمر","dt":"[8] وذهب نور القمر"},{"id":"5560","s":75,"a":9,"at":"وجمع الشمس والقمر","dt":"[9] وجمع بين الشمس والقمر في ذهاب الضوء، فلا ضوء لواحد منهما"},{"id":"5561","s":75,"a":10,"at":"يقول الانسان يومئذ اين المفر","dt":"[10] يقول الانسان وقتها: اين المهرب من العذاب؟"},{"id":"5562","s":75,"a":11,"at":"كلا لا وزر","dt":"[11] ليس الامر كما تتمناه -ايها الانسان- من طلب الفرار، لا ملجا لك ولا منجى"},{"id":"5563","s":75,"a":12,"at":"الى ربك يومئذ المستقر","dt":"[12] الى الله وحده مصير الخلائق يوم القيامه ومستقرهم، فيجازي كلا بما يستحق."},{"id":"5564","s":75,"a":13,"at":"ينبا الانسان يومئذ بما قدم واخر","dt":"[13] يخبر الانسان في ذلك اليوم بجميع اعماله: من خير وشر، ما قدمه منها في حياته وما اخره."},{"id":"5565","s":75,"a":14,"at":"بل الانسان على نفسه بصيره","dt":"[14] بل الانسان حجه واضحه على نفسه تلزمه بما فعل او ترك"},{"id":"5566","s":75,"a":15,"at":"ولو القى معاذيره","dt":"[15] ولو جاء بكل معذره يعتذر بها عن اجرامه، فانه لا ينفعه ذلك."},{"id":"5567","s":75,"a":16,"at":"لا تحرك به لسانك لتعجل به","dt":"[16] لا تحرك -ايها النبي- بالقران لسانك حين نزول الوحي؛ لاجل ان تتعجل بحفظه، مخافه ان يتفلت منك"},{"id":"5568","s":75,"a":17,"at":"ان علينا جمعه وقرانه","dt":"[17] ان علينا جمعه في صدرك، ثم ان تقراه بلسانك متى شئت"},{"id":"5569","s":75,"a":18,"at":"فاذا قراناه فاتبع قرانه","dt":"[18] فاذا قراه عليك رسولنا جبريل فاستمع لقراءته وانصت له، ثم اقراه كما اقراك اياه"},{"id":"5570","s":75,"a":19,"at":"ثم ان علينا بيانه","dt":"[19] ثم ان علينا توضيح ما اشكل عليك فهمه من معانيه واحكامه."},{"id":"5571","s":75,"a":20,"at":"كلا بل تحبون العاجله","dt":"[20] ليس الامر كما زعمتم -يا معشر المشركين- ان لا بعث ولا جزاء، بل انتم قوم تحبون الدنيا وزينتها"},{"id":"5572","s":75,"a":21,"at":"وتذرون الاخره","dt":"[21] وتتركون الاخره ونعيمها."},{"id":"5573","s":75,"a":22,"at":"وجوه يومئذ ناضره","dt":"[22] وجوه اهل السعاده يوم القيامه مشرقه حسنه ناعمه"},{"id":"5574","s":75,"a":23,"at":"الى ربها ناظره","dt":"[23] ترى خالقها ومالك امرها، فتتمتع بذلك."},{"id":"5575","s":75,"a":24,"at":"ووجوه يومئذ باسره","dt":"[24] ووجوه الاشقياء يوم القيامه عابسه كالحه"},{"id":"5576","s":75,"a":25,"at":"تظن ان يفعل بها فاقره","dt":"[25] تتوقع ان تنزل بها مصيبه عظيمه، تقصم فقار الظهر."},{"id":"5577","s":75,"a":26,"at":"كلا اذا بلغت التراقي","dt":"[26] حقا اذا وصلت الروح الى اعالي الصدر"},{"id":"5578","s":75,"a":27,"at":"وقيل من راق","dt":"[27] وقال بعض الحاضرين لبعض: هل من راق يرقيه ويشفيه مما هو فيه؟"},{"id":"5579","s":75,"a":28,"at":"وظن انه الفراق","dt":"[28] وايقن المحتضر ان الذي نزل به هو فراق الدنيا؛ لمعاينته ملائكه الموت"},{"id":"5580","s":75,"a":29,"at":"والتفت الساق بالساق","dt":"[29] واتصلت شده اخر الدنيا بشده اول الاخره"},{"id":"5581","s":75,"a":30,"at":"الى ربك يومئذ المساق","dt":"[30] الى الله تعالى مساق العباد يوم القيامه: اما الى الجنه واما الى النار."},{"id":"5582","s":75,"a":31,"at":"فلا صدق ولا صلى","dt":"[31] فلا امن الكافر بالرسول والقران، ولا ادى لله تعالى فرائض الصلاه"},{"id":"5583","s":75,"a":32,"at":"ولكن كذب وتولى","dt":"[32] ولكن كذب بالقران، واعرض عن الايمان"},{"id":"5584","s":75,"a":33,"at":"ثم ذهب الى اهله يتمطى","dt":"[33] ثم مضى الى اهله يتبختر مختالا في مشيته"},{"id":"5585","s":75,"a":34,"at":"اولى لك فاولى","dt":"[34] هلاك لك فهلاك"},{"id":"5586","s":75,"a":35,"at":"ثم اولى لك فاولى","dt":"[35] ثم هلاك لك فهلاك."},{"id":"5587","s":75,"a":36,"at":"ايحسب الانسان ان يترك سدى","dt":"[36] ايظن هذا الانسان المنكر للبعث ان يترك هملا لا يؤمر ولا ينهى، ولا يحاسب ولا يعاقب؟"},{"id":"5588","s":75,"a":37,"at":"الم يك نطفه من مني يمنى","dt":"[37] الم يك هذا الانسان نطفه ضعيفه من ماء مهين يراق ويصب في الارحام"},{"id":"5589","s":75,"a":38,"at":"ثم كان علقه فخلق فسوى","dt":"[38] ثم صار قطعه من دم جامد، فخلقه الله بقدرته وسوى صورته في احسن تقويم؟"},{"id":"5590","s":75,"a":39,"at":"فجعل منه الزوجين الذكر والانثى","dt":"[39] فجعل من هذا الانسان الصنفين: الذكر والانثى"},{"id":"5591","s":75,"a":40,"at":"اليس ذلك بقادر على ان يحيي الموتى","dt":"[40] اليس ذلك الاله الخالق لهذه الاشياء بقادر على اعاده الخلق بعد فنائهم؟ بلى انه -سبحانه وتعالى- لقادر على ذلك."},{"id":"5592","s":76,"a":1,"at":"هل اتى على الانسان حين من الدهر لم يكن شيئا مذكورا","dt":"[1] قد مضى على الانسان وقت طويل من الزمان قبل ان تنفخ فيه الروح، لم يكن شيئا يذكر، ولا يعرف له اثر."},{"id":"5593","s":76,"a":2,"at":"انا خلقنا الانسان من نطفه امشاج نبتليه فجعلناه سميعا بصيرا","dt":"[2] انا خلقنا الانسان من نطفه مختلطه من ماء الرجل وماء المراه، نختبره بالتكاليف الشرعيه فيما بعد، فجعلناه من اجل ذلك ذا سمع وذا بصر؛ ليسمع الايات، ويرى الدلائل"},{"id":"5594","s":76,"a":3,"at":"انا هديناه السبيل اما شاكرا واما كفورا","dt":"[3] انا بينا له وعرفناه طريق الهدى والضلال والخير والشر؛ ليكون اما مؤمنا شاكرا، واما كفورا جاحدا."},{"id":"5595","s":76,"a":4,"at":"انا اعتدنا للكافرين سلاسل واغلالا وسعيرا","dt":"[4] انا اعتدنا للكافرين قيودا من حديد تشد بها ارجلهم، واغلالا تغل بها ايديهم الى اعناقهم، ونارا يحرقون بها."},{"id":"5596","s":76,"a":5,"at":"ان الابرار يشربون من كاس كان مزاجها كافورا","dt":"[5] ان اهل الطاعه والاخلاص الذين يؤدون حق الله، يشربون يوم القيامه من كاس فيها خمر ممزوجه باحسن انواع الطيب، وهو ماء الكافور."},{"id":"5597","s":76,"a":6,"at":"عينا يشرب بها عباد الله يفجرونها تفجيرا","dt":"[6] هذا الشراب الذي مزج من الكافور هو عين يشرب منها عباد الله، يتصرفون فيها، ويجرونها حيث شاؤوا اجراء سهلا"},{"id":"5598","s":76,"a":7,"at":"يوفون بالنذر ويخافون يوما كان شره مستطيرا","dt":"[7] هؤلاء كانوا في الدنيا يوفون بما اوجبوا على انفسهم من طاعه الله، ويخافون عقاب الله في يوم القيامه الذي يكون ضرره خطيرا، وشره فاشيا منتشرا على الناس، الا من رحم الله"},{"id":"5599","s":76,"a":8,"at":"ويطعمون الطعام على حبه مسكينا ويتيما واسيرا","dt":"[8] ويطعمون الطعام مع حبهم له وحاجتهم اليه، فقيرا عاجزا عن الكسب لا يملك ما يكفيه ويسد حاجته، وطفلا مات ابوه وهو دون سن البلوغ ولا مال له، واسيرا اسر في الحرب من المشركين وغيرهم"},{"id":"5600","s":76,"a":9,"at":"انما نطعمكم لوجه الله لا نريد منكم جزاء ولا شكورا","dt":"[9] ويقولون في انفسهم: انما نحسن اليكم ابتغاء مرضاه الله، وطلب ثوابه، لا نبتغي عوضا ولا نقصد حمدا ولا ثناء منكم"},{"id":"5601","s":76,"a":10,"at":"انا نخاف من ربنا يوما عبوسا قمطريرا","dt":"[10] انا نخاف من ربنا يوما شديدا تعبس فيه الوجوه، وتتقطب الجباه من فظاعه امره وشده هوله."},{"id":"5602","s":76,"a":11,"at":"فوقاهم الله شر ذلك اليوم ولقاهم نضره وسرورا","dt":"[11] فوقاهم الله من شدائد ذلك اليوم، واعطاهم حسنا ونورا في وجوههم، وبهجه وفرحا في قلوبهم"},{"id":"5603","s":76,"a":12,"at":"وجزاهم بما صبروا جنه وحريرا","dt":"[12] ، واثابهم بصبرهم في الدنيا على الطاعه جنه عظيمه ياكلون منها ما شاؤوا، ويلبسون فيها الحرير الناعم"},{"id":"5604","s":76,"a":13,"at":"متكئين فيها على الارائك لا يرون فيها شمسا ولا زمهريرا","dt":"[13] متكئين فيها على الاسره المزينه بفاخر الثياب والستور، لا يرون فيها حر شمس ولا شده برد"},{"id":"5605","s":76,"a":14,"at":"ودانيه عليهم ظلالها وذللت قطوفها تذليلا","dt":"[14] وقريبه منهم اشجار الجنه مظلله عليهم، وسهل لهم اخذ ثمارها تسهيلا."},{"id":"5606","s":76,"a":15,"at":"ويطاف عليهم بانيه من فضه واكواب كانت قواريرا","dt":"[15] ويدور عليهم الخدم باواني الطعام الفضيه، واكواب الشراب من الزجاج"},{"id":"5607","s":76,"a":16,"at":"قواريرا من فضه قدروها تقديرا","dt":"[16] زجاج من فضه، قدرها السقاه على مقدار ما يشتهي الشاربون لا تزيد ولا تنقص"},{"id":"5608","s":76,"a":17,"at":"ويسقون فيها كاسا كان مزاجها زنجبيلا","dt":"[17] ويسقى هؤلاء الابرار في الجنه كاسا مملوءه خمرا مزجت بالزنجبيل"},{"id":"5609","s":76,"a":18,"at":"عينا فيها تسمى سلسبيلا","dt":"[18] يشربون من عين في الجنه تسمى سلسبيلا؛ لسلامه شرابها وسهوله مساغه وطيبه."},{"id":"5610","s":76,"a":19,"at":"ويطوف عليهم ولدان مخلدون اذا رايتهم حسبتهم لؤلؤا منثورا","dt":"[19] ويدور على هؤلاء الابرار لخدمتهم غلمان دائمون على حالهم، اذا ابصرتهم ظننتهم -لحسنهم وصفاء الوانهم واشراق وجوههم- اللؤلؤ المفرق المضيء."},{"id":"5611","s":76,"a":20,"at":"واذا رايت ثم رايت نعيما وملكا كبيرا","dt":"[20] واذا ابصرت اي مكان في الجنه رايت فيه نعيما لا يدركه الوصف، وملكا عظيما واسعا لا غايه له."},{"id":"5612","s":76,"a":21,"at":"عاليهم ثياب سندس خضر واستبرق وحلوا اساور من فضه وسقاهم ربهم شرابا طهورا","dt":"[21] يعلوهم ويجمل ابدانهم ثياب بطائنها من الحرير الرقيق الاخضر، وظاهرها من الحرير الغليظ، ويزينون من الحلي باساور من الفضه، وسقاهم ربهم فوق ذلك النعيم شرابا لا رجس فيه ولا دنس."},{"id":"5613","s":76,"a":22,"at":"ان هذا كان لكم جزاء وكان سعيكم مشكورا","dt":"[22] ويقال لهم: ان هذا اعد لكم مقابل اعمالكم الصالحه، وكان عملكم في الدنيا عند الله مرضيا مقبولا."},{"id":"5614","s":76,"a":23,"at":"انا نحن نزلنا عليك القران تنزيلا","dt":"[23] انا نحن نزلنا عليك -ايها الرسول- القران تنزيلا من عندنا؛ لتذكر الناس بما فيه من الوعد والوعيد والثواب والعقاب."},{"id":"5615","s":76,"a":24,"at":"فاصبر لحكم ربك ولا تطع منهم اثما او كفورا","dt":"[24] فاصبر لحكم ربك القدري واقبله، ولحكمه الديني فامض عليه، ولا تطع من المشركين من كان منغمسا في الشهوات او مبالغا في الكفر والضلال"},{"id":"5616","s":76,"a":25,"at":"واذكر اسم ربك بكره واصيلا","dt":"[25] وداوم على ذكر اسم ربك ودعائه في اول النهار واخره."},{"id":"5617","s":76,"a":26,"at":"ومن الليل فاسجد له وسبحه ليلا طويلا","dt":"[26] ومن الليل فاخضع لربك، وصل له، وتهجد له زمنا طويلا فيه."},{"id":"5618","s":76,"a":27,"at":"ان هؤلاء يحبون العاجله ويذرون وراءهم يوما ثقيلا","dt":"[27] ان هؤلاء المشركين يحبون الدنيا، وينشغلون بها، ويتركون خلف ظهورهم العمل للاخره، ولما فيه نجاتهم في يوم عظيم الشدائد."},{"id":"5619","s":76,"a":28,"at":"نحن خلقناهم وشددنا اسرهم واذا شئنا بدلنا امثالهم تبديلا","dt":"[28] نحن خلقناهم، واحكمنا خلقهم، واذا شئنا اهلكناهم، وجئنا بقوم مطيعين ممتثلين لاوامر الله."},{"id":"5620","s":76,"a":29,"at":"ان هذه تذكره فمن شاء اتخذ الى ربه سبيلا","dt":"[29] ان هذه السوره بما فيها من ترغيب وترهيب، ووعد ووعيد عظه للعالمين، فمن اراد الخير لنفسه في الدنيا والاخره اتخذ بالايمان والتقوى طريقا يوصله الى مغفره الله ورضوانه"},{"id":"5621","s":76,"a":30,"at":"وما تشاءون الا ان يشاء الله ان الله كان عليما حكيما","dt":"[30] وما تريدون امرا من الامور الا بتقدير الله ومشيئته. ان الله كان عليما باحوال خلقه، حكيما في تدبيره وصنعه"},{"id":"5622","s":76,"a":31,"at":"يدخل من يشاء في رحمته والظالمين اعد لهم عذابا اليما","dt":"[31] يدخل من يشاء من عباده في رحمته ورضوانه، وهم المؤمنون، واعد للظالمين المتجاوزين حدود الله عذابا موجعا."},{"id":"5623","s":77,"a":1,"at":"والمرسلات عرفا","dt":"[1] اقسم الله تعالى بالرياح حين تهب متتابعه يقفو بعضها بعضا"},{"id":"5624","s":77,"a":2,"at":"فالعاصفات عصفا","dt":"[2] وبالرياح الشديده الهبوب المهلكه"},{"id":"5625","s":77,"a":3,"at":"والناشرات نشرا","dt":"[3] ، وبالملائكه الموكلين بالسحب يسوقونها حيث شاء الله"},{"id":"5626","s":77,"a":4,"at":"فالفارقات فرقا","dt":"[4] وبالملائكه التي تنزل من عند الله بما يفرق بين الحق والباطل والحلال والحرام"},{"id":"5627","s":77,"a":5,"at":"فالملقيات ذكرا","dt":"[5] وبالملائكه التي تتلقى الوحي من عند الله وتنزل به على انبيائه"},{"id":"5628","s":77,"a":6,"at":"عذرا او نذرا","dt":"[6] اعذارا من الله الى خلقه وانذارا منه اليهم؛ لئلا يكون لهم حجه"},{"id":"5629","s":77,"a":7,"at":"انما توعدون لواقع","dt":"[7] . ان الذي توعدون به من امر يوم القيامه وما فيه من حساب وجزاء لنازل بكم لا محاله."},{"id":"5630","s":77,"a":8,"at":"فاذا النجوم طمست","dt":"[8] فاذا النجوم طمست وذهب ضياؤها"},{"id":"5631","s":77,"a":9,"at":"واذا السماء فرجت","dt":"[9] واذا السماء تصدعت"},{"id":"5632","s":77,"a":10,"at":"واذا الجبال نسفت","dt":"[10] واذا الجبال تطايرت وتناثرت وصارت هباء تذروه الرياح"},{"id":"5633","s":77,"a":11,"at":"واذا الرسل اقتت","dt":"[11] واذا الرسل عين لهم وقت واجل للفصل بينهم وبين الامم"},{"id":"5634","s":77,"a":12,"at":"لاي يوم اجلت","dt":"[12] يقال: لاي يوم عظيم اخرت الرسل؟"},{"id":"5635","s":77,"a":13,"at":"ليوم الفصل","dt":"[13] اخرت ليوم القضاء والفصل بين الخلائق"},{"id":"5636","s":77,"a":14,"at":"وما ادراك ما يوم الفصل","dt":"[14] وما اعلمك -ايها الانسان- اي شيء هو يوم الفصل وشدته وهوله؟"},{"id":"5637","s":77,"a":15,"at":"ويل يومئذ للمكذبين","dt":"[15] هلاك عظيم في ذلك اليوم للمكذبين بهذا اليوم الموعود."},{"id":"5638","s":77,"a":16,"at":"الم نهلك الاولين","dt":"[16] الم نهلك السابقين من الامم الماضيه؛ بتكذيبهم للرسل كقوم نوح وعاد وثمود؟"},{"id":"5639","s":77,"a":17,"at":"ثم نتبعهم الاخرين","dt":"[17] ثم نلحق بهم المتاخرين ممن كانوا مثلهم في التكذيب والعصيان"},{"id":"5640","s":77,"a":18,"at":"كذلك نفعل بالمجرمين","dt":"[18] مثل ذلك الاهلاك الفظيع نفعل بهؤلاء المجرمين من كفار «مكه»؛ لتكذيبهم الرسول -صلى الله عليه وسلم-."},{"id":"5641","s":77,"a":19,"at":"ويل يومئذ للمكذبين","dt":"[19] هلاك وعذاب شديد يوم القيامه لكل مكذب بان الله هو الاله الحق وحده لا شريك له، والنبوه، والبعث، والحساب."},{"id":"5642","s":77,"a":20,"at":"الم نخلقكم من ماء مهين","dt":"[20] الم نخلقكم -يا معشر الكفار- من ماء ضعيف حقير وهو النطفه"},{"id":"5643","s":77,"a":21,"at":"فجعلناه في قرار مكين","dt":"[21] فجعلنا هذا الماء في مكان حصين، وهو رحم المراه"},{"id":"5644","s":77,"a":22,"at":"الى قدر معلوم","dt":"[22] الى وقت محدود ومعلوم عند الله تعالى؟"},{"id":"5645","s":77,"a":23,"at":"فقدرنا فنعم القادرون","dt":"[23] فقدرنا على خلقه وتصويره واخراجه، فنعم القادرون نحن."},{"id":"5646","s":77,"a":24,"at":"ويل يومئذ للمكذبين","dt":"[24] هلاك وعذاب شديد يوم القيامه للمكذبين بقدرتنا."},{"id":"5647","s":77,"a":25,"at":"الم نجعل الارض كفاتا","dt":"[25] الم نجعل هذه الارض التي تعيشون عليها، تضم على ظهرها"},{"id":"5648","s":77,"a":26,"at":"احياء ‎وامواتا","dt":"[26] احياء لا يحصون، وفي بطنها امواتا لا يحصرون"},{"id":"5649","s":77,"a":27,"at":"وجعلنا فيها رواسي شامخات واسقيناكم ماء فراتا","dt":"[27] وجعلنا فيها جبالا ثوابت عاليات؛ لئلا تضطرب بكم، واسقيناكم ماء عذبا سائغا؟"},{"id":"5650","s":77,"a":28,"at":"ويل يومئذ للمكذبين","dt":"[28] هلاك وعذاب شديد يوم القيامه للمكذبين بهذه النعم."},{"id":"5651","s":77,"a":29,"at":"انطلقوا الى ما كنتم به تكذبون","dt":"[29] يقال للكافرين يوم القيامه: سيروا الى عذاب جهنم الذي كنتم به تكذبون في الدنيا"},{"id":"5652","s":77,"a":30,"at":"انطلقوا الى ظل ذي ثلاث شعب","dt":"[30] سيروا فاستظلوا بدخان جهنم الذي يتفرع منه ثلاث قطع"},{"id":"5653","s":77,"a":31,"at":"لا ظليل ولا يغني من اللهب","dt":"[31] لا يظل ذلك الظل من حر ذلك اليوم، ولا يدفع من حر اللهب شيئا"},{"id":"5654","s":77,"a":32,"at":"انها ترمي بشرر كالقصر","dt":"[32] ان جهنم تقذف من النار بشرر عظيم، كل شراره منه كالبناء المشيد في العظم والارتفاع"},{"id":"5655","s":77,"a":33,"at":"كانه جماله صفر","dt":"[33] . كان شرر جهنم المتطاير منها ابل سود يميل لونها الى الصفره."},{"id":"5656","s":77,"a":34,"at":"ويل يومئذ للمكذبين","dt":"[34] هلاك وعذاب شديد يوم القيامه للمكذبين بوعيد الله."},{"id":"5657","s":77,"a":35,"at":"هذا يوم لا ينطقون","dt":"[35] هذا يوم القيامه الذي لا ينطق فيه المكذبون بكلام ينفعهم"},{"id":"5658","s":77,"a":36,"at":"ولا يؤذن لهم فيعتذرون","dt":"[36] ولا يكون لهم اذن في الكلام فيعتذرون؛ لانه لا عذر لهم."},{"id":"5659","s":77,"a":37,"at":"ويل يومئذ للمكذبين","dt":"[37] هلاك وعذاب شديد يومئذ للمكذبين بهذا اليوم وما فيه."},{"id":"5660","s":77,"a":38,"at":"هذا يوم الفصل جمعناكم والاولين","dt":"[38] هذا يوم يفصل الله فيه بين الخلائق، ويتميز فيه الحق من الباطل، جمعناكم فيه -يا معشر كفار هذه الامه- مع الكفار الاولين من الامم الماضيه"},{"id":"5661","s":77,"a":39,"at":"فان كان لكم كيد فكيدون","dt":"[39] فان كان لكم حيله في الخلاص من العذاب فاحتالوا، وانقذوا انفسكم من بطش الله وانتقامه."},{"id":"5662","s":77,"a":40,"at":"ويل يومئذ للمكذبين","dt":"[40] هلاك وعذاب شديد يوم القيامه للمكذبين بيوم القيامه."},{"id":"5663","s":77,"a":41,"at":"ان المتقين في ظلال وعيون","dt":"[41] ان الذين خافوا ربهم في الدنيا، واتقوا عذابه بامتثال اوامره واجتناب نواهيه، هم يوم القيامه في ظلال الاشجار الوارفه وعيون الماء الجاريه"},{"id":"5664","s":77,"a":42,"at":"وفواكه مما يشتهون","dt":"[42] وفواكه كثيره مما تشتهيه انفسهم يتنعمون"},{"id":"5665","s":77,"a":43,"at":"كلوا واشربوا هنيئا بما كنتم تعملون","dt":"[43] يقال لهم: كلوا اكلا لذيذا، واشربوا شربا هنيئا؛ بسبب ما قدمتم في الدنيا من صالح الاعمال"},{"id":"5666","s":77,"a":44,"at":"انا كذلك نجزي المحسنين","dt":"[44] انا بمثل ذلك الجزاء العظيم نجزي اهل الاحسان في اعمالهم وطاعتهم لنا"},{"id":"5667","s":77,"a":45,"at":"ويل يومئذ للمكذبين","dt":"[45] هلاك وعذاب شديد يوم القيامه للمكذبين بيوم الجزاء والحساب، وما فيه من النعيم والعذاب."},{"id":"5668","s":77,"a":46,"at":"كلوا وتمتعوا قليلا انكم مجرمون","dt":"[46] ثم هدد الله الكافرين فقال: كلوا من لذائذ الدنيا، واستمتعوا بشهواتها الفانيه زمنا قليلا؛ انكم مجرمون باشراككم بالله."},{"id":"5669","s":77,"a":47,"at":"ويل يومئذ للمكذبين","dt":"[47] هلاك وعذاب شديد يوم القيامه للمكذبين بيوم الحساب والجزاء."},{"id":"5670","s":77,"a":48,"at":"واذا قيل لهم اركعوا لا يركعون","dt":"[48] واذا قيل لهؤلاء المشركين: صلوا لله واخشعوا له، لا يخشعون ولا يصلون، بل يصرون على استكبارهم."},{"id":"5671","s":77,"a":49,"at":"ويل يومئذ للمكذبين","dt":"[49] هلاك وعذاب شديد يوم القيامه للمكذبين بايات الله. ان لم يؤمنوا بهذا القران"},{"id":"5672","s":77,"a":50,"at":"فباي حديث بعده يؤمنون","dt":"[50] فباي كتاب وكلام بعده يؤمنون؟ وهو المبين لكل شيء، الواضح في حكمه واحكامه واخباره، المعجز في الفاظه ومعانيه."},{"id":"5673","s":78,"a":1,"at":"عم يتساءلون","dt":"[1] عن اي شيء يسال بعض كفار قريش بعضا؟"},{"id":"5674","s":78,"a":2,"at":"عن النبا العظيم","dt":"[2] يتساءلون عن الخبر العظيم الشان، وهو القران العظيم الذي ينبئ عن البعث"},{"id":"5675","s":78,"a":3,"at":"الذي هم فيه مختلفون","dt":"[3] الذي شك فيه كفار قريش وكذبوا به."},{"id":"5676","s":78,"a":4,"at":"كلا سيعلمون","dt":"[4] ما الامر كما يزعم هؤلاء المشركون، سيعلم هؤلاء المشركون عاقبه تكذيبهم، ويظهر لهم ما الله فاعل بهم يوم القيامه"},{"id":"5677","s":78,"a":5,"at":"ثم كلا سيعلمون","dt":"[5] ثم سيتاكد لهم ذلك، ويتاكد لهم صدق ما جاء به محمد -صلى الله عليه وسلم-، من القران والبعث.وهذا تهديد ووعيد لهم."},{"id":"5678","s":78,"a":6,"at":"الم نجعل الارض مهادا","dt":"[6] الم نجعل الارض ممهده لكم كالفراش؟"},{"id":"5679","s":78,"a":7,"at":"والجبال اوتادا","dt":"[7] والجبال رواسي؛ كي لا تتحرك بكم الارض؟"},{"id":"5680","s":78,"a":8,"at":"وخلقناكم ازواجا","dt":"[8] وخلقناكم اصنافا ذكرا وانثى؟"},{"id":"5681","s":78,"a":9,"at":"وجعلنا نومكم سباتا","dt":"[9] وجعلنا نومكم راحه لابدانكم، فيه تهدؤون وتسكنون؟"},{"id":"5682","s":78,"a":10,"at":"وجعلنا الليل لباسا","dt":"[10] وجعلنا الليل لباسا تلبسكم ظلمته، وتغشاكم، كما يستر الثوب لابسه؟"},{"id":"5683","s":78,"a":11,"at":"وجعلنا النهار معاشا","dt":"[11] وجعلنا النهار معاشا تنتشرون فيه لمعاشكم، وتسعون فيه لمصالحكم؟"},{"id":"5684","s":78,"a":12,"at":"وبنينا فوقكم سبعا شدادا","dt":"[12] وبنينا فوقكم سبع سموات متينه البناء محكمه الخلق، لا صدوع لها ولا فطور؟"},{"id":"5685","s":78,"a":13,"at":"وجعلنا سراجا وهاجا","dt":"[13] وجعلنا الشمس سراجا وقادا مضيئا؟"},{"id":"5686","s":78,"a":14,"at":"وانزلنا من المعصرات ماء ثجاجا","dt":"[14] وانزلنا من السحب الممطره ماء منصبا بكثره"},{"id":"5687","s":78,"a":15,"at":"لنخرج به حبا ونباتا","dt":"[15] لنخرج به حبا مما يقتات به الناس وحشائش مما تاكله الدواب"},{"id":"5688","s":78,"a":16,"at":"وجنات الفافا","dt":"[16] وبساتين ملتفه بعضها ببعض لتشعب اغصانها؟"},{"id":"5689","s":78,"a":17,"at":"ان يوم الفصل كان ميقاتا","dt":"[17] ان يوم الفصل بين الخلق، وهو يوم القيامه، كان وقتا وميعادا محددا للاولين والاخرين"},{"id":"5690","s":78,"a":18,"at":"يوم ينفخ في الصور فتاتون افواجا","dt":"[18] يوم ينفخ الملك في «القرن» ايذانا بالبعث فتاتون امما، كل امه مع امامهم."},{"id":"5691","s":78,"a":19,"at":"وفتحت السماء فكانت ابوابا","dt":"[19] وفتحت السماء، فكانت ذات ابواب كثيره لنزول الملائكه."},{"id":"5692","s":78,"a":20,"at":"وسيرت الجبال فكانت سرابا","dt":"[20] ونسفت الجبال بعد ثبوتها، فكانت كالسراب."},{"id":"5693","s":78,"a":21,"at":"ان جهنم كانت مرصادا","dt":"[21] ان جهنم كانت يومئذ ترصد اهل الكفر الذين اعدت لهم"},{"id":"5694","s":78,"a":22,"at":"للطاغين مابا","dt":"[22] للكافرين مرجعا"},{"id":"5695","s":78,"a":23,"at":"لابثين فيها احقابا","dt":"[23] ماكثين فيها دهورا متعاقبه لا تنقطع"},{"id":"5696","s":78,"a":24,"at":"لا يذوقون فيها بردا ولا شرابا","dt":"[24] لا يطعمون فيها ما يبرد حر السعير عنهم، ولا شرابا يرويهم"},{"id":"5697","s":78,"a":25,"at":"الا حميما وغساقا","dt":"[25] الا ماء حارا، وصديد اهل النار"},{"id":"5698","s":78,"a":26,"at":"جزاء وفاقا","dt":"[26] يجازون بذلك جزاء عادلا؛ موافقا لاعمالهم التي كانوا يعملونها في الدنيا."},{"id":"5699","s":78,"a":27,"at":"انهم كانوا لا يرجون حسابا","dt":"[27] انهم كانوا لا يخافون يوم الحساب فلم يعملوا له"},{"id":"5700","s":78,"a":28,"at":"وكذبوا باياتنا كذابا","dt":"[28] وكذبوا بما جاءتهم به الرسل تكذيبا"},{"id":"5701","s":78,"a":29,"at":"وكل شيء احصيناه كتابا","dt":"[29] وكل شيء علمناه وكتبناه في اللوح المحفوظ"},{"id":"5702","s":78,"a":30,"at":"فذوقوا فلن نزيدكم الا عذابا","dt":"[30] فذوقوا -ايها الكافرون- جزاء اعمالكم، فلن نزيدكم الا عذابا فوق عذابكم."},{"id":"5703","s":78,"a":31,"at":"ان للمتقين مفازا","dt":"[31] ان للذين يخافون ربهم ويعملون صالحا، فوزا بدخولهم الجنه"},{"id":"5704","s":78,"a":32,"at":"حدائق واعنابا","dt":"[32] ان لهم بساتين عظيمه واعنابا"},{"id":"5705","s":78,"a":33,"at":"وكواعب اترابا","dt":"[33] ولهم زوجات حديثات السن قد استدارت اثداؤهن مع ارتفاع يسير، مستويات في سن واحده"},{"id":"5706","s":78,"a":34,"at":"وكاسا دهاقا","dt":"[34] ولهم كاس مملوءه خمرا"},{"id":"5707","s":78,"a":35,"at":"لا يسمعون فيها لغوا ولا كذابا","dt":"[35] لا يسمعون في هذه الجنه باطلا من القول، ولا يكذب بعضهم بعضا."},{"id":"5708","s":78,"a":36,"at":"جزاء من ربك عطاء حسابا","dt":"[36] لهم كل ذلك جزاء ومنه من الله وعطاء كثيرا كافيا لهم"},{"id":"5709","s":78,"a":37,"at":"رب السموات والارض وما بينهما الرحمن لا يملكون منه خطابا","dt":"[37] رب السموات والارض وما بينهما، رحمن الدنيا والاخره، لا يملكون ان يسالوه الا فيما اذن لهم فيه"},{"id":"5710","s":78,"a":38,"at":"يوم يقوم الروح والملائكه صفا لا يتكلمون الا من اذن له الرحمن وقال صوابا","dt":"[38] يوم يقوم جبريل عليه السلام والملائكه مصطفين، لا يشفعون الا لمن اذن له الرحمن في الشفاعه، وقال حقا وسدادا"},{"id":"5711","s":78,"a":39,"at":"ذلك اليوم الحق فمن شاء اتخذ الى ربه مابا","dt":"[39] ذلك اليوم الحق الذي لا ريب في وقوعه، فمن شاء النجاه من اهواله فليتخذ الى ربه مرجعا بالعمل الصالح."},{"id":"5712","s":78,"a":40,"at":"انا انذرناكم عذابا قريبا يوم ينظر المرء ما قدمت يداه ويقول الكافر ياليتني كنت ترابا","dt":"[40] انا حذرناكم عذاب يوم الاخره القريب الذي يرى فيه كل امرئ ما عمل من خير او اكتسب من اثم، ويقول الكافر من هول الحساب: يا ليتني كنت ترابا فلم ابعث."},{"id":"5713","s":79,"a":1,"at":"والنازعات غرقا","dt":"[1] اقسم الله تعالى بالملائكه التي تنزع ارواح الكفار نزعا شديدا"},{"id":"5714","s":79,"a":2,"at":"والناشطات نشطا","dt":"[2] والملائكه التي تقبض ارواح المؤمنين بنشاط ورفق"},{"id":"5715","s":79,"a":3,"at":"والسابحات سبحا","dt":"[3] والملائكه التي تسبح في نزولها من السماء وصعودها اليها"},{"id":"5716","s":79,"a":4,"at":"فالسابقات سبقا","dt":"[4] فالملائكه التي تسبق وتسارع الى تنفيذ امر الله"},{"id":"5717","s":79,"a":5,"at":"فالمدبرات امرا","dt":"[5] فالملائكه المنفذات امر ربها فيما اوكل اليها تدبيره من شؤون الكون، -ولا يجوز للمخلوق ان يقسم بغير خالقه، فان فعل فقد اشرك- لتبعثن الخلائق وتحاسب"},{"id":"5718","s":79,"a":6,"at":"يوم ترجف الراجفه","dt":"[6] يوم تضطرب الارض بالنفخه الاولى نفخه الاماته"},{"id":"5719","s":79,"a":7,"at":"تتبعها الرادفه","dt":"[7] تتبعها نفخه اخرى للاحياء."},{"id":"5720","s":79,"a":8,"at":"قلوب يومئذ واجفه","dt":"[8] قلوب الكفار يومئذ مضطربه من شده الخوف"},{"id":"5721","s":79,"a":9,"at":"ابصارها خاشعه","dt":"[9] ابصار اصحابها ذليله من هول ما ترى."},{"id":"5722","s":79,"a":10,"at":"يقولون ائنا لمردودون في الحافره","dt":"[10] يقول هؤلاء المكذبون بالبعث: انرد بعد موتنا الى ما كنا عليه احياء في الارض؟"},{"id":"5723","s":79,"a":11,"at":"ائذا كنا عظاما نخره","dt":"[11] انرد وقد صرنا عظاما باليه؟"},{"id":"5724","s":79,"a":12,"at":"قالوا تلك اذا كره خاسره","dt":"[12] قالوا: رجعتنا تلك ستكون اذا خائبه كاذبه."},{"id":"5725","s":79,"a":13,"at":"فانما هي زجره واحده","dt":"[13] فانما هي نفخه واحده"},{"id":"5726","s":79,"a":14,"at":"فاذا هم بالساهره","dt":"[14] فاذا هم احياء على وجه الارض بعد ان كانوا في بطنها."},{"id":"5727","s":79,"a":15,"at":"هل اتاك حديث موسى","dt":"[15] هل اتاك -ايها الرسول- خبر موسى؟"},{"id":"5728","s":79,"a":16,"at":"اذ ناداه ربه بالواد المقدس طوى","dt":"[16] حين ناداه ربه بالوادي المطهر المبارك «طوى»."},{"id":"5729","s":79,"a":17,"at":"اذهب الى فرعون انه طغى","dt":"[17] فقال له: اذهب الى فرعون، انه قد افرط في العصيان"},{"id":"5730","s":79,"a":18,"at":"فقل هل لك الى ان تزكى","dt":"[18] فقل له: اتود ان تطهر نفسك من النقائص وتحليها بالايمان"},{"id":"5731","s":79,"a":19,"at":"واهديك الى ربك فتخشى","dt":"[19] وارشدك الى طاعه ربك، فتخشاه وتتقيه؟"},{"id":"5732","s":79,"a":20,"at":"فاراه الايه الكبرى","dt":"[20] فارى موسى فرعون العلامه العظمى: العصا واليد"},{"id":"5733","s":79,"a":21,"at":"فكذب وعصى","dt":"[21] فكذب فرعون نبي الله موسى عليه السلام، وعصى ربه عز وجل"},{"id":"5734","s":79,"a":22,"at":"ثم ادبر يسعى","dt":"[22] ثم ولى معرضا عن الايمان مجتهدا في معارضه موسى."},{"id":"5735","s":79,"a":23,"at":"فحشر فنادى","dt":"[23] فجمع اهل مملكته وناداهم"},{"id":"5736","s":79,"a":24,"at":"فقال انا ربكم الاعلى","dt":"[24] فقال: انا ربكم الذي لا رب فوقه"},{"id":"5737","s":79,"a":25,"at":"فاخذه الله نكال الاخره والاولى","dt":"[25] فانتقم الله منه بالعذاب في الدنيا والاخره، وجعله عبره ونكالا لامثاله من المتمردين"},{"id":"5738","s":79,"a":26,"at":"ان في ذلك لعبره لمن يخشى","dt":"[26] ان في فرعون وما نزل به من العذاب لموعظه لمن يتعظ وينزجر."},{"id":"5739","s":79,"a":27,"at":"اانتم اشد خلقا ام السماء بناها","dt":"[27] ابعثكم -ايها الناس- بعد الموت اشد في تقديركم ام خلق السماء؟"},{"id":"5740","s":79,"a":28,"at":"رفع سمكها فسواها","dt":"[28] رفعها فوقكم كالبناء، واعلى سقفها في الهواء لا تفاوت فيها ولا فطور"},{"id":"5741","s":79,"a":29,"at":"واغطش ليلها واخرج ضحاها","dt":"[29] واظلم ليلها بغروب شمسها، وابرز نهارها بشروقها"},{"id":"5742","s":79,"a":30,"at":"والارض بعد ذلك دحاها","dt":"[30] والارض بعد خلق السماء بسطها، واودع فيها منافعها"},{"id":"5743","s":79,"a":31,"at":"اخرج منها ماءها ومرعاها","dt":"[31] وفجر فيها عيون الماء، وانبت فيها ما يرعى من النباتات"},{"id":"5744","s":79,"a":32,"at":"والجبال ارساها","dt":"[32] واثبت فيها الجبال اوتادا لها"},{"id":"5745","s":79,"a":33,"at":"متاعا لكم ولانعامكم","dt":"[33] خلق سبحانه كل هذه النعم منفعه لكم ولانعامكم. ان اعاده خلقكم يوم القيامه اهون على الله من خلق هذه الاشياء، وكله على الله هين يسير."},{"id":"5746","s":79,"a":34,"at":"فاذا جاءت الطامه الكبرى","dt":"[34] فاذا جاءت القيامه الكبرى والشده العظمى وهي النفخه الثانيه"},{"id":"5747","s":79,"a":35,"at":"يوم يتذكر الانسان ما سعى","dt":"[35] عندئذ يعرض على الانسان كل عمله من خير وشر، فيتذكره"},{"id":"5748","s":79,"a":36,"at":"وبرزت الجحيم لمن يرى","dt":"[36] واظهرت جهنم لكل مبصر ترى عيانا."},{"id":"5749","s":79,"a":37,"at":"فاما من طغى","dt":"[37] فاما من تمرد على امر الله"},{"id":"5750","s":79,"a":38,"at":"واثر الحياه الدنيا","dt":"[38] وفضل الحياه الدنيا على الاخره"},{"id":"5751","s":79,"a":39,"at":"فان الجحيم هي الماوى","dt":"[39] فان مصيره الى النار."},{"id":"5752","s":79,"a":40,"at":"واما من خاف مقام ربه ونهى النفس عن الهوى","dt":"[40] واما من خاف القيام بين يدي الله للحساب، ونهى النفس عن الاهواء الفاسده"},{"id":"5753","s":79,"a":41,"at":"فان الجنه هي الماوى","dt":"[41] فان الجنه هي مسكنه."},{"id":"5754","s":79,"a":42,"at":"يسالونك عن الساعه ايان مرساها","dt":"[42] يسالك المشركون - ايها الرسول -استخفافا- عن وقت حلول الساعه التي تتوعدهم بها"},{"id":"5755","s":79,"a":43,"at":"فيم انت من ذكراها","dt":"[43] لست في شيء من علمها"},{"id":"5756","s":79,"a":44,"at":"الى ربك منتهاها","dt":"[44] بل مرد ذلك الى الله عز وجل"},{"id":"5757","s":79,"a":45,"at":"انما انت منذر من يخشاها","dt":"[45] وانما شانك في امر الساعه ان تحذر منها من يخافها"},{"id":"5758","s":79,"a":46,"at":"كانهم يوم يرونها لم يلبثوا الا عشيه او ضحاها","dt":"[46] كانهم يوم يرون قيام الساعه لم يلبثوا في الحياه الدنيا؛ لهول الساعه الا ما بين الظهر الى غروب الشمس، او ما بين طلوع الشمس الى نصف النهار."},{"id":"5759","s":80,"a":1,"at":"عبس وتولى","dt":"[1] ظهر التغير والعبوس في وجه الرسول صلى الله عليه وسلم"},{"id":"5760","s":80,"a":2,"at":"ان جاءه الاعمى","dt":"[2] واعرض لاجل ان الاعمى عبدالله بن ام مكتوم جاءه مسترشدا، وكان الرسول -صلى الله عليه وسلم- منشغلا بدعوه كبار قريش الى الاسلام."},{"id":"5761","s":80,"a":3,"at":"وما يدريك لعله يزكى","dt":"[3] واي شيء يجعلك عالما بحقيقه امره؟ لعله بسؤاله تزكو نفسه وتطهر"},{"id":"5762","s":80,"a":4,"at":"او يذكر فتنفعه الذكرى","dt":"[4]او يحصل له المزيد من الاعتبار والازدجار."},{"id":"5763","s":80,"a":5,"at":"اما من استغنى","dt":"[5] اما من استغنى عن هديك"},{"id":"5764","s":80,"a":6,"at":"فانت له تصدى","dt":"[6] فانت تتعرض له وتصغي الى كلامه"},{"id":"5765","s":80,"a":7,"at":"وما عليك الا يزكى","dt":"[7] واي شيء عليك الا يتطهر من كفره؟"},{"id":"5766","s":80,"a":8,"at":"واما من جاءك يسعى","dt":"[8] واما من كان حريصا على لقائك"},{"id":"5767","s":80,"a":9,"at":"وهو يخشى","dt":"[9] وهو يخشى الله من التقصير في الاسترشاد"},{"id":"5768","s":80,"a":10,"at":"فانت عنه تلهى","dt":"[10] فانت عنه تتشاغل"},{"id":"5769","s":80,"a":11,"at":"كلا انها تذكره","dt":"[11] . ليس الامر كما فعلت -ايها الرسول-، ان هذه السوره بما اشتملت عليه من الهدايه موعظه لك ولكل من شاء الاتعاظ"},{"id":"5770","s":80,"a":12,"at":"فمن شاء ذكره","dt":"[12] فمن شاء ذكر الله واتم بوحيه"},{"id":"5771","s":80,"a":13,"at":"في صحف مكرمه","dt":"[13] هذا الوحي، وهو القران في صحف معظمه، موقره"},{"id":"5772","s":80,"a":14,"at":"مرفوعه مطهره","dt":"[14] عاليه القدر مطهره من الدنس والزياده والنقص"},{"id":"5773","s":80,"a":15,"at":"بايدي سفره","dt":"[15] بايدي ملائكه كتبه، سفراء بين الله وخلقه"},{"id":"5774","s":80,"a":16,"at":"كرام برره","dt":"[16] كرام الخلق، اخلاقهم وافعالهم باره طاهره."},{"id":"5775","s":80,"a":17,"at":"قتل الانسان ما اكفره","dt":"[17] لعن الانسان الكافر وعذب، ما اشد كفره بربه!"},{"id":"5776","s":80,"a":18,"at":"من اي شيء خلقه","dt":"[18] الم ير من اي شيء خلقه الله اول مره؟"},{"id":"5777","s":80,"a":19,"at":"من نطفه خلقه فقدره","dt":"[19] خلقه الله من ماء قليل -وهو المني- فقدره اطوارا"},{"id":"5778","s":80,"a":20,"at":"ثم السبيل يسره","dt":"[20] ثم بين له طريق الخير والشر"},{"id":"5779","s":80,"a":21,"at":"ثم اماته فاقبره","dt":"[21] ثم اماته فجعل له مكانا يقبر فيه"},{"id":"5780","s":80,"a":22,"at":"ثم اذا شاء انشره","dt":"[22] ثم اذا شاء سبحانه احياه، وبعثه بعد موته للحساب والجزاء"},{"id":"5781","s":80,"a":23,"at":"كلا لما يقض ما امره","dt":"[23] ليس الامر كما يقول الكافر ويفعل، فلم يؤد ما امره الله به من الايمان والعمل بطاعته."},{"id":"5782","s":80,"a":24,"at":"فلينظر الانسان الى طعامه","dt":"[24] فليتدبر الانسان: كيف خلق الله طعامه الذي هو قوام حياته؟"},{"id":"5783","s":80,"a":25,"at":"انا صببنا الماء صبا","dt":"[25] بانا صببنا الماء على الارض صبا"},{"id":"5784","s":80,"a":26,"at":"ثم شققنا الارض شقا","dt":"[26] ثم شققناها بما اخرجنا منها من نبات شتى"},{"id":"5785","s":80,"a":27,"at":"فانبتنا فيها حبا","dt":"[27] فانبتنا فيها حبا"},{"id":"5786","s":80,"a":28,"at":"وعنبا وقضبا","dt":"[28] وعنبا وعلفا للدواب"},{"id":"5787","s":80,"a":29,"at":"وزيتونا ونخلا","dt":"[29] وزيتونا ونخلا،"},{"id":"5788","s":80,"a":30,"at":"وحدائق غلبا","dt":"[30] وحدائق عظيمه الاشجار"},{"id":"5789","s":80,"a":31,"at":"وفاكهه وابا","dt":"[31] وثمارا وكلا"},{"id":"5790","s":80,"a":32,"at":"متاعا لكم ولانعامكم","dt":"[32] تنعمون بها انتم وانعامكم."},{"id":"5791","s":80,"a":33,"at":"فاذا جاءت الصاخه","dt":"[33] فاذا جاءت صيحه البعث يوم القيامه التي تصم من هولها الاسماع"},{"id":"5792","s":80,"a":34,"at":"يوم يفر المرء من اخيه","dt":"[34] يوم يفر المرء لهول ذلك اليوم من اخيه"},{"id":"5793","s":80,"a":35,"at":"وامه وابيه","dt":"[35] وامه وابيه"},{"id":"5794","s":80,"a":36,"at":"وصاحبته وبنيه","dt":"[36] وزوجه وبنيه"},{"id":"5795","s":80,"a":37,"at":"لكل امرئ منهم يومئذ شان يغنيه","dt":"[37] لكل واحد منهم يومئذ امر يمنعه من الانشغال بغيره."},{"id":"5796","s":80,"a":38,"at":"وجوه يومئذ مسفره","dt":"[38] وجوه اهل النعيم في ذلك اليوم مستنيره"},{"id":"5797","s":80,"a":39,"at":"ضاحكه مستبشره","dt":"[39] مسروره فرحه"},{"id":"5798","s":80,"a":40,"at":"ووجوه يومئذ عليها غبره","dt":"[40] ووجوه اهل الجحيم مظلمه مسوده."},{"id":"5799","s":80,"a":41,"at":"ترهقها قتره","dt":"[41] تغشاها ذله"},{"id":"5800","s":80,"a":42,"at":"اولئك هم الكفره الفجره","dt":"[42] اولئك الموصوفون بهذا الوصف هم الذين كفروا بنعم الله وكذبوا باياته، وتجرؤوا على محارمه بالفجور والطغيان."},{"id":"5801","s":81,"a":1,"at":"اذا الشمس كورت","dt":"[1] اذا الشمس لفت وذهب ضوءها"},{"id":"5802","s":81,"a":2,"at":"واذا النجوم انكدرت","dt":"[2] واذا النجوم تناثرت، فذهب نورها"},{"id":"5803","s":81,"a":3,"at":"واذا الجبال سيرت","dt":"[3] واذا الجبال سيرت عن وجه الارض فصارت غبارا متطايرا"},{"id":"5804","s":81,"a":4,"at":"واذا العشار عطلت","dt":"[4] واذا النوق الحوامل تركت واهملت"},{"id":"5805","s":81,"a":5,"at":"واذا الوحوش حشرت","dt":"[5] واذا الحيوانات الوحشيه جمعت واختلطت؛ ليقتص الله من بعضها لبعض"},{"id":"5806","s":81,"a":6,"at":"واذا البحار سجرت","dt":"[6] واذا البحار اوقدت، فصارت على عظمها نارا تتوقد"},{"id":"5807","s":81,"a":7,"at":"واذا النفوس زوجت","dt":"[7] واذا النفوس قرنت بامثالها ونظائرها"},{"id":"5808","s":81,"a":8,"at":"واذا الموءوده سئلت","dt":"[8] واذا الطفله المدفونه حيه سئلت يوم القيامه سؤال تطييب لها وتبكيت لوائدها"},{"id":"5809","s":81,"a":9,"at":"باي ذنب قتلت","dt":"[9] باي ذنب كان دفنها؟"},{"id":"5810","s":81,"a":10,"at":"واذا الصحف نشرت","dt":"[10] واذا صحف الاعمال عرضت"},{"id":"5811","s":81,"a":11,"at":"واذا السماء كشطت","dt":"[11] واذا السماء قلعت وازيلت من مكانها"},{"id":"5812","s":81,"a":12,"at":"واذا الجحيم سعرت","dt":"[12] واذا النار اوقدت فاضرمت"},{"id":"5813","s":81,"a":13,"at":"واذا الجنه ازلفت","dt":"[13] واذا الجنه دار النعيم قربت من اهلها المتقين"},{"id":"5814","s":81,"a":14,"at":"علمت نفس ما احضرت","dt":"[14] اذا وقع ذلك، تيقنت ووجدت كل نفس ما قدمت من خير او شر."},{"id":"5815","s":81,"a":15,"at":"فلا اقسم بالخنس","dt":"[15] اقسم الله تعالى بالنجوم المختفيه انوارها نهارا"},{"id":"5816","s":81,"a":16,"at":"الجوار الكنس","dt":"[16] الجاريه والمستتره في ابراجها"},{"id":"5817","s":81,"a":17,"at":"والليل اذا عسعس","dt":"[17] والليل اذا اقبل بظلامه"},{"id":"5818","s":81,"a":18,"at":"والصبح اذا تنفس","dt":"[18] والصبح اذا ظهر ضياؤه"},{"id":"5819","s":81,"a":19,"at":"انه لقول رسول كريم","dt":"[19] ان القران لتبليغ رسول كريم هو جبريل عليه السلام"},{"id":"5820","s":81,"a":20,"at":"ذي قوه عند ذي العرش مكين","dt":"[20] ذي قوه في تنفيذ ما يؤمر به، صاحب مكانه رفيعه عند الله"},{"id":"5821","s":81,"a":21,"at":"مطاع ثم امين","dt":"[21] تطيعه الملائكه، مؤتمن على الوحي الذي ينزل به."},{"id":"5822","s":81,"a":22,"at":"وما صاحبكم بمجنون","dt":"[22] وما محمد الذي تعرفونه بمجنون"},{"id":"5823","s":81,"a":23,"at":"ولقد راه بالافق المبين","dt":"[23] ولقد راى محمد -صلى الله عليه وسلم- جبريل الذي ياتيه بالرساله على صورته الحقيقيه التي خلقه الله عليها في الافق العظيم من ناحيه المشرق ب«مكه»، وهي الرؤيه الاولى الواقعه ب«غار حراء»"},{"id":"5824","s":81,"a":24,"at":"وما هو على الغيب بضنين","dt":"[24] وما محمد -صلى الله عليه وسلم- ببخيل في تبليغ الوحي"},{"id":"5825","s":81,"a":25,"at":"وما هو بقول شيطان رجيم","dt":"[25] وما هذا القران بقول شيطان رجيم، مطرود من رحمه الله، ولكنه كلام الله ووحيه."},{"id":"5826","s":81,"a":26,"at":"فاين تذهبون","dt":"[26] فاين تذهب بكم عقولكم في التكذيب بالقران بعد هذه الحجج القاطعه؟"},{"id":"5827","s":81,"a":27,"at":"ان هو الا ذكر للعالمين","dt":"[27] ما هو الا موعظه من الله لجميع الناس"},{"id":"5828","s":81,"a":28,"at":"لمن شاء منكم ان يستقيم","dt":"[28] لمن شاء منكم ان يستقيم على الحق والايمان"},{"id":"5829","s":81,"a":29,"at":"وما تشاءون الا ان يشاء الله رب العالمين","dt":"[29] وما تشاؤون الاستقامه، ولا تقدرون على ذلك، الا بمشيئه الله رب الخلائق اجمعين."},{"id":"5830","s":82,"a":1,"at":"اذا السماء انفطرت","dt":"[1] اذا السماء انشقت، واختل نظامها."},{"id":"5831","s":82,"a":2,"at":"واذا الكواكب انتثرت","dt":"[2] اواذا الكواكب تساقطت"},{"id":"5832","s":82,"a":3,"at":"واذا البحار فجرت","dt":"[3] واذا البحار فجر الله بعضها في بعض، فذهب ماؤها"},{"id":"5833","s":82,"a":4,"at":"واذا القبور بعثرت","dt":"[4] واذا القبور قلبت ببعث من كان فيها"},{"id":"5834","s":82,"a":5,"at":"علمت نفس ما قدمت واخرت","dt":"[5] حينئذ تعلم كل نفس جميع اعمالها، ما تقدم منها وما تاخر، وجوزيت بها."},{"id":"5835","s":82,"a":6,"at":"ياايها الانسان ما غرك بربك الكريم","dt":"[6] يا ايها الانسان المنكر للبعث، ما الذي جعلك تغتر بربك الجواد الكثير الخير، الحقيق بالشكر والطاعه"},{"id":"5836","s":82,"a":7,"at":"الذي خلقك فسواك فعدلك","dt":"[7] اليس هو الذي خلقك فسوى خلقك فعدلك، وركبك لاداء وظائفك"},{"id":"5837","s":82,"a":8,"at":"في اي صوره ما شاء ركبك","dt":"8] في اي صوره شاءها خلقك؟"},{"id":"5838","s":82,"a":9,"at":"كلا بل تكذبون بالدين","dt":"[9] ليس الامر كما تقولون من انكم في عبادتكم غير الله محقون، بل تكذبون بيوم الحساب والجزاء"},{"id":"5839","s":82,"a":10,"at":"وان عليكم لحافظين","dt":"[10] وان عليكم لملائكه رقباء"},{"id":"5840","s":82,"a":11,"at":"كراما كاتبين","dt":"[11] كراما على الله كاتبين لما وكلوا باحصائه، لا يفوتهم من اعمالكم شيء"},{"id":"5841","s":82,"a":12,"at":"يعلمون ما تفعلون","dt":"[12] يعلمون ما تفعلون من خير او شر."},{"id":"5842","s":82,"a":13,"at":"ان الابرار لفي نعيم","dt":"[13] ان الاتقياء القائمين بحقوق الله وحقوق عباده لفي نعيم."},{"id":"5843","s":82,"a":14,"at":"وان الفجار لفي جحيم","dt":"[14] وان الفجار الذين قصروا في حقوق الله وحقوق عباده لفي جحيم"},{"id":"5844","s":82,"a":15,"at":"يصلونها يوم الدين","dt":"[15] يصيبهم لهبها يوم الجزاء"},{"id":"5845","s":82,"a":16,"at":"وما هم عنها بغائبين","dt":"[16] وما هم عن عذاب جهنم بغائبين لا بخروج ولا بموت."},{"id":"5846","s":82,"a":17,"at":"وما ادراك ما يوم الدين","dt":"[17] وما ادراك ما عظمه يوم الحساب"},{"id":"5847","s":82,"a":18,"at":"ثم ما ادراك ما يوم الدين","dt":"[18] ثم ما ادراك ما عظمه يوم الحساب؟"},{"id":"5848","s":82,"a":19,"at":"يوم لا تملك نفس لنفس شيئا والامر يومئذ لله","dt":"[19] يوم الحساب لا يقدر احد على نفع احد، والامر في ذلك اليوم لله وحده الذي لا يغلبه غالب، ولا يقهره قاهر، ولا ينازعه احد."},{"id":"5849","s":83,"a":1,"at":"ويل للمطففين","dt":"[1] عذاب شديد للذين يبخسون المكيال والميزان"},{"id":"5850","s":83,"a":2,"at":"الذين اذا اكتالوا على الناس يستوفون","dt":"[2] الذين اذا اشتروا من الناس مكيلا او موزونا يوفون لانفسهم"},{"id":"5851","s":83,"a":3,"at":"واذا كالوهم او وزنوهم يخسرون","dt":"[3] واذا باعوا الناس مكيلا او موزونا ينقصون في المكيال والميزان، فكيف بحال من يسرقهما ويختلسهما، ويبخس الناس اشياءهم؟ انه اولى بالوعيد من مطففي المكيال والميزان"},{"id":"5852","s":83,"a":4,"at":"الا يظن اولئك انهم مبعوثون","dt":"[4] الا يعتقد اولئك المطففون ان الله تعالى باعثهم ومحاسبهم على اعمالهم؟"},{"id":"5853","s":83,"a":5,"at":"ليوم عظيم","dt":"[5] سيكون بعثهم في يوم عظيم الهول"},{"id":"5854","s":83,"a":6,"at":"يوم يقوم الناس لرب العالمين","dt":"[6] يوم يقوم الناس بين يدي الله، فيحاسبهم على القليل والكثير، وهم فيه خاضعون لله رب العالمين."},{"id":"5855","s":83,"a":7,"at":"كلا ان كتاب الفجار لفي سجين","dt":"[7] حقا ان مصير الفجار وماواهم لفي ضيق"},{"id":"5856","s":83,"a":8,"at":"وما ادراك ما سجين","dt":"[8] وما ادراك ما هذا الضيق؟"},{"id":"5857","s":83,"a":9,"at":"كتاب مرقوم","dt":"[9] انه سجن مقيم وعذاب اليم، وهو ما كتب لهم المصير اليه، مكتوب مفروغ منه، لا يزاد فيه ولا ينقص."},{"id":"5858","s":83,"a":10,"at":"ويل يومئذ للمكذبين","dt":"[10] عذاب شديد يومئذ للمكذبين"},{"id":"5859","s":83,"a":11,"at":"الذين يكذبون بيوم الدين","dt":"[11] الذين يكذبون بوقوع يوم الجزاء"},{"id":"5860","s":83,"a":12,"at":"وما يكذب به الا كل معتد اثيم","dt":"[12] وما يكذب به الا كل ظالم كثير الاثم"},{"id":"5861","s":83,"a":13,"at":"اذا تتلى عليه اياتنا قال اساطير الاولين","dt":"[13] اذا تتلى عليه ايات القران قال: هذه اباطيل الاولين"},{"id":"5862","s":83,"a":14,"at":"كلا بل ران على قلوبهم ما كانوا يكسبون","dt":"[14] ليس الامر كما زعموا، بل هو كلام الله ووحيه الى نبيه، وانما حجب قلوبهم عن التصديق به ما غشاها من كثره ما يرتكبون من الذنوب"},{"id":"5863","s":83,"a":15,"at":"كلا انهم عن ربهم يومئذ لمحجوبون","dt":"[15] ليس الامر كما زعم الكفار، بل انهم يوم القيامه عن رؤيه ربهم -جل وعلا- لمحجوبون. وفي هذه الايه دلاله على رؤيه المؤمنين ربهم في الجنه."},{"id":"5864","s":83,"a":16,"at":"ثم انهم لصالوا الجحيم","dt":"[16] ثم انهم لداخلو النار يقاسون حرها"},{"id":"5865","s":83,"a":17,"at":"ثم يقال هذا الذي كنتم به تكذبون","dt":"[17] ثم يقال لهم: هذا الجزاء الذي كنتم به تكذبون."},{"id":"5866","s":83,"a":18,"at":"كلا ان كتاب الابرار لفي عليين","dt":"[18] حقا ان كتاب الابرار -وهم المتقون- لفي المراتب العاليه في الجنه"},{"id":"5867","s":83,"a":19,"at":"وما ادراك ما عليون","dt":"[19] وما ادراك -ايها الرسول- ما هذه المراتب العاليه؟"},{"id":"5868","s":83,"a":20,"at":"كتاب مرقوم","dt":"[20] كتاب الابرار مكتوب مفروغ منه، لا يزاد فيه ولا ينقص"},{"id":"5869","s":83,"a":21,"at":"يشهده المقربون","dt":"[21] يطلع عليه المقربون من ملائكه كل سماء."},{"id":"5870","s":83,"a":22,"at":"ان الابرار لفي نعيم","dt":"[22] ان اهل الصدق والطاعه لفي الجنه يتنعمون"},{"id":"5871","s":83,"a":23,"at":"على الارائك ينظرون","dt":"[23] على الاسره ينظرون الى ربهم، والى ما اعد لهم من خيرات"},{"id":"5872","s":83,"a":24,"at":"تعرف في وجوههم نضره النعيم","dt":"[24] ترى في وجوههم بهجه النعيم"},{"id":"5873","s":83,"a":25,"at":"يسقون من رحيق مختوم","dt":"[25] يسقون من خمر صافيه محكم اناؤها"},{"id":"5874","s":83,"a":26,"at":"ختامه مسك وفي ذلك فليتنافس المتنافسون","dt":"[26] اخره رائحه مسك، وفي ذلك النعيم المقيم فليتسابق المتسابقون"},{"id":"5875","s":83,"a":27,"at":"ومزاجه من تسنيم","dt":"[27] وهذا الشراب مزاجه وخلطه من عين في الجنه تعرف لعلوها ب«تسنيم»"},{"id":"5876","s":83,"a":28,"at":"عينا يشرب بها المقربون","dt":"[28] عين اعدت؛ ليشرب منها المقربون، ويتلذذوا بها."},{"id":"5877","s":83,"a":29,"at":"ان الذين اجرموا كانوا من الذين امنوا يضحكون","dt":"[29] ان الذين اجرموا كانوا في الدنيا يستهزئون بالمؤمنين"},{"id":"5878","s":83,"a":30,"at":"واذا مروا بهم يتغامزون","dt":"[30] واذا مروا بهم يتغامزون سخريه بهم"},{"id":"5879","s":83,"a":31,"at":"واذا انقلبوا الى اهلهم انقلبوا فكهين","dt":"[31] واذا رجع الذين اجرموا الى اهلهم وذويهم تفكهوا معهم بالسخريه من المؤمنين"},{"id":"5880","s":83,"a":32,"at":"واذا راوهم قالوا ان هؤلاء لضالون","dt":"[32] واذا راى هؤلاء الكفار اصحاب محمد -صلى الله عليه وسلم-، وقد اتبعوا الهدى قالوا: ان هؤلاء لتائهون في اتباعهم محمدا -صلى الله عليه وسلم-"},{"id":"5881","s":83,"a":33,"at":"وما ارسلوا عليهم حافظين","dt":"[33] وما بعث هؤلاء المجرمون رقباء على اصحاب محمد -صلى الله عليه وسلم-."},{"id":"5882","s":83,"a":34,"at":"فاليوم الذين امنوا من الكفار يضحكون","dt":"[34] فيوم القيامه يسخر الذين صدقوا الله ورسوله وعملوا بشرعه من الكفار، كما سخر الكافرون منهم في الدنيا."},{"id":"5883","s":83,"a":35,"at":"على الارائك ينظرون","dt":"[35] على المجالس الفاخره ينظر المؤمنون الى ما اعطاهم الله من الكرامه والنعيم في الجنه، ومن اعظم ذلك النظر الى وجه الله الكريم"},{"id":"5884","s":83,"a":36,"at":"هل ثوب الكفار ما كانوا يفعلون","dt":"[36] هل جوزي الكفار من جنس اعمالهم، جزاء وفاق ما كانوا يفعلونه في الدنيا من الشرور والاثام؟نعم، سيجزون اوفى الجزاء واعدله."},{"id":"5885","s":84,"a":1,"at":"اذا السماء انشقت","dt":"[1] اذا السماء تصدعت، وتفطرت بالغمام يوم القيامه"},{"id":"5886","s":84,"a":2,"at":"واذنت لربها وحقت","dt":"[2] واطاعت امر ربها فيما امرها به من الانشقاق، وحق لها ان تنقاد لامره"},{"id":"5887","s":84,"a":3,"at":"واذا الارض مدت","dt":"[3] و اذا الارض بسطت ووسعت، ودكت جبالها في ذلك اليوم"},{"id":"5888","s":84,"a":4,"at":"والقت ما فيها وتخلت","dt":"[4] وقذفت ما في بطنها من الاموات، وتخلت عنهم"},{"id":"5889","s":84,"a":5,"at":"واذنت لربها وحقت","dt":"[5] وانقادت لربها فيما امرها به، وحق لها ان تنقاد لامره."},{"id":"5890","s":84,"a":6,"at":"ياايها الانسان انك كادح الى ربك كدحا فملاقيه","dt":"[6] يا ايها الانسان انك ساع الى الله، وعامل اعمالا من خير او شر، ثم تلاقي الله يوم القيامه، فيجازيك بعملك بفضله او عدله."},{"id":"5891","s":84,"a":7,"at":"فاما من اوتي كتابه بيمينه","dt":"[7] فاما من اعطي صحيفه اعماله بيمينه، وهو المؤمن بربه"},{"id":"5892","s":84,"a":8,"at":"فسوف يحاسب حسابا يسيرا","dt":"[8] فسوف يحاسب حسابا سهلا"},{"id":"5893","s":84,"a":9,"at":"وينقلب الى اهله مسرورا","dt":"[9] ويرجع الى اهله في الجنه مسرورا."},{"id":"5894","s":84,"a":10,"at":"واما من اوتي كتابه وراء ظهره","dt":"[10] واما من اعطي صحيفه اعماله من وراء ظهره، وهو الكافر بالله"},{"id":"5895","s":84,"a":11,"at":"فسوف يدعو ثبورا","dt":"[11] فسوف يدعو بالهلاك والثبور"},{"id":"5896","s":84,"a":12,"at":"ويصلى سعيرا","dt":"[12] ويدخل النار مقاسيا حرها"},{"id":"5897","s":84,"a":13,"at":"انه كان في اهله مسرورا","dt":"[13] انه كان في اهله في الدنيا مسرورا مغرورا، لا يفكر في العواقب"},{"id":"5898","s":84,"a":14,"at":"انه ظن ان لن يحور","dt":"[14] انه ظن ان لن يرجع الى خالقه حيا للحساب"},{"id":"5899","s":84,"a":15,"at":"بلى ان ربه كان به بصيرا","dt":"[15] بلى سيعيده الله كما بداه ويجازيه على اعماله، ان ربه كان به بصيرا عليما بحاله من يوم خلقه الى ان بعثه."},{"id":"5900","s":84,"a":16,"at":"فلا اقسم بالشفق","dt":"[16] اقسم الله تعالى باحمرار الافق عند الغروب"},{"id":"5901","s":84,"a":17,"at":"والليل وما وسق","dt":"[17] وبالليل وما جمع من الدواب والحشرات والهوام وغير ذلك"},{"id":"5902","s":84,"a":18,"at":"والقمر اذا اتسق","dt":"[18] وبالقمر اذا تكامل نوره"},{"id":"5903","s":84,"a":19,"at":"لتركبن طبقا عن طبق","dt":"[19] لتركبن -ايها الناس- اطوارا متعدده واحوالا متباينه: من النطفه الى العلقه الى المضغه الى نفخ الروح الى الموت الى البعث والنشور. ولا يجوز للمخلوق ان يقسم بغير الله، ولو فعل ذلك لاشرك."},{"id":"5904","s":84,"a":20,"at":"فما لهم لا يؤمنون","dt":"[20] فاي شيء يمنعهم من الايمان بالله واليوم الاخر بعد ما وضحت لهم الايات؟"},{"id":"5905","s":84,"a":21,"at":"واذا قرئ عليهم القران لا يسجدون","dt":"[21] وما لهم اذا قرئ عليهم القران لا يسجدون لله، ولا يسلمون بما جاء فيه؟"},{"id":"5906","s":84,"a":22,"at":"بل الذين كفروا يكذبون","dt":"[22] انما سجيه الذين كفروا التكذيب ومخالفه الحق"},{"id":"5907","s":84,"a":23,"at":"والله اعلم بما يوعون","dt":"[23] والله اعلم بما يكتمون في صدورهم من العناد مع علمهم بان ما جاء به القران حق"},{"id":"5908","s":84,"a":24,"at":"فبشرهم بعذاب اليم","dt":"[24] فبشرهم -ايها الرسول- بان الله -عز وجل- قد اعد لهم عذابا موجعا."},{"id":"5909","s":84,"a":25,"at":"الا الذين امنوا وعملوا الصالحات لهم اجر غير ممنون","dt":"[25] لكن الذين امنوا بالله ورسوله وادوا ما فرضه الله عليهم، لهم اجر في الاخره غير مقطوع ولا منقوص."},{"id":"5910","s":85,"a":1,"at":"والسماء ذات البروج","dt":"[1] اقسم الله تعالى بالسماء ذات المنازل التي تمر بها الشمس والقمر"},{"id":"5911","s":85,"a":2,"at":"واليوم الموعود","dt":"[2] وبيوم القيامه الذي وعد الله الخلق ان يجمعهم فيه"},{"id":"5912","s":85,"a":3,"at":"وشاهد ومشهود","dt":"[3] وشاهد يشهد، ومشهود يشهد عليه، -ويقسم الله -سبحانه- بما يشاء من مخلوقاته، اما المخلوق فلا يجوز له ان يقسم بغير الله، فان القسم بغير الله شرك"},{"id":"5913","s":85,"a":4,"at":"قتل اصحاب الاخدود","dt":"[4] لعن الذين شقوا في الارض شقا عظيما؛ لتعذيب المؤمنين"},{"id":"5914","s":85,"a":5,"at":"النار ذات الوقود","dt":"[5] واوقدوا النار الشديده ذات الوقود"},{"id":"5915","s":85,"a":6,"at":"اذ هم عليها قعود","dt":"[6] اذ هم قعود على الاخدود ملازمون له"},{"id":"5916","s":85,"a":7,"at":"وهم على ما يفعلون بالمؤمنين شهود","dt":"[7] وهم على ما يفعلون بالمؤمنين من تنكيل وتعذيب حضور"},{"id":"5917","s":85,"a":8,"at":"وما نقموا منهم الا ان يؤمنوا بالله العزيز الحميد","dt":"[8] وما اخذوهم بمثل هذا العقاب الشديد الا ان كانوا مؤمنين بالله العزيز الذي لا يغالب، الحميد في اقواله وافعاله واوصافه"},{"id":"5918","s":85,"a":9,"at":"الذي له ملك السموات والارض والله على كل شيء شهيد","dt":"[9] الذي له ملك السموات والارض، وهو -سبحانه- على كل شيء شهيد، لا يخفى عليه شيء."},{"id":"5919","s":85,"a":10,"at":"ان الذين فتنوا المؤمنين والمؤمنات ثم لم يتوبوا فلهم عذاب جهنم ولهم عذاب الحريق","dt":"[10] ان الذين حرقوا المؤمنين والمؤمنات بالنار؛ ليصرفوهم عن دين الله، ثم لم يتوبوا، فلهم في الاخره عذاب جهنم، ولهم العذاب الشديد المحرق."},{"id":"5920","s":85,"a":11,"at":"ان الذين امنوا وعملوا الصالحات لهم جنات تجري من تحتها الانهار ذلك الفوز الكبير","dt":"[11] ان الذين صدقوا الله ورسوله وعملوا الاعمال الصالحات، لهم جنات تجري من تحت قصورها واشجارها الانهار، ذلك الفوز العظيم."},{"id":"5921","s":85,"a":12,"at":"ان بطش ربك لشديد","dt":"[12] ان انتقام ربك من اعدائه وعذابه لهم لعظيم شديد"},{"id":"5922","s":85,"a":13,"at":"انه هو يبدئ ويعيد","dt":"[13] انه هو يبدئ الخلق ثم يعيده"},{"id":"5923","s":85,"a":14,"at":"وهو الغفور الودود","dt":"[14] وهو الغفور لمن تاب، كثير الموده والمحبه لاوليائه"},{"id":"5924","s":85,"a":15,"at":"ذو العرش المجيد","dt":"[15] صاحب العرش، المجيد الذي بلغ المنتهى في الفضل والكرم"},{"id":"5925","s":85,"a":16,"at":"فعال لما يريد","dt":"[16] فعال لما يريد، لا يمتنع عليه شيء يريده."},{"id":"5926","s":85,"a":17,"at":"هل اتاك حديث الجنود","dt":"[17] هل بلغك -ايها الرسول- خبر الجموع الكافره المكذبه لانبيائها"},{"id":"5927","s":85,"a":18,"at":"فرعون وثمود","dt":"[18] فرعون وثمود، وما حل بهم من العذاب والنكال، لم يعتبر القوم بذلك"},{"id":"5928","s":85,"a":19,"at":"بل الذين كفروا في تكذيب","dt":"[19] بل الذين كفروا في تكذيب متواصل، كداب من قبلهم"},{"id":"5929","s":85,"a":20,"at":"والله من ورائهم محيط","dt":"[20] والله قد احاط بهم علما وقدره، لا يخفى عليه منهم ومن اعمالهم شيء"},{"id":"5930","s":85,"a":21,"at":"بل هو قران مجيد","dt":"[21] وليس القران كما زعم المكذبون والمشركون انه شعر وسحر، فكذبوا به، بل هو قران عظيم كريم"},{"id":"5931","s":85,"a":22,"at":"في لوح محفوظ","dt":"[22] في لوح محفوظ، لا يناله تبديل ولا تحريف."},{"id":"5932","s":86,"a":1,"at":"والسماء والطارق","dt":"[1] اقسم الله سبحانه بالسماء والنجم الذي يظهر ليلا"},{"id":"5933","s":86,"a":2,"at":"وما ادراك ما الطارق","dt":"[2] وما ادراك ما عظم هذا النجم؟"},{"id":"5934","s":86,"a":3,"at":"النجم الثاقب","dt":"[3] هو النجم المضيء المتوهج"},{"id":"5935","s":86,"a":4,"at":"ان كل نفس لما عليها حافظ","dt":"[4] ما كل نفس الا اوكل بها ملك رقيب يحفظ عليها اعمالها؛ لتحاسب عليها يوم القيامه."},{"id":"5936","s":86,"a":5,"at":"فلينظر الانسان مم خلق","dt":"[5] فلينظر الانسان المنكر للبعث مم خلق؟ ليعلم ان اعاده خلق الانسان ليست اصعب من خلقه اولا"},{"id":"5937","s":86,"a":6,"at":"خلق من ماء دافق","dt":"[6] خلق من مني منصب بسرعه في الرحم"},{"id":"5938","s":86,"a":7,"at":"يخرج من بين الصلب والترائب","dt":"[7] يخرج من بين صلب الرجل وصدر المراه"},{"id":"5939","s":86,"a":8,"at":"انه على رجعه لقادر","dt":"[8] ان الذي خلق الانسان من هذا الماء لقادر على رجعه الى الحياه بعد الموت."},{"id":"5940","s":86,"a":9,"at":"يوم تبلى السرائر","dt":"[9] يوم تختبر السرائر فيما اخفته، ويميز الصالح منها من الفاسد"},{"id":"5941","s":86,"a":10,"at":"فما له من قوه ولا ناصر","dt":"[10] فما للانسان من قوه يدفع بها عن نفسه، وما له من ناصر يدفع عنه عذاب الله."},{"id":"5942","s":86,"a":11,"at":"والسماء ذات الرجع","dt":"[11] والسماء ذات المطر المتكرر"},{"id":"5943","s":86,"a":12,"at":"والارض ذات الصدع","dt":"[12] والارض ذات التشقق بما يتخللها من نبات"},{"id":"5944","s":86,"a":13,"at":"انه لقول فصل","dt":"[13] ان القران لقول فصل بين الحق والباطل"},{"id":"5945","s":86,"a":14,"at":"وما هو بالهزل","dt":"[14] وما هو بالهزل. ولا يجوز للمخلوق ان يقسم بغير الله، وان فعل فقد اشرك."},{"id":"5946","s":86,"a":15,"at":"انهم يكيدون كيدا","dt":"[15] ان المكذبين للرسول -صلى الله عليه وسلم-، وللقران يكيدون ويدبرون؛ ليدفعوا بكيدهم الحق ويؤيدوا الباطل."},{"id":"5947","s":86,"a":16,"at":"واكيد كيدا","dt":"[16] واكيد كيدا لاظهار الحق، ولو كره الكافرون"},{"id":"5948","s":86,"a":17,"at":"فمهل الكافرين امهلهم رويدا","dt":"[17] فلا تستعجل لهم –ايها الرسول- بطلب انزال العقاب بهم، بل امهلهم وانظرهم قليلا، ولا تستعجل لهم، وسترى ما يحل بهم من العذاب والنكال والعقوبه والهلاك"},{"id":"5949","s":87,"a":1,"at":"سبح اسم ربك الاعلى","dt":"[1] نزه اسم ربك الاعلى عن الشريك والنقائص تنزيها يليق بعظمته سبحانه"},{"id":"5950","s":87,"a":2,"at":"الذي خلق فسوى","dt":"[2] الذي خلق المخلوقات، فاتقن خلقها، واحسنه"},{"id":"5951","s":87,"a":3,"at":"والذي قدر فهدى","dt":"[3] والذي قدر جميع المقدرات، فهدى كل خلق الى ما يناسبه"},{"id":"5952","s":87,"a":4,"at":"والذي اخرج المرعى","dt":"[4] والذي انبت الكلا الاخضر"},{"id":"5953","s":87,"a":5,"at":"فجعله غثاء احوى","dt":"[5] فجعله بعد ذلك هشيما جافا متغيرا الى السواد بعد اخضراره."},{"id":"5954","s":87,"a":6,"at":"سنقرئك فلا تنسى","dt":"[6] سنقرئك -ايها الرسول- هذا القران قراءه لا تنساها"},{"id":"5955","s":87,"a":7,"at":"الا ما شاء الله انه يعلم الجهر وما يخفى","dt":"[7] الا ما شاء الله مما اقتضت حكمته ان ينسيه لمصلحه يعلمها. انه -سبحانه- يعلم الجهر من القول والعمل، وما يخفى منهما."},{"id":"5956","s":87,"a":8,"at":"ونيسرك لليسرى","dt":"[8] ونيسرك لليسرى في جميع امورك، ومن ذلك تسهيل تلقي اعباء الرساله، وجعل دينك يسرا لا عسر فيه."},{"id":"5957","s":87,"a":9,"at":"فذكر ان نفعت الذكرى","dt":"[9] فعظ قومك -ايها الرسول- حسبما يسرناه لك بما يوحى اليك، واهدهم الى ما فيه خيرهم. وخص بالتذكير من يرجى منه التذكر، ولا تتعب نفسك في تذكير من لا يورثه التذكير الا عتوا ونفورا."},{"id":"5958","s":87,"a":10,"at":"سيذكر من يخشى","dt":"[10] سيتعظ الذي يخاف ربه."},{"id":"5959","s":87,"a":11,"at":"ويتجنبها الاشقى","dt":"[11] ويبتعد عن الذكرى الاشقى الذي لا يخشى ربه"},{"id":"5960","s":87,"a":12,"at":"الذي يصلى النار الكبرى","dt":"[12] الذي سيدخل نار جهنم العظمى يقاسي حرها"},{"id":"5961","s":87,"a":13,"at":"ثم لا يموت فيها ولا يحيا","dt":"[13] ثم لا يموت فيها فيستريح، ولا يحيا حياه تنفعه"},{"id":"5962","s":87,"a":14,"at":"قد افلح من تزكى","dt":"[14] قد فاز من طهر نفسه من الاخلاق السيئه"},{"id":"5963","s":87,"a":15,"at":"وذكر اسم ربه فصلى","dt":"[15] وذكر الله، فوحده ودعاه وعمل بما يرضيه، واقام الصلاه في اوقاتها؛ ابتغاء رضوان الله وامتثالا لشرعه."},{"id":"5964","s":87,"a":16,"at":"بل تؤثرون الحياه الدنيا","dt":"[16] انكم -ايها الناس- تفضلون زينه الحياه الدنيا على نعيم الاخره."},{"id":"5965","s":87,"a":17,"at":"والاخره خير وابقى","dt":"[17] والدار الاخره وما فيها من النعيم المقيم، خير من الدنيا وابقى."},{"id":"5966","s":87,"a":18,"at":"ان هذا لفي الصحف الاولى","dt":"[18] ان ما اخبرتم به في هذه السوره هو مما ثبت معناه في الصحف التي انزلت قبل القران"},{"id":"5967","s":87,"a":19,"at":"صحف ابراهيم وموسى","dt":"[19] وهي صحف ابراهيم وموسى عليهما السلام."},{"id":"5968","s":88,"a":1,"at":"هل اتاك حديث الغاشيه","dt":"[1] هل اتاك -ايها الرسول- خبر القيامه التي تغشى الناس باهوالها؟"},{"id":"5969","s":88,"a":2,"at":"وجوه يومئذ خاشعه","dt":"[2] وجوه الكفار يومئذ ذليله بالعذاب"},{"id":"5970","s":88,"a":3,"at":"عامله ناصبه","dt":"[3] مجهده بالعمل متعبه"},{"id":"5971","s":88,"a":4,"at":"تصلى نارا حاميه","dt":"[4] تصيبها نار شديده التوهج"},{"id":"5972","s":88,"a":5,"at":"تسقى من عين انيه","dt":"[5] تسقى من عين بلغت منتهى الحراره"},{"id":"5973","s":88,"a":6,"at":"ليس لهم طعام الا من ضريع","dt":"[6] ليس لاصحاب النار طعام الا من نبت ذي شوك لاصق بالارض، وهو من شر الطعام واخبثه"},{"id":"5974","s":88,"a":7,"at":"لا يسمن ولا يغني من جوع","dt":"[7] لا يسمن بدن صاحبه من الهزال، ولا يسد جوعه ورمقه."},{"id":"5975","s":88,"a":8,"at":"وجوه يومئذ ناعمه","dt":"[8] وجوه المؤمنين يوم القيامه ذات نعمه."},{"id":"5976","s":88,"a":9,"at":"لسعيها راضيه","dt":"[9] لسعيها في الدنيا بالطاعات راضيه في الاخره"},{"id":"5977","s":88,"a":10,"at":"في جنه عاليه","dt":"[10] في جنه رفيعه المكان والمكانه"},{"id":"5978","s":88,"a":11,"at":"لا تسمع فيها لاغيه","dt":"[11] لا تسمع فيها كلمه لغو واحده"},{"id":"5979","s":88,"a":12,"at":"فيها عين جاريه","dt":"[12] فيها عين تتدفق مياهها"},{"id":"5980","s":88,"a":13,"at":"فيها سرر مرفوعه","dt":"[13] فيها سرر عاليه"},{"id":"5981","s":88,"a":14,"at":"واكواب موضوعه","dt":"[14] واكواب معده للشاربين"},{"id":"5982","s":88,"a":15,"at":"ونمارق مصفوفه","dt":"[15] ووسائد مصفوفه، الواحده جنب الاخرى"},{"id":"5983","s":88,"a":16,"at":"وزرابي مبثوثه","dt":"[16] وبسط كثيره مفروشه."},{"id":"5984","s":88,"a":17,"at":"افلا ينظرون الى الابل كيف خلقت","dt":"[17] افلا ينظر الكافرون المكذبون الى الابل: كيف خلقت هذا الخلق العجيب؟"},{"id":"5985","s":88,"a":18,"at":"والى السماء كيف رفعت","dt":"[18] والى السماء كيف رفعت هذا الرفع البديع؟"},{"id":"5986","s":88,"a":19,"at":"والى الجبال كيف نصبت","dt":"[19] والى الجبال كيف نصبت، فحصل بها الثبات للارض والاستقرار؟"},{"id":"5987","s":88,"a":20,"at":"والى الارض كيف سطحت","dt":"[20] والى الارض كيف بسطت ومهدت؟"},{"id":"5988","s":88,"a":21,"at":"فذكر انما انت مذكر","dt":"[21] فعظ -ايها الرسول- المعرضين بما ارسلت به اليهم، ولا تحزن على اعراضهم، انما انت واعظ لهم"},{"id":"5989","s":88,"a":22,"at":"لست عليهم بمصيطر","dt":"[22] ليس عليك اكراههم على الايمان."},{"id":"5990","s":88,"a":23,"at":"الا من تولى وكفر","dt":"[23] لكن الذي اعرض عن التذكير والموعظه واصر على كفره"},{"id":"5991","s":88,"a":24,"at":"فيعذبه الله العذاب الاكبر","dt":"[24] فيعذبه الله العذاب الشديد في النار."},{"id":"5992","s":88,"a":25,"at":"ان الينا ايابهم","dt":"[25] ان الينا مرجعهم بعد الموت"},{"id":"5993","s":88,"a":26,"at":"ثم ان علينا حسابهم","dt":"[26] ثم ان علينا جزاءهم على ما عملوا."},{"id":"5994","s":89,"a":1,"at":"والفجر","dt":"[1] اقسم الله سبحانه بوقت الفجر"},{"id":"5995","s":89,"a":2,"at":"وليال عشر","dt":"[2] والليالي العشر الاول من ذي الحجه وما شرفت به"},{"id":"5996","s":89,"a":3,"at":"والشفع والوتر","dt":"[3] وبكل شفع وفرد"},{"id":"5997","s":89,"a":4,"at":"والليل اذا يسر","dt":"[4] وبالليل اذا يسري بظلامه"},{"id":"5998","s":89,"a":5,"at":"هل في ذلك قسم لذي حجر","dt":"[5] اليس في الاقسام المذكوره مقنع لذي عقل؟"},{"id":"5999","s":89,"a":6,"at":"الم تر كيف فعل ربك بعاد","dt":"[6] الم تر -ايها الرسول- كيف فعل ربك بقوم عاد"},{"id":"6000","s":89,"a":7,"at":"ارم ذات العماد","dt":"[7] قبيله ارم، ذات القوه والابنيه المرفوعه على الاعمده"},{"id":"6001","s":89,"a":8,"at":"التي لم يخلق مثلها في البلاد","dt":"[8] التي لم يخلق مثلها في البلاد في عظم الاجساد وقوه الباس؟"},{"id":"6002","s":89,"a":9,"at":"وثمود الذين جابوا الصخر بالواد","dt":"[9] وكيف فعل بثمود قوم صالح الذين قطعوا الصخر بالوادي واتخذوا منه بيوتا؟"},{"id":"6003","s":89,"a":10,"at":"وفرعون ذي الاوتاد","dt":"[10] وكيف فعل بفرعون ملك «مصر»، صاحب الجنود الذين ثبتوا ملكه، وقووا له امره؟"},{"id":"6004","s":89,"a":11,"at":"الذين طغوا في البلاد","dt":"[11] هؤلاء الذين استبدوا، وظلموا في بلاد الله"},{"id":"6005","s":89,"a":12,"at":"فاكثروا فيها الفساد","dt":"[12] فاكثروا فيها بظلمهم الفساد"},{"id":"6006","s":89,"a":13,"at":"فصب عليهم ربك سوط عذاب","dt":"[13] فصب عليهم ربك عذابا شديدا"},{"id":"6007","s":89,"a":14,"at":"ان ربك لبالمرصاد","dt":"[14] ان ربك -ايها الرسول- لبالمرصاد لمن يعصيه، يمهله قليلا، ثم ياخذه اخذ عزيز مقتدر."},{"id":"6008","s":89,"a":15,"at":"فاما الانسان اذا ما ابتلاه ربه فاكرمه ونعمه فيقول ربي اكرمن","dt":"[15] فاما الانسان اذا ما اختبره ربه بالنعمه، وبسط له رزقه، وجعله في اطيب عيش، فيظن ان ذلك لكرامته عند ربه، فيقول: ربي اكرمن."},{"id":"6009","s":89,"a":16,"at":"واما اذا ما ابتلاه فقدر عليه رزقه فيقول ربي اهانن","dt":"[16] واما اذا ما اختبره، فضيق عليه رزقه، فيظن ان ذلك لهوانه على الله، فيقول: ربي اهانن."},{"id":"6010","s":89,"a":17,"at":"كلا بل لا تكرمون اليتيم","dt":"[17] ليس الامر كما يظن هذا الانسان، بل الاكرام بطاعه الله، والاهانه بمعصيته، وانتم لا تكرمون اليتيم الذي مات ابوه وهو صغير، ولا تحسنون معاملته"},{"id":"6011","s":89,"a":18,"at":"ولا تحاضون على طعام المسكين","dt":"[18] ولا يحث بعضكم بعضا على اطعام المحتاج الذي لا يملك ما يكفيه ويسد حاجته"},{"id":"6012","s":89,"a":19,"at":"وتاكلون التراث اكلا لما","dt":"[19] ، وتاكلون حقوق الاخرين في الميراث اكلا شديدا"},{"id":"6013","s":89,"a":20,"at":"وتحبون المال حبا جما","dt":"[20] وتحبون المال حبا مفرطا."},{"id":"6014","s":89,"a":21,"at":"كلا اذا دكت الارض دكا دكا","dt":"[21] ما هكذا ينبغي ان يكون حالكم. فاذا زلزلت الارض وكسر بعضها بعضا"},{"id":"6015","s":89,"a":22,"at":"وجاء ربك والملك صفا صفا","dt":"[22] وجاء ربك لفصل القضاء بين خلقه، والملائكه صفوفا صفوفا."},{"id":"6016","s":89,"a":23,"at":"وجيء يومئذ بجهنم يومئذ يتذكر الانسان وانى له الذكرى","dt":"[23] وجيء في ذلك اليوم العظيم بجهنم، يومئذ يتعظ الكافر ويتوب، وكيف ينفعه الاتعاظ والتوبه، وقد فرط فيهما في الدنيا، وفات اوانهما؟"},{"id":"6017","s":89,"a":24,"at":"يقول ياليتني قدمت لحياتي","dt":"[24] يقول: يا ليتني قدمت في الدنيا من الاعمال ما ينفعني لحياتي في الاخره."},{"id":"6018","s":89,"a":25,"at":"فيومئذ لا يعذب عذابه احد","dt":"[25] ففي ذلك اليوم العصيب لا يستطيع احد ولا يقدر ان يعذب مثل تعذيب الله من عصاه"},{"id":"6019","s":89,"a":26,"at":"ولا يوثق وثاقه احد","dt":"[26] ولا يستطيع احد ان يوثق مثل وثاق الله، ولا يبلغ احد مبلغه في ذلك."},{"id":"6020","s":89,"a":27,"at":"ياايتها النفس المطمئنه","dt":"[27] يا ايتها النفس المطمئنه الى ذكر الله والايمان به، وبما اعده من النعيم للمؤمنين"},{"id":"6021","s":89,"a":28,"at":"ارجعي الى ربك راضيه مرضيه","dt":"[28] ارجعي الى ربك راضيه باكرام الله لك، والله سبحانه قد رضي عنك"},{"id":"6022","s":89,"a":29,"at":"فادخلي في عبادي","dt":"[29] فادخلي في عداد عباد الله الصالحين"},{"id":"6023","s":89,"a":30,"at":"وادخلي جنتي","dt":"[30] وادخلي معهم جنتي."},{"id":"6024","s":90,"a":1,"at":"لا اقسم بهذا البلد","dt":"[1] اقسم الله بهذا البلد الحرام، وهو «مكه»"},{"id":"6025","s":90,"a":2,"at":"وانت حل بهذا البلد","dt":"[2] وانت -ايها النبي- حلال في هذا «البلد الحرام» تصنع فيه ما شئت، ولم يحل له الا ساعه من نهار. وفي الايه بشاره للنبي -صلى الله عليه وسلم- بفتح «مكه» على يديه، وحلها له في القتال"},{"id":"6026","s":90,"a":3,"at":"ووالد وما ولد","dt":"[3] واقسم بوالد البشريه -وهو ادم عليه السلام- وما تناسل منه من ولد"},{"id":"6027","s":90,"a":4,"at":"لقد خلقنا الانسان في كبد","dt":"[4] لقد خلقنا الانسان في شده وعناء من مكابده الدنيا."},{"id":"6028","s":90,"a":5,"at":"ايحسب ان لن يقدر عليه احد","dt":"[5] ايظن بما جمعه من مال ان الله لن يقدر عليه؟"},{"id":"6029","s":90,"a":6,"at":"يقول اهلكت مالا لبدا","dt":"[6] يقول -متباهيا-: انفقت مالا كثيرا"},{"id":"6030","s":90,"a":7,"at":"ايحسب ان لم يره احد","dt":"[7] ايظن في فعله هذا ان الله عز وجل لا يراه، ولا يحاسبه على الصغير والكبير؟"},{"id":"6031","s":90,"a":8,"at":"الم نجعل له عينين","dt":"[8] الم نجعل له عينين يبصر بهما"},{"id":"6032","s":90,"a":9,"at":"ولسانا وشفتين","dt":"[9] ولسانا وشفتين ينطق بهما"},{"id":"6033","s":90,"a":10,"at":"وهديناه النجدين","dt":"[10] وبينا له سبيلي الخير والشر؟"},{"id":"6034","s":90,"a":11,"at":"فلا اقتحم العقبه","dt":"[11] فهلا تجاوز مشقه الاخره بانفاق ماله، فيامن."},{"id":"6035","s":90,"a":12,"at":"وما ادراك ما العقبه","dt":"[12] واي شيء اعلمك: ما مشقه الاخره، وما يعين على تجاوزها؟"},{"id":"6036","s":90,"a":13,"at":"فك رقبه","dt":"[13] انه عتق رقبه مؤمنه من اسر الرق."},{"id":"6037","s":90,"a":14,"at":"او اطعام في يوم ذي مسغبه","dt":"[14] او اطعام في يوم ذي مجاعه شديده"},{"id":"6038","s":90,"a":15,"at":"يتيما ذا مقربه","dt":"[15] يتيما -مات ابوه وهو صغير- من ذوي القرابه يجتمع فيه فضل الصدقه وصله الرحم"},{"id":"6039","s":90,"a":16,"at":"او مسكينا ذا متربه","dt":"[16] او فقيرا معدما لا شيء عنده."},{"id":"6040","s":90,"a":17,"at":"ثم كان من الذين امنوا وتواصوا بالصبر وتواصوا بالمرحمه","dt":"[17] ثم كان مع فعل ما ذكر من اعمال الخير من الذين اخلصوا الايمان لله، واوصى بعضهم بعضا بالصبر على طاعه الله وعن معاصيه، وتواصوا بالرحمه بالخلق."},{"id":"6041","s":90,"a":18,"at":"اولئك اصحاب الميمنه","dt":"[18] الذين فعلوا هذه الافعال، هم اصحاب اليمين، الذين يؤخذ بهم يوم القيامه ذات اليمين الى الجنه."},{"id":"6042","s":90,"a":19,"at":"والذين كفروا باياتنا هم اصحاب المشامه","dt":"[19] والذين كفروا بالقران هم الذين يؤخذ بهم يوم القيامه ذات الشمال الى النار."},{"id":"6043","s":90,"a":20,"at":"عليهم نار مؤصده","dt":"[20] جزاؤهم جهنم مطبقه مغلقه عليهم."},{"id":"6044","s":91,"a":1,"at":"والشمس وضحاها","dt":"[1] اقسم الله بالشمس ونهارها واشراقها ضحى."},{"id":"6045","s":91,"a":2,"at":"والقمر اذا تلاها","dt":"[2] وبالقمر اذا تبعها في طلوعه ومغيبه"},{"id":"6046","s":91,"a":3,"at":"والنهار اذا جلاها","dt":"[3] وبالنهار اذا جلى الظلمه وكشفها"},{"id":"6047","s":91,"a":4,"at":"والليل اذا يغشاها","dt":"[4] وبالليل عندما يغطي الارض فيكون ما عليها مظلما"},{"id":"6048","s":91,"a":5,"at":"والسماء وما بناها","dt":"[5] وبالسماء وبنائها المحكم"},{"id":"6049","s":91,"a":6,"at":"والارض وما طحاها","dt":"[6] وبالارض وبسطها"},{"id":"6050","s":91,"a":7,"at":"ونفس وما سواها","dt":"[7] وبكل نفس واكمال الله خلقها لاداء مهمتها"},{"id":"6051","s":91,"a":8,"at":"فالهمها فجورها وتقواها","dt":"[8] فبين لها طريق الشر وطريق الخير"},{"id":"6052","s":91,"a":9,"at":"قد افلح من زكاها","dt":"[9] قد فاز من طهرها ونماها بالخير"},{"id":"6053","s":91,"a":10,"at":"وقد خاب من دساها","dt":"[10] وقد خسر من اخفى نفسه في المعاصي."},{"id":"6054","s":91,"a":11,"at":"كذبت ثمود بطغواها","dt":"[11] كذبت ثمود نبيها ببلوغها الغايه في العصيان"},{"id":"6055","s":91,"a":12,"at":"اذ انبعث اشقاها","dt":"[12] اذ نهض اكثر القبيله شقاوه لعقر الناقه"},{"id":"6056","s":91,"a":13,"at":"فقال لهم رسول الله ناقه الله وسقياها","dt":"[13] فقال لهم رسول الله صالح عليه السلام: احذروا ان تمسوا الناقه بسوء؛ فانها ايه ارسلها الله اليكم، تدل على صدق نبيكم، واحذروا ان تعتدوا على سقيها، فان لها شرب يوم ولكم شرب يوم معلوم"},{"id":"6057","s":91,"a":14,"at":"فكذبوه فعقروها فدمدم عليهم ربهم بذنبهم فسواها","dt":"[14] فشق عليهم ذلك، فكذبوه فيما توعدهم به فنحروها، فاطبق عليهم ربهم العقوبه بجرمهم، فجعلها عليهم على السواء فلم يفلت منهم احد"},{"id":"6058","s":91,"a":15,"at":"ولا يخاف عقباها","dt":"[15] ولا يخاف -جلت قدرته- تبعه ما انزله بهم من شديد العقاب."},{"id":"6059","s":92,"a":1,"at":"والليل اذا يغشى","dt":"[1] اقسم الله سبحانه بالليل عندما يغطي بظلامه الارض وما عليها"},{"id":"6060","s":92,"a":2,"at":"والنهار اذا تجلى","dt":"[2] وبالنهار اذا انكشف عن ظلام الليل بضيائه"},{"id":"6061","s":92,"a":3,"at":"وما خلق الذكر والانثى","dt":"[3] وبخلق الزوجين: الذكر والانثى"},{"id":"6062","s":92,"a":4,"at":"ان سعيكم لشتى","dt":"[4] ان عملكم لمختلف بين عامل للدنيا وعامل للاخره."},{"id":"6063","s":92,"a":5,"at":"فاما من اعطى واتقى","dt":"[5] فاما من بذل من ماله واتقى الله في ذلك"},{"id":"6064","s":92,"a":6,"at":"وصدق بالحسنى","dt":"[6] وصدق ب«لا اله الا الله» وما دلت عليه، وما ترتب عليها من الجزاء"},{"id":"6065","s":92,"a":7,"at":"فسنيسره لليسرى","dt":"[7] فسنرشده ونوفقه الى اسباب الخير والصلاح، ونيسر له اموره."},{"id":"6066","s":92,"a":8,"at":"واما من بخل واستغنى","dt":"[8] واما من بخل بماله واستغنى عن جزاء ربه"},{"id":"6067","s":92,"a":9,"at":"وكذب بالحسنى","dt":"[9] وكذب ب«لا اله الا الله» وما دلت عليه، وما ترتب عليها من الجزاء."},{"id":"6068","s":92,"a":10,"at":"فسنيسره للعسرى","dt":"[10] فسنيسر له اسباب الشقاء"},{"id":"6069","s":92,"a":11,"at":"وما يغني عنه ماله اذا تردى","dt":"[11] ولا ينفعه ماله الذي بخل به اذا وقع في النار."},{"id":"6070","s":92,"a":12,"at":"ان علينا للهدى","dt":"[12] ان علينا بفضلنا وحكمتنا ان نبين طريق الهدى الموصل الى الله وجنته من طريق الضلال"},{"id":"6071","s":92,"a":13,"at":"وان لنا للاخره والاولى","dt":"[13] وان لنا ملك الحياه الاخره والحياه الدنيا."},{"id":"6072","s":92,"a":14,"at":"فانذرتكم نارا تلظى","dt":"[14] فحذرتكم -ايها الناس- وخوفتكم نارا تتوهج، وهي نار جهنم."},{"id":"6073","s":92,"a":15,"at":"لا يصلاها الا الاشقى","dt":"[15] لا يدخلها الا من كان شديد الشقاء"},{"id":"6074","s":92,"a":16,"at":"الذي كذب وتولى","dt":"[16] الذي كذب نبي الله محمدا -صلى الله عليه وسلم-، واعرض عن الايمان بالله ورسوله، وطاعتهما."},{"id":"6075","s":92,"a":17,"at":"وسيجنبها الاتقى","dt":"[17] وسيزحزح عنها شديد التقوى"},{"id":"6076","s":92,"a":18,"at":"الذي يؤتي ماله يتزكى","dt":"[18] الذي يبذل ماله ابتغاء المزيد من الخير"},{"id":"6077","s":92,"a":19,"at":"وما لاحد عنده من نعمه تجزى","dt":"[19] وليس انفاقه ذاك مكافاه لمن اسدى اليه معروفا"},{"id":"6078","s":92,"a":20,"at":"الا ابتغاء وجه ربه الاعلى","dt":"[20] لكنه يبتغي بذلك وجه ربه الاعلى ورضاه"},{"id":"6079","s":92,"a":21,"at":"ولسوف يرضى","dt":"[21] ولسوف يعطيه الله في الجنه ما يرضى به."},{"id":"6080","s":93,"a":1,"at":"والضحى","dt":"[1] اقسم الله بوقت الضحى، والمراد به النهار كله"},{"id":"6081","s":93,"a":2,"at":"والليل اذا سجى","dt":"[2] وبالليل اذا سكن بالخلق واشتد ظلامه، ويقسم الله بما يشاء من مخلوقاته، اما المخلوق فلا يجوز له ان يقسم بغير خالقه، فان القسم بغير الله شرك."},{"id":"6082","s":93,"a":3,"at":"ما ودعك ربك وما قلى","dt":"[3] ما تركك -ايها النبي- ربك، وما ابغضك بابطاء الوحي عنك."},{"id":"6083","s":93,"a":4,"at":"وللاخره خير لك من الاولى","dt":"[4] وللدار الاخره خير لك من دار الدنيا"},{"id":"6084","s":93,"a":5,"at":"ولسوف يعطيك ربك فترضى","dt":"[5] ولسوف يعطيك ربك -ايها النبي- من انواع الانعام في الاخره، فترضى بذلك."},{"id":"6085","s":93,"a":6,"at":"الم يجدك يتيما فاوى","dt":"[6] الم يجدك من قبل يتيما مات ابوك وانت حمل في بطن امك، فاواك ورعاك؟"},{"id":"6086","s":93,"a":7,"at":"ووجدك ضالا فهدى","dt":"[7] ووجدك لا تدري ما الكتاب ولا الايمان، فعلمك ما لم تكن تعلم، ووفقك لاحسن الاعمال؟"},{"id":"6087","s":93,"a":8,"at":"ووجدك عائلا فاغنى","dt":"[8] ووجدك فقيرا، فساق اليك رزقك، واغنى نفسك بالقناعه والصبر؟"},{"id":"6088","s":93,"a":9,"at":"فاما اليتيم فلا تقهر","dt":"[9] فاما اليتيم فلا تسئ معاملته"},{"id":"6089","s":93,"a":10,"at":"واما السائل فلا تنهر","dt":"[10] واما السائل فلا تزجره، بل اطعمه، واقض حاجته"},{"id":"6090","s":93,"a":11,"at":"واما بنعمه ربك فحدث","dt":"[11] واما بنعمه ربك التي اسبغها عليك فتحدث بها."},{"id":"6091","s":94,"a":1,"at":"الم نشرح لك صدرك","dt":"[1] الم نوسع -ايها النبي- لك صدرك لشرائع الدين، والدعوه الى الله، والاتصاف بمكارم الاخلاق"},{"id":"6092","s":94,"a":2,"at":"ووضعنا عنك وزرك","dt":"[2] وحططنا عنك بذلك حملك."},{"id":"6093","s":94,"a":3,"at":"الذي انقض ظهرك","dt":"[3] الذي اثقل ظهرك"},{"id":"6094","s":94,"a":4,"at":"ورفعنا لك ذكرك","dt":"[4] وجعلناك -بما انعمنا عليك من المكارم- في منزله رفيعه عاليه؟"},{"id":"6095","s":94,"a":5,"at":"فان مع العسر يسرا","dt":"[5] فلا يثنك اذى اعدائك عن نشر الرساله؛ فان مع الضيق فرجا"},{"id":"6096","s":94,"a":6,"at":"ان مع العسر يسرا","dt":"[6] ان مع الضيق فرجا."},{"id":"6097","s":94,"a":7,"at":"فاذا فرغت فانصب","dt":"[7] فاذا فرغت من امور الدنيا واشغالها فجد في العباده"},{"id":"6098","s":94,"a":8,"at":"والى ربك فارغب","dt":"[8] والى ربك وحده فارغب فيما عنده."},{"id":"6099","s":95,"a":1,"at":"والتين والزيتون","dt":"[1] اقسم الله بالتين والزيتون، وهما من الثمار المشهوره"},{"id":"6100","s":95,"a":2,"at":"وطور سينين","dt":"[2] واقسم بجبل «طور سيناء» الذي كلم الله عليه موسى تكليما"},{"id":"6101","s":95,"a":3,"at":"وهذا البلد الامين","dt":"3] واقسم بهذا البلد الامين من كل خوف، وهي «مكه» مهبط الوحي"},{"id":"6102","s":95,"a":4,"at":"لقد خلقنا الانسان في احسن تقويم","dt":"[4] لقد خلقنا الانسان في احسن صوره"},{"id":"6103","s":95,"a":5,"at":"ثم رددناه اسفل سافلين","dt":"[5] ثم رددناه الى النار ان لم يطع الله، ويتبع الرسل"},{"id":"6104","s":95,"a":6,"at":"الا الذين امنوا وعملوا الصالحات فلهم اجر غير ممنون","dt":"[6] لكن الذين امنوا وعملوا الاعمال الصالحه لهم اجر عظيم غير مقطوع ولا منقوص."},{"id":"6105","s":95,"a":7,"at":"فما يكذبك بعد بالدين","dt":"[7] اي شيء يحملك -ايها الانسان- على ان تكذب بالبعث والجزاء مع وضوح الادله على قدره الله تعالى على ذلك؟"},{"id":"6106","s":95,"a":8,"at":"اليس الله باحكم الحاكمين","dt":"[8] اليس الله الذي جعل هذا اليوم للفصل بين الناس، باحكم الحاكمين في كل ما خلق؟ بلى. فهل يترك الخلق سدى لا يؤمرون ولا ينهون، ولا يثابون ولا يعاقبون؟ لا يصح ذلك ولا يكون."},{"id":"6107","s":96,"a":1,"at":"اقرا باسم ربك الذي خلق","dt":"[1] اقرا -ايها النبي- ما انزل اليك من القران مفتتحا باسم ربك المتفرد بالخلق"},{"id":"6108","s":96,"a":2,"at":"خلق الانسان من علق","dt":"[2] الذي خلق كل انسان من قطعه دم غليظ احمر"},{"id":"6109","s":96,"a":3,"at":"اقرا وربك الاكرم","dt":"[3] اقرا -ايها النبي- ما انزل اليك، وان ربك لكثير الاحسان واسع الجود"},{"id":"6110","s":96,"a":4,"at":"الذي علم بالقلم","dt":"[4] الذي علم خلقه الكتابه بالقلم"},{"id":"6111","s":96,"a":5,"at":"علم الانسان ما لم يعلم","dt":"[5] علم الانسان ما لم يكن يعلم، ونقله من ظلمه الجهل الى نور العلم."},{"id":"6112","s":96,"a":6,"at":"كلا ان الانسان ليطغى","dt":"[6] حقا ان الانسان ليتجاوز حدود الله"},{"id":"6113","s":96,"a":7,"at":"ان راه استغنى","dt":"[7] اذا ابطره الغنى"},{"id":"6114","s":96,"a":8,"at":"ان الى ربك الرجعى","dt":"[8] فليعلم كل طاغيه ان المصير الى الله، فيجازي كل انسان بعمله."},{"id":"6115","s":96,"a":9,"at":"ارايت الذي ينهى","dt":"[9] ارايت اعجب من طغيان هذا الرجل، وهو ابو جهل"},{"id":"6116","s":96,"a":10,"at":"عبدا اذا صلى","dt":"[10] الذي ينهى عبدا لنا اذا صلى لربه، وهو محمد -صلى الله عليه وسلم-؟"},{"id":"6117","s":96,"a":11,"at":"ارايت ان كان على الهدى","dt":"[11] ارايت ان كان المنهي عن الصلاه على الهدى فكيف ينهاه؟"},{"id":"6118","s":96,"a":12,"at":"او امر بالتقوى","dt":"[12] او ان كان امرا غيره بالتقوى اينهاه عن ذلك؟"},{"id":"6119","s":96,"a":13,"at":"ارايت ان كذب وتولى","dt":"[13] ارايت ان كذب هذا الناهي بما يدعى اليه، واعرض عنه"},{"id":"6120","s":96,"a":14,"at":"الم يعلم بان الله يرى","dt":"[14] الم يعلم بان الله يرى كل ما يفعل؟"},{"id":"6121","s":96,"a":15,"at":"كلا لئن لم ينته لنسفعا بالناصيه","dt":"[15] ليس الامر كما يزعم ابو جهل، لئن لم يرجع هذا عن شقاقه واذاه لناخذن بمقدم راسه اخذا عنيفا وليطرحن في النار"},{"id":"6122","s":96,"a":16,"at":"ناصيه كاذبه خاطئه","dt":"[16] ناصيته ناصيه كاذبه في مقالها، خاطئه في افعالها، فكان الكذب والخطا باديان منها"},{"id":"6123","s":96,"a":17,"at":"فليدع ناديه","dt":"[17] فليحضر هذا الطاغيه اهل ناديه الذين يستنصر بهم"},{"id":"6124","s":96,"a":18,"at":"سندع الزبانيه","dt":"[18] سندعو ملائكه العذاب"},{"id":"6125","s":96,"a":19,"at":"كلا لا تطعه واسجد واقترب","dt":"[19] ليس الامر على ما يظن ابو جهل، انه لن ينالك -ايها الرسول- بسوء، فلا تطعه فيما دعاك اليه من ترك الصلاه، واسجد لربك، واقترب منه بالتحبب اليه بطاعته."},{"id":"6126","s":97,"a":1,"at":"انا انزلناه في ليله القدر","dt":"[1] انا انزلنا القران في ليله الشرف والفضل، وهي احدى ليالي شهر رمضان."},{"id":"6127","s":97,"a":2,"at":"وما ادراك ما ليله القدر","dt":"[2] وما ادراك -ايها النبي- ما ليله القدر والشرف؟"},{"id":"6128","s":97,"a":3,"at":"ليله القدر خير من الف شهر","dt":"[3] ليله القدر ليله مباركه، العمل الصالح فيها خير من عمل الف شهر ليس فيها ليله قدر. وهو تفضل من الله تعالى على هذه الامه."},{"id":"6129","s":97,"a":4,"at":"تنزل الملائكه والروح فيها باذن ربهم من كل امر","dt":"[4] يكثر نزول الملائكه وجبريل عليه السلام فيها، باذن ربهم من كل امر قضاه في تلك السنه."},{"id":"6130","s":97,"a":5,"at":"سلام هي حتى مطلع الفجر","dt":"[5] هي امن كلها، لا شر فيها الى مطلع الفجر."},{"id":"6131","s":98,"a":1,"at":"لم يكن الذين كفروا من اهل الكتاب والمشركين منفكين حتى تاتيهم البينه","dt":"[1] لم يكن الذين كفروا من اليهود والنصارى والمشركين تاركين كفرهم حتى تاتيهم العلامه التي وعدوا بها في الكتب السابقه."},{"id":"6132","s":98,"a":2,"at":"رسول من الله يتلو صحفا مطهره","dt":"[2] وهي رسول الله محمد -صلى الله عليه وسلم-، يتلو قرانا في صحف مطهره."},{"id":"6133","s":98,"a":3,"at":"فيها كتب قيمه","dt":"[3] في تلك الصحف اخبار صادقه واوامر عادله، تهدي الى الحق والى صراط مستقيم."},{"id":"6134","s":98,"a":4,"at":"وما تفرق الذين اوتوا الكتاب الا من بعد ما جاءتهم البينه","dt":"[4] وما اختلف الذين اوتوا الكتاب من اليهود والنصارى في كون محمد -صلى الله عليه وسلم- رسولا حقا؛ لما يجدونه من نعته في كتابهم، الا من بعد ما تبينوا انه النبي الذي وعدوا به في التوراه والانجيل، فكانوا مجتمعين على صحه نبوته، فلما بعث تفرقوا: فمنهم من امن به، ومنهم من جحد نبوته بغيا وحسدا."},{"id":"6135","s":98,"a":5,"at":"وما امروا الا ليعبدوا الله مخلصين له الدين حنفاء ويقيموا الصلاه ويؤتوا الزكاه وذلك دين القيمه","dt":"[5] وما امروا في سائر الشرائع الا ليعبدوا الله وحده قاصدين بعبادتهم وجهه، مائلين عن الشرك الى الايمان، ويقيموا الصلاه، ويؤدوا الزكاه، وذلك هو دين الاستقامه، وهو الاسلام."},{"id":"6136","s":98,"a":6,"at":"ان الذين كفروا من اهل الكتاب والمشركين في نار جهنم خالدين فيها اولئك هم شر البريه","dt":"[6] ان الذين كفروا من اليهود والنصارى والمشركين عقابهم نار جهنم خالدين فيها، اولئك هم اشد الخليقه شرا."},{"id":"6137","s":98,"a":7,"at":"ان الذين امنوا وعملوا الصالحات اولئك هم خير البريه","dt":"[7] ان الذين صدقوا الله واتبعوا رسوله وعملوا الصالحات، اولئك هم خير الخلق."},{"id":"6138","s":98,"a":8,"at":"جزاؤهم عند ربهم جنات عدن تجري من تحتها الانهار خالدين فيها ابدا رضي الله عنهم ورضوا عنه ذلك لمن خشي ربه","dt":"[8] جزاؤهم عند ربهم يوم القيامه جنات اقامه واستقرار في منتهى الحسن، تجري من تحت قصورها واشجارها الانهار، خالدين فيها ابدا، رضي الله عنهم فقبل اعمالهم الصالحه، ورضوا عنه بما اعد لهم من انواع الكرامات، ذلك الجزاء الحسن لمن خاف الله واجتنب معاصيه."},{"id":"6139","s":99,"a":1,"at":"اذا زلزلت الارض زلزالها","dt":"[1] اذا رجت الارض رجا شديدا"},{"id":"6140","s":99,"a":2,"at":"واخرجت الارض اثقالها","dt":"[2] واخرجت ما في بطنها من موتى وكنوز"},{"id":"6141","s":99,"a":3,"at":"وقال الانسان ما لها","dt":"[3] وتساءل الانسان فزعا: ما الذي حدث لها؟"},{"id":"6142","s":99,"a":4,"at":"يومئذ تحدث اخبارها","dt":"[4] يوم القيامه تخبر الارض بما عمل عليها من خير او شر"},{"id":"6143","s":99,"a":5,"at":"بان ربك اوحى لها","dt":"[5] وبان الله سبحانه وتعالى امرها بان تخبر بما عمل عليها."},{"id":"6144","s":99,"a":6,"at":"يومئذ يصدر الناس اشتاتا ليروا اعمالهم","dt":"[6] يومئذ يرجع الناس عن موقف الحساب اصنافا متفرقين؛ ليريهم الله ما عملوا من الحسنات والسيئات، ويجازيهم عليها."},{"id":"6145","s":99,"a":7,"at":"فمن يعمل مثقال ذره خيرا يره","dt":"[7] فمن يعمل وزن نمله صغيره خيرا، ير ثوابه في الاخره"},{"id":"6146","s":99,"a":8,"at":"ومن يعمل مثقال ذره شرا يره","dt":"[8] ومن يعمل وزن نمله صغيره شرا، ير عقابه في الاخره."},{"id":"6147","s":100,"a":1,"at":"والعاديات ضبحا","dt":"[1] اقسم الله تعالى بالخيل الجاريات في سبيله نحو العدو، حين يظهر صوت انفاسها من سرعه عدوها. ولا يجوز للمخلوق ان يقسم الا بالله؛ فان القسم بغير الله شرك."},{"id":"6148","s":100,"a":2,"at":"فالموريات قدحا","dt":"[2] فالخيل اللاتي تنقدح النار من صلابه حوافرها؛ لشده عدوها."},{"id":"6149","s":100,"a":3,"at":"فالمغيرات صبحا","dt":"[3] فالخيل التي تغير بركبانها على الاعداء عند الصبح."},{"id":"6150","s":100,"a":4,"at":"فاثرن به نقعا","dt":"[4] فهيجن بهذا العدو غبارا."},{"id":"6151","s":100,"a":5,"at":"فوسطن به جمعا","dt":"[5] فتوسطن بركبانهن جموع الاعداء."},{"id":"6152","s":100,"a":6,"at":"ان الانسان لربه لكنود","dt":"[6] ان الانسان لنعم ربه لجحود"},{"id":"6153","s":100,"a":7,"at":"وانه على ذلك لشهيد","dt":"[7] وانه بجحوده ذلك لمقر"},{"id":"6154","s":100,"a":8,"at":"وانه لحب الخير لشديد","dt":"[8] وانه لحب المال لشديد."},{"id":"6155","s":100,"a":9,"at":"افلا يعلم اذا بعثر ما في القبور","dt":"[9] افلا يعلم الانسان ما ينتظره اذا اخرج الله الاموات من القبور للحساب والجزاء؟"},{"id":"6156","s":100,"a":10,"at":"وحصل ما في الصدور","dt":"[10] واستخرج ما استتر في الصدور من خير او شر."},{"id":"6157","s":100,"a":11,"at":"ان ربهم بهم يومئذ لخبير","dt":"[11] ان ربهم بهم وباعمالهم يومئذ لخبير، لا يخفى عليه شيء من ذلك."},{"id":"6158","s":101,"a":1,"at":"القارعه","dt":"[1] الساعه التي تقرع قلوب الناس باهوالها."},{"id":"6159","s":101,"a":2,"at":"ما القارعه","dt":"[2] اي شيء هذه القارعه؟"},{"id":"6160","s":101,"a":3,"at":"وما ادراك ما القارعه","dt":"[3] واي شيء اعلمك بها؟"},{"id":"6161","s":101,"a":4,"at":"يوم يكون الناس كالفراش المبثوث","dt":"[4] في ذلك اليوم يكون الناس في كثرتهم وتفرقهم وحركتهم كالفراش المنتشر، وهو الذي يتساقط في النار."},{"id":"6162","s":101,"a":5,"at":"وتكون الجبال كالعهن المنفوش","dt":"[5] وتكون الجبال كالصوف المتعدد الالوان الذي ينفش باليد، فيصير هباء ويزول."},{"id":"6163","s":101,"a":6,"at":"فاما من ثقلت موازينه","dt":"[6] فاما من رجحت موازين حسناته"},{"id":"6164","s":101,"a":7,"at":"فهو في عيشه راضيه","dt":"[7] فهو في حياه مرضيه في الجنه."},{"id":"6165","s":101,"a":8,"at":"واما من خفت موازينه","dt":"[8] واما من خفت موازين حسناته"},{"id":"6166","s":101,"a":9,"at":"فامه هاويه","dt":"[9] ورجحت موازين سيئاته، فماواه جهنم."},{"id":"6167","s":101,"a":10,"at":"وما ادراك ما هيه","dt":"[10] وما ادراك -ايها الرسول- ما هذه الهاويه؟"},{"id":"6168","s":101,"a":11,"at":"نار حاميه","dt":"[11] انها نار قد حميت من الوقود عليها."},{"id":"6169","s":102,"a":1,"at":"الهاكم التكاثر","dt":"[1] شغلكم عن طاعه الله التفاخر بكثره الاموال والاولاد."},{"id":"6170","s":102,"a":2,"at":"حتى زرتم المقابر","dt":"[2] واستمر اشتغالكم بذلك الى ان صرتم الى المقابر، ودفنتم فيها."},{"id":"6171","s":102,"a":3,"at":"كلا سوف تعلمون","dt":"[3] ما هكذا ينبغي ان يلهيكم التكاثر بالاموال، سوف تتبينون ان الدار الاخره خير لكم."},{"id":"6172","s":102,"a":4,"at":"ثم كلا سوف تعلمون","dt":"[4] ثم احذروا سوف تعلمون سوء عاقبه انشغالكم عنها."},{"id":"6173","s":102,"a":5,"at":"كلا لو تعلمون علم اليقين","dt":"[5] ما هكذا ينبغي ان يلهيكم التكاثر بالاموال، لو تعلمون حق العلم لانزجرتم، ولبادرتم الى انقاذ انفسكم من الهلاك"},{"id":"6174","s":102,"a":6,"at":"لترون الجحيم","dt":"[6] لتبصرن الجحيم"},{"id":"6175","s":102,"a":7,"at":"ثم لترونها عين اليقين","dt":"[7] ثم لتبصرنها دون ريب"},{"id":"6176","s":102,"a":8,"at":"ثم لتسالن يومئذ عن النعيم","dt":"[8] ثم لتسالن يوم القيامه عن كل انواع النعيم."},{"id":"6177","s":103,"a":1,"at":"والعصر","dt":"[1] اقسم الله بالدهر؛ لما فيه من عجائب قدره الله الداله على عظمته"},{"id":"6178","s":103,"a":2,"at":"ان الانسان لفي خسر","dt":"[2] على ان بني ادم لفي هلكه ونقصان. ولا يجوز للعبد ان يقسم الا بالله؛ فان القسم بغير الله شرك."},{"id":"6179","s":103,"a":3,"at":"الا الذين امنوا وعملوا الصالحات وتواصوا بالحق وتواصوا بالصبر","dt":"[3] الا الذين امنوا بالله وعملوا عملا صالحا، واوصى بعضهم بعضا بالاستمساك بالحق، والعمل بطاعه الله، والصبر على ذلك."},{"id":"6180","s":104,"a":1,"at":"ويل لكل همزه لمزه","dt":"[1] شر وهلاك لكل مغتاب للناس، طعان فيهم."},{"id":"6181","s":104,"a":2,"at":"الذي جمع مالا وعدده","dt":"[2] الذي كان همه جمع المال وتعداده."},{"id":"6182","s":104,"a":3,"at":"يحسب ان ماله اخلده","dt":"[3] يظن انه ضمن لنفسه بهذا المال الذي جمعه، الخلود في الدنيا والافلات من الحساب."},{"id":"6183","s":104,"a":4,"at":"كلا لينبذن في الحطمه","dt":"[4] ليس الامر كما ظن، ليطرحن في النار التي تهشم كل ما يلقى فيها."},{"id":"6184","s":104,"a":5,"at":"وما ادراك ما الحطمه","dt":"[5] وما ادراك -ايها الرسول- ما حقيقه النار؟"},{"id":"6185","s":104,"a":6,"at":"نار الله الموقده","dt":"[6] انها نار الله المشتعله الشديده اللهب"},{"id":"6186","s":104,"a":7,"at":"التي تطلع على الافئده","dt":"[7] التي من شده حرها تنفذ من الاجسام الى القلوب."},{"id":"6187","s":104,"a":8,"at":"انها عليهم مؤصده","dt":"[8] انها عليهم مطبقه"},{"id":"6188","s":104,"a":9,"at":"في عمد ممدده","dt":"[9] في سلاسل واغلال مطوله؛ لئلا يخرجوا منها."},{"id":"6189","s":105,"a":1,"at":"الم تر كيف فعل ربك باصحاب الفيل","dt":"[1] الم تعلم -ايها الرسول- كيف فعل ربك باصحاب الفيل: ابرهه الحبشي وجيشه الذين ارادوا تدمير الكعبه المباركه؟"},{"id":"6190","s":105,"a":2,"at":"الم يجعل كيدهم في تضليل","dt":"[2] الم يجعل ما دبروه من شر في ابطال وتضييع؟"},{"id":"6191","s":105,"a":3,"at":"وارسل عليهم طيرا ابابيل","dt":"[3] وبعث عليهم طيرا في جماعات متتابعه"},{"id":"6192","s":105,"a":4,"at":"ترميهم بحجاره من سجيل","dt":"[4] تقذفهم بحجاره من طين متحجر."},{"id":"6193","s":105,"a":5,"at":"فجعلهم كعصف ماكول","dt":"[5] فجعلهم به محطمين كاوراق الزرع اليابسه التي اكلتها البهائم ثم رمت بها."},{"id":"6194","s":106,"a":1,"at":"لايلاف قريش","dt":"[1] اعجبوا لالف قريش وامنهم، واستقامه مصالحهم"},{"id":"6195","s":106,"a":2,"at":"ايلافهم رحله الشتاء والصيف","dt":"[2] وانتظام رحلتيهم في الشتاء الى «اليمن»، وفي الصيف الى «الشام»، وتيسير ذلك؛ لجلب ما يحتاجون اليه."},{"id":"6196","s":106,"a":3,"at":"فليعبدوا رب هذا البيت","dt":"[3] فليشكروا، وليعبدوا رب هذا البيت الذي يعتزون به -وهو الكعبه- ، وبسببه نالوا الشرف والرفعه، وليوحدوه ويخلصوا له العباده."},{"id":"6197","s":106,"a":4,"at":"الذي اطعمهم من جوع وامنهم من خوف","dt":"[4] الذي اطعمهم من جوع شديد، وامنهم من فزع وخوف عظيم."},{"id":"6198","s":107,"a":1,"at":"ارايت الذي يكذب بالدين","dt":"[1] ارايت حال ذلك الذي يكذب بالبعث والجزاء؟"},{"id":"6199","s":107,"a":2,"at":"فذلك الذي يدع اليتيم","dt":"[2] فذلك الذي يدفع اليتيم الذي مات ابوه وهو صغير بعنف وشده عن حقه؛ لقساوه قلبه."},{"id":"6200","s":107,"a":3,"at":"ولا يحض على طعام المسكين","dt":"[3] ولا يحض غيره على اطعام المحتاج الذي لا يملك ما يكفيه ويسد حاجته، فكيف له ان يطعمه بنفسه؟"},{"id":"6201","s":107,"a":4,"at":"فويل للمصلين","dt":"[4] فعذاب شديد للمصلين"},{"id":"6202","s":107,"a":5,"at":"الذين هم عن صلاتهم ساهون","dt":"[5] الذين هم عن صلاتهم لاهون، لا يقيمونها على وجهها، ولا يؤدونها في وقتها."},{"id":"6203","s":107,"a":6,"at":"الذين هم يراءون","dt":"[6] الذين هم يتظاهرون باعمال الخير؛ مراءاه للناس."},{"id":"6204","s":107,"a":7,"at":"ويمنعون الماعون","dt":"[7] ويمنعون اعاره ما لا تضر اعارته من الانيه وغيرها، فلا هم احسنوا عباده ربهم، ولا هم احسنوا الى خلقه."},{"id":"6205","s":108,"a":1,"at":"انا اعطيناك الكوثر","dt":"[1] انا اعطيناك -ايها النبي- الخير الكثير في الدنيا والاخره، ومن ذلك نهر الكوثر في الجنه الذي حافتاه خيام اللؤلؤ المجوف، وطينه المسك."},{"id":"6206","s":108,"a":2,"at":"فصل لربك وانحر","dt":"[2] فاخلص لربك صلاتك كلها، واذبح ذبيحتك له وعلى اسمه وحده."},{"id":"6207","s":108,"a":3,"at":"ان شانئك هو الابتر","dt":"[3] ان مبغضك ومبغض ما جئت به من الهدى والنور، هو المنقطع اثره، المقطوع من كل خير."},{"id":"6208","s":109,"a":1,"at":"قل ياايها الكافرون","dt":"[1] قل -ايها الرسول- للذين كفروا بالله ورسوله: يا ايها الكافرون بالله."},{"id":"6209","s":109,"a":2,"at":"لا اعبد ما تعبدون","dt":"[2] لا اعبد ما تعبدون من الاصنام والالهه الزائفه."},{"id":"6210","s":109,"a":3,"at":"ولا انتم عابدون ما اعبد","dt":"[3] ولا انتم عابدون ما اعبد من اله واحد، هو الله رب العالمين المستحق وحده للعباده."},{"id":"6211","s":109,"a":4,"at":"ولا انا عابد ما عبدتم","dt":"[4] ولا انا عابد ما عبدتم من الاصنام والالهه الباطله."},{"id":"6212","s":109,"a":5,"at":"ولا انتم عابدون ما اعبد","dt":"[5] ولا انتم عابدون مستقبلا ما اعبد.وهذه الايه نزلت في اشخاص باعيانهم من المشركين، قد علم الله انهم لا يؤمنون ابدا."},{"id":"6213","s":109,"a":6,"at":"لكم دينكم ولي دين","dt":"[6] لكم دينكم الذي اصررتم على اتباعه، ولي ديني الذي لا ابغي غيره."},{"id":"6214","s":110,"a":1,"at":"اذا جاء نصر الله والفتح","dt":"[1] اذا تم لك -ايها الرسول- النصر على كفار قريش، وتم لك فتح «مكه»."},{"id":"6215","s":110,"a":2,"at":"ورايت الناس يدخلون في دين الله افواجا","dt":"[2] ورايت الكثير من الناس يدخلون في الاسلام جماعات جماعات."},{"id":"6216","s":110,"a":3,"at":"فسبح بحمد ربك واستغفره انه كان توابا","dt":"[3] اذا وقع ذلك فتهيا للقاء ربك بالاكثار من التسبيح بحمده والاكثار من استغفاره، انه كان كثير التوبه على المسبحين والمستغفرين، يتوب عليهم ويرحمهم ويقبل توبتهم."},{"id":"6217","s":111,"a":1,"at":"تبت يدا ابي لهب وتب","dt":"[1] خسرت يدا ابي لهب وشقي بايذائه رسول الله محمدا -صلى الله عليه وسلم-، وقد تحقق خسران ابي لهب."},{"id":"6218","s":111,"a":2,"at":"ما اغنى عنه ماله وما كسب","dt":"[2] ما اغنى عنه ماله وولده، فلن يردا عنه شيئا من عذاب الله اذا نزل به."},{"id":"6219","s":111,"a":3,"at":"سيصلى نارا ذات لهب","dt":"[3] سيدخل نار جهنم ذات اللهب المشتعل"},{"id":"6220","s":111,"a":4,"at":"وامراته حماله الحطب","dt":"[4] هو وامراته التي كانت تحمل الشوك، فتطرحه في طريق النبي -صلى الله عليه وسلم-؛ لاذيته."},{"id":"6221","s":111,"a":5,"at":"في جيدها حبل من مسد","dt":"[5] في عنقها حبل محكم الفتل من ليف شديد خشن، ترفع به في نار جهنم، ثم ترمى الى اسفلها."},{"id":"6222","s":112,"a":1,"at":"قل هو الله احد","dt":"[1] قل -ايها الرسول-: هو الله المتفرد بالالوهيه والربوبيه، والاسماء والصفات لا يشاركه احد فيها."},{"id":"6223","s":112,"a":2,"at":"الله الصمد","dt":"[2] الله الذي كمل في صفات الشرف والمجد والعظمه، الذي يقصده الخلائق في قضاء الحوائج والرغائب."},{"id":"6224","s":112,"a":3,"at":"لم يلد ولم يولد","dt":"[3] ليس له ولد ولا والد ولا صاحبه."},{"id":"6225","s":112,"a":4,"at":"ولم يكن له كفوا احد","dt":"[4] ولم يكن له مماثلا ولا مشابها احد من خلقه، لا في اسمائه، ولا في صفاته، ولا في افعاله، تبارك وتعالى وتقدس."},{"id":"6226","s":113,"a":1,"at":"قل اعوذ برب الفلق","dt":"[1] قل -ايها الرسول-: اعوذ واعتصم برب الفلق، وهو الصبح."},{"id":"6227","s":113,"a":2,"at":"من شر ما خلق","dt":"[2] من شر جميع المخلوقات واذاها."},{"id":"6228","s":113,"a":3,"at":"ومن شر غاسق اذا وقب","dt":"[3] ومن شر ليل شديد الظلمه اذا دخل وتغلغل، وما فيه من الشرور والمؤذيات."},{"id":"6229","s":113,"a":4,"at":"ومن شر النفاثات في العقد","dt":"[4] ومن شر الساحرات اللاتي ينفخن فيما يعقدن من عقد بقصد السحر."},{"id":"6230","s":113,"a":5,"at":"ومن شر حاسد اذا حسد","dt":"[5] ومن شر حاسد مبغض للناس اذا حسدهم على ما وهبهم الله من نعم، يريد زوالها عنهم وايقاع الاذى بهم."},{"id":"6231","s":114,"a":1,"at":"قل اعوذ برب الناس","dt":"[1] قل -ايها الرسول-: اعوذ واعتصم برب الناس، القادر وحده على رد شر الوسواس."},{"id":"6232","s":114,"a":2,"at":"ملك الناس","dt":"[2] ملك الناس المتصرف في كل شؤونهم، الغني عنهم."},{"id":"6233","s":114,"a":3,"at":"اله الناس","dt":"[3] اله الناس الذي لا معبود بحق سواه."},{"id":"6234","s":114,"a":4,"at":"من شر الوسواس الخناس","dt":"[4] من اذى الشيطان الذي يوسوس عند الغفله، ويختفي عند ذكر الله."},{"id":"6235","s":114,"a":5,"at":"الذي يوسوس في صدور الناس","dt":"[5] الذي يبث الشر والشكوك في صدور الناس."},{"id":"6236","s":114,"a":6,"at":"من الجنه والناس","dt":"[6] من شياطين الجن والانس."}]
